import java.io.*;
import java.util.*;

public class tank {

    static final FastScanner fs = new FastScanner();



    public static void main(String[] args) {
        int t = 1;
        while(t-->0) {
            run_case();
        }


    }

    static boolean[][] vis;

    static void run_case() {
        int n = fs.nextInt(), m = fs.nextInt(), cnt = 0;
        char[][] arr = new char[n][m];

        vis = new boolean[n][m];

        for(int i = 0;i < n;i++) {
            arr[i] = fs.next().toCharArray();
        }

        StringBuilder ans = new StringBuilder();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if(arr[i][j] == '*') {
                    int si = fn(i, j, arr);
                    if (si == 200 || si == 0) continue;

                    vis[i][j] = true;

                    for (int k = 0; k < si; k++) vis[i + 1 + k][j] = true;
                    for (int k = 0; k < si; k++) vis[i - 1 - k][j] = true;
                    for (int k = 0; k < si; k++) vis[i][j + 1 + k] = true;
                    for (int k = 0; k < si; k++) vis[i][j - 1 - k] = true;

                    ans.append(i + 1).append(" ");
                    ans.append(j + 1).append(" ");
                    ans.append(si).append("\n");

                    cnt++;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if(arr[i][j] == '*') {
                    if(!vis[i][j]) {
                        System.out.println(-1);
                        return;
                    }
                }
            }
        }

        System.out.println(cnt);
        System.out.println(ans);
    }

    static int fn(int x, int y, char[][] arr) {
        int ret = 200, tt, n = arr.length, m = arr[0].length, rn = 0;

        tt = x + 1;

        while(tt < n) {
            if(arr[tt][y] == '*') {
                rn++;
            }
            else break;

            tt++;
        }

        ret = Math.min(ret, rn);
        rn = 0;

        tt = x - 1;

        while(tt >= 0) {
            if(arr[tt][y] == '*'){
                rn++;
            }
            else break;

            tt--;
        }

        ret = Math.min(ret, rn);
        rn = 0;

        tt = y + 1;

        while(tt < m) {
            if(arr[x][tt] == '*'){
                rn++;
            }
            else break;

            tt++;
        }

        ret = Math.min(ret, rn);
        rn = 0;

        tt = y - 1;

        while(tt >= 0) {
            if(arr[x][tt] == '*'){
                rn++;
            }
            else break;

            tt--;
        }

        ret = Math.min(ret, rn);

        return ret;
    }

    static class FastScanner {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st=new StringTokenizer("");
        String next() {
            while (!st.hasMoreTokens())
                try {
                    st=new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            return st.nextToken();
        }

        String nextLine(){
            try {
                return br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }

            return "";
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] readArray(int n) {
            int[] a=new int[n];
            for (int i=0; i<n; i++) a[i]=nextInt();
            return a;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

