		}
	}

	public int[][] left, right, up, down;
	public void builddp(){
		left = new int[height][width];
		right = new int[height][width];
		up = new int[height][width];
		down = new int[height][width];
		for ( int j = 1; j < height-1; j++){
			for ( int k = 1; k < width-1; k++){
				left[j][k] = field[j][k-1] == '*'? 1 : 0;
				if ( left[j][k] == 1 ){
					left[j][k] += left[j][k-1];
				}
			}for ( int k = width-2; k > 0; k--){
				right[j][k] = field[j][k+1] == '*'? 1 : 0;
				if ( right[j][k] == 1 ){
					right[j][k] += right[j][k+1];
				}
			}
		}
		for ( int j = 1; j < width-1; j++){
			for ( int k = 1; k < height-1; k++){
				up[k][j] = field[k-1][j] == '*'?1:0;
				if ( up[k][j] == 1 ){
					up[k][j] += up[k-1][j];
				}
			}for ( int k = height-2; k > 0; k--){
				down[k][j] = field[k+1][j] == '*'?1:0;
				if ( down[k][j] == 1 ){
					down[k][j] += down[k+1][j];
				}
			}
		}
	}

	public List<int[]> ans;
	public boolean drawable = true;
	public void solve(){
		ans = new ArrayList<>();
		for ( int j = 1; j < width-1; j++){
			for ( int k = 1; k < height-1; k++){
				if ( field[k][j] == '*' ){
					int temp = min( left[k][j], right[k][j] );
					temp = min(temp, min(up[k][j], down[k][j]));
					if ( temp != 0 ){
						visited[k][j] = true;
						for ( int i = k-temp; i <= k+temp; i++){
							visited[i][j] = true;
						}
						for ( int i = j-temp; i <= j+temp; i++){
							visited[k][i] = true;
						}
						int[] star = new int[3];
						star[0] = k+1;
						star[1] = j+1;
						star[2] = temp;
						ans.add(star);
					}
				}
			}
		}
		for ( int k = 0; k < width; k++){
			for ( int j = 0; j < height; j++){
				if ( !visited[j][k] && field[j][k] == '*' ){ drawable = false; return; }
			}
		}
	}

}

import java.io.*;
import java.util.*;

public class StarsDrawing
{

    static int n, m;
    static char[][] grid;

    public static boolean isValid(int i, int j)
    {
        return i > -1 && j > -1 && i < n && j < m && grid[i][j] == '*';
    }

    public static int move(int i, int j, int x, int y)
    {
        return !isValid(i + x, j + y) ? 0 : 1 + move(i + x, j + y, x, y);
    }

    public static void mark(int i, int j, int x, int y, int dist)
    {
        grid[i][j] = '#';
        if(dist == 0) return;
        mark(i + x, j + y, x, y, dist - 1);
    }

    public static void main(String[] args) throws IOException
    {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        n = sc.nextInt();
        m = sc.nextInt();
        grid = new char[n][m];

        for(int i = 0; i < n; i++)
            grid[i] = sc.next().toCharArray();

        int count = 0;
        boolean starFound = false;
        StringBuilder sb = new StringBuilder();
        Queue<Triple> queue = new LinkedList<>();
        for(int i = 0; i < n; i++)
        {
            for(int j = 0; j < m; j++)
            {
                if(grid[i][j] == '*')
                {
                    starFound = true;
                    int top = move(i, j, -1, 0);
                    int bottom = move(i, j, 1, 0);
                    int right = move(i, j, 0, 1);
                    int left = move(i, j, 0, -1);

                    int min = Math.min(Math.min(top, bottom), Math.min(right, left));
                    if(min > 0)
                    {
                        count++;
                        queue.add(new Triple(i, j, min));
                        sb.append((i + 1) + " " + (j + 1) + " " + min + "\n");
                    }
                }
            }
        }

        while(!queue.isEmpty())
        {
            Triple p = queue.poll();
            mark(p.x, p.y, -1, 0, p.dist);
            mark(p.x, p.y, 1, 0, p.dist);
            mark(p.x, p.y, 0, 1, p.dist);
            mark(p.x, p.y, 0, -1, p.dist);
        }

        boolean flag = true;
        for(int i = 0; i < n; i++)
            for(int j = 0; j < m; j++)
                if(grid[i][j] == '*')
                    flag = false;

        if((count == 0 && starFound) || !flag) pw.println(-1);
        else
        {
            pw.println(count);
            pw.print(sb);
        }

        pw.flush();
        pw.close();
    }

    static class Triple
    {
        int x, y, dist;

        public Triple(int x, int y, int dist)
        {
            this.x = x;
            this.y = y;
            this.dist = dist;
        }
    }
}

