    }

    static class TaskE2 {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt() + 2;
            int m = in.nextInt() + 2;
            char[][] c = new char[n][m];
            Arrays.fill(c[0], '.');
            Arrays.fill(c[n - 1], '.');
            for (int i = 1; i < n - 1; i++) {
                c[i][0] = c[i][m - 1] = '.';
                char[] qw = in.nextCharArray();
                for (int j = 1; j < m - 1; j++) {
                    c[i][j] = qw[j - 1];
                }
            }
            int[][][] a = new int[4][n][m];
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < n; j++) {
                    Arrays.fill(a[i][j], -1);
                }
            }
            for (int i = 1; i < n - 1; i++) {
                for (int j = 1; j < m - 1; j++) {
                    if (c[i][j] == '*') {
                        a[0][i][j] = a[0][i][j - 1] + 1;
                    }
                    if (c[i][m - j - 1] == '*') {
                        a[2][i][m - j - 1] = a[2][i][m - j] + 1;
                    }

                }
            }
            for (int i = 1; i < m - 1; i++) {
                for (int j = 1; j < n - 1; j++) {
                    if (c[j][i] == '*') {
                        a[1][j][i] = a[1][j - 1][i] + 1;
                    }
                    if (c[n - j - 1][i] == '*') {
                        a[3][n - j - 1][i] = a[3][n - j][i] + 1;
                    }
                }
            }
            int[][] b = new int[n][m];
            int cc = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    b[i][j] = Math.min(Math.min(a[0][i][j], a[1][i][j]), Math.min(a[2][i][j], a[3][i][j]));
                    if (b[i][j] == 0) {
                        b[i][j]--;
                    } else if (b[i][j] > 0) {
                        cc++;
                    }
                }
            }
            boolean[][] ans = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                int k1 = -1;
                int k2 = -1;
                for (int j = 0; j < m; j++) {
                    k1 = Math.max(k1, b[i][j]);
                    k2 = Math.max(k2, b[i][m - j - 1]);
                    if (k1 >= 0) {
                        ans[i][j] = true;
                        k1--;
                    }
                    if (k2 >= 0) {
                        ans[i][m - j - 1] = true;
                        k2--;
                    }
                }
            }
            for (int i = 0; i < m; i++) {
                int k1 = -1;
                int k2 = -1;
                for (int j = 0; j < n; j++) {
                    k1 = Math.max(k1, b[j][i]);
                    k2 = Math.max(k2, b[n - j - 1][i]);
                    if (k1 >= 0) {
                        ans[j][i] = true;
                        k1--;
                    }
                    if (k2 >= 0) {
                        ans[n - j - 1][i] = true;
                        k2--;
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (c[i][j] == '*' && !ans[i][j]) {
                        out.print(-1);
                        return;
                    }
                }
            }
            out.println(cc + "");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (b[i][j] > 0) {
                        out.println(i + " " + j + " " + b[i][j]);
                    }
                }
            }
        }

    }

    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        public InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
            st = null;
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[] nextCharArray() {
            return next().toCharArray();
        }

    }
}

import java.io.BufferedInputStream;
