import java.util.Scanner;

public class cf501_E {
  public static void main(String[] args) {
    Scanner s = new Scanner(new BufferedInputStream(System.in));
    PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
    solve(s, out);
    out.flush();
  }

  public static void printField(boolean[][] f) {
    StringBuilder sb = new StringBuilder();
    for (int j = 0; j < f.length; j++) {
      for (int i = 0; i < f[0].length; i++) {
        sb.append(f[j][i] ? "*" : ".");
      }
      sb.append('\n');
    }
    System.out.println(sb.toString());
  }

  static boolean matches(int midn, int midm, int size, boolean[][] field) {
    int n = field.length;
    int m = field[0].length;

    int l = midm - size;
    int r = midm + size;
    int t = midn - size;
    int b = midn + size;
    if (l < 0 || r >= m) {
      return false;
    }
    if (t < 0 || b >= n) {
      return false;
    }
    for (int i = l; i <= r; i++) {
      if (!field[midn][i]) {
        return false;
      }
    }
    for (int i = t; i <= b; i++) {
      if (!field[i][midm]) {
        return false;
      }
    }
    return true;
  }

  public static void solve(Scanner in, PrintWriter out) {
    int n = in.nextInt();
    int m = in.nextInt();
    in.nextLine();
    boolean field[][] = new boolean[n][m];
    boolean testField[][] = new boolean[n][m];
    for (int i = 0; i < n; i++) {
      String s = in.nextLine();
      for (int j = 0; j < m; j++) {
        boolean star = s.charAt(j) == '*';
        field[i][j] = star;
      }
    }


    ArrayList<Star> ss = new ArrayList<>();

    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        int size = 0;
        while (matches(i, j, size + 1, field)) {
          size++;
        }
        if (size != 0) {
          ss.add(new Star(j, i, size));
        }
      }
    }


    for (Star s : ss) {
      printStar(s, testField);
    }





    boolean eq = true;
    for (int i = 0; i < testField.length; i++) {
      if (!Arrays.equals(testField[i], field[i])) {
        eq = false;
        break;
      }
    }

    if (eq) {
      out.printf("%d\n", ss.size());
      for (Star s : ss) {
        out.printf("%d %d %d\n", s.n + 1, s.m + 1, s.s);
      }
    } else {
      out.printf("-1");
    }
  }

  private static void printStar(Star s, boolean[][] field) {
    int l = s.m - s.s;
    int r = s.m + s.s;
    int t = s.n - s.s;
    int b = s.n + s.s;

    for (int i = l; i <= r; i++) {
      field[s.n][i] = true;
    }
    for (int i = t; i <= b; i++) {
      field[i][s.m] = true;
    }
  }

  static class Star {
    final int m;
    final int n;
    final int s;

    Star(int m, int n, int s) {
      this.m = m;
      this.n = n;
      this.s = s;
    }

    @Override public String toString() {
      return "Star{" +
              "m=" + m +
              ", n=" + n +
              ", s=" + s +
              '}';
    }
  }

}

