import static java.util.Arrays.fill;
import static java.util.Arrays.sort;

public class Main {
    FastScanner in;
    PrintWriter out;

    private void solve() throws IOException {
        int n = in.nextInt(), m = in.nextInt();
        boolean[][] map = new boolean[n][m];
        for (int i = 0, j = 0; i < n; i++, j = 0)
            for (char c : in.next().toCharArray()) {
                map[i][j] = c == '*';
                j++;
            }

        int[][] left = new int[n][m], right = new int[n][m], cntLR = new int[n][m];
        int[][] up = new int[n][m], down = new int[n][m], cntUD = new int[n][m];

        for (int i = 0; i < n; i++)
            for (int j = 1; j < m; j++)
                left[i][j] = map[i][j - 1] ? left[i][j - 1] + 1 : 0;

        for (int i = 0; i < n; i++)
            for (int j = m - 2; j >= 0; j--)
                right[i][j] = map[i][j + 1] ? right[i][j + 1] + 1 : 0;

        for (int i = 1; i < n; i++)
            for (int j = 0; j < m; j++)
                up[i][j] = map[i - 1][j] ? up[i - 1][j] + 1 : 0;

        for (int i = n - 2; i >= 0; i--)
            for (int j = 0; j < m; j++)
                down[i][j] = map[i + 1][j] ? down[i + 1][j] + 1 : 0;

        int k = 0;
        int[] x = new int[n * m];
        int[] y = new int[n * m];
        int[] s = new int[n * m];

        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (map[i][j]) {
                    int l = min(min(left[i][j], right[i][j]), min(up[i][j], down[i][j]));
                    if (l > 0) {
                        x[k] = i;
                        y[k] = j;
                        s[k++] = l;

                        cntLR[i][j - l]++;
                        if (j + l + 1 < m)
                            cntLR[i][j + l + 1]--;

                        cntUD[i - l][j]++;
                        if (i + l + 1 < n)
                            cntUD[i + l + 1][j]--;
                    }
                }

        for (int i = 0; i < n; i++)
            for (int j = 1; j < m; j++)
                cntLR[i][j] += cntLR[i][j - 1];

        for (int i = 1; i < n; i++)
            for (int j = 0; j < m; j++)
                cntUD[i][j] += cntUD[i - 1][j];

        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (map[i][j] && cntLR[i][j] == 0 && cntUD[i][j] == 0) {
                    out.println(-1);
                    return;
                }

        out.println(k);
        for (int i = 0; i < k; i++)
            out.println(x[i] + 1 + " " + (y[i] + 1) + " " + s[i]);
    }

    class FastScanner {
        StringTokenizer st;
        BufferedReader br;

        FastScanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        boolean hasNext() throws IOException {
            return br.ready() || (st != null && st.hasMoreTokens());
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next().replace(',', '.'));
        }

        String nextLine() throws IOException {
            return br.readLine();
        }

        boolean hasNextLine() throws IOException {
            return br.ready();
        }

    }

    private void run() throws IOException {
        in = new FastScanner(System.in); 
        out = new PrintWriter(System.out); 

        solve();

        out.flush();
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new Main().run();
    }
}

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

public class E1015 {

	public void solve(Scanner in, PrintWriter out) {
		int n = in.nextInt(), m = in.nextInt();
		boolean[][] grid = new boolean[n][m];
		for(int i = 0; i < n; ++i) {
			String line = in.next();
			for(int j = 0; j < m; ++j) {
				grid[i][j] = line.charAt(j) == '*';
			}
		}
		int[][] rid = new int[n][m], cid = new int[n][m];
		ArrayList<Integer> rstart = new ArrayList<>();
		ArrayList<Integer> rend = new ArrayList<>();
		ArrayList<Integer> cstart = new ArrayList<>();
		ArrayList<Integer> cend = new ArrayList<>();

		for(int i = 0; i < n; ++i) {
			Arrays.fill(rid[i], -1);
			Arrays.fill(cid[i], -1);
		}

		int idx = 0;
		for(int r = 0; r < n; ++r) {
			for(int c = 0; c < m; ++c) {
				if(!grid[r][c]) continue;
				if(rid[r][c] != -1) continue;
				int cur = idx++;
				rstart.add(c);
				while(c < m && grid[r][c]) {
					rid[r][c] = cur;
					++c;
				}
				--c;
				rend.add(c);
			}
		}

		idx = 0;
		for(int c = 0; c < m; ++c) {
			for(int r = 0; r < n; ++r) {
				if(!grid[r][c]) continue;
				if(cid[r][c] != -1) continue;
				int cur = idx++;
				cstart.add(r);
				while(r < n && grid[r][c]) {
					cid[r][c] = cur;
					++r;
				}
				--r;
				cend.add(r);
			}
		}
		BIT[] rbit = new BIT[n], cbit = new BIT[m];
		for(int i = 0; i < n; ++i) rbit[i] = new BIT(m);
		for(int i = 0; i < m; ++i) cbit[i] = new BIT(n);
		StringBuilder ans = new StringBuilder();
		int cnt = 0;
		for(int r = 0; r < n; ++r) {
			for(int c = 0; c < m; ++c) {
				if(rid[r][c] == -1 || cid[r][c] == -1) continue;
				int ridx = rid[r][c], cidx = cid[r][c];
				int lr = cstart.get(cidx), hr = cend.get(cidx);
				int lc = rstart.get(ridx), hc = rend.get(ridx);
				int mindist = Math.min(Math.min(r - lr, hr - r), Math.min(c - lc, hc - c));
				if(mindist == 0) continue;
				ans.append((r + 1) + " " + (c + 1) + " " + mindist + "\n");
				++cnt;
				rbit[r].add(c - mindist, 1);
				rbit[r].add(c + mindist + 1, -1);
				cbit[c].add(r - mindist, 1);
				cbit[c].add(r + mindist + 1, -1);
			}
		}
		boolean possible = true;
		for(int r = 0; possible && r < n; ++r) {
			for(int c = 0; possible && c < m; ++c) {
				if(!grid[r][c]) continue;
				if(rbit[r].sum(0, c) + cbit[c].sum(0, r) <= 0) {
					possible = false;
				}
			}
		}
		if(!possible) {
			out.println(-1);
		} else {
			out.println(cnt);
			out.println(ans);
		}
	}

	public class BIT {

	    long[] tree;
	    int n;

	    public BIT(int n) {
	    	n += 10;
	        this.n = n;
	        tree = new long[n + 1];
	    }

	    public void add(int i, long val)
	    {
	    	i += 5;
	        while(i <= n)
	        {
	            tree[i] += val;
	            i += i & -i;
	        }
	    }

	    public long sum(int to)
	    {
	    	to += 5;
	        long res = 0;
	        for(int i = to; i >= 1; i -= (i & -i))
	        {
	            res += tree[i];
	        }
	        return res;
	    }

	    public long sum(int from, int to) {
	        return sum(to) - sum(from - 1);
	    }
	}


	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		new E1015().solve(in, out);
		in.close();
		out.close();
	}
}

