			}


			for (int r = 0; r < N; r++) {
				int p = 0, q = 0;
				while (p < M && !g[r][p])
					p++;
				while (p < M) {
					while (q < p)
						q++;
					while (q + 1 < M && g[r][q + 1])
						q++;
					while (p <= q) {
						d[RIGHT][r][p] = q - p + 1;
						p++;
					}
					while (p < M && !g[r][p])
						p++;
				}

				p = M - 1;
				q = M - 1;
				while (p >= 0 && !g[r][p])
					p--;
				while (p >= 0) {
					while (q > p)
						q--;
					while (q - 1 >= 0 && g[r][q - 1])
						q--;
					while (p >= q) {
						d[LEFT][r][p] = p - q + 1;
						p--;
					}
					while (p >= 0 && !g[r][p])
						p--;
				}
			}

			for (int c = 0; c < M; c++) {
				int p = 0, q = 0;
				while (p < N && !g[p][c])
					p++;
				while (p < N) {
					while (q < p)
						q++;
					while (q + 1 < N && g[q + 1][c])
						q++;
					while (p <= q) {
						d[DOWN][p][c] = q - p + 1;
						p++;
					}
					while (p < N && !g[p][c])
						p++;
				}

				p = N - 1;
				q = N - 1;
				while (p >= 0 && !g[p][c])
					p--;
				while (p >= 0) {
					while (q > p)
						q--;
					while (q - 1 >= 0 && g[q - 1][c])
						q--;
					while (p >= q) {
						d[UP][p][c] = p - q + 1;
						p--;
					}
					while (p >= 0 && !g[p][c])
						p--;
				}
			}

			cs = new int[N][M];
			int[] dx = { -1, 0, 0, 1 };
			int[] dy = { 0, -1, 1, 0 };
			ArrayList<int[]> cmd = new ArrayList<>();
			for (int i = 0; i < N; i++) {
				for (int j = 0; j < M; j++) {
					int min = d[0][i][j];
					for (int k = 1; k < 4; k++)
						min = Math.min(min, d[k][i][j]);
					if (min < 2)
						continue;
					cmd.add(new int[] { i + 1, j + 1, min });
					for (int k = 0; k < min; k++)
						for (int z = 0; z < 4; z++)
							try {
								cs[i + k * dx[z]][j + k * dy[z]] = 1;
							} catch (Exception e) {

							}
				}
			}

			for (int i = 0; i < N; i++) {
				for (int j = 0; j < M; j++) {
					if (g[i][j] && cs[i][j] == 0) {
						out.println(-1);
						return;
					}
				}
			}

			out.println(cmd.size());
			for (int[] a : cmd)
				out.printf("%d %d %d%n", a[0], a[1], a[2] - 1);

		}

	}

