import java.util.*;

public class E1 {

	public static boolean[][] hit;
	public static void main(String[] args) {
		Scanner s = new Scanner(System.in);
		int n = s.nextInt();
		int m = s.nextInt();

		char[][] board = new char[n][m];
		hit = new boolean[n][m];
		for (boolean[] arr : hit)
		{
			Arrays.fill(arr, false);
		}

		for (int i = 0; i < n; i++)
		{
			board[i] = s.next().toCharArray();
		}

		String ans = "";
		int k = 0;

		for (int i = 1; i < n-1; i++)
		{
			for (int j = 1; j < m-1; j++)
			{
				if (board[i][j] == '*' && board[i-1][j] == '*' && board[i+1][j] == '*' && board[i][j-1] == '*' && board[i][j+1] == '*')
				{
					int x = size(board, i, j, n, m);
					ans += (i+1) + " " + (j+1) + " " + x;
					ans += "\n";
					k++;
					fix(i,j,x);
				}
			}
		}

		for (int i = 0; i < n; i++)
		{
			for (int j = 0; j < m; j++)
			{
				if (board[i][j] == '*' && hit[i][j] == false)
				{
					System.out.println(-1);
					return;
				}
			}
		}

		String f = "";
		f += k;
		f += "\n";
		f += ans;
		System.out.println(f);

	}

	public static int size(char[][] board, int x, int y, int n, int m)
	{
		int min = Integer.MAX_VALUE/2;
		int s = 1;
		while (x - s >= 0 && board[x-s][y] == '*')
		{
			s++;
		}
		min = Math.min(s, min);
		s = 1;
		while (x + s < n && board[x+s][y] == '*')
		{
			s++;
		}
		min = Math.min(s, min);
		s = 1;
		while (y + s < m && board[x][y+s] == '*')
		{
			s++;
		}
		min = Math.min(s, min);
		s = 1;
		while (y - s >= 0 && board[x][y-s] == '*')
		{
			s++;
		}
		min = Math.min(s, min);

		return min-1;
	}

	public static void fix(int x, int y, int size)
	{
		for (int i = 0; i <= size; i++)
		{
			hit[x+i][y] = true;
			hit[x-i][y] = true;
			hit[x][y+i] = true;
			hit[x][y-i] = true;
		}
	}
}

