	static StringBuffer sb = new StringBuffer();

	public static void main(String[] args) {
		n = scan.nextInt();
		m = scan.nextInt();
		data = new char[n][];
		for (int i = 0; i < n; i++) {
			data[i] = scan.next().toCharArray();
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (data[i][j] != '.') {
					check(i, j);
				}
			}
		}

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (data[i][j] == '*') {
					System.out.println(-1);
					return;
				}
			}
		}
		System.out.println(count);
		pw.println(sb);
		pw.flush();
	}

	static void check(int i, int j) {
		int temp = 0;
		int[] num = new int[3];
		for (int k = 1; k < 500; k++) {
			if (!checkSize(i, j, k, num)) {
				temp = k;
				break;
			}
		}
		if (temp == 1)
			return;
		else {
			count++;
			sb.append(num[0] + " " + num[1] + " " + num[2] + "\n");
		}
	}

	static boolean checkSize(int i, int j, int size, int[] num) {
		if (i - size < 0 || i + size >= n || j - size < 0 || j + size >= m) {
			return false;
		}
		if (data[i - size][j] == E || data[i + size][j] == E || data[i][j - size] == E || data[i][j + size] == E) {
			return false;
		}
		data[i][j] = N;
		data[i - size][j] = N;
		data[i + size][j] = N;
		data[i][j - size] = N;
		data[i][j + size] = N;
		num[0] = i + 1;
		num[1] = j + 1;
		num[2] = size;

		return true;
	}

	static class InputReader {
		public BufferedReader reader;
		public StringTokenizer tokenizer;

		public InputReader(InputStream stream) {
			reader = new BufferedReader(new InputStreamReader(stream), 32768);
			tokenizer = null;
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

