public class CFA {
    BufferedReader br;
    PrintWriter out;
    StringTokenizer st;
    boolean eof;
    private static final long MOD = 1000L * 1000L * 1000L + 7;
    private static final int[] dx = {0, -1, 0, 1};
    private static final int[] dy = {1, 0, -1, 0};
    private static final String yes = "Yes";
    private static final String no = "No";

    void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        char[][] mat = new char[n][m];
        for (int i = 0; i < n; i++) {
            mat[i] = nextString().toCharArray();
        }

        List<Integer> x = new ArrayList<>();
        List<Integer> y = new ArrayList<>();
        List<Integer> s = new ArrayList<>();
        boolean[][] vis = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (mat[i][j] == '*') {
                    int i1 = i;
                    while (i1 < n && mat[i1][j] == '*') {
                        i1++;
                    }

                    int i2 = i;
                    while (i2 >= 0 && mat[i2][j] == '*') {
                        i2--;
                    }

                    int j1 = j;
                    while (j1 < m && mat[i][j1] == '*') {
                        j1++;
                    }

                    int j2 = j;
                    while (j2 >= 0 && mat[i][j2] == '*') {
                        j2--;
                    }


                    int max = Math.min(i1 - i, i - i2);
                    max = Math.min(max, j1 - j);
                    max = Math.min(max, j - j2);
                    if (max <= 1) {
                        continue;
                    }

                    x.add(i + 1);
                    y.add(j + 1);
                    s.add(max);
                    for (int k = 0; k < max; k++) {
                        vis[i + k][j] = true;
                        vis[i - k][j] = true;
                        vis[i][j + k] = true;
                        vis[i][j - k] = true;
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (mat[i][j] == '*' && !vis[i][j]) {
                    outln(-1);
                    return;
                }
            }
        }

        outln(x.size());
        for (int i = 0; i < x.size(); i++) {
            outln(x.get(i) + " " + y.get(i) + " " + (s.get(i) - 1));
        }
    }

    void shuffle(int[] a) {
        int n = a.length;
        for(int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }

    long gcd(long a, long b) {
        while(a != 0 && b != 0) {
            long c = b;
            b = a % b;
            a = c;
        }
        return a + b;
    }

    private void outln(Object o) {
        out.println(o);
    }
    private void out(Object o) {
        out.print(o);
    }
    private void formatPrint(double val) {
        outln(String.format("%.9f%n", val));
    }
