public class Main {


	static final long MOD = 1000000007L;


	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter pw = new PrintWriter(System.out);
		int N = sc.ni();
		int M = sc.ni();
		boolean[][] grid = new boolean[N][M];
		for (int i = 0; i < N; i++) {
			char[] row = sc.next().toCharArray();
			for (int j = 0; j < M; j++) {
				if (row[j]=='*')
					grid[i][j] = true;
			}
		}

		ArrayList<Integer>[] rowVals = new ArrayList[N];
		ArrayList<Integer>[] colVals = new ArrayList[M];
		HashMap<Integer,Integer>[] rows = new HashMap[N];
		HashMap<Integer,Integer>[] cols = new HashMap[M];
		for (int i = 0; i < N; i++) {
			rows[i] = new HashMap<Integer,Integer>();
			rowVals[i] = new ArrayList<Integer>();
		}
		for (int i = 0; i < M; i++) {
			cols[i] = new HashMap<Integer,Integer>();
			colVals[i] = new ArrayList<Integer>();
		}
		for (int i = 0; i < N; i++) {
			int index = 0;
			for (int j = 0; j < M; j++) {
				if (grid[i][j]) {
					rows[i].put(j,index);
					index++;
					rowVals[i].add(j);
				}
			}
		}
		for (int j = 0; j < M; j++) {
			int index = 0;
			for (int i = 0; i < N; i++) {
				if (grid[i][j]) {
					cols[j].put(i,index);
					index++;
					colVals[j].add(i);
				}
			}
		}
		BinaryIndexedTree[] rowBITs = new BinaryIndexedTree[N];
		BinaryIndexedTree[] colBITs = new BinaryIndexedTree[M];
		for (int i = 0; i < N; i++) {
			rowBITs[i] = new BinaryIndexedTree(M+1);
		}
		for (int j = 0; j < M; j++) {
			colBITs[j] = new BinaryIndexedTree(N+1);
		}
		ArrayList<Star> stars = new ArrayList<Star>();
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < M; j++) {
				if (grid[i][j]) {

					int rowI = rows[i].get(j);
					int colI = cols[j].get(i);
					int s1 = binSearch(rowVals[i],rowI,true);
					int s2 = binSearch(rowVals[i],rowI,false);
					int s3 = binSearch(colVals[j],colI,true);
					int s4 = binSearch(colVals[j],colI,false);
					int size = Math.min(Math.min(s1,s2),Math.min(s3,s4));
					if (size > 0) {
						stars.add(new Star(i,j,size));
						rowBITs[i].add(1,j-size);
						rowBITs[i].add(-1,j+size+1);
						colBITs[j].add(1,i-size);
						colBITs[j].add(-1,i+size+1);
					}
				}				
			}
		}
		boolean good = true;
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < M; j++) {
				if (grid[i][j]) {
					if (rowBITs[i].sum(j+1)==0 && colBITs[j].sum(i+1)==0) {
						good = false;
						break;
					}
				}
			}
		}
		if (good) {
			pw.println(stars.size());
			for (Star s: stars) {
				pw.println(s);
			}
		} else {
			pw.println(-1);
		}

		pw.close();
 	}

	static class BinaryIndexedTree {
		public int[] arr;

		public BinaryIndexedTree (int N) {
			arr = new int[N+1];
			arr[0] = 0;
		}


		public void add(int k, int i) {
			int node = i+1;
			while (node < arr.length) {
				arr[node] += k;
				node += node & (-node);
			}
		}


		public int sum(int s_i, int e_i) {
			return sum(e_i) - sum(s_i);
		}

		public int sum(int i) {
			int total = 0;
			int node = i;
			while (node > 0) {
				total += arr[node];
				node -= node & (-node);
			}
			return total;
		}
	}

	static class Star {
		public int row;
		public int col;
		public int size;
		public Star(int r, int c, int s) {
			row = r;
			col = c;
			size = s;
		}

		public String toString() {
			return ((row+1) + " " + (col+1) + " " + size);
		}
	}

	public static int binSearch(ArrayList<Integer> nums, int index, boolean lessThan) {
		int val = nums.get(index);
		if (lessThan) {
			int low = 0;
			int high = index;
			while (low < high) {
				int mid = (low+high)/2;
				if (nums.get(mid) == val-(index-mid)) {
					high = mid;
				} else {
					low = mid+1;
				}
			}
			return (index-low);
		} else {
			int low = index;
			int high = nums.size()-1;
			while (low < high) {
				int mid = (low+high+1)/2;
				if (nums.get(mid) == val+(mid-index)) {
					low = mid;
				} else {
					high = mid-1;
				}
			}
			return (low-index);
		}
	}

    public static int[][] sort(int[][] array) {

		Random rgen = new Random();
		for (int i = 0; i < array.length; i++) {
		    int randomPosition = rgen.nextInt(array.length);
		    int[] temp = array[i];
		    array[i] = array[randomPosition];
		    array[randomPosition] = temp;
		}
		Arrays.sort(array, new Comparator<int[]>() {
			  @Override
        	  public int compare(int[] arr1, int[] arr2) {
				  return arr1[0]-arr2[0]; 
	          }
		});
		return array;
	}

    public static long[][] sort(long[][] array) {

		Random rgen = new Random();
		for (int i = 0; i < array.length; i++) {
		    int randomPosition = rgen.nextInt(array.length);
		    long[] temp = array[i];
		    array[i] = array[randomPosition];
		    array[randomPosition] = temp;
		}
		Arrays.sort(array, new Comparator<long[]>() {
			  @Override

        	  public int compare(long[] arr1, long[] arr2) {
				  if (arr2[0] < arr1[0])
					  return -1;
				  if (arr2[0] > arr1[0])
					  return 1;
				  return 0;
	          }
		});
		return array;
	}

