class FastOutput {
    private final BufferedWriter bf;


    public FastOutput(OutputStream outputStream) {
        bf = new BufferedWriter(new OutputStreamWriter(outputStream));
    }

    public FastOutput() {
        this(System.out);
    }

    public void print(Object s) {
        try {
            bf.write(s.toString());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void println(Object s) {
        print(s);
        print("\n");
    }

    public void print(Object ...os) {
        printd(" ", os);
    }

    public void printd(String delimiter, Object ...os) {
        for (Object o : os) {
            print(o);
            print(delimiter);
        }
    }

    public void flush() {
        try {
            bf.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void close() {
        try {
            bf.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void finish() {
        flush();
        close();
    }
}

