import java.util.*;

public class Solution {
	static char grid[][];
	static char copy[][];

	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();
		grid = new char[n][];
		for (int i = 0; i < n; i++) {
			grid[i] = sc.nextLine().toCharArray();
		}
		int up[][] = new int[n][m];
		int down[][] = new int[n][m];
		int left[][] = new int[n][m];
		int right[][] = new int[n][m];

		dp(-1, 0, up, n, m);
		dp2(1, 0, down, n, m);
		dp(0, -1, left, n, m);
		dp2(0, 1, right, n, m);

		copy = new char[n][m];
		for (int i = 0; i < n; i++)
			Arrays.fill(copy[i], '.');
		StringBuilder ans = new StringBuilder();
		int count = 0;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				int size = Math.min(up[i][j], Math.min(down[i][j], Math.min(left[i][j], right[i][j])));
				size--;
				if (size >= 1) {
					fill(size, i, j);
					count++;
					ans.append((i + 1) + " " + (j + 1) + " " + size + "\n");
				}
			}
		}
		if(Arrays.deepEquals(grid, copy)) {
			System.out.println(count);
			System.out.println(ans);
		}else {
			System.out.println(-1);
		}


	}

	static void fill(int s, int row, int col) {
		copy[row][col] = '*';
		for (int i = 1; i <= s; i++) {
			copy[row + i][col] = '*';
			copy[row - i][col] = '*';
			copy[row][col + i] = '*';
			copy[row][col - i] = '*';

		}
	}

	static void dp(int dx, int dy, int arr[][], int n, int m) {
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (grid[i][j] == '*') {
					arr[i][j] = 1;
					int row = i + dx;
					int col = j + dy;
					if (row >= 0 && row < n && col >= 0 && col < m) {
						arr[i][j] += arr[row][col];
					}
				}

			}
		}
	}

	static void dp2(int dx, int dy, int arr[][], int n, int m) {
		for (int i = n - 1; i >= 0; i--) {
			for (int j = m - 1; j >= 0; j--) {
				if (grid[i][j] == '*') {
					arr[i][j] = 1;
					int row = i + dx;
					int col = j + dy;
					if (row >= 0 && row < n && col >= 0 && col < m) {
						arr[i][j] += arr[row][col];
					}
				}

			}
		}
	}
}

