import java.util.Scanner;

public class StarsDrawingEasy {

	public static char prev = 'X';

	public static void main(String [] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt(); int m = sc.nextInt();
		char [][] grid = new char[n+1][];
		grid[0] = new char[m+1];
		for(int i = 1; i<=n; i++) {
			grid[i] = (" " + sc.next()).toCharArray();
		}
		getResult(grid);
		sc.close();
	}

	static void getResult(char [][] grid) {
		int numStars = 0;
		StringBuilder res = new StringBuilder("");
		for(int i = 1; i<grid.length; i++) {
			for(int j = 1; j<grid[1].length; j++) {
				if(grid[i][j]!='*'&&grid[i][j]!=prev) {
					continue;
				}
				int rad = getRad(i, j, grid);
				for(int cur = rad; cur>=1; cur--) {
					if(isPossible(grid, i, j, cur)) {
						numStars++;
						res.append(i + " " + j + " " + cur + "\n");
						modify(grid, i, j, cur);
						break;
					}
				}
			}
		}
		if(valid(grid)) {
			System.out.println(numStars);
			System.out.println(res);
		}
		else {
			System.out.println(-1);
		}
	}


	static boolean valid(char [][] grid) {
		for(char [] cur: grid) {
			for(char curChar : cur) {
				if(curChar=='*') {
					return false;
				}
			}
		}
		return true;
	}

	static boolean isPossible(char [][] grid,int x, int y, int rad) {
		boolean res = true;
		res = res&&check(grid, x, y, 1, 0, rad);
		res = res&&check(grid, x, y, -1, 0, rad);
		res = res&&check(grid, x, y, 0, 1, rad);
		res = res&&check(grid, x, y, 0, -1, rad);
		return res;
	}

	static void modify(char [][] grid, int x, int y, int rad) {
		grid[x][y] = prev;
		modifyLine(grid, x, y, 1, 0, rad);
		modifyLine(grid, x, y, -1, 0, rad);
		modifyLine(grid, x, y, 0, -1, rad);
		modifyLine(grid, x, y, 0, 1, rad);
	}

	static void modifyLine(char [][] grid, int  x, int  y, int xInc,int yInc,int numInc) {
		for(int i = 1; i<=numInc; i++) {
			x = x+xInc;
			y = y+yInc;
			grid[x][y] = prev;
		}
		return;
	}

	static boolean check(char [][] grid, int  x, int  y, int xInc,int yInc,int numInc) {
		for(int i = 1; i<=numInc; i++) {
			x = x+xInc;
			y = y+yInc;
			if(grid[x][y]==prev||grid[x][y]=='*') {
				continue;
			}
			return false;

		}
		return true;
	}

	static int getRad(int x, int y, char [][] grid) {
		return Math.min(grid[1].length-1-y,Math.min(y-1,Math.min(x-1, grid.length-1-x)));
	}
}

import java.io.*;
import java.util.*;

public class StarsDrawing
{

    static int n, m;
    static char[][] grid;

    public static boolean isValid(int i, int j)
    {
        return i > -1 && j > -1 && i < n && j < m && grid[i][j] == '*';
    }

    public static int move(int i, int j, int x, int y)
    {
        return !isValid(i + x, j + y) ? 0 : 1 + move(i + x, j + y, x, y);
    }

    public static void mark(int i, int j, int x, int y, int dist)
    {
        grid[i][j] = '#';
        if(dist == 0) return;
        mark(i + x, j + y, x, y, dist - 1);
    }

    public static void main(String[] args) throws IOException
    {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        n = sc.nextInt();
        m = sc.nextInt();
        grid = new char[n][m];

        for(int i = 0; i < n; i++)
            grid[i] = sc.next().toCharArray();


        int[][] up = new int[n][m];
        for(int i = 0; i < m; i++)
            for(int j = 0; j < n; j++)
                if(isValid(j, i))
                    up[j][i] += isValid(j, i - 1) ? 1 + up[j][i - 1] : 0;

        int[][] down = new int[n][m];
        for(int i = m - 1; i > -1; i--)
            for(int j = 0; j < n; j++)
                if(isValid(j, i))
                    down[j][i] += isValid(j, i + 1) ? 1 + down[j][i + 1] : 0;

        int[][] right = new int[n][m];
        for(int i = n - 1; i > -1; i--)
            for(int j = 0; j < m; j++)
                if(isValid(i, j))
                    right[i][j] += isValid(i + 1, j) ? 1 + right[i + 1][j] : 0;

        int[][] left = new int[n][m];
        for(int i = 0; i < n; i++)
            for(int j = 0; j < m; j++)
                if(isValid(i, j))
                    left[i][j] += isValid(i - 1, j) ? 1 + left[i - 1][j] : 0;

        int count = 0;
        boolean starFound = false;
        StringBuilder sb = new StringBuilder();
        for(int i = 0; i < n; i++)
        {
            for(int j = 0; j < m; j++)
            {
                if(grid[i][j] != '.')
                {
                    starFound = true;
                    int min = Math.min(Math.min(up[i][j], down[i][j]), Math.min(right[i][j], left[i][j]));
                    if(min > 0)
                    {
                        count++;
                        for(int c = 0; c <= min; c++)
                        {
                            grid[i + c][j] = '#';
                            grid[i - c][j] = '#';
                            grid[i][j + c] = '#';
                            grid[i][j - c] = '#';
                        }
                        sb.append((i + 1) + " " + (j + 1) + " " + min + "\n");
                    }
                }
            }
        }




        boolean flag = true;
        for(int i = 0; i < n; i++)
            for(int j = 0; j < m; j++)
                if(grid[i][j] == '*')
                    flag = false;

        if((count == 0 && starFound) || !flag) pw.println(-1);
        else
        {
            pw.println(count);
            pw.print(sb);
        }

        pw.flush();
        pw.close();
    }

    static class Triple
    {
        int x, y, dist;

        public Triple(int x, int y, int dist)
        {
            this.x = x;
            this.y = y;
            this.dist = dist;
        }
    }
}

