import java.util.*;
import java.io.*;

public class DrawingStars {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out,false);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];
        for(int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        ArrayList<Line> horiz = new ArrayList<>();
        ArrayList<Line> verts = new ArrayList<>();
        int cnt = 0;
        PriorityQueue<Event> q = new PriorityQueue<>();
        StringBuilder sb = new StringBuilder();
        for(int i = 0; i < n; i++) {
            int prev = -1;
            for(int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    if (prev == -1) prev = j;
                } else {
                    if (prev != -1) {
                        if (j - prev > 2) {

                            horiz.add(new Line(prev, j, i));
                            q.offer(new Event(prev, cnt, 1));
                            q.offer(new Event(j, cnt, 0));
                            cnt++;
                        }
                        prev = -1;
                    }
                }
            }
            if (prev != -1 && m - prev > 2) {

                horiz.add(new Line(prev, m, i));
                q.offer(new Event(prev, cnt, 1));
                q.offer(new Event(m, cnt, 0));
                cnt++;
            }
        }
        for(int j = 0; j < m; j++) {
            int prev = -1;
            for(int i = 0; i < n; i++) {
                if (grid[i][j] == '*') {
                    if (prev == -1) prev = i;
                } else {
                    if (prev != -1) {
                        if (i - prev > 2) {

                            verts.add(new Line(prev, i, j));
                        }
                        prev = -1;
                    }
                }
            }
            if (prev != -1) verts.add(new Line(prev, n, j));
        }
        int[][] prefVert = new int[n+1][m];
        int[][] prefHoriz = new int[n][m+1];
        Collections.sort(verts, new Comparator<Line>() {
            public int compare(Line o1, Line o2) {
                if (o1.x == o2.x) return o1.l - o2.l;
                return o1.x - o2.x;
            }
        });
        int v = 0, h = 0;
        Line[] active = new Line[n];
        int ss = verts.size();
        int ans = 0;
        for(int z = 0; z < ss; z++) {
            Line curLine = verts.get(z);
            while(!q.isEmpty() && q.peek().x <= curLine.x) {
                Event curEv = q.poll();
                Line hh = horiz.get(curEv.ind);
                if (curEv.type == 0) {
                    active[hh.x] = null;
                } else {

                    active[hh.x] = hh;
                }
            }
            for(int i = curLine.l; i < curLine.r; i++) {
                if (active[i]==null)continue;

                int vdist = Math.min(curLine.r-i-1, i - curLine.l);
                int hdist = Math.min(active[i].r - curLine.x-1, curLine.x - active[i].l);
                int dist = Math.min(hdist, vdist);

                if (dist > 0) {
                    prefVert[i - dist][curLine.x]++;
                    prefVert[i + dist + 1][curLine.x]--;
                    prefHoriz[i][curLine.x-dist]++;
                    prefHoriz[i][curLine.x+dist+1]--;
                    ans++;
                    sb.append((i+1) + " " + (curLine.x+1) + " " + dist + "\n");
                }
            }
        }
        int[][] gh = new int[n][m];
        int[][] gv = new int[m][n];
        for(int i= 0; i < n; i++) { 
            int cur = 0;
            for(int j = 0; j < m; j++) { 
                cur += prefHoriz[i][j];
                gh[i][j] = cur;
            }

        }
        for(int j = 0; j < m; j++) { 
            int cur = 0;
            for(int i= 0; i < n; i++) { 
                cur += prefVert[i][j]; 
                gv[j][i] = cur;
            } 

        }
        boolean good = true;
        for(int i = 0; i < n; i++) { for(int j = 0; j < m; j++) { good &= grid[i][j] == '.' || (grid[i][j] == '*' && (gh[i][j] > 0 || gv[j][i] > 0)); } }
        if (!good) out.println(-1);
        else {
            out.println(ans);
            out.print(sb);
        }
        out.flush();
    }
    static class Event implements Comparable<Event> {
        int x, type, ind;

        public Event(int xx, int ii, int tt) {
            x = xx; type = tt;ind = ii;
        }
        public int compareTo(Event o) {
            if (x == o.x) return type - o.type;
            return x- o.x;
        }
    }
    static class Line {
        int l, r, x;
        public Line(int ll, int rr, int xx) {
            l = ll; r = rr; x = xx;
        }
    }
    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        public FastScanner(Reader in) {
            br = new BufferedReader(in);
        }
        public FastScanner() {
            this(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
        long nextLong() {
            return Long.parseLong(next());
        }
        double nextDouble() {
            return Double.parseDouble(next());
        }
        String readNextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

