    static class E1StarsDrawingEasyEdition {
        char[][] arr;
        char[][] fal;
        int n;
        int m;

        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            n = in.scanInt();
            m = in.scanInt();
            arr = new char[n][m];
            fal = new char[n][m];
            for (int i = 0; i < n; i++) {
                String str = in.scanString();
                arr[i] = str.toCharArray();
                for (int j = 0; j < m; j++) {
                    fal[i][j] = '.';
                }
            }


            int c = 0;
            int ans[][] = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    for (int k = 1; k <= 100; k++) {
                        if (!check(i, j, k)) {
                            break;
                        } else {
                            ans[i][j] = k;
                        }
                    }

                    if (ans[i][j] != 0) {
                        c++;
                        set(i, j, ans[i][j]);
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (arr[i][j] != fal[i][j]) {
                        out.println(-1);
                        return;
                    }
                }
            }

