                        out.print((i + 1) + " ");
                        out.print((j + 1) + " ");
                        out.println((ans[i][j]));
                    }
                }
            }
        }

        boolean check(int x, int y, int k) {
            boolean flag = true;
            if (arr[x][y] != '*') return false;
            if (x - k < 0) return false;
            if (x + k >= n) return false;
            if (y - k < 0) return false;
            if (y + k >= m) return false;
            for (int i = x; i >= x - k; i--) if (arr[i][y] != '*') return false;
            for (int i = x; i <= x + k; i++) if (arr[i][y] != '*') return false;
            for (int i = y; i >= y - k; i--) if (arr[x][i] != '*') return false;
            for (int i = y; i <= y + k; i++) if (arr[x][i] != '*') return false;


            return true;
        }

        void set(int x, int y, int k) {
            fal[x][y] = '*';
            for (int i = x; i >= x - k; i--) fal[i][y] = '*';
            for (int i = x; i <= x + k; i++) fal[i][y] = '*';
            for (int i = y; i >= y - k; i--) fal[x][i] = '*';
            for (int i = y; i <= y + k; i++) fal[x][i] = '*';
        }

    }

    static class ScanReader {
        private byte[] buf = new byte[4 * 1024];
        private int INDEX;
        private BufferedInputStream in;
        private int TOTAL;

        public ScanReader(InputStream inputStream) {
            in = new BufferedInputStream(inputStream);
        }

        private int scan() {
            if (INDEX >= TOTAL) {
                INDEX = 0;
                try {
                    TOTAL = in.read(buf);
                } catch (Exception e) {
                    e.printStackTrace();
                }
                if (TOTAL <= 0) return -1;
            }
            return buf[INDEX++];
        }

        public int scanInt() {
            int I = 0;
            int n = scan();
            while (isWhiteSpace(n)) n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    I *= 10;
                    I += n - '0';
                    n = scan();
                }
            }
            return neg * I;
        }

        public String scanString() {
            int c = scan();
            while (isWhiteSpace(c)) c = scan();
            StringBuilder RESULT = new StringBuilder();
            do {
                RESULT.appendCodePoint(c);
                c = scan();
            } while (!isWhiteSpace(c));
            return RESULT.toString();
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1) return true;
            else return false;
        }

    }
}

import java.io.BufferedReader;
