public class Solution{

	static boolean[][] visited;
	static ArrayList<Integer> list;



	public static void main(String[] args) {

		FastScanner fs = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);

		int tt = 1;
		while(tt-->0) {

			int n = fs.nextInt(), m = fs.nextInt();

			int[][] up = new int[n][m];
			int[][] down = new int[n][m];
			int[][] left = new int[n][m];
			int[][] right = new int[n][m];



			char[][] arr = new char[n][];
			for(int i=0;i<n;i++) arr[i] = fs.next().toCharArray();

			visited = new boolean[n][m];
			list = new ArrayList<Integer>();

			for(int i=0;i<n;i++) {
				int cur = 0;
				for(int j=0;j<m;j++) {
					if(cur<j) cur++;
					while(cur<m-1 && arr[i][cur+1]=='*') cur++;
					right[i][j] = cur-j;
				}
			}
			for(int i=0;i<n;i++) {
				int cur = m-1;
				for(int j=m-1;j>=0;j--) {
					if(cur>j) cur--;
					while(cur>0 && arr[i][cur-1]=='*') cur--;
					left[i][j] = j-cur;
				}
			}
			for(int i=0;i<m;i++) {
				int cur = 0;
				for(int j=0;j<n;j++) {
					if(cur<j) cur++;
					while(cur<n-1 && arr[cur+1][i]=='*') cur++;
					down[j][i] = cur-j;
				}
			}
			for(int i=0;i<m;i++) {
				int cur = n-1;
				for(int j=n-1;j>=0;j--) {
					while(cur>j) cur--;
					while(cur>0 && arr[cur-1][i]=='*') cur--;
					up[j][i] = j-cur;
				}
			}



			for(int i=0;i<n;i++) {
				for(int j=0;j<m;j++) {
					if(arr[i][j]=='*') {
						int min = min(up[i][j], down[i][j], left[i][j], right[i][j]);
						if(min>0) makeStar(i, j, min);
					}
				}
			}


			boolean bool = true;
			outer:
			for(int i=0;i<n;i++) {
				for(int j=0;j<m;j++) {
					if(arr[i][j]=='*' && !visited[i][j]) {
						bool = false;
						break outer;
					}
				}
			}

			if(!bool) {
				out.println(-1);
				out.flush();
				return;
			}

			out.println(list.size()/3);
			for(int i=0;i<list.size();i+=3) {
				out.println((list.get(i)+1)+" "+(list.get(i+1)+1)+" "+list.get(i+2));
			}



		}

		out.close();

	}

	static int min(int a, int b, int c, int d) {
		ArrayList<Integer> list = new ArrayList<Integer>();
		list.add(a); list.add(b); list.add(c); list.add(d);
		Collections.sort(list);
		return list.get(0);
	}



	static void makeStar(int i, int j, int s) {
		visited[i][j] = true;
		for(int k=1;k<=s;k++) {
			visited[i+k][j] = true;
			visited[i-k][j] = true;
			visited[i][j+k] = true;
			visited[i][j-k] = true;
		}
		list.add(i); list.add(j); list.add(s);
	}







	static final Random random=new Random();

	static void ruffleSort(int[] a) {
		int n=a.length;
		for (int i=0; i<n; i++) {
			int oi=random.nextInt(n), temp=a[oi];
			a[oi]=a[i]; a[i]=temp;
		}
		Arrays.sort(a);
	}



	static class FastScanner{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer("");

		public String next(){
			while(!st.hasMoreElements()){
				try{
					st = new StringTokenizer(br.readLine());
				} catch(IOException e){
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		public String nextLine() throws IOException {
			return br.readLine();
		}

		public int nextInt(){
			return Integer.parseInt(next());
		}

		public int[] readArray(int n){
			int[] a = new int[n];
			for(int i=0;i<n;i++)
				a[i] = nextInt();
			return a;
		}

		public long nextLong() {
			return Long.parseLong(next());
		}

		public char nextChar() {
			return next().toCharArray()[0];
		}
	}

}

import java.util.*;
