public class Q4 {

	static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
	static PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));

	static class FastScanner {
	    private InputStream stream;
	    private byte[] buf = new byte[1024];
	    private int curChar;
	    private int numChars;
	    private SpaceCharFilter filter;

	    public FastScanner(InputStream stream) {
	        this.stream = stream;
	    }

	    public static boolean isWhitespace(int c) {
	        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
	    }

	    public int read() {
	        if (numChars == -1)
	            throw new InputMismatchException();
	        if (curChar >= numChars) {
	            curChar = 0;
	            try {
	                numChars = stream.read(buf);
	            } catch (IOException e) {
	                throw new InputMismatchException();
	            }
	            if (numChars <= 0)
	                return -1;
	        }
	        return buf[curChar++];
	    }

	    public int nextInt() {
	        int c = read();
	        while (isSpaceChar(c))
	            c = read();
	        int sgn = 1;
	        if (c == '-') {
	            sgn = -1;
	            c = read();
	        }
	        int res = 0;
	        do {
	            if (c < '0' || c > '9')
	                throw new InputMismatchException();
	            res *= 10;
	            res += c - '0';
	            c = read();
	        } while (!isSpaceChar(c));
	        return res * sgn;
	    }

	    public long nextLong() {
	        int c = read();
	        while (isSpaceChar(c))
	            c = read();
	        int sgn = 1;
	        if (c == '-') {
	            sgn = -1;
	            c = read();
	        }
	        long res = 0;
	        do {
	            if (c < '0' || c > '9')
	                throw new InputMismatchException();
	            res *= 10;
	            res += c - '0';
	            c = read();
	        } while (!isSpaceChar(c));
	        return res * sgn;
	    }

	    public String nextToken() {
	        int c = read();
	        while (isSpaceChar(c))
	            c = read();
	        StringBuilder res = new StringBuilder();
	        do {
	            res.appendCodePoint(c);
	            c = read();
	        } while (!isSpaceChar(c));
	        return res.toString();
	    }

	    public boolean isSpaceChar(int c) {
	        if (filter != null)
	            return filter.isSpaceChar(c);
	        return isWhitespace(c);
	    }

	    public interface SpaceCharFilter {
	        public boolean isSpaceChar(int ch);
	    }
	}

	static class Pair implements Comparable<Pair> {
		int u, v, d;

		public Pair(int u, int v, int d) {
			this.u = u;
			this.v = v;
			this.d = d;
		}

		public int compareTo(Pair o) {
			if(d > o.d)
				return -1;
			else
				return 1;
		}
	}

	public static void main(String[] args) throws Exception {
		FastScanner fs = new FastScanner(System.in);
		int r = fs.nextInt(), c = fs.nextInt();
		char[][] grid = new char[r][c];
		for(int i=0; i<r; i++) { 
			String s = fs.nextToken();
			for(int j=0; j<c; j++)
				grid[i][j] = s.charAt(j);
		}

		boolean[][] fill = new boolean[r][c];
		for(int i=0; i<r; i++)
			for(int j=0; j<c; j++) 
				fill[i][j] = grid[i][j] == '.';

		ArrayList<Integer> rowAns = new ArrayList<>(), colAns = new ArrayList<>(), sizeAns = new ArrayList<>();
		for(int i=0; i<r; i++) {
			for(int j=0; j<c; j++) {
				if(grid[i][j] != '*') 
					continue;

				int maxLen = Math.min(Math.abs(0-i), Math.min(Math.abs(0-j), Math.min(Math.abs(r-1-i), Math.abs(c-1-j))));
				int bestK = -1;
				for(int k=1; k<=maxLen; k++) {
					if(grid[i][j+k]=='*' && grid[i][j-k]=='*' && grid[i-k][j]=='*' && grid[i+k][j]=='*') {
						fill[i][j] = fill[i][j+k] = fill[i][j-k] = fill[i-k][j] = fill[i+k][j] = true;
						bestK = Math.max(bestK, k);
					} 
					else 
						break;
				}

				if(bestK > 0) {
					rowAns.add(i+1);
					colAns.add(j+1);
					sizeAns.add(bestK);
				}
			}
		}

		boolean flag = true;
		for(int i=0; i<r; i++)
			for(int j=0; j<c; j++) 
				flag &= fill[i][j];

		if(flag) {
			pw.println(rowAns.size());
			for(int i=0; i<rowAns.size(); i++)
				pw.println(rowAns.get(i) + " " + colAns.get(i) + " " + sizeAns.get(i));
		} 
		else 
			pw.println("-1");
		pw.flush();
		pw.close();
	}
}

