public class temp {

	class pair
	{
		int r,c,l;
		public pair(int f,int s,int t)
		{
			this.r = f;
			this.c = s;
			this.l = t;
		}
	}

    void solve() throws IOException
    {
        FastReader sc=new FastReader();
        int n = sc.nextInt();
        int m = sc.nextInt();

        int a[][] = new int[n][m];
        boolean g = false;

        for(int i=0;i<n;i++)
        {
        	String s = sc.next();
        	for(int j=0;j<m;j++)
        	{
        		a[i][j] = (s.charAt(j)=='*'?1:0);

        		if(a[i][j]==1)
        			g = true;
        	}
        }

        if(!g)
        {
        	System.out.println("0");
        	return;
        }

        int rl[][] = new int[n][m];
        int rr[][] = new int[n][m];
        int cu[][] = new int[n][m];
        int cd[][] = new int[n][m];

        for(int i=0;i<n;i++)
        {
        	rl[i][0] = a[i][0];
        	rr[i][m-1] = a[i][m-1];
        }

        for(int i=1;i<m;i++)
        {
        	for(int j=0;j<n;j++)
        		rl[j][i] = (a[j][i] == 0 ? 0 : rl[j][i-1] + 1);
        }

        for(int i=m-2;i>=0;i--)
        {
        	for(int j=0;j<n;j++)
        		rr[j][i] = (a[j][i] == 0 ? 0 : rr[j][i+1] + 1);
        }

        for(int i=0;i<m;i++)
        {
        	cu[0][i] = a[0][i];
        	cd[n-1][i] = a[n-1][i];
        }

        for(int i=1;i<n;i++)
        {
        	for(int j=0;j<m;j++)
        		cu[i][j] = (a[i][j] == 0 ? 0 : cu[i-1][j] + 1);
        }

        for(int i=n-2;i>=0;i--)
        {
        	for(int j=0;j<m;j++)
        		cd[i][j] = (a[i][j] == 0 ? 0 : cd[i+1][j] + 1);
        }

        ArrayList<pair> p = new ArrayList<>();

        for(int i=0;i<n;i++)
        {
        	for(int j=0;j<m;j++)
        	{
        		int len = Math.min(rl[i][j], Math.min(rr[i][j],Math.min(cu[i][j],cd[i][j])));

        		if(len>1)
        		{
        			p.add(new pair(i+1,j+1,len-1));

        			int l = i;
        			while(l!= i-len)
        				a[l--][j] = 0;

        			l = i;
        			while(l!=i+len)
        				a[l++][j] = 0;

        			int k = j;
        			while(k!=j+len)
        				a[i][k++] = 0;

        			k = j;
        			while(k!=j-len)
        				a[i][k--] = 0;
        		}
        	}
        }

        if(p.isEmpty())
        	System.out.println("-1");
        else
        {
        	boolean f = true;

        	for(int i=0;i<n;i++)
        	{
        		for(int j=0;j<m;j++)
        		{
        			if(a[i][j] == 1)
        			{
        				f = false;
        				break;
        			}
        		}
        	}

        	if(!f)
        		System.out.println("-1");
        	else
        	{
        		System.out.println(p.size());
        		for(pair i:p)
        			System.out.println(i.r+" "+i.c+" "+i.l);
        	}
        }
    }

