public class Solution{


	static int[][] h, w;
	static int n, m;



    public static void main(String[] args) throws IOException {

    	FastScanner fs = new FastScanner();
    	PrintWriter out = new PrintWriter(System.out);



    	int tt = 1;
    	while(tt-->0) {


    		n = fs.nextInt();
    		m = fs.nextInt();

    		char[][] arr = new char[n][];
    		for(int i=0;i<n;i++) {
    			arr[i] = fs.next().toCharArray();
    		}

    		h = new int[n][m];
    		w = new int[n][m];


    		int[][] up = new int[n][m], down = new int[n][m], left = new int[n][m], right = new int[n][m];

    		for(int i=0;i<n;i++) {
    			for(int j=0;j<m;j++) {
    				if(i>0) {
    					if(arr[i][j]=='*')
    						up[i][j] = up[i-1][j] + 1;
    				}
    				else {
    					up[i][j] = (arr[i][j]=='*'?1:0);
    				}
    				if(j>0) {
    					if(arr[i][j]=='*')
    						left[i][j] = left[i][j-1] + 1;
    				}
    				else {
    					left[i][j] = (arr[i][j]=='*'?1:0);
    				}

    			}
    		}

    		for(int i=n-1;i>=0;i--) {
    			for(int j=m-1;j>=0;j--) {
    				if(i<n-1) {
    					if(arr[i][j]=='*')
    						down[i][j] = down[i+1][j] + 1;
    				}
    				else {
    					down[i][j] = arr[i][j]=='*'?1:0;
    				}
    				if(j<m-1) {
    					if(arr[i][j]=='*')
    						right[i][j] = right[i][j+1] + 1;
    				}
    				else {
    					right[i][j] = arr[i][j]=='*'?1:0;
    				}
    			}
    		}

    		ArrayList<int[]> list = new ArrayList<int[]>();

    		for(int i=0;i<n;i++) {
    			for(int j=0;j<m;j++) {
    				if(arr[i][j]=='*') {
    					int s = min(up[i][j], down[i][j], left[i][j], right[i][j]) - 1 ;
    					if(s>0) {
    						draw(i, j, s);
    						list.add(new int[] {i+1, j+1, s});
    					}
    				}
    			}
    		}


    		for(int i=0;i<n;i++) {
    			for(int j=0;j<m;j++) {
    				if(i>0) h[i][j] += h[i-1][j];
    				if(j>0) w[i][j] += w[i][j-1];
    			}
    		}


    		for(int i=0;i<n;i++) {
    			for(int j=0;j<m;j++) {
    				if(arr[i][j]=='*') {
    					if(h[i][j]==0 && w[i][j]==0) {
    						out.println(-1);
    						out.flush();
    						return;
    					}
    				}
    			}
    		}

    		out.println(list.size());
    		for(int[] a: list) {
    			out.println(a[0]+" "+a[1]+" "+a[2]);
    		}



    	}




    	out.close();

    }



    static void draw(int i, int j, int s) {
    	h[i-s][j]++;
    	if(i+s+1<=n-1) {
    		h[i+s+1][j]--;
    	}
    	w[i][j-s]++;
    	if(j+s+1<=m-1) {
    		w[i][j+s+1]--;
    	}
    }


    static int min(int a, int b, int c, int d) {
    	return Math.min(a, Math.min(b, Math.min(c,  d)));
    }




    static final Random random=new Random();

    static void ruffleSort(int[] a) {
    	int n=a.length;
    	for (int i=0; i<n; i++) {
    		int oi=random.nextInt(n); int temp=a[oi];
    		a[oi]=a[i]; a[i]=temp;
    	}
    	Arrays.sort(a);
    }





