public final class Solution {
    BufferedReader br;
    StringTokenizer stk;

    public static void main(String[] args) throws Exception {
        new Solution().run();
    }

    {
        stk = null;
        br = new BufferedReader(new InputStreamReader(System.in));
    }

    long mod = 1000_000_000 + 7;
    StringBuilder res = new StringBuilder(1000005);

    void run() throws Exception {
        int n = ni();
        int m = ni();
        int[][] up =    new int[n][m];
        int[][] down =  new int[n][m];
        int[][] right = new int[n][m];
        int[][] left =  new int[n][m];
        int[][] org =   new int[n][m];
        int[][] map =   new int[n][m];

        for(int i = 0; i < n; i++) {
            String s = nt();
            for(int j = 0; j < m; j++) {
                if(s.charAt(j) == '*') {
                    up[i][j] = down[i][j] = right[i][j] = left[i][j] = org[i][j] = 1;
                }
            }
        }
        for(int i = 1; i < n; i++) {
            for(int j = 0; j < m; j++) {
                if(up[i - 1][j] > 0 && up[i][j] > 0) {
                    up[i][j] += up[i - 1][j];
                }
            }
        }
        for(int i = 0; i < n; i++) {
            for(int j = 1; j < m; j++) {
                if(left[i][j - 1] > 0 && left[i][j] > 0) {
                    left[i][j] += left[i][j - 1];
                }
            }
        }
        for(int i = n - 2; i >= 0; i--) {
            for(int j = 0; j < m; j++) {
                if(down[i + 1][j] > 0 && down[i][j] > 0) {
                    down[i][j] += down[i + 1][j];
                }
            }
        }
        for(int i = 0; i < n; i++) {
            for(int j = m - 2; j >= 0; j--) {
                if(right[i][j + 1] > 0 && right[i][j] > 0) {
                    right[i][j] += right[i][j + 1];
                }
            }
        }

        List<Triplet> list = new ArrayList<>();
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                if(org[i][j] == 1) {
                    int min = Math.min(up[i][j], down[i][j]);
                    min = Math.min(min, Math.min(right[i][j], left[i][j]));
                    min--;
                    if(min >= 1) {
                        list.add(new Triplet(i + 1, j + 1, min));
                        for(int k = j - min; k <= j + min; k++) {
                            map[i][k] = 1;
                        }
                        for(int k = i - min; k <= i + min; k++) {
                            map[k][j] = 1;
                        }
                    }
                }
            }
        }

        boolean ok = true;
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                if(map[i][j] != org[i][j]) {
                    ok = false;
                    break;
                }
            }
        }
        if(!ok) {
            System.out.println("-1");
            return;
        }

        res.append(list.size()).append("\n");
        for(Triplet tri : list) {
            res.append(tri.a).append(" ").append(tri.b).append(" ").append(tri.c).append("\n");
        }
        System.out.print(res);
    }

    class Triplet {
        int a, b, c;
        public Triplet(int a, int b, int c) {
            this.a = a;
            this.b = b;
            this.c = c;
        }
    }


    String nextToken() throws Exception {
        if (stk == null || !stk.hasMoreTokens()) {
            stk = new StringTokenizer(br.readLine(), " ");
        }
        return stk.nextToken();
    }

    String nt() throws Exception {
        return nextToken();
    }

    int ni() throws Exception {
        return Integer.parseInt(nextToken());
    }

    long nl() throws Exception {
        return Long.parseLong(nextToken());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class Main {

	public static class Pair implements Comparable<Pair>{
		int start, end;
		public Pair(int start, int end){
			this.start = start;
			this.end = end;
		}
		@Override
		public int compareTo(Pair o) {
			return Integer.compare(this.start, o.start);
		}

	}

	public static class Star{
		int i, j, size;
		public Star(int i, int j, int size){
			this.i = i;
			this.j = j;
			this.size = size;
		}
	}

	public static void main(String[] args){
		InputReader sc = new InputReader(System.in);

		int n = sc.nextInt();
		int m = sc.nextInt();

		String[] grid = new String[n];

		for(int i = 0; i < n; i++){
			grid[i] = sc.nextLine();
		}

		int[][][] dp = new int[n][m][4];

		for(int i = 0; i < n; i++){
			for(int j = 1; j < m; j++){
				dp[i][j][0] = (grid[i].charAt(j - 1) == '*' ? dp[i][j - 1][0] + 1 : 0);
			}
		}
		for(int i = 0; i < n; i++){
			for(int j = m - 2; j >= 0; j--){
				dp[i][j][1] = (grid[i].charAt(j + 1) == '*' ? dp[i][j + 1][1] + 1 : 0);
			}
		}
		for(int i = 1; i < n; i++){
			for(int j = 0; j < m; j++){
				dp[i][j][2] = (grid[i - 1].charAt(j) == '*' ? dp[i - 1][j][2] + 1 : 0);
			}
		}

		for(int i = n - 2; i >= 0; i--){
			for(int j = 0; j < m; j++){
				dp[i][j][3] = (grid[i + 1].charAt(j) == '*' ? dp[i + 1][j][3] + 1 : 0);
			}
		}

		PriorityQueue<Pair>[] rows = new PriorityQueue[n];
		PriorityQueue<Pair>[] columns = new PriorityQueue[m];
		for(int i = 0; i < n; i++){
			rows[i] = new PriorityQueue<Pair>();
		}
		for(int i = 0; i < m; i++){
			columns[i] = new PriorityQueue<Pair>();
		}

		ArrayList<Star> stars = new ArrayList<Star>();

		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(grid[i].charAt(j) == '*'){
					int maxSize = Math.min(Math.min(dp[i][j][0], dp[i][j][1]), 
							Math.min(dp[i][j][2], dp[i][j][3]));
					if(maxSize > 0){
						stars.add(new Star(i, j, maxSize));

						Pair col = new Pair(i - maxSize, i + maxSize);
						Pair row = new Pair(j - maxSize, j + maxSize);

						columns[j].add(col);
						rows[i].add(row);

					}

				}
			}
		}

		boolean[][] ans = new boolean[n][m];

		for(int i = 0; i < n; i++){
			int maxEnd = 0;
			while(!rows[i].isEmpty()){
				Pair curr = rows[i].remove();
				int start = Math.max(curr.start, maxEnd);
				int end = curr.end;
				for(int j = start; j <= end; j++){
					ans[i][j] = true;
				}
				maxEnd = Math.max(maxEnd, end);
			}
		}

		for(int i = 0; i < m; i++){
			int maxEnd = 0;
			while(!columns[i].isEmpty()){
				Pair curr = columns[i].remove();
				int start = Math.max(curr.start, maxEnd);
				int end = curr.end;
				for(int j = start; j <= end; j++){
					ans[j][i] = true;
				}
				maxEnd = Math.max(maxEnd, end);
			}
		}

		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(grid[i].charAt(j) == '*' && !ans[i][j]){
					System.out.println(-1);
					return;
				}
			}
		}

		PrintWriter out = new PrintWriter(System.out);
		out.println(stars.size());
		for(Star s : stars){
			out.println((s.i + 1) + " " + (s.j + 1) + " " + s.size);
		}
		out.close();
	}

	static class InputReader {
		public BufferedReader reader;
		public StringTokenizer tokenizer;

		public InputReader(InputStream stream) {
			reader = new BufferedReader(new InputStreamReader(stream), 32768);
			tokenizer = null;
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public String nextLine() {
			String str = "";
			try {
				str = reader.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}

			return str;
		}
	}

}

