public class E1015 {

    public static void main(String[] args) {
        FasterScanner fs = new FasterScanner();

        int n = fs.nextInt();
        int m = fs.nextInt();

        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = fs.nextLine().toCharArray();
        }

        int dimension = Math.max(n, m);

        int freq[][][] = new int[dimension][dimension][4];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '*') {
                    continue;
                }

                int upCount = 0;

                int x = i;
                int y = j;

                while (--x >= 0 && grid[x][y] == '*') {
                    upCount++;
                }

                if (upCount == 0) {
                    continue;
                }

                x = i;
                y = j;

                int leftCount = 0;

                while (--y >= 0 && grid[x][y] == '*') {
                    leftCount++;
                }

                if (leftCount == 0) {
                    continue;
                }

                x = i;
                y = j;

                int rightCount = 0;

                while (++y < m && grid[x][y] == '*') {
                    rightCount++;
                }

                if (rightCount == 0) {
                    continue;
                }

                x = i;
                y = j;

                int downCount = 0;

                while (++x < n && grid[x][y] == '*') {
                    downCount++;
                }

                if (downCount == 0) {
                    continue;
                }

                freq[i][j][0] = upCount;
                freq[i][j][1] = leftCount;
                freq[i][j][2] = rightCount;
                freq[i][j][3] = downCount;
            }
        }

        StringBuilder result = new StringBuilder();
        int count = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int startLength = Math.min(Math.min(freq[i][j][0], freq[i][j][1]),
                        Math.min(freq[i][j][2], freq[i][j][3]));

                if (startLength > 0) {
                    result.append(i + 1).append(" ").append(j + 1).append(" ").append(startLength).append("\n");

                    count++;

                    grid[i][j] = '#';

                    int x = i;
                    int y = j;
                    int c = startLength;

                    while (c > 0) {
                        x--;
                        c--;
                        grid[x][y] = '#';
                    }

                    x = i;
                    y = j;
                    c = startLength;

                    while (c > 0) {
                        y--;
                        c--;
                        grid[x][y] = '#';
                    }

                    x = i;
                    y = j;
                    c = startLength;

                    while (c > 0) {
                        y++;
                        c--;
                        grid[x][y] = '#';
                    }

                    x = i;
                    y = j;
                    c = startLength;

                    while (c > 0) {
                        x++;
                        c--;
                        grid[x][y] = '#';
                    }
                }
            }
        }

        boolean solvable = validateGrid(grid);

        System.out.println(solvable? count + "\n" + result : -1);
    }

    private static boolean validateGrid(char[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == '*') {

                    return false;
                }
            }
        }

        return true;
    }

    public static class FasterScanner {
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = System.in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

