		for(int i = 0; i < r; i++){
			for(int j = 0; j < c; j++){
				if(grid[i][j]){
					max[i][j] = Math.min(Math.min(commfr[i][j], commbr[i][j]), Math.min(commfc[i][j], commbc[i][j])) - 1;
				}
			}
		}

		SegmentTree [] srow = new SegmentTree [r];
		SegmentTree [] scol = new SegmentTree [c];

		int N = 1; while(N < r) N <<= 1; 
		for(int i = 0; i < c; i++){
			scol[i]  = new SegmentTree(N);
		}

		N = 1; while(N < c) N <<= 1;

		for(int i = 0; i < r; i++){
			srow[i] = new SegmentTree(N);
			for(int j = 0; j < c; j++){
				if(max[i][j] != 0){
					srow[i].update_range(j + 1 - max[i][j], j + 1 + max[i][j], 1);
					scol[j].update_range(i+1 - max[i][j], i + 1 + max[i][j], 1);
				}
			}
		}
		boolean poss = true;
	L1:	for(int i = 0; i < r; i++){
			for(int j = 0; j < c; j++){
				if(grid[i][j]){
					if (Math.max(srow[i].query(j+1, j+1), scol[j].query(i + 1, i + 1))< 1){
						poss = false;
						break L1;
					}
				}
			}
		}

		if(!poss){
			out.println(-1);
		} else {
			int count = 0;
			StringBuilder sb = new StringBuilder("");
			for(int i = 0;  i < r; i++){
				for(int j = 0; j < c; j++){
					if(max[i][j] != 0){
						sb.append((i + 1) +" " + (j +  1) +" " + max[i][j]+"\n");
						count++;
					}
				}
			}
			out.println(count);
			out.println(sb);
		}

		out.flush();
		out.close();
	}

	static class SegmentTree {		

		int N; 			
		int[] sTree, lazy;

		SegmentTree(int N)		
		{
			this.N = N;
			sTree = new int[N<<1];		
			lazy = new int[N<<1];

		}

		void update_point(int index, int val)			
		{
			index += N - 1;				
			sTree[index] += val;			
			while(index>1)				
			{
				index >>= 1;
				sTree[index] = sTree[index<<1] + sTree[(index<<1) + 1];		
			}
		}


		void update_range(int i, int j, int val)		
		{
			update_range(1,1,N,i,j,val);
		}

		void update_range(int node, int b, int e, int i, int j, int val)
		{
			if(i > e || j < b)		
				return;
			if(b >= i && e <= j)		
			{
				sTree[node] += (e-b+1)*val;			
				lazy[node] += val;				
			}							
			else		
			{
				propagate(node, b, e);
				update_range(node<<1,b,(b+e)/2,i,j,val);
				update_range((node<<1)+1,(b+e)/2+1,e,i,j,val);
				sTree[node] = sTree[node<<1] + sTree[(node<<1)+1];		
			}

		}
		void propagate(int node, int b, int e)		
		{
			int mid = (b+e)/2;
			lazy[node<<1] += lazy[node];
			lazy[(node<<1)+1] += lazy[node];
			sTree[node<<1] += (mid-b+1)*lazy[node];		
			sTree[(node<<1)+1] += (e-mid)*lazy[node];		
			lazy[node] = 0;
		}

		int query(int i, int j)
		{
			return query(1,1,N,i,j);
		}

		int query(int node, int b, int e, int i, int j)	
		{
			if(i>e || j <b)
				return 0;		
			if(b>= i && e <= j)
				return sTree[node];
			propagate(node, b, e);
			int q1 = query(node<<1,b,(b+e)/2,i,j);
			int q2 = query((node<<1)+1,(b+e)/2+1,e,i,j);
			return q1 + q2;	

		}
	}

	static class Scanner {
		StringTokenizer st;
		BufferedReader br;

		public Scanner(InputStream s) {
			br = new BufferedReader(new InputStreamReader(s));
		}

		public String next() throws IOException {
			while (st == null || !st.hasMoreTokens())
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		public int nextInt() throws IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws IOException {
			return Long.parseLong(next());
		}

		public String nextLine() throws IOException {
			return br.readLine();
		}

		public double nextDouble() throws IOException {
			String x = next();
			StringBuilder sb = new StringBuilder("0");
			double res = 0, f = 1;
			boolean dec = false, neg = false;
			int start = 0;
			if (x.charAt(0) == '-') {
				neg = true;
				start++;
			}
			for (int i = start; i < x.length(); i++)
				if (x.charAt(i) == '.') {
					res = Long.parseLong(sb.toString());
					sb = new StringBuilder("0");
					dec = true;
				} else {
					sb.append(x.charAt(i));
					if (dec)
						f *= 10;
				}
			res += Long.parseLong(sb.toString()) / f;
			return res * (neg ? -1 : 1);
		}

		public boolean ready() throws IOException {
			return br.ready();
		}

	}

}

