public class Solve6 {

    public static void main(String[] args) throws IOException {
        PrintWriter pw = new PrintWriter(System.out);
        new Solve6().solve(pw);
        pw.flush();
        pw.close();
    }

    public void solve(PrintWriter pw) throws IOException {
        FastReader sc = new FastReader();
        int n = sc.nextInt(), m = sc.nextInt();
        char[][] s = new char[n][m];
        for (int i = 0; i < n; i++) {
            s[i] = sc.next().toCharArray();
        }
        int[][] rowpre = new int[n][m], rowsuff = new int[n][m];
        int[][] colpre = new int[n][m], colsuff = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0, k = m - 1; j < m; j++, k--) {
                if (s[i][j] == '*') {
                    rowpre[i][j] = (j == 0 ? 0 : rowpre[i][j - 1]) + 1;
                }
                if (s[i][k] == '*') {
                    rowsuff[i][k] = (k + 1 == m ? 0 : rowsuff[i][k + 1]) + 1;
                }
            }
        }
        for (int j = 0; j < m; j++) {
            for (int i = 0, k = n - 1; i < n; i++, k--) {
                if (s[i][j] == '*') {
                    colpre[i][j] = (i == 0 ? 0 : colpre[i - 1][j]) + 1;
                }
                if (s[k][j] == '*') {
                    colsuff[k][j] = (k + 1 == n ? 0 : colsuff[k + 1][j]) + 1;
                }
            }
        }
        int[][] b = new int[n][m];
        int[][] c = new int[n][m];
        ArrayList<Star> ans = new ArrayList();
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (s[i][j] == '*') {
                    int min = Math.min(rowpre[i][j - 1], rowsuff[i][j + 1]);
                    min = Math.min(min, Math.min(colpre[i - 1][j], colsuff[i + 1][j]));
                    if (min > 0) {
                        b[i][j - min] = Math.max(b[i][j - min], 2 * min + 1);
                        c[i - min][j] = Math.max(c[i - min][j], 2 * min + 1);
                        ans.add(new Star(i + 1, j + 1, min));
                    }
                }
            }
        }
        boolean[][] cnt = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            int x = 0;
            for (int j = 0; j < m; j++) {
                x = Math.max(x, b[i][j]);
                if (x > 0) {
                    cnt[i][j] = true;
                    --x;
                }
            }
        }
        for (int j = 0; j < m; j++) {
            int x = 0;
            for (int i = 0; i < n; i++) {
                x = Math.max(x, c[i][j]);
                if (x > 0) {
                    cnt[i][j] = true;
                    --x;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s[i][j] == '*' && !cnt[i][j]) {
                    pw.println(-1);
                    return;
                }
            }
        }
        pw.println(ans.size());
        for (int i = 0; i < ans.size(); i++) {
            pw.println(ans.get(i).x + " " + ans.get(i).y + " " + ans.get(i).s);
        }
    }

    class Star {

        int x, y, s;

        public Star(int x, int y, int s) {
            this.x = x;
            this.y = y;
            this.s = s;
        }
    }

    static class FastReader {

        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public FastReader(String s) {
            try {
                br = new BufferedReader(new FileReader(s));
            } catch (FileNotFoundException e) {
            }
        }

        public String next() {
            if (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (Exception e) {
            }
            return null;
        }

        public boolean hasNext() throws IOException {
            if (st != null && st.hasMoreTokens()) {
                return true;
            }
            String s = br.readLine();
            if (s == null || s.isEmpty()) {
                return false;
            }
            st = new StringTokenizer(s);
            return true;
        }
    }
}

