public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Kattio in = new Kattio(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE1 solver = new TaskE1();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE1 {
        public void solve(int testNumber, Kattio in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] arr = new char[n][m];
            for (int i = 0; i < n; ++i) {
                arr[i] = in.next().toCharArray();
            }

            ArrayList<Star> ans = new ArrayList<>();
            boolean[][] vis = new boolean[n][m];
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (arr[i][j] == '*') {
                        int size = getSize(arr, i, j, n, m);
                        if (size > 0) {
                            ans.add(new Star(i + 1, j + 1, size));
                            markVisited(vis, i, j, size);
                        }
                    }
                }
            }


            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (arr[i][j] == '*')
                        if (!vis[i][j]) {
                            out.println(-1);
                            return;
                        }
                }
            }

            out.println(ans.size());
            ans.stream().forEach(out::println);

        }

        private void markVisited(boolean[][] vis, int i, int j, int size) {

            for (int k = 0; k <= size; ++k) {
                vis[i + k][j] = true;
                vis[i - k][j] = true;
                vis[i][j + k] = true;
                vis[i][j - k] = true;
            }
        }

        private int getSize(char[][] arr, int i, int j, int n, int m) {
            int size = 0;
            for (size = 0; size < n && size < m; ++size) {
                if (i + size >= n || i - size < 0 || j + size >= m || j - size < 0)
                    break;

                if (arr[i + size][j] != '*'
                        || arr[i - size][j] != '*'
                        || arr[i][j + size] != '*'
                        || arr[i][j - size] != '*')
                    break;
            }

            return size - 1;
        }

        public class Star {
            int x;
            int y;
            int l;

            public Star(int x, int y, int l) {
                this.x = x;
                this.y = y;
                this.l = l;
            }


            public String toString() {
                return x + " " + y + " " + l;
            }

        }

    }

    static class Kattio extends PrintWriter {
        private BufferedReader r;
        private String line;
        private StringTokenizer st;
        private String token;

        public Kattio(InputStream i) {
            super(new BufferedOutputStream(System.out));
            r = new BufferedReader(new InputStreamReader(i));
        }

        public Kattio(InputStream i, OutputStream o) {
            super(new BufferedOutputStream(o));
            r = new BufferedReader(new InputStreamReader(i));
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public String next() {
            return nextToken();
        }

        private String peekToken() {
            if (token == null)
                try {
                    while (st == null || !st.hasMoreTokens()) {
                        line = r.readLine();
                        if (line == null) return null;
                        st = new StringTokenizer(line);
                    }
                    token = st.nextToken();
                } catch (IOException e) {
                }
            return token;
        }

        private String nextToken() {
            String ans = peekToken();
            token = null;
            return ans;
        }

    }
}

