		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		Task solver = new Task();
		solver.solve(1, in, out);
		out.close();
	}

	static class Task {
		public void solve(int testNumber, InputReader in, PrintWriter out) {
			int n = in.nextInt();
			int m = in.nextInt();
			char[][] grid = new char[n][m];
			for (int i = 0; i < n; i++) {
				grid[i] = in.next().toCharArray();
			}
			List<Pair> pairs = new ArrayList<>();
			for (int i = 1; i < n - 1; i++) {
				for (int j = 1; j < m - 1; j++) {
					if (grid[i][j] == '*' && grid[i - 1][j] == '*' && grid[i + 1][j] == '*' && grid[i][j - 1] == '*' && grid[i][j + 1] == '*') {
						pairs.add(new Pair(i, j));
					}
				}
			}
			List<Triple> tris = new ArrayList<>();
			for (int i = 0; i < pairs.size(); i++) {
				Pair p = pairs.get(i);
				grid[p.x][p.y] = '1';
				int maxRay = 0;
				for (int j = 1; j < Math.min(n, m); j++) {
					if (p.x - j >= 0 && p.x + j < n && p.y - j >= 0 && p.y + j < m) {
						if (grid[p.x - j][p.y] != '.' && grid[p.x + j][p.y] != '.' && grid[p.x][p.y-j] != '.' && grid[p.x][p.y+j] != '.') {
							grid[p.x - j][p.y] = '1';
							grid[p.x + j][p.y] = '1';
							grid[p.x][p.y-j] = '1';
							grid[p.x][p.y+j] = '1';
							maxRay = j;
						} else {
							break;
						}
					} else {
						break;
					}
				}
				if (maxRay > 0) {
					tris.add(new Triple(p.x, p.y, maxRay));
				}
			}
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					if (grid[i][j] == '*') {
						out.println(-1);
						return;
					}
				}
			}
			out.println(tris.size());
			for (int i = 0; i < tris.size(); i++) {
				Triple tri = tris.get(i);
				out.println((tri.x+1) + " " + (tri.y+1) + " " + tri.ray);
			}
		}

		static class Pair {
			int x;
			int y;

			public Pair(int x, int y) {
				this.x = x;
				this.y = y;
			}
		}

		static class Triple {
			int x;
			int y;
			int ray;

			public Triple(int x, int y, int ray) {
				this.x = x;
				this.y = y;
				this.ray = ray;
			}
		}
	}

	static class InputReader {
