				if(chs[i][j] == '*') RL[i][j] = (j<m-1?RL[i][j+1]:0)+1;
			}
		}

		UD = new int[n][m];
		for(int j = 0; j < m; j++) {
			for(int i = 0; i < n; i++) {
				if(chs[i][j] == '*') UD[i][j] = (i>0?UD[i-1][j]:0)+1;
			}
		}

		DU = new int[n][m];
		for(int j = 0; j < m; j++) {
			for(int i = n-1; i >= 0; i--) {
				if(chs[i][j] == '*') DU[i][j] = (i<n-1?DU[i+1][j]:0)+1;
			}
		}


		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(chs[i][j] == '*') doit(i,j);
			}
		}
		boolean ok = true;
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(chs[i][j] != cht[i][j]) ok = false;
			}
		}
		if(!ok) out.println(-1);
		else {
			out.println(res.size());
			for(Integer[] cur : res) {
				out.println(cur[0]+" "+cur[1]+" "+cur[2]);
			}
		}
	}

	char[][] cht;
	ArrayList<Integer[]> res;

	void doit(int i, int j) {
		int k = Math.min(LR[i][j], RL[i][j]);
		k = Math.min(k, UD[i][j]);
		k = Math.min(k, DU[i][j]);

		k--;
		if(k > 0) {
			res.add(new Integer[] {i+1,j+1,k});
			while(k >= 0) {
				draw(i+k,j);
				draw(i-k,j);
				draw(i,j+k);
				draw(i,j-k);
				k--;
			}
		}

	}

	void draw(int x, int y) {
		cht[x][y] = '*';
	}

	boolean verify(int x, int y) {
		if(0 <= x && x < n && 0 <= y && y < m && chs[x][y] == '*') return true;
		else return false;
	}

	public static void main(String[] args) {
		(new E984()).run();
	} 

	private BufferedReader in;
	private PrintWriter out;
	private StringTokenizer tokenizer;

	public void run() {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			tokenizer = null;
			out = new PrintWriter(System.out);
			solve();
			in.close();
			out.close();
		} catch (Exception e) {
			e.printStackTrace();
			System.exit(1);
		}
