    static class E1StarsDrawingEasyEdition {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt(), m = in.nextInt();
            char c[][] = new char[n][];
            for (int i = 0; i < n; i++) {
                c[i] = in.next().toCharArray();
            }
            StringBuilder s = new StringBuilder();
            int l[][] = new int[n][m];
            int r[][] = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 1; j < m; j++) {
                    if (c[i][j - 1] == '*' && c[i][j] == '*') {
                        l[i][j] = l[i][j - 1] + 1;
                    }
                }
                for (int j = m - 2; j >= 0; j--) {
                    if (c[i][j + 1] == '*' && c[i][j] == '*') {
                        r[i][j] = r[i][j + 1] + 1;
                    }
                }
            }
            int u[][] = new int[n][m];
            int d[][] = new int[n][m];
            for (int i = 0; i < m; i++) {
                for (int j = 1; j < n; j++) {
                    if (c[j - 1][i] == '*' && c[j][i] == '*') {
                        u[j][i] = u[j - 1][i] + 1;
                    }
                }
                for (int j = n - 2; j >= 0; j--) {
                    if (c[j + 1][i] == '*' && c[j][i] == '*') {
                        d[j][i] = d[j + 1][i] + 1;
                    }
                }
            }
            int ct = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int tm = Math.min(Math.min(l[i][j], r[i][j]), Math.min(u[i][j], d[i][j]));
                    if (tm > 0) {
                        s.append((i + 1) + " " + (j + 1) + " " + tm + "\n");
                        ct++;
                        d[i][j] = u[i][j] = r[i][j] = l[i][j] = tm + 1;
                    } else {
                        d[i][j] = u[i][j] = r[i][j] = l[i][j] = 0;
                    }
                }
            }
            boolean v[][] = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                int max = 0;
                for (int j = 0; j < m; j++) {
                    max = Math.max(max, r[i][j]);
                    if (max > 0) {
                        v[i][j] = true;
                        max--;
                    }
                }
                max = 0;
                for (int j = m - 1; j >= 0; j--) {
                    max = Math.max(max, l[i][j]);
                    if (max > 0) {
                        v[i][j] = true;
                        max--;
                    }
                }
            }
            for (int i = 0; i < m; i++) {
                int max = 0;
                for (int j = 0; j < n; j++) {
                    max = Math.max(max, u[j][i]);
                    if (max > 0) {
                        v[j][i] = true;
                        max--;
                    }
                }
                max = 0;
                for (int j = n - 1; j >= 0; j--) {
                    max = Math.max(max, d[j][i]);
                    if (max > 0) {
                        v[j][i] = true;
                        max--;
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (c[i][j] == '*' && !v[i][j]) {
                        out.println(-1);
                        return;
                    }
                }
            }
            out.println(ct);
            out.println(s);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));

            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            }
            while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return readString();
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.io.*;
