    public static void main(String[] args) throws IOException{




		MyScanner sc = new MyScanner();
		out = new PrintWriter(new BufferedOutputStream(System.out));


		int n = sc.nextInt();
		int m = sc.nextInt();

		String[] cur = new String[n];

		for(int i = 0; i < n; i++){
			cur[i] = sc.nextLine();
		}

		int[][] up = new int[n][m];
		int[][] down = new int[n][m];
		int[][] left = new int[n][m];
		int[][] right = new int[n][m];

		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(i == 0){
					if(cur[i].charAt(j) == '*') up[i][j] = 0;
					else up[i][j] = -1;
				}else{
					if(cur[i].charAt(j) == '*') up[i][j] = 1 + up[i-1][j];
					else up[i][j] = -1;
				}

				if(j == 0){
					if(cur[i].charAt(j) == '*') left[i][j] = 0;
					else left[i][j] = -1;
				}else{
					if(cur[i].charAt(j) == '*') left[i][j] = 1 + left[i][j-1];
					else left[i][j] = -1;
				}

			}
		}

		for(int i = n - 1; i >= 0; i--){
			for(int j = m - 1; j >= 0; j--){
				if(i == n - 1){
					if(cur[i].charAt(j) == '*') down[i][j] = 0;
					else down[i][j] = -1;
				}else{
					if(cur[i].charAt(j) == '*') down[i][j] = 1 + down[i+1][j];
					else down[i][j] = -1;
				}

				if(j == m - 1){
					if(cur[i].charAt(j) == '*') right[i][j] = 0;
					else right[i][j] = -1;
				}else{
					if(cur[i].charAt(j) == '*') right[i][j] = 1 + right[i][j+1];
					else right[i][j] = -1;
				}
			}
		}

		ArrayList<Node> arrayList = new ArrayList<>();

		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(cur[i].charAt(j) == '*'){
					int len = Math.min(Math.min(up[i][j], down[i][j]), Math.min(left[i][j], right[i][j]));
					if(len > 0) arrayList.add(new Node(i, j, len));
				}
			}
		}

		int[][] h = new int[n][m];
		int[][] v = new int[n][m];

		for(Node temp: arrayList){
			h[temp.i][temp.j - temp.length]++;
			if(temp.j + temp.length + 1 < m) h[temp.i][temp.j + temp.length + 1]--;

			v[temp.i - temp.length][temp.j]++;
			if(temp.i + temp.length + 1 < n) v[temp.i + temp.length + 1][temp.j]--;
		}

		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(j > 0) h[i][j] += h[i][j-1];
				if(i > 0) v[i][j] += v[i-1][j];
			}
		}

		boolean flag = true;

		label1: 
		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(cur[i].charAt(j) == '*'){
					if(h[i][j] <= 0 && v[i][j] <= 0){
						out.println(-1);
						flag = false;
						break label1;
					}
				}
			}
		}

		if(flag){
			out.println(arrayList.size());
			for(Node temp: arrayList)
				out.println((temp.i + 1) + " " + (temp.j + 1) + " " + temp.length);
		}



		out.close();
    }

