    static class TaskE2 {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            boolean[][] a = new boolean[n][m];
            ArrayList<Pair> p = new ArrayList<>();

            ArrayList<Pair> ans = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                StringBuilder sb = new StringBuilder(in.next());
                for (int j = 0; j < m; j++) {
                    if (sb.charAt(j) == '.') a[i][j] = false;
                    else {
                        a[i][j] = true;
                        p.add(new Pair(i, j));
                    }
                }
            }

            for (int k = 0; k < p.size(); k++) {
                Pair x = p.get(k);
                int i = x.a;
                int j = x.b;

                int w = 0;

                while (true) {
                    if (i + w + 1 < n && i - (w + 1) >= 0 && j + (w + 1) < m && j - (w + 1) >= 0) {
                        if (a[i + w + 1][j] && a[i - (w + 1)][j] && a[i][j + w + 1] && a[i][j - (w + 1)]) {
                            w++;
                            continue;
                        }
                        break;
                    } else {
                        break;
                    }
                }

                if (w > 0) {
                    ans.add(new Pair(i, j, w));
                }
            }

            boolean x[][] = new boolean[n][m];
            boolean flag = true;

            for (Pair z : ans) {
                int i = z.a;
                int j = z.b;
                int w = z.w;

                x[i][j] = true;

                for (int k = 1; k <= w; k++) {
                    x[i + k][j] = true;
                    x[i - k][j] = true;
                    x[i][j + k] = true;
                    x[i][j - k] = true;
                }
            }

            outer:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++)
                    if (a[i][j] != x[i][j]) {
                        flag = false;
                        break outer;
                    }
            }

            if (flag) {
                out.println(ans.size());
                for (Pair z : ans) {
                    out.println((z.a + 1) + " " + (z.b + 1) + " " + z.w);
                }
            } else {
                out.println("-1");
            }
        }

    }

    static class Pair implements Comparable<Pair> {
        int a;
        int b;
        int w;

        Pair(int a, int b) {
            this.a = a;
            this.b = b;
        }

        Pair(int a, int b, int w) {
            this.a = a;
