		List<int[]> placed = new ArrayList<int[]>();

		int m = sc.nextInt();
		int n = sc.nextInt();

		String[] grid = new String[m];
		for (int i = 0; i < m; i++) {
			grid[i] = sc.next();
		}

		boolean[][] centered = new boolean[m][n];
		boolean[][] covered = new boolean[m][n];

		int[][] up = new int[m][n];
		int[][] down = new int[m][n];
		int[][] left = new int[m][n];
		int[][] right = new int[m][n];


		for (int r = 0; r < m; r++) {
			for (int c = 0; c < n; c++) {
				if (grid[r].charAt(c) == '*') {
					up[r][c] = 1;
					left[r][c] = 1;

					if (r > 0) up[r][c] += up[r-1][c];
					if (c > 0) left[r][c] += left[r][c-1];
				}
			}
		}


		for (int r = m-1; r >= 0; r--) {
			for (int c = n-1; c >= 0; c--) {
				if (grid[r].charAt(c) == '*') {
					down[r][c] = 1;
					right[r][c] = 1;

					if (r + 1 < m) down[r][c] += down[r+1][c];
					if (c + 1 < n) right[r][c] += right[r][c+1];
				}
			}
		}


		for (int size = Math.min((m - 1) / 2, (n - 1) / 2); size >= 1; size--) {
			for (int r = 0; r < m; r++) {
				for (int c = 0; c < n; c++) {
					if (grid[r].charAt(c) == '*') {

						if (!centered[r][c]) {
							if (up[r][c] >= size+1 && down[r][c] >= size+1 && left[r][c] >= size+1 && right[r][c] >= size+1) {

								centered[r][c] = true;
								covered[r][c] = true;

								placed.add(new int[] {r+1, c+1, size});


								for (int offset = 1; offset <= size; offset++) {
									covered[r+offset][c] = true;
									covered[r-offset][c] = true;
									covered[r][c+offset] = true;
									covered[r][c-offset] = true;
								}
							}
						}
					}
				}
			}
		}




		boolean isPossible = true;

		for (int r = 0; r < m; r++) {
			for (int c = 0; c < n; c++) {
				if (grid[r].charAt(c) == '*') {
					if (!covered[r][c]) {
						isPossible = false;
						break;
					}
				}
			}
		}

		if (placed.size() > m*n) {
			isPossible = false;
		}

		if (isPossible) {
			out.println(placed.size());

			for (int[] arr : placed) {
				out.println(arr[0] + " " + arr[1] + " " + arr[2]);
			}
		}
		else {
			out.println(-1);
		}


		out.close();
	}
