        int t = 1;
        for (int tc = 0; tc < t; tc++) {
            int n = fs.ni(), m = fs.ni();
            int[][] matrix = new int[n][m];
            int[][] left = new int[n][m];
            int[][] right = new int[n][m];
            int[][] up = new int[n][m];
            int[][] down = new int[n][m];
            for (int i = 0; i < n; i++) {
                String s = fs.next();

                for (int j = 0; j < m; j++) {
                    if (s.charAt(j)=='*') {
                        matrix[i][j]++;
                        left[i][j]++;
                        right[i][j]++;
                        up[i][j]++;
                        down[i][j]++;
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (j!=0 && matrix[i][j]==1) {
                        left[i][j] += left[i][j-1];
                    }
                }
                for (int j = m-1; j > -1; j--) {
                    if (j!=m-1 && matrix[i][j]==1) {
                        right[i][j] += right[i][j+1];
                    }
                }
            }

            for (int j = 0; j < m; j++) {
                for (int i = 0; i < n; i++) {
                    if (i!=0 && matrix[i][j]==1) {
                        up[i][j] += up[i-1][j];
                    }
                }
                for (int i = n-1; i > -1; i--) {
                    if (i!=n-1 && matrix[i][j]==1) {
                        down[i][j] += down[i+1][j];
                    }
                }
            }

            int k = 0;
            int[][] r = new int[n][m];
            int[][] c = new int[n][m];
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int s = left[i][j];
                    s = Math.min(s,right[i][j]);
                    s = Math.min(s,up[i][j]);
                    s = Math.min(s,down[i][j]);
                    s--;
                    if (s>0) {
                        k++;
                        sb.append((i+1) + " " + (j+1) + " " + s);
                        sb.append("\n");
                        r[i-s][j]++;
                        if (i+s+1<n) r[i+s+1][j]--;
                        c[i][j-s]++;
                        if (j+s+1<m) c[i][j+s+1]--;
                    }
                }
            }

            boolean flag = true;
            boolean[][] good = new boolean[n][m];
            int s = 0;
            for (int i = 0; i < n; i++) {
                s = 0;
                for (int j = 0; j < m; j++) {
                    s += c[i][j];
                    if (s>0) good[i][j]=true;
                }
            }
            for (int j = 0; j < m; j++) {
                s = 0;
                for (int i = 0; i < n; i++) {
                    s += r[i][j];
                    if (s>0) good[i][j]=true;
                    if (matrix[i][j]==1 && !good[i][j]) {
                        flag = false;
                        break;
                    }
                }
            }


            if (flag) {
                pw.println(k);
                pw.println(sb);
            } else {
                pw.println(-1);

            }
        }
        pw.close();
    }
    public static boolean in(int r, int c, int n, int m) {
        if (r<0 || c<0 || r>=n || c>=m) return true;
        return false;
    }
