public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        E1StarsDrawingEasyEdition solver = new E1StarsDrawingEasyEdition();
        solver.solve(1, in, out);
        out.close();
    }

    static class E1StarsDrawingEasyEdition {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] matrix = new char[n][];
            for (int i = 0; i < n; i++) {
                matrix[i] = in.next().toCharArray();
            }

            Stack<Star> stars = new Stack<>();

            findSolution(matrix, stars);

            if (check(matrix)) {
                out.println(stars.size());
                while (!stars.empty()) {
                    Star s = stars.pop();
                    out.printf("%d %d %d\n", s.x + 1, s.y + 1, s.len);
                }
            } else {
                out.println(-1);
            }
        }

        private boolean check(char[][] matrix) {
            for (int i = 0; i < matrix.length; i++) {
                for (int j = 0; j < matrix[0].length; j++) {
                    if (matrix[i][j] == '*') return false;
                }
            }
            return true;
        }

        private void findSolution(char[][] matrix, Stack<Star> stars) {
            int maxLen = Math.min(matrix.length, matrix[0].length);
            for (int i = 0; i < matrix.length; i++) {
                for (int j = 0; j < matrix[0].length; j++) {

                    if (matrix[i][j] != '.') {
                        for (int k = maxLen; k >= 1; k--) {
                            if (placed(i, j, k, matrix)) {
                                stars.push(new Star(i, j, k));
                                break;
                            }
                        }
                    }
                }
            }

        }

        private boolean placed(int x, int y, int len, char[][] matrix) {
            for (int i = x - len; i <= x + len; ++i) {
                if (i < 0 || i >= matrix.length || matrix[i][y] == '.') {
                    return false;
                }
            }
            for (int i = y - len; i <= y + len; ++i) {
                if (i < 0 || i >= matrix[0].length || matrix[x][i] == '.') {
                    return false;
                }
            }

            drawStar(x, y, len, matrix, '#');
            return true;
        }

        private void drawStar(int x, int y, int len, char[][] matrix, char c) {
            for (int i = x - len; i <= x + len; ++i) {
                matrix[i][y] = c;
            }
            for (int i = y - len; i <= y + len; ++i) {
                matrix[x][i] = c;
            }
        }

        class Star {
            int x;
            int y;
            int len;

            public Star(int x, int y, int len) {
                this.x = x;
                this.y = y;
                this.len = len;
            }

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

