		for(int k = i - size; k <= i + size; k++) {
			if(memo[k][j] == null) return false;
		}
		for(int k = j - size; k <= j + size; k++) {
			if(memo[i][k] == null) return false;
		}
		for(int k = i - size; k <= i + size; k++) {
			memo[k][j] = true;
		}
		for(int k = j - size; k <= j + size; k++) {
			memo[i][k] = true;
		}
		return true;
	}

