public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE1 solver = new TaskE1();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE1 {
        int n;
        int m;
        boolean[][] mrk;
        int[][] grid;

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();

            mrk = new boolean[n + 1][m + 1];
            grid = new int[n + 1][m + 1];
            for (int i = 0; i < n; i++) {
                String s = in.nextLine();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = s.charAt(j) == '.' ? 0 : 1;
                }
            }
            List<Star> y = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 1) {
                        int p = mxLength(i, j);
                        if (p > 0) {
                            mrk[i][j] = true;
                            y.add(new Star(i + 1, j + 1, p));
                            color(i, j, p);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {

                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 1 && !mrk[i][j]) {
                        out.print(-1);
                        return;
                    }
                }
            }

            out.println(y.size());
            for (Star x : y) {
                out.println(x.x + " " + x.y + " " + x.r);
            }

        }

        private void color(int x, int y, int p) {
            for (int i = x - 1; i >= x - p; i--) {
                mrk[i][y] = true;
            }

            for (int i = y - 1; i >= y - p; i--) {
                mrk[x][i] = true;
            }

            for (int i = x + 1; i <= x + p; i++) {
                mrk[i][y] = true;
            }

            for (int i = y + 1; i <= y + p; i++) {
                mrk[x][i] = true;
            }
        }

        private int mxLength(int x, int y) {
            int l1 = 0, l2 = 0, l3 = 0, l4 = 0;
            for (int i = x - 1; i >= 0; i--) {
                if (grid[i][y] == 1) l1++;
                else break;
            }

            for (int i = x + 1; i < n; i++) {
                if (grid[i][y] == 1) l2++;
                else break;
            }

            for (int i = y - 1; i >= 0; i--) {
                if (grid[x][i] == 1) l3++;
                else break;
            }

            for (int i = y + 1; i < m; i++) {
                if (grid[x][i] == 1) l4++;
                else break;
            }
            return Math.min(Math.min(l1, l2), Math.min(l3, l4));
        }

        private class Star {
            int x;
            int y;
            int r;

            public Star(int x, int y, int r) {
                this.x = x;
                this.y = y;
                this.r = r;
            }

        }

    }

