public class E1_StarPainting {

    public static void main(String[] args) throws IOException {

        MyScanner sc = new MyScanner();
        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] input = new char[n][m];

        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < m; j++) {
                input[i][j] = line.charAt(j);
            }
        }

        int[][] leftStarsCount = new int[n][m];
        int[][] rightStarsCount = new int[n][m];
        int[][] topStarsCount = new int[n][m];
        int[][] bottomStarsCount = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                leftStarsCount[i][j] = input[i][j] == '*' && input[i][j - 1] == '*' ? leftStarsCount[i][j - 1] + 1 : 0;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = m - 2; j >= 0; j--) {
               rightStarsCount[i][j] = input[i][j] == '*' && input[i][j + 1] == '*' ? rightStarsCount[i][j + 1] + 1 : 0;
            }
        }

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < m; j++) {
                topStarsCount[i][j] = input[i][j] == '*' && input[i - 1][j] == '*' ? topStarsCount[i - 1][j] + 1 : 0;
            }
        }

        for (int i = n - 2; i >= 0; i--) {
            for (int j = 0; j < m; j++) {
                bottomStarsCount[i][j] = input[i][j] == '*' && input[i + 1][j] == '*' ? bottomStarsCount[i + 1][j] + 1 : 0;
            }
        }

        class Star {
            int x, y, size;

            Star(int x, int y, int size) {
                this.x = x;
                this.y = y;
                this.size = size;
            }

            @Override
            public String toString() {
                return x + " " + y + " " + size;
            }
        }


        ArrayList<String> answer = new ArrayList<>();
        int count = 0;

        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                int left = leftStarsCount[i][j];
                int right = rightStarsCount[i][j];
                int top = topStarsCount[i][j];
                int bottom = bottomStarsCount[i][j];

                if (left == 0 || right == 0 || top == 0 || bottom == 0) continue;

                int size = Math.min(left, right);
                size = Math.min(size, top);
                size = Math.min(size, bottom);


                answer.add((i + 1) + " " + (j +1 ) + " " + size);
                count++;

                for (int k = i - size; k <= i + size; k++) {
