            for (int j = 0; j <m ; j++) {
                mass[i][j] = tmp.charAt(j);
            }
        }
        char[][] newMass = new char[n][m];
        for (int i = 0; i <n ; i++) {
            Arrays.fill(newMass[i],'.');
        }
        for (int i = 1; i <n-1 ; i++) {
            for (int j = 1; j <m-1 ; j++) {
                check(mass,i,j);
            }
        }
        for (int i = 0; i <arrayList.size() ; i++) {
            draw(arrayList.get(i),newMass);
        }
        for (int i = 0; i <n ; i++) {
            for (int j = 0; j <m ; j++) {
                if(mass[i][j]!=newMass[i][j]){
                    System.out.println(-1);
                    return;
                }
            }
        }
