    public static void draw(ourStruct a,char[][] mass){
        mass[a.i][a.j]='*';
        for (int i = 0; i <a.rad ; i++) {
            mass[a.i-i-1][a.j]='*';
            mass[a.i+i+1][a.j]='*';
            mass[a.i][a.j-i-1]='*';
            mass[a.i][a.j+i+1]='*';
        }
    }
    public static void check(char[][] mass, int i,int j){
        if(mass[i][j]=='.') return;
        else{
            int up=i,down=i,left=j,right=j;
            int rad=0;
            while(true){
                up--;
                down++;
                left--;
                right++;
                if(up <0 || down>=mass.length || left <0 || right>=mass[0].length) {
                    if(rad!=0){
                        arrayList.add(new ourStruct(i,j,rad));

                    }
                    return;
                }
                else if(mass[up][j]==mass[down][j] && mass[i][left]==mass[i][right] && mass[i][left]==mass[down][j] &&mass[down][j]=='*' ){
                    rad++;
                }
                else{
                    if(rad!=0){
                        arrayList.add(new ourStruct(i,j,rad));

                    }
                    return;
                }

            }
        }
    }
}


