public class Main {

    class Star {
        int i, j, len;

        Star(int i, int j, int len) {
            this.i = i;
            this.j = j;
            this.len = len;
        }
    }

    public void run() {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt(), m = s.nextInt();

        boolean[][] before = new boolean[n][m];
        boolean[][] after = new boolean[n][m];

        List<Star> result = new LinkedList<>();

        for (int i = 0; i < n; i++) {
            String str = s.next();
            for (int j = 0; j < m; j++) {
                before[i][j] = str.charAt(j) == '*';
                after[i][j] = before[i][j];
            }
        }

        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (!before[i][j])
                    continue;

                int len = 1;
                for (; true; len++) {
                    if (i - len < 0 || i + len >= n || j - len < 0 || j + len >= m)
                        break;
                    if (!before[i - len][j] || !before[i + len][j] || !before[i][j - len] || !before[i][j + len])
                        break;

                    after[i - len][j] = false;
                    after[i + len][j] = false;
                    after[i][j - len] = false;
                    after[i][j + len] = false;
                }

                len--;
                if (len >= 1) {
                    after[i][j] = false;
                    result.add(new Star(i, j, len));
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (after[i][j]) {
                    System.out.println("-1");
                    return;
                }
            }
        }

        System.out.println(result.size());

        result.forEach(r -> System.out.println((r.i + 1) + " " + (r.j + 1) + " " + r.len));
    }

