public class Codeforces {

    static class Triplet{
        int x, y, s;

        public Triplet(int a, int b, int c){
            x = a;
            y = b;
            s = c;
        }

        @Override
        public String toString() {
            return x + " " + y + " " + s;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        char[][] grid = new char[n][m];
        boolean[][] vis = new boolean[n][m];
        for(int i = 0; i < n; i++){
            grid[i] = br.readLine().toCharArray();
        }
        ArrayList<Triplet> stars = new ArrayList<>();
        for(int i = 0; i < n; i++){
            for(int j = 0; j < m; j++){
                if(grid[i][j] == '*'){
                    int c1 = 0, c2 = 0, c3 = 0, c4 = 0;
                    for(int k = j - 1; k >= 0; k--){
                        if(grid[i][k] == '*')c1++;
                        else break;
                    }
                    for(int k = j + 1; k < m; k++){
                        if(grid[i][k] == '*')c2++;
                        else break;
                    }
                    for(int k = i - 1; k >= 0; k--){
                        if(grid[k][j] == '*')c3++;
                        else break;
                    }
                    for(int k = i + 1; k < n; k++){
                        if(grid[k][j] == '*')c4++;
                        else break;
                    }
                    int min = Math.min(c1, Math.min(c2, Math.min(c3, c4)));
                    if(min != 0){
                        stars.add(new Triplet(i + 1, j + 1, min));
                        for(int k = i - min; k <= i + min; k++){
                            vis[k][j] = true;
                        }
                        for(int k = j - min; k <= j + min; k++){
                            vis[i][k] = true;
                        }
                    }
                }
            }
        }
        boolean f = true;
        for(int i = 0; i < n; i++){
            for(int j = 0; j < m; j++){
                if(grid[i][j] == '*' && !vis[i][j])
                    f = false;
            }
        }
        if(!f){
            pw.println(-1);
        }else{
            if(stars.size() > n * m){
                for(int i = 0; i < stars.size(); i++){
                    int x = stars.get(i).x, y = stars.get(i).y;
                    for(int j = i + 1; j < stars.size(); j++){
                        if(x == stars.get(j).x && y == stars.get(j).y){
                            if(stars.get(i).s < stars.get(j).s){
                                stars.remove(i);
                            }else{
                                stars.remove(j);
                            }
                        }
                    }
                }
            }
            pw.println(stars.size());
            for(Triplet t : stars){
                pw.println(t);
            }
        }
        pw.flush();
        pw.close();
    }
}

