			for(int j=1; j<m-1; j++) {
				if(!board[i][j]) continue;
				int size = Math.min(i, n-i-1);
				size = Math.min(size, j);
				size = Math.min(size, m-j-1);
				for(int k=1; k<=size; k++) {
					if(board[i+k][j] && board[i-k][j]
							&& board[i][j+k] && board[i][j-k]) {
						check[i][j] = true;
						check[i+k][j] = true; check[i-k][j] = true;
						check[i][j+k] = true; check[i][j-k] = true;
						triple t = new triple(i+1,j+1,k);
						if(k>1) {
							ans.remove(ans.size()-1);
						}
						ans.add(t);
						continue;
					}
					break;
				}
			}
		}
		for(int i=0; i<n; i++) {
			for(int j=0; j<m; j++) {
				if(board[i][j]) {
					if(!check[i][j]) {
						correct = false;
					}
				}
			}
		}
		total = ans.size();
		if(!correct) System.out.println(-1);
		else  {
			System.out.println(total);
			for(int i=0; i<total; i++) {
				System.out.println(ans.get(i).x + " " + ans.get(i).y + " " + ans.get(i).size);
			}
		}
		sc.close();
	}
}

import java.io.*;
import java.util.*;  

public class Main {
    public static class Task {

        int getPSum(int[] prefix, int from, int to) {
            if (from < 0 || to >= prefix.length) return 0;
            return prefix[to] - prefix[from];
        }

        int bs(int[] rowP, int[] colP, int i, int j) {
            int lo = 0, hi = 1000;
            while (lo <= hi) {
                int mid = (lo + hi) / 2;
                int rs = getPSum(rowP, j - mid, j + mid + 1);
                int cs = getPSum(colP, i - mid, i + mid + 1);
                if (rs != 2 * mid + 1 || cs != 2 * mid + 1) {
                    hi = mid - 1;
                } else {
                    lo = mid + 1;
                }
            }
            return hi;
        }

        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int[][] matrix = new int[n][m];
            for (int i = 0; i < n; i++) {
                String s = sc.next();
                for (int j = 0; j < m; j++) {
                    matrix[i][j] = s.charAt(j) == '.' ? 0 : 1;
                }
            }
            int[][] rowPrefix = new int[n][m + 1];
            int[][] colPrefix = new int[m][n + 1];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    rowPrefix[i][j + 1] = rowPrefix[i][j] + matrix[i][j];
                }
            }
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    colPrefix[i][j + 1] = colPrefix[i][j] + matrix[j][i];
                }
            }
            int[][] rowPS = new int[n][m + 1];
            int[][] colPS = new int[m][n + 1];
            List<int[]> output = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (matrix[i][j] == 1) {
                        int k = bs(rowPrefix[i], colPrefix[j], i, j);
                        if (k > 0) {
                            output.add(new int[]{i, j, k});
                            rowPS[i][j + k + 1]--;
                            rowPS[i][j - k]++;
                            colPS[j][i + k + 1]--;
                            colPS[j][i - k]++;
                        }
                    }
                }
            }
            int[][] otM = new int[n][m];
            for (int i = 0; i < n; i++) {
                int r = 0;
                for (int j = 0; j < m; j++) {
                    r += rowPS[i][j];
                    if (r > 0) otM[i][j] = 1;
                }
            }
            for (int i = 0; i < m; i++) {
                int c = 0;
                for (int j = 0; j < n; j++) {
                    c += colPS[i][j];
                    if (c > 0) otM[j][i] = 1;
                }
            }
            boolean good = true;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (otM[i][j] == 1 && matrix[i][j] == 0) throw new RuntimeException();
                    if (otM[i][j] == 0 && matrix[i][j] == 1) {
                        good = false;
                    }
                }
            }
            if (!good ){
                pw.println(-1);
            } else {
                pw.println(output.size());
                for (int[] x: output) {
                    pw.println((x[0] + 1) + " " + (x[1] + 1) + " " + x[2]);
                }
            }
        }
    }

    static long TIME_START, TIME_END;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);

        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));


        Runtime runtime = Runtime.getRuntime();
        long usedMemoryBefore = runtime.totalMemory() - runtime.freeMemory();
        TIME_START = System.currentTimeMillis();
        Task t = new Task();
        t.solve(sc, pw);
        TIME_END = System.currentTimeMillis();
        long usedMemoryAfter = runtime.totalMemory() - runtime.freeMemory();
        pw.close();
        System.err.println("Memory increased: " + (usedMemoryAfter - usedMemoryBefore) / 1000000);
        System.err.println("Time used: " + (TIME_END - TIME_START) + ".");
    }

