public class stars_drawing_easy {

	public static void main(String[] args) throws Exception {
		new stars_drawing_easy().run();
	}

	public void run() throws Exception {
		FastIO file = new FastIO();
		int n = file.nextInt();
		int m = file.nextInt();
		char[][] c = new char[n][m];
		for (int i = 0; i < n; i++) {
			c[i] = file.next().toCharArray();
		}
		ArrayList<Integer> ans = new ArrayList<>();
		boolean works = true;
		boolean[][] used = new boolean[n][m];
		boolean[][] usedMid = new boolean[n][m];
		for (int i = 1; i < n - 1; i++) {
			for (int j = 1; j < m - 1; j++) {
				if (c[i][j] == '*' && c[i][j+1] == '*' && c[i][j-1] == '*' && c[i+1][j] == '*' && c[i-1][j] == '*' && !usedMid[i][j]) {
					int aa = 0;
					int bb = 0;
					int cc = 0;
					int dd = 0;
					for (int k = i - 1; k >= 0 && c[k][j] == '*'; aa++, k--);
					for (int k = j - 1; k >= 0 && c[i][k] == '*'; bb++, k--);
					for (int k = i + 1; k < n && c[k][j] == '*'; cc++, k++);
					for (int k = j + 1; k < m && c[i][k] == '*'; dd++, k++);
					aa = bb = cc = dd = Math.min(Math.min(Math.min(aa, bb), cc), dd);
					if (aa > 0) {
						ans.add(i + 1);
						ans.add(j + 1);
						ans.add(aa);
						usedMid[i][j] = true;
						for (int k = i; aa >= 0; aa--, k--) used[k][j] = true;
						for (int k = j; bb >= 0; bb--, k++) used[i][k] = true;
						for (int k = i; cc >= 0; cc--, k++) used[k][j] = true;
						for (int k = j; dd >= 0; dd--, k--) used[i][k] = true;
						i = 1; j = 1;
					}
				}
			}
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (c[i][j] == '*' && !used[i][j]) {
					works = false;
				}
			}
		}

		if (works) {
			System.out.println(ans.size() / 3);
			for (int i = 0; i < ans.size(); i+=3) {
				System.out.println(ans.get(i) + " " + ans.get(i + 1) + " " + ans.get(i + 2));
			}
		}
		else {
			System.out.println(-1);
		}
	}

	public static class FastIO {
		BufferedReader br;
		StringTokenizer st;

		public FastIO() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		long nextLong() {
			return Long.parseLong(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}
			return str;
		}
	}

	public static long pow(long n, long p, long mod) {
		if (p == 0)
			return 1;
		if (p == 1)
			return n % mod;
		if (p % 2 == 0) {
			long temp = pow(n, p / 2, mod);
			return (temp * temp) % mod;
		} else {
			long temp = pow(n, (p - 1) / 2, mod);
			temp = (temp * temp) % mod;
			return (temp * n) % mod;

		}
	}

	public static long pow(long n, long p) {
		if (p == 0)
			return 1;
		if (p == 1)
			return n;
		if (p % 2 == 0) {
			long temp = pow(n, p / 2);
			return (temp * temp);
		} else {
			long temp = pow(n, (p - 1) / 2);
			temp = (temp * temp);
			return (temp * n);

		}
	}

	public static long gcd(long x, long y) {
		if (x == 0)
			return y;
		else
			return gcd(y % x, x);
	}

	public static boolean isPrime(int n) {
		if (n <= 1)
			return false;
		if (n <= 3)
			return true;

		if (n % 2 == 0 || n % 3 == 0)
			return false;

		for (int i = 5; i * i <= n; i = i + 6)
			if (n % i == 0 || n % (i + 2) == 0)
				return false;

		return true;
	}
}

