	static class Solver {
		static long mod = (long) (1e9);

		public void solve(FastScanner br, PrintWriter pw) throws IOException {
			int n = br.ni();
			int m = br.ni();
			boolean[][] s = new boolean[n][m];
			for (int i = 0; i < n; i++) {
				String in = br.nt();
				for (int j = 0; j < m; j++) {
					s[i][j] = in.charAt(j) == '*';
				}
			}
			ArrayList<Point> out = new ArrayList<Point>();
			boolean[][] hit = new boolean[n][m];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					if (s[i][j]) {
						int a = 0;
						int b = Math.min(Math.min(n - i-1, m - j-1), Math.min(i, j));
						for (int k = 1; k <= b; k++) {
							if (!s[i][j + k] || !s[i][j - k] || !s[i + k][j] || !s[i - k][j])
								break;
							hit[i][j + k] = true;
							hit[i][j - k] = true;
							hit[i + k][j] = true;
							hit[i - k][j] = true;
							a++;
						}
						if (a != 0) {
							hit[i][j] = true;
							out.add(new Point(i, j, a));
						}
					}
				}
			}
			boolean good = true;
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					if (s[i][j] && !hit[i][j]) {
						good = false;
					}
				}
			}
			if (good) {
				pw.println(out.size());
				for (Point p : out) {
					pw.println((p.a + 1) + " " + (p.b + 1) + " " + p.c);
				}
			} else {
				pw.println(-1);
			}

		}

		static long gcd(long a, long b) {
			if (a > b)
				return gcd(b, a);
			if (a == 0)
				return b;
			return gcd(b % a, a);
		}

		static long lcm(long a, long b) {
			return a * (b / gcd(a, b));
		}

		static long pow(long a, long b) {
			if (b == 0)
				return 1L;
			long val = pow(a, b / 2);
			if (b % 2 == 0)
				return val * val % mod;
			else
				return val * val % mod * a % mod;
		}

	}

	static class Point implements Comparable<Point> {
		int a;
		int b;
		int c;

