import java.util.*;
import java.lang.*;
import java.io.*;


public class Ideone
{
    public static int[][] done;

    public static class Node{
        int x=0;
        int y=0;
        int s=0;
        Node(int xi,int yi,int si){
            x=xi;
            y=yi;
            s=si;
        }
    }
    public static int dfs(int i,int j,String[] a,int x,int size){
        if(a[i].charAt(j)!='*'){
            return size;
        }

        size++;
        int n=a.length;
        int m=a[0].length();
        int count=0;
        if(x==0 && i!=n-1){
            return dfs(i+1,j,a,x,size);
        }
        else if(x==1 && j!=0){
            return dfs(i,j-1,a,x,size);
        }
        else if(x==2 && i!=0){
            return dfs(i-1,j,a,x,size);
        }
        else if(x==3 && j!=m-1){
            return dfs(i,j+1,a,x,size);
        }
        return size;
    }
    public static void main (String[] args) throws java.lang.Exception
    {

        Scanner scan=new Scanner(System.in);
        int n=scan.nextInt();
        int m=scan.nextInt();
        String[] a=new String[n];
        for(int i=0;i<n;i++){
            a[i]=scan.next();
        }
        done=new int[n][m];

        ArrayList<Node> ans=new ArrayList<Node>();
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(i==0 || i==n-1 || j==0 || j==m-1){
                    continue;
                }
                int count=0;
                if(a[i].charAt(j)=='*'){

                    int min=Integer.MAX_VALUE;
                    min=Math.min(min,dfs(i+1,j,a,0,0));
                    min=Math.min(dfs(i,j-1,a,1,0),min);
                    min=Math.min(min,dfs(i-1,j,a,2,0));
                    min=Math.min(min,dfs(i,j+1,a,3,0));



                    if(min!=0){
                        done[i][j]=1;
                        for(int k=1;k<=min;k++){
                            done[i+k][j]=1;
                            done[i][j+k]=1;
                            done[i-k][j]=1;
                            done[i][j-k]=1;
                        }
                        Node node=new Node(i+1,j+1,min);
                        ans.add(node);
                    }
                }
            }
        }
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(a[i].charAt(j)=='*' && done[i][j]!=1){
                    System.out.println(-1);
                    return;
                }
            }
        }
        System.out.println(ans.size());
        for(int i=0;i<ans.size();i++){
            System.out.println(ans.get(i).x + " " + ans.get(i).y + " " + ans.get(i).s);
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.util.LinkedList;
import java.util.Queue;

public class P1015E2
{
	public static int n;
	public static int m;
	public static char[][] grid;
	public static boolean[][] star;
	public static int[] di = {-1, 0, 1, 0};
	public static int[] dj = {0, 1, 0, -1};
	public static int[][] up;
	public static int[][] down;
	public static int[][] left;
	public static int[][] right;

	public static void main(String[] args)
	{
		FastScanner in = new FastScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		n = in.nextInt();
		m = in.nextInt();
		grid = new char[n][m];
		for (int i = 0; i < n; i++)
			grid[i] = in.nextLine().toCharArray();
		star = new boolean[n][m];
		up = new int[n][m];
		down = new int[n][m];
		left = new int[n][m];
		right = new int[n][m];
		for (int i = 0; i < n; i++) {
			if (grid[i][0] == '*')
				left[i][0] = 1;
			for (int j = 1; j < m; j++)
				if (grid[i][j] == '*')
					left[i][j] = left[i][j - 1] + 1;
			if (grid[i][m - 1] == '*')
				right[i][m - 1] = 1;
			for (int j = m - 2; j >= 0; j--)
				if (grid[i][j] == '*')
					right[i][j] = right[i][j + 1] + 1;
		}
		for (int j = 0; j < m; j++) {
			if (grid[0][j] == '*')
				up[0][j] = 1;
			for (int i = 1; i < n; i++)
				if (grid[i][j] == '*')
					up[i][j] = up[i - 1][j] + 1;
			if (grid[n - 1][j] == '*')
				down[n - 1][j] = 1;
			for (int i = n - 2; i >= 0; i--)
				if (grid[i][j] == '*')
					down[i][j] = down[i + 1][j] + 1;
		}
		Queue<Star> stars = new LinkedList<>();
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (grid[i][j] == '.')
					continue;
				int ray = rayLength(i, j);
				if (ray < 1)
					continue;
				fillStar(i, j, ray);
				stars.add(new Star(i, j, ray));
			}
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (grid[i][j] == '*' && !star[i][j]) {
					out.println(-1);
					out.close();
					return;
				}
			}
		}
		out.println(stars.size());
		for (Star s : stars)
			out.println(s);
		out.close();
	}

	public static void fillStar(int i, int j, int ray)
	{
		star[i][j] = true;
		for (int k = 0; k < 4; k++) {
			int ii = i;
			int jj = j;
			for (int l = 0; l < ray; l++) {
				ii += di[k];
				jj += dj[k];
				star[ii][jj] = true;
			}
		}
	}

	public static int rayLength(int i, int j)
	{
		return Math.min(up[i][j], Math.min(down[i][j], Math.min(left[i][j], right[i][j]))) - 1;
	}

	public static class Star
	{
		int i;
		int j;
		int s;

		public Star(int a, int b, int c)
		{
			i = a;
			j = b;
			s = c;
		}

		@Override
		public String toString()
		{
			return (i + 1) + " " + (j + 1) + " " + s;
		}
	}


	public static class FastScanner
	{
		private InputStream stream;
		private byte[] buf = new byte[1024];
		private int curChar;
		private int numChars;

		public FastScanner(InputStream stream)
		{
			this.stream = stream;
		}

		int read()
		{
			if (numChars == -1)
				throw new InputMismatchException();
			if (curChar >= numChars)
			{
				curChar = 0;
				try
				{
					numChars = stream.read(buf);
				} catch (IOException e)
				{
					throw new InputMismatchException();
				}
				if (numChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		boolean isSpaceChar(int c)
		{
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		boolean isEndline(int c)
		{
			return c == '\n' || c == '\r' || c == -1;
		}

		public int nextInt()
		{
			return Integer.parseInt(next());
		}

		public long nextLong()
		{
			return Long.parseLong(next());
		}

		public double nextDouble()
		{
			return Double.parseDouble(next());
		}

		public String next()
		{
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do
			{
				res.appendCodePoint(c);
				c = read();
			} while (!isSpaceChar(c));
			return res.toString();
		}

		public String nextLine()
		{
			int c = read();
			while (isEndline(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do
			{
				res.appendCodePoint(c);
				c = read();
			} while (!isEndline(c));
			return res.toString();
		}
	}
}

import java.io.*;
import java.util.*;

public class Main {

    static int H, W;
    static char[][] C;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        C = new char[H][];
        for (int i = 0; i < H; i++) {
            C[i] = sc.next().toCharArray();
        }

        List<Cord> cords = solve();
        if( cords == null ) {
            System.out.println(-1);
        } else {
            PrintWriter pw = new PrintWriter(System.out);
            pw.println(cords.size());
            for (Cord c : cords) {
                pw.println((c.h+1) + " " + (c.w+1) + " " + c.size);
            }
            pw.flush();
        }
    }

    static List<Cord> solve() {
        int[][] u = new int[H][W];
        for (int w = 0; w < W; w++) {
            int cnt = 0;
            for (int h = 0; h < H; h++) {
                u[h][w] = cnt;
                if( C[h][w] == '*' ) cnt++;
                else cnt = 0;
            }
        }
        int[][] d = new int[H][W];
        for (int w = 0; w < W; w++) {
            int cnt = 0;
            for (int h = H-1; h >= 0; h--) {
                d[h][w] = cnt;
                if( C[h][w] == '*' ) cnt++;
                else cnt = 0;
            }
        }
        int[][] l = new int[H][W];
        for (int h = 0; h < H; h++) {
            int cnt = 0;
            for (int w = 0; w < W; w++) {
                l[h][w] = cnt;
                if( C[h][w] == '*' ) cnt++;
                else cnt = 0;
            }
        }
        int[][] r = new int[H][W];
        for (int h = 0; h < H; h++) {
            int cnt = 0;
            for (int w = W-1; w >= 0; w--) {
                r[h][w] = cnt;
                if( C[h][w] == '*' ) cnt++;
                else cnt = 0;
            }
        }

        int[][] rowmask = new int[H][W+1];
        int[][] colmask = new int[H+1][W];
        List<Cord> cords = new ArrayList<>();
        for (int h = 0; h < H; h++) {
            for (int w = 0; w < W; w++) {
                if( C[h][w] != '*' ) continue;

                int size = min(l[h][w], r[h][w], u[h][w], d[h][w]);
                if( size >= 1 ) {
                    cords.add( new Cord(h, w, size) );
                    rowmask[h][w-size]++;
                    rowmask[h][w+size+1]--;
                    colmask[h-size][w]++;
                    colmask[h+size+1][w]--;
                }
            }
        }

        for (int h = 0; h < H; h++) {
            for (int wi = 1; wi < W; wi++) {
                rowmask[h][wi] += rowmask[h][wi-1];
            }
        }

        for (int w = 0; w < W; w++) {
            for (int hi = 1; hi < H; hi++) {
                colmask[hi][w] += colmask[hi-1][w];
            }
        }

        for (int h = 0; h < H; h++) {
            for (int w = 0; w < W; w++) {
                if( C[h][w] == '*' && (rowmask[h][w] == 0 && colmask[h][w] == 0)) return null;
            }
        }

        return cords;
    }

    static class Cord {
        int h, w, size;

        public Cord(int h, int w, int size) {
            this.h = h;
            this.w = w;
            this.size = size;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
