            int need = 7 - mask;
            tmp[0] = arr[need & (need - 1)];
            need -= need & (need - 1);
            tmp[1] = arr[need];

            outln(new String(tmp));
            return;
        }

        List<Integer> l1 = new ArrayList<>();
        List<Integer> l2 = new ArrayList<>();
        List<Integer> l3 = new ArrayList<>();
        for (int i = 0; i < tmp.length; i++) {
            char c = tmp[i];
            if (c >= 'A' && c <= 'Z') {
                l1.add(i);
            }
            else if (c >= 'a' && c <= 'z') {
                l2.add(i);
            }
            else {
                l3.add(i);
            }
        }

        int nxt = 7 - mask;
        if (l1.size() >= 2) {
            tmp[l1.get(0)] = arr[nxt];
        }
        else if (l2.size() >= 2) {
            tmp[l2.get(0)] = arr[nxt];
        }
        else {
            tmp[l3.get(0)] = arr[nxt];
        }

        outln(new String(tmp));
    }

    void shuffle(int[] a) {
        int n = a.length;
        for(int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }

    long gcd(long a, long b) {
        while(a != 0 && b != 0) {
            long c = b;
            b = a % b;
            a = c;
        }
        return a + b;
    }

