    static class TaskA {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int t = in.nextInt();
            while (t-- > 0) {
                String str = in.next();
                int countU = 0;
                int countL = 0;
                int countN = 0;
                for (int i = 0; i < str.length(); i++) {
                    if (str.charAt(i) >= 'A' && str.charAt(i) <= 'Z') {
                        countU++;
                    } else if (str.charAt(i) >= 'a' && str.charAt(i) <= 'z') {
                        countL++;
                    } else
                        countN++;
                }
                StringBuilder strb = new StringBuilder();
                strb.append(str);
                if (countN > 0 && countL > 0 && countU > 0) {
                    out.println(str);
                    continue;
                } else if (countN == 0 && countL == 0 && countU > 0) {
                    strb.replace(0, 2, "a3");
                } else if (countN == 0 && countL > 0 && countU == 0) {
                    strb.replace(0, 2, "A3");
                } else if (countN > 0 && countL == 0 && countU == 0) {
                    strb.replace(0, 2, "aA");
                } else if (countN == 0 && countU > 0 && countL > 0) {
                    if (countL < countU) {
                        for (int i = 0; i < str.length(); i++)
                            if (str.charAt(i) <= 'Z' && str.charAt(i) >= 'A') {
                                strb.replace(i, i + 1, "1");
                                break;
                            }
                    } else {
                        for (int i = 0; i < str.length(); i++)
                            if (str.charAt(i) <= 'z' && str.charAt(i) >= 'a') {
                                strb.replace(i, i + 1, "1");
                                break;
                            }
                    }
                } else if (countN > 0 && countU == 0 && countL > 0) {
                    if (countL > countN) {
                        for (int i = 0; i < str.length(); i++)
                            if (str.charAt(i) <= 'z' && str.charAt(i) >= 'a') {
                                strb.replace(i, i + 1, "A");
                                break;
                            }
                    } else {
                        for (int i = 0; i < str.length(); i++)
                            if (str.charAt(i) >= '0' && str.charAt(i) <= '9') {
                                strb.replace(i, i + 1, "A");
                                break;
                            }
                    }
                } else if (countN > 0 && countU > 0 && countL == 0) {
                    if (countU > countN) {
                        for (int i = 0; i < str.length(); i++)
                            if (str.charAt(i) <= 'Z' && str.charAt(i) >= 'A') {
                                strb.replace(i, i + 1, "a");
                                break;
                            }
                    } else {
                        for (int i = 0; i < str.length(); i++)
                            if (str.charAt(i) >= '0' && str.charAt(i) <= '9') {
                                strb.replace(i, i + 1, "a");
                                break;
                            }
                    }
                }

                out.println(strb);

            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }


            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;

            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();

                res *= 10;
                res += c & 15;

                c = read();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        public String next() {
            int c = read();

            while (isSpaceChar(c))
                c = read();

            StringBuilder res = new StringBuilder();

            do {
                res.appendCodePoint(c);

                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

