    boolean isSecure(String s) {
        boolean u = false, l = false, n = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if ('A' <= c && c <= 'Z') u = true;
            if ('a' <= c && c <= 'z') l = true;
            if ('0' <= c && c <= '9') n = true;
        }
        return u && l && n;
    }

    void test(String s) {
        if (isSecure(s)) {
            System.out.println(s);
            return;
        }
        for (int i = 0; i < s.length(); i++) {
            if (isSecure(s.substring(0, i) + "A" + s.substring(i + 1))) {
                System.out.println(s.substring(0, i) + "A" + s.substring(i + 1));
                return;
            } else if (isSecure(s.substring(0, i) + "a" + s.substring(i + 1))) {
