public class Main {


    public static void go(StringBuilder s) {
        System.out.println(s);
    }

    public static boolean good(StringBuilder s) {

        boolean ok1 = false;
        boolean ok2 = false;
        boolean ok3 = false;

        for (int i = 0; i < s.length(); i++) {
            if(s.charAt(i) >= 'a' && s.charAt(i) <= 'z') ok1 = true;
            if(s.charAt(i) >= 'A' && s.charAt(i) <= 'Z') ok2 = true;
            if(s.charAt(i) >= '0' && s.charAt(i) <= '9') ok3 = true;
        }
        return (ok1 && ok2 && ok3);
    }

    public static void solve(StringBuilder s) {
        if(good(s)) {
            go(s);
            return;
        }

        for (int i = 0; i < s.length(); i++) {
            char t = s.charAt(i);
            s.setCharAt(i, 'a');
            if(good(s)) {
                go(s);
                return;
            }

            s.setCharAt(i, 'A');
            if(good(s)) {
                go(s);
                return;
            }

            s.setCharAt(i, '9');
            if(good(s)) {
                go(s);
                return;
            }
            s.setCharAt(i, t);
        }

        for (int i = 0; i + 1 < s.length(); i++) {
            String t = s.substring(i, i + 2);

            s.replace(i, i + 2, "aA");
            if(good(s)) {
                go(s);
                return;
            }

            s.replace(i, i + 2, "a9");
            if(good(s)) {
                go(s);
                return;
            }
            s.replace(i, i + 2, "A9");
            if(good(s)) {
                go(s);
                return;
            }

            s.replace(i, i + 2, t);
        }
    }

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        int test = sc.nextInt();

        while(test-- > 0) {
            String tmp = sc.next();

            StringBuilder s = new StringBuilder(tmp);

            solve(s);

        }

    }
}

