public class Main {

    static class Task {
        PrintWriter out;
        MyScanner in;

        int best = 0;
        String bestString = null;

        public void solve(MyScanner in, PrintWriter out) {
            this.out = out;
            this.in = in;


            int t = in.nextInt();

            for (int tt = 0; tt < t; tt++) {
                best = Integer.MAX_VALUE;

                String s = in.next();

                for (int start = 0; start < s.length(); start++) {
                    for (int end = start; end <= s.length(); end++) {
                        doTry(s, start, end);
                    }
                }

                System.out.println(bestString);
            }

        }




        void doTry(String s, int start, int end) { 
            boolean isNumber = false;
            boolean isLower = false;
            boolean isUpper = false;

            int dist = end - start;

            for (int i = 0; i < start; i++) {
                if (Character.isDigit(s.charAt(i))) {
                    isNumber = true;
                }
                if (Character.isLowerCase(s.charAt(i))) {
                    isLower = true;
                }
                if (Character.isUpperCase(s.charAt(i))) {
                    isUpper = true;
                }
            }

            for (int i = end; i < s.length(); i++) {
                if (Character.isDigit(s.charAt(i))) {
                    isNumber = true;
                }
                if (Character.isLowerCase(s.charAt(i))) {
                    isLower = true;
                }
                if (Character.isUpperCase(s.charAt(i))) {
                    isUpper = true;
                }
            }

            String toAdd = "";
            if (!isNumber) {
                toAdd = toAdd + "1";
            }
            if (!isUpper) {
                toAdd = toAdd + "A";
            }
            if (!isLower) {
                toAdd = toAdd + "a";
            }

            if (toAdd.length() > dist) {
                return;
            }
            while (toAdd.length() != dist) {
                toAdd = toAdd + "0";
            }

            String copy = s.substring(0, start) + toAdd + s.substring(end, s.length());

            if (dist < best) {
                best = dist;
                bestString = copy;

            }
        }





























    }

    public static void main(String[] args) {
        MyScanner in = new MyScanner();
        PrintWriter out = new PrintWriter(System.out);
        Task solver = new Task();
        solver.solve(in, out);
        out.close();
    }

    public static class MyScanner {
        BufferedReader br;
        StringTokenizer st;

        public MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
