    boolean isSecure(String s) {
        boolean u = false, l = false, n = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if ('A' <= c && c <= 'Z') u = true;
            if ('a' <= c && c <= 'z') l = true;
            if ('0' <= c && c <= '9') n = true;
        }
        return u && l && n;
    }

    String[] sub = {"A", "a", "1", "Aa", "A1", "a1"};

    String test(String s) {
        if (isSecure(s)) return s;
        for (int i = 0; i < s.length(); i++) {
            for (int j = 0; j < 3; j++) {
                String t = s.substring(0, i) + sub[j] + s.substring(i + 1);
                if (isSecure(t)) return t;
            }
        }
        for (int i = 0; i < s.length(); i++) {
            for (int j = 3; j < 6; j++) {
                String t = s.substring(0, i) + sub[j] + s.substring(i + 2);
                if (isSecure(t)) return t;
            }
        }
        return "";
    }

