	private static String convert(String str) {
		int a = 0;
		int b = 0; 
		int c = 0;
		StringBuilder sb = new StringBuilder(str);
		for(int i = 0; i < str.length(); i++) {
			char ch = str.charAt(i); 
			if(ch >= 'a' && ch <= 'z') a++;
			else if(ch >= 'A' && ch <= 'Z') b++;
			else if(ch >= '0' && ch <= '9' ) c++;
			if(a > 0 && b > 0 && c > 0) return sb.toString();
		}
		int idx = 0;
		if(a > 0 && b > 0 && c == 0) {
			if(a > b) {
				for(; idx < str.length(); idx++) {
					if(sb.charAt(idx) >= 'a' && sb.charAt(idx) <= 'z') break;
				}

			}
			else {
				for(; idx < str.length(); idx++) {
					if(sb.charAt(idx) >= 'A' && sb.charAt(idx) <= 'Z') break;
				}
			}
			sb.replace(idx, idx+1, "1");
			return sb.toString();
		}
		else if(a > 0 && b == 0 && c > 0) {
			if(a > c) {
				for(; idx < str.length(); idx++) {
					if(sb.charAt(idx) >= 'a' && sb.charAt(idx) <= 'z') break;
				}

			}
			else {
				for(; idx < str.length(); idx++) {
					if(sb.charAt(idx) >= '0' && sb.charAt(idx) <= '9') break;
				}
			}
			sb.replace(idx, idx+1, "A");
			return sb.toString();
		}
		else if(a == 0 && b > 0 && c > 0) {
			if(b > c) {
				for(; idx < str.length(); idx++) {
					if(sb.charAt(idx) >= 'A' && sb.charAt(idx) <= 'Z') break;
				}
			}
			else {
				for(; idx < str.length(); idx++) {
					if(sb.charAt(idx) >= '0' && sb.charAt(idx) <= '9') break;
				}
			}
			sb.replace(idx, idx+1, "a");
			return sb.toString();
		}
		else if(a == 0 && b == 0 && c > 0) {
			sb.replace(idx, idx+2, "aA");
			return sb.toString();
		}
		else if(a == 0 && b > 0 && c == 0) {
			sb.replace(idx, idx+2, "a0");
			return sb.toString();
		}
		else if(a > 0 && b == 0 && c == 0) {
			sb.replace(idx, idx+2, "A0");
			return sb.toString();
		}
		return sb.toString();
	}
}

