                            if (check(tmp, len).size() == 3) {
                                System.out.println(tmp);
                                break;
                            }
                        }
                    }
                } else if (map.size() == 2) {
                    if (!map.containsKey("num")) {
                        for (int j = 0; j < len; j++) {
                            String replace = "1";
                            String tmp = "";
