                            String replace = "A";
                            String tmp = "";
                            tmp = s.substring(0, j).concat(replace).concat(s.substring(j + 1));
                            if (check(tmp, len).size() == 3) {
                                System.out.println(tmp);
                                break;
                            }
                        }

                    } else {
                        for (int j = 0; j < len; j++) {
                            String replace = "a";
