                boolean lower = false, upper = false, digit = false;
                for (int i = 0; i < s.length; i++) {
                    digit |= Character.isDigit(s[i]);
                    upper |= Character.isUpperCase(s[i]);
                    lower |= Character.isLowerCase(s[i]);
                }
                if (lower && upper && digit)
                    out.println(s);
                else if (lower && upper) {
                    for (int i = 0; i < s.length; i++) {
                        char temp = s[i];
                        s[i] = '1';
                        if (valid(s)) {
                            out.println(s);
                            break;
                        }
                        s[i] = temp;
                    }
                } else if (lower && digit) {
                    for (int i = 0; i < s.length; i++) {
                        char temp = s[i];
                        s[i] = 'A';
                        if (valid(s)) {
                            out.println(s);
                            break;
                        }
                        s[i] = temp;
                    }
                } else if (upper && digit) {
                    for (int i = 0; i < s.length; i++) {
                        char temp = s[i];
                        s[i] = 'a';
                        if (valid(s)) {
                            out.println(s);
                            break;
                        }
                        s[i] = temp;
                    }
                } else {
                    if(digit) {
                        s[0] = 'a'; s[1] = 'A';
                    }
                    else if(upper) {
                        s[0] = '1'; s[1] = 'a';
                    }
                    else if(lower) {
                        s[0] = '1'; s[1] = 'A';
                    }
                    else {
                        s[0] = '1'; s[1] = 'a'; s[2] = 'A';
                    }
                    out.println(s);
                }
            }
        }

        private boolean valid(char[] s) {
            boolean lower = false, upper = false, digit = false;
            for (int i = 0; i < s.length; i++) {
                digit |= Character.isDigit(s[i]);
                upper |= Character.isUpperCase(s[i]);
                lower |= Character.isLowerCase(s[i]);
            }
            return lower && upper && digit;
        }

    }
}

