public class A {

	public Object solve() {
		char [] C = sc.nextChars();
		int N = C.length;

		int [] K = count(C);

		if (K[0] == 0) {
			if (K[1] == 0) {
				C[0] = '1'; C[1] = 'a';
				return print(new String(C));
			}
			else if (K[2] == 0) {
