public class A {

	public static int getCharDetail(char c) {
		if(c-'a'>=0 && c-'a'<26)
			return 0;
		else if(c-'A'>=0 && c-'Z'<26)
			return 1;
		else
			return 2;
	}

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		int t = sc.nextInt();
		sc.nextLine();
		while(t--!=0)
		{
			StringBuffer sb = new StringBuffer(sc.nextLine());
			int isNumber = 0, isCapital = 0, isSmall = 0;
			for(int i=0;i<sb.length();i++)
			{
				int k = getCharDetail(sb.charAt(i));
				if(k==0)
					isSmall++;
				else if(k==1)
					isCapital++;
				else
					isNumber++;
			}
			if(isSmall>0 && isCapital>0 && isNumber>0)
				out.println(sb.toString());
			else
			{

				int need = 0;
				if(isSmall==0)
					need++;
				if(isCapital==0)
					need++;
				if(isNumber==0)
					need++;
				for(int i=0;i<sb.length()-need+1;i++)
				{
					boolean flag = true;
					int tmpSmall = isSmall;
					int tmpCapital = isCapital;
					int tmpNumber = isNumber;
					for(int j=i;j<i+need;j++)
					{
						int k = getCharDetail(sb.charAt(i));
						if(k==0 && tmpSmall>1)
							tmpSmall--;
						else if(k==1 && tmpCapital>1)
							tmpCapital--;
						else if(k==2 && tmpNumber>1)
							tmpNumber--;
						else
						{
							flag = false;
							break;
						}
					}
					if(flag)
					{
						for(int j=i;j<i+need;j++)
						{
							if(isSmall==0)
							{
								sb.insert(j, 'a');
								isSmall++;
								sb.deleteCharAt(j+1);
							}
							else if(isCapital==0)
							{
								sb.insert(j, 'A');
								isCapital++;
								sb.deleteCharAt(j+1);
							}
							else if(isNumber==0)
							{
								sb.insert(j, '1');
								isNumber++;
								sb.deleteCharAt(j+1);
							}
						}
						break;
					}
				}
				out.println(sb.toString());
			}
		}
