        for (int i = 0; i < s.length; i++) {
            char c = s[i];
            if (c >= 'a' && c <= 'z') {
                count[0]++;
            } else if (c >= 'A' && c <= 'Z') {
                count[1]++;
            } else {
                count[2]++;
            }
        }
        if (count[0] > 0 && count[1] > 0 && count[2] > 0) {
            return true;
        }
        return false;
    }

    static String getString(char[] c) {
        String ret = "";
        for (char i : c) {
            ret += "" + i;
        }
        return ret;
    }

    static int getLen(char[] a, char[] b) {
        int[] pos = new int[2];
        int counter = 0;
        for (int i = 0; i < a.length; i++) {
            if (a[i] != b[i]) {
                pos[counter++] = i;
            }
        }
        return pos[1] - pos[0];
    }

