public class A {
	static int firstCapital = -1;
	static int firstLowerCase = -1;
	static int firstNumber = -1;

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int t = scan.nextInt();
		scan.nextLine();
		for (int i = 0; i < t; i++) {
			firstCapital = -1;
			firstLowerCase = -1;
			firstNumber = -1;
			System.out.println(checkString(scan.nextLine()));
		}

	}

	private static String checkString(String str) {
		StringBuilder strNew = new StringBuilder(str);
		char ch;
		boolean capitalFlag = false;
		boolean lowerCaseFlag = false;
		boolean numberFlag = false;
		for (int i = 0; i < str.length(); i++) {
			ch = str.charAt(i);
			if (Character.isDigit(ch)) {
				firstNumber = i;
				numberFlag = true;
			} else if (Character.isUpperCase(ch)) {
				firstCapital = i;
				capitalFlag = true;
			} else if (Character.isLowerCase(ch)) {
				firstLowerCase = i;
				lowerCaseFlag = true;
			}
		}
		if (!capitalFlag) {
			for (int j = 0; j < str.length(); j++) {
				if (j != firstCapital && j != firstLowerCase && j != firstNumber) {
					strNew.setCharAt(j, 'A');
					firstCapital = j;
					break;
				}
			}
		}
		if (!lowerCaseFlag) {
			for (int j = 0; j < str.length(); j++) {
				if (j != firstCapital && j != firstLowerCase && j != firstNumber) {
					strNew.setCharAt(j, 'a');
					firstLowerCase = j;
					break;
				}
			}
		}
		if (!numberFlag) {
			for (int j = 0; j < str.length(); j++) {
				if (j != firstCapital && j != firstLowerCase && j != firstNumber) {
					strNew.setCharAt(j, '1');
					firstNumber = j;
					j = 100000;
					break;
				}
			}

		}
		return strNew.toString();

	}
}

