		Scanner scanner = new Scanner(System.in);
		int n = scanner.nextInt();
		int m = scanner.nextInt();
		char[][] a = new char[n][m];
		for(int i = 0; i < n; i++) {
			String line = scanner.next();
			for(int j = 0; j < m; j++) {
				a[i][j] = line.charAt(j);
			}
		}
		char[][] b = new char[n][m];
		for(int i = 0; i < n; i++) {
			Arrays.fill(b[i], '.');
		}
		for(int i = 1; i < n - 1; i++) {
			for(int j = 1; j < m - 1; j++) {
				if(canSign(a, i, j)) {
					sign(b, i, j);
				}
			}
		}
		if(isEqual(a, b)) {
			System.out.println("YES");
		}
		else {
			System.out.println("NO");
		}
	}

	private static boolean canSign(char[][] a, int x, int y) {
		for(int i = -1; i < 2; i++) {
			for(int j = -1; j < 2; j++) {
				if(i != 0 || j != 0) {
					if(a[x + i][y + j] == '.') {
						return false;
					}
				}
			}
		}
		return true;
	}

	private static void sign(char[][] a, int x, int y) {
		for(int i = -1; i < 2; i++) {
			for(int j = -1; j < 2; j++) {
				if(i != 0 || j != 0) {
					a[x + i][y + j] = '#';
				}
			}
		}
	}

	private static boolean isEqual(char[][] a, char[][] b) {
		for(int i = 0; i < a.length; i++) {
			for(int j = 0; j < a[i].length; j++) {
				if(a[i][j] != b[i][j]) {
					return false;
				}
			}
		}
		return true;
	}
}

