        boolean[][] covered;

        private void read(InputReader in) {
            n = in.nextInt();
            m = in.nextInt();
            s = new char[n][m];
            covered = new boolean[n][m];
            for (int i = 0; i < n; ++i) {
                s[i] = in.next().toCharArray();
            }
        }

        boolean cover(int x, int y) {
            for (int i = 0; i < 3; ++i) {
                for (int j = 0; j < 3; ++j) {
                    if (i == 1 && j == 1) {
                        continue;
                    }
                    if (s[x + i][y + j] != '#') {
                        return false;
                    }
                }
            }
            return true;
        }

        private void solve(PrintWriter out) {
            for (int i = 0; i + 2 < n; ++i) {
                for (int j = 0; j + 2 < m; ++j) {
                    if (cover(i, j)) {
                        for (int dx = 0; dx < 3; ++dx) {
                            for (int dy = 0; dy < 3; ++dy) {
                                if (dx == 1 && dy == 1) {
                                    continue;
                                }
                                covered[i + dx][j + dy] = true;
                            }
                        }
                    }
                }
            }
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (s[i][j] == '#' && !covered[i][j]) {
                        out.print("NO");
                        return;
                    }
                }
            }
            out.print("YES");
        }

        void run(InputReader in, PrintWriter out) {
            read(in);
            solve(out);
        }
    }


    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 1 << 15);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

