    static boolean atleastOneCenter(char[][] arr, int i, int j, int n, int m) {
        boolean canBeFormed = false;
        if(isCenter(arr,i-1,j-1, n,m)) canBeFormed = true;
        if(isCenter(arr,i-1,j,n,m)) canBeFormed = true;
        if(isCenter(arr,i-1,j+1,n,m)) canBeFormed = true;
        if(isCenter(arr,i,j-1,n,m)) canBeFormed = true;
        if(isCenter(arr,i,j+1,n,m)) canBeFormed = true;
        if(isCenter(arr,i+1,j-1,n,m)) canBeFormed = true;
        if(isCenter(arr,i+1,j,n,m)) canBeFormed = true;
        if(isCenter(arr,i+1,j+1,n,m)) canBeFormed = true;
        return canBeFormed;
    }



    static boolean checkIfCenter(char[][] arr, int i, int j, int n, int m) {
        if(i==0 || i==n-1 || j==0 || j==m-1)
            return false;
        boolean isCenter = true;
        if(!isHash(arr,i-1,j-1)) isCenter = false;
        if(!isHash(arr,i-1,j)) isCenter = false;
        if(!isHash(arr,i-1,j+1)) isCenter = false;
        if(!isHash(arr,i,j-1)) isCenter = false;
        if(!isHash(arr,i,j+1)) isCenter = false;
        if(!isHash(arr,i+1,j-1)) isCenter = false;
        if(!isHash(arr,i+1,j)) isCenter = false;
        if(!isHash(arr,i+1,j+1)) isCenter = false;
        return isCenter;
    }

    static boolean isHash(char[][] arr, int i, int j) {
        if(arr[i][j] == '#') return true;
        return false;
    }

    static boolean isCenter(char[][] arr, int i, int j, int n, int m) {
        if(i<=0 || i>=n-1 || j<=0 || j>=m-1) return false;
        if(arr[i][j] == 'C') return true;
        return false;
    }


