                            possible |= check(a, mark, i - 2, j - 2);
                        }
                        if (i < n - 2 && j < m - 2) {
                            possible |= check(a, mark, i, j);
                        }
                        if (i < n - 2 && j > 1) {
                            possible |= check(a, mark, i, j - 2);
                        }
                        if (i > 1 && j < m - 2) {
                            possible |= check(a, mark, i - 2, j);
                        }
                        if (mark[i][j] == 0 && !possible) {
                            ans = false;
                        }
                    }
                }
            }
            if (ans)
                out.println("YES");
            else
                out.println("NO");
        }

    }

    static class InputReader extends BufferedReader {
        public InputReader(InputStream st) {
            super(new InputStreamReader(st));
        }

        public String readLine() {
            try {
                return super.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        private int skip() {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b)) ;
            return b;
        }

        private int readByte() {
            try {
                return read();
            } catch (IOException e) {
                throw new RuntimeException();
            }
        }

        public int ni() {
            int num = 0, b;
            boolean minus = false;
            while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
            if (b == '-') {
                minus = true;
                b = readByte();
            }

            while (true) {
                if (b >= '0' && b <= '9') {
                    num = num * 10 + (b - '0');
                } else {
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }

        public String ns() {
            int b = skip();
            StringBuilder sb = new StringBuilder();
            while (!(isSpaceChar(b))) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

    }
}

