public class CFB {

    BufferedReader br;
    PrintWriter out;
    StringTokenizer st;
    boolean eof;
    private static final long MOD = 1000L * 1000L * 1000L + 7;
    private static final int[] dx = {0, -1, 0, 1};
    private static final int[] dy = {1, 0, -1, 0};
    private static final String yes = "Yes";
    private static final String no = "No";

    int n;
    int m;
    char[][] mat;
    char[][] has;
    void solve() throws IOException {
        n = nextInt();
        m = nextInt();
        mat = new char[n][m];
        for (int i = 0; i < n; i++) {
            mat[i] = nextString().toCharArray();
        }

        has = new char[n][m];
        for (int i = 0; i < n; i++) {
            Arrays.fill(has[i], '.');
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (mat[i][j] == '#' && has[i][j] == '.') {
                    boolean valid = fill(i, j);
                    if (!valid) {
                        outln(no.toUpperCase());
                        return;
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (mat[i][j] != has[i][j]) {
                    outln(no.toUpperCase());
                    return;
                }
            }
        }

        outln(yes.toUpperCase());
    }

    boolean fill(int r, int c) {
        int left = c - 2;
        int top = r - 2;
        boolean valid = false;
        for (int i = top; i <= r; i++) {
            for (int j = left; j <= c; j++) {
                int ni = i + 2;
                int nj = j + 2;

                if (i + ni == 2 * r && j + nj == c) {
                    continue;
                }

                if (i >= 0 && i < n && j >= 0 && j < m
                        && ni >= 0 && ni < n && nj >= 0 && nj < m) {

                    boolean tmp = canFill(i, j);
                    if (tmp) {
                        fillHas(i, j);
                        valid = true;
                    }
                }
            }
        }

        return valid;
    }


    void fillHas(int r, int c) {
        for (int i = r; i < r + 3; i++) {
            for (int j = c; j < c + 3; j++) {
                if (i == r + 1 && j == c + 1) {
                    continue;
                }
                has[i][j] = '#';
            }
        }
    }

    boolean canFill(int r, int c) {
        for (int i = r; i < r + 3; i++) {
            for (int j = c; j < c + 3; j++) {
                if (i == r + 1 && j == c + 1) {
                    continue;
                }

                if (mat[i][j] == '.') {
                    return false;
                }
            }
        }

        return true;
    }

    void shuffle(int[] a) {
        int n = a.length;
        for(int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }
    long gcd(long a, long b) {
        while(a != 0 && b != 0) {
            long c = b;
            b = a % b;
            a = c;
        }
        return a + b;
    }
    private void outln(Object o) {
        out.println(o);
    }
    private void out(Object o) {
        out.print(o);
    }
    private void formatPrint(double val) {
        outln(String.format("%.9f%n", val));
    }
    public CFB() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }
