    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            boolean[][] used = new boolean[n][m];
            String[] field = new String[n];
            String[] pat = {"###", "#.#", "###"};
            for (int i = 0; i < n; i++) {
                field[i] = in.next();
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    calc(used, field, pat, i - 2, j - 2);
                    calc(used, field, pat, i - 2, j - 1);
                    calc(used, field, pat, i - 2, j);
                    calc(used, field, pat, i - 1, j - 2);
                    calc(used, field, pat, i - 1, j - 1);
                    calc(used, field, pat, i - 1, j);
                    calc(used, field, pat, i, j - 2);
                    calc(used, field, pat, i, j - 1);
                    calc(used, field, pat, i, j);
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (field[i].charAt(j) == '#') {
                        if (!used[i][j]) {
                            out.println("NO");
                            return;
                        }
                    }
                }
            }
            out.println("YES");
