        void calc(boolean[][] used, String[] field, String[] pat, int y, int x) {
            if (x >= 0 && x + pat[0].length() <= field[0].length()
                    && y >= 0 && y + pat.length <= field.length) {
                for (int i = 0; i < pat.length; i++) {
                    for (int j = 0; j < pat[0].length(); j++) {
                        if (pat[i].charAt(j) == '#' && pat[i].charAt(j) != field[y + i].charAt(x + j)) {
                            return;
                        }
                    }
                }
                for (int i = 0; i < pat.length; i++) {
                    for (int j = 0; j < pat[0].length(); j++) {
                        if (pat[i].charAt(j) == '#') used[y + i][x + j] = true;
                    }
                }
            }
        }

