public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        boolean[][] grid;
        boolean[][] filled;
        int N;
        int M;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            N = in.nextInt();
            M = in.nextInt();
            grid = new boolean[N][M];
            filled = new boolean[N][M];
            for (int i = 0; i < N; i++) {
                char[] s = in.next().toCharArray();
                for (int j = 0; j < M; j++) {
                    grid[i][j] = (s[j] == '#');
                }
            }
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    if (works(i, j)) {
                        fill(i, j);
                    }
                }
            }
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    if (grid[i][j] != filled[i][j]) {
                        out.println("NO");
                        return;
                    }
                }
            }
            out.println("YES");
        }

        void fill(int r, int c) {
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    if (i != 1 || j != 1) {
                        filled[r + i][c + j] = true;
                    }
                }
            }
        }

        boolean works(int r, int c) {
            if (r + 2 >= N || c + 2 >= M) {
                return false;
            } else {
                for (int i = 0; i < 3; i++) {
                    for (int j = 0; j < 3; j++) {
                        if (i != 1 || j != 1) {
                            if (!grid[r + i][c + j]) {
                                return false;
                            }
                        }
                    }
                }
                return true;
            }
        }

    }

