            for (int j = 0; j < m; j++) {
                a[i][j] = s.charAt(j) == '#';
            }
        }
        boolean[][] b = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (i + 2 < n && j + 2 < m) {
                    boolean can = true;
                    for (int x = i; x < i + 3; x++) {
                        for (int y = j; y < j + 3; y++) {
                            if (x - i == 1 && y - j == 1) continue;
                            if (!a[x][y]) {

                                can = false;
                                break;
                            }
                        }
                    }
                    if (can) {

                        for (int x = i; x < i + 3; x++) {
                            for (int y = j; y < j + 3; y++) {
                                if (x - i == 1 && y - j == 1) continue;
                                b[x][y] = true;
                            }
                        }
                    }
                }
            }
        }





        if (same(a, b)) out.println("YES");
        else out.println("NO");
    }

    private boolean same(boolean[][] a, boolean[][] b) {
        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < a[0].length; j++)
                if (a[i][j] != b[i][j]) {

                    return false;
                }
        }
        return true;
    }
