				placePen(signArea, i, j);

			}
		}

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {

				if(signArea[i][j] == '#') {
					System.out.println("NO");
					return;
				}

			}
		}
		System.out.println("YES");
	}


