		for(int i = 0; i < sa.length; i++) {
			for(int j = 0; j < sa[i].length; j++) {
				System.out.print(sa[i][j]);
			}
			System.out.println();
		}
	}

	private static void placePen(char[][] signArea, int i, int j) {

		if (isWithInk(i + 1,j + 1, signArea) && 
				isWithInk(i + 1,j, signArea)&&
				isWithInk(i + 1,j - 1, signArea) &&
				isWithInk(signArea, i, j + 1)  && isWithInk(signArea,i,j - 1)  && isWithInk(signArea, i - 1, j + 1)&& 
				isWithInk(signArea, i - 1,j)&& isWithInk(i - 1,j - 1,signArea )) {
			signArea[i + 1][j + 1] = 'v';
			signArea[i + 1][j] = 'v';
			signArea[i + 1][j - 1] = 'v';
			signArea[i][j + 1] = 'v';
			signArea[i][j - 1] = 'v';
			signArea[i - 1][j + 1] = 'v';
			signArea[i - 1][j] = 'v';
			signArea[i - 1][j - 1] = 'v';
		}

	}

	public static boolean isWithInk(int i, int j, char[][] signArea) {
		return signArea[i][j] == 'v' || signArea[i][j] == '#';
	}


	public static boolean isWithInk(char[][] signArea, int i, int j) {
		return signArea[i][j] == 'v' || signArea[i][j] == '#';
	}
}

