        for (int i = 0; i < n; i++) {
            s[i] = is().toCharArray();
            Arrays.fill(a[i], '.');
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (valid(i, j)) {
