        a[i][j + 1] = '#';
        a[i + 1][j + 1] = '#';
    }

    boolean canFillInk(int i, int j) {
        return s[i - 1][j - 1] == '#' &&
                s[i][j - 1] == '#' &&
                s[i + 1][j - 1] == '#' &&
                s[i - 1][j] == '#' &&
                s[i + 1][j] == '#' &&
                s[i - 1][j + 1] == '#' &&
                s[i][j + 1] == '#' &&
                s[i + 1][j + 1] == '#';
    }

    boolean valid(int i, int j) {
        return 0 <= (i - 1) &&
                (i + 1) < n &&
                0 <= (j - 1) &&
                (j + 1) < m;
    }

    int n, m;
    char s[][], a[][];


