                            for (int dj = -2; dj <= 0; dj++) {
                                if (i + di < 0 || j + dj < 0) {
                                    continue;
                                }
                                if (di == -1 && dj == -1) {
                                    continue;
                                }
                                if (i + di + 3 > n || j + dj + 3 > m) {
                                    continue;
                                }
                                any |= check(i + di, j + dj);
                            }
                        }
                        if (!any) {
                            out.print("NO");
                            return;
                        }
                    }
                }
            }
            out.print("YES");
        }

        boolean check(int i0, int j0) {
