            {
                for(int j = 0; j < n/2; j++) {
                    int a1 = a[k];
                    int a2 = a[k + 1];
                    int a3 = a[k + 2];
                    int a4 = a[k + 3];
                    if (a1 != a2 || a2 != a3 || a3 != a4) {
                        System.out.println("NO");
                        return;
                    } else {
                        matrix[i][j] = a1;
                        matrix[n-1-i][j] = a1;
