                if (a1 != a2) {
                    if (false == spFound) {
                        k = k + 1;
                        spElem = a1;
                        spFound = true;
                        a1 = a[k + 1];
                        if (a1 != a2) {
                            failed = true;
                        }
                        matrix[n / 2][i] = a1;
                        matrix[n / 2][n - 1 - i] = a1;
                    } else {
                        failed = true;
                    }
                } else {
                    matrix[n / 2][i] = a1;
                    matrix[n / 2][n - 1 - i] = a1;
                }
                k += 2;
                if (failed) {
                    System.out.println("No");
                    return;
