import java.io.*;
import java.util.*;

public class Main {

	static int N, L;
	static int[] input, count = new int[1001];
	static int[][] out;
	static boolean odd = false;
	static Queue<Pair> list2 = new LinkedList<>();
	static Queue<Pair> list4 = new LinkedList<>();

	public static void main(String[] args) throws Exception {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
		N = Integer.parseInt(br.readLine());
		if (N % 2 == 1) {
			odd = true;
		}
		input = new int[N * N];
		L = (N + 1) / 2;
		out = new int[L][L];

		int max = 0;
		StringTokenizer st = new StringTokenizer(br.readLine());
		for (int n = 0; n < N * N; n++) {
			count[input[n] = Integer.parseInt(st.nextToken())]++;
			max = Math.max(max, input[n]);
		}

		boolean find = true;
		if (odd) {
			for (int j = 0; j < L - 1; j++) { 
				list2.add(new Pair(L - 1, j));
			}
			for (int i = 0; i < L - 1; i++) { 
				list2.add(new Pair(i, L - 1));
			}
			for (int i = 0; i < L - 1; i++) {
				for (int j = 0; j < L - 1; j++) {
					list4.add(new Pair(i, j));
				}
			}
		} else {
			for (int i = 0; i < L; i++) {
				for (int j = 0; j < L; j++) {
					list4.add(new Pair(i, j));
				}
			}
		}

		int n = 1;
		Pair p;
		boolean allZero = true;
		while (true) {
			if (n == 1) {
				allZero = true;
			}
			if (count[n] == 0) {
			} else if (count[n] % 2 == 1) {
				out[L - 1][L - 1] = n;
				count[n]--;
				allZero = false;
			} else if (count[n] % 4 == 2) {
				if (!list2.isEmpty()) {
					p = list2.poll();
					out[p.x][p.y] = n;
					count[n] -= 2;
					allZero = false;
				} else {
					find = false;
					break;
				}
			} else if (count[n] % 4 == 0) {
				if (!list4.isEmpty()) {
					p = list4.poll();
					out[p.x][p.y] = n;
					count[n] -= 4;
				} else if (!list2.isEmpty()) {
					p = list2.poll();
					out[p.x][p.y] = n;
					count[n] -= 2;
				} else {
					find = false;
					break;
				}
				allZero = false;
			}
			n++;
			if (n > max) {
				if (allZero) {
					if (!list2.isEmpty() || !list4.isEmpty()) {
						find = false;
					}
					break;
				} else {
					n = 1;
				}
			}
		}

		if (find) {
			bw.write("YES\n");
			if (odd) {
				for (int i = 0; i < L; i++) {
					for (int j = 0; j < L; j++) {
						bw.write(out[i][j] + " ");
					}
					for (int j = L - 2; j >= 0; j--) {
						bw.write(out[i][j] + " ");
					}
					bw.write("\n");
				}
				for (int i = L - 2; i >= 0; i--) {
					for (int j = 0; j < L; j++) {
						bw.write(out[i][j] + " ");
					}
					for (int j = L - 2; j >= 0; j--) {
						bw.write(out[i][j] + " ");
					}
					bw.write("\n");
				}
			} else {
				for (int i = 0; i < L; i++) {
					for (int j = 0; j < L; j++) {
						bw.write(out[i][j] + " ");
					}
					for (int j = L - 1; j >= 0; j--) {
						bw.write(out[i][j] + " ");
					}
					bw.write("\n");
				}
				for (int i = L - 1; i >= 0; i--) {
					for (int j = 0; j < L; j++) {
						bw.write(out[i][j] + " ");
					}
					for (int j = L - 1; j >= 0; j--) {
						bw.write(out[i][j] + " ");
					}
					bw.write("\n");
				}
			}
		} else {
			bw.write("NO\n");
		}
		bw.close();

	}

	static class Pair {

		int x, y;

		public Pair(int x, int y) {
			super();
			this.x = x;
			this.y = y;
		}

	}

}

