    }

    static class CPalindromnayaMatrica {
        InputReader in;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            this.in = in;

            int n = ni();
            if (n == 1) {
                out.println("YES");
                out.print(in.nextInt());
                return;
            }

            int[] count = new int[2000];
            for (int i = 0; i < n * n; i++) {
                count[in.nextInt()]++;
            }

            TreeMap<Integer, ArrayDeque<CPalindromnayaMatrica.Pair>> tree = new TreeMap<>();
            for (int i = 0; i < 2000; i++) {
                if (count[i] != 0)
                    tree.computeIfAbsent(count[i], k -> new ArrayDeque<>()).offer(new CPalindromnayaMatrica.Pair(i, count[i]));
            }

            int[][] res = new int[n][n];

            Integer key = null;
            ArrayDeque<CPalindromnayaMatrica.Pair> next = null;
            CPalindromnayaMatrica.Pair nextPair = null;
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    if (key == null || next == null || (nextPair == null && next.isEmpty())) {
                        key = tree.ceilingKey(4);
                        if (key == null) {
                            out.print("NO");
                            return;
                        }

                        next = tree.remove(key);
                        nextPair = next.poll();
                    }

                    if (nextPair == null) nextPair = next.poll();

                    res[i][j] = res[n - i - 1][j] = res[i][n - j - 1] = res[n - i - 1][n - j - 1] = nextPair.i;
                    nextPair.count -= 4;

                    if (nextPair.count > 0 && nextPair.count < 4) {
                        tree.computeIfAbsent(nextPair.count, k -> new ArrayDeque<>()).offer(nextPair);
                        nextPair = null;
                    } else if (nextPair.count == 0) nextPair = null;
                }
            }

            if (nextPair != null && nextPair.count > 0)
                tree.computeIfAbsent(nextPair.count, k -> new ArrayDeque<>()).offer(nextPair);
            if (key != null && next != null && !next.isEmpty()) tree.put(key, next);

            if (n % 2 == 1) {
                key = null;
                next = null;
                nextPair = null;
                for (int i = 0; i < n / 2; i++) {
                    if (key == null || next == null || (nextPair == null && next.isEmpty())) {
                        key = tree.ceilingKey(2);
                        if (key == null) {
                            out.print("NO");
                            return;
                        }

                        next = tree.remove(key);
                        nextPair = next.poll();
                    }

                    if (nextPair == null) nextPair = next.poll();

                    res[i][n / 2] = res[n - i - 1][n / 2] = nextPair.i;
                    nextPair.count -= 2;

                    if (nextPair.count > 0 && nextPair.count < 2) {
                        tree.computeIfAbsent(nextPair.count, k -> new ArrayDeque<>()).offer(nextPair);
                        nextPair = null;
                    } else if (nextPair.count == 0) nextPair = null;
                }

                if (nextPair != null && nextPair.count > 0)
                    tree.computeIfAbsent(nextPair.count, k -> new ArrayDeque<>()).offer(nextPair);
                if (key != null && next != null && !next.isEmpty()) tree.put(key, next);

                key = null;
                next = null;
                nextPair = null;
                for (int i = 0; i < n / 2; i++) {
                    if (key == null || next == null || (nextPair == null && next.isEmpty())) {
                        key = tree.ceilingKey(2);
                        if (key == null) {
                            out.print("NO");
                            return;
                        }

                        next = tree.remove(key);
                        nextPair = next.poll();
                    }

                    if (nextPair == null) nextPair = next.poll();

                    res[n / 2][i] = res[n / 2][n - i - 1] = nextPair.i;
                    nextPair.count -= 2;

                    if (nextPair.count > 0 && nextPair.count < 2) {
                        tree.computeIfAbsent(nextPair.count, k -> new ArrayDeque<>()).offer(nextPair);
                        nextPair = null;
                    } else if (nextPair.count == 0) nextPair = null;
                }

                key = tree.ceilingKey(1);
                if (key == null) {
                    out.print("NO");
                    return;
                }

                next = tree.remove(key);

                res[n / 2][n / 2] = next.poll().i;
            }

            StringBuilder resS = new StringBuilder("YES\n");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    resS.append(res[i][j]).append(' ');
                }
                resS.append('\n');
            }
            out.print(resS);
        }

