    public void solve() {
        int n = ni();
        if (n == 1) {
            write("YES\n" + ni() + "\n");
            return;
        }
        int[] nums = new int[1001];
        for (int i = 0; i < n*n; i++) {
            nums[ni()]++;
        }
        a = new ArrayList<>();
        for (int i = 1; i <= 1000; i++) {
            if (nums[i] > 0) {
                int cur = nums[i];
                if (cur % 2 == 1) {
                    a.add(new P(i, 1));
                    cur--;
                }
                if (cur % 4 != 0) {
                    a.add(new P(i, cur % 4));
                    cur -= cur % 4;
                }
                a.add(new P(i, cur));
            }
        }
        Collections.sort(a);
        int oneCount = 0;
        int twoCount = 0;
        for (P p: a) {
            int cur = p.n;
            if (cur % 2 == 1) {
                oneCount++;
                cur--;
            }
            if (cur % 4 != 0) {
                twoCount += cur % 4;
            }
        }
        if ((n % 2 == 0) && (oneCount > 0) || (n % 2 != 0) && (oneCount != 1)) {
            write("NO\n");
            return;
        }
        if ((n % 2 == 0) && (twoCount != 0) || (n % 2 != 0) && (twoCount > (n - 1) * 2)) {
            write("NO\n");
            return;
        }
        int s = n / 2 + n % 2;
        int[][] f = new int[s][s];
        int c = 0;
        if (n % 2  == 1) {
            f[s - 1][s - 1] = next(1);
            for (int i = 0; i < n / 2; i++) {
                f[s - 1][i] = next(2);
                f[i][s - 1] = next(2);
            }
        }
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                f[i][j] = next(4);
            }
        }
        write("YES\n");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int x = i > s - 1 ? n - i - 1: i;
                int y = j > s - 1 ? n - j - 1: j;
                write(f[x][y] + " ");
            }
            write("\n");
        }
    }

    int next(int t) {
        P cur = a.get(c);
        if (cur.n == 0) {
            c++;
            return next(t);
        } else {
            cur.n -= t;
            return cur.x;
        }
    }

    class P implements Comparable<P> {
        public int x;
        public int n;
        public int p;
        public P(int x, int n) {
            this.x = x;
            this.n = n;
            p = n % 4 == 0 ? 2 : (n % 2 == 0 ? 1 : 0);
        }

        @Override
        public int compareTo(P p) {
            return Integer.compare(this.p, p.p);
        }
    }



