    	for(int a=0;a<middle&&judge==1;a++)
    	{
    		for(int b=0;b<middle;b++)
    		{
    			int index=getIndexByDecreasingOrder(arr);


    			if(index==-1)
    			{
    				judge=0;
    				break;
    			}

    			else
    			{

    				output[a][b]=arr.get(index).value;
