    public static int getIndexByIncreasingOrder(ArrayList<Data> arr) 
    {
    	int result=-1;
    	for(int a=0;a<arr.size();a++)
    	{
    		if(arr.get(a).count>=2)
    		{
    			result=a;
    			break;
    		}
    	}
    	return result;
    }
    public static int getIndexByDecreasingOrder(ArrayList<Data> arr) 
    {
    	int result=-1;
    	for(int a=arr.size()-1;a>=0;a--)
    	{
    		if(arr.get(a).count>=4)
    		{
    			result=a;
    			break;
    		}
    	}
    	return result;
    }
