                int size = (j - i) / 4;
                for (int p = 0; p < size; ++p) nums.add(a[i]);
                for (int p = i; p < i + (size * 4); ++p) a[p] = -1;
                i = j;
            }

            int ptr = 0;
            try {
                for (int i = 0; i < n / 2; ++i) {
                    for (int j = 0; j < n / 2; ++j) {
                        map[i][j] = map[n - 1 - i][j] = map[i][n - 1 - j] = map[n - 1 - i][n - 1 - j] = nums.get(ptr);
                        ++ptr;
                    }
                }
            } catch (Exception e) {
