            }

            a = ArrayUtils.sort(a);
            ArrayList<Integer> rem = new ArrayList<>();
            for (int i = ptr; i < nums.size(); ++i) {
                rem.add(nums.get(i));
                rem.add(nums.get(i));
            }
            nums = rem;
            try {
                if (n % 2 == 1) {
