                        i = j;
                    }


                    ptr = 0;
                    for (int j = 0; j < n / 2; ++j) {
                        map[n / 2][j] = map[n / 2][n - 1 - j] = nums.get(ptr);
                        ++ptr;
                    }

                    for (int j = 0; j < n / 2; ++j) {
                        map[j][n / 2] = map[n - 1 - j][n / 2] = nums.get(ptr);
                        ++ptr;
                    }

                    a = ArrayUtils.sort(a);
                    rem = new ArrayList<>();
                    for (i = ptr; i < nums.size(); ++i) {
                        rem.add(nums.get(i));
                        rem.add(nums.get(i));
                    }
                    nums = rem;
                    i = 0;
                    while (i < a.length && a[i] == -1) ++i;
                    if (i < a.length) nums.add(a[a.length - 1]);

                    if (nums.size() > 1) {
                        out.println("NO");
                        return;
                    }
                    if (n % 2 == 1) map[n / 2][n / 2] = nums.get(0);
                }
            } catch (Exception e) {
                out.println("NO");
                return;
            }
            if (check(map)) {
                out.println("YES");
                ArrayUtils.printMap(out, map);
                return;
            }
        }

        private boolean check(int[][] map) {
            int n = map.length;
            final int bad = -1;

            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    if (map[i][j] == bad) return false;
                }
            }

            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    if (map[i][j] != map[n - 1 - i][j]) return false;
                    if (map[i][j] != map[i][n - 1 - j]) return false;
                    if (map[i][j] != map[n - 1 - i][n - j - 1]) return false;
                }
            }
            return true;
        }

    }

    static class ArrayUtils {
        public static int[] sort(int[] a) {
            a = shuffle(a, new SplittableRandom());
            Arrays.sort(a);
            return a;
        }

        public static int[] shuffle(int[] a, SplittableRandom gen) {
            for (int i = 0, n = a.length; i < n; i++) {
                int ind = gen.nextInt(n - i) + i;
                int d = a[i];
                a[i] = a[ind];
                a[ind] = d;
            }
            return a;
        }

        public static void fill(int[][] array, int value) {
            for (int[] row : array) {
                Arrays.fill(row, value);
            }
        }

        public static void printArray(PrintWriter out, int[] array) {
            if (array.length == 0) return;
            for (int i = 0; i < array.length; i++) {
                if (i != 0) out.print(" ");
                out.print(array[i]);
            }
            out.println();
        }

        public static void printMap(PrintWriter out, int[][] map) {
            for (int i = 0; i < map.length; i++) {
                printArray(out, map[i]);
            }
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[8192];
        private int curChar;
        private int pnumChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int pread() {
            if (pnumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= pnumChars) {
                curChar = 0;
                try {
                    pnumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (pnumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = pread();
            while (isSpaceChar(c))
                c = pread();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = pread();
            }
            int res = 0;
            do {
                if (c == ',') {
                    c = pread();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = pread();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }

