import java.util.HashMap;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;
import java.util.Scanner;

public class Main {

	private static int[][] output = new int[100][100];	

	public static void main(String[] args) {							

		Scanner scan = new Scanner(System.in);

		int i , j , n = scan.nextInt();
		Map<Integer , Integer> map = new HashMap<>();
		for (i = 1;i <= n * n;i ++) {
			int value = scan.nextInt();
			map.put(value , map.getOrDefault(value , 0) + 1);			
		}

		if (n % 2 == 0) {
			Queue<Integer> queue = new LinkedList<>();					
			for (Map.Entry<Integer , Integer> entry : map.entrySet()) {
				int cnt = entry.getValue();			
				if (cnt % 4 != 0) {
					System.out.println("NO");
					return;					
				}			
				for (i = 0;i < cnt / 4;i ++) {
					queue.add(entry.getKey());				
				}
			}			
			for (i = 1;i <= n / 2;i ++) {
				for (j = 1;j <= n / 2;j ++) {
					output[i][j] = output[n - i + 1][j] = output[i][n - j + 1] = output[n - i + 1][n - j + 1] = queue.poll();
				}
			}
		} else {
			int remain = - 1;	
			Queue<Integer> fourQueue = new LinkedList<>() , twoQueue = new LinkedList<>();			
			for (Map.Entry<Integer , Integer> entry : map.entrySet()) {
				int cnt = entry.getValue();			
				if (cnt % 4 != 0) {
					int value = cnt % 4;
					if (value == 2) {
						twoQueue.add(entry.getKey());						
					} else if (value == 1) {
						if (remain < 0) {							
							remain = entry.getKey();
						} else {
							System.out.println("NO");
							return;							
						}
					} else if (value == 3) {
						twoQueue.add(entry.getKey());
						if (remain < 0) {
							remain = entry.getKey();
						} else {
							System.out.println("NO");
							return;
						}
					}
				}
				for (i = 0;i < cnt / 4;i ++) {
					fourQueue.add(entry.getKey());				
				}
			}	
			for (i = 1;i <= n / 2;i ++) {
				for (j = 1;j <= n / 2;j ++) {
					if (fourQueue.isEmpty()) {
						System.out.println("NO");
						return;
					} else {
						int value = fourQueue.poll();
						output[i][j] = output[n - i + 1][j] = output[i][n - j + 1] = output[n - i + 1][n - j + 1] = value;					
					}
				}
			}
			for (i = 1;i <= n / 2;i ++) {
				if (twoQueue.isEmpty()) {
					if (!fourQueue.isEmpty()) {
						int value = fourQueue.poll();
						twoQueue.add(value);
						twoQueue.add(value);	
					}
				} 
				if (twoQueue.isEmpty()) {
					System.out.println("NO");
					return;					
				} else {
					output[i][(n + 1) / 2] = output[n - i + 1][(n + 1) / 2] = twoQueue.poll();
				}
			}
			for (j = 1;j <= n / 2;j ++) {
				if (twoQueue.isEmpty()) {
					if (!fourQueue.isEmpty()) {
						int value = fourQueue.poll();
						twoQueue.add(value);
						twoQueue.add(value);						
					}
				} 
				if (twoQueue.isEmpty()) {
					System.out.println("NO");
					return;					
				} else {
					output[(n + 1) / 2][j] = output[(n + 1) / 2][n - j + 1] = twoQueue.poll();
				}
			}
			output[(n + 1) / 2][(n + 1) / 2] = remain;
		}

		System.out.println("YES");
		for (i = 1;i <= n;i ++) {
			StringBuilder builder = new StringBuilder();
			for (j = 1;j <= n;j ++) {
				if (j > 1) {
					builder.append(" ");
				}
				builder.append(output[i][j]);
			}
			System.out.println(builder.toString());
		}

	}


}

import java.io.PrintWriter;
import java.lang.reflect.Array;
import java.util.Arrays;
import java.util.Scanner;

public class PalindromicMatrix {

	public static void main(String[] args) {

		Scanner in = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		int n = in.nextInt();
		int n2 = n*n;
		int [] arr = new int [n2];
		boolean works = true;

		for (int i = 0; i < n2; i++) {
			arr[i] = in.nextInt();
		}
		Arrays.sort(arr);
		int[][] outMat = new int[(n+1)/2][(n+1)/2];

		if (n % 2 == 0) {

			int j = 0;
			while (works && j < n2) {
				int current = arr[j];
				if (current != arr[j + 1] || current != arr[j+2] || current != arr[j+3]) {
					works = false;
				}
				j += 4;
			}
			for(int i = 0; i<n/2; i++) {
				for(int k = 0; k<n/2; k++) {
					outMat[i][k] = arr[(i*(n/2)+k)*4];
				}
			}
		}else {
			int ind4 = 0;
			int ind2 = 0;
			int[] part4 = new int[(n/2)*(n/2)];
			int[] part2 = new int[2*(n/2)];
			int oddV = -1;
			for(int i =0; i< n*n;) {
				int st = i;
				i++;
				while(i<n*n && arr[i] == arr[st]) {
					i++;
				}

				if((i-st)%2==1) {
					if(oddV==-1) {
						oddV = arr[st];
						st++;
					}
				}

				while(st+4<= i && ind4<part4.length) {
					part4[ind4] = arr[st];
					ind4++;
					st+=4;
				}
				while(st+2 <= i && ind2<part2.length) {
					part2[ind2] = arr[st];
					st += 2;
					ind2++;
				}
				if(i!=st) {
					works = false;
				}
			}
			if(oddV==-1) {
				works = false;
			}
			for(int i = 0; i<n/2; i++) {
				for(int j = 0; j<n/2; j++) {
					outMat[i][j] = part4[i*(n/2)+j];
				}
			}
			for (int i = 0; i < n/2; i++) {
				outMat[i][n/2] = part2[i];
			}
			for (int i = n/2; i < 2*(n/2); i++) {
				outMat[n/2][i-n/2] = part2[i];
			}
			outMat[n/2][n/2] = oddV;
		}
		int[][] matrix = new int[n][n];
		for (int i = 0; i < outMat.length; i++) {
			for (int j = 0; j < outMat.length; j++) {
				matrix[i][j] = outMat[i][j];
				matrix[n-1-i][j] = outMat[i][j];
				matrix[i][n-1-j] = outMat[i][j];
				matrix[n-1-i][n-1-j] = outMat[i][j];

			}
		}

		if (works) {
			out.println("YES");


			printArr(matrix, out);
		} else {
			out.println("NO");
		}

		in.close();
		out.close();
	}

	private static void printArr(int[][] matrix, PrintWriter out) {

		for (int i = 0; i < matrix.length; i++) {
			for(int j = 0; j < matrix.length - 1; j++) {
				out.print(matrix[i][j]+ " ");
			}
			out.println(matrix[i][matrix.length - 1]);
		}




	}

}

