                    a[i]--;
                    break;
                }
            }

            int j = 0;
            for (int i = 0; i < n / 2; i++) {
                while (j < a.length) {
                    if (a[j] == 0) {
                        j++;
                        continue;
                    }
                    if (a[j] % 2 == 1) {
                        return "NO";
                    } else if (a[j] % 4 != 0) {
                        b[i][n / 2] = j;
                        b[n - i - 1][n / 2] = j;
                        a[j] -= 2;
                        break;
                    }
                    j++;
                }
            }
            j = 0;
            for (int i = 0; i < n / 2; i++) {
                while (j < a.length) {
                    if (a[j] == 0) {
                        j++;
                        continue;
                    }
                    if (a[j] % 2 == 1) {
                        return "NO";
                    } else if (a[j] % 4 != 0) {
                        b[n / 2][i] = j;
                        b[n / 2][n - i - 1] = j;
                        a[j] -= 2;
                        break;
                    }
                    j++;
                }
            }

            j = 0;
            for (int i = 0; i < n / 2; i++) {
                if (b[i][n / 2] == 0) {
                    while (j < a.length) {
                        if (a[j] == 0) {
                            j++;
                            continue;
                        }
                        if (a[j] % 2 == 1) {
                            return "NO";
                        } else {
                            b[i][n / 2] = j;
                            b[n - i - 1][n / 2] = j;
                            a[j] -= 2;
                            break;
                        }
                    }
                }
                if (b[n / 2][i] == 0) {
                    while (j < a.length) {
                        if (a[j] == 0) {
                            j++;
                            continue;
                        }
                        if (a[j] % 2 == 1) {
                            return "NO";
                        } else {
                            b[n / 2][i] = j;
                            b[n / 2][n - i - 1] = j;
                            a[j] -= 2;
                            break;
                        }
                    }
                }
            }
        }
        int x = 0;
        int y = 0;
        for (int i = 0; i < a.length; i++) {
            if (a[i] % 4 != 0) {
                return "NO";
            } else {
                while (a[i] > 0) {
                    b[x][y] = i;
                    b[x][n - y - 1] = i;
                    b[n - x - 1][y] = i;
                    b[n - x - 1][n - y - 1] = i;
                    x++;
                    a[i] -= 4;
                    if (x == n / 2) {
                        x = 0;
                        y++;
                    }
                }
            }
        }

        StringBuilder sb = new StringBuilder("YES\n");
        for (int[] bb : b) {
            for (int i : bb) {
                sb.append(i).append(" ");
            }
            sb.append("\n");
        }
        return sb.toString();
    }
