				if (map.get(arr[j])>=2)
				{
					matrix[i][(n-1)/2]=arr[j];
					matrix[n-1-i][(n-1)/2]=arr[j];
					map.put(arr[j],map.get(arr[j])-2);
					i++;
				}
				if (map.get(arr[j])<2)
				j++;
			}
			j=0;
			for (int i=0;i<n/2 && j<arr.length;)
			{
				if (map.get(arr[j])>=2)
				{
					matrix[(n-1)/2][i]=arr[j];
					matrix[(n-1)/2][n-1-i]=arr[j];
					map.put(arr[j],map.get(arr[j])-2);
					i++;
				}
				if (map.get(arr[j])<2)
				j++;
			}
			for (int i=0;i<arr.length;i++)
			{
				if (map.get(arr[i])>=1)
					{
					matrix[(n-1)/2][(n-1)/2]=arr[i];
					map.put(arr[i],map.get(arr[i])-1);
