import java.io.*;
import java.util.*;

public class PalindromicMatrix {
	public static void main(String[] args) throws Exception {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(in.readLine());
		ArrayList<Integer> nums = new ArrayList<Integer>();
		StringTokenizer st = new StringTokenizer(in.readLine());
		for(int i = 0; i<n*n; i++) {
			nums.add(Integer.parseInt(st.nextToken()));
		}
		in.close();
		solve(n, nums);
	}

	public static void solve(int n, ArrayList<Integer> nums) {
		Map<Integer, Integer> count = new HashMap<Integer,Integer>();
		for(int i : nums) {
			if(count.containsKey(i)) {
				count.put(i, count.get(i)+1);
			} else {
				count.put(i, 1);
			}
		}
		int[][] res = new int[n][n];
		if(n%2==0) {
			int start = 0;
			int end = n/2 - 1;
			int x = 0, y = 0;
			for(int i : count.keySet()) {
				int times = count.get(i);
				if(times%4!=0) {
					System.out.println("NO");
					return;
				} 
				while(times!=0) {
					res[x][y] = i;
					res[n - 1 - x][n - 1 - y] = i;
					res[x][n - 1 - y] = i;
					res[n - 1 - x][y] = i;
					times -= 4;
					if(x==end) {
						x = 0;
						y++;
					} else {
						x++;
					}
				}
			}
		} else {
			int start = 0;
			int end = n/2 - 1;
			int middle = n/2;
			int x = 0, y = 0;
			boolean centerUsed = false;
			int mid = 0;
			boolean midUsed = n==1;
			boolean swappedToVertical = false;
			int spaceLeftQuads = middle*middle*4;

			for(int i : count.keySet()) {
				int times = count.get(i);
				while(times>=4 && spaceLeftQuads>0) {
					res[x][y] = i; 
					res[n - 1 - x][n - 1 - y] = i; 
					res[x][n - 1 - y] = i; 
					res[n - 1 - x][y] = i; 
					times -= 4;
					spaceLeftQuads -= 4;
					if(x==end) {
						x = 0;
						y++;
					} else {
						x++;
					}
				}
				while(times>=2) {
					if(midUsed) {
						System.out.println("NO");
						return;
					}
					if(swappedToVertical) {
						res[middle][mid] = i;
						res[middle][n - 1 - mid] = i;
						times -= 2;
						mid++;
						if(mid==middle) {
							midUsed = true;
						}
					} else {
						res[mid][middle] = i;
						res[n - 1 - mid][middle] = i;
						times -= 2;
						mid++;
						if(mid==middle) {
							mid = 0;
							swappedToVertical = true;
						}
					}
				}
				if(times>=1 && !centerUsed) {
					res[middle][middle] = i;
					centerUsed = true;
				} else if(times>=1) {
					System.out.println("NO");
					return;
				}
			}
		}
		System.out.println("YES");
		for(int i = 0; i<n; i++) {
			for(int j = 0; j<n-1; j++) {
				System.out.print(res[i][j] + " ");
			}
			System.out.println(res[i][n-1]);
		}
	}
}

