public class c {

	static class Solver {

		int N, mat[][], vals[], f[];
		ArrayDeque<int[][]> fours, twos, ones;

		void solve(FastScanner s, PrintWriter out) {
			N = s.nextInt(); vals = s.nextIntArray(N * N);
			f = new int[1001]; for(int x : vals) f[x]++;
			PriorityQueue<Integer> q = new PriorityQueue<>((a, b) -> f[b] - f[a]);
			IntStream.range(1, 1001).forEach(x -> q.add(x));

			fours = new ArrayDeque<>(); twos = new ArrayDeque<>(); ones = new ArrayDeque<>();
			for(int i = 0, ii = N - 1; i < N / 2; i++, ii--)
				for(int j = 0, jj = N - 1; j < N / 2; j++, jj--)
					fours.add(new int[][] { { i, j }, { ii, j }, { i, jj }, { ii, jj } });

			if(N % 2 == 1) {
				for(int i = 0, ii = N - 1, j = N / 2; i < N / 2; i++, ii--) {
					twos.add(new int[][] { { i, j }, { ii, j } });
					twos.add(new int[][] { { j, i }, { j, ii } });
				}
				ones.add(new int[][] { { N / 2, N / 2 } });
			}

			int cur, cf; mat = new int[N][N];
			assign: while(!q.isEmpty()) {
				if((cf = f[cur = q.poll()]) == 0) break;
				put4: if(cf >= 4) {
					if(fours.isEmpty()) break put4;
					for(int[] a : fours.poll())
						mat[a[0]][a[1]] = cur;
					f[cur] -= 4; q.add(cur); continue assign;
				}

				put2: if(cf >= 2) {
					if(twos.isEmpty()) break put2;
					for(int[] a : twos.poll())
						mat[a[0]][a[1]] = cur;
					f[cur] -= 2; q.add(cur); continue assign;
				}

				put1: if(cf >= 1) {
					if(ones.isEmpty()) break put1;
					for(int[] a : ones.poll())
						mat[a[0]][a[1]] = cur;
					f[cur] -= 1; q.add(cur); continue assign;
				}

				out.println("NO"); return;
			}

			out.println("YES");
			for(int[] row : mat) {
				for(int v : row) out.print(v + " ");
				out.println();
			}

		}

		String debug(Object ... o) { return Arrays.deepToString(o); }

	}

	public static void main(String[] args) {
		FastScanner s = new FastScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		new Solver().solve(s, out);
		out.close();
		s.close();
	}

