    static class CPalindromnayaMatrica {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] a = in.readIntArray(n * n);
            int[] cnt = new int[1001];
            for (int x : a) {
                cnt[x]++;
            }

            boolean[][] used = new boolean[n][n];
            List<Set<IntIntPair>> groups = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (!used[i][j]) {
                        Set<IntIntPair> group = new HashSet<>();
                        int i1 = n - i - 1;
                        int j1 = n - j - 1;
                        group.add(IntIntPair.makePair(i, j));
                        group.add(IntIntPair.makePair(i, j1));
                        group.add(IntIntPair.makePair(i1, j));
                        group.add(IntIntPair.makePair(i1, j1));
                        groups.add(group);
                        used[i][j] = used[i][j1] = used[i1][j] = used[i1][j1] = true;
                    }
                }
            }
            groups.sort(Comparator.comparingInt(g -> -g.size()));
            int[][] ans = new int[n][n];
            for (Set<IntIntPair> group : groups) {
                boolean ok = false;
                for (int i = 0; i < cnt.length; i++) {
                    if (cnt[i] >= group.size()) {
                        for (IntIntPair p : group) {
                            ans[p.first][p.second] = i;
                            cnt[i]--;
                        }
                        ok = true;
                        break;
                    }
                }
                if (!ok) {
                    out.print("NO");
                    return;
                }
            }
            out.printLine("YES");
            for (int[] row : ans) {
                out.printLine(row);
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int[] readIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = readInt();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
