public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        ReaderFastIO in = new ReaderFastIO(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CPalindromicMatrix solver = new CPalindromicMatrix();
        solver.solve(1, in, out);
        out.close();
    }

    static class CPalindromicMatrix {
        private static int MAX = 1000;
        private static PrintWriter out;

        public void solve(int testNumber, ReaderFastIO in, PrintWriter out) {

            this.out = out;
            int n = in.nextInt();
            int[] a = in.readArrayInt(n * n);
            int[] d = new int[MAX + 1];
            int[][] m = new int[n][n];

            for (int i = 0; i < a.length; i++) {
                d[a[i]]++;
            }

            int ra = 0;
            int rb = n - 1;
            int ca = 0;
            int cb = n - 1;
            int index = 1;

            while (ra < rb) {

                while (index <= MAX && d[index] < 4) index++;

                if (index > MAX) break;

                m[ra][ca] = index;
                m[ra][cb] = index;
                m[rb][ca] = index;
                m[rb][cb] = index;

                d[index] -= 4;

                ca++;
                cb--;

                if (ca >= cb) {
                    ca = 0;
                    cb = n - 1;
                    ra++;
                    rb--;
                }
            }

            if (n % 2 == 0) {

                if (isOK(m)) {
                    out.println("YES");
                    print(m);
                } else {
                    out.println("NO");
                }

                return;
            } else {

                index = 0;
                ca = 0;
                cb = n - 1;
                while (ca < cb) {
                    while (index <= MAX && d[index] < 2) index++;
                    if (index > MAX) break;

                    m[(n - 1) / 2][ca] = index;
                    m[(n - 1) / 2][cb] = index;

                    d[index] -= 2;
                    ca++;
                    cb--;
                }

                index = 0;
                ra = 0;
                rb = n - 1;
                while (ra < rb) {
                    while (index <= MAX && d[index] < 2) index++;
                    if (index > MAX) break;

                    m[ra][(n - 1) / 2] = index;
                    m[rb][(n - 1) / 2] = index;

                    d[index] -= 2;
                    ra++;
                    rb--;
                }

                index = 0;
                while (index <= MAX && d[index] < 1) index++;
                if (index <= MAX) {
                    m[(n - 1) / 2][(n - 1) / 2] = index;
                    d[index]--;
                }

                if (isOK(m)) {
                    out.println("YES");
                    print(m);
                } else {
                    out.println("NO");
                }

                return;
            }
        }

        public static void print(int[][] m) {
            for (int i = 0; i < m.length; i++) {
                for (int j = 0; j < m[i].length; j++) {
                    out.print(m[i][j] + " ");
                }
                out.println();
            }
        }

        public static boolean isOK(int[][] m) {
            for (int i = 0; i < m.length; i++) {
                for (int j = 0; j < m[i].length; j++) {
                    if (m[i][j] == 0) return false;
                }
            }

            return true;
        }

    }

    static class ReaderFastIO {
