import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;
import java.util.Stack;

public class ProblemC {

	static HashMap<Integer, Integer> times = new HashMap<>();
	static int onces = 1;
	static double twoces = 0;
	static double fources = 0;
	static int[] four;
	static Integer fourIndex = 0;
	static Integer twoIndex = 0;
	static int[] two;
	static int one;
	static String[] lvls;
	static boolean mid;

	public static void main(String[] args) {

		Scanner in = new Scanner(System.in);
	    int n = in.nextInt();
	    int k = Math.multiplyExact(n, n);
	    int number;

	    if (n == 1) {
	    	System.out.println("YES");
	    	System.out.println(in.nextInt());
	    	in.close();
	    	return;
	    }

	    for (int i = k; i > 0; i--) {
	    	number = in.nextInt();
	    	if (times.containsKey(number))
	    		times.put(number, times.get(number) + 1);
	    	else
	    		times.put(number, 1);
	    }

	    in.close();

	    fources = Math.pow(n/2, 2);
	    four = new int[(int) fources];
	    lvls = new String[n/2];
	    mid = n % 2 == 1;
	    if (mid) {
	    	twoces = n - 1;
	    	two = new int[(int) twoces];
	    }


	    times.entrySet().stream().sorted(Map.Entry.comparingByValue()).allMatch((entry) -> {
	    	int left = entry.getValue();
	    	int times = Math.floorDiv(left, 4);



	    	fources -= times;
	    	left %= 4;

    		if (fources < 0) {
    			int subs = (int) (fources * -1 * 2);
    			twoces -= subs;
    			times += fources;
    			move(entry.getKey(), four, fourIndex, times, false);
    			move(entry.getKey(), two, twoIndex, subs, true);
    			fources = 0;
    		} else
    			move(entry.getKey(), four, fourIndex, times, false);

	    	if (left >= 2) {
	    		twoces--;
	    		left -= 2;
	    		if (twoces < 0) {
	    			System.out.println("NO");

	    			return false;
	    		}
    			move(entry.getKey(), two, twoIndex, 1, true);
	    	}

	    	if (left == 1) {
	    		onces--;
	    		if (onces < 0) {
	    			System.out.println("NO");

	    			return false;
	    		}
	    		one = entry.getKey();
	    	}
	    	return true;

	    });

	    if (!(onces < 0 || twoces < 0 || fources < 0)) {
	    	System.out.println("YES");

		    fourIndex = 0;
		    twoIndex = 0;

		    printMatrix(0);

		    if (mid) {
		    	StringBuilder sb = new StringBuilder();
				Stack<Integer> numbers = new Stack<>();
				for (int i = lvls.length; i > 0; i--) {
					sb.append(two[twoIndex] + " ");
					numbers.push(two[twoIndex]);
					twoIndex++;
				}
				sb.append(one + " ");
				for (int i = lvls.length; i > 0; i--) 
					sb.append(numbers.pop() + " ");
				System.out.println(sb.toString());
		    }

		    for (int i = lvls.length - 1; i >= 0; i--) {
		    	System.out.println(lvls[i]);
		    }
	    }
	}

	private static void move(int key, int[] arr, int index, int times, boolean dos) {
		for (int i = times; i>0; i--) {
			arr[index] = key;
			if (dos)
				index = ++twoIndex;
			else
				index = ++fourIndex;
		}
	}

	private static void printMatrix(int lvl) {
		if (lvl == lvls.length)
			return;
		StringBuilder sb = new StringBuilder();
		Stack<Integer> numbers = new Stack<>();
		for (int i = lvls.length; i > 0; i--) {
			sb.append(four[fourIndex] + " ");
			numbers.push(four[fourIndex]);
			fourIndex++;
		}
		if (mid) {
			sb.append(two[twoIndex] + " ");
			twoIndex++;
		}

		for (int i = lvls.length; i > 0; i--) 
			sb.append(numbers.pop() + " ");

		lvls[lvl] = sb.toString();
		System.out.println(lvls[lvl]);
		printMatrix(lvl + 1);
	}
}

