import java.util.*;
import java.io.*;

public class PalindromicMatrix {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int N = scanner.nextInt();
        int[] arr = new int[N*N];
        int[] cnts = new int[1001];
        for(int i = 0; i < N*N; i++) {
            arr[i] = scanner.nextInt();
            cnts[arr[i]]++;
        }
        PriorityQueue<Pair> queue = new PriorityQueue<>();
        for(int i = 0; i < 1001; i++) {
            if (cnts[i] > 0) queue.offer(new Pair(i, cnts[i]));
        }
        int[][] ans = new int[N][N];

        int curRow = 0;
        int curCol = 0;
        while(curRow < N/2) {
            while(curCol < N/2) {
                if (queue.isEmpty() || queue.peek().cnt < 4) {
                    out.println("NO");
                    out.flush();
                    return;
                }
                Pair next = queue.poll();
                ans[curRow][curCol] = next.val;
                ans[N-1-curRow][curCol] = next.val;
                ans[N-1-curRow][N-1-curCol] = next.val;
                ans[curRow][N-1-curCol] = next.val;
                if (next.cnt > 4) queue.offer(new Pair(next.val, next.cnt-4));
                curCol++;
            }
            curRow++;
            curCol = 0;
        }

        if (N%2==1) {

            curCol = 0;
            while(curCol < N/2) {
                if (queue.isEmpty() || queue.peek().cnt < 2) {
                    out.println("NO");
                    out.flush();
                    return;
                }
                Pair next = queue.poll();
                ans[N/2][curCol] = next.val;
                ans[N/2][N-1-curCol] = next.val;
                if (next.cnt > 2) queue.offer(new Pair(next.val, next.cnt-2));
                curCol++;
            }

            curRow = 0;
            while(curRow < N/2){
                if (queue.isEmpty() || queue.peek().cnt < 2) {
                    out.println("NO");
                    out.flush();
                    return;
                }
                Pair next = queue.poll();
                ans[curRow][N/2] = next.val;
                ans[N-1-curRow][N/2] = next.val;
                if (next.cnt > 2) queue.offer(new Pair(next.val, next.cnt-2));
                curRow++;
            }

            if (queue.isEmpty()) {
                out.println("NO");
                out.flush();
                return;
            }
            ans[N/2][N/2] = queue.poll().val;
        }
        out.println("YES");
        for(int i = 0; i < N; i++) {
            for(int j = 0; j < N; j++) {
                out.print(ans[i][j] + " ");
            }
            out.println();
        }
        out.flush();
    }

    public static class Pair implements Comparable<Pair> {
        int val, cnt;
        public Pair(int vv, int cc) {
            val = vv;
            cnt = cc;
        }
        public int compareTo(Pair o) {
            return Integer.compare(-this.cnt, -o.cnt);
        }
    }

    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(Reader in) {
            br = new BufferedReader(in);
