public class B {

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		StringTokenizer st = new StringTokenizer(br.readLine());
		int h = Integer.parseInt(st.nextToken());
		int w = Integer.parseInt(st.nextToken());
		char[][] map = new char[h][w];
		int x = -1, xa = 0, xb = 0;
		for(int i = 0; i < h; i++){
			map[i] = br.readLine().toCharArray();
		}
		for(int i = 0; i < h; i++){
			Pair p = solve(map[i]);
			if(p.a == -2){
				System.out.println("NO"); return;
			}
			else if(p.a != p.b){
				if(x < 0){
					x = i; xa = p.a; xb = p.b;
				}
				else{
					System.out.println("NO"); return;
				}
			}
		}
		int y = -1, ya = -1, yb = -1;
		for(int i = 0; i < w; i++){
			char[] s = new char[h];
			for(int j = 0; j < h; j++) s[j] = map[j][i];
			Pair p = solve(s);
			if(p.a == -2){
				System.out.println("NO"); return;
			}
			else if(p.a != p.b){
				if(y < 0){
					y = i; ya = p.a; yb = p.b;
				}
				else{
					System.out.println("NO"); return;
				}
			}
		}
		if(xa < y && y < xb && ya < x && x < yb){
			for(int i = xa; i <= xb; i++){
				map[x][i] = '.';
			}
			for(int i = ya; i <= yb; i++){
				map[i][y] = '.';
			}
			if(check(map)){
				System.out.println("YES");
			}
			else{
				System.out.println("NO");
			}
		}
		else{
			System.out.println("NO");
		}
	}
	static boolean check(char[][] map){
		int h = map.length, w = map[0].length;
		for(int i = 0; i < h; i++){
			for(int j = 0; j < w; j++){
				if(map[i][j] == '*') return false;
			}
		}
		return true;
	}
	static Pair solve(char[] s){
		int a = -1, b = -1, sec = 0;
		for(int i = 0; i < s.length; i++){
			if(sec == 0 && s[i] == '.') continue;
			if(sec == 0 && s[i] == '*'){
				a = i; b = i; sec++; continue;
			}
			if(sec == 1 && s[i] == '.'){
				sec++; continue;
			}
			if(sec == 1 && s[i] == '*') {
				b++; continue;
			}
			if(sec == 2 && s[i] == '.') continue;
			if(sec == 2 && s[i] == '*'){
				return new Pair(-2, -1);
			}
		}
		return new Pair(a, b);
	}

	static class Pair{
		int a, b;
		public Pair(int a, int b){
			this.a = a; this.b = b;
		}
	}
}

