    static class InputReader {

        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar, snumChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int snext() {
            if (snumChars == -1)
                throw new InputMismatchException();
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int a[] = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        public long[] nextLongArray(int n) {
            long a[] = new long[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextLong();
            }
            return a;
        }

        public String readString() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = snext();
            while (isSpaceChar(c))
                c = snext();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }
}

import java.util.Scanner;

public class Main {

	private static int h;
	private static int w;
	private static int cnt;
	private static char[][] a;

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		h = in.nextInt();
		w = in.nextInt();
		a = new char[h][];
		for (int i = 0; i < h; ++i) {
			a[i] = in.next().toCharArray();
			count(i);
		}
		for (int i = 0; i < h; ++i) {
			for (int j = 0; j < w; ++j) {
				if (validPlusShape(i, j)) {
					System.out.println("YES");
					return;
				}
			}
		}
		System.out.println("NO");
	}

	private static boolean validPlusShape(int i, int j) {
		if (i == h || j == w || a[i][j] != '*') return false;
		return up(i - 1, j) + down(i + 1, j) + left(j - 1, i) + right(j + 1, i) + 1 == cnt;
	}

	private static void count(int i) {
		for (int j = 0; j < w; ++j) cnt += (a[i][j] == '*' ? 1 : 0);
	}

	private static int up(int r, int c) {
		return check(r, 0, -1, c, true);
	}

	private static int down(int r, int c) {
		return check(r, h, 1, c, true);
	}

	private static int left(int r, int c) {
		return check(r, 0, -1, c, false);
	}

	private static int right(int r, int c) {
		return check(r, w, 1, c, false);
	}

	private static int check(int r, int nd, int dir, int c, boolean row) {
		int k = 0;
		for (int i = r; ((dir > 0) == (i < nd)); i += dir) {
			if (a[row ? i : c][row ? c : i] != '*') break;
			if (a[row ? i : c][row ? c : i] == '*') ++k;
		}
		return k == 0 ? -999999 : k;
	}
}

