    static class BPlusFromPicture {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int M = in.nextInt();
            int[][] arr = new int[N][M];
            for (int i = 0; i < N; i++) {
                String s = in.next();
                for (int j = 0; j < M; j++) {
                    arr[i][j] = (s.charAt(j) == '*') ? 1 : 0;
                }
            }

            int foundx = -1;
            int foundy = -1;
            for (int i = 1; i < N - 1; i++) {
                for (int j = 1; j < M - 1; j++) {
                    if (arr[i][j] == 1 && arr[i - 1][j] == 1 && arr[i + 1][j] == 1 && arr[i][j - 1] == 1 && arr[i][j + 1] == 1) {
                        foundx = i;
                        foundy = j;
                        break;
                    }
                }
                if (foundx >= 0) break;
            }

            if (foundx < 0) {
                out.println("NO");
                return;
            }

            HashSet<Point> allPoints = new HashSet<>();
            int x = foundx;
            int y = foundy;
            while (x >= 0 && arr[x][y] == 1) {
                allPoints.add(new Point(x, y));
                x--;
            }
            x = foundx;
            while (x < arr.length && arr[x][y] == 1) {
                allPoints.add(new Point(x, y));
                x++;
            }
            x = foundx;

            while (y >= 0 && arr[x][y] == 1) {
                allPoints.add(new Point(x, y));
                y--;
            }
            y = foundy;
            while (y < arr[0].length && arr[x][y] == 1) {
                allPoints.add(new Point(x, y));
                y++;
            }


            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    if (arr[i][j] == 1 && !allPoints.contains(new Point(i, j))) {
                        out.println("NO");
                        return;
                    }
                }
            }

            out.println("YES");

        }

    }

