import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Scanner;

public class Main {

    private static int[] dx = {-1, 0, 1, 0};
    private static int[] dy = {0, 1, 0, -1};
    private static char CLOSE = '*';
    private static String YES = "YES";
    private static String NO = "NO";

    public static void main(String[] args) {
        Scanner I = new Scanner(new BufferedReader(new InputStreamReader(System.in)));

        int R = I.nextInt();
        int C = I.nextInt();
        char[][] grid = new char[R][C];
        for (int i = 0; i < R; i++) {
            String s = I.next();
            grid[i] = s.toCharArray();
        }

        String s = solve(grid, R, C);
        System.out.println(s);

    }

    private static String solve(char[][] grid, int R, int C) {
        if (R <= 2 || C <= 2) {
            return NO;
        }
        boolean[][] visited = new boolean[R][C];
        int r = -1;
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (r != 1 && grid[i][j] == CLOSE && isPlus(i, j, grid, R, C)) {
                    visit(i, j, grid, visited, R, C);
                    r = 1;
                }
            }
        }
        if (r == -1) {
            return NO;
        }
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (grid[i][j] == CLOSE && visited[i][j] == false) {
                    return NO;
                }
            }
        }
        return YES;
    }


    private static void visit(int x, int y, char[][] grid, boolean[][] visited, int R, int C) {
        visited[x][y] = true;

        for (int i = 0; i < 4; i++) {
            int xi = x;
            int yi = y;
            while (true) {
                xi += dx[i];
                yi += dy[i];
                if (isInGrid(xi, yi, R, C) && grid[xi][yi] == CLOSE) {
                    visited[xi][yi] = true;
                } else {
                    break;
                }
            }

        }
    }


    private static boolean isPlus(int x, int y, char[][] grid, int R, int C) {

        for (int i = 0; i < 4; i++) {
            int xi = x + dx[i];
            int yi = y + dy[i];
            if (isInGrid(xi, yi, R, C) && grid[xi][yi] == CLOSE) {
                continue;
            } else {
                return false;
            }
        }
        return true;
    }



    private static boolean isInGrid(int x, int y, int R, int C) {
        if (x < 0 || y < 0) {
            return false;
        }
        if (x >= R || y >= C) {
            return false;
        }

        return true;
    }

    private static void error(String msg) {

        throw new RuntimeException(msg);
    }


}

import java.util.Scanner;

public class star {














	static void dfs(int graph[][],int x,int y,boolean visited[][],int direction) {
		if(x<0 || y<0 || x>=graph.length || y>=graph[0].length || graph[x][y]==0) {
			return;
		}
		visited[x][y]=true;
		if(x>=1 && !visited[x-1][y] && direction==0)
			dfs(graph,x-1,y,visited,direction);
		if(x<graph.length-1 && !visited[x+1][y] && direction==2)
			dfs(graph,x+1,y,visited,direction);
		if(y>=1 && !visited[x][y-1] && direction==3)
			dfs(graph,x,y-1,visited,direction);
		if(y<graph[0].length-1 && !visited[x][y+1] && direction==1)
			dfs(graph,x,y+1,visited,direction);
	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int h = sc.nextInt();
		int w = sc.nextInt();
		boolean isEmpty=true;
		sc.nextLine();
		int graph[][] = new int[h][w];
		for(int i=0;i<h;i++) {
			String line = sc.nextLine();
			for(int j=0;j<w;j++) {
				graph[i][j]=line.charAt(j)=='.'?0:1;
				if(graph[i][j]==1) {
					isEmpty=false;
				}

			}

		}
		if(isEmpty) {
			System.out.println("NO");
			sc.close();
			return;
		}
		boolean visited[][] = new boolean[h][w];
		boolean found=false;
		for(int i=1;i<h-1 && !found;i++) {
			for(int j=1;j<w-1 && !found;j++) {
				if(graph[i-1][j]==1 && graph[i+1][j]==1 && graph[i][j-1]==1 && graph[i][j+1]==1 && graph[i][j]==1) {
					dfs(graph,i,j,visited,0);
					dfs(graph,i,j,visited,1);
					dfs(graph,i,j,visited,2);
					dfs(graph,i,j,visited,3);
					found=true;
				}
			}
		}
		for(int i=0;i<h;i++) {
			for(int j=0;j<w;j++) {

				if(!visited[i][j] && graph[i][j]==1) {
					System.out.println("NO");
					sc.close();
					return;
				}
			}

		}
		System.out.println("YES");
		sc.close();
	}

}

