import java.io.PrintWriter;
import java.util.Scanner;


public class Solution {

	private final int height;
	private final int width;
	private final char[][] picture;

	public Solution(Scanner scanner) {
		this.height = scanner.nextInt();
		this.width = scanner.nextInt();

		this.picture = new char[this.height][];
		for (int i = 0; i < this.height; i++) {
			this.picture[i] = scanner.next().toCharArray();
		}
	}

	private boolean[][] getPlusShapeAt(int i, int j) {
		if (this.picture[i][j] != '*'
						|| this.picture[i][j + 1] != '*'
						|| this.picture[i][j - 1] != '*'
						|| this.picture[i - 1][j] != '*'
						|| this.picture[i + 1][j] != '*') {
			return null;
		}

		boolean[][] shape = new boolean[this.height][this.width];
		for (int k = j; k < this.width; k++) {
			if (this.picture[i][k] != '*') {
				break;
			}
			shape[i][k] = true;
		}
		for (int k = j; k >= 0; k--) {
			if (this.picture[i][k] != '*') {
				break;
			}
			shape[i][k] = true;
		}
		for (int k = i; k < this.height; k++) {
			if (this.picture[k][j] != '*') {
				break;
			}
			shape[k][j] = true;
		}
		for (int k = i; k >= 0; k--) {
			if (this.picture[k][j] != '*') {
				break;
			}
			shape[k][j] = true;
		}

		return shape;
	}

	private boolean[][] getFirstPlusShape() {
		for (int i = 1; i < this.height - 1; i++) {
			for (int j = 1; j < this.width - 1; j++) {
				boolean[][] plusPic = this.getPlusShapeAt(i, j);
				if (plusPic != null) {
					return plusPic;
				}
			}
		}
		return null;
	}

	public String solve() {
		boolean[][] plusShape = this.getFirstPlusShape();
		if (plusShape == null) {
			return "NO";
		}

		for (int i = 0; i < this.height; i++) {
			for (int j = 0; j < this.width; j++) {
				if (plusShape[i][j] || this.picture[i][j] == '.') {
					continue;
				}
				return "NO";
			}
		}

		return "YES";
	}

	public static void main(String args[]) {
		try (Scanner scanner = new Scanner(System.in);
				 PrintWriter writer = new PrintWriter(System.out)) {
			Solution solution = new Solution(scanner);
			String answer = solution.solve();
			writer.println(answer);
		}
		System.exit(0);
	}

}

