class Picture {
    static final int[] MODX = {0, -1, 0, 1, 0};
    static final int[] MODY = {0, 0, 1, 0, -1};

    private char[][] mat;

    public Picture(int rows, int cols) {
        mat = new char[rows][cols];
    }

    public void setRow(int index, String row) {
        mat[index] = row.toCharArray();
    }

    public int countStars() {
        int stars = 0;
        for (int i = 0; i < mat.length; i += 1) {
            for (int j = 0; j < mat[i].length; j += 1) {
                stars += (isStar(i, j) ? 1 : 0);
            }
        }
        return stars;
    }

    public boolean isPlus(int x, int y) {
        for (int i = 0; i < MODX.length; i += 1) {
            int cx = x + MODX[i];
            int cy = y + MODY[i];
            if (!isStar(cx, cy)) {
                return false;
            }
        }
        return true;
    }

    public void removePlus(int x, int y) {
        for (int i = 0; i < MODX.length; i += 1) {
            int cx = x + MODX[i];
            int cy = y + MODY[i];

            while (isStar(cx, cy)) {
                mat[cx][cy] = '.';
                cx += MODX[i];
                cy += MODY[i];
            }
        }
    }

    private boolean isStar(int x, int y) {
        return inBounds(x, y) && mat[x][y] == '*';
    }

    private boolean inBounds(int x, int y) {
        return (0 <= x && x < mat.length && 0 <= y && y < mat[x].length);
    }
}

