	void solve() 
	{
		int n = ni(), m = ni();
		char[][] s = nm(n, m);
		for(int i = 1; i < n-1; i++) {
			for(int j = 1; j < m-1; j++) {
				if(s[i][j] == '*') {
					if(ok(s, i, j)) {
						fill(s, i, j);
						if(check(s)) {
							out.println("YES");
						}
						else {
							out.println("NO");
						}
						return;
					}
				}
			}
		}
		out.println("NO");
	}

	public static boolean ok(char[][] s, int x, int y) {
		if(s[x-1][y] == '.') return false;
		if(s[x][y-1] == '.') return false;
		if(s[x][y+1] == '.') return false;
		if(s[x+1][y] == '.') return false;
		return true;
	}

	public static void fill(char[][] s, int x, int y) {
		for(int i = x; i >= 0; i--) {
			if(s[i][y] == '#') continue;
			if(s[i][y] == '*') s[i][y] = '#';
			else break;
		}

		for(int i = x; i < s.length; i++) {
			if(s[i][y] == '#') continue;
			if(s[i][y] == '*') s[i][y] = '#';
			else break;
		}

		for(int i = y; i >= 0; i--) {
			if(s[x][i] == '#') continue;
			if(s[x][i] == '*') s[x][i] = '#';
			else break;
		}

		for(int i = y; i < s[x].length; i++) {
			if(s[x][i] == '#') continue;
			if(s[x][i] == '*') s[x][i] = '#';
			else break;
		}
	}

	public static boolean check(char[][] s) {
		for(int i = 0; i < s.length; i++) {
			for(int j = 0; j < s[i].length; j++) {
				if(s[i][j] == '.' || s[i][j] == '#') continue;
				else return false;
			}
		}
		return true;
	}

	void run() throws Exception {
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		long s = System.currentTimeMillis();
		solve();
		out.flush();
		if (!INPUT.isEmpty())
			tr(System.currentTimeMillis() - s + "ms");
	}

	public static void main(String[] args) throws Exception {
		new Main().run();
	}

	private byte[] inbuf = new byte[1024];
	public int lenbuf = 0, ptrbuf = 0;

	private int readByte() {
		if (lenbuf == -1)
			throw new InputMismatchException();
		if (ptrbuf >= lenbuf) {
			ptrbuf = 0;
			try {
				lenbuf = is.read(inbuf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (lenbuf <= 0)
				return -1;
		}
		return inbuf[ptrbuf++];
	}

	private boolean isSpaceChar(int c) {
		return !(c >= 33 && c <= 126);
	}

	private int skip() {
		int b;
		while ((b = readByte()) != -1 && isSpaceChar(b))
			;
		return b;
	}

	private double nd() {
		return Double.parseDouble(ns());
	}

	private char nc() {
		return (char) skip();
	}

	private String ns() {
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while (!(isSpaceChar(b))) { 
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private char[] ns(int n) {
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while (p < n && !(isSpaceChar(b))) {
			buf[p++] = (char) b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private char[][] nm(int n, int m) {
		char[][] map = new char[n][];
		for (int i = 0; i < n; i++)
			map[i] = ns(m);
		return map;
	}

	private int[] na(int n) {
		int[] a = new int[n];
		for (int i = 0; i < n; i++)
			a[i] = ni();
		return a;
	}

	private int ni() {
		int num = 0, b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private long nl() {
		long num = 0;
		int b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) {
		System.out.println(Arrays.deepToString(o));
	}
}

