import java.util.*;
import java.io.*;

public class BB {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int H = scanner.nextInt();
        int W = scanner.nextInt();
        char[][] pic = new char[H][W];
        for(int i =0; i < H; i++) {
            char[] line = scanner.next().toCharArray();
            for(int j = 0; j < W; j++) {
                pic[i][j] = line[j];
            }
        }
        int[] rowCnt = new int[H];
        int[] colCnt = new int[W];
        for(int i = 0; i < H; i++) {
            for(int j = 0; j < W; j++) {
                if (pic[i][j] == '*') {
                    rowCnt[i]++;
                    colCnt[j]++;
                }
            }
        }
        int tot = 0;
        for(int i = 0; i < H; i++) tot += rowCnt[i];
        if (tot < 4) bad();
        boolean[][] vis = new boolean[H][W];
        boolean done = false;
        for(int i = 0; i < H && !done; i++) {
            for(int j = 0; j < W && !done; j++) {
                if (pic[i][j] == '*') {
                    vis[i][j] = true;
                    int[] dirsR = new int[] {1, 0, -1, 0};
                    int[] dirsC = new int[] {0, 1, 0, -1};
                    ArrayDeque<Pair> queue = new ArrayDeque<>();
                    queue.offer(new Pair(i, j));
                    int total = 0;
                    done = true;
                    while(!queue.isEmpty()) {
                        total++;
                        Pair cur = queue.poll();
                        for(int k = 0; k < dirsC.length; k++) {
                            int nextR = cur.r + dirsR[k];
                            int nextC = cur.c + dirsC[k];
                            if (nextR < 0 || nextC < 0 || nextR >= H || nextC >= W || vis[nextR][nextC] || pic[nextR][nextC] != '*') continue;
                            vis[nextR][nextC] = true;
                            queue.offer(new Pair(nextR, nextC));
                        }
                    }
                    if (total != tot) bad();
                }
            }
        }
        if (H == 1 || W == 1) bad();
        boolean inc = true;
        for(int i = 1; i < H; i++) {
            if (inc && rowCnt[i] < rowCnt[i-1]) bad();
            else if (rowCnt[i-1] > 1 && rowCnt[i] != 1) bad();
            else if (inc && rowCnt[i] > 1) inc = false;
            else if (!inc && rowCnt[i] > 1) bad();
            else if(!inc && rowCnt[i] > rowCnt[i-1]) bad();
        }
        if (inc) bad();
        inc = true;
        for(int i = 1; i < W; i++) {
            if (inc && colCnt[i] < colCnt[i-1]) bad();
            else if (colCnt[i-1] > 1 && colCnt[i] != 1) bad();
            else if (inc && colCnt[i] > 1) inc = false;
            else if (!inc && colCnt[i] > 1) bad();
            else if(!inc && colCnt[i] > colCnt[i-1]) bad();
        }
        if(inc) bad();
        out.println("YES");
        out.flush();
    }

    public static class Pair {
        int r, c;
        public Pair(int rr, int cc) {
            r = rr; c = cc;
        }
    }

    public static void bad() {
        System.out.println("NO");
        System.exit(0);
    }

    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String readNextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        int[] readIntArray(int n) {
            int[] a = new int[n];
            for (int idx = 0; idx < n; idx++) {
                a[idx] = nextInt();
            }
            return a;
        }
    }
}

