            IntStream.range(0, n).boxed().map(integer -> 0).forEach(lowestIndex::add);
            IntStream.range(0, n).boxed().map(integer -> 0).forEach(indexes::add);
        }

        List<Vertex> getVertices(int u) {
            return this.vertices.get(u).adjacentVertices;
        }

        void addEdge(int u, int v) {
            Vertex vertexU = vertices.get(u);
            Vertex vertexV = vertices.get(v);
            vertexU.addEdge(vertexV);
            vertexV.addEdge(vertexU);
        }

        boolean isNotVisited(int u) {
            return indexes.get(u).equals(0);
        }

        int getLowestIndex(int u) {
            return lowestIndex.get(u);
        }

        int getIndex(int u) {
            return indexes.get(u);
        }

        void setIndex(int u, int value) {
            indexes.set(u, value);
        }

        void setLowestIndex(int u, int value) {
            lowestIndex.set(u, value);
        }

        void increaseBridge(int u, int v) {
            this.bridges.add(new MyObject<>(u, v));
        }

        void increaseCuttingVertex(int u) {
            this.cuttingVertices.add(u);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int w = scanner.nextInt();
        int h = scanner.nextInt();
        char[][] input = new char[w][h];
        for (int i = 0; i < w; i++) {
            input[i] = scanner.next().toCharArray();
        }

        if (w < 3 || h < 3) {
            System.out.println("NO");
            return;
        }

        boolean[][] isVisited = new boolean[w][h];
        int numberOfArea = 0;
        for (int i = 0; i < w; i++) {
            for (int j = 0; j < h; j++) {
                if (!isVisited[i][j] && input[i][j] == '*') {
                    numberOfArea++;

                    if (numberOfArea > 1) {
                        System.out.println("NO");
                        return;
                    }

                    dfs(i, j, input, isVisited);
                }
            }
        }

        if (numberOfArea == 0) {
            System.out.println("NO");
            return;
        }

        int center_x = -1;
        int center_y = -1;
        int count = 0;
        for (int i = 1; i < w - 1; i++) {
            for (int j = 1; j < h - 1; j++) {
                if (input[i][j] == '*' && input[i - 1][j] == '*' && input[i][j - 1] == '*' && input[i][j + 1] == '*' && input[i + 1][j] == '*') {
                    center_x = i;
                    center_y = j;
                    count++;
                }
            }
        }

        if (center_x == -1 || count > 1) {
            System.out.println("NO");
            return;
        }

        for (int i = 0; i < w; i++) {
            for (int j = 0; j < h; j++) {
                if (input[i][j] == '*' && center_x != i && center_y != j) {
                    System.out.println("NO");
                    return;
                }
            }
        }

        System.out.println("YES");
    }

    private static final int H = 4;
    private static final int[] H_I = {-1, 0, 0, 1};
    private static final int[] H_J = {0, -1, 1, 0};

    private static void dfs(int i, int j, char[][] input, boolean[][] isVisited) {
        isVisited[i][j] = true;

        for (int hh = 0; hh < H; hh++) {
            int ii = i + H_I[hh];
            int jj = j + H_J[hh];

            if (inside(input, ii, jj) && !isVisited[ii][jj] && input[ii][jj] == '*')
                dfs(ii, jj, input, isVisited);
        }
    }

    private static boolean inside(char[][] size, int ii, int jj) {
        return !(ii < 0 || ii >= size.length || jj < 0 || jj >= size[0].length);
    }

}

