		{
		    for(j=1;j<m-1;j++)
		    {   int check=0;
		        if(a[i][j]==1 && a[i-1][j]==1 &&a[i][j+1]==1 &&a[i][j-1]==1 &&a[i+1][j]==1)
		        {   

		            int temp1=i,temp2=j;
		            while(temp1<n && temp1>=0 && temp2<m && temp2>=0)
		            {   
