		                    check++;
		                else
		                    break;
		            }
		            temp1=i;temp2=j;

		            while( temp1<n && temp1>=0 && temp2<m && temp2>=0)
		            {   
		                if(a[temp1--][temp2]==1)
		                    check++;
		                else
		                    break;
		            }
		            temp1=i;temp2=j;
		            while( temp1<n-1 && temp1>=0 && temp2<m && temp2>=0)
		            {   
		                if(a[temp1][temp2--]==1)
		                    check++;
		                else
		                    break;
		            }
		            check-=3;
		            if(count==check)
		                flag=1;
		            else
		                flag=-1;
		               break; 
		        }
		    }
		    if(flag==1 || flag==-1)
