    static class Pair {
        Integer fst;
        Integer snd;

        Pair(int a, int b) {
            fst = a;
            snd = b;
        }

        @Override
        public int hashCode() {
            return fst.hashCode() ^ snd.hashCode();
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Pair)) return false;
            Pair pairo = (Pair) o;
            return this.fst.equals(pairo.fst) &&
                    this.snd.equals(pairo.snd);
        }
    }

