        int hCenter = 0;
        int jCenter = 0;
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            matrix[i] = line;
        }
        HashSet<Pair> stars = new HashSet<>();
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (matrix[i].charAt(j) == '*' &&
                        matrix[i - 1].charAt(j) == '*' &&
                        matrix[i + 1].charAt(j) == '*' &&
                        matrix[i].charAt(j - 1) == '*' &&
                        matrix[i].charAt(j + 1) == '*') {
                    jCenter = j;
                    hCenter = i;
                }
            }
        }
        boolean found = false;
        boolean stopped = false;
        boolean broken = false;
        if (hCenter == 0 && jCenter == 0) {
            System.out.println("NO");
            return;
        }
        String line = matrix[hCenter];
        for (int i = 0; i < m; i++) {
            if (found) {
                if (line.charAt(i) == '*') {
                    if (stopped) {
                        broken = true;
                    }
                    stars.add(new Pair(hCenter, i));
                } else {
                    stopped = true;
                }
            }
            if (!found && line.charAt(i) == '*') {
                stars.add(new Pair(hCenter, i));
                found = true;
            }
        }
        if (broken) {
            System.out.println("NO");
            return;
        }
        found = false;
        stopped = false;
        for (int i = 0; i < n; i++) {
            if (found) {
                if (matrix[i].charAt(jCenter) == '*') {
                    if (stopped) {
                        broken = true;
                    }
                    stars.add(new Pair(i, jCenter));
                } else {
                    stopped = true;
                }
            } else if (matrix[i].charAt(jCenter) == '*') {
                stars.add(new Pair(i, jCenter));
                found = true;
            }

        }
        if (broken) {
            System.out.println("NO");
            return;
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (matrix[i].charAt(j) == '*' && !stars.contains(new Pair(i, j))) {
                    broken = true;
                }
            }
        }
        if (broken) {
            System.out.println("NO");
        } else System.out.println("YES");
    }
}

