			for(int j=0;j<col;j++) {
				c[i][j] = z.charAt(j);
			}
		}
		go();
	}


	private static void go() {
		int centerCnt = 0;
		int centerX = -1, centerY = -1;
		for(int i=0;i<c.length;i++)
			for(int j=0;j<c[i].length;j++) {
				if(isCenter(i,j)) {
					centerX = i;
					centerY = j;
					centerCnt++;
				}
			}
		if(centerCnt != 1) {
			System.out.println("NO");
		} else {
			StringBuffer x = new StringBuffer();
			StringBuffer y = new StringBuffer();
			for(int i=0;i<col;i++) {
				x = x.append(c[centerX][i]);
			}
			for(int i=0;i<row;i++) {
				y = y.append(c[i][centerY]);
			}
			boolean ok = true;
			for(int i=0;i<row;i++) {
				for(int j=0;j<col;j++) {
					if(i == centerX || j == centerY) continue;
					if(c[i][j] == '*') {
						ok = false;
						break;
					}
				}
			}

			String xx = x.toString().replaceAll("\\.+", " ").trim();
			String yy = y.toString().replaceAll("\\.+", " ").trim();

			if(xx.matches("\\*+") && yy.matches("\\*+") && ok) {
				System.out.println("YES");
			}else {
				System.out.println("NO");
			}
		}
	}

	private static boolean isCenter(int x, int y) {
		if(x - 1 < 0 || x >= row - 1 || y - 1 < 0 || y >= col - 1) return false;
		if(c[x][y+1] == '*' && c[x][y-1] == '*' && c[x-1][y] == '*' && c[x+1][y] == '*') return true;
		return false;
	}
}

