import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Round566Div2B {

	public static void main(String[] args) {

		out=new PrintWriter (new BufferedOutputStream(System.out));
		FastReader s=new FastReader();
		int h=s.nextInt();
		int w=s.nextInt();
		String[] grid=new String[h];
		for(int i=0;i<h;i++) {
			grid[i]=s.next();
		}
		int row=-1,col=-1;
		int count=0;
		boolean possible=true;
		for(int i=1;i<h-1;i++) {
			for(int j=1;j<w-1;j++) {
				if(grid[i].charAt(j)=='*') {
					if(grid[i-1].charAt(j)=='*' && grid[i+1].charAt(j)=='*'&&grid[i].charAt(j+1)=='*'&& grid[i].charAt(j-1)=='*') {
						row=i;
						col=j;
					}
				}
			}
		}
		for(int i=0;i<h;i++) {
			for(int j=0;j<w;j++) {
				if(grid[i].charAt(j)=='*')count++;
			}
		}
		if(col==-1 || row==-1) {
			possible=false;
			out.println("NO");
			out.close();
			return;
		}
		int countrow=0;
		int value=col;
		while(value>=0 && grid[row].charAt(value)=='*') {
			value--;
			countrow++;
		}
		value=col+1;
		while(value<w && grid[row].charAt(value)=='*') {
			value++;
			countrow++;
		}
		int tempcount=countrow;
		for(int i=0;i<w;i++) {
			if(grid[row].charAt(i)=='*') {
				countrow--;
			}
		}
		if(countrow<0) {
			possible=false;
		}
		int countcol=0;
		value=row;
		while(value>=0 && grid[value].charAt(col)=='*') {
			value--;
			countcol++;
		}
		value=row+1;
		while(value<h && grid[value].charAt(col)=='*') {
			value++;
			countcol++;
		}
		tempcount+=countcol;
		for(int i=0;i<h;i++) {
			if(grid[i].charAt(col)=='*') {
				countcol--;
			}
		}
		if(countcol<0) {
			possible=false;
		}
		if(tempcount!=count+1) {
			possible=false;
		}
		if(!possible) {
			out.println("NO");
		}else {
			out.println("YES");
		}
		out.close();
	}

	public static PrintWriter out;

	public static class FastReader {
		BufferedReader br;
		StringTokenizer st;



		public FastReader() {
			br = new BufferedReader(new InputStreamReader(System.in));


		}

		String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (Exception e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		long nextLong() {
			return Long.parseLong(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (Exception e) {
				e.printStackTrace();
			}
			return str;
		}
	}

}

