import java.util.List;
import java.util.Scanner;

public class Contest {




    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);



        String line = sc.nextLine();
        String[] split = line.split(" ");
        int h = Integer.valueOf(split[0]);
        int w = Integer.valueOf(split[1]);
        int[][] matrix = new int[h][w];
        for (int i = 0; i < h; i++) {
            line = sc.nextLine();
            split = line.split("");
            for (int j = 0; j < w; j++) {
                if (split[j].equals("*")) {
                    matrix[i][j] = 1;
                } else {
                    matrix[i][j] = 0;
                }
            }
        }
        boolean result = solve(matrix, h, w);

        if(result) {
            System.out.println("YES"); 
        } else {
            System.out.println("NO");
        }
    }

    private static boolean solve(int[][] matrix, int h, int w) {
        int plusRow = -1;
        for (int i = 0; i < h; i++) {
            int counter = 0;
            for (int j = 0; j < w; j++) {
                if (matrix[i][j] == 1) {
                    counter++;
                }
                if (counter > 1) {
                    plusRow = i;
                }
            }
        }
        if(plusRow == 0 || plusRow == (h-1) || plusRow == -1) {
            return false;
        }
        int center = -1;
        boolean upDeleted = false;
        boolean left = false;
        for (int j = 0; j < w; j++) {
            if (matrix[plusRow][j] == 1) {
                left = true;
                if (!upDeleted) {
                    boolean follow = true;
                    for (int k = 0; k < h; k++) {
                        if ((matrix[k][j] == 1) && (k != plusRow) && (follow)) {


                            if(k>plusRow && !upDeleted) {
                                return false;
                            }
                            upDeleted = true;
                            center = j;
                            matrix[k][j] = 0;
                        } else if ((matrix[k][j] == 0) && (upDeleted)) {
                            if(k <= (plusRow+1)) {
                                return false;
                            }
                            break;
                        }
                    }
                }
                matrix[plusRow][j] = 0;
            } else if(left){
                if(j == (center+1)) {
                    return false;
                }
                break;
            }
        }
        if(!upDeleted) {
            return false;
        }
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if(matrix[i][j] == 1) {
                    return false;
                }
            }
        }

        return true;
    }

    public static boolean isPrime(int num) {
        if (num > 2 && num % 2 == 0) {

            return false;
        }
        int top = (int) Math.sqrt(num) + 1;
        for (int i = 3; i < top; i += 2) {
            if (num % i == 0) {

                return false;
            }
        }

        return true;
    }

    private static void doneList(List<Integer> a) {
        StringBuilder builder = new StringBuilder("");
        for (int i = 0; i < a.size(); i++) {
            builder.append(a.get(i)).append(" ");
        }
        System.out.println(builder.toString().substring(0, builder.toString().length() - 1));
    }

    private static void doneArray(Integer[] a) {
        StringBuilder builder = new StringBuilder("");
        for (int i = 2; i < a.length; i++) {
            builder.append(a[i]).append(" ");
        }
        System.out.println(builder.toString().substring(0, builder.toString().length() - 1));
    }

    private static void done() {
        System.out.println("-1");
    }

    private static int lowerBound(int[] a, int low, int high, int element) {
        while (low < high) {
            int middle = low + (high - low) / 2;
            if (element > a[middle]) {
                low = middle + 1;
            } else {
                high = middle;
            }
        }
        return low;
    }

    private static int upperBound(int[] a, int low, int high, int element) {
        while (low < high) {
            int middle = low + (high - low) / 2;
            if (a[middle] > element) {
                high = middle;
            } else {
                low = middle + 1;
            }
        }
        return low;
    }

}

