public class Problemo {

    public static void main(String[] args) {
        System.out.println(solve());

    }

     private static String solve(){
        Scanner scanner = new Scanner(System.in);
        int[] centerpoint = new int[2];

        int hieght = scanner.nextInt();
        int width = scanner.nextInt();
        scanner.nextLine();
        boolean firstNotFound = true;
        boolean secondNotFound = true;
        boolean middleLineNotBroken = true;
        String[] lines = new String[hieght];
        for (int i=0;i<hieght;i++) {
            lines[i]=scanner.nextLine();
        }

        for (int row = 0; row<hieght;row++){
            for(int currentLineIndex= 0; currentLineIndex<width;currentLineIndex++){
                if(firstNotFound){
                    if(lines[row].charAt(currentLineIndex) == '*'){
                        centerpoint[0] = currentLineIndex;
                        if(currentLineIndex == 0 || currentLineIndex == (width-1))
                            return "NO";
                        firstNotFound = false;
                        continue;
                    }
                }
                if(!firstNotFound){

                    if(centerpoint[0] == currentLineIndex && middleLineNotBroken){
                        if(lines[row].charAt(currentLineIndex) != '*' ) {
                            if(row <= (centerpoint[1]+1))
                                return "NO";
                            middleLineNotBroken = false;
                        }
                        continue;
                    }
                    if(lines[row].charAt(currentLineIndex) == '*' && secondNotFound){
                        secondNotFound = false;
                        centerpoint[1]= row;
                        if(row == (hieght-1) || currentLineIndex > centerpoint[0])
                            return "NO";
                        boolean lineBroken= false;
                        while(currentLineIndex < width){
                            if(lines[row].charAt(currentLineIndex) == '*'){
                                if(lineBroken){
                                    return "NO";
                                }
                                currentLineIndex++;
                                continue;
                            }
                            if(lines[row].charAt(currentLineIndex) != '*'){
                                if(currentLineIndex <= (centerpoint[0]+1))return "NO";
                                lineBroken = true;
                            }
                            currentLineIndex++;
                        }
                        continue;
                    }
                    if(lines[row].charAt(currentLineIndex) == '*' )
                        return "NO";
                }

            }
        }
        if(centerpoint[0] == 0 || centerpoint[1] == 0)
            return "NO";
        return "YES";
    }


}

