                        c=j;
                        continue;
                    }
                    if (c!=-1) {
                        if (c<j && ch=='*') {
                            return "NO";
                        }
                        if (c>j && ch=='*') {
                            cur=1;
                        }
                        if (j==c && ch!='*')
                            return "NO";
                    }
                }
                if (cur==1) {
                    mid=i;
                    if (ch!='*') {
                        if (j<=c+1) {
                            return "NO";
                        }
                        else if (end==-1) {
                            end=j;
                        }
                    }
                    else if (end!=-1) {
                        return "NO";
                    }
                }
                if (cur==2) {
                    if (ch=='*'&&c!=-1&&j!=c) {
                        return "NO";
