            a[i] = in.readString();
        }

        boolean f1 = false;
        boolean f2 = false;

        int th = -1;
        int tw = -1;

        int rh = -1;
        int rw = -1;
        for(int i=0;i<h;i++) {
            for(int j=0;j<w;j++) {
                if(a[i].charAt(j) == '.') {
                    if(f1 && th == j) {
                        f1 = false;
                    }
                    if(f2 && tw == i) {
                        f2 = false;
                    }
                }
                else {
                    if(th == -1) {
                        th = j;
                        rh = i;
                        f1 = true;
                    }
                    else if(f1 && th == j) {
                        continue;
                    }
                    else if(tw == -1) {
                        rw = j;
                        tw = i;
                        f2 = true;
                    }
                    else if(f2 && tw == i) {
                        continue;
                    }
                    else {
                        System.out.println("NO");
                        return;
                    }
                }
            }
        }

        if(rh == -1 || th == -1 || rw == -1 || tw == -1) {
            System.out.println("NO");
            return;
        }

        int x=0,y=-1;
        for(int i=rh;i<h;i++) {
            if(a[i].charAt(th) != '*') {
                break;
            }
            else {
                if(i>=tw) {
                    y++;
                }
                else {
                    x++;
                }
            }
        }

        if(x < 1 || y < 1) {
            System.out.println("NO");
            return;
        }
        else {
            x=0;
            y=-1;
            for(int j=rw;j<w;j++) {
                if(a[tw].charAt(j) != '*') {
                    break;
                }
                else {
                    if(j>=th) {
                        y++;
                    }
                    else {
                        x++;
                    }
                }
            }

