            }
        }
        System.out.println("YES");
    }

    static int lowerBound(int a[],int n,long x) {
        int lo = 0;
        int hi = n;

        while(lo < hi) {
            int mid = (lo + hi)/2;
            if(a[mid] >= x) {
                hi = mid;
            }
            else {
                lo = mid + 1;
            }
        }

        return lo;
    }


