    }

    private static String Sol(char[][] matrix) {
        int possible = 0;
        int cont = 0;
        int max = 0;

        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[0].length; j++) {
                if (matrix[i][j] == '*'){
                    cont +=1;
                }
            }
        }

        for (int i = 1; i < matrix.length-1; i++) {
            for (int j = 1; j < matrix[0].length-1; j++) {
                int ref = verify(matrix,i,j);
                if(ref>max){
                    max = ref;
                }
            }
        }

        if (cont == max && croos){
            return "YES";
        }else{
            return  "NO";
        }
    }

    static boolean croos = false;

    private static int verify(char[][] matrix, int x, int y) {


        if(matrix[x][y] == '*'){
            int points = 1;
            if(matrix[x+1][y] == '*'){
                points++;
            }

            if(matrix[x-1][y] == '*'){
                points++;
            }

            if(matrix[x][y+1] == '*'){
                points++;
            }

            if(matrix[x][y-1] == '*'){
                points++;
            }

            if(points == 5) {
                points = 0;
                croos = true;
                for (int i = 0; i+x < matrix.length; i++) {
                    if (matrix[x+i][y] != '*'){
                        break;
                    }
                    points++;
                }
                for (int i = x; i >= 0; i--) {
                    if (matrix[i][y] != '*'){
                        break;
                    }
                    points++;
                }
                for (int i = 0; i+y < matrix[0].length; i++) {
                    if (matrix[x][y+i] != '*'){
                        break;
                    }
                    points++;
                }
                for (int i = y; i >= 0; i--) {
                    if (matrix[x][i] != '*'){
                        break;
                    }
                    points++;
                }
                return points-3;
            }else{
                return 0;
            }
        }

        return 0;
    }
