public class B {
    static BufferedReader br;
    static StringTokenizer st;

    static int h;
    static int w;
    static char[][] grid;

    public static void main(String[] args) throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        st = new StringTokenizer(br.readLine());
        h = Integer.parseInt(st.nextToken());
        w = Integer.parseInt(st.nextToken());
        grid = new char[h][w];
        for (int i = 0; i<h; i++) {
            String line = br.readLine();
            for (int j = 0; j<w; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        solve();
    }

    public static void solve() {
        if (h<3||w<3) {
            System.out.println("NO");
        }
        else {
            int totalStarCount = 0;
            for (int i = 0; i<h; i++) {
                for (int j = 0; j<w; j++) {
                    if (grid[i][j]=='*') {
                        totalStarCount++;
                    }
                }
            }
            for (int i = 1; i<h-1; i++) {
                for (int j = 1; j<w-1; j++) {
                    if (grid[i][j]=='*') {
                        if (grid[i][j+1]=='*'
                        && grid[i][j-1]=='*'
                        && grid[i-1][j]=='*'
                        && grid[i+1][j]=='*') {
                            int result = 1;
                            result+=countStars(i, j+1, 0, 1);
                            result+=countStars(i, j-1, 0,-1);
                            result+=countStars(i+1, j, 1, 0);
                            result+=countStars(i-1, j, -1, 0);
                            if (result==totalStarCount) {
                                System.out.println("YES");
                                return;
                            }
                            else {
                                System.out.println("NO");
                                return;
                            }
                        }
                    }
                }
            }
            System.out.println("NO");
        }
    }

    public static int countStars(int y, int x, int yOffset, int xOffset) {
        if (y==h || x==w || y==-1 || x==-1) {
            return 0;
        }
        if (grid[y][x]=='.') {
            return 0;
        }
        return 1+countStars(y+yOffset, x+xOffset, yOffset, xOffset);
    }
}

