			}
		}


		  if (cent(matrix)) {
			  if (fitXAxis(maxRight(), maxLeft()) 
				  && fitYAxis(maxUp(),maxDown()) 
				  && noOtherStars()) {
			  System.out.println("YES");
			  } 
		  else {
		  System.out.println("NO");
		  }

  } else {
	  System.out.println("NO"); 
	  }

	}

	public static boolean cent(char[][] matrix) {
		for (int i = 1; i < h - 1; i++) {
			for (int j = 1; j < w - 1; j++) {
				       if (matrix[i][j] == '*' 
						&& matrix[i - 1][j] == '*' 
						&& matrix[i + 1][j] == '*' 
						&& matrix[i][j - 1] == '*'
						&& matrix[i][j + 1] == '*') {

					colomn = j;
					row = i;
					return true;
				}
			}
		}
		return false;
	}

	public static int maxRight() {

		for (int i = 0; i < w; i++) {
			if (matrix[row][i] == '*') {
				maxRightIndex = i;
				break;
			}
		}
		return maxRightIndex;
	}

	public static int maxLeft() {

		for (int i = w - 1; i >= 0; i--) {
			if (matrix[row][i] == '*') {
				maxLeftIndex = i;
				break;
			}
		}
		return maxLeftIndex;
	}

	public static boolean fitXAxis(int r, int l) {
		for (int i = r + 1; i < l; i++) {
			if (matrix[row][i] == '.') {
				return false;
			}
		}
		return true;
	}

	public static int maxUp() {

		for (int i = 0; i < h; i++) {
			if (matrix[i][colomn] == '*') {
				maxUpIndex = i;
				break;
			}
		}
		return maxUpIndex;
	}

	public static int maxDown() {
		for (int i = h - 1; i >= 0; i--) {
			if (matrix[i][colomn] == '*') {
				maxDowntIndex = i;
				break;
			}
		}
		return maxDowntIndex;
	}

	public static boolean fitYAxis(int t, int d) {

		for (int i = t + 1; i < d; i++) {
			if (matrix[i][colomn] == '.') {
				return false;
			}
		}
		return true;
	}

	public static boolean noOtherStars() {
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (matrix[i][j] == '*' && j != colomn && i != row) {
					return false;
				}
			}
		}
		return true;
	}

}

