                if(m[i][j] == 'O'){
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean dotAB(char[][] m, int r, int ti, int tj) {
        if((ti + 1) < r && (m[ti + 1][tj] == '.')){
            return true;
        }else if((ti - 1) >= 0 && (m[ti - 1][tj] == '.')){
            return true;
        }
        return false;
    }

}

