import java.util.Scanner;

public class B {

    static boolean[][] grid, marked;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        int h = in.nextInt(), w = in.nextInt();

        grid = new boolean[h][w];
        marked = new boolean[h][w];

        for (int i = 0; i < grid.length; i++) {
            char[] row = in.next().toCharArray();
            for (int j = 0; j < grid[i].length; j++) {
                grid[i][j] = (row[j] == '*');
            }
        }

        boolean crossFound = false;
        for (int i = 0; i < grid.length && !crossFound; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (crossNonEmpty(i, j)) {
                    markCross(i, j);
                    crossFound = true;
                    break;
                }
            }
        }

        boolean misMatchFound = false;
        for (int i = 0; i < grid.length && !misMatchFound; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] != marked[i][j]) {
                    misMatchFound = true;
                    break;
                }
            }
        }

        System.out.println((crossFound && !misMatchFound) ? "YES" : "NO");
    }

    static void markCross(int i, int j) {

        for (int start = i; start >= 0 && grid[start][j]; start--) {
            marked[start][j] = true;
        }


        for (int start = i; start < grid.length && grid[start][j]; start++) {
            marked[start][j] = true;
        }


        for (int start = j; start >= 0 && grid[i][start]; start--) {
            marked[i][start] = true;
        }


        for (int start = j; start < grid[i].length && grid[i][start]; start++) {
            marked[i][start] = true;
        }
    }

    static boolean crossNonEmpty(int i, int j) {
        return topNonEmpty(i, j)
                && leftNonEmpty(i, j)
                && rightNonEmpty(i, j)
                && bottomNonEmpty(i, j)
                && centerNonEmpty(i, j);
    }

    static boolean topNonEmpty(int i, int j) {
        return (i > 0 && grid[i-1][j]);
    }

    static boolean leftNonEmpty(int i, int j) {
        return (j > 0 && grid[i][j-1]);
    }

    static boolean rightNonEmpty(int i, int j) {
        return (i < grid.length-1 && grid[i+1][j]);
    }

    static boolean bottomNonEmpty(int i, int j) {
        return (j < grid[i].length-1 && grid[i][j+1]);
    }

    static boolean centerNonEmpty(int i, int j) {
        return grid[i][j];
    }
}

