            {
                if(row[i][0]>=j && row[i][1]<=(j+k-1) && row[i][0]!=n)
                    cnt++;
            }
            rowst[0][j]=cnt;
            for(i=1;i<=n-k;i++)
            {
                if(row[i-1][0]>=j && row[i-1][1]<=(j+k-1) && row[i-1][0]!=n)
                    cnt--;
                if(row[i+k-1][0]>=j && row[i+k-1][1]<=(j+k-1) && row[i+k-1][0]!=n)
                    cnt++;
                rowst[i][j]=cnt;
            }
        }
        for(i=0;i<=n-k;i++)
        {
            cnt=0;
            for(j=0;j<k;j++)
            {
                if(col[j][0]>=i && col[j][1]<=(i+k-1) && col[j][0]!=n)
                    cnt++;
            }
            colst[i][0]=cnt;
            for(j=1;j<=n-k;j++)
            {
                if(col[j-1][0]>=i && col[j-1][1]<=(i+k-1) && col[j-1][0]!=n)
                    cnt--;
                if(col[j+k-1][0]>=i && col[j+k-1][1]<=(i+k-1) && col[j+k-1][0]!=n)
                    cnt++;
                colst[i][j]=cnt;
            }
        }
        for(i=0;i<=n-k;i++)
        {
            for(j=0;j<=n-k;j++)
            {

                ans=Math.max(ans,rowst[i][j]+colst[i][j]);
            }

        }
        System.out.println(c+ans);

    }
