        int n;

        int range(int x1, int y1, int x2, int y2) {
            return sum[x2][y2] - sum[x1 - 1][y2] - sum[x2][y1 - 1] + sum[x1 - 1][y1 - 1];
        }

        boolean allWhiteCol(int c) {
            return range(1, c, n, c) == 0;
        }

        int getMax(char[][] map, int k) {
            sum = new int[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    sum[i][j] = sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1];
                    sum[i][j] += (map[i][j] == 'B' ? 1 : 0);
                }
            }

            int[] max = new int[n + 1];
            int[] min = new int[n + 1];

            for (int row = 1; row <= n; row++) {
                max[row] = -1;
                min[row] = n + 1;
                for (int col = 1; col <= n; col++) {
                    if (map[row][col] == 'B') {
                        min[row] = Math.min(col, min[row]);
                        max[row] = Math.max(col, max[row]);
                    }
                }
            }

            int ans = 0;
            for (int row = 1; row <= n - k + 1; row++) {
                int startCol = 1;
                int whiteLines = 0;
                ArrayList<Integer[]> intervals = new ArrayList<>();
                for (int rowSquare = row; rowSquare <= row + k - 1; rowSquare++) {
                    if (max[rowSquare] >= min[rowSquare] && max[rowSquare] - min[rowSquare] <= k) {
                        intervals.add(new Integer[]{max[rowSquare], +rowSquare});
                        intervals.add(new Integer[]{min[rowSquare], -rowSquare});
                    }
                }
                Collections.sort(intervals, new Comparator<Integer[]>() {

                    public int compare(Integer[] o1, Integer[] o2) {
                        if (o1[0].equals(o2[0]) == false) return o1[0] < o2[0] ? -1 : 1;
                        else if (o1[1].equals(o2[1]) == false) return o1[1] < o2[1] ? -1 : 1;
                        return 0;
                    }
                });
                ArrayList<Integer[]> seenIntervals = new ArrayList<>();
                int intervalID = 0;
                int seenIntervalID = 0;
                for (int endCol = 1; endCol <= n; endCol++) {
                    if (endCol > k) {
                        while (seenIntervalID < seenIntervals.size() && seenIntervals.get(seenIntervalID)[0] == startCol) {
                            if (seenIntervals.get(seenIntervalID)[1] < 0) {
                                whiteLines--;
                            }
                            seenIntervalID++;
                        }
                        if (allWhiteCol(startCol) == false && range(row, startCol, row + k - 1, startCol) == range(1, startCol, n, startCol)) {
                            whiteLines--;
                        }
                        startCol++;
                    }
                    if (allWhiteCol(endCol) == false && range(row, endCol, row + k - 1, endCol) == range(1, endCol, n, endCol)) {
                        whiteLines++;
                    }
                    while (intervalID < intervals.size() && intervals.get(intervalID)[0] == endCol) {
                        if (intervals.get(intervalID)[1] > 0) {
                            whiteLines++;
                        }
                        seenIntervals.add(new Integer[]{intervals.get(intervalID)[0], intervals.get(intervalID)[1]});
                        intervalID++;
                    }
                    ans = Math.max(ans, whiteLines);
                }
            }
            return ans;
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            int k = in.nextInt();
            char[][] map = new char[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                char[] aux = in.nextLine().toCharArray();
                for (int j = 1; j <= n; j++) {
                    map[i][j] = aux[j - 1];
                }
            }

            sum = new int[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    sum[i][j] = sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1];
                    sum[i][j] += (map[i][j] == 'B' ? 1 : 0);
                }
            }

            int oldLines = 0;
            for (int row = 1; row <= n; row++)
                if (range(row, 1, row, n) == 0)
                    oldLines++;
            for (int col = 1; col <= n; col++)
                if (range(1, col, n, col) == 0)
                    oldLines++;

            int newLines = getMax(map, k);
            out.print(oldLines + newLines);
        }

    }

    static class InputReader {
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputStream stream;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        private int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sgn;
        }

        public String nextLine() {
            int c = read();
            while (isWhitespace(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

    }
}

