		int[] b = new int[n];
		int[] l = new int[n];
		int[] r = new int[n];

		Arrays.fill(t, -1);
		Arrays.fill(l, -1);

		int rl = 0;
		int cl = 0;

		for (int j = 0; j < n; j++) {
			for (int i = 0; i < n; i++) {
				if (a[i].charAt(j) == 'B') {
					if (t[j] == -1) {
						t[j] = i;
						b[j] = i;
					} else {
						b[j] = i;
					}
				}
			}
			if (t[j] == -1) rl++;
		}

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (a[i].charAt(j) == 'B') {
					if (l[i] == -1) {
						l[i] = j;
						r[i] = j;
					} else {
						r[i] = j;
					}
				}
			}
			if (l[i] == -1) cl++;
		}

		int[][] numr = new int[n][n];
		int[][] numc = new int[n][n];


		for (int i = 0; i < n; i++) {
			Queue<Integer> q = new LinkedList<>();
			for (int j = 0; j < k; j++) {
				if (t[j] > -1 && t[j] >= i && b[j] <= i + k - 1) {
					numr[i][0] += 1;
					q.add(1);
				} else {
					q.add(0);
				}
			}

			for (int j = 1; j < n; j++) {
				numr[i][j] = numr[i][j - 1];
				numr[i][j] -= q.poll();

				if (j + k - 1 < n && t[j + k - 1] > -1 && t[j + k - 1] >= i && b[j + k - 1] <= i + k - 1) {
					numr[i][j] += 1;
					q.add(1);
				} else {
					q.add(0);
				}
			}
		}

		for (int j = 0; j < n; j++) {
			Queue<Integer> q = new LinkedList<>();
			for (int i = 0; i < k; i++) {
				if (l[i] > -1 && l[i] >= j && r[i] <= j + k - 1) {
					numc[0][j] += 1;
					q.add(1);
				} else {
					q.add(0);
				}
			}

			for (int i = 1; i < n; i++) {
				numc[i][j] = numc[i-1][j];
				numc[i][j] -= q.poll();

				if (i + k - 1 < n && l[i + k - 1] > -1 && l[i + k - 1] >= j && r[i + k - 1] <= j + k - 1) {
					numc[i][j] += 1;
					q.add(1);
				} else {
					q.add(0);
				}
			}
		}










































		int ans = 0;
		for (int i = 0; i < n - k + 1; i++) {
			for (int j = 0; j < n - k + 1; j++) {
				ans = Math.max(ans, numr[i][j] + numc[i][j]);
			}
		}





		return ans + rl + cl;
	}

}

