public class CodingLegacy {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        ScanReader in = new ScanReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Palindrome solver = new Palindrome();

        int t = 1;


        for (int i = 0; i < t; i++) {
            solver.solve(i + 1, in, out);
        }

        out.close();
    }

    static class Palindrome {
        static long mod = 1000000007;
        static long maxX = (long) 1e18;
        static long mod2 = 998244353;

        int[][] row,col;
        int n,k;
        void solve(int testNumber, ScanReader in, PrintWriter out) {
            n = in.nextInt();k = in.nextInt();

            char[][] s = new char[n][];

            for (int i = 0; i < n; i++) {
                s[i] = in.next().toCharArray();
            }

            row = new int[n][2];
            col = new int[n][2];

            int whiteStart = 0;

            for(int i = 0;i<n;i++) {
                int bMin = n,bMax = -1;
                for(int j =0;j<n;j++) {
                    if(s[i][j] == 'B'){
                        bMin = Math.min(bMin,j);
                        bMax = j;
                    }
                }
                if(bMin == n) whiteStart++;
                row[i][0] = bMin;row[i][1] = bMax;
            }

            int[][] ansForRow = new int[n][n];
            int[][] ansForCol = new int[n][n];

            for(int i = 0;i + k -1<n;i++) {
                int temp = 0;
                for(int j = 0;j<k;j++) {
                    if(check1(j,i)) temp++;
                }
                ansForRow[0][i] = temp;

                for(int j = 1;j + k -1< n;j++) {
                    ansForRow[j][i] = ansForRow[j-1][i] - (check1(j-1,i)?1:0) + (check1(j + k -1 ,i)?1:0);
                }
            }

            for(int i = 0;i<n;i++) {
                int bMin = n,bMax = -1;
                for(int j = 0;j<n;j++) {
                    if(s[j][i] == 'B' ){
                        bMin = Math.min(bMin,j);
                        bMax = j;
                    }
                }
                if(bMin == n) whiteStart++;
                col[i][0] = bMin;col[i][1] = bMax;
            }

            for (int i = 0; i + k - 1< n; i++) {
                int temp = 0;
                for(int j = 0;j<k;j++) {
                    if(check2(j,i)) temp++;
                }
                ansForCol[i][0] = temp;
                for(int j = 1;j + k -1< n;j++) {
                    ansForCol[i][j] = ansForCol[i][j-1] - (check2(j-1,i)?1:0) + (check2(j + k -1,i)?1:0);
                }
            }

            int ans = 0;
            for(int i = 0;i< n;i++) {
                for(int j = 0;j<n;j++) {
                    ans = Math.max(ans,ansForCol[i][j] + ansForRow[i][j]);
                }
            }

            out.println(ans + whiteStart);
        }

        boolean check1(int r,int c) {
            if(row[r][0] == n) return false;
            return row[r][0] >= c && row[r][1] < c + k;
        }

        boolean check2(int c,int r){
            if(col[c][0] == n) return false;
            return col[c][0] >= r && col[c][1] < r + k;
        }

    }

    static class ScanReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;
        private BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        public ScanReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        public int nextInt() {
            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));

            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;

            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));
            return res * sgn;
        }

        public double nextDouble() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            double res = 0;
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E')
                    return res * Math.pow(10, nextInt());
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            if (c == '.') {
                c = read();
                double m = 1;
                while (!isSpaceChar(c)) {
                    if (c == 'e' || c == 'E')
                        return res * Math.pow(10, nextInt());
                    if (c < '0' || c > '9')
                        throw new InputMismatchException();
                    m /= 10;
                    res += (c - '0') * m;
                    c = read();
                }
            }
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            }
            while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return readString();
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }
}

