                    row_bound[i][0]=Math.min(j,row_bound[i][0]);
                    row_bound[i][1]=Math.max(j,row_bound[i][1]);
                    col_bound[j][0]=Math.min(col_bound[j][0],i);
                    col_bound[j][1]=Math.max(col_bound[j][1],i);
                }


            }
        }
        int res=0,max=0;
        for(int i=0;i<n;i++)
        {
            if(row_bound[i][1]<0)
                res++;
            if(col_bound[i][1]<0)
                res++;
        }
        for(int i=0;i<k;i++)
        {
            if(row_bound[i][1]<k && row_bound[i][1]>=0)
                dp[0][0][0]++;
            if(col_bound[i][1]<k && col_bound[i][1]>=0)
                dp[0][0][1]++;
        }
        max=dp[0][0][0]+dp[0][0][1];
        for(int i=0;i<dp.length;i++)
        {
            if(i>0)
            {
                dp[i][0][0]=dp[i-1][0][0];
                if(row_bound[i-1][1]<k && row_bound[i-1][1]>=0)
                    dp[i][0][0]--;
                if(row_bound[i+k-1][1]<k && row_bound[i+k-1][1]>=0)
                    dp[i][0][0]++;
                int temp=0;
                for (int m = 0; m < k; m++)
                {
                    if (col_bound[m][1] < 0)
                        continue;
                    if (i - 1 <= col_bound[m][0] && i + k - 2 >= col_bound[m][1])
                    {
                            if (i > col_bound[m][0])
                                temp--;
                    }
                    else
                    {
                        if (i <= col_bound[m][0] && i + k - 1 >= col_bound[m][1])
                            temp++;
                    }
                }
                dp[i][0][1]=dp[i-1][0][1]+temp;
            }
            max=Math.max(max,dp[i][0][0]+dp[i][0][1]);
            for (int j = 1; j < dp[i].length; j++)
            {
                dp[i][j][0]=dp[i][j-1][0];
                dp[i][j][1]=dp[i][j-1][1];

                if(col_bound[j-1][1]>=0 && i<=col_bound[j-1][0] && i+k-1>=col_bound[j-1][1])
                    dp[i][j][1]--;
                if(col_bound[j+k-1][1]>=0 && i<=col_bound[j+k-1][0] && i+k-1>=col_bound[j+k-1][1])
                    dp[i][j][1]++;
                if(i==0)
                {
                    int cur=0;
                    for (int q = i; q <= i + k - 1; q++)
                    {
                        if (row_bound[q][1] < 0)
                            continue;
                        if (j - 1 <= row_bound[q][0] && j + k - 2 >= row_bound[q][1])
                        {
                            if (j > row_bound[q][0])
                                cur-=1;
                        }
                        else
                        {
                            if (j <= row_bound[q][0] && j + k - 1 >= row_bound[q][1])
                                cur+=1;
                        }
                    }
                    save[j]=cur;
                    dp[i][j][0]=dp[i][j-1][0]+cur;
                }
                else
                {
                    int now=0;
                    if (j - 1 <= row_bound[i-1][0] && j + k - 2 >= row_bound[i-1][1])
                    {
                        if (j > row_bound[i-1][0])
                            now++;
                    }
                    else
                    {
                        if (j <= row_bound[i-1][0] && j + k - 1 >= row_bound[i-1][1])
                            now--;
                    }
                    if (j - 1 <= row_bound[i+k-1][0] && j + k - 2 >= row_bound[i+k-1][1])
                    {
                        if (j > row_bound[i+k-1][0])
                            now--;
                    }
                    else
                    {
                        if (j <= row_bound[i+k-1][0] && j + k - 1 >= row_bound[i+k-1][1])
                            now++;
                    }
                    save[j]+=now;
                    dp[i][j][0]=dp[i][j-1][0]+save[j];
                }
                max=Math.max(max,dp[i][j][0]+dp[i][j][1]);
            }
        }
        System.out.println(max+res);

    }
