    static class TaskD {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt(), k = in.nextInt();
            char[][] X = new char[n][n];
            int[] rowMin = new int[n];
            int[] rowMax = new int[n];
            int[] colMin = new int[n];
