            Arrays.fill(colMin, n + 1);

            for (int i = 0; i < n; i++) {
                X[i] = in.readCharArray(n);

                for (int j = 0; j < n; j++)
                    if (X[i][j] == 'B') {
                        rowMax[i] = Integer.max(rowMax[i], j + 1);
                        rowMin[i] = Integer.min(rowMin[i], j + 1);

                        colMax[j] = Integer.max(colMax[j], i + 1);
                        colMin[j] = Integer.min(colMin[j], i + 1);
                    }
            }
            int ans = 0;
            for (int i = 0; i < n; i++) {
                if (rowMax[i] == 0) ans++;
                if (colMax[i] == 0) ans++;
            }

            for (int j = 0; j + k <= n; j++) {
                int l = j + 1, r = j + k;
                int cnt = 0;
                for (int i = 0; i < k; i++) if (rowMax[i] != 0 && (rowMax[i] <= r && rowMin[i] >= l)) cnt++;
                addition[0][j] += cnt;
                for (int i = 1; i + k <= n; i++) {
                    int mn = rowMin[i + k - 1], mx = rowMax[i + k - 1];

                    if (mx > 0 && (mx <= r && mn >= l)) cnt++;
                    mn = rowMin[i - 1];
                    mx = rowMax[i - 1];
                    if (mx > 0 && (mx <= r && mn >= l)) cnt--;
                    addition[i][j] += cnt;
                }
            }
            for (int i = 0; i + k <= n; i++) {
                int l = i + 1, r = i + k;
                int cnt = 0;
                for (int j = 0; j < k; j++) {
                    int mn = colMin[j], mx = colMax[j];
                    if (mx > 0 && (mx <= r && mn >= l)) cnt++;
                }

                addition[i][0] += cnt;
                for (int j = 1; j + k <= n; j++) {
                    int mn = colMin[j + k - 1], mx = colMax[j + k - 1];
                    if (mx > 0 && (mx <= r && mn >= l)) cnt++;
                    mn = colMin[j - 1];
                    mx = colMax[j - 1];
                    if (mx > 0 && (mx <= r && mn >= l)) cnt--;
                    addition[i][j] += cnt;
                }
            }
            int value = ans;
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++) value = Integer.max(value, ans + addition[i][j]);
            out.println(value);

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public char[] readCharArray(int size) {
            char[] array = new char[size];
            for (int i = 0; i < size; i++) {
                array[i] = readCharacter();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

