    static class Palindrome {
        static long mod = 1000000007;
        static long maxX = (long) 1e18;
        static long mod2 = 998244353;

        int[][] p;
        int n;
        void solve(int testNumber, ScanReader in, PrintWriter out) {
            n = in.nextInt();int k = in.nextInt();

            char[][] s = new char[n][];

            for (int i = 0; i < n; i++) {
                s[i] = in.next().toCharArray();
            }
            p = new int[n + 1][n + 1];

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    p[i][j] = p[i - 1][j] + p[i][j - 1] - p[i - 1][j - 1] + (s[i - 1][j - 1] == 'B' ? 1 : 0);
                }
            }








            int ans = 0;

            for(int i = 1;i<=n;i++) {
                if(get(i,1,i,n) == 0) ans++;
                if(get(1,i,n,i) == 0) ans++;
            }

            int[][] row = new int[n+1][n+1],col = new int[n+1][n+1];

            for(int i = 1;i<=n;i++) {
                for(int j = 1;j<=n;j++) {
                    if( (get(i,j,i,j + k - 1) == get(i,1,i,n))  && get(i,1,i,n) != 0) row[i][j] = 1;
                    if( (get(i,j,i+k-1,j ) == get(1,j,n,j))  && get(1,j,n,j) != 0) col[i][j] = 1;
                }
            }















            for(int i = 1;i<=n;i++){
                for(int j= 1;j<=n;j++) {
                    row[i][j] += row[i-1][j];
                    col[i][j] += col[i][j-1];
                }
            }
            int res = 0;

            for(int i = 1;i<=n;i++){
                for(int j = 1;j<=n;j++) {
                    res = Math.max(res,row[Math.min(n,i+k -1)][j] - row[i-1][j] + col[i][Math.min(n,j + k -1)] - col[i][j-1]);
                }
            }

            out.println(ans + res);

        }

        int get (int l1,int r1,int l2,int r2) {
            l2 = Math.min(l2,n);
            r2 = Math.min(r2,n);
            return p[l2][r2] - p[l1-1][r2] - p[l2][r1 - 1] + p[l1 - 1][r1 - 1];
        }
    }

    static class ScanReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;
        private BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        public ScanReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        public int nextInt() {
            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));

            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;

            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));
            return res * sgn;
        }

        public double nextDouble() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            double res = 0;
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E')
                    return res * Math.pow(10, nextInt());
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            if (c == '.') {
                c = read();
                double m = 1;
                while (!isSpaceChar(c)) {
                    if (c == 'e' || c == 'E')
                        return res * Math.pow(10, nextInt());
                    if (c < '0' || c > '9')
                        throw new InputMismatchException();
                    m /= 10;
                    res += (c - '0') * m;
                    c = read();
                }
            }
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            }
            while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return readString();
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }
}

