            String s = IO.next();
            for (int j = 0; j < n; j++) {
                bl[i][j] = s.charAt(j) == 'B';
                if (bl[i][j]) {
                    collast[j] = i;
                    if (colfirst[j] == -1)
                        colfirst[j] = i;
                }
            }
            int f = s.indexOf('B');
            int l = s.lastIndexOf('B');
            Pair pair=null;
            if(f<0) {
                ans++;
            } else if(l-f+1 <= k) {
                pair = new Pair(Math.max(l-k+1, 0), f);
            }
            lines.add(pair);
        }

        int best=0;
        int sum[] = new int[2005];
        for(int i=0; i<n; i++) {
            int li = i-k+1;
            Pair pair = lines.get(i);
            if(pair !=null) {
                for (int j = pair.first; j <= pair.second; j++) {
                    sum[j]++;
                }
            }
            if(li>0) {
                pair = lines.get(li-1);
                if(pair !=null) {
                    for (int j = pair.first; j <= pair.second; j++) {
                        sum[j]--;
                    }
                }
            }
            int cols=0;
