                if(lj>0 && (colfirst[lj-1]>=0 && colfirst[lj-1] >= li && collast[lj-1] <= i))
                    cols--;
                if(lj>=0)
                    best=Math.max(best, sum[lj]+cols);
            }
        }
        for(int i=0; i<n; i++) {
            if(colfirst[i]<0)
                ans++;
        }
        System.out.println(best+ans);
