    static class TaskD {
        public void solve(int testNumber, Input in, PrintWriter out) {
            try {
                int n = in.readInt();
                int k = in.readInt();
                char[][] c = new char[n][];
                for (int i = 0; i < n; i++) {
                    c[i] = in.readWord().toCharArray();
                }

                int[] Rmin = new int[n];
                int[] Rmax = new int[n];
                Arrays.fill(Rmin, -1);
                Arrays.fill(Rmax, -1);
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (c[i][j] == 'B') {
                            if (Rmin[i] == -1 || Rmin[i] > j) {
                                Rmin[i] = j;
                            }
                            if (Rmax[i] == -1 || Rmax[i] < j) {
                                Rmax[i] = j;
                            }
                        }
                    }
                }

                int[] Cmin = new int[n];
                int[] Cmax = new int[n];
                Arrays.fill(Cmin, -1);
                Arrays.fill(Cmax, -1);
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (c[j][i] == 'B') {
                            if (Cmin[i] == -1 || Cmin[i] > j) {
                                Cmin[i] = j;
                            }
                            if (Cmax[i] == -1 || Cmax[i] < j) {
                                Cmax[i] = j;
                            }
                        }
                    }
                }

                int base = 0;
                int[][] S = new int[n][n];
                for (int i = 0; i < n; i++) {
                    if (Rmin[i] == -1 && Rmax[i] == -1) {
                        base++;
                    } else if (Rmax[i] - Rmin[i] < k) {
                        int tmin = Math.max(Rmax[i] - k + 1, 0);
                        int tmax = Rmin[i] + 1;
                        for (int j = i - k + 1; j <= i; j++) {
                            if (j >= 0 && j < n) {
                                S[j][tmin] += 1;
                                if (tmax < n) {
                                    S[j][tmax] += -1;
                                }
                            }
                        }
                    }
                }

                for (int i = 0; i < n; i++) {
                    if (Cmin[i] == -1 && Cmax[i] == -1) {
                        base++;
                    } else if (Cmax[i] - Cmin[i] < k) {
                        int tmin = Math.max(i - k + 1, 0);
                        int tmax = i + 1;
                        for (int j = Cmax[i] - k + 1; j <= Cmin[i]; j++) {
                            if (j >= 0 && j < n) {
                                S[j][tmin] += 1;
                                if (tmax < n) {
                                    S[j][tmax] += -1;
                                }
                            }
                        }
                    }
                }

                int ans = 0;
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (j > 0) {
                            S[i][j] += S[i][j - 1];
                        }
                        if (S[i][j] > ans) {
                            ans = S[i][j];
                        }
                    }
                }

                out.println(base + ans);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

    }

    static class Input {
        public final BufferedReader reader;
        private String line = "";
        private int pos = 0;

        public Input(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        private boolean isSpace(char ch) {
            return ch <= 32;
        }

        public String readWord() throws IOException {
            skip();
            int start = pos;
            while (pos < line.length() && !isSpace(line.charAt(pos))) {
                pos++;
            }
            return line.substring(start, pos);
        }

        public int readInt() throws IOException {
            return Integer.parseInt(readWord());
        }

        private void skip() throws IOException {
            while (true) {
                if (pos >= line.length()) {
                    line = reader.readLine();
                    pos = 0;
                }
                while (pos < line.length() && isSpace(line.charAt(pos))) {
                    pos++;
                }
                if (pos < line.length()) {
                    return;
                }
            }
        }

    }
}

