    static class DWhiteLines {
        public void solve(int testNumber, inputClass sc, PrintWriter out) {
            int n = sc.nextInt();
            int k = sc.nextInt();
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.nextLine().toCharArray();
            }
            int[] nbC = new int[n];
            int toadd = 0;
            for (int i = 0; i < n; i++) {
                int act = 0;
                for (int j = 0; j < n; j++) {
                    if (grid[j][i] == 'B') {
                        act++;
                    }
                }
                nbC[i] = act;
                if (act == 0) {
                    toadd++;
                }
            }
            int[] nbR = new int[n];
            for (int i = 0; i < n; i++) {
                int act = 0;
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'B') {
                        act++;
                    }
                }
                nbR[i] = act;
                if (act == 0) {
                    toadd++;
                }
            }
            int[][] yesR = new int[n][n];
            for (int i = 0; i < n; i++) {
                int act = 0;
                for (int j = 0; j < k; j++) {
                    if (grid[i][j] == 'B') {
                        act++;
                    }
                }
                if (nbR[i] != 0) {
                    if (act == nbR[i]) {
                        yesR[i][0] = 1;
                    }
                }
                for (int j = 1; j + k - 1 < n; j++) {
                    if (grid[i][j - 1] == 'B') {
                        act--;
                    }
                    if (grid[i][j + k - 1] == 'B')
                        act++;
                    if (nbR[i] != 0) {
                        if (act == nbR[i]) {
                            yesR[i][j] = 1;
                        }
                    }
                }
            }

            int[][] yesC = new int[n][n];
            for (int i = 0; i < n; i++) {
                int act = 0;
                for (int j = 0; j < k; j++) {
                    if (grid[j][i] == 'B') {
                        act++;
                    }
                }
                if (nbC[i] != 0) {
                    if (act == nbC[i]) {
                        yesC[0][i] = 1;
                    }
                }
                for (int j = 1; j + k - 1 < n; j++) {
                    if (grid[j - 1][i] == 'B') {
                        act--;
                    }
                    if (grid[j + k - 1][i] == 'B')
                        act++;
                    if (nbC[i] != 0) {
                        if (act == nbC[i]) {
                            yesC[j][i] = 1;
                        }
                    }
                }
            }
            int[][] ansR = new int[n][n];
            for (int i = 0; i + k - 1 < n; i++) {
                for (int j = 0; j < k; j++) {
                    ansR[0][i] += yesR[j][i];
                }
                for (int j = 1; j + k - 1 < n; j++) {
                    ansR[j][i] = ansR[j - 1][i];
                    if (yesR[j - 1][i] == 1) {
                        ansR[j][i]--;
                    }
                    if (yesR[j + k - 1][i] == 1) {
                        ansR[j][i]++;
                    }
                }
            }
            int[][] ansC = new int[n][n];
            for (int i = 0; i + k - 1 < n; i++) {
                for (int j = 0; j < k; j++) {
                    ansC[i][0] += yesC[i][j];
                }
                for (int j = 1; j + k - 1 < n; j++) {
                    ansC[i][j] = ansC[i][j - 1];
                    if (yesC[i][j - 1] == 1) {
                        ansC[i][j]--;
                    }
                    if (yesC[i][j + k - 1] == 1) {
                        ansC[i][j]++;
                    }
                }
            }
            long ans = 0;
            for (int i = 0; i + k - 1 < n; i++) {
                for (int j = 0; j + k - 1 < n; j++) {
                    ans = Math.max(ans, ansR[i][j] + ansC[i][j]);
                }
            }
            out.println(ans + toadd);
        }

