public class D {

	static FasterScanner sc = new FasterScanner();
	static PrintWriter out = new PrintWriter(System.out);

	static void exit() {
		out.close();
	}

	int [][] rows, cols;
	int n, k;
	public D () {
		n = sc.nextInt();
		k = sc.nextInt();
		rows = new int [n][2];
		cols = new int [n][2];
		for (int i = 0; i < n; i++) {
			rows[i][0] = cols[i][0] = n;
			rows[i][1] = cols[i][1] = -1;
		}
		for (int i = 0; i < n; i++) {
			String line = sc.nextString();
			for (int j = 0; j < n; j++) {
				if (line.charAt(j) == 'B') {
					rows[i][0] = Math.min(rows[i][0], j);
					rows[i][1] = Math.max(rows[i][1], j);

					cols[j][0] = Math.min(cols[j][0], i);
					cols[j][1] = Math.max(cols[j][1], i);
				}
			}
		}
		if (n == k) {
			out.println(2 * n);
			return;
		}

		int empty_lines = 0;
		for (int i = 0; i < n; i++) {
			if (rows[i][0] == n) empty_lines ++;
			if (cols[i][0] == n) empty_lines ++;
		}

		int [][] b_rows = new int [n][n];
		for (int j = 0; j <= n-k; j++) {

			for (int  i = 0; i < k; i++) {
				if (rows[i][0] < n && rows[i][0] >= j && rows[i][1] <= j+k-1) b_rows[0][j] ++;
			}
			for (int i = 1; i <= n-k; i++) {
				b_rows[i][j] = b_rows[i-1][j];
				if (rows[i-1][0] < n && rows[i-1][0] >= j && rows[i-1][1] <= j+k-1) b_rows[i][j] --;
				if (rows[i+k-1][0] < n && rows[i+k-1][0] >= j && rows[i+k-1][1] <= j+k-1) b_rows[i][j] ++;
			}
		}

		int [][] b_cols = new int [n][n];
		for (int i = 0; i <= n-k; i++) {

			for (int j = 0; j < k; j++) {
				if (cols[j][0] < n && cols[j][0] >= i && cols[j][1] <= i+k-1) b_cols[i][0] ++;
			}
			for (int j = 1; j <= n-k; j++) {
				b_cols[i][j] = b_cols[i][j-1];
				if (cols[j-1][0] < n && cols[j-1][0] >= i && cols[j-1][1] <= i+k-1) b_cols[i][j] --;
				if (cols[j+k-1][0] < n && cols[j+k-1][0] >= i && cols[j+k-1][1] <= i+k-1) b_cols[i][j] ++;
			}
		}
		int max = 0;
		for (int i = 0; i <= n-k; i++) {
			for (int j = 0;j <= n-k;j++) {
				max = Math.max(max, empty_lines + b_rows[i][j] + b_cols[i][j]);
			}
		}
		out.println(max);
	}

