        boolean[][] cols = new boolean[n][n-k+1];
        for(int i = 0; i < n; i++) {
            int cnt = 0;
            int j = 0;
            for(; j < k; j++) if (!grid[j][i]) cnt++;
            if (needCols[i] == cnt) cols[i][j-k] = true;
            for(; j < n; j++) {
                if (!grid[j][i]) cnt++;
                if (!grid[j-k][i]) cnt--;
                if (needCols[i] == cnt) cols[i][j-k+1] = true;
            }
        }
        boolean[][] rows = new boolean[n][n-k+1];
        for(int i = 0; i < n; i++) {
            int cnt = 0;
            int j = 0;
            for(; j < k; j++) if (!grid[i][j]) cnt++;
            if (needRows[i] == cnt) rows[i][j-k] = true;
            for(; j < n; j++) {
                if (!grid[i][j]) cnt++;
                if (!grid[i][j-k]) cnt--;
                if (needRows[i] == cnt) rows[i][j-k+1] = true;
            }
        }
        int[][] amt = new int[n-k+1][n-k+1];
        for(int i = 0; i <= n-k; i++) {
            int cnt = 0;
            int j = 0;
            for(; j < k; j++) {
                if (cols[j][i]) cnt++;
            }
            amt[j-k][i]+= cnt;
            for(; j < n; j++) {
                if (cols[j][i]) cnt++;
                if (cols[j-k][i]) cnt--;
                amt[j-k+1][i] += cnt;
            }
        }
        for(int i = 0; i <= n-k; i++) {
            int cnt = 0;
            int j = 0;
            for(; j < k; j++) {
                if (rows[j][i]) cnt++;
            }
            amt[i][j-k]+= cnt;
            for(; j < n; j++) {
                if (rows[j][i]) cnt++;
                if (rows[j-k][i]) cnt--;
                amt[i][j-k+1] += cnt;
            }
        }
        int best = 0;
        for(int i =0; i <= n-k; i++) {
            for(int j = 0; j <= n-k; j++) {
                best = Math.max(best, amt[i][j]);
            }
        }
        out.println((ans + best));
        out.flush();
    }

