import java.util.*;
import java.math.*;
import java.io.*;
public class Solution{


    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int[][] c = new int[n][n];
        for(int i=0;i<n;i++){
            String s = sc.next();
            for(int j=0;j<n;j++){
                if(s.charAt(j)=='W') c[i][j] = 1;
                else c[i][j] = 0;
            }
        }


        int[][] row = new int[n][2];
        for(int i=0;i<n;i++) Arrays.fill(row[i],-1);
        for(int i=0;i<n;i++){
            for(int j=0;j<n;j++){
                if(c[i][j]==0){
                    if(row[i][0]==-1) row[i][0] = j;
                    row[i][1] = j;
                }
            }
        }
        int[][] col = new int[n][2];
        for(int i=0;i<n;i++) Arrays.fill(col[i],-1);
        for(int j=0;j<n;j++){
            for(int i=0;i<n;i++){
                if(c[i][j]==0){
                    if(col[j][0]==-1) col[j][0] = i;
                    col[j][1] = i;
                }
            }
        }

        int[][] nbr = new int[n][n-k+1];
        for(int i=0;i<n;i++){
            if(row[i][0]==-1) continue;
            for(int j=0;j<n-k+1;j++){

                if(row[i][0]>=j && row[i][1]<=j+k-1) nbr[i][j] = 1;

            }
        }

        int[][] nbc = new int[n-k+1][n];
        for(int j=0;j<n;j++){
            if(col[j][0]==-1) continue;
            for(int i=0;i<n-k+1;i++){

                if(col[j][0]>=i && col[j][1]<=i+k-1) nbc[i][j] = 1;

            }
        }

        int[][] rep = new int[n-k+1][n-k+1];
        int max = 0;
        for(int j=0;j<n-k+1;j++){
            for(int i=0;i<k;i++){
                rep[0][j] += nbr[i][j];
            }
        }

        for(int j=0;j<n-k+1;j++){
            for(int i=k;i<n;i++){
                rep[i-k+1][j] = rep[i-k][j] + nbr[i][j] - nbr[i-k][j]; 

            }
        }


        int[][] rep2 = new int[n-k+1][n-k+1];

        for(int i=0;i<n-k+1;i++){
            for(int j=0;j<k;j++){
                rep2[i][0] += nbc[i][j];
            }
        }


        for(int i=0;i<n-k+1;i++){
            for(int j=k;j<n;j++){
                rep2[i][j-k+1] = rep2[i][j-k] + nbc[i][j] - nbc[i][j-k]; 
            }
        }


        for(int i=0;i<n-k+1;i++){
            for(int j=0;j<n-k+1;j++){
                rep[i][j] += rep2[i][j];
                max = (int) Math.max(max,rep[i][j]);
            }
        }

        for(int i=0;i<n;i++){
            if(row[i][0]==-1) max++;
            if(col[i][0]==-1) max++;
        }
        System.out.println(max);




    }

}

