			map[i] = br.readLine().toCharArray();
		}
		int[] emptyrow = new int[n];
		for(int i = 0; i < n; i++){
			boolean foundb = false;
			for(int j = 0; j < n; j++){
				if(map[i][j] == 'B') foundb = true;
			}
			if(!foundb) emptyrow[i] = 1;
		}
		int[] emptycol = new int[n];
		for(int j = 0; j < n; j++){
			boolean foundb = false;
			for(int i = 0; i < n; i++){
				if(map[i][j] == 'B') foundb = true;
			}
			if(!foundb) emptycol[j] = 1;
		}
		int[] ecolsleft = new int[n];
		int ac = 0;
		for(int i = 0; i < n; i++){
			ac += emptycol[i];
			ecolsleft[i] = ac;
		}
		int[] ecolsright = new int[n];
		ac = 0;
		for(int i = n-1; i >= 0; i--){
			ac += emptycol[i];
			ecolsright[i] = ac;
		}
		int[] erowsup = new int[n];
		ac = 0;
		for(int i = 0; i < n; i++){
			ac += emptyrow[i];
			erowsup[i] = ac;
		}
		int[] erowsdown = new int[n];
		ac = 0;
		for(int i = n-1; i >= 0; i--){
			ac += emptyrow[i];
			erowsdown[i] = ac;
		}
		int[][] left = new int[n][n];
		for(int i = 0; i < n; i++){
			for(int j = 0; j < n; j++){
				if(j > 0) left[i][j] = left[i][j-1];
				if(map[i][j] == 'B') left[i][j]++;
			}
		}
		int[][] right = new int[n][n];
		for(int i = 0; i < n; i++){
			for(int j = n-1; j >= 0; j--){
				if(j < n-1) right[i][j] = right[i][j+1];
				if(map[i][j] == 'B') right[i][j]++;
			}
		}
		int[][] up = new int[n][n];
		for(int i = 0; i < n; i++){
			for(int j = 0; j < n; j++){
				if(j > 0) up[j][i] = up[j-1][i];
				if(map[j][i] == 'B') up[j][i]++;
			}
		}
		int[][] down = new int[n][n];
		for(int i = 0; i < n; i++){
			for(int j = n-1; j >= 0; j--){
				if(j < n-1) down[j][i] = down[j+1][i];
				if(map[j][i] == 'B') down[j][i]++;
			}
		}
		int[][] errow = new int[n][n];
		int[][] ercol = new int[n][n];
		for(int i = 0; i < n; i++){
			for(int j = 0; j < n; j++){
				if((j + k >= n || right[i][j+k] == 0) && 
						(j == 0 || left[i][j-1] == 0) ) errow[i][j] = 1;
				if((i + k >= n || down[i+k][j] == 0) && 
						(i == 0 || up[i-1][j] == 0) ) ercol[i][j] = 1;
			}
		}
		int[][] cbyrow = new int[n][n];
		for(int i = 0; i < n; i++){
			int acc = 0;
			for(int j = n-1; j >= 0; j--){
				acc += ercol[i][j];
				if(j+k < n) acc -= ercol[i][j+k];
				cbyrow[i][j] = acc;
			}
		}
		int[][] cbycol = new int[n][n];
		for(int i = 0; i < n; i++){
			int acc = 0;
			for(int j = n-1; j >= 0; j--){
				acc += errow[j][i];
				if(j+k < n) acc -= errow[j+k][i];
				cbycol[j][i] = acc;
			}
		}
		int res = 0;
		for(int i = 0; i < n; i++){
			for(int j = 0; j < n; j++){
				int curr = cbycol[i][j] + cbyrow[i][j];
				if(i > 0) curr += erowsup[i-1];
				if(i+k < n) curr += erowsdown[i+k];
				if(j > 0) curr += ecolsleft[j-1];
				if(j+k < n) curr += ecolsright[j+k];
				res = Integer.max(res, curr);
			}
		}
		System.out.println(res);
	}
}

