            for (int j = 1; j <= n; j++) {
                for (int i = 1; i <= n; i++) {
                    if (j + k - 1 <= n) {
                        if (j == 1) {
                            sum[i][j] = ps[i][n] - ps[i][j + k - 1] + k;
                        } else {
                            sum[i][j] = ps[i][n] - ps[i][j + k - 1] + ps[i][j - 1] - ps[i][0] + k;
                        }
                    }
                }
            }


            long big[][] = new long[n + 5][n + 5];
            for (int j = 1; j <= n; j++) {
                int ccc = 0;
                for (int i = 1; i <= k; i++) if (sum[i][j] == n) ccc++;
                int r = k + 1;
                big[1][j] = ccc;
                for (int i = 2; i <= n; i++) {
                    if (i + k - 1 <= n) {
                        if (sum[i - 1][j] == n) ccc--;
                        if (sum[r++][j] == n) ccc++;
                        big[i][j] = ccc;
                    } else {
                        break;
                    }
                }
            }


            long sum_col[][] = new long[n + 5][n + 5];
            ppc = new int[n + 5][n + 5];
            for (int j = 1; j <= n; j++) {
                for (int i = 1; i <= n; i++) {
                    if (arr[i][j] == 'W') ppc[i][j] = 1;
                }
                for (int i = 1; i < n + 5; i++) ppc[i][j] += ppc[i - 1][j];
            }
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (i + k - 1 <= n) {
                        if (i == 1) {
                            sum_col[i][j] = ppc[n][j] - ppc[i + k - 1][j] + k;
                        } else {
                            sum_col[i][j] = ppc[n][j] - ppc[i + k - 1][j] + ppc[i - 1][j] + k;
                        }
                    }
                }
            }


            long bigcol[][] = new long[n + 5][n + 5];
            for (int i = 1; i <= n; i++) {
                int ccc = 0;
                for (int j = 1; j <= k; j++) if (sum_col[i][j] == n) ccc++;
                int r = k + 1;
                bigcol[i][1] = ccc;
                for (int j = 2; j <= n; j++) {
                    if (j + k - 1 <= n) {
                        if (sum_col[i][j - 1] == n) ccc--;
                        if (sum_col[i][r++] == n) ccc++;
                        bigcol[i][j] = ccc;
                    } else {
                        break;
                    }
                }
            }


            long ans = 0;
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (i + k - 1 <= n && j + k - 1 <= n) {
                        long aa = 0;
                        aa += row(1, i - 1) + row(i + k, n) + big[i][j];
                        aa += coll(1, j - 1) + coll(j + k, n) + bigcol[i][j];
                        ans = Math.max(aa, ans);
                    }
                }
            }
            out.println(ans);


        }

        int row(int l, int r) {
            if (l <= r) return raw[r] - raw[l - 1];
            else return 0;
        }

        int coll(int l, int r) {
            if (l <= r) return col[r] - col[l - 1];
            else return 0;
        }

    }

    static class ScanReader {
        private byte[] buf = new byte[4 * 1024];
        private int INDEX;
        private BufferedInputStream in;
        private int TOTAL;

        public ScanReader(InputStream inputStream) {
            in = new BufferedInputStream(inputStream);
        }

        private int scan() {
            if (INDEX >= TOTAL) {
                INDEX = 0;
                try {
                    TOTAL = in.read(buf);
                } catch (Exception e) {
                    e.printStackTrace();
                }
                if (TOTAL <= 0) return -1;
            }
            return buf[INDEX++];
        }

        public int scanInt() {
            int I = 0;
            int n = scan();
            while (isWhiteSpace(n)) n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    I *= 10;
                    I += n - '0';
                    n = scan();
                }
            }
            return neg * I;
        }

        public String scanString() {
            int c = scan();
            while (isWhiteSpace(c)) c = scan();
            StringBuilder RESULT = new StringBuilder();
            do {
                RESULT.appendCodePoint(c);
                c = scan();
            } while (!isWhiteSpace(c));
            return RESULT.toString();
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1) return true;
            else return false;
        }

    }
}

import java.util.Scanner;

public class White_lines {
	public static int solve(int n,int k,int[][] grid) {
		int n_columns=0;
		int n_rows=0;
		int[] in_dp_c=new int[n+1];
		int[] in_dp_r=new int[n+1];


		int[][] dp_row=new int[n][n];
		for(int i=n-1;i>=0;i--) {

			int[] white_cells=new int[n+1];
			if(grid[i][n-1]==1) {
				white_cells[n-1]+=1;
			}
			for(int j=n-2;j>=0;j--) {
				white_cells[j]=white_cells[j+1];
				if(grid[i][j]==1) {
					white_cells[j]+=1;
				}
			}
			if(white_cells[0]==n) {
				n_rows++;

			}
			in_dp_r[i]=n_rows;
			for(int j=n-k;j>=0;j--){
				if(j==0 ) {
					if(    (k+white_cells[j+k]==n)     ) {
						dp_row[i][j]=1;
					}
					continue;
				}
				if(j+k==n) {
					if( (k+white_cells[0]-white_cells[j])==n) {
						dp_row[i][j]=1;
						continue;
					}
				}
				if((j+k)<n) {
				if(  (k+white_cells[j+k] -white_cells[j]+white_cells[0] )==n ) {
					dp_row[i][j]=1;
				}}
			}
		}

		int[][] dp_columns=new int[n][n];
		for(int j=n-1;j>=0;j--) {

			int[] white_cells=new int[n+1];
			if(grid[n-1][j]==1) {
				white_cells[n-1]=1;
			}
			for(int i=n-2;i>=0;i--) {
				white_cells[i]=white_cells[i+1];
				if(grid[i][j]==1) {
					white_cells[i]+=1;
				}
			}
			if(white_cells[0]==n) {
				n_columns++;

			}
			in_dp_c[j]=n_columns;
			for(int i=0;i<n;i++) {
				if(i==0) {
					if(   (k+white_cells[i+k])==n           ) {
						dp_columns[i][j]=1;

					}
					continue;
				}
				if((i+k)<n) {
				if(  (k+ white_cells[0]-white_cells[i]+white_cells[i+k])==n ) {
					dp_columns[i][j]=1;
				}}

				if((i+k)==n) {
					if(  (k+white_cells[0]-white_cells[i])==n       ) {
						dp_columns[i][j]=1;
					}
				}
			}
		}
		int[][] white_rows=new int[n][n];
		int[][] white_columns=new int[n][n];


		int ans=0;



		for(int i=n-k;i>=0;i--) {
			for(int j=n-k;j<n;j++) {

				white_columns[i][n-k]+=dp_columns[i][j];
			}
			ans=Math.max(ans, white_columns[i][n-k]+in_dp_c[0]-in_dp_c[n-k]);
		}

		for(int j=n-k-1;j>=0;j--) {
			for(int i=n-k;i>=0;i--) {
				white_columns[i][j]+=white_columns[i][j+1]+dp_columns[i][j]-dp_columns[i][j+k];
				ans=Math.max(ans, white_columns[i][j]+in_dp_c[0]-in_dp_c[j]+in_dp_c[j+k]);
			}

		}
		for(int j=n-k;j>=0;j--) {
			for(int i=n-k;i<n;i++) {
				white_rows[n-k][j]+=dp_row[i][j];
			}
			ans=Math.max(ans, white_rows[n-k][j]+in_dp_r[0]-in_dp_r[n-k]+white_columns[n-k][j]+in_dp_c[0]-in_dp_c[j]+in_dp_c[j+k]);
		}

		for(int i=n-k-1;i>=0;i--) {
			for(int j=n-k;j>=0;j--) {
				white_rows[i][j]+=white_rows[i+1][j]-dp_row[i+k][j] + dp_row[i][j];
				ans=Math.max(white_rows[i][j]+white_columns[i][j]+in_dp_c[0]-in_dp_c[j]+in_dp_c[j+k]+in_dp_r[0]-in_dp_r[i]+in_dp_r[i+k], ans);
			}
		}
		return ans;
	}

	public static void main(String[] args) {

		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
		int k=s.nextInt();
		int[][] grid=new int[n][n];
		for(int i=0;i<n;i++) {
			String input=s.next();
			for(int j=0;j<n;j++) {
				Character curr=input.charAt(j);
				if(curr=='W'){
						grid[i][j]=1;
				}
				else {
					grid[i][j]=0;
				}
			}
		}
      System.out.println(solve(n, k, grid));
	}

}

