					}
				}
				if(!col[j - k]) {
					if(left[j - k] >= i && right[j - k] <= i + k - 1) {
						already--;
					}
				}
				ans[i][j - k + 1] += already;
			}
		}
		int tem = 0;
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < n; j++) {
				tem = Math.max(tem, ans[i][j]);
			}
		}
		System.out.println(tem);
	}

}

import java.util.*;
public class Generator {
    public static int n, k;
    public static int[][] arr, row, col, cutRow, cutCol, prefCutRow, prefCutCol;
    public static int[] filledRows, filledCols;
    public static int row(int i, int l, int r) {
        if (l > r) {
            return 0;
        }
        if (l == 0) {
            return row[i][r];
        }
        return row[i][r] - row[i][l - 1];
    }
    public static int col(int i, int l, int r) {
        if (l > r) {
            return 0;
        }
        if (l == 0) {
            return col[i][r];
        }
        return col[i][r] - col[i][l - 1];
    }
    public static int rows(int l, int r) {
        if (l > r) {
            return 0;
        }
        if (l == 0) {
            return filledRows[r];
        }
        return filledRows[r] - filledRows[l - 1];
    }
    public static int cols(int l, int r) {
        if (l > r) {
            return 0;
        }
        if (l == 0) {
            return filledCols[r];
        }
        return filledCols[r] - filledCols[l - 1];
    }
    public static int countRows(int i, int l, int r) {
        if (l > r) {
            return 0;
        }
        if (l == 0) {
            return prefCutRow[i][r];
        }
        return prefCutRow[i][r] - prefCutRow[i][l - 1];
    }
    public static int countCols(int i, int l, int r) {
        if (l > r) {
            return 0;
        }
        if (l == 0) {
            return prefCutCol[i][r];
        }
        return prefCutCol[i][r] - prefCutCol[i][l - 1];
    }
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        k = in.nextInt();
        arr = new int[n][n];
        for (int i = 0; i < n; i++) {
            String s = in.next();
            for (int j = 0; j < n; j++) {
                arr[i][j] = (s.charAt(j) == 'W') ? 1 : 0;
            }
        }
        row = new int[n][n];
        col = new int[n][n];
        for (int i = 0; i < n; i++) {
            row[i][0] = arr[i][0];
            for (int j = 1; j < n; j++) {
                row[i][j] = row[i][j - 1] + arr[i][j];
            }
        }
        for (int i = 0; i < n; i++) {
            col[i][0] = arr[0][i];
            for (int j = 1; j < n; j++) {
                col[i][j] = col[i][j - 1] + arr[j][i];
            }
        }
        filledRows = new int[n];
        filledCols = new int[n];
        filledRows[0] = (row[0][n - 1] == n ? 1 : 0);
        for (int i = 1; i < n; i++) {
            filledRows[i] = filledRows[i - 1] + (row[i][n - 1] == n ? 1 : 0);
        }
        filledCols[0] = (col[0][n - 1] == n ? 1 : 0);
        for (int i = 1; i < n; i++) {
            filledCols[i] = filledCols[i - 1] + (col[i][n - 1] == n ? 1 : 0);
        }
        cutRow = new int[n][n];
        cutCol = new int[n][n];
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j < n; j++) {
                int val = row(j, 0, i - 1) + row(j, i + k, n - 1);
                if (val + k == n) {
                    cutRow[i][j] = 1;
                }
            }
        }
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j < n; j++) {
                int val = col(j, 0, i - 1) + col(j, i + k, n - 1);
                if (val + k == n) {
                    cutCol[i][j] = 1;
                }
            }
        }
        prefCutRow = new int[n][n];
        prefCutCol = new int[n][n];
        for (int i = 0; i <= n - k; i++) {
            prefCutRow[i][0] = cutRow[i][0];
            for (int j = 1; j < n; j++) {
                prefCutRow[i][j] = prefCutRow[i][j - 1] + cutRow[i][j];
            }
        }
        for (int i = 0; i <= n - k; i++) {
            prefCutCol[i][0] = cutCol[i][0];
            for (int j = 1; j < n; j++) {
                prefCutCol[i][j] = prefCutCol[i][j - 1] + cutCol[i][j];
            }
        }
        int best = 0;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                int cnt = 0;
                cnt += countRows(j, i, i + k - 1);
                cnt += countCols(i, j, j + k - 1);
                cnt += (rows(0, i - 1) + rows(i + k, n - 1));
                cnt += (cols(0, j - 1) + cols(j + k, n - 1));
                best = Math.max(best, cnt);
            }
        }
        System.out.println(best);
    }
}

import java.util.*;
import java.io.*;
import java.math.*;
public class Solution{
    public static void main(String[] args)throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int[] rmin = new int[n];
        int[] rmax = new int[n];
        int[] cmin = new int[n];
        int[] cmax = new int[n];
        Arrays.fill(rmin,-1);
        Arrays.fill(rmax,-1);
        Arrays.fill(cmin,-1);
        Arrays.fill(cmax,-1);
        for(int i=0;i<n;i++){
            st = new StringTokenizer(br.readLine());
            char[] c = st.nextToken().toCharArray();
            for(int j=0;j<n;j++){
                if(c[j]=='B'){
                    if(rmin[i]==-1) rmin[i] = j;
                    if(cmin[j]==-1) cmin[j] = i;
                    rmax[i] = j;
                    cmax[j] = i;
                }
            }
        }
        int res = 0;
        for(int i=0;i<n;i++){
            if(rmin[i]==-1) res++;
            else if(rmax[i]-rmin[i]+1>k){
                rmax[i] = -1;
                rmin[i] = -1;
            }
            if(cmin[i]==-1) res++;
            else if(cmax[i]-cmin[i]+1>k){
                cmax[i] = -1;
                cmin[i] = -1;
            }
        }
        int[][] srmin = new int[n][n];
        int[][] srmax = new int[n][n];
        int[][] scmin = new int[n][n];
        int[][] scmax = new int[n][n];
        for(int i=0;i<n;i++){
            if(rmin[i]!=-1) srmin[i][rmin[i]] = 1;
            if(rmax[i]!=-1) srmax[i][rmax[i]] = 1;
            if(cmin[i]!=-1) scmin[cmin[i]][i] = 1;
            if(cmax[i]!=-1) scmax[cmax[i]][i] = 1;
        }
        for(int i=0;i<n;i++){
            for(int j=1;j<n;j++){
                srmin[j][i] += srmin[j-1][i];
                srmax[j][i] += srmax[j-1][i];
                scmin[i][j] += scmin[i][j-1];
                scmax[i][j] += scmax[i][j-1];
            }
        }
        int[][] dp = new int[n-k+1][n-k+1];
        for(int i=0;i<k;i++){
            dp[0][0] += srmax[k-1][i];
            dp[0][0] += scmax[i][k-1];
        }
        for(int i=0;i<n-k+1;i++){
            for(int j=0;j<n-k+1;j++){
                if(i==0&&j==0) continue;
                if(j==0){
                    dp[i][j] = dp[i-1][j];
                    dp[i][j] += scmax[i+k-1][j+k-1];
                    dp[i][j] -= scmin[i-1][j+k-1];
                    if(rmin[i-1]>=j&&rmax[i-1]<j+k) dp[i][j]--;
                    if(rmin[i+k-1]>=j&&rmax[i+k-1]<j+k) dp[i][j]++;
                }else{
                    dp[i][j] = dp[i][j-1];
                    dp[i][j] += srmax[i+k-1][j+k-1];
                    if(i>0) dp[i][j] -= srmax[i-1][j+k-1];
                    dp[i][j] -= srmin[i+k-1][j-1];
                    if(i>0) dp[i][j] += srmin[i-1][j-1];
                    if(cmin[j-1]>=i&&cmax[j-1]<i+k) dp[i][j]--;
                    if(cmin[j+k-1]>=i&&cmax[j+k-1]<i+k) dp[i][j]++;
                }
            }
        }

        int max = 0;
        for(int i=0;i<=n-k;i++){
            for(int j=0;j<=n-k;j++){
                max = Math.max(max,dp[i][j]);

            }
        }

        res += max;
        out.println(res);
        out.flush(); 
    }
}

