    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            String[] screen = new String[n];
            for (int i = 0; i < n; ++i) {
                screen[i] = in.next();
            }

            int[] firstB = new int[n];
            int[] lastB = new int[n];
            int countW = 0;


            for (int i = 0; i < n; ++i) {
                firstB[i] = -1;
                for (int j = 0; j < n && firstB[i] < 0; ++j) {
                    if (screen[i].charAt(j) == 'B') {
                        firstB[i] = j;
                    }
                }
                lastB[i] = n;
                if (firstB[i] < 0) ++countW;
                else {
                    for (int j = n - 1; j >= 0 && lastB[i] >= n; --j) {
                        if (screen[i].charAt(j) == 'B') {
                            lastB[i] = j;
                        }
                    }
                }
            }

            int[][] vr = new int[n][n];
            for (int j = 0; j + k - 1 < n; ++j) {
                int[] v = new int[n];
                for (int i = 0; i < n; ++i) {
                    v[i] = (j <= firstB[i] && lastB[i] <= j + k - 1) ? 1 : 0;
                }
                int sum = 0;
                for (int i = 0; i < k - 1; ++i) {
                    sum += v[i];
                }
                for (int i = 0; i + k - 1 < n; ++i) {
                    sum += v[i + k - 1];
                    vr[i][j] = sum;
                    sum -= v[i];
                }
            }


            for (int j = 0; j < n; ++j) {
                firstB[j] = -1;
                for (int i = 0; i < n && firstB[j] < 0; ++i) {
                    if (screen[i].charAt(j) == 'B') {
                        firstB[j] = i;
                    }
                }
                lastB[j] = n;
                if (firstB[j] < 0) ++countW;
                else {
                    for (int i = n - 1; i >= 0 && lastB[j] >= n; --i) {
                        if (screen[i].charAt(j) == 'B') {
                            lastB[j] = i;
                        }
                    }
                }
            }

            int[][] vc = new int[n][n];
            for (int i = 0; i + k - 1 < n; ++i) {
                int[] v = new int[n];
                for (int j = 0; j < n; ++j) {
                    v[j] = (i <= firstB[j] && lastB[j] <= i + k - 1) ? 1 : 0;
                }
                int sum = 0;
                for (int j = 0; j < k - 1; ++j) {
                    sum += v[j];
                }
                for (int j = 0; j + k - 1 < n; ++j) {
                    sum += v[j + k - 1];
                    vc[i][j] = sum;
                    sum -= v[j];
                }
            }


            int res = 0;
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    res = Math.max(res, vr[i][j] + vc[i][j]);
                }
            }
            out.print(res + countW);
        }

    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

