					c[j][1] = i;
					if(c[j][0]==-1) c[j][0]=i;
				}
			}
		}
		int w = 0;
		for(int i=N-1;i>=0;i--) {
			if(r[i][0]==-1) w++;;
			if(c[i][0]==-1) w++;
		}
		int[][] col = new int[N][N];
		int[][] row = new int[N][N];
		for(int i=N-1;i>=0;i--) {
			for(int j=N-1;j>=0;j--) {
				if(i<=N-k) {
					if(c[j][0]>=i && c[j][1]<i+k) col[i][j]++;
				}
				if(j<=N-k) {
					if(r[i][0]>=j &&r[i][1]<j+k) row[i][j]++;
				}
			}
		}
		for(int i=N-1;i>=0;i--) {
			for(int j=N-2;j>=0;j--) {
				col[i][j] += col[i][j+1];
			}
		}
		for(int i=N-2;i>=0;i--) {
			for(int j=N-1;j>=0;j--) {
				row[i][j] += row[i+1][j];
			}
		}
		Integer max = 0;
		for(int i=N-k;i>=0;i--) {
			for(int j=N-k;j>=0;j--) {
				int v = col[i][j]+row[i][j];
				if((i+k)<N) {
					v-= row[i+k][j];
				}
				if((j+k)<N) {
					v-= col[i][j+k];
				}
				max = Math.max(max, v);
			}
		}
		System.out.println((max+w));
	}

}

