public class Codeforces1200D {

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(br.readLine());
		int n = Integer.parseInt(st.nextToken());
		int k = Integer.parseInt(st.nextToken());


		boolean[][] grid = new boolean[n][n];
		for (int i = 0; i < n; i++) {
			st = new StringTokenizer(br.readLine());
			String s = st.nextToken();
			for (int j = 0; j < n; j++) {
				if (s.charAt(j) == 'W') {
					grid[i][j] = true;
				}
			}
		}

		int ctr = 0;

		int[][] horizontal = new int[n][n-k+1];
		for (int i = 0; i < n; i++) {
			int firstBlack = -1;
			int lastBlack = -1;
			for (int j = 0; j < n; j++) {
				if (!(grid[i][j])) {
					lastBlack = j;
					if (firstBlack == -1) {
						firstBlack = j;
					}
				}
			}

			if (firstBlack == -1) {
				ctr++;
			}
			else {
				for (int j = Math.max(0, lastBlack-k+1); j < Math.min(n-k+1, firstBlack+1); j++) {
					horizontal[i][j] = 1;
				}
			}
		}

		int[][] vertical = new int[n-k+1][n];
		for (int i = 0; i < n; i++) {
			int firstBlack = -1;
			int lastBlack = -1;
			for (int j = 0; j < n; j++) {
				if (!(grid[j][i])) {
					lastBlack = j;
					if (firstBlack == -1) {
						firstBlack = j;
					}
				}
			}

			if (firstBlack == -1) {
				ctr++;
			}
			else {
				for (int j = Math.max(0, lastBlack-k+1); j < Math.min(n-k+1, firstBlack+1); j++) {
					vertical[j][i] = 1;
				}
			}
		}

		int[][] thing = new int[n-k+1][n-k+1];

		for (int i = 0; i < n-k+1; i++) {
			for (int j = 0; j < k; j++) {
				thing[0][i] += horizontal[j][i];
			}
			for (int j = 1; j < n-k+1; j++) {
				thing[j][i] = thing[j-1][i] - horizontal[j-1][i] + horizontal[j+k-1][i];
			}
		}

		int[][] stuff = new int[n-k+1][n-k+1];
		for (int i = 0; i < n-k+1; i++) {
			for (int j = 0; j < k; j++) {
				stuff[i][0] += vertical[i][j];
			}
			for (int j = 1; j < n-k+1; j++) {
				stuff[i][j] = stuff[i][j-1] - vertical[i][j-1] + vertical[i][j+k-1];
			}
		}

		int max = 0;
		for (int i = 0; i < n-k+1; i++) {
			for (int j = 0; j < n-k+1; j++) {
				max = Math.max(max, stuff[i][j] + thing[i][j]);
			}
		}
		System.out.println(max+ctr);
	}

}

