    static class DWhiteLines {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int k = in.readInt();
            String[] b = in.readStringArray(n);
            boolean[][][] s = new boolean[4][n + 2][n + 2];
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < n + 2; j++) {
                    Arrays.fill(s[i][j], true);
                }
            }
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < n; j++) {
                    for (int l = 0; l < n; l++) {
                        s[i][j + 1][l + 1] = b[j].charAt(l) == 'W';
                    }
                }
            }

            int sum = 0;
            int[] sumY = new int[n + 1];
            int[] sumX = new int[n + 1];
            for (int i = 0; i < n; i++) {
                boolean all = true;
                for (int j = 0; j < n; j++) {
                    all &= b[i].charAt(j) == 'W';
                }
                if (all) {
                    sumY[i + 1] = 1;
                    sum++;
                }
            }
            for (int i = 0; i < n; i++) {
                boolean all = true;
                for (int j = 0; j < n; j++) {
                    all &= b[j].charAt(i) == 'W';
                }
                if (all) {
                    sumX[i + 1] = 1;
                    sum++;
                }
            }
            for (int i = 0; i < n; i++) {
                sumY[i + 1] += sumY[i];
                sumX[i + 1] += sumX[i];
            }

            for (int i = 0; i < n + 2; i++) {
                for (int j = 0; j < n + 1; j++) {
                    s[0][i][j + 1] &= s[0][i][j];
                    s[1][i][n - j] &= s[1][i][n - j + 1];
                    s[2][j + 1][i] &= s[2][j][i];
                    s[3][n - j][i] &= s[3][n - j + 1][i];
                }
            }

            int[][][] cnt = new int[2][n + 2][n + 2];
            for (int i = 1; i < n + 1; i++) {
                for (int j = 1; j < n + 1; j++) {
                    if (j + k >= n + 2) continue;
                    cnt[0][i][j] = s[0][i][j - 1] & s[1][i][j + k] ? 1 : 0;
                    cnt[1][j][i] = s[2][j - 1][i] & s[3][j + k][i] ? 1 : 0;
                }
            }
            for (int i = 0; i < n + 2; i++) {
                for (int j = 0; j < n + 1; j++) {
                    cnt[0][j + 1][i] += cnt[0][j][i];
                    cnt[1][i][j + 1] += cnt[1][i][j];
                }
            }

            int ans = 0;
            for (int i = 1; i <= n - k + 1; i++) {
                for (int j = 1; j <= n - k + 1; j++) {
                    int tmp = sum - (sumY[i + k - 1] - sumY[i - 1] + sumX[j + k - 1] - sumX[j - 1]);
                    tmp += cnt[0][i + k - 1][j] - cnt[0][i - 1][j];
                    tmp += cnt[1][i][j + k - 1] - cnt[1][i][j - 1];
                    ans = Math.max(ans, tmp);
                }
            }

            out.printLine(ans);
        }

    }

