public class D {
    public static void main(String[] args) throws Exception {
        BufferedReader bf = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        StringTokenizer st = new StringTokenizer(bf.readLine());

        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int[][] a = new int[n][n];
        int[][] cum = new int[n+1][n+1];
        for(int i=0; i<n; i++) {
          String s = bf.readLine();
          for(int j=0; j<n; j++) {
            if(s.charAt(j)=='B') a[i][j] = 0;
            else a[i][j] = 1;
          }
        }
        for(int i=0; i<n; i++) {
          int min_j = n;
          int max_j = -1;
          for(int j=0; j<n; j++) {
            if(a[i][j]==0) {
              max_j = j;
              if(min_j == n) min_j = j;
            }
          }
          if(min_j == n) {
            cum[0][0] += 1;
            cum[n][n] += 1;
            cum[n][0] += -1;
            cum[0][n] += -1;
          }
          else {
            if(max_j - min_j >= k) continue;
            cum[Math.max(0, i-k+1)][Math.max(0, max_j-k+1)] += 1;
            cum[i+1][min_j+1] += 1;
            cum[Math.max(0, i-k+1)][min_j+1] -= 1;
            cum[i+1][Math.max(0, max_j-k+1)] -= 1;
          }

        }
        for(int j=0; j<n; j++) {
          int min_i = n;
          int max_i = -1;
          for(int i=0; i<n; i++) {
            if(a[i][j]==0) {
              max_i = i;
              if(min_i == n) min_i = i;
            }
          }
          if(min_i == n) {
            cum[0][0] += 1;
            cum[n][n] += 1;
            cum[n][0] += -1;
            cum[0][n] += -1;
          }
          else {
            if(max_i - min_i >= k) continue;
            cum[Math.max(0, max_i-k+1)][Math.max(0, j-k+1)] += 1;
            cum[min_i+1][j+1] += 1;
            cum[Math.max(0, max_i-k+1)][j+1] -= 1;
            cum[min_i+1][Math.max(0, j-k+1)] -= 1;
          }

        }
        int max = 0;
        for(int i=1; i<n; i++) cum[0][i] += cum[0][i-1];
        for(int i=1; i<n; i++) cum[i][0] += cum[i-1][0];
        for(int i=1; i<n; i++)
          for(int j=1; j<n; j++)
            cum[i][j] += cum[i-1][j] + cum[i][j-1] - cum[i-1][j-1];

        for(int i=0; i<n; i++)
          for(int j=0; j<n; j++)
            if(cum[i][j] > max) max = cum[i][j];
        out.println(max);

        out.close(); System.exit(0);
    }
}

import java.io.*;
import java.util.*;

public class F {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(reader.readLine());
        int n  = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int[] lx = new int[n];
        int[] rx = new int[n];
        int[] ly = new int[n];
        int[] ry = new int[n];
        for(int i = 0; i < n; ++i){
            lx[i] = rx[i] = ly[i] = ry[i] = -1;
        }
        for(int i = 0; i < n; ++i){
            char[] b = reader.readLine().toCharArray();
            for(int j = 0; j < n; ++j){
                if(b[j] == 'B'){
                    if(lx[i] == -1 || lx[i] > j) {
                        lx[i] = j;
                    }
                    rx[i] = Math.max(rx[i], j);
                    if(ly[j] == -1 || ly[j] > i) {
                        ly[j] = i;
                    }
                    ry[j] = Math.max(ry[j], i);
                }
            }
        }
        int ans = 0;
        int max = 0;
        for(int i = 0; i < n; ++i){
            if(lx[i] == -1){
                ++ans;
            }
            if(ly[i] == -1){
                ++ans;
            }
        }
        for(int i = 0; i < n - k + 1; ++ i){
            TreeMap<Integer, Integer> lefts = new TreeMap<>();
            TreeMap<Integer, Integer> rights = new TreeMap<>();
            int strs = 0;
            TreeSet<Integer> stolbs = new TreeSet<>();
            for(int j = i; j < i + k; ++j){
                if(lx[j] != -1 && rx[j] - lx[j] < k){
                    lefts.put(lx[j], lefts.getOrDefault(lx[j], 0) + 1);
                    rights.put(rx[j], rights.getOrDefault(rx[j], 0) + 1);
                    if(rx[j] <= k - 1){
                        ++strs;
                    }
                }
            }
            for(int j = 0; j < k; ++j){
                if(ry[j] < i + k && ly[j] >= i){
                    stolbs.add(j);
                }
            }
            max = Math.max(max, stolbs.size() + strs + ans);
            for(int j = k; j < n; ++j){
                stolbs.remove(j - k);
                strs -= lefts.getOrDefault(j - k, 0);
                strs += rights.getOrDefault(j, 0);
                if(ry[j] < i + k && ly[j] >= i){
                    stolbs.add(j);
                }
                max = Math.max(max, stolbs.size() + strs + ans);
            }
        }
        System.out.println(max);
        writer.close();
    }
}

