        int[] lx = new int[n];
        int[] rx = new int[n];
        boolean[] rowHasBlack = new boolean[n];
        int[] ly = new int[n];
        int[] ry = new int[n];
        boolean[] columnHasBlack = new boolean[n];
        for (int x = 0; x < n; x++) {
            ly[x] = 0;
            ry[x] = n - 1;
        }
        for (int y = 0; y < n; y++) {
