                    max[i] = Math.max(j, max[i]);
                }
            }

            if(min[i] == Integer.MAX_VALUE)
                set.add(i);
        }

        for(int j=0; j<=n-k; j++){

            int start = j, end = j+k-1;

            arr2[0][j] += set.size();
            for(int i=0; i<k; i++){
                if(!set.contains(i) && start <= min[i] && max[i] <= end)
                    arr2[0][j]++;
