import java.util.Arrays;
import java.util.Scanner;

public class WhiteLines {
	public static void main(String[] args) {
		Scanner scan=new Scanner(System.in);
		int n=scan.nextInt(), k=scan.nextInt()-1;
		int[][] a=new int[n][n];
		for(int i=0;i<n;i++) {
			String s=scan.next();
			for(int j=0;j<n;j++) {
				if(s.charAt(j)=='B') a[i][j]++;
			}
		}
		pre(a,n);

		int[][] canRow=new int[n][n], canCol=new int[n][n];

		int perfect=0;
		for(int i=0;i<n;i++) {
			for(int j=0;j<n;j++) {
				int total=ct(i,0,i,n-1,a);
				if(j+k<n&&ct(i,j,i,j+k,a)==total&&total>0) canRow[i][j]=1;
				else if(total==0&&j==0) perfect++;
			}
		}
		for(int i=0;i<n;i++) {
			for(int j=0;j<n;j++) {
				int total=ct(0,j,n-1,j,a);
				if(i+k<n&&ct(i,j,i+k,j,a)==total&&total>0) canCol[i][j]=1;
				else if(total==0&&i==0) perfect++;
			}
		}




		pre(canRow,n);
		pre(canCol,n);

		int res=0;
		for(int i=0;i<n;i++) {
			for(int j=0;j<n;j++) {
				if(i+k<n&&j+k<n) {
					res=Math.max(res,ct(i,j,i+k,j,canRow)+ct(i,j,i,j+k,canCol)+perfect);
				}
			}
		}
		System.out.println(res);
	}
	public static int ct(int i1, int j1, int i2, int j2, int[][] a) {
		int res=a[i2][j2];
		if(i1>0) res-=a[i1-1][j2];
		if(j1>0) res-=a[i2][j1-1];
		if(i1>0&&j1>0) res+=a[i1-1][j1-1];
		return res;
	}
	public static void pre(int[][] a, int n) {
		for(int i=0;i<n;i++) {
			for(int j=1;j<n;j++) {
				a[i][j]+=a[i][j-1];
			}
		}
		for(int j=0;j<n;j++) {
			for(int i=1;i<n;i++) {
				a[i][j]+=a[i-1][j];
			}
		}
	}
}

