import java.io.InputStream;


public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.readInt(), k = in.readInt();
            char[][] charTable = in.readTable(n, n);
            int[][] intTable = new int[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    intTable[i][j] = charTable[i][j] == 'W' ? 0 : 1;
                }
            }
            Repainter rowsRepainter = new Repainter(k, intTable, false);
            Repainter columnsRepainter = new Repainter(k, intTable, true);
            int initialWhiteLines = rowsRepainter.getWhiteLinesAmount() + columnsRepainter.getWhiteLinesAmount();
            int maxWhiteLines = initialWhiteLines;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    int newWhiteRows = rowsRepainter.getNewWhitesIfRepaintFrom(i, j);
                    int newWhiteColumns = columnsRepainter.getNewWhitesIfRepaintFrom(i, j);
                    maxWhiteLines = Math.max(maxWhiteLines, initialWhiteLines + newWhiteColumns + newWhiteRows);
                }
            }
            out.println(maxWhiteLines);
        }

        private class Repainter {
            int[][] repainterTable;
            int whiteLinesAmount;

            public Repainter(int k, int[][] intTable, boolean isColumns) {
                if (!isColumns) {
                    this.repainterTable = createPrecalcedRepainter(k, intTable);
                } else {
                    this.repainterTable = createTransposedMatrix(createPrecalcedRepainter(k, createTransposedMatrix(intTable)));
                }
            }

            private int[][] createTransposedMatrix(int[][] intTable) {
                int[][] transposedTable = new int[intTable.length][intTable.length];
                for (int i = 0; i < intTable.length; i++) {
                    for (int j = 0; j < intTable.length; j++) {
                        transposedTable[i][j] = intTable[j][i];
                    }
                }
                return transposedTable;
            }

            private int[][] createPrecalcedRepainter(int k, int[][] intTable) {
                int[][] precalcedLines = new int[intTable.length][intTable.length];
                for (int i = 0; i < intTable.length; i++) {
                    int[] row = intTable[i];
                    int[] pref = new int[row.length + 1];
                    int[] suf = new int[row.length + 1];
                    for (int j = 0; j < row.length; j++) {
                        pref[j + 1] = pref[j] + row[j];
                        int sufInd = row.length - 1 - j;
                        suf[sufInd] = suf[sufInd + 1] + row[sufInd];
                    }
                    int[] precalcedLine = new int[row.length];
                    if (pref[row.length] == 0) {
                        precalcedLines[i] = precalcedLine;
                        whiteLinesAmount++;
                    } else {
                        int[] whitableLine = new int[row.length];
                        for (int j = 0; j < row.length - k + 1; j++) {
                            if ((pref[j] == 0) && (suf[j + k] == 0)) {
                                whitableLine[j] = 1;
                            }
                        }
                        precalcedLines[i] = whitableLine;
                    }
                }
                int[][] precalcedRepainter = new int[intTable.length][intTable.length];
                for (int j = 0; j < intTable.length; j++) {
                    int[] pref = new int[intTable.length + 1];
                    int[] columnSegmSums = new int[intTable.length];
                    for (int i = 0; i < intTable.length; i++) {
                        pref[i + 1] = pref[i] + precalcedLines[i][j];
                    }
                    for (int i = 0; i < intTable.length - k + 1; i++) {
                        columnSegmSums[i] = pref[i + k] - pref[i];
                    }
                    for (int i = 0; i < intTable.length; i++) {
                        precalcedRepainter[i][j] = columnSegmSums[i];
                    }
                }
                return precalcedRepainter;
            }

            public int getNewWhitesIfRepaintFrom(int row, int col) {
                return repainterTable[row][col];
            }

            public int getWhiteLinesAmount() {
                return whiteLinesAmount;
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public char[] readCharArray(int size) {
            char[] array = new char[size];
            for (int i = 0; i < size; i++) {
                array[i] = readCharacter();
            }
            return array;
        }

        public char[][] readTable(int rowCount, int columnCount) {
            char[][] table = new char[rowCount][];
            for (int i = 0; i < rowCount; i++) {
                table[i] = this.readCharArray(columnCount);
            }
            return table;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int inf = (int) 1e9;
    static int n, k, a[][];
    static int ver[][], hor[][];
    static int min_ans = 0;
    static void scan() throws IOException {
        n = nextInt();
        k = nextInt();
        char h[][] = new char[n][n];
        a = new int [n][n];
        ver = new int [2][n];
        hor = new int [2][n];
        for(int i = 0;i < n;i++) {
            h[i] = next().toCharArray();
            for(int j = 0;j < n;j++) {
                if (h[i][j] == 'W') a[i][j] = 0;
                else a[i][j] = 1;
            }
        }
        for(int i = 0;i < n;i++) {
            ver[1][i] = inf;
            hor[1][i] = inf;
            for(int j = 0;j < n;j++) {
                if (a[i][j] == 1) hor[1][i] = j;
                if (a[j][i] == 1) ver[1][i] = j;
            }
            for(int j = n - 1;j >= 0;j--) {
                if (a[i][j] == 1) hor[0][i] = j;
                if (a[j][i] == 1) ver[0][i] = j;
            }
            if (hor[1][i] == inf) min_ans++;
            if (ver[1][i] == inf) min_ans++;
        }
    }

    static int solve() {
        int ans = 0;
        for(int i = 0;i + k <= n;i++) {
            segment_tree a = new segment_tree(n);
            int b[] = new int [n];
            for(int j = 0;j < n;j++) if (ver[0][j] >= i && ver[1][j] < i + k) b[j] = 1;
            int sum = 0;
            for(int j = 0;j < k;j++) sum += b[j];
            a.add(0, 0, sum);
            for(int j = k;j < n;j++) {
                sum += b[j] - b[j - k];
                a.add(j - k + 1, j - k + 1, sum);
            }
            for(int j = i;j < i + k;j++) {
                if (hor[1][j] - hor[0][j] > k) continue;
                a.add(hor[1][j] - k + 1, hor[0][j], 1);
            }
            ans = Math.max(ans, min_ans + a.get());
        }
        return ans;
