class segment_tree {
    int max[], last;
    int push[];
    segment_tree(int n) {
        last = n - 1;
        max = new int [4 * n];
        push = new int [4 * n];
    }

    void pushing(int v) {
        push[v * 2 + 1] += push[v];
        push[v * 2 + 2] += push[v];
        max[v * 2 + 1] += push[v];
        max[v * 2 + 2] += push[v];
        push[v] = 0;
    }

    void add(int l, int r, int sum) {
        add(0, 0, last, l, r, sum);
    }

    void add(int v, int l, int r, int left, int right, int sum) {
        if (l > right || r < left) return;
        if (l >= left && r <= right) {
            max[v] += sum;
            push[v] += sum;
            return;
        }
        pushing(v);
        int m = ((l + r) >> 1);
        add(v * 2 + 1, l, m, left, right, sum);
        add(v * 2 + 2, m + 1, r, left, right, sum);
        max[v] = Math.max(max[v * 2 + 1], max[v * 2 + 2]);
    }

    int get() {
        return max[0];
    }
}

