        for(int i = 0; i < n; i++) {
            if(maxBCol[i] == -1) tot++;
            if(maxBRow[i] == -1) tot++;

            if(maxBCol[i] != -1 && maxBCol[i]-minBCol[i]+1 <= k) {
                int diff = k-(maxBCol[i]-minBCol[i]+1);
                int less = Math.max(0, minBCol[i]-diff);
                for(int j = i; j >= 0 && j > i-k; j--) {
                    cols[j][less]++;
                    cols[j][minBCol[i]+1]--;
                }
            }

            if(maxBRow[i] != -1 && maxBRow[i]-minBRow[i]+1 <= k) {
