                    rows[j][less]++;
                    rows[j][minBRow[i]+1]--;
                }
            }
        }

        for(int i = 0; i < n; i++) {
            for(int j = 1; j < n+2; j++) {
                rows[i][j] += rows[i][j-1];
                cols[i][j] += cols[i][j-1];
            }
