    static class SuperBIT {

        long[] dataMul, dataAdd;

        SuperBIT(int n) {
            dataMul = new long[n];
            dataAdd = new long[n];
        }

        void update(int left, int right, long val) {
            internalUpdate(left, val, -val * (left - 1));
            internalUpdate(right, -val, val * right);
        }

        void internalUpdate(int at, long mul, long add) {
            while (at < dataMul.length) {
                dataMul[at] += mul;
                dataAdd[at] += add;
                at |= (at + 1);
            }
        }

        long query(int at) {
            long mul = 0;
            long add = 0;
            int start = at;
            while (at >= 0) {
                mul += dataMul[at];
                add += dataAdd[at];
                at = (at & (at + 1)) - 1;
            }
            return mul * start + add;
        }

        long query(int left, int right) {
            if (left > right) {
                int temp = left;
                left = right;
                right = temp;
            }
            return query(right) - (left > 0 ? query(left - 1) : 0);
        }
    }

    static class FS {

        BufferedReader in;
        StringTokenizer token;

        public FS(InputStream str) {
            in = new BufferedReader(new InputStreamReader(str));
        }

        public String next() {
            if (token == null || !token.hasMoreElements()) {
                try {
                    token = new StringTokenizer(in.readLine());
                } catch (IOException ex) {
                }
                return next();
            }
            return token.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

