        }

        int[][] upBonusAcc = new int[n][];
        int[][] leftBonusAcc = new int[n][];

        for (int i = 0; i < n; i++) {
            upBonusAcc[i] = new int[n];
            leftBonusAcc[i] = new int[n];
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                upBonusAcc[i][j] = ((j > 0) ? upBonusAcc[i][j - 1] : 0) + upBonus[i][j];
                leftBonusAcc[i][j] = ((i > 0) ? leftBonusAcc[i - 1][j] : 0) + leftBonus[i][j];
            }
        }

        int best = 0;
        for (int i = 0; i < n - k; i++) {
            for (int j = 0; j < n - k; j++) {
                int bonus = upBonusAcc[i][j + k] - ((j > 0) ? upBonusAcc[i][j - 1] : 0)
                        + leftBonusAcc[i + k][j] - ((i > 0) ? leftBonusAcc[i - 1][j] : 0);
                best = Math.max(best, bonus);
            }
        }

        int initial = 0;
        for (int i = 0; i < n; i++) {
            if (accV[n - 1][i] == 0) ++initial;
            if (accH[i][n - 1] == 0) ++initial;
        }







































        System.out.println(best + initial);
    }
}

