class Solver {
    IO io = new IO(System.in, System.out);

    int N, K;
    boolean[][] grid;

    void solve() throws Exception {
        int i, j, k;

        N = io.nextInt(); K = io.nextInt();
        grid = new boolean[N][N];
        for (i = 0; i < N; ++i) {
            String row = io.next();
            for (j = 0; j < N; ++j) grid[i][j] = row.charAt(j) == 'B';
        }

        ans = new int[N][N];

        for (i = 0; i < N; ++i) {
            int min = N + 7, max = -7;
            for (j = 0; j < N; ++j) if (grid[i][j]) {
                min = Math.min(min, j); max = Math.max(max, j);
            }

            if (min > max) update(0, 0, N - 1, N - 1);
            else if (max - min < K) {
                update(i - K + 1, max - K + 1, i, min);
            }
        }
        for (j = 0; j < N; ++j) {
            int min = N + 7, max = -7;
            for (i = 0; i < N; ++i) if (grid[i][j]) {
                min = Math.min(min, i); max = Math.max(max, i);
            }

            if (min > max) update(0, 0, N - 1, N - 1);
            else if (max - min < K) {
                update(max - K + 1, j - K + 1, min, j);
            }
        }

        for (i = 0; i < N; ++i) for (j = 1; j < N; ++j) ans[i][j] += ans[i][j - 1];
        for (i = 1; i < N; ++i) for (j = 0; j < N; ++j) ans[i][j] += ans[i - 1][j];



        long finalAns = 0;
        for (i = 0; i < N; ++i) for (j = 0; j < N; ++j) finalAns = Math.max(finalAns, ans[i][j]);
        io.println(finalAns);

        io.flush();
    }

    int[][] ans;

    void update(int i1, int j1, int i2, int j2) {
        int i, j, k;
        i1 = Math.max(i1, 0); i2 = Math.min(i2, N - 1);
        j1 = Math.max(j1, 0); j2 = Math.min(j2, N - 1);



        ++ans[i1][j1];
        if (i2 + 1 < N && j2 + 1 < N) ++ans[i2 + 1][j2 + 1];
        if (i2 + 1 < N) --ans[i2 + 1][j1];
        if (j2 + 1 < N) --ans[i1][j2 + 1];
    }
}


class IO {
    static byte[] buf = new byte[2048];
    static int index, total;
    static InputStream in;
    static BufferedWriter bw;


    IO(InputStream is, OutputStream os) {
        try {
            in = is;
            bw = new BufferedWriter(new OutputStreamWriter(os));
        } catch (Exception e) {
        }
    }

    IO(String inputFile, String outputFile) {
        try {
            in = new FileInputStream(inputFile);
            bw = new BufferedWriter(new OutputStreamWriter(
                    new FileOutputStream(outputFile)));
        } catch (Exception e) {
        }
    }

    int scan() throws Exception {
        if (index >= total) {
            index = 0;
            total = in.read(buf);
            if (total <= 0)
                return -1;
        }
        return buf[index++];
    }

    String next() throws Exception {
        int c;
        for (c = scan(); c <= 32; c = scan()) ;
        StringBuilder sb = new StringBuilder();
        for (; c > 32; c = scan())
            sb.append((char) c);
        return sb.toString();
    }

    int nextInt() throws Exception {
        int c, val = 0;
        for (c = scan(); c <= 32; c = scan()) ;
        boolean neg = c == '-';
        if (c == '-' || c == '+')
            c = scan();
        for (; c >= '0' && c <= '9'; c = scan())
            val = (val << 3) + (val << 1) + (c & 15);
        return neg ? -val : val;
    }

    long nextLong() throws Exception {
        int c;
        long val = 0;
        for (c = scan(); c <= 32; c = scan()) ;
        boolean neg = c == '-';
        if (c == '-' || c == '+')
            c = scan();
        for (; c >= '0' && c <= '9'; c = scan())
            val = (val << 3) + (val << 1) + (c & 15);
        return neg ? -val : val;
    }

    void print(Object a) throws Exception {
        bw.write(a.toString());
    }

    void printsp(Object a) throws Exception {
        print(a);
        bw.write(" ");
    }

    void println() throws Exception {
        bw.write("\n");
    }

    void println(Object a) throws Exception {
        print(a);
        println();
    }

    void flush() throws Exception {
        bw.flush();
        bw.close();
    }
}

