        oc_col = new Pair[n];
        for (int i = 0; i < n; i++) {
            boolean bool_row = true, bool_col = true;
            int row_i = -1, row_j = -1, col_i = -1, col_j = -1;
            for (int j = 0; j < n; j++) {
                if (arr[i][j] == 'B') {
                    bool_row = false;
                    if (row_i != -1)
                        row_j = j;
                    if (row_i == -1) {
                        row_i = j;
                        row_j = j;
                    }
                }
                if (arr[j][i] == 'B') {
                    bool_col = false;
                    if (col_i != -1)
                        col_j = j;
                    if (col_i == -1) {
                        col_i = j;
                        col_j = j;
                    }
                }
            }
            col[i] = bool_col;
            row[i] = bool_row;
            oc_row[i] = new Pair(row_i, row_j);
            oc_col[i] = new Pair(col_i, col_j);
        }
        int cnt = col_init();

        int kitna_row_khali[][] = new int[n][n];
        int kitna_col_khali[][] = new int[n][n];
        kitna_col_khali[0][0] = cnt;
        for (int i = 0; i <= n - k; i++) {
            int ori = cnt;
            for (int j = 0; j < n - k; j++) {
                cnt = right_col(i, j, cnt, kitna_col_khali);
            }
            if (i < n - k)
                cnt = down_col(i, 0, ori, kitna_col_khali);
        }
        cnt = row_init();
        kitna_row_khali[0][0] = cnt;
        for (int j = 0; j <= n - k; j++) {
            int ori = cnt;
            for (int i = 0; i < n - k; i++) {
                cnt = down_row( i,j, cnt, kitna_row_khali);
            }
            if (j < n - k)
                cnt = right_row(0, j, ori, kitna_row_khali);
        }
















        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                max = max(max, kitna_col_khali[i][j] + kitna_row_khali[i][j]);
        System.out.println(max);
    }

    static int row_init() {
        int cnt = 0;
        for (int p = 0; p < k; p++)
            if (row[p] || oc_row[p].last < k)
                cnt++;
        for (int p = k; p < n; p++)
            if (row[p]) cnt++;
        return cnt;
    }

    static int col_init() {
        int cnt = 0;
        for (int p = 0; p < k; p++)
            if (col[p] || oc_col[p].last < k)
                cnt++;
        for (int p = k; p < n; p++)
            if (col[p]) cnt++;
        return cnt;
    }

    static class Pair {
        int first, last;

        Pair(int x, int y) {
            first = x;
            last = y;
        }

        public String toString() {
            return first + " " + last;
        }
    }

    static int down_row(int i, int j, int cnt, int arr[][]) {


        if (!row[i] && oc_row[i].first >= j && oc_row[i].last < j + k)
            cnt--;
        if (!row[i + k] && oc_row[i + k].first >= j && oc_row[i + k].last < j + k)
            cnt++;

        arr[i + 1][j] = cnt;
        return cnt;
    }

    static int right_row(int i, int j, int cnt, int arr[][]) {


        for (int p = i; p < i + k; p++) {
            if (!row[p] && oc_row[p].first >= j && oc_row[p].last < j + k)
                cnt--;
            if (!row[p] && oc_row[p].first > j && oc_row[p].last <= j + k)
                cnt++;
        }

        arr[i][j + 1] = cnt;
        return cnt;
    }

    static int down_col(int i, int j, int cnt, int arr[][]) {

        for (int p = j; p < j + k; p++) {
            if (!col[p] && oc_col[p].first >= i && oc_col[p].last < i + k)
                cnt--;
            if (!col[p] && oc_col[p].first > i && oc_col[p].last <= i + k)
                cnt++;
        }
        arr[i + 1][j] = cnt;
        return cnt;
    }

    static int right_col(int i, int j, int cnt, int arr[][]) {


        if (!col[j] && oc_col[j].first >= i && oc_col[j].last < i + k)
            cnt--;

        if (!col[j + k] && oc_col[j + k].first >= i && oc_col[j + k].last < i + k)
            cnt++;
        arr[i][j + 1] = cnt;
        return cnt;
    }
}

