    static void solve(BufferedScanner in, BufferedPrinter out) throws Exception {

        int n = in.nextInt(), k = in.nextInt();

        boolean[][] grid = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            String s = in.next();

            for (int j = 0; j < n; j++) {
                grid[i][j] = s.charAt(j) == 'B';
            }
        }

        int empty = 0;

        int[][] lp = new int[n + 1][n + 1];
        for (int i = 0; i < n; i++) {
            int x = Math.max(0, i - k + 1);

            ArrayList<Integer> idx = new ArrayList<>();
            for(int j = 0; j < n; j++){
                if(grid[i][j]) idx.add(j);
            }

            if(idx.size() == 0){
                empty++;
            }else{
                int start = Math.max(0, idx.get(idx.size() - 1) - k + 1);
                int end = idx.get(0);

                if(end < start) continue;

           lp[x][start]++;
                lp[x][end+1]--;
                lp[i+1][start]--;
                lp[i+1][end+1]++;
            }
        }

        for (int i = 0; i < n; i++) {
            int x = Math.max(0, i - k + 1);

            ArrayList<Integer> idx = new ArrayList<>();
            for(int j = 0; j < n; j++){
                if(grid[j][i]) idx.add(j);
            }

            if(idx.size() == 0){
                empty++;
            }else{
                int start = Math.max(0, idx.get(idx.size() - 1) - k + 1);
                int end = idx.get(0);

                if(end < start) continue;

                lp[start][x]++;
                lp[end+1][x]--;
                lp[start][i+1]--;
                lp[end+1][i+1]++;
            }
        }


        int[][] sums = new int[lp.length][lp.length];
        sums[0][0] = lp[0][0];
        for (int i = 1; i < lp.length; i++) {
            sums[i][0] = lp[i][0] + sums[i - 1][0];
            sums[0][i] = lp[0][i] + sums[0][i - 1];
        }

        for (int i = 1; i < lp.length; i++) {
            for (int j = 1; j < lp.length; j++) {
                sums[i][j] = sums[i - 1][j] + sums[i][j - 1] - sums[i - 1][j - 1] + lp[i][j];
            }
        }

        int ans = 0;
        for (int i = 0; i < lp.length; i++) {
            for (int j = 0; j < lp.length; j++) {
                ans = Math.max(ans, sums[i][j]);
            }
        }

        out.println(ans + empty);
    }





