            for (int j = 0; j < n; j++) {
                if (a[i][j] == 1) {
                    f = j;
                    break;
                }
            }
            for (int j = n - 1; j >= 0; j--) {
                if (a[i][j] == 1) {
                    l = j;
                    break;
                }
            }
            if (f == -1) {
                empty++;
                continue;
            }
            if (l - f >= k) {
                continue;
            }
            w.add(new rect(i - k + 1, i, l - k + 1, f));
        }
        for (int j = 0; j < n; j++) {
            int f = -1;
            int l = n;
            for (int i = 0; i < n; i++) {
                if (a[i][j] == 1) {
                    f = i;
                    break;
                }
            }
            for (int i = n - 1; i >= 0; i--) {
                if (a[i][j] == 1) {
                    l = i;
                    break;
                }
            }
            if (f == -1) {
                empty++;
                continue;
            }
            if (l - f >= k) {
                continue;
            }
            w.add(new rect(l - k + 1, f, j - k + 1, j));
        }
        int t[][] = new int[n + 1][n + 1];
        for (int k = 0; k < w.size(); k++) {
            rect r = w.get(k);
            t[r.x1][r.y1]++;
            t[r.x1][r.y2 + 1]--;
            t[r.x2 + 1][r.y1]--;
            t[r.x2 + 1][r.y2 + 1]++;
        }
        int s[][] = new int[n + 1][n + 1];
        int max = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                s[i + 1][j + 1] = s[i + 1][j] + s[i][j + 1] - s[i][j] + t[i][j];
                max = Math.max(s[i + 1][j + 1], max);
            }
        }
        System.out.println(max + empty);
    }

    static class rect {
        int x1;
