    static class DWhiteLines {
        int[][] sum;
        int[][] vertical;
        int[][] horizontal;
        int n;

        public int findItSSS(int i1, int j1, int i2, int j2) {
            while (i2 > n) i2--;
            while (j2 > n) j2--;
            while (i1 <= 0) i1++;
            while (j1 <= 0) j1++;
            if (i2 < i1) return 0;
            if (j2 < j1) return 0;
            return sum[i2][j2] - sum[i2][j1 - 1] - sum[i1 - 1][j2] + sum[i1 - 1][j1 - 1];
        }

        public int findItVVV(int i1, int j1, int i2, int j2) {
            return vertical[i2][j2] - vertical[i2][j1 - 1] - vertical[i1 - 1][j2] + vertical[i1 - 1][j1 - 1];
        }

        public int findItHHH(int i1, int j1, int i2, int j2) {
            return horizontal[i2][j2] - horizontal[i2][j1 - 1] - horizontal[i1 - 1][j2] + horizontal[i1 - 1][j1 - 1];
        }

        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            n = in.scanInt();
            int k = in.scanInt();
            int[][] ar = new int[n + 1][n + 1];
            int[] row = new int[n + 1];
            int[] column = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    ar[i][j] = (in.scanChar() == 'B' ? 1 : 0);
                    if (ar[i][j] == 0) {
                        row[i]++;
                        column[j]++;
                    }
                }
            }
            for (int i = 1; i <= n; i++) {
                if (row[i] == n) row[i] = 1;
                else row[i] = 0;
                if (column[i] == n) column[i] = 1;
                else column[i] = 0;
            }
            for (int i = 1; i <= n; i++) row[i] = row[i] + row[i - 1];
            for (int i = 1; i <= n; i++) column[i] = column[i] + column[i - 1];
            sum = new int[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    sum[i][j] += sum[i - 1][j];
                    sum[i][j] += sum[i][j - 1];
                    sum[i][j] -= sum[i - 1][j - 1];
                    sum[i][j] += ar[i][j];
                }
            }
            vertical = new int[n + 2][n + 2];
            for (int i = 1; i <= n + 1; i++) {
                for (int j = 1; j <= n + 1; j++) {
                    if (i - k - 1 >= 0) {
                        if (findItSSS(0, j, i - k - 1, j) + findItSSS(i, j, n, j) == 0) vertical[i][j]++;
                    }
                    vertical[i][j] += vertical[i - 1][j];
                    vertical[i][j] += vertical[i][j - 1];
                    vertical[i][j] -= vertical[i - 1][j - 1];
                }
            }
            horizontal = new int[n + 2][n + 2];
            for (int i = 1; i <= n + 1; i++) {
                for (int j = 1; j <= n + 1; j++) {
                    if (j - k - 1 >= 0) {
                        if (findItSSS(i, 0, i, j - k - 1) + findItSSS(i, j, i, n) == 0) horizontal[i][j]++;
                    }
                    horizontal[i][j] += horizontal[i - 1][j];
                    horizontal[i][j] += horizontal[i][j - 1];
                    horizontal[i][j] -= horizontal[i - 1][j - 1];
                }
            }
            int ans = 0;
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (i + k - 1 <= n && j + k - 1 <= n) {
                        int sum = row[n] + column[n];
                        sum -= (row[i + k - 1] - row[i - 1]);
                        sum -= (column[j + k - 1] - column[j - 1]);
                        sum += (findItVVV(i + k, j, i + k, j + k - 1));
                        sum += findItHHH(i, j + k, i + k - 1, j + k);
                        ans = Math.max(ans, sum);
                    }
                }
            }
            out.println(ans);

        }

    }

    static class ScanReader {
        private byte[] buf = new byte[4 * 1024];
        private int index;
        private BufferedInputStream in;
        private int total;

        public ScanReader(InputStream inputStream) {
            in = new BufferedInputStream(inputStream);
        }

        private int scan() {
            if (index >= total) {
                index = 0;
                try {
                    total = in.read(buf);
                } catch (Exception e) {
                    e.printStackTrace();
                }
                if (total <= 0) return -1;
            }
            return buf[index++];
        }

        public char scanChar() {
            int c = scan();
            while (isWhiteSpace(c)) c = scan();
            return (char) c;
        }

        public int scanInt() {
            int integer = 0;
            int n = scan();
            while (isWhiteSpace(n)) n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    integer *= 10;
                    integer += n - '0';
                    n = scan();
                }
            }
            return neg * integer;
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1) return true;
            else return false;
        }

    }
}

