public class d {
    static int k;
    public static String[] transpose(String[] s) {
        int n = s.length;
        String[] t = new String[n];
        for(int i=0; i < n; i++) {
            char[] x = new char[n];
            for(int j=0; j < n; j++) {
                x[j] = s[j].charAt(i);
            }
            t[i] = new String(x);
        }
        return t;
    }
    public static int[][] solve(String[] s) {
        int n = s.length;
        int[][] p = new int[n][n];
        int[][] res = new int[n][n];
        for(int i=0; i < n; i++) {
            int a=n, b=-1;
            for(int j=0; j < n; j++) {
                if(s[i].charAt(j) == 'B') {
                    a = Integer.min(a, j);
                    b = Integer.max(b, j);
                }
            }
            if(b == -1) {
                continue;
            }
            for(int j=Integer.max(0, b-k+1); j <= a; j++) {
                p[i][j] = 1;
            }
        }
        for(int i=0; i < n; i++) {
            int le=0, ri=0;
            int su=0;
            while(ri < k) {
                su+=p[ri][i];
                ri++;
            }
            for(int j=0; j < n-k+1; j++) {
                res[j][i] = su;
                if(j == n-k) {
                    break;
                }
                su+=p[ri][i];
                su-=p[le][i];
                ri++; le++;
            }
        }
        return res;
    }
    static int countEmpty(String[] s) {
        int n = s.length;
        int res=0;
        for(int i=0; i < n; i++) {
            int a=1, b=1;
            for(int j=0; j < n; j++) {
                if(s[i].charAt(j) == 'B') {
                    a=0;
                }
                if(s[j].charAt(i) == 'B') {
                    b=0;
                }
            }
            res+=a+b;
        }
        return res;
    }
    public static void main(String[] args) {
        Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(System.out);
        int n;
        n = in.nextInt();
        k = in.nextInt();
        in.nextLine();
        String[] s = new String[n];
        for(int i=0; i < n; i++) {
            s[i] = new String();
            s[i] = in.nextLine();
        }
        String[] t = transpose(s);
        int[][] v, h;
        v = solve(s);
        h = solve(t);
        int res=0;


        for(int i=0; i < n; i++) {
            for(int j=0; j < n; j++) {
                res = Integer.max(res, v[i][j]+h[j][i]);
            }
        }
        res+=countEmpty(s);
        out.println(res);
        in.close();
        out.close();
    }
}

