         char[][] grid = new char[N][N];
         for(int i=0; i < N; i++)
            grid[i] = infile.readLine().toCharArray();
         int[] rc = new int[N];
         int[] cc = new int[N];
         for(int r=0; r < N; r++)
            for(int c=0; c < N; c++)
               if(grid[r][c] == 'B')
               {
                  rc[r]++;
                  cc[c]++;
               }
         int alreadywhite = 0;
         for(int i=0; i < N; i++)
         {
            if(rc[i] == 0)
               alreadywhite++;
            if(cc[i] == 0)
               alreadywhite++;
         }
         int[][] rowsums = new int[N][N];
         int[][] colsums = new int[N][N];
         for(int r=0; r < N; r++)
         {
            if(grid[r][0] == 'B')
               rowsums[r][0] = 1;
            for(int c=1; c < N; c++)
               rowsums[r][c] = rowsums[r][c-1]+(grid[r][c] == 'B' ? 1 : 0);
         }
         for(int c=0; c < N; c++)
         {
            if(grid[0][c] == 'B')
               colsums[0][c] = 1;
            for(int r=1; r < N; r++)
               colsums[r][c] = colsums[r-1][c]+(grid[r][c] == 'B' ? 1 : 0);
         }
         int[][] white = new int[N][N];

         for(int x=0; x < N-K+1; x++)
         {
            int temp = 0;
            for(int y=0; y < K; y++)
            {
               if(cc[y] == 0);
               else if(works1(x, y, K, colsums, cc))
                  temp++;
            }
            white[x][0] = temp;
            for(int y=K; y < N; y++)
            {
               if(cc[y-K] == 0);
               else if(works1(x, y-K, K, colsums, cc))
                  temp--;
               if(cc[y] == 0);
               else if(works1(x, y, K, colsums, cc))
                  temp++;
               white[x][y-K+1] = temp;
            }
         }

         for(int y=0; y < N-K+1; y++)
         {
            int temp = 0;
            for(int x=0; x < K; x++)
            {
               if(rc[x] == 0);
               else if(works2(x, y, K, rowsums, rc))
                  temp++;
            }
            white[0][y] += temp;
            for(int x=K; x < N; x++)
            {
               if(rc[x-K] == 0);
               else if(works2(x-K, y, K, rowsums, rc))
                  temp--;
               if(rc[x] == 0);
               else if(works2(x, y, K, rowsums, rc))
                  temp++;
               white[x-K+1][y] += temp;
            }
         }
         int res = 0;
         for(int r=0; r < N; r++)
            for(int c=0; c < N; c++)
               res = Math.max(res, white[r][c]);
         System.out.println(res+alreadywhite);
      }
      public static boolean works1(int r, int c, int K, int[][] colsums, int[] cc)
      {
         int val = colsums[r+K-1][c];
         if(r > 0)
            val -= colsums[r-1][c];
         return val == cc[c];
      }
      public static boolean works2(int r, int c, int K, int[][] rowsums, int[] rc)
      {
         int val = rowsums[r][c+K-1];
         if(c > 0)
            val -= rowsums[r][c-1];
         return val == rc[r];
      }
   }

import java.io.PrintWriter;
import java.util.*;

public class Main {

    void solve(Scanner in, PrintWriter out) {
        int n = in.nextInt();
        int k = in.nextInt();
        char[][] f = new char[n][n];
        for (int i = 0; i < n; ++i) {
            f[i] = in.next().toCharArray();
        }

        int nWhite = 0;
        boolean[][] strBecW = new boolean[n][n];
        for (int i = 0; i < n; ++i) {
            int beg = -1, end = -1;
            for (int j = 0; j < n; ++j) {
                if (f[i][j] == 'B') {
                    if (beg == -1) beg = j;
                    end = j;
                }
            }
            if (beg == -1) {
                ++nWhite;
                continue;
            }
            for (int j = Math.max(0, end - k + 1); j <= beg; ++j) {
                strBecW[i][j] = true;
            }
        }
        boolean[][] colBecW = new boolean[n][n];
        for (int i = 0; i < n; ++i) {
            int beg = -1, end = -1;
            for (int j = 0; j < n; ++j) {
                if (f[j][i] == 'B') {
                    if (beg == -1) beg = j;
                    end = j;
                }
            }
            if (beg == -1) {
                ++nWhite;
                continue;
            }
            for (int j = Math.max(0, end - k + 1); j <= beg; ++j) {
                colBecW[j][i] = true;
            }
        }
        int[][] sumStr = new int[n - k + 1][n - k + 1];
        for (int j = 0; j <= n - k; ++j) {
            for (int i = 0; i < k; ++i) {
                if (strBecW[i][j]) {
                    ++sumStr[0][j];
                }
            }
            for (int i = 1; i <= n - k; ++i) {
                sumStr[i][j] = sumStr[i - 1][j];
                if (strBecW[i - 1][j]) {
                    --sumStr[i][j];
                }
                if (strBecW[i + k - 1][j]) {
                    ++sumStr[i][j];
                }
            }
        }
        int[][] sumCol = new int[n - k + 1][n - k + 1];
        for (int i = 0; i <= n - k; ++i) {
            for (int j = 0; j < k; ++j) {
                if (colBecW[i][j]) {
                    ++sumCol[i][0];
                }
            }
            for (int j = 1; j <= n - k; ++j) {
                sumCol[i][j] = sumCol[i][j - 1];
                if (colBecW[i][j - 1]) {
                    --sumCol[i][j];
                }
                if (colBecW[i][j + k - 1]) {
                    ++sumCol[i][j];
                }
            }
        }
        int ans = nWhite;
        for (int i = 0; i <= n - k; ++i) {
            for (int j = 0; j <= n - k; ++j) {
                ans = Math.max(ans, nWhite + sumCol[i][j] + sumStr[i][j]);
            }
        }
        out.println(ans);
    }

    public static void main(String[] args) {
        new Main().run();
    }

    void run() {
        try (
                Scanner in = new Scanner(System.in);
                PrintWriter out = new PrintWriter(System.out);
        ) {
            solve(in, out);
        }
    }

}

import java.io.*;
