import java.util.NoSuchElementException;

public class P1200D_2 {

    public static void main(String[] args) {
        SimpleScanner scanner = new SimpleScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int k = scanner.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; ++i)
            grid[i] = scanner.next().toCharArray();
        int[] top = new int[n];
        int[] bottom = new int[n];
        int[] left = new int[n];
        int[] right = new int[n];
        Arrays.fill(top, n);
        Arrays.fill(left, n);
        Arrays.fill(bottom, -1);
        Arrays.fill(right, -1);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j)
                if (grid[i][j] == 'B') {
                    top[j] = Math.min(top[j], i);
                    bottom[j] = Math.max(bottom[j], i);
                    left[i] = Math.min(left[i], j);
                    right[i] = Math.max(right[i], j);
                }
        }
        int initClear = 0;
        for (int i = 0; i < n; ++i)
            if (right[i] < left[i])
                ++initClear;
        for (int j = 0; j < n; ++j)
            if (bottom[j] < top[j])
                ++initClear;
        int[][] colIncrement = new int[n - k + 1][n - k + 1];
        for (int i = 0; i <= n - k; ++i) {
            for (int j = 0; j < k; ++j) {
                if (bottom[j] >= top[j] && bottom[j] < i + k && top[j] >= i)
                    ++colIncrement[i][0];
            }
            for (int j = 1; j <= n - k; ++j) {
                colIncrement[i][j] = colIncrement[i][j - 1];
                if (bottom[j - 1] >= top[j - 1] && bottom[j - 1] < i + k && top[j - 1] >= i)
                    --colIncrement[i][j];
                if (bottom[j + k - 1] >= top[j + k - 1] && bottom[j + k - 1] < i + k && top[j + k - 1] >= i)
                    ++colIncrement[i][j];
            }
        }
        int[][] rowIncrement = new int[n - k + 1][n - k + 1];
        for (int j = 0; j <= n - k; ++j) {
            for (int i = 0; i < k; ++i) {
                if (right[i] >= left[i] && right[i] < j + k && left[i] >= j)
                    ++rowIncrement[0][j];
            }
            for (int i = 1; i <= n - k; ++i) {
                rowIncrement[i][j] = rowIncrement[i - 1][j];
                if (right[i - 1] >= left[i - 1] && right[i - 1] < j + k && left[i - 1] >= j)
                    --rowIncrement[i][j];
                if (right[i + k - 1] >= left[i + k - 1] && right[i + k - 1] < j + k && left[i + k - 1] >= j)
                    ++rowIncrement[i][j];
            }
        }
        int max = 0;
        for (int i = 0; i <= n - k; ++i) {
            for (int j = 0; j <= n - k; ++j) {
                max = Math.max(rowIncrement[i][j] + colIncrement[i][j], max);
            }
        }
        writer.println(initClear + max);

        writer.close();
    }

    private static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    private static class SimpleScanner {

        private static final int BUFFER_SIZE = 10240;

        private Readable in;
        private CharBuffer buffer;
        private boolean eof;

        SimpleScanner(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
            buffer = CharBuffer.allocate(BUFFER_SIZE);
            buffer.limit(0);
            eof = false;
        }


        private char read() {
            if (!buffer.hasRemaining()) {
                buffer.clear();
                int n;
                try {
                    n = in.read(buffer);
                } catch (IOException e) {
                    n = -1;
                }
                if (n <= 0) {
                    eof = true;
                    return '\0';
                }
                buffer.flip();
            }
            return buffer.get();
        }

        void checkEof() {
            if (eof)
                throw new NoSuchElementException();
        }

        char nextChar() {
            checkEof();
            char b = read();
            checkEof();
            return b;
        }

        String next() {
            char b;
            do {
                b = read();
                checkEof();
            } while (Character.isWhitespace(b));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append(b);
                b = read();
            } while (!eof && !Character.isWhitespace(b));
            return sb.toString();
        }

        int nextInt() {
            return Integer.valueOf(next());
        }

        long nextLong() {
            return Long.valueOf(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

