public class Rextester{
    static class Gaps implements Comparable<Gaps>{
        int size,beg,end;
        boolean done;
        public Gaps(int size,int beg,int end){
            this.size=size;
            this.beg=beg;
            this.end=end;
            done=false;
        }
        public int compareTo(Gaps o){
            return this.size-o.size;
        }
    }
    public static void main(String[] args)throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = new Integer(br.readLine());
        StringTokenizer st = new StringTokenizer(br.readLine());
        br.close();
        boolean[] done = new boolean[n+1];
        int[] array = new int[n];
        for(int i=0;i<n;i++){
            array[i]=new Integer(st.nextToken());
            if(array[i]!=0){
                done[array[i]]=true;
            }
        }
        int odd=0,even=0;
        for(int i=1;i<=n;i++){
            if(!done[i]){
                if(i%2==0){
                    even++;
                }
                else{
                    odd++;
                }
            }
        }
        Gaps[] gs = new Gaps[n];
        int p=0,count=0,b=0,e=0;
        for(int i=0;i<n;i++){
            if(array[i]==0){
                if(i>0){
                    b=array[i-1];
                }
                else{
                    b=-1;
                }
                int j=i;
                for(j=i;j<n;j++){
                    if(array[j]==0){
                        count++;
                    }
                    else{
                        i=j;
                        e=array[j];
                        gs[p++]=new Gaps(count,b,e);
                        count=0;
                        break;
                    }
                }
                if(j==n){
                    e=-1;
                    gs[p++]=new Gaps(count,b,e);
                    break;
                }
            }
        }

        Arrays.sort(gs,0,p);

        int ans=0;
        for(int i=0;i<p;i++){
            if(!gs[i].done){
                if(gs[i].beg!=-1&&gs[i].end!=-1){
                    if((gs[i].beg==-1&&gs[i].end%2==0)||(gs[i].beg%2==0&&gs[i].end%2==0)||(gs[i].beg%2==0&&gs[i].end==-1)){
                        if(even-gs[i].size>=0){
                            even-=gs[i].size;
                            gs[i].done=true;
                        }
                    }
                    else if((gs[i].beg==-1&&gs[i].end%2!=0)||(gs[i].beg%2!=0&&gs[i].end==-1)||(gs[i].beg%2!=0&&gs[i].end%2!=0)){
                        if(odd-gs[i].size>=0){
                             odd-=gs[i].size;
                             gs[i].done=true;
                        }
                    }
                }
            }
        }
        for(int i=0;i<p;i++){
            if(!gs[i].done){
                if(gs[i].beg==-1){
                    if(gs[i].end%2==0){
                        if(even-gs[i].size>=0){
                            even-=gs[i].size;
                            gs[i].done=true;
                        }
                    }
                    else if(gs[i].end%2!=0){
                        if(odd-gs[i].size>=0){
                            odd-=gs[i].size;
                            gs[i].done=true;
                        }
                    }
                }
                else if(gs[i].end==-1){
                    if(gs[i].beg%2!=0){
                        if(odd-gs[i].size>=0){
                            odd-=gs[i].size;
                            gs[i].done=true;
                        }
                    }
                    else{
                        if(even-gs[i].size>=0){
                            even-=gs[i].size;
                            gs[i].done=true;
                        }
                    }
                }
            }
        }
        for(int i=0;i<p;i++){
            if(!gs[i].done){
                if(gs[i].beg%2!=gs[i].end%2&&gs[i].beg!=-1&&gs[i].end!=-1){
                    ans++;
                }
                else if(gs[i].beg==-1||gs[i].end==-1){
                    ans++;
                }
                else{
                    ans+=2;
                }
            }
        }
        for(int i=0;i<n-1;i++){
            if(array[i]!=0&&array[i+1]!=0){
                if(array[i]%2!=array[i+1]%2){
                    ans++;
                }
            }
        }
        System.out.println(ans);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class C {

    private static BufferedReader br;
    private static StringTokenizer tokenizer;
    private static int[][][][] memo;
    private static int len;
    private static int[] arr;

    private static boolean isOdd(int num) {
        return num % 2 == 1;
    }

    private static int backTrack(int from, int oddCount, int evenCount, boolean isLastOdd) {
        if (from == len) {
            return 0;
        }

        if (from == len - 1) {
            if (from == 0) {
                return 0;
            }

            boolean isCurNumOdd = arr[from] != 0 ? isOdd(arr[from]) : oddCount == 1;
            if (isCurNumOdd && !isLastOdd || !isCurNumOdd && isLastOdd) {
                return 1;
            }
            return 0;
        }

        if (memo[from][oddCount][evenCount][isLastOdd ? 1 : 0] != -1) {
            return memo[from][oddCount][evenCount][isLastOdd ? 1 : 0];
        }

        if (oddCount == 0 && evenCount == 0) {
            int count = 0;
            for (int i = from; i < len - 1; i++) {
                if (isOdd(arr[i]) && !isOdd(arr[i+1]) || !isOdd(arr[i]) && isOdd(arr[i+1])) {
                    count++;
                }
            }

            if (from == 0) {
                return count;
            }

            boolean isCurNumOdd = isOdd(arr[from]);
            if (isCurNumOdd && !isLastOdd || !isCurNumOdd && isLastOdd) {
                count++;
            }

            memo[from][oddCount][evenCount][isLastOdd ? 1 : 0] = count;
            return count;
        }

        if (arr[from] != 0) {
            boolean isCurNumOdd = isOdd(arr[from]);
            int count = backTrack(from + 1, oddCount, evenCount, isCurNumOdd);
            if (from == 0) {
                return count;
            }

            if (isCurNumOdd && !isLastOdd || !isCurNumOdd && isLastOdd) {
                count++;
            }

            memo[from][oddCount][evenCount][isLastOdd ? 1 : 0] = count;
            return count;
        }


        int curOddMinCount = Integer.MAX_VALUE;
        if (oddCount > 0) {
            curOddMinCount = backTrack(from + 1, oddCount - 1, evenCount, true);
            if (from > 0 && !isLastOdd) {
                curOddMinCount++;
            }
        }

        int curEvenMinCount = Integer.MAX_VALUE;
        if (evenCount > 0) {
            curEvenMinCount = backTrack(from + 1, oddCount, evenCount - 1, false);
            if (from > 0 && isLastOdd) {
                curEvenMinCount++;
            }
        }

        if (curOddMinCount < curEvenMinCount) {
            memo[from][oddCount][evenCount][isLastOdd ? 1 : 0] = curOddMinCount;
            return curOddMinCount;
        }

        memo[from][oddCount][evenCount][isLastOdd ? 1 : 0] = curEvenMinCount;
        return curEvenMinCount;
    }

    private static void solve() throws IOException {
        int n = nextInt();
        arr = new int[n];
        for (int i =0; i < n; i++) {
            arr[i] = nextInt();
        }

        Set<Integer> set = new HashSet<>();
        for (int i = 0; i < n; i++) {
            if (arr[i] != 0) {
                set.add(arr[i]);
            }
        }

        int oddCount = 0;
        int evenCount = 0;
        for (int i = 1; i <= n; i++) {
            if (set.contains(i)) {
                continue;
            }
            if ((i & 1) == 1) {
                oddCount++;
            } else {
                evenCount++;
            }
        }

        len = n;
        memo = new int[n+1][n+1][n+1][2];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    for (int l = 0; l < 2; l++) {
                        memo[i][j][k][l] = -1;
                    }
                }
            }
        }
        int minCount = backTrack(0, oddCount, evenCount, true);
        System.out.println(minCount);
    }

    public static void main(String[] args) throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        solve();
    }

    public static String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null)
                throw new IOException();
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public static long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    public static double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }

}

