        if(array[0] == 0){
            for(int i = 0; i < n; ++i){
                if(array[i] != 0){
                    if(array[i] % 2 == 0 && chet.size() >= i){
                        for(int j = 0; j < i; ++j){
                            array[j] = chet.pollFirst();
                        }
                    }
                    else if(array[i] % 2 == 1 && nech.size() >= i){
