        while(nech.size() > 0 || chet.size() > 0){
            for(int i = 0; i < n; ++i){
                if(i > 0 && array[i] == 0){
                    if(array[i - 1] % 2 == 1 && nech.size() > 0){
                        array[i] = nech.pollFirst();
                    }
                    else if(array[i - 1] % 2 == 1 && nech.size() == 0){
                        array[i] = chet.pollFirst();
                    }
                    else if(array[i - 1] != 0 &&array[i - 1] % 2 == 0 && chet.size() > 0){
                        array[i] = chet.pollFirst();
                    }
                    else if(array[i - 1] != 0 &&array[i - 1] % 2 == 0 && chet.size() == 0){
                        array[i] = nech.pollFirst();
                    }
                }
                if(array[i] == 0 && i < n - 1){
                    if(array[i + 1] % 2 == 1 && nech.size() > 0){
                        array[i] = nech.pollFirst();
                    }
                    else if(array[i + 1] % 2 == 1 && nech.size() == 0){
