        int even = n/2, odd = n/2+n%2;
        int res = 0;
        for (int i=0; i<n; i++) {
            arr[i] = Integer.parseInt(sToken.nextToken());
            if (arr[i]==0) continue;
            if (i>0 && arr[i-1]>0) {
                if ((arr[i-1]%2==0 && arr[i]%2==1) || (arr[i-1]%2==1 && arr[i]%2==0)) res++;
            }
            if (arr[i]%2==0) even--;
            else odd--;
        }
        int[][] dp = new int[even+1][odd+1];
        int start = -1;
        for (int i=0; i<n; i++) {
            if (arr[i]>0) {
                start = i; break;
            }
        }
        if (start==-1) {
            if (n==1) System.out.println(0);
            else System.out.println(1);
            System.exit(0);
        }
        for (int i=0; i<=even; i++) {
            for (int j=0; j<=odd; j++) {
                dp[i][j] = -1;
            }
        }
        dp[0][0] = 0;
        if (start>0) {
            int cout = start;
            for (int i=even; i>-1; i--) {
                for (int j=odd; j>-1; j--) {
                    for (int k = 0; k<=cout; k++) {
                        if (k>i || cout-k>j) continue;
                        int x = 1;
                        if (k==cout && arr[start]%2==0) x = 0;
                        if (k==0 && arr[start]%2==1) x = 0;
                        if (dp[i-k][j-(cout-k)]==-1) continue;
                        if (dp[i][j]==-1) dp[i][j] = dp[i-k][j-(cout-k)]+x;
                        else dp[i][j] = Math.min(dp[i][j], dp[i-k][j-(cout-k)]+x);
                    }
                }
            }
        }
        int end = start+1;
        for (; end<n; end++) {
            if (arr[end]!=0) {
                int cout = end-start-1;
                if (cout!=0) {
                    for (int i=even; i>-1; i--) {
                        for (int j=odd; j>-1; j--) {
                            for (int k=0; k<=cout; k++) {
                                if (k>i || cout-k>j) continue;
                                int x = 2;
                                int s = arr[start]%2, e = arr[end]%2;
                                if ((s==0 && e==1) || (s==1 && e==0)) x = 1;
                                if (s==0 && e==0 && k==cout) x = 0;
                                if (s==1 && e==1 && k==0) x = 0;
                                if (dp[i-k][j-(cout-k)]==-1) continue;
                                if (dp[i][j]==-1) dp[i][j] = dp[i-k][j-(cout-k)]+x;
                                else dp[i][j] = Math.min(dp[i][j], dp[i-k][j-(cout-k)]+x);
                            }
                        }
                    }
                }
                start = end;
            }
        }
        if (start<n-1) {
            int cout = n-start-1;
            for (int i=even; i>-1; i--) {
                for (int j=odd; j>-1; j--) {
                    for (int k=0; k<=cout; k++) {
                        if (k>i || cout-k>j) continue;
                        int x = 1;
                        if (k==cout && arr[start]%2==0) x = 0;
                        if (k==0 && arr[start]%2==1) x = 0;
                        if (dp[i-k][j-(cout-k)]==-1) continue;
                        if (dp[i][j]==-1) dp[i][j] = dp[i-k][j-(cout-k)]+x;
                        else dp[i][j] = Math.min(dp[i][j], dp[i-k][j-(cout-k)]+x);
                    }
                }
            }
        }
        System.out.println(res + dp[even][odd]);
