import java.io.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;



public class Main {

    static FastReader in;
    static PrintWriter out;
    static Random rand = new Random();
    static final int INF = (int) (1e9);
    static final int MOD = (int) (1e9 + 7);
    static final int N = (int) (1e5 + 5);

    static void solve() {
        int n = in.nextInt();

        int[] p = new int[n];
        for (int i = 0; i < n; i++) {
            p[i] = in.nextInt();
        }

        int[] free = new int[2];
        free[0] = n / 2;
        free[1] = n / 2 + n % 2;
        for (int i = 0; i < n; i++) {
            if (p[i] != 0) {
                free[p[i] % 2]--;
            }
        }

        if (free[0] + free[1] == n) {
            if (n == 1) {
                out.println(0);
            } else {
                out.println(1);
            }
            return;
        }

        PriorityQueue<Integer> q00 = new PriorityQueue<>();
        PriorityQueue<Integer> q01 = new PriorityQueue<>();
        PriorityQueue<Integer> q10 = new PriorityQueue<>();
        PriorityQueue<Integer> q11 = new PriorityQueue<>();
        int cnt = 0, f0 = 0, f1 = 0, l0 = 0, l1 = 0;
        for (int i = 0; i < n; i++) {
            if (p[i] == 0) {
                int j = i;
                while (j < n && p[j] == 0) j++;

                if (i == 0) {
                    if (p[j] % 2 == 0) {
                        f0 = j;
                    } else {
                        f1 = j;
                    }
                } else if (j == n) {
                    if (p[i - 1] % 2 == 0) {
                        l0 = n - i;
                    } else {
                        l1 = n - i;
                    }
                } else {
                    if (p[i - 1] % 2 == 0 && p[j] % 2 == 0) {
                        q00.add(j - i);
                    } else if (p[i - 1] % 2 == 0 && p[j] % 2 == 1) {
                        q01.add(j - i);
                    } else if (p[i - 1] % 2 == 1 && p[j] % 2 == 0) {
                        q10.add(j - i);
                    } else if (p[i - 1] % 2 == 1 && p[j] % 2 == 1) {
                        q11.add(j - i);
                    }
                }

                i = j;
            } else {
                if (i > 0 && p[i - 1] != 0) {
                    if ((p[i - 1] % 2 + p[i] % 2) % 2 == 1) {
                        cnt++;
                    }
                }
            }
        }
        cnt += q01.size();
        cnt += q10.size();

        while (!q00.isEmpty()) {
            int x = q00.poll();
            if (free[0] >= x) {
                free[0] -= x;
            } else {
                cnt += 2;
            }
        }
        while (!q11.isEmpty()) {
            int x = q11.poll();
            if (free[1] >= x) {
                free[1] -= x;
            } else {
                cnt += 2;
            }
        }

        if (f0 != 0) {
            if (free[0] >= f0) {
                free[0] -= f0;
            } else {
                cnt++;
            }
        }
        if (f1 != 0) {
            if (free[1] >= f1) {
                free[1] -= f1;
            } else {
                cnt++;
            }
        }
        if (l0 != 0) {
            if (free[0] >= l0) {
                free[0] -= l0;
            } else {
                cnt++;
            }
        }
        if (l1 != 0) {
            if (free[1] >= l1) {
                free[1] -= l1;
            } else {
                cnt++;
            }
        }

        out.println(cnt);
    }

    public static void main(String[] args) throws FileNotFoundException {
        in = new FastReader(System.in);

        out = new PrintWriter(System.out);



        int q = 1;

        while (q-- > 0) {
            solve();
        }

        out.close();
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        Integer nextInt() {
            return Integer.parseInt(next());
        }

        Long nextLong() {
            return Long.parseLong(next());
        }

        Double nextDouble() {
            return Double.parseDouble(next());
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(nextLine());
            }
            return st.nextToken();
        }

        String nextLine() {
            String s = "";
            try {
                s = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return s;
        }
    }
}

