                if (prev == -1) {
                    if (count == 0) {
                        prev = p[i];
                        continue;
                    }

                    if (p[i] % 2 == 0) {
                        openIntervals.add(new Interval(Type.EVEN, count));
                    } else {
                        openIntervals.add(new Interval(Type.ODD, count));
                    }
                } else {
                    if (count == 0) {
                        prev = p[i];
                        continue;
                    }

                    if (p[i] % 2 == prev % 2) {
                        if (p[i] % 2 == 0) {
                            intervals.add(new Interval(Type.EVEN, count));
                        } else {
                            intervals.add(new Interval(Type.ODD, count));
                        }
                    } else {
                        res++;
                    }
                }

                count = 0;
                prev = p[i];
            } else {
                count++;
                if (i == p.length - 1) {
                    if (prev % 2 == 0) {
                        openIntervals.add(new Interval(Type.EVEN, count));
                    } else {
                        openIntervals.add(new Interval(Type.ODD, count));
                    }
                }
            }
        }

        for (int i = 1; i < p.length; i++) {
            if (p[i] != 0 && p[i - 1] != 0 && p[i] % 2 != p[i - 1] % 2) {
                res++;
            }
        }

        Collections.sort(intervals);

        for (Interval interval : intervals) {
            if (interval.type == Type.EVEN) {
                if (even >= interval.count) {
                    even -= interval.count;
                } else {
                    res += 2;
                }
            } else {
                if (odd >= interval.count) {
                    odd -= interval.count;
                } else {
                    res += 2;
                }
            }
        }

        for (Interval openInterval : openIntervals) {
            if (openInterval.type == Type.EVEN) {
                if (even < openInterval.count) {
                    res++;
                }
            } else {
                if (odd < openInterval.count) {
                    res++;
                }
            }
        }

        out.println(res);
        out.close();
    }

    private static void print2Arr(int[][] arr, PrintWriter out) {
        for (int i = 0; i < arr.length; i++) {
            for (int j = 0; j < arr[0].length; j++) {
                out.print(arr[i][j] + " ");
            }
            out.println();
        }
    }


    private static void printArr(int[] arr, PrintWriter out) {
        for (int i = 0; i < arr.length; i++) {
            out.print(arr[i] + " ");
        }
        out.println();
    }

    public static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }

            return null;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int[] nextIntArr(int n) {
            int[] arr = new int[n];
            for (int j = 0; j < arr.length; j++) {
                arr[j] = nextInt();
            }

            return arr;
        }

        public long[] nextLongArr(int n) {
            long[] arr = new long[n];
            for (int j = 0; j < arr.length; j++) {
                arr[j] = nextLong();
            }

            return arr;
        }
    }
}

import java.util.Scanner;

public class Garland {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int countJi = (n % 2 == 0) ? (n / 2) : (n / 2) + 1;
        int countOu = n / 2;
        int[] arr = new int[n];
        int firstIndex = -1;
        int lastIndex = -1;
        int[] disArr = new int[n];
        int distance = 0;
        int frontNum = -1;
        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
            if (arr[i] != 0) {
                lastIndex = i;
                if (firstIndex == -1) {
                    firstIndex = i;
                }
                if (arr[i] % 2 == 0) {
                    countOu--;
                } else {
                    countJi--;
                }
                if (frontNum == -1) {
                    frontNum = arr[i];
                    distance = 0;
                } else {
                    if ((frontNum % 2 == 0 && arr[i] % 2 == 0) || (frontNum % 2 != 0 && arr[i] % 2 != 0)) {
                        disArr[distance] = 1;
                    }
                    frontNum = arr[i];
                    distance = 0;
                }
                continue;
            }
            distance++;
        }

        if (firstIndex == -1) {
            if (n == 1) {
                System.out.println(0);
            } else {
                System.out.println(1);
            }
        } else {

            for (int i = 1; i < n; i++) {
                if (disArr[i] != 0) {
                    distance = i;
                    for (int j = 0; j < n - distance - 1; j++) {
                        if (arr[j] != 0 && arr[j + distance + 1] != 0 &&
                                ((arr[j] % 2 == 0 && arr[j + distance +1] % 2 == 0) ||
                                        (arr[j] % 2 != 0 && arr[j + distance + 1] % 2 != 0))) {
                            boolean isZero = true;
                            for (int k = j + 1; k <= j + distance; k++) {
                                if (arr[k] != 0) {
                                    isZero = false;
                                    break;
                                }
                            }
                            if (isZero) {
                                if (arr[j] % 2 == 0 && countOu >= distance) {
                                    for (int k = j + 1; k <= j + distance; k++) {
                                        arr[k] = 2;
                                    }
                                    countOu -= distance;
                                }
                                if (arr[j] % 2 != 0 && countJi >= distance) {
                                    for (int k = j + 1; k <= j + distance; k++) {
                                        arr[k] = 1;
                                    }
                                    countJi -= distance;
                                }
                            }
                        }
                    }
                }
            }

            if (lastIndex != (n - 1)) { 
                int isInsert = -1;
                if (arr[lastIndex] % 2 == 0 && countOu >= (n - lastIndex - 1)) { 
                    isInsert = 2;
                    countOu -= (n - lastIndex - 1);
                }
                if (arr[lastIndex] % 2 != 0 && countJi >= (n - lastIndex - 1)) { 
                    isInsert = 1;
                    countJi -= (n - lastIndex - 1);
                }
                if (isInsert != -1) {
                    for (int i = lastIndex + 1; i < n; i++) {
                        arr[i] = isInsert;
                    }
                }
            }

            for (int i = firstIndex - 1; i >= 0; i--) {
                if (arr[i + 1] % 2 == 0) {
                    if (countOu > 0) {
                        countOu--;
                        arr[i] = 2;
                    } else {
                        countJi--;
                        arr[i] = 1;
                    }
                } else {
                    if (countJi > 0) {
                        countJi--;
                        arr[i] = 1;
                    } else {
                        countOu--;
                        arr[i] = 2;
                    }
                }
            }

            for (int i = firstIndex + 1; i < n; i++) {
                int front = arr[i - 1];
                int num   = arr[i];
                if (num != 0) {
                    continue;
                }
                if (i == n - 1) { 
                    if (front % 2 == 0) {
                        if (countOu > 0) {
                            countOu--;
                            arr[i] = 2;
                        } else {
                            countJi--;
                            arr[i] = 1;
                        }
                    } else {
                        if (countJi > 0) {
                            countJi--;
                            arr[i] = 1;
                        } else {
                            countOu--;
                            arr[i] = 2;
                        }
                    }
                    continue;
                }
                int back = arr[i + 1];
                if (front != 0 && back != 0 &&
                        ((front % 2 == 0) && (back % 2 != 0) || (front % 2 != 0) && (back % 2 == 0))) { 
                    continue;
                }

                if (front % 2 == 0) {
                    if (countOu > 0) {
                        countOu--;
                        arr[i] = 2;
                    } else {
                        countJi--;
                        arr[i] = 1;
                    }
                } else {
                    if (countJi > 0) {
                        countJi--;
                        arr[i] = 1;
                    } else {
                        countOu--;
                        arr[i] = 2;
                    }
                }
            }

            for (int i = firstIndex + 1; i < n; i++) {
                arr[i] = (arr[i] == 0) ? 1 : arr[i];
            }

            int answer = 0;
            for (int i = 0; i < n - 1; i++) {
                if ((arr[i] % 2 == 0 && arr[i + 1] % 2 != 0) || (arr[i] % 2 != 0 && arr[i + 1] % 2 == 0)) {
                    answer++;
                }
            }
            System.out.println(answer);
        }
    }

}

import java.util.*;
import java.lang.*;
import java.io.*;

public class EF3 {
    static PrintWriter out=new PrintWriter(new OutputStreamWriter(System.out));
    public static void main(String[] Args)throws Exception{
        FastReader scan=new FastReader(System.in);
        int t=1;

        while(t-->0){
            int n=scan.nextInt();
            int ods=n/2;
            int evs=n/2;
            if(n%2!=0){
                ods++;
            }
            int[] arr=new int[n];
            for(int i=0;i<n;i++){
                int num=scan.nextInt();
                if(num==0){
                    arr[i]=-1;
                }else {
                    if (num % 2 == 0) {
                        evs--;
                        arr[i] = 0;
                    } else {
                        ods--;
                        arr[i] = 1;
                    }
                }
            }
            int[][][][] dp=new int[n][ods+1][evs+1][3];
            for(int i=0;i<n;i++){
                for(int j=0;j<=ods;j++){
                    for(int k=0;k<=evs;k++){
                        Arrays.fill(dp[i][j][k],-1);
                    }
                }
            }
            out.println(recur(dp,0,arr,ods,evs,2));
        }
        out.flush();
        out.close();
    }
    static int recur(int[][][][] dp,int i,int[] arr,int ods,int evs,int p){
        if(i==arr.length){
            return 0;
        }
        if(dp[i][ods][evs][p]!=-1){
            return dp[i][ods][evs][p];
        }
        int ans=0;
        if(arr[i]!=-1){
            if((arr[i]==0&&p==1)||(arr[i]==1&&p==0)){
                ans++;
            }
            ans+=recur(dp,i+1,arr,ods,evs,arr[i]);
        }else{
            int t1=Integer.MAX_VALUE;
            int t2=Integer.MAX_VALUE;
            if(ods>0){
                t1=0;
                if(p==0){
                    t1++;
                }
                t1+=recur(dp,i+1,arr,ods-1,evs,1);
            }
            if(evs>0){
                t2=0;
                if(p==1){
                    t2++;
                }
                t2+=recur(dp,i+1,arr,ods,evs-1,0);
            }
            ans=Math.min(t1,t2);
        }
        dp[i][ods][evs][p]=ans;
        return ans;
    }
    static class FastReader {

        byte[] buf = new byte[2048];
        int index, total;
        InputStream in;

        FastReader(InputStream is) {
            in = is;
        }

        int scan() throws IOException {
            if (index >= total) {
                index = 0;
                total = in.read(buf);
                if (total <= 0) {
                    return -1;
                }
            }
            return buf[index++];
        }

        String next() throws IOException {
            int c;
            for (c = scan(); c <= 32; c = scan()) ;
            StringBuilder sb = new StringBuilder();
            for (; c > 32; c = scan()) {
                sb.append((char) c);
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c, val = 0;
            for (c = scan(); c <= 32; c = scan()) ;
            boolean neg = c == '-';
            if (c == '-' || c == '+') {
                c = scan();
            }
            for (; c >= '0' && c <= '9'; c = scan()) {
                val = (val << 3) + (val << 1) + (c & 15);
            }
            return neg ? -val : val;
        }
        long nextLong() throws IOException {
            int c;
            long val = 0;
            for (c = scan(); c <= 32; c = scan()) ;
            boolean neg = c == '-';
            if (c == '-' || c == '+') {
                c = scan();
            }
            for (; c >= '0' && c <= '9'; c = scan()) {
                val = (val << 3) + (val << 1) + (c & 15);
            }
            return neg ? -val : val;
        }
    }
}

