    static class TaskC {
        int INF = 1000;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int odd = (N + 1) / 2;
            int even = N / 2;
            int[] arr = new int[N];
            for (int i = 0; i < N; i++) {
                int a = in.nextInt();
                if (a != 0) {
                    if (a % 2 == 0) {
                        even--;
                    } else {
                        odd--;
                    }
                }
                arr[i] = a;
            }
            int[][][][] dp = new int[N][2][odd + 1][even + 1];
            if (arr[0] != 0) {
                int par = (arr[0] + 1) % 2;
                for (int oddC = 0; oddC <= odd; oddC++) {
                    for (int evenC = 0; evenC <= even; evenC++) {
                        dp[0][par][oddC][evenC] = INF;
                    }
                }
            } else {
                for (int par = 0; par < 2; par++) {
                    for (int oddC = 0; oddC <= odd; oddC++) {
                        for (int evenC = 0; evenC <= even; evenC++) {
                            if (par == 0) {
                                if (evenC == 0) {
                                    dp[0][0][oddC][evenC] = INF;
                                }
                            } else {
                                if (oddC == 0) {
                                    dp[0][1][oddC][evenC] = INF;
                                }
                            }
                            if (0 < N - 1 && arr[1] != 0 && arr[1] % 2 != par) {
                                dp[0][par][oddC][evenC]++;
                            }
                        }
                    }
                }
            }
            int cnt = 0;
            for (int i = 1; i < N; i++) {
                if (arr[i] != 0 && arr[i - 1] != 0 && arr[i] % 2 != arr[i - 1] % 2) {
                    cnt++;
                }
            }
            for (int i = 1; i < N; i++) {
                for (int par = 0; par < 2; par++) {
                    for (int oddC = 0; oddC <= odd; oddC++) {
                        for (int evenC = 0; evenC <= even; evenC++) {
                            if (arr[i] != 0) {
                                if (par == arr[i] % 2) {
                                    dp[i][par][oddC][evenC] = Math.min(dp[i - 1][0][oddC][evenC], dp[i - 1][1][oddC][evenC]);
                                } else {
                                    dp[i][par][oddC][evenC] = INF;
                                }
                            } else {
                                if (par == 0) {
                                    if (evenC == 0) {
                                        dp[i][0][oddC][evenC] = INF;
                                    } else {
                                        dp[i][0][oddC][evenC] = Math.min(dp[i - 1][0][oddC][evenC - 1], dp[i - 1][1][oddC][evenC - 1] + 1);
                                    }
                                } else {
                                    if (oddC == 0) {
                                        dp[i][1][oddC][evenC] = INF;
                                    } else {
                                        dp[i][1][oddC][evenC] = Math.min(dp[i - 1][0][oddC - 1][evenC] + 1, dp[i - 1][1][oddC - 1][evenC]);
                                    }
                                }
                                if (i < N - 1 && arr[i + 1] != 0 && arr[i + 1] % 2 != par) {
                                    dp[i][par][oddC][evenC]++;
                                }
                            }
                        }
                    }
                }
            }
            out.println(cnt + Math.min(dp[N - 1][0][odd][even], dp[N - 1][1][odd][even]));
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

