  static void solve() throws Exception {
    n = in.nextInt();
    a = new int[n];
    int odd = 0, even = 0;
    for (int i = 0; i < n; i++) {
      a[i] = in.nextInt();
      if (a[i] % 2 == 1) odd++;
      else if (a[i] != 0) even++;
    }



    even = n / 2 - even;
    odd = n / 2 - odd + (n % 2);





    int cur = 0;
    while (cur < n && a[cur] == 0) {cur++;}
    if (cur == n) {out.println(Math.min(n - 1, 1)); return;}


    List<Gap> gaps = new ArrayList<>();

    if (cur > 0) gaps.add(new Gap(0, cur - 1));


    int start = cur;
    while (cur < n) {
      while (cur < n && a[cur] != 0) {cur++;}
      start = cur;
      while (cur < n && a[cur] == 0) {cur++;}
      if (start < cur) gaps.add(new Gap(start, cur - 1));
    }














    List<Gap> odds = new ArrayList<>();
    List<Gap> evens = new ArrayList<>();
    int count = 0;

























      boolean first = false, last = false;
      for (int i = 0; i < gaps.size(); i++) {

        Gap g = gaps.get(i);
        g.size = g.end - g.start + 1;
        if (g.start == 0) {first = true; continue;}
        if (g.end == n - 1) {last = true; continue;}


        if (a[(g.start + n - 1) % n] % 2 ==  0 && a[g.end + 1] % 2 == 0) {g.type = 0; evens.add(g);}
        else if (a[(g.start + n - 1) % n] % 2 == 1 && a[g.end + 1] % 2 == 1) {g.type = 1; odds.add(g);}
        else {g.type = 2; count++;}
      }

      Collections.sort(odds, (x, y) -> (x.size - y.size));
      Collections.sort(evens, (x, y) -> (x.size - y.size));

      for (int i = 0; i < odds.size(); i++) {
        if (odds.get(i).size <= odd) {odd -= odds.get(i).size;}
        else {count += 2;}
      }

      for (int i = 0; i < evens.size(); i++) {
        if (evens.get(i).size <= even) {even -= evens.get(i).size;}
        else {count += 2;}
      }



      if (first) {
        if (a[gaps.get(0).end + 1] % 2 == 1) {
          if (odd < gaps.get(0).size) {count++;}
          else {odd -= gaps.get(0).size;}
        }
        else {
          if (even < gaps.get(0).size) {count++;}
          else {even -= gaps.get(0).size;}
        }
      }

      if (last) {
        if (a[gaps.get(gaps.size() - 1).start - 1] % 2 == 1) {
          if (odd < gaps.get(gaps.size() - 1).size) {count++;}
          else {odd -= gaps.get(gaps.size() - 1).size;}
        }
        else {
          if (even < gaps.get(gaps.size() - 1).size) {count++;}
          else {even -= gaps.get(gaps.size() - 1).size;}
        }
      }


    for (int i = 0; i < n - 1; i++) {
      if (a[i] == 0 || a[i + 1] == 0) continue;
      if (a[i] % 2 != a[i + 1] % 2) count++;
    }

    System.out.println(count);




  }


  static class Gap {
