        FastReader fr =new FastReader();    PrintWriter op =new PrintWriter(System.out);

        n =fr.nextInt() ;   dp =new int[n+1][n/2+1][3] ;    ar =new int[n+1] ;
        ct =new int[n+1] ;  e =n/2 ;    o =(int)Math.ceil(n/2.0) ;   int i ,j ;
        if (n==1)   op.println("0") ;
        else {
            for (i =1 ; i<=n ; ++i) {
                j =fr.nextInt() ;   if (j==0)   {   ar[i] =0 ;  ct[i] =1 ;  continue ;  }
                if ((j&1)==0)   {   ar[i] =2 ;  --e ;   }
                if ((j&1)==1)   {   ar[i] =1 ;  --o ;   }
            }
            for (i =1 ; i<=n ; ++i) ct[i] += ct[i-1] ;
            for (i =0 ; i<=n ; ++i) {
                for (j =0 ; j<=n/2 ; ++j)   dp[i][j][0] =dp[i][j][1] =dp[i][j][2] =-1 ;
            }
            op.println(calc (1 , e , -1)) ;
        }
        op.flush(); op.close();
    }
    static int calc (int ps , int ec , int p) {
        int i =0 ,oc =o-(ct[ps-1]-(e-ec)) ,j ;
        if (ps==1) {
            if (ar[ps]==0) {
                j =n+5 ;
                if (oc>0)   j =Math.min(j,calc (ps+1 , ec , 1)) ;
                if (ec>0)   j =Math.min(j,calc (ps+1 , ec-1 , 2)) ;
                i =j ;
            }
            else    i =calc (ps+1 , ec , ar[ps]) ;
        }
        else {
            if (dp[ps][ec][p] != -1)    return dp[ps][ec][p] ;
            if (ar[ps]==0) {
                j =n+5 ;    int k ;
                if (oc>0) {
                    if (p==2)   k =1 ;  else    k =0 ;  
                    if (ps<n)   j =Math.min(j,calc (ps+1 , ec , 1)+k) ;
                    else    j =Math.min(j,k) ;
                }
                if (ec>0) {
                    if (p==1)   k =1 ;  else    k =0 ;
                    if (ps<n)   j =Math.min(j,calc (ps+1 , ec-1 , 2)+k) ;
                    else    j =Math.min(j,k) ;
                }
                i =j ;
            }
            else {
                if (p!=ar[ps])  j =1 ;  else    j =0 ;
                if (ps<n)   i =j+calc (ps+1 , ec , ar[ps]) ;
                else    i =j ;  
            }
            dp[ps][ec][p] =i ;
        }
        return i ;
    }
