import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.function.IntConsumer;
import java.util.InputMismatchException;
import java.io.IOException;
import java.io.InputStream;


public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC(in, out);
        try {
            solver.solve();
        } catch (ExitException ignored) {
        }
        out.close();
    }

    static class TaskC {
        FastScanner sc;
        PrintWriter out;

        public TaskC(FastScanner sc, PrintWriter out) {
            this.sc = sc;
            this.out = out;
        }

        public void solve() {
            times(1, this::solve);
        }

        public void solve(int time) {
            int n = sc.nextInt();
            int[] set = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                int val = sc.nextInt();
                if (val > 0) {
                    set[i] = val;
                }
            }

            int start = 0;
            int end = 0;
            int so = 0;
            int sx = 0;
            int oe = 0;
            int xe = 0;
            if (set[1] == 0) {
                for (int i = 1; i <= n; i++) {
                    if (set[i] == 0) {
                        start++;
                    } else {
                        if (set[i] % 2 == 0) so = start;
                        else sx = start;
                        break;
                    }
                }
                if (start == n) {
                    if (n == 1) answer(0);
                    answer(1);
                }
            }

            if (set[n] == 0) {
                for (int i = n; i >= 1; i--) {
                    if (set[i] == 0) {
                        end++;
                    } else {
                        if (set[i] % 2 == 0) oe = end;
                        else xe = end;
                        break;
                    }
                }
            }

            int ans = 0;
            int odd = (n + 1) / 2;
            int even = n - odd;
            IntArray oo = new IntArray();
            IntArray xx = new IntArray();
            for (int i = 1 + start, prev = set[i] % 2, len = 0; i <= n - end; i++) {
                if (set[i] == 0) {
                    len++;
                    continue;
                }

                int mod = set[i] % 2;
                if (mod == 0) even--;
                else odd--;
                if (mod == prev) {
                    if (len > 0) {
                        if (mod == 0) oo.add(len);
                        else xx.add(len);
                    }
                } else { 
                    ans++;
                }
                prev = mod;
                len = 0;
            }

            oo.sort();
            xx.sort();
            for (int i = 0; i < oo.size; i++) {
                if (even >= oo.get(i)) {
                    even -= oo.get(i);
                } else {
                    ans += 2;
                }
            }
            if (so > 0) {
                if (even >= so) {
                    even -= so;
                } else {
                    ans++;
                }
            }
            if (oe > 0) {
                if (even >= oe) {
                    even -= oe;
                } else {
                    ans++;
                }
            }

            for (int i = 0; i < xx.size; i++) {
                if (odd >= xx.get(i)) {
                    odd -= xx.get(i);
                } else {
                    ans += 2;
                }
            }
            if (sx > 0) {
                if (odd >= sx) {
                    odd -= sx;
                } else {
                    ans++;
                }
            }
            if (xe > 0) {
                if (odd >= xe) {
                    odd -= xe;
                } else {
                    ans++;
                }
            }
            answer(ans);
        }

        private void answer(Object ans) {
            out.println(ans);
            throw new ExitException();
        }

        private void times(int n, IntConsumer consumer) {
            for (int i = 0; i < n; i++) {
                try {
                    consumer.accept(i);
                } catch (ExitException ignored) {
                }
            }
        }

    }

    static class IntArray {
        public int[] array;
        public int size;

        public IntArray() {
            this(20);
        }

        public IntArray(int capacity) {
            capacity = Math.max(capacity, 10);
            this.array = new int[capacity];
        }

        public void add(int n) {
            ensureCapacity(size + 1);
            array[size++] = n;
        }

        public void sort() {
            shuffle();
            Arrays.sort(array, 0, size);
        }

        public int get(int idx) {
            if (idx >= size) throw new IndexOutOfBoundsException();
            return array[idx];
        }

        void shuffle() {
            for (int i = 0; i < size; i++) {
                int r = i + (int) (Math.random() * (size - i));
                {
                    int tmp = array[i];
                    array[i] = array[r];
                    array[r] = tmp;
                }
            }
        }

        private void ensureCapacity(int cap) {
            if (cap > array.length) grow();
        }

        private void grow() {
            int oldCapacity = array.length;
            int newCapacity = oldCapacity + (oldCapacity >> 1);
            array = Arrays.copyOf(array, newCapacity);
        }

    }

    static class ExitException extends RuntimeException {
    }

    static class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

    }
}

import java.util.*;
