public class CF1287C extends PrintWriter {
	CF1287C() { super(System.out, true); }
	Scanner sc = new Scanner(System.in);
	public static void main(String[] $) {
		CF1287C o = new CF1287C(); o.main(); o.flush();
	}

	int sum(int[] aa, int n) {
		int s = 0;
		for (int i = 0; i < n; i++)
			s += aa[i];
		return s;
	}
	void reverse(int[] aa, int n) {
		for (int i = 0, j = n - 1; i < j; i++, j--) {
			int tmp = aa[i]; aa[i] = aa[j]; aa[j] = tmp;
		}
	}
	int solve(int k, int[] qu, int cnt) {
		int ans = 0;
		while (k > 0 && cnt > 0) {
			ans++;
			if (k >= qu[cnt - 1])
				k -= qu[--cnt];
			else
				k = 0;
		}
		return ans;
	}
	int solve_(int k0, int[] qu1, int cnt1, int[] qu11, int cnt11) {
		Arrays.sort(qu1, 0, cnt1);
		Arrays.sort(qu11, 0, cnt11);
		int ans;
		if (cnt1 >= 1 && k0 <= qu1[cnt1 - 1])
			ans = 1;
		else if (cnt1 == 2 && k0 <= qu1[0] + qu1[1])
			ans = 2;
		else {
			ans = k0 * 2;
			int s = sum(qu11, cnt11);
			if (k0 <= s)
				ans = Math.min(ans, solve(k0, qu11, cnt11) * 2);
			if (cnt1 >= 1 && k0 - qu1[0] <= s)
				ans = Math.min(ans, 1 + solve(k0 - qu1[0], qu11, cnt11) * 2);
			if (cnt1 == 2 && k0 - qu1[1] <= s)
				ans = Math.min(ans, 1 + solve(k0 - qu1[1], qu11, cnt11) * 2);
			if (cnt1 == 2 && k0 - qu1[0] - qu1[1] <= s)
				ans = Math.min(ans, 2 + solve(k0 - qu1[0] - qu1[1], qu11, cnt11) * 2);
		}
		return ans;
	}
	void main() {
		int n = sc.nextInt();
		int[] pp = new int[n];
		int k0 = 0, k1 = 0;
		for (int i = 0; i < n; i++) {
			int p = sc.nextInt();
			if (p == 0)
				pp[i] = -1;
			else if ((pp[i] = p % 2) == 0)
				k0++;
			else
				k1++;
		}
		k0 = n / 2 - k0;
		k1 = (n + 1) / 2 - k1;
		if (k0 + k1 == n) {
			println(n == 1 ? 0 : 1);
			return;
		}
		int[] qu00 = new int[n]; int cnt00 = 0;
		int[] qu11 = new int[n]; int cnt11 = 0;
		int[] qu01 = new int[n]; int cnt01 = 0;
		int[] qu0 = new int[2]; int cnt0 = 0;
		int[] qu1 = new int[2]; int cnt1 = 0;
		int ans = 0, i_ = -1;
		for (int i = 0; i < n; i++) {
			if (pp[i] == -1)
				continue;
			int g = i - i_ - 1;
			if (g > 0) {
				if (pp[i] == 0) {
					if (i_ == -1)
						qu0[cnt0++] = g;
					else if (pp[i_] == pp[i])
						qu00[cnt00++] = g;
					else
						qu01[cnt01++] = g;
				} else {
					if (i_ == -1)
						qu1[cnt1++] = g;
					else if (pp[i_] == pp[i])
						qu11[cnt11++] = g;
					else
						qu01[cnt01++] = g;
				}
			}
			if (i_ != -1 && pp[i_] != pp[i])
				ans++;
			i_ = i;
		}
		if (k0 + k1 == 0) {
			println(ans);
			return;
		}
		int g = n - i_ - 1;
		if (g > 0) {
			if (pp[i_] == 0)
				qu0[cnt0++] = g;
			else
				qu1[cnt1++] = g;
		}
		if ((k0 -= sum(qu00, cnt00) + sum(qu0, cnt0)) >= 0) {
			if ((k0 -= sum(qu01, cnt01)) > 0)
				ans += solve_(k0, qu1, cnt1, qu11, cnt11);
		} else if ((k1 -= sum(qu11, cnt11) + sum(qu1, cnt1)) >= 0) {
			if ((k1 -= sum(qu01, cnt01)) > 0)
				ans += solve_(k1, qu0, cnt0, qu00, cnt00);
		}
		println(ans);
	}
}

import java.util.*;
import java.io.*;

public class Solution{

	public Solution(){
		Scanner sc = new Scanner(System.in);
		int tests = 1;

        for(int t=1; t<=tests; t++){
			int n = sc.nextInt();

			int[] arr = new int[n];
			int oddCount = 0;
			int evenCount = 0;

			for(int i=0; i<n; i++){
				arr[i] = sc.nextInt();
				if(arr[i] > 0){
					if(arr[i]%2 == 0){
						evenCount++;
					}
					else{
						oddCount++;
					}
				}
			}
			int totEven = n/2;
			int totOdd = n-totEven;
			oddCount = totOdd-oddCount;
			evenCount = totEven-evenCount;

			int[] odd = new int[n];
			int[] even = new int[n];

			int res = 0;
			for(int i=0; i<(n-1); i++){
				if(arr[i] == 0){
					continue;
				}
				int j = i+1;
				while(j < n && arr[j] == 0){
					j++;
				}
				if(j == n){
					break;
				}

				if((arr[i]%2) == 0){
					if(arr[j]%2 == 0){
						even[j-i-1]++;
					}
					else{
						res++;
					}
				}
				else{
					if(arr[j]%2 == 1){
						odd[j-i-1]++;
					}
					else{
						res++;
					}
				}
			}

			for(int i=1; i<n; i++){
				int req = i*odd[i];
				if(req <= oddCount){
					oddCount -= req;
				}
				else{
					int comp = oddCount/i;
					odd[i] -= comp;
					res += (odd[i]*2);
					comp *= i;
					oddCount -= comp;
				}

				req = i*even[i];
				if(req <= evenCount){
					evenCount -= req;
				}
				else{
					int comp = evenCount/i;
					even[i] -= comp;
					res += (even[i]*2);
					comp *= i;
					evenCount -= comp;
				}
			}

			int index = 0;
			while(index < n && arr[index] == 0){
				index++;
			}

			if(index == n){
				if(n == 1){
					System.out.println(0);
				}
				else{
					System.out.println(1);
				}
				continue;
			}

			if(arr[index]%2 == 0){
				if(index <= evenCount){
					evenCount -= index;
				}
				else{
					res++;
				}
			}
			else{
				if(index <= oddCount){
					oddCount -= index;
				}
				else{
					res++;
				}
			}

			index = n-1;
			while(index >= 0 && arr[index] == 0){
				index--;
			}

			if(arr[index]%2 == 0){
				if((n-1-index) <= evenCount){
					evenCount -= index;
				}
				else{
					res++;
				}
			}
			else{
				if((n-1-index) <= oddCount){
					oddCount -= index;
				}
				else{
					res++;
				}
			}

			System.out.println(res);
        }
	}

	public static void main(String[] args){
		new Solution();
	}
}

import java.util.Scanner;

public class Garland {

    private static int countJi;
    private static int countOu;

    private static void insert(int[] arr, int index, int num) {

        if ((num % 2 == 0 && Garland.countOu > 0) || (num % 2 != 0 && Garland.countJi <= 0)) {
            arr[index] = 2;
            Garland.countOu--;
        } else {
            arr[index] = 1;
            Garland.countJi--;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        Garland.countJi = (n % 2 == 0) ? (n / 2) : (n / 2) + 1;
        Garland.countOu = n / 2;
        int[] arr    = new int[n];
        int[] disArr = new int[n];
        int firstIndex = -1;
        int lastIndex  = -1;
        int frontNum   = -1;
        int distance   = 0;
        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
            if (arr[i] != 0) {
                lastIndex = i;
                if (firstIndex == -1) {
                    firstIndex = i;
                }
                if (arr[i] % 2 == 0) {
                    Garland.countOu--;
                } else {
                    Garland.countJi--;
                }
                if (frontNum == -1) {
                    frontNum = arr[i];
                    distance = 0;
                } else {
                    if ((frontNum % 2 == 0 && arr[i] % 2 == 0) || (frontNum % 2 != 0 && arr[i] % 2 != 0)) {
                        disArr[distance] = 1;
                    }
                    frontNum = arr[i];
                    distance = 0;
                }
                continue;
            }
            distance++;
        }
        int answer = 0;

        if (firstIndex == -1) {
            answer = (n == 1) ? 0 : 1;
        } else {

            for (int i = 1; i < n; i++) {
                if (disArr[i] != 0) {
                    distance = i;
                    for (int j = 0; j < n - distance - 1; j++) {

                        if (arr[j] != 0 && arr[j + distance + 1] != 0 &&
                                ((arr[j] % 2 == 0 && arr[j + distance +1] % 2 == 0) ||
                                        (arr[j] % 2 != 0 && arr[j + distance + 1] % 2 != 0))) {
                            boolean isZero = true;
                            for (int k = j + 1; k <= j + distance; k++) {
                                if (arr[k] != 0) {
                                    isZero = false;
                                    break;
                                }
                            }
                            if (isZero) {
                                if (arr[j] % 2 == 0 && Garland.countOu >= distance) {
                                    for (int k = j + 1; k <= j + distance; k++) {
                                        arr[k] = 2;
                                    }
                                    Garland.countOu -= distance;
                                }
                                if (arr[j] % 2 != 0 && Garland.countJi >= distance) {
                                    for (int k = j + 1; k <= j + distance; k++) {
                                        arr[k] = 1;
                                    }
                                    Garland.countJi -= distance;
                                }
                            }
                        }
                    }
                }
            }

            if (lastIndex != (n - 1)) { 
                int isInsert = -1;
                if (arr[lastIndex] % 2 == 0 && Garland.countOu >= (n - lastIndex - 1)) { 
                    isInsert = 2;
                    Garland.countOu -= (n - lastIndex - 1);
                }
                if (arr[lastIndex] % 2 != 0 && Garland.countJi >= (n - lastIndex - 1)) { 
                    isInsert = 1;
                    Garland.countJi -= (n - lastIndex - 1);
                }
                if (isInsert != -1) {
                    for (int i = lastIndex + 1; i < n; i++) {
                        arr[i] = isInsert;
                    }
                }
            }

            for (int i = firstIndex - 1; i >= 0; i--) {
                Garland.insert(arr, i, arr[i + 1]);
            }

            for (int i = firstIndex + 1; i < n; i++) {
                if (arr[i] != 0) {
                    continue;
                }

                if ((i != (n - 1)) && arr[i - 1] != 0 && arr[i + 1] != 0 &&
                        ((arr[i - 1] % 2 == 0) && (arr[i + 1] % 2 != 0) || (arr[i - 1] % 2 != 0) && (arr[i + 1] % 2 == 0))) {
                    continue;
                }

                Garland.insert(arr, i, arr[i - 1]);
            }

            for (int i = firstIndex + 1; i < n; i++) {
                arr[i] = (arr[i] == 0) ? 1 : arr[i];
            }

            for (int i = 0; i < n - 1; i++) {
                if ((arr[i] % 2 == 0 && arr[i + 1] % 2 != 0) || (arr[i] % 2 != 0 && arr[i + 1] % 2 == 0)) {
                    answer++;
                }
            }
        }
        System.out.println(answer);
    }

}

