  public static class Solver {
    public Solver() {

      int N = sc.nextInt();

      int[] A = new int[N];
      int odd = (N+1)/2;
      for (int i=0; i<N; i++) {
        int a = sc.nextInt();
        if (a == 0) {
          A[i] = -1;
        } else {
          odd -= A[i] = a % 2;
        }
      }

      long[][][] dp = new long[N+1][N+1][2];
      for (int i=0; i<=N; i++) {
        for (int j=0; j<=N; j++) {
          for (int k=0; k<2; k++) {
            dp[i][j][k] = INF;
          }
        }
      }
      dp[0][0][0] = 0;
      dp[0][0][1] = 0;
      for (int i=1; i<=N; i++) {
        for (int j=0; j<=odd; j++) {
          if (A[i-1] == -1) {
            dp[i][j][0] = Math.min(dp[i-1][j][0], dp[i-1][j][1] + 1);
            if (j-1 >= 0) dp[i][j][1] = Math.min(dp[i-1][j-1][0] + 1, dp[i-1][j-1][1]);
          } else {
            dp[i][j][A[i-1]] = Math.min(dp[i-1][j][0] + A[i-1], dp[i-1][j][1] + (1-A[i-1]));
          }
        }
      }

      out.println(Math.min(dp[N][odd][0], dp[N][odd][1]));

    }
  }

