	    				{
	    					dp[i][j][k][m] = n + 1;
	    				}
	    				if (arr[i] != -1)
	    				{
	    					dp[i][j][k][1 - arr[i]] = n + 1;
	    				}

	    			}
	    		}
	    	}
	    }

