		if(index >= x.length) {
			return 0;
		}
		if (dp[index][oddsNeeded][prev] != -1) {
			return dp[index][oddsNeeded][prev];
		}
		if (x[index] != 0) {
			dp[index][oddsNeeded][0] = solve(x, index + 1, oddsNeeded, numbersMissing, 0, dp);
			return dp[index][oddsNeeded][0];
		}

		int min = Integer.MAX_VALUE;
