		if (evensNeeded > 0) {
			int evenParity = (prev == 1 || isOdd(x, index - 1) ? 1 : 0) + (isOdd(x, index + 1) ? 1 : 0);
			min = Math.min(min, evenParity + solve(x, index + 1, oddsNeeded, numbersMissing - 1, 2, dp));
		}
		dp[index][oddsNeeded][prev] = min;
		return min;
	}
	public static boolean isOdd(int[] x, int i) {
		if (i < 0 || i >= x.length || x[i] == 0) {
			return false;
		}
		return x[i] % 2 == 1;
	}
	public static boolean isEven(int[] x, int i) {
		if (i < 0 || i >= x.length || x[i] == 0) {
			return false;
		}
		return x[i] % 2 == 0;
	}
}

