public class Main {

	private static final int INF = 1000000000;

	public static void main(String[] args) {

        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        int n = in.nextInt(), s0 = 0, s1 = 0;
        int[] a = new int[200];
        int[] b = new int[200];
        int[] c = new int[200];
        int[][][] f = new int[200][200][2];
        for (int i = 0; i < 200; i ++)
        	for (int j = 0; j < 200; j ++)
        		for (int k = 0; k < 2; k ++) f[i][j][k] = INF;
        c[0] = 0;
        for (int i = 1; i <= n; i ++) {
        	a[i] = in.nextInt();
        	c[i] = c[i - 1];
        	if (a[i] == 0) {
        		c[i] ++;
        		continue;
        	}
        	b[a[i]] = 1;
        }
        for (int i = 1; i <= n; i ++) {
        	if (b[i] == 0) 
        		if (i % 2 == 1) s1 ++; else s0 ++;
        }
        if (a[1] == 0) {
        	if (s0 > 0) f[1][1][0] = 0;
        	if (s1 > 0) f[1][0][1] = 0; 
        } else f[1][0][a[1] % 2] = 0;
        for (int i = 1; i < n; i ++) {
        	for (int j = 0; j <= i; j ++) {
        		for (int k = 0; k < 2; k ++) {
        			if (f[i][j][k] == INF) continue;
        			if (a[i + 1] == 0) {
        				if (j + 1 <= s0) f[i + 1][j + 1][0] = Math.min(f[i + 1][j + 1][0], f[i][j][k] + (k ^ 0));
        				if (c[i]- j + 1 <= s1) f[i + 1][j][1] = Math.min(f[i + 1][j][1],  f[i][j][k] + (k ^ 1));
        			} else {
        				f[i + 1][j][a[i + 1] % 2] = Math.min(f[i + 1][j][a[i + 1] % 2],  f[i][j][k] + (k ^ (a[i + 1] % 2)));
        			}
        		}
        	}
        }
        int ans = n + 1;
        for (int i = 0; i <= s0; i ++) {
        	ans = Math.min(ans, f[n][i][0]);
        	ans = Math.min(ans, f[n][i][1]);
        }
        out.println(ans);
        out.close();       
	}

