public class Solution{
    public static void main (String[] args)
    {

        Scanner s=new Scanner(System.in);
        int n=s.nextInt();
        int a[]=new int[n];
        for(int i=0;i<n;i++) {
            a[i]=s.nextInt();
        }
        HashSet<Integer> h=new HashSet<Integer>();
        int count=0,odd=0,even=0;
        ArrayList<Integer> list=new ArrayList<Integer>();
        for(int i=0;i<n;i++) {
            if(a[i]!=0) {
                h.add(a[i]);
                list.add(i);
            }
        }
        if(list.size()==0) {
            if(n==1)
                System.out.println(0);
            else
                System.out.println(1);
            return ;
        }
        for(int i=1;i<=n;i++) {
            if(!h.contains(i)) {
                if(i%2==0)
                    even++;
                else
                    odd++;
            }
        }
        ArrayList<Integer> qe=new ArrayList<Integer>();
        ArrayList<Integer> qo=new ArrayList<Integer>();
        for(int i=1;i<list.size();i++) {
            int idx1=list.get(i);
            int idx2=list.get(i-1);
            if(a[idx1]%2==a[idx2]%2) {

                int diff=idx1-idx2-1;

                if(a[idx1]%2==0) {

                    qe.add(diff);

                }
                else {

                    qo.add(diff);

                }
            }
            else {
                count+=1;
            }

        }

        Collections.sort(qe);Collections.sort(qo);

        for(int i=0;i<qe.size();i++) {
            if(even>=qe.get(i)) {
                even-=qe.get(i);
            }
            else {
                count+=2;
            }
        }
        for(int i=0;i<qo.size();i++) {
            if(odd>=qo.get(i)) {
                odd-=qo.get(i);
            }
            else {
                count+=2;
            }
        }
        if(list.size()>=1) {
            int idx=list.get(0);
            int diff=idx;
            if(a[idx]%2==0) {
                if(even>=diff) {
                    even-=diff;
                }
                else {
                    count+=1;
                }
            }
            else {
                if(odd>=diff) {
                    odd-=diff;
                }
                else {
                    count+=1;
                }
            }
        }
        if(list.size()>=1) {
            int idx=list.get(list.size()-1);
            int diff=n-1-idx;
            if(a[idx]%2==0) {
                if(even>=diff) {
                    even-=diff;
                }
                else {
                    count+=1;
                }
            }
            else {
                if(odd>=diff) {
                    odd-=diff;
                }
                else {
                    count+=1;
                }
            }
        }
        System.out.println(count);

    }
}

