            if (sym == 0) {
                int case1 = -1, case2 = -1;
                if (odd != 0) {
                    g.set(id, 1);
                    case1 = rec(g, odd - 1, even, id + 1, 1);
                    if (id > 0) {
                        case1 += Math.abs(g.get(id - 1) - 1);
                    }
                    g.set(id, 0);
                }
                if (even != 0) {
                    g.set(id, 2);
                    case2 = rec(g, odd, even - 1, id + 1, 2);
                    if (id > 0) {
                        case2 += Math.abs(g.get(id - 1) - 2);
                    }
                    g.set(id, 0);
                }
                if (case1 != -1 && case2 != -1) {
                    ans = Math.min(case1, case2);
                }
                if (case1 == -1) {
                    ans = case2;
                }
                if (case2 == -1) {
                    ans = case1;
                }
            } else {
                ans += rec(g, odd, even, id + 1, sym);
                if (id > 0) {
                    ans += Math.abs(g.get(id - 1) - sym);
                }
            }
            dp[state][odd][even][id] = ans;
        }
        return ans;
    }

}

