            if(!present[i]){
                if(i%2==0){
                    even++;
                }
                else{
                    odd++;
                }
            }
        }

        int dp[][][][]=new int[n+1][odd+1][even+1][2];
        for(int i=0;i<=n;i++){
            for(int j=0;j<=odd;j++){
                for(int k=0;k<=even;k++){
                    for(int l=0;l<2;l++){
                        dp[i][j][k][l]=Integer.MAX_VALUE/2;
                    }
                }
            }
        }
