            HashSet<Integer> set = new HashSet<>();
            for (int i = 0; i < N; i++) {
                a[i] = in.nextInt();
                set.add(a[i]);
            }
            for (int i = 1; i <= N; i++) {
                if (!set.contains(i)) {
                    if (i % 2 == 0) {
                        evenRemaining++;
                    } else {
                        oddRemaining++;
                    }
                }
            }
            if (N == 1) {
                out.printLine(0);
                return;
            } else {
                ans = Math.min(recur(0, evenRemaining, oddRemaining, 0), recur(0, evenRemaining, oddRemaining, 1));
            }
            out.printLine(ans);
        }

        public int recur(int index, int evenRemaining, int oddRemaining, int last) {
            if (index >= a.length) {
                return 0;
            }
            if (dp[index][evenRemaining][oddRemaining][last] != Constants.INT_INFINITY) {
                return dp[index][evenRemaining][oddRemaining][last];
            }
            int p = Constants.INT_INFINITY, q = Constants.INT_INFINITY;
            if (a[index] == 0) {
                if (evenRemaining > 0) {
                    p = recur(index + 1, evenRemaining - 1, oddRemaining, 0);
                    if (last != 0) {
                        p++;
                    }
                }
                if (oddRemaining > 0) {
                    q = recur(index + 1, evenRemaining, oddRemaining - 1, 1);
                    if (last != 1) {
                        q++;
                    }
                }
            } else {
                p = recur(index + 1, evenRemaining, oddRemaining, a[index] % 2);
                if (last != (a[index] % 2)) {
                    p++;
                }
            }
            return dp[index][evenRemaining][oddRemaining][last] = Math.min(p, q);
        }

    }

    static class Constants {
        public static final Integer INT_INFINITY = (int) 2e9;

    }

    static class OutputWriter {
        PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tokenizer = null;

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    tokenizer = new StringTokenizer(in.readLine());
                }
                return tokenizer.nextToken();
            } catch (IOException e) {
                return null;
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

