		for (int i = 0; i < arr.length; i++) {
			arr[i] = sc.nextInt();
			v[arr[i]] = true;
		}

		for (int i = 1; i <= n; i++) {
			if (!v[i]) {
				if (i % 2 == 0)
					even++;
				else
					odd++;
			}
		}

		int s = Math.max(odd, even) + 10;
		int[][][] dpOdd = new int[n + 1][s][s];
		int[][][] dpEven = new int[n + 1][s][s];
		for (int x = 0; x < n; x++)
			for (int i = 0; i < s; i++) {
				for (int j = 0; j < s; j++) {
					dpOdd[x][i][j] = -1;
					dpEven[x][i][j] = -1;
				}
			}
		int a = rec(true, 0, arr, odd, even, dpOdd, dpEven);
		int b = rec(false, 0, arr, odd, even, dpOdd, dpEven);

		System.out.println(Math.min(a, b));
	}

	public static int rec(boolean isLastOdd, int idx, int[] arr, int odd, int even, int[][][] dpOdd, int[][][] dpEven) {
		if (idx == arr.length) {
			return 0;
		}

		if (isLastOdd) {
			if (dpOdd[idx][odd][even] != -1)
				return dpOdd[idx][odd][even];
		} else {
			if (dpEven[idx][odd][even] != -1)
				return dpEven[idx][odd][even];
		}

		int ans = 0;

		if (arr[idx] == 0) {
			int a = arr.length + 10, b = arr.length + 10;
			if (odd > 0) {
				int p = isLastOdd ? 0 : 1;
				a = p + rec(true, idx + 1, arr, odd - 1, even, dpOdd, dpEven);
			}
			if (even > 0) {
				int p = !isLastOdd ? 0 : 1;
				b = p + rec(false, idx + 1, arr, odd, even - 1, dpOdd, dpEven);
			}
			ans = Math.min(a, b);
		} else {
			boolean isOdd = arr[idx] % 2 != 0;
			int p = isLastOdd == isOdd ? 0 : 1;
			ans = p + rec(isOdd, idx + 1, arr, odd, even, dpOdd, dpEven);
		}
		if (isLastOdd) {
			dpOdd[idx][odd][even] = ans;
		} else {
			dpEven[idx][odd][even] = ans;
		}
		return ans;
	}

