public class TaskC {
    public static String doMain(Reader reader) throws IOException {
        MyReader in = new MyReader(reader);
        int n = in.nextInt();
        int[] nums = in.readIntArray(n);
        if (n == 1) return 0 + "";
        boolean[] visited = new boolean[n];
        int[] count = new int[2];
        for (int i = 0; i < n; i++) {
            if (nums[i] != 0) {
                visited[nums[i] - 1] = true;
            }
        }
        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;
            count[(i + 1) % 2]++;
        }
        PriorityQueue<Integer>[] twoSides = new PriorityQueue[]{
                new PriorityQueue<>(),
                new PriorityQueue<>()
        };
        PriorityQueue<Integer>[] oneSide = new PriorityQueue[]{
                new PriorityQueue<>(),
                new PriorityQueue<>()
        };
        int diff = 0;
        int b = 0;
        while (b < n && nums[b] == 0) {
            b++;
        }
        if (b == n) return "1";
        if (b > 0) {
            oneSide[nums[b] % 2].add(b);
        }
        while (true) {
            int e = b + 1;
            while (e < n && nums[e] == 0) {
                e++;
            }
            if (e == n) break;
            if (nums[b] % 2 != nums[e] % 2) {
                diff++;
            } else if (e > b + 1) {
                twoSides[nums[e] % 2].add(e - b - 1);
            }
            b = e;
        }
        if (b + 1 < n) {
            oneSide[nums[b] % 2].add(n - b - 1);
        }
        for (int j = 0; j < 2; j++) {
            while (!twoSides[j].isEmpty() && twoSides[j].peek() <= count[j]) {
                count[j] -= twoSides[j].poll();
            }
            while (!oneSide[j].isEmpty() && oneSide[j].peek() <= count[j]) {
                count[j] -= oneSide[j].poll();
            }
            diff += twoSides[j].size() * 2 + oneSide[j].size();
        }
        return diff + "";
    }

    public static void main(String[] args) throws IOException {
        String result = doMain(new InputStreamReader(System.in));
        System.out.println(result);
    }

    static class MyReader {
        BufferedReader bf;

        StringTokenizer st;

        String last;

        MyReader(Reader reader) throws IOException {
            bf = new BufferedReader(reader);
            readNextLine();
        }

        String nextToken() throws IOException {
            while (!st.hasMoreTokens()) {
                readNextLine();
            }
            return st.nextToken();
        }

        void readNextLine() throws IOException {
            last = bf.readLine();
            if (last == null) last = "";
            st = new StringTokenizer(last);
        }

        String nextLine() throws IOException {
            String s = last;
            readNextLine();
            return s;
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        int[] readIntArray(int n) throws IOException {
            int[] answer = new int[n];
