public class A {

	static int n, a[], INF = (int) 1e9;

	static int[][][][] memo;

	static int dp(int even, int odd, int idx, int prev) {
		if (idx == n)
			return 0;
		if (memo[prev][even][odd][idx] != -1)
			return memo[prev][even][odd][idx];
		int ans = INF;
		if (a[idx] != 0) {
			ans = dp(even, odd, idx + 1, a[idx] % 2) + (a[idx] % 2 != prev && prev != 2 ? 1 : 0);
		} else {
			if (even > 0)
				ans = Math.min(ans, dp(even - 1, odd, idx + 1, 0) + (prev == 1 ? 1 : 0));
			if (odd > 0)
				ans = Math.min(ans, dp(even, odd - 1, idx + 1, 1) + (prev == 0 ? 1 : 0));
		}
		return memo[prev][even][odd][idx] = ans;
	}

