		for (int i = 0; i < n; i++)
			a[i] = sc.nextInt();
		memo = new int[3][n + 1][n + 1][n + 1];
		for (int[][][] x3 : memo)
			for (int[][] x2 : x3)
				for (int[] x : x2)
					Arrays.fill(x, -1);
		for (int i = 1; i <= n; i++) {
			boolean found = false;
			for (int x : a)
				if (x == i)
					found = true;
			if (!found) {
				if (i % 2 == 0)
