public class C1287 {

	static int[] arr;
	static int[][][][] dp;

	public static int dp(int idx, int e, int o, int prev) {
		if (idx == arr.length)
			return 0;
		if (dp[idx][e][o][prev] != -1)
			return dp[idx][e][o][prev];
		if (arr[idx] != 0) {
			return dp[idx][e][o][prev] = dp(idx + 1, e, o, arr[idx] % 2) + (prev == arr[idx] % 2 ? 0 : 1);
		}
		int ans = (int) 1e9;
		if (e != 0) {
			ans = Math.min(dp(idx + 1, e - 1, o, 0) + prev, ans);
		}
		if (o != 0) {
			ans = Math.min(dp(idx + 1, e, o - 1, 1) + 1 - prev, ans);
		}
		return dp[idx][e][o][prev] = ans;
	}

	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		PrintWriter pw = new PrintWriter(System.out);
		int n = sc.nextInt();
		HashSet<Integer> e = new HashSet<Integer>();
		HashSet<Integer> o = new HashSet<Integer>();
		for (int i = 1; i <= n; i++)
			if (i % 2 == 0)
				e.add(i);
			else
				o.add(i);
		arr = new int[n];
		for (int i = 0; i < arr.length; i++) {
			arr[i] = sc.nextInt();
			if (arr[i] != 0) {
				if (arr[i] % 2 == 0)
					e.remove(arr[i]);
				else
					o.remove(arr[i]);
			}
		}
		if (n == 1)
			pw.println(0);
		else {
			dp = new int[n + 1][e.size() + 1][o.size() + 1][2];
			for (int[][][] x : dp)
				for (int[][] y : x)
					for (int[] z : y)
						Arrays.fill(z, -1);
			if (arr[0] == 0) {
				int ans = (int) 1e9;
				if (o.size() != 0) {
					ans = Math.min(dp(1, e.size(), o.size() - 1, 1), ans);
				}
				if (e.size() != 0) {
					ans = Math.min(dp(1, e.size() - 1, o.size(), 0), ans);
				}
				pw.println(ans);
			} else {
				pw.println(dp(1, e.size(), o.size(), arr[0] % 2));
			}
		}
		pw.close();
	}

