public class C {
    static int EVENS = 0, ODDS = 0, n, arr[], dp[][][], inf = (int) 1e8;

    public static void main(String[] args) throws Exception {
        new Thread(null ,new Runnable(){
            public void run(){
                try{solveIt();} catch(Exception e){e.printStackTrace(); System.exit(1);}
            }
        },"Main",1<<28).start();
    }

    public static void solveIt() throws Exception {
        Scanner in = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        n = in.nextInt();
        arr = new int[n];
        int f[] = new int[n + 1];
        for (int i = 0; i < n; i++) {
            arr[i] = in.nextInt();
            f[arr[i]]++;
        }

        for (int i = 1; i <= n; i++) {
            if (f[i] == 0) {
                if (i % 2 == 0) EVENS++;
                else ODDS++;
            }
        }

        dp = new int[2][n + 1][n + 1];
        for (int a[][] : dp) for (int b[] : a) Arrays.fill(b, -1);

        int res = solve(0, 0, 0, 0);

        pw.println(res);

        pw.close();
    }

    static int solve(int lastParity, int pos, int oddCnt, int evenCnt) {
        if (pos >= n) {
            return 0;
        }
        if (dp[lastParity][pos][oddCnt] != -1) return dp[lastParity][pos][oddCnt];
        int res = inf;
        if (arr[pos] == 0) {
            if (oddCnt < ODDS) {
                int temp = 0;
                if (pos > 0 && lastParity == 0) temp = 1;
                res = min(res, temp + solve(1, pos + 1, oddCnt + 1, evenCnt));
            }
            if (evenCnt < EVENS) {
                int temp = 0;
                if (pos > 0 && lastParity == 1) temp = 1;
                res = min(res, temp + solve(0, pos + 1, oddCnt, evenCnt + 1));
            }
        } else {
            int currParity = arr[pos] & 1;
            int temp = 0;
            if (pos > 0 && lastParity != currParity) temp = 1;
            res = min(res, temp + solve(currParity, pos + 1, oddCnt, evenCnt));
        }

        return dp[lastParity][pos][oddCnt] = res;
    }

    static void debug(Object... obj) {
        System.err.println(Arrays.deepToString(obj));
    }
}

