        private int odd;
        private int even;
        int[] a;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            this.in = in;
            this.out = out;
            n = in.nextInt();
            a = new int[n + 2];
            for (int i = 1; i <= n; i++) a[i] = in.nextInt();
            odd = (n + 1) / 2;
            even = n - odd;
            for (int i = 1; i <= n; i++) {
                if (a[i] != 0) {
                    if (a[i] % 2 == 1) odd--;
                    else even--;
                }
            }
            int ans = 1000;
            a[0] = 1;
            a[n + 1] = 1;
            ans = MaxMin.Min(ans, sol());

            a[0] = 2;
            a[n + 1] = 1;
            ans = MaxMin.Min(ans, sol());

            a[0] = 1;
            a[n + 1] = 2;
            ans = MaxMin.Min(ans, sol());

            a[0] = 2;
            a[n + 1] = 2;
            ans = MaxMin.Min(ans, sol());

            out.println(ans);
        }

        int sol() {
            int res = 0;
            int curO = odd;
            int curE = even;
            ArrayList<PairII> l2 = new ArrayList<>();
            int l1 = 0;

            int i = 0;
            for (int j = 1; j <= n + 1; j++) {
                while (j <= n + 1) {
                    if (a[j] != 0) break;
                    j++;
                }
                if ((a[i] + a[j]) % 2 != 0) {
                    l1++;
                } else {
                    l2.add(new PairII(j - i - 1, a[i] % 2));
                }
                i = j;
            }

            Collections.sort(l2);



            for (PairII p : l2) {
                if (p.second % 2 == 1) {
                    if (p.first <= curO) {
                        curO -= p.first;
                    } else res += 2;
                } else {
                    if (p.first <= curE) {
                        curE -= p.first;
                    } else res += 2;
                }
            }




