			if(num1 > 0) odd = (1 == prev ? 0 : 1) + go(idx + 1, num0, num1 - 1, 1);

			out = Math.min(eve, odd);
		}

		if(prev == 2) --out;
		return dp[idx][num0][num1][prev] = out;
	}
