                out.printLine("No");
                out.flush();
                continue;
            }
            vis = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if ( maze[i][j] == 'B' ) {
                        blockDfs(i, j);
                    }
                }
            }
            boolean posssible = true;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if ( maze[i][j] == 'G' ) {
                        vis = new int[n][m];
                        if ( !goodCan(i, j) ) {
                            posssible = false;
                            break;
                        }
                    }
                }
                if ( !posssible )
                    break;
            }
            out.printLine(posssible ? "Yes" : "No");
            out.flush();
        }
    }
    private boolean goodCan(int i, int j) {
        if ( i < 0 || j < 0 || i > n - 1 || j > m - 1 )
            return false;
        if ( i == n - 1 && j == m - 1 && (maze[i][j] == 'G' || maze[i][j] == '.') ) {
            return true;
        }
        if ( vis[i][j] == 1 )
            return false;
        if ( maze[i][j] == '#' ) {
            return false;
        } else {
            vis[i][j] = 1;
            boolean possible = false;
            possible = goodCan(i + 1, j);
            if ( !possible )
                possible = goodCan(i, j + 1);
            if ( !possible )
                possible |= goodCan(i - 1, j);
            if ( !possible )
                possible |= goodCan(i, j - 1);
            return possible;
        }
    }

    private void blockDfs(int i, int j) {
        if ( i < 0 || j < 0 || i > n - 1 || j > m - 1 )
            return;
        if ( vis[i][j] == 1 ) {
            return;
        }
        if ( maze[i][j] == '#' )
            return;
        if ( maze[i][j] == '.' ) {
            maze[i][j] = '#';
        } else {
            vis[i][j] = 1;
            blockDfs(i - 1, j);
            blockDfs(i, j - 1);
            blockDfs(i + 1, j);
            blockDfs(i, j + 1);
        }
    }

