    static void solve(char[][] ch, int n, int m, int i, int j)
    {
    visited[i][j] = true;
    if(i - 1 >= 0 && ch[i-1][j] != '#' && !visited[i-1][j])
        solve(ch,n,m,i-1,j);
    if(i + 1 < n && ch[i+1][j] != '#' && !visited[i+1][j])
        solve(ch,n,m,i+1,j);
    if(j - 1 >= 0 && ch[i][j-1] != '#' && !visited[i][j-1])
        solve(ch,n,m,i,j-1);
    if(j + 1 < m && ch[i][j+1] != '#' && !visited[i][j+1])
        solve(ch,n,m,i,j+1); 
    }
