                {
                if(ch[i][j] == 'B')
                    {
                    if(i - 1 >= 0 && ch[i-1][j] == '.')
                        ch[i-1][j] = '#';
                    if(i + 1 < n && ch[i+1][j] == '.')
                        ch[i+1][j] = '#';
