      static class DSolveTheMaze {
            ArrayList<Integer>[] list;

            public void solve(int testNumber, InputReader in, OutputWriter out) {
                  int t = in.nextInt();
                  abc:
                  while (t-- > 0) {
                        int n = in.nextInt();
                        int m = in.nextInt();
                        char[][] mat = new char[n][m];
                        for (int i = 0; i < n; i++) {
                              String str = in.next();
                              mat[i] = str.toCharArray();
                        }

                        for (int j = m - 1; j > 0; j--) {
                              for (int i = 0; i < n; i++) {
                                    if (mat[i][j] == 'B') {
                                          if (mat[i][j - 1] == '.') {
                                                mat[i][j - 1] = '#';
                                          }
                                    }
                              }
                        }

                        for (int j = 0; j < m - 1; j++) {
                              for (int i = 0; i < n; i++) {
                                    if (mat[i][j] == 'B') {
                                          if (mat[i][j + 1] == '.') {
                                                mat[i][j + 1] = '#';
                                          }
                                    }
                              }
                        }

                        for (int i = 0; i < n - 1; i++) {
                              for (int j = 0; j < m; j++) {
                                    if (mat[i][j] == 'B') {
                                          if (mat[i + 1][j] == '.') {
                                                mat[i + 1][j] = '#';
                                          }
                                    }
                              }
                        }

                        for (int i = n - 1; i > 0; i--) {
                              for (int j = 0; j < m; j++) {
                                    if (mat[i][j] == 'B') {
                                          if (mat[i - 1][j] == '.') {
                                                mat[i - 1][j] = '#';
                                          }
                                    }
                              }
                        }


                        list = new ArrayList[n * m];
                        for (int i = 0; i < n * m; i++) {
                              list[i] = new ArrayList();
                        }

                        int[][] arr = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
                        for (int i = 0; i < n; i++) {
                              for (int j = 0; j < m; j++) {
                                    if (mat[i][j] != '#')
                                          for (int k = 0; k < 4; k++) {
                                                int x = i + arr[k][0];
                                                int y = j + arr[k][1];
                                                if (x >= 0 && y >= 0 && x < n && y < m && mat[x][y] != '#') {
                                                      list[i * m + j].add(x * m + y);
                                                      list[x * m + y].add(i * m + j);
                                                }
                                          }
                              }
                        }

                        int dis[] = new int[n * m];
                        Arrays.fill(dis, -1);
                        dis[n * m - 1] = 0;
                        ArrayDeque<Integer> dq = new ArrayDeque();
                        dq.add(n * m - 1);

                        while (!dq.isEmpty()) {
                              int u = dq.poll();
                              for (int v : list[u]) {
                                    if (dis[v] == -1) {
                                          dis[v] = dis[u] + 1;
                                          dq.addLast(v);
                                    }
                              }
                        }

                        for (int i = 0; i < n * m; i++) {
