    char[][] mat;
    public void recur(int r, int c) {
        if(r < 0 || c < 0 || r >= mat.length || c >= mat[0].length || vis[r][c] || mat[r][c] == '#') return;
        vis[r][c] = true;
        recur(r+1, c);
        recur(r, c+1);
        recur(r-1, c);
        recur(r, c-1);
    }

