                        bads.add(new int[] {i,j});
                    }
                }
            }



            if(array[n-1][m-1]=='B') {
                System.out.println("No");
                continue;
            }


            boolean end = false;
            for(int[] bad : bads) {
                int i = bad[0], j = bad[1];
                if(i > 0) {
                    if(array[i-1][j] == 'G') {
                        end = true;
                        break;
                    }
                    if(array[i-1][j] != 'B') {
                        array[i-1][j] = '#';
                    }
                }
                if(j > 0) {
                    if(array[i][j-1] == 'G') {
                        end = true;
                        break;
                    }
                    if(array[i][j-1] != 'B') {
                        array[i][j-1] = '#';
                    }
                }

                if(i < n-1) {
                    if(array[i+1][j] == 'G') {
                        end = true;
                        break;
                    }
                    if(array[i+1][j] != 'B') {
                        array[i+1][j] = '#';
                    }
                }

                if(j < m-1) {
                    if(array[i][j+1] == 'G') {
                        end = true;
                        break;
                    }
                    if(array[i][j+1] != 'B') {
                        array[i][j+1] = '#';
                    }
                }
            }


            if(end) {
                System.out.println("No");
                continue;
            }

            rek(n-1,m-1);

            if(num == 0) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }

        }

    }

    private static void rek(int i, int j) {
        if(num == 0 || i < 0 || j < 0 || array.length <= i || array[0].length <= j  || array[i][j] == '#') {
            return;
        }

        if(array[i][j] == 'G') {
            num--;
        }

        array[i][j] = '#';
        rek(i-1,j);
        rek(i,j-1);
        rek(i+1,j);
        rek(i,j+1);
    }
}

