		bpffvis[i][j] = true;
		for (int d = 0; d < 4; d++) {
			int ni = i+dx[d];
			int nj = j+dy[d];
			if (ni >= 0 && ni < maze.length && nj >= 0 && nj < maze[0].length && maze[ni][nj] != '#') {
				if (maze[ni][nj] == '.') {
					maze[ni][nj] = '#';
				} else if (!bpffvis[ni][nj]) {
					bpff(ni, nj);
				}
			}
		}
	}

	static int[] dx = {-1, 0, 1, 0};
	static int[] dy = {0, 1, 0, -1};
	static void ff(int i, int j) {
		if (maze[i][j] == '#') return;
		ffd[i][j] = true;
		for (int d = 0; d < 4; d++) {
			int ni = i+dx[d];
			int nj = j+dy[d];
			if (ni >= 0 && ni < maze.length && nj >= 0 && nj < maze[0].length && !ffd[ni][nj] && maze[ni][nj] != '#') {
				ff(ni, nj);
			}
		}
	}

	static boolean checkgp() {
		for (int i = 0; i < maze.length; i++) {
			for (int j = 0; j < maze[i].length; j++) {
				if (maze[i][j] == 'G' && !ffd[i][j]) return false;
			}
		}
		return true;
	}
