    static class DSolveTheMaze {
        int[] dx = {-1, 0, 1, 0};
        int[] dy = {0, 1, 0, -1};
        char[][] mat;
        int n;
        int m;
        boolean[][] vis;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int ntc = in.nextInt();
            while ((ntc--) > 0) {
                n = in.nextInt();
                m = in.nextInt();
                int gc = 0;
                int bc = 0;
                mat = new char[n][m];
                vis = new boolean[n][m];
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        char ch = in.nextCharacter();
                        if (ch == 'G') {
                            gc++;
                        }
                        if (ch == 'B') {
                            bc++;
                        }
                        mat[i][j] = ch;
                    }
                }
                if (gc == 0) {
                    out.println("Yes");
                    continue;
                }
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        if (mat[i][j] == 'B') {
                            for (int k = 0; k < 4; k++) {
                                int newx = dx[k] + i;
                                int newy = dy[k] + j;
                                if (isvalid(newx, newy) && mat[newx][newy] == '.') {
                                    mat[newx][newy] = '#';
                                }
                            }
                        }
                    }
                }
                if (mat[n - 1][m - 1] == '.') {
                    mat[n - 1][m - 1] = '#';
                }
                bfs(n - 1, m - 1);
                boolean ok = true;

                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        if (mat[i][j] == 'G' && !vis[i][j]) {
                            ok = false;
                            break;
                        } else if (mat[i][j] == 'B' && vis[i][j]) {
                            ok = false;
                            break;
                        }
                    }
                }
                if (ok) {
                    out.println("Yes");
                } else {
                    out.println("No");
                }

            }
        }

        void bfs(int x, int y) {
            ArrayDeque<Integer> queue = new ArrayDeque<>();
            queue.addLast(x);
            queue.addLast(y);
            vis[x][y] = true;
            while (!queue.isEmpty()) {
                int u = queue.removeFirst();
                int v = queue.removeFirst();
                for (int i = 0; i < 4; i++) {
                    int newx = u + dx[i];
                    int newy = v + dy[i];
                    if (isvalid(newx, newy) && mat[newx][newy] != '#' && !vis[newx][newy]) {



                        vis[newx][newy] = true;
                        queue.addLast(newx);
                        queue.addLast(newy);
                    }
                }
            }

        }

        boolean isvalid(int x, int y) {
            if (x < 0 || x >= n) {
                return false;
            }
            if (y < 0 || y >= m) {
                return false;
            }
            return true;
        }

    }

