			}
			for (int r = 0; r < rows; r++) {
				for (int c = 0; c < cols; c++){
					if (grid[r][c]=='B') { 

						if (r>0) {
							if (grid[r-1][c]=='G') bad=true;
							else if (grid[r-1][c]!='B') grid[r-1][c]='#';
						}
						if (r<rows-1) {
							if (grid[r+1][c]=='G') bad=true;
							else if (grid[r+1][c]!='B') grid[r+1][c]='#';
						}
						if (c>0) {
							if (grid[r][c-1]=='G') bad=true;
							else if (grid[r][c-1]!='B') grid[r][c-1]='#';
						}
						if (c<cols-1) {
							if (grid[r][c+1]=='G') bad=true;
							else if (grid[r][c+1]!='B') grid[r][c+1]='#';
						}
					}
					if (bad) break;
				}
				if (bad) break;
			}


			if (!bad) { 
				boolean[][] outvis = new boolean[rows][cols];
				for (int r = 0; r < rows; r++) {
					for (int c = 0; c < cols; c++) {
						if (grid[r][c]=='G'&&!outvis[r][c]) {
							outvis[r][c]=true;
							int[] start = {r,c};
							int[] end = {rows-1,cols-1};
							if (!BFS(start,end,grid,rows,cols,outvis)) {
								bad=true;
								break;
							}
						}
					}
					if (bad) break;
				}
			}
			w.println(bad?"No":"Yes");
			w.flush();
		}
