	public static boolean BFS(int[] start, int[] end, char[][] grid,int rows, int cols,
	boolean[][] outvis) {
		Queue<int[]> cur = new LinkedList<int[]>();
		boolean[][] vis = new boolean[rows][cols];
		vis[start[0]][start[1]]=true;
		cur.add(start);
		while (!cur.isEmpty()) {
			for (int i = 0; i < cur.size(); i++) {
				int[] pair = cur.poll(); 
				int r = pair[0];
				int c = pair[1];
				int[] U = {r-1,c};
				int[] D = {r+1,c};
				int[] L = {r,c-1};
				int[] R = {r,c+1}; 
				if (r>0&&!vis[r-1][c]&&grid[r-1][c]!='#') {
					cur.add(U);
					vis[r-1][c]=true;
					if (grid[r-1][c]=='G') outvis[r-1][c]=true;
					if (r-1==end[0]&&c==end[1]) return true;
				} 
				if (r<rows-1&&!vis[r+1][c]&&grid[r+1][c]!='#') {
					cur.add(D);
					vis[r+1][c]=true;
					if (grid[r+1][c]=='G') outvis[r+1][c]=true;
					if (r+1==end[0]&&c==end[1]) return true;
				} 
				if (c>0&&!vis[r][c-1]&&grid[r][c-1]!='#') {
					cur.add(L);
					vis[r][c-1]=true;
					if (grid[r][c-1]=='G') outvis[r][c-1]=true;
					if (r==end[0]&&c-1==end[1]) return true;
				} 
				if (c<cols-1&&!vis[r][c+1]&&grid[r][c+1]!='#') {
					cur.add(R);
					vis[r][c+1]=true;
					if (grid[r][c+1]=='G') outvis[r][c+1]=true;
					if (r==end[0]&&c+1==end[1]) return true;
				} 


			}
		}
		return false;
	}
	static class FastScanner {
		BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st=new StringTokenizer("");
		String next() {
			while (!st.hasMoreTokens())
				try {
					st=new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			return st.nextToken();
		}

