import java.util.*;
import java.io.*;

public class SolveTheMaze {

    static class Kattio extends PrintWriter {
        private BufferedReader r;
        private StringTokenizer st;


        public Kattio() { this(System.in,System.out); }
        public Kattio(InputStream i, OutputStream o) {
            super(o);
            r = new BufferedReader(new InputStreamReader(i));
        }

        public Kattio(String problemName) throws IOException {
            super(new FileWriter(problemName+".out"));
            r = new BufferedReader(new FileReader(problemName+".in"));
        }


        public String next() {
            try {
                while (st == null || !st.hasMoreTokens())
                    st = new StringTokenizer(r.readLine());
                return st.nextToken();
            } catch (Exception e) {}
            return null;
        }

        public int nextInt() { return Integer.parseInt(next()); }
        public double nextDouble() { return Double.parseDouble(next()); }
        public long nextLong() { return Long.parseLong(next()); }
    }

    static int[] rowMovement = {0, 1, 0, -1};  
    static int[] columnMovement = {1, 0, -1, 0};
    static char[][] grid;
    static boolean[][] visited;
    static int numRows;
    static int numColumns;

    static void floodfill (int row, int column) {
        visited[row][column] = true;


        for (int x = 0; x < 4; x++) {  
            int newRow = row + rowMovement[x];
            int newColumn = column + columnMovement[x];
            if (newRow >= 0 && newRow < numRows && newColumn >= 0 && newColumn < numColumns) {  
                if (! visited[newRow][newColumn] && grid[newRow][newColumn] != '#') {  
                    floodfill(newRow, newColumn);
                }
            }
        }
    }

    static String solve () {
        int ok = 1;

        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numColumns; j++) {
                if (grid[i][j] == 'B') {
                    for (int x = 0; x < 4; x++) {  
                        int newRow = i + rowMovement[x];
                        int newColumn = j + columnMovement[x];

                        if (newRow >= 0 && newRow < numRows && newColumn >= 0 && newColumn < numColumns) {
                            if (grid[newRow][newColumn] == 'G') {  
                                ok = 0;
                            }
                            if (grid[newRow][newColumn] == '.') {  
                                grid[newRow][newColumn] = '#';
                            }
                        }
                    }
                }
            }
        }



        if (ok == 0) {
            return "No";
        }
        ok = 1;

        if (grid[numRows - 1][numColumns - 1] != '#') {
            floodfill(numRows - 1, numColumns - 1);  
        }



        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numColumns; j++) {

                if (grid[i][j] == 'G' && !visited[i][j]) {
                    ok = 0;
                    break;
                }
            }
        }



        if (ok == 0) {
            return "No";
        }
        return "Yes";
    }

    public static void main (String[] args) {
        Kattio io = new Kattio();
        int numTestCases = io.nextInt();
        for (int x = 0; x < numTestCases; x++) {
            numRows = io.nextInt();
            numColumns = io.nextInt();
            grid = new char[numRows][numColumns];
            visited = new boolean[numRows][numColumns];

            for (int row = 0; row < numRows; row++) {  
                String line = io.next();
                for (int column = 0; column < numColumns; column++) {
                    grid[row][column] = line.charAt(column);
                }
            }
            io.println(solve());
        }
        io.close();
    }

}

import java.io.*;
import java.math.*;
import java.util.*;

public class Solve {
    FastScanner in;
    PrintWriter out;

    static final int[] dy = {0, 0, -1, 1};
    static final int[] dx = {1, -1, 0, 0};

    static boolean inBounds(int row, int col, int rows, int cols) {
        return (0 <= row &&
                0 <= col &&
                row < rows &&
                col < cols);
    }

    static class Point {
        int row, col;
        Point(int r, int c) {
            row = r;
            col = c;
        }
    }

    void solve() {
        int T = in.nextInt();
        while (0 < T--) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] maze = new char[rows][cols];
            for (int row = 0; row < rows; row++) {
                maze[row] = in.next().toCharArray();
            }

            int totalGood = 0;
            for (int row = 0; row < rows; row++) {
                for (int col = 0; col < cols; col++) {
                    if (maze[row][col] == 'B') {
                        for (int d = 0; d < 4; d++) {
                            int drow = row + dy[d];
                            int dcol = col + dx[d];
                            if (inBounds(drow, dcol, rows, cols) &&
                                maze[drow][dcol] == '.') {

                                maze[drow][dcol] = '#';
                            }
                        }

                    } else if (maze[row][col] == 'G') {
                        totalGood++;
                    }
                }
            }










            LinkedList<Point> bfs = new LinkedList<>();
            boolean[][] seen = new boolean[rows][cols];

            if (maze[rows-1][cols-1] == '.') {
                bfs.add(new Point(rows-1, cols-1));
                seen[rows-1][cols-1] = true;
            }

            int foundGood = 0;
            int foundBad = 0;
            while ( ! bfs.isEmpty()) {
                Point currPoint = bfs.poll();
                char curr = maze[currPoint.row][currPoint.col];

                if (curr == 'G') {
                    foundGood++;
                } else if (curr == 'B') {
                    foundBad++;
                }

                for (int d = 0; d < 4; d++) {
                    int drow = currPoint.row + dy[d];
                    int dcol = currPoint.col + dx[d];
                    if (inBounds(drow, dcol, rows, cols) &&
                        ! seen[drow][dcol] &&
                        maze[drow][dcol] != '#') {

                        bfs.add(new Point(drow, dcol));
                        seen[drow][dcol] = true;
                    }
                }
            }


            out.println((foundGood == totalGood && foundBad == 0) ? "Yes" : "No");
        }
    }

    void run() {
        try {
            in = new FastScanner(new File("Solve.in"));
            out = new PrintWriter(new File("Solve.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    void runIO() {

        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return false;
                st = new StringTokenizer(s);
            }
            return true;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        BigInteger nextBigInteger() {
            return new BigInteger(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) {
        new Solve().runIO();
    }
}

