            char[][] maze = new char[n][m]; 
            for (int i = 0; i < n; i++) {
                maze[i] = input.next().toCharArray();
            }
            boolean escape = true;

            outerloop:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (maze[i][j] == 'B') {
                        for (int k = 0; k < 4; k++) {
                            int x = i + xx[k];
                            int y = j + yy[k];
                            if (valid(x, y)) {
                                if (maze[x][y] == 'G') {
                                    escape = false;
                                    break outerloop;
                                } else if (maze[x][y] == '.') {
                                    maze[x][y] = '#';
                                }
                            }
                        }
                    }
                }
            }
            boolean[][] reach = new boolean[n][m];
            if (maze[n - 1][m - 1] == '.') {
                reach[n - 1][m - 1] = true;
                Queue<Integer> queue = new LinkedList<>();
                queue.add(n * m - 1);
                while (!queue.isEmpty()) {
                    int current = queue.poll();
                    int currentX = current / m;
                    int currentY = current - currentX * m;
                    for (int k = 0; k < 4; k++) {
                        int x = currentX + xx[k];
                        int y = currentY + yy[k];
                        if (valid(x, y) && (maze[x][y] == '.' || maze[x][y] == 'G') && !reach[x][y]) {
                            reach[x][y] = true;
                            queue.add(x * m + y);
                        }
                    }
                }
            } 

            outerloop:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (maze[i][j] == 'G' && !reach[i][j]) {
                        escape = false;
                        break outerloop;
                    }
                }
            }

            output.println(escape ? "Yes" : "No");
        }

        output.close();
    }

    private static boolean valid(int x, int y) {
        return 0 <= x && x < n && 0 <= y && y < m;
