                    if(ch.charAt(j)=='B')arr[i][j]=2;
                    if(ch.charAt(j)=='G')arr[i][j]=3;
                }
            }
            int flag=0;

            for(int i=0;i<n;i++) {
                for (int j = 0; j < m; j++) {
                    if(arr[i][j]==3){
                        if(g==0){x=i;y=j;}
