                    }
                    if(arr[i][j]==2){
                        boolean val = true;
                        val = val && modf(i+1,j);
                        val = val && modf(i-1,j);
                        val = val && modf(i,j+1);
                        val = val && modf(i,j-1);
                        if(!val) {
                            flag=1;
                            break;
                        }
                    }
                }
            }
