    private static boolean modf(int x, int y) {
        if(x>=0 && y>=0 && x<arr.length && y<arr[0].length) {
            if(arr[x][y]==0) arr[x][y] = 1;
            if(arr[x][y]==3) return false;
        }
        return true;
    }


    private static int cnt;
    private static boolean hit;
    private static int[][] visited;

    private static void chekr(int n, int m, int x, int y) {


        int cur = arr[x][y];
        visited[x][y] = 1;

        if(cur==3) cnt+=1;
        if(x==n-1 && y==m-1){
            hit =  true;
        }

        if(checkG(x,y-1)) chekr(n,m,x,y-1);
        if(checkG(x,y+1)) chekr(n,m,x,y+1);
        if(checkG(x-1,y)) chekr(n,m,x-1,y);
        if(checkG(x+1,y)) chekr(n,m,x+1,y);

        return;
    }

    private static boolean checkG(int x, int i) {
        int n = arr.length;
        int m = arr[0].length;
        if(x>=0 && x<n && i>=0 && i<m && visited[x][i]==0 && arr[x][i]!=1 && arr[x][i]!=2) return true;
        return false;
    }
