            }


            for(int i = 0; i < n; i++){
                for(int j = 0; j < m; j++){
                    if(grid[i][j] == 'G' && !done[i][j]){
                        boolean escaped = bfs(grid, i, j, n, m);
                        if(!escaped){
                            println("No");
                            continue outer;
                        }
                    }
                }
            }
            println("Yes");
        }

        in.close();
        out.close();
    }

    static int dx[] = {1, 0, -1, 0};
    static int dy[] = {0, -1, 0, 1};

    static boolean blockBadPersons(char grid[][], int n, int m){
        for(int i = 0; i < n; i++){
            for(int j = 0; j < m; j++){
                if(grid[i][j] == 'B'){
                    for(int k = 0; k < 4; k++){
                        int x = i + dx[k];
                        int y = j + dy[k];
                        if(x >= 0 && x < n && y >= 0 && y < m){
                            if(grid[x][y] == 'G'){
                                return false;
                            }
                            else if(grid[x][y] == '.'){
                                grid[x][y] = '#';
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    static boolean bfs(char grid[][], int i, int j, int n, int m){
        Deque<int[]> q = new LinkedList<>();
        boolean visited[][] = new boolean[n][m];
        visited[i][j] = true;
        q.add(new int[]{i, j});
        while(!q.isEmpty()){
            int u[] = q.poll();
            if(u[0] == n - 1 && u[1] == m - 1){
                return true;
            }
            for(int k = 0; k < 4; k++){
                int x = u[0] + dx[k];
                int y = u[1] + dy[k];
                if(x >= 0 && x < n && y >= 0 && y < m && !visited[x][y]){
                    if(grid[x][y] == '#'){
                        continue;
                    }
                    else if(grid[x][y] == 'G'){
                        done[x][y] = true;
                    }
                    q.add(new int[]{x, y});
                    visited[x][y] = true;
                }
            }
        }
        return false;
    }

