public class NeighborGrid {
    public static void main(String agrs[]) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int t = in.nextInt();
        for(int i = 0; i < t; i++)
        {
            int n = in.nextInt();
            int m = in.nextInt();
            int[][] grid = new int[n][m];
            for(int a = 0; a < n; a++)
            {
                for(int b = 0; b < m; b++)
                {
                    grid[a][b] = in.nextInt();
                }
            }
            boolean shouldbreak = false;
            for(int a = 0; a < n; a++)
            {
                if(shouldbreak)
                    break;
                for(int b = 0; b < m; b++)
                {
                    if(!checkGrid(grid, n, m, a, b))
                    {
                        shouldbreak = true;
                        break;
                    }
                }
            }
            if(shouldbreak)
            {
                out.println("NO");
            }
            else
            {
                out.println("YES");
                for(int a = 0; a < n; a++)
                {
                    for(int b = 0; b < m; b++)
                    {
                        if(b != m - 1)
                        {
                            out.print(grid[a][b] + " ");
                        }
                        else
                        {
                            out.println(grid[a][b]);
                        }
                    }
                }
            }
        }
        out.close();
    }
    public static boolean checkGrid(int[][] grid, int n, int m, int a, int b)
    {
        int count = 0;
        if(a + 1 < n)
        {
            count++;
        }
        if(b + 1 < m)
        {
            count++;
        }
        if(a - 1 >= 0)
        {
            count++;
        }
        if(b - 1 >= 0)
        {
            count++;
        }
        if(count >= grid[a][b])
        {
            grid[a][b] = count;
            return true;
        }
        else
        {
            return false;
        }
    }
}

