public class NeighbourGrid {

    public static void main(String[] args) {

        try (Scanner scanner = new Scanner(System.in)) {
            int numberOfTestcases = Integer.valueOf(scanner.nextLine());
            while (numberOfTestcases > 0) {

                String defs = scanner.nextLine();

                Integer matrixDefLines = Integer.valueOf(defs.split(" ")[0]);
                Integer matrixDefColumns = Integer.valueOf(defs.split(" ")[1]);

                int[][] arr = new int[matrixDefLines][matrixDefColumns];

                int count=0;

                while (matrixDefLines > count) {

                    String arrayOfEntries = scanner.nextLine();

                    int innerCounter=0;

                    for (String s : arrayOfEntries.split(" ")) {
                        arr[count][innerCounter] = Integer.valueOf(s);
                        innerCounter++;
                    }

                    count++;
                }
                matrixGood(arr);
                numberOfTestcases--;
            }

        }
    }

    private static void matrixGood(int[][] matrix) {
        if (isMatrixBad(matrix)) {
            System.out.println("NO");
        } else {
            for (int i = 0; i < matrix.length; i++) {
                for (int j = 0; j < matrix[i].length; j++) {
                    if ((i == 0 && j == 0) || (i == 0 && j == matrix[i].length - 1 || (j == 0 && i == matrix.length -1) || (i == matrix.length -1 && j == matrix[i].length -1))) {
                        matrix[i][j] = 2;
                    } else if (j == 0 || i == 0 || i == matrix.length -1 || j == matrix[i].length -1 ) {
                        matrix[i][j] = 3;
                    } else {
                        matrix[i][j] = 4;
                    }
                }
            }
            System.out.println("YES");
            printMatrix(matrix);
        }


    }

    private static boolean isMatrixBad(int[][] matrix) {

        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                if (matrix[0][0] > 2 || matrix[0][matrix[0].length - 1] > 2 || matrix[matrix.length - 1][0] > 2 || matrix[matrix.length - 1][matrix[matrix.length - 1].length - 1] > 2) {
                    return true;
                } else if (j == 0 || i == 0 || i == matrix.length -1 || j == matrix[i].length -1) {
                    if (matrix[i][j] > 3) {
                        return true;
                    }
                } else if (matrix[i][j] > 4) {
                    return true;
                }
            }
        }
        return false;

    }

     private static void printMatrix(int[][] matrix) {

        for( int[] i : matrix) {
            for ( int j : i) {
                System.out.print(j + " ");
            }
            System.out.println();
        }
    }
