public class B {
    private static int[][] directions = new int[][]{{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    private static boolean isValid(int i, int j, int[] direction, int[][] grid) {
        return i + direction[0] >= 0 && j + direction[1] >= 0 && i + direction[0] < grid.length && j + direction[1] < grid[0].length;
    }
    public static void main(String[] args) throws IOException {
        Reader sc = new Reader();
        int t = sc.nextInt();
        StringBuilder sb = new StringBuilder();
        while (t-- > 0){
            int n = sc.nextInt();
            int m = sc.nextInt();
            int[][] grid = new int[n][m];
            for(int i = 0; i < n; i++){
                for(int j = 0; j < m; j++){
                    grid[i][j] = sc.nextInt();
                }
            }
            List<Pair> notGood = new ArrayList<>();
            boolean no = false;
            for(int i = 0; i < n; i++){
                for(int j = 0; j < m; j++){
                    if(grid[i][j] == 0) continue;
                    int count = 0;
                    int max = 0;
                    for(int[] direction : directions){
                        if(isValid(i, j, direction, grid)){
                            max++;
                            if(grid[i + direction[0]][j + direction[1]] > 0){
                                count++;
                            }
                        }
                    }
                    if(grid[i][j] > max){
                        no = true;
                        break;
                    }
                    if(grid[i][j] == count) continue;
                    notGood.add(new Pair(i, j, count));
                }
                if(no) break;
            }
            if(no){
                sb.append("NO").append("\n");
                continue;
            }

            for(Pair pair : notGood){
                if(grid[pair.first][pair.second] < pair.fill){
                    grid[pair.first][pair.second] = pair.fill;
                    continue;
                }
                int cc = 0;
                for(int[] direction : directions) {
                    if (isValid(pair.first, pair.second, direction, grid)) {
                        if (grid[pair.first + direction[0]][pair.second + direction[1]] > 0) {
                            cc++;
                        }
                    }
                }
                int remaining = grid[pair.first][pair.second] - cc;
                if(remaining == 0) continue;
                for(int[] direction : directions){
                    if(isValid(pair.first, pair.second, direction, grid)){
                        if(grid[pair.first + direction[0]][pair.second + direction[1]] == 0){

                            int x = pair.first + direction[0];
                            int y = pair.second + direction[1];
                            int count = 0;
                            for(int[] dir : directions){
                                if(isValid(x, y, dir, grid)){
                                    if(grid[x + dir[0]][y + dir[1]] > 0){
                                        count++;
                                    }
                                }
                            }
                            grid[x][y] = count;
                            remaining--;
                            if(remaining == 0) break;
                        }
                    }
                }
            }
            for(int i = 0; i < n; i++){
                for(int j = 0; j < m; j++){
                    if(grid[i][j] == 0) continue;
                    int count = 0;
                    for(int[] direction : directions){
                        if(isValid(i, j, direction, grid)){
                            if(grid[i + direction[0]][j + direction[1]] > 0){
                                count++;
                            }
                        }
                    }
                    grid[i][j] = count;
                }
            }
            sb.append("YES").append("\n");
            for(int i = 0; i < n; i++){
                for(int j = 0; j < m; j++){
                    sb.append(grid[i][j]).append(" ");
                }
                sb.append("\n");
            }
        }
        System.out.println(sb.toString());
    }

    static class Pair{
