public class Main {

    public static int t;

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        t = scan.nextInt();
        for (int i = 0; i < t; i++) {
            solve(scan);
        }
    }

    private static void solve(Scanner scan) {
        int n = scan.nextInt(), m = scan.nextInt();
        int[][] arr = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                arr[i][j] = scan.nextInt();
            }
        }

        boolean hasSolution = true, isCorrected = true;

        while (isCorrected) {
            isCorrected = false;
            for (int i = 0; i < arr.length; i++) {
                for (int j = 0; j < arr[i].length; j++) {
                    int number = arr[i][j];
                    if (number + (i == 0 || i == n - 1 ? 1 : 0) + (j == 0 || j == m - 1 ? 1 : 0) > 4)
                        hasSolution = false;
                    if (!hasSolution) break;

                    int i1 = arr[i][j]
                            - (i > 0 && arr[i - 1][j] > 0 ? 1 : 0) - (i < n - 1 && arr[i + 1][j] > 0 ? 1 : 0)
                            - (j > 0 && arr[i][j - 1] > 0 ? 1 : 0) - (j < m - 1 && arr[i][j + 1] > 0 ? 1 : 0);
                    if (i1 < 0) {
                        if (i1 != -1 || arr[i][j] != 0) {
                            arr[i][j] -= i1;
                            isCorrected = true;
                        }
                    } else if (i1 != 0) {
                        if (i > 0 && arr[i - 1][j] == 0) {
                            i1--;
                            arr[i - 1][j]++;
                            isCorrected = true;
                        }
                        if (i1 > 0 && i < n - 1 && arr[i + 1][j] == 0) {
                            i1--;
                            arr[i + 1][j]++;
                            isCorrected = true;
                        }
                        if (i1 > 0 && j > 0 && arr[i][j - 1] == 0) {
                            i1--;
                            arr[i][j - 1]++;
                            isCorrected = true;

                        }
                        if (i1 > 0 && j < m - 1 && arr[i][j + 1] == 0) {
                            arr[i][j + 1]++;
                            isCorrected = true;
                        }
                    }

                }
                if (!hasSolution) break;
            }
        }

        if (hasSolution) {
            System.out.println("YES");
            for (int i = 0; i < arr.length; i++) {
                for (int j = 0; j < arr[i].length; j++) {
                    if (j != 0) System.out.print(' ');
                    System.out.print(arr[i][j]);
                }
                System.out.println();
            }
        } else System.out.println("NO");
    }
}

