        int low = 0;
        int high = nums2.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums2[mid] == i)
                return mid;
            else if (nums2[mid] < i)
                low = mid + 1;
            else
                high = mid - 1;
        }
        return -1;
        }   
