public class BB {
    public static void main(String[] args) {
        try {
            FastReader fr = new FastReader(System.in);
            int t = fr.nextInt();
            while (t > 0) {
                t--;
                int n, m;
                n = fr.nextInt();
                m = fr.nextInt();
                List<List<Integer>> matrix = new ArrayList<>();
                boolean ans = true;
                for (int i = 0; i < n; i++) {
                    List<Integer> row = new ArrayList<>();
                    for (int j = 0; j < m; j++) {
                        int curr = fr.nextInt();
                        int no = getNo(i, j, n, m);
                        if (no < curr) {
                            ans = false;
                            row.add(curr);
                        } else {
                            row.add(no);
                        }
                    }
                    matrix.add(row);
                }
                if (ans) {
                    System.out.println("YES");
                    for (int i = 0; i < n; i++) {
                        List<Integer> row = matrix.get(i);
                        for (int j = 0; j < m; j++) {
                            System.out.print(row.get(j) + " ");
                        }
                        System.out.print("\n");
                    }
                } else System.out.println("NO");
            }
        } catch (Exception e) {

        }
    }

    private static int getNo(int i, int j, int n, int m) {
        int total = 0;
        if(j>0) total++;
        if(j<m-1) total++;
        if(i>0) total++;
        if(i<n-1) total++;

        return total;
    }

    static class FastReader {

        byte[] buf = new byte[2048];
        int index, total;
        InputStream in;

        FastReader(InputStream is) {
            in = is;
        }

        int scan() throws IOException {
            if (index >= total) {
                index = 0;
                total = in.read(buf);
                if (total <= 0) {
                    return -1;
                }
            }
            return buf[index++];
        }

        String next() throws IOException {
            int c;
            for (c = scan(); c <= 32; c = scan()) ;
            StringBuilder sb = new StringBuilder();
            for (; c > 32; c = scan()) {
                sb.append((char) c);
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c, val = 0;
            for (c = scan(); c <= 32; c = scan()) ;
            boolean neg = c == '-';
            if (c == '-' || c == '+') {
                c = scan();
            }
            for (; c >= '0' && c <= '9'; c = scan()) {
                val = (val << 3) + (val << 1) + (c & 15);
            }
            return neg ? -val : val;
        }

        long nextLong() throws IOException {
            int c;
            long val = 0;
            for (c = scan(); c <= 32; c = scan()) ;
            boolean neg = c == '-';
            if (c == '-' || c == '+') {
                c = scan();
            }
            for (; c >= '0' && c <= '9'; c = scan()) {
                val = (val << 3) + (val << 1) + (c & 15);
            }
            return neg ? -val : val;
        }
    }

}

