		int n = matrix.length;
		int m = matrix[0].length;
		matrix[0][0] = 2;
		matrix[n - 1][0] = 2;
		matrix[0][m - 1] = 2;
		matrix[n - 1][m - 1] = 2;

		for (int i = 1; i < n - 1; i++) {
			matrix[i][0] = 3;
			matrix[i][m - 1] = 3;
		}
		for (int j = 1; j < m - 1; j++) {
			matrix[0][j] = 3;
			matrix[n - 1][j] = 3;
		}

		for (int i = 1; i < n - 1; i++) {
			for (int j = 1; j < m - 1; j++) {
				matrix[i][j] = 4;
			}
		}
	}

	private static boolean canSolve(int[][] matrix) {



		int n = matrix.length;
		int m = matrix[0].length;
		if (matrix[0][0] > 2 || matrix[n - 1][0] > 2 || matrix[0][m - 1] > 2 || matrix[n - 1][m - 1] > 2) {
			return false;
		}
		for (int i = 0; i < n; i++) {
			if (matrix[i][0] > 3 || matrix[i][m - 1] > 3) {
				return false;
			}
		}
		for (int j = 0; j < m; j++) {
			if (matrix[0][j] > 3 || matrix[n - 1][j] > 3) {
				return false;
			}
		}

		for (int i = 1; i < n - 1; i++) {
			for (int j = 1; j < m - 1; j++) {
				if (matrix[i][j] > 4) {
					return false;
				}
			}
		}

		return true;
	}
}

