import java.util.Scanner;

public class NeighborGrid {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        int[][][] tests = new int[t][][];
        for (int i = 0; i < t; i++) {
            int n = scanner.nextInt(), m = scanner.nextInt();
            int[][] test = new int[n][m];
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < m; k++) {
                    test[j][k] = scanner.nextInt();
                }
            }
            tests[i] = test;
        }
        for (int i = 0; i < t; i++) {
            int[][] test = tests[i];
            boolean possible = canBe(test);
            System.out.println(possible ? "YES" : "NO");
            if (possible) {
                int[][] res = good(test);
                for (int j = 0; j < res.length; j++) {
                    for (int k = 0; k < res[0].length; k++) {
                        System.out.print(res[j][k] + " ");
                    }
                    System.out.println();
                }
            }
        }


    }
    private static boolean canBe(int[][] test) {
        for (int i = 0; i < test.length; i++) {
            for (int j = 0; j < test[0].length; j++) {
                if (neighbors(test, i, j) < test[i][j]) return false;
            }
        }
        return true;
    }
    private static int neighbors(int[][] arr, int i, int j) {
        int firstR = 0;
        int firstC = 0;
        int lastR = arr.length - 1;
        int lastC = arr[0].length - 1;
        if (firstR < i && i < lastR && firstC < j && j < lastC) return 4;
        else if ((i == firstR && j == firstC) || (i == lastR && j == firstC) || (i == firstR && j == lastC) || (i == lastR && j == lastC)) return 2;
        else return 3;
    }
    private static int[][] good(int[][] test) {
        int[][] res = new int[test.length][test[0].length];
        for (int i = 0; i < res.length; i++) {
            for (int j = 0; j < res[0].length; j++) {
                res[i][j] = neighbors(test, i, j);
            }
        }
        return res;
    }

}

