    public static int sol(Integer[][][][] dp, String a, String b, int l1, int r1, int l2, int r2){

        if(r1<0||r2<0||l1==a.length()||l2==b.length()){
            return Integer.MAX_VALUE;
        }

        if(dp[l1][r1][l2][r2]!=null){
            return dp[l1][r1][l2][r2];
        }
        if(l1>r1){
            dp[l1][r1][l2][r2] = r2-l2+1;
            return r2-l2+1;
        }
        if(l2>r2){
            dp[l1][r1][l2][r2] = r1-l1+1;
            return r1-l1+1;
        }
        if(a.substring(l1,r1).equals(b.substring(l2,r2))){
            dp[l1][r1][l2][r2] = 0;
            return 0;
        }

        int ans = Integer.MAX_VALUE;
        if(r1-l1>=r2-l2){
            ans = Math.min(ans,1+Math.min(sol(dp,a,b,l1+1,r1,l2,r2),sol(dp,a,b,l1,r1-1,l2,r2)));
        }
        if(r2-l2>=r1-l1){
            ans = Math.min(ans,1+Math.min(sol(dp,a,b,l1,r1,l2+1,r2),sol(dp,a,b,l1,r1,l2,r2-1)));
        }
        dp[l1][r1][l2][r2] = ans;
        return ans;

    }



