            int zero = 0, one = 0;
            char[] ans = new char[s.length()];
            Arrays.fill(ans, '?');
            for(int i = 0, j = s.length() - 1; i < j; i++, j--) {
                char c1 = s.charAt(i), c2 = s.charAt(j);
                if(c1 != '?' && c2 != '?') {
                    if(c1 != c2) {
                        can = false;
                        break;
