                    one += (c2 == '0' ? 0 : 2);
                    if(zero > a || one > b) {
                        can = false;
                        break;
                    }
                    ans[i] = c2;
                    ans[j] = c2;
                }
            }
            if(s.length() % 2 != 0 && s.charAt(s.length() / 2) != '?') {
                zero += (s.charAt(s.length() / 2) == '0' ? 1 : 0);
                one += (s.charAt(s.length() / 2) == '0' ? 0 : 1);
                if(zero > a || one > b) {
