import java.io.*;
import java.util.*;

public class Main {
    static void solve(InputReader in, OutputWriter out) {
        int t = in.nextInt();
        for (int i = 0; i < t; i++) {
            int availZeros = in.nextInt();
            int availOnes = in.nextInt();
            int n = availZeros+availOnes;
            char[] ar = in.next().toCharArray();

            boolean isPossible = true;
            int singleZeros = 0, singleOnes = 0;
            for (int j = 0; j < n/2; j++) {
                if (ar[j] != '?' && ar[n-1-j] != '?') {
                    if (ar[j] == ar[n-1-j]) {
                        if (ar[j] == '0') {
                            availZeros -= 2;
                        } else {
                            availOnes -= 2;
                        }
                    } else {
                        isPossible = false;
                        break;
                    }
                } else if (ar[j] != '?' || ar[n-1-j] != '?') {
                    if (ar[j] == '0' || ar[n-1-j] == '0') singleZeros++;
                    else if (ar[j] == '1' || ar[n-1-j] == '1') singleOnes++;
                }
            }
            if (n%2 != 0 && ar[n/2] != '?') {
                if (ar[n/2] == '0') availZeros--;
                else availOnes--;
            }

            if (!isPossible || availOnes < 0 || availZeros < 0 || singleZeros*2 > availZeros || singleOnes*2 > availOnes) {
                out.println(-1);
            } else {
                for (int j = 0; j < n / 2; j++) {
                    if (ar[j] == '?' && ar[n-1-j] != '?') {
                        ar[j] = ar[n-1-j];
                        if (ar[j] == '0') availZeros -= 2;
                        else availOnes -= 2;
                    } else if (ar[j] != '?' && ar[n-1-j] == '?') {
                        ar[n-1-j] = ar[j];
                        if (ar[j] == '0') availZeros -= 2;
                        else availOnes -= 2;
                    }
                }

                for (int j = 0; j < n / 2; j++) {
                    if (ar[j] == '?') {
                        if (availZeros < 2 && availOnes < 2) {
                            isPossible = false;
                            break;
                        } else if (availZeros > 1) {
                            ar[j] = ar[n-1-j] = '0';
                            availZeros -= 2;
                        } else {
                            ar[j] = ar[n-1-j] = '1';
                            availOnes -= 2;
                        }
                    }
                }
                if (!isPossible) {
                    out.println(-1);
                    continue;
                }
                if (n%2 != 0 && ar[n/2] == '?') {
                    ar[n/2] = availZeros > 0 ? '0' : '1';
                }

                for (char c : ar) {
                    out.print(c);
                }
                out.print('\n');
            }
        }
    }

    static class Pair<R, T> {
        R x;
        T y;
        public Pair(R x, T y) {
            this.x = x;
            this.y = y;
        }
    }

    static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        } else {
            return gcd(b, a % b);
        }
    }

    static void shufflePairList(List<Pair> list) {
        int index;
        Random random = new Random();
        for (int i = list.size() - 1; i > 0; i--) {
            index = random.nextInt(i + 1);
            if (index != i) {
                Pair t = list.get(i);
                list.set(i, list.get(index));
                list.set(index, t);
            }
        }
    }

    static void shuffleArray(int[] array) {
        int index;
        Random random = new Random();
        for (int i = array.length - 1; i > 0; i--) {
            index = random.nextInt(i + 1);
            if (index != i) {
                array[index] ^= array[i];
                array[i] ^= array[index];
                array[index] ^= array[i];
            }
        }
    }

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        solve(in, out);
        in.close();
        out.close();
    }

