        }

        System.out.print(answer);
    }

    public String solve(int a, int b, String s) {
        char[] S = s.toCharArray();
        int n = S.length;

        int[] count = new int[3];
        for (int i = 0;i < (n+1)/2;i++) {
            if (S[i] == '?' && S[n-i-1] == '?') {
            } else if (S[i] == '?') {
                S[i] = S[n-i-1];
            } else if (S[n-i-1] == '?') {
                S[n-i-1] = S[i];
            } else if (S[i] != S[n-i-1]) {
                return "-1";
            }
        }

        for (char value : S) {
            if (value == '?') {
                count[2]++;
            } else {
                count[value % 2]++;
            }
        }

        a -= count[0];
        b -= count[1];

        for (int i = 0;i < (n+1)/2;i++) {
            if (S[i] == '?') {
                if (a >= b) {
                    S[i] = S[n - i - 1] = '0';
                    a -= (i == n - i - 1) ? 1 : 2;
                } else {
                    S[i] = S[n - i - 1] = '1';
                    b -= (i == n - i - 1) ? 1 : 2;
                }
            }

            if (a < 0 || b < 0) {
                return "-1";
            }
        }

        StringBuilder answer = new StringBuilder();
        for (char c : S) {
            answer.append(c);
        }

        return answer.toString();
    }
}

class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int currentChar;
    private int numberOfChars;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numberOfChars == -1)
            throw new InputMismatchException();
        if (currentChar >= numberOfChars) {
            currentChar = 0;
            try {
                numberOfChars = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numberOfChars <= 0)
                return -1;
        }
        return buffer[currentChar++];
    }

    public boolean isSpace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int readInt() {
        int c = read();
        while (isSpace(c))
            c = read();

        byte sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }

        int result = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            result *= 10;
            result += (c - '0');
            c = read();
        }
        while (!isSpace(c));
        return sign * result;
    }

    public long readLong() {
        int c = read();
        while (isSpace(c))
            c = read();

        byte sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }

        long result = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            result *= 10;
            result += (c - '0');
            c = read();
        }
        while (!isSpace(c));

        return sign * result;
    }

    public double readDouble() {
        int c = read();
        while (isSpace(c))
            c = read();

        byte sign = 1;

        if (c == '-') {
            sign = -1;
            c = read();
        }

        double result = 0.0;

        while (!isSpace(c) && c != '.') {
            if (c == 'e' || c == 'E')
                return result * Math.pow(10, readInt());
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            result *= 10;
            result += (c - '0');
            c = read();
        }
        if (c == '.') {
            c = read();
            double m = 1;
            while (!isSpace(c)) {
                if (c == 'e' || c == 'E')
                    return result * Math.pow(10, readInt());
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                m /= 10;
                result += (c - '0') * m;
                c = read();
            }
        }
        return result * sign;
    }

    public String readString() {
        int c = read();
        while (isSpace(c))
            c = read();
        StringBuilder result = new StringBuilder();
        do {
            result.appendCodePoint(c);
            c = read();
        }
        while (!isSpace(c));

        return result.toString();
    }
}

