import java.io.PrintWriter;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;


public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CABPalindrome solver = new CABPalindrome();
        int testCount = Integer.parseInt(in.next());
        for (int i = 1; i <= testCount; i++)
            solver.solve(i, in, out);
        out.close();
    }

    static class CABPalindrome {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int a = in.nextInt();
            int a_current = 0;
            int b = in.nextInt();
            int b_current = 0;
            int q = 0;
            String s = in.next();
            char[] arr = s.toCharArray();
            for (int i = 0; i < s.length(); i++) {
                if (arr[i] == '0') {
                    if (arr[s.length() - i - 1] == '?') {
                        arr[s.length() - i - 1] = arr[i];
                    }
                } else if (arr[i] == '1') {
                    if (arr[s.length() - i - 1] == '?') {
                        arr[s.length() - i - 1] = arr[i];
                    }
                }
            }
            for (int i = 0; i < s.length(); i++) {
                if (arr[i] == '?') {
                    q++;
                } else if (arr[i] == '0') {
                    a_current++;
                } else if (arr[i] == '1') {
                    b_current++;
                }
            }

            a = a - a_current;
            b = b - b_current;

            if (a < 0 || b < 0 || a + b != q) {
                out.println("-1");
                return;
            }

            if (q == 0) {
                print(arr, out);
                return;
            }

            if (a % 2 == 1 && b % 2 == 1) {
                out.println("-1");
                return;
            }

            if (a % 2 == 0 && b % 2 == 0) {
                fill(arr, a, b);
                print(arr, out);
                return;
            }

            if (a % 2 == 1) {
                arr[arr.length / 2] = '0';
                a--;
                fill(arr, a, b);
                print(arr, out);
                return;
            }

            arr[arr.length / 2] = '1';
            b--;
            fill(arr, a, b);
            print(arr, out);
        }

        private void fill(char[] arr, int a, int b) {
            for (int i = 0; i < arr.length; i++) {
                if (arr[i] == '?') {
                    if (a > 0) {
                        arr[i] = '0';
                        a--;
                        if (arr[arr.length - i - 1] == '?') {
                            arr[arr.length - i - 1] = '0';
                            a--;
                        }
                    } else if (b > 0) {
                        arr[i] = '1';
                        b--;
                        if (arr[arr.length - i - 1] == '?') {
                            arr[arr.length - i - 1] = '1';
                            b--;
                        }
                    }
                }
            }
        }

        private boolean isPalindrome(String str) {
            int length = str.length();
            for (int i = 0; i < str.length(); i++) {
                if (str.charAt(i) != str.charAt(length - i - 1)) {
                    return false;
                }
                if (str.charAt(i) == '?') {
                    return false;
                }
            }
            return true;
        }

        private void print(char[] arr, PrintWriter out) {
            if (isPalindrome(Printer.print(arr))) {
                out.println(Printer.print(arr));
            } else {
                out.println("-1");
            }
        }

    }

    static class Printer {
        public static String print(char[] arr) {
            return print(arr, "");
        }

        public static String print(char[] arr, String separator) {
            if (arr == null || arr.length == 0) {
                return "";
            }

            StringBuilder sb = new StringBuilder();
            for (char c : arr) sb.append(c).append(separator);
            return sb.toString();
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.io.OutputStream;
