public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        int testCount = Integer.parseInt(in.next());
        for (int i = 1; i <= testCount; i++)
            solver.solve(i, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int zero = in.readInt();
            int one = in.readInt();

            int n = zero + one;
            char a[] = in.readCharArray(n);

            int l = 0, r = n - 1;
            while (l <= r) {

                if (l != r && ((a[l] == '0' && a[r] == '1') || (a[l] == '1' && a[r] == '0'))) {
                    out.println(-1);
                    return;
                }

                if (l == r) {
                    if (a[l] == '0') {
                        if (zero <= 0) {
                            out.println(-1);
                            return;
                        } else {
                            --zero;
                        }
                    } else if (a[l] == '1') {
                        if (one <= 0) {
                            out.println(-1);
                            return;
                        } else {
                            --one;
                        }
                    } else {
                        if (zero + one <= 0) {
                            out.println(-1);
                            return;
                        } else {
                            if (zero % 2 == 1) {
                                --zero;
                                a[l] = '0';
                            } else {
                                --one;
                                a[l] = '1';
                            }
                        }
                    }
                } else if (a[l] == a[r] && a[l] == '?') {
                    ++l;
                    --r;
                    continue;
                } else if (a[l] == a[r] && a[r] == '0') {

                    if (zero - 2 < 0) {
                        out.println(-1);
                        return;
                    }

                    zero -= 2;
                } else if (a[l] == a[r] && a[r] == '1') {

                    if (one - 2 < 0) {
                        out.println(-1);
                        return;
                    }

                    one -= 2;
                } else if (a[l] == '?' && a[r] == '0') {

                    if (zero - 2 < 0) {
                        out.println(-1);
                        return;
                    }

                    zero -= 2;
                    a[l] = '0';
                } else if (a[l] == '?' && a[r] == '1') {

                    if (one - 2 < 0) {
                        out.println(-1);
                        return;
                    }

                    one -= 2;
                    a[l] = '1';
                } else if (a[r] == '?' && a[l] == '0') {

                    if (zero - 2 < 0) {
                        out.println(-1);
                        return;
                    }

                    zero -= 2;
                    a[r] = '0';
                } else if (a[r] == '?' && a[l] == '1') {

                    if (one - 2 < 0) {
                        out.println(-1);
                        return;
                    }

                    one -= 2;
                    a[r] = '1';
                }

                ++l;
                --r;
            }

            l = 0;
            r = n - 1;
            while (l < r) {
                if (a[l] == a[r] && a[l] == '?') {
                    if (one >= 2) {
                        a[l] = a[r] = '1';
                        one -= 2;
                    } else if (zero >= 2) {
                        a[l] = a[r] = '0';
                        zero -= 2;
                    } else {
                        out.println(-1);
                        return;
                    }
                }
                ++l;
                --r;
            }

            out.println(a);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public char[] readCharArray(int size) {
            char[] array = new char[size];
            for (int i = 0; i < size; i++) {
                array[i] = readCharacter();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public String next() {
            return readString();
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

