  static int mod = (int) 1e9 + 7;



  static long fac[];

  static long ncr(int n, int r, int p) {

    if (n < r)
      return 0;

    if (r == 0)
      return 1;





    return (fac[n] * modInverse(fac[r], p) % p * modInverse(fac[n - r], p) % p) % p;
  }

  private static long modInverse(long l, int p) {

    return pow(l,p-2);
  }

