      a[i] = aa.get(i);
  }

  static long pow(long x, long y) {
    long res = 1l;
    while (y != 0) {
      if (y % 2 == 1) {
        res = x * res % mod;
      }
      y /= 2;
      x = (x * x) % mod;
    }
    return res;
  }


