public class abpalindrome2 {
	public static void main(String[] args) throws IOException {
		BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
		int t = Integer.parseInt(f.readLine());
		outerLoop : while(t > 0) {
			t --;
			StringTokenizer st = new StringTokenizer(f.readLine());
			int a = Integer.parseInt(st.nextToken());
			int b = Integer.parseInt(st.nextToken());
			char[] s = f.readLine().toCharArray();
			int n = s.length;
			int currA = 0;
			int currB = 0;
			for(int i = 0; i < n; i ++) {
				int curr = s[i];
				if(curr != '?') {
					if(curr == '0') {

						if(s[n - i - 1] == '?') {

							s[n - i - 1] = '0';
						}
						else if(s[n - i - 1] != curr) {
							System.out.println(-1);
							continue outerLoop;
						}
					}
					if(curr == '1') {

						if(s[n - i - 1] == '?') {

							s[n - i - 1] = '1';
						}
						else if(s[n - i - 1] != curr) {
							System.out.println(-1);
							continue outerLoop;
						}
					}
				}
				else {
					if(s[n - i - 1] == '?') continue;
					else if(s[n - i - 1] == '0') {

						s[i] = '0';
					}
					else if(s[n - i - 1] == '1') {

						s[i] = '1';
					}
				}
			}
			for(char x : s) {
				if(x == '0') currA ++;
				if(x == '1') currB ++;
			}
			int diffA = a - currA;
			int diffB = b - currB;
			for(int i = 0; i < n/2; i ++) {
				if(s[i] == '?') {
					if(diffA > 1) {
						diffA -= 2;
						s[i] = '0';
						s[n - i - 1] = '0';
					}
					else {
						diffB -= 2;
						s[i] = '1';
						s[n - i - 1] = '1';
					}
				}
			}
			if(n % 2 == 1 && s[n/2] == '?') {
				if(diffA > 0) {
					diffA --;
					s[n/2] = '0';
				}
				else {
					diffB --;
					s[n/2] = '1';
				}
			}
			if(diffA == 0 && diffB == 0) System.out.println(new String (s));
			else System.out.println(-1);
		}
	}
}

