                        continue;
                    }

                    op[i] = Integer.parseInt(arr[a+b-i-1]);
                }else{
                    op[i] = Integer.parseInt(arr[i]);
                }
                if(op[i] == 1){
                    num1s++;
                }else if(op[i] == 0){
                    num0s++;
                }
            }
            num0s = 0;
            num1s = 0;
            for(int i : op){
                if(i == 1){
