                    int diff1 = b-num1s;

                    if(op[r] == -1){
                        int add = 2;
                        if(r == i)
                            add = 1;
                        if(diff > diff1){

                            num0s+=add;
                            op[i] = 0;
                            op[r] = 0;
                        }else{
                            num1s+=add;
                            op[i] = 1;
                            op[r] = 1;
                        }
