public class Codeforces {
	static int mod=1000_000_007;
	public static void main(String[] args) {

		FastScanner fs=new FastScanner();
		int t=fs.nextInt();
		while(t-->0) {
			int a=fs.nextInt(),b=fs.nextInt();
			char arr[]=fs.next().toCharArray();
			solve(a,b,arr);
		}

	}
	static void solve(int a,int b,char[]arr) {
		int n=a+b;
		char ques='?',one='1',zero='0';
		for(int i=0;i<n;i++) {
			if(arr[i]==zero) a--;
			else if(arr[i]==one) b--;
		}
		for(int i=0;i<n;i++) {

			if(arr[i]=='?'&&arr[n-1-i]!=ques) {
				arr[i]=arr[n-1-i];
				if(arr[n-1-i]==one) {
					b--;
				}
				else a--;
			}
			if(a<0||b<0) {
				System.out.println(-1);
				return ;
			}

		}
		for(int i=0;i<n&&a>1;i++) {
			if(arr[i]==ques&&i!=n-i-1) {
				arr[i]=arr[n-1-i]=zero;
				a-=2;
			}
		}
		for(int i=0;i<n&&b>1;i++) {
			if(arr[i]==ques&&i!=n-i-1) {
				arr[i]=arr[n-1-i]=one;
				b-=2;
			}
		}
		if(arr[n/2]==ques&&n/2==n-(n/2)-1) {
			if(a>0) {
				arr[n/2]='0';
				a--;
			}
			else if(b>0) {
				arr[n/2]=one;
				b--;
			}
			else {
				System.out.println(-1);
				return ;
			}
		}
		if(a==0&&b==0&&isp(arr))
		System.out.println(String.valueOf(arr));
		else System.out.println(-1);
	}
	static boolean isp(char arr[]) {
		int l=0,r=arr.length-1;
		while(l<r) {
			if(arr[l]!=arr[r])
				return false;
			l++;
			r--;
		}
		return true;
	}
	static void mysort(int[] a) {

		int n=a.length;
		Random r=new Random();
		for (int i=0; i<a.length; i++) {
			int oi=r.nextInt(n), temp=a[i];
			a[i]=a[oi];
			a[oi]=temp;
		}


		Arrays.sort(a);
	}


