            for(i=0,j=N-1;i<N;i++,j--)
            {
                if(str[i]=='?'&&str[j]=='?') continue;
                if(str[i]!='?')
                {
                    if(str[j]=='?') str[j]=str[i];
                    else if(str[i]!=str[j]) break;
                }
            }
            if(i<N) flag=false;

            for(char ch:str)
            {
                if(ch=='0') a--;
                else if(ch=='1') b--;
            }

            for(i=0,j=N-1;i<N;i++,j--)
            {
                if(str[i]=='?')
                {
                    if(a>b)
                    {
                        str[i] = str[j] = '0';
                        if(i!=j) a-=2;
                        else a--;
                    }
                    else
                    {
                        str[i] = str[j] = '1';
                        if(i!=j) b-=2;
                        else b--;
                    }
                }
