public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while (t > 0) {
            int a = sc.nextInt(), b = sc.nextInt();
            String input = sc.next();
            System.out.println(findPalindrome(input, a, b));
            t--;
        }
    }

    public static String findPalindrome(String input, int a, int b) {
        char[] palindrome = input.toCharArray();
        int n = a + b;

        for (int i = 0; i < n / 2; i++) {
            if (palindrome[i] != palindrome[n - i - 1]) {
                if (palindrome[i] == '?' || palindrome[n - i - 1] == '?') {
                    if (palindrome[i] != '?') palindrome[n - i - 1] = palindrome[i];
                    else palindrome[i] = palindrome[n - i - 1];
                } else return "-1";
            }
        }

        for (int i = 0; i < n / 2; i++) {
            if (palindrome[i] == '0') a -= 2;
            else if (palindrome[i] == '1') b -= 2;
        }
        for (int i = 0; i < n / 2; i++) {
            if (palindrome[i] == '?') {
                if (a >= 2) {
                    palindrome[i] = '0';
                    palindrome[n - i - 1] = '0';
                    a -= 2;
                } else if (b >= 2) {
                    palindrome[i] = '1';
                    palindrome[n - i - 1] = '1';
                    b -= 2;
                } else return "-1";
            }
        }
        if (n % 2 != 0) {
            if (a % 2 != 0) {
                if (palindrome[n / 2] != '1') {
                    palindrome[n / 2] = '0';
                    a--;
                }
            }
            else {
                if (palindrome[n / 2] != '0') {
                    palindrome[n / 2] = '1';
                    b--;
                }
            }
        }
        if ( a != 0 || b != 0) return "-1";
        return new String(palindrome);
    }
}

