            int n = arr.length;
            for (int i = 0; i < n; i++) {
                if (arr[i] == '?' && arr[n - i - 1] != '?') {
                    arr[i] = arr[n - i - 1];
                } 
                if (arr[i] != '?' && arr[n - i - 1] == '?') {
                    arr[n - i - 1] = arr[i];
                }
            }
            for (int i = 0; i < n; i++) {
                if (arr[i] == '0') {
                    a--;
                } else if (arr[i] == '1') {
                    b--;
                }
            }
            for (int i = 0; i < n; i++) {
                if (arr[i] == '?') {
                    if (a > b) {
                        arr[i] = '0';
                        arr[n - i - 1] = '0';
                        if (i == n - i - 1) {
                            a--;
                        } else {
                            a -= 2;
                        }
                    } else {
                        arr[i] = '1';
                        arr[n - i - 1] = '1';
                        if (i == n - i - 1) {
                            b--;
                        } else {
                            b -= 2;
                        }
                    }
                }
            }
