        FastReader s = new FastReader();
        int t = s.nextInt();
        while(t-->0){
            solve(s);
        }
    }
    public static void solve(FastReader s){
        int a = s.nextInt();
        int b = s.nextInt();
        StringBuilder str = new StringBuilder(s.next());
        int len = str.length();
        int list[] = new int[len/2];
        int count = 0;
        int i=0,j=str.length()-1;
        while(i<j){
            if(str.charAt(i)=='0'&&str.charAt(j)=='1'){
                System.out.println("-1");
                return;
            }
            if(str.charAt(i)=='0'&&str.charAt(j)=='0') {
                a-=2;
            }
            if(str.charAt(i)=='1'&&str.charAt(j)=='1') {
                b-=2;
            }
            if(str.charAt(i)=='0'&&str.charAt(j)=='?'){
                str.replace(j,j+1,"0");
                a-=2;
            }
            if(str.charAt(i)=='?'&&str.charAt(j)=='0'){
                str.replace(i,i+1,"0");
                a-=2;
            }
            if(str.charAt(i)=='1'&&str.charAt(j)=='?'){
                str.replace(j,j+1,"1");
                b-=2;
            }
            if(str.charAt(i)=='?'&&str.charAt(j)=='1'){
                str.replace(i,i+1,"1");
                b-=2;
            }
            if(str.charAt(i)=='?'&&str.charAt(j)=='?'){
                list[count++] = i;
            }
            i++;
            j--;
        }
        for(int k=0;k<count;k++){
            int n = list[k];
            if(a>1){
                str.replace(n,n+1,"0");
                str.replace(len-n-1,len-n,"0");
                a-=2;
            }else if(b>1){
                str.replace(n,n+1,"1");
                str.replace(len-n-1,len-n,"1");
                b-=2;
            }
        }
        if(len%2!=0){
            if(str.charAt(len/2)=='?'){
                if(a>0){
                    str.replace(len/2,(len/2)+1,"0");
                    a--;
                }else if(b>0){
                    str.replace(len/2,(len/2)+1,"1");
                    b--;
                }
            }else {
                if(str.charAt(len/2)=='0') a--;
                if(str.charAt(len/2)=='1') b--;
            }

        }
        if(a>0||b>0){
            System.out.println("-1");
        }else {
            System.out.println(str);
        }
    }
}

import java.io.BufferedOutputStream;
