import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class C {
    public static void main(String[] args) {
        new C().solve(System.in, System.out);
    }

    public void solve(InputStream in, OutputStream out) {
        InputReader inputReader = new InputReader(in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(out));

        int t = inputReader.nextInt();
        for (int t1 = 0; t1 < t; t1++) {
            int a = inputReader.nextInt();
            int b = inputReader.nextInt();
            String s = inputReader.next();
            String result = solve(a, b, s);
            writer.println(result);
        }

        writer.close();
    }

    public String solve(int a, int b, String s) {
        char[] c = new char[s.length()];
        for (int i = 0; i < s.length(); i++) {
            c[i] = s.charAt(i);
        }

        for (int i = 0; i < s.length() / 2; i++) {
            int j = s.length() - 1 - i;
            if (c[i] == '?' && c[j] != '?') {
                c[i] = c[j];
                continue;
            }
            if (c[i] != '?' && c[j] == '?') {
                c[j] = c[i];
                continue;
            }
            if (c[i] != '?' && c[j] != '?' && c[i] != c[j]) {
                return "-1";
            }
        }

        int zeroCount = 0;
        int oneCount = 0;
        for (int i = 0; i < c.length; i++) {
            if (c[i] == '0') {
                zeroCount++;
                continue;
            }
            if (c[i] == '1') {
                oneCount++;
            }
        }

        if (zeroCount > a || oneCount > b) {
            return "-1";
        }

        for (int i = 0; i < c.length / 2; i++) {
            int j = s.length() - 1 - i;
            if (c[i] == '?') {
                if (zeroCount < a - 1) {
                    c[i] = '0';
                    c[j] = '0';
                    zeroCount += 2;
                    continue;
                }
                if (oneCount < b - 1) {
                    c[i] = '1';
                    c[j] = '1';
                    oneCount += 2;
                    continue;
                }
                return "-1";
            }
        }
        if (c.length % 2 == 1) {
            int i = c.length / 2;
            if (c[i] == '?') {
                if (oneCount < b) {
                    c[i] = '1';
                    oneCount++;
                } else if (zeroCount < a) {
                    c[i] = '0';
                    zeroCount++;
                } else {
                    return "-1";
                }
            }
        }
        if (zeroCount != a || oneCount != b) {
            return "-1";
        }
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < c.length; i++) {
            result.append(c[i]);
        }
        return result.toString();
    }

    private static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

public class C {
    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);
        int t = scan.nextInt();

        for (int testcase = 0; testcase < t; testcase++) {
            int a = scan.nextInt(), b = scan.nextInt();
            String word = scan.next();

            String ans = solve(a, b, word);
            System.out.println(ans);
        }
        scan.close();
    }

    private static String solve(int a, int b, String word) {

        int i = 0, j = word.length() - 1;

        char[] arr = word.toCharArray();

        for (; i < arr.length; i++) {
            if (arr[i] == '0')
                a--;
            else if (arr[i] == '1')
                b--;
        }

        i = 0;

        while (i < j) {

            if (arr[i] == arr[j]) {
                i++;
                j--;
            } else if (arr[i] == '0' && arr[j] == '?') {
                arr[j] = '0';
                a--;
                i++;
                j--;
            } else if (arr[i] == '1' && arr[j] == '?') {
                arr[j] = '1';
                b--;
                i++;
                j--;
            } else if (arr[j] == '0' && arr[i] == '?') {
                arr[i] = '0';
                a--;
                i++;
                j--;
            } else if (arr[j] == '1' && arr[i] == '?') {
                arr[i] = '1';
                b--;
                i++;
                j--;
            } else {
                i++;
                j--;
            }

        }

        i = 0;
        j = arr.length - 1;

        while (i <= j) {
            if (i != j) {
                if (arr[i] == arr[j] && arr[i] == '?') {
                    if (a > b) {
                        a -= 2;
                        arr[i] = '0';
                        arr[j] = '0';
                    } else {
                        b -= 2;
                        arr[i] = '1';
                        arr[j] = '1';
                    }
                }
            } else {
                if (arr[i] == arr[j] && arr[i] == '?') {
                    if (a > b) {
                        a -= 1;
                        arr[i] = '0';
                        arr[j] = '0';
                    } else {
                        b -= 1;
                        arr[i] = '1';
                        arr[j] = '1';
                    }
                }
            }
            i++;
            j--;
        }

        if (a == 0 && b == 0 && palindrome(arr))
            return String.valueOf(arr);
        else
            return "-1";
    }

    private static boolean palindrome(char[] arr) {

        int i = 0, j = arr.length - 1;
        while (i < j) {
            if (arr[i++] != arr[j--]) {
                return false;
            }
        }
        return true;
    }
}

