	        try {
	            br = new BufferedReader(new FileReader(f));
	        } catch (FileNotFoundException e) {
	            e.printStackTrace();
	        }
	    }

	    public FastScanner(InputStream f) {
	        br = new BufferedReader(new InputStreamReader(f));
	    }

	    String next() {
	        while (st == null || !st.hasMoreTokens()) {
	            String s = null;
	            try {
	                s = br.readLine();
	            } catch (IOException e) {
	                e.printStackTrace();
	            }
	            if (s == null)
	                return null;
	            st = new StringTokenizer(s);
	        }
	        return st.nextToken();
	    }

	    boolean hasMoreTokens() {
	        while (st == null || !st.hasMoreTokens()) {
	            String s = null;
	            try {
	                s = br.readLine();
	            } catch (IOException e) {
	                e.printStackTrace();
	            }
	            if (s == null)
	                return false;
	            st = new StringTokenizer(s);
	        }
	        return true;
	    }

	    int nextInt() {
	        return Integer.parseInt(next());
	    }

	    long nextLong() {
	        return Long.parseLong(next());
	    }

	    double nextDouble(){
	        return Double.parseDouble(next());
	    }
	}

	public static void main(String[] args) {
		FastScanner sc = new FastScanner(System.in);
		int R = sc.nextInt();
		int C = sc.nextInt();

		List<String> map = new ArrayList<String>();
		int exitR = -1;
		int exitC = -1;
		for (int r = 0; r < R; r++) {
			String line = sc.next();
			map.add(line);
			if (line.indexOf("E") >= 0) {
				exitR = r;
				exitC = line.indexOf("E");
			}
		}

		int[][] dist = new int[R][C];
		for (int[] drow : dist)
			Arrays.fill(drow, -1);
		dist[exitR][exitC] = 0;

		List<int[]> breeders = new ArrayList<int[]>();
		int me = -1;

		Queue<int[]> q = new LinkedList<int[]>();
		q.add(new int[] {exitR, exitC});
		while (!q.isEmpty()) {
			int[] pos = q.poll();
			int r = pos[0];
			int c = pos[1];
			int d = dist[r][c];
			if ('0' <= map.get(r).charAt(c) && map.get(r).charAt(c) <= '9')
				breeders.add(new int[] {d, map.get(r).charAt(c) - '0'});
			else if (map.get(r).charAt(c) == 'S')
				me = d;

			if (r + 1 < R && dist[r+1][c] == -1 && map.get(r).charAt(c) != 'T') {
				dist[r+1][c] = d + 1;
				q.add(new int[] {r+1, c});
			}
			if (r - 1 >= 0 && dist[r-1][c] == -1 && map.get(r).charAt(c) != 'T') {
				dist[r-1][c] = d + 1;
				q.add(new int[] {r-1, c});
			}
			if (c + 1 < C && dist[r][c+1] == -1 && map.get(r).charAt(c) != 'T') {
				dist[r][c+1] = d + 1;
				q.add(new int[] {r, c+1});
			}
			if (c - 1 >= 0 && dist[r][c-1] == -1 && map.get(r).charAt(c) != 'T') {
				dist[r][c-1] = d + 1;
				q.add(new int[] {r, c-1});
			}
		}

		long ans = 0;
		for (int[] obj : breeders) {
			int d = obj[0];
			int qty = obj[1];
			if (d <= me)
				ans += qty;
		}
		System.out.println(ans);
	}

}

