class TaskB {
    public void solve(int testNumber, InputStreamReader inSt, PrintWriter out) {
        InputReader in = new InputReader(inSt);

        int r = in.nextInt();
        int c = in.nextInt();
        int[][] map = new int[r + 2][c + 2];

        for (int i = 0; i < map[0].length; i++) {
            map[0][i] = -1;
        }
        for (int i = 0; i < map[r + 1].length; i++) {
            map[r + 1][i] = -1;
        }

        for (int i = 0; i < r + 2; i++) {
            map[i][0] = -1;
        }
        for (int i = 0; i < r + 2; i++) {
            map[i][c + 1] = -1;
        }

        int startR = 0;
        int startC = 0;

        int exitR = 0;
        int exitC = 0;

        for (int i = 0; i < r; i++) {
            String st = in.next();
            for (int j = 0; j < st.length(); j++) {
                char ch = st.charAt(j);
                if (ch == 'T') {
                    map[i + 1][j + 1] = -1;
                } else if (ch == 'S') {
                    startR = i + 1;
                    startC = j + 1;
                } else if (ch == 'E') {
                    exitR = i + 1;
                    exitC = j + 1;
                } else {
                    int k = ch - '0';
                    map[i + 1][j + 1] = k;
                }
            }
        }

        int[][] distance = find(map, exitR, exitC);
        int pathLen = distance[startR][startC];
        long result = 0;
        for (int i = 1; i < r + 1; i++) {
            for (int j = 1; j < c + 1; j++) {
                if (map[i][j] > 0) {
                    if (distance[i][j] <= pathLen) {
                        result += map[i][j];
                    }
                }
            }
        }

        out.println(result);
    }

    private int[][] find(int[][] map, int firstR, int firstC) {
        LinkedList<Point> queue = new LinkedList<>();

        boolean[][] used = new boolean[map.length][map[0].length];
        int[][] distance = new int[map.length][map[0].length];
        for (int i = 0; i < distance.length; i++) {
            Arrays.fill(distance[i], (int) 1e9);
        }
        distance[firstR][firstC] = 0;

        queue.add(new Point(firstR, firstC));
        used[firstR][firstC] = true;
        while (!queue.isEmpty()) {
            Point curP = queue.removeFirst();
            if (map[curP.r - 1][curP.c] >= 0) {
                if (!used[curP.r - 1][curP.c]) {
                    used[curP.r - 1][curP.c] = true;
                    queue.addLast(new Point(curP.r - 1, curP.c));
                    distance[curP.r - 1][curP.c] = distance[curP.r][curP.c] + 1;
                }
            }
            if (map[curP.r + 1][curP.c] >= 0) {
                if (!used[curP.r + 1][curP.c]) {
                    used[curP.r + 1][curP.c] = true;
                    queue.addLast(new Point(curP.r + 1, curP.c));
                    distance[curP.r + 1][curP.c] = distance[curP.r][curP.c] + 1;
                }
            }

            if (map[curP.r][curP.c - 1] >= 0) {
                if (!used[curP.r][curP.c - 1]) {
                    used[curP.r][curP.c - 1] = true;
                    queue.addLast(new Point(curP.r, curP.c - 1));
                    distance[curP.r][curP.c - 1] = distance[curP.r][curP.c] + 1;
                }
            }

            if (map[curP.r][curP.c + 1] >= 0) {
                if (!used[curP.r][curP.c + 1]) {
                    used[curP.r][curP.c + 1] = true;
                    queue.addLast(new Point(curP.r, curP.c + 1));
                    distance[curP.r][curP.c + 1] = distance[curP.r][curP.c] + 1;
                }
            }

        }
        return distance;
    }

    class Point {
        int r;
        int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    class InputReader {
        public BufferedReader reader;
        private String[] currentArray;
        int curPointer;

        public InputReader(InputStreamReader inputStreamReader) {
            reader = new BufferedReader(inputStreamReader);
        }

        public String next() {
            try {
                currentArray = null;
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public void nextChars(char[] t) {
            try {
                currentArray = null;
                reader.read(t);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public char nextChar() {
            try {
                currentArray = null;
                return (char) reader.read();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            if ((currentArray == null) || (curPointer >= currentArray.length)) {
                try {
                    currentArray = reader.readLine().split(" ");
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                curPointer = 0;
            }
            return Integer.parseInt(currentArray[curPointer++]);
        }

        public long nextLong() {
            if ((currentArray == null) || (curPointer >= currentArray.length)) {
                try {
                    currentArray = reader.readLine().split(" ");
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                curPointer = 0;
            }
            return Long.parseLong(currentArray[curPointer++]);
        }

    }
