public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BBiridianForest solver = new BBiridianForest();
        solver.solve(1, in, out);
        out.close();
    }

    static class BBiridianForest {
        int row;
        int col;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            row = in.ni();
            col = in.ni();
            int[][] ar = new int[row][col];
            int sr = -1, sc = -1, ec = -1, er = -1;
            for (int i = 0; i < row; ++i) {
                String curr = in.next();
                for (int j = 0; j < col; ++j) {
                    char r = curr.charAt(j);
                    if (r == 'T') ar[i][j] = -1;
                    else if (r == 'S') {
                        sr = i;
                        sc = j;
                    } else if (r == 'E') {
                        er = i;
                        ec = j;
                    } else ar[i][j] = Character.getNumericValue(r);
                }
            }
            int[][] ans = new int[row][col];
            for (int i = 0; i < row; ++i) {
                for (int j = 0; j < col; ++j) ans[i][j] = Integer.MAX_VALUE;
            }
            ans[er][ec] = 0;
            PriorityQueue<Path> pq = new PriorityQueue<>(new Comparator<Path>() {

                public int compare(Path o1, Path o2) {
                    return Integer.compare(o1.dist, o2.dist);
                }
            });
            pq.add(new Path(er, ec, 0));
            while (!pq.isEmpty()) {
                Path pop = pq.poll();
                if (f(pop.i + 1, pop.j) && ar[pop.i + 1][pop.j] != -1 && pop.dist + 1 < ans[pop.i + 1][pop.j]) {
                    ans[pop.i + 1][pop.j] = pop.dist + 1;
                    pq.add(new Path(pop.i + 1, pop.j, pop.dist + 1));
                }
                if (f(pop.i - 1, pop.j) && ar[pop.i - 1][pop.j] != -1 && pop.dist + 1 < ans[pop.i - 1][pop.j]) {
                    ans[pop.i - 1][pop.j] = pop.dist + 1;
                    pq.add(new Path(pop.i - 1, pop.j, pop.dist + 1));
                }
                if (f(pop.i, pop.j + 1) && ar[pop.i][pop.j + 1] != -1 && pop.dist + 1 < ans[pop.i][pop.j + 1]) {
                    ans[pop.i][pop.j + 1] = pop.dist + 1;
                    pq.add(new Path(pop.i, pop.j + 1, pop.dist + 1));
                }
                if (f(pop.i, pop.j - 1) && ar[pop.i][pop.j - 1] != -1 && pop.dist + 1 < ans[pop.i][pop.j - 1]) {
                    ans[pop.i][pop.j - 1] = pop.dist + 1;
                    pq.add(new Path(pop.i, pop.j - 1, pop.dist + 1));
                }
            }
            int num = ans[sr][sc];
            int pr = 0;
            for (int i = 0; i < row; ++i) {
                for (int j = 0; j < col; ++j) {
                    if (ar[i][j] != -1 && ans[i][j] <= num) {
                        pr += ar[i][j];
                    }
                }
            }
            out.print(pr);
        }

        public boolean f(int i, int j) {
            if (i >= 0 && j >= 0 && i < row && j < col) return true;
            else return false;
        }

        public class Path {
            int i;
            int j;
            int dist;

            public Path(int i, int j, int dist) {
                this.i = i;
                this.j = j;
                this.dist = dist;
            }

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ni() {
            return Integer.parseInt(next());
        }

    }
}

