        char[][] map = new char[r][c];


        int endI = -1, endJ = -1, startI = -1, startJ = -1;
        for (int i=0; i<r; i++){
            String s = in.next();
            for (int j=0; j<c; j++){
                map[i][j] = s.charAt(j);
                len[i][j] = -1;

                if (map[i][j] == 'T'){
                    len[i][j] = -2;
                }

                if (map[i][j] == 'E'){
                    endI = i;
                    endJ = j;
                }
                if (map[i][j] == 'S'){
                    startI = i;
                    startJ = j;
                }
            }
        }

        len[endI][endJ] = 0;

        ArrayList<Point> first = new ArrayList<>();
        first.add(new Point(endI, endJ));

        ArrayList<ArrayList<Point>> allNextCallBuffer = new ArrayList<>();
        ArrayList<ArrayList<Point>> allNextCall = new ArrayList<>();
        allNextCall.add(first);

        while (allNextCall.size() > 0) {
            for (ArrayList<Point> list : allNextCall){
                for (Point p : list){
                    allNextCallBuffer.add(getLen(len, p.x, p.y));
                }
            }

            allNextCall = allNextCallBuffer;
            allNextCallBuffer = new ArrayList<>();
        }

        for (int i=0; i<len.length; i++){
            for (int j=0; j< len[i].length; j++){
                if (len[i][j] >= 0) debug.print(len[i][j]+ " ");
                else debug.print("* ");
            }

            debug.println("");
        }

        int lenToExit = len[startI][startJ];
        debug.println("LenToExit: " + lenToExit);

        int countBattle = 0;
        for (int i=0; i<r; i++){
            for (int j=0; j<c; j++){
                if (   (len[i][j] <= lenToExit && len[i][j] >= 0) &&
                       (map[i][j] == '1' || map[i][j] == '2' || map[i][j] == '3' ||
                        map[i][j] == '4' || map[i][j] == '5' || map[i][j] == '6' ||
                        map[i][j] == '7' || map[i][j] == '8' || map[i][j] == '9' ||
                        map[i][j] == '0')){
                    countBattle += Integer.parseInt(map[i][j] + "");
                }
            }
        }

        out.println(countBattle);

    }

    public static ArrayList<Point> getLen(int[][] len, int i, int j){
        ArrayList<Point> nextCall = new ArrayList<>();

        if (j > 0 && len[i][j-1] == -1){
            len[i][j-1] = len[i][j]+1;
            nextCall.add(new Point(i, j-1));
        }
        if (j < len[i].length-1 && len[i][j+1] == -1){
            len[i][j+1] = len[i][j]+1;
            nextCall.add(new Point(i, j+1));
        }
        if (i > 0 && len[i-1][j] == -1){
            len[i-1][j] = len[i][j]+1;
            nextCall.add(new Point(i-1, j));
        }
        if (i < len.length-1 && len[i+1][j] == -1){
            len[i+1][j] = len[i][j]+1;
            nextCall.add(new Point(i+1, j));
        }

        return nextCall;
    }

