class TaskB {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int height = in.nextInt();
        int width = in.nextInt();
        char[][] forest = in.next2DCharArray(height, width);
        int startI = -1;
        int startJ = -1;
        int endI = -1;
        int endJ = -1;
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (forest[i][j] == 'S') {
                    startI = i;
                    startJ = j;
                } else if (forest[i][j] == 'E') {
                    endI = i;
                    endJ = j;
                }
            }
        }
        int[][] dist = new int[height][width];
        ArrayUtils.fill(dist, -1);
        dist[endI][endJ] = 0;
        Queue<Pair<Integer, Integer>> queue = new ArrayDeque<Pair<Integer, Integer>>();
        queue.add(Pair.makePair(endI, endJ));
        while (!queue.isEmpty()) {
            int curI = queue.peek().first;
            int curJ = queue.poll().second;
            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    if ((di == 0) ^ (dj == 0)) {
                        int newI = curI + di;
                        int newJ = curJ + dj;
                        if (newI < 0 || newI >= height || newJ < 0 || newJ >= width
                                || forest[newI][newJ] == 'T' || dist[newI][newJ] != -1)
                            continue;
                        dist[newI][newJ] = dist[curI][curJ] + 1;
                        queue.add(Pair.makePair(newI, newJ));
                    }
                }
            }
        }
        int myDist = dist[startI][startJ];
        int answer = 0;
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (dist[i][j] != -1 && dist[i][j] <= myDist && forest[i][j] >= '0' && forest[i][j] <= '9') {
                    answer += forest[i][j] - '0';
                }
            }
        }
        out.println(answer);
    }
}

class InputReader {

    private InputStream stream;
    private byte[] buf = new byte[1 << 16];
    private int curChar;
    private int numChars;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int nextInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c & 15;
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public static boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public char nextChar() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        return (char) c;
    }

    public char[] nextCharArray(int count) {
        char[] result = new char[count];
        for (int i = 0; i < count; i++) {
            result[i] = nextChar();
        }
        return result;
    }

    public char[][] next2DCharArray(int n, int m) {
        char[][] result = new char[n][];
        for (int i = 0; i < n; i++) {
            result[i] = nextCharArray(m);
        }
        return result;
    }

    }

