class TaskB {
    private static final int INF = 100000000;
    private final int[] di = { 0, 1, 0, -1 };
    private final int[] dj = { 1, 0, -1, 0 };

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int N = in.nextInt();
        int M = in.nextInt();
        char[][] A = new char[N][M];
        for(int i = 0; i < N; i++)
            A[i] = in.nextString().toCharArray();

        int si = -1;
        int sj = -1;
        int ei = -1;
        int ej = -1;
        for(int i = 0; i < N; i++)
            for(int j = 0; j < M; j++)
                if(A[i][j] == 'S') {
                    si = i;
                    sj = j;
                }
                else if(A[i][j] == 'E') {
                    ei = i;
                    ej = j;
                }

        Queue<Integer> Q = new LinkedList<Integer>();
        int[][] D = new int[N][M];
        for(int i = 0; i < N; i++)
            Arrays.fill(D[i], INF);
        boolean[][] v = new boolean[N][M];
        Q.add(ei);
        Q.add(ej);
        D[ei][ej] = 0;
        v[ei][ej] = true;

        while(!Q.isEmpty()) {
            int pi = Q.remove();
            int pj = Q.remove();

            for(int d = 0; d < 4; d++) {
                int ni = pi + di[d];
                int nj = pj + dj[d];

                if(ni < 0 || ni >= N || nj < 0 || nj >= M)
                    continue;
                if(A[ni][nj] == 'T')
                    continue;

                if(D[pi][pj] + 1 < D[ni][nj]) {
                    D[ni][nj] = D[pi][pj] + 1;
                    if(!v[ni][nj]) {
                        v[ni][nj] = true;
                        Q.add(ni);
                        Q.add(nj);
                    }
                }
            }

            v[pi][pj] = false;
        }

        int d = D[si][sj];
        int ans = 0;
        for(int i = 0; i < N; i++)
            for(int j = 0; j < M; j++)
                if(Character.isDigit(A[i][j]) && D[i][j] <= d)
                    ans += A[i][j] - '0';

        out.println(ans);
    }
}

class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int nextInt() {
        return Integer.parseInt(nextString());
    }

    public String nextString() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuffer res = new StringBuffer();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));

        return res.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    }

