        }


        LinkedList<Integer> xQueue = new LinkedList<Integer>();
        LinkedList<Integer> yQueue = new LinkedList<Integer>();
        LinkedList<Integer> count = new LinkedList<Integer>();

        xQueue.add(exitX);
        yQueue.add(exitY);
        count.add(0);
        visited[exitX][exitY] = true;

        while (!xQueue.isEmpty()) {
            int x = xQueue.poll();
            int y = yQueue.poll();
            int cnt = count.poll();

            if (graph[x][y] == 'S') {
                dist[x][y] = cnt;
                min = cnt;

            }

            if (graph[x][y] > '0' && graph[x][y] <= '9') {
                dist[x][y] = cnt;
            }

            if (x - 1 >= 0 && !visited[x - 1][y] && graph[x - 1][y] != 'T') {
                xQueue.add(x - 1);
                yQueue.add(y);
                visited[x - 1][y] = true;
                count.add(cnt + 1);
            }
            if (y - 1 >= 0 && !visited[x][y - 1] && graph[x][y - 1] != 'T') {
                xQueue.add(x);
                yQueue.add(y - 1);
                visited[x][y - 1] = true;
                count.add(cnt + 1);
            }
            if (x + 1 < n && !visited[x + 1][y] && graph[x + 1][y] != 'T') {
                xQueue.add(x + 1);
                yQueue.add(y);
                visited[x + 1][y] = true;
                count.add(cnt + 1);
            }
            if (y + 1 < m && !visited[x][y + 1] && graph[x][y + 1] != 'T') {
                xQueue.add(x);
                yQueue.add(y + 1);
                visited[x][y + 1] = true;
                count.add(cnt + 1);
            }

        }

        int ans = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if ((graph[i][j] > '0' && graph[i][j] <= '9') && dist[i][j] <= min) {
                    ans += (graph[i][j] - '0');
                }
            }
        }
        System.out.println(ans);
    }
}

