class TaskB {
    int r, c;
    char[][] map;

    static final int[] dx = new int[] {1, -1, 0, 0};
    static final int[] dy = new int[] {0, 0, 1, -1};

    int[][] calcDistances(int startR, int startC) {
        final int INF = Integer.MAX_VALUE;
        int[][] res = new int[r][c];
        for (int[] ii: res)
            Arrays.fill(ii, INF);
        res[startR][startC] = 0;
        ArrayList<Integer> frontR = new ArrayList<Integer>();
        ArrayList<Integer> frontC = new ArrayList<Integer>();
        frontR.add(startR);
        frontC.add(startC);
        int t = 1;
        while (!frontR.isEmpty()) {
            ArrayList<Integer> nextFrontR = new ArrayList<Integer>();
            ArrayList<Integer> nextFrontC = new ArrayList<Integer>();
            for (int i = 0; i < frontR.size(); ++i) {
                int curR = frontR.get(i);
                int curC = frontC.get(i);
                for (int j = 0; j < 4; ++j) {
                    int nextR = curR + dx[j];
                    int nextC = curC + dy[j];
                    if (nextR >= 0 && nextR < r && nextC >= 0 && nextC < c
                        && res[nextR][nextC] == INF && map[nextR][nextC] != 'T') {
                        res[nextR][nextC] = t;
                        nextFrontR.add(nextR);
                        nextFrontC.add(nextC);
                    }
                }
            }
            frontR = nextFrontR;
            frontC = nextFrontC;
            ++t;
        }
        return res;
    }

    public void solve(@SuppressWarnings("UnusedParameters") int testNumber, TokenizerReader in, PrintWriter out) {
        r = in.nextInt();
        c = in.nextInt();
        int startR = 0, startC = 0, endR = 0, endC = 0;
        map = new char[r][c];
        for (int i = 0; i < r; ++i) {
            char[] s = in.nextString().toCharArray();
            for (int j = 0; j < c; ++j) {
                map[i][j] = s[j];
                if (s[j] == 'S') {
                    startR = i;
                    startC = j;
                } else if (s[j] == 'E') {
                    endR = i;
                    endC = j;
                }
            }
        }

        int[][] d = calcDistances(endR, endC);
        int t = d[startR][startC];

        int res = 0;
        for (int i = 0; i < r; ++i) for (int j = 0; j < c; ++j) {
            if (d[i][j] <= t && map[i][j] >= '1' && map[i][j] <= '9')
                res += (map[i][j] - '0');
        }

        out.println(res);
    }
}

