public class CopyOfproblemD {

	static void solve() throws IOException {
		int n = nextInt();
		int m = nextInt();
		char[][] grid = new char[n][m];
		int endx = -1, endy = -1;
		int stx = -1, sty = -1;
		for (int i = 0; i < n; i++) {
			grid[i] = nextToken().toCharArray();
			for (int j = 0; j < m; j++) {
				if (grid[i][j] == 'E') {
					endx = i;
					endy = j;
				} 
				else if (grid[i][j] == 'S') {
					stx = i;
					sty = j;
				}
			}
		}
		int[] qq = new int[n * m * 2];
		int qh = 0, qt = 0;
		qq[qt++] = endx;
		qq[qt++] = endy;
		int[][] dist = new int[n][m];
		for (int i = 0; i < n; i++) {
			Arrays.fill(dist[i], Integer.MAX_VALUE);
		}
		dist[endx][endy] = 0;
		int[] dx = {-1, 1, 0, 0};
		int[] dy = {0, 0, -1, 1};
		while (qh < qt) {
			int x = qq[qh++];
			int y = qq[qh++];
			for (int i = 0; i < 4; i++) {
				int nx = dx[i] + x;
				int ny = dy[i] + y;
				if (!(nx >= 0 && nx < n && ny >= 0 && ny < m && grid[nx][ny] != 'T')) 
					continue;
				if (dist[nx][ny] > dist[x][y] + 1) {
					dist[nx][ny] = dist[x][y] + 1;
					qq[qt++] = nx;
					qq[qt++] = ny;
				}
			}
		}
		int len = dist[stx][sty];
		int ans = 0;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (grid[i][j] != 'T' && grid[i][j] != 'S' && grid[i][j] != 'E') {
					if (dist[i][j] <= len) {
						int cnt = grid[i][j] - '0';
						ans += cnt;
					}
				}
			}
		}
		out.println(ans);
	}

	static BufferedReader br;
	static PrintWriter out;
	static StringTokenizer st;

	static boolean hasNextToken() throws IOException {
		while (st == null || !st.hasMoreTokens()) {
			String line = br.readLine();
			if (line == null) {
				return false;
			}
			st = new StringTokenizer(line);
		}
		return true;
	}

	static String nextToken() throws IOException {
		return hasNextToken() ? st.nextToken() : null;
	}

	static int nextInt() throws IOException {
		return Integer.parseInt(nextToken());
	}

	public static void main(String[] args) throws IOException {
		br = new BufferedReader(new InputStreamReader(System.in));
		out = new PrintWriter(new OutputStreamWriter(System.out));
		solve();
		br.close();
		out.close();
	}
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
