import java.util.Arrays;
import java.io.BufferedInputStream;
import java.util.PriorityQueue;
import java.io.FilterInputStream;
import java.io.InputStream;



public class Main {
    public static void main(String[] args) {
        new Thread(null, new Runnable() {
            public void run() {
                new Main().solve();
            }
        }, "1", 1 << 26).start();
    }

    void solve() {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        ScanReader in = new ScanReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BBiridianForest solver = new BBiridianForest();
        solver.solve(1, in, out);
        out.close();
    }

    static class BBiridianForest {
        char[][] ar;
        int n;
        int m;
        long[][] dis;

        public boolean isvalid(int x, int y) {
            return x >= 0 && x < n && y >= 0 && y < m && ar[x][y] != 'T';
        }

        private int dijkstra(int x, int y) {
            int tt = 0;
            PriorityQueue<pair> pq = new PriorityQueue<pair>();
            pq.add(new pair(x, y, 0));
            for (int i = 0; i < n; i++) Arrays.fill(dis[i], 1000000000);
            boolean[][] vis = new boolean[n][m];
            while (pq.size() > 0) {
                tt++;
                pair pp = pq.poll();
                if (vis[pp.x][pp.y]) continue;
                vis[pp.x][pp.y] = true;
                dis[pp.x][pp.y] = pp.dis;
                if (isvalid(pp.x + 1, pp.y) && !vis[pp.x + 1][pp.y])
                    pq.add(new pair(pp.x + 1, pp.y, pp.dis + 1));
                if (isvalid(pp.x - 1, pp.y) && !vis[pp.x - 1][pp.y])
                    pq.add(new pair(pp.x - 1, pp.y, pp.dis + 1));
                if (isvalid(pp.x, pp.y + 1) && !vis[pp.x][pp.y + 1])
                    pq.add(new pair(pp.x, pp.y + 1, pp.dis + 1));
                if (isvalid(pp.x, pp.y - 1) && !vis[pp.x][pp.y - 1])
                    pq.add(new pair(pp.x, pp.y - 1, pp.dis + 1));
            }
            return tt;
        }

        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            n = in.scanInt();
            m = in.scanInt();
            ar = new char[n][];
            dis = new long[n][m];
            for (int i = 0; i < n; i++) ar[i] = in.scanString().toCharArray();
            int xE = -1;
            int xS = -1;
            int yE = -1;
            int yS = -1;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (ar[i][j] == 'E') {
                        xE = i;
                        yE = j;
                    } else if (ar[i][j] == 'S') {
                        xS = i;
                        yS = j;
                    }
                }
            }
            int tt = dijkstra(xE, yE);
            long ans = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (Character.isDigit(ar[i][j]) && dis[i][j] <= dis[xS][yS]) ans += (ar[i][j] - '0');
                }
            }
            out.println(ans);

        }

        class pair implements Comparable<pair> {
            int x;
            int y;
            int dis;

            public int compareTo(pair o) {
                return this.dis - o.dis;
            }

            public pair(int x, int y, int dis) {
                this.x = x;
                this.y = y;
                this.dis = dis;
