                    }
                }
            }
            if (j > 0) {
                if (a[i][j - 1] != 'T') {
                    if(used[i][j - 1] == 0){
                        q.add(i * m + j - 1);
                        used[i][j - 1] = used[i][j] + 1;
                    }
                }
            }
            if (j < m - 1) {
                if (a[i][j + 1] != 'T') {
                    if(used[i][j + 1] == 0){
                        q.add(i * m + j + 1);
                        used[i][j + 1] = used[i][j] + 1;
