	static void solve() throws IOException {
		int r = nextInt(), c = nextInt();
		char[][] grid = new char[r][];
		for (int i = 0; i < r; i++) {
			grid[i] = nextToken().toCharArray();
		}

		int[][] distance = new int[r][c];
		for (int i = 0; i < r; i++) {
			Arrays.fill(distance[i], -1);
		}
		int[] queue = new int[r * c];
		int qh = 0, qt = 0;
		for (int i = 0; i < r; i++) {
			for (int j = 0; j < c; j++) {
				if (grid[i][j] == 'E') {
					queue[qt++] = (i << 16) + j;
					distance[i][j] = 0;
				}
			}
		}
		while (qh < qt) {
			int u = queue[qh++];
			int x = u >> 16, y = u & 0xFFFF;
			for (int dir = 0; dir < 4; dir++) {
				int nx = x + DX[dir];
				int ny = y + DY[dir];
				if (nx < 0 || ny < 0 || nx >= r || ny >= c
						|| grid[nx][ny] == 'T') {
					continue;
				}
				if (distance[nx][ny] < 0) {
					distance[nx][ny] = distance[x][y] + 1;
					queue[qt++] = (nx << 16) + ny;
				}
			}
		}

		int ourDistance = 0;
		for (int i = 0; i < r; i++) {
			for (int j = 0; j < c; j++) {
				if (grid[i][j] == 'S') {
					ourDistance = distance[i][j];
				}
			}
		}

		int fight = 0;
		for (int i = 0; i < r; i++) {
			for (int j = 0; j < c; j++) {
				if (distance[i][j] >= 0 && distance[i][j] <= ourDistance) {
					if (grid[i][j] >= '0' && grid[i][j] <= '9') {
						 fight += grid[i][j] - '0';
					}
				}
			}
		}

		out.println(fight);
	}

