            for (int dr = -1; dr <= 1; ++dr)
                for (int dc = -1; dc <= 1; ++dc)
                    if (Math.abs(dr) + Math.abs(dc) == 1) {
                        int nr = r + dr;
                        int nc = c + dc;
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && map[nr].charAt(nc) != 'T' && d[nr][nc] < 0) {
                            d[nr][nc] = d[r][c] + 1;
                            qr[qh] = nr;
                            qc[qh] = nc;
                            ++qh;
                        }
                    }
        }
        int md = 0;
        for (int r = 0; r < rows; ++r)
