		Scanner in = new Scanner(System.in);
		rows = in.nextInt();
		columns = in.nextInt();
		in.nextLine();
		char[][] forest = new char[rows][columns];

		int exitX = -1, exitY = -1, startX = -1, startY = -1;

		for(int r = 0; r < rows; r++) {
			forest[r] = in.nextLine().toCharArray();
			for(int i = 0; i < forest[r].length; i++) {
				if(forest[r][i] == 'S') { 
					startX = r;
					startY = i;
				}
				if(forest[r][i] == 'E') {
					exitX = r;
					exitY = i;
				}
			}
		}

		int[][] temp = bfs(forest, startX, startY);
		int exit_Dist = temp[exitX][exitY];
		int[][] distance = bfs(forest, exitX, exitY);


		int minBattles = 0;
		for(int x = 0; x < rows; x++) {
			for(int y = 0; y < columns; y++) {
				char forest_element = forest[x][y];
				int dist_element = distance[x][y];
				if(forest_element != 'S' && forest_element != 'E' && dist_element <= exit_Dist && dist_element >= 0) {
					minBattles += (forest_element - '0');
				}
			}
		}
		System.out.println(minBattles);
	}

	public static int[][] bfs(char[][] forest, int sX, int sY) {
		LinkedList<Integer> queue = new LinkedList<Integer>();
		int[][] distance = new int[rows][columns];

		for(int i = 0;i < distance.length; i++) {
			Arrays.fill(distance[i], -1);
		}

		distance[sX][sY] = 0;
		queue.add(sX);
		queue.add(sY);

		while(!queue.isEmpty()) {
				int x = queue.remove();
				int y = queue.remove();
				for(int k = 0; k < dx.length; k++) {
					int xDx = dx[k] + x;
					int yDy = dy[k] + y;
					if(xDx >= 0 && xDx < rows && yDy >= 0 && yDy < columns && distance[xDx][yDy] == -1 && forest[xDx][yDy] != 'T') {
						distance[xDx][yDy] = distance[x][y] + 1;
						queue.add(xDx);
						queue.add(yDy);
					}  
				}
		}
		return distance;
	}
}

