public class biridianForest {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int rows = sc.nextInt();
		int columns = sc.nextInt();
		int battles = 0;
		int requiredstep = 0;
		char[][] map = new char[rows][columns];
		for (int i = 0; i < rows; i++) {
			String aString = sc.next();
			map[i] = aString.toCharArray();
		}
		int[][] step = new int[rows][columns];
		for (int i = 0; i < rows; i++) {
			Arrays.fill(step[i], Integer.MAX_VALUE);
		}
		LinkedList<Integer> xQueue = new LinkedList<Integer>();
		LinkedList<Integer> yQueue = new LinkedList<Integer>();
		outer_loop: for (int i = 0; i < rows; i++) {
			for (int j = 0; j < columns; j++) {
				if (map[i][j] == 'E') {
					step[i][j] = 0;
					xQueue.add(j);
					yQueue.add(i);
					break outer_loop;
				}
			}
		}
		while (!xQueue.isEmpty() && !yQueue.isEmpty()) {
			int curx = xQueue.poll();
			int cury = yQueue.poll();
			if (curx > 0 && step[cury][curx - 1] > step[cury][curx] + 1) {
				if (map[cury][curx - 1] != 'T') {
					step[cury][curx - 1] = step[cury][curx] + 1;
					xQueue.add(curx - 1);
					yQueue.add(cury);
				}
			}
			if (curx < columns - 1 && step[cury][curx + 1] > step[cury][curx] + 1) {
				if (map[cury][curx + 1] != 'T') {
					step[cury][curx + 1] = step[cury][curx] + 1;
					xQueue.add(curx + 1);
					yQueue.add(cury);
				}
			}
			if (cury > 0 && step[cury - 1][curx] > step[cury][curx] + 1) {
				if (map[cury - 1][curx] != 'T') {
					step[cury - 1][curx] = step[cury][curx] + 1;
					xQueue.add(curx);
					yQueue.add(cury - 1);
				}
			}
			if (cury < rows - 1 && step[cury + 1][curx] > step[cury][curx] + 1) {
				if (map[cury + 1][curx] != 'T') {
					step[cury + 1][curx] = step[cury][curx] + 1;
					xQueue.add(curx);
					yQueue.add(cury + 1);
				}
			}
		}
		for (int i = 0; i < rows; i++) {
			for (int j = 0; j < columns; j++) {
				if (map[i][j] == 'S') {
					requiredstep = step[i][j];
				}
			}
		}
		for (int i = 0; i < rows; i++) {
			for (int j = 0; j < columns; j++) {
				if (map[i][j] > 48 && map[i][j] < 58 && step[i][j] <= requiredstep) {
					battles += map[i][j] - '0';
				}
			}
		}
		System.out.print(battles);
	}
}

import java.util.*;
import java.io.*;

public class CF330D{ 
  public static int R, C, mat[][], visited[][];
  public static void main(String[] args)throws Exception {
    InputReader in = new InputReader(System.in);
    PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));
    R = in.nextInt(); C = in.nextInt();
    mat = new int[R][C];
    ArrayList<Pair> list = new ArrayList<Pair>();
    Pair s = null, e = null;
    for(int i = 0; i < R; i++){
      String str = in.next();
      for(int j = 0; j < C; j++){
        mat[i][j] = str.charAt(j);
        if(mat[i][j] == 'S') s = new Pair(i, j, 0);
        else if (mat[i][j] == 'E') e = new Pair(i, j, -1);
        else if( mat[i][j] != 'T') list.add(new Pair(i,j, (mat[i][j]-'0')));
      }
    }

    bfs(e);

    int moves = visited[s.x][s.y] , size = list.size();

    long ans = 0;

    for(int i = 0; i < size; i++){
      int x = visited[list.get(i).x][list.get(i).y];
      if(x != -1 && x <= moves){
        ans += (long) list.get(i).n;
      }
    }

    pw.println(ans);
    pw.close();
  }

  public static boolean isValid(int r, int c){
    return r >= 0 && r < R && c >= 0 && c < C && mat[r][c] != 'T';
  }

  public static void bfs(Pair start){
    int dirx[] = {1,  -1,   0,    0};
    int diry[] = {0,   0,  -1,    1};
    visited = new int[R][C];
    for(int i = 0; i < R; i++) Arrays.fill(visited[i], -1);
    Queue<Pair> q = new LinkedList<Pair>();
    q.add(start);
    visited[start.x][start.y] = 0;
    while(!q.isEmpty()){
      Pair pop = q.poll();
      if(mat[pop.x][pop.y] == '*') continue;
      for(int i = 0; i < 4; i++){
        int x = pop.x + dirx[i],  y = pop.y + diry[i];
        if(isValid(x, y) && visited[x][y] == -1){
          visited[x][y] = visited[pop.x][pop.y] + 1;
          q.add(new Pair(x,y,0));
        }
      }
    }
  }

  static class Pair{
    public int x, y, n;
    public Pair(int xx, int yy, int nn){
      x = xx; y = yy; n = nn;
    }
  }



  static class InputReader {
    public BufferedReader reader;
    public StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
      reader = new BufferedReader(new InputStreamReader(stream));
      tokenizer = null;
    }

    public String next() {

      try {
        while (tokenizer == null || !tokenizer.hasMoreTokens())
          tokenizer = new StringTokenizer(reader.readLine());
      } catch (IOException e) {
        return null;
      }

      return tokenizer.nextToken();
    }

    public String nextLine() {
      String line = null;
      try {
        tokenizer = null;
        line =  reader.readLine();
      } catch (IOException e) {
        throw new RuntimeException(e);
      }
      return line;
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public long nextLong() {
      return Long.parseLong(next());
    }
    public boolean hasNext(){
      try {
        while (tokenizer == null || !tokenizer.hasMoreTokens())
          tokenizer = new StringTokenizer(reader.readLine());
      } 
      catch (Exception e) {
        return false;
      }

    return true; 

    }
  }
}

