class TaskD {

    private int rowCounter, columnCounter, startX, startY, finishX, finishY, size, next;
    private int[][] forest, distance;
    private boolean[][] used;
    private int[] queueX, queueY;

    private static final int[] dx = {-1, 0, 1, 0};
    private static final int[] dy = {0, 1, 0, -1};

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        rowCounter = in.nextInt();
        columnCounter = in.nextInt();
        forest = new int[rowCounter][columnCounter];
        distance = new int[rowCounter][columnCounter];
        used = new boolean[rowCounter][columnCounter];
        queueX = new int[rowCounter * columnCounter];
        queueY = new int[rowCounter * columnCounter];
        for (int i = 0; i < rowCounter; i++) {
            String current = in.next();
            for (int j = 0; j < columnCounter; j++) {
                if (current.charAt(j) == 'T')
                    forest[i][j] = -1;
                else if (current.charAt(j) == 'S') {
                    startX = i;
                    startY = j;
                } else if (current.charAt(j) == 'E') {
                    finishX = i;
                    finishY = j;
                } else
                    forest[i][j] = current.charAt(j) - '0';
            }
        }
        for (int i = 0; i < rowCounter; i++) {
            Arrays.fill(distance[i], -1);
        }
        distance[finishX][finishY] = 0;
        queueX[size] = finishX;
        queueY[size] = finishY;
        size++;
        used[finishX][finishY] = true;
        while (next < size) {
            for (int d = 0; d < 4; d++) {
                int x = queueX[next] + dx[d];
                int y = queueY[next] + dy[d];
                if (isValid(x, y) && !used[x][y]) {
                    used[x][y] = true;
                    distance[x][y] = distance[queueX[next]][queueY[next]] + 1;
                    queueX[size] = x;
                    queueY[size] = y;
                    size++;
                }
            }
            next++;
        }
        int maximum = distance[startX][startY];
        int answer = 0;
        for (int i = 0; i < rowCounter; i++) {
            for (int j = 0; j < columnCounter; j++) {
                if (distance[i][j] != -1 && distance[i][j] <= maximum)
                    answer += forest[i][j];
            }
        }
        out.println(answer);
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && x < rowCounter && y >= 0 && y < columnCounter && forest[x][y] != -1;
    }

}

