		Pos(int i, int j) {
			this.i = i;
			this.j = j;
		}
	}

	static boolean valid(int i, int j) {
		return i >= 0 && i < n && j >= 0 && j < m && g[i][j] != 'T';
	}

	static int n, m;
	static char[][] g;
	static int[] dx = { 1, -1, 0, 0 }, dy = { 0, 0, 1, -1 };

	static int bfs() {
		Pos start = null;
		loop: for (int i = 0; i < n; i++)
			for (int j = 0; j < m; j++)
				if (g[i][j] == 'E') {
					start = new Pos(i, j);
					break loop;
				}
		int inf = (int) 1e9;
		int[][] d = new int[n][m];
		for (int i = 0; i < n; i++)
			Arrays.fill(d[i], inf);
		d[start.i][start.j] = 0;
		Queue<Pos> q = new LinkedList<>();
		q.add(start);
		int dS = -1;
		while (!q.isEmpty()) {
			Pos p = q.remove();
			if (g[p.i][p.j] == 'S')
				dS = d[p.i][p.j];
			for (int x = 0; x < 4; x++) {
				int newI = p.i + dx[x], newJ = p.j + dy[x];
				if (valid(newI, newJ) && d[newI][newJ] == inf) {
					d[newI][newJ] = 1 + d[p.i][p.j];
					q.add(new Pos(newI, newJ));
				}
			}
		}

		int ans = 0;
		for (int i = 0; i < n; i++)
			for (int j = 0; j < m; j++)
				if (Character.isDigit(g[i][j]) && d[i][j] <= dS)
					ans += g[i][j] - '0';

		return ans;
	}

