        out.close();
    }

    static void bfs(Point S) {
        dist = new int[n][m];
        for (int[] a : dist)
            Arrays.fill(a, INF);
        dist[S.x][S.y] = 0;
        Queue<Point> q = new LinkedList<>();
        q.add(S);
        while (!q.isEmpty()) {
            Point cur = q.remove();
            for (int k = 0; k < 4; k++) {
                int x = cur.x + dx[k];
                int y = cur.y + dy[k];
                if (!valid(x, y)) continue;
                dist[x][y] = 1 + dist[cur.x][cur.y];
                q.add(new Point(x, y));
            }
        }
    }

    static boolean valid(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m && grid[x][y] != 'T' && dist[x][y] == INF;
    }

    static class Point {
        int x, y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

