	 static class InputReader {

		private InputStream stream;
		private byte[] buf = new byte[8192];
		private int curChar;
		private int snumChars;
		private SpaceCharFilter filter;

		public InputReader(InputStream stream) {
			this.stream = stream;
		}

		public int snext() {
			if (snumChars == -1)
				throw new InputMismatchException();
			if (curChar >= snumChars) {
				curChar = 0;
				try {
					snumChars = stream.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (snumChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		public int nextInt() {
			int c = snext();
			while (isSpaceChar(c))
				c = snext();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = snext();
			}

			int res = 0;

			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = snext();
			} while (!isSpaceChar(c));

			return res * sgn;
		}

		public long nextLong() {
			int c = snext();
			while (isSpaceChar(c))
				c = snext();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = snext();
			}

			long res = 0;

			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = snext();
			} while (!isSpaceChar(c));

			return res * sgn;
		}

		public String readString() {
			int c = snext();
			while (isSpaceChar(c))
				c = snext();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = snext();
			} while (!isSpaceChar(c));
			return res.toString();
		}

		public boolean isSpaceChar(int c) {
			if (filter != null)
				return filter.isSpaceChar(c);
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		public interface SpaceCharFilter {
			public boolean isSpaceChar(int ch);
		}
	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;
import java.util.Queue;
import java.util.LinkedList;

public class biridianForest {


    static class FastReader
    {
        BufferedReader br;
        StringTokenizer st;

        public FastReader()
        {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }

    private static boolean validateVertex (int[][] arr, int row, int col) {
        return (row >= 0) && (col >= 0) && (row < arr.length) && (col < arr[0].length);
    }


    public static void main(String[] args) {
        FastReader s = new FastReader();
        int r = s.nextInt();
        int c = s.nextInt();

        int[][] arr = new int[r][c];

        int er = 0;
        int ec = 0;

        int sr = 0;
        int sc = 0;

        for (int i = 0; i < r; i++) {
            String str = s.nextLine();
            for (int j = 0; j < c; j++) {
                if (str.charAt(j) == 'T') {
                    arr[i][j] = -1;
                }
                else if (str.charAt(j) == 'E') {
                    er = i;
                    ec = j;
                    arr[i][j] = 0;
                }

                else if (str.charAt(j) == 'S') {
                    sr = i;
                    sc = j;
                    arr[i][j] = -2;

                }

                else arr[i][j] = Character.getNumericValue(str.charAt(j));
            }
        }

        int[][] min = new int[r][c];
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                min[i][j] = Integer.MAX_VALUE;
            }
        }

        min[er][ec] = 0;
        boolean[][] visited = new boolean[r][c];

        Queue<Integer> rowQ = new LinkedList<Integer>();
        Queue<Integer> colQ = new LinkedList<Integer>();

        ((LinkedList<Integer>) rowQ).add(er);
        ((LinkedList<Integer>) colQ).add(ec);
        visited[er][ec] = true;

        while (!rowQ.isEmpty()) {

            int row = rowQ.remove();
            int col = colQ.remove();

            if (validateVertex(arr, row + 1, col) && !visited[row + 1][col] && arr[row + 1][col] != -1) {
                rowQ.add(row + 1);
                colQ.add(col);
                min[row + 1][col] = min[row][col] + 1;
                visited[row + 1][col] = true;
            }

            if (validateVertex(arr, row - 1, col) && !visited[row - 1][col] && arr[row - 1][col] != -1) {
                rowQ.add(row - 1);
                colQ.add(col);
                min[row - 1][col] = min[row][col] + 1;
                visited[row - 1][col] = true;
            }

            if (validateVertex(arr, row, col + 1) && !visited[row][col + 1] && arr[row][col + 1] != -1) {
                rowQ.add(row);
                colQ.add(col + 1);
                min[row][col + 1] = min[row][col] + 1;
                visited[row][col + 1] = true;
            }

            if (validateVertex(arr, row, col - 1) && !visited[row][col - 1] && arr[row][col - 1] != -1) {
                rowQ.add(row);
                colQ.add(col - 1);
                min[row][col - 1] = min[row][col] + 1;
                visited[row][col - 1] = true;
            }



        }



        int battle = 0;

        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (arr[i][j] != -1 && arr[i][j] != -2) {
                    if (min[i][j] <= min[sr][sc]) {
                        battle += arr[i][j];
                    }
                }
            }
        }

        System.out.print(battle);






    }
}

