		if (cX - cN > 1 || cX - cN < 0)
			out.println("illegal");
		else if (getCntWin() == 0) {
			if (moves == 9)
				out.println("draw");
			else
				out.println(cX > cN ? "second" : "first");
		} else {
			boolean ok = false;
			for (int i = 0; i < 3; i++)
				for (int j = 0; j < 3; j++)
					if (q[i][j] != '.') {
						char t = q[i][j];
						q[i][j] = '.';
						int newCntWin = getCntWin();
