							ok = true;
						q[i][j] = t;
					}
			if (!ok)
				out.println("illegal");
			else
				out.println(cX > cN ? "the first player won" : "the second player won");
		}
		in.close();
		out.close();
	}
	private int getCntWin() {
		int cntWin = 0;
		for (int i = 0; i < 3; i++) {
			if (isTriple(i, 0, 0, 1))
				cntWin++;
			if (isTriple(0, i, 1, 0))
				cntWin++;
		}
		if (isTriple(0, 0, 1, 1))
			cntWin++;
		if (isTriple(0, 2, 1, -1))
			cntWin++;
		return cntWin;
	}

	private boolean isTriple(int x, int y, int dx, int dy) {
		if (q[x][y] == '.')
			return false;
		return q[x][y] == q[x + dx][y + dy] && q[x + dx][y + dy] == q[x + 2 * dx][y + 2 * dy];
	}
