public class Main
{
  public static void main (String args[]) throws Exception
  {

    Scanner cin = new Scanner(System.in);
    String a = cin.next();
    String b = cin.next();
    String c = cin.next();
    squares(a,b,c);
  }

  public static void squares(String a, String b, String c){
	String[][] grid = {scanning(a),scanning(b),scanning(c)};
	int[] count = count(grid);
	if(count[1] > count[0]){
		System.out.println("illegal");
	}
	else if(count[0] - count[1] >1){
		System.out.println("illegal");
	}
	else if((checkWin(grid,"X") && count[1]==count[0])
			|| (checkWin(grid,"0") && count[0]>count[1])){
		System.out.println("illegal");
	}
	else if(checkWin(grid,"X")){
		System.out.println("the first player won");
	}
	else if(checkWin(grid,"0")){
		System.out.println("the second player won");
	}
	else if(count[2] == 0){
		System.out.println("draw");
	}
	else if(count[0]==count[1]){
		System.out.println("first");
	}
	else{
		System.out.println("second");
	}
  }

  public static Boolean checkWin(String[][] grid, String n){
	  if(	(n.equals(grid[0][0]) && n.equals(grid[0][1]) && n.equals(grid[0][2]))
		  || (n.equals(grid[1][0]) && n.equals(grid[1][1]) && n.equals(grid[1][2]))
		  || (n.equals(grid[2][0]) && n.equals(grid[2][1]) && n.equals(grid[2][2]))
		  || (n.equals(grid[0][0]) && n.equals(grid[1][0]) && n.equals(grid[2][0]))
		  || (n.equals(grid[0][1]) && n.equals(grid[1][1]) && n.equals(grid[2][1]))
		  || (n.equals(grid[0][2]) && n.equals(grid[1][2]) && n.equals(grid[2][2]))
		  || (n.equals(grid[0][0]) && n.equals(grid[1][1]) && n.equals(grid[2][2]))
		  || (n.equals(grid[0][2]) && n.equals(grid[1][1]) && n.equals(grid[2][0]))
			  ){
		  return true;
	  }
	  return false;


  }

  public static String[] scanning(String n){
	  String[] arr = n.split("");
	  return arr;
  }

  public static int[] count(String[][] grid){
	  int x = 0;
	  int o = 0;
	  int period = 0;
	  for(int i=0;i<3;i++){
		  for(int j=0;j<3;j++){
			  if(grid[i][j].equals("X")){
				  x++;
			  }
			  else if(grid[i][j].equals("0")){
				  o++;
			  }
			  else{
				  period++;
			  }
		  }
	  }
	  int result[] =  {x,o,period};
	  return result;

  }


