        for (int i = 0; i < firstLine.length(); i++) {
            if (firstLine.charAt(i) == 'X')
                crossCounter++;
            else if (firstLine.charAt(i) == '0')
                noughtCounter++;
            else if (firstLine.charAt(i) == '.')
