            if (thirdLine.charAt(i) == 'X')
                crossCounter++;
            else if (thirdLine.charAt(i) == '0')
                noughtCounter++;
            else if (thirdLine.charAt(i) == '.')
                dotCounter++;
        }

        if (crossCounter - noughtCounter > 1)
            out.print("illegal");
        else if (noughtCounter - crossCounter > 0)
            out.print("illegal");
        else if ((firstLine.charAt(0) == 'X' && firstLine.charAt(1) == 'X' && firstLine.charAt(2) == 'X') ||
