                (firstLine.charAt(2) == 'X' && secondLine.charAt(2) == 'X' && thirdLine.charAt(2) == 'X') ||
                (firstLine.charAt(0) == 'X' && secondLine.charAt(1) == 'X' && thirdLine.charAt(2) == 'X') ||
                (firstLine.charAt(2) == 'X' && secondLine.charAt(1) == 'X' && thirdLine.charAt(0) == 'X')) {

            if (crossCounter - noughtCounter == 1)
