public class TicTacToe {

    public static void main(String[] args) throws IOException {
        BufferedReader rdr = new BufferedReader (new InputStreamReader(System.in));
        char [][] game = new char [3][3];
        int countX = 0;
        int countO = 0;
        boolean full = true;
        for(int i = 0; i < 3; i++)
            game[i] = rdr.readLine().toCharArray();
        for(int i = 0; i < 3; i++)
            for(int j = 0; j < 3; j++) {
                if(game[i][j] == 'X')
                    countX++;
                if(game[i][j] == '0')
                    countO++;
                if(game[i][j] == '.')
                    full = false;
            }
        if((isWin('X',game) && isWin('0',game)) || countO > countX || countX - countO > 1) {
            System.out.println("illegal");
        }
        else if (isWin('X',game) && countO == countX) {
            System.out.println("illegal");
        }
        else if(isWin('0',game) && countX > countO) {
            System.out.println("illegal");
        }
        else if (isWin('X',game)) {
            System.out.println("the first player won");
        }
        else if (isWin('0',game)) {
            System.out.println("the second player won");
        }
        else if(countO == countX && !full) {
            System.out.println("first");
        }
        else if (!full) {
            System.out.println("second");
        }
        else if (full) {
            System.out.println("draw");
        }
        else {
            System.out.println("illegal");
        }
    }
    public static boolean isWin (char x , char [][] game) {
        if(game[0][0] == x && game[0][1] == x && game[0][2] == x)
            return true;
        if(game[0][0] == x && game[1][0] == x && game[2][0] == x)
            return true;
        if(game[0][2] == x && game[1][2] == x && game[2][2] == x)
            return true;
        if(game[2][0] == x && game[2][1] == x && game[2][2] == x)
            return true;
