class Grid {
	private char[] tiles;

	public Grid() {
		tiles = new char[9];
	}

	public void add(char t, int x, int y) {
		tiles[pos(x, y)] = t;
	}

	public int pos(int x, int y) {
		return (x * 3) + y;
	}

	public char at(int i) {
		return tiles[i];
	}
}

