        {
            for(int j = 0; j < krenoliki[i].length; j++)
            {
                if(krenoliki[i][j].compareTo("x") == 0) xCount++;
                else if(krenoliki[i][j].compareTo("0") == 0) oCount++;
                else if(krenoliki[i][j].compareTo(".") == 0) nullCount++;
            }
        }

        if(Math.abs(xCount - oCount) > 1 || oCount > xCount)
        {
            trace("illegal");
            return;
        }

        defineWinner();
    }

    private void defineWinner()
    {
        boolean firstWon = false;
        boolean secondWon = false;

        for(int i = 0; i < krenoliki.length; i++)
        {
            if(krenoliki[i][0].compareTo(krenoliki[i][1]) == 0 && krenoliki[i][0].compareTo(krenoliki[i][2]) == 0)
            {
                if(krenoliki[i][0].compareTo("x") == 0) { if(xCount > oCount) firstWon = true; else { trace("illegal"); return; } }
                else if(krenoliki[i][0].compareTo("0") == 0) { if(xCount == oCount) secondWon = true; else { trace("illegal"); return; } }
            }
            else if(krenoliki[0][i].compareTo(krenoliki[1][i]) == 0 && krenoliki[0][i].compareTo(krenoliki[2][i]) == 0)
            {
                if(krenoliki[0][i].compareTo("x") == 0) { if(xCount > oCount) firstWon = true; else { trace("illegal"); return; } }
                else if(krenoliki[0][i].compareTo("0") == 0) { if(xCount == oCount) secondWon = true; else { trace("illegal"); return; } }
            }
        }

        if(krenoliki[0][0].compareTo(krenoliki[1][1]) == 0 && krenoliki[0][0].compareTo(krenoliki[2][2]) == 0)
        {
            if(krenoliki[0][0].compareTo("x") == 0) { if(xCount > oCount) firstWon = true; else { trace("illegal"); return; } }
            else if(krenoliki[0][0].compareTo("0") == 0) { if(xCount == oCount) secondWon = true; else { trace("illegal"); return; } }
        }
        else if(krenoliki[2][0].compareTo(krenoliki[1][1]) == 0 && krenoliki[2][0].compareTo(krenoliki[0][2]) == 0)
        {
            if(krenoliki[2][0].compareTo("x") == 0) { if(xCount > oCount) firstWon = true; else { trace("illegal"); return; } }
            else if(krenoliki[2][0].compareTo("0") == 0) { if(xCount == oCount) secondWon = true; else { trace("illegal"); return; } }
        }

        if(firstWon && secondWon)
        {
            trace("illegal");
            return;
        }
        else if(firstWon && !secondWon)
        {
            trace("the first player won");
            return;
        }
        else if(!firstWon && secondWon)
        {
            trace("the second player won");
            return;
        }

        findMove();
    }

    private void findMove()
    {
        if(xCount - oCount == -1 && nullCount > 0 || xCount == oCount) trace("first");
        else if(xCount - oCount == 1 && nullCount > 0) trace("second");
        else if(nullCount == 0) trace("draw");
    }

