			}

			if (countHorizontalWins > 1) return false;


			for (int i=0; i<3; i++) {

				hasWon = true;

				for (int j=0; j<3; j++) {
					if (matrix[j][i] != '0') hasWon = false;
				}

				if (hasWon) {
					countVerticalWins++;
					hasWon = false;
				} 
			}

			if (countVerticalWins > 1) return false;

			if (countHorizontalWins == 1 && countVerticalWins == 1) {
				return true;
			}

			countWins = countHorizontalWins + countVerticalWins;
			countWinsBeforeDiagonal = countWins;


			if (matrix[0][0] == '0' && matrix[0][0] == matrix[1][1] && matrix[1][1] == matrix[2][2]) {
				countDiagonal++;
				countWins++;
			}
			if (matrix[2][0] == '0' && matrix[2][0] == matrix[1][1] && matrix[1][1] == matrix[0][2]) {
				countDiagonal++;
				countWins++;
			}
			if (countDiagonal == 2 && countWinsBeforeDiagonal == 2) return true;
			if (countDiagonal == 1 && countWinsBeforeDiagonal == 1) return true;
			if (countDiagonal == 2 && countWins == 2) return true;
			if (countDiagonal == 1 && countWins == 1) return true;
			if (countWins > 1) return false;
			else if (countWins == 1) return true;
			else return false;
		}
		return false;
	}
