public class TicTacToe {
	public static void main(String[] args) {
		Scanner input = new Scanner(System.in);
		String row1 = input.next();
		String row2 = input.next();
		String row3 = input.next();

		int countX = countCharOccurance(row1, 'X')
				+ countCharOccurance(row2, 'X') + countCharOccurance(row3, 'X');
		int count0 = countCharOccurance(row1, '0')
				+ countCharOccurance(row2, '0') + countCharOccurance(row3, '0');
		if (count0 > countX || countX == count0 + 2) {
			System.out.println("illegal");
			return;
		}

		boolean xWin = false;
		if (countX > 2) xWin = checkWin(row1, row2, row3, 'X');
		boolean OWin = false;
		if (count0 > 2)
			OWin = checkWin(row1, row2, row3, '0');
		if (xWin && OWin) {
			System.out.println("illegal");
			return;
		}

		if (xWin && countX == count0 + 1) {
			System.out.println("the first player won");
			return;
		} else if (OWin && countX == count0) {
			System.out.println("the second player won");
			return;
		} else if (OWin || xWin) {
			System.out.println("illegal");
			return;
		}

		if (countX == count0) {
			System.out.println("first");
			return;
		} else if (countX == count0 + 1 && countX + count0 != 9) {
			System.out.println("second");
			return;
		} else if (countX == 5 && count0 == 4) {
			System.out.println("draw");
			return;
		}

		System.out.println("illegal");
	}

	private static boolean checkWin(String row1, String row2, String row3,
			char c) {
		if (row1.charAt(0) == c && row1.charAt(1) == c && row1.charAt(2) == c) {
			return true;
		} else if (row2.charAt(0) == c && row2.charAt(1) == c
				&& row2.charAt(2) == c) {
			return true;
		} else if (row3.charAt(0) == c && row3.charAt(1) == c
				&& row3.charAt(2) == c) {
			return true;
		} else if (row1.charAt(0) == c && row2.charAt(0) == c
				&& row3.charAt(0) == c) {
			return true;
		} else if (row1.charAt(1) == c && row2.charAt(1) == c
				&& row3.charAt(1) == c) {
			return true;
		} else if (row1.charAt(2) == c && row2.charAt(2) == c
				&& row3.charAt(2) == c) {
			return true;
		} else if (row1.charAt(0) == c && row2.charAt(1) == c
				&& row3.charAt(2) == c) {
			return true;
		} else if (row1.charAt(2) == c && row2.charAt(1) == c
				&& row3.charAt(0) == c) {
			return true;
		} else {
			return false;
		}
	}

	private static int countCharOccurance(String string, char c) {
		int count = 0;
		for (int i = 0; i < string.length(); i++) {
			if (string.charAt(i) == c)
				count++;
		}
		return count;
	}
}

