import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class C implements Runnable {
    public static void main(String[] args) {
        new Thread(new C()).start();
    }

    static final char CROSS = 'X';
    static final char ZERO = '0';

    public void run() {
        try {
            solve();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    BufferedReader br;
    StringTokenizer st = new StringTokenizer("");

    private void solve() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        char[][] field = new char[3][3];
        for (int i = 0; i < 3; i++) {
            String line = nextToken();
            for (int j = 0; j < 3; j++) {
                field[i][j] = line.charAt(j);
            }
        }
        br.close();
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(subSolve(field));
        pw.close();
    }

    String subSolve(char[][] field) {
        final int crossMoves = count(field, CROSS);
        final int zeroMoves = count(field, ZERO);
        if (crossMoves < zeroMoves || crossMoves > zeroMoves + 1) {
            return "illegal";
        }
        boolean crossWin = isWin(field, CROSS);
        boolean zeroWin = isWin(field, ZERO);
        if (crossWin && zeroWin) {
            return "illegal";
        }
        if (crossWin && crossMoves == zeroMoves) {
            return "illegal";
        }
        if (crossWin) {
            return "the first player won";
        }
        if (zeroWin && crossMoves == zeroMoves + 1) {
            return "illegal";
        }
        if (zeroWin) {
            return "the second player won";
        }
        if (crossMoves + zeroMoves == 9) {
            return "draw";
        }
        if (crossMoves == zeroMoves) {
            return "first";
        } else {
            return "second";
        }
    }

    int count(char[][] field, char ch) {
        int cnt = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (field[i][j] == ch) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    boolean isWin(char[][] field, char ch) {
        return isWin(field, ch, 1, 0) || isWin(field, ch, 0, 1) || isWin(field, ch, 1, 1) || isWin(field, ch, 1, -1);
    }

    boolean isWin(char[][] field, char ch, int di, int dj) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (isWin(field, ch, i, j, di, dj)) {
                    return true;
                }
            }
        }
        return false;
    }

    boolean isWin(char[][] field, char ch, int i0, int j0, int di, int dj) {
        int cnt = 0;
        int i = i0, j = j0;
        while (i >=0 && i < 3 && j >=0 && j < 3) {
            if (field[i][j] == ch) {
                cnt++;
            }
            i += di;
            j += dj;
        }
        return cnt == 3;
    }

    String nextToken() throws IOException {
        while (!st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }
}

