public static char check(char[][] ch)
{
	String ans = "";
	for(int i=0;i<3;i++)
	{
		if(ch[i][0]!='.' && ch[i][1]==ch[i][0] && ch[i][2]==ch[i][0]) ans = ans+ch[i][0];
		if(ch[0][i]!='.' && ch[1][i]==ch[0][i] && ch[2][i]==ch[1][i]) ans = ans+ch[0][i];
	}
	if(ch[0][0]!='.' && ch[1][1]==ch[0][0] && ch[2][2]==ch[1][1]) ans = ans + ch[0][0];
	if(ch[1][1]!='.' && ch[2][0]==ch[1][1] && ch[0][2]==ch[1][1]) ans = ans + ch[1][1];

	if(ans.length()==1) return ans.charAt(0);
	else if(ans.equals("XX")) return ans.charAt(0);
	else if(ans.length()>1) return '2';
	else return '1';

}
}

