	static boolean win(char t) {
		boolean ret = false;

		for(int i = 0; i < 3; ++i) {
			boolean x = true;
			for(int j = 0; j < 3; ++j) {
				char c = grid[i].charAt(j);
				if(c != t) x = false;
			}
			if(x) ret = true;
		}

		for(int i = 0; i < 3; ++i) {
			boolean x = true;
			for(int j = 0; j < 3; ++j) {
				char c = grid[j].charAt(i);
				if(c != t) x = false;
			}
			if(x) ret = true;
		}		

		if(grid[0].charAt(0) == t && grid[1].charAt(1) == t && grid[2].charAt(2) == t) ret = true; 
		if(grid[0].charAt(2) == t && grid[1].charAt(1) == t && grid[2].charAt(0) == t) ret = true;
