    }

    double readDouble() throws IOException {
        return Double.parseDouble(readString());
    }

    <T> List<T>[] createGraphList(int size) {
        List<T>[] list = new List[size];
        for (int i = 0; i < size; i++) {
            list[i] = new ArrayList<>();
        }
        return list;
    }

    public static void main(String[] args) {
        new Template().run();

    }

    long timeBegin, timeEnd;

    void time() {
        timeEnd = System.currentTimeMillis();
        System.err.println("Time = " + (timeEnd - timeBegin));
    }

    long memoryTotal, memoryFree;

    void memory() {
        memoryFree = Runtime.getRuntime().freeMemory();
        System.err.println("Memory = " + ((memoryTotal - memoryFree) >> 10)
                + " KB");
    }

    public void run() {
        try {
            timeBegin = System.currentTimeMillis();
            memoryTotal = Runtime.getRuntime().freeMemory();
            init();
            solve();
            out.close();
            if (System.getProperty("ONLINE_JUDGE") == null) {
                time();
                memory();
            }
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(-1);
        }
    }

    boolean equal(char[][] a, char[][] b) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (a[i][j] != b[i][j]) return false;
            }
        }
        return true;
    }

    char CROSS = 'X';
    char ZERO = '0';

    boolean found = false;
    char now = '$';
    boolean draw = false;

    void brut(char[][] a, char[][] b, char now) {
        if (equal(a, b)) {
            found = true;
            this.now = now;
            draw = true;
            for (char[] x : a) {
                for (char y : x) {
                    if (y == '.') draw = false;
                }
            }
        }
        if (winner(b, CROSS) || winner(b, ZERO)) return;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (b[i][j] == '.') {
                    b[i][j] = now;
                    brut(a, b, now == CROSS ? ZERO : CROSS);
                    b[i][j] = '.';
                }
            }
        }
    }

    boolean winner(char[][] a, char x) {
        for (int i = 0; i < 3; i++) {
            if (a[i][0] == x && a[i][1] == x && a[i][2] == x) return true;
            if (a[0][i] == x && a[1][i] == x && a[2][i] == x) return true;
        }
        if (a[0][0] == x && a[1][1] == x && a[2][2] == x) return true;
        if (a[0][2] == x && a[1][1] == x && a[2][0] == x) return true;
        return false;
    }

    void solve() throws IOException {
        char[][] a = new char[3][];
        a[0] = readString().toCharArray();
        a[1] = readString().toCharArray();
        a[2] = readString().toCharArray();
        char[][] b = {{'.', '.', '.'}, {'.', '.', '.'}, {'.', '.', '.'}};
        brut(a, b, CROSS);
        if (!found) {
            out.println("illegal");
            return;
        }
        boolean xwin = winner(a, CROSS);
        boolean owin = winner(a, ZERO);
        if (xwin) {
            out.println("the first player won");
            return;
        }
        if (owin) {
            out.println("the second player won");
            return;
        }
        if (draw) {
            out.println("draw");
            return;
        }
        if (now == CROSS) {
            out.println("first");
        } else {
            out.println("second");
        }

    }

}

import java.io.*;
import java.text.*;
import java.math.*;
import java.util.*;

public class Main implements Runnable {

    int check(int[] p) {
        for (int i = 0; i < 9; i += 3) {
            if (p[i] == p[i + 1] && p[i] == p[i + 2] && p[i] != 0)
                return p[i];
        }
        for (int i = 0; i < 3; i++) {
            if (p[i] == p[i + 3] && p[i] == p[i + 6] && p[i] != 0)
                return p[i];
        }
        if (p[0] == p[4] && p[0] == p[8] && p[0] != 0)
            return p[0];
        if (p[2] == p[4] && p[2] == p[6] && p[2] != 0)
            return p[2];

        for (int i=0; i<9; i++)
        {
            if (p[i]==0)
                return 0;
        }
        return 3;
    }

    int code(int[] p)
    {
        int res = 0, x = 1;
        for (int i=0; i<9; i++)
        {
            res+=x*p[i];
            x*=3;
        }
        return res;
    }
    int[] decode(int x, int[] a)
    {
        for (int i=0; i<9; i++)
        {
            a[i] = x%3;
            x/=3;
        }
        return a;
    }

    int[] win;

    int[] cur;
    int turn;
    public int dfs()
    {
        int x = code(cur);
        if (win[x]!=0)
            return win[x];
        int s = check(cur);
        if (s!=0)
        {
            win[x] = s;
            return s;
        }
        int t = 3-turn;
        for (int i=0; i<9; i++)
            if (cur[i]==0)
            {
                cur[i] = turn;
                turn = 3-turn;
                int t2 = dfs();
                turn = 3-turn;
                cur[i] = 0;
                if (t2 == turn)
                    t = t2;
                else if (t2==3 && t!=turn)
                    t = 3;
            }
        win[x] = t;
        return t;
    }


    public void solve() throws Exception {
        win = new int[50000];
        cur = new int[9];
        turn = 1;
        dfs();
        int[] field = new int[9];
        for (int i=0; i<9; i+=3)
        {
            String s = readword();
            for (int j=0; j<3; j++)
                if (s.charAt(j)=='X')
                    field[i+j] = 1;
                else if (s.charAt(j)=='0')
                    field[i+j] = 2;
        }
        int x = code(field);
        if (win[x] == 0)
        {
            out.write("illegal\n");
            return;
        }
        if (check(field)==1)
        {
            out.write("the first player won\n");
            return;
        }
        if (check(field)==2)
        {
            out.write("the second player won\n");
            return;
        }
        if (check(field)==3)
        {
            out.write("draw\n");
            return;
        }
        int[] a = new int[3];
        for (int i=0; i<9; i++)
            a[field[i]]++;
        if (a[1]>a[2])
            out.write("second\n");
        else out.write("first\n");
    }

    public void run() {
        try {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new BufferedWriter(new OutputStreamWriter(System.out));
            solve();
            out.flush();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    public int iread() throws Exception {
        return Integer.parseInt(readword());
    }

    public double dread() throws Exception {
        return Double.parseDouble(readword());
    }

    public long lread() throws Exception {
        return Long.parseLong(readword());
    }

    BufferedReader in;

    BufferedWriter out;

    public String readword() throws IOException {
        StringBuilder b = new StringBuilder();
        int c;
        c = in.read();
        while (c >= 0 && c <= ' ')
            c = in.read();
        if (c < 0)
            return "";
        while (c > ' ') {
            b.append((char) c);
            c = in.read();
        }
        return b.toString();
    }

    public static void main(String[] args) {
        try {
            Locale.setDefault(Locale.US);
        } catch (Exception e) {

        }
        new Thread(new Main()).start();
    }
}

