public class Problem3C {

	private static int[][] pos;
	private static boolean noMove;
	private static int first, second;

	static {
		pos = new int[3][3];
		noMove = true;
		first = second = 0;
	}

	private static int won() {
		int winner = 0, count = 0;

		for (int i = 0; i < 3; i++) {
			if (pos[i][0] == pos[i][1] && pos[i][0] == pos[i][2]
					&& pos[i][0] != winner && pos[i][0] != 0) {
				winner = pos[i][0];
				count++;
			}
			if (pos[0][i] == pos[1][i] && pos[0][i] == pos[2][i]
					&& pos[0][i] != winner && pos[0][i] != 0) {
				winner = pos[0][i];
				count++;
			}
		}
		if (pos[0][0] == pos[1][1] && pos[1][1] == pos[2][2]
				&& pos[1][1] != winner && pos[1][1] != 0) {
			winner = pos[0][0];
			count++;
		}
		if (pos[0][2] == pos[1][1] && pos[1][1] == pos[2][0]
				&& pos[1][1] != winner && pos[1][1] != 0) {
			winner = pos[0][2];
			count++;
		}
		if (count > 1) {
			System.out.println("illegal");
			System.exit(0);
		}
		return winner;
	}

	private static void solve() {
		int toMove = 0;
		int winner = won();
		if (noMove) {
			if (first != second + 1) {
				System.out.println("illegal");
			} else {
				if (winner == 0) {
					System.out.println("draw");
				} else if (winner == 1) {
