public class Solution 
{
	static boolean firstWinner = false;
	static boolean secondWinner = false;
	static char[][] game = new char[3][3];

	public static void check(char a)
	{
		if (a == 'X')
		{
			firstWinner = true;
		}
		else if(a == '0')
		{
			secondWinner = true;
		}
	}

	public static boolean checkWin(int move_decay)
	{

		char center = game[1][1];
		if (center != '.')
		{
			if ((game[0][0] == center && center == game[2][2]) || (game[2][0] == center && center == game[0][2]))
			{
				check(center);
			}
		}

		for (int i=0;i<3;i++)
		{
			char a = game[i][0];
			if (a != '.' && game[i][1] == a && game[i][2] == a)
				check(a);
		}

		{
			for (int i=0;i<3;i++)
			{
				char a = game[0][i];
				if (a != '.' && game[1][i] == a && game[2][i] == a)
					check(a);
			}
		}
		if (!firstWinner && !secondWinner)
		{
			return false;
		}
		if (firstWinner && secondWinner)
		{
			System.out.println("illegal");
		}
		else if (firstWinner)
		{
			if (move_decay == 1)
			{
				System.out.println("the first player won");
			}
			else
			{
				System.out.println("illegal");
			}
		}
		else if(secondWinner)
		{
			if (move_decay == 0)
			{
				System.out.println("the second player won");
			}
			else
			{
				System.out.println("illegal");
			}
		}
		return true;
	}

	public static void main(String[] args) 
	{
		Scanner s = new Scanner(System.in);
		int first_move = 0;
		int second_move = 0;

		for (int i=0;i<3;i++)
		{
			game[i] = s.next().toCharArray();
			for (int j=0;j<3;j++)
			{
				if (game[i][j] == 'X') 
				{
					first_move++;
				}
				else if (game[i][j] == '0') 
				{
					second_move++;
				}
			}
		}


		int total_move = first_move + second_move;
		int move_decay = first_move - second_move;
		if(move_decay == 1)
		{
			if (!checkWin(move_decay))
			{
				if (total_move!= 9)
				{
					System.out.println("second");
					System.exit(0);
				}
				else
				{
					System.out.println("draw");
					System.exit(0);
				}
			}
		}
		else if (move_decay == 0)
		{
			if (!checkWin(move_decay))
			{
				System.out.println("first");
				System.exit(0);
			}
		}
		else 
		{
			System.out.println("illegal");
		}
	}
}

