            if (a[0][i] == a[1][i] && a[1][i] == a[2][i] && a[2][i] == x) return true;
        }
        if (a[0][0] == a[1][1] && a[1][1] == a[2][2] && a[2][2] == x) return true;
        if (a[2][0] == a[1][1] && a[1][1] == a[0][2] && a[0][2] == x) return true;
        return false;
    }
