public class TicTacToe
{	
	public static boolean checkIfWin(char[][] grid, char C){
		boolean win = false;

		for(int i = 0; i < 3; i++){
			if(grid[i][0] == C && grid[i][1] == C && grid[i][2] == C){
				win = true;			
			}
		}

		for(int i = 0; i < 3; i++){
			if(grid[0][i] == C && grid[1][i] == C && grid[2][i] == C){
				win = true;
			}
		}

		if(grid[0][0] == C && grid[1][1] == C && grid[2][2] == C){
			win = true;			
		}
		else if(grid[2][0] == C && grid[1][1] == C && grid[0][2] == C){
			win = true;			
		}

		return win;
	}

	public static void main(String[] args) throws IOException
	{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter pw = new PrintWriter(System.out);

		char[][] grid = new char[3][3];

		int numX = 0;
		int num0 = 0;
		int numBlank = 0;

		for(int x = 0; x < 3; x++){
			String s = br.readLine();
			for(int y = 0; y < 3; y++){
				char c = s.charAt(y);
				grid[x][y] = c;
				if(c == 'X'){
					numX++;
				}
				else if(c == '0'){
					num0++;
				}
				else{
					numBlank++;
				}					
			}
		}

		boolean xWin = checkIfWin(grid, 'X');
		boolean oWin = checkIfWin(grid, '0');

		if(Math.abs((double)numX - num0) > 1){

			pw.println("illegal");
		}
		else if(num0 - numX > 0){

			pw.println("illegal");
		}
		else if(numBlank == 0 && numX > num0 && !xWin){
			pw.println("draw");			
		}
		else if(xWin && oWin){
			pw.println("illegal");
		}
		else if(oWin && numX > num0){
			pw.println("illegal");
		}
		else if(xWin && numX == num0){
			pw.println("illegal");
		}
		else if(xWin){
			pw.println("the first player won");
		}
		else if(oWin){
			pw.println("the second player won");
		}
		else if(numX == num0){
			pw.println("first");
		}
		else if(num0 < numX){
			pw.println("second");
		}
		else{
			pw.println("illegal");
		}

		pw.close();		
	}

}

