public class TicTacToe {
    static char[][] grid;
    static String playerTurn, winner, first = "the first player won",
            second = "the second player won";
    static boolean draw;

    static boolean checkIllegal() {
        int oC = 0;
        int xC = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (grid[i][j] == '0')
                    oC++;
                else if (grid[i][j] == 'X')
                    xC++;
            }
        }
        if (oC > xC)
            return true;
        if (xC - oC > 1)
            return true;
        int winnerC = 0;
        for (int i = 0; i < 3; i++) {
            if (grid[i][0] != '.' && grid[i][0] == grid[i][1]
                    && grid[i][1] == grid[i][2]) {
                if (grid[i][0] == '0' && xC > oC)
                    return true;
                else if (grid[i][0] == 'X' && oC >= xC)
                    return true;
                winnerC++;
                winner = grid[i][0] == 'X' ? first : second;
            }
        }
        if (winnerC > 1)
            return true;
        winnerC = 0;
        for (int i = 0; i < 3; i++) {
            if (grid[0][i] != '.' && grid[0][i] == grid[1][i]
                    && grid[1][i] == grid[2][i]) {
                if (grid[0][i] == '0' && xC > oC)
                    return true;
                else if (grid[0][i] == 'X' && oC >= xC)
                    return true;
                winnerC++;
                winner = grid[0][i] == 'X' ? first : second;
            }
        }
        if (winnerC > 1)
            return true;
        if (grid[1][1] != '.') {
