                    return true;
                else if (grid[2][0] == 'X' && oC >= xC)
                    return true;
                winner = grid[0][2] == 'X' ? first : second;
            }
        }
        if (xC == 5 && oC == 4)
            draw = true;
        if (xC == oC)
            playerTurn = "first";
