class TaskC {
    char[][] board = new char[3][3];

    boolean check(char c)
    {
        if ( board[0][0]==c && board[1][1]==c && board[2][2]==c ) return true;
        if ( board[0][2]==c && board[1][1]==c && board[2][0]==c ) return true;
        for (int i=0; i<3; i++)
        {
            if ( board[i][0]==c && board[i][1]==c && board[i][2]==c ) return true;
            if ( board[0][i]==c && board[1][i]==c && board[2][i]==c ) return true;
        }
        return false;
    }

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int x = 0, o = 0;
        for (int i=0; i<3; i++)
        {
            board[i] = in.next().toCharArray();
            for (char c : board[i])
            {
                if ( c == 'X' ) x++;
                if ( c == '0' ) o++;
            }
        }

        if ( x==o || x==o+1 )
        {
            boolean wonX = check('X');
            boolean wonO = check('0');
            if ( wonO && wonX ) out.println("illegal");
            else if ( wonX ) out.println(x==o+1 ? "the first player won" : "illegal");
            else if ( wonO ) out.println(x==o ? "the second player won" : "illegal");
            else if ( x+o == 9 ) out.println("draw");
            else if ( x == o ) out.println("first");
            else out.println("second");
        }
        else out.println("illegal");
    }
}

