    private static int[] cnt(char chs[][]) {
        int t1 = 0, t2 = 0;
        for (char tmp[] : chs) {
            for (int i = 0; i < 3; i++) {
                if (tmp[i] == 'X') {
                    t1++;
                } else if (tmp[i] == '0') {
                    t2++;
                }
            }
        }
        return new int[] { t1, t2 };
    }

    private static boolean check(char chs[][], char c) {
        if (chs[0][0] == chs[1][1] && chs[1][1] == chs[2][2] || chs[2][0] == chs[1][1] && chs[1][1] == chs[0][2]) {
            if (chs[1][1] == c)
                return true;
        }
        for (int i = 0; i < 3; i++) {
            boolean ok1 = true;
            boolean ok2 = true;
            for (int j = 0; j < 3; j++) {
                if (chs[i][j] != c) {
