public class Solution {

	static InputReader in = new InputReader(System.in);
	static char[][] tic;

	public static void main(String[] args) {

		tic = new char[3][3];

		tic[0] = in.next().toCharArray();
		tic[1] = in.next().toCharArray();
		tic[2] = in.next().toCharArray();

		int numX = count('X');
		int numO = count('0');

		if (numX > numO + 1 || numO > numX) {
			System.out.println("illegal");
		} else if (winner('X') && winner('0')) {
			System.out.println("illegal");
		} else if (winner('X') && numX != numO + 1) {
			System.out.println("illegal");
		} else if (winner('0') && numX != numO) {
			System.out.println("illegal");
		} else if (winner('X') && !winner('0')) {
			System.out.println("the first player won");
		} else if (winner('0') && !winner('X')) {
			System.out.println("the second player won");
		} else if (numX == numO + 1 && numX < 5) {
			System.out.println("second");
		} else if (numX == numO) {
			System.out.println("first");
		} else if (numX == 5 && numO == 4) {
			System.out.println("draw");
		}

	}

	private static boolean winner(char c) {

		for (int i = 0; i < 3; i++)
			if (tic[0][i] == c && tic[1][i] == c && tic[2][i] == c)
				return true;

		for (int i = 0; i < 3; i++)
			if (tic[i][0] == c && tic[i][1] == c && tic[i][2] == c)
				return true;

		for (int i = 0; i < 3; i++)
			if (tic[0][0] == c && tic[1][1] == c && tic[2][2] == c)
				return true;

		for (int i = 0; i < 3; i++)
			if (tic[2][0] == c && tic[1][1] == c && tic[0][2] == c)
				return true;

		return false;
	}

	private static int count(char c) {

		int cnt = 0;

		for (int i = 0; i < 3; i++)
			for (int j = 0; j < 3; j++)
				if (tic[i][j] == c)
					cnt++;
		return cnt;
	}
}

