public class TicTacToe {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader inp = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Solver solver = new Solver();
        solver.solve(inp, out);
        out.close();
    }

    static class Solver {
        private void solve(InputReader inp, PrintWriter out) {
            boolean[][] a = new boolean[3][3];
            boolean[][] b = new boolean[3][3];
            int a2 = 0, b2 = 0;
            for (int i = 0; i < 3; i++) {
                String row = inp.next();
                for (int j = 0; j < 3; j++) {
                    if (row.charAt(j) == 'X') {
                        a[i][j] = true;
                        a2++;
                    } else if (row.charAt(j) == '0') {
                        b[i][j] = true;
                        b2++;
                    }
                }
            }
            boolean first = false, second = false;
            if (a[0][0]&&a[0][1]&&a[0][2]) first = true;
            if (a[1][0]&&a[1][1]&&a[1][2]) first = true;
            if (a[2][0]&&a[2][1]&&a[2][2]) first = true;
            if (a[0][0]&&a[1][0]&&a[2][0]) first = true;
            if (a[0][1]&&a[1][1]&&a[2][1]) first = true;
            if (a[0][2]&&a[1][2]&&a[2][2]) first = true;
            if (a[0][0]&&a[1][1]&&a[2][2]) first = true;
            if (a[0][2]&&a[1][1]&&a[2][0]) first = true;

            if (b[0][0]&&b[0][1]&&b[0][2]) second = true;
            if (b[1][0]&&b[1][1]&&b[1][2]) second = true;
            if (b[2][0]&&b[2][1]&&b[2][2]) second = true;
            if (b[0][0]&&b[1][0]&&b[2][0]) second = true;
            if (b[0][1]&&b[1][1]&&b[2][1]) second = true;
            if (b[0][2]&&b[1][2]&&b[2][2]) second = true;
            if (b[0][0]&&b[1][1]&&b[2][2]) second = true;
            if (b[0][2]&&b[1][1]&&b[2][0]) second = true;

            if (b2 > a2 || (a2 - 2 >= b2) || (first && second) || (a2 > b2 && second) || (a2 == b2 && first)) out.print("illegal");
            else if (first) out.print("the first player won");
            else if (second) out.print("the second player won");
            else if (a2 + b2 == 9) out.print("draw");
            else if (a2 == b2 + 1) out.print("second");
            else if (a2 == b2) out.print("first");
            else out.print("draw");
        }
    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

public final class TicTacToe {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[3][];
        for (int i = 0; i < 3; i++) {
            board[i] = scanner.nextLine().toCharArray();
        }

        int numberOfXs = 0;
        int numberOf0s = 0;
        int numberOfDots = 0;
        int numberOfXWins = 0;
        int numberOf0Wins = 0;
        for (int i = 0; i < 3; i++) {
            char row = board[i][0];
            char col = board[0][i];
            boolean rowSame = true;
            boolean colSame = true;
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == 'X') numberOfXs++;
                else if (board[i][j] == '0') numberOf0s++;
                else if (board[i][j] == '.') numberOfDots++;

                if (board[i][j] != row) rowSame = false;
                if (board[j][i] != col) colSame = false;
            }

            if (rowSame)
                if (row == 'X') numberOfXWins++;
                else if (row == '0') numberOf0Wins++;


            if (colSame)
                if (col == 'X') numberOfXWins++;
                else if (col == '0') numberOf0Wins++;
        }

        char forward = board[0][0];
        char backward = board[2][0];
        boolean fSame = true;
        boolean bSame = true;
        for (int i = 0; i < 3; i++) {
            if (forward != board[i][i]) fSame = false;
            if (backward != board[2 - i][i]) bSame = false;
        }

        if (fSame)
            if (forward == 'X') numberOfXWins++;
            else if (forward == '0') numberOf0Wins++;

        if (bSame)
            if (backward == 'X') numberOfXWins++;
            else if (backward == '0') numberOf0Wins++;

        if (numberOfXWins >= 1 && numberOf0Wins >= 1 ||
            numberOfXWins >= 1 && numberOfXs == numberOf0s ||
            numberOf0Wins >= 1 && numberOfXs == numberOf0s + 1 ||
            numberOfXs < numberOf0s || numberOfXs > numberOf0s + 1)
            System.out.println("illegal");
        else if (numberOfXWins >= 1)
            System.out.println("the first player won");
        else if (numberOf0Wins >= 1)
            System.out.println("the second player won");
        else if (numberOfDots == 0)
            System.out.println("draw");
        else if (numberOfXs == numberOf0s)
            System.out.println("first");
        else if (numberOfXs == numberOf0s + 1)
            System.out.println("second");
        else
            throw new IllegalStateException(numberOfXs + " " +
                                            numberOf0s + " " +
                                            numberOfDots + " " +
                                            numberOfXWins + " " +
                                            numberOf0Wins);
    }
}

