public class D {

	static int getWinner(char[][] board, int x, int y, int dx, int dy)
	{
		char c = board[x][y];
		if(board[x + dx][y + dy] != c || board[x + 2 * dx][y + 2 * dy] != c)
			return 0;
		if(c == '.')
			return 0;
		return c == 'X' ? 1 : 2;
	} 

	public static void main(String[] args) throws IOException 
	{
		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		char[][] board = new char[3][];
		for(int i = 0; i < 3; ++i)
			board[i] = sc.next().toCharArray();
		int winner = getWinner(board, 0, 0, 1, 1) | getWinner(board, 2, 0, -1, 1);
		for(int i = 0; i < 3; ++i)
		{
			winner |= getWinner(board, i, 0, 0, 1);
			winner |= getWinner(board, 0, i, 1, 0);
		}
		int x = 0, o = 0, e = 0;
		for(int i = 0; i < 3; ++i)
			for(char c: board[i])
				if(c == '.')
					++e;
				else if(c == 'X')
					++x;
				else
					++o;

		if(winner == 3 || o > x || x - o > 1 || x - o == 1 && winner == 2 || x == o && winner == 1)
			out.println("illegal");
		else if(winner != 0)
			out.printf("the %s player won\n", winner == 1 ? "first" : "second");
		else if(e == 0)
				out.println("draw");
			else if(x == o)
				out.println("first");
			else
				out.println("second");

		out.flush();
		out.close();
	}

	static class Scanner 
	{
		StringTokenizer st;
		BufferedReader br;

		public Scanner(InputStream s){    br = new BufferedReader(new InputStreamReader(s));}

		public Scanner(FileReader r){    br = new BufferedReader(r);}

		public String next() throws IOException 
		{
			while (st == null || !st.hasMoreTokens()) 
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		public int nextInt() throws IOException {return Integer.parseInt(next());}

		public long nextLong() throws IOException {return Long.parseLong(next());}

		public String nextLine() throws IOException {return br.readLine();}

		public double nextDouble() throws IOException
		{
			String x = next();
			StringBuilder sb = new StringBuilder("0");
			double res = 0, f = 1;
			boolean dec = false, neg = false;
			int start = 0;
			if(x.charAt(0) == '-')
			{
				neg = true;
				start++;
			}
			for(int i = start; i < x.length(); i++)
				if(x.charAt(i) == '.')
				{
					res = Long.parseLong(sb.toString());
					sb = new StringBuilder("0");
					dec = true;
				}
				else
				{
					sb.append(x.charAt(i));
					if(dec)
						f *= 10;
				}
			res += Long.parseLong(sb.toString()) / f;
			return res * (neg?-1:1);
		}

		public boolean ready() throws IOException {return br.ready();}


	}
}

