            }
            win |= can1 | can2;
        }
        boolean can1 = true;
        boolean can2 = true;
        for (int i = 0; i < 3; i++) {
            can1 &= x[i][i] == y;
            can2 &= x[i][3 - i - 1] == y;
        }
        win |= can1 | can2;
        return win;
    }

