  public void solve() {
    Scanner in = new Scanner(System.in);
    char[][] board = new char[3][3];
    for (int i = 0; i < 3; ++i)
      board[i] = (in.next()).toCharArray();

    int[] winners = getWinners(board);
    int turn = getTurn(board);

    if ((winners[0] > 0 && winners[1] > 0) || turn == -1) {
      System.out.println("illegal");
      return;
    }

    if ((turn == 1 && winners[0] > 0) || (turn == 2 && winners[1] > 0)) {
      System.out.println("illegal");
      return;
    }

    if (winners[0] > 0) {
      System.out.println("the first player won");
      return;
    }
    if (winners[1] > 0) {
      System.out.println("the second player won");
      return;
    }
    if (turn == 3) {
      System.out.println("draw");
      return;
    }
    if (turn == 1)
      System.out.println("first");
    else
      System.out.println("second");
  }

  public int getTurn(char[][] board) {
    int xCount = 0;
    int oCount = 0;
    for (int i = 0; i < board.length; ++i) {
      for (int j = 0; j < board[i].length; ++j) {
        xCount += (board[i][j] == 'X' ? 1 : 0);
        oCount += (board[i][j] == '0' ? 1 : 0);
      }
    }
    if (xCount == oCount)
      return 1;
    else if (xCount == oCount + 1) {
      if (xCount + oCount == 9)
        return 3;
      return 2;
    }
    return -1;
  }

  public int[] getWinners(char[][] board) {
    int[][][] win = { {{0,0},{0,1},{0,2}},{{1,0},{1,1},{1,2}},{{2,0},{2,1},{2,2}},{{0,0},{1,0},{2,0}},{{0,1},{1,1},{2,1}},{{0,2},{1,2},{2,2}},{{0,0},{1,1},{2,2}},{{0,2},{1,1},{2,0}}};
    int[] ret = new int[2];
    for (int i = 0; i < win.length; ++i) {

      int[][] m = win[i];
      boolean same = (board[m[0][0]][m[0][1]] == board[m[1][0]][m[1][1]] && board[m[0][0]][m[0][1]] == board[m[2][0]][m[2][1]]);
      if (!same)
        continue;
      char c = board[m[0][0]][m[0][1]];
      if (c == '.')
        continue;
      if (c == 'X')
        ++ret[0];
      else
        ++ret[1];
    }
    return ret;
  }
}

