public class Main {

	static int[] dp=new int[20000];
	static int[][] grid=new int[4][4];
	static int same(int pos, int dir)
	{
		int cross=0, circle=0;
		if (dir==1)
		{
			for (int i=0; i<3; i++)
				if (grid[pos][i]==0)
					return 0;
				else if (grid[pos][i]==1)
					cross++;
				else 
					circle++;
			if (cross==3)
				return 1;
			if (circle==3)
				return 2;
			return 0;
		}
		else if (dir==2)
		{
			for (int i=0; i<3; i++)
				if (grid[i][pos]==0)
					return 0;
				else if (grid[i][pos]==1)
					cross++;
				else 
					circle++;
			if (cross==3)
				return 1;
			if (circle==3)
				return 2;
			return 0;
		}
		else if (dir==3)
		{
			for (int i=0; i<3; i++)
				if (grid[i][i]==0)
					return 0;
				else if (grid[i][i]==1)
					cross++;
				else 
					circle++;
			if (cross==3)
				return 1;
			if (circle==3)
				return 2;
			return 0;
		}
		else if (dir==4)
		{
			for (int i=0; i<3; i++)
				if (grid[i][2-i]==0)
					return 0;
				else if (grid[i][2-i]==1)
					cross++;
				else 
					circle++;
			if (cross==3)
				return 1;
			if (circle==3)
				return 2;
			return 0;
		}
		return 0;
	}
	static int win()
	{
		for (int i=0; i<3; i++)
		{
			int temp=same(i, 1);
			if (temp>0)
				return temp;
			temp=same(i, 2);
			if (temp>0)
				return temp;
		}
		int temp=same(0, 3);
		if (temp>0)
			return temp;
		temp=same(0, 4);
		if (temp>0)
			return temp;
		return 0;
	}

	static void fill(int cnt, int next)
	{
		if (dp[cnt]>0)
			return;
		int temp=win();
		if (temp>0)
		{
			dp[cnt]=temp+2;
			return;
		}
		else
			dp[cnt]=next;

		int flag=1;
		int tag=0;
		for (int i=0; i<3; i++)
			for (int j=0; j<3; j++)
			{
				if (grid[i][j]==0)
				{
					grid[i][j]=next;
					fill(cnt+flag*next, 3-next);
					grid[i][j]=0;
					tag=1;
				}
				flag*=3;
			}
		if (tag==0)
			dp[cnt]=5;

	}

	public static void main(String[] args)
	{

		Scanner cin=new Scanner(System.in);
		String temp;

		for (int i=0; i<3; i++)
			for (int j=0; j<3; j++)
				grid[i][j]=0;
		fill(0, 1);

		int flag=1, cnt=0;
		for (int i=0; i<3; i++)
		{
			temp=cin.next();
			for (int j=0; j<3; j++)
			{
				if (temp.charAt(j)=='X')
					cnt+=flag;
				else if (temp.charAt(j)=='0')
					cnt+=2*flag;
				flag*=3;
			}
		}

		if (dp[cnt]==0)
			System.out.println("illegal");
		else if (dp[cnt]==1)
			System.out.println("first");
		else if (dp[cnt]==2)
			System.out.println("second");
		else if (dp[cnt]==3)
			System.out.println("the first player won");
		else if (dp[cnt]==4)
			System.out.println("the second player won");
		else if (dp[cnt]==5)
			System.out.println("draw");
	}

}

