public class TicTacToe {

      static boolean firstwinner, secondwinner;

      public static void main(String[] args) {
            Scanner scan = new Scanner(System.in);
            char[][] grid = new char[3][3];
            int xcount = 0, count = 0;
            boolean dot = false;
            for(int i = 0 ; i < 3 ; i++){
                  String line = scan.nextLine();
                  for(int j = 0 ; j < 3 ; j++){
                        grid[i][j] = line.charAt(j);
                        if(grid[i][j] == 'X') xcount++;
                        if(grid[i][j] == '0') count++;
                        if(grid[i][j] == '.') dot = true;
                  }
            } 
            if(xcount - count == 0 || xcount - count == 1){
                  horizontal(grid);
                  vertical(grid);
                  diagonal1(grid);
                  diagonal2(grid);
                  if(firstwinner && secondwinner) System.out.println("illegal");
                  else if(firstwinner){
                        if(xcount - count == 1) System.out.println("the first player won");
                        else System.out.println("illegal");
                  } 
                  else if(secondwinner){
                        if(xcount - count == 0) System.out.println("the second player won");
                        else System.out.println("illegal");
                  } 
                  else if(dot){
                        if(xcount - count == 0) System.out.println("first");
                        else System.out.println("second");  
                  }
                  else System.out.println("draw");
            }
            else System.out.println("illegal");
      }
      static void horizontal(char[][] grid) {
            for(int i = 0 ; i < 3 ; i++){
                  int xcount = 0, count = 0;
                  for(int j = 0 ; j < 3 ; j++){
                        if(grid[i][j] == 'X') xcount++;
                        if(grid[i][j] == '0') count++;
                  }
                  if(xcount == 3) firstwinner = true;
                  if(count == 3) secondwinner = true;
            }
            return;
      }
      static void vertical(char[][] grid) {
            for(int i = 0 ; i < 3 ; i++){
                  int xcount = 0, count = 0;
                  for(int j = 0 ; j < 3 ; j++){
                        if(grid[j][i] == 'X') xcount++;
                        if(grid[j][i] == '0') count++;
                  }
                  if(xcount == 3) firstwinner = true;
                  if(count == 3) secondwinner = true;
            }
            return;
      }
      static void diagonal1(char[][] grid) {
            int xcount = 0, count = 0;
            for(int i = 0 , j = 0 ; i < 3 ; i++ , j++){
                  if(grid[i][j] == 'X') xcount++;
                  if(grid[i][j] == '0') count++;
            }
            if(xcount == 3) firstwinner = true;
            if(count == 3) secondwinner = true;
            return;
      }
      static void diagonal2(char[][] grid) {
            int xcount = 0, count = 0;
            for(int i = 2 , j = 0 ; j < 3 ; i-- , j++){
                  if(grid[i][j] == 'X') xcount++;
                  if(grid[i][j] == '0') count++;
            }
            if(xcount == 3) firstwinner = true;
            if(count == 3) secondwinner = true;
            return;
      }
}

