	public static boolean win(char[][] arr, char symbol) {
		int[] rows = new int[3];
		int[] cols = new int[3];

		for (int i = 0; i < 3; i++)
			for (int j = 0; j < 3; j++)
				if (arr[i][j] == symbol) {
					rows[i]++;
					cols[j]++;
				}

		for (int i = 0; i < 3; i++) {
			if (rows[i] == 3)
				return true;
			if (cols[i] == 3)
				return true;
		}

		boolean ok = true;
