			if (arr[i][i] != symbol)
				ok = false;
		if (ok)
			return true;

		ok = true;
		for (int i = 0; i < 3; i++)
			if (arr[i][2 - i] != symbol)
				ok = false;
		if (ok)
			return true;

		return false;
	}
