			win = b[0][0];
			winners.add(win + "");

		}
		if (b[0][0] == b[1][0] && b[1][0] == b[2][0]) {
			win = b[0][0];
			winners.add(win + "");

		}
		if (b[0][1] == b[1][1] && b[1][1] == b[2][1]) {
			win = b[0][1];
			winners.add(win + "");

