		if (b[0][0] == b[1][1] && b[1][1] == b[2][2]) {
			win = b[0][0];
			winners.add(win + "");

		}
		if (b[2][0] == b[1][1] && b[1][1] == b[0][2]) {
			win = b[2][0];
			winners.add(win + "");


		}
