public class FoxAndTwoDots {
	static int row = 0;
	static int column = 0;
	static int[][] board;
	static Stack stack;

	static int count = 0;
	static int[][] delete;
	static int deleteCount=0;
	public static void main(String[] args) {

		Scanner scanner = new Scanner(System.in);

		row = scanner.nextInt();
		column = scanner.nextInt();

