		scanner.nextLine();

		for(int i=0; i<row; i++){
			String rowInfo = scanner.nextLine();
			for(int j=0; j<column; j++){
				board[i][j] = (int)(rowInfo.charAt(j));	
			}
		}
		int alpha = 0;
		int turn = 0;
		stack = new Stack();

		for(int i=0; i<row; i++){
			for(int j=0; j<column; j++){

				if(board[i][j] != 0){
					alpha = board[i][j];

					foo(i,j, alpha,i,j);	
				}

				for(int k=0; k<row; k++){
					for(int l=0; l<column; l++){
						if(board[k][l] == 1){
							board[k][l] = 0;
						}
					}
				}
			}
		}
		if(count == 1){
			System.out.println("Yes");
		}else{
			System.out.println("No");
		}		
	}

	public static void foo(int i, int j, int alpha, int parentRow, int parentColumn){



		board[i][j] = 1;
		int beforei = parentRow;
		int beforej = parentColumn;

		int numberOfPop = 0;

		if((i-1 >= 0) && (alpha == board[i-1][j]) && ((i-1 != beforei)||(j != beforej))){

			int[] temp = new int[2];
			temp[0] = i-1;
			temp[1] = j;

			stack.push(temp);
			numberOfPop ++;
		}else if((i-1 >= 0) && (board[i-1][j] == 1) && ((i-1 != beforei)||(j != beforej))){

			count = 1;
			return;
		}

		if((i+1 < row) && (alpha == board[i+1][j]) && ((i+1 != beforei)||(j != beforej))){
			int[] temp = new int[2];
			temp[0] = i+1;
			temp[1] = j;

			numberOfPop ++;
			stack.push(temp);
		}else if((i+1 < row) && (board[i+1][j] == 1)&& ((i+1 != beforei)||(j != beforej))){

			count = 1;
			return;
		}

		if((j-1 >= 0) && (alpha == board[i][j-1]) && ((i != beforei)||(j-1 != beforej))){
			int[] temp = new int[2];
			temp[0] = i;
			temp[1] = j-1;
			numberOfPop ++;
			stack.push(temp);
		}else if((j-1 >= 0) && (board[i][j-1] == 1)&& ((i != beforei)||(j-1 != beforej))){

			count = 1;
			return;
		}

		if((j+1 < column) && (alpha == board[i][j+1]) && ((i != beforei)||(j+1 != beforej))){
			int[] temp = new int[2];
			temp[0] = i;
			temp[1] = j+1;
			numberOfPop ++;
			stack.push(temp);
		}else if((j+1 < column) && (board[i][j+1] == 1)&& ((i != beforei)||(j+1 != beforej))){

			count = 1;
			return;
		}

		beforei = i;
		beforej = j;

		for(int l=0; l<numberOfPop; l++){
			int[] test = (int[])stack.pop();	
			foo(test[0], test[1], alpha, beforei, beforej);	
		}
	}
}

