class TaskB {

    private static final int[] DI = {1, -1, 0, 0};
    private static final int[] DJ = {0, 0, 1, -1};

    int n;
    int m;
    char[][] field;
    boolean[][] was;

    public void solve(int testNumber, FastScanner in, PrintWriter out) {
        n = in.nextInt();
        m = in.nextInt();
        field = new char[n + 2][m + 2];
        was = new boolean[n + 2][m + 2];
        for (int i = 1; i <= n; i++) {
            char[] line = in.nextWord();
            System.arraycopy(line, 0, field[i], 1, m);
        }

        boolean answer = false;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (!was[i][j]) {
                    if (dfs(i, j, -1, -1)) {
                        answer = true;
                        break;
                    }
                }
            }
        }

        out.print(answer ? "Yes" : "No");
    }

    private boolean dfs(int i, int j, int prevI, int prevJ) {
        if (was[i][j])
            return true;

        was[i][j] = true;
        for (int k = 0; k < 4; k++) {
            int newI = i + DI[k];
            int newJ = j + DJ[k];
            if (!(newI == prevI && newJ == prevJ) && field[i][j] == field[newI][newJ])
                if (dfs(newI, newJ, i, j))
                    return true;
        }

        return false;
    }

}

