import java.util.*;

public class Graph {

	public static class LinkedList {
		Node head; 

		public class Node {

			int element;
			Node nextElement;

			public Node(int e) {
				this.element = e;
				this.nextElement = null;
			}
		}

		public void add(int newElement) {
			if (head == null) { 
				head = new Node(newElement); 
				return;
			} else {
				Node newNode = new Node(newElement); 
				Node last = head; 
				while (last.nextElement != null) { 

					last = last.nextElement;
				}
				last.nextElement = newNode; 

				return;
			}
		}
	}

	static LinkedList graph[];
	static int V, n, m;

	public Graph(int v) {
		V = v;
		graph = new LinkedList[v];
		for (int aux = 0; aux < V; aux++) {
			graph[aux] = new LinkedList();
		}
	}

	public void addGraph(int v, int element) {
		graph[v].add(element);
		graph[element].add(v);
	}

	public static boolean checkCycle() {
		boolean visited[] = new boolean[V];

		for (int aux = 0; aux < V; aux++) {
			visited[aux] = false;
		}

		for (int aux = 0; aux < V; aux++) {
			if (visited[aux] == false) {
				if (DFSUtil(aux, -1, visited) == true) {
					return true;
				}
			}
		}
		return false;
	}

	public static boolean DFSUtil(int index, int previous, boolean visited[]) {

		visited[index] = true;
		LinkedList.Node last = graph[index].head;
		int a;

		while (last != null) {
			a = last.element;
			if (visited[a] == false) {
				if (DFSUtil(a, index, visited) == true) {
					return true;
				}
			} else if (a != previous) {
					return true;
			}
		last = last.nextElement;
		} 
		return false;
	}

	public static void main(String[] args) {

		Scanner in = new Scanner(System.in);

		n = in.nextInt();
		m = in.nextInt();

		Graph g = new Graph(n * m);

		char[] color = new char[n * m];
		int index = 0, next = index + 1;

		for (int i = 0; i < n; i++) {
			String line = in.next();
			for (int j = 0; j < m; j++, index++, next++) {
				if (j < m - 1) {
					color[index] = line.charAt(j);
					color[next] = line.charAt(j + 1);
					if (line.charAt(j) == line.charAt(j + 1)) {
						g.addGraph(index, next);
					}
				}
				if (i > 0) {
					if (line.charAt(j) == color[index - m]) {
						g.addGraph(index, index - m);
					}
				}
			}
		}

		boolean cycle = checkCycle();

		if (cycle == true) {
			System.out.println("Yes");
		} else {
			System.out.println("No");
		}

		in.close();
	}

}

