			visited[current]=true;
			return ans;
		}

		public boolean GraphCheckUtil() {
			boolean[] visited=new boolean[V];
			boolean ans=false;
			for(int i=0;i<V;i++) {
				if(!visited[i]) {
					ans|=GraphCheck(i, visited, new boolean[V], new int[V]);
				}
			}
			return ans;
		}
	}

