public class Solution {
    public static void main(String[] args) throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] temp = br.readLine().trim().split(" ");
        int rows = Integer.parseInt(temp[0]);
        int cols = Integer.parseInt(temp[1]);
        int[][] matrix=new int[rows][cols];
        for(int i=0;i<rows;i++){
            String str=br.readLine();
            for(int j=0;j<cols;j++){
                matrix[i][j]=str.charAt(j);
            }
        }

        ArrayList<ArrayList<Integer>> graph=new ArrayList<>();

        for(int i=0;i<=rows*cols;i++){
            graph.add(new ArrayList<>());
        }

        for(int i=0;i<rows;i++){
            for(int j=0;j<cols;j++){
                int pointNumber1=(i)*cols+j+1;
                if(i-1>=0 && matrix[i-1][j]==matrix[i][j]){
                    int pointNumber2=(i-1)*cols+j+1;
                    graph.get(pointNumber1).add(pointNumber2);
                    graph.get(pointNumber2).add(pointNumber1);
                }
                if(j-1>=0 && matrix[i][j-1]==matrix[i][j]){
                    int pointNumber2=i*cols+(j-1)+1;
                    graph.get(pointNumber1).add(pointNumber2);
                    graph.get(pointNumber2).add(pointNumber1);
                }
            }
        }

        boolean[] visited=new boolean[rows*cols+1];

        for(int i=1;i<=rows*cols;i++){
            if(visited[i]==false){
                Pair ans=dfs(graph,i,visited);
                int edges=ans.getDegreeSum()/2;
                if(edges>ans.getVertices()-1){
                    System.out.println("Yes");
                    return;
                }
            }
        }

        System.out.println("No");
    }
    public static Pair dfs(ArrayList<ArrayList<Integer>> graph,int start,boolean[] visited){
        int vertices = 1;
        int degreeSum = graph.get(start).size();

        visited[start] = true;

        for(int i=0;i<graph.get(start).size();i++){
            if(visited[graph.get(start).get(i)]==false){
                Pair smallAns=dfs(graph,graph.get(start).get(i),visited);
                vertices+=smallAns.getVertices();
                degreeSum+=smallAns.getDegreeSum();
            }
        }
        Pair ans = new Pair(vertices, degreeSum);
        return ans;
    }
}

class Pair {
    private int vertices;
    private int degreeSum;

    public Pair(int vertices, int degreeSum) {
        this.vertices = vertices;
        this.degreeSum = degreeSum;
    }

    public int getVertices() {
        return this.vertices;
    }

    public int getDegreeSum() {
        return this.degreeSum;
    }
}

import java.io.BufferedReader;
