                    System.out.println("Yes");
                    return;
                }
            }
        }  
        System.out.println("No");
    }

    static int[] dirX = new int[]{-1, 0, 0, 1};
    static int[] dirY = new int[]{0, -1, 1, 0};

    public static boolean dfs(int thisI, int thisJ, int lastI, int lastJ) {

        if(visited[thisI][thisJ]) return true;

        visited[thisI][thisJ] = true;

        for(int k=0;k<4;++k) {
            int nextI = thisI + dirX[k];
            int nextJ = thisJ + dirY[k];

            if(grid[nextI][nextJ] == grid[thisI][thisJ] && (nextI != lastI || nextJ != lastJ)) {
                if(dfs(nextI, nextJ, thisI, thisJ)) {
                    return true;
                }
            }
        }

        return false;
    }

}

