import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class CodeForces {
	public static class Point {
		int row;
		int col;

		public Point(int r, int c) {
			row = r;
			col = c;
		}

	}

	public static boolean hasCycle(char[][] m) {
		for(int i = 0; i < m.length; i++) {
			for(int j = 0; j < m[0].length; j++) {

				char color = m[i][j];
				boolean hasCycle = CodeForces.dfs(color, new Point(i,j), new Point(i,j), new HashSet<String>(), m, new int[] {-1, 1, 0,0},new int[] {0,0,-1,1}, new Point(-1,-1));		
				if (hasCycle) {
					return true;
				}

			}		
		}

		return false;
	}

	private static boolean dfs(char col, Point start, Point end, Set<String> visited, char[][] m, int[] rows, int[] cols, Point parent) {
		visited.add(""+start.row + "," + start.col);
			int r = start.row;
			int c = start.col;
			for (int i = 0; i < rows.length; i++) {
				int nextR =  r + rows[i];
				int nextC = c + cols[i];

				Point p1 = new Point(nextR,nextC);
				String next= "" + nextR + "," + nextC;
				if (visited.contains(next)) {
					if (nextR != parent.row && nextC != parent.col) {
						return true;
					} 
					continue;
				}

				if (CodeForces.inBounds(nextR,nextC, m.length, m[0].length) && m[nextR][nextC] == col)
				{

						boolean result = dfs(col, p1, end, visited, m, rows, cols, start);
						if (result) {
							return true;
						}
				}

		}
		return false;
	}

	private static boolean inBounds(int row, int col, int numRows, int numCols) {
		return (row < numRows && row >= 0) && (col < numCols && col >= 0);
	}


	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		int r = sc.nextInt();
		int c = sc.nextInt();
		char[][] m = new char[r][c];
		for (int i = 0; i < r; i ++) {
			m[i] = sc.next().toCharArray();
		}

		boolean result = CodeForces.hasCycle(m);
		System.out.println(result ? "Yes" : "No");
	}

}

