		v_map[r][c] = true; 
		int y, x; 

		int depth = i++;
		if(depth>max_depth){
			max_depth=depth;
		}
		if(endFlag){
			return;
		}

		int wR, wC; 
		while (!stack.isEmpty()) { 
			if(endFlag){
				return;
			}


			temp = stack.pop();
			x = temp.getX();
			y = temp.getY();

			for (int i = 0; i < 4; i++) { 
				wR = y + move[i][1];
