public class FoxAndTwoDots {



	static int n;
	static int m;
	static char mat[][];
	static boolean vis[][];
	static boolean done = false;

	static void dfs(int i,int j,char c,int pi,int pj)
	{
		if(i-1 >= 0 && mat[i-1][j] == c && !(pi == i-1 && pj == j))
		{
			if(vis[i-1][j])
			{
				done = true;

				return;
			}
			else
			{
				vis[i-1][j] = true;
				dfs(i-1,j,c,i,j);
			}
		}
		if(j-1 >= 0 && mat[i][j-1] == c && !(pi == i && pj == j-1))
		{
			if(vis[i][j-1])
			{
				done = true;

				return;
			}
			else
			{
				vis[i][j-1] = true;
				dfs(i,j-1,c,i,j);
			}
		}
		if(i+1 < n && mat[i+1][j] == c  && !(pi == i+1 && pj == j))
		{
			if(vis[i+1][j])
			{
				done = true;

				return;
			}
			else
			{
				vis[i+1][j] = true;
				dfs(i+1,j,c,i,j);
			}
		}
		if(j+1 < m && mat[i][j+1] == c && !(pi == i && pj == j+1))
		{
			if(vis[i][j+1])
			{
				done = true;

				return;
			}
			else
			{
				vis[i][j+1] = true;
				dfs(i,j+1,c,i,j);
			}
		}
		vis[i][j] = false;
	}
	public static void main(String[] args) throws IOException {

		InputStreamReader r = new InputStreamReader(System.in);
		BufferedReader br = new BufferedReader(r);
		String s[] = br.readLine().trim().split("\\s+");
		n = Integer.parseInt(s[0]);
		m = Integer.parseInt(s[1]);

		mat = new char[n][m];
		for(int i = 0; i < n; i++)
		{
			mat[i] = br.readLine().toCharArray();
		}

		vis = new boolean[n][m];

		for(int i = 0; i < n; i++)
		{
			Arrays.fill(vis[i],false);
		}

		for(int i = 0; i < n; i++)
		{
			for(int j = 0; j < m; j++)
			{	
				if(!vis[i][j])
				{
					vis[i][j] = true;
					char c = mat[i][j];
					dfs(i,j,c,-1,-1);
					if(done == true)
					{
						System.out.println("Yes");
						return;
					}
				}
			}
		}

		System.out.println("No");
	}

}

