public class B {

	static int startI, startJ;
	static boolean cycleFound = false;

	public static void main(String[] args) throws NumberFormatException, IOException {
		BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter out = new PrintWriter(System.out);
		Scanner s = new Scanner(System.in);

		String[] split = f.readLine().split("\\s+");
		int n = Integer.parseInt(split[0]), m = Integer.parseInt(split[1]);
		char[][] grid = new char[n][m];
		for(int i = 0; i < n; i++) grid[i] = f.readLine().toCharArray();
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(hasNeighbors(i, j, grid)) {
					startI = i; startJ = j;

					boolean[][] V = new boolean[n][m];
					V[i][j] = true;
					dfs(-1, -1, i, j, V, grid);
					if(cycleFound) {

						System.out.println("Yes");
						return;
					}
				} else {

				}
			}
		}
		System.out.println("No");
	}

	static void dfs(int fromI, int fromJ, int i, int j, boolean[][] V, char[][] grid) {
		int n = grid.length, m = grid[0].length;

		if(inBounds(i-1, j, n, m) && grid[i-1][j] == grid[i][j]) {
			if(!V[i-1][j]) {
				V[i-1][j] = true;
				dfs(i, j, i-1, j, V, grid);
			} else if(i-1 == startI && j == startJ && i-1 != fromI && j != fromJ) {

				cycleFound = true;
				return;
			}
		}
		if(inBounds(i+1, j, n, m) && grid[i+1][j] == grid[i][j]) {
			if(!V[i+1][j]) {
				V[i+1][j] = true;
				dfs(i, j, i+1, j, V, grid);
			} else if(i+1 == startI && j == startJ && i+1 != fromI && j != fromJ) {

				cycleFound = true;
				return;
			}
		}
		if(inBounds(i, j-1, n, m) && grid[i][j-1] == grid[i][j]) {
			if(!V[i][j-1]) {
				V[i][j-1] = true;
				dfs(i, j, i, j-1, V, grid);
			} else if(i == startI && j-1 == startJ && i != fromI && j-1 != fromJ) {

				cycleFound = true;
				return;
			}
		}
		if(inBounds(i, j+1, n, m) && grid[i][j+1] == grid[i][j]) {
			if(!V[i][j+1]) {
				V[i][j+1] = true;
				dfs(i, j, i, j+1, V, grid);
			} else if(i == startI && j+1 == startJ && i != fromI && j+1 != fromJ) {

				cycleFound = true;
				return;
			}
		}
	}

	static boolean hasNeighbors(int i, int j, char[][] grid) {
		int nc = 0, n = grid.length, m = grid[0].length;
		if(inBounds(i-1, j, n, m) && grid[i-1][j] == grid[i][j]) nc++;
		if(inBounds(i+1, j, n, m) && grid[i+1][j] == grid[i][j]) nc++;
		if(inBounds(i, j-1, n, m) && grid[i][j-1] == grid[i][j]) nc++;
		if(inBounds(i, j+1, n, m) && grid[i][j+1] == grid[i][j]) nc++;
		return nc >= 2;
	}

	static boolean inBounds(int i, int j, int n, int m) {
		return i >= 0 && i < n && j >= 0 && j < m;
	}
}

