public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BFoxAndTwoDots solver = new BFoxAndTwoDots();
        solver.solve(1, in, out);
        out.close();
    }

    static class BFoxAndTwoDots {
        static char[][] a;
        static int[][] visited;
        static boolean ans;
        int m;
        int n;

        void dfs(int i, int j, int pi, int pj) {
            visited[i][j] = 1;
            if (i - 1 >= 0) {
                if (visited[i - 1][j] == 1 && (i - 1 != pi) && a[i][j] == a[i - 1][j]) {
                    ans |= true;
                    return;
                } else if (visited[i - 1][j] == 0 && (i - 1 != pi) && a[i][j] == a[i - 1][j]) {
                    dfs(i - 1, j, i, j);
                }
            }
            if (i + 1 <= n - 1) {
                if (visited[i + 1][j] == 1 && (i + 1 != pi) && a[i][j] == a[i + 1][j]) {
                    ans |= true;
                    return;
                } else if (visited[i + 1][j] == 0 && (i + 1 != pi) && a[i][j] == a[i + 1][j]) {
                    dfs(i + 1, j, i, j);
                }
            }
            if (j + 1 <= m - 1) {
                if (visited[i][j + 1] == 1 && (j + 1 != pj) && a[i][j] == a[i][j + 1]) {
                    ans |= true;
                    return;
                } else if (visited[i][j + 1] == 0 && (j + 1 != pj) && a[i][j] == a[i][j + 1]) {
                    dfs(i, j + 1, i, j);
                }
            }
            if (j - 1 >= 0) {
                if (visited[i][j - 1] == 1 && (j - 1 != pj) && a[i][j] == a[i][j - 1]) {
                    ans |= true;
                    return;
                } else if (visited[i][j - 1] == 0 && (j - 1 != pj) && a[i][j] == a[i][j - 1]) {
                    dfs(i, j - 1, i, j);
                }
            }
        }

        public void solve(int testNumber, Scanner sc, PrintWriter out) {
            n = sc.nextInt();
            m = sc.nextInt();
            a = new char[n][m];
            for (int i = 0; i < n; i++) {
                String s = sc.next();
                for (int j = 0; j < m; j++) {
                    a[i][j] = s.charAt(j);
                }
            }
            ans = false;
            visited = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (visited[i][j] == 0) {
                        dfs(i, j, -1, -1);
                    }
                }
            }
            if (ans == true) out.println("Yes");
            else out.println("No");
        }

    }
}

import java.util.Scanner;
import java.util.Stack;


public class CodeForce510B {
    static boolean yesOrNoFlag = false;
    static Stack<String> stack = new Stack<String>();
    public static void main(String[] args) {
        int n, m;
        String input;
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        sc.nextLine();

        String[][] list = new String[n + 2][m + 2];
        for (int i = 0; i < n + 2; i++) {
            list[i][0] = "-1";
            list[i][m + 1] = "-1";
        }
        for (int i = 0; i < m + 2; i++) {
            list[0][i] = "-1";
            list[n + 1][i] = "-1";
        }

        for (int i = 1; i < n + 1; i++) {
            input = sc.nextLine();
            for (int j = 1; j < m + 1; j++) {
                list[i][j] = input.split("")[j - 1];
            }

        }
        for (int i = 1; i < n + 1; i++) {
            for (int j = 1; j < m + 1; j++){
                if (list[i][j] != "-1") {
                    depthPrioritySearch(list, i, j);
                    zeroToMinus(list);
                }
            }
        }
        if (yesOrNoFlag) {
            System.out.print("Yes");
        }else {
            System.out.print("No");
        }
    }

    public static void zeroToMinus(String[][] list) {
        for (int i = 1; i < list.length - 1; i++) {
            for (int j = 1; j < list[i].length - 1; j++) {
                if (list[i][j] == "0") {
                    list[i][j] = "-1";
                }
            }
        }
    }

    public static void depthPrioritySearch(String[][] list, int x, int y) {
        if (yesOrNoFlag) {
            return;
        }
        String currentChar = list[x][y];
        String previousRow, previousCol;
        if (stack.size() == 0) {
            previousRow = "0";
            previousCol = "0";
        }else {
            previousRow = stack.peek().split(",")[0];
            previousCol = stack.peek().split(",")[1];
        }
        list[x][y] = "0";   
        stack.push(x + "," + y);    
        if (list[x - 1][y].equals(currentChar) &&
                !(x - 1 == Integer.parseInt(previousRow)&&
                        y == Integer.parseInt(previousCol))) {

            depthPrioritySearch(list,x - 1, y);
        }
        if(list[x + 1][y].equals(currentChar) &&
                !(x + 1 == Integer.parseInt(previousRow) &&
                        y == Integer.parseInt(previousCol))){

            depthPrioritySearch(list, x + 1, y);
        }
        if(list[x][y - 1].equals(currentChar) &&
                !(x == Integer.parseInt(previousRow) &&
                        y - 1 == Integer.parseInt(previousCol))){

            depthPrioritySearch(list, x, y - 1);
        }
        if(list[x][y + 1].equals(currentChar) &&
                !(x == Integer.parseInt(previousRow) &&
                        y + 1 == Integer.parseInt(previousCol))){

            depthPrioritySearch(list, x, y + 1);
        } 










        if (!(x - 1 == Integer.parseInt(previousRow) && y == Integer.parseInt(previousCol)) &&
                list[x - 1][y].equals("0")) {
            if (stack.search((x - 1) + "," + y) != -1) { 
                yesOrNoFlag = true;
            }
        }else if(!(x + 1 == Integer.parseInt(previousRow) && y == Integer.parseInt(previousCol)) &&
                list[x + 1][y].equals("0")){
            if (stack.search((x + 1) + "," + y) != -1) { 
                yesOrNoFlag = true;
            }
        }else if(!(x == Integer.parseInt(previousRow) && y - 1 == Integer.parseInt(previousCol)) &&
                list[x][y - 1].equals("0")){
            if (stack.search(x + "," + (y - 1)) != -1) { 
                yesOrNoFlag = true;
            }
        }else if(!(x == Integer.parseInt(previousRow) && y + 1 == Integer.parseInt(previousCol)) &&
                list[x][y + 1].equals("0")){
            if (stack.search(x + "," + (y + 1)) != -1) { 
                yesOrNoFlag = true;
            }
        }
        stack.pop();
        return;

    }





}

