    	  }
      }
       if(bool)out.println("Yes");else out.println("No");


    }

    void dfs(int la,int lb,int let,int pa,int pb){

    	vis[la][lb]=true;
    	for(int i = -1; i <= 1; i++){
    		for(int j = -1; j <= 1; j++){
    			if(Math.abs(i)+Math.abs(j) == 1){
    				int sa = la + i;
    				int sb = lb + j;

    				if(sa >= 0 && sb >= 0 && sa < n && sb < m && arr[sa][sb] == arr[la][lb] && (sa != pa || sb != pb) && vis[sa][sb] && let >= 4)
                        {bool=true;return;}
    				else if(sa >= 0 && sb >= 0 && sa < n && sb < m && arr[sa][sb] == arr[la][lb] && !vis[sa][sb] && !bool)
    					dfs(sa,sb,++let,la, lb);

    			}
    		}
    	}
    }
}

