public class FoxDots {
	public static void main(String[] ar) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] strnm = br.readLine().split(" ");
		int n = Integer.parseInt(strnm[0]);
		int m = Integer.parseInt(strnm[1]);

		char[][] graph = new char[n][m];
		for(int i=0; i<n; i++)
			graph[i] = br.readLine().toCharArray();

		boolean[][] visited = new boolean[n][m];
		HashMap<String, String> bfsParent = new HashMap<>();

		boolean cycleFound = false;

		for(int i=0; i<n; i++) {
			for(int j=0; j<m; j++) {
				if(visited[i][j])
					continue;


				Queue<String> q = new LinkedList<>();
				q.add(strFromCoords(i, j));
				bfsParent.put(strFromCoords(i, j), strFromCoords(i, j));

				while(!q.isEmpty()) {
					String currLoc = q.remove();
					int x = Integer.parseInt(currLoc.split("_")[0]);
					int y = Integer.parseInt(currLoc.split("_")[1]);
					visited[x][y] = true;
					char currVal = graph[x][y];

					String newLoc = strFromCoords(x-1, y);
					if(x > 0 && graph[x-1][y] == currVal && !bfsParent.get(currLoc).equals(newLoc)) {
						if(visited[x-1][y]) {
							cycleFound = true;
							break;
						}
						bfsParent.put(newLoc, currLoc);
						q.add(newLoc);

					}

					newLoc = strFromCoords(x, y-1);
					if(y > 0 && graph[x][y-1] == currVal && !bfsParent.get(currLoc).equals(newLoc)) {
						if(visited[x][y-1]) {
							cycleFound = true;
							break;
						}
						bfsParent.put(newLoc, currLoc);
						q.add(newLoc);
					}

					newLoc = strFromCoords(x+1, y);
					if(x < n-1 && graph[x+1][y] == currVal && !bfsParent.get(currLoc).equals(newLoc)) {
						if(visited[x+1][y]) {
							cycleFound = true;
							break;
						}
						bfsParent.put(newLoc, currLoc);
						q.add(newLoc);
					}

					newLoc = strFromCoords(x, y+1);
					if(y < m-1 && graph[x][y+1] == currVal && !bfsParent.get(currLoc).equals(newLoc)) {
						if(visited[x][y+1]) {
							cycleFound = true;
							break;
						}
						bfsParent.put(newLoc, currLoc);
						q.add(newLoc);
					}
				}
				if(cycleFound)
					break;
			}
			if(cycleFound)
				break;
		}
		if(cycleFound)
			System.out.println("Yes");
		else
			System.out.println("No");
	}

	static String strFromCoords(int x, int y) {
		return x + "_" + y;
	}
}

