public class CFB {
	static int n;
	static int m;
	static char[][] a;
	static int sx;
	static int sy;
	static int depth = 0;
	static boolean[][] used;
	static boolean die = false;
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		n = in.nextInt();
		m = in.nextInt();
		a = new char[n][m];
		for (int i = 0; i<n; i++){
			String inp = in.next();
			for (int j = 0; j<m; j++){
				a[i][j] = inp.charAt(j);
			}
		}
		for (int i = 0; i<n; i++){
			for (int j = 0; j<m; j++){
				used = new boolean[n][m];
				depth = 0;
				die = false;
				sy = i;
				sx = j;
				if (cycleSearchDFS(i, j)){
					System.out.println("Yes");
					return;
				}
			}
		}
		System.out.println("No");
	}
	static boolean cycleSearchDFS(int y, int x){
		depth++;
		used[y][x] = true;
		if (y+1==sy&&x==sx&&y+1<n&&a[y+1][x]==a[y][x]&&depth>=4) {
			die = true;
			return true;
		}
		if (y-1==sy&&x==sx&&y-1>=0&&a[y-1][x]==a[y][x]&&depth>=4){
			die = true;
			return true;
		}
		if (y==sy&&x+1==sx&&x+1<m&&a[y][x+1]==a[y][x]&&depth>=4){
			die = true;
			return true;
		}
		if (y==sy&&x-1==sx&&x-1>=0&&a[y][x-1]==a[y][x]&&depth>=4){
			die = true;
			return true;
		}
		if (y+1<n&&a[y+1][x]==a[y][x]&&!used[y+1][x]){
			cycleSearchDFS(y+1, x);
			if (die) return true;
			depth--;

		}
		if (y-1>=0&&a[y-1][x]==a[y][x]&&!used[y-1][x]){
			cycleSearchDFS(y-1, x);
			if (die) return true;
			depth--;

		}
		if (x+1<m&&a[y][x+1]==a[y][x]&&!used[y][x+1]){
			cycleSearchDFS(y, x+1);
			if (die) return true;
			depth--;

		}
		if (x-1>=0&&a[y][x-1]==a[y][x]&&!used[y][x-1]){
			cycleSearchDFS(y, x-1);
			if (die) return true;
			depth--;

		}
		return false;
	}

}

