    static class BFoxAndTwoDots {
        public static char grid[][] = new char[50][50];
        public static boolean isVisited[][] = new boolean[50][50];
        public static int n;
        public static int m;
        public static boolean cycleExists = false;

        public void solve(int testNumber, InputReader in, OutputWriter out) throws IOException {
            n = in.nextInt();
            m = in.nextInt();
            for (int i = 0; i < n; i++) {
                String S = in.nextLine();
                if (S.equals(""))
                    S = in.nextLine();
                for (int j = 0; j < m; j++)
                    grid[i][j] = S.charAt(j);
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!isVisited[i][j])
                        spread(i, j, -1, -1);
                }
            }
            out.printLine((cycleExists) ? "Yes" : "No");

        }

        public void spread(int x, int y, int x0, int y0) {
            isVisited[x][y] = true;
            if (x > 0 && (grid[x][y] == grid[x - 1][y])) {
                if (isVisited[x - 1][y] && (x - 1 != x0))
                    cycleExists = true;
                else if (!isVisited[x - 1][y])
                    spread(x - 1, y, x, y);
            }
            if (y > 0 && (grid[x][y] == grid[x][y - 1])) {
                if (isVisited[x][y - 1] && (y - 1 != y0))
                    cycleExists = true;
                else if (!isVisited[x][y - 1])
                    spread(x, y - 1, x, y);
            }
            if (x < n - 1 && (grid[x][y] == grid[x + 1][y])) {
                if (isVisited[x + 1][y] && (x + 1 != x0))
                    cycleExists = true;
                else if (!isVisited[x + 1][y])
                    spread(x + 1, y, x, y);
            }
            if (y < m - 1 && (grid[x][y] == grid[x][y + 1])) {
                if (isVisited[x][y + 1] && (y + 1 != y0))
                    cycleExists = true;
                else if (!isVisited[x][y + 1])
                    spread(x, y + 1, x, y);
            }
        }

    }

    static class InputReader {
        private static final int DEFAULT_BUFFER_SIZE = 1 << 16;
        private static final InputStream DEFAULT_STREAM = System.in;
        private int c;
        private byte[] buf;
        private int bufferSize;
        private int bufIndex;
        private int numBytesRead;
        private InputStream stream;
        private static final byte EOF = -1;
        private static final byte NEW_LINE = 10;
        private static final byte SPACE = 32;
        private static final byte DASH = 45;
        private char[] charBuffer;
        private static byte[] bytes = new byte[58];
        private static int[] ints = new int[58];
        private static char[] chars = new char[128];

        static {
            char ch = ' ';
            int value = 0;
            byte _byte = 0;
            for (int i = 48; i < 58; i++) bytes[i] = _byte++;
            for (int i = 48; i < 58; i++) ints[i] = value++;
            for (int i = 32; i < 128; i++) chars[i] = ch++;
        }

        public InputReader() {
            this(DEFAULT_STREAM, DEFAULT_BUFFER_SIZE);
        }

        public InputReader(int bufferSize) {
            this(DEFAULT_STREAM, bufferSize);
        }

        public InputReader(InputStream stream) {
            this(stream, DEFAULT_BUFFER_SIZE);
        }

        public InputReader(InputStream stream, int bufferSize) {
            if (stream == null || bufferSize <= 0)
                throw new IllegalArgumentException();
            buf = new byte[bufferSize];
            charBuffer = new char[128];
            this.bufferSize = bufferSize;
            this.stream = stream;
        }

        private byte read() throws IOException {

            if (numBytesRead == EOF) throw new IOException();

            if (bufIndex >= numBytesRead) {
                bufIndex = 0;
                numBytesRead = stream.read(buf);
                if (numBytesRead == EOF)
                    return EOF;
            }

            return buf[bufIndex++];
        }

        private int readJunk(int token) throws IOException {

            if (numBytesRead == EOF) return EOF;


            do {

                while (bufIndex < numBytesRead) {
                    if (buf[bufIndex] > token) return 0;
                    bufIndex++;
                }


                numBytesRead = stream.read(buf);
                if (numBytesRead == EOF) return EOF;
                bufIndex = 0;

            } while (true);

        }

        public int nextInt() throws IOException {

            if (readJunk(DASH - 1) == EOF) throw new IOException();
            int sgn = 1, res = 0;

            c = buf[bufIndex];
            if (c == DASH) {
                sgn = -1;
                bufIndex++;
            }

            do {

                while (bufIndex < numBytesRead) {
                    if (buf[bufIndex] > SPACE) {
                        res = (res << 3) + (res << 1);
                        res += ints[buf[bufIndex++]];
                    } else {
                        bufIndex++;
                        return res * sgn;
                    }
                }


                numBytesRead = stream.read(buf);
                if (numBytesRead == EOF) return res * sgn;
                bufIndex = 0;

            } while (true);

        }

        private void doubleCharBufferSize() {
            char[] newBuffer = new char[charBuffer.length << 1];
            for (int i = 0; i < charBuffer.length; i++) newBuffer[i] = charBuffer[i];
            charBuffer = newBuffer;
        }

        public String nextLine() throws IOException {

            try {
                c = read();
            } catch (IOException e) {
                return null;
            }
            if (c == NEW_LINE) return ""; 
            if (c == EOF) return null; 

            int i = 0;
            charBuffer[i++] = (char) c;

            do {

                while (bufIndex < numBytesRead) {
                    if (buf[bufIndex] != NEW_LINE) {
                        if (i == charBuffer.length) doubleCharBufferSize();
                        charBuffer[i++] = (char) buf[bufIndex++];
                    } else {
                        bufIndex++;
                        return new String(charBuffer, 0, i);
                    }
                }


                numBytesRead = stream.read(buf);
                if (numBytesRead == EOF)
                    return new String(charBuffer, 0, i);
                bufIndex = 0;

