public class Fox_And_two_dots {

	static int n;
	static int m;
	static char[][] input;
	public static void main(String[] args) throws IOException{
		InputStreamReader isr = new InputStreamReader(System.in);
		BufferedReader br = new BufferedReader(isr);
		String[] s = br.readLine().split(" ");
		n = Integer.parseInt(s[0]);
		m = Integer.parseInt(s[1]);
		input = new char[n][m];
		for(int i = 0 ; i < n; i++ )
		{
			input[i] = br.readLine().toCharArray();
		}
		boolean[][] status = new boolean[n][m];
		boolean found = false;
		outer : for(int i = 0; i < n; i++)
		{
			for(int j = 0 ; j < m; j++)
			{
				if(!status[i][j])
				{
					boolean[][] vis = new boolean[n][m];
					if(dfs(i,j,input[i][j],vis, i, j))
					{
						System.out.println("Yes");
						found = true;
						break outer;
					}
				}
			}
		}

		if(!found)
		{
			System.out.println("No");
		}
		br.close();


	}
	static boolean dfs(int i, int j, char c, boolean[][] vis, int pi, int pj)
	{
		if(input[i][j] != c)
		{
			return false;
		}
		if(vis[i][j])
		{
			return true;
		}

		vis[i][j] = true;

		if(j+1 < m)
		{
			if((i != pi || j+1 != pj ) && dfs(i,j+1,c,vis, i, j))
			{
				return true;
			}
		}
		if(i+1 < n)
		{
			if((i+1 != pi || j != pj ) && dfs(i+1,j,c,vis, i, j))
			{
				return true;
			}
		}

		if(j-1 >= 0)
		{
			if((i != pi || j-1 != pj ) && dfs(i,j-1,c,vis, i, j))
			{
				return true;
			}
		}

		if(i-1 >= 0)
		{
			if((i-1 != pi || j != pj ) && dfs(i-1,j,c,vis, i, j))
			{
				return true;
			}
		}
		return false;
	}

}

import java.io.IOException;
