public class FoxAndTwoDots {

	static class Solver {

		int N, M;
		int[][] grid;

		int[] dr = { -1, 0, 0, 1 };
		int[] dc = { 0, -1, 1, 0 };

		boolean dfs(int r, int c, int sr, int sc, int pr, int pc) {
			if (r == sr && c == sc && !(r == pr && c == pc))
				return true;
			for (int k = 0; k < 4; k++) {
				int rr = r + dr[k], cc = c + dc[k];
				if (rr < 0 || rr >= N || cc < 0 || cc >= M)
					continue;
				if (grid[r][c] != grid[rr][cc])
					continue;
				if (rr == pr && cc == pc)
					continue;
				if (dfs(rr, cc, sr, sc, r, c))
					return true;
			}
			return false;
		}

		void solve(FastScanner s, PrintWriter out) {
			N = s.nextInt();
			M = s.nextInt();
			grid = new int[N][M];
			for (int i = 0; i < N; i++) {
				char[] cc = s.next().toCharArray();
				for (int j = 0; j < M; j++)
					grid[i][j] = cc[j] - 'A';
			}

			for (int i = 0; i < N; i++) {
				for (int j = 0; j < M; j++) {
					if (dfs(i, j, i, j, i, j)) {
						out.println("Yes");
						return;
					}
				}
			}

			out.println("No");

		}

	}

	public static void main(String[] args) {
		FastScanner s = new FastScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		Solver solver = new Solver();
		solver.solve(s, out);

		out.close();
	}

	static class FastScanner {
		private InputStream stream;
		private byte[] buf = new byte[1024];
		private int curChar;
		private int numChars;

		public FastScanner(InputStream stream) {
			this.stream = stream;
		}

		int read() {
			if (numChars == -1)
				throw new InputMismatchException();
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = stream.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (numChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		boolean isSpaceChar(int c) {
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		boolean isEndline(int c) {
			return c == '\n' || c == '\r' || c == -1;
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public String next() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isSpaceChar(c));
			return res.toString();
		}

		public String nextLine() {
			int c = read();
			while (isEndline(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isEndline(c));
			return res.toString();
		}



		public int[] nextIntArray(int N) {
			int[] ret = new int[N];
			for (int i = 0; i < N; i++)
				ret[i] = this.nextInt();
			return ret;
		}

		public long[] nextLongArray(int N) {
			long[] ret = new long[N];
			for (int i = 0; i < N; i++)
				ret[i] = this.nextLong();
			return ret;
		}

		public int[][] next2DIntArray(int N, int M) {
			int[][] ret = new int[N][];
			for (int i = 0; i < N; i++)
				ret[i] = this.nextIntArray(M);
			return ret;
		}

		public double[] nextDoubleArray(int N) {
			double[] ret = new double[N];
			for (int i = 0; i < N; i++)
				ret[i] = this.nextDouble();
			return ret;
		}

		public double[][] next2DDoubleArray(int N, int M) {
			double[][] ret = new double[N][];
			for (int i = 0; i < N; i++)
				ret[i] = this.nextDoubleArray(M);
			return ret;
		}

	}

}

