      point [][]parent =new point [n][m];
      for(int i=0;i<n;i++)
      {
          for(int j=0;j<m;j++)
          {
              if(!visited[i][j] && a==0)
              {  char ch=graph[i][j];parent [i][j]=new point (-1,-1);f(visited,graph,m,n,i,j,ch,parent);}
          }
      }
      if(a==1)System.out.println("Yes");
      else System.out.println("No");
    }
    static void f(boolean [][] visited,char [][]graph,int m,int n,int i,int j,char ch,point [][]parent)
    {
        visited[i][j]=true;
        if(issafe(visited,graph,m,n,i+1,j,ch))   
        {
            if(visited[i+1][j]==true && !(parent[i][j].x==i+1 && parent [i][j].y==j)){a=1;return;}
            if(!visited[i+1][j]){parent[i+1][j]=new point(i,j);f(visited,graph,m,n,i+1,j,ch,parent);}

        }
        if(issafe(visited,graph,m,n,i-1,j,ch))   
        {
            if(visited[i-1][j]==true && !(parent[i][j].x==i-1 && parent [i][j].y==j)){a=1;return;}
            if(!visited[i-1][j]){parent[i-1][j]=new point(i,j);f(visited,graph,m,n,i-1,j,ch,parent);}

        }
        if(issafe(visited,graph,m,n,i,j+1,ch))   
        {
            if(visited[i][j+1]==true && !(parent[i][j].x==i && parent [i][j].y==j+1)){a=1;return;}
            if(!visited[i][j+1]){parent[i][j+1]=new point(i,j);f(visited,graph,m,n,i,j+1,ch,parent);}

        }
        if(issafe(visited,graph,m,n,i,j-1,ch))   
        {
            if(visited[i][j-1]==true && !(parent[i][j].x==i && parent [i][j].y==j-1)){a=1;return;}
            if(!visited[i][j-1]){parent[i][j-1]=new point(i,j);f(visited,graph,m,n,i,j-1,ch,parent);}

        }
    }
    static boolean issafe(boolean [][]visited,char [][]graph,int m,int n,int a,int b,char ch )

    {
        if(a>=0 && a<n && b>=0 && b<m && graph[a][b]==ch)
            return true;
        return false;
    }
