public class P510B {

  final static int [][] DXDY = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

  int n, m;
  char [][] desk = null;
  long [] cused = null;
  long [] used = null;

  boolean trace(int x, int y, int lx, int ly, char c) {
    if ((cused[y] & (1L << x)) != 0) {
      return true;
    }

    cused[y] |= (1L << x);

    for (int i = 0; i < DXDY.length; i++) {
      int nx = x + DXDY[i][0];
      int ny = y + DXDY[i][1];

      if ((nx >= 0) && (ny >= 0) && (nx < m) && (ny < n) &&
          (c == desk[ny][nx]) && ((nx != lx) || (ny != ly)) && trace(nx, ny, x, y, c)) {
        return true;
      }
    }

    return false;
  }

  @SuppressWarnings("unchecked")
  public void run() throws Exception {
    n = nextInt();
    m = nextInt();
    desk = new char [n][];
    for (int i = 0; i < n; i++) {
      desk[i] = next().toCharArray();
    }

    used = new long [n];

    for (int y = 0; y < n; y++) {
      for (int x = 0; x < m; x++) {
        if ((used[y] & (1L << x)) == 0) {
          cused = new long [n];

          if (trace(x, y, x, y, desk[y][x])) {
            println("Yes");
            return;
          }

          for (int i = 0; i < n; i++) {
            used[i] |= cused[i];
          }
        }
      }
    }

    println("No");
  }

