import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Set;

import static java.lang.Integer.valueOf;
import static java.util.Arrays.stream;


public class CF290B2 {
    private static class Pos {
        final int x;
        final int y;

        public Pos(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;

            Pos pos = (Pos) o;

            if (x != pos.x) return false;
            return y == pos.y;

        }

        @Override
        public int hashCode() {
            int result = x;
            result = 31 * result + y;
            return result;
        }
    }

    private static class Visit {
        final Pos pos;
        final Pos from;

        public Visit(Pos p, Pos from) {
            this.pos = p;
            this.from = from;
        }
    }

    private static final Pos[] moves = new Pos[]{new Pos(0, 1), new Pos(0, -1), new Pos(1, 0), new Pos(-1, 0)};

    private static Pos findPos(char[][] a, boolean[][] visited, int n, int m, char c) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] == c && !visited[i][j]) return new Pos(j, i);
            }
        }
        return null;
    }

    private static boolean solveChar(char[][] a, int n, int m, char c) {
        boolean[][] visited = new boolean[n][m];
        ArrayDeque<Visit> queue = new ArrayDeque<>();

        Pos pos = findPos(a, visited, n, m, c);
        while (pos != null) {
            queue.addLast(new Visit(pos, null));
            while (!queue.isEmpty()) {
                Visit visit = queue.removeFirst();
                if (visited[visit.pos.y][visit.pos.x]) return true;
                visited[visit.pos.y][visit.pos.x] = true;
                for (Pos move: moves) {
                    Pos newPos = new Pos(visit.pos.x + move.x, visit.pos.y + move.y);
                    if (newPos.y >= 0 && newPos.y < n &&
                            newPos.x >= 0 && newPos.x < m &&
                            a[newPos.y][newPos.x] == c &&
                            !newPos.equals(visit.from)) {
                        queue.addLast(new Visit(newPos, visit.pos));
                    }
                }
            }
            pos = findPos(a, visited, n, m, c);
        }

        return false;
    }

    private static String solve(char[][] a, int n, int m) {
        Set<Character> chars = new HashSet<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                chars.add(a[i][j]);
            }
        }
        for (char c: chars) {
            boolean res = solveChar(a, n, m, c);
            if (res) return "Yes";
        }
        return "No";
    }

    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        String[] st = in.readLine().split(" ");
        int n = valueOf(st[0]);
        int m = valueOf(st[1]);
        char[][] a = new char[n][];
        for (int i = 0; i < n; i++) {
            a[i] = new char[m];
            String s = in.readLine();
            a[i] = s.toCharArray();
        }
        System.out.println(solve(a, n, m));
   }
}

