public class B {
    int n;
    int m;
    char[][] ch;
    boolean[][] v;
    public boolean res;

    public static void main(String[] args) {
        B cf = new B();
        if (cf.res) System.out.println("Yes");
        else System.out.println("No");
    }

    B() {
        try{
            Scanner in = new Scanner(System.in);
            PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            n = in.nextInt();
            m = in.nextInt();
            ch = new char[n][m];
            v = new boolean[n][m];
            for(int i = 0; i < n; i++){
                String str = in.next();
                for(int j = 0; j < m; j++){
                    ch[i][j] = str.charAt(j);
                }
            }

            Stack<Node> st = new Stack<Node>();
            boolean result = false;
            int a1, b1;
            for (int i = 0; i < n && !result; i++) {
                for (int j = 0; j < m && !result; j++) {
                    if(!v[i][j]) {
                        v[i][j] = true;
                        st.push(new Node(i,j,-1));
                        while (!st.empty() && !result) {
                            Node node = st.peek();
                            if(node.hasNext()) {
                                a1 = node.a();
                                b1 = node.b();
                                if (v[a1][b1]) {
                                    if (node.checkDir()) {
                                        result = true;
                                    }
                                } else {
                                    v[a1][b1] = true;
                                    st.push(new Node(a1, b1, node.d()));
                                }
                            } else {
                                st.pop();
                            }

                        } 
                    } 
                }
            }
            res = result;
        }catch(Exception e){}
    }

    private class Node {
        public int a;
        public int b;
        private int direction = -1;
        public int prev;
        Node(int a, int b, int prev) {this.a = a; this.b = b; this.prev = prev;}
        public boolean hasNext() {
            direction++;
            if (direction > 3) return false;
            int a1 = a();
            int b1 = b();
            if (checkAB(a1, b1)) {
                if (ch[a][b] == ch[a1][b1]) return true;
                else return hasNext();
            } else {
                return hasNext();
            }
        }

        public int a() {
            switch (direction) {
                case 0: return a - 1;
                case 1: return a;
                case 2: return a + 1;
                case 3: return a;
                default: return -1;
            }
        }

        public int b() {
            switch (direction) {
                case 0: return b;
                case 1: return b + 1;
                case 2: return b;
                case 3: return b - 1;
                default: return -1;
            }
        }

        public int d() { return direction; }

        public boolean checkAB(int a, int b) {
            if (a >=0 && a < n && b >= 0 && b < m) return true;
            return false;
        }

        public boolean checkDir() {
            switch(prev) {
                case -1: return true;
                case 0: return direction != 2;
                case 1: return direction != 3;
                case 2: return direction != 0;
                case 3: return direction != 1;
                default: return false;
            }
        }
    }
}

