    static void sort(int[] a, int low, int high) 
    {
        int N = high - low;         
        if (N <= 1) 
            return; 
        int mid = low + N/2; 
        sort(a, low, mid); 
        sort(a, mid, high); 
        int[] temp = new int[N];
        int i = low, j = mid;
        for (int k = 0; k < N; k++) 
        {
            if (i == mid)  
                temp[k] = a[j++];
            else if (j == high) 
                temp[k] = a[i++];
            else if (a[j]<a[i]) 
                temp[k] = a[j++];
            else 
                temp[k] = a[i++];
        }    
        for (int k = 0; k < N; k++) 
            a[low + k] = temp[k];         
    }
    static void lsort(long[] a, int low, int high) 
    {
        int N = high - low;         
        if (N <= 1) 
            return; 
        int mid = low + N/2; 
        lsort(a, low, mid); 
        lsort(a, mid, high); 
        long[] temp = new long[N];
        int i = low, j = mid;
        for (int k = 0; k < N; k++) 
        {
            if (i == mid)  
                temp[k] = a[j++];
            else if (j == high) 
                temp[k] = a[i++];
            else if (a[j]<a[i]) 
                temp[k] = a[j++];
            else 
                temp[k] = a[i++];
        }    
        for (int k = 0; k < N; k++) 
            a[low + k] = temp[k];         
    }
    public static long fexp(long x, long y, long p) {
        long res = 1;      


        x = x % p;  

        while (y > 0) 
        { 

            if((y & 1)==1) 
                res = (res * x) % p; 


            y = y >> 1;  
            x = (x * x) % p;  
        } 
        return res; 

    }
    static int gcd(int a, int b) 
    { 
        if (b == 0) 
            return a; 
        return gcd(b, a % b);  

    }
    static long lgcd(long a, long b) 
    { 
        if (b == 0) 
            return a; 
        return lgcd(b, a % b);  

    }

}

import java.util.Scanner;

public class FoxAndTwoDots {

	static boolean ret = false;

	public static void dfs(char[][] adj, boolean[][] vis, int prevx, int prevy, int x, int y) {
		vis[x][y] = true;

		if (x > 0 && adj[x][y] == adj[x - 1][y] && !vis[x - 1][y]) {
			dfs(adj, vis, x, y, x - 1, y);
		} else if (x > 0 && adj[x][y] == adj[x - 1][y] && vis[x - 1][y] && prevx != x - 1 && prevy != y) {
			ret = true;
			return;
		}

		if (y > 0 && adj[x][y] == adj[x][y - 1] && !vis[x][y - 1]) {
			dfs(adj, vis, x, y, x, y - 1);
		} else if (y > 0 && adj[x][y] == adj[x][y - 1] && vis[x][y - 1] && prevx != x && prevy != y - 1) {
			ret = true;
			return;
		}

		if (x < adj.length - 1 && adj[x][y] == adj[x + 1][y] && !vis[x + 1][y]) {
			dfs(adj, vis, x, y, x + 1, y);
		} else if (x < adj.length - 1 && adj[x][y] == adj[x + 1][y] && vis[x + 1][y] && prevx != x + 1 && prevy != y) {
			ret = true;
			return;
		}

		if (y < adj[0].length - 1 && adj[x][y] == adj[x][y + 1] && !vis[x][y + 1]) {
			dfs(adj, vis, x, y, x, y + 1);
		} else if (y < adj[0].length - 1 && adj[x][y] == adj[x][y + 1] && vis[x][y + 1] && prevx != x
				&& prevy != y + 1) {
			ret = true;
			return;
		}

	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();

		char[][] adj = new char[n][m];
		for (int i = 0; i < n; i++)
			adj[i] = sc.next().toCharArray();

		boolean[][] vis = new boolean[n][m];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (!vis[i][j]) {
					dfs(adj, vis, -1, -1, i, j);
				}
			}
		}

		System.out.println(ret ? "Yes" : "No");

	}

}

