import java.io.*;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

public class School {

    public static class Point {
        int x;
        int y;

        public Point() {};
        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object obj) {
            Point p = (Point) obj;

            return x == p.x && y == p.y;
        }

        @Override
        public String toString() {
            return "[" + x + ", " + y + "]";
        }
    }

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int[] diffX = {1, -1, 0, 0};
        int[] diffY = {0, 0, 1, -1};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                Point start = new Point(i, j);

                for (int l = 0; l < diffX.length; l++) {
                    if (check(grid, start.x + diffX[l], start.y + diffY[l]) && grid[i][j] == grid[i + diffX[l]][j + diffY[l]]) {
                        boolean[][] used = new boolean[n][m];
                        Point second = new Point(start.x + diffX[l], start.y + diffY[l]);

                        Queue<Point> queue = new LinkedList<>();
                        queue.add(second);
                        used[start.x][start.y] = true;
                        used[second.x][second.y] = true;

                        while (!queue.isEmpty()) {
                            Point p = queue.poll();

                            for (int k = 0; k < diffX.length; k++) {
                                Point next = new Point(p.x + diffX[k], p.y + diffY[k]);

                                if (check(grid, next) && grid[p.x][p.y] == grid[p.x + diffX[k]][p.y + diffY[k]]) {
                                    if (!p.equals(second) && next.equals(start)) {

                                        out.println("Yes");
                                        out.close();
                                        return;
                                    } else {
                                        if (!used[next.x][next.y]) {
                                            queue.add(next);
                                        }

                                        used[next.x][next.y] = true;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        out.println("No");
        out.close();
    }

    public static boolean isNeighbour(int fX, int fY, int sX, int sY) {
        return (Math.abs(fX - sX) == 1 && (fY - sY == 0)) || (Math.abs(fY - sY) == 1 && (fX - sX == 0));
    }

    public static boolean check(char[][] arr, int x, int y) {
        return x >= 0 && x < arr.length && y >= 0 && y < arr[0].length;
