public class Solution {

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    static void print(Object s) {
        System.out.println(s);
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();

        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] a = new char[n][m];
        int[][] visited = new int[n][m];
        for(int i = 0; i < n; i++){
            a[i] = sc.next().toCharArray();
            Arrays.fill(visited[i], 0);
        }

        boolean cycle = false;
        for(int i = 0; i < n && !cycle; i++){
            for(int j = 0; j < m; j++){
                if(visited[i][j] == 0){
                    cycle |= dfs(a, visited, i , j, -1, -1);
                }
            }
        }
        print(cycle ? "Yes" : "No");
    }

    static boolean dfs(char[][] a, int[][] visited, int r, int c, int parentR, int parentC){
        visited[r][c] = 1;

        if(isValid(r, c+1, visited.length, visited[0].length) && (a[r][c+1] == a[r][c])){
            if(visited[r][c+1] == 0){
                if (dfs(a, visited, r, c+1, r, c))  return true;
            }
            else if(visited[r][c+1] == 1 && parentR != r && parentC != c+1)    return true;
        }

        if(isValid(r+1, c, visited.length, visited[0].length) && (a[r+1][c] == a[r][c])){
            if(visited[r+1][c] == 0){
                if (dfs(a, visited, r+1, c, r, c))  return true;
            }
            else if(visited[r+1][c] == 1 && parentR != r+1 && parentC != c)    return true;
        }

        if(isValid(r, c-1, visited.length, visited[0].length) && (a[r][c-1] == a[r][c])){
            if(visited[r][c-1] == 0){
                if (dfs(a, visited, r, c-1, r, c))  return true;
            }
            else if(visited[r][c-1] == 1 && parentR != r && parentC != c-1)    return true;
        }

        if(isValid(r-1, c, visited.length, visited[0].length) && (a[r-1][c] == a[r][c])){
            if(visited[r-1][c] == 0){
                if (dfs(a, visited, r-1, c, r, c))  return true;
            }
            else if(visited[r-1][c] == 1 && parentR != r-1 && parentC != c)    return true;
        }

        return false;
    }

    static boolean isValid(int r, int c, int n, int m){
        return r>=0 && c>=0 && r<n && c<m;
    }
}

