        public Reader() 
        { 
            din = new DataInputStream(System.in); 
            buffer = new byte[BUFFER_SIZE]; 
            bufferPointer = bytesRead = 0; 
        } 

        public Reader(String file_name) throws IOException 
        { 
            din = new DataInputStream(new FileInputStream(file_name)); 
            buffer = new byte[BUFFER_SIZE]; 
            bufferPointer = bytesRead = 0; 
        } 

        public String readLine() throws IOException 
        { 
            byte[] buf = new byte[64]; 
            int cnt = 0, c; 
            while ((c = read()) != -1) 
            { 
                if (c == '\n') 
                    break; 
                buf[cnt++] = (byte) c; 
            } 
            return new String(buf, 0, cnt); 
        } 

        public int nextInt() throws IOException 
        { 
            int ret = 0; 
            byte c = read(); 
            while (c <= ' ') 
                c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 
            do
            { 
                ret = ret * 10 + c - '0'; 
            }  while ((c = read()) >= '0' && c <= '9'); 

            if (neg) 
                return -ret; 
            return ret; 
        } 

        public long nextLong() throws IOException 
        { 
            long ret = 0; 
            byte c = read(); 
            while (c <= ' ') 
                c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 
            do { 
                ret = ret * 10 + c - '0'; 
            } 
            while ((c = read()) >= '0' && c <= '9'); 
            if (neg) 
                return -ret; 
            return ret; 
        } 

        public double nextDouble() throws IOException 
        { 
            double ret = 0, div = 1; 
            byte c = read(); 
            while (c <= ' ') 
                c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 

            do { 
                ret = ret * 10 + c - '0'; 
            } 
            while ((c = read()) >= '0' && c <= '9'); 

            if (c == '.') 
            { 
                while ((c = read()) >= '0' && c <= '9') 
                { 
                    ret += (c - '0') / (div *= 10); 
                } 
            } 

            if (neg) 
                return -ret; 
            return ret; 
        } 

        private void fillBuffer() throws IOException 
        { 
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE); 
            if (bytesRead == -1) 
                buffer[0] = -1; 
        } 

        private byte read() throws IOException 
        { 
            if (bufferPointer == bytesRead) 
                fillBuffer(); 
            return buffer[bufferPointer++]; 
        } 

        public void close() throws IOException 
        { 
            if (din == null) 
                return; 
            din.close(); 
        } 
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Set;
import java.util.StringTokenizer;

public class CF290B {
	private FastScanner in;
	private PrintWriter out;

	static int n, m;
	static char[][] ar;
	static final int[][] dir = new int[][]{{1,0}, {-1,0}, {0,1}, {0,-1}};
	public void solve() throws IOException {
		n = in.nextInt();
		m = in.nextInt();
		ar = new char[n][m];
		for (int i = 0; i < n; i++){
			char[] s = in.next().toCharArray();
			for (int j = 0; j < m; j++){
				ar[i][j] = s[j];
			}
		}
		if (hasCycle(ar)) { out.println("Yes"); return; }
		out.println("No");
	}

	static boolean hasCycle(char[][] board) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[0].length; j++) {
                if (board[i][j] != '#' && bfs(board, i, j)) return true;
            }
        }
        return false;
    }

    static boolean bfs(char[][] board, int x, int y) {
        char color = board[x][y];
        Set<Integer> pending = new HashSet<>();
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(x); queue.offer(y);
        while (!queue.isEmpty()) {
            int cx = queue.poll(), cy = queue.poll();
            board[cx][cy] = '#';
            pending.remove(cx*board[0].length + cy);
            for (int[] d : dir) {
                int nx = cx + d[0], ny = cy + d[1];
                if (nx >= 0 && nx < board.length && 
                		ny >= 0 && ny < board[0].length
                        	&& board[nx][ny] == color) {
                    if (pending.add(nx*board[0].length + ny)) {
                        queue.offer(nx); queue.offer(ny);
                    } 
                    else 
                    	return true;
                }
            }
        }
        return false;
    }

	public static boolean isValid(int x, int y){
		if (x < 0 || y < 0 || x >= n || y >= m){
			return false;
		}
		return true;
	}

	public static void main(String[] args) {
		new CF290B().run();
	}

	public void run() {
		try {
			in = new FastScanner();
			out = new PrintWriter(System.out);
			solve();
			out.close();
		} catch (IOException e) {
			e.printStackTrace();
		}
	}

	private class FastScanner {
		private BufferedReader br;
		private StringTokenizer st;

		public FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}
	}
}

