public class Main {

    static int time = 0;


    public static void main(String[] args) throws IOException {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new PrintWriter(System.out));


        String[] ln1 = br.readLine().split(" ");

        int n = Integer.parseInt(ln1[0]);
        int m = Integer.parseInt(ln1[1]);

        int[][] D = new int[n][m];

        for(int i=0;i<n;i++){
            String ln2 = br.readLine();
            for(int j=0;j<m;j++){
                D[i][j] = (int) (ln2.charAt(j) - 64);

            }

        }



        bw.append(solve(D)+"\n");
        bw.close();
    }

    private static String solve(int[][] D) {

        int n = D.length;
        int m = D[0].length;

        int[][] seen = new int[n][m];
        boolean[][] val = new boolean[n][m];
        Parent[][] p = new Parent[n][m];
        Parent stubp = new Parent(-1,-1);

        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){

                p[i][j] = stubp;
            }
        }

        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(seen[i][j] == 0){
                    val[i][j] = dfs(i,j,seen,val,D,p);
                    if(val[i][j])   break;
                }
            }
        }

        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(val[i][j])   return "Yes";
            }
        }

        return "No";

    }

    private static boolean dfs(int i, int j, int[][] seen, boolean[][] val, int[][] D, Parent[][] P) {

        seen[i][j] = 1;
        ArrayList<int[]> A = new ArrayList();
        int[] first = {i-1,j};
        int[] second = {i,j+1};
        int[] third = {i+1,j};
        int[] fourth = {i,j-1};



        A.add(first);A.add(second);A.add(third);A.add(fourth);



        for(int cnt=0; cnt<4; cnt++){

            int[] child = A.get(cnt);

            if((child[0] >= 0 && child[0] < seen.length && child[1]>=0 && child[1] < seen[0].length) && (D[i][j] == D[child[0]][child[1]])){

                int[] stub = {child[0],child[1]};

                if(seen[child[0]][child[1]] == 0){

                    P[child[0]][child[1]] = new Parent(i,j); 

                    val[child[0]][child[1]] = dfs(child[0],child[1],seen,val,D,P);
                }else if(!(P[i][j].p[0]==stub[0] && P[i][j].p[1] == stub[1])){

                    val[i][j] = true;
                }
            }

        }

        return val[i][j];
    }


    private static class Parent{

    int[] p;
    public Parent(int i, int j){
        this.p = new int[2];
        p[0] = i;p[1]=j;
    }
}




}

