import java.util.Scanner;

public class Code2Feb02 {

    public static void main(String[] args) {
        solve();
    }

    static int n, m;

    static char[][] array = new char[55][55];
    static int[][] visitedNodes = new int[55][55];
    static int[][][] previous = new int[55][55][2];

    static void solve() {
        read();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if(visitedNodes[i][j] == 0) {
                    breathFirstSearch(i, j);
                }
            }
        }

        System.out.println("No");
    }



    static void read() {
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        m = in.nextInt();

        in.nextLine();
        for(int i = 0 ; i < n; i++) {
            array[i] = in.nextLine().toCharArray();
        }
    }

    void printVisited() {
        for(int i = 0; i < n; i++) {
            for(int j = 0 ; j < m; j++) {
                System.out.print(visitedNodes[i][j] + " ");
            }
            System.out.println();
        }
    }

    static void breathFirstSearch(int x, int y) {
        int[][] queue = new int[n*m][2];
        int end = 0;

        queue[end][0] = x;
        queue[end][1] = y;
        visitedNodes[x][y] = 1;
        previous[x][y][0] = -1;
        previous[x][y][1] = -1;

        end++;
        for(int i = 0; i < end; i++) {
            x = queue[i][0];
            y = queue[i][1];
            if(x+1 < n && array[x+1][y] == array[x][y]) {
                if(visitedNodes[x+1][y] == 0) {
                    queue[end][0] = x+1;
                    queue[end][1] = y;
                    visitedNodes[x+1][y] = 1;
                    previous[x+1][y][0] = x;
                    previous[x+1][y][1] = y;
                    end++;
                } else {
                    if (!(previous[x][y][0] == x+1 && previous[x][y][1] == y)) {
                        System.out.println("Yes");
                        System.exit(0);
                    }
                }
            }

            if(x-1 >= 0 && array[x-1][y] == array[x][y]) {
                if(visitedNodes[x-1][y] == 0) {
                    queue[end][0] = x-1;
                    queue[end][1] = y;
                    visitedNodes[x-1][y] = 1;
                    previous[x-1][y][0] = x;
                    previous[x-1][y][1] = y;
                    end++;
                } else {
                    if (!(previous[x][y][0] == x-1 && previous[x][y][1] == y)) {
                        System.out.println("Yes");
                        System.exit(0);
                    }
                }
            }

            if(y+1 < m && array[x][y+1] == array[x][y]) {
                if(visitedNodes[x][y+1] == 0) {
                    queue[end][0] = x;
                    queue[end][1] = y+1;
                    visitedNodes[x][y+1] = 1;
                    previous[x][y+1][0] = x;
                    previous[x][y+1][1] = y;
                    end++;
                } else {
                    if (!(previous[x][y][0] == x && previous[x][y][1] == y+1)) {
                        System.out.println("Yes");
                        System.exit(0);
                    }
                }
            }

            if(y-1 >= 0 && array[x][y-1] == array[x][y]) {
                if(visitedNodes[x][y-1] == 0) {
                    queue[end][0] = x;
                    queue[end][1] = y-1;
                    visitedNodes[x][y-1] = 1;
                    previous[x][y-1][0] = x;
                    previous[x][y-1][1] = y;
                    end++;
                }else {
                    if (!(previous[x][y][0] == x && previous[x][y][1] == y-1)) {
                        System.out.println("Yes");
                        System.exit(0);
                    }
                }
            }
        }

    }

}

