public class CF510B_FoxAndTwoDots {
    public static void main(String[] args){
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int m = in.nextInt();
        int[] dx = {1,-1,0,0};
        int[] dy = {0,0,1,-1};
        int[] key = {1, 0, 3, 2};

        char[][] map = new char[n][m];
        for(int i = 0; i < n; i ++){
            String s = in.next();
            for(int j = 0; j < m; j ++){
                map[i][j] = s.charAt(j);
            }
        }

        boolean ans = false;
        Queue<State> q = new LinkedList<State>();
        int[][] vis = new int[n][m];
        for(int i = 0; i < n; i ++) Arrays.fill(vis[i], -1);

        for(int i = 0; i < n; i ++){
            for(int j = 0; j < m; j ++){
                if(vis[i][j] != -1) continue;
                q.add(new State(i, j, -1));
                vis[i][j] = 0;
                while(!q.isEmpty()){
                    State at = q.poll();
                    for(int k = 0; k < 4; k ++){
                        if(k == at.d) continue;
                        int nx = at.x + dx[k];
                        int ny = at.y + dy[k];
                        if(!(nx < n && nx > -1 && ny < m && ny > -1) || map[at.x][at.y]!= map[nx][ny])
                            continue;
                        if(vis[nx][ny] != -1){

                            ans = true;
                            break;
                        }
                        vis[nx][ny] = vis[at.x][at.y] + 1;
                        q.add(new State(nx, ny, key[k]));
                    }
                    if(ans)break;
                }
            }
        }

        System.out.println(ans ? "Yes" : "No");

    }

    public static class State{
        int d;
        int x;
        int y;
        State(int xv, int yv, int dir){
            d = dir;
            x = xv;
            y = yv;
        }
    }
}

