class TaskB {
    int dx[] = {-1, 0, 0, 1};
    int dy[] = {0, 1, -1, 0};
    boolean discovered[][];
    boolean processed[][];
    int n;
    int m;

    public void solve(int testNumber, Scanner in, PrintWriter out) {
        n = in.nextInt();
        m = in.nextInt();
        char[][] table = new char[n][m];
        in.nextLine();
        for (int i = 0; i < n; i++) {
            String row = in.nextLine();
            for (int j = 0; j < m; j++) {
                table[i][j] = row.charAt(j);
            }
        }


        boolean found = false;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                discovered = new boolean[n][m];
                processed = new boolean[n][m];
                found |= dfs(i, j, -1, -1, table);
            }
        }

        if (found)
            out.print("Yes");
        else
            out.print("No");
    }

    private boolean dfs(int x, int y, int prevx, int prevy, char[][] table) {
        discovered[x][y] = true;
        boolean res = false;
        for (int dir = 0; dir < dx.length; dir++) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m && !(nx == prevx && ny == prevy) && table[nx][ny] == table[x][y]) {
                if (discovered[nx][ny])
                    return true;
                res|= dfs(nx, ny, x, y, table);
            }
        }
        return false;
    }
}

