public class TaskB
{
    private static int dx[] = {0, 1, 0, -1};
    private static int dy[] = {1, 0, -1, 0};

    Scanner in;
    PrintWriter out;
    int n, m;
    List<String> field;
    boolean used[][];
    boolean cycleFound = false;

    public static void main(String[] args)
    {
        TaskB mainTest = new TaskB();

        mainTest.readData();
        mainTest.solve();
        mainTest.outputData();
    }

    public TaskB()
    {
        in = new Scanner(System.in);
        out = new PrintWriter(new OutputStreamWriter(System.out));
    }

    public void readData()
    {
        n = in.nextInt();
        m = in.nextInt();

        field = new ArrayList<String>();

        for (int i = 0; i < n; i++) {
            String s = in.next();
            field.add(s);
        }
    }

    private void dfs(int row, int column, int prevRow, int prevColumn) {
        used[row][column] = true;

        for (int i = 0; i < 4; i++) {
            int newX = row + dx[i];
            int newY = column + dy[i];

            if (newX >= 0 && newX < n && newY >= 0 && newY < m) {
                if (field.get(row).charAt(column) == field.get(newX).charAt(newY) && (newX != prevRow || newY != prevColumn)) {
                    if (used[newX][newY]) {
                        cycleFound = true;
                    } else {
                        dfs(newX, newY, row, column);
                    }
                }
            }
        }

    }

    public void solve()
    {
        used = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!used[i][j]) {
                    dfs(i, j , i, j);
                }
            }
        }
    }

    public void outputData()
    {
        out.println(cycleFound ? "Yes" : "No");
        out.flush();
    }
}

