	                    visit[arr[i][j]]=true;
	                    int nr[]={0,0,-1,1};
	                    int nc[]={-1,1,0,0};
	                    for(int k=0;k<4;k++)
	                    {
	                        boolean ok=safe(i+nr[k],j+nc[k]);
	                        if(ok)
	                        {
	                            if(arr[i+nr[k]][j+nc[k]]==0)
	                            {
	                                ok=false;
	                            }
	                        }

	                        if(ok)
	                        {
	                            ls[arr[i][j]].add(arr[i+nr[k]][j+nc[k]]);
	                            ls[arr[i+nr[k]][j+nc[k]]].add(arr[i][j]);
	                            visit[arr[i+nr[k]][j+nc[k]]]=true;
	                        }
	                    }
	                }
	            }
	        }
	    }

	}
	public boolean safe(int x,int y)
	{
	    if(x>=0 && x<n && y>=0 && y<m )
	    {
	        return true;
	    }
	    return false;
	}
}

