public class cf_290_b {
    private FastScanner in;
    private PrintWriter out;

    int[] dx = {-1,1,0,0};
    int[] dy = {0,0,1,-1};
    public void solve() throws IOException {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] c = new char[n][m];
        for (int i=0; i<n; i++){
            char[] temp = in.next().toCharArray();
            for (int j=0; j<m; j++){
                c[i][j] = temp[j];
            }
        }

        boolean[][] visited = new boolean[n][m];
        boolean[][] searched = new boolean[n][m];
        int[][] step = new int[n][m];

        for (int i=0; i<n; i++){
            for (int j=0; j<m; j++){
                if (searched[i][j]) continue;
                step[i][j] = 1;
                if (DFS(c, searched, visited, 1, i, j, c[i][j], step)){
                    out.print("Yes");
                    return;
                }
            }
        }

        out.print("No");
        return;
    }

    boolean DFS(char[][] c, boolean[][] searched, boolean[][] visited, int curStep, int x, int y, char curChar, int[][] step){
        visited[x][y] = true;
        searched[x][y] = true;
        step[x][y] = curStep;

        for (int i=0; i<4; i++){
            int newx = x+dx[i];
            int newy = y+dy[i];
            if(newx<0 || newy<0 || newx>=c.length || newy>=c[0].length || c[newx][newy]!=curChar)   continue;

            if (visited[newx][newy] && Math.abs(curStep - step[newx][newy])>=3){
                return true;
            }

            if (!visited[newx][newy]){
                if (DFS(c, searched, visited, curStep+1, newx, newy, curChar, step)){
                    return true;
                }
            }
        }

        visited[x][y] = false;
        return false;
    }


    public void run() {
        try {
            in = new FastScanner();
            out = new PrintWriter(System.out);
            solve();
            out.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

