    int m;
    char[][] map;
    boolean[][] vis;
    boolean hasCycle = false;
    int[] dx = {-1, 1, 0, 0};
    int[] dy = {0, 0, -1, 1};
    void solve() throws IOException {
        n = nextInt();
        m = nextInt();
        vis = new boolean[n][m];

        map = new char[n][m];
        for(int i = 0; i < n; i++) {
            map[i] = nextString().toCharArray();
        }

        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                if(!vis[i][j]) {
                    dfs(i, j, -1, -1, map[i][j]);
                }
            }
        }

        if(hasCycle) {
            out("Yes");
        }
        else {
            out("No");
        }
    }
    void dfs(int toX, int toY, int fromX, int fromY, char c) {
        if(toX < 0 || toX >= n || toY < 0 || toY >= m) {
            return;
        }
        if(map[toX][toY] != c) {
            return;
        }
        if(vis[toX][toY]) {
            hasCycle = true;
            return;
        }
        vis[toX][toY] = true;
        for(int i = 0; i < dx.length; i++) {
            int newX = toX + dx[i];
            int newY = toY + dy[i];
            if(newX == fromX && newY == fromY) {
                continue;
            }
            dfs(newX, newY, toX, toY, c);
        }
    }
    void shuffle(int[] a) {
        int n = a.length;
        for(int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }
