class Vertex{
    boolean visited;
    int parent;
    int rank;
    char label;
    Vertex(char a,int n)
    {
        label=a;
        rank=0;
        parent=n;
        visited=false;
    }
}

class Edge{
    int src,dest;
    Edge(int a,int b)
    {
        src=a;
        dest=b;
    }
}

class Graph{

    Vertex vertex[];
    Edge edge[];
    int adg[][];
    int nvertex;
    int e;
    int flag;
    Graph()
    {
        vertex=new Vertex[5000];
        edge=new Edge[10];
        adg=new int[3000][3000];
        nvertex=0;
        e=0;
        flag=0;
    }

    void addvertex(char a)
    {
        vertex[nvertex]=new Vertex(a,nvertex++);
    }
    void addedge(int a,int b)
    {
        edge[e++]=new Edge(a,b);
    }

    public int find(int a){
        if(a!=vertex[a].parent)
            vertex[a].parent=find(vertex[a].parent);
        return vertex[a].parent;

    }

    void union(int a,int b)
    {
        if(vertex[a].label!=vertex[b].label)
            return;
        int x=find(a);
        int y=find(b);

        if(x==y)
        {

            flag=1;
            return;

        }
        if(vertex[x].rank > vertex[y].rank)
            vertex[y].parent=x;
        else if(vertex[y].rank > vertex[x].rank)
            vertex[x].parent=y;
        else{
            vertex[y].parent=x;
            vertex[x].rank++;
        }
    }
}

