    static class TaskC {

        private static int[] e = {1,-1,0,0};
        private static int[] f = {0,0,1,-1};

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] graph = new char[n][m];
            for(int i = 0;i < n; i++){
                String s = in.next();
                for(int j = 0; j < m;j++){
                    graph[i][j] = s.charAt(j);
                }
            }

            boolean[][] visited = new boolean[n][m];

            boolean res = false;

            search_loop:
            for(int i = 0; i < n; i++){
                for(int j = 0; j < m; j++){
                    if(visited[i][j]) continue;
                    if(isCycle(graph, i, j,visited, graph[i][j], i, j)){
                        res = true;
                        break search_loop;
                    }
                }
            }

            if(res)
                out.println("Yes");
            else
                out.println("No");

        }

        private static boolean isCycle(char[][] graph, int i, int j, boolean[][] visited, char a, int c, int d){
            if(i < 0 || j < 0 || i > graph.length - 1 || j > graph[0].length - 1){
                return false;
            }

            if(graph[i][j] != a)
                return false;

            if(visited[i][j]) return true;

            visited[i][j] = true;

            for(int k = 0; k < 4; k++){
                int g = i + e[k];
                int h = j + f[k];
                if(g != c || h != d){
                    if(isCycle(graph, g, h, visited, a, i, j))
                        return true;
                }
            }

            visited[i][j] = false;

            return false;

        }

    }

