                count += 1 ;
            }
        }
        LinkedList <pair> box = new LinkedList() ;
        pair cob = new pair(0,-10);
        box.add(cob);
        boolean[] visited = new boolean[s*c];
        Arrays.fill(visited,false);
        visited[0] = true ;

        while(!(checkedAll(visited) && box.isEmpty())) {
            if(box.isEmpty()) {
                for(int p=0;p<s*c;p++) {
                    if(visited[p] == false) {
                        visited[p] = true ;
                        cob = new pair(p,-10);
                        box.add(cob) ;
                        break ;
                    }
                }
            }
            pair temp = box.pollFirst() ;
            int prev = temp.f;
            int popped = temp.o ;

            int m , n ;
            m = popped / c ;
            n = popped - m*c ;

            char d = arr[m][n];
            if(m > 0) {
                if(arr[m-1][n] == d) {
