public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        QuickScanner in = new QuickScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        FoxAndTwoDots solver = new FoxAndTwoDots();
        solver.solve(1, in, out);
        out.close();
    }

    static class FoxAndTwoDots {
        boolean[][] vis;
        char[][] G;
        int n;
        int m;
        int[][] moves = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        public void solve(int testNumber, QuickScanner in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            G = new char[n][];
            vis = new boolean[n][m];
            int[] cnt = new int[26];
            for (int i = 0; i < n; i++) {
                G[i] = in.nextString().toCharArray();
                for (char c : G[i]) {
                    cnt[c - 'A']++;
                }
            }
            List<Integer>[] graph = new List[n * m];
            for (int i = 0; i < graph.length; i++) {
                graph[i] = new ArrayList<>();
            }
            for (char letter = 'A'; letter <= 'Z'; ++letter) {
                if (cnt[letter - 'A'] < 4) continue;
                for (int i = 0; i < graph.length; i++) graph[i].clear();
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        if (G[i][j] == letter) {
                            for (int[] mv : moves) {
                                int ni = i + mv[0];
                                int nj = j + mv[1];
                                if (valid(ni, nj) && G[ni][nj] == letter) {
                                    graph[hash(i, j)].add(hash(ni, nj));
                                }
                            }
                        }
                    }
                }
                if (cycleDetected(graph)) {
                    out.println("Yes");
                    return;
                }
            }
            out.println("No");
        }

        boolean cycleDetected(List<Integer>[] graph) {
            boolean[] vis = new boolean[graph.length];
            int[] level = new int[graph.length];
            for (int node = 0; node < graph.length; ++node) {
                if (!vis[node]) {
                    Arrays.fill(vis, false);
                    Arrays.fill(level, 0);
                    if (dfs(node, vis, level, graph, 0)) return true;
                }
            }
            return false;
        }

        boolean dfs(int node, boolean[] vis, int[] level, List<Integer>[] graph, int d) {
            level[node] = d;
            vis[node] = true;
            for (int v : graph[node]) {
                if (vis[v] && level[v] - d >= 3) {
                    return true;
                } else if (!vis[v]) {
                    if (dfs(v, vis, level, graph, d + 1)) {
                        return true;
                    }
                }
            }
            return false;
        }

        boolean valid(int i, int j) {
            return i >= 0 && j >= 0 && i < n && j < m;
        }

        int hash(int i, int j) {
            return i * m + j;
        }

    }

    static class QuickScanner {
        BufferedReader br;
        StringTokenizer st;
        InputStream is;

        public QuickScanner(InputStream stream) {
            is = stream;
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public String nextString() {
            return nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

    }
}

