class TaskB {
    private boolean haveAnswer = false;
    private static final int[] DX4 = MiscUtils.DX4;
    private static final int[] DY4 = MiscUtils.DY4;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int rowCount = in.readInt();
        int columnCount = in.readInt();
        char[][] table = IOUtils.readTable(in, rowCount, columnCount);
        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < columnCount; j++) {
                dfs(i, j, -1, -1, table[i][j], 1, table);
            }
        }

        if (haveAnswer) {
            out.printLine("Yes");
            return;
        }
        out.printLine("No");
    }

    private void dfs(int curX, int curY, int fromX, int fromY, char curColor, int deepCount, char[][] table) {
        if (haveAnswer) {
            return;
        }
        table[curX][curY] = '*';
        for (int i = 0; i < 4; i++) {
            int nextX = curX + DX4[i];
            int nextY = curY + DY4[i];
            if (nextX == fromX && nextY == fromY) {
                continue;
            }
            if (MiscUtils.isValidCell(nextX, nextY, table.length, table[0].length)) {
                if (table[nextX][nextY] == curColor) {
                    dfs(nextX, nextY, curX, curY, curColor, deepCount + 1, table);
                } else if (table[nextX][nextY] == '*' && deepCount >= 4) {
                    haveAnswer = true;
                }
            }
        }
        table[curX][curY] = curColor;
    }
}

