                            int[] e = q.poll();
                            cnt++;
                            int nb = 0;
                            boolean localVert = true;
                            for(int[] d: df) {
                                int y = e[0] + d[0];
                                int x = e[1] + d[1];
                                if(y >= 0 && y < n && x >= 0 && x < m) {
                                    if(c[y][x] == '.') {
                                        if(!k[y][x]) {
                                            k[y][x] = true;
                                            q.add(new int[] { y, x });
                                            localVert = d[0] != 0;
                                        }
                                    } else {
                                        nb++;
                                    }
                                } else {
                                    nb++;
                                }
                            }
                            if(nb == 4) {
                                poss = false;
                                break;
                            } else if(nb == 3 && start == null) {
                                start = e;
                                vert = localVert;
                            }
                        }
                        if(cnt%2==1 || start == null) {
                            poss = false;
                        } else {
                            q = new LinkedList<>();
                            q.add(start);
                            while(!q.isEmpty()) {
                                int[] e = q.poll();
                                if(c[e[0]][e[1]] == '.') {
                                    draw(e,vert);
                                }
                            }
                        }
                    }
                    if(!poss) {
                        break;
                    }
                }
                if(!poss) {
                    break;
                }
            }
        }
        if(poss) {
            StringBuilder buf = new StringBuilder();
            for(int i=0;i<n;i++) {
                buf.append(new String(c[i]));
                buf.append('\n');
            }
            out(buf);
        } else {
            out("Not unique");
        }
    }

    private int cntnb(int i, int j) {
        int nb = 0;
        for(int[] d: df) {
            int y = i + d[0];
            int x = j + d[1];
            if(y >= 0 && y < n && x >= 0 && x < m && c[y][x]=='.') {
                nb++;
            }
        }
        return nb;
    }

    private void draw(int[] e, boolean v) {
        if(v) {
            int y0 = 0;
            int y1 = 0;
            if(e[0] > 0 && c[e[0]-1][e[1]] == '.') {
                y0 = e[0]-1;
                y1 = e[0];
            } else if(e[0] < n-1 && c[e[0]+1][e[1]] == '.') {
                y0 = e[0];
                y1 = e[0]+1;
            }
            if(y0 != y1) {
                c[y0][e[1]] = '^';
                c[y1][e[1]] = 'v';
                for(int[] d: dfv) {
                    int y = y0 +d[0];
                    int x = e[1] + d[1];
                    if(y >= 0 && y < n && x >= 0 && x < m && c[y][x]=='.') {
                        q.add(new int[] { y, x });
                    }
                }
            }
        } else {
            int x0 = 0;
            int x1 = 0;
            if(e[1] > 0 && c[e[0]][e[1]-1] == '.') {
                x0 = e[1]-1;
                x1 = e[1];
            } else if(e[1] < m-1 && c[e[0]][e[1]+1] == '.') {
                x0 = e[1];
                x1 = e[1]+1;
            }
            if(x0 != x1) {
                c[e[0]][x0] = '<';
                c[e[0]][x1] = '>';
                for(int[] d: dfv) {
                    int y = e[0] + d[1];
                    int x = x0 + d[0];
                    if(y >= 0 && y < n && x >= 0 && x < m && c[y][x]=='.') {
                        q.add(new int[] { y, x });
                    }
                }
            }

        }
    }

