        sc.nextLine();
        f = new int[n][m];
        already = new boolean[n][m];
        for (int i = 0; i < f.length; i++) {
            char[] s =sc.nextLine().toCharArray();
            for (int j = 0; j < s.length; j++) {
                f[i][j] = s[j];
            }
        }
        Queue<int[]>q = new LinkedList<>();
        for (int i = 0; i < f.length; i++) {
            for (int j = 0; j < m; j++) {
                if(f[i][j] !='.')continue;
                if(ji(i, j)==1){
                    q.add(new int[]{i,j});
                }
            }
        }

        while(!q.isEmpty()){
            int y = q.peek()[0];
            int x = q.poll()[1];
            if(f[y][x]!='.')continue;
            for (int i = 0; i < v1.length; i++) {
                int yy = y + v1[i];
                int xx = x + v2[i];
                if(yy <0 || yy >= n || xx < 0 || xx >= m)continue;
                if(f[yy][xx] == '.'){
                    put(y,x,yy,xx);
                    for (int j = 0; j < v1.length; j++) {
                        int yyy = yy + v1[j];
                        int xxx = xx + v2[j];
                        if(yyy <0 || yyy >= n || xxx < 0 || xxx >= m)continue;
                        if(ji(yyy,xxx)==1){
                            q.add(new int[]{yyy,xxx});
                        }
                    }
                    break;
                }
            }

        }

        for (int i = 0; i < f.length; i++) {
            for (int j = 0; j < m; j++) {
                if(f[i][j] == '.'){
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        output();
    }
    void output(){
        StringBuilder sb=new StringBuilder();
        for (int i = 0; i < f.length; i++) {
            for (int j = 0; j < m; j++) {
                sb.append((char)f[i][j]);


            }
            sb.append('\n');

        }
        System.out.println(sb);
    }
    boolean[][] already;
    void dfs(int y,int x){
        Stack<int[]>stack = new Stack<int[]>();
        stack.add(new int[]{y,x});
        while(stack.isEmpty()==false){
            y = stack.peek()[0];
            x = stack.pop()[1];

            if(f[y][x]!='.')continue;
            already[y][x]=true;

            int myj = ji(y, x);
            if(myj==1){
                for (int i = 0; i < v1.length; i++) {
                    int yy = y+v1[i];
                    int xx = x+v2[i];
                    if(yy <0 || yy >= n || xx < 0 || xx >= m)continue;
                    if(f[yy][xx] == '.'){
                        put(y,x,yy,xx);
                        break;
                    }
                }
                continue;
            }
            boolean canback = false;
            for (int i = 0; i < v1.length; i++) {
                int yy = y+v1[i];
                int xx = x+v2[i];
                if(yy <0 || yy >= n || xx < 0 || xx >= m)continue;
                if(f[yy][xx]!= '.')continue;
                int ji = ji(yy,xx);
                if(ji==1){
                    put(y,x,yy,xx);
                    canback=true;
                    break;
                }
            }

            for (int i = 0; i < v1.length; i++) {
                int yy = y+v1[i];
                int xx = x+v2[i];
                if(yy <0 || yy >= n || xx < 0 || xx >= m)continue;
                if(f[yy][xx] == '.'){
                    if(canback || already[yy][xx] ==false){
                        stack.add(new int[]{yy,xx});
                    }
                }
            }
        }


    }

    int[] v1 = {1,0,-1,0};
    int[] v2 = {0,-1,0,1};

    void put(int y,int x,int yy,int xx){
        if(x==xx){
            if(y < yy){
                int tmp = y;
                y = yy;
                yy = tmp;
            }
            f[yy][x] = '^';
            f[y][x] = 'v';
        } else {
            if(x < xx){
                int tmp = x;
                x = xx;
                xx = tmp;
            }
            f[y][x]='>';
            f[y][xx]='<';
        }


    }
    int ji(int y,int x){
        int res = 0;
        for (int i = 0; i < v1.length; i++) {
            int yy = y+v1[i];
            int xx = x+v2[i];
            if(yy <0 || yy >= n || xx < 0 || xx >= m)continue;
            if(f[yy][xx] == '.')res++;
        }
        return res;
    }
    void run(){
        solve();
        out.flush();
    }
    public static void main(String[] args) {
        new B().run();
    }
