        System.err.println(deepToString(os));
    }
}

import java.util.ArrayDeque;
import java.util.Scanner;

public class D {
    ArrayDeque<Integer> q = new ArrayDeque<>();
    int[] dx = {0, 0, 1, -1};
    int[] dy = {1, -1, 0, 0};
    int n, m;
    char[][] grid;
    boolean dot(int i, int j) {
        if (i < 0 || j < 0 || i >= n || j >= m) {
            return false;
        }
        return grid[i][j] == '.';
    }

    void adjacent(int i, int j) {
        int sc = 4;
        int ni = 0, nj = 0;
        for (int a = 0; a < 4; a++) {
            if (dot(i + dx[a], j + dy[a])) {
                sc--;
                ni = i + dx[a];
                nj = j + dy[a];
            }
        }
        if (sc == 3) {
            q.add(i);
            q.add(j);
            q.add(ni);
            q.add(nj);
        }
    }

    boolean soln() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') return false;
            }
        }
        return true;
    }

    D() {
        Scanner s = new Scanner(System.in);
        n = s.nextInt();
        m = s.nextInt();
        grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = s.next().toCharArray();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m ; j++) {
                adjacent(i, j);
            }
        }
        while (!q.isEmpty()) {
            int i = q.remove();
            int j = q.remove();
            int ni = q.remove();
            int nj = q.remove();

            if (dot(i, j) && dot(ni, nj)) {
                if (ni == i) {
                    if (nj > j) {
                        grid[i][j] = '<';
                        grid[ni][nj] = '>';
                    }
                    else {
                        grid[ni][nj] = '<';
                        grid[i][j] = '>';
                    }
                }
                else { 
                    if (ni > i) {
                        grid[i][j] = '^';
                        grid[ni][nj] = 'v';
                    }
                    else {
                        grid[ni][nj] = '^';
                        grid[i][j] = 'v';
                    }
                }
                for (int a = 0; a < 4; a++) {
                    if (dot(i + dx[a], j + dy[a]))
                        adjacent(i + dx[a], j + dy[a]);
                    if (dot(ni + dx[a], nj + dy[a]))
                        adjacent(ni + dx[a], nj + dy[a]);
                }
            }
        }
        boolean u = soln();
        if (u)
            for (int i = 0; i < n; i++) {
                System.out.println(new String(grid[i]));
            }
        else System.out.println("Not unique");
    }

    public static void main(String[] args) {
        D d = new D();
    }
}

