                degree = new int[r][c];
                for(int i = 0; i < r; i++)
                    for(int j = 0; j < c; j++)
                        if(is_good(i, j))
                        for(int k = 0; k < 4; k++){
                            int nx = i + dx[k];
                            int ny = j + dy[k];
                            if(is_good(nx, ny))
                                degree[i][j]++;
                        }


                q = new LinkedList<>();
                for(int i = 0; i < r; i++){
                    for(int j = 0; j < c; j++){
                        if(degree[i][j] == 1){
                            q.add(i);
                            q.add(j);
                        }
                    }
                }



                while(!q.isEmpty()){
                    int x = q.poll();
                    int y = q.poll();
                    for(int k = 0; k < 4; k++){
                        int nx = x + dx[k];
                        int ny = y + dy[k];
                        if(is_good(nx, ny)){
                            set(x, y, nx,ny);
                            update(x, y);
                            update(nx, ny);
                            break;
                        }
                    }
                }

                boolean done = true;
                for(int i = 0; i < r; i++){

                    for(int j = 0; j < c; j++){
                        if(map[i][j] == '.')
                            done = false;
                    }
                }




                if(!done)
                    out.println("Not unique");
                else{
                    for(int i = 0; i < r; i++){
                        out.println(new String(map[i]));
                    }
                }
	}




















