public class DrazilAndTiles {

	static class Cell {
		int row, col;

		Cell(int r, int c) {
			row = r;
			col = c;
		}

		@Override
		public String toString() {
			return row + " " + col;
		}
	}

	static int N, M;
	static final int[] dx = { 1, 0, -1, 0 };
	static final int[] dy = { 0, -1, 0, 1 };

	static boolean isValid(int r, int c) {
		return r >= 0 && r < N && c >= 0 && c < M;
	}

	public static void main(String[] args) throws IOException {
		MyScanner sc = new MyScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		N = sc.nextInt();
		M = sc.nextInt();
		char[][] g = new char[N][M];
		for (int i = 0; i < N; i++)
			g[i] = sc.next().toCharArray();
		Queue<Cell> q = new LinkedList<>();
		int[][] d = new int[N][M];
		for (int r = 0; r < N; r++)
			for (int c = 0; c < M; c++) {
				if (g[r][c] == '*')
					continue;
				int degree = 0;
				for (int i = 0; i < 4; i++) {
					int row = r + dx[i], col = c + dy[i];
					if (isValid(row, col) && g[row][col] != '*')
						degree++;
				}
				d[r][c] = degree;
				if (degree == 1)
					q.add(new Cell(r, c));
			}
		while (!q.isEmpty()) {
			Cell c = q.poll();
			for (int i = 0; i < 4; i++) {
				int row = c.row + dx[i], col = c.col + dy[i];
				if (isValid(row, col) && g[row][col] == '.') {
					d[c.row][c.col] = 0;
					d[row][col] = 0;
					for (int k = 0; k < 4; k++) {
						int nr = row + dx[k], nc = col + dy[k];
						if (isValid(nr, nc) && g[nr][nc] == '.') {
							d[nr][nc]--;
							if (d[nr][nc] == 1)
								q.add(new Cell(nr, nc));
						}
					}
					if (i == 0) {
						g[c.row][c.col] = '^';
						g[row][col] = 'v';
					} else if (i == 1) {
						g[c.row][c.col] = '>';
						g[row][col] = '<';
					} else if (i == 2) {
						g[c.row][c.col] = 'v';
						g[row][col] = '^';
					} else {
						g[c.row][c.col] = '<';
						g[row][col] = '>';
					}
					break;
				}
			}
		}
		boolean f = true;
		for (int r = 0; r < N; r++)
			for (int c = 0; c < M; c++)
				if (g[r][c] == '.') {
					f = false;
				}
		if (!f)
			out.println("Not unique");
		else {
			for (int r = 0; r < N; r++)
				out.println(new String(g[r]));
		}
		out.flush();
		out.close();
	}

	static class MyScanner {

		StringTokenizer st;
		BufferedReader br;

		public MyScanner(InputStream s) {
			br = new BufferedReader(new InputStreamReader(s));
		}

		public MyScanner(String filename) throws IOException {
			br = new BufferedReader(new FileReader(new File(filename)));
		}

		public String next() throws IOException {
			while (st == null || !st.hasMoreTokens())
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		public int nextInt() throws IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws IOException {
			return Long.parseLong(next());
		}

		public String nextLine() throws IOException {
			return br.readLine();
		}

		public boolean ready() throws IOException {
			return br.ready();
		}
	}
}

