public class B {

    class Point implements Comparable<Point>{
        int x,y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }



        @Override
        public int compareTo(Point o) {
            if(x!=o.x)return y-o.y;
            return x-o.x;
        }
    }

    int[] dx={-1,1,0,0};
    int[] dy={0,0,-1,1};

    boolean check(Point p,int[][] a){
        int count=0;
        for(int i=0;i<4;i++){
            if(a[p.x+dx[i]][p.y+dy[i]]!=0)count++;
        }
        return count==3;
    }

    void addPoint(Point p,int[][] a,PriorityQueue<Point> q){

        for(int i=0;i<4;i++){
            int x=p.x+dx[i];
            int y=p.y+dy[i];
            if(a[x][y]==0&&check(new Point(x,y),a))q.add(new Point(x,y));
        }
    }

    void solve() throws IOException {
        int n=nextInt();
        int m=nextInt();
        int[][] a=new int[n+2][m+2];
        for(int i=0;i<=n;i++)a[i][0]=a[i][m+1]=-1;
        for(int i=0;i<=m;i++)a[0][i]=a[n+1][i]=-1;
        for(int i=0;i<n;i++){
            String s=nextToken();
            for(int j=0;j<m;j++)
                if(s.charAt(j)=='*')a[i+1][j+1]=-1;
        }
        PriorityQueue<Point> q=new PriorityQueue<Point>();
        for(int i=1;i<=n;i++)
            for(int j=1;j<=m;j++)
                if(a[i][j]==0&&check(new Point(i,j),a))
                    q.add(new Point(i,j));
        char[] c={'<','>','^','v'};
        while(!q.isEmpty()){
            Point cur=q.poll();
            if(a[cur.x][cur.y]!=0)continue;
            for(int i=0;i<4;i++) {
                int newx=cur.x+dx[i];
                int newy=cur.y+dy[i];
                if (a[newx][newy] == 0) {
                    switch (i) {
                        case 2:
                            a[newx][newy] = 1;
                            a[cur.x][cur.y] = 2;
                            break;
                        case 3:
                            a[newx][newy]=2;
                            a[cur.x][cur.y]=1;
                            break;
                        case 0:
                            a[newx][newy]=3;
                            a[cur.x][cur.y]=4;
                            break;
                        case 1:
                            a[newx][newy]=4;
                            a[cur.x][cur.y]=3;
                    }
                    addPoint(new Point(newx, newy), a, q);
                    addPoint(cur, a, q);
                    break;
                }
            }
        }
        boolean good=true;
        for(int i=1;i<=n;i++)
            for(int j=1;j<=m;j++)
                if(a[i][j]==0)good=false;
        if(!good){
            out.println("Not unique");
        }
        else{
            for(int i=1;i<=n;i++){
                for(int j=1;j<=m;j++)
                    if(a[i][j]==-1)
                        out.print('*');
                    else
                        out.print(c[a[i][j]-1]);
                out.println();
            }

        }
    }

    public static void main(String[] args) throws IOException {
        new B().run();
    }

    void run() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));

        tokenizer = null;
        out = new PrintWriter(new OutputStreamWriter(System.out));

        solve();
        reader.close();
        out.flush();

    }

    BufferedReader reader;
    StringTokenizer tokenizer;
    PrintWriter out;

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }
}

import java.util.*;

public class Solution {
    private int[] di = {-1, 1, 0, 0};
    private int[] dj = {0, 0, -1, 1};

    public void drazilTiles() {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        int m = s.nextInt();
        char[][] board = new char[n][m]; 
        for (int i = 0; i < n; ++i) {
            board[i] = s.next().trim().toCharArray();
        }
        s.close();
        solve(board);
    }

    private void solve(char[][] board) {
        Queue<Integer> terminals = new LinkedList<>();
        for (int i = 0; i < board.length; ++i) {
            for (int j = 0; j < board[i].length; ++j) {
                if (isTerminal(board, i, j)) {
                    terminals.add(i);
                    terminals.add(j);
                }
            }
        }
        while (!terminals.isEmpty()) {
            int i = terminals.remove();
            int j = terminals.remove();
            switch (getDir(board, i, j)) {
            case 0: {
                board[i - 1][j] = '^';
                board[i][j] = 'v';
                addTerminal(terminals, board, i - 1, j);
                break;
            }
            case 1: {
                board[i][j] = '^';
                board[i + 1][j] = 'v';
                addTerminal(terminals, board, i + 1, j);
                break;
            }
            case 2: {
                board[i][j - 1] = '<';
                board[i][j] = '>';
                addTerminal(terminals, board, i, j - 1);
                break;
            }
            case 3: {
                board[i][j] = '<';
                board[i][j + 1] = '>';
                addTerminal(terminals, board, i, j + 1);
                break;
            }
            }
            addTerminal(terminals, board, i, j);
        }

        for (char[] row : board) {
            for (char i : row) {
                if (i == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }

    private void addTerminal(Queue<Integer> q, char[][] board, int i, int j) {
        for (int n = 0; n < 4; ++n) {
            if (isTerminal(board, i + di[n], j + dj[n])) {
                q.add(i + di[n]);
                q.add(j + dj[n]);
            }
        }
    }

    private int getDir(char[][] board, int i, int j) {
        for (int n = 0; n < 4; ++n) {
            if (isOnBoard(board, i + di[n], j + dj[n]) && board[i + di[n]][j + dj[n]] == '.') {
                return n;
            }
        }
        return -1;
    }

    private boolean isTerminal(char[][] board, int i, int j) {
        if (!isOnBoard(board, i, j) || board[i][j] != '.') {
            return false;
        }
        int count = 0;
        for (int n = 0; n < 4; ++n) {
            if (isOnBoard(board, i + di[n], j + dj[n]) && board[i + di[n]][j + dj[n]] == '.') {
                count++;
            }
        }
        return count == 1;
    }

    private boolean isOnBoard(char[][] board, int i, int j) {
        return !(i < 0 || i >= board.length || j < 0 || j >= board[i].length);
    }

    public static void main(String[] args) {
        new Solution().drazilTiles();
    }
}

