class TaskD {

    char[][] table;
    Deque<IntPair> list;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int n=in.readInt(), m=in.readInt();
        table= IOUtils.readTable(in, n, m);
        list=new ArrayDeque<IntPair>();
        for (int i=0; i<n; i++) for (int j=0; j<m; j++) if (table[i][j]=='.') {
            int x=f(i, j);
            if (x==0) {
                out.printLine("Not unique");

                return;
            }
            if (x==1) list.add(new IntPair(i, j));
        }
        while (!list.isEmpty()) {
            IntPair pair=list.pollFirst();
            if (table[pair.first][pair.second]!='.') continue;
            if (!process(pair)) {
                out.printLine("Not unique");

                return;
            }
        }
        for (char[] i: table) for (char j: i) if (j=='.') {
            out.printLine("Not unique");
            return;
        }
        IOUtils.printTable(out, table);
    }

    int f(int x, int y) {
        int ret=0;
        for (int i=0; i<4; i++) {
            int x2=x+MiscUtils.DX4[i], y2=y+MiscUtils.DY4[i];
            if (MiscUtils.isValidCell(x2, y2, table.length, table[0].length) && table[x2][y2]=='.') ret++;
        }
        return ret;
    }

    boolean process(IntPair pair) {
        int x=pair.first, y=pair.second;
        IntPair pair2=null;
        for (int i=0; i<4; i++) {
            int x2=pair.first+MiscUtils.DX4[i], y2=pair.second+MiscUtils.DY4[i];
            if (MiscUtils.isValidCell(x2, y2, table.length, table[0].length) && table[x2][y2]=='.') {
                if (x2<x) {
                    table[x][y]='v';
                    table[x2][y2]='^';
                } else if (x2>x) {
                    table[x][y]='^';
                    table[x2][y2]='v';
                } else if (y2<y) {
                    table[x][y]='>';
                    table[x2][y2]='<';
                } else {
                    table[x][y]='<';
                    table[x2][y2]='>';
                }
                pair2=new IntPair(x2, y2);
            }
        }
        for (int i=0; i<4; i++) {
            int x2=pair2.first+MiscUtils.DX4[i], y2=pair2.second+MiscUtils.DY4[i];
            if (MiscUtils.isValidCell(x2, y2, table.length, table[0].length) && table[x2][y2]=='.' && (x!=x2 || y!=y2)) {
                int n=f(x2, y2);
                if (n==0) return false;
                if (n==1) list.add(new IntPair(x2, y2));
            }
        }
        return true;
    }
}

class IntPair implements Comparable<IntPair> {
    public final int first, second;

    public IntPair(int first, int second) {
        this.first = first;
        this.second = second;
    }

    public String toString() {
        return "(" + first + "," + second + ")";
    }

    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        IntPair intPair = (IntPair) o;

        return first == intPair.first && second == intPair.second;

    }

    public int hashCode() {
        int result = first;
        result = 31 * result + second;
        return result;
    }

    public int compareTo(IntPair o) {
        if (first < o.first)
            return -1;
        if (first > o.first)
            return 1;
        if (second < o.second)
            return -1;
        if (second > o.second)
            return 1;
        return 0;
    }
}

class InputReader {

    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public boolean isSpaceChar(int c) {
        if (filter != null)
            return filter.isSpaceChar(c);
        return isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public char readCharacter() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        return (char) c;
    }

    public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }
}

