            if (neighbour.x > node.x) {
                grid[node.y][node.x] = '<';
                grid[neighbour.y][neighbour.x] = '>';
            } else if (neighbour.x < node.x) {
                grid[node.y][node.x] = '>';
                grid[neighbour.y][neighbour.x] = '<';
            } else if (neighbour.y < node.y) {
                    grid[node.y][node.x] = 'v';
                    grid[neighbour.y][neighbour.x] = '^';
                } else {
                    grid[node.y][node.x] = '^';
                    grid[neighbour.y][neighbour.x] = 'v';
                }

        int i = neighbour.y;
