                if (dyi >= 0 && dyi < grid[0].length) {
                    if (grid[dxi][dyi] == '.') {
                   if (grid[dxi][dyi] != '.') {
                    continue;
                }
                        idegree(dxi,dyi);
                    }
                }
            }
        }

        }
