public class B {
    BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    PrintWriter writer = new PrintWriter(System.out);
    StringTokenizer stringTokenizer;

    B() throws IOException {


    }

    String next() throws IOException {
        while (stringTokenizer == null || !stringTokenizer.hasMoreTokens()) {
            stringTokenizer = new StringTokenizer(reader.readLine());
        }
        return stringTokenizer.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }

    int[][] mul(int[][] a, int[][] b) {
        int[][] result = new int[2][2];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                for (int k = 0; k < 2; k++) {
                    result[i][j] = sum(result[i][j], product(a[i][k], b[k][j]));
                }
            }
        }
        return result;
    }

    int[][] pow(int[][] a, int k) {
        int[][] result = {{1, 0}, {0, 1}};
        while (k > 0) {
            if (k % 2 == 1) {
                result = mul(result, a);
            }
            a = mul(a, a);
            k /= 2;
        }
        return result;
    }

    final int MOD = 1000 * 1000 * 1000 + 7;

    int sum(int a, int b) {
        a += b;
        return a >= MOD ? a - MOD : a;
    }

    int product(int a, int b) {
        return (int) (1l * a * b % MOD);
    }

    @SuppressWarnings("unchecked")
    void solve() throws IOException {
        final int n = nextInt(), m = nextInt();
        final char[][] f = new char[n + 2][m + 2];
        for (char[] aF : f) {
            Arrays.fill(aF, '*');
        }
        for (int i = 1; i <= n; i++) {
            System.arraycopy(next().toCharArray(), 0, f[i], 1, m);
        }
        final int[] dd = {-1, 0, 1, 0};
        class Utils {
            int nc(int r, int c) {
                int nc = 0;
                for(int k = 0; k < 4; k++) {
                    int rr = r + dd[k];
                    int cc = c + dd[k + 1 & 3];
                    if(f[rr][cc] == '.') nc++;
                }
                return nc;
            }
        }
        Utils utils = new Utils();
        char[] foo = "v<^>".toCharArray();
        char[] boo = "^>v<".toCharArray();
        class CellQueue {
            short[] row = new short[n * m + 1];
            short[] column = new short[n * m + 1];
            int start = 0, end = 0;

            boolean isEmpty() {
                return start == end;
            }

            void add(int r, int c) {
                row[end] = (short) r;
                column[end] = (short) c;
                end++;
            }

            void pop() {
                start++;
            }

            int r() {
                return row[start];
            }

            int c() {
                return column[start];
            }
        }
        CellQueue q = new CellQueue();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if(f[i][j] == '*') continue;
                if(utils.nc(i, j) <= 1) {
                    q.add(i, j);
                }
            }
        }
        boolean ok = true;
        while(!q.isEmpty()) {
            int r = q.r();
            int c = q.c();
            q.pop();
            if(f[r][c] != '.') {
                continue;
            }
            int rn = 0;
            int cn = 0;
            int kn = 0;
            for(int k = 0; k < 4; k++) {
                rn = r + dd[k];
                cn = c + dd[k + 1 & 3];
                kn = k;
                if(f[rn][cn] == '.') break;
            }
            if(f[rn][cn] != '.') {
                ok = false;
                break;
            }
            f[r][c] = foo[kn];
            f[rn][cn] = boo[kn];
            for(int k = 0; k < 4; k++) {
                int rr = rn + dd[k];
                int cc = cn + dd[k + 1 & 3];
                if(f[rr][cc] == '.' && utils.nc(rr, cc) <= 1) {
                    q.add(rr, cc);
                }
            }
        }
        for (char[] row : f) {
            if(!ok) break;
            for (char c : row) {
                if(!ok) break;
                if(c == '.') {
                    ok = false;
                }
            }
        }
        if(!ok) {
            writer.println("Not unique");
        } else {
            for(int i = 1; i <= n; i++) {
                for(int j = 1; j <= m; j++) {
                    writer.print(f[i][j]);
                }
                writer.println();
            }
        }
        writer.close();
    }

    public static void main(String[] args) throws IOException {
        new B().solve();
    }

}

import java.util.Scanner;

public class Main {
    int n;
    int m;
    byte[] field;
    int[] xRet;
    int[] yRet;
    int retCount = 0;

    byte get(int i, int j) {
        return field[(i + 1) * (m + 2) + j + 1];
    }

    void set(int i, int j, byte b) {
        field[(i + 1) * (m + 2) + j + 1] = b;
    }

    final byte two = 2;
    final byte one = 1;
    final byte zero = 0;
    final byte up = 9;
    final byte down = 8;
    final byte left = 7;
    final byte right = 6;

    public void solve() {
        Parser parser = new Parser();
        n = parser.nextInteger();
        m = parser.nextInteger();
        parser.nextLine();

        xRet = new int[m * n];
        yRet = new int[m * n];
        field = new byte[(m + 2) * (n + 2)];

        byte[] field = new byte[(n + 2) * (m + 2)];
        for (int i = 0; i < n; ++i) {
            String str = parser.nextLine();
            for (int j = 0; j < m; ++j) {
                if (str.charAt(j) == '*') {
                    set(i, j, one);
                }
            }
        }
        for (int i = 0; i < n; ++i) {
            set(i, -1, one);
            set(i, m, one);
        }

        for (int j = 0; j < m; ++j) {
            set(-1, j, one);
            set(n, j, one);
        }

        try {

            for (int i = 0; i < n; ++i)
                for (int j = 0; j < m; ++j) {
                    doTry(i, j);
                }
            while (retCount > 0) {
                int i = xRet[--retCount];
                int j = yRet[retCount];
                doTry(i, j);
            }
            for (int i = 0; i < n; ++i)
                for (int j = 0; j < m; ++j) {
                    if (get(i, j) == zero) throw new Exception();
                }


        } catch (Exception exc) {
            System.out.print("Not unique");
            return;
        }
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                switch (get(i, j)) {
                    case one:
                        builder.append('*');
                        break;
                    case up:
                        builder.append('^');
                        break;
                    case down:
                        builder.append('v');
                        break;
                    case left:
                        builder.append('<');
                        break;
                    case right:
                        builder.append('>');
                        break;
                }
            }
            builder.append('\n');
        }
        System.out.print(builder.toString());
    }

    void addRet(int i, int j) {
        if (get(i, j) != 0) return;
        xRet[retCount] = i;
        yRet[retCount++] = j;

    }

    void doTry(int i, int j) throws Exception {
        if (get(i, j) != 0) return;
        int emptyN = countNeighbours(i, j, zero);
        if (emptyN > 1) return;
        if (emptyN == zero) throw new Exception();
        if (get(i - 1, j) == zero) {
            set(i - 1, j, up);
            set(i, j, down);
            addRet(i - 2, j);
            addRet(i - 1, j - 1);
            addRet(i - 1, j + 1);
        }
        if (get(i + 1, j) == zero) {
            set(i, j, up);
            set(i + 1, j, down);
            addRet(i + 2, j);
            addRet(i + 1, j + 1);
            addRet(i + 1, j - 1);
        }
        if (get(i, j - 1) == zero) {
            set(i, j - 1, left);
            set(i, j, right);
            addRet(i, j - 2);
            addRet(i - 1, j - 1);
            addRet(i + 1, j - 1);
        }
        if (get(i, j + 1) == zero) {
            set(i, j + 1, right);
            set(i, j, left);
            addRet(i, j + 2);
            addRet(i + 1, j + 1);
            addRet(i - 1, j + 1);
        }


    }

    int countNeighbours(int i, int j, byte b) {
        int count = 0;
        if (get(i - 1, j) == b) ++count;
        if (get(i + 1, j) == b) ++count;
        if (get(i, j - 1) == b) ++count;
        if (get(i, j + 1) == b) ++count;
        return count;
    }

    public static void main(String[] args) {
        new Main().solve();
    }

    static public class Parser {
        Scanner scanner;

        public Parser() {
            scanner = new Scanner(System.in);
        }

        public Parser(String str) {
            scanner = new Scanner(str);
        }

        long nextLong() {
            return scanner.nextLong();
        }

        int nextInteger() {
            return scanner.nextInt();
        }

        double nextDouble() {
            return scanner.nextDouble();
        }

        String nextLine() {
            return scanner.nextLine();
        }

        int[] nextIntegers(int count) {
            int[] result = new int[count];
            for (int i = 0; i < count; ++i) {
                result[i] = nextInteger();
            }
            return result;
        }

        long[] nextLongs(int count) {
            long[] result = new long[count];
            for (int i = 0; i < count; ++i) {
                result[i] = nextLong();
            }
            return result;
        }

        int[][] nextIntegers(int fields, int count) {
            int[][] result = new int[fields][];
            for (int i = 0; i < fields; ++i) {
                result[i] = new int[count];
            }
            for (int c = 0; c < count; ++c) {
                for (int i = 0; i < fields; ++i) {
                    result[i][c] = nextInteger();
                }
            }
            return result;
        }
    }
