public class A {

	static final int[] dx = {0, 0, -1, 1};
	static final int[] dy = {-1, 1, 0, 0};
	static final char[] s1 = {'>','<','v','^'};
	static final char[] s2 = {'<','>','^','v'};
	static int n, m;
	static char[][] grid;

	static boolean valid(int x, int y)
	{
		return x >= 0 && y >= 0 && x < n && y < m && grid[x][y] == '.';
	}

	public static void main(String[] args) throws IOException 
	{
		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		n = sc.nextInt();
		m = sc.nextInt();
		int[] deg = new int[n * m];
		grid = new char[n][m];
		for(int i = 0; i < n; ++i)
			grid[i] = sc.next().toCharArray();
		Queue<Integer> q = new LinkedList<>();
		boolean[] inQueue = new boolean[n * m];
		int cnt = 0;
		for(int i = 0; i < n; ++i)
			for(int j = 0; j < m; ++j)
				if(grid[i][j] == '.')
				{
					++cnt;
					for(int k = 0; k < 4; ++k)
					{
						int x = i + dx[k], y = j + dy[k];
						if(valid(x, y))
							++deg[i * m + j];
					}
					if(deg[i * m + j] == 1)
					{
						inQueue[i * m + j] = true;
						q.add(i * m + j);
					}
				}
		while(!q.isEmpty())
		{
			--cnt;
			int cur = q.remove(), x = cur / m, y = cur % m;
			boolean match = grid[x][y] != '.';
			for(int k = 0; k < 4; ++k)
			{
				int i = x + dx[k], j = y + dy[k];
				if(valid(i, j))
				{
					if(--deg[i * m + j] == 1)
					{
						inQueue[i * m + j] = true;
						q.add(i * m + j);
					}

					if(!match)
					{
						match = true;
						grid[x][y] = s1[k];
						grid[i][j] = s2[k];
						if(!inQueue[i * m + j])
						{
							inQueue[i * m + j] = true;
							q.add(i * m + j);
						}
					}
				}
			}
			if(!match)
				++cnt;
		}

		if(cnt != 0)
			out.println("Not unique");
		else
			for(char[] x: grid)
				out.println(x);
		out.flush();
		out.close();
	}

