    int[][] d = {{0,0,1,-1}, {1,-1,0,0}};
    char[][] c = {{'<','>','^','v'},{'>','<','v','^'}};
    char[][] map;
    int i,j,k,ii,jj,i1,j1,x, result, idx;
    ArrayDeque<Integer> q = new ArrayDeque<>();

    public static void main(String[] args) {
        new CF515D();
    }

    CF515D() {
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        m = in.nextInt();
        cc = 0;

        map = new char[n][m];
        for (int i = 0; i < n; i++) {
            map[i] = in.next().toCharArray();
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map[i][j] =='.') {
                    cc++;
                    add(i, j);
                }
            }
        }

        while (!q.isEmpty() && cc > 0) {
            i = q.remove(); j = q.remove(); k = q.remove();
            ii = i + d[0][k]; jj = j + d[1][k];
            if (map[i][j] =='.' && map[ii][jj] =='.') {
                map[i][j] = c[0][k];
                map[ii][jj] = c[1][k];
                cc -= 2;
                for (x = 0; x < d[0].length; x++) {
                    i1 = i + d[0][x]; j1 = j + d[1][x];
                    if (is(i1,j1)) {
                        add(i1,j1);
                    }
                    i1 = ii + d[0][x]; j1 = jj + d[1][x];
                    if (is(i1,j1)) {
                        add(i1,j1);
                    }
                }
            }
        }

        if (cc > 0) System.out.println("Not unique");
        else {
            for (i = 0; i < n; i++) {
                System.out.println(new String(map[i]));
            }
        }
    }

    private boolean is(int i, int j) {return (i >= 0 && i < n && j < m && j >= 0) && map[i][j] == '.';}

    private void add(int i, int j) {
        result = 0;
        for(int k = 0; k < d[0].length; k++) {
            if (is(i + d[0][k],j + d[1][k])) {result++; idx = k;}
        }
        if(result == 1) {q.add(i);q.add(j);q.add(idx);}
    }
}

