public class E {
    public static char[][] grid;
    public static int n,m;
    public static Queue<Integer> q;
    public static int[] dx = {0,0,1,-1};
    public static int[] dy = {1,-1,0,0};
    public static void main(String[] args) {

        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        m = in.nextInt();
        grid = new char[n][m];

        q = new ArrayDeque<Integer>();
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        for(int i = 0; i<n; i++)
            for(int j = 0; j<m; j++){
                if(grid[i][j] == '*')
                    continue;
                check(i, j);
            }
        int ux,uy,vx,vy;
        while (!q.isEmpty()) {



             ux = q.remove();
             uy = q.remove();

             vx = q.remove();
             vy = q.remove();
            if (grid[ux][uy] != '.' || grid[vx][vy] != '.') continue;
            if (ux != vx) {
                if (ux > vx) {
                    grid[vx][vy] = '^';
                    grid[ux][uy] = 'v';
                } else {
                    grid[vx][vy] = 'v';
                    grid[ux][uy] = '^';
                }
            } else {
                if (uy > vy) {
                    grid[vx][vy] = '<';
                    grid[ux][uy] = '>';
                } else {
                    grid[vx][vy] = '>';
                    grid[ux][uy] = '<';
                }
            }
            for(int d = 0; d<4; d++)
                if(!isSolid(ux+dx[d], uy+dy[d]))
                    check(ux+dx[d], uy+dy[d]);
            for(int d = 0; d<4; d++)
                if(!isSolid(vx+dx[d], vy+dy[d]))
                    check(vx+dx[d], vy+dy[d]);
        }
        boolean unique = true;
        for(int i = 0; i<n; i++)
            for(int j = 0; j<m; j++)
                unique &= grid[i][j] != '.';
        if(unique){
            for(int i = 0; i<n; i++)
                System.out.println(new String(grid[i]));
        }else System.out.println("Not unique");

    }

    public static void error(String msg) {

        System.out.println("Not unique");
        System.exit(0);
    }

    private static boolean isSolid(int i, int j){
        if(i < 0 || j < 0 || i >=n || j>=m)
            return true;
        return grid[i][j] != '.';
    }
    private static void check(int i, int j) {
        int ni,nj;
        ni = nj = -1;
        int sc = 4;
        for(int d = 0; d<4; d++)
            if(!isSolid(i+dx[d], j+dy[d])){
                sc--;
                ni = i+dx[d];
                nj = j+dy[d];
            }
        if(sc == 3){
            q.add(i);
            q.add(j);
            q.add(ni);
            q.add(nj);

        }
    }
