public class Task4 {

  static char[][] map;
  static int[] dx = { -1, 0, 1, 0 };
  static int[] dy = {0,1,0,-1};
  static char[] sym = { 'v', '<', '^', '>' };

  public static int numNeighbors(int x, int y) {
    if (map[x][y] != '.')
      return 0;
    int s = 0;
    for (int i = 0; i < 4; i++) {
      if (map[x + dx[i]][y + dy[i]] == '.') {
        s++;
      }
    }
    return s;
  }

  public static int fill(int x, int y) {
    for (int i=0;i<4;i++) {
      if (map[x + dx[i]][y + dy[i]] == '.') {
        map[x][y] = sym[i];
        map[x + dx[i]][y + dy[i]] = sym[(i + 2) % 4];
        return i;
      }
    }
    throw new RuntimeErrorException(null);
  }

  public static void main(String[] args) {
    Scanner in = new Scanner(System.in);
    int N = in.nextInt();
    int M = in.nextInt();
    map = new char[N + 2][M + 2];
    for (int i = 0; i < N; i++) {
      map[i + 1][0] = map[i + 1][M + 1] = '#';
    }
    for (int i = 0; i < M; i++) {
      map[0][i + 1] = map[N + 1][i + 1] = '#';
    }
    String dummy = in.nextLine();
    for (int i = 0; i < N; i++) {
      String s = in.nextLine();
      for (int j = 0; j < M; j++) {
        map[i + 1][j + 1] = s.charAt(j);
      }
    }
    in.close();
    List<Integer> ones = new LinkedList<Integer>();
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < M; j++) {
        if (numNeighbors(i + 1, j + 1) == 1) {
          ones.add(i * M + j);
        }
      }
    }
    while (!ones.isEmpty()) {
      int next = ones.get(0);
      ones.remove(0);
      int x = next / M;
      int y = next % M;
      if (numNeighbors(x + 1, y + 1) != 1)
        continue;
      int dir = fill(x + 1, y + 1);
      for (int i = 0; i < 4; i++) {
        int x1 = x + dx[i];
        int x2 = x + dx[i] + dx[dir];
        int y1 = y + dy[i];
        int y2 = y + dy[i] + dy[dir];
        if (numNeighbors(x1 + 1, y1 + 1) == 1) {
          ones.add(x1 * M + y1);
        }
        if (numNeighbors(x2 + 1, y2 + 1) == 1) {
          ones.add(x2 * M + y2);
        }
      }
    }
    int done = 1;
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < M; j++) {
        if (map[i + 1][j + 1] == '.') {
          done = 0;
        }
      }
    }
    if (done == 0) {
      System.out.println("Not unique");
      return;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < M; j++) {
        sb.append(map[i + 1][j + 1]);
      }
      sb.append('\n');
    }
    System.out.print(sb.toString());
  }
}

