            int d = b + dy[i];
            if (!ok(c, d)) {
                continue;
            }
            if (i == 0) {
                f[a][b] = '<';
                f[c][d] = '>';
            } else if (i == 1) {
                f[a][b] = '>';
                f[c][d] = '<';
            } else if (i == 2) {
                f[a][b] = '^';
                f[c][d] = 'v';
            } else {
                f[a][b] = 'v';
                f[c][d] = '^';
            }
            return i;
        }
        return -1;
    }

    static int degree(int x, int y) {
        int ret = 0;
        for (int i = 0; i < 4; ++i) {
            int x1 = x + dx[i];
            int y1 = y + dy[i];
            if (ok(x1, y1)) {
                ++ret;
            }
        }
        return ret;
    }

    static void solve() throws IOException {
        n = in.nextInt();
        m = in.nextInt();
        f = new char[n][];
        for (int i = 0; i < n; ++i) {
            f[i] = in.nextToken().toCharArray();
        }
        int[] qx = new int[n * m];
        int[] qy = new int[n * m];
        int h = 0;
        int t = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (ok(i, j) && degree(i, j) == 1) {
                    qx[t] = i;
                    qy[t++] = j;
                }
            }
        }
        while (h < t) {
            int x = qx[h];
            int y = qy[h];
            ++h;
            if (!ok(x, y)) {
                continue;
            }
            int j = domino(x, y);
            if (j == -1) {
                out.println("Not unique");
                return;
            }
            x = x + dx[j];
            y = y + dy[j];
            for (int i = 0; i < 4; ++i) {
                int x1 = x + dx[i];
                int y1 = y + dy[i];
                if (ok(x1, y1) && degree(x1, y1) == 1) {
                    qx[t] = x1;
                    qy[t++] = y1;
                }
            }
        }
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (ok(i, j)) {
                    out.println("Not unique");
                    return;
                }
            }
        }
        for (int i = 0; i < n; ++i) {
            out.println(new String(f[i]));
        }
    }

    public void run() {
        try {
            in = new FastScanner();
            out = new PrintWriter(System.out);
            solve();
            out.close();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

