    static int qx[] = new int[4010000];
    static int qy[] = new int[4010000];
    static int n;
    static int m;
    public static void BFS(int x, int y)
    {
        int las = 0;
        int fir = -1;
        qx[0] = x;
        qy[0] = y;
        while(fir < las)
        {
            fir++;
            x = qx[fir];
            y = qy[fir];
            int h, k;
            if(s[x][y] != '.' || deg[x][y] != 1) continue;
            if(y - 1 >= 0 && s[x][y - 1] == '.')
            {
                h = x;
                k = y - 1;
                s[h][k] = '<';
                s[x][y] = '>';
            }
            else if(y + 1 < n && s[x][y + 1] == '.')
            {
                h = x;
                k = y + 1;
                s[x][y] = '<';
                s[h][k] = '>';
            }
            else if(x - 1 >= 0 && s[x - 1][y] == '.')
            {
                h = x- 1;
                k = y;
                s[h][k] = '^';
                s[x][y] = 'v';
            }
            else 
            {
                h = x + 1;
                k = y;
                s[x][y] = '^';
                s[h][k] = 'v';
            }
            for(int i = 0; i < 4; i++)
            {
                int hh = h + cx[i];
                int kk = k + cy[i];
                if(hh >= 0 && hh < m && kk >= 0 && kk < n && s[hh][kk] == '.')
                {
                    deg[hh][kk]--;
                    if(deg[hh][kk] == 1)
                    {
                        las++;
                        qx[las] = hh;
                        qy[las] = kk;
                    }
                }
                hh = x + cx[i];
                kk = y + cy[i];
                if(hh >= 0 && hh < m && kk >= 0 && kk < n && s[hh][kk] == '.')
                {
                    deg[hh][kk]--;
                    if(deg[hh][kk] == 1)
                    {
                        las++;
                        qx[las] = hh;
                        qy[las] = kk;
                    }
                }
            }
        }
    }
    public static void main(String args[])
    {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        m = in.readInt();
        n = in.readInt();
        for(int i = 0; i < m; i++)
            s[i] = in.readString().toCharArray();
        for(int[] row : deg)
            Arrays.fill(row, 0);
        for(int i = 0; i < m; i++)
            for(int j = 0; j < n; j++)
            if(s[i][j] == '.')
            {
                for(int l = 0; l < 4; l++)
                {
                    int h = i + cx[l];
                    int k = j + cy[l];
                    if(h >= 0 && h < m && k >= 0 && k < n && s[h][k] == '.')
                        deg[i][j]++;
                }
            }
        for(int i = 0; i < m; i++)
            for(int j = 0; j < n; j++)
                if(s[i][j]== '.' && deg[i][j] == 1)
                    BFS(i, j);
        for(int i = 0; i < m; i++)
            for(int j = 0; j < n; j++)
                if(s[i][j] == '.')
                {
                    out.println("Not unique");
                    out.flush();
                    out.close();
                    return;
                }
        for(int i = 0; i < m; i++)
            out.println(s[i]);
        out.flush();
        out.close();
    }

