class InputReader {

    private InputStream stream;
    private byte[] buf = new byte[1000];
    private int curChar, numChars;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public long readLong() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String readString() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuffer res = new StringBuffer();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    private String readLine0() {
        StringBuffer buf = new StringBuffer();
        int c = read();
        while (c != '\n' && c != -1) {
            buf.appendCodePoint(c);
            c = read();
        }
        return buf.toString();
    }

    public String readLine() {
        String s = readLine0();
        while (s.trim().length() == 0)
            s = readLine0();
        return s;
    }

    public String readLine(boolean ignoreEmptyLines) {
        if (ignoreEmptyLines)
            return readLine();
        else
            return readLine0();
    }

    public char readCharacter() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        return (char) c;
    }

    public double readDouble() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        double res = 0;
        while (!isSpaceChar(c) && c != '.') {
            if (c == 'e' || c == 'E')
                return res * Math.pow(10, readInt());
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        }
        if (c == '.') {
            c = read();
            double m = 1;
            while (!isSpaceChar(c)) {
                if (c == 'e' || c == 'E')
                    return res * Math.pow(10, readInt());
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                m /= 10;
                res += (c - '0') * m;
                c = read();
            }
        }
        return res * sgn;
    }
}

import java.io.*;
import java.util.*;

public class B {

    FastScanner in;
    PrintWriter out;

    int[] dx = new int[] { -1, 0, 1, 0 };
    int[] dy = new int[] { 0, 1, 0, -1 };

    void solve() {
        int n = in.nextInt(), m = in.nextInt();
        char[][] field = new char[n][m];
        for (int i = 0; i < n; i++) {
            field[i] = in.nextToken().toCharArray();
        }

        int[][] deg = new int[n][m];
        int[] queue = new int[2 * n * m];
        int head = 0, tail = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (field[i][j] == '*') {
                    continue;
                }
                for (int d = 0; d < 4; d++) {
                    int ni = i + dx[d], nj = j + dy[d];
                    if (0 <= ni && ni < n && 0 <= nj && nj < m
                            && field[ni][nj] == '.') {
                        deg[i][j]++;
                    }
                }
                if (deg[i][j] == 1) {
                    queue[tail++] = i;
                    queue[tail++] = j;
                }
            }
        }

        while (head < tail) {
            int i = queue[head++], j = queue[head++];
            if (field[i][j] != '.') {
                continue;
            }

            int foundI = -1, foundJ = -1;
            for (int d = 0; d < 4; d++) {
                int ni = i + dx[d], nj = j + dy[d];
                if (0 <= ni && ni < n && 0 <= nj && nj < m
                        && field[ni][nj] == '.') {
                    foundI = ni;
                    foundJ = nj;
                    break;
                }
            }
            if (foundI == -1 || foundJ == -1) {
                out.println("Not unique");
                return;
            }

            if (foundI == i) {
                field[i][Math.min(j, foundJ)] = '<';
                field[i][Math.max(j, foundJ)] = '>';
            } else {
                field[Math.min(i, foundI)][j] = '^';
                field[Math.max(i, foundI)][j] = 'v';

            }
            for (int d = 0; d < 4; d++) {
                int ni = foundI + dx[d], nj = foundJ + dy[d];
                if (0 <= ni && ni < n && 0 <= nj && nj < m
                        && field[ni][nj] == '.') {
                    deg[ni][nj]--;
                    if (deg[ni][nj] == 1) {
                        queue[tail++] = ni;
                        queue[tail++] = nj;
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (field[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            out.println(new String(field[i]));
        }
    }

    void run() {
        in = new FastScanner();
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public FastScanner(String s) {
            try {
                br = new BufferedReader(new FileReader(s));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }

    public static void main(String[] args) {
        new B().run();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;


public class DrazilTiles {

    int[] dx = new int[]{-1, 0, 0, 1};
    int[] dy = new int[]{0, -1, 1, 0};
    char[] dir = new char[]{'U', 'L', 'R', 'D'};

    void solve() {
        int n = in.nextInt(), m = in.nextInt();
        char[][] B = new char[n][];
        for (int i = 0; i < n; i++) B[i] = in.nextToken().toCharArray();

        int cnt = 0;
        int[][] deg = new int[n][m];
        Queue<int[]> qu = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (B[i][j] == '.') {
                    cnt++;
                    for (int k = 0; k < 4; k++) {
                        int x = i + dx[k], y = j + dy[k];
                        if (x >= 0 && x < n && y >= 0 && y < m && B[x][y] == '.') deg[i][j]++;
                    }
                    if (deg[i][j] == 1) qu.offer(new int[]{i, j});
                }
            }
        }

        while (!qu.isEmpty()) {
            int[] c = qu.poll();
            int x = c[0], y = c[1];
            if (B[x][y] != '.') continue;
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i], ny = y + dy[i];
                if (nx >= 0 && nx < n && ny >= 0 && ny < m && B[nx][ny] == '.') {
                    cnt -= 2;
                    switch (dir[i]) {
                        case 'U':
                            B[x][y] = 'v';
                            B[nx][ny] = '^';
                            break;
                        case 'D':
                            B[x][y] = '^';
                            B[nx][ny] = 'v';
                            break;
                        case 'L':
                            B[x][y] = '>';
                            B[nx][ny] = '<';
                            break;
                        case 'R':
                            B[x][y] = '<';
                            B[nx][ny] = '>';
                    }
                    for (int j = 0; j < 4; j++) {
                        int mx = nx + dx[j], my = ny + dy[j];
                        if (mx >= 0 && mx < n && my >= 0 && my < m && B[mx][my] == '.') {
                            if (--deg[mx][my] == 1) {
                                qu.offer(new int[]{mx, my});
                            }
                        }
                    }
                }
            }
        }

        if (cnt != 0) {
            out.println("Not unique");
