		for(int a=0;a<N;a++)grid[a]=sc.next().toCharArray();

		LinkedList<Integer> X = new LinkedList<Integer>();
		LinkedList<Integer> Y = new LinkedList<Integer>();
		for(int a=0;a<N;a++){
			for(int b=0;b<M;b++){
				X.add(b);
				Y.add(a);
				while(!X.isEmpty()){
					int x = X.poll();
					int y = Y.poll();
					if(grid[y][x]=='.'){
						int ways = 0;
						for(int d=0;d<4;d++){
							int nx = x+dx[d];
							int ny = y+dy[d];
							if(nx<0||ny<0||nx>=M||ny>=N)continue;
							if(grid[ny][nx]=='.')ways++;
						}
						if(ways==1){
							for(int d=0;d<4;d++){
								int nx = x+dx[d];
								int ny = y+dy[d];
								if(nx<0||ny<0||nx>=M||ny>=N)continue;
								if(grid[ny][nx]=='.'){
									if(d==0){
										grid[ny][nx]='^';
										grid[y][x]='v';
									}else if(d==1){
										grid[ny][nx]='v';
										grid[y][x]='^';
									}else if(d==2){
										grid[ny][nx]='<';
										grid[y][x]='>';
									}
									else if(d==3){
										grid[ny][nx]='>';
										grid[y][x]='<';
									}

									for(int dd=0;dd<4;dd++){
										int nnx = nx+dx[dd];
										int nny = ny+dy[dd];
										if(nnx<0||nny<0||nnx>=M||nny>=N)continue;
										X.add(nnx);
										Y.add(nny);
									}
								}
							}
						}
					}
				}
			}
		}
		boolean empty=  false;
		for(int a=0;a<N;a++){
			for(int b=0;b<M;b++){
				empty|=grid[a][b]=='.';
			}
