public class Main implements Runnable {

    int n, m;
    char [][] g;
    int [][] deg;
    int dx[] = {-1, 0, 1, 0};
    int dy[] = {0, -1, 0, 1};
    boolean [][] used;


    public void solve() throws IOException {
        n = nextInt();
        m = nextInt();
        String s;
        g = new char [n][];
        for (int i = 0 ; i < n ; i ++) {
            s = next();
            g[i] = s.toCharArray();
        }

        used = new boolean [n][m];

        deg = new int[n][m];
        Queue<Integer> q = new LinkedList<Integer>();

        for (int i = 0 ; i < n ; i ++) {
            for (int j = 0 ; j < m ; j ++) {
                if (g[i][j] == '*') continue;

                for (int k = 0 ; k < 4 ;k ++) {
                    int ii = i + dx[k], jj = j + dy[k];
                    if (ii < 0 || ii >= n || jj < 0 || jj >= m)
                        continue;
                    if (g[ii][jj] == '.')
                        deg[i][j] ++;
                }
                if (deg[i][j] == 1)
                    q.add(i * m + j);

            }
        }
        while (!q.isEmpty()) {
            int cur = q.poll();

            int i = cur / m, j = cur % m;
            if (g[i][j] != '.')
                continue;



            int it = -1, jt = -1;
            for (int k = 0 ; k < 4 ; k ++) {
                int ii = i + dx[k], jj = j + dy[k];
                if (ii < 0 || ii >= n || jj < 0 || jj >= m)
                    continue;



                if (g[ii][jj] == '.') {
                    it = ii;
                    jt = jj;
                    break;
                }
            }

            if (it < 0) {
                out.println("Not unique");
                return;
            }

            if (i == it) {
                if (j < jt) {
                    g[i][j] = '<';
                    g[i][jt] = '>';
                } else {
                    g[i][j] = '>';
                    g[i][jt] = '<';
                }
            } else {
                if (i > it) {
                    g[i][j] = 'v';
                    g[it][j] = '^';
                } else {
                    g[i][j] = '^';
                    g[it][j] = 'v';
                }
            }

            for (int k = 0 ; k < 4 ; k ++) {
                int ii = it + dx[k], jj = jt + dy[k];
                if (ii < 0 || ii >= n || jj < 0 || jj >= m)
                    continue;
                if (g[ii][jj] == '.' && !used[ii][jj] && deg[ii][jj] > 0) {
                    deg[ii][jj] --;
                    if (deg[ii][jj] == 1) {
                        q.add(ii * m + jj);
                        used[ii][jj] = true;
                    }
                }
            }
        }

        for (int i = 0 ; i < n ; i ++) {
            for (int j = 0 ; j < m ; j ++) {
                if (g[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }
        for (int i = 0 ; i < n ; i ++) {
            for (int j = 0 ; j < m ; j ++)
                out.print(g[i][j]);
            out.println();
        }

    }




