import java.util.*;
import java.io.*;

public class B
{
   public static void main(String[] args)
   {
      PrintWriter out = new PrintWriter(System.out);
      new B(new FastScanner(), out);
      out.close();
   }

   int R, C;
   int[][] type;

   int getId(int i, int j)
   {
      if (i < 0 || j < 0 || i >= R || j >= C) return -1;
      return i*C+j;
   }

   String dir = "^v<>";
   int[] dr = {-1, 1, 0, 0};
   int[] dc = {0, 0, -1, 1};
   int getDir(int ddr, int ddc)
   {
      for (int u=0; u<4; u++)
         if (dr[u] == ddr && dc[u] == ddc)
            return u;
      return -1;
   }

   int[] adj;
   void addEdge(int i, int j)
   {
      for (int u=0; u<4; u++)
         if (adj[i*4+u] == -1)
         {
            adj[i*4+u] = j;
            return;
         }
   }

   public B(FastScanner in, PrintWriter out)
   {
      R = in.nextInt();
      C = in.nextInt();
      type = new int[R][C];
      for (int i=0; i<R; i++)
      {
         String s = in.next();
         for (int j=0; j<C; j++)
            type[i][j] = s.charAt(j) == '*' ? -1 : -2;
      }

      int N = R*C;
      adj = new int[N*4];
      Arrays.fill(adj, -1);
      int[] loc = new int[N*2];

      for (int i=0; i<R; i++)
      {
         for (int j=0; j<C; j++) if (type[i][j] == -2)
         {
            int x = getId(i, j);
            loc[x*2] = i;
            loc[x*2+1] = j;
            for (int u=0; u<4; u++)
            {
               int nr = i+dr[u];
               int nc = j+dc[u];
               int y = getId(nr, nc);
               if (y != -1 && type[nr][nc] == -2)
                  addEdge(x, y);
            }
         }
      }

      int[] q = new int[N];
      int fptr = 0, bptr = 0;
      for (int i=0; i<N; i++)
      {
         int sz = 0;
         for (int u=0; u<4; u++)
            if (adj[i*4+u] != -1)
               sz++;
         if (sz == 1)
            q[bptr++] = i;
      }

      while (fptr < bptr)
      {
         int i = q[fptr++];
         int r = loc[i*2];
         int c = loc[i*2+1];

         int j = -1;
         for (int u=0; u<4; u++)
            if (adj[i*4+u] != -1)
            {
               j = adj[i*4+u];
               adj[i*4+u] = -1;
               break;
            }
         if (j == -1) continue;

         int r2 = loc[j*2];
         int c2 = loc[j*2+1];
         int d1 = getDir(r2-r, c2-c);
         int d2 = getDir(r-r2, c-c2);
         type[r2][c2] = d1;
         type[r][c] = d2;

         for (int u=0; u<4; u++)
         {
            int k = adj[j*4+u];
            if (k == -1) continue;
            int sz = 0;
            for (int p=0; p<4; p++)
               if (adj[k*4+p] == j)
                  adj[k*4+p] = -1;
               else if (adj[k*4+p] != -1)
                  sz++;
            if (sz == 1)
               q[bptr++] = k;
         }
      }

      for (int r=0; r<R; r++)
      {
         for (int c=0; c<C; c++)
         {
            if (type[r][c] == -2)
            {
               out.println("Not unique");
               return;
            }
         }
      }

      for (int r=0; r<R; r++)
      {
         for (int c=0; c<C; c++)
         {
            if (type[r][c] == -1)
               out.print('*');
            else
               out.print(dir.charAt(type[r][c]));
         }
         out.println();
      }
   }
}

