import java.io.BufferedInputStream;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;

public class D292 {
	static final int[] dr = {-1,0,1,0}, dc = {0,-1,0,1};
	static final char[] dir = {'v','>','^','<'};
	static int R, C;
	static char[][] mat;
	public static void main(String[] args) {
		Jolty scan = new Jolty(System.in);
		R = scan.nextInt();
		C = scan.nextInt();

		mat = new char[R][C];
		int[][] color = new int[R][C];
		for(int i=0;i<R;i++)mat[i] = scan.next().toCharArray();
		for(int i=0;i<R;i++)Arrays.fill(color[i], -1);
		color[0][0] = 0;
		ArrayDeque<Integer> q = new ArrayDeque<>();
		for(int i=0;i<R;i++){
			for(int j=0;j<C;j++){
				if(i==0&&j==0)continue;
				color[i][j] = (j!=0)?color[i][j-1]^1:1^color[i-1][j];
				if(mat[i][j]!='.')continue;
				if(check(i,j)){
					q.add(i);
					q.add(j);
				}
			}
		}
		while(!q.isEmpty()){
			int r = q.poll();
			int c = q.poll();
			for(int i=0;i<4;i++){
				int rr = r+dr[i], cc = c+dc[i];
				if(rr<0||rr>=R||cc<0||cc>=C||mat[rr][cc]!='.')continue;
				mat[r][c] = dir[i];
				mat[rr][cc] = dir[(i+2)%4];
				for(int j=0;j<4;j++){
					int rrr = rr+dr[j], ccc = cc+dc[j];
					if(rrr<0||rrr>=R||ccc<0||ccc>=C||mat[rrr][ccc]!='.')continue;
					if(check(rrr,ccc)){
						q.add(rrr);
						q.add(ccc);
					}
				}
			}
		}
		boolean done = true;
		for(int i=0;i<R;i++)for(int j=0;j<C;j++)done = (mat[i][j]=='.')?false:done;
		PrintWriter out = new PrintWriter(System.out);
		if(!done){
			out.println("Not unique");
		}else{
			for(int i=0;i<R;i++){
				for(int j=0;j<C;j++){
					out.print(mat[i][j]);
				}out.println();
			}
		}

		out.close();
	}
	private static boolean check(int r, int c) {
		int count = 0;
		for(int i=0;i<4;i++){
			int rr = r+dr[i], cc = c+dc[i];
			if(rr<0||rr>=R||cc<0||cc>=C)continue;
			if(mat[rr][cc]!='.')continue;
			count++;
		}
		return count==1;
	}
	private static class Jolty{
		static final int BASE_SPEED = 130;
		static final int BUFFER_SIZE = 1<<16;
		static final char NULL_CHAR = (char)-1;

		BufferedInputStream in;
		StringBuilder str = new StringBuilder();
		byte[] buffer = new byte[BUFFER_SIZE];

		char c = NULL_CHAR;
		int bufferIdx = 0, size = 0;

		public Jolty(InputStream in) {
			this.in = new BufferedInputStream(in,BUFFER_SIZE);
		}
		public int nextInt() {return (int)nextLong();}
		public double nextDouble() {return Double.parseDouble(next());}
		public long nextLong() {
			long negative = 0, res = 0;
			if(c==NULL_CHAR)c=nextChar();
			for(;(c<'0'||c>'9');c=nextChar())
				negative = (c=='-')?1:0;
			for(;c>='0'&&c<='9';c=nextChar())
				res = (res<<3)+(res<<1)+c-'0';
			return negative==1 ? -res : res;
		}

		public String nextLine() {
			str.setLength(0);
			for(c = c == NULL_CHAR ? nextChar() : c; c!='\n'; c= nextChar())
				str.append(c);
			c = NULL_CHAR;
			return str.toString();
		}
		public String next() {
			for(c = c == NULL_CHAR ? nextChar() : c; Character.isWhitespace(c);)
				c = nextChar();
			str.setLength(0);
			for(;!Character.isWhitespace(c);c=nextChar())
				str.append(c);
			return str.toString();
		}
		public char nextChar() {
			while(bufferIdx == size) {
				try{
					size = in.read(buffer);
					if(size == -1)throw new Exception();
				} catch (Exception e){}
				if(size == -1)size = BUFFER_SIZE;
				bufferIdx = 0;
			}
			return (char) buffer[bufferIdx++];
		}
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.LinkedList;
import java.util.Queue;

public class B {
	FastScanner in = new FastScanner(System.in);
	PrintWriter out = new PrintWriter(System.out);

	class Node {
		int x;
		int y;
		int nx, ny;

		Node(int x, int y, int nx, int ny) {
			this.x = x;
			this.y = y;
			this.nx = nx;
			this.ny = ny;
		}

		public String toString() {
			return "Node : " + x + " " + y + ", " + nx + " " + ny;
		}
	}

	int[] vx = {0, -1, 1, 0};
	int[] vy = {-1, 0, 0, 1};

	public void run() {
		int n = in.nextInt(), m = in.nextInt();
		char[][] map = new char[n][];

		Queue<Node> q = new LinkedList<Node>();
		for (int i = 0; i < n; i++) {
			map[i] = in.next().toCharArray();
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (map[i][j] == '.') {
					int sum = 0, xx = -1, yy = -1;
					for (int d = 0; d < 4; d++) {
						int nx = j + vx[d], ny = i + vy[d];
						if (nx >= 0 && nx < m && ny >= 0 && ny < n && map[ny][nx] == '.') { 
							sum++;
							xx = nx;
							yy = ny;
						}
					}
					if (sum == 1) {
						q.add(new Node(j, i, xx, yy));
					}
				}
			}
		}

		while (!q.isEmpty()) {
			Node nd = q.poll();
			if (map[nd.y][nd.x] != '.' || map[nd.ny][nd.nx] != '.') continue;

			if (nd.y - nd.ny == 1) {
				map[nd.y][nd.x] = 'v';
				map[nd.ny][nd.nx] = '^';
			} else if (nd.y - nd.ny == -1) {
				map[nd.y][nd.x] = '^';
				map[nd.ny][nd.nx] = 'v';
			} else if (nd.x - nd.nx == -1) {
				map[nd.y][nd.x] = '<';
				map[nd.ny][nd.nx] = '>';
			} else if (nd.x - nd.nx == 1) {
				map[nd.y][nd.x] = '>';
				map[nd.ny][nd.nx] = '<';
			}

			for (int dd = 0; dd < 4; dd++) {
				int i = nd.ny + vy[dd], j = nd.nx + vx[dd];
				if (i >= 0 && i < n && j >= 0 && j < m && map[i][j] == '.') {
					int sum = 0, xx = -1, yy = -1;
					for (int d = 0; d < 4; d++) {
						int nx = j + vx[d], ny = i + vy[d];
						if (nx >= 0 && nx < m && ny >= 0 && ny < n && map[ny][nx] == '.') { 
							sum++;
							xx = nx;
							yy = ny;
						}
					}
					if (sum == 1) {
						q.add(new Node(j, i, xx, yy));
					}
				}
			}
		}

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (map[i][j] == '.') {
					System.out.println("Not unique");
					return;
				}
			}
		}
		for (int i = 0; i < n; i++) {
			System.out.println(String.valueOf(map[i]));
		}
		out.close();
	}

	public static void main(String[] args) {
		new B().run();
	}

