        PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out));

        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int n = Integer.parseInt(tokenizer.nextToken());
        int m = Integer.parseInt(tokenizer.nextToken());

        map = new char[n][m];
        for(int i = 0 ; i < n ; i++)
            map[i] = reader.readLine().toCharArray();

        Queue<Integer> queue = new LinkedList<Integer>();
        boolean [][] visited = new boolean[n][m];

        for(int i = 0 ; i < n ; i++)
            for(int j = 0 ; j < m ; j++)
                if(map[i][j] == '.')
                    if(possibles(i, j) == 1)
                    {
                        visited[i][j] = true;
                        queue.offer(i);
                        queue.offer(j);
                    }

        while(!queue.isEmpty())
        {
            int x = queue.poll();
            int y = queue.poll();

            for(int d = 0 ; d < 4 ; d++)
            {
                int tx = x + dx[d];
                int ty = y + dy[d];

                if(tx < 0 || ty < 0 || tx >= n || ty >= m)
                    continue;
                if(map[tx][ty] != '.')
                    continue;

                if(tx < x)
                {
                    map[tx][ty] = '^';
                    map[x][y] = 'v';
                }
                else if(tx > x)
                {
                    map[tx][ty] = 'v';
                    map[x][y] = '^';
                }
                else if(ty < y)
                {
                    map[tx][ty] = '<';
                    map[x][y] = '>';
                }
                else
                {
                    map[tx][ty] = '>';
                    map[x][y] = '<';
                }

                for(int dd = 0 ; dd < 4 ; dd++)
                {
                    {
                        int ttx = tx + dx[dd];
                        int tty = ty + dy[dd];

                        if(ttx < 0 || tty < 0 || ttx >= n || tty >=m)
                            continue;
                        if(map[ttx][tty] != '.')
                            continue;
                        if(visited[ttx][tty])
                            continue;
                        if(possibles(ttx, tty) == 1)
                        {
                            queue.offer(ttx);
                            queue.offer(tty);
                            visited[ttx][tty] = true;
                        }
                    }


                    {
                        int ttx = x + dx[dd];
                        int tty = y + dy[dd];

                        if(ttx < 0 || tty < 0 || ttx >= n || tty >=m)
                            continue;
                        if(map[ttx][tty] != '.')
                            continue;
                        if(visited[ttx][tty])
                            continue;
                        if(possibles(ttx, tty) == 1)
                        {
                            queue.offer(ttx);
                            queue.offer(tty);
                            visited[ttx][tty] = true;
                        }
                    }
                }
            }
        }

        boolean res = true;
        for(int i = 0;  i < n ; i++)
            for(int j = 0 ; j < m ; j++)
                if(map[i][j] == '.')
                    res = false;
        if(!res)
        {
            writer.println(NO);
        }
        else
        {
            for (int i = 0; i < n; i++)
                writer.println(new String(map[i]));
        }

        writer.flush();
        writer.close();

    }

    private static int possibles(int x, int y)
    {
        int p = 0;
        for(int d = 0 ; d < 4 ; d++)
        {
            int tx = x + dx[d];
            int ty = y + dy[d];

            if(tx < 0 || ty < 0 || tx >= map.length || ty >= map[0].length)
                continue;
            if(map[tx][ty] != '.')
                continue;
            p++;
        }

        return p;
    }
}

