class ArrayUtil {
    static int lowerbs(int arr[], int start, int end, int key) {
        if(start + 1 < end) {
            int mid = start + (end - start)/2;
            if(arr[mid] <= key) {
                return lowerbs(arr, mid, end, key);
            } else {
                return lowerbs(arr, start, mid - 1, key);
            }
        } else {
            int idx = -1;
            for(int i = start; i <= end; i++) {
                if(arr[i] <= key) {
                    idx = i;
                }
            }
            return idx;
        }
    }
    static int upperbs(int arr[], int start, int end, int key) {
        if(start + 1 < end) {
            int mid = start + (end - start)/2;
            if(arr[mid] >= key) {
                return upperbs(arr, start, mid, key);
            } else {
                return upperbs(arr, mid + 1, end, key);
            }
        } else {
            int idx = -1;
            for(int i = start; i <= end; i++) {
                if(arr[i] >= key) {
                    idx = i;
                    break;
                }
            }
            return idx;
        }
    }
}
class Pair <Type1 extends Comparable<Type1>, Type2 extends Comparable<Type2>> implements Comparable <Pair<Type1, Type2>>{
    Type1 F;
    Type2 S;
    public Pair(Type1 F, Type2 S) {
        this.F = F;
        this.S = S;
    }
    @Override 
    public int compareTo(Pair <Type1, Type2> p) {
        if(F.compareTo(p.F) == 0)
            return S.compareTo(p.S);
        return F.compareTo(p.F);
    }
}

