    public static boolean ch(int x, int y){
        if (x>=0 && x<n && y>=0 && y<m && b[x][y]=='.') return true;
        return false;
    }

    public static int dg (int x, int y){
        int c=0;
        if (ch(x+1,y)) c+=1;
        if (ch(x-1,y)) c+=1;
        if (ch(x,y+1)) c+=1;
        if (ch(x,y-1)) c+=1;
        return c;
    }

    public static int f(int x, int y) {
        int c=-1;
        if (ch(x-1,y)) c=0;
        if (ch(x,y+1)) c=1;
        if (ch(x+1,y)) c=2;
        if (ch(x,y-1)) c=3;
        return c;
    }

    public static void main (String[] args) throws java.lang.Exception
    {

        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
