        for(int i=0; i<n; i++) {
            for(int j=0; j<m; j++) {
                if(ch(i,j)&&dg(i,j)==1) q.add(i*m+j);
            }
        }

        char[] sy={'v','<','^','>'};
        int[] nx={-1,0,1,0};
        int[] ny={0,1,0,-1};

