import static java.lang.Math.*;
public class B {

    public static final int[] VR = {1, 0, -1, 0};
    public static final int[] VC = {0, 1, 0, -1};
    public static final char[] S1 = {'^', '<', 'v', '>'};
    public static final char[] S2 = {'v', '>', '^', '<'};

    public B() throws Exception {
        int R = in.nextInt();
        int C = in.nextInt();
        char[][] map = new char[R][];
        for (int r=0; r<R; r++) map[r] = in.next().toCharArray();
        int empty = 0;
        int[][] deg = new int[R][C];
        Queue<Integer> queue = new LinkedList<Integer>();
        for (int r=0; r<R; r++) {
            for (int c=0; c<C; c++) {
                if (map[r][c]!='.') continue;
                empty++;
                for (int i=0; i<4; i++) {
                    int nr = r+VR[i];
                    int nc = c+VC[i];
                    if (nr<0||nr>=R||nc<0||nc>=C) continue;
                    if (map[nr][nc]!='.') continue;
                    deg[r][c]++;
                }

                if (deg[r][c]==1) {
                    queue.add(r);
                    queue.add(c);
                }
            }
        }

        while (!queue.isEmpty()) {
            int r = queue.poll();
            int c = queue.poll();

            for (int i=0; i<4; i++) {
                int nr = r+VR[i];
                int nc = c+VC[i];
                if (nr<0||nr>=R||nc<0||nc>=C) continue;
                if (map[nr][nc]!='.') continue;
                empty -= 2;
                map[r][c] = S1[i];
                map[nr][nc] = S2[i];

                for (int j=0; j<4; j++) {
                    int fr = nr+VR[j];
                    int fc = nc+VC[j];
                    if (fr<0||fr>=R||fc<0||fc>=C) continue;
                    if (map[fr][fc]!='.') continue;
                    deg[fr][fc]--;
                    if (deg[fr][fc]==1) {
                        queue.add(fr);
                        queue.add(fc);
                    }
                }
            }
        }

        if (empty > 0) {
           buf.append("Not unique\n");
        } else {
            for (int r=0; r<R; r++) {
                for (int c=0; c<C; c++) {
                    buf.append(map[r][c]);
                }
                buf.append('\n');
            }
        }

    }

    public static Scanner in = new Scanner(System.in);
    public static StringBuilder buf = new StringBuilder();
    public static void debug(Object... arr) { 
        System.err.println(Arrays.deepToString(arr));
    } 
    public static void main(String[] args) throws Exception { 
        new B();
        System.out.print(buf);
    } 
}

