            g[i] = in.readLine().toCharArray();

        int nx,ny,tx,ty;
        int [][] deg = new int[n][m];
        for(int i=0; i<n; i++) {
            for(int j=0; j<m; j++) {
                if(g[i][j]=='*') continue;
                for(int k=0; k<4; k++) {
                    nx = i+dx[k];
                    ny = j+dy[k];

                    if(nx<0 || ny<0 || nx>=n || ny>=m || g[nx][ny]=='*') continue;

                    deg[i][j]++;
                }
            }
        }

        Queue<point> q = new LinkedList<>();
        for(int i=0; i<n; i++)
            for(int j=0; j<m; j++)
                if(deg[i][j]==1)
                    q.add(new point(i,j));
