        while(!q.isEmpty()) {
            p = q.remove();

            for(int i=0; i<4; i++) {
                nx = p.x+dx[i];
                ny = p.y+dy[i];

                if(nx>=0 && nx<n && ny>=0 && ny<m && g[nx][ny]=='.') {
                    g[p.x][p.y] = d1[i];
                    g[nx][ny] = d2[i];

                    for(int j=0; j<4; j++) {
                        tx = nx+dx[j];
                        ty = ny+dy[j];

                        if(tx>=0 && tx<n && ty>=0 && ty<m && g[tx][ty]=='.') {
                            deg[tx][ty]--;
                            if(deg[tx][ty]==1) q.add(new point(tx,ty));
                        }
                    }
                    break;
                }
            }
        }

        for(int i=0; i<n; i++) {
            for(int j=0; j<m; j++) {
                if(g[i][j]=='.') {
                    System.out.println("Not unique");
