        n = Integer.parseInt(s1[0]);
        m = Integer.parseInt(s1[1]);
        A = new char[n][m];
        for (int i=0;i<n;i++)   A[i] = in.readLine().toCharArray();
        for (int i=0;i<n;i++)   for (int j=0;j<m;j++)   if (A[i][j] == '.') explore(i, j);
        boolean ff = true;
        for (int i=0;i<n;i++)   for (int j=0;j<m;j++)
        {
            if (A[i][j] == '.')
            {
                ff = false;
                break;
            }
        }
        if (ff)
        {
            StringBuilder stringBuilder = new StringBuilder();
            for (int i=0;i<n;i++)
            {
                for (int j=0;j<m;j++)   stringBuilder.append(A[i][j]);
                stringBuilder.append("\n");
            }
            System.out.println(stringBuilder);
        }
        else
            System.out.println("Not unique");
    }
    public static void explore(int x, int y)
    {
        int deg = deg(x, y);
        if (deg > 1 || deg < 1) return;
        int nx = -1;
        int ny = -1;
        for (int i=0;i<4;i++)
        {
            int xx = x + dx[i];
            int yy = y + dy[i];
            if (inBounds(xx, yy))
            {
                if (A[xx][yy] == '.')
                {
                    nx = xx;    ny = yy;
                }
            }
        }
        if (nx == x)
        {
            if (ny == y - 1)
            {
                A[nx][ny] = '<';
                A[x][y] = '>';
            }
            else
            {
                A[nx][ny] = '>';
                A[x][y] = '<';
            }
        }
        else
        {
            if (nx == x - 1)
            {
                A[nx][ny] = '^';
                A[x][y] = 'v';
            }
            else
            {
                A[nx][ny] = 'v';
                A[x][y] = '^';
            }
        }
        for (int i=0;i<4;i++)
        {
            int xx = x + dx[i];
            int yy = y + dy[i];
            if (inBounds(xx, yy) && A[xx][yy] == '.')
                explore(xx, yy);
        }
        for (int i=0;i<4;i++)
        {
            int xx = nx + dx[i];
            int yy = ny + dy[i];
            if (inBounds(xx, yy) && A[xx][yy] == '.')
                explore(xx, yy);
        }
    }
    public static int deg(int x, int y)
    {
        int count = 0;
        for (int i=0;i<4;i++)
        {
            int xx = x + dx[i];
            int yy = y + dy[i];
            if (inBounds(xx, yy) && A[xx][yy] == '.')
                count++;
        }
        return count;
    }
    public static boolean inBounds(int x, int y)
    {
        return x >= 0 && x < n && y >= 0 && y < m;
    }
}
class Reader
{
    final private int BUFFER_SIZE = 1 << 16;
    private DataInputStream din;
    private byte[] buffer;
    private int bufferPointer, bytesRead;

    public Reader()
    {
        din = new DataInputStream(System.in);
        buffer = new byte[BUFFER_SIZE];
        bufferPointer = bytesRead = 0;
    }

    public Reader(String file_name) throws IOException
    {
        din = new DataInputStream(new FileInputStream(file_name));
        buffer = new byte[BUFFER_SIZE];
        bufferPointer = bytesRead = 0;
    }

    public String readLine() throws IOException
    {
        byte[] buf = new byte[64]; 
        int cnt = 0, c;
        while ((c = read()) != -1)
        {
            if (c == '\n')
                break;
            buf[cnt++] = (byte) c;
        }
        return new String(buf, 0, cnt);
    }

    public int nextInt() throws IOException
    {
        int ret = 0;
        byte c = read();
        while (c <= ' ')
            c = read();
        boolean neg = (c == '-');
        if (neg)
            c = read();
        do
        {
            ret = ret * 10 + c - '0';
        }  while ((c = read()) >= '0' && c <= '9');

        if (neg)
            return -ret;
        return ret;
    }

    public long nextLong() throws IOException
    {
        long ret = 0;
        byte c = read();
        while (c <= ' ')
            c = read();
        boolean neg = (c == '-');
        if (neg)
            c = read();
        do {
            ret = ret * 10 + c - '0';
        }
        while ((c = read()) >= '0' && c <= '9');
        if (neg)
            return -ret;
        return ret;
    }

    public double nextDouble() throws IOException
    {
        double ret = 0, div = 1;
        byte c = read();
        while (c <= ' ')
            c = read();
        boolean neg = (c == '-');
        if (neg)
            c = read();

        do {
            ret = ret * 10 + c - '0';
        }
        while ((c = read()) >= '0' && c <= '9');

        if (c == '.')
        {
            while ((c = read()) >= '0' && c <= '9')
            {
                ret += (c - '0') / (div *= 10);
            }
        }

        if (neg)
            return -ret;
        return ret;
    }

    private void fillBuffer() throws IOException
    {
        bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
        if (bytesRead == -1)
            buffer[0] = -1;
    }

    private byte read() throws IOException
    {
        if (bufferPointer == bytesRead)
            fillBuffer();
        return buffer[bufferPointer++];
    }

    public void close() throws IOException
    {
        if (din == null)
            return;
        din.close();
    }
}

import java.io.*;
