public class B {
    FastScanner in;
    PrintWriter out;
    int n, m;
    char[][] s;
    int[] di = {1, -1, 0, 0};
    int[] dj = {0, 0, 1, -1};

    public int check(int i, int j) {
        int count = 0;
        if (i + 1 == n || s[i + 1][j] != '.') {
            count++;
        }
        if (i - 1 == -1 || s[i - 1][j] != '.') {
            count++;
        }
        if (j + 1 == m || s[i][j + 1] != '.') {
            count++;
        }
        if (j - 1 == -1 || s[i][j - 1] != '.') {
            count++;
        }
        return count;
    }

    public int ifThree(int i, int j) {
        if (i + 1 != n && s[i + 1][j] == '.') {
            return 0;
        }
        if (i - 1 != -1 && s[i - 1][j] == '.') {
            return 1;
        }
        if (j + 1 != m && s[i][j + 1] == '.') {
            return 2;
        }
        if (j - 1 != -1 && s[i][j - 1] == '.') {
            return 3;
        }
        return -1;
    }

    public void set(int i, int j, int type) {
        switch (type) {
            case 0:
                s[i][j] = '^';
                break;
            case 1:
                s[i][j] = 'v';
                break;
            case 2:
                s[i][j] = '<';
                break;
            case 3:
                s[i][j] = '>';
                break;
        }

    }

    public boolean dfs(int i, int j) {
        if (i < 0 || i >= n || j < 0 || j >= m || s[i][j] != '.') {
            return true;
        }
        if (check(i, j) == 4) {
            return false;
        }
        boolean flag = true;
        if (check(i, j) == 3) {
            int ni = i + di[ifThree(i, j)];
            int nj = j + dj[ifThree(i, j)];
            set(i, j, ifThree(i, j));
            set(ni, nj, ifThree(i, j) ^ 1);
            for (int k = 0; k < 4; k++) {
                flag &= dfs(ni + di[k], nj + dj[k]);
            }
        }
        return flag;
    }


    public void solve() throws IOException {
        n = in.nextInt();
        m = in.nextInt();
        s = new char[n][];
        Arrays.setAll(s, i -> in.next().toCharArray());
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!dfs(i, j)) {
                    out.println("Not unique");
                    return;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(s[i][j]);
            }
            out.println();
        }
    }

    public void run() {
        try {
            in = new FastScanner(System.in);
            out = new PrintWriter(System.out);
            Locale.setDefault(Locale.US);

            solve();

            out.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] arg) {
        new B().run();
    }
}

