class TaskB {
    final int[] di = { 1, 0, -1, 0 };
    final int[] dj = { 0, -1, 0, 1};
    char[][] A;
    Queue<Integer> Q;
    int N;
    int M;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        N = in.nextInt();
        M = in.nextInt();
        A = new char[N][];
        for (int i = 0; i < N; i++) {
            A[i] = in.nextString().toCharArray();
        }
        int[][] G = new int[N][M];
        Q = new LinkedList<Integer>();
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (A[i][j] == '.') {
                    int cnt = 0;
                    for (int d = 0; d < 4; d++) {
                        int ni = i + di[d];
                        int nj = j + dj[d];
                        if (ni >= 0 && ni < N && nj >= 0 && nj < M && A[ni][nj] == '.') {
                            cnt++;
                        }
                    }
                    G[i][j] = cnt;
                    if (G[i][j] == 1) {
                        Q.add(i);
                        Q.add(j);
                    }
                }
            }
        }
        while (!Q.isEmpty()) {
            int pi = Q.remove();
            int pj = Q.remove();
            if (A[pi][pj] != '.') continue;
            for (int d = 0; d < 4; d++) {
                int ni = pi + di[d];
                int nj = pj + dj[d];
                if (ni >= 0 && ni < N && nj >= 0 && nj < M && A[ni][nj] == '.') {
                    G[ni][nj]--;
                    if (G[ni][nj] == 1) {
                        Q.add(ni);
                        Q.add(nj);
                    }
                }
            }
            int mi = -1;
            int mj = -1;
            for (int d = 0; d < 4; d++) {
                int ni = pi + di[d];
                int nj = pj + dj[d];
                if (ni >= 0 && ni < N && nj >= 0 && nj < M && A[ni][nj] == '.') {
                    mark(pi, pj, ni, nj);
                    mi = ni;
                    mj = nj;
                    break;
                }
            }
            if (mi == -1) continue;
            for (int d = 0; d < 4; d++) {
                int ni = mi + di[d];
                int nj = mj + dj[d];
                if (ni >= 0 && ni < N && nj >= 0 && nj < M && A[ni][nj] == '.') {
                    G[ni][nj]--;
                    if (G[ni][nj] == 1) {
                        Q.add(ni);
                        Q.add(nj);
                    }
                }
            }
        }

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (A[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        for (int i = 0; i < N; i++) {
            out.println(A[i]);
        }
    }

    private void mark(int pi, int pj, int ni, int nj) {
        if (pi == ni) { 
            if (pj > nj) {
                int aux = pj; pj = nj; nj = aux;
            }
            A[pi][pj] = '<';
            A[ni][nj] = '>';
        }
        else { 
            if (pi > ni) {
                int aux = pi; pi = ni; ni = aux;
            }
            A[pi][pj] = '^';
            A[ni][nj] = 'v';
        }
    }
}

class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int nextInt() {
        return Integer.parseInt(nextString());
    }

    public String nextString() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuffer res = new StringBuffer();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));

        return res.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringTokenizer;

public class CF292_B {


	public static void main(String[] args) {

		MyScanner in = new MyScanner();
		String notUnique = "Not unique";

		int nRows = in.nextInt();
		int nCols = in.nextInt();

		char[][] board = new char[nRows + 2][nCols + 2];
		Arrays.fill(board[0], '*');
		Arrays.fill(board[board.length - 1], '*');
		for (int i = 1; i <= nRows; i++) {
			char[] row = in.next().toCharArray();
			board[i][0] = '*';
			board[i][board[i].length - 1] = '*';
			for (int j = 0; j < row.length; j++) {
				board[i][j + 1] = row[j];
			}
		}


		int nEmpties = 0;
		for (int i = 0; i < board.length; i++) {
			for (int j = 0; j < board[i].length; j++) {
				if (board[i][j] == '.') {
					nEmpties++;
				}
			}
		}
		if (nEmpties % 2 == 1) {
			System.out.println(notUnique);
			return;
		}

		ArrayDeque<Integer> toProcI = new ArrayDeque<Integer>();
		ArrayDeque<Integer> toProcJ = new ArrayDeque<Integer>();
		ArrayDeque<Integer> toProcDir = new ArrayDeque<Integer>();
		int UP = 0;
		int DOWN = 1;
		int RIGHT = 2;
		int LEFT = 3;
		int[] delI = { 1, -1, 0, 0 };
		int[] delJ = { 0, 0, 1, -1 };


		for (int i = 0; i < board.length; i++) {
			for (int j = 0; j < board[i].length; j++) {
				if (board[i][j] == '.') {
					int count = 0;
					int dir = -1;
					if (board[i + 1][j] == '.') {
						count++;
						dir = UP;
					}
					if (board[i - 1][j] == '.') {
						count++;
						dir = DOWN;
					}
					if (board[i][j + 1] == '.') {
						count++;
						dir = RIGHT;
					}
					if (board[i][j - 1] == '.') {
						count++;
						dir = LEFT;
					}
					if (count == 1) {
						toProcI.add(i);
						toProcJ.add(j);
						toProcDir.add(dir);
					}
				}
			}
		}


		while (!toProcI.isEmpty()) {

			int i0 = toProcI.pop();
			int j0 = toProcJ.pop();
			int dir0 = toProcDir.pop();

			int toFillI = i0 + delI[dir0];
			int toFillJ = j0 + delJ[dir0];


			if (board[i0][j0] != '.' || board[toFillI][toFillJ] != '.') {
				continue;
			}

			nEmpties -= 2;

			if (dir0 == UP) {
				board[i0][j0] = '^';
				board[toFillI][toFillJ] = 'v';
			}
			if (dir0 == DOWN) {
				board[i0][j0] = 'v';
				board[toFillI][toFillJ] = '^';
			}
			if (dir0 == LEFT) {
				board[i0][j0] = '>';
				board[toFillI][toFillJ] = '<';
			}
			if (dir0 == RIGHT) {
				board[i0][j0] = '<';
				board[toFillI][toFillJ] = '>';
			}

			for (int iDirCheck = 0; iDirCheck < 4; iDirCheck++) {

				int i = toFillI + delI[iDirCheck];
				int j = toFillJ + delJ[iDirCheck];

				if (board[i][j] == '.') {
					int count = 0;
					int dir = -1;
					if (board[i + 1][j] == '.') {
						count++;
						dir = UP;
					}
					if (board[i - 1][j] == '.') {
						count++;
						dir = DOWN;
					}
					if (board[i][j + 1] == '.') {
						count++;
						dir = RIGHT;
					}
					if (board[i][j - 1] == '.') {
						count++;
						dir = LEFT;
					}
					if (count == 1) {
						toProcI.add(i);
						toProcJ.add(j);
						toProcDir.add(dir);
					}
				}

			}

		}

		if (nEmpties != 0) {
			System.out.println(notUnique);
			return;
		}

		StringBuilder sb = new StringBuilder();
		for (int i = 1; i < board.length - 1; i++) {
			for (int j = 1; j < board[i].length - 1; j++) {
				sb.append(board[i][j]);
			}
			sb.append('\n');
		}

		System.out.print(sb);

	}


