import java.io.*;
import java.util.*;

public class Solution {

    BufferedReader br;
    PrintWriter out;
    StringTokenizer st;
    boolean eof;

    static final int Mod = 1000000007;
    static final int max = 2222;

    int deg[][], q[], n, m;
    char s[][];
    static final int dx[] = {1, -1, 0, 0};
    static final int dy[] = {0, 0, 1, -1};

    boolean isValid(int x, int y) {
        return (x >= 0 && x < n && y >= 0 && y < m);
    }

    void mark(int x1, int y1, int x2, int y2) {
        if (x1 == x2) {
            if (y1 > y2) {
                int tmp = y2;
                y2 = y1;
                y1 = tmp;
            }
            s[x1][y1] = '<';
            s[x2][y2] = '>';
        } else {
            if (x1 > x2) {
                int tmp = x1;
                x1 = x2;
                x2 = tmp;
            }
            s[x1][y1] = '^';
            s[x2][y2] = 'v';
        }
    }

    void solve() throws IOException {
        n = nextInt();
        m = nextInt();
        s = new char[n][m];
        deg = new int[n][m];
        q = new int[max*max];
        for (int i = 0; i < n; i++) {
            s[i] = nextString().toCharArray();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s[i][j] == '*') continue;
                for (int d = 0; d < 4; d++) {
                    int nx = i + dx[d];
                    int ny = j + dy[d];
                    if (isValid(nx, ny) && s[nx][ny] == '.')
                        deg[i][j]++;
                }
            }
        }
        int head = 0, tail = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (deg[i][j] == 1)
                    q[tail++] = i * m + j;
            }
        }
        while (head < tail) {
            int v = q[head++];
            int cx = v / m;
            int cy = v % m;
            if (s[cx][cy] != '.') continue;
            for (int d = 0; d < 4; d++) {
                int nx = cx + dx[d];
                int ny = cy + dy[d];
                if (!isValid(nx, ny) || s[nx][ny] != '.') continue;
                mark(nx, ny, cx, cy);
                for (int i = 0; i < 4; i++) {
                    int x = nx + dx[i];
                    int y = ny + dy[i];
                    if (isValid(x, y) && s[x][y] == '.') {
                        deg[x][y]--;
                        if (deg[x][y] == 1) {
                            q[tail++] = x * m + y;
                        }
                    }
                }
            }
        }
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (s[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(s[i][j]);
            }
            out.println();
        }

    }

    Solution() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new Solution();
    }

    String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                eof = true;
                return null;
            }
        }
        return st.nextToken();
    }

    String nextString() {
        try {
            return br.readLine();
        } catch (IOException e) {
            eof = true;
            return null;
        }
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }
}

