public class B {
    public static void main(String[] args) throws IOException {
        final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String s = reader.readLine();
        String[] split = s.split("\\s");
        int n = parseInt(split[0]);
        int m = parseInt(split[1]);
        final int[][] map = new int[n + 2][m + 2];
        for (int[] ints : map) {
            Arrays.fill(ints, 1);
        }
        for (int i = 0; i < n; i++) {
            s = reader.readLine();
            for (int j = 0; j < m; j++) {
                map[i + 1][j + 1] = s.charAt(j) == '.' ? 0 : 1;
            }
        }

        if (!get(n, m, map)) {
            System.out.println("Not unique");
        }
    }

    public static boolean get(int n, int m, int[][] map) {
        final int[][] d = new int[n + 2][m + 2];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (map[i][j] != 0) continue;

                d[i][j] += map[i - 1][j] == 0 ? 1 : 0;
                d[i][j] += map[i + 1][j] == 0 ? 1 : 0;
                d[i][j] += map[i][j - 1] == 0 ? 1 : 0;
                d[i][j] += map[i][j + 1] == 0 ? 1 : 0;
            }
        }

        boolean more = true;
        while (more) {
            boolean ok = true;
            more = false;
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (map[i][j] == 0 && d[i][j] == 1) {
                        more = true;
                        int k = i, l = j;
                        while (map[k][l] == 0 && d[k][l] == 1) {

                            if (map[k - 1][l] == 0) {
                                map[k][l] = 2;
                                map[k - 1][l] = 3;


                                relax(d, k, l);
                                k--;
                                relax(d, k, l);
                                if (d[k - 1][l] == 1) k--;
                                if (d[k][l - 1] == 1) l--;
                                if (d[k][l + 1] == 1) l++;
                                continue;
                            }

                            if (map[k][l - 1] == 0) {
                                map[k][l] = 4;
                                map[k][l - 1] = 5;

                                relax(d, k, l);
                                l--;
                                relax(d, k, l);
                                if (d[k - 1][l] == 1) k--;
                                if (d[k + 1][l] == 1) k++;
                                if (d[k][l - 1] == 1) l--;
                                continue;
                            }

                            if (map[k + 1][l] == 0) {
                                map[k][l] = 3;
                                map[k + 1][l] = 2;

                                relax(d, k, l);
                                k++;
                                relax(d, k, l);
                                if (d[k + 1][l] == 1) k++;
                                if (d[k][l - 1] == 1) l--;
                                if (d[k][l + 1] == 1) l++;
                                continue;
                            }

                            if (map[k][l + 1] == 0) {
                                map[k][l] = 5;
                                map[k][l + 1] = 4;

                                relax(d, k, l);
                                l++;
                                relax(d, k, l);
                                if (d[k - 1][l] == 1) k--;
                                if (d[k + 1][l] == 1) k++;
                                if (d[k][l + 1] == 1) l++;
                                continue;
                            }

                            return false;
                        }
                    } else if (map[i][j] == 0) {
                        ok = false;
                    }
                }
            }

            if (!ok && !more) return false;
        }

        for (int i = 1; i <= n; i++) {
            final StringBuilder builder = new StringBuilder();
            for (int j = 1; j <= m; j++) {
                if (map[i][j] == 1) {
                    builder.append('*');
                    continue;
                }

                switch (map[i][j]) {
                    case 2:
                        builder.append('v');
                        break;
                    case 3:
                        builder.append('^');
                        break;
                    case 4:
                        builder.append('>');
                        break;
                    case 5:
                        builder.append('<');
                        break;
                    default:

                }
            }
            System.out.println(builder.toString());
        }


        return true;
    }

    private static void relax(int[][] d, int k, int l) {
        if (d[k - 1][l] > 0) d[k - 1][l] -= 1;
        if (d[k + 1][l] > 0) d[k + 1][l] -= 1;
        if (d[k][l - 1] > 0) d[k][l - 1] -= 1;
        if (d[k][l + 1] > 0) d[k][l + 1] -= 1;
    }
}

