class TaskB {
    public void solve(int testNumber, Scanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        String [] A = new String[n];
        int [][] a = new int[n][m];
        for (int i = 0; i < n; i++) {
            A[i] = in.next();
            for (int j = 0; j < m; j++) {
                a[i][j] = (A[i].charAt(j) == '.' ? 1 : 0);
            }
        }
        int [][] b = new int[n][m];
        Queue<Integer> Q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if(a[i][j] == 1) {
                    b[i][j] = add(i, j, a);
                    if(b[i][j] == 0) {
                        out.print("Not unique");
                        return;
                    }
                    if(b[i][j] == 1) {
                        Q.add(i);
                        Q.add(j);
                    }
                } else {
                    b[i][j] = -10000000;
                }
            }
        }

        while(!Q.isEmpty()) {
            int ci = Q.remove();
            int cj = Q.remove();

            if(a[ci][cj] != 1) continue;
            if(b[ci][cj] != 1) {
                out.print("Not unique");
                return;
            }
            int ni = 0, nj = 0;
            if(valid(ci-1, cj, a) == 1) {
                ni = ci-1; nj = cj;
            }
            if(valid(ci+1, cj, a) == 1) {
                ni = ci+1; nj = cj;
            }
            if(valid(ci, cj-1, a) == 1) {
                ni = ci; nj = cj-1;
            }
            if(valid(ci, cj+1, a) == 1) {
                ni = ci; nj = cj+1;
            }


            b[ci][cj] = -(ni * 3000 + nj);
            b[ni][nj] = -(ci * 3000 + cj);
            a[ci][cj] = 0;
            a[ni][nj] = 0;

            if(valid(ni-1, nj, a) == 1) {
                b[ni-1][nj]--;
                if(b[ni-1][nj] == 1) {
                    Q.add(ni-1);
                    Q.add(nj);
                }
            }
            if(valid(ni+1, nj, a) == 1) {
                b[ni+1][nj]--;
                if(b[ni+1][nj] == 1) {
                    Q.add(ni+1);
                    Q.add(nj);
                }
            }
            if(valid(ni, nj-1, a) == 1) {
                b[ni][nj-1]--;
                if(b[ni][nj-1] == 1) {
                    Q.add(ni);
                    Q.add(nj-1);
                }
            }
            if(valid(ni, nj+1, a) == 1) {
                b[ni][nj+1]--;
                if(b[ni][nj+1] == 1) {
                    Q.add(ni);
                    Q.add(nj+1);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if(b[i][j] > 0) {

                    out.println("Not unique");
                    return;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if(b[i][j] == -10000000) {
                    out.print('*');
                } else {
                    int tp = -b[i][j];
                    int nj = tp % 3000;
                    int ni = tp / 3000;
                    if(ni == i) {
                        out.print(nj < j ? '>' : '<');
                    } else {
                        out.print(ni < i ? 'v' : '^');
                    }
                }
            }
            out.println();
        }
    }

    private int add(int i, int j, int[][] a) {
        int ret = 0;
        ret += valid(i-1, j, a);
        ret += valid(i+1, j, a);
        ret += valid(i, j-1, a);
        ret += valid(i, j+1, a);
        return ret;
    }

    private int valid(int i, int j, int[][] a) {
        if(i < 0 || j < 0) return 0;
        if( (i >= a.length) || (j >= a[0].length)) return 0;
        return a[i][j];
    }
}

