	private final int[] dx = {0, 1, 0, -1}, dy = {-1, 0, 1, 0};
	private final char[][] tile = {{'v', '^'}, {'<', '>'}, {'^', 'v'}, {'>', '<'}};
	private int n;
	private int m;
	private char[][] map;

	public boolean isLegal(int x, int y)
	{
		return x >= 0 && x < m && y >= 0 && y < n;
	}

	public boolean topo()
	{
		Queue<Point> q = new LinkedList<Point>();
		int[][] deg = new int[n][m];
		for(int i = 0;i < n;++i)
		{
			for(int j = 0;j < m;++j)
			{
				if(map[i][j] != '.')
				{
					continue;
				}
				for(int k = 0;k < 4;++k)
				{
					int xNext = j + dx[k];
					int yNext = i + dy[k];
					if(isLegal(xNext, yNext) && '.' == map[yNext][xNext])
					{
						++deg[i][j];
					}
				}
				if(1 == deg[i][j])
				{
					q.offer(new Point(j, i));
				}
			}
		}
		while(!q.isEmpty())
		{
			Point p = q.poll();
			deg[p.y][p.x] = 0;
			for(int k = 0;k < 4;++k)
			{
				int xNext = p.x + dx[k];
				int yNext = p.y + dy[k];
				if(isLegal(xNext, yNext) && '.' == map[yNext][xNext])
				{
					map[p.y][p.x] = tile[k][0];
					map[yNext][xNext] = tile[k][1];
					for(int h = 0;h < 4;++h)
					{
						int xNextNext = xNext + dx[h];
						int yNextNext = yNext + dy[h];
						if(isLegal(xNextNext, yNextNext))
						{
							--deg[yNextNext][xNextNext];
							if(1 == deg[yNextNext][xNextNext])
							{
								q.offer(new Point(xNextNext, yNextNext));
							}
						}
					}
					break;
				}
			}
		}
		for(int i = 0;i < n;++i)
		{
			for(int j = 0;j < m;++j)
			{
				if('.' == map[i][j])
				{
					return false;
				}
			}
		}
		return true;
	}

