		int res = 0;
		for (int i = 0; i < 4; ++i) {
			int nx = x + dy[i];
			int ny = y + dx[i];
			if (check(nx, ny) && a[nx][ny] == '.') {
				++res;
			}
		}
		return res;
	}

	void set(int x, int y, char c, Queue<Integer> qx, Queue<Integer> qy) {
		a[x][y] = c;
		for (int i = 0; i < 4; ++i) {
			int nx = x + dy[i];
			int ny = y + dx[i];
			if (check(nx, ny) && a[nx][ny] == '.' && get(nx, ny) == 1) {
				qx.add(nx);
				qy.add(ny);
			}
		}
