				continue;
			}
			boolean ok = false;
			for (int i = 0; i < 4; ++i) {
				int nx = x + dy[i];
				int ny = y + dx[i];
				if (check(nx, ny) && a[nx][ny] == '.') {
					set(x, y, ch[i ^ 2], qx, qy);
