		boolean put[][] = new boolean[n][m];
		for (char[] b : ans)
			Arrays.fill(b, '*');
		for (int i = 0; i < n; i++) {
			String line = in.next();
			for (int j = 0; j < m; j++) {
				if (line.charAt(j) == '*') {
					c[i][j] = 0;
					put[i][j] = true;
				}
			}
		}
		int dx[] = { -1, 1, 0, 0 };
		int dy[] = { 0, 0, -1, 1 };
		Queue<Integer> queue = new ArrayDeque<>();
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (c[i][j] > 0) {
					int x = 0;
					for (int k = 0; k < 4; k++) {
						int a = i + dx[k], b = j + dy[k];
						if (0 <= a && a < n && 0 <= b && b < m && c[a][b] > 0) {
							x++;
						}
					}
					c[i][j] = x;
					if (x == 1)
						queue.add(i * m + j);
				}
			}
		}
		while (!queue.isEmpty()) {
			int pos = queue.poll(), i = pos / m, j = pos % m;
			if (c[i][j] != 1)
				continue;
			for (int k = 0; k < 4; k++) {
				int a = i + dx[k], b = j + dy[k];
				if (0 <= a && a < n && 0 <= b && b < m && c[a][b] > 0) {
					if (k == 0) {
						ans[i][j] = 'v';
						ans[a][b] = '^';
						put[i][j] = put[a][b] = true;
					}
					if (k == 1) {
						ans[i][j] = '^';
						ans[a][b] = 'v';
						put[i][j] = put[a][b] = true;
					}
					if (k == 2) {
						ans[i][j] = '>';
						ans[a][b] = '<';
						put[i][j] = put[a][b] = true;
					}
					if (k == 3) {
						ans[i][j] = '<';
						ans[a][b] = '>';
						put[i][j] = put[a][b] = true;
					}
					for (int p = 0; p < 4; p++) {
						int e = a + dx[p], f = b + dy[p];
						if (0 <= e && e < n && 0 <= f && f < m && c[e][f] > 0) {
							c[e][f]--;
							if (c[e][f] == 1)
								queue.add(e * m + f);
						}
					}
					c[a][b] = 0;
					break;
				}
			}














		}
		boolean ok = true;
