class TaskD {
    private static final int[] DX = MiscUtils.DX4;
    private static final int[] DY = MiscUtils.DY4;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int rowCount = in.readInt();
        int columnCount = in.readInt();
        char[][] table = IOUtils.readTable(in, rowCount, columnCount);
        int[][] deg = new int[rowCount][columnCount];

        Queue<Pair<Integer, Integer>> queue = new ArrayDeque<Pair<Integer, Integer>>();
        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < columnCount; j++) {
                if (table[i][j] == '*') {
                    continue;
                }
                for (int k = 0; k < 4; k++) {
                    int nextX = i + DX[k];
                    int nextY = j + DY[k];
                    if (!MiscUtils.isValidCell(nextX, nextY, rowCount, columnCount) || table[nextX][nextY] != '.') {
                        continue;
                    }
                    deg[i][j]++;
                }
                if (deg[i][j] == 1) {
                    queue.add(new Pair<Integer, Integer>(i, j));
                }
            }
        }

        while (!queue.isEmpty()) {
            Pair<Integer, Integer> top = queue.poll();
            for (int i = 0; i < 4; i++) {
                int nextX = top.first + DX[i];
                int nextY = top.second + DY[i];
                if (!MiscUtils.isValidCell(nextX, nextY, rowCount, columnCount) || table[nextX][nextY] != '.') {
                    continue;
                }

                if (i == 0) {
                    table[top.first][top.second] = '^';
                    table[nextX][nextY] = 'v';
                }
                if (i == 1) {
                    table[top.first][top.second] = '>';
                    table[nextX][nextY] = '<';
                }
                if (i == 2) {
                    table[top.first][top.second] = 'v';
                    table[nextX][nextY] = '^';
                }
                if (i == 3) {
                    table[top.first][top.second] = '<';
                    table[nextX][nextY] = '>';
                }

                for (int j = 0; j < 4; j++) {
                    int nextNextX = nextX + DX[j];
                    int nextNextY = nextY + DY[j];
                    if (!MiscUtils.isValidCell(nextNextX, nextNextY, rowCount, columnCount) || table[nextNextX][nextNextY] != '.') {
                        continue;
                    }
                    deg[nextNextX][nextNextY]--;
                    if (deg[nextNextX][nextNextY] == 1) {
                        queue.add(new Pair<Integer, Integer>(nextNextX, nextNextY));
                    }
                }
            }
        }

        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < columnCount; j++) {
                if (table[i][j] == '.') {
                    out.printLine("Not unique");
                    return;
                }
            }
        }

        for (int i = 0; i < rowCount; i++) {
            out.printLine(String.valueOf(table[i]));
        }
    }
}

class MiscUtils {
    public static final int[] DX4 = {1, 0, -1, 0};
    public static final int[] DY4 = {0, -1, 0, 1};

    public static boolean isValidCell(int row, int column, int rowCount, int columnCount) {
        return row >= 0 && row < rowCount && column >= 0 && column < columnCount;
    }

}

class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public boolean isSpaceChar(int c) {
        if (filter != null)
            return filter.isSpaceChar(c);
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public char readCharacter() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        return (char) c;
    }

    public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }

}

