import java.util.*;
import java.io.*;

public class Main{

    BufferedReader in;
    StringTokenizer str = null;
    PrintWriter out;

    private String next() throws Exception{
    	while (str == null || !str.hasMoreElements())
    	    str = new StringTokenizer(in.readLine());
    	return str.nextToken();
    }

    private int nextInt() throws Exception{
	   return Integer.parseInt(next());
    }
    int n, m;
    char [][]a, r;
    int [][]deg;
    Queue<Integer> q;

    final static int BASE = 2001;
    final int []di = new int[]{0, -1, 0, 1};
    final int []dj = new int[]{-1, 0, 1, 0};

    public void run() throws Exception{
    	in = new BufferedReader(new InputStreamReader(System.in));
    	out = new PrintWriter(System.out);
        n = nextInt();
        m = nextInt();
        a = new char[n][m];
        for(int i = 0; i < n; ++i) a[i] = next().toCharArray();

        r = new char[n][m];
        for(int i = 0; i < n; ++i) {
            for(int j = 0; j < m; ++j) {
                r[i][j] = a[i][j];
            }
        }

        q = new LinkedList<Integer>();
        deg = new int[n][m];
        for(int i = 0; i < n; ++i) {
            for(int j = 0; j < m; ++j) {
                if (a[i][j] != '.') continue;
                deg[i][j] = 4;
                for(int k = 0; k < 4; ++k) {
                    int ni = i + di[k], nj = j + dj[k];
                    if (blocked(ni, nj)) --deg[i][j];
                }
                if (deg[i][j] == 1) {
                    q.add(i * BASE + j);
                }
            }
        }

        while(q.size() > 0) {
            int cur = q.poll();
            int x = cur / BASE, y = cur % BASE;
            if (deg[x][y] == 0) continue;

            int mask = (1 << 4) - 1;
            for(int k = 0; k < 4; ++k) {
                int ni = x + di[k], nj = y + dj[k];
                if (blocked(ni, nj)) {
                    mask &= ~(1 << k);
                }
            }
            int neigx = x, neigy = y;
            if (mask == 1) {
                r[x][y] = '>';
                r[x][y-1] = '<';
                --neigy;
            }else if (mask == 2) {
                r[x][y] = 'v';
                r[x-1][y] = '^';
                --neigx;
            }else if (mask == 4) {
                r[x][y] = '<';
                r[x][y+1] = '>';
                ++neigy;
            }else if (mask == 8){
                r[x][y] = '^';
                r[x+1][y] = 'v';
                ++neigx;
            }else {

                throw new RuntimeException();
            }

            deg[neigx][neigy]--;
            for(int k = 0; k < 4; ++k) {
                int ni = neigx + di[k], nj = neigy + dj[k];
                if (0 <= ni && ni < n && 0 <= nj && nj < m) {
                    if (r[ni][nj] != '.') continue;
                    --deg[ni][nj];
                    if (deg[ni][nj] == 1) {
                        q.add(ni * BASE + nj);
                    }
                }
            }





        }

        for(int i = 0; i < n; ++i) {
            for(int j = 0; j < m; ++j) {
                if (r[i][j] == '.') {
                    out.println("Not unique");
                    out.close();
                    return;
                }
            }
        }

        for(int i = 0; i < n; ++i) out.println(new String(r[i]));
        out.close();
    }

    private boolean blocked(int x, int y) {
        if (x < 0 || y < 0) return true;
        if (x >= n || y >= m) return true;
        if (r[x][y] != '.') return true;
        return false;
    }

    public static void main(String args[]) throws Exception{
	   new Main().run();
    }
}

