public class B {

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(in.readLine());
        PrintWriter out = new PrintWriter(System.out);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int[][] a = new int[n][m];
        for (int i = 0; i < n; i++) {
            String s = in.readLine();
            for (int j = 0; j < m; j++) {
                a[i][j] = s.charAt(j) == '.' ? 0 : -1;
            }
        }
        ArrayDeque<int[]> q = new ArrayDeque<int[]>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                check(a, i, j, q, n, m);
            }
        }
        while (!q.isEmpty()) {
            int[] x = q.pollLast();
            int i = x[0];
            int j = x[1];
            boolean flag = true;
            if (i > 0 && a[i - 1][j] == 0) {
                a[i - 1][j] = 2;
                a[i][j] = 1;
                flag = false;
            }
            if (j > 0 && a[i][j - 1] == 0) {
                a[i][j - 1] = 4;
                a[i][j] = 3;
                flag = false;
            }
            if (i < n - 1 && a[i + 1][j] == 0) {
                a[i + 1][j] = 1;
                a[i][j] = 2;
                flag = false;
            }
            if (j < m - 1 && a[i][j + 1] == 0) {
                a[i][j + 1] = 3;
                a[i][j] = 4;
                flag = false;
            }
            for (int r = -2; r <= 2; r++) {
                for (int p = -2; p <= 2; p++) {
                    check(a, i + p, j + r, q, n, m);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] == 0) {
                    out.println("Not unique");
                    in.close();
                    out.close();
                    return;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] == -1) {
                    out.print("*");
                }
                if (a[i][j] == 1) {
                    out.print("v");
                }
                if (a[i][j] == 2) {
                    out.print("^");
                }
                if (a[i][j] == 3) {
                    out.print(">");
                }
                if (a[i][j] == 4) {
                    out.print("<");
                }
            }
            out.println();
        }
        in.close();
        out.close();
    }

    public static void check(int[][] a, int i, int j, ArrayDeque<int[]> q,
            int n, int m) {
        if (i < 0 || j < 0 || i >= n || j >= m) {
            return;
        }
        if (a[i][j] == 0) {
            int cnt = 0;
            if (i > 0 && a[i - 1][j] == 0) {
                cnt++;
            }
            if (j > 0 && a[i][j - 1] == 0) {
                cnt++;
            }
            if (i < n - 1 && a[i + 1][j] == 0) {
                cnt++;
            }
            if (j < m - 1 && a[i][j + 1] == 0) {
                cnt++;
            }
            if (cnt == 1) {
                q.add(new int[] { i, j });
            }
        }
    }
}

