    private static void expand(char[][] board, int N, int M, int r0, int c0) {
    	int d0 = getDirection(board, N, M, r0, c0);
    	if (d0 < 0) {
    		return;
    	}
    	LinkedList<Integer> rQ = new LinkedList<Integer>();
    	LinkedList<Integer> cQ = new LinkedList<Integer>();
    	LinkedList<Integer> dQ = new LinkedList<Integer>();
    	rQ.addLast(r0);
    	cQ.addLast(c0);
    	dQ.addLast(d0);
    	updateBoard(board, N, M, r0, c0, d0);
    	while (!rQ.isEmpty()) {
    		int r = rQ.removeFirst();
    		int c = cQ.removeFirst();
    		int d = dQ.removeFirst();
    		int rp = r + DR[d];
    		int cp = c + DC[d];
    		for (int i = 0; i < 4; i++) {
    			int rn = rp + DR[i];
    			int cn = cp + DC[i];
    			int dn = getDirection(board, N, M, rn, cn);
    			if (dn >= 0) {
    				updateBoard(board, N, M, rn, cn, dn);
    				rQ.addLast(rn);
    				cQ.addLast(cn);
    				dQ.addLast(dn);
    			}
    		}
    	}
    }

    private static void updateBoard(char[][] board, int N, int M, int r, int c, int d) {
    	if (d == 0) {
    		board[r - 1][c] = '^';
    		board[r][c] = 'v';
    	} else if (d == 1) {
    		board[r][c] = '<';
    		board[r][c + 1] = '>';
    	} else if (d == 2) {
    		board[r][c] = '^';
    		board[r + 1][c] = 'v';
    	} else if (d == 3) {
    		board[r][c - 1] = '<';
    		board[r][c] = '>';
    	}
    }

    private static int getDirection(char[][] board, int N, int M, int r0, int c0) {
    	if (!valid(N, M, r0, c0) || board[r0][c0] != '.') {
    		return -1;
    	}

    	int dir = -1;
    	boolean found = false;
    	for (int i = 0; i < 4; i++) {
    		int r = r0 + DR[i];
    		int c = c0 + DC[i];
    		if (valid(N, M, r, c) && board[r][c] == '.') {
    			if (!found) {
    				dir = i;
    				found = true;
    			} else {
    				return -1;
    			}
    		}
    	}
    	return dir;
    }

    private static boolean valid(int N, int M, int r, int c) {
    	return (r >= 0 && r < N && c >= 0 && c < M);
    }

	public static class FasterScanner {
		private byte[] buf = new byte[1024];
		private int curChar;
		private int numChars;

		public int read() {
			if (numChars == -1)
				throw new InputMismatchException();
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = System.in.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (numChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		public String nextLine() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isEndOfLine(c));
			return res.toString();
		}

		public String nextString() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isSpaceChar(c));
			return res.toString();
		}

		public long nextLong() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = read();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			} while (!isSpaceChar(c));
			return res * sgn;
		}

		public int nextInt() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = read();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			} while (!isSpaceChar(c));
			return res * sgn;
		}

	    public int[] nextIntArray(int n) {
	        int[] arr = new int[n];
	        for (int i = 0; i < n; i++) {
	            arr[i] = nextInt();
	        }
	        return arr;
	    }

		public long[] nextLongArray(int n) {
		    long[] arr = new long[n];
		    for (int i = 0; i < n; i++) {
		        arr[i] = nextLong();
		    }
		    return arr;
		}

	    private boolean isSpaceChar(int c) {
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		private boolean isEndOfLine(int c) {
			return c == '\n' || c == '\r' || c == -1;
		}
	}
}

import java.util.*;
public class B {

    static Scanner reader = new Scanner(System.in);
    static int n,m;
    static StringBuilder a[];
    static class cell{
        public int row,col;
        cell(int row,int col){
            this.row=row; this.col=col;
        }
    };
    static int dr[]={0,0,-1,1},
                    dc[]={-1,1,0,0};
    static ArrayList<cell> q=new  ArrayList<cell>();
    static boolean dd[][];
    static void doProc(int i,int j) throws Exception{
        if (calcdeg(i, j)!=1) return;
        int x=i,y=j,k;

        for (k=0;k<4;k++){
            x=i+dr[k]; y=j+dc[k];
            if (x>=0&&x<n&&y>=0&&y<m){
                if (a[x].charAt(y)=='.')
                    break;
            }
        }
        if (k<4){
            if (k<=1){
                if (k==0){
                    a[i].setCharAt(j-1,'<');
                    a[i].setCharAt(j,'>');
                }else{
                    a[i].setCharAt(j,'<');
                    a[i].setCharAt(j+1,'>');
                }
            }else{
                if (k==2){
                    a[i-1].setCharAt(j, '^');
                    a[i].setCharAt(j, 'v');
                }else{
                    a[i].setCharAt(j, '^');
                    a[i+1].setCharAt(j, 'v');
                }
            }
            for (k=0;k<4;k++){
                if (calcdeg(x+dr[k],y+dc[k])==1){
                    q.add(new cell(x+dr[k], y+dc[k]));
                }
            }
        }
    }
    static int calcdeg(int i,int j)throws Exception{
        if (i<0||i>=n||j<0||j>=m) return 0;
        if (a[i].charAt(j)!='.') return 0;
        int k,x =i,y=j,res;
        res=0;
        for (k=0;k<4;k++){
            x=i+dr[k]; y=j+dc[k];
            if (x>=0&&x<n&&y>=0&&y<m){
                if (a[x].charAt(y)=='.')
                    res++;
            }
        }
        if (res==1){
            if (dd[i][j]==false){
                q.add(new cell(i, j));
                dd[i][j]=true;
            }
        }
        return res;
    }

    public static void main(String[] args) throws Exception{
        n=reader.nextInt();
        m=reader.nextInt();
        reader.nextLine();
        a=new StringBuilder[n];
        int i,j,k,x,y;
        dd=new boolean[n+2][m+2];
        for (i=0;i<=n;i++)Arrays.fill(dd[i], false); 
        for (i=0;i<n;i++)
            a[i]=new StringBuilder(reader.nextLine());
        for (i=0;i<n;i++) for (j=0;j<m;j++){
            if (a[i].charAt(j)=='.') calcdeg(i, j);
        }
        for (i=0;i<q.size();i++){
            doProc(q.get(i).row, q.get(i).col);
        }
        for (i=0;i<n;i++) for (j=0;j<m;j++) 
            if (a[i].charAt(j)=='.'){
                System.out.print("Not unique");
                return;
            }
        for (i=0;i<n;i++)
            System.out.println(a[i].toString());
    }

}

import java.io.*;
import java.util.*;

public class Solution {
    StringTokenizer st;
    BufferedReader in;
    PrintWriter out;

    void solve() throws IOException {



        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(new OutputStreamWriter(System.out));
        Locale.setDefault(Locale.ENGLISH);

        n = nextInt();
        m = nextInt();

        a = new char[n][m];
        for (int i = 0; i < n; i++) {
            String s = in.readLine();
            for (int j = 0; j < m; j++) {
                a[i][j] = s.charAt(j);
            }
        }

        Queue<int[]> q = new LinkedList<>();
        boolean[][] used = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int[] pos = getPos(i, j);
                if (pos[0] != -1) {
                    used[pos[0]][pos[1]] = true;
                    q.add(pos);
                }
            }
        }

        while (!q.isEmpty()) {
            int x = q.peek()[0];
            int y = q.peek()[1];
            q.poll();

            for (int k = 0; k < 4; k++) {
                int nx = x + dx[k];
                int ny = y + dy[k];
                int[] pos = getPos(nx, ny);
                if (pos[0] != -1 && !used[pos[0]][pos[1]]) {
                    used[pos[0]][pos[1]] = true;
                    q.add(pos);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] == '.') {
                    out.print("Not unique");
                    out.close();
                    return;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(a[i][j]);
            }
            out.println();
        }

        in.close();
        out.close();
    }

    char[][] a;
    int n, m;

    int[] dx = {-1, 0, 1, 0};
    int[] dy = {0, -1, 0, 1};

    int[] getPos(int x, int y) {
        if (!inside(x, y) || a[x][y] != '.') {
            return new int[]{-1, -1};
        }

        int[] pos = new int[]{-1, -1};

        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k];
            int ny = y + dy[k];

            if (inside(nx, ny) && a[nx][ny] == '.') {
                if (pos[0] == -1) {
                    pos = new int[]{nx, ny};
                } else {
                    return new int[]{-1, -1};
                }
            }
        }

        if (pos[0] == -1) {
            return new int[]{-1, -1};
        }

        if (pos[0] < x) {
            a[pos[0]][y] = '^';
            a[x][y] = 'v';
        }

        if (pos[0] > x) {
            a[x][y] = '^';
            a[pos[0]][y] = 'v';
        }

        if (pos[1] < y) {
            a[x][pos[1]] = '<';
            a[x][y] = '>';
        }

        if (pos[1] > y) {
            a[x][y] = '<';
            a[x][pos[1]] = '>';
        }

        return pos;
    }

    boolean inside(int x, int y) {
        return 0 <= x && x < n && 0 <= y && y < m;
    }

    public static void main(String[] args) throws IOException {
        new Solution().solve();
    }

    String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(in.readLine());
        }
        return st.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }
}

