	static int[] ydir = new int[]{0, 0, -1, 1};

	public static void main(String[] args) throws Exception {
		str = in.readLine();
		int n = Integer.parseInt(str.substring(0, str.indexOf(" ")));
		int m = Integer.parseInt(str.substring(str.indexOf(" ") + 1));
		char[][] mat = new char[n][m];
		for(int i = 0; i < n; i++) {
			mat[i] = in.readLine().toCharArray();
		}
		ArrayDeque<Dom> ad = new ArrayDeque<Dom>();
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(mat[i][j] == '.') {
					int count = 0;
					Point p = null;
					for(int k = 0; k < 4; k++) {
						int tx = i + xdir[k];
						int ty = j + ydir[k];
						if(isValid(tx, ty, n, m) && mat[tx][ty] == '.') {
							count++;
							p = new Point(tx, ty);
						}
					}
					if(count == 1) {
						ad.addLast(new Dom(new Point(i, j), p));
					}
				}
			}
		}
		while(!ad.isEmpty()) {
			Dom d = ad.pollFirst();
			if(mat[d.p1.x][d.p1.y] == '.' && mat[d.p2.x][d.p2.y] != '.') {
				System.out.println("Not unique");
				return;
			}
			if(mat[d.p1.x][d.p1.y] == '.') {
				if(d.p1.x == d.p2.x - 1) {
					mat[d.p1.x][d.p1.y] = '^';
					mat[d.p2.x][d.p2.y] = 'v';
				}
				if(d.p1.x == d.p2.x + 1) {
					mat[d.p1.x][d.p1.y] = 'v';
					mat[d.p2.x][d.p2.y] = '^';
				}
				if(d.p1.y == d.p2.y - 1) {
					mat[d.p1.x][d.p1.y] = '<';
					mat[d.p2.x][d.p2.y] = '>';
				}
				if(d.p1.y == d.p2.y + 1) {
					mat[d.p1.x][d.p1.y] = '>';
					mat[d.p2.x][d.p2.y] = '<';
				}
				for(int k = 0; k < 4; k++) {
					int tx = d.p2.x + xdir[k];
					int ty = d.p2.y + ydir[k];
					if(isValid(tx, ty, n, m) && mat[tx][ty] == '.') {
						int count = 0;
						Point p = null;
						for(int l = 0; l < 4; l++) {
							int tx2 = tx + xdir[l];
							int ty2 = ty + ydir[l];
							if(isValid(tx2, ty2, n, m) && mat[tx2][ty2] == '.') {
								count++;
								p = new Point(tx2, ty2);
							}
						}
						if(count == 1) {
							ad.addLast(new Dom(new Point(tx, ty), p));
						}
					}
				}
			}
		}
		StringBuilder sb = new StringBuilder("");
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(mat[i][j] == '.') {
					System.out.println("Not unique");
					return;
				}
				sb.append(mat[i][j]);
			}
			sb.append("\n");
		}
		System.out.print(sb.toString());
	}

	public static boolean isValid(int x, int y, int dimx, int dimy) {
		return -1 < x && x < dimx && -1 < y && y < dimy;
	}

	static class Dom {
		Point p1;
		Point p2;

		public Dom(Point temp1, Point temp2) {
			p1 = temp1;
			p2 = temp2;
		}
	}

	static class Point {
		int x;
		int y;

		public Point(int tempx, int tempy) {
			x = tempx;
			y = tempy;
		}
	}

	static class InputReader {
		BufferedReader br;
		public InputReader() {
			try {
				br = new BufferedReader(new FileReader("cf292D.in"));
			} catch(Exception e) {
				br = new BufferedReader(new InputStreamReader(System.in));
			}
		}

		public String readLine() throws Exception {
			return br.readLine();
		}
	}
}

import java.io.*;
import java.util.*;
public class F{
    public static void main(String[] args)throws Throwable {
        MyScanner sc=new MyScanner();
        PrintWriter pw=new PrintWriter(System.out);


        n=sc.nextInt();
        m=sc.nextInt();
        V=n*m;
        a=new char [n][m];
        for(int i=0;i<n;i++)
            a[i]=sc.next().toCharArray();
        deg=new int [V];
        int [] q=new int [V+10];
        int front=0,back=0;
        int cntDot=0;
        for(int i=0;i<n;i++)
        	for(int j=0;j<m;j++) {
        		if(a[i][j]=='.') {
        			cntDot++;
        			for(int k=0;k<4;k+=2) {
        				int nr=i+dx[k];
        				int nc=j+dy[k];
        				if(valid(nr, nc) && a[nr][nc]=='.') {
        					deg[i*m+j]++;
        					deg[nr*m+nc]++;
        				}
        			}
        			if(deg[i*m+j]==1)
        				q[back++]=i*m+j;
        		}
        	}
        boolean ok=true;
        while(front!=back) {
        	int p=q[front++];
        	int r=p/m;
        	int c=p%m;
        	if(a[r][c]!='.')
        		continue;
        	cntDot-=2;
        	boolean done=false;
        	for(int k=0;k<4;k++) {
				int nr=r+dx[k];
				int nc=c+dy[k];
				if(valid(nr, nc) && a[nr][nc]=='.') {
					done=true;
					a[r][c]=s1[k];
					a[nr][nc]=s2[k];
					for(int k2=0;k2<4;k2++) {
						int nnr=nr+dx[k2];
						int nnc=nc+dy[k2];
						if(valid(nnr, nnc) && --deg[nnr*m+nnc]==1)
							q[back++]=nnr*m+nnc;
					}
					break;
				}
        	}
        	ok &=done;

        }
        if(!ok || cntDot>0)
        	pw.println("Not unique");
        else
        	for(int i=0;i<n;i++)
        		pw.println(new String(a[i]));

        pw.flush();
        pw.close();
    }

    static int [] deg;
    static int n,m,V;
    static char [][] a;
    static int [] dx={1,-1,0,0};
    static int [] dy={0,0,1,-1};
    static char [] s1={'^','v','<','>'};
    static char [] s2={'v','^','>','<'};

    static boolean valid(int r,int c){
        return r>=0 && c>=0 && r<n && c<m;
    }


    static class MyScanner {
        BufferedReader br;
        StringTokenizer st;
        public MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {while (st == null || !st.hasMoreElements()) {
            try {st = new StringTokenizer(br.readLine());}
            catch (IOException e) {e.printStackTrace();}}
            return st.nextToken();}
        int nextInt() {return Integer.parseInt(next());}
        long nextLong() {return Long.parseLong(next());}
        double nextDouble() {return Double.parseDouble(next());}
        String nextLine(){String str = "";
            try {str = br.readLine();}
            catch (IOException e) {e.printStackTrace();}
            return str;}
    }
}

import java.awt.Point;
