class TaskB {
    int dx[]={1,-1,0,0};
    int dy[]={0,0,1,-1};
    char val[]={'^','v','<','>'};

    int n,m;
    char arr[][];
    int neigh[][];
    Queue<Integer> queue=new ArrayDeque<Integer>();
    void update(int i, int j)
    {
        for(int k=0;k<4;k++)
        {
            int ni=i+dx[k];
            int nj=j+dy[k];
            if(isOk(ni,nj))
            {
                neigh[ni][nj]--;
                if(neigh[ni][nj]==1)
                {
                    queue.add(ni);
                    queue.add(nj);
                }
            }
        }
    }
    public void solve(int testNumber, QuickScanner in, PrintWriter out) {

        n=in.nextInt();
        m=in.nextInt();
        arr=new char[n][];
        neigh=new int[n][m];
        for(int i=0;i<n;i++)
            arr[i]=in.next().toCharArray();

        for(int i=0;i<n;i++)
            for(int j=0;j<m;j++)
            {
                if(arr[i][j]!='*')
                {
                    for(int k = 0; k < 4; k++)
                    {
                        int ni = i + dx[k];
                        int nj = j + dy[k];
                        if(isOk(ni,nj) && arr[ni][nj] == '.')
                        {
                            neigh[i][j]++;
                        }
                    }
                    if(neigh[i][j]==1)
                    {
                        queue.add(i);
                        queue.add(j);
                    }
                }
            }
        while(!queue.isEmpty())
        {
            int x=queue.poll();
            int y=queue.poll();
            if(arr[x][y]=='.')
            {
                for(int j = 0; j < 4; j++)
                {
                    int ni = x + dx[j];
                    int nj = y + dy[j];
                    if(isOk(ni, nj) && arr[ni][nj] == '.')
                    {
                        arr[x][y] = val[j];
                        arr[ni][nj] = val[j ^ 1];
                        update(x, y);
                        update(ni, nj);
                        break;
                    }
                }
            }
        }
        boolean ok=true;
        for(int i=0;i<n;i++)
            for(int j=0;j<m;j++)
                if(arr[i][j]=='.')
                    ok=false;
        if(!ok)
            out.println("Not unique");
        else
        {
            for(int i=0;i<n;i++)
                out.println(new String(arr[i]));
        }
    }

    private boolean isOk(int ni, int nj)
    {
        return 0 <= ni && ni < n && 0 <= nj && nj < m;
    }
}

class QuickScanner {
    BufferedReader in;
    StringTokenizer token;
    String delim;
    public QuickScanner(InputStream inputStream)
    {
        this.in=new BufferedReader(new InputStreamReader(inputStream));
        this.delim=" \n\t";
        this.token=new StringTokenizer("",delim);
    }

    public boolean hasNext()
    {
        while(!token.hasMoreTokens())
        {
            try {
                String s=in.readLine();
                if(s==null) return false;
                token=new StringTokenizer(s,delim);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
        }
        return true;
    }

    public String next()
    {
        hasNext();
        return token.nextToken();
    }

    public int nextInt()
    {
        return Integer.parseInt(next());
    }

}

