        for (int i = 0; i < n; ++i) {
            s[i] = next().toCharArray();
        }
        Queue<Cell> q = new LinkedList<Cell>();
        for (int x = 0; x < n; ++x) {
            for (int y = 0; y < m; ++y) {
                if (s[x][y] == '.') {
                    int cnt = 0;
                    for (int k = 0; k < 4; ++k) {
                        int x2 = x + moveX[k];
                        int y2 = y + moveY[k];
                        if (x2 >= 0 && x2 < n && y2 >= 0 && y2 < m && s[x2][y2] == '.') {
                            ++cnt;
                        }
                    }
                    if (cnt == 1) {
                        q.add(new Cell(x, y));
                    }
                }
            }
        }
        while (!q.isEmpty()) {
            int x = q.peek().x;
            int y = q.poll().y;
            if (s[x][y] != '.') {
                continue;
            }
            int cnt = 0;
            for (int k = 0; k < 4; ++k) {
                int x2 = x + moveX[k];
                int y2 = y + moveY[k];
                if (x2 >= 0 && x2 < n && y2 >= 0 && y2 < m && s[x2][y2] == '.') {
