import java.util.Stack;

public class DrazilAndTiles515D {

    static int[][] d = {{0, -1}, {-1, 0}, {0, 1}, {1, 0}};
    static char[][] dir = {{'>', '<'}, {'v', '^'}, {'<', '>'}, {'^', 'v'}};

    static void go() {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] map = new char[n + 2][m + 2];
        for (int i = 0; i < n; i++) {
            char[] temp = in.nextCharArray(m);
            System.arraycopy(temp, 0, map[i + 1], 1, m);
        }

        int count = 0;
        int[][] ones = new int[n*m][2];
        int start = 0, end = 0;

        int[][] degree = new int[n + 2][m + 2];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (map[i][j] != '.') continue;
                if (map[i][j + 1] == '.') {
                    degree[i][j]++;
                    degree[i][j + 1]++;
                }
                if (map[i + 1][j] == '.') {
                    degree[i][j]++;
                    degree[i + 1][j]++;
                }
                count++;
                if (degree[i][j] == 1) {
                    ones[end][0] = i;
                    ones[end][1] = j;
                    end++;
                }
            }
        }

        while (start < end) {
            int r = ones[start][0];
            int c = ones[start][1];
            start++;
            if (map[r][c] != '.') {
                continue;
            }
            if (degree[r][c] != 1) {
                break;
            }

            for (int i = 0; i < 4; i++) {
                if (map[r + d[i][0]][c + d[i][1]] == '.') {
                    int a = r + d[i][0], b = c + d[i][1];
                    map[r][c] = dir[i][0];
                    map[a][b] = dir[i][1];
                    for (int[] diff : d) {
                        if (--degree[a + diff[0]][b + diff[1]] == 1) {
                            ones[end][0] = a + diff[0];
                            ones[end][1] = b + diff[1];
                            end++;
                        }
                    }
                }
            }
            count -= 2;
        }

        if (count != 0) {
            out.println("Not unique");
        } else {
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++)
                    out.print(map[i][j]);
                out.println();
            }
        }
    }

    static InputReader in;
    static PrintWriter out;

    public static void main(String[] args) {
        in = new InputReader(System.in);
        out = new PrintWriter(System.out);

        go();

        out.close();
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int[] nextIntArray(int len) {
            int[] ret = new int[len];
            for (int i = 0; i < len; i++)
                ret[i] = nextInt();
            return ret;
        }

        public long[] nextLongArray(int len) {
            long[] ret = new long[len];
            for (int i = 0; i < len; i++)
                ret[i] = nextLong();
            return ret;
        }


        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder sb = new StringBuilder(1024);
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        public char[] nextCharArray(int n) {
            char[] ca = new char[n];
            for (int i = 0; i < n; i++) {
                int c = read();
                while (isSpaceChar(c))
                    c = read();
                ca[i] = (char) c;
            }
            return ca;
        }

        public static boolean isSpaceChar(int c) {
            switch (c) {
                case -1:
                case ' ':
                case '\n':
                case '\r':
                case '\t':
                    return true;
                default:
                    return false;
            }
        }
    }
}

