class SolverD {

    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char a[][] = new char[n+2][m+2];


        for (int i=0; i<=m+1; i++) {
            a[0][i] = '*';
            a[n+1][i] = '*';
        }
        for (int i=0; i<=n+1; i++) {
            a[i][0] = '*';
            a[i][m+1] = '*';
        }

        for (int i=1; i<=n; i++) {
            String s = in.next();
            for (int j=1; j<=m; j++) {
                a[i][j] = s.charAt(j-1);
            }
        }

        Queue<Tuple> q = new LinkedList<>();
        for (int i=1; i<=n; i++) {
            for (int j=1; j<=m; j++) {
                if (a[i][j] == '.' && deg1(a, i, j)) {
                    q.add(new Tuple(i, j));
                }
            }
        }

        while (!q.isEmpty()) {
            Tuple t = q.poll();

            if (a[t.a][t.b] != '.') {
                continue;
            }

            Tuple next = next(a, t);

            if (next == null) {
                continue;
            }

            if (deg1(a, next.a-1, next.b)) {
                q.add(new Tuple(next.a-1, next.b));
            }
            if (deg1(a, next.a+1, next.b)) {
                q.add(new Tuple(next.a+1, next.b));
            }
            if (deg1(a, next.a, next.b-1)) {
                q.add(new Tuple(next.a, next.b-1));
            }
            if (deg1(a, next.a, next.b+1)) {
                q.add(new Tuple(next.a, next.b+1));
            }
        }

        boolean good = true;
        for (int i=1; i<=n; i++) {
            for (int j=1; j<=m; j++) {
                if (a[i][j] == '.') {
                    good = false;
                    break;
                }
            }
            if (!good) {
                break;
            }
        }

        if (!good) {
            out.println("Not unique");
        } else {
            for (int i=1; i<=n; i++) {
                for (int j=1; j<=m; j++) {
                    out.print(a[i][j]);
                }
                out.println();
            }
        }

    }

    private Tuple next(final char[][] a, final Tuple t) {
        if (a[t.a-1][t.b] == '.') {
            a[t.a-1][t.b] = '^';
            a[t.a][t.b] = 'v';
            return new Tuple(t.a-1, t.b);
        }
        if (a[t.a+1][t.b] == '.') {
            a[t.a][t.b] = '^';
            a[t.a+1][t.b] = 'v';
            return new Tuple(t.a+1, t.b);
        }
        if (a[t.a][t.b-1] == '.') {
            a[t.a][t.b-1] = '<';
            a[t.a][t.b] = '>';
            return new Tuple(t.a, t.b-1);
        }
        if (a[t.a][t.b+1] == '.') {
            a[t.a][t.b] = '<';
            a[t.a][t.b+1] = '>';
            return new Tuple(t.a, t.b+1);
        }
        return null;
    }

    private boolean deg1(final char[][] a, final int i, final int j) {
        if (a[i][j] != '.') {
            return false;
        }

        int d = 0;
        d += a[i][j-1] == '.' ? 1 : 0;
        d += a[i][j+1] == '.' ? 1 : 0;
        d += a[i-1][j] == '.' ? 1 : 0;
        d += a[i+1][j] == '.' ? 1 : 0;
        return d == 1;
    }

    class Tuple {
        int a, b;

        Tuple(int a, int b) {
            this.a = a;
            this.b = b;
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;



public class D { 

	static class OneOptionField { 
		int r, c;
		int dir; 




		public OneOptionField(int r, int c, int dir) { 
			this.r = r;
			this.c = c;
			this.dir = dir;
		}
	}

	static int [] dr = {1,-1,0,0};
	static int [] dc = {0,0,1,-1};
	static int R,C;
	static char[][] M;
	static String bad = "Not unique";

	static boolean isValid(int r, int c) { 
		return 0 <= r && r <R && 0 <= c && c <C && M[r][c] == '.';
	}

	static int computeDir(int r, int c) { 
		for(int k=0; k<dr.length; k++) { 
			int nextR = r + dr[k];
			int nextC = c + dc[k];

			if(isValid(nextR, nextC)) return k;
		}
		return -1;
	}


	public static void main(String [] args) throws IOException { 

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer tokenizer = new StringTokenizer(br.readLine());

		R = Integer.parseInt(tokenizer.nextToken());
		C = Integer.parseInt(tokenizer.nextToken());

		M = new char[R][C];
		int [][] hm = new int[R][C];
		for(int i=0; i<R; i++) { 
			String s = br.readLine();
			M[i] = s.toCharArray();
		}

		Queue<OneOptionField> q = new LinkedList<OneOptionField>();

		for(int i=0; i<R; i++) { 
			for(int j=0; j<C; j++) {
				if(M[i][j] != '.') {
					hm[i][j] = -1;
					continue; 
				}

				int howMany = 0;
				int dir = -1;
				for(int k=0; k<dr.length; k++) { 
					int nextR = i + dr[k];
					int nextC = j + dc[k];

					if(isValid(nextR, nextC)) { 
						howMany++;
						dir = k;
					}
				}

				hm[i][j] = howMany;
				if(howMany == 0) { 
					System.out.println(bad);
					return;
				}

				if(howMany > 1) continue;

				OneOptionField oof = new OneOptionField(i,j,dir);
				q.add(oof);

			}
		}

		while(!q.isEmpty()) { 

			OneOptionField top = q.poll();
			if(!isValid(top.r, top.c)) continue;

			int r_n = top.r + dr[top.dir];
			int c_n = top.c + dc[top.dir];
			hm[top.r][top.c] = -1;
			hm[r_n][c_n] = -1;

			if(top.dir == 0) { 
				M[top.r][top.c] = '^';
				M[r_n][c_n] = 'v';
			} else if(top.dir == 1) { 
				M[top.r][top.c] = 'v';
				M[r_n][c_n] = '^';
			} else if(top.dir == 2) { 
				M[top.r][top.c] = '<';
				M[r_n][c_n] = '>';

			} else if(top.dir == 3) { 
				M[top.r][top.c] = '>';
				M[r_n][c_n] = '<';
			}



			for(int i=0; i<dr.length; i++) { 
				int r_u = r_n + dr[i];
				int c_u = c_n + dc[i];

				if(isValid(r_u, c_u)) { 


					if(hm[r_u][c_u] == 1) { 
						System.out.println(bad);
						return;
					}

					hm[r_u][c_u]--;
					if(hm[r_u][c_u] == 1) { 
						OneOptionField newField = new OneOptionField(r_u, c_u, computeDir(r_u, c_u));
						q.add(newField);
					}
				}
			}

		}

		for(int i=0; i<R; i++) { 
			for(int j=0; j<C; j++) { 
				if(isValid(i,j)) { 
					System.out.println(bad);
					return;
				}
			}
