public class D {
    static int n, m;
    static char[][] maze;
    static int[][] deg;
    static char[][] tile = { {'v','^'}, {'^','v'}, {'>', '<'}, {'<','>'}};
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};
    public static void main(String[] args){
        Scanner cin = new Scanner(System.in);
        n = cin.nextInt();  m = cin.nextInt();
        deg = new int[n][m];
        maze = new char[n][];
        for(int[] row: deg) Arrays.fill(row, 0);
        for(int i = 0; i < n; ++i){
            String row = cin.next();
            maze[i] = row.toCharArray();
        }
        Queue<Integer> que = new LinkedList<Integer>();
        for(int i = 0; i < n; ++i){
            for(int j = 0; j < m; ++j)if( maze[i][j] == '.' ){
                for(int k = 0; k < 4; ++k){
                    int xx = i + dx[k];  int yy = j + dy[k];
                    if( !emptyCell(xx, yy) ){
                        deg[i][j]++;
                    }
                }
                if( deg[i][j] == 3 ) {
                    que.add(i);
                    que.add(j);
                }
            }
        }
        while( !que.isEmpty() ){
            int x = que.poll(); int y = que.poll();
            for(int k  = 0; k < 4; ++k){
                int xx = x + dx[k]; int yy = y  + dy[k];
                if( emptyCell(xx, yy) ) {
                    maze[x][y] = tile[k][0]; maze[xx][yy] = tile[k][1];
                    for(int p = 0; p < 4; ++p ){
                        int nx = xx + dx[p];
                        int ny = yy + dy[p];
                        if (emptyCell(nx, ny)) {
                            deg[nx][ny]++;
                            if (deg[nx][ny] == 3) {
                                que.add(nx);
                                que.add(ny);
                            }
                        }
                    }
                }
            }
        }

        for(int i = 0; i < n; ++i){
            for(int j = 0; j < m; ++j)if( maze[i][j] == '.' ){
                System.out.println("Not unique"); return;
            }
        }
        for(char[] row: maze ){
            System.out.println(row);
        }


    }

    private static boolean emptyCell(int x, int y) {
        if( x >=0 && x < n && y >= 0 && y < m && maze[x][y] == '.' ) return true;
        return false;
    }
}

import java.io.*;
import java.util.*;

public class CF_515D {

    static char[][] field;
    static boolean[][] visited;
    static int[][] power;
    static int[][] dir = {{0, 1}, {0, -1}, {-1, 0}, {1, 0},};
    static ArrayDeque<int[]> q = new ArrayDeque<int[]>();

    static void updatePower(int i, int j) {
        if (i < 0 || j < 0 || i>= field.length || j>= field[0].length) return;   
        power[i][j] = 0;
        if (field[i][j]!='.') {
            return;
        }
        for (int[] d : dir) {
            int[] cand = {i + d[0], j + d[1]};
            if (cand[0] < 0 || cand[1] < 0 || cand[0] >= field.length || cand[1] >= field[0].length) continue;            
            if (field[cand[0]][cand[1]] !='.') continue;            
            power[i][j]++;
        }
        if (power[i][j] == 1 && !visited[i][j]) {
            q.add(new int[]{i, j});
            visited[i][j] = true;
        }
    }

    static void fill(int i, int j) {
        if (field[i][j]!='.' || power[i][j] != 1) {
            return;
        }
        for (int k=0;k<4;k++) {
            int[] cand = {i + dir[k][0], j + dir[k][1]};
            if (cand[0] < 0 || cand[1] < 0 || cand[0] >= field.length || cand[1] >= field[0].length) continue;            
            if (field[cand[0]][cand[1]]!='.') continue;

            switch (k){
                case 0: 
                    field[i][j]='<';
                    field[cand[0]][cand[1]]='>';
                    break;
                case 1: 
                    field[i][j]='>';
                    field[cand[0]][cand[1]]='<';
                    break;
                case 2: 
                    field[i][j]='v';
                    field[cand[0]][cand[1]]='^';
                    break;
                case 3: 
                    field[i][j]='^';
                    field[cand[0]][cand[1]]='v';
                    break;
            }            

            power[i][j]=power[cand[0]][cand[1]] = 0;
            for (int[] d2 : dir) {
                updatePower(cand[0] + d2[0], cand[1] + d2[1]);
            }
            break;
        }
    }

    static boolean uniqueSol(){
        for (int i=0;i<field.length;i++)
            for(int j=0;j<field[0].length;j++)
                if (field[i][j]=='.') return false;
        return true;
    }


    public static void main(String[] args) throws IOException {

        InputStream in = System.in;
        PrintStream out = System.out;




        Scanner sc = new Scanner(in);

        int n = sc.nextInt(), m = sc.nextInt();
        field = new char[n][m];
        visited = new boolean[n][m];
        power = new int[n][m];

        for (int i = 0; i < n; i++) {
            String s = sc.next();
            for (int j = 0; j < m; j++) 
                field[i][j] = s.charAt(j) ;            
        }

        for (int i = 0; i < n; i++) 
            for (int j = 0; j < m; j++) 
                updatePower(i,j);

        while (!q.isEmpty()){
            int[] v = q.poll();
            fill(v[0],v[1]);
        }
        if (uniqueSol()) {
            for (int i=0;i<n;i++)
                out.println(new String(field[i]));
        }
        else out.println("Not unique");



    }
}

