public class SolveContest {
    private BufferedReader in;
    private PrintWriter out;

    public SolveContest() {
        try {
            in = new BufferedReader(new FileReader("input.txt"));
            out = new PrintWriter(new FileWriter("output.txt"),true);
            solve();
        } catch (Exception e) {
            e.printStackTrace();
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
            solve();
        } finally {
            try {
                in.close();
            } catch (IOException e) {

            }
            out.close();
        }
    }
    StringTokenizer st;
    String nextToken() {
        while (st == null || !st.hasMoreTokens())
            try {
                st = new StringTokenizer(in.readLine());
            } catch (IOException e) {

            }
        return st.nextToken();
    }

    int nextInt() {
        return Integer.valueOf(nextToken());
    }
    long nextLong() {
        return Long.valueOf(nextToken());
    }
    char[][] a;
    int[] dx = {1,-1,0,0};
    int[] dy = {0,0,1,-1};
    char[] bg = {'^','v','<','>'};
    char[] end = {'v','^','>','<'};
    int n;
    int m;

    boolean isCorrect(int newX, int newY) {
        return (0 <= newX && newX < n) && (0 <= newY && newY < m);
    }

    int getPower(int i, int j) {
        if (a[i][j] != '.') return 0;
        int power = 0;
        for (int k = 0; k < 4; k++) {
            int newX = i + dx[k];
            int newY = j + dy[k];
            if (isCorrect(newX, newY) && a[newX][newY] == '.') {
                power++;
            }
        }
        return power;
    }

    public void solve() {
        n = nextInt();
        m = nextInt();
        a = new char[n][m];
        for (int i = 0; i < n; i++) {
            String s = nextToken();
            for (int j = 0; j < m; j++) {
                a[i][j] = s.charAt(j);
            }
        }
        Queue<Pair> q = new LinkedList<Pair>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (getPower(i,j) == 1)
                    q.add(new Pair(i,j));
            }
        }
        while (!q.isEmpty()) {
            Pair p = q.poll();
            if (a[p.i][p.j] != '.') continue;
            int pow = 0;
            int dir = 0;
            for (int i = 0; i < 4; i++) {
                int newX = p.i + dx[i];
                int newY = p.j + dy[i];
                if (isCorrect(newX, newY) && a[newX][newY] == '.') {
                    pow++;
                    dir = i;
                }
            }
            if (pow != 1) {
                out.print("Not unique");
                return;
            }
            int newX = p.i + dx[dir];
            int newY = p.j + dy[dir];
            a[newX][newY] = end[dir];
            a[p.i][p.j] = bg[dir];
            for (int i = 0; i < 4; i++) {
                int newNewX = newX + dx[i];
                int newNewY = newY + dy[i];
                if (isCorrect(newNewX, newNewY) && getPower(newNewX, newNewY) == 1) {
                    q.add(new Pair(newNewX, newNewY));
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] == '.') {
                    out.print("Not unique");
                    return;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(a[i][j]);
            }
            out.println();
        }
    }

    public static void main(String[] args) {
        new SolveContest();
    }
}

