class TaskB {

    public char[][] a;
    public static int[][] grad;
    public int n,m;
    public final int[] dl = {0,0,-1,1};
    public final int[] dc = {1,-1,0,0};

    static class Pair{
        int x;
        int y;
        Pair(int x,int y){
            this.x = x;
            this.y = y;
        }
    }

    Queue<Pair> Q = new ArrayDeque<Pair>();

    private boolean good_cell(int x,int y){
        if(x >= n || y >= m || x < 0 || y < 0) return false;
        if(a[x][y] == '.') return true;
        return false;
    }

    private void update_neighbours(int i,int j){
        for(int k = 0; k < 4; k++){
            int x = i + dl[k];
            int y = j + dc[k];
            if(good_cell(x,y)) {
                grad[x][y]--;
                if(grad[x][y] == 1) Q.add(new Pair(x,y));
            }
        }
    }

    public void solve(int testNumber, Scanner in, PrintWriter out) {
        n = in.nextInt();
        m = in.nextInt();
        a = new char[n+1][m+1];
        grad = new int[n+1][m+1];
        for(int i = 0; i < n; i++)
            a[i] = in.next().toCharArray();
        for(int i = 0; i < n; i++)
            for(int j = 0; j < m; j++)
                if(a[i][j] == '.') {
                    for (int k = 0; k < 4; k++) {
                        int ii = i + dl[k];
                        int jj = j + dc[k];
                        if (good_cell(ii, jj)) grad[i][j]++;
                    }
                    if (grad[i][j] == 1) Q.add(new Pair(i,j));
                }
        while(!Q.isEmpty()){
            Pair p = Q.remove();
            if(grad[p.x][p.y] == 0){
                out.print("Not unique");
                return;
            }
            for(int k = 0; k < 4; k++){
                int ii = p.x + dl[k];
                int jj = p.y + dc[k];
                if(good_cell(ii,jj)){
                    if(k == 0){
                        a[p.x][p.y] = '<';
                        a[ii][jj] = '>';
                        update_neighbours(ii,jj);
                    }
                    else if(k == 1){
                        a[p.x][p.y] = '>';
                        a[ii][jj] = '<';
                        update_neighbours(ii,jj);
                    }
                    else if(k == 2){
                        a[p.x][p.y] = 'v';
                        a[ii][jj] = '^';
                        update_neighbours(ii,jj);
                    }
                    else{
                        a[p.x][p.y] = '^';
                        a[ii][jj] = 'v';
                        update_neighbours(ii,jj);
                    }
                    break;
                }
            }
        }
        for(int i = 0; i < n; i++)
            for(int j = 0; j < m; j++)
                if(a[i][j] == '.'){
                    out.print("Not unique");
                    return;
                }
        for(int i = 0; i < n; i++){
            for(int j = 0; j < m; j++)
                out.print(a[i][j]);
            out.print("\n");
        }

    }
}

