            for(int j = 0; j<m; j++){
                if(grid[i][j] == '*')
                    continue;
                check(i, j);
            }


        int ci, cj, ni, nj;
        while(!q.isEmpty()){
            ci = q.remove();
            cj = q.remove();
            ni = q.remove();
            nj = q.remove();
            if(grid[ci][cj] == '.' && grid[ni][nj] == '.'){
                if(ni == ci){
                    if(nj > cj){
                        grid[ci][cj] = '<';
                        grid[ni][nj] = '>';
                    }else{
                        grid[ci][cj] = '>';
                        grid[ni][nj] = '<';
                    }
                }else{ 
                    if(ni > ci){
                        grid[ci][cj] = '^';
                        grid[ni][nj] = 'v';
                    }else{
                        grid[ci][cj] = 'v';
                        grid[ni][nj] = '^';
                    }
                }
                for(int d = 0; d<4; d++)
                    if(!isSolid(ci+dx[d], cj+dy[d]))
                        check(ci+dx[d], cj+dy[d]);
                for(int d = 0; d<4; d++)
                    if(!isSolid(ni+dx[d], nj+dy[d]))
                        check(ni+dx[d], nj+dy[d]);
            }
        }
        boolean unique = true;
        for(int i = 0; i<n; i++)
            for(int j = 0; j<m; j++)
                unique &= grid[i][j] != '.';
        if(unique){
            for(int i = 0; i<n; i++)
                System.out.println(new String(grid[i]));
        }else System.out.println("Not unique");
    }
