    int[] dx = {0,0,1,-1};
    int[] dy = {1,-1,0,0};
    int n, m;
    char[][] grid;
    int ni, nj, sc;
    boolean isSolid(int i, int j){
        if(i < 0 || j < 0 || i >=n || j>=m)
            return true;
        return grid[i][j] != '.';
    }
    void check(int i, int j){
        ni = nj = -1;
        sc = 4;
        for(int d = 0; d<4; d++)
            if(!isSolid(i+dx[d], j+dy[d])){
                sc--;
                ni = i+dx[d];
                nj = j+dy[d];
            }
        if(sc == 3){
            q.add(i);
            q.add(j);
            q.add(ni);
            q.add(nj);

        }
    }
    public static void main(String[] args) {
        new D();
    }
}

