    static class TaskD {
        String[] colors = {
                "v^", "<>", "^v", "><"
        };
        char EMPTY = '.';
        int[] dx = {-1, 0, 1, 0};
        int[] dy = {0, 1, 0, -1};
        int n;
        int m;
        char[][] field;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.readInt();
            m = in.readInt();
            field = new char[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    field[i][j] = in.readCharacter();
                }
            }
            Queue<IntIntPair> q = new ArrayDeque<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (field[i][j] == EMPTY) {
                        if (degree(i, j) == 1) {
                            q.add(IntIntPair.makePair(i, j));
                        }
                    }
                }
            }
            while (!q.isEmpty()) {
                IntIntPair cur = q.poll();
                int i = cur.first;
                int j = cur.second;
                for (int d = 0; d < 4; d++) {
                    int x = i + dx[d];
                    int y = j + dy[d];
                    if (inside(x, y) && field[x][y] == EMPTY) {
                        fill(i, j, d);
                        for (int t = 0; t < 2; t++) {
                            for (int k = 0; k < 4; k++) {
                                int x1 = (t == 0 ? i : x) + dx[k];
                                int y1 = (t == 0 ? j : y) + dy[k];
                                if (inside(x1, y1) && field[x1][y1] == EMPTY && degree(x1, y1) == 1) {
                                    q.add(IntIntPair.makePair(x1, y1));
                                }
                            }
                        }
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (field[i][j] == '.') {
                        out.print("Not unique");
                        return;
                    }
                }
            }
            for (char[] row : field) {
                out.printLine(row);
            }
        }

        void fill(int x, int y, int d) {
            String color = colors[d];
            field[x][y] = color.charAt(0);
            field[x + dx[d]][y + dy[d]] = color.charAt(1);
        }

        int degree(int i, int j) {
            int deg = 0;
            for (int d = 0; d < 4; d++) {
                int x = i + dx[d];
                int y = j + dy[d];
                if (inside(x, y) && field[x][y] == EMPTY) {
                    deg++;
                }
            }
            return deg;
        }

        boolean inside(int x, int y) {
            return 0 <= x && x < n && 0 <= y && y < m;
        }

    }

