class TaskB {
    char grid[][];
    int degree[][];
    int dx[] = new int[]{0, 1, 0, -1};
    int dy[] = new int[]{1, 0, -1, 0};
    int n;
    int m;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        n = in.nextInt();
        m = in.nextInt();
        grid = new char[n + 2][m + 2];
        degree = new int[n + 2][m + 2];
        for (int i = 1; i <= n; i++) {
            char row[] = in.next().toCharArray();
            for (int j = 1; j <= m; j++) {
                grid[i][j] = row[j - 1];
            }
        }

        Queue<Pair> q = new LinkedList<>();
        int cells = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.') {
                    cells++;
                    for (int k = 0; k < 4; k++) {
                        int nx = i + dx[k];
                        int ny = j + dy[k];
                        if (grid[nx][ny] == '.') degree[i][j]++;
                    }
                    if (degree[i][j] == 1) q.add(new Pair(i, j));
                }
            }
        }

        while (!q.isEmpty()) {
            Pair p1 = q.remove();

            if (grid[p1.x][p1.y] != '.') continue;
            Pair p2 = adj(p1);
            if (p2 == null) {
                out.println("Not unique");
                return;
            }

            cover(p1.x, p1.y, p2.x, p2.y);
            degree[p1.x][p1.y] = 0;
            degree[p2.x][p2.y] = 0;
            for (int k = 0; k < 4; k++) {
                int nx = p2.x + dx[k];
                int ny = p2.y + dy[k];
                degree[nx][ny]--;
                if (degree[nx][ny] == 1) q.add(new Pair(nx, ny));
            }
            cells -= 2;
        }
        if (cells > 0) {
            out.println("Not unique");
        } else {
            for (int i = 1; i <= n; i++) {
                out.println(new String(grid[i], 1, m));
            }
        }

    }

    private Pair adj(Pair p) {
        for (int k = 0; k < 4; k++) {
            int nx = p.x + dx[k];
            int ny = p.y + dy[k];
            if (grid[nx][ny] == '.') return new Pair(nx, ny);
        }
        return null;
    }

    private void cover(int x1, int y1, int x2, int y2) {
        if (x1 == x2) {
            grid[x1][Math.min(y1, y2)] = '<';
            grid[x2][Math.max(y1, y2)] = '>';
        } else {
            grid[Math.min(x1, x2)][y1] = '^';
            grid[Math.max(x1, x2)][y2] = 'v';
        }
    }

    private class Pair {
        private final int x;
        private final int y;

        public Pair(int i, int j) {
            this.x = i;
            this.y = j;
        }
    }
}

