            map[i][j - 1] = '<';
            map[i][j] = '>';
            updateNeib(i, j - 1);
        }

        if (valid(i + 1, j) && map[i + 1][j] == '.') {
            map[i][j] = '^';
            map[i + 1][j] = 'v';
            updateNeib(i + 1, j);
        }

        if (valid(i - 1, j) && map[i - 1][j] == '.') {
            map[i - 1][j] = '^';
            map[i][j] = 'v';
            updateNeib(i - 1, j);
        }
        updateNeib(i, j);
    }

