class TaskD {
    char OCCUPIED = 'x';
    char PIECE = 'o';
    char EMPTY = '.';

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.readInt();
        char[][] board = new char[n][];
        for (int i = 0; i < n; ++i) {
            board[i] = in.readString().toCharArray();
        }
        char[][] ans = new char[2 * n - 1][2 * n - 1];
        for (char[] a : ans) Arrays.fill(a, EMPTY);
        ans[n - 1][n - 1] = PIECE;

        char[][] other = new char[n][n];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (board[i][j] == PIECE) {
                    other[i][j] = PIECE;
                } else {
                    other[i][j] = EMPTY;
                }
            }
        }
        for (int x = -1 * (n - 1); x <= n - 1; ++x) {
            for (int y = -1 * (n - 1); y <= n - 1; ++y) {
                if (x == 0 && y == 0) continue;
                boolean r = is_valid(board, x, y);
                if (r) {
                    ans[n - 1 + x][n - 1 + y] = OCCUPIED;
                    for (int i = 0; i < n; ++i) {
                        for (int j = 0; j < n; ++j) {
                            if (other[i][j] == PIECE) {
                                if (in(n, i + x, j + y)) {
                                    if (other[i + x][j + y] == EMPTY) {
                                        other[i + x][j + y] = OCCUPIED;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        boolean valid = true;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (board[i][j] != other[i][j]) {
                    valid = false;
                }
            }
        }
        if (valid) {
            out.println("YES");
            for (int i = 0; i < 2 * n - 1; ++i) {
                for (int j = 0; j < 2 * n - 1; ++j) {
                    out.print(ans[i][j]);
                }
                out.println();
            }
        } else {
            out.println("NO");
        }
    }

    private boolean is_valid(char[][] board, int x, int y) {
        int n = board.length;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (board[i][j] == PIECE) {
                    int x1 = i + x;
                    int y1 = j + y;
                    if (in(n, x1, y1)) {
                        if (board[x1][y1] == EMPTY) {
                            return false;
                        }
                    }
                } else if (board[i][j] == EMPTY) {
                    int x1 = i - x;
                    int y1 = j - y;
                    if (in(n, x1, y1)) {
                        if (board[x1][y1] == PIECE) {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

    private boolean in(int n, int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }
}

class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new UnknownError();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new UnknownError();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        } else if (c == '+') {
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String readString() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuffer res = new StringBuffer();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public static boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

}

import java.io.BufferedReader;
import java.io.InputStreamReader;
