import java.util.Arrays;
import java.util.StringTokenizer;

public class Solution {
  public void solve() throws Exception {
    int n = in.nextInt();
    boolean[][] atk = new boolean[n][n];
    ArrayList<int[]> pcs = new ArrayList<int[]>();
    for(int i = 0; i < n; i++) {
      String x = in.next();
      for(int j = 0; j < n; j++) {
        if(x.charAt(j) == 'x') {
          atk[i][j] = true;
        } else if(x.charAt(j) == 'o') {
          pcs.add(new int[]{i, j});
          atk[i][j] = true;
        }
      }
    }
    boolean[][] res = new boolean[2 * n - 1][2 * n - 1];
    for(int i = 0; i < res.length; i++) {
      Arrays.fill(res[i], true);
    }
    res[n - 1][n - 1] = false;
    for(int[] o : pcs) {
      for(int dx = 1 - n; dx <= n; dx++) {
        for(int dy = 1 - n; dy <= n; dy++) {
          int x = o[0] + dx;
          int y = o[1] + dy;
          if(x >= 0 && y >= 0 && x < n && y < n) {
            if(!atk[x][y]) {
              res[dx + n - 1][dy + n - 1] = false;
            }
          }
        }
      }
    }
    boolean[][] rec = new boolean[n][n];
    for(int[] o : pcs) {
      for(int dx = 1 - n; dx <= n; dx++) {
        for(int dy = 1 - n; dy <= n; dy++) {
          int x = o[0] + dx;
          int y = o[1] + dy;
          if(x >= 0 && y >= 0 && x < n && y < n) {
            if(res[dx + n - 1][dy + n - 1] || (dx == 0 && dy == 0)) {
              rec[x][y] = true;
            }
          }
        }
      }
    }
    for(int i = 0; i < rec.length; i++) {
      for(int j = 0; j < rec.length; j++) {
        if(rec[i][j] != atk[i][j]) {
          System.out.println("NO");
          return;
        }
      }
    }
    System.out.println("YES");
    for(int i = 0; i < res.length; i++) {
      for(int j = 0; j < res.length; j++) {
        if(i == n - 1 && j == n - 1) {
          System.out.print("o");
        } else {
          if(res[i][j]) {
            System.out.print("x");
          } else {
            System.out.print(".");
          }
        }
      }
      System.out.println();
    }

  }

  class Scanner {
    BufferedReader br;
    StringTokenizer st;
    public Scanner() throws Exception{
      br = new BufferedReader(new InputStreamReader(System.in));
    }
    String next() throws Exception {
      while (st == null || !st.hasMoreTokens()) {
        st = new StringTokenizer(br.readLine());
      }
      return st.nextToken();
    }

    public int nextInt() throws Exception {
      return Integer.parseInt(next());
    }

    public long nextLong() throws Exception {
      return Long.parseLong(next());
    }
  }
  Scanner in;
  PrintWriter out;

  public static void main(String[] args) throws Exception {
    new Solution().run();
  }

  private void run() throws Exception {
    in = new Scanner();
    out = new PrintWriter(System.out);
    solve();
    out.close();
  }
}

