public class D {

	final static int piece = 'o' - 'x';
	final static int space = '.' - 'x';
	static int n;

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		n = in.nextInt();
		int[][] table = new int[3*n][3*n];
		for (int i = 0; i < n; i++) {
			char[] c = in.next().toCharArray();
			for (int j = 0; j < n; j++) {
				table[n+j][n+i] = c[j] - 'x';
			}
		}
		in.close();




		boolean[][] moves = new boolean[2*n-1][2*n-1];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (table[n+j][n+i] == piece) {
					boolean[][] m = new boolean[2*n-1][2*n-1];
					getmoves(table, m, n+i, n+j);
					intersect(moves, m);
				}
			}			
		}




		int[][] newTable = new int[3*n][3*n];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (table[n+j][n+i] == piece) {
					insert(moves, newTable, i, j);
				}
			}
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (table[n+j][n+i] == 0) {
					if (newTable[n+j][n+i]!=1) {
						System.out.println("NO");
						return;
					}
				}
			}
		}




		System.out.println("YES");
		print(moves);
	}

	private static void print(boolean[][] moves) {
		for (int i = 0; i < 2*n -1 ; i++) {
			for (int j = 0; j < 2*n - 1; j++) {
				if (i == n-1 && j == n-1) {
					System.out.print('o');
				} else {
					if (moves[j][i]) {
						System.out.print(".");
					} else {
						System.out.print("x");
					}
				}
			}
			System.out.println();
		}
	}

	private static void insert(boolean[][] moves, int[][] newTable,
			int i, int j) {
		for (int y = i+1; y < i + 2*n; y++) {
			for (int x = j + 1; x < j + 2*n; x++) {
				if (!moves[x-j -1][y-i-1]) { 
					newTable[x][y] = 1;
				}
			}	
		}
	}



	private static void intersect(boolean[][] moves, boolean[][] m) {
		for (int i = 0; i < m.length; i++) {
			for (int j = 0; j < m.length; j++) {
				moves[j][i] = moves[j][i] || m [j][i];  
			}
		}
	}

	private static void getmoves(int[][] table, boolean[][] m, int i, int j) {
		for (int y = i-n+1; y < i+n; y++) {
			for (int x = j-n+1; x < j+n; x++) {
				m[x - j + n -1][y - i + n -1] = (table[x][y] == space);
			}
		}
	}

}

