class Solver{
	int n;
	char[][] board;
	List<Point> occupiedSquares;

	void read(InputReader in){
		n = in.nextInt();
		board = new char[n][];
		for(int i=0; i<n; i++) board[i] = in.next().toCharArray();


		occupiedSquares = new ArrayList<>();
		for(int row=0; row<n; row++){
			for(int column=0; column<n; column++){
				if(board[row][column] == 'o') 
					occupiedSquares.add(new Point(column, row));
			}
		}
	}

	boolean withinBounds(int x, int y){
		return x >= 0 && x < n && y >= 0 && y < n;
	}

	public void solve(InputReader in, PrintWriter out){
		read(in);

		char[][] res = new char[2*n-1][2*n-1];
		List<Point> moves = new ArrayList<>();

		for(int row=0; row<res.length; row++){
			for(int column=0; column<res[row].length; column++){
				if(row == n-1 && column == n-1){
					res[row][column] = 'o';
				}else{
					int xdir = column-(n-1), ydir = row-(n-1);
					for(Point square : occupiedSquares){
						int destinationX = square.x+xdir, destinationY = square.y+ydir;
						if(withinBounds(destinationX, destinationY)){
							if(board[destinationY][destinationX] == '.'){
								res[row][column] = '.';
								break;
							}
						}
					}
					if(res[row][column] != '.'){
						res[row][column] = 'x';
						moves.add(new Point(xdir, ydir));
					}
				}
			}
		}

		for(int row=0; row<n; row++){
			for(int column=0; column<n; column++){
				if(board[row][column] == 'x'){
					boolean possible = false;
					for(Point move : moves){
						int destinationX = column-move.x, destinationY = row-move.y;
						if(withinBounds(destinationX, destinationY) 
							&& board[destinationY][destinationX] == 'o')
						{
							possible = true;
							break;
						}
					}
					if(!possible){
						out.println("NO");
						return;
					}
				}
			}
		}

		out.println("YES");
		for(char[] row : res){
			for(char column : row){
				out.print(column);
			}
			out.println();
		}
	}
}

class InputReader {
	public BufferedReader reader;
	String currentLine[];
	int token;

	public InputReader(InputStream stream) {
		reader = new BufferedReader(new InputStreamReader(stream), 32768);
		currentLine = null;
		token = 0;
	}

	public String next(){
		while (currentLine == null || token >= currentLine.length) {
			try {
				currentLine = reader.readLine().trim().split("\\s+");
				token = 0;
			} catch (IOException e) {
				e.printStackTrace();
			}
		}
		return currentLine[token++];
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}
}

