class TaskD {
    private final FastScanner in;
    private final PrintWriter out;

    public TaskD(FastScanner in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }

    public void solve(int testNumber) throws IOException {
        int n = in.nextInt();
        String[] board = new String[n];
        for (int i = 0; i < n; i++) {
            board[i] = in.next();
        }
        int[] x = new int[n*n];
        int[] y = new int[n*n];
        int m = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i].charAt(j) == 'o') {
                    x[m] = i;
                    y[m] = j;
                    m++;
                }
            }
        }
        char[][] moves = new char[2*n-1][2*n-1];
        for (int i = 0; i < moves.length; i++) {
            Arrays.fill(moves[i], 'x');
        }
        moves[n - 1][n - 1] = 'o';
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i].charAt(j) == '.') {
                    for (int k = 0; k < m; k++) {
                        int dx = i - x[k];
                        int dy = j - y[k];
                        moves[n - 1 + dx][n - 1 + dy] = '.';
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i].charAt(j) == 'x') {
                    boolean ok = false;
                    for (int k = 0; k < m; k++) {
                        int dx = i - x[k];
                        int dy = j - y[k];
                        if (moves[n - 1 + dx][n - 1 + dy] == 'x') {
                            ok = true;
                            break;
                        }
                    }
                    if (!ok) {
                        out.println("NO");
                        return;
                    }
                }
            }
        }
        out.println("YES");
        for (int i = 0; i < moves.length; i++) {
            out.println(new String(moves[i]));
        }
    }
}

class FastScanner {
    private BufferedReader br;
    private String line = "";
    private int pos;

    public FastScanner(InputStream is) {
        this(new BufferedReader(new InputStreamReader(is)));
    }

    public FastScanner(Reader reader) {
        br = new BufferedReader(reader);
    }

    public String next() throws IOException {
        if (!goToNextToken()) {
            return null;
        }
        return readString();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    private boolean goToNextToken() throws IOException {
        if (br == null) {
            return false;
        }

        while (pos == line.length()) {
            line = br.readLine();

            if (line == null) {
                br = null;
                return true;
            }

            pos = 0;

            skipWhitespace();
        }

        return true;
    }

    private String readString() {
        int start = pos;

        while (pos < line.length()) {
            char c = line.charAt(pos);

            if (c == ' ' || c == '\t') {
                break;
            }

            pos++;
        }

        String result = line.substring(start, pos);

        skipWhitespace();

        return result;
    }

    private void skipWhitespace() {
        while (pos < line.length()) {
            char c = line.charAt(pos);

            if (c != ' ' && c != '\t') {
                break;
            }

            pos++;
        }
    }
}

