        a = new char[n][];
        idx = 0;
        oi = new int[n * n];
        oj = new int[n * n];
        for (int i = 0; i < n; i++)
        {
            a[i] = in.ns ().toCharArray ();
            for (int j = 0; j < n; j++)
            {
                if (a[i][j] == 'o')
                {
                    oi[idx] = i;
                    oj[idx] = j;
                    idx++;
                }
            }
        }
        baseI = baseJ = n - 1;
        safe = new boolean[2 * n - 1][2 * n - 1];
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                if (a[i][j] == '.')
                {
                    markSafe (i, j);
                }
            }
        }

        boolean ok = true;
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                if (a[i][j] == 'x')
                {
                    ok &= checkAttacked (i, j);
                }
            }
        }

        if (!ok)
        {
            out.println ("NO");
            return;
        }

        int len = 2 * n - 1;
        out.println ("YES");

        for (int i = 0; i < len; i++)
        {
            for (int j = 0; j < len; j++)
            {
                if (i == baseI && j == baseJ)
                {
                    out.print ('o');
                    continue;
                }
                out.print (safe[i][j] ? '.' : 'x');
            }
            out.println ();
        }

    }

    private boolean checkAttacked(int i, int j)
    {
        for (int k = 0; k < idx; k++)
        {
            int ii = oi[k];
            int jj = oj[k];
            int di = i - ii;
            int dj = j - jj;
            if(!safe[baseI + di][baseJ + dj])
            {
                return true;
            }
        }
        return false;
    }

    boolean safe[][];
    int baseI, baseJ;
    private void markSafe(int i, int j)
    {
        for (int k = 0; k < idx; k++)
        {
            int ii = oi[k];
            int jj = oj[k];
            int di = i - ii;
            int dj = j - jj;
            safe[baseI + di][baseJ + dj] = true;
        }
    }
}

class FastReader
{

    public InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public FastReader(InputStream stream)
    {
        this.stream = stream;
    }

    public int read()
    {
        if (numChars == -1)
        {
            throw new InputMismatchException ();
        }
        if (curChar >= numChars)
        {
            curChar = 0;
            try
            {
                numChars = stream.read (buf);
            } catch (IOException e)
            {
                throw new InputMismatchException ();
            }
            if (numChars <= 0)
            {
                return -1;
            }
        }
        return buf[curChar++];
    }

    public int ni()
    {
        int c = read ();
        while (isSpaceChar (c))
            c = read ();
        int sgn = 1;
        if (c == '-')
        {
            sgn = -1;
            c = read ();
        }
        int res = 0;
        do
        {
            if (c < '0' || c > '9')
            {
                throw new InputMismatchException ();
            }
            res *= 10;
            res += c - '0';
            c = read ();
        } while (!isSpaceChar (c));
        return res * sgn;
    }

    public String ns()
    {
        int c = read ();
        while (isSpaceChar (c))
            c = read ();
        StringBuilder res = new StringBuilder ();
        do
        {
            res.appendCodePoint (c);
            c = read ();
        } while (!isSpaceChar (c));
        return res.toString ();
    }

    public boolean isSpaceChar(int c)
    {
        if (filter != null)
        {
            return filter.isSpaceChar (c);
        }
        return isWhitespace (c);
    }

    public static boolean isWhitespace(int c)
    {
        return c==' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public interface SpaceCharFilter
    {
        public boolean isSpaceChar(int ch);
    }
}

