        char[][] c = new char[n][];
        for (int i = 0; i < n; i++)
            c[i] = in.next().toCharArray();
        boolean[][] good = new boolean[2 * n + 1][2 * n + 1];
        boolean[][] covered = new boolean[n][n];
        for (int dx = -n; dx <= n; dx++) {
            for (int dy = -n; dy <= n; dy++)
                if (dx != 0 || dy != 0)
                    good[dx + n][dy + n] = true;
        }
