class TaskD {
    int n;
    public void solve(int testNumber, Reader in, PrintWriter out) {
        n = in.ni();
        String[] s = new String[n];
        for(int i = 0; i < n; i++) {
            s[i] = in.rl();
        }
        int n2 = 2 * n - 1;
        char[][] ans = new char[n2][n2];
        boolean[][] beat = new boolean[n][n];
        for(int i = 0; i < n2; i++) {
            for(int j = 0; j < n2; j++) {
                ans[i][j] = '.';
            }
        }
        ans[n - 1][n - 1] = 'o';
        int dx, dy;
        for(int i = 0; i < n2; i++) {
            for(int j = 0; j < n2; j++) {
                if(i == n - 1 && j == n - 1) {
                    continue;
                }
                dx = i - n + 1;
                dy = j - n + 1;
                boolean allFine = true;
                for(int x = 0; x < n; x++) {
                    for(int y = 0; y < n; y++) {
                        if(s[x].charAt(y) == 'o' && check(x + dx, y + dy)) {
                            if(s[x + dx].charAt(y + dy) == '.') {
                               allFine = false;
                            }
                        }
                    }
                }
                if(allFine) {
                    for(int x = 0; x < n; x++) {
                        for(int y = 0; y < n; y++) {
                            if(s[x].charAt(y) == 'o' && check(x + dx, y + dy)) {
                                if(s[x + dx].charAt(y + dy) == 'x') {
                                    beat[x + dx][y + dy] = true;
                                }
                            }
                        }
                    }
                    ans[i][j] = 'x';
                }
            }
        }
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < n; j++) {
                if(s[i].charAt(j) == 'x' && !beat[i][j]) {
                    out.println("NO");
                    return;
                }
            }
        }
        out.println("YES");
        for(int i = 0; i < n2; i++) {
            for(int j = 0; j < n2; j++) {
                out.print(ans[i][j]);
            }
            out.println();
        }
    }

    public boolean check(int x, int y) {
        return (x >= 0 && x < n && y >= 0 && y < n);
    }
}

