        for (int i = 0; i < 2*n-1; i++)
        {
            for (int j = 0; j < 2*n-1; j++)
            {
                if (vector[i][j] == 0) continue;
                int dx = i-n+1;
                int dy = j-n+1;
                for (Pair pair : pieces)
                {
                    if (oob(pair.x + dx, pair.y + dy, n))
                    {
                        continue;
                    }
                    board2[pair.x + dx][pair.y + dy] = 1;
                }
            }
        }
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                if (board[i][j] == 1 && board2[i][j] != 1)
                {
                    System.out.println("NO");
                    return;
                }
                if (board[i][j] == 0 && board[i][j] != 0)
                {
                    System.out.println("NO");
                    return;
                }
            }
        }
        System.out.println("YES");
        for (int i = 0; i < 2*n-1; i++)
        {
            for (int j = 0; j < 2*n-1; j++)
            {
                if (vector[i][j] == 1)
                {
                    System.out.print("x");
                }
                else if (vector[i][j] == -1)
                {
                    System.out.print("o");
                }
                else
                {
                    System.out.print(".");
                }
            }
            System.out.println();
        }
    }

    static boolean oob(int x, int y, int n)
    {
        return x < 0 || x >= n || y < 0 || y >= n;
    }

    static class Pair
    {
        int x, y;
        public Pair(int xx, int yy)
        {
            x = xx; y = yy;
        }
    }
}

