    static class TaskD {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.readInt();
            char[][] a = new char[n][n];
            for (int i = 0; i < n; i++) {
                a[i] = in.readString().toCharArray();
            }
            char[][] sol = new char[2 * n - 1][2 * n - 1];
            for (int i = 0; i < 2 * n - 1; i++) {
                Arrays.fill(sol[i], 'x');
            }
            sol[n - 1][n - 1] = 'o';
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (a[i][j] == 'o') {
                        for (int k = 0; k < n; k++) {
                            for (int l = 0; l < n; l++) {
                                if (a[k][l] == '.') {
                                    sol[n - 1 - i + k][n - 1 - j + l] = '.';
                                }
                            }
                        }
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (a[i][j] == 'x') {
                        boolean f = false;
                        for (int k = 0; k < n; k++) {
                            for (int l = 0; l < n; l++) {
                                if (a[k][l] == 'o') {
                                    if (sol[n - 1 + i - k][n - 1 + j - l] != '.') {
                                        f = true;
                                    }
                                }
                            }
                        }
                        if (!f) {
                            out.println("NO");
                            return;
                        }
                    }
                }
            }
            out.println("YES");
            for (int i = 0; i < 2 * n - 1; i++) {
                for (int j = 0; j < 2 * n - 1; j++) {
                    out.print(sol[i][j]);
                }
                out.println();
            }
        }

    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            try {
                if (curChar >= numChars) {
                    curChar = 0;
                    numChars = stream.read(buf);
                    if (numChars <= 0)
                        return -1;
                }
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return buf[curChar++];
        }

        public int readInt() {
            return (int) readLong();
        }

        public long readLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
                if (c == -1) throw new RuntimeException();
            }
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return negative ? (-res) : (res);
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

