class TaskD {
    String[] board;
    class P {
        int x;
        int y;

        public String toString() {
            return "P{" +
                    "x=" + x +
                    ", y=" + y +
                    '}';
        }

        public P(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;

            P p = (P) o;

            if (x != p.x) return false;
            if (y != p.y) return false;

            return true;
        }

        public int hashCode() {
            int result = x;
            result = 31 * result + y;
            return result;
        }
    }
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        board = new String[n];
        for (int i = 0; i < n; i++) {
            board[i] = in.next();
        }
        Set<P> os = new HashSet<>();
        Set<P> xs = new HashSet<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i].charAt(j)=='o') os.add(new P(i,j));
                if (board[i].charAt(j)=='x') xs.add(new P(i,j));
            }
        }
        Set<P> allowedShifts = new HashSet<>();
        for (int dx = -n+1; dx < n ; dx++) {
            for (int dy = -n+1; dy < n; dy++) {
                boolean OK = true;
                for(P o : os) {

                    int nx = o.x + dx;
                    int ny = o.y + dy;
                    if (nx<0 || nx>=n || ny<0 || ny>=n) continue;
                    P nn = new P(nx, ny);
                    if (!(os.contains(nn) || xs.contains(nn))) {

                        OK = false;
                        break;
                    }
                }
                if (OK) allowedShifts.add(new P(dx,dy));
            }
        }


        for(P x : xs) {
            int explained = 0;
            for (P o : os) {
                int dx = x.x - o.x;
                int dy = x.y - o.y;
                if (allowedShifts.contains(new P(dx,dy))) ++explained;
            }
            if (explained==0) {
                out.println("NO");
                return;
            }
        }
        out.println("YES");

        char[][] moves = new char[2 * n - 1][2 * n - 1];
        for (int i = 0; i < 2 * n - 1; i++) {
            for (int j = 0; j < 2 * n - 1; j++) {
                moves[i][j]='.';
            }
        }
        for (int i = 0; i < 2*n-1; i++) {
            for (int j = 0; j < 2*n-1; j++) {
                int dx = i - n + 1;
                int dy = j - n + 1;
                if (allowedShifts.contains(new P(dx,dy))) {
                    moves[i][j]='x';
                }
            }
        }
        moves[n-1][n-1]='o';
        for (int i = 0; i < 2 * n - 1; i++) {
            out.println(new String(moves[i]));
        }

    }
}

