public class DMain {
    String noResultMessage = "NO";
    Parser in = new Parser();
    PrintWriter out;

    int n = in.nextInteger();

    char[][] area = new char[n][];

    char fig = 'o';
    char X = 'x';
    char empty = '.';

    int[] figX = new int[n*n];
    int[] figY = new int[n*n];
    int figCount = 0;


    public void solve() {
        in.nextLine();
        for(int i = 0; i < n; ++i){
            area[i] = in.nextLine().toCharArray();
            for(int j = 0; j < n; ++j){
                if(area[i][j] == fig){
                    figX[figCount] = i;
                    figY[figCount++] = j;
                }
            }
        }
        char[][] res = new char[2*n-1][2*n-1];
        for(int i = -n+1; i < n; ++i){
            for(int j = -n+1; j < n; ++j){
                if(i == 0 && j == 0)continue;

                boolean hasX = false;
                boolean hasEmpty = false;
                for(int f = 0; f < figCount; ++f){
                    int x = figX[f] + i;
                    int y = figY[f] + j;
                    if(x < 0 || y < 0 || x >= n || y >= n)continue;
                    if(area[x][y] == fig)continue;
                    if(area[x][y] == X)hasX = true;
                    else hasEmpty = true;
                }
                res[n+i-1][n+j-1] = hasEmpty ? empty : X;
            }
        }
        res[n-1][n-1] = fig;

        for(int i = -n+1; i < n; ++i){
            for(int j = -n+1; j < n; ++j){
                if(res[n+i-1][n+j-1] != X)continue;
                for(int f = 0; f < figCount; ++f){
                    int x = figX[f] + i;
                    int y = figY[f] + j;
                    if(x < 0 || y < 0 || x >= n || y >= n)continue;
                    area[x][y] = empty;
                }
            }
        }
        for(int i = 0; i < n; ++i){
            for(int j = 0; j < n; ++j){
                if(area[i][j] == X)noResult();
            }
        }
        out.println("YES");
        for(char[] row : res){
            out.println(new String(row));
        }
    }



    static public class Parser{
        Scanner scanner;

        public Parser() {
            scanner = new Scanner(System.in).useLocale(Locale.ENGLISH);
        }

        public Parser(String str) {
            scanner = new Scanner(str).useLocale(Locale.ENGLISH);
        }

        long nextLong(){
            return scanner.nextLong();
        }

        int nextInteger(){
            return scanner.nextInt();
        }

        double nextDouble(){
            return scanner.nextDouble();
        }

        String nextLine(){
            return scanner.nextLine();
        }

        String next(){
            return scanner.next();
        }

        int[] nextIntegers(int count){
            int[] result = new int[count];
            for(int i = 0; i < count; ++i){
                result[i] = nextInteger();
            }
            return result;
        }

        long[] nextLongs(int count){
            long[] result = new long[count];
            for(int i = 0; i < count; ++i){
                result[i] = nextLong();
            }
            return result;
        }

        int[][] nextIntegers(int fields, int count){
            int[][] result = new int[fields][count];
            for(int c = 0; c < count; ++c){
                for(int i = 0; i < fields; ++i){
                    result[i][c] = nextInteger();
                }
            }
            return result;
        }
    }

    void noResult(){
        throw new NoResultException();
    }

    void noResult(String str){
        throw new NoResultException(str);
    }

    void run(){
        try{
            ByteArrayOutputStream outStream = new ByteArrayOutputStream();
            out = new PrintWriter(outStream);
            solve();
            out.close();
            System.out.print(outStream.toString());
        } catch (NoResultException exc){
            System.out.print(null == exc.response ? noResultMessage : exc.response);
        }
    }

    public static void main(String[] args) {
        new DMain().run();
    }

    public static class NoResultException extends RuntimeException{
        private String response;

        public NoResultException(String response) {
            this.response = response;
        }

        public NoResultException() {
        }
    }
}

