public class C {
	FastScanner in;
	PrintWriter out;

	boolean check(char[][] d, char[][] c) {
		int n = c.length;
		boolean[][] beat = new boolean[n][n];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (c[i][j] == 'o') {
					for (int ii = -n + 1; ii < n; ii++) {
						for (int jj = -n + 1; jj < n; jj++) {
							if (d[n - 1 + ii][n - 1 + jj] == 'x' && i + ii >= 0
									&& i + ii < n && j + jj >= 0 && j + jj < n) {
								beat[i + ii][j + jj] = true;
							}
						}
					}
				}
			}
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (c[i][j] == 'x' && !beat[i][j])
					return false;
			}
		}
		return true;
	}

	void solve() {
		int n = in.nextInt();
		char[][] c = new char[n][n];
		for (int i = 0; i < n; i++) {
			c[i] = in.next().toCharArray();
		}
		char[][] res = new char[2 * n - 1][2 * n - 1];

		for (int di = -n + 1; di < n; di++) {
			for (int dj = -n + 1; dj < n; dj++) {
				boolean ok = true;
				checkLoop:
				for (int i = 0; i < n; i++) {
					for (int j = 0; j < n; j++) {
						if (c[i][j] == 'o') {
							int ni = i + di, nj = j + dj;
							if (ni >= 0 && ni < n && nj >= 0 && nj < n && c[ni][nj] == '.') {
								ok = false;
								break checkLoop;
							}
						}
					}
				}
				res[di + n - 1][dj + n - 1] = ok ? 'x' : '.';
			}
		}
		res[n - 1][n - 1] = 'o';
		if (!check(res, c)) {
			out.println("NO");
		} else {
			out.println("YES");
			for (char[] cc : res) {
				out.println(new String(cc));
			}
		}
	}

	void run() {
		in = new FastScanner();
		out = new PrintWriter(System.out);

		solve();

		out.close();
	}

	class FastScanner {
