import java.util.Scanner;

public class D {

	static char[][] board;
	static int n;
	static char[][] move;

	public static void main(String[] args) {

		Scanner in = new Scanner(System.in);

		n = in.nextInt();
		in.nextLine();

		board = new char[n][n];

		for (int i = 0; i < n; i++) {
			board[i] = in.nextLine().toCharArray();
		}

		move = new char[2 * n - 1][2 * n - 1];
		move[n - 1][n - 1] = 'o';

		for (int dx = -n + 1; dx <= n - 1; dx++) {
			for (int dy = -n + 1; dy <= n - 1; dy++) {
				if (dx != 0 || dy != 0) {
					if (valid(dx, dy)) {
						move[n - 1 + dx][n - 1 + dy] = 'x';
						mark(dx, dy);
					} else {
						move[n - 1 + dx][n - 1 + dy] = '.';
					}
				}
			}
		}

		if (unmarked()) {
			System.out.print("NO");
		} else {
			System.out.println("YES");
			for (int i = 0; i < 2 * n - 1; i++) {
				for (int j = 0; j < 2 * n - 1; j++) {
					System.out.print(move[i][j]);
				}
				System.out.println();
			}
		}

	}

	private static void mark(int dx, int dy) {
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (board[i][j] == 'o')
					mark(i, j, dx, dy);
			}
		}
	}

	private static void mark(int i, int j, int dx, int dy) {
		if (i + dx >= 0 && i + dx < n && j + dy >= 0 && j + dy < n && board[i + dx][j + dy] == 'x') {
			board[i + dx][j + dy] = 'X';
		}
	}

	private static boolean unmarked() {
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (board[i][j] == 'x')
					return true;
			}
		}
		return false;
	}

	private static boolean valid(int dx, int dy) {
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (board[i][j] == 'o' && unattacked(i, j, dx, dy))
					return false;
			}
		}
		return true;
	}

	private static boolean unattacked(int i, int j, int dx, int dy) {
		if (i + dx >= 0 && i + dx < n && j + dy >= 0 && j + dy < n
				&& board[i + dx][j + dy] == '.') {
			return true;
		}
		return false;
	}
}

