		PrintWriter pw = new PrintWriter(System.out);

		int n = nextInt(br);

		int[][] grid = new int[n][n];
		char[][] ans = new char[2*n-1][2*n-1];

		for(int i = 0; i < 2*n-1; i++){
			Arrays.fill(ans[i], '.');
		}

		ArrayList<Integer> px = new ArrayList<Integer>();
		ArrayList<Integer> py = new ArrayList<Integer>();

		for(int i = 0; i < n; i++){
