						grid[i][j] = 0;
						break;
				}
			}
		}

		for(int i = -n+1; i < n; i++){
			for(int j = -n+1; j < n; j++){
				boolean poss = true;
				for(int k = 0; k < px.size(); k++){
					if(px.get(k) + i >= 0 && px.get(k) + i < n && py.get(k) + j >= 0 && py.get(k) + j < n){
						if(grid[px.get(k)+i][py.get(k)+j] == 0){
							poss = false;
							break;
						}
					}
				}

				if(poss){
					ans[i+n-1][j+n-1] = 'x';
				}
			}
