        for (int i : arr) {
            System.out.print(i + " ");
        }
        System.out.println();
    }

    public static void solve(char[][] board, int size) {
        boolean[][] marked = new boolean[size][size];
        ArrayList<Pair> wo = new ArrayList<Pair>();
        ArrayList<Pair> pi = new ArrayList<Pair>();
        for (int i =0 ; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (board[i][j] == 'o') {
                    Pair p = new Pair(i, j);
                    pi.add(p);
                    marked[i][j] = true;
                } else if (board[i][j] == 'x') { marked[i][j] = false; }
                else { marked[i][j] = true; }
            }
        }

        char[][] output = new char[2*size-1][2*size-1];
        for (int i = 0; i < 2*size-1; i++) {
            for (int j = 0; j < 2*size-1; j++) {
                output[i][j] = '.';
            }
        }
        output[size-1][size-1] = 'o';
        boolean g = false;
        boolean one = false;
        for (int dx = -(size-1); dx <= (size - 1); dx++) {
            for (int dy = -(size-1); dy <= (size - 1); dy++) {
                if (dx == 0 && dy == 0) { continue; }
                g = true;
                for (Pair p : pi) {
                    int x = p.x; int y = p.y;
                    if (x + dx < 0 || x + dx >= size)  {
                        continue;
                    }
                    if (y + dy < 0 || y + dy >= size)  {
                        continue;
                    }
                    if (board[x+dx][y+dy] == '.') {
                        g = false;
                        break;
                    }
                }
                if (g) {
                    wo.add(new Pair(dx, dy));
                    for (Pair p : pi) {
                        int x = p.x; int y = p.y;
                        if (x + dx < 0 || x + dx >= size)  {
                            continue;
                        }
                        if (y + dy < 0 || y + dy >= size)  {
                            continue;
                        }
                        marked[x+dx][y+dy] = true;
                    }
                }
            }
        }
        if (wo.size() == 0) {
            print("NO");
            return;
        }
        for (int i = 0; i < size; i++) {
            for (int j =0; j < size; j++) {
                if (!marked[i][j]) {
                    print("NO");
                    return;
                }
            }
        }
        print("YES");
        for (Pair p: wo) {
            int x = p.x; int y = p.y;
            output[size-1+x][size-1+y] = 'x';
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < output.length; i++) {
            sb.append(output[i]);
            sb.append("\n");
        }
        System.out.println(sb.toString());
    }

    public static void main(String args[]) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        int size = Integer.parseInt(br.readLine());
        char[][] board = new char[size][size];
        for (int i = 0; i < size; i++) {
            board[i] = br.readLine().toCharArray();
        }
        if (size == 1) {
            print("YES");
            print("o");
        } else {
            solve(board, size);
        }
    }
}

