public class D {
	private static BufferedReader in;
	private static StringTokenizer st;
	private static PrintWriter out;

	public static void main(String[] args) throws NumberFormatException, IOException {
		Locale.setDefault(Locale.US);
		in = new BufferedReader(new InputStreamReader(System.in));
		st = new StringTokenizer("");
		out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
		int n = nextInt();
		char a[][] = new char[n+1][n+1];
		ArrayList<Point> list = new ArrayList<Point>();
		for (int i = 1; i <= n; i++) {
			String s = next();
			for (int j = 1; j <= n; j++) {
				a[i][j] = s.charAt(j-1);
				if(a[i][j] =='o'){
					list.add(new Point(i,j));
				}
			}
		}
		ArrayList<Point> moves = new ArrayList<Point>();
		for (int dx = -n; dx <=n; dx++) {
			for (int dy = -n; dy <=n; dy++) {
				boolean movable = true;
				for (Point p : list) {
					Point go = new Point(p.x + dx, p.y + dy);
					if(inBoard(go,n) && a[go.x][go.y] == '.'){
						movable = false;
						break;
					}
				}
				if(movable){
					moves.add(new Point(dx, dy));
				}
			}
		}
		boolean attacked[][] = new boolean [n+1][n+1];
		for (Point piece : list) {
			for (Point move : moves) {
				Point go = new Point(piece.x + move.x, piece.y + move.y);
				if(inBoard(go, n)){
					attacked[go.x][go.y] = true;
				}
			}
		}

		boolean ok = true;
		for (int i = 1; i <= n; i++) {
			for (int j = 1; j <= n; j++) {
				if(a[i][j] == 'x'){
					if(!attacked[i][j]){
						ok = false;
						break;
					}
				}
			}
		}
		if(!ok){
			System.out.println("NO");
			return;
		}
		char ans[][] = new char [2 * n + 1][2 * n+1];
		for (int i = 1; i <= 2 * n; i++) {
			for (int j = 1; j <= 2 * n - 1; j++) {
				ans[i][j] = '.';
			}
		}
		ans[n][n] = 'o';
		for (Point d : moves) {
			if(ans[n + d.x][n+d.y] == '.')
				ans[n + d.x][n+d.y] = 'x';
		}
		out.println("YES");
		for (int i = 1; i <= 2 * n-1; i++) {
			for (int j = 1; j <= 2 * n-1; j++) {
				out.print(ans[i][j]);
			}
			out.println();
		}
		out.close();
	}

	private static boolean inBoard(Point go, int n) {
		return 1 <= go.x && go.x <=n && 1 <= go.y && go.y <=n;
	}

	private static double nextDouble() throws NumberFormatException, IOException {
		return Double.parseDouble(next());
	}

	private static long nextLong() throws NumberFormatException, IOException {
		return Long.parseLong(next());
	}

	private static int nextInt() throws NumberFormatException, IOException {
		return Integer.parseInt(next());
	}

	private static String next() throws IOException {
		while(!st.hasMoreTokens())
			st = new StringTokenizer(in.readLine());
		return st.nextToken();
	}
}

