public class D {

    void run(){
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        char[][] m = new char[n][];
        Set<int[]> xs = new HashSet<int[]>(), os = new HashSet<int[]>();
        for(int i=0;i<n;i++){
            m[i] = sc.next().toCharArray();
            for(int j=0;j<n;j++){
                if(m[i][j]=='o')os.add(new int[]{i, j});
                else if(m[i][j]=='x')xs.add(new int[]{i, j});
            }
        }
        char[][] res = new char[2*n-1][2*n-1];
        boolean[][] cover = new boolean[n][n];
        for(int i=0;i<2*n-1;i++)for(int j=0;j<2*n-1;j++){
            res[i][j] = '.';
            if (i==n-1 && j==n-1){
                res[n-1][n-1] = 'o'; continue;
            }
            int dy = i-(n-1), dx = j-(n-1);
            boolean ok = true;
            for(int[] o:os){
                int ni = o[0]+dy, nj = o[1]+dx;
                if (0<=ni&&ni<n && 0<=nj&&nj<n && m[ni][nj]=='.'){
                    ok = false; break;
                }
            }
            if (ok){
                res[i][j] = 'x';
                for(int[] o:os){
                    int ni = o[0]+dy, nj = o[1]+dx;
                    if (0<=ni&&ni<n && 0<=nj&&nj<n){
                        cover[ni][nj] = true;
                    }
                }
            }
        }
        boolean exist = true;
        for(int[] x:xs)exist&=cover[x[0]][x[1]];
        if(exist){
            System.out.println("YES");
            for(int i=0;i<2*n-1;i++)System.out.println(new String(res[i]));
        }
        else System.out.println("NO");
    }

    void debug(Object...o){
        System.out.println(Arrays.deepToString(o));
    }

    public static void main(String[] args) {
        new D().run();
    }
}

