class TaskD {

    public void solve(int testNumber, FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        char[][] field = new char[n][];
        for (int i = 0; i < n; i++)
            field[i] = in.nextWord();

        boolean[][] answer = new boolean[2 * n - 1][2 * n - 1];
        for (boolean[] anAnswer : answer)
            Arrays.fill(anAnswer, true);

        int mid = n - 1;
        answer[mid][mid] = false;

        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (field[i][j] == 'o')
                    for (int k = 0; k < n; k++)
                        for (int l = 0; l < n; l++)
                            if (field[k][l] == '.')
                                answer[mid + k - i][mid + l - j] = false;

        boolean[][] covered = new boolean[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (field[i][j] == 'o')
                    for (int k = 0; k < n; k++)
                        for (int l = 0; l < n; l++)
                            if (answer[k - i + mid][l - j + mid])
                                covered[k][l] = true;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (field[i][j] == 'x' && !covered[i][j]) {
                    out.print("NO");
                    return;
                }
            }
        }

        out.println("YES");
        for (int i = 0; i < answer.length; i++) {
            for (int j = 0; j < answer.length; j++)
                out.print(i == mid && j == mid ? 'o' : answer[i][j] ? 'x' : '.');

            out.println();
        }
    }

}

