			st = new StringTokenizer(in.readLine());
		return st.nextToken();
	}

	int nextInt() throws Exception {
		return Integer.parseInt(next());
	}

	long nextLong() throws Exception {
		return Long.parseLong(next());
	}

	double nextDouble() throws Exception {
		return Double.parseDouble(next());
	}

	void solve() throws Exception {
		int n = nextInt();
		String s[] = new String[n];
		int u[][] = new int[n][n];
		ArrayList<Integer> f = new ArrayList<Integer>();
		ArrayList<Integer> e = new ArrayList<Integer>();

		for (int i = 0; i < n; i++) {
			s[i] = next();
			for (int j = 0; j < n; j++) {
				if (s[i].charAt(j) == 'x')
					u[i][j] = 1;
				if (s[i].charAt(j) == 'o') {
					u[i][j] = 0;
					f.add(i * 64 + j);
				}
				if (s[i].charAt(j) == '.') {
					u[i][j] = -1;
					e.add(i * 64 + j);
				}
			}
		}

		boolean forb[][] = new boolean[2 * n - 1][2 * n - 1];

		for (int cf : f)
			for (int ce : e) {
				int fx = cf / 64;
				int fy = cf & 63;
				int ex = ce / 64;
				int ey = ce & 63;
				int dx = ex - fx;
				int dy = ey - fy;
				forb[dx + n - 1][dy + n - 1] = true;
			}

		boolean field[][] = new boolean[n][n];
		for (int cf : f) {
			int fx = cf / 64;
			int fy = cf & 63;

			for (int dx = -fx; dx + fx < n; dx++)
				for (int dy = -fy; dy + fy < n; dy++)
					if (!forb[dx + n - 1][dy + n - 1]) { 
						field[fx + dx][fy + dy] = true;
					}
		}

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++)
				if (!field[i][j] && u[i][j] == 1) {
					out.print("NO");
					return;
				}
		}
		out.println("YES");

		for (int i = 0; i < 2 * n - 1; i++) {
			for (int j = 0; j < 2 * n - 1; j++)
				if ((i == n - 1) && (j == n - 1))
					out.print("o");
				else {
					out.print(forb[i][j] ? "." : "x");
				}
			out.println();
		}

	}

	void run() {
		try {
			Locale.setDefault(Locale.US);
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(new OutputStreamWriter(System.out));
			solve();
			out.close();
		} catch (Exception e) {
			e.printStackTrace();
			System.exit(1);
		}
	}

	public static void main(String[] args) {
		new A().run();
	}

}

