    private int MOD = 1000 * 1000 * 1000 + 7;

    int sum(int a, int b) {
        a += b;
        return a >= MOD ? a - MOD : a;
    }

    int product(int a, int b) {
        return (int) (1l * a * b % MOD);
    }

    int pow(int x, int k) {
        int result = 1;
        while (k > 0) {
            if (k % 2 == 1) {
                result = product(result, x);
            }
            x = product(x, x);
            k /= 2;
        }
        return result;
    }

    int inv(int x) {
        return pow(x, MOD - 2);
    }

    void solve() throws IOException {
        int n = nextInt();
        char[][] board = new char[n][n];
        for (char[] row : board) {
            System.arraycopy(next().toCharArray(), 0, row, 0, n);
        }
        char[][] moves = new char[2 * n - 1][2 * n - 1];
        for (char[] row : moves) {
            Arrays.fill(row, 'x');
        }
        int xc = n - 1, yc = n - 1;
        moves[xc][yc] = 'o';
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < n; j++) {
                if(board[i][j] == 'o') {
                    for(int r = 0; r < n; r++) {
                        for(int c = 0; c < n; c++) {
                            if(board[r][c] == '.') {
                                moves[xc + r - i][yc + c - j] = '.';
                            }
                        }
                    }
                }
            }
        }
        char[][] check = new char[n][n];
        for (char[] row : check) {
            Arrays.fill(row, '.');
        }
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < n; j++) {
                if(board[i][j] == 'o') {
                    check[i][j] = 'o';
                    for(int r = 0; r < n; r++) {
                        for(int c = 0; c < n; c++) {
                            if(check[r][c] == '.' && moves[xc + r - i][yc + c - j] == 'x') {
                                check[r][c] = 'x';
                            }
                        }
                    }
                }
            }
        }
        for(int i = 0; i < n; i++) {
            if(!new String(board[i]).equals(new String(check[i]))) {
                writer.println("NO");
                return;
            }
        }
        writer.println("YES");
        for (char[] row : moves) {
            writer.println(row);
        }
    }

    public static void main(String[] args) throws IOException {
        try (A a = new A()) {
            a.solve();
        }
    }

