public class TaskA {
    static class Escanner {
        BufferedReader in;
        StringTokenizer st;

        Escanner() throws Throwable {
            in = new BufferedReader(new InputStreamReader(System.in));
            st = new StringTokenizer("");
        }

        String nextStr() throws Throwable {
            if (st.hasMoreTokens())
                return st.nextToken();
            st = new StringTokenizer(in.readLine());
            return nextStr();
        }

        int nextInt() throws Throwable {
            return Integer.parseInt(nextStr());
        }

        long nextLong() throws Throwable {
            return Long.parseLong(nextStr());

        }

        BigInteger nextBigInt() throws Throwable {
            return new BigInteger(nextStr());
        }

        double nextDouble() throws Throwable {
            return Double.parseDouble(nextStr());
        }
    }

    static int n, m, r1, r2, c1, c2;
    static boolean[][] g;
    static boolean reached = false;
    static int[] dr = { 0, 1, -1, 0 };
    static int[] dc = { 1, 0, 0, -1 };

    static void dfs(int r, int c) {
        g[r][c] = true;
        for (int k = 0; k < 4; k++) {
            if (reached)
                break;
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (nr == r2 && nc == c2) {
                reached = true;
                return;
            } else if (isValid(nr, nc) && !g[nr][nc])
                dfs(nr, nc);
        }
    }

    static boolean isValid(int r, int c) {
        return (r >= 0 && r < n && c >= 0 && c < m);
    }

    static boolean isN(int r1,int c1,int r2,int c2){
        int dr = Math.abs(r1-r2);
        int dc = Math.abs(c1-c2);
        return (dr==1 && dc==0) || (dr==0 && dc==1);

    }
    static int nncn(int r, int c) {
        int cnt=0;
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isValid(nr, nc) && !g[nr][nc])
                cnt++;
        }
        return cnt;
    }

    public static void main(String[] args) throws Throwable {
        Escanner sc = new Escanner();
        n = sc.nextInt();
        m = sc.nextInt();
        g = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String s = sc.nextStr();
            for (int j = 0; j < m; j++)
                g[i][j] = s.charAt(j) == '.' ? false : true;
        }
        r1 = sc.nextInt() - 1;
        c1 = sc.nextInt() - 1;
        r2 = sc.nextInt() - 1;
        c2 = sc.nextInt() - 1;
        boolean cracked = g[r2][c2];
        int ncn = nncn(r2,c2);


        dfs(r1, c1);
        if (reached){
            if (cracked || (isN(r1,c1,r2,c2) && ncn>=1) || ncn>=2)
                System.out.println("YES");
            else
                System.out.println("NO");
        }else
            System.out.println("NO");

    }
}

