        for (int i = 0; i < 4; i++) {
            int r = r2 + dx[i];
            int c = c2 + dy[i];
            if (r < n && r >= 0 && c < m && c >= 0 && (b[r][c] == '.' || (r == r1 && c == c1))) cnt++;
        }
        if (r1 == r2 && c1 == c2) {
            if (cnt > 0)
                System.out.println("YES");
            else
                System.out.println("NO");
