        v[r1][c1] = true;
        for (int i = 0; i < 4; i++) {
            int r = r1 + dx[i];
            int c = c1 + dy[i];
            if (r < n && r >= 0 && c < m && c >= 0 && !v[r][c])
                dfs(b, r, c, v);
        }
    }
}

import java.util.LinkedList;
import java.util.Scanner;

public class C2 {
	Scanner sc = new Scanner(System.in);
	int[] dx = { 1, 0, 0, -1 };
	int[] dy = { 0, 1, -1, 0 };

	void run() {
		int n = sc.nextInt();
		int m = sc.nextInt();
		int[][] v = new int[n][m];
		char[][] f = new char[n][m];
		for (int i = 0; i < n; i++) {
			String in = sc.next();
			for (int j = 0; j < m; j++) {
				f[i][j] = in.charAt(j);
				v[i][j] = f[i][j] == '.' ? 2 : 1;
			}
		}
		int sh = sc.nextInt() - 1;
		int sw = sc.nextInt() - 1;
		int th = sc.nextInt() - 1;
		int tw = sc.nextInt() - 1;

		LinkedList<Pair> que = new LinkedList<Pair>();
		que.add(new Pair(sh, sw));
		v[sh][sw] = 2;
		while (!que.isEmpty()) {
			Pair p = que.poll();
			if (p.h == th && p.w == tw && v[th][tw] == 1) {
				System.out.println("YES");
				return;
			}
			if (v[p.h][p.w] == 1) {
				continue;
			}
			v[p.h][p.w]--;
			for (int i = 0; i < 4; i++) {
				int nh = p.h + dy[i];
				int nw = p.w + dx[i];
				if (inner(nh, nw, n, m)) {
					que.push(new Pair(nh, nw));
				}
			}
		}
		System.out.println("NO");
	}

	class Pair {

		int h;
		int w;

		public Pair(int h, int w) {
			super();
			this.h = h;
			this.w = w;
		}
	}

	public static void main(String[] args) {
		new C2().run();
	}

	boolean inner(int h, int w, int limH, int limW) {
		return 0 <= h && h < limH && 0 <= w && w < limW;
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class CF540C {
    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        PrintWriter pw = new PrintWriter(System.out);
        int n = sc.nextInt(), m = sc.nextInt();
        boolean[][] mat = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String[] line = sc.nextToken().split("");
            for (int j = 0; j < m; j++)
                mat[i][j] = line[j].equals(".");
        }
        int sourceRow = sc.nextInt() - 1, sourceCol = sc.nextInt() - 1;
        int destRow = sc.nextInt() - 1, destCol = sc.nextInt() - 1;
        pw.println(solve(mat, sourceRow, sourceCol, destRow, destCol) ? "YES" : "NO");
        pw.flush();
    }

    static boolean solve(boolean[][] mat, int sourceRow, int sourceCol, int destRow, int destCol) {
        mat[sourceRow][sourceCol] = true;
        int adjBlank = countAdjBlank(destRow, destCol, mat);
        return dfs(sourceRow, sourceCol, destRow, destCol, mat, new boolean[mat.length][mat[0].length])
                && (!mat[destRow][destCol] || adjBlank >= 2
                        || (sourceRow == destRow && sourceCol == destCol && adjBlank >= 1));
    }

    static int countAdjBlank(int i, int j, boolean[][] mat) {
        int l = j > 0 ? mat[i][j - 1] ? 1 : 0 : 0;
        int r = j < mat[i].length - 1 ? mat[i][j + 1] ? 1 : 0 : 0;
        int u = i > 0 ? mat[i - 1][j] ? 1 : 0 : 0;
        int d = i < mat.length - 1 ? mat[i + 1][j] ? 1 : 0 : 0;
        return l + r + u + d;
    }

    static boolean dfs(int i, int j, int destRow, int destCol, boolean[][] mat, boolean[][] visited) {
        if (i < 0 || i >= mat.length || j < 0 || j >= mat[i].length || visited[i][j])
            return false;
        visited[i][j] = true;
        if (i == destRow && j == destCol)
            return true;
        if (!mat[i][j])
            return false;
        return dfs(i - 1, j, destRow, destCol, mat, visited) || dfs(i + 1, j, destRow, destCol, mat, visited)
                || dfs(i, j - 1, destRow, destCol, mat, visited) || dfs(i, j + 1, destRow, destCol, mat, visited);
    }

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner() {
            this.in = new BufferedReader(new InputStreamReader(System.in));
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
