	int[][] marked=new int[n+2][m+2],graph=new int[n+2][m+2];
	for (int i=1;i<=n;i++) {
	    String row=in.next();
	    for (int j=1;j<=m;j++) {
		graph[i][j]=(row.charAt(j-1)=='.')?1:0;
	    }
	}
	Deque<Integer> st=new ArrayDeque<Integer>();
	st.addLast(in.nextInt());st.addLast(in.nextInt());
	int fx=in.nextInt(),fy=in.nextInt();
	while (st.size()>0) {
	    int y=st.pollLast(),x=st.pollLast();
	    if (marked[x][y]==0) {
		marked[x][y]++;
		if (graph[x-1][y]==1) {st.addLast(x-1);st.addLast(y);}
		if (graph[x+1][y]==1) {st.addLast(x+1);st.addLast(y);}
		if (graph[x][y-1]==1) {st.addLast(x);st.addLast(y-1);}
		if (graph[x][y+1]==1) {st.addLast(x);st.addLast(y+1);}
	    }
	}
