public class IceCave {

    static int N, M;
    static char[][] grid;
    static boolean[][] visited;
    static int r1, c1, r2, c2;

    static final int[] adjX = {-1, 1, 0, 0};
    static final int[] adjY = {0, 0, -1, 1};

    public static void floodfill(int r, int c) {
        if (!(r >= 0 && r < N && c >= 0 && c < M)) return;
        if ((grid[r][c] == 'X' || visited[r][c]) && !(r == r2 && c == c2)) return;

        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            floodfill(r + adjX[i], c + adjY[i]);
        }
    }

    public static int adjVisited(int r, int c) {
        int adj = 0;
        for (int i = 0; i < 4; i++) {
            try {
                if (visited[r + adjX[i]][c + adjY[i]]) {
                    adj++;
                }
            } catch (IndexOutOfBoundsException ignored) {
            }
        }
        return adj;
    }

    public static void main(String[] args) {
        N = io.nextInt();
        M = io.nextInt();

        grid = new char[N][M];
        for (int i = 0; i < N; i++) {
            String line = io.next();
            for (int j = 0; j < M; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        r1 = io.nextInt() - 1;
        c1 = io.nextInt() - 1;
        r2 = io.nextInt() - 1;
