        visited = new boolean[N][M];
        grid[r1][c1] = '.';
        floodfill(r1, c1);

        String ans = "NO";
        if (visited[r2][c2]) {
            if (r1 == r2 && c1 == c2) {
                int endAdj = adjVisited(r2, c2);

                if (endAdj >= 1) {
                    ans = "YES";
                }
            } else if (grid[r2][c2] == 'X') {
                ans = "YES";
            } else {
                int endAdj = adjVisited(r2, c2);

                if (endAdj >= 2) {
                    ans = "YES";
                }
            }
        }

        io.println(ans);
        io.close();
    }

