public class IceCave {

    int[] dx = {0, 0, -1, 1};
    int[] dy = {-1, 1, 0, 0};

    int n, m;
    int[][] A;
    int r1, c1, r2, c2;

    boolean[][] vis;

    void solve() {
        n = in.nextInt();
        m = in.nextInt();
        A = new int[n][m];
        for (int i = 0; i < n; i++) {
            String s = in.nextToken();
            for (int j = 0; j < m; j++) {
                if (s.charAt(j) == '.') A[i][j] = 1;
                else A[i][j] = 0;
            }
        }
        r1 = in.nextInt() - 1;
        c1 = in.nextInt() - 1;
        r2 = in.nextInt() - 1;
        c2 = in.nextInt() - 1;

        if (r1 == r2 && c1 == c2) {
            for (int i = 0; i < 4; i++) {
                int x = r2 + dx[i], y = c2 + dy[i];
                if (x >= 0 && x < n && y >= 0 && y < m && A[x][y] == 1) {
                    out.println("YES");
                    return;
                }
            }
            out.println("NO");
            return;
        }

        vis = new boolean[n][m];
        if (dfs(r1, c1)) {
            if (A[r2][c2] == 0) {
                out.println("YES");
                return;
            }
            int entry = 0;
            for (int i = 0; i < 4; i++) {
                int nx = r2 + dx[i], ny = c2 + dy[i];
                if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                    if (vis[nx][ny] || A[nx][ny] == 1) entry++;
                }
            }
            if (entry >= 2) {
                out.println("YES");
                return;
            }
        }
        out.println("NO");
    }

    boolean dfs(int x, int y) {
        A[x][y] = 0;
        vis[x][y] = true;
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                if (nx == r2 && ny == c2) {
                    return true;
                }
                if (A[nx][ny] > 0) {
                    if (dfs(nx, ny)) return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new IceCave().solve();
        out.close();
    }

