            q.push(y);
            while (!q.isEmpty()) {
                int cx = q.pollLast();
                int cy = q.pollLast();
                for (int k = 0; k < 4; ++k) {
                    int nx = cx + dx[k];
                    int ny = cy + dy[k];
                    if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
