    public boolean BFS(char[][] c, int r1, int c1, int r2, int c2){
        int[] dx = {1,-1,0,0};
        int[] dy = {0,0,1,-1};
        int n = c.length;
        int m = c[0].length;
        LinkedList<Integer> list = new LinkedList<>();
        list.add(r1*m + c1);

        while (!list.isEmpty()){
            int cur = list.poll();
            int row = cur/m;
            int col = cur%m;

            for (int i=0; i<4; i++){
                int x = row + dx[i];
                int y = col + dy[i];

                if (x==r2 && y==c2)
