		vis[x1][y1] = true;
		int[] dx = { 1, -1, 0, 0 };
		int[] dy = { 0, 0, 1, -1 };
		boolean canReach = false;
		while (!q.isEmpty()) {
			int fx = q.remove();
			int fy = q.remove();
			if (fx == x2 && fy == y2) {
				canReach = true;
			}
			for (int k = 0; k < 4; k++) {
				int nx = fx + dx[k];
				int ny = fy + dy[k];
				if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
					if (arr[nx][ny] == '.' && !vis[nx][ny]) {
						q.add(nx);
						q.add(ny);
						vis[nx][ny] = true;
					}
				}
			}
		}
		for (int i = 0; i < arr.length; i++) {
			for (int j = 0; j < arr[i].length; j++) {
				if (vis[i][j] && arr[i][j] == '.') {
					for (int k = 0; k < 4; k++) {
						int nx = i + dx[k];
						int ny = j + dy[k];
						if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
							if (nx == x2 && ny == y2 && arr[nx][ny] == 'X')
								canReach = true;
						}
					}
				}
			}
		}
		int cnt = 0;
		for (int k = 0; k < 4; k++) {
			int nx = x2 + dx[k];
			int ny = y2 + dy[k];
			if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
