public class a 
{
	public static void main(String[] arg)
	{
		new a();
	}
	public a()
	{

		Scanner in = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		int row = in.nextInt();
		int col = in.nextInt();
		char[][] grid = new char[row][col];
		for(int i = 0; i < row; i++) grid[i] = in.next().toCharArray();
		Pair source = new Pair(in.nextInt()-1, in.nextInt()-1);
		Pair sink = new Pair(in.nextInt()-1, in.nextInt()-1);
		int check = findIntact(grid, sink, row, col);
		boolean flag = false;
		if(source.equals(sink))
		{
			if(check >= 1) flag = true;
			else flag = false;
		}
		else if(source.adjacent(sink))
		{
			if(grid[sink.row][sink.col] == 'X') flag = true;
			else
			{
				if(check >= 2) flag = true;
				else if(check >= 1 && grid[source.row][source.col] == 'X') flag = true;
				else flag = false;
			}
		}
		else
		{
			if(findPath(source, sink, grid))
			{
				if(grid[sink.row][sink.col] == 'X') flag = true;
				else
				{
					if(check >= 2) flag = true;
					else flag = false;
				}
			}
			else flag = false;
		}
		System.out.println(flag ? "YES" : "NO");
		in.close();
		out.close();
	}
	public boolean findPath(Pair start, Pair end, char[][] grid)
	{
		ArrayDeque<Pair> q = new ArrayDeque<Pair>();
		q.add(start);
		boolean answer = false;
		int[] dx = {0 ,0, -1, 1};
		int[] dy = {-1, 1, 0, 0};
		while(q.size() > 0)
		{
			Pair temp = q.poll();
			if(!temp.isValid(grid)) continue;
			if(temp.equals(end)) return true;
			if(!temp.equals(start) && grid[temp.row][temp.col] == 'X') continue;
			grid[temp.row][temp.col] = 'X';
			for(int i = 0; i < 4; i++)
			{
				q.add(new Pair(temp.row+dx[i], temp.col+dy[i]));
			}
		}
		return answer;
	}
	public int findIntact(char[][] grid, Pair cur, int maxRow, int maxCol)
	{
		int answer = 0;
		int x = cur.row;
		int y = cur.col;
		if(x != 0)
			if(grid[x-1][y] == '.') answer++;

		if(x != maxRow-1)
			if(grid[x+1][y] == '.') answer++;

		if(y != 0)
			if(grid[x][y-1] == '.') answer++;

		if(y != maxCol-1)
			if(grid[x][y+1] == '.') answer++;

		return answer;
	}
	class Pair
	{
		public int row, col;
		public Pair(int a, int b)
		{
			row = a;
			col = b;
		}
		public boolean equals(Pair a)
		{
			return row == a.row && col == a.col;
		}
		public boolean adjacent(Pair a)
		{
			return Math.abs(row-a.row) + Math.abs(col-a.col) == 1;
		}
		public boolean isValid(char[][] grid)
		{
			if(row < 0 || row >= grid.length) return false;
			if(col < 0 || col >= grid[row].length) return false;
			return true;
		}
	}
	public class JoltyScanner 
	{
	    public static final int BUFFER_SIZE = 1 << 16;
		public static final char NULL_CHAR = (char) -1;

	    byte[] buffer = new byte[BUFFER_SIZE];
		boolean EOF_FLAG = false;
		int bufferIdx = 0, size = 0;
		char c = NULL_CHAR;
		BufferedInputStream in;

		public JoltyScanner(InputStream in) 
		{
			this.in = new BufferedInputStream(in, BUFFER_SIZE);
		}

		public int nextInt() 
		{
			long x = nextLong();
			if (x > Integer.MAX_VALUE || x < Integer.MIN_VALUE) 
			{
				throw new ArithmeticException("Scanned value overflows integer");
			}
			return (int) x;
		}

		public long nextLong() 
		{
			boolean negative = false;
			if (c == NULL_CHAR) 
			{
				c = nextChar();
			}
			for (; !EOF_FLAG && (c < '0' || c > '9'); c = nextChar()) 
			{
				if (c == '-') 
				{
					negative = true;
				}				
			}
			checkEOF();
			long res = 0;
			for (; c >= '0' && c <= '9'; c = nextChar()) 
			{
				res = (res << 3) + (res << 1) + c - '0';
			}
			return negative ? -res : res;
		}

	    public char nextChar() 
	    {
			if (EOF_FLAG) 
			{
				return NULL_CHAR;
			}
			while (bufferIdx == size) 
			{
				try 
				{
					size = in.read(buffer);
					if (size == -1) 
					{
						throw new Exception();
					}
				} 
				catch (Exception e) 
				{
					EOF_FLAG = true;
					return NULL_CHAR;
				}
				if (size == -1) 
				{
					size = BUFFER_SIZE;
				}
				bufferIdx = 0;
			}
			return (char) buffer[bufferIdx++];
		}

	    public void checkEOF() 
	    {
			if (EOF_FLAG) 
			{
				throw new EndOfFileException();
			}
		}

		public class EndOfFileException extends RuntimeException 
		{
		}
	}
}

import java.util.LinkedList;
import java.util.Scanner;

public class IceCave 
{
	static boolean[][] map;
	static boolean[][] mark;
	static int w, h, tx, ty, sx, sy;
	static boolean found = false;

	static int avail(int x, int y)
	{

		if(x < 0 || y < 0 || x >= w || y >= h || (map[x][y] && !(x == sx && y == sy)))
		{
			return 0;
		}
		else
		{
			return 1;
		}
	}

	static void traverse(int x, int y)
	{
		if(x < 0 || y < 0 || x >= w || y >= h)return;
		if(x == tx && y == ty)found = true;
		if(found)return;
		if(mark[x][y] || map[x][y])
		{

			return;			
		}

		mark[x][y] = true;
		traverse(x+1, y);
		traverse(x-1, y);
		traverse(x, y+1);
		traverse(x, y-1);



	}

	public static void main(String[] args) 
	{
		Scanner sc = new Scanner(System.in);

		h = sc.nextInt();
		w = sc.nextInt();
		map = new boolean[w][h];
		mark = new boolean[w][h];

		for(int y = 0; y < h; y++)
		{
			String in = sc.next();

			for(int x = 0; x < w; x++)
			{
				if(in.charAt(x) == 'X')
				{
					map[x][y] = true;
				}
			}
		}



		sy = sc.nextInt()-1;
		sx = sc.nextInt()-1;
		ty = sc.nextInt()-1;
		tx = sc.nextInt()-1;

		int adj = avail(tx+1, ty) + avail(tx-1, ty) + avail(tx, ty+1) + avail(tx, ty-1);

		if(adj <= 1 && !map[tx][ty])
		{

			System.out.println("NO");
			return;
		}
		else
		{
			LinkedList<Integer> vx = new LinkedList<Integer>();
			LinkedList<Integer> vy = new LinkedList<Integer>();

			vx.push(sx+1);
			vy.push(sy);
			vx.push(sx-1);
			vy.push(sy);
			vx.push(sx);
			vy.push(sy+1);
			vx.push(sx);
			vy.push(sy-1);



			while(!vx.isEmpty() && !found)
			{
				int x = vx.poll();
				int y = vy.poll();

				if(x == tx && y == ty)
				{
					found = true;

				}
				else if(x >= 0 && y >= 0 && x < w && y < h && !mark[x][y] && !map[x][y])
				{


					vx.push(x+1);
					vy.push(y);
					vx.push(x-1);
					vy.push(y);
					vx.push(x);
					vy.push(y+1);
					vx.push(x);
					vy.push(y-1);					

					mark[x][y] = true;				
				}

			}



			if(found)
			{
				System.out.println("YES");
			}
			else
			{

				System.out.println("NO");
			}
			return;
		}
	}
}

