                        way[i-1][j] = k+1;
                        is.add(i-1);
                        js.add(j);
                    }
                    if ((i != n-1) && ((field[i+1][j] == '.') && (way[i+1][j] > k+1)) || ((i+1 == i1) && (j == j1))) {
