public class C {

    int[] di = {-1, 1, 0, 0};
    int[] dj = {0, 0, -1, 1};

    void solve() throws IOException {
        in = new InputReader("__std");
        out = new OutputWriter("__std");

        int n = in.readInt();
        int m = in.readInt();
        char[][] b = new char[n][];
        for (int i = 0; i < n; ++i) {
            b[i] = in.readToken().toCharArray();
        }
        int r1 = in.readInt() - 1;
        int c1 = in.readInt() - 1;
        int r2 = in.readInt() - 1;
        int c2 = in.readInt() - 1;

        boolean flag = true;

        if (b[r2][c2] == '.') {
            int cnt = 0;
            for (int k = 0; k < 4; ++k) {
                int ii = r2 + di[k];
                int jj = c2 + dj[k];
                if (ii >= 0 && ii < n && jj >= 0 && jj < m && b[ii][jj] == '.') ++cnt;
            }
            flag = (cnt > 1) || (cnt == 1 && Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1);
        }

        if (flag) {
            boolean[][] mask = new boolean[n][m];
            Queue<Integer> qi = new LinkedList<>();
            Queue<Integer> qj = new LinkedList<>();
            qi.add(r1);
            qj.add(c1);
            while (!qi.isEmpty()) {
                int i = qi.poll();
                int j = qj.poll();
                for (int k = 0; k < 4; ++k) {
                    int ii = i + di[k];
                    int jj = j + dj[k];
                    if (ii >= 0 && ii < n && jj >= 0 && jj < m && !mask[ii][jj]) {
                        mask[ii][jj] = true;
                        if (b[ii][jj] == '.') {
                            qi.add(ii);
                            qj.add(jj);
                        }
                    }
                }
            }
            flag = mask[r2][c2];
