public class Solution2 {
    private static int row;
    private static int column;
    private static int r2;
    private static int c2;
    private static int[][] grid;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        row = in.nextInt();
        column = in.nextInt();
        String[] rowStrings = new String[row];
        for (int i = 0; i < row; i++) {
            rowStrings[i] = in.next();
        }
        int r1 = in.nextInt();
        int c1 = in.nextInt();
        r2 = in.nextInt();
        c2 = in.nextInt();
        grid = new int[row + 1][column + 1];
        for (int i = 1; i <= row; i++) {
            for (int j = 1; j <= column; j++) {
                grid[i][j] = (rowStrings[i - 1].charAt(j - 1) == '.') ? 1 : 0;
            }
        }
        List<Integer> filledCells = new LinkedList<>();
        filledCells.add(convert(r1, c1));
        int target = convert(r2, c2);
        boolean reached = false;
        if (firstCheck(r1, c1)) {
            int index = 0;
            reached = (r1 == r2 && c1 == c2);
            while (!reached && index < filledCells.size()) {

                int n = filledCells.get(index);
                int r = row(n);
                int c = column(n);

                if ((r - 1 == r2 && c == c2) || (r == r2 && c + 1 == c2) || (r + 1 == r2 && c == c2) || (r == r2 && c - 1 == c2)) {
                    reached = true;
                } else {

                    if (r - 1 >= 1 && grid[r - 1][c] == 1) {
                        filledCells.add(convert(r - 1, c));
                        grid[r - 1][c] = 'X';

                    }
                    if (c + 1 <= column && grid[r][c + 1] == 1) {
                        filledCells.add(convert(r, c + 1));
                        grid[r][c + 1] = 'X';
                    }
                    if (r + 1 <= row && grid[r + 1][c] == 1) {
                        filledCells.add(convert(r + 1, c));
                        grid[r + 1][c] = 'X';
                    }
                    if (c - 1 >= 1 && grid[r][c - 1] == 1) {
                        filledCells.add(convert(r, c - 1));
                        grid[r][c - 1] = 'X';
                    }
                }


                index++;
            }
        }











        System.out.println(reached ? "YES" : "NO");
    }

    public static int convert(int r, int c) {
        return (r - 1) * column + c;
    }

    public static int column(int n) {
        int result = n % column;
        if (result == 0) {
            return column;
        } else {
            return result;
        }
    }

    public static int row(int n) {
        if (n % column == 0) {
            return n / column;
        } else {
            return (n / column) + 1;
        }
    }

    public static boolean firstCheck(int r, int c) {
        boolean sideBySide = (r + 1 == r2 && c == c2) || (r - 1 == r2 && c == c2) || (r == r2 && c + 1 == c2) || (r == r2 && c - 1 == c2);
        int reqGate;
        if (sideBySide) {
            if (grid[r2][c2] == 0) {
                reqGate = 0;
            } else {
                reqGate = 1;
            }


        } else if (r == r2 && c == c2) {
            reqGate = 1;
        } else {
            if (grid[r2][c2] == 0) {
                reqGate = 1;
            } else {
                reqGate = 2;
            }
        }


        int gate = 0;
        gate += (r2 - 1 >= 1 && grid[r2 - 1][c2] == 1) ? 1 : 0;
        gate += (c2 - 1 >= 1 && grid[r2][c2 - 1] == 1) ? 1 : 0;
        gate += (r2 + 1 <= row && grid[r2 + 1][c2] == 1) ? 1 : 0;
        gate += (c2 + 1 <= column && grid[r2][c2 + 1] == 1) ? 1 : 0;

        return gate >= reqGate;
    }

}

