public class Solution {

    public static int solidNeighbours(char[][] map, int r1, int c1) {
        int res = 0;
        for (int i = -1; i < 2; i++)
            if (i != 0) {
                if (r1 + i >= 0 && r1 + i < map.length && map[r1 + i][c1] != 'X') res++;
                if (c1 + i >= 0 && c1 + i < map[0].length && map[r1][c1 + i] != 'X') res++;
            }
        return res;
    }

    public static boolean solve(char[][] map, int r1, int c1, int r2, int c2) {
        if (r1 == r2 && c1 == c2 && solidNeighbours(map, r1, c1) > 0) return true;
        if (Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1 && map[r2][c2] == 'X') return true;
        if (Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1 && solidNeighbours(map, r2, c2) > 0) return true;
        if (!path(map, r1, c1, r2, c2)) return false;
        if (map[r2][c2] == 'X' && solidNeighbours(map, r2, c2) > 0) return true;
        if (solidNeighbours(map, r2, c2) > 1) return true;
        return false;
    }

    public static boolean path(char[][] map, int r1, int c1, int r2, int c2) {
        if (Math.abs(r1 - r2) +  Math.abs(c1 - c2) == 1)
            return true;

        Stack<Integer> stack = new Stack<>();
        Set<Integer> visited = new HashSet<>();
        stack.add(c1 + r1 * map[0].length);
        while (!stack.isEmpty()) {
            int v = stack.pop();
            if (visited.contains(v)) continue;
            int r = v / map[0].length;
            int c = v % map[0].length;
            if (r == r2 && c == c2) return true;
            for (int i = -1; i < 2; i++)
                if (i != 0) {
                    if (r + i >= 0 && r + i < map.length) {
                        if (r + i == r2 && c == c2) return true;
                        if (map[r + i][c] != 'X')
                            stack.push((r + i) * map[0].length + c);
                    }
                    if (c + i >= 0 && c + i < map[0].length) {
                        if (r == r2 && c + i == c2) return true;
                        if (map[r][c + i] != 'X')
                            stack.push(r * map[0].length + c + i);
                    }
                }
            visited.add(v);
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int m = in.nextInt();
        in.nextLine();
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++)
            map[i] = in.nextLine().toCharArray();

        int r1 = in.nextInt() - 1;
        int c1 = in.nextInt() - 1;
        int r2 = in.nextInt() - 1;
        int c2 = in.nextInt() - 1;

        if (solve(map, r1, c1, r2, c2)) System.out.println("YES");
        else System.out.println("NO");
    }
}

