    private static boolean[][] marked;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        N = in.nextInt();
        M = in.nextInt();

        board = new char[N][M];
        for (int i = 0; i < N; i++) {
            board[i] = in.next().toCharArray();        }
        int r1 = in.nextInt() - 1;
        int c1 = in.nextInt() - 1;

        int r2 = in.nextInt() - 1;
        int c2 = in.nextInt() - 1;

        marked = new boolean[N][M];

        char c = board[r2][c2];
        board[r1][c1] = '.';
        board[r2][c2] = '.';

        int count = 0;
        int[] dr = new int[]{0, 1, 0, -1};
        int[] dc = new int[]{1, 0, -1, 0};
        for (int i = 0; i < 4; i++) {
            if (r2 + dr[i] >= 0 && r2 + dr[i] < N &&
                c2 + dc[i] >= 0 && c2 + dc[i] < M &&
                board[r2 + dr[i]][c2 + dc[i]] == '.') {

                count++;
            }
        }

        if (r1 == r2 && c1 == c2) {
            if (count >= 1) {
                System.out.println("YES");
            }
            else {
                System.out.println("NO");
            }
        }
        else {
            dfs(r1, c1);

            if (marked[r2][c2]) {
                if (count <= 1) {
                    if (c == 'X') {
                        System.out.println("YES");
                    }
                    else {
                        System.out.println("NO");
                    }
                }
                else {
                    System.out.println("YES");
                }
            }
            else {
                System.out.println("NO");
            }
        }
    }

    private static void dfs(int r, int c) {
        marked[r][c] = true;

        int[] dr = new int[]{0, 1, 0, -1};
        int[] dc = new int[]{1, 0, -1, 0};

        for (int i = 0; i < 4; i++) {
            if (r + dr[i] >= 0 && r + dr[i] < N &&
                c + dc[i] >= 0 && c + dc[i] < M &&
                board[r + dr[i]][c + dc[i]] == '.' &&
                !marked[r + dr[i]][c + dc[i]]) {

                dfs(r + dr[i], c + dc[i]);
            }
        }
    }

}

import java.util.ArrayList;
import java.util.Scanner;
import java.util.concurrent.ArrayBlockingQueue;

public class Main{
	static boolean[] reach;
	public static void main(String[] args) throws InterruptedException {
		try (Scanner scan = new Scanner(System.in)) {

			int r=scan.nextInt(),c=scan.nextInt(); scan.nextLine();
			int xStart, yStart, xEnd, yEnd;

			if (r*c==1){
				System.out.println("NO");
				return;
			}

			char[][] map = new char[c][r];
			reach = new boolean[c*r];
			ArrayList<Integer>[] g =(ArrayList<Integer>[]) new ArrayList[c*r];


			for (int i = 0; i < r; i++) {
				String line = scan.nextLine();
				for (int j = 0; j < c; j++) {
					map[j][i] = line.charAt(j);
				}
			}
			yStart = scan.nextInt()-1; xStart=scan.nextInt()-1; yEnd = scan.nextInt()-1; xEnd = scan.nextInt()-1;
			int start = yStart*c+xStart;
			int end = yEnd*c+xEnd;


			for (int i = 0; i < r; i++) {
				for (int j = 0; j < c; j++) {
					g[i*c+j] = new ArrayList<Integer>();
					if (i-1>=0)
						g[i*c+j].add((i-1)*c+j);
					if (i+1<r)
						g[i*c+j].add((i+1)*c+j);
					if (j-1>=0)
						g[i*c+j].add((i)*c+(j-1));
					if (j+1<c)
						g[i*c+j].add((i)*c+(j+1));
				}
			}

			ArrayBlockingQueue<Integer> frontier = new ArrayBlockingQueue<Integer>(c*r);
			boolean state =false;
			frontier.add(start);
			if (map[xEnd][yEnd]=='.' && numIntact(yEnd, xEnd,map,c,r, start)<2) { System.out.println("NO"); return;}



			int count = 0;
			while(!frontier.isEmpty()){
				int val = frontier.take();
				if (val==end){
					if (end==start&&count==0)count++;
					else{ state=true;break;}
				}
				if ((val==start || map[val%c][val/c]!='X') && !reach[val]){
					if (start==end && val==start)reach[val] = false;
					else reach[val]=true;
					for (int i : g[val])
						frontier.add(i);
				}
			}

			if (state) System.out.println("YES");
			else System.out.println("NO");


		}
	}

	private static int numIntact(int i,int j,char[][] map, int c, int r, int start) {
		int count = 0;
		if (i-1>=0 && (map[j][i-1]=='.' || (i-1)*c+j==start))count++;

		if (i+1<r && (map[j][i+1]=='.' || (i+1)*c+j==start))count++;

		if (j-1>=0 && (map[j-1][i]=='.' || (i)*c+j-1==start))count++;

		if (j+1<c && (map[j+1][i]=='.' || (i)*c+j+1==start))count++;

		return count;
	}


}

