        str[i] = inp.nextLine();
    }

    Graph g = new Graph(n, m, str);

    int xc = inp.nextInt();
    int yc = inp.nextInt();
    int xr = inp.nextInt();
    int yr = inp.nextInt();

    xc--;
    yc--;
    xr--;
    yr--;

    if (g.check(xc + 1, yc, xr, yr) || g.check(xc - 1, yc, xr, yr)
        || g.check(xc, yc + 1, xr, yr) || g.check(xc, yc - 1, xr, yr))
        System.out.println("YES");
    else
        System.out.println("NO");

    }

}

class Graph {
    int visited[][];
    int graph[][];
    int n, m;

    Graph(int n, int m, String str[]) {
    this.n = n;
    this.m = m;
    visited = new int[n][m];
    graph = new int[n][m];

    for (int i = 0; i < str.length; i++) {
        for (int j = 0; j < str[i].length(); j++) {
        if (str[i].charAt(j) == 'X') {
            graph[i][j] = 0;
        } else {
            graph[i][j] = 1;
        }
        visited[i][j] = 0;
        }
    }
    }

    public boolean check(int xc, int yc, int xr, int yr) {

    if ((xc == xr) && (yc == yr) && (graph[xc][yc] == 0))
        return true;

    if ((xc >= n) || (yc >= m) || (xc < 0) ||(yc < 0 ) || (visited[xc][yc] >= 2)
        || (graph[xc][yc] == 0))
        return false;


    visited[xc][yc]++;

    if (graph[xc][yc] == 1)
        graph[xc][yc] = 0;

    if (check(xc + 1, yc, xr, yr) || check(xc - 1, yc, xr, yr)
        || check(xc, yc + 1, xr, yr) || check(xc, yc - 1, xr, yr))
        return true;

    return false;
    }
}

