    static class CIceCave {
        static char[][] grid;
        static boolean[][] visited;
        static int n;
        static int m;
        static int x1;
        static int y1;
        static int x2;
        static int y2;

        static void dfs(int x, int y, int xpar, int ypar) {
            if (x == x2 && y == y2) {
                if (grid[x][y] == '.') {
                    grid[x][y] = 'X';
                    visited[x][y] = false;
                    if (x < n - 1 && !visited[x + 1][y]) {
                        dfs(x + 1, y, x, y);
                    }
                    if (y < m - 1 && !visited[x][y + 1]) {
                        dfs(x, y + 1, x, y);
                    }
                    if (x > 0 && !visited[x - 1][y]) {
                        dfs(x - 1, y, x, y);
                    }
                    if (y > 0 && !visited[x][y - 1]) {
                        dfs(x, y - 1, x, y);
                    }
                    return;
                } else {
                    if (xpar != -1 && ypar != -1) {
                        visited[x][y] = true;
                        return;
                    } else {
                        if (x < n - 1 && !visited[x + 1][y]) {
                            dfs(x + 1, y, x, y);
                        }
                        if (y < m - 1 && !visited[x][y + 1]) {
                            dfs(x, y + 1, x, y);
                        }
                        if (x > 0 && !visited[x - 1][y]) {
                            dfs(x - 1, y, x, y);
                        }
                        if (y > 0 && !visited[x][y - 1]) {
                            dfs(x, y - 1, x, y);
                        }
                        return;
                    }
                }
            }
            visited[x][y] = true;
            if (grid[x][y] == 'X' && (x != x1 || y != y1)) {
                return;
            }
            if (x < n - 1 && !visited[x + 1][y]) {
                dfs(x + 1, y, x, y);
            }
            if (y < m - 1 && !visited[x][y + 1]) {
                dfs(x, y + 1, x, y);
            }
            if (x > 0 && !visited[x - 1][y]) {
                dfs(x - 1, y, x, y);
            }
            if (y > 0 && !visited[x][y - 1]) {
                dfs(x, y - 1, x, y);
            }
        }

        public void solve(int testNumber, inputClass sc, PrintWriter out) {
            n = sc.nextInt();
            m = sc.nextInt();
            grid = new char[n][m];
            visited = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.nextLine().toCharArray();
            }
            x1 = sc.nextInt() - 1;
            y1 = sc.nextInt() - 1;
            x2 = sc.nextInt() - 1;
            y2 = sc.nextInt() - 1;
            dfs(x1, y1, -1, -1);
            if (visited[x2][y2])
                out.println("YES");
            else
                out.println("NO");
        }

    }

    static class inputClass {
        BufferedReader br;
        StringTokenizer st;

        public inputClass(InputStream in) {

            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
