    static class TaskC {
        static int n;
        static int m;
        static boolean[][] cracked;
        static int[] dx = {0, 0, 1, -1};
        static int[] dy = {1, -1, 0, 0};
        static int rS;
        static int cS;
        static int rE;
        static int cE;
        static boolean[][] visited;

        static boolean valid(int row, int col) {
            return row >= 0 && col >= 0 && row < n && col < m;
        }

        static void flood_fill(int row, int col) {
            visited[row][col] = true;
            for (int k = 0; k < 4; k++) {
                int nxtRow = row + dx[k], nxtCol = col + dy[k];
                if (valid(nxtRow, nxtCol) && !visited[nxtRow][nxtCol] && (!cracked[nxtRow][nxtCol] || (nxtRow == rE && nxtCol == cE))) {
                    if (cracked[nxtRow][nxtCol]) visited[nxtRow][nxtCol] = true;
                    else flood_fill(nxtRow, nxtCol);
                }
            }
        }

        public void solve(int testNumber, Scanner sc, PrintWriter out) {
            n = sc.nextInt();
            m = sc.nextInt();
            visited = new boolean[n][m];
            char[][] tmp = new char[n][m];
            cracked = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                tmp[i] = sc.next().toCharArray();
                for (int j = 0; j < m; j++)
                    cracked[i][j] = tmp[i][j] == 'X';
            }

            rS = sc.nextInt() - 1;
            cS = sc.nextInt() - 1;
            rE = sc.nextInt() - 1;
            cE = sc.nextInt() - 1;
            if (rS == rE && cS == cE) {
                for (int k = 0; k < 4; k++) {
                    int nxtR = rS + dx[k], nxtC = cS + dy[k];
                    if (valid(nxtR, nxtC) && !cracked[nxtR][nxtC]) {
                        out.println("YES");
                        return;
                    }
                }
                out.println("NO");
                return;
            }

            flood_fill(rS, cS);

            if (cracked[rE][cE]) {
                if (visited[rE][cE]) out.println("YES");
                else out.println("NO");
                return;
            }

            int cntNxt = 0;
            boolean foundOne = false;
            for (int k = 0; k < 4; k++) {
                int nxtRow = rE + dx[k], nxtCol = cE + dy[k];
                if (valid(nxtRow, nxtCol) && visited[nxtRow][nxtCol]) foundOne = true;
                if (valid(nxtRow, nxtCol) && (nxtRow == rS && nxtCol == cS || !cracked[nxtRow][nxtCol])) cntNxt++;
            }
            if (cntNxt >= 2 && foundOne) out.println("YES");
            else out.println("NO");
        }

    }

