import java.util.Scanner;
import java.util.Stack;

public class C {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		int m = in.nextInt();
		boolean[][] visited = new boolean[n][m];
		String[] g = new String[n];
		for (int i = 0; i < n; ++i) {
			g[i] = in.next();
		}
		int startX = in.nextInt() - 1;
		int startY = in.nextInt() - 1;
		int endX = in.nextInt() - 1;
		int endY = in.nextInt() - 1;

		Stack<Integer> stack = new Stack<Integer>();
		stack.add(startX);
		stack.add(startY);

		int[][] delta = new int[][] { { 0, 1 }, { 0, -1 }, { 1, 0 }, { -1, 0 } };


		while (!stack.isEmpty()) {
			int y = stack.pop();
			int x = stack.pop();	

			if (x == endX && y == endY&&visited[x][y]) {				
				System.out.println("YES");
				return;				
			}

			visited[x][y] = true;
			for (int[] d : delta) {
				int nx = x + d[0];
				int ny = y + d[1];
				if (nx == endX && ny == endY) {
					if(visited[nx][ny]||g[nx].charAt(ny) == 'X'){
						System.out.println("YES");
						return;
					}else{						
						stack.push(nx);
						stack.push(ny);
						continue;
					}
				}

				if (nx >= 0 && ny >= 0 && nx < n && ny < m && g[nx].charAt(ny)=='.' &&  !visited[nx][ny]) {
					stack.push(nx);
					stack.push(ny);
				}
			}
		}
		System.out.println("NO");
	}

}

