public class Main {
	static BufferedReader in;
	static PrintWriter out;

	static char[][] cave;
	static int n,m, sx, sy, ex, ey;
	static int[] dx = {1,-1,0,0};
	static int[] dy = {0,0,1,-1};
	static String ans;

	static class Point {
		int x,y;
		public Point(int x, int y) {
			this.x = x;
			this.y = y;
		}

		@Override
		public String toString() {
			return "["+x+","+y+"]";
		}
	}

	public static boolean isValid(int x, int y) {
		return (x>=0 && x<n && y>=0 && y<m);
	}

	public static boolean isValidDot(int x, int y) {
		return (isValid(x,y) && cave[x][y]=='.');
	}

	public static boolean isValidDotX(int x, int y) {
		return (isValid(x,y) && (cave[x][y]=='.' || (x==ex && y==ey && cave[x][y]=='X')));
	}

	public static void main(String[] args) throws IOException {
		in = new BufferedReader(new InputStreamReader(System.in));
		out = new PrintWriter(System.out);

		String[] tok = rst();
		n = Integer.parseInt(tok[0]);
		m = Integer.parseInt(tok[1]);

		cave = new char[n][];
		for (int i=0;i<n;i++) {
			cave[i] = in.readLine().toCharArray();
		}

		tok = rst();
		sx = Integer.parseInt(tok[0])-1;
		sy = Integer.parseInt(tok[1])-1;

		tok = rst();
		ex = Integer.parseInt(tok[0])-1;
		ey = Integer.parseInt(tok[1])-1;

		boolean poss = false;
		if (sx==ex && sy==ey) {
			for (int i=0;i<4;i++) {
				if (isValidDot(sx+dx[i],sy+dy[i])) {
					poss=true;
					break;
				}
			}
		} else if ((sx==ex && Math.abs(sy-ey)==1) || (sy==ey && Math.abs(sx-ex)==1)) {
			if (cave[ex][ey]=='X') {
				poss=true;
			} else {
				for (int i=0;i<4;i++) {
					if (isValidDot(ex+dx[i],ey+dy[i])) {
						poss=true;
						break;
					}
				}
			}
		} else {
			List<Point> vis = new ArrayList<Point>();
			boolean[][] used = new boolean[n][m];
			vis.add(new Point (sx,sy));
			used[sx][sy] = true;
			int pos = 0;
			while (pos<vis.size()) {
				Point p = vis.get(pos);
				if (p.x==ex && p.y==ey) {
					poss=true;
					break;
				} else {
					for (int i=0;i<4;i++) {
						if (isValidDotX(p.x+dx[i],p.y+dy[i]) && !used[p.x+dx[i]][p.y+dy[i]]) {
							vis.add(new Point(p.x+dx[i], p.y+dy[i]));
							used[p.x+dx[i]][p.y+dy[i]] = true;
						}
					}
				}
				pos++;
			}

			if (poss) {
				if (cave[ex][ey]=='.') {
					int numDots = 0;
					for (int i=0;i<4;i++) {
						if (isValidDot(ex+dx[i],ey+dy[i])) {
							numDots++;
						}
					}
					if (numDots<2) poss=false;
				}
			}
		}

		out.println(poss?"YES":"NO");

		in.close();
		out.close();
	}

