    private void solve() throws IOException {
        int n = io.nI(), m = io.nI();

        boolean[][] solid = new boolean[n][m];
        io.wc(".X");
        for (int i = 0; i < n; i++) {
            char[] s = io.nS().toCharArray();
            for (int j = 0; j < m; j++) {
                solid[i][j] = s[j] == '.';
            }
        }

        int sx = io.nI() - 1, sy = io.nI() - 1;
        int fx = io.nI() - 1, fy = io.nI() - 1;

        if (sx == fx && sy == fy) {
            for (int i = 0; i < 4; i++) {
                int nx = sx + dx[i];
                int ny = sy + dy[i];

                if (0 <= nx && nx < n && 0 <= ny && ny < m && solid[nx][ny]) {
                    io.wln("YES");
                    return;
                }
            }
            io.wln("NO");
            return;
        }

        boolean[][] used = new boolean[n][m];
        used[sx][sy] = true;
        ArrayDeque<Integer> adx = new ArrayDeque<>();
        adx.add(sx);
        ArrayDeque<Integer> ady = new ArrayDeque<>();
        ady.add(sy);

        boolean hey = false;

        while (!adx.isEmpty()) {
            int cx = adx.pollFirst();
            int cy = ady.pollFirst();

            if (cx == fx && cy == fy) {
                hey = true;
                break;
            }

            for (int i = 0; i < 4; i++) {
                int nx = cx + dx[i];
                int ny = cy + dy[i];

                if (0 <= nx && nx < n && 0 <= ny && ny < m && !used[nx][ny] && (solid[nx][ny] || nx == fx && ny == fy)) {
                    adx.addLast(nx);
                    ady.addLast(ny);
                    used[nx][ny] = true;
                }
            }
        }

        if (!hey) {
            io.wln("NO");
            return;
        }
        if (!solid[fx][fy]) {
            io.wln("YES");
            return;
        }
        int k = 0;
        for (int i = 0; i < 4; i++) {
            int nx = fx + dx[i];
            int ny = fy + dy[i];

            if (0 <= nx && nx < n && 0 <= ny && ny < m && solid[nx][ny] || sx == nx && sy == ny)
                k++;
        }

        if (k <= 1)
            io.wln("NO");
        else
            io.wln("YES");
    }

    public static void main(String[] args) throws IOException {
        IO.launchSolution(args);
    }

    Solution(IO io) throws IOException {
        this.io = io;
        solve();
    }

    private final IO io;
}

