public class Task540C {

    static char[][] cave;
    static boolean[][] visited;
    static int r1, c1, r2, c2;
    static int n, m;
    static boolean isPath = false;

    public static void main(String[] args) throws IOException {
        InputScanner is = new InputScanner();
        n = is.nextInt();
        m = is.nextInt();

        cave = new char[n][];
        visited = new boolean[n][m];
        for (int i = 0; i < n; i++) cave[i] = is.next().toCharArray();
        r1 = is.nextInt() - 1;
        c1 = is.nextInt() - 1;
        r2 = is.nextInt() - 1;
        c2 = is.nextInt() - 1;
        cave[r1][c1] = '.';
        dfs(r2, c2);

        if (c1 == c2 && r1 == r2 && getGoodNeighbors(r1, c1) > 0) {
            System.out.println("YES");
            return;
        }
        if (isPath) {
            if (cave[r2][c2] == 'X') {
                System.out.println("YES");
                return;
            } else {
                if (getGoodNeighbors(r2, c2) > 1) {
                    System.out.println("YES");
                    return;
                }
            }
        }

        System.out.println("NO");
    }

    static int getGoodNeighbors(int r, int c) {
        int result = 0;
        if (r + 1 < n && cave[r + 1][c] == '.') result++;
        if (r - 1 >= 0 && cave[r - 1][c] == '.') result++;
        if (c + 1 < m && cave[r][c + 1] == '.') result++;
        if (c - 1 >= 0 && cave[r][c - 1] == '.') result++;
        return result;
    }

    static void dfs(int r, int c) {
        if (r == r1 && c == c1) isPath = true;
        visited[r][c] = true;
        if (r + 1 < n) {
            if (!visited[r + 1][c] && cave[r + 1][c] == '.') dfs(r + 1, c);
        }
        if (r - 1 >= 0) {
            if (!visited[r - 1][c] && cave[r - 1][c] == '.') dfs(r - 1, c);
        }
        if (c + 1 < m) {
            if (!visited[r][c + 1] && cave[r][c + 1] == '.') dfs(r, c + 1);
        }
        if (c - 1 >= 0) {
            if (!visited[r][c - 1] && cave[r][c - 1] == '.') dfs(r, c - 1);
        }
    }

    static class InputScanner {
        BufferedReader br;
        StringTokenizer st;

        public InputScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            if (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String next = next();
            return Integer.parseInt(next);
        }

        public long nextLong() throws IOException {
            String next = next();
            return Long.parseLong(next);
        }
    }
}

