        arr[x1][y1] = '.';
        int cnt = 0;
        if(x2 > 0 && arr[x2-1][y2] == '.')
            cnt++;
        if(x2 < arr.length - 1 && arr[x2+1][y2] == '.')
            cnt++;
        if(y2 > 0 && arr[x2][y2-1] == '.')
            cnt++;
        if(y2 < arr[0].length - 1 && arr[x2][y2+1] == '.')
            cnt++;

        if(x1 == x2 && y1 == y2 && cnt >= 1) {
            out.println("YES");
            return;
