public class Main {

    static int n,m;
    static char [][] g;
    static int [][] v;
    static int [] dx = {0,0,-1,1},dy = {-1,1,0,0};

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));

        StringBuilder out = new StringBuilder();
        StringTokenizer tk;

        tk = new StringTokenizer(in.readLine());
        n = parseInt(tk.nextToken());
        m = parseInt(tk.nextToken());

        g = new char[n][m];
        for(int i=0; i<n; i++)
            g[i] = in.readLine().toCharArray();

        v = new int[n][m];

        tk = new StringTokenizer(in.readLine());
        int x1 = parseInt(tk.nextToken())-1,y1 = parseInt(tk.nextToken())-1;
        tk = new StringTokenizer(in.readLine());
        int x2 = parseInt(tk.nextToken())-1,y2 = parseInt(tk.nextToken())-1;

        System.out.println(BFS(x1,y1,x2,y2) ? "YES" : "NO");
    }

    static boolean BFS(int x1,int y1,int x2,int y2) {
        Queue<point> q = new LinkedList<point>();
        point p = new point(x1,y1);
        q.add(p);
        v[x1][y1] = 1;

        while(!q.isEmpty()) {
            p = q.remove();

            if(p.x==x2 && p.y==y2 && (v[x2][y2]>=2 || (v[x2][y2]==1 && g[x2][y2]=='X' && !(x1==x2 && y1==y2))))
                return true;

            for(int i=0; i<4; i++) {
                int nx = p.x+dx[i];
                int ny = p.y+dy[i];

                if(nx<0 || nx>=n || ny<0 || ny>=m) continue;


                if(nx==x2 && ny==y2) {
                    v[nx][ny]++;
                    q.add(new point(nx,ny));
                } else if(v[nx][ny]==0 && g[nx][ny]!='X'){
                    v[nx][ny] = 1;
                    q.add(new point(nx,ny));
                }
            }
        }

        return false;
    }
}

