public class IceCave {
	private static int n, m;
	private static char[][] matrix;
	private static int[][] move = {{1,0}, {0,-1}, {-1,0}, {0,1}}; 

	public static class Point {
		public int x;
		public int y;
	}

	private static Point sp, ep;

	private static void getMatrix(Scanner scan){
		matrix = new char[n][];
		for (int i = 0; i < n; i++){
			matrix[i] = new char[m];
			String line = scan.next();
			for (int j = 0; j < m; j++){
				matrix[i][j] = line.charAt(j);
			}
		}
	}

	private static Boolean inRange(int x, int y){
		if (x < 0 || x >= n || y < 0 || y >= m)
			return false;
		return true;
	}

	private static String bfsAnswer(){
		int neighborDot = 0;
		for (int i = 0; i < 4; i++){
			if (inRange(ep.x + move[i][0], ep.y + move[i][1]) && matrix[ep.x + move[i][0]][ep.y + move[i][1]]=='.')
				neighborDot++;
		}


		Queue<Point> queue = new LinkedList<Point>();
		queue.add(sp);
		while (!queue.isEmpty()){
			Point head = queue.element();
			queue.remove();
			for (int i = 0; i < 4; i++){
				Point tail = new Point();
				tail.x = head.x + move[i][0];
				tail.y = head.y + move[i][1]; 

				if (inRange(tail.x, tail.y)) {
					if (tail.x == ep.x && tail.y == ep.y){
						if (matrix[tail.x][tail.y] == 'X')
							return "YES";
						else {
							matrix[tail.x][tail.y] = 'X';
							queue.add(tail);
						}
					}  
					else if (matrix[tail.x][tail.y] == '.'){
						matrix[tail.x][tail.y] = 'X';
						queue.add(tail);
					}
				}

			}
		}
		return "NO";
	};

	public static void main(String args[]){
		Scanner scan = new Scanner(System.in);
		n = scan.nextInt();
		m = scan.nextInt();
		getMatrix(scan);
		sp = new Point();
		sp.x = scan.nextInt() - 1;
		sp.y = scan.nextInt() - 1;
		ep = new Point();
		ep.x = scan.nextInt() - 1;
		ep.y = scan.nextInt() - 1;
		System.out.println(bfsAnswer());
	}
}

