    public static boolean dfs(int x, int y)
    {
    	visited[x][y] = true;
    	if(x ==  r && y == c)
    	{
    		return true;
    	}

    	if(isValid(x + 1, y))
    	{
    		boolean res = dfs(x + 1, y);
    		if (res) return res;
    	}

    	if(isValid(x, y + 1))
    	{
    		boolean res = dfs(x, y + 1);
    		if (res) return res;
    	} 

    	if(isValid(x - 1, y))
    	{
    		boolean res = dfs(x - 1, y);
    		if (res) return res;
    	} 

    	if(isValid(x, y - 1))
    	{
    		boolean res = dfs(x, y - 1);
    		if (res) return res;

    	} 



    	if(x + 1 == r && y == c)
    	{
    		return true;
    	}

    	if(x == r && y + 1 == c)
    	{
    		return true;
    	} 

    	if(x - 1 == r && y == c)
    	{
    		return true;
    	} 

    	if(x == r && y - 1 == c)
    	{
    		return true;

    	} 

    	return false;
    }

    private static boolean isValid(int x, int y)
    {
    	return (x >= 0 && x < N && y >= 0 && y < M && grid[x][y] == '.' && !visited[x][y]);
    }

    private static boolean inGrid(int x, int y)
    {
    	return (x >= 0 && x < N && y >= 0 && y < M && grid[x][y] == '.');
    }

    private static boolean areNeighbours(int x, int y)
    {
    	if(x + 1 == r && y == c) return true;
    	else if(x - 1 == r && y == c) return true;
    	else if(x == r && y + 1 == c) return true;
    	else if(x == r && y - 1 == c) return true;
    	else return false;
    }

