    public SolveContest() {
        try {
            in = new BufferedReader(new FileReader("input.txt"));
            out = new PrintWriter(new FileWriter("output.txt"),true);
            solve();
        } catch (Exception e) {
            e.printStackTrace();
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
            solve();
        } finally {
            try {
                in.close();
            } catch (IOException e) {

            }
            out.close();
        }
    }
    StringTokenizer st;
    String nextToken()
    {
        while (st == null || !st.hasMoreTokens())
            try {
                st = new StringTokenizer(in.readLine());
            } catch (IOException e) {

            }
        return st.nextToken();
    }
    int nextInt() {
        return Integer.valueOf(nextToken());
    }
    long nextLong() {
        return Long.valueOf(nextToken());
    }

    int n;
    int m;

    char[][] ch;
    boolean can(int i,int j) {
        return i >= 0 && j >= 0 && i < n && j < m;
    }

    public void solve() {
        n = nextInt();
        m = nextInt();
        ch = new char[n][m];
        for (int i = 0; i < n; i++) {
            String s = nextToken();
            for (int j = 0; j < m; j++) {
                ch[i][j] = s.charAt(j);
            }
        }
        Pair st = new Pair(nextInt()-1, nextInt()-1);
        Pair fsh = new Pair(nextInt()-1, nextInt()-1);

        int dx[] = {0,0,1,-1};
        int dy[] = {1,-1,0,0};
        Queue<Pair> q = new LinkedList<Pair>();
        q.add(st);
        boolean[][] used = new boolean[n][m];
        while (!q.isEmpty()) {
            Pair p = q.poll();
            for (int i = 0; i < dx.length; i++) {
                int x = p.a + dx[i];
                int y = p.b + dy[i];
                if (can(x,y)) {
                    if (fsh.a == x && fsh.b == y && ch[x][y] == 'X') {
                        out.print("YES");
                        return;
                    }
                    if (!used[x][y]) {
                        if (ch[x][y] == 'X') continue;
                        used[x][y] = true;
                        ch[x][y] = 'X';
                        q.add(new Pair(x, y));
                    }
                }
            }
        }
        out.print("NO");
    }

    public static void main(String[] args) {
        new SolveContest();
    }
}

