		else
			System.out.println("NO");
	}

	private boolean solve()
	{
		if (start.r == end.r && start.c == end.c)
		{

			for (int i = 0; i < 4; i++)
			{
				int r = start.r + dx[i];
				int c = start.c + dy[i];
				if (valid(r, c))
					if (g[r][c])
						return true;
			}
			return false;
		} else
		{
			if (g[end.r][end.c])
			{

				for (int i = 0; i < 4; i++)
				{
					int r = end.r + dx[i];
					int c = end.c + dy[i];
					if (valid(r, c))
						if (g[r][c])
							if (bfs(new Cell(r, c)))
								return true;
				}
				return false;
			} else
			{

				return bfs(null);
			}
		}
	}

	private boolean bfs(Cell leave)
	{
		Queue<Cell> q = new LinkedList<>();
		boolean visited[][] = new boolean[R][C];
		if (leave != null)
			visited[leave.r][leave.c] = true;
		q.add(start);
		visited[start.r][start.c] = true;

		while (!q.isEmpty())
		{

			Cell cell = q.poll();
			if (cell.r == end.r && cell.c == end.c)
				return true;


			if (g[cell.r][cell.c] || cell == start)
				for (int i = 0; i < 4; i++)
				{
					int r = cell.r + dx[i];
					int c = cell.c + dy[i];
					if (valid(r, c))
						if (!visited[r][c])
						{
							visited[r][c] = true;
							q.add(new Cell(r, c));
						}
				}
		}
		return false;
	}

	private boolean valid(int r, int c)
	{
		return r >= 0 && r < R && c >= 0 && c < C;
	}

}

