class TaskC {

    class Coordinate {
        int x, y;

        Coordinate(int v1, int v2) {
            x = v1;
            y = v2;
        }

        public int getX() {
            return x;
        }

        public int getY() {
            return y;
        }
    }

    int e1, e2, n, m;
    char[][] board = new char[501][501];
    int[] d1 = {0, 0, 1, -1};
    int[] d2 = {1, -1, 0, 0};

    public boolean bfs(int s1, int s2) {
        Queue q = new LinkedList();
        q.add(new Coordinate(s1, s2));
        board[s1][s2] = 'X';
        while (!q.isEmpty()) {
            Coordinate f = (Coordinate) q.remove();
            s1 = f.getX();
            s2 = f.getY();
            for (int i = 0; i < 4; i++) {
                int ns1 = s1 + d1[i];
                int ns2 = s2 + d2[i];
                if (!checkRange(ns1, ns2))
                    continue;
                if (board[ns1][ns2] == 'X') {
                    if (ns1 == e1 && ns2 == e2)
                        return true;
                } else {
                    board[ns1][ns2] = 'X';
                    q.add(new Coordinate(ns1, ns2));
                }
            }
        }
        return false;
    }

    private boolean checkRange(int s1, int s2) {
        if (s1 >= n || s2 >= m) return false;
        if (s1 < 0 || s2 < 0) return false;
        return true;
    }

    public void solve(int testNumber, Scanner in, PrintWriter out) {
        n = in.nextInt();
        m = in.nextInt();
        in.nextLine();
