            String s = in.nextLine();
            for (int j = 0; j < m; j++) {
                board[i][j] = s.charAt(j);
            }
        }
        int s1 = in.nextInt() - 1, s2 = in.nextInt() - 1;
        e1 = in.nextInt() - 1;
        e2 = in.nextInt() - 1;
        if (bfs(s1, s2)) {
            out.write("YES");
        } else {
            out.write("NO");
        }
    }
}

