                br = new BufferedReader(new InputStreamReader(System.in));
                st = new StringTokenizer(br.readLine());
            } catch (Exception e){e.printStackTrace();}
        }

        public String next() {
            if (st.hasMoreTokens()) return st.nextToken();
            try {st = new StringTokenizer(br.readLine());}
            catch (Exception e) {e.printStackTrace();}
            return st.nextToken();
        }

        public int nextInt() {return Integer.parseInt(next());}

        public long nextLong() {return Long.parseLong(next());}

        public double nextDouble() {return Double.parseDouble(next());}

        public String nextLine() {
            String line = "";
            if(st.hasMoreTokens()) line = st.nextToken();
            else try {return br.readLine();}catch(IOException e){e.printStackTrace();}
            while(st.hasMoreTokens()) line += " "+st.nextToken();
            return line;
        }
    }

    static int n, m;
    static char[][] grid;

	public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        n = sc.nextInt(); m = sc.nextInt();
        grid = new char[n][m];


        for(int i=0;i<n;i++) {
            grid[i] = sc.nextLine().toCharArray();
        }


        int r1 = sc.nextInt() - 1; int c1 = sc.nextInt() - 1;
        int r2 = sc.nextInt() - 1; int c2 = sc.nextInt() - 1;

        if(dfs(r1, c1, r2, c2)) System.out.println("YES");
        else System.out.println("NO");
    }

    static int[] dirX = {-1, 0, 0, 1};
    static int[] dirY = {0, 1, -1, 0};

    public static boolean dfs(int i, int j, int endI, int endJ) {
        grid[i][j] = 'X';
        for(int k=0;k<4;k++) {
            int nextI = i + dirX[k];
            int nextJ = j + dirY[k];

            if(nextI == endI && nextJ == endJ && grid[endI][endJ] == 'X') {
                return true;
            }
            if(inBounds(nextI, nextJ) && grid[nextI][nextJ] == '.') {
                if(dfs(nextI, nextJ, endI, endJ)) {
                    return true;
                }
            }
        }

        return false;
    }

    public static boolean inBounds(int thisI, int thisJ) {
        return thisI >= 0 && thisI < n && thisJ >= 0 && thisJ < m;
    }

}

import java.util.*;

public class IceCave2 {

    static int n;
    static int m;
    static int r1;
    static int c1;
    static int r2;
    static int c2;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        m = scanner.nextInt();
        char[][] board = new char[n][m];
        for (int i = 0; i < n; i++) {
            board[i] = scanner.next().toCharArray();
        }
        r1 = scanner.nextInt() - 1;
        c1 = scanner.nextInt() - 1;
        r2 = scanner.nextInt() - 1;
        c2 = scanner.nextInt() - 1;
        if (solution(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    public static boolean solution(char[][] board) {
        Stack<Pair> q = new Stack<>();
        Pair pair = new Pair(r1, c1);
        q.add(pair);
        while (!q.isEmpty()) {
            pair = q.pop();
            List<Pair> moves = getMoves(pair.r, pair.c);

            for (Pair p : moves) {
                if (p.r == r2 && p.c == c2 && board[p.r][p.c] == 'X') { return true; }
                if (board[p.r][p.c] == 'X') { continue; }
                q.add(p);
                board[p.r][p.c] = 'X';
            }
        }
        return false;
    }

    static List<Pair> getMoves(int r, int c) {
        List<Pair> moves = new ArrayList<>();
        if (validMove(r - 1, c)) {
            moves.add(new Pair(r - 1, c));
        }
        if (validMove(r + 1, c)) {
            moves.add(new Pair(r + 1, c));
        }
        if (validMove(r, c + 1)) {
            moves.add(new Pair(r, c + 1));
        }
        if (validMove(r, c - 1)) {
            moves.add(new Pair(r, c - 1));
        }
        return moves;
    }

    static boolean validMove(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    static class Pair implements Comparable<Pair> {
        int r, c;

        public Pair(int r, int c) {
            this.r = r;
            this.c = c;
        }

        int distance(Pair o) {
            return Math.abs(r - o.r) + Math.abs(c - o.c);
        }

        @Override
        public int compareTo(Pair o) {
            return distance(this) - distance(o);
        }
    }
}

