public class IceCave {

    int[] dx = new int[]{-1, 0, 0, 1};
    int[] dy = new int[]{0, -1, 1, 0};

    int n, m;
    char[][] g;
    boolean[][] vis;
    int r1, c1, r2, c2;

    void solve() {
        n = in.nextInt();
        m = in.nextInt();
        g = new char[n][];
        for (int i = 0; i < n; i++) {
            g[i] = in.nextToken().toCharArray();
        }
        r1 = in.nextInt() - 1;
        c1 = in.nextInt() - 1;
        r2 = in.nextInt() - 1;
        c2 = in.nextInt() - 1;

        if (r1 == r2 && c1 == c2) {
            boolean ok = false;
            for (int i = 0; i < 4; i++) {
                int x = r1 + dx[i], y = c1 + dy[i];
                if (x >= 0 && x < n && y >= 0 && y < m && g[x][y] == '.') {
                    ok = true;
                    break;
                }
            }
            if (ok) out.println("YES");
            else out.println("NO");
            return;
        }

        vis = new boolean[n][m];
        dfs(r1, c1);

        if (!vis[r2][c2]) {
            out.println("NO");
            return;
        }

        if (g[r2][c2] == 'X') {
            out.println("YES");
            return;
        }

        int cnt = 0;
        for (int i = 0; i < 4; i++) {
            int x = r2 + dx[i], y = c2 + dy[i];
            if (x >= 0 && x < n && y >= 0 && y < m && (g[x][y] == '.' || x == r1 && y == c1)) cnt++;
        }
        if (cnt >= 2) out.println("YES");
        else out.println("NO");
    }

    void dfs(int r, int c) {
        vis[r][c] = true;
        for (int i = 0; i < 4; i++) {
            int x = r + dx[i], y = c + dy[i];
            if (x >= 0 && x < n && y >= 0 && y < m && g[x][y] == '.' || x == r2 && y == c2) {
                if (!vis[x][y]) dfs(x, y);
            }
        }
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new IceCave().solve();
        out.close();
    }

    static FastScanner in;
    static PrintWriter out;

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

