import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;

public class Main {

    private static final char X = 'X';
    private static final char D = '.';

    private static int n;
    private static int m;
    private static int r2;
    private static int c2;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        m = scanner.nextInt();
        char[][] board = new char[n][m];
        for (int i = 0; i < n; i++) {
            board[i] = scanner.next().toCharArray();
        }
        int r1 = scanner.nextInt() - 1;
        int c1 = scanner.nextInt() - 1;
        r2 = scanner.nextInt() - 1;
        c2 = scanner.nextInt() - 1;
        boolean possible = search(board, r1, c1);
        if (possible) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    private static boolean search(char[][] board, int r1, int c1) {
        ArrayDeque<Pair> q = new ArrayDeque<>();
        q.add(new Pair(r1, c1));

        while (!q.isEmpty()) {
            Pair p = q.pollLast();
            List<Pair> next = getNext(p.r, p.c);
            Collections.sort(next);
            for (Pair n : next) {
                if (n.r == r2 && n.c == c2 && board[n.r][n.c] == X) {
                    return true;
                }
                if (board[n.r][n.c] == X) {
                    continue;
                }
                q.addLast(n);
                board[n.r][n.c] = X;
            }
        }
        return false;
    }

    private static List<Pair> getNext(int r1, int c1) {
        List<Pair> pairs = new ArrayList<>();
        if (ok(r1 - 1, c1)) {
            pairs.add(new Pair(r1 - 1, c1));
        }
        if (ok(r1 + 1, c1)) {
            pairs.add(new Pair(r1 + 1, c1));
        }
        if (ok(r1, c1 - 1)) {
            pairs.add(new Pair(r1, c1 - 1));
        }
        if (ok(r1, c1 + 1)) {
            pairs.add(new Pair(r1, c1 + 1));
        }
        return pairs;
    }

    private static boolean ok(int nextR, int nextC) {
        return nextR >= 0 && nextC >= 0 && nextR < n && nextC < m;
    }

    static class Pair implements Comparable<Pair> {
        int r, c;
        Pair(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public int compareTo(Pair o) {
            return dist(o) - dist(this);
        }

        private int dist(Pair o) {
            return Math.abs(r2 - o.r) + Math.abs(c2 - o.c);
        }

        @Override
        public String toString() {
            return String.format("{r:%d,c:%d}", r, c);
        }
    }

}

