public class Solution extends Thread{
    public Solution(String inputFileName, String outputFileName) {
        try {
            if (inputFileName != null) {
                this.input = new BufferedReader(new FileReader(inputFileName));
            } else {
                this.input = new BufferedReader(new InputStreamReader(System.in));
            }
            if (outputFileName != null) {
                this.output = new PrintWriter(outputFileName);
            } else {
                this.output = new PrintWriter(System.out);
            }
            this.setPriority(Thread.MAX_PRIORITY);
        } catch (Throwable e) {
            System.err.println(e.getMessage());
            e.printStackTrace();
            System.exit(666);
        }
    }

    static class Segment implements Comparable<Segment> {
        int l, r;
        public Segment(int l, int r) {
            this.l = l;
            this.r = r;
        }

        @Override
        public int compareTo(Segment o) {
            if (this.l < o.l && this.r < o.r) {
                return -1;
            }
            if (this.l > o.l && this.r > o.r) {
                return 1;
            }
            if (this.l <= o.l && this.r >= o.r) {
                return 0;
            }
            return 0;
        }

        public int getCount() {
            return r - l;
        }
    }

    private void solve() throws Throwable {
        int n = nextInt(), m = nextInt();
        char []str = next().toCharArray();
        int curAns = 0;
        NavigableSet<Segment> segments = new TreeSet<>();
        for (int i = 0; i < n; ) {
            while (i < n && str[i] != '.') {
                ++i;
            }
            if (i >= n) {
                break;
            }
            int j = i;
            while (j < n && str[j] == '.') {
                ++j;
            }
            segments.add(new Segment(i, j - 1));
            curAns += j - 1 - i;
            i = j;
        }
        while (m-- > 0) {
            int at = nextInt() - 1;
            char c = next().charAt(0);
            Segment now = new Segment(at, at);
            if (c == '.') {
                Segment floor = segments.floor(now), ceil = segments.ceiling(now);
                int newLeft = -1, newRight = -1;
                if (floor != null) {
                    if (!(floor.l <= at && floor.r >= at)) {
                        if (floor.r + 1 == at) {
                            newLeft = floor.l;
                            newRight = at;
                            curAns -= floor.getCount();
                            segments.remove(floor);
                        }
                    }
                }
                if (ceil != null) {
                    if (!(ceil.l <= at && ceil.r >= at)) {
                        if (ceil.l - 1 == at) {
                            if (newLeft == -1) {
                                newLeft = at;
                            }
                            newRight = ceil.r;
                            curAns -= ceil.getCount();
                            segments.remove(ceil);
                        }
                    }
                }
                if (newLeft != -1) {
                    segments.add(new Segment(newLeft, newRight));
                    curAns += newRight - newLeft;
                } else {
                    segments.add(new Segment(at, at));
                }
            } else {
                Segment floor = segments.ceiling(now);
                if (floor != null) {
                    if (floor.l <= at && floor.r >= at) {
                        segments.remove(floor);
                        curAns -= floor.getCount();
                        if (floor.l == at) {
                            if (floor.r != at) {
                                segments.add(new Segment(at + 1, floor.r));
                                curAns += floor.r - at - 1;
                            }
                        } else {
                            if (floor.r == at) {
                                if (floor.l != at) {
                                    segments.add(new Segment(floor.l, at - 1));
                                    curAns += at - 1 - floor.l;
                                }
                            } else {
                                segments.add(new Segment(floor.l, at - 1));
                                segments.add(new Segment(at + 1, floor.r));
                                curAns += at - 1 - floor.l;
                                curAns += floor.r - at - 1;
                            }
                        }
                    }
                }
            }
            output.println(curAns);
        }

    }

    public void run() {
        try {
            solve();
        } catch (Throwable e) {
            System.err.println(e.getMessage());
            e.printStackTrace();
            System.exit(666);
        } finally {
            output.close();
        }
    }

    public static void main(String... args) {
        new Solution(null, null).start();
    }

