import java.util.StringTokenizer;


public class Replacement {
    void solve() {
        int n = in.nextInt(), m = in.nextInt();
        String s = in.nextToken();
        char[] ch = s.toCharArray();

        int periods = 0, segments = 0;
        for (int i = 0; i < n; ) {
            if (ch[i] == '.') {
                int j = i;
                while (j + 1 < n && ch[j + 1] == '.') j++;
                periods += j - i + 1;
                segments++;
                i = j + 1;
            } else {
                i++;
            }
        }

        for (int i = 0; i < m; i++) {
            int x = in.nextInt() - 1;
            char c = in.nextToken().charAt(0);
            if (c == '.' && ch[x] != '.') {
                ch[x] = c;
                periods++;
                if (x > 0 && x < n - 1) {
                    if (ch[x - 1] == '.' && ch[x + 1] == '.') {
                        segments--;
                    } else if (ch[x - 1] != '.' && ch[x + 1] != '.') {
                        segments++;
                    }
                } else if (n - 1 == 0) {
                    segments++;
                } else if (x == 0) {
                    if (ch[x + 1] != '.') {
                        segments++;
                    }
                } else if (x == n - 1) {
                    if (ch[x - 1] != '.') {
                        segments++;
                    }
                }
            } else if (c != '.' && ch[x] == '.') {
                ch[x] = c;
                periods--;
                if (x > 0 && x < n - 1) {
                    if (ch[x - 1] == '.' && ch[x + 1] == '.') {
                        segments++;
                    } else if (ch[x - 1] != '.' && ch[x + 1] != '.') {
                        segments--;
                    }
                } else if (x == 0 && x == n - 1) {
                    segments--;
                } else if (x == 0) {
                    if (ch[x + 1] != '.') {
                        segments--;
                    }
                } else if (x == n - 1) {
                    if (ch[x - 1] != '.') {
                        segments--;
                    }
                }
            }
            out.println(periods - segments);
        }
    }

    int search(List<Range> ranges, int s, int e, int x) {
        int m = (s + e) / 2;
        Range r = ranges.get(m);
        if (x >= r.a && x <= r.b) return m;
        if (x < r.a) return search(ranges, s, m - 1, x);
        return search(ranges, m + 1, e, x);
    }

    static class Range implements Comparable<Range> {
        int a;
        int b;
        boolean p;

        public Range(int a, int b, boolean p) {
            this.a = a;
            this.b = b;
            this.p = p;
        }

        @Override
        public int compareTo(Range r) {
            if (a != r.a) return a - r.a;
            return b - r.b;
        }
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new Replacement().solve();
        out.close();
    }

    static FastScanner in;
    static PrintWriter out;

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
