    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[] s = in.next().toCharArray();
            TreeSet<Seg> set = new TreeSet<>();
            int count = 1;
            int from = 0;
            int to = 0;
            int ans = 0;
            for (int i = 0; i < s.length - 1; i++) {
                if (s[i] == s[i + 1] && s[i] == '.') {
                    count++;
                    to++;
                    if (i == s.length - 2) {
                        ans += to - from;
                        set.add(new Seg(from, to));
                    }
                } else {
                    if (count != 1) {
                        ans += to - from;
                        set.add(new Seg(from, to));
                    }
                    from = i + 1;
                    to = i + 1;
                    count = 1;
                }
            }

            for (int i = 0; i < m; i++) {
                int x = in.nextInt() - 1;
                char c = in.next().charAt(0);
                if (s[x] == '.' && c == '.') {
                    out.println(ans);
                    continue;
                }
                s[x] = c;
                if (c == '.') {
                    boolean was1 = false;
                    boolean was2 = false;
                    Seg cur1 = null;
                    Seg cur2 = null;
                    if (x + 1 < n && s[x + 1] == '.') {
                        cur1 = set.lower(new Seg(x + 1, -1));
                        if (cur1 != null && cur1.l != x + 1)
                            cur1 = null;
                        was1 = true;
                    }
                    if (x - 1 >= 0 && s[x - 1] == '.') {
                        cur2 = set.lower(new Seg(x - 1, -1));
                        if (cur2 != null && cur2.r != x - 1)
                            cur2 = null;
                        was2 = true;
                    }
                    if (was1 && was2) {
                        if (cur1 == null && cur2 == null) {
                            set.add(new Seg(x - 1, x + 1));
                            ans += 2;
                        } else if (cur1 == null) {
                            set.add(new Seg(cur2.l, x + 1));
                            set.remove(cur2);
                            ans += 2;
                        } else if (cur2 == null) {
                            set.add(new Seg(x - 1, cur1.r));
                            set.remove(cur1);
                            ans += 2;
                        } else {
                            set.add(new Seg(cur2.l, cur1.r));
                            set.remove(cur1);
                            set.remove(cur2);
                            ans -= cur1.r - cur1.l;
                            ans -= cur2.r - cur2.l;
                            ans += cur1.r - cur2.l;
                        }
                    } else if (was1) {
                        if (cur1 == null) {
                            set.add(new Seg(x, x + 1));
                            ans++;
                        } else {
                            set.add(new Seg(x, cur1.r));
                            set.remove(cur1);
                            ans++;
                        }
                    } else if (was2) {
                        if (cur2 == null) {
                            set.add(new Seg(x - 1, x));
                            ans++;
                        } else {
                            set.add(new Seg(cur2.l, x));
                            set.remove(cur2);
                            ans++;
                        }
                    }
                    out.println(ans);
                    continue;
                }
                Seg cur = set.lower(new Seg(x, -1));
                if (cur == null || cur.r < x) {
                    out.println(ans);
                    continue;
                }
                TaskC.Seg left = new Seg(cur.l, x - 1);
                TaskC.Seg right = new Seg(x + 1, cur.r);
                set.remove(cur);
                if (left.r - left.l > 0) {
                    set.add(left);
                    ans += left.r - left.l;
                }
                if (right.r - right.l > 0) {
                    set.add(right);
                    ans += right.r - right.l;
                }
                ans -= cur.r - cur.l;
                out.println(ans);
            }
        }

        class Seg implements Comparable<Seg> {
            int l;
            int r;

            public Seg(int l, int r) {
                this.l = l;
                this.r = r;
            }

            public int compareTo(Seg o) {
                if (this.l != o.l)
                    return this.l - o.l;
                return o.r - this.r;
            }

        }

    }

