    static class _570C_{
        public void solve(int testNumber,InputReader in,OutputWriter out){
            int strlen=in.nextInt(), queries=in.nextInt();
            char[] s=in.next().toCharArray();
            int total=0, groups=0, i=0;
            while(i<strlen){
                if(s[i]=='.'){
                    ++groups;
                    while(i<strlen && s[i++]=='.') ++total;
                }else ++i;
            }
            while(queries-->0){
                int position=in.nextInt()-1;
                char replacement=in.nextCharacter();
                if(replacement!='.'){
                    if(s[position]=='.'){
                        --total;
                        if((position-1>=0 && s[position-1]=='.') && (position+1<strlen && s[position+1]=='.'))
                            ++groups;
                        else if((((position-1>=0 && s[position-1]!='.') || position==0) && ((position+1<strlen && s[position+1]!='.') || position==strlen-1)) || strlen==1)
                            --groups;
                    }
                }else{
                    if(s[position]!='.'){
                        ++total;
                        if(((position-1>=0 && s[position-1]=='.') && (position+1<strlen && s[position+1]=='.')))
                            --groups;
                        else if(((position-1>=0 && s[position-1]!='.') || position==0) && ((position+1<strlen && s[position+1]!='.') || position==strlen-1))
                            ++groups;
                    }
                }
                s[position]=replacement;
                out.println(total-groups);
            }
        }

