        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader fi = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(1, fi, out);
        out.close();
    }

    static class Task {
        public void solve(int testNumber, InputReader fi, PrintWriter out) {
            int i,j,k,ans;
            int n=fi.nextInt();
            int q=fi.nextInt();
            char []s=fi.readString().toCharArray();
            ans=0;
            for (i=0;i<n;i++){
                j=0;
                while (i<n && s[i]=='.') {
                    j++;
                    i++;
                }
                ans+=Math.max(0,j-1);
            }

            while (q-- > 0){
                int pos=fi.nextInt()-1;
                char ch=fi.readString().charAt(0);
                if (ch=='.'){
                    if (s[pos]!='.'){
                        if (pos-1>=0 && s[pos-1]=='.') ans++;
                        if (pos+1<n && s[pos+1]=='.') ans++;
                    }
                }
                else if (ch!='.'){
                    if (s[pos]=='.'){
                        if (pos-1>=0 && s[pos-1]=='.') ans--;
                        if (pos+1<n && s[pos+1]=='.') ans--;
                    }
                }
                s[pos]=ch;
                out.println(ans);
            }
        }
    }
