public class C {

	static final Reader in = new Reader();
	static final PrintWriter out = new PrintWriter(System.out,false);
	static boolean debug = false;

	static void solve(){
		int n = in.nextInt();
		int m = in.nextInt();
		char[] s = in.next().toCharArray();
		int ans = 0;
		for (int r=0; r<n; r++) {
			if (s[r] != '.') continue;
			int l = r;
			while (r+1 < n && s[r+1] == '.') r++;
			ans += r - l;
		}
		for (int i=0; i<m; i++) {
			int p = in.nextInt() - 1;
