					if (0 <= p-1 && s[p-1] == '.') d++;
					ans += d;
				}

			} else {
				if (s[p] == '.') {
					int d = 0;
					if (p + 1 < n && s[p+1] == '.') d++;
					if (0 <= p-1 && s[p-1] == '.') d++;
					ans -= d;
				}
			}
			s[p] = c;
			out.println(ans);
		}
