public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            in.nextLine();
            String s = in.nextLine();
            int from = -1;

            long total = 0;
            char[] chars = new char[s.length()];
            for (int i = 0; i < s.length(); i++) {
                chars[i] = s.charAt(i);
                if (from < 0 && s.charAt(i) == '.') {
                    from = i;
                    continue;
                }
                if (from >= 0 && s.charAt(i) != '.') {
                    total += Math.max(i - 1 - from, 0);
                    from = -1;
                }
            }

            if (from >= 0) {
                total += Math.max(s.length() - 1 - from, 0);
            }

            for (int i = 0; i < m; i++) {
                int idx = in.nextInt() - 1;
                char c = in.next().charAt(0);
                if (c != '.') {

                    if (chars[idx] != '.') {

                        out.println(total);
                        continue;
                    }

                    chars[idx] = c;
                    if (dotToTheLeft(idx, chars) && dotToTheRight(idx, chars)) {
                        total -= 2;
                    } else if (dotToTheLeft(idx, chars) || dotToTheRight(idx, chars)) {

                        total--;
                    }
                } else if (chars[idx] != '.') {

                    if (dotToTheLeft(idx, chars) && dotToTheRight(idx, chars)) {


                        if (!dotToTheLeft(idx - 1, chars) && !dotToTheRight(idx + 1, chars)) {

                            total += 2;
                        } else if (dotToTheLeft(idx - 1, chars) || dotToTheRight(idx + 1, chars)) {
                            total += 2;
                        } else {
                            total++;
                        }
                    } else if (dotToTheLeft(idx, chars) || dotToTheRight(idx, chars)) {
                        total++;
                    }
                    chars[idx] = '.';

                }
                out.println(total);

            }
        }

        private boolean dotToTheLeft(int idx, char[] chars) {
            return idx > 0 && chars[idx - 1] == '.';
        }

        private boolean dotToTheRight(int idx, char[] chars) {
            return idx < chars.length - 1 && chars[idx + 1] == '.';
        }

    }
}

