		PrintWriter out = new PrintWriter(System.out);
		int n = sc.nextInt();
		int m = sc.nextInt();

		char ch [] = sc.nextLine().toCharArray();
		int count = 0;
		int s = 0;
		int e = 0;
		boolean dot = false;
		for(int i = 0; i < ch.length; i++){
			if(ch[i] == '.')
				if(dot)
					e = i;
				else{
					dot = true;
					s = e = i;
				}
			else
				if(dot){
					dot = false;
					count += (e-s);
				}


		}
		if(dot)
			count += (e-s);


		while(m-- > 0){
			int ind = sc.nextInt() - 1;
			char c = sc.next().charAt(0);
			if(ch[ind] == '.'){
				if(c != '.'){
					ch[ind] = c;
					if((ind!=0 && ch[ind-1] == '.') || (ind < n -1 && ch[ind+1] == '.'))
						count--;
					if(ind!=0 && ch[ind-1] == '.' && ind < n -1 && ch[ind+1] == '.')
						count--;
				}
			}
			else{
				if(c == '.' ){
					ch[ind] = c;
					if((ind!=0 && ch[ind-1] == '.') || (ind < n -1 && ch[ind+1] == '.'))
						count++;
					if(ind!=0 && ch[ind-1] == '.' && ind < n -1 && ch[ind+1] == '.')
						count++;
				}
			}

			out.println(count);

