                            sols++;
                        if (f < ch.length - 1 && ch[f + 1] == '.')
                            sols++;
                    }
                } else {
                    if (c != '.') {
                        if (f - 1 >= 0 && ch[f - 1] == '.')
                            sols--;
                        if (f < ch.length - 1 && ch[f + 1] == '.')
                            sols--;
                    }
                }
