            int len = in.nextInt();
            int m = in.nextInt();
            StringBuilder sb = new StringBuilder(in.next());
            int count = 0;
            for (int i = 1; i < len; i++) {
                if (sb.charAt(i) == '.' && sb.charAt(i - 1) == '.')
                    count++;
            }
            while (m-- > 0) {
