                        count--;
                    if (index != len - 1 && sb.charAt(index + 1) == '.')
                        count--;
                    out.println(count);
                    sb.setCharAt(index, c);
                    continue;
                }
                if (c == '.') {
                    if (index != 0 && sb.charAt(index - 1) == '.')
                        count++;
                    if (index != len - 1 && sb.charAt(index + 1) == '.')
                        count++;
                    out.println(count);
                    sb.setCharAt(index, c);
                    continue;
                }
                sb.setCharAt(index, c);
