        int total = 0;
        for (int i = 1; i < n; i++) {
            if (s[i] == '.' && s[i - 1] == '.') {
                total++;
            }
        }
        for (int i = 0; i < m; i++) {
            int pos = in.nextInt() - 1;
            String t = in.next();
            if (s[pos] != '.' && t.charAt(0) == '.') {
