                    total++;
                }
                if (pos + 1 < n && s[pos + 1] == '.') {
                    total++;
                }
                s[pos] = '.';
            } else if (s[pos] == '.' && t.charAt(0) != '.') {
                if (pos > 0 && s[pos - 1] == '.') {
                    total--;
                }
                if (pos + 1 < n && s[pos + 1] == '.') {
                    total--;
                }
                s[pos] = t.charAt(0);
            }
            out.println(total);
        }
