        }

        public String next() {
            if (!hasMoreElements()) {
                return null;
            }
            return st.nextToken();
        }

        public boolean hasMoreElements() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

