			writer.print(i);
		}

		public void close() {
			writer.close();
		}

		public void print(int i) {
			writer.print(i);
		}

	}

	static class InputReader {
		private InputStream stream;
		private byte[] buf = new byte[1024];
		private int curChar;
		private int numChars;
		private SpaceCharFilter filter;

		public InputReader(InputStream stream) {
			this.stream = stream;
		}

		public int read() {
			if (numChars == -1)
				throw new InputMismatchException();
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = stream.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (numChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		public int readInt() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = read();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			} while (!isSpaceChar(c));
			return res * sgn;
		}

		public boolean isSpaceChar(int c) {
			if (filter != null)
				return filter.isSpaceChar(c);
			return isWhitespace(c);
		}

		public static boolean isWhitespace(int c) {
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		public char readCharacter() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			return (char) c;
		}

		public interface SpaceCharFilter {
			public boolean isSpaceChar(int ch);

		}

	}

	static class DSU {
		private final int n;
		private final int m;
		private final int[] parent;
		private final int[] size;

		public DSU(int n, int m) {
			this.n = n;
			this.m = m;
			int nm = n * m;
			parent = IntStream.range(0, nm).toArray();
			size = ArrayUtils.createArray(nm, 1);
		}

		public int findParent(int v) {
			if (parent[v] == v) return v;
			return parent[v] = findParent(parent[v]);
		}

		private void unite(int i1, int i2) {
			int p1 = findParent(i1);
			int p2 = findParent(i2);
			if (p1 != p2) {
				parent[p1] = p2;
				size[p2] += size[p1];
			}
		}

		private int convertToIndex(int i, int j) {
			return i * m + j;
		}

		public int findParent(int i, int j) {
			return findParent(convertToIndex(i, j));
		}

		public void unite(int i1, int j1, int i2, int j2) {
			unite(convertToIndex(i1, j1), convertToIndex(i2, j2));
		}

		public int getSize(int index) {
			return size[findParent(index)];
		}

	}

	static class ArrayUtils {
		public static int[] createArray(int count, int value) {
			int[] array = new int[count];
			Arrays.fill(array, value);
			return array;
		}

	}
}

import java.io.*;
import java.util.*;

public class C {

    void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] map = new char[n][m];
        for (int i = 0; i < n; i++) {
            String s = in.next();
            for (int j = 0; j < m; j++) {
                map[i][j] = s.charAt(j);
            }
        }

        Union union = new Union(n * m);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map[i][j] == '.') {
                    if (i + 1 < n && map[i + 1][j] == '.')
                        union.link(i * m + j, i * m + j + m);
                    if (j + 1 < m && map[i][j + 1] == '.')
                        union.link(i * m + j, i * m + j + 1);
                }
            }
        }

        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, 1, 0, -1};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map[i][j] == '.')
                    continue;
                int[] roots = new int[4];
                int curRoot = 0;
                int total = 0;
                outer:
                for (int k = 0; k < 4; k++) {
                    int nr = i + dr[k], nc = j + dc[k];
                    if (nr < n && nr >= 0 && nc < m && nc >= 0 && map[nr][nc] == '.') {
                        int root = union.root(nr * m + nc);
                        for (int u = 0; u < curRoot; u++) {
                            if (root == roots[u])
                                continue outer;
                        }
                        roots[curRoot++] = root;
                        total -= union.upper[root];
                    }
                }
                map[i][j] = (char) ('0' + (total + 1) % 10);
            }
        }

        for (int i = 0; i < n; i++) {
            out.println(map[i]);
        }
    }

    class Union {
        int[] upper;

        public Union(int n) {
            upper = new int[n];
            Arrays.fill(upper, -1);
        }

        int root(int x) {
            return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
        }

        boolean link(int x, int y) {
            x = root(x);
            y = root(y);
            if (x != y) {
                if (upper[y] < upper[x]) {
                    int tmp = x;
                    x = y;
                    y = tmp;
                }
                upper[x] += upper[y];
                upper[y] = x;
            }
            return x == y;
        }


    }

    InputReader in;
    PrintWriter out;

    void runIO() {

        in = new InputReader(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    class InputReader {
        BufferedReader br;
        StringTokenizer st;

        public InputReader(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
