public class C {

	static int[] dx = { 1, -1, 0, 0 };
	static int[] dy = { 0, 0, 1, -1 };
	static ArrayList<Integer> lx;
	static ArrayList<Integer> ly;
	static char[][] grid;

	static boolean isV(int N, int M, int i, int j) {
		return i < N && j < M && i >= 0 && j >= 0;
	}

	static int go(int i, int j, int N, int M) {

		Queue<Integer> qx = new LinkedList<Integer>();
		Queue<Integer> qy = new LinkedList<Integer>();
		int ret = 1;
		qx.add(i);
		qy.add(j);
		grid[i][j] = '$';
		while (!qx.isEmpty()) {
			i = qx.remove();
			j = qy.remove();
			lx.add(i);
			ly.add(j);
			for (int d = 0; d < 4; d++) {
				int X = dx[d] + i;
				int Y = dy[d] + j;
				if (isV(N, M, X, Y) && grid[X][Y] == '.') {
					grid[X][Y] = '$';
					ret++;
					qx.add(X);
					qy.add(Y);
				}
			}
		}
		return ret;
	}

	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int M = sc.nextInt();

		grid = new char[N][];
		int[][] vals = new int[N][M];
		for (int i = 0; i < N; i++)
			grid[i] = sc.next().toCharArray();
		int cc = 0;
		lx = new ArrayList<Integer>();
		ly = new ArrayList<Integer>();
		int[][] findCC = new int[N][M];
		for (int i = 0; i < N; i++)
			for (int j = 0; j < M; j++) {
				if (grid[i][j] == '.') {
					lx.clear();
					ly.clear();
					int ret = go(i, j, N, M);
					for (int k = 0, sz = lx.size(); k < sz; k++) {
						int px = lx.get(k);
						int py = ly.get(k);
						vals[px][py] = ret;
						findCC[px][py] = cc;
					}
					cc++;
				}
			}
		HashSet<Integer> set = new HashSet<Integer>();
		for (int i = 0; i < N; i++)
			for (int j = 0; j < M; j++) {
				if (grid[i][j] == '*') {
					vals[i][j] = 1;
					set.clear();
					for (int d = 0; d < 4; d++) {
						int X = dx[d] + i;
						int Y = dy[d] + j;
						if (!isV(N, M, X, Y))
							continue;
						if (grid[X][Y] == '$' && !set.contains(findCC[X][Y])) {
							vals[i][j] += vals[X][Y];
							set.add(findCC[X][Y]);
						}

					}
					vals[i][j] %= 10;
				}
			}

		StringBuilder ans = new StringBuilder();
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < M; j++) {
				if (grid[i][j] == '*')
					ans.append(vals[i][j]);
				else
					ans.append(".");
			}
			ans.append("\n");
		}
		System.out.print(ans);
	}

