import java.util.StringTokenizer;

public class ProblemC {
	private static int[] dx = { -1, 0, 0, 1 };
	private static int[] dy = { 0, -1, 1, 0 };

	public static void main(String[] args) {
		InputReader in = new InputReader();
		PrintWriter out = new PrintWriter(System.out);

		new ProblemC().solve(in, out);

		out.close();
	}

	public void solve(InputReader in, PrintWriter out) {
		int n = in.nextInt();
		int m = in.nextInt();

		char[][] a = new char[n][m];
		for (int i = 0; i < n; i++) {
			String s = in.nextLine();

			for (int j = 0; j < m; j++) {
				a[i][j] = s.charAt(j);
			}
		}

		boolean[][] marked = new boolean[n][m];

		int[][] components = new int[n][m];

		Map<Integer, Integer> map = new HashMap<Integer, Integer>();

		int index = 1;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {

				if (!marked[i][j] && a[i][j] == '.') {
					int count = bfs(n, m, a, i, j, marked, index, components);

					map.put(index, count);

					index++;
				}
			}
		}

		for (int i = 0; i < n; i++) {

			for (int j = 0; j < m; j++) {

				if (a[i][j] == '.') {
					out.print(".");
				} else {

					Set<Integer> set = new HashSet<Integer>();

					for (int k = 0; k < 4; k++) {
						int newX = i + dx[k];
						int newY = j + dy[k];

						if (newX >= 0 && newX < n && newY >= 0 && newY < m && a[newX][newY] != '*') {
							set.add(components[newX][newY]);
						}
					}

					int total = 1;
					for (int v : set) {
						total += map.get(v);
					}

					out.print(total % 10);
				}
			}

			out.println();
		}
	}

	private static int bfs(int n, int m, char[][] a, int i, int j, boolean[][] marked, int index, int[][] components) {
		int total = 1;

		Queue<Integer> qI = new LinkedList<Integer>();
		Queue<Integer> qJ = new LinkedList<Integer>();

		marked[i][j] = true;

		qI.add(i);
		qJ.add(j);

		components[i][j] = index;

		while (!qI.isEmpty()) {
			int x = qI.poll();
			int y = qJ.poll();

			for (int k = 0; k < 4; k++) {
				int newX = x + dx[k];
				int newY = y + dy[k];

				if (newX >= 0 && newX < n && newY >= 0 && newY < m && !marked[newX][newY] && a[newX][newY] == '.') {
					qI.add(newX);
					qJ.add(newY);

					marked[newX][newY] = true;

					components[newX][newY] = index;

					total++;
				}
			}
		}

		return total;
	}

	static class InputReader {
		public BufferedReader br;
		public StringTokenizer st;

		public InputReader() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
