public class TheLabyrinth {

	static class Pair {
		int r, c;

		Pair (int r, int c){
			this.r = r;
			this.c = c;
		}

		public String toString (){
			return r + " " + c;
		}
	}

	static int maxr, maxc;
	static char grid[][];

	static int newGrid [][];
	static int result [][];
	static boolean visited [][];
	static int dx[] = { 1, 0, -1, 0 };
	static int dy[] = { 0, 1, 0, -1 };

	static boolean isValid (int r, int c){
		return r >= 0 && r < maxr && c >= 0 && c < maxc;
	}

	static int dfs (int r, int c, int id, int size){
		visited[r][c] = true;
		int max = 1;
		for(int i = 0;i < dx.length;i++){
			int newr = r + dx[i];
			int newc = c + dy[i];
			if(isValid(newr, newc) && !visited[newr][newc] && grid[newr][newc] != '*')
				max += dfs(newr, newc,id,size);
		}
		newGrid[r][c] = id;

		return max;
	}

	static void solve () throws IOException{
		MyScanner sc = new MyScanner(System.in);
		PrintWriter pw = new PrintWriter(System.out);
		maxr = sc.nextInt();
		maxc = sc.nextInt();
		grid = new char [maxr][maxc];

		newGrid = new int [maxr][maxc];
		result = new int [maxr][maxc];
		visited = new boolean[maxr][maxc];
		for(int i = 0;i < maxr;i++){
			grid[i] = sc.nextLine().toCharArray();
		}
		int id = 1;
		HashMap<Integer, Integer> map = new HashMap<>();
		for(int i = 0;i < maxr;i++){
			for(int j = 0;j < maxc;j++){
				if(!visited[i][j] && grid[i][j] != '*'){
					int size = dfs(i,j,id,0);
					map.put(id++, size);
				}
			}
		}
		for(int i = 0;i < maxr;i++){
			for(int j = 0;j < maxc;j++){
				if(grid[i][j] != '*')
					continue;
				HashMap<Integer, Boolean> vis = new HashMap<>();
				for(int k = 0;k < dx.length;k++){
					int newr = i + dx[k];
					int newc = j + dy[k];
					if(isValid(newr, newc) && grid[newr][newc] == '.'){
						if(vis.get(newGrid[newr][newc]) == null){
							result[i][j] += map.get(newGrid[newr][newc]);
							vis.put(newGrid[newr][newc], true);
						}
					}
				}
				result[i][j]++;
			}
		}
		StringBuilder sb = new StringBuilder();
		for(int i = 0;i < maxr;i++){
			for(int j = 0;j < maxc;j++){
				if(result[i][j] == 0)
					sb.append('.');
				else
					sb.append(result[i][j] % 10);
			}
			sb.append('\n');
		}
		pw.println(sb);
		pw.close();
	}

	public static void main(String[] args) throws IOException {

		new Thread(null,new Runnable() {

			@Override
			public void run() {
				try {
					solve();
				}
				catch (Exception e){
					e.printStackTrace();
				}
			}
		},"please work",1 << 28).start();
	}

	static class MyScanner {
		StringTokenizer st;
		BufferedReader br;

		public MyScanner(InputStream s) {
			br = new BufferedReader(new InputStreamReader(s));
		}

		public String next() throws IOException {
			while (st == null || !st.hasMoreTokens())
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

