public class Solution {
    public static class Point {
        int row, col;
        public Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static class Component {
        int id;
        int size;
        public Component() {
            this.id = nextId();
            size = 0;
        }

        static int nextId() {
            return ++lastId;
        }
        static int lastId = 0;
    }

    static boolean inBounds(int row, int column) {
        return row >= 0 && row < maze.length && column >= 0 && column < maze[0].length;
    }

    static boolean isFree(int row, int column) {
        return inBounds(row, column) && maze[row][column] == '.';
    }

    static void componentSize(int row, int column, Component component) {
        Queue<Point> q = new LinkedList<Point>();
        maze[row][column] = '$';
        q.add(new Point(row, column));

        while (q.size() > 0) {
            Point point = q.poll();
            components[point.row][point.col] = component;
            ++component.size;

            for (int i = 0; i < 4; ++i) {
                int nextRow = point.row + rowMoves[i];
                int nextColumn = point.col + columnMoves[i];
                if (isFree(nextRow, nextColumn)) {
                    maze[nextRow][nextColumn] = '$';
                    q.add(new Point(nextRow, nextColumn));
                }
            }
        }
    }

    static int[] rowMoves = new int[] { -1, 1, 0, 0 };
    static int[] columnMoves = new int[] { 0, 0, -1, 1 };
    static char[][] maze;
    static Component[][] components;

public static void main(String[] args) {
    MyScanner sc = new MyScanner();
    out = new PrintWriter(new BufferedOutputStream(System.out));

    int n = sc.nextInt();
    int m = sc.nextInt();
    maze = new char[n][m];
    components = new Component[n][m];

    for (int i = 0; i < n; ++i) {
        String row = sc.next();
        for (int j = 0; j < m; ++j) {
            maze[i][j] = row.charAt(j);
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (isFree(i, j)) {
                Component component = new Component();
                componentSize(i, j, component);
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (maze[i][j] == '$') {
                out.print('.');
            } else {
                int size = 1;
                HashSet<Integer> ids = new HashSet<Integer>();
                for (int k = 0; k < 4; ++k) {
                    int nextRow = i + rowMoves[k];
                    int nextCol = j + columnMoves[k];
                    if (inBounds(nextRow, nextCol) && components[nextRow][nextCol] != null && !ids.contains(components[nextRow][nextCol].id)) {
                        size += components[nextRow][nextCol].size;
                        ids.add(components[nextRow][nextCol].id);
                    }
                }
                out.print(size % 10);
            }
        }
        out.println();
    }
    out.close();
}

