public class Main {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(in, out);
        out.close();
    }

    public static class TaskC {
        private int di[] = {-1, 0, 1, 0};
        private int dj[] = {0, 1, 0, -1};

        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char ar[][] = new char[n][m];
            char rem[][] = new char[n][m];
            for (int i = 0; i < n; i++) {
                String s = in.next();
                for (int j = 0; j < m; j++)
                    rem[i][j] = ar[i][j] = s.charAt(j);
            }
            int ID[][] = new int[n][m];
            Hashtable<Integer, Integer> hashTable = new Hashtable<>();
            int lastID = 0;
            for (int i = 0; i < n; i++)
                for (int j = 0; j < m; j++)
                    if (ar[i][j] == '.') {
                        bfs(ar, i, j, ID, lastID, hashTable);
                        ar[i][j] = '.';
                        lastID++;
                    }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++)
                    if (rem[i][j] == '.')
                        out.print('.');
                    else {
                        HashSet<Integer> setID = new HashSet<>();
                        int ans = 0;
                        for (int dir = 0; dir < 4; dir++) {
                            int newI = i + di[dir];
                            int newJ = j + dj[dir];
                            if (in(newI, newJ, n, m) && (ar[newI][newJ] == '.' || ar[newI][newJ] == '#')) {
                                int curID = ID[newI][newJ];
                                if (!setID.contains(curID)) {
                                    ans += hashTable.get(curID);
                                    setID.add(curID);
                                }
                            }
                        }
                        out.print((ans + 1) % 10);
                    }
                out.println("");
            }
        }

        private void bfs(char ar[][], int startI, int startJ, int ID[][], int lastID, Hashtable<Integer, Integer> table) {
            ArrayDeque<Point> deque = new ArrayDeque<>();
            deque.addLast(new Point(startI, startJ));
            int n = ar.length;
            int m = ar[0].length;
            int amount = 1;
            while (!deque.isEmpty()) {
                Point curPoint = deque.pollFirst();
                int i = curPoint.i;
                int j = curPoint.j;
                ID[i][j] = lastID + 1;
                ar[i][j] = '#';
                for (int dir = 0; dir < 4; dir++) {
                    int newI = i + di[dir];
                    int newJ = j + dj[dir];
                    if (in(newI, newJ, n, m) && ar[newI][newJ] == '.') {
                        ar[newI][newJ] = '#';
                        amount++;
                        deque.addLast(new Point(newI, newJ));
                    }
                }
            }
            table.put(lastID + 1, amount);
        }

        private boolean in(int i, int j, int n, int m) {
            return i >= 0 && i < n && j >= 0 && j < m;
        }

        private static class Point {
            private int i, j;

            public Point(int i, int j) {
                this.i = i;
                this.j = j;
            }
        }
    }

    public static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

