public class Main {
    FastScanner in;
    PrintWriter out;

    static final String FILE = "";

    int n, m;
    String ms[];
    StringBuffer buf[];
    boolean used[][];
    int pointerX[][];
    int pointerY[][];
    int size[][];
    int currX, currY;
    int cnt;

    void dfs(int x, int y) {
        if (x < 0 || y < 0 || x >= n || y >= m)
            return;
        if (ms[x].charAt(y) == '*')
            return;
        if (used[x][y])
            return;
        cnt++;
        used[x][y] = true;
        pointerX[x][y] = currX;
        pointerY[x][y] = currY;
        dfs(x - 1, y);
        dfs(x + 1, y);
        dfs(x, y - 1);
        dfs(x, y + 1);
    }

    PairInt getPointer(int x, int y) {
        if (x < 0 || y < 0 || x >= n || y >= m)
            return new PairInt(-1, -1);
        if (ms[x].charAt(y) == '*')
            return new PairInt(-1, -1);
        return new PairInt(pointerX[x][y], pointerY[x][y]);
    }

    int getSize(PairInt pointer) {
        if (pointer.a < 0)
            return 0;
        return size[pointer.a][pointer.b];
    }

    int check(int x, int y) {
        if (ms[x].charAt(y) == '.')
            return -1;
        TreeSet<PairInt> pointers = new TreeSet<>();
        pointers.add(getPointer(x - 1, y));
        pointers.add(getPointer(x + 1, y));
        pointers.add(getPointer(x, y - 1));
        pointers.add(getPointer(x, y + 1));
        int ans = 1;
        for (PairInt pair : pointers) {
            ans += getSize(pair);
        }
        return ans;
    }

    public void solve() {
        n = in.nextInt();
        m = in.nextInt();
        ms = new String[n];
        buf = new StringBuffer[n];
        used = new boolean[n][m];
        pointerX = new int[n][m];
        pointerY = new int[n][m];
        size = new int[n][m];
        for (int i = 0; i < n; i++)
            ms[i] = in.next();

        for (int i = 0; i < n; i++) {
            for (int z = 0; z < m; z++) {
                if (ms[i].charAt(z) == '*')
                    continue;
                cnt = 0;
                currX = i;
                currY = z;
                dfs(i, z);
                size[i][z] = cnt;
            }
        }

        for (int i = 0; i < n; i++) {
            buf[i] = new StringBuffer();
            for (int z = 0; z < m; z++) {
                int curr = check(i, z);
                if (curr == -1)
                    buf[i].append('.');
                else
                    buf[i].append((char)((curr % 10) + '0'));
            }
            out.println(buf[i]);
        }
    }

    public void run() {
        if (FILE.equals("")) {
            in = new FastScanner(System.in);
            out = new PrintWriter(System.out);
        } else {
            try {
                in = new FastScanner(new FileInputStream(FILE + ".in"));
                out = new PrintWriter(new FileOutputStream(FILE + ".out"));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }
        solve();
        out.close();
    }

    public static void main(String[] args) {
        (new Main()).run();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public String nextLine() {
            st = null;
            try {
                return br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
                return "";
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    class Pair<A extends Comparable<A>, B extends Comparable<B>> implements Comparable<Pair<A, B>> {
        public A a;
        public B b;

        public Pair(A a, B b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public int compareTo(Pair<A, B> o) {
            if (o == null || o.getClass() != getClass())
                return 1;
            int cmp = a.compareTo(o.a);
            if (cmp == 0)
                return b.compareTo(o.b);
            return cmp;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;

            Pair<?, ?> pair = (Pair<?, ?>) o;

            if (a != null ? !a.equals(pair.a) : pair.a != null) return false;
            return !(b != null ? !b.equals(pair.b) : pair.b != null);
        }
    }

    class PairInt extends Pair<Integer, Integer> {
        public PairInt(Integer u, Integer v) {
            super(u, v);
        }
    }

}

