import java.io.*;
import java.util.Arrays;

public class C {

    static char[][] t;
    static int[][] cc;
    static int c;

    static void solve() throws IOException {
        long start = System.currentTimeMillis();
        String[] s = in.readLine().split( " " );
        int m = Integer.parseInt( s[0] );
        int n = Integer.parseInt( s[1] );


        t = new char[m + 2][n + 2];
        Arrays.fill( t[0], '*' );
        Arrays.fill( t[m + 1], '*' );
        for ( int i = 1; i <= m; i ++ ) {
            t[i] = ( "*" + in.readLine() + "*" ).toCharArray();



        }
        System.err.println( System.currentTimeMillis() - start );
        cc = new int[m + 2][n + 2];
        c = 0;
        int[] cs = new int[m * n + 1];
        for ( int i = 1; i <= m + 1; i ++ ) {
            for ( int j = 1; j <= n + 1; j ++ ) {
                if ( cc[i][j] == 0 && t[i][j] == '.' ) {
                    cs[++ c] = go( i, j );
                }
            }
        }
        System.err.println( System.currentTimeMillis() - start );
        char[][] r = new char[m][n];
        int[] comp = new int[5];
        for ( int i = 0; i < m; i ++ ) {
            for ( int j = 0; j < n;j ++ ) {
                if ( t[i + 1][j + 1] == '.' ) {
                    r[i][j] = '.';
                    continue;
                }
                int ccomp = 1;
                for ( int di = -1; di <= 1; di ++ ) {
                    for ( int dj = -1; dj <= 1; dj ++ ) {
                        if ( Math.abs( di ) + Math.abs( dj ) != 1 ) continue;
                        comp[ccomp ++] = cc[i + 1 + di][j + 1 + dj];
                    }
                }
                Arrays.sort( comp );
                int sum = 1;
                for ( int k = 1; k < comp.length; k ++ ) {
                    if ( comp[k] != comp[k - 1] ) {
                        sum += cs[comp[k]];
                    }
                }
                r[i][j] = ( char ) ( '0' + sum % 10 );
            }
        }
        System.err.println( System.currentTimeMillis() - start );

        for ( char[] rr : r ) {





            out.println( new String( rr ) );

        }

        System.err.println( System.currentTimeMillis() - start );
    }

    private static int go( int x, int y ) {
        if ( t[x][y] == '*' || cc[x][y] > 0 ) return 0;
        cc[x][y] = c;
        int r = 1;
        r += go( x - 1, y ) + go( x + 1, y ) + go( x, y - 1 ) + go( x, y + 1 );






        return r;
    }

    static BufferedReader in;

    static PrintWriter out;






    public static void main( String[] args ) throws IOException {
        in = new BufferedReader( new InputStreamReader( System.in ) );
        out = new PrintWriter( new BufferedOutputStream( System.out ) );
        solve();
        out.close();
    }
}

