public class TheLabyrinth {
	static int[] dx = {-1, 0, 1, 0};
	static int[] dy = {0, -1, 0, 1};
	static char[][] grid;
	static int r, c, count;
	static boolean[][] b;
	static ArrayDeque<Integer> a;
	static int[][] ans;
	static ArrayDeque<Integer> bfs;
	public static void main(String[] args) throws IOException{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter out = new PrintWriter(System.out);
		String[] split = br.readLine().split(" ");
		r = Integer.parseInt(split[0]); 
		c = Integer.parseInt(split[1]);
		grid = new char[r][c];
		ans = new int[r][c];
		a = new ArrayDeque<>();
		b = new boolean[r][c];
		for(int i = 0 ; i < r ; i++) grid[i] = br.readLine().toCharArray();
		for(int i = 0 ; i < r ; i++) for(int j = 0 ; j < c ; j++) if(grid[i][j] == '*') ans[i][j] = 1;
		for(int i = 0 ; i < r ; i++){
			for(int j = 0 ; j < c ; j++){
				if(grid[i][j] == '.' && !b[i][j]){
					count = 1;
					bfs = new ArrayDeque<>();
					b[i][j] = true;
					bfs.add(i);
					bfs.add(j);
					BFS();
					fill(count);
				}
			}
		}
		for(int i = 0 ; i < r ; i++){
			StringBuilder sb = new StringBuilder();
			for(int j = 0 ; j < c ; j++){
				if(grid[i][j] == '*') sb.append(ans[i][j]%10);
				else sb.append('.');
			}
			out.println(sb);
		}
		out.close();
	}
	static void fill(int n){
		while(!a.isEmpty()){
			int row = a.poll(), col = a.poll();
			ans[row][col] += n;
			b[row][col] = false;
		}
	}
	static void BFS(){
		while(!bfs.isEmpty()){
			int row = bfs.poll(), col = bfs.poll();
			for(int i = 0 ; i < 4 ; i++){
				int dr = row + dx[i], dc = col + dy[i];
				if(inbounds(dr, dc)){
					if(grid[dr][dc] == '*' && !b[dr][dc]){
						a.add(dr);
						a.add(dc);
						b[dr][dc] = true;
					}
					if(grid[dr][dc] == '.' && !b[dr][dc]){
						bfs.add(dr);
						bfs.add(dc);
						count++;
						b[dr][dc] = true;
					}
				}
			}
		}
	}
	static boolean inbounds(int row, int col){
		return row >= 0 && row < r && col >= 0 && col < c;
	}
}

