		int y;
		public Index(int x, int y){
			this.x=x;
			this.y=y;
		}
	}
	static int r;
	static int c;
	static char graph [][];
	static int result[][];
	static Queue <Index> temp;
	static int count;
	static boolean visited[][];


	public static void bfs(int i, int j){
		Queue<Index> q= new LinkedList<Index>();
		q.add(new Index(i,j));
		while(!q.isEmpty()){
			Index ind=q.poll();
			i=ind.x;
			j=ind.y;
			count++;
			visited[i][j]=true;
			if(i!=0)
				if(!visited[i-1][j]){
					visited[i-1][j]=true;
					if(graph[i-1][j]=='*')
						temp.add(new Index(i-1,j));

					else
						q.add(new Index(i-1,j));
				}
			if(i!=r-1)
				if(!visited[i+1][j]){
					visited[i+1][j]=true;
					if(graph[i+1][j]=='*')
						temp.add(new Index(i+1,j));

					else
						q.add(new Index(i+1,j));
				}
			if(j!=0)
				if(!visited[i][j-1]){
					visited[i][j-1]=true;
					if(graph[i][j-1]=='*')
						temp.add(new Index(i,j-1));

					else
						q.add(new Index(i,j-1));
				}
			if(j!=c-1)
				if(!visited[i][j+1]){
					visited[i][j+1]=true;
					if(graph[i][j+1]=='*')
						temp.add(new Index(i,j+1));

					else
						q.add(new Index(i,j+1));
				}
		}

	}
