		BufferedReader bf= new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st= new StringTokenizer(bf.readLine());
		r= Integer.parseInt(st.nextToken());
		c= Integer.parseInt(st.nextToken());
		graph= new char[r][c];
		for(int i=0; i<r; i++){
			String s= bf.readLine();
			for(int j=0; j<c; j++)
				graph[i][j]=s.charAt(j);
		}
		result= new int [r][c];
		visited= new boolean[r][c];
		temp= new LinkedList();
		for(int i=0; i<r; i++)
			for(int j=0; j<c;j++)
				if(!visited[i][j])
				if(graph[i][j]=='.'){
					count=0;
					bfs(i,j);
					while(!temp.isEmpty()){
						Index z=temp.poll();
						int x= z.x;
						int y= z.y;
						result[x][y]+=count;
						visited[x][y]=false;

					}
				}
		StringBuilder sb= new StringBuilder("");
		for(int i=0;i<r;i++){
			for(int j=0; j<c;j++){
				if(graph[i][j]=='.')
					sb.append('.');
					else
						sb.append((result[i][j]+1)%10);
			}
			sb.append("\n");
