public class C616 {

    public static int go(int x, int y, char[][] grid, int n, int m, int[][] group, int g)
    {
        grid[x][y] = 'v';
        int sum = 1;
        group[x][y] = g;
        if (x + 1 < n && grid[x + 1][y] =='.')
        {
            sum += go(x + 1, y, grid,n, m, group, g);
        }
        if (x - 1 >= 0 && grid[x - 1][y] == '.')
        {
            sum += go(x - 1, y, grid,  n, m, group, g);
        }
        if (y + 1 < m && grid[x][y + 1] =='.')
        {
            sum += go(x, y + 1, grid, n, m, group, g);
        }
        if (y - 1 >= 0 && grid[x][y - 1] == '.')
        {
            sum += go(x, y - 1, grid, n, m, group, g);
        }
        return sum;
    }

    public static void main(String... xxx) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++)
            br.readLine().getChars(0, m, grid[i], 0);

        int[][] group = new int[n][m];
        int[] z = new int[n * m];
        int groupCounter = 1;
        StringBuilder fin = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' || grid[i][j] == 'v')fin.append(".");
                else
                {
                    int sum = 1;
                    int a = 0,b = 0,c = 0,d = 0;
                    if (i + 1 < n && (grid[i + 1][j] == '.'  || grid[i + 1][j] == 'v'))
                    {
                        if (group[i + 1][j] == 0)
                        {
                            z[groupCounter] = go(i + 1, j, grid, n ,m,group, groupCounter);
                            groupCounter++;
                        }
                        a = group[i + 1][j];
                        sum += z[a];
                    }
                    if (i - 1 >= 0 && (grid[i - 1][j] == '.' || grid[i - 1][j] == 'v'))
                    {
                        if (group[i - 1][j] == 0)
                        {
                            z[groupCounter] = go(i - 1, j, grid, n ,m,group, groupCounter);
                            groupCounter++;
                        }
                        b = group[i - 1][j];
                        if (a != b)sum += z[b];
                    }
                    if (j + 1 < m  && (grid[i][j + 1] == '.' || grid[i][j + 1] == 'v'))
                    {
                        if (group[i][j + 1] == 0)
                        {
                            z[groupCounter] = go(i, j + 1, grid, n ,m,group, groupCounter);
                            groupCounter++;
                        }
                        c = group[i][j + 1];
                        if (a != c && b != c)sum += z[c];
                    }
                    if (j - 1 >= 0  && (grid[i][j - 1] == '.' || grid[i][j - 1] == 'v'))
                    {
                        if (group[i][j - 1] == 0)
                        {
                            z[groupCounter] = go(i, j - 1, grid, n ,m,group, groupCounter);
                            groupCounter++;
                        }
                        d = group[i][j - 1];
                        if (a != d && b != d && c != d)sum += z[d];
                    }
                    fin.append(sum%10);
                }
            }
            fin.append("\n");
        }
        pw.println(fin);
        pw.close();
    }
}

