    static boolean validCell(int row, int col) {
        return row >= 0 && row < numRows && col >= 0 && col < numCols;
    }

    static int cellToIdx(int row, int col) {
        return numCols*row + col;
    }

    static class ConnectedComponents {
        private List<Integer>[] graph;

        private boolean[] marked;
        private int[] id;
        private int[] ccSize;
        private int count;

        private int[] tempSize;
        private Deque<Integer> tempStack = new ArrayDeque<>();

        public ConnectedComponents(List<Integer>[] g) {
            graph = g;
            int size = graph.length;
            marked = new boolean[size];
            id = new int[size];
            tempSize = new int[size];
            for (int vertex = 0; vertex < size; vertex++) {

                if (!marked[vertex] && emptyCell.get(vertex)) {

                    iterativeDfs(vertex);
                    count++;
                }
            }

            ccSize = new int[count];
            for (int cc = 0; cc < count; cc++) {
                ccSize[cc] = tempSize[cc];
            }
            tempSize = null;
            tempStack = null;
        }

        private void iterativeDfs(int src) {
            tempStack.push(src);
            marked[src] = true;
            while (!tempStack.isEmpty()) {
                int cur = tempStack.pop();
                id[cur] = count;
                tempSize[count]++;
                for (int neighbor : graph[cur]) {
                    if (!marked[neighbor]) {
                        marked[neighbor] = true;
                        tempStack.push(neighbor);
                    }
                }
            }
        }

        private void dfs(int cur) {
            marked[cur] = true;
            id[cur] = count;
            tempSize[count]++;
            for (int neighbor : graph[cur]) {
                if (!marked[neighbor]) {
                    dfs(neighbor);
                }
            }
        }

        private boolean connected(int v, int w) {
            return id[v] == id[w];
        }
    }

