		for(int i = 0; i < n; i++)
		{
			for(int j = 0; j < m; j++)
			{
				if(memo[i][j] == -1 && grid[i].charAt(j) != '*')
				{
					flood(i, j);
				}
			}
		}
		for(int i = 0; i < n; i++)
		{
			for(int j = 0; j < m; j++)
			{
				if(grid[i].charAt(j) == '.') out.print(".");
				else
				{
					TreeSet<Integer> ts = new TreeSet<Integer>();
					for(int k = 0; k < 4; k++)
					{
						int ni = i+dr[k];
						int nj = j+dc[k];
						if(0 <= ni && ni < n && 0 <= nj && nj < m && grid[ni].charAt(nj) == '.')
						{
							ts.add(memo[ni][nj]);
						}
					}
					int ret = 1;
					for(int v : ts)
					{
