	}
	void flood(int r, int c)
	{
		ArrayDeque<Integer> q = new ArrayDeque<Integer>();
		q.add(r);
		q.add(c);
		memo[r][c] = r*m+c;
		while(q.size() > 0)
		{
			int cr = q.poll();
			int cc = q.poll();
			values[memo[r][c]]++;
			for(int i = 0; i < 4; i++)
			{
				int nr = cr+dr[i];
				int nc = cc+dc[i];
				if(0 <= nr && nr < n && 0 <= nc && nc < m && grid[nr].charAt(nc) == '.' && memo[nr][nc] == -1)
				{
					q.add(nr);
					q.add(nc);
					memo[nr][nc] = r*m+c;
				}
			}
		}
	}
