class Csolver {

    public Csolver(CIO io) {
        int n = io.nextInt();
        int m = io.nextInt();
        boolean[][] t = new boolean[n+3][m+3];
        for (int y=1; y<=n; y++) {
            String row = io.next();
            for (int x=1; x<=m; x++) {
                t[y][x] = (row.charAt(x-1) == '.');
            }
        }
        int currentSet = 1;
        int[][] set = new int[n+3][m+3];
        int[] membersInSet = new int[500001];
        boolean[][] visited = new boolean[n+3][m+3];
        for (int y=1; y<=n; y++) {
            for (int x=1; x<=m; x++) {
                if (!t[y][x]) continue;
                if (visited[y][x]) continue;
                ArrayDeque<Integer> neighbors = new ArrayDeque<>();
                neighbors.add(y*1002+x);
                while (!neighbors.isEmpty()) {
                    int neighbor = neighbors.pollFirst();
                    int n_y = neighbor / 1002;
                    int n_x = neighbor % 1002;
                    if (!t[n_y][n_x]) continue;
                    if (visited[n_y][n_x]) continue;
                    visited[n_y][n_x] = true;
                    set[n_y][n_x] = currentSet;
                    membersInSet[currentSet]++;
                    neighbors.addLast((n_y + 1) * 1002 + n_x);
                    neighbors.addLast((n_y - 1) * 1002 + n_x);
                    neighbors.addLast((n_y) * 1002 + n_x + 1);
                    neighbors.addLast((n_y) * 1002 + n_x - 1);
                }
                currentSet++;
            }
        }
        StringBuilder ans = new StringBuilder();
        for (int y=1; y<=n; y++) {
            for (int x=1; x<=m; x++) {
                if (t[y][x]) {
                    ans.append('.');
                    continue;
                }
                int countMembers = 1; 
                HashSet<Integer> neighboringSets = new HashSet<>();
                neighboringSets.add(set[y-1][x]);
                neighboringSets.add(set[y+1][x]);
                neighboringSets.add(set[y][x+1]);
                neighboringSets.add(set[y][x-1]);
                for (int setti : neighboringSets) {
                    countMembers += membersInSet[setti];
                }
                ans.append(countMembers % 10);
            }
            ans.append("\n");
        }
        io.println(ans.toString());
    }

    int hash(int y, int x) {
        return 1001*y + x;
    }

}

class CIO extends PrintWriter {
    private InputStreamReader r;
    private static final int BUFSIZE = 1 << 15;
    private char[] buf;
    private int bufc;
    private int bufi;
    private StringBuilder sb;

    public CIO() {
            super(new BufferedOutputStream(System.out));
            r = new InputStreamReader(System.in);

            buf = new char[BUFSIZE];
            bufc = 0;
            bufi = 0;
            sb = new StringBuilder();
    }

    private void fillBuf() throws IOException {
            bufi = 0;
            bufc = 0;
            while(bufc == 0) {
                    bufc = r.read(buf, 0, BUFSIZE);
                    if(bufc == -1) {
                            bufc = 0;
                            return;
                    }
            }
    }

    private boolean pumpBuf() throws IOException {
            if(bufi == bufc) {
                    fillBuf();
            }
            return bufc != 0;
    }

    private boolean isDelimiter(char c) {
            return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
    }

    private void eatDelimiters() throws IOException {
            while(true) {
                    if(bufi == bufc) {
                            fillBuf();
                            if(bufc == 0) throw new RuntimeException("IO: Out of input.");
                    }

                    if(!isDelimiter(buf[bufi])) break;
                    ++bufi;
            }
    }

    public String next() {
            try {
                    sb.setLength(0);

                    eatDelimiters();
                    int start = bufi;

                    while(true) {
                            if(bufi == bufc) {
                                    sb.append(buf, start, bufi - start);
                                    fillBuf();
                                    start = 0;
                                    if(bufc == 0) break;
                            }

                            if(isDelimiter(buf[bufi])) break;
                            ++bufi;
                    }

                    sb.append(buf, start, bufi - start);

                    return sb.toString();
            } catch(IOException e) {
                    throw new RuntimeException("IO.next: Caught IOException.");
            }
    }

    public int nextInt() {
            try {
                    int ret = 0;

                    eatDelimiters();

                    boolean positive = true;
                    if(buf[bufi] == '-') {
                            ++bufi;
                            if(!pumpBuf()) throw new RuntimeException("IO.nextInt: Invalid int.");
                            positive = false;
                    }

                    boolean first = true;
                    while(true) {
                            if(!pumpBuf()) break;
                            if(isDelimiter(buf[bufi])) {
                                    if(first) throw new RuntimeException("IO.nextInt: Invalid int.");
                                    break;
                            }
                            first = false;

                            if(buf[bufi] >= '0' && buf[bufi] <= '9') {
                                    if(ret < -214748364) throw new RuntimeException("IO.nextInt: Invalid int.");
                                    ret *= 10;
                                    ret -= (int)(buf[bufi] - '0');
                                    if(ret > 0) throw new RuntimeException("IO.nextInt: Invalid int.");
                            } else {
                                    throw new RuntimeException("IO.nextInt: Invalid int.");
                            }

                            ++bufi;
                    }

                    if(positive) {
                            if(ret == -2147483648) throw new RuntimeException("IO.nextInt: Invalid int.");
                            ret = -ret;
                    }

                    return ret;
            } catch(IOException e) {
                    throw new RuntimeException("IO.nextInt: Caught IOException.");
            }
    }

    public long nextLong() {
            try {
                    long ret = 0;

                    eatDelimiters();

                    boolean positive = true;
                    if(buf[bufi] == '-') {
                            ++bufi;
                            if(!pumpBuf()) throw new RuntimeException("IO.nextLong: Invalid long.");
                            positive = false;
                    }

                    boolean first = true;
                    while(true) {
                            if(!pumpBuf()) break;
                            if(isDelimiter(buf[bufi])) {
                                    if(first) throw new RuntimeException("IO.nextLong: Invalid long.");
                                    break;
                            }
                            first = false;

                            if(buf[bufi] >= '0' && buf[bufi] <= '9') {
                                    if(ret < -922337203685477580L) throw new RuntimeException("IO.nextLong: Invalid long.");
                                    ret *= 10;
                                    ret -= (long)(buf[bufi] - '0');
                                    if(ret > 0) throw new RuntimeException("IO.nextLong: Invalid long.");
                            } else {
                                    throw new RuntimeException("IO.nextLong: Invalid long.");
                            }

                            ++bufi;
                    }

                    if(positive) {
                            if(ret == -9223372036854775808L) throw new RuntimeException("IO.nextLong: Invalid long.");
                            ret = -ret;
                    }

                    return ret;
            } catch(IOException e) {
                    throw new RuntimeException("IO.nextLong: Caught IOException.");
            }
    }

    public double nextDouble() {
            return Double.parseDouble(next());
    }

}

