public class Labirinth2 {
    static int n, m;
    static boolean matrix[][];
    static int matrComp[][];
    static int matrSqare[];
    static StringBuilder stringBuilder = new StringBuilder();


    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter printWriter = new PrintWriter(System.out);
        String s = br.readLine();
        String[] split = s.split(" ");
        n = Integer.parseInt(split[0]);
        m = Integer.parseInt(split[1]);
        matrix = new boolean[n][m];
        matrComp=new int[n][m];
        matrSqare=new int[n*m+1];

        for (int i = 0; i < n; i++) {
            String line = br.readLine();

            for (int j = 0; j < m; j++) {
                if (line.charAt(j) =='*') {
                    matrix[i][j] = true;
                } else {
                    matrix[i][j] = false;
                }
            }
        }


        int k=1;
        for(int i=0;i<n;i++){
            for (int j = 0; j < m; j++) {
                if(matrix[i][j]){

                    matrComp[i][j]=-1;
                    continue;
                }
                if(matrComp[i][j]==0) {
                    dfs(i, j, k);
                    k++;
                }
            }
        }


        findComps2();
        printWriter.println(stringBuilder);
        printWriter.close();

    }


    static void dfs(int i, int j, int k){

        if(i<0||i>=n||j<0||j>=m) return;

        if(matrix[i][j]) return;

        if(matrComp[i][j]!=0) return;
        matrComp[i][j]=k;
        matrSqare[k]++;
        dfs(i+1,j,k);
        dfs(i-1,j,k);
        dfs(i,j+1,k);
        dfs(i,j-1,k);

    }


    static void findComps2() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {


                if (!matrix[i][j] ) {
                    stringBuilder.append(".");
                    continue;
                }
                int s1[]=new int[4];
                long S=1;
                if(i>0) {
                    s1[0] = matrComp[i - 1][j];
                    if(s1[0]!=-1){
                        S+=matrSqare[s1[0]];
                        S=S%10;
                    }
                }
                if(j>0) {
                    s1[1] = matrComp[i][j-1];
                    if(s1[1]!=-1 && s1[1]!=s1[0]){
                        S+=matrSqare[s1[1]];
                        S=S%10;
                    }
                }

                if(i<n-1) {
                    s1[2] = matrComp[i+1][j];
                    if(s1[2]!=-1 && s1[2]!=s1[0] && s1[2]!=s1[1]){
                        S+=matrSqare[s1[2]];
                        S=S%10;
                    }
                }
                if(j<m-1) {
                    s1[3] = matrComp[i][j+1];
                    if(s1[3]!=-1 && s1[3]!=s1[0] && s1[3]!=s1[1] && s1[3]!=s1[2]){
                        S+=matrSqare[s1[3]];
                        S=S%10;
                    }
                }


                stringBuilder.append(S);

            }
            stringBuilder.append("\n");
        }
    }



    static void findComps() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {


                if (matrix[i][j] ) {
                    stringBuilder.append(".");
                    continue;
                }
                int comps = search(i, j);
                stringBuilder.append(comps);

            }
            stringBuilder.append("\n");
        }
    }

    static int search(int i, int j) {
        int count = 0;
        boolean[][] visited = new boolean[n][m];
        Stack<int[]> stack = new Stack();
        stack.add(new int[]{i, j});
        while (!stack.empty()) {

            int[] pop = stack.pop();
            int row = pop[0];
            int col = pop[1];
            if (visited[row][col] == false) {
                visited[row][col] = true;
                count++;
                if ((row - 1 >= 0) && (matrix[row - 1][col] == false)) {
                    stack.add(new int[]{row - 1, col});
                }
                if ((row <= n - 2) && (matrix[row + 1][col] == false)) {
                    stack.add(new int[]{row + 1, col});
                }
                if ((col - 1 >= 0) && (matrix[row][col - 1] == false)) {
                    stack.add(new int[]{row, col - 1});
                }
                if ((col <= m - 2) && (matrix[row][col + 1] == false)) {
                    stack.add(new int[]{row, col + 1});
                }
            }


        }
        if (count > 10) count = count % 10;
        if (count < 0) count = count + 10;
        return count;
    }

}

