public class F
{

    Reader in;
    PrintWriter out;
    int i = 0, j = 0;
    void solve()
    {


        int n = in.nextInt(), m = in.nextInt();
        char[][] grid = new char[n+2][m+2];
        Arrays.fill(grid[0], '#');
        Arrays.fill(grid[grid.length-1], '#');
        for (i = 1; i <= n; i++)
        {
            grid[i] = ("#" + in.next() + "#").toCharArray();
        }
        int curCount = 0;
        int curComp = 1;
        HashMap<Integer, Integer> vals = new HashMap<Integer, Integer>();
        vals.put(0, 0);
        int[][] compID = new int[n+2][m+2];
        ArrayList<Integer> obY = new ArrayList<Integer>();
        ArrayList<Integer> obX = new ArrayList<Integer>();
        for (i = 0; i < n+2; i++)
        {
            for (j = 0; j < m+2; j++)
            {
                if (grid[i][j] == '#')
                {
                    compID[i][j] = 0;
                }
                else if (grid[i][j] == '*')
                {
                    obY.add(i);
                    obX.add(j);
                }
                else
                {
                    if (compID[i][j] == 0)
                    {
                        compID[i][j] = curComp;
                        curCount = 1;
                        ArrayDeque<Integer> ys = new ArrayDeque<Integer>();
                        ArrayDeque<Integer> xs = new ArrayDeque<Integer>();
                        ys.addLast(i);
                        xs.addLast(j);
                        while (!ys.isEmpty())
                        {
                            int curY = ys.removeFirst();
                            int curX = xs.removeFirst();
                            if (grid[curY+1][curX] == '.' && compID[curY+1][curX] == 0)
                            {
                                compID[curY+1][curX] = curComp;
                                curCount++;
                                ys.addLast(curY+1);
                                xs.addLast(curX);
                            }
                            if (grid[curY-1][curX] == '.' && compID[curY-1][curX] == 0)
                            {
                                compID[curY-1][curX] = curComp;
                                curCount++;
                                ys.addLast(curY-1);
                                xs.addLast(curX);
                            }
                            if (grid[curY][curX+1] == '.' && compID[curY][curX+1] == 0)
                            {
                                compID[curY][curX+1] = curComp;
                                curCount++;
                                ys.addLast(curY);
                                xs.addLast(curX+1);
                            }
                            if (grid[curY][curX-1] == '.' && compID[curY][curX-1] == 0)
                            {
                                compID[curY][curX-1] = curComp;
                                curCount++;
                                ys.addLast(curY);
                                xs.addLast(curX-1);
                            }
                        }
                        vals.put(curComp, curCount);
                        curComp++;
                    }
                }
            }
        }
        for (i = 0; i < obY.size(); i++)
        {
            HashSet<Integer> sur = new HashSet<Integer>();
            sur.add(compID[obY.get(i)+1][obX.get(i)]);
            sur.add(compID[obY.get(i)-1][obX.get(i)]);
            sur.add(compID[obY.get(i)][obX.get(i)+1]);
            sur.add(compID[obY.get(i)][obX.get(i)-1]);
            long sum = 1;
            for (Integer z : sur)
                sum += vals.get(z);
            sum %= 10;
            grid[obY.get(i)][obX.get(i)] = (char)('0' + sum);
        }
        for (i = 1; i <= n; i++)
        {
            for (j = 1; j <= m; j++)
            {
                out.print(grid[i][j]);
            }
            out.println();
        }








    }
    void runIO()
    {
        in = new Reader();
        out = new PrintWriter(System.out, false);
        solve();
        out.close();
    }

    public static void main(String[] args)
    {
        new F().runIO();
    }



    static class Reader
    {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public Reader()
        {
            din = new DataInputStream(System.in);

            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }



        public final String next()
        {
            int c = read();
            while (isSpaceChar(c))
            {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do
            {
                res.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c)
        {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt()
        {
            int ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do
            {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg)
                return -ret;
            return ret;
        }

        public long nextLong()
        {
            long ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do
            {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg)
                return -ret;
            return ret;
        }

        public double nextDouble()
        {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do
            {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (c == '.')
                while ((c = read()) >= '0' && c <= '9')
                    ret += (c - '0') / (div *= 10);
            if (neg)
                return -ret;
            return ret;
        }

        public int[] readIntArray(int size)
        {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++)
                arr[i] = nextInt();
            return arr;
        }

        public long[] readLongArray(int size)
        {
            long[] arr = new long[size];
            for (int i = 0; i < size; i++)
                arr[i] = nextInt();
            return arr;
        }

        private void fillBuffer()
        {
            try
            {
                bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            }
            catch (IOException e)
            {

            }

            if (bytesRead == -1)
                buffer[0] = -1;
        }

        private byte read()
        {
            if (bufferPointer == bytesRead)
                fillBuffer();
            return buffer[bufferPointer++];
        }
    }
}

