                    a2[0] = i-1 >= 0 ? a[i-1][j] : 0;
                    a2[1] = j-1 >= 0 ? a[i][j-1] : 0;
                    a2[2] = i+1 < n ? a[i+1][j] : 0;
                    a2[3] = j+1 < m ? a[i][j+1] : 0;


                    sum += answers[a2[0]];
                    if (a2[1] != a2[0]) sum += answers[a2[1]];
                    if (a2[2] != a2[1] && a2[2] != a2[0]) sum += answers[a2[2]];
                    if (a2[3] != a2[2] && a2[3] != a2[1] && a2[3] != a2[0]) sum += answers[a2[3]];

                    outp[i][j] = (char)((sum % 10) + '0');
                }
