    static int rec(char[][] d, int[][] a, int ans, int x, int y) {
        if (x < 0 || x == d.length || y < 0 || y == d[0].length) return 0;
        if (a[x][y] != 0) return 0;

        if (d[x][y] == '*') return 0;

        a[x][y] = ans;

        return 1 + rec(d,a,ans,x+1,y) + rec(d,a,ans,x,y+1) + rec(d,a,ans,x-1,y) + rec(d,a,ans,x,y-1);
    }

