public class P616C
{
	private static PrintWriter pw;
	private static char[][] maze;
	private static int ROWS;
	private static int COLS;
	private static boolean[][] checked;
	private static Cell[][] grid;
	private static int CURRENT_ID;
	private static int[] dc = { 1, 0, -1, 0 };
	private static int[] dr = { 0, 1, 0, -1 };
	private static ArrayList<Integer> groups = new ArrayList<Integer>();

	public static void main(String[] args) throws IOException
	{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		pw = new PrintWriter(System.out);
		String dim = br.readLine();
		int rows = Integer.parseInt(dim.split("\\s+")[0]);
		int cols = Integer.parseInt(dim.split("\\s+")[1]);
		ROWS = rows;
		COLS = cols;
		maze = new char[rows][cols];
		checked = new boolean[ROWS][COLS];
		grid = new Cell[ROWS][COLS];

		for (int i = 0; i < rows; i++)
		{
			maze[i] = br.readLine().toCharArray();
		}
		findGroups();
		getTotals();
		printMaze();
		pw.flush();
	}
	private static void findGroups()
	{
		CURRENT_ID = 0;
		Queue<Cell> q = new LinkedList<Cell>();
		q.add(new Cell(0, 0));
		int t = 0;
		while (!q.isEmpty())
		{
			Cell cell = q.poll();
			if (checked[cell.row][cell.column])
				continue;
			if (maze[cell.row][cell.column] != '.')
			{
				checked[cell.row][cell.column] = true;
				for (int i = 0; i < 4; i++)
				{
					int newRow = cell.row + dr[i];
					int newCol = cell.column + dc[i];
					if (invalid(newRow, newCol))
						continue;
					q.add(new Cell(newRow, newCol));
				}
				continue;
			}
			Queue<Cell> groupQ = new LinkedList<Cell>();
			cell.groupNum = CURRENT_ID;
			groupQ.add(cell);
			checked[cell.row][cell.column] = true;
			grid[cell.row][cell.column] = cell;
			int count = 0;
			while (!groupQ.isEmpty())
			{
				count++;
				Cell c = groupQ.poll();
				for (int i = 0; i < 4; i++)
				{
					int newRow = c.row + dr[i];
					int newCol = c.column + dc[i];
					if (invalid(newRow, newCol))
						continue;
					if (maze[newRow][newCol] != '.')
					{
						q.add(new Cell(newRow, newCol));
						continue;
					}
					Cell newCell = new Cell(newRow, newCol, CURRENT_ID);
					grid[newRow][newCol] = newCell;
					checked[newRow][newCol] = true;
					groupQ.add(newCell);
				}
			}
			groups.add(count);
			CURRENT_ID++; 
		}
	}
	private static boolean invalid(int newRow, int newCol)
	{

		if (newRow < 0 || newCol < 0 || newRow >= ROWS || newCol >= COLS)
			return true;

		if (checked[newRow][newCol])
			return true;
		return false;
	}
	private static void getTotals()
	{
		int[] adjacentGroups = new int[4];
		for (int i = 0; i < ROWS; i++)
		{
			for (int j = 0; j < COLS; j++)
			{
				if (maze[i][j] == '*')
				{
					Arrays.fill(adjacentGroups, -1);

					for (int a = 0; a < 4; a++)
					{
						int newRow = i + dr[a];
						int newCol = j + dc[a];
						if (newRow < 0 || newCol < 0 || newRow >= ROWS || newCol >= COLS)
							continue;
						if (maze[newRow][newCol] != '.')
							continue;
						adjacentGroups[a] = grid[newRow][newCol].groupNum;
					}
					int total = 1;
					Outer:
					for (int a = 0; a < 4; a++)
					{
						if (adjacentGroups[a] == -1)
							continue;
						for (int b = 0; b < a; b++)
							if (adjacentGroups[a] == adjacentGroups[b]) 
								continue Outer;
						total += groups.get(adjacentGroups[a]);
					}
					maze[i][j] = (char)(total % 10);
				}
			}
		}
	}
	private static void printMaze()
	{
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < ROWS; i++)
		{
			for (int j = 0; j < COLS; j++)
			{
				if (maze[i][j] == '.')
					sb.append('.');
				else
					sb.append((char)(maze[i][j] + '0'));
			}
			sb.append("\n");
		}
		System.out.println(sb);
	}

	static class Cell
	{
		int row, column;
		int groupNum = 0;
		public Cell(int r, int c)
		{
			row = r;
			column = c;
		}
		public Cell(int r, int c, int group)
		{
			row = r;
			column = c;
			groupNum = group;
		}
		public String toString()
		{
			return row + " " + column;
		}
	}
}

import java.io.BufferedReader;
