import java.util.regex.Pattern;
import java.util.stream.Collectors;

public class Main {
    public void exec() {
        int n = stdin.nextInt();
        int m = stdin.nextInt();
        String[] s = stdin.nextStringArray(n);

        int[][] diffs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

        Tuple[][] parent = new Tuple[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s[i].charAt(j) == '*') {
                    continue;
                }

                Tuple root = new Tuple(i, j);
                Deque<Tuple> stack = new ArrayDeque<>();
                stack.add(root);
                while (!stack.isEmpty()) {
                    Tuple current = stack.removeLast();
                    int x = current.x;
                    int y = current.y;
                    if (0 <= x && x < n && 0 <= y && y < m && s[x].charAt(y) == '.' && parent[x][y] == null) {
                        root.size++;
                        parent[x][y] = root;
                        for (int[] diff : diffs) {
                            stack.add(new Tuple(x + diff[0], y + diff[1]));
                        }
                    }
                }
            }
        }

        String[][] t = new String[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s[i].charAt(j) == '.') {
                    t[i][j] = ".";
                } else {
                    Set<Tuple> used = new HashSet<>();
                    int count = 1;
                    for (int[] diff : diffs) {
                        int x = i + diff[0];
                        int y = j + diff[1];
                        if (0 <= x && x < n && 0 <= y && y < m && s[x].charAt(y) == '.') {
                            Tuple root = parent[x][y];
                            if (!used.contains(root)) {
                                count += root.size;
                                used.add(root);
                            }
                        }
                    }
                    t[i][j] = Integer.toString(count%10);
                }
            }
        }

        for (String[] row : t) {
            stdout.println(String.join("", row));
        }
    }

    public class Tuple {
        public int x;
        public int y;
        public int size;
        public Tuple(int x, int y) {
            this.x = x;
            this.y = y;
            this.size = 0;
        }
        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
        @Override
        public boolean equals(Object obj) {
            if (obj instanceof Tuple) {
                Tuple other = (Tuple) obj;
                return this.x == other.x && this.y == other.y;
            }
            return false;
        }
    }


    private static final Stdin stdin = new Stdin();
    private static final Stdout stdout = new Stdout();

    public static void main(String[] args) {
        try {
            new Main().exec();
        } finally {
            stdout.flush();
        }
    }

    public static class Stdin {
        private BufferedReader stdin;
        private Deque<String> tokens;
        private Pattern delim;

        public Stdin() {
            stdin = new BufferedReader(new InputStreamReader(System.in));
            tokens = new ArrayDeque<>();
            delim = Pattern.compile(" ");
        }

        public String nextString() {
            try {
                if (tokens.isEmpty()) {
                    String line = stdin.readLine();
                    if (line == null) {
                        throw new UncheckedIOException(new EOFException());
                    }
                    delim.splitAsStream(line).forEach(tokens::addLast);
                }
                return tokens.pollFirst();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public double nextDouble() {
            return Double.parseDouble(nextString());
        }

        public long nextLong() {
            return Long.parseLong(nextString());
        }

        public String[] nextStringArray(int n) {
            String[] a = new String[n];
            for (int i = 0; i < n; i++) a[i] = nextString();
            return a;
        }

        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        public double[] nextDoubleArray(int n) {
            double[] a = new double[n];
            for (int i = 0; i < n; i++) a[i] = nextDouble();
            return a;
        }

        public long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = nextLong();
            return a;
        }
    }

    public static class Stdout {
        private PrintWriter stdout;

        public Stdout() {
            stdout =  new PrintWriter(System.out, false);
        }

        public void printf(String format, Object ... args) {
            String line = String.format(format, args);
            if (line.endsWith(System.lineSeparator())) {
                stdout.print(line);
            } else {
                stdout.println(line);
            }
        }

        public void println(Object o) {
            stdout.println(o);
        }

        public void debug(Object ... objs) {
            String line = Arrays.stream(objs).map(this::deepToString).collect(Collectors.joining(" "));
            stdout.printf("DEBUG: %s%n", line);
        }

        private String deepToString(Object o) {
            if (o == null) {
                return "null";
            }

            Class<?> clazz = o.getClass();


            if (clazz.isArray()) {
                int len = Array.getLength(o);
                String[] tokens = new String[len];
                for (int i = 0; i < len; i++) {
                    tokens[i] = deepToString(Array.get(o, i));
                }
                return "{" + String.join(",", tokens) + "}";
            }


            if (Arrays.stream(clazz.getDeclaredMethods()).anyMatch(method -> method.getName().equals("toString") && method.getParameterCount() == 0)) {
                return Objects.toString(o);
            }


            try {
                List<String> tokens = new ArrayList<>();
                for (Field field : clazz.getFields()) {
                    String token = String.format("%s=%s", field.getName(), deepToString(field.get(o)));
                    tokens.add(token);
                }
                return String.format("%s:[%s]", clazz.getName(), String.join(",", tokens));
            } catch (IllegalAccessException e) {
                throw new IllegalArgumentException(e);
            }
        }

        public void flush() {
            stdout.flush();
        }
    }
}

import java.io.*;
import java.math.*;
import java.util.*;

public class TheLabyrinth {
	static PrintWriter pw;

	static class Pair {
		int f, s;

		Pair(int f, int s) {
			this.f = f;
			this.s = s;
		}
	}

	static class FastReader {
		private InputStream mIs;
		private byte[] buf = new byte[1024];
		private int curChar, numChars;

		public FastReader() {
			this(System.in);
		}

		public FastReader(InputStream is) {
			mIs = is;
		}

		public int read() {
			if (numChars == -1)
				throw new InputMismatchException();
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = mIs.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (numChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		public String nextLine() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isEndOfLine(c));
			return res.toString();
		}

		public String next() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isSpaceChar(c));
			return res.toString();
		}

		public long l() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = read();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			} while (!isSpaceChar(c));
			return res * sgn;
		}

		public int i() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = read();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			} while (!isSpaceChar(c));
			return res * sgn;
		}

		public double d() throws IOException {
			return Double.parseDouble(next());
		}

		public boolean isSpaceChar(int c) {
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		public boolean isEndOfLine(int c) {
			return c == '\n' || c == '\r' || c == -1;
		}

		public void scanIntArr(int[] arr) {
			for (int li = 0; li < arr.length; ++li)
				arr[li] = i();
		}

		public void scanIntIndexArr(int[] arr) {
			for (int li = 0; li < arr.length; ++li) {
				arr[li] = i() - 1;
			}
		}

		public void printIntArr(int[] arr) {
			for (int li = 0; li < arr.length; ++li)
				pw.print(arr[li] + " ");
			pw.println();
		}

		public void printLongArr(long[] arr) {
			for (int li = 0; li < arr.length; ++li)
				pw.print(arr[li] + " ");
			pw.println();
		}

		public void scanLongArr(long[] arr) {
			for (int i = 0; i < arr.length; ++i) {
				arr[i] = l();
			}
		}

		public void shuffle(int[] arr) {
			for (int i = arr.length; i > 0; --i) {
				int r = (int) (Math.random() * i);
				int temp = arr[i - 1];
				arr[i - 1] = arr[r];
				arr[r] = temp;
			}
		}

		public int findMax(int[] arr) {
			return Arrays.stream(arr).max().getAsInt();
		}
	}

	public static boolean valid(int r, int c, int n, int m) {
		return r >= 0 && r < n && c >= 0 && c < m;
	}

	public static void main(String[] args) throws IOException {
		FastReader fr = new FastReader();
		pw = new PrintWriter(System.out);
		int i, j, n, m, temp, t, idct = 0, ni, nj;
		String arr[] = new String[1000];
		Pair[][] dp = new Pair[1000][1000];
		Stack<Pair> st = new Stack<>();
		Queue<Pair> q = new LinkedList<>();
		boolean[][] vis = new boolean[1000][1000];
		int xx[] = { 0, 0, 1, -1 };
		int yy[] = { 1, -1, 0, 0 };
		n = fr.i();
		m = fr.i();
		for (i = 0; i < n; i++)
			arr[i] = fr.nextLine();
		for (boolean[] row : vis)
			Arrays.fill(row, false);

		for (i = 0; i < n; i++) {
			for (j = 0; j < m; j++) {
				if (arr[i].charAt(j) == '*')
					continue;
				if (vis[i][j] == false) {
					temp = 0;
					st.clear();
					q.clear();
					vis[i][j] = true;
					++idct;
					st.push(new Pair(i, j));
					++temp;
					q.add(new Pair(i, j));
					while (!q.isEmpty()) {
						int ti, tj;
						ti = q.peek().f;
						tj = q.peek().s;
						q.remove();
						for (int k = 0; k < 4; k++) {
							ni = ti + xx[k];
							nj = tj + yy[k];
							if (valid(ni, nj, n, m) && arr[ni].charAt(nj) == '.' && !vis[ni][nj]) {
								vis[ni][nj] = true;
								st.push(new Pair(ni, nj));
								q.add(new Pair(ni, nj));
								++temp;
							}
						}
					}
					while (!st.empty()) {
						ni = st.peek().f;
						nj = st.peek().s;
						dp[ni][nj] = new Pair(idct, temp);
						st.pop();
					}
				}
			}
		}
		Set<Integer> unique = new HashSet<>();
		for(i=0;i<n;i++) {
			StringBuilder sb = new StringBuilder();
			for(j=0;j<m;j++) {
				if (arr[i].charAt(j) == '.') {
					sb.append(".");
					continue;
				}
				unique.clear();
				temp = 1;
				for (int k = 0; k < 4; k++) {
					ni = i + xx[k];
					nj = j + yy[k];
					if (valid(ni, nj, n, m) && arr[ni].charAt(nj) == '.' && !unique.contains(dp[ni][nj].f)) {
						unique.add(dp[ni][nj].f);
						temp += dp[ni][nj].s;
					}
				}

				sb.append(temp % 10);
			}
			pw.println(sb);
		}
		pw.flush();
		pw.close();
	}
}

import java.util.*;
import java.io.*;
public class C
{
	public static void main(String[] args) throws Exception
	{
		FastScanner in = new FastScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		int n = in.nextInt();
		int m = in.nextInt();

		int[][] grid = new int[n][m];
		for(int x = 0; x < n; x++)
		{
			String line = in.next();
			for(int y = 0; y < m; y++)
			{
				if(line.charAt(y) == '*')
				{
					grid[x][y] = -1;
				}
			}
		}

		int[] dr = {1, 0, -1, 0};
		int[] dc = {0, 1, 0, -1};

		int[] size = new int[n * m + 1];
		int index = 1;
		for(int z = 0; z < grid.length; z++)
		{
			for(int a = 0; a < grid[0].length; a++)
			{
				if(grid[z][a] == 0)
				{
					grid[z][a] = index;

					ArrayDeque<Integer> queue = new ArrayDeque<Integer>();
					queue.add(z);
					queue.add(a);

					int currentSize = 0;
					while(queue.size() > 0)
					{
						int row = queue.remove();
						int col = queue.remove();

						currentSize++;

						for(int b = 0; b < dr.length; b++)
						{
							int nr = row + dr[b];
							int nc = col + dc[b];

							if(nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length && grid[nr][nc] == 0)
							{
								grid[nr][nc] = index;
								queue.add(nr);
								queue.add(nc);
							}
						}
					}

					size[index] = currentSize;
					index++;
				}
			}
		}

		char[][] result = new char[n][m];
		for(int c = 0; c < grid.length; c++)
		{
			for(int d = 0; d < grid[0].length; d++)
			{
				if(grid[c][d] == -1)
				{
					int count = 1;

					HashSet<Integer> hs = new HashSet<Integer>();
					for(int e = 0; e < dr.length; e++)
					{
						int nr = c + dr[e];
						int nc = d + dc[e];

						if(nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length && grid[nr][nc] != -1 && !hs.contains(grid[nr][nc]))
						{
							hs.add(grid[nr][nc]);
							count += size[grid[nr][nc]];
						}
					}

					result[c][d] = (char)('0' + (count % 10));
				}
				else
				{
					result[c][d] = '.';
				}
			}
		}

		for(int f = 0; f < result.length; f++)
		{
			out.println(new String(result[f]));
		}

		out.close();
	}

	static class FastScanner
	{
		BufferedReader br;
		StringTokenizer st;

		public FastScanner(InputStream input)
		{
			br = new BufferedReader(new InputStreamReader(input));
			st = new StringTokenizer("");
		}

		public String next() throws IOException
		{
			if(st.hasMoreTokens())
			{
				return st.nextToken();
			}
			else
			{
				st = new StringTokenizer(br.readLine());
				return next();
			}
		}

		public int nextInt() throws IOException
		{
			return Integer.parseInt(next());
		}
	}
}

