import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;

public class Main {

	private final static int DIRECTIONS = 4;
	private final static int[] dx = {-1, 0, 1, 0};
	private final static int[] dy = {0, 1, 0, -1};


	private static int fill(int i, int j, int[][] regions, int color) {
		regions[i][j] = color;

		int discovered = 1;
		for (int d = 0; d < DIRECTIONS; ++d) {
			int adji = i + dx[d];
			int adjj = j + dy[d];

			if (adji >= 0 && adji < regions.length 
					&& adjj >= 0 && adjj < regions[0].length
					&& regions[adji][adjj] == 0) {
				discovered += fill(adji, adjj, regions, color);
			}
		}

		return discovered;
	}


	private static void getRegions(int n, int m, String[] matrix, 
			int[][] regions, Map<Integer, Integer> regionSize) {

		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < m; ++j) {
				if (matrix[i].charAt(j) == '*') {
					regions[i][j] = -1;
				}
			}
		}

		int color = 0;

		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < m; ++j) {
				if (regions[i][j] == 0) {
					++color;
					regionSize.put(color, fill(i, j, regions, color));
				}
			}
		}
	}

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt(), m = sc.nextInt();
		sc.nextLine();
		String[] matrix = new String[n];
		for (int i = 0; i < n; ++i) {
			matrix[i] = sc.nextLine();
		}

		int[][] regions = new int[n][m];
		Map<Integer, Integer> regionSize = new HashMap<Integer, Integer>();
		getRegions(n, m, matrix, regions, regionSize);

		char[][] output = new char[n][m];
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < m; ++j) {
				if (regions[i][j] == -1) {
					int sum = 1;
					Set<Integer> added = new HashSet<Integer>();

					for (int d = 0; d < DIRECTIONS; ++d) {
						int adji = i + dx[d];
						int adjj = j + dy[d];

						if (adji >= 0 && adji < regions.length 
								&& adjj >= 0 && adjj < regions[0].length
								&& regions[adji][adjj] != -1) {
							if (!added.contains(regions[adji][adjj])) {
								added.add(regions[adji][adjj]);
								sum += regionSize.get(regions[adji][adjj]);
							}
						}
					}

					output[i][j] = (char) (sum % 10 + '0');
				} else {
					output[i][j] = '.';
				}
			}
		}


		for (int i = 0; i < n; ++i) {
			System.out.println(output[i]);
		}
	}
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class CF5C {
    private static boolean debug = false;

    private static int N, M;
    private static boolean[][] A;

    private static void solveProblem(InputStream instr) throws Exception {
        InputReader sc = new InputReader(instr);
        int testCount = 1;
        if (debug) {
            testCount = sc.nextInt();
        }

        for (int t = 1; t <= testCount; t++) {
            printDebug("------ " + t + " ------");
            N = sc.nextInt();
            M = sc.nextInt();
            A = new boolean[N + 2][M + 2];
            for(int i = 0; i < N; i++){
                char[] str = sc.next().toCharArray();
                for(int j = 0; j < M; j++){
                    A[i+1][j+1] = (str[j] == '.');
                }
            }
            Object result = solveTestCase();
            System.out.println(result);
        }
    }


    private static Object solveTestCase() {
        List<StringBuilder> answer = new ArrayList<>();
       int[][] visited = new int[N+2][M+2];

        int code = 1;
        Map<Integer, Integer> map = new HashMap<>();
        for(int i = 1; i <= N; i++){
            for(int j = 1; j <= M; j++) {
                if(visited[i][j] == 0 && A[i][j]) {
                    map.put(code, getCount(i, j, visited, code));
                    code++;
                }
            }
        }
        for(int i = 1; i <= N; i++){
            StringBuilder builder = new StringBuilder();
            answer.add(builder);
            for(int j = 1; j <= M; j++) {
                if(A[i][j]){
                    builder.append(".");
                    continue;
                }
                Set<Integer> codes = new HashSet<>();
                Pair cell = new Pair(i, j);
                int count = 0;
                for(int a = cell.x-1; a <= cell.x + 1; a++) {
                    for (int b = cell.y - 1; b <= cell.y + 1; b++) {
                        if(!A[a][b]){
                            continue;
                        }
                        if ((a == cell.x && b == cell.y)) {
                            continue;
                        }
                        if(a == cell.x || b == cell.y) {
                            if(!codes.contains(visited[a][b])) {
                                count += map.get(visited[a][b]);
                                codes.add(visited[a][b]);
                            }
                        }
                    }
                }
                count++;
                builder.append(count == 0 ? "." : (count % 10));
                A[i][j] = false;
            }
        }
        return joinValues(answer, "\n");
    }



    private static int getCount(int i, int j, int[][] visited , int code){
        int count = 0;
        Stack<Pair> stack = new Stack<>();
        stack.push(new Pair(i, j));
        while(!stack.empty()){
            Pair cell = stack.pop();
            if(visited[cell.x][cell.y] == 0){
                visited[cell.x][cell.y] = code;
                count++;
                for(int a = cell.x-1; a <= cell.x + 1; a++) {
                    for (int b = cell.y - 1; b <= cell.y + 1; b++) {
                        if(visited[a][b] != 0 || !A[a][b]){
                            continue;
                        }
                        if ((a == cell.x && b == cell.y)) {
                            continue;
                        }
                        if(a == cell.x || b == cell.y) {
                            stack.push(new Pair(a, b));
                        }
                    }
                }
            }
        }
        return count;
    }

