import java.util.Map;
import java.util.Map.Entry;
import java.util.Set;
import java.util.StringTokenizer;
import java.util.TreeSet;

public class C {

	public static final int[][] move_dir = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

	public static boolean is_ok(final int x, final int y, final int W, final int H){
		return (x >= 0) && (x < W) && (y >= 0) && (y < H);
	}

	public static int bfs(final int id, final int n, final int m, boolean[][] is_block, final int sx, final int sy, int[][] id_map){
		if(is_block[sy][sx]){ return 0; }
		if(id_map[sy][sx] >= 0 && id_map[sy][sx] != id){ return 0; }

		LinkedList<Integer> x_queue = new LinkedList<Integer>();
		LinkedList<Integer> y_queue = new LinkedList<Integer>();
		x_queue.add(sx);
		y_queue.add(sy);
		id_map[sy][sx] = id;

		int count = 1;

		while(!x_queue.isEmpty()){
			final int x = x_queue.poll();
			final int y = y_queue.poll();

			for(int[] move : move_dir){
				final int nx = x + move[0];
				final int ny = y + move[1];

				if(!is_ok(nx, ny, m, n)){
					continue;
				}else if(is_block[ny][nx]){
					continue;
				}else if(id_map[ny][nx] >= 0){
					continue;
				}

				id_map[ny][nx] = id;
				x_queue.add(nx);
				y_queue.add(ny);
				count++;
			}
		}
		return count;

	}

	public static void main(String[] args) {

		try (final Scanner sc = new Scanner(System.in)) {
			final int n = sc.nextInt();
			final int m = sc.nextInt();

			boolean[][] is_block = new boolean[n][m];
			for(int i = 0; i < n; i++){
				final char[] array = sc.next().toCharArray();

				for(int j = 0; j < m; j++){
					is_block[i][j] = array[j] == '*';
				}
			}

			int[][] id_map = new int[n][m];
			for(int i = 0; i < n; i++){
				for(int j = 0; j < m; j++){
					id_map[i][j] = -1;
				}
			}

			ArrayList<Integer> id_sizes = new ArrayList<Integer>();
			{
				int id = 0;
				for(int i = 0; i < n; i++){
					for(int j = 0; j < m; j++){
						if(!is_block[i][j] && id_map[i][j] < 0){
							id_sizes.add(bfs(id++, n, m, is_block, j, i, id_map));
						}
					}
				}
			}


			try(PrintWriter out = new PrintWriter(System.out)){
				for(int y = 0; y < n; y++){
					for(int x = 0; x < m; x++){
						if(!is_block[y][x]){
							out.print(".");
							continue;
						}

						long answer = 1;
						HashSet<Integer> id_set = new HashSet<Integer>();

						for(int[] move : move_dir){
							final int nx = x + move[0];
							final int ny = y + move[1];

							if(!is_ok(nx, ny, m, n)){
								continue;
							}else if(is_block[ny][nx]){
								continue;
							}else{
								final int next_id = id_map[ny][nx];
								if(id_set.contains(next_id)){ continue; }

								id_set.add(next_id);
								answer += id_sizes.get(next_id);
							}
						}

						out.print(answer % 10);
					}
					out.println();
				}
				out.flush();
			}
		}
	}	

	public static class Scanner implements Closeable {
		private BufferedReader br;
		private StringTokenizer tok;

		public Scanner(InputStream is) {
			br = new BufferedReader(new InputStreamReader(is));
		}

		private void getLine() {
			try {
				while (!hasNext()) {
					tok = new StringTokenizer(br.readLine());
				}
			} catch (IOException e) { 
			}
		}

		private boolean hasNext() {
			return tok != null && tok.hasMoreTokens();
		}

		public String next() {
			getLine();
			return tok.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}

		public void close() {
			try {
				br.close();
			} catch (IOException e) { 
			}
		}
	}
}

import java.io.BufferedReader;
