public class Educational5C {
    static BufferedReader reader = new BufferedReader(new InputStreamReader(System.in)); 
    static PrintWriter writer=new PrintWriter(new OutputStreamWriter(System.out));
    static int n=0;
    static int m=0;
    final static int maxn=1005;
    static String []s=new String [maxn];
    static char [][]c=new char [maxn][maxn];
    static String []ans=new String[maxn];
    static int [][]h=new int[maxn][maxn];
    static int []p=new int[maxn*maxn];
    static int num=0;
    static int [][]dir={{0,1},{0,-1},{-1,0},{1,0}};
    public static void dfs(int x,int y){
        h[x][y]=num;
        for(int i=0;i<4;i++){
            int nx=x+dir[i][0];
            int ny=y+dir[i][1];
            if(nx>=0&&nx<n&&ny>=0&&ny<m&&h[nx][ny]==0&&c[nx][ny]=='.'){
                p[num]++;
                dfs(nx,ny);
            }
        }
    }
    public static void main(String []args) throws IOException{

        String l=reader.readLine();
        int t=0;
        for(int i=0;i<l.length();i++){
            if(l.charAt(i)==' '){
                t=i+1;
                break;
            }
            n=n*10+l.charAt(i)-'0'; 
        }
        for(int i=t;i<l.length();i++)
            m=m*10+l.charAt(i)-'0';
        for(int i=0;i<n;i++){
            Arrays.fill(h[i], 0);
            s[i]=new String();
            s[i]=reader.readLine();
            c[i]=s[i].toCharArray();
        }
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(h[i][j]==0&&c[i][j]=='.'){
                    num++;
                    p[num]=1;
                    dfs(i,j);
                }
            }
        }
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(c[i][j]=='.')
                    ans[i]+='.';
                else{
                    int tem=1;
                    int []hash=new int[4];
                    int ll=0;
                    for(int k=0;k<4;k++){
                        boolean judge=true;
                        int xx=i+dir[k][0];
                        int yy=j+dir[k][1];
                        if(xx>=0&&xx<n&&yy>=0&&yy<m&&c[xx][yy]=='.'){
                            for(int r=0;r<ll;r++)
                                if(hash[r]==h[xx][yy])
                                    judge=false;
                            if(judge){
                                tem+=p[h[xx][yy]];
                                hash[ll++]=h[xx][yy];
                            }
                        }
                    }
                    ans[i]+=(char)('0'+tem%10);
                }
            }
            writer.println(ans[i].substring(4,ans[i].length()));
        }
        writer.close();
    }
}

import java.io.OutputStream;
