public class CF616C {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskX solver = new TaskX();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskX {
        static final int MAX = 1000;
        static int n, m;
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};
        int[] cnt = new int [MAX * MAX + 5];
        int[][] region = new int[MAX + 5][MAX + 5];
        String[] mat = new String[MAX + 5];
        StringBuilder[] res = new StringBuilder[MAX + 5];
        int totalRegion = 0;

        void go(int x, int y) {
            for (int i = 0; i < 4; ++i) {
                int nx = dx[i] + x;
                int ny = dy[i] + y;

                if (nx >= 0 && nx < n && ny >= 0 && ny < m && mat[nx].charAt(ny) == '.' && region[nx][ny] == 0) {
                    if (mat[x].charAt(y) == '*') {
                        totalRegion++;
                    } 

                    region[nx][ny] = totalRegion;
                    cnt[totalRegion]++;
                    go(nx, ny);
                }
            }
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();

            for (int i = 0; i < n; ++i) {
                mat[i] = in.next();
            }

            for (int i = 0; i < n; ++i) {
                res[i] = new StringBuilder(mat[i]);

                for (int j = 0; j < m; ++j) {
                    if (mat[i].charAt(j) == '*') {
                        go(i, j);
                        int val = 0;
                        Set<Integer> regions = new HashSet<>();
                        for (int t = 0; t < 4; ++t) {
                            int ni = i + dx[t];
                            int nj = j + dy[t];

                            if (ni >= 0 && ni < n && 0 <= nj && nj < m && mat[ni].charAt(nj) == '.' && !regions.contains(region[ni][nj])) {
                                regions.add(region[ni][nj]);
                                val += cnt[region[ni][nj]];
                            }
                        }

                        res[i].setCharAt(j, (char) ('0' + (1 + val) % 10));
                    }
                }
                out.println(res[i]);
            }
        }
    }

    static class Pair {
        int x, y;
        public Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDoule() {
            return Double.parseDouble(next());
        }
    }
}

