		int[] size = new int[n*m + 1];
		int ident = 1;
		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(index[i][j] == 0 && map[i][j] == '.'){
					int s = 1;
					ArrayList<Coor> q = new ArrayList<>();
					q.add(new Coor(i, j));
					ArrayList<Coor> seen = new ArrayList<>();
					seen.add(new Coor(i, j));
					index[i][j] = ident;
					while(!q.isEmpty()){
						Coor c = q.remove(0);
						for(int[] d: dir){
							int x = c.x + d[0]; int y = c.y + d[1];
							if(x >= 0 && x < n && y >= 0 && y < m && map[x][y] == '.' && index[x][y] == 0){
								q.add(new Coor(x, y));
								seen.add(new Coor(x, y));
								index[x][y] = ident;
								s++;
							}
						}
					}
					size[ident] = s;
					ident++;
				}
			}
		}
		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(map[i][j] == '*'){
					int tot = 1;
					HashSet<Integer> fields = new HashSet<>();
					for(int[] d: dir){
						int x = i + d[0]; int y = j + d[1];
						if(x >= 0 && x < n && y >= 0 && y < m && map[x][y] == '.'){
							fields.add(index[x][y]);
						}
					}
					for(int ind: fields){
						tot += size[ind];
					}
					map[i][j] = (char)(tot % 10 + '0');
				}						
			}
		}
		PrintWriter pw = new PrintWriter(System.out);
