public class C {
  private static final int[][] dir = {{-1, 0}, {0, -1}, {1, 0}, {0, 1}};

  public static void main(String[] args) throws IOException {
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    StringTokenizer st = new StringTokenizer(br.readLine());
    int n = Integer.valueOf(st.nextToken());
    int m = Integer.valueOf(st.nextToken());
    char[][] ca = new char[n][m];
    for (int i = 0; i < n; i++) {
      String str = br.readLine();
      for (int j = 0; j < m; j++) {
        ca[i][j] = str.charAt(j);
      }
    }
    int num = 0;
    int[][] fa = new int[n][m];
    int[] dc = new int[n*m + 1];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        if (ca[i][j] == '*') {
          fa[i][j] = -1;
          continue;
        }
        if (ca[i][j] == '.' && fa[i][j] == 0) {
          num++;
          dc[num] = fill(ca, fa, i, j, num);
        }
      }
    }
    char[][] res = new char[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        if (fa[i][j] == -1) {
          Set<Integer> set = new HashSet<>();
          for (int k = 0; k < dir.length; k++) {
            int dx = dir[k][0];
            int dy = dir[k][1];
            if (i + dx >= 0 && j + dy >= 0 && i + dx < fa.length && j + dy < fa[0].length && fa[i + dx][j + dy] > -1) {
              set.add(fa[i + dx][j + dy]);
            }
          }
          int cnt = 1;
          for (Integer si : set) {
            cnt += dc[si];
          }
          res[i][j] = (char)('0' + (char)(cnt % 10));
        } else {
          res[i][j] = '.';
        }
      }
    }
    for (int i = 0; i < n; i++) {
      String s = String.valueOf(res[i]);
      System.out.println(s);
    }
  }
  private static int fill(char[][] ca, int[][] fa, int i, int j, int num) {
    int count = 1;
    fa[i][j] = num;
    Queue<int[]> q = new ArrayDeque<>();
    q.add(new int[]{i, j});
    while (q.size() > 0) {
      int[] p = q.remove();
      int x = p[0];
      int y = p[1];
      for (int a = 0; a < dir.length; a++) {
        int dx = dir[a][0];
        int dy = dir[a][1];
        if (x + dx >= 0 && y + dy >= 0 && x + dx < ca.length && y + dy < ca[0].length) {
          if (ca[x + dx][y + dy] == '.' && fa[x + dx][y + dy] == 0) {
            fa[x + dx][y + dy] = num;
            q.add(new int[]{x + dx, y + dy});
            count++;
          }
        }
      }
    }
    return count;
  }
}

import java.util.*;
import java.io.*;

public class Solution {
    private static final int[] X = { -1, 0, 1, 0 };
    private static final int[] Y = { 0, 1, 0, -1 };

    private static void dfs(char[][] array, int row, int column, int[][] num,
            int[] size, int current) {
        if (row >= array.length || row < 0 || column < 0
                || column >= array[0].length) {
            return;
        }

        if (array[row][column] == '*') {
            return;
        }

        if (num[row][column] != -1) {
            return;
        }

        size[current]++;
        num[row][column] = current;
        for (int i = 0; i < X.length; i++) {
            dfs(array, row + X[i], column + Y[i], num, size, current);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(
                System.in));
        String[] nm = reader.readLine().split(" ");
        int n = Integer.parseInt(nm[0]);
        int m = Integer.parseInt(nm[1]);

        char[][] array = new char[n][m];
        for (int i = 0; i < n; i++) {
            array[i] = reader.readLine().toCharArray();
        }

        int[] size = new int[n * m];
        int[][] num = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                num[i][j] = -1;
            }
        }
        int current = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (num[i][j] == -1 && array[i][j] == '.') {
                    dfs(array, i, j, num, size, current);
                    current++;
                }
            }
        }

        char[][] res = new char[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (array[i][j] != '.') {
                    int sum = 1;
                    Set<Integer> temp = new HashSet<>();
                    for (int k = 0; k < X.length; k++) {
                        int xx = i + X[k];
                        int yy = j + Y[k];
                        if (xx >= array.length || xx < 0 || yy < 0
                                || yy >= array[0].length) {
                            continue;
                        }
                        if (array[xx][yy] == '*') {
                            continue;
                        }
                        temp.add(num[xx][yy]);
                    }
                    for (Integer e : temp) {
                        sum += size[e];
                    }
                    res[i][j] = (char) ((sum % 10) + '0');
                } else {
                    res[i][j] = array[i][j];
                }
            }
        }
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < n; i++) {
            pw.println(String.valueOf(res[i]));
        }
        pw.close();
    }
}

import java.io.*;
import java.util.*;
public class ProC {
	static int n,m,ct,c,x,y,a;
	static String ss;
	static int[] xx={0,0,1,-1},yy={1,-1,0,0};
	static int[] mm=new int[1000005];
	static int[][] vis=new int[1005][1005];
	static char[][] map=new char[1005][1005];
	static Map<Integer,Integer> mp=new HashMap<Integer,Integer>();
	static void dfs(int i,int j)
	{
		vis[i][j]=c;ct++;
		for(int k=0;k<4;k++)
		{
			x=i+xx[k];y=j+yy[k];
			if(0<x&&x<=n&&0<y&&y<=m&&vis[x][y]==0&&map[x][y]=='.')
				dfs(x,y);
		}
	}
	static PrintWriter out=new PrintWriter(new OutputStreamWriter(System.out));

	public static void main(String[] args) {
		Scanner in=new Scanner(System.in);
		n=in.nextInt();m=in.nextInt();
		in.nextLine();
		for(int i=1;i<=n;i++)
		{
			ss=in.nextLine();
			for(int j=0;j<m;j++)
				map[i][j+1]=ss.charAt(j);
		}
		for(int i=1;i<=n;i++)
		for(int j=1;j<=m;j++)
		{
			if(vis[i][j]==0&&map[i][j]=='.') 
			{ 
				ct=0;c++;dfs(i,j);
				mm[c]=ct;
			}
		}
		for(int i=1;i<=n;i++)
		{
			for(int j=1;j<=m;j++)
			{
				if(map[i][j]=='.') out.print(".");
				else
				{
					a=0;mp.clear();
					for(int k=0;k<4;k++)
					{
						x=i+xx[k];y=j+yy[k];
						if(0<x&&x<=n&&0<y&&y<=m)
						{
							c=vis[x][y];
							if(mp.get(c)==null) { mp.put(c,1);a+=mm[c];}
						}
					}
					a++;a%=10;
					out.print(a);
				}
			}
			out.println();
		}
		out.flush();
	}
}

import java.io.*;
import java.util.ArrayList;
import java.util.HashSet;


public class Main implements Runnable{
    int X , Y;
    public void run(){
        Reader in = new Reader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int x , y;

        x = in.nextInt();
        y = in.nextInt();
        X = x;
        Y = y;
        a = new char[x][y];
        for(int i = 0;i < x;i++){
            a[i] = in.nextString(y).toCharArray();
        }
        color = new int[x][y];
        int ans[][] = new int[x][y];
        u = new boolean[x][y];
        ArrayList < Integer > c = new ArrayList<Integer>();
        int col = 0;
        for(int i = 0;i < x;i++) {
            for (int j = 0; j < y; j++) {
                if (a[i][j] == '.' && !u[i][j])
                    c.add(dfs(i, j, col++));
            }
        }
        for(int i = 0;i < x;i++){
            for(int j = 0;j < y;j++){
                if(a[i][j] == '*'){
                    HashSet < Integer > colors = new HashSet<Integer>();
                    if(i - 1 >= 0 && a[i - 1][j] == '.')
                        colors.add(color[i - 1][j]);
                    if(j - 1 >= 0 && a[i][j - 1] == '.')
                        colors.add(color[i][j - 1]);
                    if(i + 1 < x && a[i + 1][j] == '.')
                        colors.add(color[i + 1][j]);
                    if(j + 1 < y && a[i][j + 1] == '.')
                        colors.add(color[i][j + 1]);
                    for(Integer f : colors){
                        ans[i][j] = ans[i][j] + c.get(f);
                        ans[i][j] %= 10;
                    }
                    out.print((ans[i][j] + 1) % 10);
                }else{
                    out.print(".");
                }
            }
            out.println();
        }
        out.close();
    }
    public char a[][];
    public int color[][];
    public int dfs(int x , int y , int col){
        color[x][y] = col;
        u[x][y] = true;
        int ans = 1;
        for(int i = -1;i <= 1;i++){
            for(int j = -1;j <= 1;j++){
                if(Math.abs(i) + Math.abs(j) == 1){
                    if(x + i >= 0 && y + j >= 0 && x + i < X && y + j < Y && !u[x + i][y + j] && a[x + i][y + j] == '.')
                        ans += dfs(x + i , y + j , col);
                }
            }
        }
        return ans;
    }
    public boolean u[][];
    public static void main(String argc[])throws IOException {
        new Thread(new Main()).run();
    }
    class Reader{
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte [] buffer;
        private int bufferPointer, bytesRead;

        public Reader(InputStream in) {
            din = new DataInputStream(in);
            buffer = new byte [ BUFFER_SIZE ];
            bufferPointer = bytesRead = 0;
        }
        public String nextString(int maxSize) {
            byte[] ch = new byte[maxSize];
            int point =  0;
            try {
                byte c = read();
                while (c == ' ' || c == '\n' || c=='\r')
                    c = read();
                while (c != ' ' && c != '\n' && c!='\r') {
                    ch[point++] = c;
                    c = read();
                }
            } catch (Exception e) {}
            return new String(ch, 0,point);
        }
        public int nextInt() {
            int ret =  0;
            boolean neg;
            try {
                byte c = read();
                while (c <= ' ')
                    c = read();
                neg = c == '-';
                if (neg)
                    c = read();
                do {
                    ret = ret * 10 + c - '0';
                    c = read();
                } while (c > ' ');

                if (neg) return -ret;
            } catch (Exception e) {}
            return ret;
        }
        public long nextLong() {
            long ret =  0;
            boolean neg;
            try {
                byte c = read();
                while (c <= ' ')
                    c = read();
                neg = c == '-';
                if (neg)
                    c = read();
                do {
                    ret = ret * 10 + c - '0';
                    c = read();
                } while (c > ' ');

                if (neg) return -ret;
            } catch (Exception e) {}
            return ret;
        }
        private void fillBuffer() {
            try {
                bytesRead = din.read(buffer, bufferPointer =  0, BUFFER_SIZE);
            } catch (Exception e) {}
            if (bytesRead == -1) buffer[0] = -1;
        }

        private byte read() {
            if (bufferPointer == bytesRead) fillBuffer();
            return buffer[bufferPointer++];
        }
    }
}

