                        int ii = i+dy[k];
                        int jj = j+dx[k];
                        if (Math.min(ii, jj) < 0 || ii >= n || jj >= m) continue;
                        int b = num[ii][jj];
                        if (b != -1 && !set.contains(b)){
                            a+=size[b];
                            set.add(b);
                        }
                    }
                    a%=10;
                    str.append(a);
                } else {
                    str.append('.');
                }
            }
            out.println(str);
        }
        out.close();
    }

    static int dy[] = { 0, -1, 0, 1 };
    static int dx[] = { -1, 0, 1, 0 };


