            return;
        if (f[i][j] != '.')
            return;
        if (color[i][j] != 0)
            return;

        color[i][j] = col;
        size[col]++;
        for (int di = -1; di <= 1; di++) {
            for (int dj = -1; dj <= 1; dj++) {
                if (di * di + dj * dj == 1) {
                    paint(i + di, j + dj, col);
                }
            }
        }
