public class TheLabyrinth
{




    static class WeightedQuickUnionUF {
	int[] parent;   
	int[] size;     
	int count;      
	public WeightedQuickUnionUF(int N) {
	    count = N;
	    parent = new int[N];
	    size = new int[N];
	    for (int i = 0; i < N; i++) {
		parent[i] = i;
		size[i] = 1;
	    }
	}
	public int count() {
	    return count;
	}
	public int find(int p) {
	    while (p != parent[p])
	    {
		parent[p] = parent[parent[p]];    
		p = parent[p];
	    }
	    return p;
	}

	public boolean connected(int p, int q) {
	    return find(p) == find(q);
	}
	public void union(int p, int q) {
	    int rootP = find(p);
	    int rootQ = find(q);
	    if (rootP == rootQ) return;


	    if (size[rootP] < size[rootQ]) {
		parent[rootP] = rootQ;
		size[rootQ] += size[rootP];	           
	    }
	    else {
		parent[rootQ] = rootP;
		size[rootP] += size[rootQ];
	    }
	    count--;
	}
    }


    static int r,c;
    static char arr[][];
    static boolean isValid(int i,int j)
    {
	if(i<0 || j<0 || i>=r || j>=c || arr[i][j] == '*')
	    return false;
	else
	    return true;
    }
    static int to1D(int i,int j)
    {
	return (i*c)+j;
    }
    static ArrayList<Integer> adj(int i,int j)
    {		
	ArrayList<Integer> adj  = new ArrayList<>();
	if(isValid(i+1, j))
	    adj.add(to1D(i+1,j));
	if(isValid(i-1, j))
	    adj.add(to1D(i-1, j));
	if(isValid(i, j+1))
	    adj.add(to1D(i, j+1));
	if(isValid(i, j-1))
	    adj.add(to1D(i, j-1));
	return adj;
    }

    private static int size(WeightedQuickUnionUF dsu,int p)
    {
	return dsu.size[dsu.find(p)];
    }
    private static void solve(FastScanner s1, FastWriter out){
	r = s1.nextInt();
	c = s1.nextInt();
	arr = new char[r][c];
	for(int i = 0 ;i<r;i++)
	    arr[i] = s1.next().toCharArray();
	WeightedQuickUnionUF dsu = new WeightedQuickUnionUF(r*c);
	for(int i=0;i<r;i++)
	{
	    for(int j=0;j<c;j++)
	    {
		int u = to1D(i,j);

		if(arr[i][j] == '.')
		{
		    for(int v : adj(i, j))
			dsu.union(u, v);
		}
	    }
	}

	char output[][] = new char[r][c];

	for(int i=0;i<r;i++)
	{
	    for(int j=0;j<c;j++)
	    {
		if(arr[i][j] == '.')
		    output[i][j] = '.';
		else
		{
		    ArrayList<Integer> arl = adj(i,j);
		    int len = arl.size();
		    int total = 1;
		    TreeSet<Integer> set = new TreeSet<>(arl); 
		    while(set.size()>0)
		    {
			int p = set.pollFirst();	
			ArrayList<Integer> TBR = new ArrayList<>();
			for(int q:set)
			    if(dsu.connected(p, q))
				TBR.add(q);

			for(int q:TBR)
			    set.remove(q);

			total += size(dsu,p);
		    }
		    output[i][j] = (char)('0' + (total%10));
		}
	    }	    
	}

	for(int i=0;i<r;i++)
	{
	    for(int j=0;j<c;j++)
	    {
		out.print(output[i][j]);
	    }
	    out.println();
	}
    }







    public static void main(String []args) throws IOException {
	FastScanner in  = new FastScanner(System.in);
	FastWriter  out = new FastWriter(System.out);
	solve(in, out);
	in.close();
	out.close();
    }    

