public class Edu5C {
    static boolean visited[][];
    static int n;
    static int m;
    static char[][] grid;
    static int setNo = 1;
    static int belongsTo[][];
    static boolean assigned[][];
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        sc.nextLine();
        grid = new char[n][m];
        visited = new boolean[n][m];
        for(int i=0; i<n; i++){
            grid[i] = sc.nextLine().toCharArray();
        }

        visited = new boolean[n][m];
        assigned = new boolean[n][m];
        belongsTo = new int[n][m];
        int[][] countSCC = new int[n][m];
        for(int i=0; i<n; i++){
            for(int j=0; j<m; j++){
                if(grid[i][j] != '.' || visited[i][j])
                    continue;
                int count = getCount(i,j);
                assignCount(i,j,count,countSCC,setNo);
                setNo++;
            }
        }

        int [][] res = new int[n][m];
        for(int i=0; i<n; i++)
            for(int j=0; j<m; j++){
                if(grid[i][j] == '*'){
                    HashSet<Integer> added = new HashSet<Integer>(4);
                    res[i][j] = 1;
                    if(i>0){
                        res[i][j] += countSCC[i-1][j];
                        added.add(belongsTo[i-1][j]);

                    }
                    if(i<n-1 && !added.contains(belongsTo[i+1][j])){
                        res[i][j] += countSCC[i+1][j];
                        added.add(belongsTo[i+1][j]);

                    }
                    if(j>0 && !added.contains(belongsTo[i][j-1])){
                        res[i][j] += countSCC[i][j-1];

                        added.add(belongsTo[i][j-1]);
                    }
                    if(j<m-1 && !added.contains(belongsTo[i][j+1])){
                        res[i][j] += countSCC[i][j+1];
                        added.add(belongsTo[i][j+1]);

                    }
                }
            }
        PrintWriter out = new PrintWriter(System.out);
        for(int i=0; i<n; i++){
            for(int j=0; j<m; j++){
                if(res[i][j]>0)
                    out.print(res[i][j]%10);
                else
                    out.print('.');
            }
            out.println();
        }
        out.flush();


    }
    static void assignCount(int i, int j, int c, int[][] cSCC,int set){
        if(i<0 || j<0 || i>=n || j>=m || assigned[i][j])
            return;
        cSCC[i][j] = c;
        assigned[i][j] = true;
        belongsTo[i][j] = set;
        if(i>0 && grid[i-1][j] == '.')
            assignCount(i-1,j,c,cSCC,set);
        if(j>0 && grid[i][j-1] == '.')
            assignCount(i,j-1,c,cSCC,set);
        if(i<n-1 && grid[i+1][j] == '.')
            assignCount(i+1,j,c,cSCC,set);
        if(j<m-1 && grid[i][j+1] == '.')
            assignCount(i,j+1,c,cSCC,set);

    }
    static int getCount(int i, int j){

        if(i<0 || j<0 || i>=n || j>=m)
            return 0;
        if(grid[i][j] != '.' || visited[i][j])
            return 0;
        visited[i][j] = true;
        int right = getCount(i+1,j);
        int down = getCount(i,j+1);
        int up = getCount(i,j-1);
        int left = getCount(i-1,j);


        return 1 + right + down + up + left;
    }





}

