    class UnionFind {
      int[] rank;

      int[] size;

      int[] parent;

      int n;

      int count;

      UnionFind(int size)
      {
        count = size;
        n = size;
        rank = new int[n];
        parent = new int[n];
        for(int i = 0; i < n; i++)
          parent[i] = i;

        this.size = new int[n];
        Arrays.fill(this.size, 1);
      }

      void merge(int a, int b)
      {
        int pa = find(a);
        int pb = find(b);

        if(pa == pb)
          return;

        if(rank[pa] > rank[pb]) {
          parent[pb] = pa;
          rank[pb] += rank[pa];
          size[pa] += size[pb];
        } else {
          parent[pa] = pb;
          rank[pa] += rank[pb];
          size[pb] += size[pa];
        }
        count--;
      }

      int find(int a)
      {
        if(a != parent[a])
          parent[a] = find(parent[a]);
        return parent[a];
      }

      int count()
      {
        return count;
      }

      int size(int a)
      {
        int pa = find(a);
        return size[pa];
      }
    }


