              if(i > 0 && lab[i-1][j] == '.')
                uf.merge(index, index - m);
              if(j > 0 && lab[i][j-1] == '.')
                uf.merge(index, index - 1);
            }
          }
        }

        char[] res = new char[m];
        for(int i = 0; i < n; i++) {
          for(int j = 0; j < m; j++) {
            res[j] = lab[i][j];
