static class UnionFindTree{

 private int[] par;

 public UnionFindTree(int size){
  par=new int[size];
  Arrays.fill(par,-1);
 }

 public int root(int x){
  if(par[x]<0) return x;
  else return par[x]=root(par[x]);
 }

 public void unite(int x,int y){
  x=root(x);
  y=root(y);
  if(x==y) return;
  if(par[y]>par[x]){
   int temp=y;
   y=x;
   x=temp;
  }
  par[x]+=par[y];
  par[y]=x;
 }

 public boolean same(int x,int y){
  return root(x)==root(y);
 }

 public int set_count(){
  int ret=0;
  for(int v : par){
   if(v<0) ret++;
  }
  return ret;
 }

 public int set_size(int x){
  return -par[root(x)];
 }
}

