public class TheLabyrinth {
    private  static VertexDefinder[][] arrayOfAnswers;
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String s = br.readLine();
        int n = Integer.parseInt(s.split(" ")[0]), m = Integer.parseInt(s.split(" ")[1]);
        char[][] a = new char[n][];
        char[][] original = new char[n][];
        arrayOfAnswers = new VertexDefinder[n][m];
        for (int i = 0; i < n; i++) {
            s = br.readLine();
            a[i] = s.toCharArray();
            original[i] = s.toCharArray();
        }
        VertexDefinder vd;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] == '.') {
                    vd = new VertexDefinder(0);
                    vd.value = pathFinder(a, i, j, vd);
                }
            }
        }
        StringBuilder sb = new StringBuilder("");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (original[i][j] == '*') {
                    int k = 0;
                    int[] b = new int[4];
                    int[][] coordinates = new int[4][2];
                    if (j < original[i].length - 1 && original[i][j + 1] == '.') {
                        b[k] = arrayOfAnswers[i][j + 1].connectedComponentId;
                        coordinates[k][0] = i;
                        coordinates[k][1] = j + 1;
                        k++;
                    }
                    if (i < original.length - 1 && original[i + 1][j] == '.') {
                        b[k] = arrayOfAnswers[i + 1][j].connectedComponentId;
                        coordinates[k][0] = i + 1;
                        coordinates[k][1] = j;
                        k++;
                    }
                    if (j > 0 && original[i][j - 1] == '.') {
                        b[k] = arrayOfAnswers[i][j - 1].connectedComponentId;
                        coordinates[k][0] = i;
                        coordinates[k][1] = j - 1;
                        k++;
                    }
                    if (i > 0 && original[i - 1][j] == '.') {
                        b[k] = arrayOfAnswers[i - 1][j].connectedComponentId;
                        coordinates[k][0] = i - 1;
                        coordinates[k][1] = j;
                        k++;
                    }
                    int sum = 1;
                    for (k = 0; k < 4; k++) {
                        if (b[k] > 0) {
                            for (int l = k + 1; l < 4; l++) {
                                if (b[k] == b[l]) {
                                    b[l] = -1;
                                }
                            }
                            sum += arrayOfAnswers[coordinates[k][0]][coordinates[k][1]].value;
                        }
                    }
                    sb.append(sum % 10);
                }
                else {
                    sb.append('.');
                }
            }
            sb.append("\n");
        }
        pw.println(sb.toString());
        pw.close();
    }
    static int pathFinder (char[][] a, int i, int j, VertexDefinder vd) {
        int result = 1;
        a[i][j] = '-';
        arrayOfAnswers[i][j] = vd;
        if (j < a[i].length - 1 && a[i][j + 1] == '.') {
            result += pathFinder(a, i, j + 1, vd);
        }
        if (i < a.length - 1 && a[i + 1][j] == '.') {
            result += pathFinder(a, i + 1, j, vd);
        }
        if (j > 0 && a[i][j - 1] == '.') {
            result += pathFinder(a, i, j - 1, vd);
        }
        if (i > 0 && a[i - 1][j] == '.') {
            result += pathFinder(a, i - 1, j, vd);
        }
        return result;
    }
}

