            map[i] = s.toCharArray();
        }


        for (int i = 0; i < n ;i++) {
            for (int j = 0; j < m ;j++) {
                if (map[i][j] == '.') {
                    gao(map,count,p,i,j);
                }
            }
        }

        Map<Integer, Integer> set = new HashMap<>();
        for (int i = 0; i < n ;i++) {
            for (int j = 0; j < m ;j++) {
                if (map[i][j] == '*') {
                    count[i][j] = 1;
                    set.clear();
                    for (int ii = 0; ii < 4; ii++) {
                        int x1 = i + xoff[ii];
                        int y1 = j + yoff[ii];
                        if (isValid(x1, y1) && map[x1][y1] == '+' && !set.containsKey(p[x1][y1])) {
