                }
                else pr.print('.');
            }
            pr.print("\n");
        }
        pr.close();
        br.close();
    }

    private static void gao(char[][] map, int[][] count, int[][] p, int x, int y) {
        version++;
        LinkedList<Pair> list = new LinkedList<>();
        list.addLast(new Pair(x, y));
        map[x][y] = '-';
        int num = 0;
        while (!list.isEmpty()) {
            Pair pair = list.pollFirst();
            num++;
            for (int i = 0; i < 4; i++) {
                int x1 = pair.x + xoff[i];
                int y1 = pair.y + yoff[i];
                if (isValid(x1,y1) && map[x1][y1] == '.') {
                    list.addLast(new Pair(x1, y1));
                    map[x1][y1]='-';
                }
            }
        }

        list.addLast(new Pair(x, y));
        map[x][y] = '+';
        while (!list.isEmpty()) {
            Pair pair = list.pollFirst();
            count[pair.x][pair.y] = num;
            p[pair.x][pair.y] = version;
            for (int i = 0; i < 4; i++) {
                int x1 = pair.x + xoff[i];
                int y1 = pair.y + yoff[i];
                if (isValid(x1,y1) && map[x1][y1] == '-') {
                    list.addLast(new Pair(x1, y1));
                    map[x1][y1]='+';
                }
            }
        }


    }

    private static boolean isValid(int x, int y) {
        return (x>=0 && x<n && y>=0 && y<m);
    }
}
