    static class Solver {

        int n, m;
        int[][] map;
        int[][] color;
        int[] count;
        int[][] d = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            map = new int[n][m];
            color = new int[n][m];
            for (int i = 0; i < n; i++) {
                String s = in.next();
                for (int j = 0; j < m; j++) {
                    map[i][j] = (s.charAt(j) == '.' ? 0 : -1);
                    color[i][j] = map[i][j];
                }
            }

            int currentColor = 0;
            count = new int[n * m + 1];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (color[i][j] == 0) {
                        currentColor++;
                        dfs(i, j, currentColor);
                    }
                }
            }
            StringBuilder sb = new StringBuilder();
            HashSet<Integer> set;
            for (int i = 0; i < n; i++) {
                sb.setLength(0);
                for (int j = 0; j < m; j++) {
                    if (color[i][j] > 0) {
                        sb.append(".");
                    } else {
                        set = new HashSet<Integer>();
                        int q = 1;
                        for (int k = 0; k < 4; k++) {
                            int X = i + d[k][0];
                            int Y = j + d[k][1];
                            if (inField(X, Y) && color[X][Y] > 0) {
                                if (set.contains(color[X][Y])) {
                                } else {
                                    q += count[color[X][Y]];
                                    set.add(color[X][Y]);
                                }
                            }
                        }
                        sb.append(q % 10);
                    }
                }
                out.println(sb);
            }
        }

        public void dfs(int x, int y, int col) {
            color[x][y] = col;
            count[col]++;
            for (int i = 0; i < 4; i++) {
                if (inField(x + d[i][0], y + d[i][1]) && color[x + d[i][0]][y + d[i][1]] == 0) {
                    dfs(x + d[i][0], y + d[i][1], col);
                }
            }
        }

        public boolean inField(int x, int y) {
            return (x >= 0 && x < n && y >= 0 && y < m);
        }
    }

