public class Abood2B {

	static int N, M, C, grid[][], group[][];

	static int[] dx = {0, 1, 0, -1};
	static int[] dy = {1, 0, -1, 0};

	static int bfs(int x, int y) {
		Queue<Point> q = new LinkedList<>();
		group[x][y] = C;
		q.add(new Point(x, y));
		int ans = 1;

		while(!q.isEmpty()) {
			x = q.peek().x;
			y = q.remove().y;
			for (int i = 0; i < 4; i++) {
				if(valid(x + dx[i], y + dy[i]) && group[x + dx[i]][y + dy[i]] == -1 && grid[x + dx[i]][y + dy[i]] == 0) {
					ans ++;
					q.add(new Point(x + dx[i], y + dy[i]));
					group[x + dx[i]][y + dy[i]] = C;
				}
			}
		}

		return ans;
	}
	static boolean valid(int x, int y) {
		return x >= 0 && x < N && y >= 0 && y < M;
	}



	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		N = sc.nextInt();
		M = sc.nextInt();

		grid = new int[N][M];

		for (int i = 0; i < N; i++) {
			String s = sc.next();
			for (int j = 0; j < M; j++)
				if(s.charAt(j) == '*')
					grid[i][j] = 1;
		}

		ArrayList<Integer> count = new ArrayList<>();
		C = 0;
		group = new int[N][M];
		for (int i = 0; i < N; i++)
			Arrays.fill(group[i], -1);

		for (int i = 0; i < N; i++)
			for (int j = 0; j < M; j++)
				if(group[i][j] == -1 && grid[i][j] == 0) {
					int x = bfs(i, j);
					count.add(x);
					C++;
				}

		for (int i = 0; i < N; i++) {
			for (int j = 0; j < M; j++) {
				if(grid[i][j] == 0) {
					out.print('.');
					continue;
				}

				HashSet<Integer> set = new HashSet<>();
				int ans = 1;
				for (int k = 0; k < 4; k++) {
					if(valid(i + dx[k], j + dy[k]) && grid[i + dx[k]][j + dy[k]] == 0 && !set.contains(group[i + dx[k]][j + dy[k]])) {
						ans += count.get(group[i + dx[k]][j + dy[k]]);
						set.add(group[i + dx[k]][j + dy[k]]);
					}
				}
				out.print(ans % 10);
			}
			out.println();
		}


		out.flush();
		out.close();
	}




	static class Scanner 



	{
		StringTokenizer st;
		BufferedReader br;

		public Scanner(InputStream s){	br = new BufferedReader(new InputStreamReader(s));}

		public String next() throws IOException 
		{
			while (st == null || !st.hasMoreTokens()) 
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		public int nextInt() throws IOException {return Integer.parseInt(next());}

		public long nextLong() throws IOException {return Long.parseLong(next());}

		public String nextLine() throws IOException {return br.readLine();}


		public double nextDouble() throws IOException
		{
			String x = next();
			StringBuilder sb = new StringBuilder("0");
			double res = 0, f = 1;
			boolean dec = false, neg = false;
			int start = 0;
			if(x.charAt(0) == '-')
			{
				neg = true;
				start++;
			}
			for(int i = start; i < x.length(); i++)
				if(x.charAt(i) == '.')
				{
					res = Long.parseLong(sb.toString());
					sb = new StringBuilder("0");
					dec = true;
				}
				else
				{
					sb.append(x.charAt(i));
					if(dec)
						f *= 10;
				}
			res += Long.parseLong(sb.toString()) / f;
			return res * (neg?-1:1);
		}

		public boolean ready() throws IOException {return br.ready();}



	}

