class Cell {
    int x, y;

    public Cell(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

class Task {

    private Map<Integer, Integer> map = new HashMap<>();

    private char tab[][];

    private int count[][];

    private int n,m;

    public void solve(InputReader in, OutputWriter out) {
        n = in.nextInt();
        m = in.nextInt();
        tab = new char[n][m];
        count = new int[n][m];
        for(int i=0;i<n;i++) {
            tab[i] = in.next().toCharArray();
        }
        int counter = 1;
        for(int i=0;i<n;i++) {
            for(int j=0;j<m;j++) {
                if(tab[i][j] == '.') {
                    int c = bfs(i,j,counter);
                    map.put(counter, c);
                    counter++;
                }
            }
        }
        Set<Integer> set = new HashSet<>();
        for(int i=0;i<n;i++) {
            for(int j=0;j<m;j++) {
                if(tab[i][j] == '*') {
                    for(int k=0;k<4;k++) {
                        if(i+moveX[k] >=0 && i+moveX[k] < n && j+moveY[k] >=0 && j+moveY[k] < m && tab[i+moveX[k]][j+moveY[k]] != '*') {
                            set.add(count[i+moveX[k]][j+moveY[k]]);
                        }
                    }
                    int total = 1;
                    for(int element : set) {
                        total += map.get(element);
                    }
                    set.clear();
                    out.print(total % 10);
                } else {
                    out.print(".");
                }
            }
            out.printLine();
        }
    }

    private int moveX[] = {-1,1,0,0};

    private int moveY[] = {0,0,-1,1};

    private int bfs(int i, int j, int counter) {
        Queue<Cell> Q = new ArrayDeque<>();
        Q.add(new Cell(i,j));
        int c = 0;
        tab[i][j] = '-';
        while(!Q.isEmpty()) {
            Cell cell = Q.poll();
            count[cell.x][cell.y] = counter;
            c++;
            for(int k=0;k<4;k++) {
                if(inside(cell, k) && tab[cell.x+moveX[k]][cell.y+moveY[k]] == '.') {
                    Q.add(new Cell(cell.x+moveX[k], cell.y+moveY[k]));
                    tab[cell.x+moveX[k]][cell.y+moveY[k]] = '-';
                }
            }
        }
        return c;
    }

    private boolean inside(Cell cell, int k) {
        return cell.x + moveX[k] >= 0 && cell.x + moveX[k] < n && cell.y + moveY[k] >=0 && cell.y + moveY[k] < m;
    }


}

