public class Main
{


	InputReader in;
	StringTokenizer tok;
	StringBuilder ans;


	int R, C;
	boolean g[][];
	int currComponent;
	boolean[][] visited;
	int[][] component;
	int[] size;
	int[] dx = new int[]
	{ 1, -1, 0, 0 };
	int[] dy = new int[]
	{ 0, 0, 1, -1 };

	public static void main(String[] args) throws FileNotFoundException
	{
		Main sol = new Main();
		sol.begin();

	}

	private void begin() throws FileNotFoundException
	{

		boolean file = false;
		if (file)
			in = new InputReader(new FileInputStream("input.txt"));
		else
			in = new InputReader(System.in);
		ans = new StringBuilder();


		R = Integer.parseInt(in.next());
		C = Integer.parseInt(in.next());
		g = new boolean[R][C];
		for (int r = 0; r < R; r++)
		{
			String str = in.next();
			for (int c = 0; c < C; c++)
				if (str.charAt(c) == '.')
					g[r][c] = true;
		}


		solve();
		System.out.print(ans.toString());
	}

	private void solve()
	{

		currComponent = 0;
		component = new int[R][C];
		size = new int[R * C + 4];
		visited = new boolean[R][C];
		for (int r = 0; r < R; r++)
			for (int c = 0; c < C; c++)
				if (!visited[r][c] && g[r][c])
				{
					visited[r][c] = true;
					currComponent++;
					bfs(r, c);
				}


		for (int r = 0; r < R; r++)
		{
			for (int c = 0; c < C; c++)
				if (g[r][c])
					ans.append(".");
				else
				{
					int count = 1;
					HashSet<Integer> neighbours = new HashSet<>();
					for (int i = 0; i < dx.length; i++)
					{
						int newR = r + dx[i];
						int newC = c + dy[i];
						if (valid(newR, newC))
							if (!neighbours.contains(component[newR][newC]))
							{
								neighbours.add(component[newR][newC]);
								count += size[component[newR][newC]];
							}
					}
					ans.append((count % 10) + "");
				}
			ans.append("\n");
		}

	}

	private void bfs(int rS, int cS)
	{
		Queue<Integer> qr = new LinkedList<>();
		Queue<Integer> qc = new LinkedList<>();
		qr.add(rS);
		qc.add(cS);

		while (!qr.isEmpty())
		{
			int r = qr.poll();
			int c = qc.poll();
			component[r][c] = currComponent;
			size[currComponent]++;


			for (int i = 0; i < dx.length; i++)
			{
				int newR = r + dx[i];
				int newC = c + dy[i];
				if (valid(newR, newC))
					if (!visited[newR][newC])
						if (g[newR][newC])
						{
							visited[newR][newC] = true;
							qr.add(newR);
							qc.add(newC);
						}
			}
		}
	}

	private boolean valid(int r, int c)
	{
		return r >= 0 && r < R && c >= 0 && c < C;
	}
}

