    static class DPolyline {
        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            int x1 = in.scanInt();
            int y1 = in.scanInt();
            int x2 = in.scanInt();
            int y2 = in.scanInt();
            int x3 = in.scanInt();
            int y3 = in.scanInt();

            int ans = 3;
            if (x1 == x2 && x2 == x3) ans = Math.min(ans, 1);
            if ((x1 == x2 && (y3 >= Math.max(y1, y2) || y3 <= Math.min(y1, y2))) || (x1 == x3 && (y2 >= Math.max(y1, y3) || y2 <= Math.min(y1, y3))) || (x3 == x2 && (y1 >= Math.max(y3, y2) || y1 <= Math.min(y3, y2))))
                ans = Math.min(ans, 2);
            if (y1 == y2 && y2 == y3) ans = Math.min(ans, 1);
            if ((y1 == y2 && (x3 >= Math.max(x1, x2) || x3 <= Math.min(x1, x2))) || (y1 == y3 && (x2 >= Math.max(x1, x3) || x2 <= Math.min(x1, x3))) || (y3 == y2 && (x1 >= Math.max(x3, x2) || x1 <= Math.min(x3, x2))))
                ans = Math.min(ans, 2);
            out.println(ans);

        }

    }

    static class ScanReader {
        private byte[] buf = new byte[4 * 1024];
        private int index;
        private BufferedInputStream in;
        private int total;

        public ScanReader(InputStream inputStream) {
            in = new BufferedInputStream(inputStream);
        }

        private int scan() {
            if (index >= total) {
                index = 0;
                try {
                    total = in.read(buf);
                } catch (Exception e) {
                    e.printStackTrace();
                }
                if (total <= 0) return -1;
            }
            return buf[index++];
        }

        public int scanInt() {
            int integer = 0;
            int n = scan();
            while (isWhiteSpace(n)) n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    integer *= 10;
                    integer += n - '0';
                    n = scan();
                }
            }
            return neg * integer;
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1) return true;
            else return false;
        }

    }
}

