class Utils {
    public static void shuffleint(int[] a) {
        int n=a.length,tmp,pi;
        Random r=new Random();
        for (int i=0;i<n;++i) {
            tmp=a[i];
            pi=i+r.nextInt(n-i);
            a[i]=a[pi];
            a[pi]=tmp;
        }
    }
    public static void shufflelong(long[] a) {
        int n=a.length,pi;
        long tmp;
        Random r=new Random();
        for (int i=0;i<n;++i) {
            tmp=a[i];
            pi=i+r.nextInt(n-i);
            a[i]=a[pi];
            a[pi]=tmp;
        }
    }
    public static void sortint(int[] a) {
        shuffleint(a);
        Arrays.sort(a);
    }
    public static void sortlong(long[] a) {
        shufflelong(a);
        Arrays.sort(a);
    }
}

