        Point second = new Point(input.nextLong(), input.nextLong());
        Point third = new Point(input.nextLong(), input.nextLong());

        output.println(getResult(first, second, third));
        output.close();
    }

    private static int getResult(Point first, Point second, Point third) {
        if (first.a == second.a && second.a == third.a
                || first.b == second.b && second.b == third.b) {
            return 1;
        }

        if (first.a == second.a && (third.b >= first.b && third.b >= second.b || third.b <= first.b && third.b <= second.b)) {
            return 2;
        }
        if (first.a == third.a && (second.b >= first.b && second.b >= third.b || second.b <= first.b && second.b <= third.b)) {
            return 2;
        }
        if (second.a == third.a && (first.b >= second.b && first.b >= third.b || first.b <= second.b && first.b <= third.b)) {
            return 2;
        }

        if (first.b == second.b && (third.a >= first.a && third.a >= second.a || third.a <= first.a && third.a <= second.a)) {
            return 2;
        }
        if (first.b == third.b && (second.a >= first.a && second.a >= third.a || second.a <= first.a && second.a <= third.a)) {
            return 2;
        }
        if (second.b == third.b && (first.a >= second.a && first.a >= third.a || first.a <= second.a && first.a <= third.a)) {
            return 2;
        }

        return 3;
    }

