class SegmentTree5 {		

	int N; 			
	int[] array, sTree, lazy;

	SegmentTree5(int[] in)		
	{
		array = in; N = in.length - 1;
		sTree = new int[N<<1];		
		lazy = new int[N<<1];

	}

	int getRoot()
	{
		return sTree[1];
	}


	void update_point(int index, int val, boolean byValue)			
	{
		index += N - 1;
		if(byValue)
			sTree[index] = val;
		else
			sTree[index] = Math.max(sTree[index] + val, 0);
		while(index>1)				
		{
			index >>= 1;
			sTree[index] = sTree[index<<1] + sTree[(index<<1) + 1];		
		}
	}


	void update_range(int i, int j, int val)		
	{
		update_range(1,1,N,i,j,val);
	}

	void update_range(int node, int b, int e, int i, int j, int val)
	{
		if(i > e || j < b)		
			return;
		if(b >= i && e <= j)		
		{
			sTree[node] = Math.max(sTree[node] + (e-b+1)*val, 0) ;			
			lazy[node] += val;				
		}							
		else		
		{
			propagate(node, b, e);
			update_range(node<<1,b,(b+e)/2,i,j,val);
			update_range((node<<1)+1,(b+e)/2+1,e,i,j,val);
			sTree[node] = sTree[node<<1] + sTree[(node<<1)+1];		
		}

	}
	void propagate(int node, int b, int e)		
	{
		int mid = (b+e)/2;
		lazy[node<<1] += lazy[node];
		lazy[(node<<1)+1] += lazy[node];
		sTree[node<<1] = Math.max(sTree[node<<1] + (mid-b+1)*lazy[node], 0);		
		sTree[(node<<1)+1] = Math.max(sTree[(node<<1)+1] + (e-mid)*lazy[node], 0);		
		lazy[node] = 0;
	}

	int query(int i, int j)
	{
		return query(1,1,N,i,j);
	}

	int query(int node, int b, int e, int i, int j)	
	{
		if(i>e || j <b)
			return 0;		
		if(b>= i && e <= j)
			return sTree[node];
		propagate(node, b, e);
		int q1 = query(node<<1,b,(b+e)/2,i,j);
		int q2 = query((node<<1)+1,(b+e)/2+1,e,i,j);
		return q1 + q2;	

	}
}

