	}

	public void solve(InputReader in, PrintWriter out) {
		int[] x = new int[3];
		int[] y = new int[3];

		x[0] = in.nextInt();
		y[0] = in.nextInt();

		x[1] = in.nextInt();
		y[1] = in.nextInt();

		x[2] = in.nextInt();
		y[2] = in.nextInt();


		if (x[0] == x[1] && x[0] == x[2]) {
			out.println(1);

			return;
		}

		if (y[0] == y[1] && y[0] == y[2]) {
			out.println(1);

			return;
		}


		for (int i = 0; i < 3; i++) {
			for (int j = i + 1; j < 3; j++) {


				boolean parallelX = isParallelX(y[i], y[j]);

				if (parallelX) {
					int k = remainingPoint(i, j);

					if ((x[k] > x[i] && x[k] < x[j]) || (x[k] < x[i] && x[k] > x[j])) {
						out.println(3);

						return;
					} else {
						out.println(2);

						return;
					}
				}


				boolean parallelY = isParallelY(x[i], x[j]);

				if (parallelY) {
					int k = remainingPoint(i, j);

					if ((y[k] > y[i] && y[k] < y[j]) || (y[k] < y[i] && y[k] > y[j])) {
						out.println(3);

						return;
					} else {
						out.println(2);

						return;
					}
				}
			}
		}


		out.println(3);
	}

	private static boolean isParallelX(int ya, int yb) {
		return ya == yb;
	}

	private static boolean isParallelY(int xa, int xb) {
		return xa == xb;
	}

	private static int remainingPoint(int i, int j) {
		boolean[] b = new boolean[3];

		b[i] = true;
		b[j] = true;

		for (int k = 0; k < 3; k++) {
			if (!b[k]) {
				return k;
			}
		}

		return -1;
	}

