    static class Line {
        long a, b, c;
        Point p, q;

        public Line(Point a, Point b) {
            this.p = a;
            this.q = b;
            this.a = b.y - a.y;
            this.b = a.x - b.x;
            this.c = a.y * b.x - a.x * b.y;
        }
    }

    public static boolean compr(Line l, Point p) {
        if (l.a * p.x + l.b * p.y + l.c == 0) return true;
        return false;
    }

    public static boolean perp(Line l1, Line l2) {
        long n1 = l1.p.x - l1.q.x, m1 = l1.p.y - l1.q.y, n2 = l2.p.x - l2.q.x, m2 = l2.p.y - l2.q.y;
        if (n1 * n2 + m1 * m2 == 0) {
            return true;
        }
        return false;
    }

    public static Point a;
    public static Point b;
    public static Point c;

    public static boolean check(Line l, int i, boolean ox) {
        if (i == 0) return checker(c, l, ox);
        if (i == 1) return checker(b, l, ox);
        if (i == 2) return checker(a, l, ox);
        return false;
    }

    public static boolean checker(Point k, Line l, boolean ox) {
        long upy = Math.max(l.q.y, l.p.y), upx = Math.max(l.p.x, l.q.x), downy = Math.min(l.q.y, l.p.y), downx = Math.min(l.q.x, l.p.x);
        if (ox) {
            if (downy < k.y && k.y < upy) return false;
            else return true;
        } else {
            if (downx < k.x && k.x < upx) return false;
            else return true;
        }

    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        a = new Point(in.nextInt(), in.nextInt());
        b = new Point(in.nextInt(), in.nextInt());
        c = new Point(in.nextInt(), in.nextInt());
        Line oy = new Line(new Point(0, 0), new Point(0, 1)), ox = new Line(new Point(0, 0), new Point(1, 0));
        Line ab = new Line(a, b), bc = new Line(b, c), ac = new Line(a, c);
        Line[] lines = {ab, ac, bc};
        int ans = 0;
        if ((perp(ab, ox) && perp(ac, ox)) || (perp(ab, oy) && perp(ac, oy))) ans = 1;
        else {
            for (int i = 0; i < 3; i++) {
                if (perp(lines[i], ox)) {
                    if (check(lines[i], i, true)) ans = 2;
                    break;
                }
                if (perp(lines[i], oy)) {
                    if (check(lines[i], i, false)) ans = 2;
                    break;
                }
            }
            if (ans == 0) ans = 3;
        }
        System.out.print(ans);
    }
