	private static void solve(InputReader in, PrintWriter out) {

		int[][] tab = new int[3][2];
		for (int i = 0; i < 3; i++) {
			tab[i][0] = in.nextInt();
			tab[i][1] = in.nextInt();
		}

		int res = 3;

		if (tab[0][0] == tab[1][0] && tab[1][0] == tab[2][0]) {
			res = 1;
		}
		if (tab[0][1] == tab[1][1] && tab[1][1] == tab[2][1]) {
			res = 1;
		}

		if (res == 1) {
			out.print(res);
			return;
		}

		if (ok(tab)) {
			out.print(2);
			return;
		}

		for (int i = 0; i < 3; i++) {
			int tmp = tab[i][0];
			tab[i][0] = tab[i][1];
			tab[i][1] = tmp;
		}

		if (ok(tab)) {
			out.print(2);
			return;
		}

		out.print(3);

