public class Polyline {

    int[] x = new int[3], y = new int[3];

    void solve() {
        for (int i = 0; i < 3; i++) {
            x[i] = in.nextInt();
            y[i] = in.nextInt();
        }
        int ans = calc();
        out.println(ans);
    }

    private int calc() {
        if (x[0] == x[1] && x[1] == x[2] || y[0] == y[1] && y[1] == y[2]) return 1;
        if (ok(0, 1, 2) || ok(0, 2, 1) || ok(1, 2, 0)) return 2;
        return 3;
    }

    private boolean ok(int i, int j, int k) {
        if (x[k] == x[i] || x[k] == x[j]) {
            return y[k] >= Math.min(y[i], y[j]) && y[k] <= Math.max(y[i], y[j]);
        } else if (y[k] == y[i] || y[k] == y[j]) {
            return x[k] >= Math.min(x[i], x[j]) && x[k] <= Math.max(x[i], x[j]);
        }
        return false;
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new Polyline().solve();
        out.close();
