        int m = input.nextInt();
        if (n == 1) {
            System.out.println("Yes");
            System.out.println("a");
        } else {
            boolean graph[][] = new boolean[n][n];
            int v1, v2;
            for (int i = 0; i < m; i++) {
                v1 = input.nextInt();
                v2 = input.nextInt();
                graph[v1 - 1][v2 - 1] = true;
                graph[v2 - 1][v1 - 1] = true;
            }

            boolean isB[] = new boolean[n];
            int firsUndefIndex = -1;
            boolean broken = false;
            boolean hasAllConnections;
            for (int i = 0; i < n; i++) {
                hasAllConnections = true;
                for (int j = 0; j < n; j++) {
                    if (i == j) {
                        continue;
                    } else if (!graph[i][j]) {
                        hasAllConnections = false;
                        break;
                    }
                }
                if (hasAllConnections) {
                    isB[i] = true;
                } else if (firsUndefIndex == -1) {
                    firsUndefIndex = i;
                }
            }
            boolean isA[] = new boolean[n];
            boolean isC[] = new boolean[n];
            if (firsUndefIndex >= 0) {
                isA[firsUndefIndex] = true;
                for (int i = 0; i < n; i++) {
                    if (i == firsUndefIndex) {
                        continue;
                    }
                    if (graph[firsUndefIndex][i]) {
                        if (!isB[i]) {
                            isA[i] = true;
                        }
                    } else {
                        isC[i] = true;
                    }
                }
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (i == j) {
                            continue;
                        } else {
                            if (graph[i][j] && (isA[i] && isC[j] || isA[j] && isC[i])) {
                                broken = true;
                                break;
                            }
                            if (!graph[i][j] && (isA[i] && isA[j] || isA[i] && isB[j] || isB[i] && isA[j] || isB[i] && isB[j] || isB[i] && isC[j] || isC[i] && isB[j] || isC[i] && isC[j])) {
                                broken = true;
                                break;
                            }
                        }
                    }
                    if (broken) {
                        break;
                    }
                }
            }
            if (broken) {
                System.out.println("No");
