public class CF {
    public static void main(String[] args) {

        InputReader inputReader = new InputReader(System.in);
        PrintWriter printWriter = new PrintWriter(System.out, true);

        int n = inputReader.nextInt();
        int m = inputReader.nextInt();
        boolean[][] adj = new boolean[n][n];
        char[] vs = new char[n];
        for (int i = 0; i < m; i++) {
            int u = inputReader.nextInt() - 1;
            int v = inputReader.nextInt() - 1;
            adj[u][v] = true;
            adj[v][u] = true;
        }

        for (int i = 0; i < n; i++) {
            boolean isB = true;
            for (int j = 0; j < n; j++) {
                if (i != j && !adj[i][j]) {
                    isB = false;
                    break;
                }
            }
            if (isB) {
                vs[i] = 'b';
            }
        }

        int mark = 0;
        for (int i = 0; i < n; i++) {
            if (vs[i] != 'b') {
                vs[i] = 'a';
                mark = i;
                break;
            }
        }

        for (int i = mark; i < n; i++) {
            if (vs[i] != 'b' && adj[mark][i]) {
                vs[i] = 'a';
            }
        }

        for (int i = 0; i < n; i++) {
            if (vs[i] != 'a' && vs[i] != 'b') {
                vs[i] = 'c';
            }
        }

        boolean isPossible = true;
        out:
        for (int i = 0; i < n; i++) {
            switch (vs[i]) {
                case 'a':
                    for (int j = 0; j < n; j++) {
                        if (i != j) {
                            if ((!adj[i][j] && (vs[j] == 'b' || vs[j] == 'a')) ||
                                    (adj[i][j] && vs[j] == 'c')) {
                                isPossible = false;
                                break out;
                            }
                        }
                    }
                    break;
                case 'c':
                    for (int j = 0; j < n; j++) {
                        if (i != j) {
                            if (((vs[j] == 'b' || vs[j] == 'c') && !adj[i][j]) ||
                                    (vs[j] == 'a' && adj[i][j])) {
                                isPossible = false;
                                break out;
                            }
                        }
                    }
                    break;
            }
        }

        if (isPossible) {
            printWriter.println("Yes");
            for (char c : vs) {
                printWriter.print(c);
            }
        } else {
            printWriter.print("No");
        }

        printWriter.close();
    }

    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public int[] nextIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; ++i) {
                array[i] = nextInt();
            }
            return array;
        }

        public long[] nextLongArray(int size) {
            long[] array = new long[size];
            for (int i = 0; i < size; ++i) {
                array[i] = nextLong();
            }
            return array;
        }

        public double[] nextDoubleArray(int size) {
            double[] array = new double[size];
            for (int i = 0; i < size; ++i) {
                array[i] = nextDouble();
            }
            return array;
        }

        public String[] nextStringArray(int size) {
            String[] array = new String[size];
            for (int i = 0; i < size; ++i) {
                array[i] = next();
            }
            return array;
        }

        public boolean[][] nextBooleanTable(int rows, int columns, char trueCharacter) {
            boolean[][] table = new boolean[rows][columns];
            for (int i = 0; i < rows; ++i) {
                String row = next();
                assert row.length() == columns;
                for (int j = 0; j < columns; ++j) {
                    table[i][j] = (row.charAt(j) == trueCharacter);
                }
            }
            return table;
        }

        public char[][] nextCharTable(int rows, int columns) {
            char[][] table = new char[rows][];
            for (int i = 0; i < rows; ++i) {
                table[i] = next().toCharArray();
                assert table[i].length == columns;
            }
            return table;
        }

        public int[][] nextIntTable(int rows, int columns) {
            int[][] table = new int[rows][columns];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < columns; j++) {
                    table[i][j] = nextInt();
                }
            }
            return table;
        }

        public long[][] nextLongTable(int rows, int columns) {
            long[][] table = new long[rows][columns];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < columns; j++) {
                    table[i][j] = nextLong();
                }
            }
            return table;
        }

        public double[][] nextDoubleTable(int rows, int columns) {
            double[][] table = new double[rows][columns];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < columns; j++) {
                    table[i][j] = nextDouble();
                }
            }
            return table;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public BigInteger nextBigInteger() {
            return new BigInteger(next());
        }

        public boolean hasNext() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = readLine();
                if (line == null) {
                    return false;
                }
                tokenizer = new StringTokenizer(line);
            }
            return true;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(readLine());
            }
            return tokenizer.nextToken();
        }

        public String readLine() {
            String line;
            try {
                line = reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return line;
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
