import java.util.LinkedList;

public class AIMDiv2C {
	static int graph[][];
	static boolean b = false;
	static boolean prev = false;

	static boolean bfs(int i, int[] letter) {
		LinkedList<Integer> q = new LinkedList<>();
		q.add(i);
		letter[i] = prev ? 2 : 0;
		prev = true;
		while (!q.isEmpty()) {
			int u = q.poll();
			for (int v = 1; v < letter.length; v++) {
				if (graph[u][v] == 1 && letter[v] == -1) {
					q.addLast(v);
					if (!b) {
						if (letter[u] == 2) {
							letter[v] = 2;
						} else if (connectedToAll(v, 0, letter))
							letter[v] = 0;
						else {
							letter[u] = 1;
							letter[v] = 2;
							b = true;
						}
					} else {
						if (connectedToAll(v, 1, letter)) {
							if (connectedToAll(v, 2, letter)) {
								if (connectedToAll(v, 0, letter)) {
									letter[v] = 1;
								} else {
									letter[v] = 2;
								}
							} else if (connectedToAll(v, 0, letter)) {
								letter[v] = 0;
							} else {
								letter[v] = 1;
							}
						} else {
							return false;
						}
					}
				}
			}
		}
		return true;
	}

	public static void main(String[] args) throws Exception {
		BufferedReader bf = new BufferedReader(new InputStreamReader(System.in));
		String[] l = bf.readLine().split(" ");
		int n = Integer.parseInt(l[0]);
		int m = Integer.parseInt(l[1]);
		graph = new int[n][n];
		int letter[] = new int[n];
		for (int i = 0; i < m; i++) {
			l = bf.readLine().split(" ");
			int a = Integer.parseInt(l[0]) - 1;
			int b = Integer.parseInt(l[1]) - 1;
			graph[a][b] = graph[b][a] = 1;
		}
		Arrays.fill(letter, -1);
		for (int i = 0; i < letter.length; i++) {
			if (letter[i] == -1)
				bfs(i, letter);
		}

		for (int i = 0; i < n; i++) {
			if (letter[i] == -1 || !connectedToAll(i, 1, letter)) {
				System.out.println("No");
				return;
			}
			if (letter[i] == 0) {
				if (!connectedToAll(i, 0, letter)) {
					System.out.println("No");
					return;
				}

			} else if (letter[i] == 1) {
				if (!connectedToAll(i, 0, letter)
						|| !connectedToAll(i, 2, letter)) {
					System.out.println("No");
					return;
				}
			} else {
				if (!connectedToAll(i, 2, letter)) {
					System.out.println("No");
					return;
				}

			}
		}
		for (int i = 0; i < n; i++) {
			boolean good = true;
			for (int let = 0; let < 3; let++) {
				if (!connectedToAll(i, let, letter)) {
					good = false;
					break;
				}
			}
			if (good)
				letter[i] = 1;

		}
		for (int i = 0; i < letter.length; i++) {
			if (letter[i] == 0) {
				for (int j = 0; j < letter.length; j++) {
					if (j != i) {
						if (letter[j] == 2 && graph[j][i] == 1) {
							System.out.println("No");
							return;
						}
					}
				}
			} else if (letter[i] == 2) {
				for (int j = 0; j < letter.length; j++) {
					if (j != i) {
						if (letter[j] == 0 && graph[j][i] == 1) {
							System.out.println("No");
							return;
						}
					}
				}
			}
		}
		StringBuffer sb = new StringBuffer();
		for (int i = 0; i < letter.length; i++) {
			char x = (char) (letter[i] + 'a');
			sb.append((x));
		}
		System.out.println("Yes");
		System.out.println(sb);
	}

	private static boolean connectedToAll(int v, int let, int[] letter) {
		for (int i = 0; i < letter.length; i++) {
			if (i == v)
				continue;
			if (letter[i] == let && graph[v][i] != 1)
				return false;
		}
		return true;
	}
}

