                if (isB) {
                    res[i] = 1;
                }
            }

            boolean[] u = new boolean[n];
            for (int i = 0; i < n; ++i) {
                if (res[i] == -1) {
                    dfs(i, g, u, res);
                    break;
                }
            }
            for (int i = 0; i < n; ++i) {
                if (res[i] != -1) continue;
                if (u[i]) {
                    for (int j = 0; j < n; ++j) {
                        if (res[j] == -1) {
                            if (g[i][j] && !u[j]) {
                                out.println("No");
                                return;
                            }
                            if (!g[i][j] && u[j]) {
                                out.println("No");
                                return;
                            }
                        }
                    }
                } else {
                    for (int j = 0; j < n; ++j) {
                        if (res[j] == -1) {
                            if (g[i][j] && u[j]) {
                                out.println("No");
                                return;
                            }
                            if (!g[i][j] && !u[j]) {
                                out.println("No");
                                return;
                            }
                        }
                    }
                }
            }
            for (int i = 0; i < n; ++i) {
                if (u[i]) {
                    res[i] = 0;
                }
            }
            out.println("Yes");
            for (int c : res) {
                if (c == 0) {
                    out.print('a');
                } else if (c == 1) {
                    out.print('b');
                } else {
                    out.print('c');
                }
            }
            out.println();
        }

        private void dfs(int v, boolean[][] g, boolean[] u, int[] a) {
            u[v] = true;
            for (int i = 0; i < g.length; ++i) {
                if (g[v][i] && !u[i] && a[i] == -1) {
                    dfs(i, g, u, a);
                }
            }
        }

    }

