        int n = in.readInt();
        boolean[][] ug = new boolean[n+1][n+1];
        int[] edgeCount = new int[n+1];
        int m = in.readInt();
        for(int i=0; i<m; ++i){
            int u = in.readInt();
            int v = in.readInt();
            ug[u][v] = true;
            ug[v][u] = true;
            edgeCount[u]++;
            edgeCount[v]++;
        }
        char[] str = new char[n+1];
        char last = 'c';
        boolean flag = true;
        int i=1;
        while((flag)&&(i<=n)){
            if(edgeCount[i] != n-1) {
                if (last == 'c') {
                    str[i] = 'a';
                    last = 'a';
                } else {
                    str[i] = 'c';
                    last = 'c';
                }
                for( int j=i+1;j<=n; ++j){
                    if(ug[i][j]){
                        if(edgeCount[j]!= n-1) {
                            str[j] = str[i];
                        }
                        else{
                            str[j] = 'b';
                        }
                    }
                }
                flag = false;
                for( int j=i+1;j<=n; ++j){
                    if(!ug[i][j]){
                       flag = true;
                       i= j;
                       break;
                    }

                }
            }
            else{
                str[i] = 'b';
                i++;
            }

        }
        flag = true;
        for(i=1; i<=n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if(i==j){
                    continue;
                }
                if (Math.abs(str[j] - str[i]) == 2) {
                    if (ug[i][j]) {
                        flag = false;
                    }
                }
                else{
                    if(!ug[i][j]){
                        flag = false;
                    }
                }
            }
        }

        if(flag){
            out.println("Yes");
            for(i=1; i<=n; ++i){
                out.print(str[i]);
            }
            out.println();
        }
        else{
            out.println("No");
        }


    }

    public static void main(String[] args) throws Exception {
        solve();
        out.close();
    }







    private static class InputReader {
        private InputStream stream;
        private byte[] buffer;
        private int currentIndex;
        private int bytesRead;

        public InputReader(InputStream stream) {
            this.stream = stream;
            buffer = new byte[131072];
        }


        public InputReader(InputStream stream, int bufferSize) {
            this.stream = stream;
            buffer = new byte[bufferSize];
        }


        private int read() throws IOException {
            if (currentIndex >= bytesRead) {
                currentIndex = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentIndex++];
        }

        public String readString() throws IOException {
            int c = read();
            while (!isPrintable(c)) {
                c = read();
            }
            StringBuilder result = new StringBuilder();
            do {
                result.appendCodePoint(c);
                c = read();
            } while (isPrintable(c));
            return result.toString();
        }

        public int readInt() throws Exception {
            int c = read();
            int sign = 1;
            while (!isPrintable(c)) {
                c = read();
            }
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                if ((c < '0') || (c > '9')) {
                    throw new InputMismatchException();
                }
                result *= 10;
                result += (c - '0');
                c = read();
            } while (isPrintable(c));
            return sign * result;
        }

        public long readLong() throws Exception {
            int c = read();
            int sign = 1;
            while (!isPrintable(c)) {
                c = read();
            }
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long result = 0;
            do {
                if ((c < '0') || (c > '9')) {
                    throw new InputMismatchException();
                }
                result *= 10;
                result += (c - '0');
                c = read();
            } while (isPrintable(c));
            return sign * result;
        }

        public double readDouble() throws Exception {
            int c = read();
            int sign = 1;
            while (!isPrintable(c)) {
                c = read();
            }
            if (c == '-') {
                sign = -1;
                c = read();
            }
            boolean fraction = false;
            double multiplier = 1;
            double result = 0;
            do {
                if ((c == 'e') || (c == 'E')) {
                    return sign * result * Math.pow(10, readInt());
                }
                if ((c < '0') || (c > '9')) {
                    if ((c == '.') && (!fraction)) {
                        fraction = true;
                        c = read();
                        continue;
                    }
                    throw new InputMismatchException();
                }
                if (fraction) {
                    multiplier /= 10;
                    result += (c - '0') * multiplier;
                    c = read();
                } else {
                    result *= 10;
                    result += (c - '0');
                    c = read();
                }
            } while (isPrintable(c));
            return sign * result;
        }

        private boolean isPrintable(int c) {
            return ((c > 32) && (c < 127));
        }
    }

