  public void solve(int test, Reader input, PrintWriter out)
  {
    MyScanner in = new MyScanner(input);

    int n = in.nextInt();
    int m = in.nextInt();

    boolean[][] adj = new boolean[n][n];
    for(int i = 0; i < m; i++) {
      int a = in.nextInt() - 1;
      int b = in.nextInt() - 1;
      adj[a][b] = true;
      adj[b][a] = true;
    }

    char[] v = new char[n];
    for(int i = 0; i < n; i++) {
      int d = 0;
      for(int j = 0; j < n; j++) {
        if(j == i) continue;
        if(adj[i][j]) d++;
      }
      if(d == n-1)
        v[i] = 'b';
    }
    int a = -1;
    for(int i = 0; i < n; i++) {
      if(v[i] == 0) {
        v[i] = 'a';
        a = i;
        break;
      }
    }
    for(int i = 0; a != -1 && i < n; i++) {
      if(v[i] == 0 && a != i) {
        if(adj[a][i]) v[i] = 'a';
        else v[i] = 'c';
      }
    }

    boolean valid = true;
    for(int i = 0; i < n && valid; i++)
      if(v[i] == 0) valid = false;

    for(int i = 0; i < n && valid; i++) {
      char c = v[i];
      for(int j = 0; j < n && valid; j++) {
        if(i == j) continue;
        if(c == 'a') {
          if(!adj[i][j] && (v[j] == 'a'))
            valid = false;
          if(adj[i][j] && v[j] == 'c')
            valid = false;
        } else if(c == 'c') {
          if(!adj[i][j] && (v[j] == 'c'))
            valid = false;
          if(adj[i][j] && v[j] == 'a')
            valid = false;
        }
      }
    }
    if(valid) {
      out.println("Yes");
      out.println(new String(v));
    } else
      out.println("No");
  }


