			out.println();
			out.close();
		}
		Node[] node = new Node[n];
		for(int i=0; i<n; i++) node[i] = new Node(i);
		for(int i=0; i<m; i++){
			int u = in.nextInt()-1;
			int v = in.nextInt()-1;
			node[u].append(node[v]);
			node[v].append(node[u]);
		}
		char[] code = new char[n];
		int check = 0;
		for(int i=0; i<n; i++){
			if(node[i].cnt!=n-1) continue;
			code[i] = 'b';
			check++;
			for(Node v: node[i].edge){
				v.remove(node[i]);
			}
		}
		for(int i=0; i<n; i++){
			if(code[i]!=0) continue;
			if(!isCompleteGraph(node[i], n)){
				System.out.println("No");
				return;
			}
			code[i] = 'a';
			check++;
			for(Node v: node[i].edge){
				code[v.id] = 'a';
				check++;
			}
			break;
		}
		for(int i=0; i<n; i++){
			if(code[i]!=0) continue;
			if(!isCompleteGraph(node[i], n)){
				System.out.println("No");
				return;
			}
			code[i] = 'c';
			check++;
			for(Node v: node[i].edge){
				code[v.id] = 'c';
				check++;
			}
			break;
		}
		for(int i=0; i<n; i++){
			if(code[i]==0){
				System.out.println("No");
				return;
			}
		}
		if(check==n){
			System.out.println("Yes");
			for(int i=0; i<n; i++){
				out.write(code[i]);
			}
			out.println();
			out.close();
		}else System.out.println("No");
	}

	boolean isCompleteGraph(Node s, int n){
		BitSet used = new BitSet(n);
		BitSet tmp = new BitSet(n);
		for(Node v: s.edge){
			used.set(v.id);
		}
		used.set(s.id);
		for(Node v: s.edge){
			tmp.clear();
			tmp.set(v.id);
			for(Node vv: v.edge){
				tmp.set(vv.id);
			}
			if(!tmp.equals(used)) return false;
		}
		return true;
	}
}

