    static class TaskC {
        public void solve(int testNumber, QuickScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            boolean[][] g = new boolean[n][n];
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                g[u][v] = g[v][u] = true;
            }
            boolean ok = true;
            LOOP:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        if (i != j && j != k && i != k) {
                            if (!g[i][j] && !g[j][k] && !g[k][i]) {
                                ok = false;
                                break LOOP;
                            }
                        }
                    }
                }
            }
            if (!ok) out.println("No");
            else {
                char[] ans = new char[n];
                Set<Integer>[] diff = new Set[n];
                for (int i = 0; i < n; i++) {
                    diff[i] = new HashSet<>();
                }
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (i != j && !g[i][j]) {
                            diff[i].add(j);
                            diff[j].add(i);
                        }
                    }
                }
                LOOP2:
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (!g[i][j] || i == j) continue;
                        for (int k = 0; k < n; k++) {
                            if (i == k) continue;
                            if (g[i][j] && g[j][k] && !g[i][k]) {
                                if (ans[i] == 'b' || ans[k] == 'b') {
                                    ok = false;
                                    break LOOP2;
                                }
                                ans[j] = 'b';
                                diff[i].add(k);
                                diff[k].add(i);
                            }
                        }
                    }
                }

                for (int i = 0; i < n; i++) {
                    if (ans[i] == '\0') {
                        ans[i] = 'a';
                        for (int other : diff[i]) {
                            if (ans[other] == '\0') {
                                ans[other] = 'c';
                            }

                        }
                    }
                }
                if (!ok) out.println("No");
                else {
                    out.println("Yes");
                    for (int i = 0; i < n; i++) {
                        out.print(ans[i]);
                    }
                }
            }
        }

    }

