import java.io.IOException;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int m = in.nextInt();
        boolean[][] g = new boolean[n][n];
        for (int i = 0; i < n; ++i) g[i][i] = true;
        for (int i = 0; i < m; ++i) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            g[a][b] = g[b][a] = true;
        }
        solve(n, g);
    }

    private static void solve(int n, boolean[][] g) {
        int f = 0;
        int s = 1;
        boolean found = false;
        for (f = 0; f < n && !found; ++f) {
            for (s = f + 1; s < n && !found; ++s) {
                if (!g[f][s]) {
                    found = true;
                }
            }
        }
        --f;
        --s;

        if (!found) {
            System.out.println("Yes");
            for (int i = 0; i < n; ++i) System.out.print("a");
            return;
        }

        Set<Integer> as = new HashSet<>();
        Set<Integer> cs = new HashSet<>();
        for (int i = 0; i < n; ++i) {
            if (!g[f][i]) {
                cs.add(i);
            }
            if (!g[s][i]) {
                as.add(i);
            }
        }

        for (Integer i : as) {
            for (Integer j : as) {
                if (!g[i][j]) {
                    System.out.print("No");
                    return;
                }
            }
        }

        for (Integer i : cs) {
            for (Integer j : cs) {
                if (!g[i][j]) {
                    System.out.print("No");
                    return;
                }
            }
        }

        for (Integer i : as) {
            for (Integer j : cs) {
                if (g[i][j]) {
                    System.out.print("No");
                    return;
                }
            }
        }

        StringBuilder res = new StringBuilder();
        Set<Integer> bs = new HashSet<>();
        for (int i = 0; i < n; ++i) {
            if (as.contains(i)) {
                res.append('a');
            } else if (cs.contains(i)) {
                res.append('c');
            } else {
                res.append('b');
                for (Integer a : as) {
                    if (!g[a][i]) {
                        System.out.print("No");
                        return;
                    }
                }
                for (Integer c : cs) {
                    if (!g[c][i]) {
                        System.out.print("No");
                        return;
                    }
                }
                bs.add(i);
            }
        }

        for (Integer i : bs) {
            for (Integer j : bs) {
                if (!g[i][j]) {
                    System.out.print("No");
                    return;
                }
            }
        }

        System.out.println("Yes");
        System.out.println(res);
    }
}

