	public static ArrayList<Integer> G[];
	public static int ans[];
	public static boolean ok;
	public static boolean vis[];
	public static int n;
	public static HashSet<Integer> mp[];

	public static boolean ch(int node, int num) {

		for (int i = 0; i < n; i++) {

			if (ans[i] == num && !check(node, i))
				return false;

			if (Math.abs(ans[i] - num) <= 1 && !mp[node].contains(i))
				return false;

		}

		return true;
	}

	public static void dfs(int node, int num) {
		vis[node] = true;
		ans[node] = num;
		if (!ok)
			return;

		for (int i = 0; i < G[node].size(); i++) {
			int ne = G[node].get(i);
			if (vis[ne])
				continue;
			int num1;
			int num2;
			if (num == 0) {
				num1 = 1;
				num2 = -1;
			} else if (num == 1) {
				num1 = 0;
				num2 = 2;
			} else {
				num1 = -1;
				num2 = 1;
			}
			if (ch(ne, num)) {
				dfs(ne, num);
			} else if (num1 != -1 && ch(ne, num1)) {
				dfs(ne, num1);
			} else if (num2 != -1 && ch(ne, num2)) {
				dfs(ne, num2);
			} else {
				ok = false;
				break;
			}
		}
	}

	public static void main(String[] args) throws IOException {
		in.init(System.in);
