		for (int i = 0; i < n; i++) {
			G[i] = new ArrayList();
			parent[i] = i;
			mp[i] = new HashSet();
		}

		for (int i = 0; i < m; i++) {
			int one = in.nextInt();
			int two = in.nextInt();
			one--;
			two--;
			G[one].add(two);
			G[two].add(one);
			mp[one].add(two);
			mp[two].add(one);
		}

		for (int i = 0; i < n; i++) {
			for (int j = i + 1; j < n; j++) {
				if (G[i].size() != G[j].size() || check(i, j))
					continue;
				int j2;
				for (j2 = 0; j2 < G[i].size(); j2++) {
					if (G[i].get(j2) == j)
						continue;
					if (!mp[j].contains(G[i].get(j2)))
						break;
				}
				if (j2 == G[i].size())
					join(i, j);
			}
		}
		ans = new int[n];
		vis = new boolean[n];
		for (int i = 0; i < 3; i++) {
			for (int j = 0; j < n; j++) {
				ans[j] = -5;
				vis[j] = false;
			}
			ok = true;
			dfs(0, i);
			for (int j = 0; j < n && ok; j++) {
				if (!vis[j]) {
					int j2;
					for (j2 = 0; j2 < 3; j2++) {
						if (ch(j, j2)) {
							dfs(j, j2);
							break;
						}
					}
					if (j2 == 3) {
						ok = false;
						break;
					}
				}
			}
			if (ok) {
