import java.io.IOException;
import java.util.HashSet;
import java.util.InputMismatchException;

public class GraphAndString {
    public static void main(String[] args) {
        FasterScanner sc = new FasterScanner();

        int N = sc.nextInt();
        int M = sc.nextInt();

        IntSet[] G = new IntSet[N];
        for (int i = 0; i < N; i++) {
        	G[i] = new IntSet();
        }

        for (int i = 0; i < M; i++) {
        	int U = sc.nextInt() - 1;
        	int V = sc.nextInt() - 1;
        	G[U].add(V);
        	G[V].add(U);
        }

        char[] S = new char[N];

        for (int i = 0; i < N; i++) {
        	if (G[i].size() == N - 1) {
        		S[i] = 'b';
        	}
        }

        for (int i = 0; i < N; i++) {
        	if (S[i] == '\0') {
        		S[i] = 'a';
        		for (int j = i + 1; j < N; j++) {
        			if (!G[i].contains(j)) {
        				S[j] = 'c';
        			}
        		}
        	}
        }

        for (int i = 0; i < N; i++) {
        	for (int j = i + 1; j < N; j++) {
        		boolean should = G[i].contains(j);
        		boolean have = (Math.abs(S[i] - S[j]) <= 1);
        		if (should != have) {
        			System.out.println("No");
        			return;
        		}
        	}
        }
        System.out.println("Yes");
        System.out.println(new String(S));
    }

    public static class IntSet extends HashSet<Integer> {
		private static final long serialVersionUID = -525791443646842834L;
    }

	public static class FasterScanner {
		private byte[] buf = new byte[1024];
		private int curChar;
		private int numChars;

		public int read() {
			if (numChars == -1)
				throw new InputMismatchException();
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = System.in.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (numChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		public String nextLine() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isEndOfLine(c));
			return res.toString();
		}

		public String nextString() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isSpaceChar(c));
			return res.toString();
		}

		public long nextLong() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = read();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			} while (!isSpaceChar(c));
			return res * sgn;
		}

		public int nextInt() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = read();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			} while (!isSpaceChar(c));
			return res * sgn;
		}

	    public int[] nextIntArray(int n) {
	        int[] arr = new int[n];
	        for (int i = 0; i < n; i++) {
	            arr[i] = nextInt();
	        }
	        return arr;
	    }

		public long[] nextLongArray(int n) {
		    long[] arr = new long[n];
		    for (int i = 0; i < n; i++) {
		        arr[i] = nextLong();
		    }
		    return arr;
		}

	    private boolean isSpaceChar(int c) {
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		private boolean isEndOfLine(int c) {
			return c == '\n' || c == '\r' || c == -1;
		}
	}
}

