public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            ArrayList<ArrayList<Integer>> neig = new ArrayList<>();
            for (int i = 0; i <= n; i++) neig.add(new ArrayList<>());
            char[] ans = new char[n + 1];
            for (int i = 0; i < m; i++) {
                int v = in.nextInt();
                int u = in.nextInt();
                neig.get(u).add(v);
                neig.get(v).add(u);
            }
            for (int i = 1; i <= n; i++) {
                if (neig.get(i).size() == n - 1) ans[i] = 'b';
            }
            for (int i = 1; i <= n; i++) {
                if (ans[i] == 0) {
                    dfs(ans, neig, i);
                    break;
                }
            }
            for (int i = 1; i <= n; i++) {
                if (ans[i] == 0) {
                    ans[i] = 'c';
                }
            }
            for (int i = 1; i <= n; i++) {
                Set<Integer> neigSet = new HashSet<>();
                for (int j : neig.get(i)) {
                    neigSet.add(j);
                    if (Math.abs(ans[i] - ans[j]) > 1) {
                        out.println("No");
                        return;
                    }
                }
                for (int j = 1; j <= n; j++) {
                    if (!neigSet.contains(j) && j != i) {
                        if (Math.abs(ans[i] - ans[j]) <= 1) {
                            out.println("No");
                            return;
                        }
                    }
                }
            }
            out.println("Yes");
            for (int i = 1; i <= n; i++) out.print(ans[i]);
        }

        void dfs(char[] ans, ArrayList<ArrayList<Integer>> neig, int node) {
            ans[node] = 'a';
            for (int nei : neig.get(node)) {
                if (ans[nei] == 0) {
                    dfs(ans, neig, nei);
                }
            }
        }

    }

    static class InputReader {
        private StringTokenizer tokenizer;
        private BufferedReader reader;

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        private void fillTokenizer() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
        }

        public String next() {
            fillTokenizer();
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.*;
import java.io.*;

public class A {
    MyScanner sc;
    PrintWriter out;

    int min(int a, int b) {
        return a < b ? a : b;
    }
    int max(int a, int b) {
        return a > b ? a : b;
    }

    int N, M;
    int[] col;
    int[][] adj;
    boolean poss;
    void rec( int v, int c ){
        col[v] = c;
        for(int u=0; u<N && poss; u++){
            if( u==v ) continue;
            if( adj[v][u] == 0 ){
                if( col[u] == c ) { poss = false; return; }
                if( col[u] == 0 ){
                    rec( u, -c );
                }
            }
        }
    }

    void sol() {
        sc = new MyScanner();
        out = new PrintWriter(new BufferedOutputStream(System.out));
        N = ni(); M = ni();

        col = new int[N];
        adj = new int[N][N];
        for(int i=0; i<M; i++){
            int a = ni(), b = ni(); a--; b--;
            adj[a][b] = adj[b][a] = 1;
        }
        poss = true;
        for(int i=0; i<N && poss; i++){
            if( col[i] != 0 ) continue;
            boolean ex = false;
            for(int j=0; j<N; j++){
                if( i==j ) continue;
                if( adj[i][j] == 0 ) { ex = true; break; }
            }
            if( ex ) rec( i, -1 ); 
        }
        if( poss ){
            for(int i=0; i<N && poss; i++){
                for(int j=i+1; j<N && poss; j++){
                    int dc = col[i] - col[j];
                    if( adj[i][j] == 1 && !(dc==-1 || dc==0 || dc==1) )
                        poss = false;
                }
            }
        }
        if( poss ){
            out.println( "Yes" );
            for(int i=0; i<N; i++){
                out.print( (char)( 'a' + col[i] + 1 ) );
            }
            out.println();
        }else{
            out.println( "No" );
        }
        out.close();
    }

    public static void main(String args[]) {
        new A().sol();
    }

    class MyScanner {
        BufferedReader br;
        StringTokenizer st;

        public MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
    }

    int ni() {
        return Integer.parseInt(sc.next());
    }
}

