public class GraphAndString {

  public static void main(String[] args) {

    try {
      BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
      String input = br.readLine();

      String inputArray[] = input.split("\\s+");

      int noOfVertices = Integer.parseInt(inputArray[0]);
      int noOfEdges = Integer.parseInt(inputArray[1]);

      ArrayList<ArrayList<Integer>> adjList = new ArrayList<ArrayList<Integer>>();
      char finalString[] = new char[noOfVertices+1];

      boolean validity = true;

      for(int i = 0; i <= noOfVertices; i++) {
        adjList.add(new ArrayList<Integer>());
      }

      for(int j = 0; j < noOfEdges; j++) {
        input = br.readLine();
        inputArray = input.split("\\s+");
        adjList.get(Integer.parseInt(inputArray[0])).add(Integer.parseInt(inputArray[1]));
        adjList.get(Integer.parseInt(inputArray[1])).add(Integer.parseInt(inputArray[0]));
      }




      int startForA = -1;
      int noOfA = 0;

      for(int k = 1; k <= noOfVertices; k++) {
        if(adjList.get(k).size() == (noOfVertices-1)) {
          finalString[k] = 'b';
        }else{
          startForA = k;
        }
      }

      if(startForA != -1) {

        noOfA++;


        finalString[startForA] = 'a';
        ArrayList<Integer> aChildrenList = adjList.get(startForA);
        int aChildren = aChildrenList.size();

        for(int m = 0; m < aChildren; m++) {
          int child = aChildrenList.get(m);
          if(finalString[child] != 'b') {
            noOfA++;
            finalString[child] = 'a';
          }
        }
      }

      int startForC = -1;
      int noOfC = 0;


      for(int n = 1; n <= noOfVertices; n++) {
        if(finalString[n] != 'a' && finalString[n] != 'b') {
          startForC = n;
          break;
        }
      }

      if(startForC != -1) {
        noOfC++;

        finalString[startForC] = 'c';
        ArrayList<Integer> cChildrenList = adjList.get(startForC);
        int cChildren = cChildrenList.size();

        for(int o = 0; o < cChildren; o++) {
          int child = cChildrenList.get(o);

          if(finalString[child] != 'b') {
            noOfC++;
            finalString[child] = 'c';
          }
        }
      }



      for(int v = 1; v <= noOfVertices; v++) {
        char itself;
        if(finalString[v] == '\u0000') {
          validity = false;
          break;
        }else{
          itself = finalString[v];
        }


        if(itself != 'b') {
          ArrayList<Integer> childList = adjList.get(v);
          int vChildren = childList.size();


          int validCount = 0;

          for(int u = 0; u < vChildren; u++) {
            if(finalString[childList.get(u)] != itself && finalString[childList.get(u)] != 'b') {
              validity = false;
              break;
            }else if(finalString[childList.get(u)] == itself) {
              validCount++;
            }
          }

          if((itself == 'a' && validCount != (noOfA-1)) || (itself == 'c' && validCount != (noOfC-1))) {
              validity = false;
              break;            
          }
        }

        if(!validity) {
          break;
        }

      }

      PrintWriter pw = new PrintWriter(System.out);

      if(validity) {
        pw.println("Yes");
        for(int p = 1; p <= noOfVertices; p++) {
          pw.print(finalString[p]);
        }
        pw.println();
      }else{
        pw.println("No");
      }

      br.close();
      pw.close();

    }catch(Exception e) {

    }
  }
}

