import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class C {

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(br.readLine());
		int n = Integer.parseInt(st.nextToken());
		int m = Integer.parseInt(st.nextToken());
		boolean[][] graph = new boolean[n][n];
		for (int i = 0; i < m; i++) {
			StringTokenizer st2 = new StringTokenizer(br.readLine());
			int a = Integer.parseInt(st2.nextToken()) - 1;
			int b = Integer.parseInt(st2.nextToken()) - 1;
			graph[a][b] = true;
			graph[b][a] = true;
		}

		boolean[][] comp = new boolean[n][n];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++)
				if (j != i) {
					comp[i][j] = !graph[i][j];
				}
		}

		int[] color = new int[n]; 
		int[] neig = new int[n];
		for (int i = 0; i < n; i++) {
			int t = 0;
			for (int j = 0; j < n; j++)
				if (comp[i][j]) {
					t++;
				}
			neig[i] = t;
			if (t == 0) {
				color[i] = 2;
			}
		}
		int root = -1;
		for (int i = 0; i < n; i++) {
			if (neig[i] > 0) {
				root = i;
				break;
			}
		}
		boolean can = true;
		if (root != -1) {
			color[root] = 1;
			Queue<Integer> q = new ArrayDeque<>();
			q.add(root);
			int aes = 1;
			int ces = 0;
			while (!q.isEmpty()) {
				int cur = q.poll();
				for (int next = 0; next < n; next++)
					if (next != cur && comp[cur][next]) {
						if (color[next] == 2 || color[next] == color[cur]) {
							can = false;
						} else if (color[next] == 0) {
							if (color[cur] == 1) {
								color[next] = 3;
								ces++;
							} else {
								color[next] = 1;
								aes++;
							}
							q.add(next);
						}
					}
			}
			for (int i = 0; i < n; i++) {
				if (color[i] == 0) {
					can = false;
				}
				if (color[i] == 1 && neig[i] != ces) {
					can = false;
				} else if (color[i] == 3 && neig[i] != aes) {
					can = false;
				}
			}
		}
		if (can) {
			char[] ls = new char[] { 'a', 'b', 'c' };
