import java.io.*;
import java.lang.reflect.Array;
import java.util.*;

public class Main {

    private static InputStream inputStream;
    private static OutputStream outputStream;
    private static PrintWriter writer;
    private static InputReader reader;

    public static void main(String[] args) {
        inputStream = System.in;
        outputStream = System.out;
        reader = new InputReader(inputStream);
        writer = new PrintWriter(outputStream);
        new Main().main();
        writer.close();
    }


    static boolean[][] gragh;
    static boolean[] visit;
    static int n;
    static int[] color;

    boolean dfs(int u, int pre, int colored) {
        visit[u] = true;
        color[u] = colored;
        for (int i = 0; i < n; ++i) {
            if (i == pre || !gragh[u][i] || i == u) {
                continue;
            }
            if (visit[i] && color[i] == colored) {
                return false;
            }
            if (!visit[i] && !dfs(i, u, colored ^ 1)) {
                return false;
            }
        }
        return true;
    }

    private void main() {
        n = reader.nextInt();
        int m = reader.nextInt();
        gragh = new boolean[n][n];
        visit = new boolean[n];
        color = new int[n];
        int[] degrees = new int[n];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                gragh[i][j] = true;
            }
            degrees[i] = n - 1;
        }
        for (int i = 0; i < m; ++i) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            gragh[u][v] = gragh[v][u] = false;
            degrees[u]--;
            degrees[v]--;
        }

        for (int i = 0; i < n; ++i) {
            if (!visit[i]) {
                if (!dfs(i, i, 0)) {
                    writer.println("No");
                    return;
                }
            }
        }

        int[] ans = new int[n];
        for (int i = 0; i < n; ++i) {
            if (degrees[i] == 0) {
                ans[i] = 1;
            } else if (color[i] == 1) {
                ans[i] = 2;
            } else {
                ans[i] = 0;
            }
        }
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (ans[i] == ans[j] || Math.abs(ans[i] - ans[j]) == 1) {
                    --m;
                }
            }
        }
        if (m != 0) {
            writer.println("No");
        } else {
            writer.println("Yes");
            for (int i = 0; i < n; ++i) {
                char ch = (char) (ans[i] + 'a');
                writer.print(ch);
            }
            writer.println();
        }
    }


}


