import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

public class Main
{

    boolean[][] a;
    char[] ans;

    int dfs( int v, char q )
    {
        ans[ v ] = q;
        int res = 1;
        for( int i = 0; i < a.length; i++ )
        {
            if( a[ v ][ i ] )
            {
                if( ans[ i ] == q ) return -1;
                if( ans[ i ] == 'b' )
                {
                    int t = dfs( i, q == 'a' ? 'c' : 'a' );
                    if( t == -1 ) return -1;
                    res += t;
                }
            }
        }
        return res;
    }

    void solve() throws Exception
    {
        int n = nextInt();
        int m = nextInt();
        a = new boolean[ n ][ n ];
        for( boolean[] q : a ) Arrays.fill( q, true );
        for( int i = 0; i < m; i++ )
        {
            int u = nextInt() - 1;
            int v = nextInt() - 1;
            a[ u ][ v ] = a[ v ][ u ] = false;
        }
        for( int i = 0; i < n; i++ ) a[ i ][ i ] = false;
        ans = new char[ n ];
        Arrays.fill( ans, 'b' );
        int cc = 0;
        for( int i = 0; i < n; i++ ) if( ans[ i ] == 'b' )
        {
            int q = dfs( i, 'a' );
            if( q == -1 )
            {
                cc = -1;
                break;
            }
            if( q == 1 ) ans[ i ] = 'b';
            if( q > 1 ) cc++;
        }
        if( cc == 1 || cc == 0 )
        {
            boolean fail = false;
            for( int i = 0; i < n; i++ )
            {
                for( int j = 0; j < n; j++ )
                {
                    fail |= !a[ i ][ j ] && Math.abs( ans[ i ] - ans[ j ] ) == 2;
                }
            }
            if( fail )
            {
                out.println( "No" );
            }
            else
            {
                out.println( "Yes" );
                for( int i = 0; i < n; i++ ) out.print( ans[ i ] );
                out.println();
            }
        }
        else
        {
            out.println( "No" );
        }
    }

    public static void main( String[] args )
    {
        new Main().run();
    }

    public void run()
    {
        try
        {
            in = new BufferedReader( new InputStreamReader( System.in ) );
            out = new PrintWriter( System.out );
            solve();
        }
        catch( Exception e )
        {
            e.printStackTrace();
            System.exit( 1 );
        }
        finally
        {
            out.close();
        }
    }

    BufferedReader in;
    PrintWriter out;
    StringTokenizer st;

    String nextToken() throws IOException
    {
        while( st == null || !st.hasMoreTokens() ) st = new StringTokenizer( in.readLine() );
        return st.nextToken();
    }

    int nextInt() throws IOException
    {
        return Integer.parseInt( nextToken() );
    }

    long nextLong() throws IOException
    {
        return Long.parseLong( nextToken() );
    }

}

import java.util.*;
