public class GraphandString
{





	private static void solve(FastScanner s1, FastWriter out){

		int V = s1.nextInt();
		int E = s1.nextInt();
		if(E == 0)
		{
			if(V == 1 || V == 2)
			{
				out.println("Yes");
				out.print((V==1)?"a":"ac");
			}
			else
				out.print("No");
			return;

		}
		HashSet<Integer>[] adj = (HashSet<Integer>[])new HashSet[V+1];	
		for(int i=1;i<=V;i++)
			adj[i] = new HashSet<>();
		for(int i=1;i<=E;i++)
		{
			int u = s1.nextInt();
			int v = s1.nextInt();
			adj[u].add(v);
			adj[v].add(u);
		}
		HashSet<Integer> A = new HashSet<>();
		HashSet<Integer> B = new HashSet<>();
		HashSet<Integer> C = new HashSet<>();
		for(int i=1;i<=V;i++)
		{
			if(adj[i].size() == V-1)
				B.add(i);
		}
		for(int i=1;i<=V;i++)
		{
			if(!B.contains(i))			
			{
				A.add(i);
				for(int v:adj[i])
					if(!B.contains(v))
						A.add(v);

				break;
			}
		}
		for(int i=1;i<=V;i++)
		{
			if(!A.contains(i) && !B.contains(i))
				C.add(i);
		}

		int sA = A.size();
		int sB = B.size();
		int sC = C.size();
		for(int a:A)
		{
			int needed = sA + sB - 1;
			for(int v:adj[a])
			{
				if(A.contains(v) || B.contains(v))
					needed--;
				if(C.contains(v))
				{
					out.print("No");
					return;
				}
			}
			if(needed != 0)
			{
				out.print("No");
				return;
			}
		}
		for(int b:B)
		{
			int needed = sA + sB + sC - 1;
			for(int v:adj[b])
			{
				if(A.contains(v) || B.contains(v) || C.contains(v))
					needed--;					
			}
			if(needed != 0)
			{
				out.print("No");
				return;
			}
		}
		for(int c:C)
		{
			int needed = sC + sB - 1;
			for(int v:adj[c])
			{
				if(C.contains(v) || B.contains(v))
					needed--;
				if(A.contains(v))
				{						
					out.print("No");
					return;						
				}
			}
			if(needed != 0)
			{
				out.print("No");
				return;
			}
		}

		out.println("Yes");
		StringBuilder sb = new StringBuilder();
		sb.setLength(V);
		for(int i:A)
			sb.setCharAt(i-1, 'a');
		for(int i:B)
			sb.setCharAt(i-1, 'b');
		for(int i:C)
			sb.setCharAt(i-1, 'c');
		out.print(sb);
	}







	public static void main(String []args) throws IOException {
		FastScanner in  = new FastScanner(System.in);
		FastWriter  out = new FastWriter(System.out);
		solve(in, out);
		in.close();
		out.close();
	}    

