		if(label[i]=='x'){
			firstUnmarked = i; 
			break; 
		}
	}
	if(firstUnmarked>-1){
		label[firstUnmarked] = 'a'; 
		as.add(firstUnmarked); 
		for(int i =0; i<adjList.get(firstUnmarked).size(); i++){
			if(label[adjList.get(firstUnmarked).get(i)]=='x'){
				label[adjList.get(firstUnmarked).get(i)]='a'; 
				as.add(adjList.get(firstUnmarked).get(i)); 
			}
		}
	}

	for(int i =0; i<as.size(); i++){
		for(int j =i+1; j<as.size(); j++){
			if(!adjList.get(as.get(i)).contains(as.get(j))){
				System.out.println("No");
				return; 
			}
		}
	}
	for(int i =0; i<n; i++){
		if(label[i]=='x'){
			label[i]='c';
			cs.add(i); 
		}
	}
	for(int i =0; i<cs.size(); i++){
		for(int j =i+1; j<cs.size(); j++){
			if(!adjList.get(cs.get(i)).contains(cs.get(j))){
				System.out.println("No");
				return; 
			}
		}
	}
	String answer = ""; 
	boolean can = true;
	boolean [] taken = new boolean [n]; 
	for(int i = 0; i<n && can; i++){
		if(!taken[i]){
			answer = answer + label[i]; 
			for(int j =0; j<adjList.get(i).size(); j++){
				can = match(label[i], label[adjList.get(i).get(j)]); 
				if(!can){
					break; 
				}

			}
		}
	}
	if(can){
		System.out.println("Yes\n" + answer);
	}
	else{
		System.out.println("No");
	}

}
