    Arrays.fill(vis, -1);

    char c;

    for(int i = 1, cnt = 1; i <= n; i++){
      if(vis[i] == -1 && ans[i] == 'b') {
        if(cnt %2 == 0) c = 'c';
        else c = 'a';
        cnt++;
        dfs(vis, mat, ans, n, i, c);
      }
    }


    for(int i = 1, cnt = 1; i <= n; i++){
      if(vis[i] == -1) {
        if(cnt %2 == 0) c = 'c';
        else c = 'a';
        cnt++;
        dfs(vis, mat, ans, n, i, c);
      }
    }

    boolean bol = true;

    for(int i = 1; i <= n; i++){
      if(ans[i] == 'a'){
        for(int j = 1; j <= n; j++){
          if((ans[j] == 'a' || ans[j] == 'b') && mat[i][j] != 1 && i != j){
            bol = false;
            break;
          }
        }
      }

      else if(ans[i] == 'c'){
        for(int j = 1; j <= n; j++){
          if((ans[j] == 'b' || ans[j] == 'c') && mat[i][j] != 1 && i != j){
            bol = false;
            break;
          }
        }
      }

      if(!bol) break;
    }

    if(!bol) pw.println("No");
    else{
      pw.println("Yes");
      for(int i = 1; i <= n; i++){
        pw.print(ans[i]);
      }
      pw.println();
    }

    pw.close();
  }

  static void dfs(int vis[], int [][]mat, char [] ans, int n, int i, char c){

    vis[i] = 0;
    int cnt = 0;
    if(ans[i] == '\0') ans[i] = c;
    char a = 'a', b = 'c';
    if(a == 'c'){ a = 'c'; b = 'a';}
    for(int j = 1; j <= n; j++){
      if(mat[i][j] == 1 && ans[j] == '\0' && vis[j] == -1){
        if(cnt == 0 && ans[i] == 'b') ans[j] = a;
        else if(cnt == 1 && ans[i] == 'b') ans[j] = b;
        else if(ans[i] != 'b') ans[j] = ans[i];
        dfs(vis, mat, ans, n, j, c);
        cnt++;
      }
    }

  }

