            if (letter[i] != '\0') continue;
            boolean found = false;
            for (int j = 0; j < N; j++) {
                if (graph[i][j] && letter[j] != '\0' && letter[j] != 'b') {
                    letter[i] = letter[j];
                    found = true;
                    break;
                }
            }
            if (!found) {
                letter[i] = curr;
                curr = 'c';
            }
        }
        System.out.println(new String(letter));
    }
}

