public class Main {

    static MyScanner in;
    static PrintWriter out;

    static List<Integer>[] lists;
    static StringBuilder sb = new StringBuilder();
    static boolean w[][];

    static void paint(int i, char c) {
        sb.setCharAt(i, c);
        for (int e : lists[i]) {
            if (sb.charAt(e) == '\0') {
                paint(e, c);
            }
        }
    }

    static boolean check() {
        for (int i = 0; i < sb.length(); i++) {
            for (int j = i + 1; j < sb.length(); j++) {
                if (Math.abs(sb.charAt(i) - sb.charAt(j)) <= 1) {
                    if (!w[i][j]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        in = new MyScanner();
        out = new PrintWriter(System.out, false);

        int n = in.nextInt(), q = in.nextInt();
        sb.setLength(n);
        lists = new List[n];
        w = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            lists[i] = new ArrayList<>();
        }

        while (q-- > 0) {
            int a = in.nextInt() - 1, b = in.nextInt() - 1;
            lists[a].add(b);
            lists[b].add(a);
            w[a][b] = w[b][a] = true;
        }

        for (int i = 0; i < n; i++){
            if (lists[i].size() == n - 1) {
                sb.setCharAt(i, 'b');
            }
        }

        int cnt = 0;
        for (int i = 0; i < n; i++) {
            if (sb.charAt(i) != '\0') {
                continue;
            }
            if (cnt == 0) {
                paint(i, 'a');
                cnt++;
            } else if (cnt == 1) {
                paint(i, 'c');
                cnt++;
            } else {
                out.println("No");
                out.close();
                return;
            }
        }

        if (!check()) {
            out.println("No");
            out.close();
            return;
        }

        out.println("Yes");
        out.println(sb.toString());
        out.close();
    }
}

