            for (int i = 0; i < M; i++) {
                int v = in.nextInt() - 1;
                int w = in.nextInt() - 1;
                adj[v][w] = adj[w][v] = true;
                degree[v]++;
                degree[w]++;
            }

            char nodes[] = new char[N];

            for (int i = 0; i < N; i++) {
                if (degree[i] == N - 1) {
                    nodes[i] = 'b';
                }
            }

            for (int i = 0; i < N; i++) {
                if (nodes[i] != 'b') {
                    nodes[i] = 'a';
                    for (int j = 0; j < N; j++) {
                        if (i != j && adj[i][j] && nodes[j] == 0) {
                            nodes[j] = 'a';
                        }
                    }
                    break;
                }
            }

            for (int i = 0; i < N; i++) {
                if (nodes[i] == 0) {
                    nodes[i] = 'c';
                }
            }
            boolean answer = true;
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (i == j) continue;

                    if (adj[i][j] && Math.abs(nodes[i] - nodes[j]) == 2) {
                        answer = false;
                    } else if (!adj[i][j] && Math.abs(nodes[i] - nodes[j]) != 2) {
                        answer = false;
                    }
                }
            }

            if (!answer) {
                out.println("No");
                return;
            }

            out.println("Yes");
            for (int i = 0; i < N; i++) {
                out.print(nodes[i]);
            }
            out.println();
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
