import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;


public class CF_624C {
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt(), m = scan.nextInt();
		int[] degrees = new int[n];
		ArrayList<Integer>[] edgeLists = new ArrayList[n];
		for(int i=0;i<n;i++)
			edgeLists[i] = new ArrayList<>();
		for(int i=0;i<m;i++) {
			int a = scan.nextInt()-1, b = scan.nextInt()-1;
			edgeLists[a].add(b);
			edgeLists[b].add(a);
			degrees[a]++;
			degrees[b]++;
		}

		char[] string = new char[n];
		Arrays.fill(string, '\0');
		for(int i=0;i<n;i++) {
			if(degrees[i] == n-1)
				string[i] = 'b';
		}
		int countA = -1;
		int countC = -1;
		for(int i=0;i<n;i++) {
			char type = string[i];
			if(type == 'b')
				continue;
			if(type == 'a' || type == 'c') {
				int count = 0;
				for(int edge : edgeLists[i]) {
					if(string[edge] == 'b')
						continue;
					if(string[edge] != type) {
						System.out.println("No");
						System.err.println(type + " connects to " + string[edge]);
						return;
					}
					count++;
				}
				boolean works = type == 'a' ? countA==count : countC==count;
				if(!works) {
					System.out.println("No");
					System.err.println(type + " hits " + count + ", should hit more");
					return;
				}
				continue;
			}
			char newType;
			if(countA == -1) {
				newType = 'a';
			} else if(countC == -1) {
				newType = 'c';
			} else {
				System.out.println("No");
				System.err.println("Used all available letters");
				return;
			}
			string[i] = newType;
			int count = 0;
			for(int edge : edgeLists[i]) {
				if(string[edge] == 'b')
					continue;
				if(string[edge] != type) {
					System.out.println("No");
					System.err.println("New empty letter is attached to an old letter");
					return;
				}
				string[edge] = newType;
				count++;
			}
			if(newType == 'a') {
				countA = count;
			} else if(newType == 'c') {
				countC = count;
			} 

		}
		System.out.println("Yes");
		System.out.println(new String(string));
	}
}

