import java.util.Queue;
import java.util.StringTokenizer;

public class C {

	public static boolean bfs(int index, int [][] adjMat, int [] color) { 
		Queue<Integer> queue = new LinkedList<Integer>();

		color[index] = 0;
		queue.add(index);

		boolean atLeastOne = false;

		while(!queue.isEmpty()) { 
			Integer top = queue.poll();

			for(int j=0; j<color.length; j++) { 

				if(j == top) continue;
				if(adjMat[top][j] == 1) continue;

				if(color[j] == -1) { 
					color[j] = 2 - color[top];
					atLeastOne = true;
					queue.add(j);

				} else if(color[j] == color[top]){ 
					return false;
				}
			}

		}

		if(!atLeastOne) { 
			color[index] = -1;
		}
		return true;

	}

	public static void main(String [] args) throws IOException { 
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer tokenizer = new StringTokenizer(br.readLine());

		int V = Integer.parseInt(tokenizer.nextToken());
		int E = Integer.parseInt(tokenizer.nextToken());

		int [][] adjMat = new int[V][V];

		for(int i=0; i<E; i++) { 
			tokenizer = new StringTokenizer(br.readLine());
			int v1 =  Integer.parseInt(tokenizer.nextToken());
			int v2 = Integer.parseInt(tokenizer.nextToken());
			v1--;
			v2--;
			adjMat[v1][v2] = 1;
			adjMat[v2][v1] = 1;
		}

		int [] color = new int[V];
		for(int i=0; i<V; i++)
			color[i] = -1;

		for(int i=0; i<V; i++) { 
			if(color[i] == -1) { 
				boolean result = bfs(i, adjMat, color);

				if(!result) { 
					System.out.println("No");
					return;
				}			
}
		}

		for(int i=0; i<V; i++) { 
			for(int j=i+1; j<V; j++) { 
				if(adjMat[i][j] == 1) { 
					if(color[i] != -1 && color[j] != -1) {

						if(Math.abs(color[i] - color[j]) > 1) { 
							System.out.println("No");
							return;
						}
					}

					if(color[i] == -1) color[i] = 1;
					if(color[j] == -1) color[j] = 1;

				}
			}
		}

		System.out.println("Yes");

		StringBuilder sb = new StringBuilder();

		for(int i=0; i<V; i++) { 
			if(color[i] == -1) { 
				sb.append('b');
			} else { 
				sb.append((char)('a' + color[i]));
			}
		}

		System.out.println(sb.toString());


	}

}

