public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskA solver = new TaskA();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskA {
		boolean bipartite;

		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int m = in.nextInt();
			boolean[][] g = new boolean[n][n];
			int[] deg = new int[n];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					if (i != j) {
						g[i][j] = true;
						++deg[i];
					}
				}
			}
			for (int i = 0; i < m; i++) {
				int a = in.nextInt() - 1;
				int b = in.nextInt() - 1;
				g[a][b] = false;
				g[b][a] = false;
				--deg[a];
				--deg[b];
			}
			char[] ans = new char[n];
			bipartite = true;
			Arrays.fill(ans, 'b');
			for (int i = 0; i < n; i++) {
				if (ans[i] == 'b' && deg[i] > 0) {
					dfs(i, g, ans, 'a');
				}
			}
			if (!bipartite) {
				out.println("No");
				return;
			}
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					boolean ac = ans[i] == 'a' && ans[j] == 'c';
					boolean ca = ans[i] == 'c' && ans[j] == 'a';
					if (g[i][j] != (ac || ca)) {
						out.println("No");
						return;
					}
				}
			}
			out.println("Yes");
			out.println(new String(ans));
		}

		private void dfs(int i, boolean[][] g, char[] ans, char ch) {
			ans[i] = ch;
			for (int j = 0; j < g.length; j++) {
				if (!g[i][j]) {
					continue;
				}
				if (ans[j] == 'b') {
					dfs(j, g, ans, rev(ch));
				} else if (ans[j] != rev(ch)) {
					bipartite = false;
				}
			}
		}

		private char rev(char ch) {
			return ch == 'a' ? 'c' : 'a';
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

