    			adjlist[u].add(v);
    			adjlist[v].add(u);
    			adjmat[u][v] = 1;
    			adjmat[v][u] = 1;
    		}

    		for(int i=0;i<n;i++) {
    			if(adjlist[i].size()==n-1) {
    				ans[i] = 1;
    			}
    		}

    		int k = 0;
    		for(int i=0;i<n;i++) {
    			if(ans[i]==-1) {
    				dfs(i, k);
    				k += 2;
    			}
    		}

