public class C {

	static int V;
	static int[] s;
	static boolean[][] adjMat;


	static boolean color(int u, int c)
	{
		s[u] = c;
		for(int v = 0; v < V; ++v)
			if(u != v && !adjMat[u][v])
			{
				if(s[v] == -1)
				{
					if(!color(v, c ^ 1))
						return false;
				}
				else
					if(s[v] == s[u])
						return false;

			}
		return true;
	}

	public static void main(String[] args) throws IOException 
	{
		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		V = sc.nextInt();
		int E = sc.nextInt();
		s = new int[V];
		Arrays.fill(s, -1);
		adjMat = new boolean[V][V];
		int[] deg = new int[V];
		while(E-->0)
		{
			int u = sc.nextInt() - 1, v = sc.nextInt() - 1;
			adjMat[u][v] = adjMat[v][u] = true;
			deg[u]++;
			deg[v]++;
		}

		boolean possible = true;
		for(int i = 0; possible && i < V; ++i)
			if(s[i] == -1 && deg[i] != V - 1)
				possible &= color(i, 1);

		for(int i = 0; possible && i < V; ++i)
			for(int j = 0; j < V; ++j)
				if(adjMat[i][j] && s[i] + s[j] == 1)
					possible = false;
			if(!possible)
				out.println("No");
			else
			{
				out.println("Yes");
				StringBuilder ans = new StringBuilder();
				for(int i = 0; i < V; ++i)
					if(s[i] == -1)
						ans.append('b');
					else
						if(s[i] == 0)
							ans.append('a');
						else
							ans.append('c');
				out.println(ans);
			}
		out.flush();
		out.close();

	}


	static class Scanner 
	{
		StringTokenizer st;
		BufferedReader br;

		public Scanner(InputStream s){	br = new BufferedReader(new InputStreamReader(s));}

		public String next() throws IOException 
		{
			while (st == null || !st.hasMoreTokens()) 
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		public int nextInt() throws IOException {return Integer.parseInt(next());}

		public long nextLong() throws IOException {return Long.parseLong(next());}

		public String nextLine() throws IOException {return br.readLine();}

		public double nextDouble() throws IOException
		{
			String x = next();
			StringBuilder sb = new StringBuilder("0");
			double res = 0, f = 1;
			boolean dec = false, neg = false;
			int start = 0;
			if(x.charAt(0) == '-')
			{
				neg = true;
				start++;
			}
			for(int i = start; i < x.length(); i++)
				if(x.charAt(i) == '.')
				{
					res = Long.parseLong(sb.toString());
					sb = new StringBuilder("0");
					dec = true;
				}
				else
				{
					sb.append(x.charAt(i));
					if(dec)
						f *= 10;
				}
			res += Long.parseLong(sb.toString()) / f;
			return res * (neg?-1:1);
		}

		public boolean ready() throws IOException {return br.ready();}
	}
}

import java.util.*;

public class graph_and_string
{
    static int n, m;

    static ArrayList<Integer>[] e;

    static int[] c;

    static boolean search;

    @SuppressWarnings("unchecked")
    public static void main( String[] args )
    {
        Scanner in = new Scanner( System.in );
        n = in.nextInt();
        m = in.nextInt();
        e = new ArrayList[n + 1];
        for ( int i = 1; i <= n; i++ )
            e[i] = new ArrayList<Integer>();
        for ( int i = 0; i < m; i++ )
        {
            int u = in.nextInt(), v = in.nextInt();
            e[u].add( v );
            e[v].add( u );
        }
        c = new int[n + 1];
        for ( int i = 1; i <= n; i++ )
            if ( e[i].size() == n - 1 )
                c[i] = 2;
        search = false;
        for ( int i = 1; i <= n && !search; i++ )
            if ( c[i] == 0 )
                fill( i, 1 );
        search = false;
        for ( int i = 1; i <= n && !search; i++ )
            if ( c[i] == 0 )
                fill( i, 3 );
        if ( !all() || !cxed() )
            System.out.println( "No" );
        else
        {
            System.out.println( "Yes" );
            for ( int i = 1; i <= n; i++ )
                System.out.print( (char)( c[i] - 1 + 'a' ) );
        }
        in.close();
        System.exit( 0 );
    }

    public static boolean cxed()
    {
        for ( int i = 1; i < n; i++ )
            for ( int j = i + 1; j <= n; j++ )
                if ( Math.abs( c[i] - c[j] ) <= 1 && !e[i].contains( j ) )
                    return false;
                else if ( Math.abs( c[i] - c[j] ) > 1 && e[i].contains( j ) )
                    return false;
        return true;
    }

    public static boolean all()
    {
        for ( int i = 1; i <= n; i++ )
            if ( c[i] == 0 )
                return false;
        return true;
    }

    public static void fill( int x, int co )
    {
        LinkedList<Integer> q = new LinkedList<Integer>();
        q.add( x );
        while ( !q.isEmpty() )
        {
            int v = q.pop();
            ArrayList<Integer> adj = e[v];
            for ( int i = 0; i < adj.size(); i++ )
                if ( c[adj.get( i )] == 0 )
                    q.add( adj.get( i ) );
            c[v] = co;
        }
        search = true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.StringTokenizer;

public class Solution {

	static int M;
	static int N;
	static int[] dx = { -1,1,0,0};
	static int[] dy = {0,0,-1,1};

	static class FastReader
    {
        BufferedReader br;
        StringTokenizer st;

        public FastReader()
        {
            br = new BufferedReader(new
                     InputStreamReader(System.in));
        }

        String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException  e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }

	public static void DFS(int row, int col, char[][] g, boolean[][]filled) {
		filled[row][col] = true;
		for(int m = 0 ; m < 4; m ++) {
			int rnew = dx[m] + row;
			int cnew = dy[m] + col;
			if(rnew >= 0 && rnew < M && cnew >=0 && cnew < N && g[rnew][cnew] == '.' && !filled[rnew][cnew] )
				DFS(rnew, cnew, g, filled);
		}

	}
	public static void DFS2(int row, int col, char[][] g, boolean[][]filled, ArrayList<Point> ps) {
		filled[row][col] = true;
		ps.add(new Point(row, col));
		for(int m = 0 ; m < 4; m ++) {
			int rnew = dx[m] + row;
			int cnew = dy[m] + col;
			if(rnew >= 0 && rnew < M && cnew >=0 && cnew < N && g[rnew][cnew] == '.' && !filled[rnew][cnew] )
				DFS2(rnew, cnew, g, filled,ps);
		}
	}
	public static class Point{
		int row;
		int col;
		public Point(int row, int col) {
			super();
			this.row = row;
			this.col = col;
		}

	}

	public static class Lake {
		ArrayList<Point> ps;
	}

	public static void main(String[] args)  {

		FastReader fr = new FastReader();
		int row = fr.nextInt();
		M = row;
		int col = fr.nextInt();
		N = col;
		int k = fr.nextInt();
		char[][] g = new char[row][col];
		for(int i = 0 ; i < row; i ++) {
			fr.nextLine().getChars(0, col, g[i], 0);

		}
		boolean[][]filled = new boolean[row][col];

		for(int i = 0 ; i < row; i ++) {
			for( int j = 0; j < col ; j ++) {
				if( i == 0 || j == 0 || j == col - 1 || i == row -1) {
					if(g[i][j] == '.' && !filled[i][j])  
						DFS(i, j, g, filled);
				}
			}
		}

		ArrayList<Lake> lakes = new ArrayList<>();
		for(int i = 0 ; i < row; i ++) {
			for( int j = 0; j < col ; j ++) {
				if(g[i][j] == '.' && !filled[i][j]){
					Lake lake = new Lake();
					ArrayList<Point> ps = new ArrayList<Point>();
					DFS2(i, j, g, filled, ps);
					lake.ps = ps;
					lakes.add(lake);
				}
			}
		}
		Collections.sort(lakes, (p,q) -> p.ps.size() - q.ps.size());
		int total = lakes.size();
		int run = 0;
		int ans = 0;
		while(total - run > k) {
			Lake lake = lakes.get(run);
			for(Point p : lake.ps) {
				g[p.row][p.col] = '*';
			}
			ans += lake.ps.size();
			run++;
		}
		PrintWriter pw = new PrintWriter(System.out);
		pw.println(ans);
		for(int i = 0; i < row; i ++) pw.println(g[i]);
		pw.close();
	}

}

import java.util.*;

public class FloodFill_LakesInBerland {

	static int N, M , K;
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();
		M = sc.nextInt();
		K = sc.nextInt();
		boolean[][] area = new boolean[N][M];
		sc.nextLine();
		for (int r = 0; r < N; r++)
		{
			String next = sc.next();
			for (int c = 0; c < M; c++)
			{
				if (next.charAt(c) == '.')
					area[r][c] = true;
			}
		}
		boolean[][] copy = new boolean[N][M];
		for (int i = 0; i < N; i++)
			copy[i] = Arrays.copyOf(area[i], M);


		ArrayList<Lake> lakes = new ArrayList<Lake>();
		for (int r = 0; r < N; r++)
		{
			for (int c = 0; c < M; c++)
			{
				if (copy[r][c])
				{
					int size = fill(r, c, copy);
					if (size != 0)
					{
						lakes.add(new Lake(new Point(r, c), size));
					}
				}
			}
		}

		int lakesToRemove = lakes.size() - K;
		Collections.sort(lakes);
		int landAdded = 0;
		for (int k = 0; k < lakesToRemove; k++)
		{
			Lake l = lakes.get(k);
			landAdded += l.size;
			fill(l.p.r, l.p.c, area);

		}
		System.out.print(landAdded);
		StringBuilder sb = new StringBuilder();
		for (boolean[] row : area)
		{
			sb.append("\n");
			for (boolean b : row)
			{
				if (b)
					sb.append("."); 
				else
					sb.append("*");
			}
		}
		System.out.print(sb);
	}

	public static int fill(int r, int c, boolean[][] arr)
	{
		Queue<Point> explore = new ArrayDeque<Point>();
		explore.add(new Point(r, c));
		int size = 0;
		while (!explore.isEmpty())
		{
			Point p = explore.poll();
			if (arr[p.r][p.c]) {
				if (isBorder(p.r, p.c))		
				{
					do
					{
						if (arr[p.r][p.c]) {
							arr[p.r][p.c] = false;
							for (int[] d : dirs)
							{
								if (isValid(p.r + d[0], p.c + d[1]))
									explore.add(new Point(p.r + d[0], p.c + d[1]));

							}
							arr[p.r][p.c] = false;		
						}
						p = explore.poll();
					}  while (p != null);
					return 0;	
				}

				arr[p.r][p.c] = false;
				size++;
				for (int[] d : dirs)
				{
					if (isValid(p.r + d[0], p.c + d[1]))
						explore.add(new Point(p.r + d[0], p.c + d[1]));
				}
			}
		}
		return size;
	}

	public static int[][] dirs = { {1, 0}, {-1, 0}, {0, 1}, {0, -1} }; 

	public static class Lake implements Comparable<Lake>{
		Point p;
		int size;
		public Lake (Point p, int size) { this.p = p; this.size = size; }
		public int compareTo(Lake other) { return Integer.compare(this.size, other.size); }
	}


	public static class Point {
		int r, c;
		public Point (int r, int c) { this.r = r;  this.c = c;}
	}

	public static boolean isValid(int r, int c)
	{
		if (r >= 0 && r < N && c >= 0 && c < M)
			return true;
		return false;
	}


	public static boolean isBorder(int r, int c)
	{
		if (c == 0 || c == M - 1 || r == 0 || r == N - 1)
			return true;
		return false;

	}

}

import java.util.*;

public class LakesInBerland {
    static class Lake {
        public Lake(Cell c, int water) {
            this.c = c;
            this.water = water;
        }
        Cell c;
        int water;
    }

    static class Cell {
        int r;
        int c;
        Cell(int _r, int _c) {
            this.r = _r;
            this.c = _c;
        }
    }

    static int[] r = {-1, 0, 1, 0};
    static int[] c = {0, -1, 0, 1};

    static int N;
    static int M;
    static char[][] maze;
    static List<Lake> lakes;
    static boolean[][] visited;
    static boolean isValid(int r, int c) {
        return r > -1 && r < N && c > -1 && c < M;
    }

    static void DFS(Cell s, boolean isRemove) {
        boolean isOceanConnected = false;
        Stack<Cell> stack = new Stack<>();
        int water = maze[s.r][s.c] == '.' ? 1 : 0;
        stack.add(s);
        if(isRemove) maze[s.r][s.c] = '*';
        visited[s.r][s.c] = true;
        Cell tmp;
        while (!stack.isEmpty()) {
            tmp = stack.pop();
            for (int k = 0; k < 4; k++) {
                int rv = tmp.r + r[k];
                int cv = tmp.c + c[k];
                if (!isValid(rv, cv)) {
                    isOceanConnected = true;
                    continue;
                }
                if (!visited[rv][cv] && maze[rv][cv] == '.') {
                    water++;
                    if(isRemove){
                        maze[rv][cv] = '*';
                    }
                    visited[rv][cv] = true;
                    stack.add(new Cell(rv, cv));
                }
            }
        }
        if (!isOceanConnected && !isRemove) {
            lakes.add(new Lake(s,water));
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        int K = sc.nextInt();
        maze = new char[N][M];
        for (int i = 0; i < N; i++) {
            maze[i] = sc.next().toCharArray();
        }

        lakes = new ArrayList<>();
        visited = new boolean[N][M];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (maze[i][j] == '*' || visited[i][j]) {
                    continue;
                }
                DFS(new Cell(i, j), false);
            }
        }

        lakes.sort(Comparator.comparingInt(o -> o.water));
        int count = 0;
        visited = new boolean[N][M];
        if (lakes.size() > K) {
            int rm = lakes.size() - K;
            for (int i = 0; i < rm; i++) {
                count+=lakes.get(i).water;
                DFS(lakes.get(i).c,true);
            }
        }
        System.out.println(count);
        for(int i=0;i<N;i++){
            System.out.println(maze[i]);
        }
    }
}

