			return;
		if(vis[i][j])
			return;
		vis[i][j] = true;
		grid[i][j] = '*';
		fill(i+1,j);
		fill(i-1,j);
		fill(i,j+1);
		fill(i,j-1);
	}

	static int find(int i, int j)
	{

		if(i<0 || i>=n || j<0 || j>=m)
		{

			return -100000;
		}


