public class Round375D {
	public static void main(String[] args) throws NumberFormatException, IOException {
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		m = sc.nextInt();

		int k = sc.nextInt();

		grid = new char[n][m];
		visited = new boolean[n][m];

		for(int i = 0; i < n; i++)
			grid[i] = sc.nextLine().toCharArray();

		for(int i = 0; i < n; i++)
		{
			fillOc(i, 0);
			fillOc(i, m - 1);
		}

		for(int i = 0; i < m; i++) {
			fillOc(0, i);
			fillOc(n - 1, i);
		}

		int count = 0;

		ArrayList<Integer> res = new ArrayList<Integer>();

		for(int i = 0; i < n; i++)
			for(int j = 0; j < m; j++) {
				if(validW(i,j)) {
					int c = countCC(i, j);
					count++;
					res.add(c);
				}
			}

		int fill = count - k;

		int ret = 0;

		int occ[] = new int[n * m + 1];

		Collections.sort(res);

		for(int i = 0; i < fill; i++) {
			occ[res.get(i)]++;
			ret += res.get(i);
		}

		visited = new boolean[n][m];

		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(validW(i, j)) {
					int c = countCC(i, j);
					if(occ[c] > 0){
						occ[c]--;
						for(int i1 = 0; i1 < n; i1++)
							for(int i2 = 0; i2 < m; i2++) {
								if(visited[i1][i2])
									grid[i1][i2] = '*';
							}
					}

					visited = new boolean[n][m];
				}
			}

		}

		PrintWriter out = new PrintWriter(System.out);
		out.println(ret);

		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++)
				if(grid[i][j] == 'O')
					out.print('.');
				else
					out.print(grid[i][j]);
			out.println();
		}

		out.flush();
		out.close();


	}
	static char grid[][];
	static boolean visited[][];
	static int n,m;
	static boolean validW(int i, int j) {
		return i >= 0 && i < n && j >=0 && j < m && grid[i][j] == '.' && !visited[i][j]; 
	}

	static int[] dx = {1, -1, 0, 0};
	static int[] dy = {0, 0, 1, -1};

	static void fillOc(int i, int j) {
		if(!validW(i, j))
			return;

		grid[i][j] = 'O';

		for(int x = 0; x < 4; x++) {
			fillOc(i + dx[x], j + dy[x]);
		}
	}

	static int countCC(int i, int j) {
		if(!validW(i, j))
			return 0;

		visited[i][j] = true;

		int res = 1;

		for(int x = 0; x < 4; x++)
			res += countCC(i + dx[x], j + dy[x]);


		return res;
	}

	static class Scanner {
		BufferedReader br;
		StringTokenizer st;

		Scanner(FileReader f) {
			br = new BufferedReader(f);
		}

		public boolean ready() throws IOException {
			return br.ready();
		}

		Scanner(InputStream s) {
			br = new BufferedReader(new InputStreamReader(s));
		}

		String next() throws IOException {
			while (st == null || !st.hasMoreTokens())
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		String nextLine() throws IOException {
			return br.readLine();
		}

		int nextInt() throws NumberFormatException, IOException {
			return Integer.parseInt(next());
		}

		long nextLong() throws NumberFormatException, IOException {
			return Long.parseLong(next());
		}
	}
}

import java.util.*;
import java.io.*;
import java.util.LinkedList;

public class CF723D{ 
  public static int index;
  public static char mat[][];
  public static int n, m, k, vis[][], dirx[], diry[];
  public static void main(String[] args)throws Exception {
    InputReader in = new InputReader(System.in);
    PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));
    n = in.nextInt(); m = in.nextInt(); k = in.nextInt();

    dirx = new int[]{0, 1, 0, -1};
    diry = new int[]{1, 0, -1, 0};

    mat = new char[n+1][m+1];
    vis = new int[n+1][m+1];

    for(int i = 1; i <= n; i++){
      String s = in.next();
      for(int j = 1; j <= m; j++){
        mat[i][j] = s.charAt(j-1);
      }
    }


    ArrayList<Node> list = new ArrayList<Node>();

    int idx = -1;

    for(int i = 1; i <= n; i++){
      for(int j = 1; j <= m; j++){
        if((i == 1 || i == n || j == 1 || j == m ) && mat[i][j] == '.' && vis[i][j] == 0){
          bfs(i,j,idx);
        }
      }
    }

    idx = 1;
    for(int i = 2; i < n; i++){
      for(int j = 2; j < m; j++){
        if(mat[i][j] == '.' && vis[i][j] == 0){
          list.add(new Node(bfs(i,j,idx), idx++));
        }
      }
    }

    Collections.sort(list);

    int d = list.size() - k;

    int ans = 0;
    for(int i = 0; i < d; i++){
      ans += list.get(i).dots;
      color(list.get(i).idx);
    }

    pw.println(ans);

    for(int i = 1; i <= n; i++){
      for(int j = 1; j <= m; j++){
        pw.print(mat[i][j]);
      }
      pw.println();
    }

    pw.close();
  }


  static void color(int idx){
    for(int i = 1; i <= n; i++){
      for(int j = 1; j <= m; j++){
        if(mat[i][j] == '.' && vis[i][j] == idx){
           mat[i][j] = '*';
        }
      }
    }
  }

  static boolean isValid(int x, int y){
    return x >= 1 && x <= n && y >= 1 && y <= m && mat[x][y] == '.' && vis[x][y] == 0;
  }

  static int bfs(int x, int y, int idx){
    Queue<Integer> q = new LinkedList<Integer>();
    q.add(x); q.add(y);
    vis[x][y] = idx;
    int count = 1;

    while(!q.isEmpty()){
      int xx = q.poll(), yy = q.poll();
      for(int i = 0; i < 4; i++){
        int dx = xx + dirx[i], dy = yy + diry[i];
        if(isValid(dx, dy)){
          vis[dx][dy] = idx;
          count++;
          q.add(dx); q.add(dy);
        }
      }

    }

    return count;

  }


  static class Node implements Comparable<Node>{
    public int dots, idx;
    public Node(int i, int j){
      dots = i; idx = j;
    }
    public int compareTo(Node nd){
      return dots - nd.dots;
    }
    public String toString(){
      return dots+" "+idx;
    }
  }

  static class InputReader {
    public BufferedReader reader;
    public StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
      reader = new BufferedReader(new InputStreamReader(stream));
      tokenizer = null;
    }

    public String next()throws Exception {
      while (tokenizer == null || !tokenizer.hasMoreTokens())
        tokenizer = new StringTokenizer(reader.readLine());
      return tokenizer.nextToken();
    }

    public String nextLine()throws Exception {
      String line = null;
      tokenizer = null;
      line =  reader.readLine();
      return line;
    }

    public int nextInt()throws Exception {
      return Integer.parseInt(next());
    }

    public double nextDouble() throws Exception{
      return Double.parseDouble(next());
    }

    public long nextLong()throws Exception {
      return Long.parseLong(next());
    }

  }
}

