public class R375D2P4 {

	public static void main(String[] args) throws Exception {
		BufferedReader bf = new BufferedReader(new InputStreamReader(System.in));

		StringTokenizer st = new StringTokenizer(bf.readLine());
		int n = Integer.parseInt(st.nextToken());
		int m = Integer.parseInt(st.nextToken());
		int k = Integer.parseInt(st.nextToken());

		char[][] map = new char[n][];
		for (int i = 0; i < n; i++) {
			map[i] = bf.readLine().trim().toCharArray();
		}

		boolean[][] visited = new boolean[n][m];
		PriorityQueue<LinkedList<int[]>> queue = new PriorityQueue<>(new Comparator<LinkedList<int[]>>() {
			@Override
			public int compare(LinkedList<int[]> a, LinkedList<int[]> b) {
				return a.size() - b.size();
			}
		});
		for (int startRow = 0; startRow < n; startRow++) {
			for (int startCol = 0; startCol < m; startCol++) {

				if (visited[startRow][startCol]) {
					continue;
				}
				if (map[startRow][startCol] == '*') {
					continue;
				}

				LinkedList<int[]> coords = new LinkedList<>();
				boolean isOcean = dfs(startRow, startCol, map, visited, coords);
				if (!isOcean) {
					queue.add(coords);
				}
			}
		}

		int num = 0;
		while (queue.size() > k) {
			LinkedList<int[]> cur = queue.remove();
			for (int[] coord : cur) {
				map[coord[0]][coord[1]] = '*';
			}
			num += cur.size();
		}

		System.out.println(num);
		for (int i = 0; i < n; i++) {
			System.out.println(new String(map[i]));
		}
	}

	public static final int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 }, };

	private static boolean dfs(int row, int col, char[][] map, boolean[][] visited, LinkedList<int[]> coords) {
		boolean isOcean = (row == 0) || (col == 0) || (row == map.length - 1) || (col == map[0].length - 1);

		visited[row][col] = true;
		coords.add(new int[] { row, col });

		for (int i = 0; i < 4; i++) {
			int nextRow = row + dirs[i][0];
			int nextCol = col + dirs[i][1];
			if (nextRow >= 0 && nextRow < map.length && nextCol >= 0 && nextCol < map[0].length) {
				if (!visited[nextRow][nextCol] && map[nextRow][nextCol] == '.') {
					isOcean |= dfs(nextRow, nextCol, map, visited, coords);
				}
			}
		}
		return isOcean;
	}
}

