            }
        }
        ArrayList<lake> arr=new ArrayList<lake>();
        lake l;
        for(int i=0;i<n;++i)
        {
            for(int j=0;j<m;++j)
            {
                if(ar[i][j]=='.' && visited[i][j]==-1)
                {
                    l=new lake(0,0,0);
                    l.size=findSize(ar,visited,i,j,n,m);
                    l.row=i;
                    l.col=j;
                    arr.add(l);
                }
            }
        }
        Collections.sort(arr,new Comparator<lake>(){
           public int compare(lake l1,lake l2)
           {
               if(l1.size<l2.size)
               {
                   return 1;
               }
               else if(l1.size==l2.size)
               {
                   return 0;
               }
               else
               {
