    public static int findSize(char ar[][],int visited[][],int i,int j,int n,int m)
    {
        if(ar[i][j]=='*')
        {
            return 0;
        }
        if(visited[i][j]!=-1)
        {
            return 0;
        }
        visited[i][j]=0;
        int a=0,b=0,c=0,d=0;
        if(i>0)
        {
            a=findSize(ar,visited,i-1,j,n,m);
        }
        if(i<n-1)
        {
            b=findSize(ar, visited, i+1, j, n, m);
        }
        if(j>0)
        {
            c=findSize(ar, visited, i, j-1, n, m);
        }
        if(j<m-1)
        {
            d=findSize(ar, visited, i, j+1, n, m);
        }
        visited[i][j]=a+b+c+d+1;
        return visited[i][j];
    }

    public static void changeLakeOceanic(char ar[][],int i,int j,int n,int m)
    {
        if(ar[i][j]=='*')
        {
            return;
        }
        ar[i][j]='*';
        if(i>0)
        {
            changeLakeOceanic(ar,i-1,j,n,m);
        }
        if(i<n-1)
        {
            changeLakeOceanic(ar,i+1,j,n,m);
        }
        if(j>0)
        {
            changeLakeOceanic(ar, i, j-1, n, m);
        }
        if(j<m-1)
        {
            changeLakeOceanic(ar, i, j+1, n, m);
        }
        return;
    }
};

