public class Main {
    public static void main(String[] args) {
        ConsoleIO io = new ConsoleIO();
        new Main(io).solve();
        io.close();
    }
    ConsoleIO io;
    Main(ConsoleIO io) {
        this.io = io;
    }

    long MOD = 1_000_000_007;
    int N, M, Q;

    class Group{
        public Group(int i, int j){
            row = i;
            col = j;
        }
        public int row;
        public int col;
    }

    int[] dx = {0,1,0,-1};
    int[] dy = {1,0,-1,0};

    public void solve() {
        int[] l = io.readIntArray();
        N = l[0];
        M = l[1];
        int Max = l[2];
        char[][] all = new char[N][];
        for (int i = 0; i < N; i++) {
            char[] cc = io.readLine().toCharArray();
            all[i] = cc;
        }

        Group[] q = new Group[N * M + 5];
        char lakeId = 1000;
        List<Group> list = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (all[i][j] == '.') {
                    int count = 0;
                    boolean good = true;
                    int head = 0;
                    int tail = 1;
                    all[i][j] = lakeId;
                    q[0] = new Group(i, j);
                    while (head < tail) {
                        Group cur = q[head++];
                        if (cur.row == 0 || cur.row == N - 1 || cur.col == 0 || cur.col == M - 1) {
                            good = false;
                        }
                        count++;
                        for (int a = 0; a < 4; a++) {
                            int r = cur.row + dx[a];
                            int c = cur.col + dy[a];
                            if (r >= 0 && r < N && c >= 0 && c < M && all[r][c] == '.') {
                                all[r][c] = lakeId;
                                q[tail++] = new Group(r, c);
                            }
                        }
                    }

                    if (good) {
                        list.add(new Group(lakeId, count));
                    }
                    lakeId++;
                }
            }
        }

        list.sort((Group g1, Group g2) -> {
            return g1.col - g2.col;
        });

        int res = 0;
        int[] look = new int[4100];
        for (int i = 0; i + Max < list.size(); i++) {
            Group g = list.get(i);
            res += g.col;
            look[g.row] = 1;
        }

        io.writeLine(res + "");
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                int c = all[i][j];
                if (look[c] == 1)
                    all[i][j] = '*';
                else if (c != '.' && c != '*')
                    all[i][j] = '.';

            }
            io.writeLine(new String(all[i]));
        }


    }

}

