	static int dirI[] = {0, 0, 1, -1}, dirJ[] = {1, -1, 0, 0}; 
	static Scanner input = new Scanner(System.in);

	private static void constructLake(int row, int column, int numberOfRows, int numberOfColumns)
	{

		List currentLake = new ArrayList<Point>();
		boolean isOcean = false; 

		Queue <Point> queue = new LinkedList <Point> ();
		queue.add(new Point(row, column)); 

		while (queue.isEmpty() == false) 
		{			 
			 Point currentPoint = queue.element(); 
			 queue.remove(); 


			 if (visited[currentPoint.row][currentPoint.column] == true)
				 continue; 
			 visited[currentPoint.row][currentPoint.column] = true; 


			 if (currentPoint.row == 0 || currentPoint.row == numberOfRows-1)
				 isOcean = true; 
			 if (currentPoint.column == 0 || currentPoint.column == numberOfColumns-1)
				 isOcean = true; 

			 currentLake.add(currentPoint); 



			 for (int index = 0; index < 4; index++)
			 {
				 int nextRow = currentPoint.row + dirI[index]; 
				 int nextColumn = currentPoint.column + dirJ[index];


				 if (nextRow < 0 || nextColumn < 0 || nextRow >= numberOfRows || nextColumn >= numberOfColumns)
					 continue; 

				 if (map[nextRow][nextColumn] == '*')
					 continue; 

				 if (visited[nextRow][nextColumn] == true)
					 continue; 

				 queue.add(new Point(nextRow, nextColumn)); 
			 }		 
		}

		if (isOcean == false)  
			lake.add(currentLake);


	}

	public static void main(String[] args)
	{
		int numberOfRows = input.nextInt();
		int numberOfColumns = input.nextInt(); 
		int requiredLakes = input.nextInt(); 

		for (int row = 0; row < numberOfRows; row++)
		{
			String line = input.next();
			for (int column = 0; column < numberOfColumns; column++)
				map[row][column] = line.charAt(column);
		}

		for (int row = 1; row < numberOfRows-1; row++) 
			for (int column = 1; column < numberOfColumns-1; column++)
				if (map[row][column] == '.' && visited[row][column] == false) 
					constructLake(row, column, numberOfRows, numberOfColumns);

		Collections.sort(lake, new Comparator<List<Point>>() {
			public int compare(List<Point> list1, List<Point> list2)
				{return list1.size() - list2.size();}
		});

		int result = 0; 
		for (int lakesDestroyed = 0; lakesDestroyed < lake.size()-requiredLakes; lakesDestroyed++)
			for (int index = 0; index < lake.get(lakesDestroyed).size(); index++)
			{
				int changeRow = lake.get(lakesDestroyed).get(index).row; 
				int changeColumn = lake.get(lakesDestroyed).get(index).column;
				map[changeRow][changeColumn] = '*'; 

				result++;
			}

		System.out.println(result); 
		for (int row = 0; row < numberOfRows; row++)
		{
			for (int column = 0; column < numberOfColumns; column++)
				System.out.print(map[row][column]);
			System.out.println();
		}
	} 	
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;


public class Main {

    static boolean[][] visited;
    static boolean[][] visited2;
    static int[] X = {1,-1,0,0};
    static int[] Y = {0,0, 1, -1};
    static int n,m;
    static char[][] earth;
    static int cntLakeCells;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        n = sc.nextInt();
        m = sc.nextInt();

        int k = sc.nextInt();
        earth = new char[n][m];
        visited = new boolean[n][m];
        for(int i=0; i<n; i++ ) {
            String str = sc.next();
            for (int j = 0; j < m; j++) {
                earth[i][j] = str.charAt(j);
            }
        }

        ArrayList<Lake> lakes = new ArrayList<>();

        for(int i=0; i<n; i++ ) {
            for (int j = 0; j < m; j++) {
                if(earth[i][j] == '.' && visited[i][j] == false) {
                    cntLakeCells = 0;
                    if(dfs(i, j)) {
                        Lake lake = new Lake(cntLakeCells, j,i);
                        lakes.add(lake);
                    }
                }
            }
        }

        int lakeSize = lakes.size();
        Collections.sort(lakes);
        int i=0;
        int covered = 0;
        visited2 = new boolean[n][m];
        while(lakeSize > k){
            Lake lake = lakes.get(i);
            coverLake(lake.y, lake.x);
            covered += lake.cells;
            lakeSize--;
            i++;
        }

        System.out.println(covered);

        for (int j = 0; j < n; j++) {
            for (int l = 0; l < m; l++) {
                System.out.print(earth[j][l]);
            }
            System.out.println();
        }

    }

    public static void coverLake(int y, int x) {
        if(y >= n || x >= m) return;
        if(y < 0 || x < 0) return;
        if(earth[y][x] == '*') return;
        if(visited2[y][x] == true) return;

        visited2[y][x] = true;
        earth[y][x] = '*';

        for(int i=0; i<4; i++) {
            coverLake(y+Y[i], x+X[i]);
        }

    }
    public static boolean dfs(int y, int x) {
        if(y >= n || x >= m) return false;
        if(y < 0 || x < 0) return false;
        if(earth[y][x] == '*') return true;
        if(visited[y][x] == true) return true;

        visited[y][x] = true;
        cntLakeCells++;


        boolean isLake = true;
        for(int i=0; i<4; i++) {
            isLake = isLake & dfs(y+Y[i], x+X[i]);
        }

        return isLake;
    }

    private static class Lake implements Comparable<Lake> {
        int cells;
        int x,y;

        public Lake(int cells, int x, int y) {
            this.cells = cells;
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Lake o) {
            return Integer.compare(cells, o.cells);
        }
    }
}

import java.util.*;
import java.util.stream.Collectors;


public class D {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n, m, k;
        n = in.nextInt(); m = in.nextInt(); k = in.nextInt();

        char[][] field = new char[n][];

        for (int i = 0; i < n; ++i) {
            field[i] = in.next().toCharArray();
        }

        List<Point> lakePts = new ArrayList<>();
        for (int i = 0; i < n; ++i) for (int j = 0; j < m; ++j) {
            if (field[i][j] == '.') lakePts.add(new Point(j, i));
        }

        for (Point pt1 : lakePts) for (Point pt2 : lakePts) if (pt1 != pt2 && pt1.isNeighbor(pt2)) {
            pt1.neighbors.add(pt2);
        }

        int currentGroup = 1;
        for (Point pt : lakePts) if (pt.group == -1) {
            markGroup(pt, currentGroup);
            ++currentGroup;
        }

        Map<Integer, List<Point>> lakes = lakePts.stream().collect(Collectors.groupingBy(pt -> pt.group));

        List<List<Point>> realLakes = lakes.entrySet().stream()
                .map(Map.Entry::getValue)
                .filter(lake -> !lake.stream().anyMatch(pt -> pt.isOnBorder(m, n)))
                .collect(Collectors.toList());

        realLakes.sort(Comparator.comparing(lake -> lake.size()));

        int deleted = 0;
        for (int i = 0; i < (realLakes.size() - k); ++i) {
            deleted += realLakes.get(i).size();

            for (Point pt : realLakes.get(i)) field[pt.y][pt.x] = '*';
        }

        System.out.println(deleted);
        for (char[] line : field) System.out.println(new String(line));
    }

    private static void markGroup(Point pt, int group) {
        if (pt.group != -1) return;
        pt.group = group;

        for (Point neighbor : pt.neighbors) markGroup(neighbor, group);
    }

    private static class Point {
        int x, y;
        int group = -1;
        List<Point> neighbors = new ArrayList<>();

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public boolean isOnBorder(int m, int n) {
            return x == 0 || x == m - 1 || y == 0 || y == n - 1;
        }

        public boolean isNeighbor(Point other) {
            return (Math.abs(x - other.x) == 1 && y == other.y) || (Math.abs(y - other.y) == 1 && x == other.x);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Point point = (Point) o;
            return x == point.x &&
                    y == point.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }
}

