    public static void dfs(int i, int j)
    {
        vis[i][j] = 1;
        num++;
        if (i == n || i == 1 || j == 1 || j == m)
            ocean = 1;
        if (t[i + 1][j] == '.' && vis[i + 1][j] == 0)
            dfs(i + 1, j);
        if (t[i][j + 1] == '.' && vis[i][j + 1] == 0)
            dfs(i, j + 1);
        if (t[i][j - 1] == '.' && vis[i][j - 1] == 0)
            dfs(i, j - 1);
        if (t[i - 1][j] == '.' && vis[i - 1][j] == 0)
            dfs(i - 1, j);
    }
    public static void dfs_modify(int i, int j)
    {
        t[i][j] = '*';
        if (t[i + 1][j] == '.')
            dfs_modify(i + 1, j);
        if (t[i][j + 1] == '.')
            dfs_modify(i, j + 1);
        if (t[i][j - 1] == '.')
            dfs_modify(i, j - 1);
        if (t[i - 1][j] == '.')
            dfs_modify(i - 1, j);
    }
