import java.util.*;
import java.io.*;
public class LakesinBerland
{




	static int x[] = {-1 , 0 , 1 , 0}; 
	static int y[] = {0 , 1 , 0 , -1};
	static int R , C;
	static boolean marked[][];
	static char grid[][];
	static boolean isValid(int i , int j) {
		return i >= 0 && i < R && j >= 0 && j < C;
	}
	static boolean isEdge(int i , int j) {
		return i == 0 || i == R - 1 || j == 0 || j == C - 1;
	}


	static int dfsCount(int i , int j) {
		int cnt = 1;
		marked[i][j] = true;
		boolean flag = isEdge(i, j);

		for(int k = 0;k<4;k++)
			if(isValid(x[k]+i, y[k]+j) && grid[x[k]+i][y[k]+j] == '.' && !marked[x[k] + i][y[k] + j]) {
				int res = dfsCount(x[k] + i, y[k] + j);
				if(res > 0 )
					cnt += res;
				flag |= res == -1;
			}

		if(flag)
			return -1;
		else
			return cnt;
	}

	static void fill(int i , int j) {
		marked[i][j] = true;
		grid[i][j] = '*';
		for(int k = 0;k<4;k++)
			if(isValid(x[k]+i, y[k]+j) && grid[x[k]+i][y[k]+j] == '.' && !marked[x[k] + i][y[k] + j])
				fill(i + x[k], j + y[k]);
	}

	static class Lake implements Comparable<Lake> {
		int x , y , size;
		Lake(int _x , int _y , int _size) {
			x = _x;
			y = _y;
			size = _size;
		}
		@Override
		public int compareTo(Lake o) {
			return Integer.compare(this.size, o.size);
		}
		@Override
		public String toString() {
			return "["+x+", " + y+"] " + "sz " + size;
		}
	}
	private static void solve(FastScanner s1, PrintWriter out){

		R = s1.nextInt();
		C = s1.nextInt();
		int K =  s1.nextInt();
		grid = new char[R][];
		marked = new boolean[R][C];
		for(int i=0;i<R;i++)
			grid[i] = s1.nextLine().toCharArray();

		ArrayList<Lake> lakes = new ArrayList<>();

		for(int i=0;i<R;i++)
			for(int j=0;j<C;j++)
				if(!marked[i][j] && grid[i][j] == '.') {
					int sz = dfsCount(i, j);
					if(sz > 0)
						lakes.add(new Lake(i, j, sz));
				}


		Collections.sort(lakes);
		int cnt = 0;
		marked = new boolean[R][C];
		for(int i=0,need = lakes.size() - K;i < need;i++) {
			fill(lakes.get(i).x, lakes.get(i).y);
			cnt += lakes.get(i).size;
		}


		out.println(cnt);
		for(int i=0;i<R;i++)
			out.println(new String(grid[i]));

	}	











	public static void main(String []args) throws IOException {
		FastScanner in  = new FastScanner(System.in);
		PrintWriter out = 
				new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)), false); 
		solve(in, out);
		in.close();
		out.close();
	}    

	static class FastScanner{
		BufferedReader reader;
		StringTokenizer st;
		FastScanner(InputStream stream){reader=new BufferedReader(new InputStreamReader(stream));st=null;}	
		String next()
		{while(st == null || !st.hasMoreTokens()){try{String line = reader.readLine();if(line == null){return null;}		    
		st = new StringTokenizer(line);}catch (Exception e){throw new RuntimeException();}}return st.nextToken();}
		String nextLine()  {String s=null;try{s=reader.readLine();}catch(IOException e){e.printStackTrace();}return s;}	    	  	
		int    nextInt()   {return Integer.parseInt(next());}
		long   nextLong()  {return Long.parseLong(next());}		
		double nextDouble(){return Double.parseDouble(next());}
		char   nextChar()  {return next().charAt(0);}
		int[]  nextIntArray(int n)         {int[] arr= new int[n];   int i=0;while(i<n){arr[i++]=nextInt();}  return arr;}
		long[] nextLongArray(int n)        {long[]arr= new long[n];  int i=0;while(i<n){arr[i++]=nextLong();} return arr;}	
		int[]  nextIntArrayOneBased(int n) {int[] arr= new int[n+1]; int i=1;while(i<=n){arr[i++]=nextInt();} return arr;}	    	
		long[] nextLongArrayOneBased(int n){long[]arr= new long[n+1];int i=1;while(i<=n){arr[i++]=nextLong();}return arr;}	    	
		void   close(){try{reader.close();}catch(IOException e){e.printStackTrace();}}				
	}


}

import java.util.*;

public class Main {
    static final int MAX = 51;
    static int[] dr = {0, 0, 1, -1};
    static int[] dc = {1, -1, 0, 0};
    static int n, m, k;
    static boolean[][] visited = new boolean[MAX][MAX];
    static char[][] table = new char[MAX][MAX];

    static class Cell {
        int r, c;

        public Cell(int _r, int _c) {
            this.r = _r;
            this.c = _c;
        }
    };

    static ArrayList<ArrayList<Cell>> lakes = new ArrayList<ArrayList<Cell>>();

    public static boolean isValid(int r, int c) {
        return r >= 0 && c >= 0 && r < n && c < m;
    }

    public static boolean onBorder(int r, int c) {
        return r == 0 || c == 0 || r == n - 1 || c == m - 1;
    }

    public static void DFS(Cell scr) {
        Stack<Cell> s = new Stack<>();
        visited[scr.r][scr.c] = true;
        s.add(scr);

        boolean isOcean = false;
        ArrayList<Cell> temp = new ArrayList<>();

        while (!s.isEmpty()) {
            Cell u = s.pop();
            temp.add(u);

            if (onBorder(u.r, u.c)) {
                isOcean = true;
            }

            for (int i = 0; i < 4; i++) {
                int r = u.r + dr[i];
                int c = u.c + dc[i];

                if (isValid(r, c) && table[r][c] == '.' && !visited[r][c]) {
                    visited[r][c] = true;
                    s.add(new Cell(r, c));
                }
            }
        }

        if (!isOcean) {
            lakes.add(temp);
        }
    }

    static class SortBySize implements Comparator<ArrayList<Cell>> {
        public int compare(ArrayList<Cell> a, ArrayList<Cell> b) {
            return a.size() - b.size();
        }
    }

    public static void main(String[] agrs) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();

        for (int i = 0; i < n; i++) {
            table[i] = sc.next().toCharArray();
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j] && table[i][j] == '.') {
                    DFS(new Cell(i, j));
                }
            }
        }

        Collections.sort(lakes, new SortBySize());
        int sum_cell = 0;

        for (int i = 0; i < lakes.size() - k; i++) {
            sum_cell += lakes.get(i).size();
            for (Cell u : lakes.get(i)) {
                table[u.r][u.c] = '*';
            }
        }

        System.out.println(sum_cell);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                System.out.print(table[i][j]);
            }
            System.out.println();
        }
    }
}

