import java.io.IOException;
import java.io.FileInputStream;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.Objects;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.util.Comparator;
import java.util.Collections;
import java.io.InputStream;


public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        DLakesInBerland solver = new DLakesInBerland();
        solver.solve(1, in, out);
        out.close();
    }

    static class DLakesInBerland {
        private int n;
        private int m;
        private char[][] arr;
        private int[][] vis;
        private int comp_id = 1;
        private int comp_size;

        private boolean isValid(int x, int y) {
            return x >= 0 && x <= n + 1 && y >= 0 && y <= m + 1 && arr[x][y] == '.' && vis[x][y] == 0;
        }

        private void floodFill(int x, int y) {
            vis[x][y] = comp_id;
            comp_size++;
            if (isValid(x + 1, y)) floodFill(x + 1, y);
            if (isValid(x - 1, y)) floodFill(x - 1, y);
            if (isValid(x, y + 1)) floodFill(x, y + 1);
            if (isValid(x, y - 1)) floodFill(x, y - 1);
        }

        private void printMatrix(OutputWriter out) {
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    out.print(arr[i][j]);
                }
                out.println();
            }
        }

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            int k = in.nextInt();
            arr = new char[n + 2][m + 2];
            for (int i = 0; i <= n + 1; i++) {
                arr[i][0] = arr[i][m + 1] = '.';
            }
            for (int j = 0; j <= m + 1; j++) {
                arr[0][j] = arr[n + 1][j] = '.';
            }

            for (int i = 1; i <= n; i++) {
                String str = in.nextLine();
                for (int j = 1; j <= m; j++) {
                    arr[i][j] = str.charAt(j - 1);
                }
            }
            vis = new int[n + 2][m + 2];
            floodFill(0, 0);
            ArrayList<Util.Pair<Integer>> al = new ArrayList<>();
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (arr[i][j] == '.' && vis[i][j] == 0) {
                        comp_size = 0;
                        comp_id++;
                        floodFill(i, j);
                        al.add(new Util.Pair<>(comp_size, comp_id));
                    }
                }
            }
            int numOfLakes = comp_id - 1;
            if (numOfLakes == k) {
                out.println(0);
                printMatrix(out);
                out.flush();
                return;
            }
            Collections.sort(al, Comparator.comparingInt(o -> o.x));
            HashSet<Integer> hs = new HashSet<>();
            int toDelete = numOfLakes - k;
            int cellsChanged = 0;
            for (int i = 0; i < toDelete; i++) {
                Util.Pair<Integer> p = al.get(i);
                cellsChanged += p.x;
                hs.add(p.y);
            }
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (arr[i][j] == '.' && hs.contains(vis[i][j])) arr[i][j] = '*';
                }
            }
            out.println(cellsChanged);
            printMatrix(out);
            out.flush();
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;
        private ArrayList<String> res = new ArrayList<>();
        private StringBuilder sb = new StringBuilder("");

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

