public class MainD {
	static int[][] dir = new int[][]{{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
	public static void main(String args[]){
		Scanner scanner = new Scanner (System.in);
		String s = scanner.nextLine();
		String[] ss = s.split(" ");
		int n = Integer.parseInt(ss[0]);
		int m = Integer.parseInt(ss[1]);
		int k = Integer.parseInt(ss[2]);

		char[][] map = new char[n][m];
		for(int i = 0; i < n; i ++){
			map[i] = scanner.nextLine().toCharArray();
		}

		scanner.close();

		char[][] mapcopy = copymap(map);

		for(int j = 0; j < m; j ++){
			fill(mapcopy, 0, j);
			fill(mapcopy, n - 1, j);
		}

		for(int i = 0; i < n; i ++){
			fill(mapcopy, i, 0);
			fill(mapcopy, i, m - 1);
		}



		PriorityQueue<Water> waters = new PriorityQueue<Water>();

		for(int i = 0; i < n; i ++){
			for(int j = 0; j < m; j ++){
				if(mapcopy[i][j] == '.'){
					int size = fill(mapcopy, i, j);
					Water w = new Water(i, j, size);
					waters.add(w);
				}
			}
		}

		char[][] copy2 = copymap(map);
		int num = 0;
		while(waters.size() > k){
			Water w = waters.poll();
			num += fill(copy2, w.x, w.y);
		}


		System.out.println(num);


		printmap(copy2);
	}

	private static int fill(char[][] map, int x, int y){
		int[] size = new int[1];
		size[0] = 0;
		fillInner(map, x, y, size);
		return size[0];
	}

	private static void fillInner(char[][]map, int x, int y, int[] size){
		if(!in(map, x, y))
			return;
		if(map[x][y] == '*')
			return;
		size[0] ++;
		map[x][y] = '*';
		for(int i = 0; i < dir.length; i ++){
			fillInner(map, x + dir[i][0], y + dir[i][1], size);
		}
	}

	private static boolean in(char[][] map, int x, int y){
		int n = map.length;
		int m = map[0].length;
		if(x >= 0 && x < n && y >= 0 && y < m)
			return true;
		return false;
	}

	private static char[][] copymap(char[][] map){
		char[][] copymap = new char[map.length][map[0].length];
		for(int i = 0; i < map.length; i ++){
			for(int j = 0; j < map[i].length; j ++){
				copymap[i][j] = map[i][j];
			}
		}

		return copymap;
	}

	private static void printmap(char[][] map){
		for(int i = 0; i < map.length; i ++){
			for(int j = 0; j < map[0].length; j ++){
				System.out.print(map[i][j]);
			}
			System.out.println();
		}
	}
}

