public final class Problem723D {

	private Problem723D() {}

	private static final char WATER = '.', LAND = '*';
	private static int numRows, numCols;
	private static char[][] grid;

	public static void main(String[] args) {
		Scanner input = new Scanner(System.in);
		numRows = input.nextInt();
		numCols = input.nextInt();
		grid = new char[numRows][numCols];
		int target = input.nextInt();
		input.nextLine();
		for (int i = 0; i < numRows; ++i)
			grid[i] = input.nextLine().toCharArray();
		input.close();

		DisjointSets connectedBodies = new DisjointSets(numRows * numCols);

		for (int j = 0; j < numCols; ++j) {
			connectedBodies.merge(0, getID(0, j));
			connectedBodies.merge(0, getID(numRows - 1, j));
		}
		for (int i = 0; i < numRows; ++i) {
			connectedBodies.merge(0, getID(i, 0));
			connectedBodies.merge(0, getID(i, numCols - 1));
		}

		for (int i = 1; i < numRows; ++i)
			for (int j = 1; j < numCols; ++j) {
				int id = getID(i, j);
				if (grid[i][j] == LAND) {
					connectedBodies.merge(0, id);
				} else {
					if (grid[i][j - 1] == WATER)
						connectedBodies.merge(getID(i, j - 1), id);
					if (grid[i - 1][j] == WATER)
						connectedBodies.merge(getID(i - 1, j), id);
				}
			}

		int toEliminate = (connectedBodies.numSets() - 1) - target;
		ArrayList<Integer> lakes = new ArrayList<>(connectedBodies.numSets() - 1);
		for (int i = numCols + 1; i < numRows * numCols; ++i) {
			if (connectedBodies.size(i) != 0 
					&& connectedBodies.find(0) != connectedBodies.find(i))
				lakes.add(i);
		}

		Collections.sort(lakes, new Comparator<Integer>() {
			@Override
			public int compare(Integer a, Integer b) {
				return connectedBodies.size(a) - connectedBodies.size(b);
			}
		});

		int result = 0;
		for (int i = 0; i < toEliminate; i++)
			result += connectedBodies.size(lakes.get(i));

		System.out.println(result);

		for (int i = 0; i < numRows; ++i) {
			for (int j = 0; j < numCols; ++j) {
				int id = getID(i, j);
				int loc = lakes.indexOf(connectedBodies.find(id));
				if (loc != -1 && loc < toEliminate) grid[i][j] = LAND;
				System.out.print(grid[i][j]);
			}
			System.out.println();
		}

	}

	private static int getID(int x, int y) {
		return x * numCols + y;
	}

}


final class DisjointSets {



	private int[] parent, size;
	private int numSets;

	public DisjointSets(int numSets) {
		parent = new int[numSets];
		size = new int[numSets];
		for (int i = 0; i < size.length; ++i)
			size[i] = 1;
		this.numSets = numSets;
		for (int i = 0; i < parent.length; ++i)
			parent[i] = i;
	}

	public int find(int x) {
		if (parent[x] != x)
			parent[x] = find(parent[x]);
		return parent[x];
	}

	public void merge(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (size[y] > size[x]) {
			int temp = x;
			x = y;
			y = temp;
		}
		parent[y] = x;
		size[x] += size[y];
		--numSets;
	}

	public int numSets() {return numSets;}

	public int size(int id) {

		if (parent[id] != id) return 0;
		return size[id];
	}

}

