public class apples{
	public static void main(String []args){
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		int m=sc.nextInt();
		int k=sc.nextInt();
		int graph[][]=new int[n][m];
		int graph1[][]=new int[n][m];
		PriorityQueue<lnode> pq=new PriorityQueue<lnode>(new comp());
		for(int i=0;i<n;i++){
			String s=sc.next();
			for(int j=0;j<m;j++){
				if(s.charAt(j)=='*'){
					graph[i][j]=1;
					graph1[i][j]=1;
				}
				else{
					graph[i][j]=0;
					graph1[i][j]=0;
				}
			}
		}
		for(int i=0;i<n;i++){
			for(int j=0;j<m;j++){
				if(graph[i][j]==0){
					dfs(graph,i,j,n,m,pq);
				}
			}
		}
		int ans=0;
		while(pq.size()>k){
			lnode temp=pq.poll();
			ans+=temp.sum;
			change(graph1, temp.i,temp.j,n,m);
		}
		System.out.println(ans);
		for(int i=0;i<n;i++){
			for(int j=0;j<m;j++){
				if(graph1[i][j]==1)
					System.out.print("*");
				else
					System.out.print(".");
			}
			System.out.println();
		}
	}
	public static void change(int graph[][], int i, int j, int n, int m){
		Stack<Integer> st1=new Stack<Integer>();
		Stack<Integer> st2=new Stack<Integer>();
		st1.push(i);
		st2.push(j);
		graph[i][j]=1;
		while(!st1.isEmpty()){
			int a=st1.peek();
			int b=st2.peek();
			if(a+1<n&&graph[a+1][b]==0){
				graph[a+1][b]=1;
				st1.push(a+1);
				st2.push(b);
			}
			else if(b+1<m&&graph[a][b+1]==0){
				graph[a][b+1]=1;
				st1.push(a);
				st2.push(b+1);
			}
			else if(a-1>=0&&graph[a-1][b]==0){
				graph[a-1][b]=1;
				st1.push(a-1);
				st2.push(b);
			}
			else if(b-1>=0&&graph[a][b-1]==0){
				graph[a][b-1]=1;
				st1.push(a);
				st2.push(b-1);
			}
			else{
				st1.pop();
				st2.pop();
			}
		}
	}
	public static void dfs(int graph[][], int i, int j, int n, int m,PriorityQueue<lnode> pq){
		Stack<Integer> st1=new Stack<Integer>();
		Stack<Integer> st2=new Stack<Integer>();
		st1.push(i);
		st2.push(j);
		graph[i][j]=-1;
		int sum=0;
		int count =0;
		while(!st1.isEmpty()){
			int a=st1.peek();
			int b=st2.peek();
			if(a+1>=n||b+1>=m||a-1<0||b-1<0){
				count=1;
			}
			if(a+1<n&&graph[a+1][b]==0){
				graph[a+1][b]=-1;
				st1.push(a+1);
				st2.push(b);
			}
			else if(b+1<m&&graph[a][b+1]==0){
				graph[a][b+1]=-1;
				st1.push(a);
				st2.push(b+1);
			}
			else if(a-1>=0&&graph[a-1][b]==0){
				graph[a-1][b]=-1;
				st1.push(a-1);
				st2.push(b);
			}
			else if(b-1>=0&&graph[a][b-1]==0){
				graph[a][b-1]=-1;
				st1.push(a);
				st2.push(b-1);
			}
			else{
				st1.pop();
				st2.pop();
				sum++;
			}
		}
		if(count==0)
			pq.offer(new lnode(i,j,sum));
	}
}
class lnode{
	int i;
	int j;
	int sum;
	lnode(int i, int j, int sum){
		this.i=i;
		this.j=j;
		this.sum=sum;
	}
}
class comp implements Comparator<lnode>{
	public int compare(lnode a, lnode b){
		return a.sum-b.sum;
	}
}

