	static int dfs(int x, int y, int c)
	{
		int ret = 1;
		grid[x][y] = '$';
		getCC[x][y] = c;
		for(int k = 0; k < 4; ++k)
		{
			int i = x + dx[k], j = y + dy[k];
			if(valid(i, j))
			{
				if(grid[i][j] != '.')
					continue;
				int cur = dfs(i, j, c);
				if(cur == -1)
					ret = -1;
				if(ret != -1)
					ret += cur;
			}
			else
				ret = -1;
		}
		return ret;
	}

