			makeLand[ccs.get(i).idx] = true;
			ans += ccs.get(i).count;
		}
		for(int i = 0; i < R; ++i)
			for(int j = 0; j < C; ++j)
				if(grid[i][j] == '$')
					if(makeLand[getCC[i][j]])
