					else
						grid[i][j] = '.';
		out.println(ans);
		for(char[] x: grid)
			out.println(x);
		out.flush();
		out.close();
	}

	static class Pair implements Comparable<Pair>
	{
		int idx, count;

		Pair(int a, int b) { idx = a; count = b; }

