	}

	public static int dfs(int x, int y, boolean fill) {

		if (valid(x, y))
			if (fill) {
				if (grid[x][y] == '.'){
					grid[x][y] = '*';

				dfs(x - 1, y, fill);
				dfs(x + 1, y, fill);
				dfs(x, y - 1, fill);
				dfs(x, y + 1, fill);
				}
				return 0;
			}
			else
			{
				if(visited[x][y] || grid[x][y]!='.')
					return 0;
				else
				{
					visited[x][y]=true;
					return 1+dfs(x - 1, y, fill)
							+dfs(x + 1, y, fill)
							+dfs(x, y - 1, fill)
							+dfs(x, y + 1, fill);
				}
			}

		return -(int) 1e6;
	}

