class mergesort{
    static void sort(int l, int h, int[] arr){
        if(l<h){
            int mid = (l+h)/2;

            sort(l,mid,arr);
            sort(mid+1,h,arr);
            merge(l,mid,h,arr);
        }
    }
    static void merge(int l, int m , int h , int [] arr){

        int[] left = new int[m-l+1];
        int[] right = new int[h-m];
        for(int i= 0 ;i< m-l+1;i++){
            left[i] = arr[l+i];
        }
        for(int i=0;i<h-m;i++){
            right[i] = arr[m+1+i];
        }


        int i=l;
        int lindex = 0;
        int rindex =  0;

        while(lindex<m-l+1 && rindex<h-m){
            if(left[lindex]<=right[rindex]){
                arr[i]=left[lindex];
                lindex++;
                i++;
            }
            else{
                arr[i]=right[rindex];
                rindex++;
                i++;
            }
        }
        while(lindex<m-l+1){
            arr[i]=left[lindex];
            lindex++;
            i++;
        }
        while(rindex<h-m){
            arr[i]=right[rindex];
            rindex++;
            i++;
        }
    }

}

import java.io.*;
import java.util.*;

public class CF723D {
	static char[][] cc;
	static int[][] aa;
	static int n, m;
	static int dfs(int i, int j, int a) {
		if (i < 0  || i >= n || j < 0 || j >= m)
			return -1;
		if (cc[i][j] != '.' || aa[i][j] > 0)
			return 0;
		aa[i][j] = a;
		int w = dfs(i - 1, j, a);
		int e = dfs(i + 1, j, a);
		int n = dfs(i, j - 1, a);
		int s = dfs(i, j + 1, a);
		if (w < 0 || e < 0 || n < 0 || s < 0)
			return -1;
		return w + e + n + s + 1;
	}
	static void dfs2(int i, int j, int a) {
		if (i < 0  || i >= n || j < 0 || j >= m)
			return;
		if (cc[i][j] != '.' || aa[i][j] != a)
			return;
		cc[i][j] = '*';
		dfs2(i - 1, j, a);
		dfs2(i + 1, j, a);
		dfs2(i, j - 1, a);
		dfs2(i, j + 1, a);
	}
	static class L {
		int a, cnt;
		L(int a, int cnt) {
			this.a = a;
			this.cnt = cnt;
		}
	}
	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(br.readLine());
		n = Integer.parseInt(st.nextToken());
		m = Integer.parseInt(st.nextToken());
		int k = Integer.parseInt(st.nextToken());
		cc = new char[n][m];
		for (int i = 0; i < n; i++)
			br.readLine().getChars(0, m, cc[i], 0);
		aa = new int[n][m];
		ArrayList<L> list = new ArrayList<>();
		for (int i = 0; i < n; i++)
			for (int j = 0; j < m; j++) {
				int a = i * 50 + j + 1;
				int cnt = dfs(i, j, a);
				if (cnt > 0)
					list.add(new L(a, cnt));
			}
		int l = list.size();
		L[] ll = list.toArray(new L[l]);
		Arrays.sort(ll, (p, q) -> p.cnt - q.cnt);
		int sum = 0;
		for (int g = 0; g < l - k; g++) {
			sum += ll[g].cnt;
			int a = ll[g].a;
			int i = (a - 1) / 50;
			int j = (a - 1) % 50;
			dfs2(i, j, a);
		}
		PrintWriter pw = new PrintWriter(System.out);
		pw.println(sum);
		for (int i = 0; i < n; i++)
			pw.println(cc[i]);
		pw.close();
	}
}

