import java.util.*;

public class Cheker{
	static char[][] A;
	static int n;
	static int m;
	static int k;
	static class Pair{
		int row;
		int col;
		Pair(int i,int j){
			this.row=i;
			this.col=j;
		}
	}
	static class MyComp implements Comparator<LinkedList<Pair>>{
		public int compare(LinkedList<Pair> a,LinkedList<Pair> b){
			return a.size()-b.size();
		}
	}
	static boolean visited[][];
	static LinkedList<LinkedList<Pair>> list=new LinkedList<LinkedList<Pair>>();
	static LinkedList<Pair> temp;
	public static void main(String[] args){
		Scanner sc=new Scanner(System.in);
		n=sc.nextInt();
		m=sc.nextInt();
		k=sc.nextInt();
		A=new char[n][m];
		visited=new boolean[n][m];
		for(int i=0;i<n;i++){
			String str=sc.next();
			for(int j=0;j<m;j++){
				A[i][j]=str.charAt(j);
			}
		}
		for(int i=0;i<m;i++){
			if(A[0][i]=='.')
			DFSForPlus(0,i);
			if(A[n-1][i]=='.')
			DFSForPlus(n-1,i);
		}
		for(int i=0;i<n;i++){
			if(A[i][0]=='.'){
				DFSForPlus(i,0);
			}
			if(A[i][m-1]=='.'){
				DFSForPlus(i,m-1);
			}
		}
		for(int i=1;i<n-1;i++){
			for(int j=1;j<m-1;j++){
				if(A[i][j]=='.'){
					temp=new LinkedList<Pair>();
					DFSForCount(i,j);
					list.add(temp);
				}
			}
		}
		Collections.sort(list, new MyComp());
		int diff=list.size()-k;
		Iterator<LinkedList<Pair>> outer=list.iterator();
		int count=0;
		int size=0;
		while(outer.hasNext()){
			if(count==diff){
				break;
			}
			LinkedList<Pair> p=outer.next();
			size+=p.size();
			Iterator<Pair> inner=p.iterator();
			while(inner.hasNext()){
				Pair node=inner.next();
				A[node.row][node.col]='*';
			}
			count+=1;
		}
		System.out.println(size);
		for(int i=0;i<n;i++){
			for(int j=0;j<m;j++){
				if(A[i][j]=='+'){
					A[i][j]='.';
				}
				System.out.print(A[i][j]);
			}
			System.out.println();
		}
		sc.close();
	}
	static void DFSForCount(int r,int c){
		if(visited[r][c]==true){
			return;
		}
		visited[r][c]=true;
		temp.add(new Pair(r,c));
		if(r+1<=n-1 && A[r+1][c]=='.'){
			DFSForCount(r+1,c);
		}
		if(r-1>=0 && A[r-1][c]=='.'){
			DFSForCount(r-1,c);
		}
		if(c+1<=m-1 && A[r][c+1]=='.'){
			DFSForCount(r,c+1);
		}
		if(c-1>=0 && A[r][c-1]=='.'){
			DFSForCount(r,c-1);
		}
	}
	static void DFSForPlus(int r,int c){
		A[r][c]='+';
		if(r+1<=n-1 && A[r+1][c]=='.'){
			DFSForPlus(r+1,c);
		}
		if(r-1>=0 && A[r-1][c]=='.'){
			DFSForPlus(r-1,c);
		}
		if(c+1<=m-1 && A[r][c+1]=='.'){
			DFSForPlus(r,c+1);
		}
		if(c-1>=0 && A[r][c-1]=='.'){
			DFSForPlus(r,c-1);
		}
	}
}

import java.io.BufferedReader;
