public class Main {
    public static class FastInput {
        final private int BUFFER_SIZE = 1 << 16;

        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public FastInput(InputStream in) {
            din = new DataInputStream(in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public long nextLong() throws Exception {
            long ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = c == '-';
            if (neg)
                c = read();
            do {
                ret = ret * 10 + c - '0';
                c = read();
            } while (c > ' ');
            if (neg)
                return -ret;
            return ret;
        }


        public String next() throws Exception {
            StringBuilder ret = new StringBuilder();
            byte c = read();
            while (c <= ' ')
                c = read();
            do {
                ret = ret.append((char) c);
                c = read();
            } while (c > ' ');
            return ret.toString();
        }

        public int nextInt() throws Exception {
            int ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = c == '-';
            if (neg)
                c = read();
            do {
                ret = ret * 10 + c - '0';
                c = read();
            } while (c > ' ');
            if (neg)
                return -ret;
            return ret;
        }

        private void fillBuffer() throws Exception {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1)
                buffer[0] = -1;
        }

        private byte read() throws Exception {
            if (bufferPointer == bytesRead)
                fillBuffer();
            return buffer[bufferPointer++];
        }
    }

    static ArrayList<Boolean> visited = new ArrayList<>();
    static ArrayList<ArrayList<Integer>> graph = new ArrayList<>();
    static ArrayList<Integer> vertices = new ArrayList<>();
    static ArrayList<Character> input = new ArrayList<>();

    public static void main(String[] args) throws Exception {
        try {
            FastInput sc = new FastInput(System.in);


            int row = sc.nextInt();
            int col = sc.nextInt();
            int k = sc.nextInt();


            for (int i = 0; i < row; i++) {
                String curRow = sc.next();

                for (int j = 0; j < curRow.length(); j++) {
                    visited.add(false);
                    graph.add(new ArrayList<Integer>(0));
                    input.add(curRow.charAt(j));
                    if (curRow.charAt(j) == '.') {
                        vertices.add(j + col * i);





                    }
                }
            }


            for (int i = 0; i < vertices.size(); i++) {
                for (int j = 0; j < vertices.size(); j++) {
                    if (i != j) {
                        if (isTwoNearVertice(vertices.get(i), vertices.get(j), row, col)) {
                            graph.get(vertices.get(i)).add(vertices.get(j));
                        }
                    }
                }
            }



            ArrayList<ArrayList<Integer>> lakes = new ArrayList<>();
            for (int i = 0; i < vertices.size(); i++) { 
                if (!visited.get(vertices.get(i))) {
                    ArrayList<Integer> path = DFS(vertices.get(i));

                    boolean isLaked = true;
                    for (int a : path) {
                        if (isBoundedVertice(a, row, col)) {
                            isLaked = false;
                        }
                    }
                    if (isLaked) {
                        lakes.add(path);

                    }
                }
            }



            lakes.sort(Comparator.comparingInt(ArrayList::size));




            int count = lakes.size();
            int curLake = 0;

            int numOfChangedCell = 0;
            while (count > k) {

                for(int index: lakes.get(curLake)){
                    input.set(index, '*');
                    numOfChangedCell++;
                }

                count--;
                curLake++;
            }


            System.out.println(numOfChangedCell);

            for (int i = 0; i < input.size(); i++) {
                if (i % col < col - 1) {
                    System.out.print(input.get(i));
                } else {
                    System.out.println(input.get(i));

                }
            }


        } catch (Exception e) {
            e.printStackTrace();
        }

    }

    static public boolean isTwoNearVertice(int a, int b, int row, int col) {
        if (Math.abs(a - b) == 1 && a / col == b / col) 
            return true;
        else if (Math.abs(a - b) == col && a % col == b % col) 
            return true;
        else
            return false;
    }


    static public boolean isBoundedVertice(int a, int row, int col) {
        if (a % col == 0 || a % col == col - 1 || a / col == 0 || a / col == row - 1) {
            return true;

        }

        return false;
    }

    public static void printResultRecur(ArrayList<Integer> path, int s, int f) {
        if (s == f) {
            System.out.print(s + " ");
        } else {
            if (path.get(f) == -1) {
                System.out.println("NO path ");
            } else {
                System.out.print(f + " ");
                printResultRecur(path, s, path.get(f));

            }
        }
    }

    static ArrayList<Integer> DFS(int s) {
        ArrayList<Integer> path = new ArrayList<Integer>();

        Stack<Integer> stack = new Stack<Integer>();

        path.add(s);

        visited.set(s, true);
        stack.add(s);
        while (!stack.isEmpty()) {
            int u = (int) stack.pop();
            for (int i = 0; i < graph.get(u).size(); i++) {
                int v = graph.get(u).get(i);
                if (!visited.get(v)) {
                    path.add(v);

                    visited.set(v, true);

                    stack.add(v);
                }
            }
        }

        return path;
    }
}

import java.util.*;

public class Main {
    static int m;
    static int n;
    static int k;
    static int[] dx = new int[]{-1, 1, 0, 0};
    static int[] dy = new int[]{0, 0, -1, 1};
    static ArrayList<ArrayList<Character>> map = new ArrayList<>();
    static ArrayList<ArrayList<Boolean>> visited = new ArrayList<>();
    static HashMap<Integer, ArrayList<PointMap>> pathLake = new HashMap<>();
    static ArrayList<Lake> refLake = new ArrayList<>();

    static int idxLake = 0;
    static int cntCellPerLake = 0;
    static boolean isLake = true;

    private static class Lake {
        Integer mCntCell;
        Integer mIdxLake;

        public Lake(Integer cntCell, Integer idxLake) {
            this.mCntCell = cntCell;
            this.mIdxLake = idxLake;
        }

        public Integer getCntCell() {
            return mCntCell;
        }
    }

    private static class PointMap {
        int x;
        int y;

        public PointMap(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        n = scanner.nextInt();
        skipExceptionIn(scanner);
        m = scanner.nextInt();
        skipExceptionIn(scanner);
        k = scanner.nextInt();
        skipExceptionIn(scanner);


        for (int i = 0; i < n; i++) {
            String lineN = scanner.nextLine();

            map.add(new ArrayList<>());
            visited.add(new ArrayList<>());
            for (int j = 0; j < m; j++) {
                map.get(i).add(lineN.charAt(j));
                visited.get(i).add(false);
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map.get(i).get(j) == '.'
                        && !visited.get(i).get(j)) {
                    PointMap s = new PointMap(i, j);

                    pathLake.put(idxLake, new ArrayList<>());
                    cntCellPerLake = 0;
                    isLake = true;
                    DFS(s);


                    if (isLake) {
                        Lake lake = new Lake(cntCellPerLake, idxLake);

                        refLake.add(lake);
                        idxLake++;
                    }
                }
            }
        }

        int cntLakeRedundancy = refLake.size() - k;

        int minCellTransformed = 0;
        if (cntLakeRedundancy > 0) {
            Collections.sort(refLake, Comparator.comparing(Lake::getCntCell));

            for (int i = 0; i < cntLakeRedundancy; i++) {
                ArrayList<PointMap> cellsWater = pathLake.get(refLake.get(i).mIdxLake);

                minCellTransformed += cellsWater.size();
                for (int j = 0; j < cellsWater.size(); j++) {
                    PointMap tmp = cellsWater.get(j);

                    map.get(tmp.x).set(tmp.y, '*');
                }
            }
        }


        System.out.println(minCellTransformed);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                System.out.print(map.get(i).get(j));
            }

            System.out.println();
        }
    }

    private static void DFS(PointMap s) {
        visited.get(s.x).set(s.y, true);
        pathLake.get(idxLake).add(s);
        cntCellPerLake++;

        for (int i = 0; i < 4; i++) {
            int vX = s.x + dx[i];
            int vY = s.y + dy[i];

            if (vX < 0
                    || vX >= n
                    || vY < 0
                    || vY >= m) {
                isLake = false;
                continue;
            }

            if (!visited.get(vX).get(vY)
                    && map.get(vX).get(vY) == '.') {
                PointMap vPointMap = new PointMap(vX, vY);

                DFS(vPointMap);
            }
        }

    }

    private static void skipExceptionIn(Scanner scanner) {
        scanner.skip("(\r\n|[\n\r\u2028\u2029\u0085])?");
    }
}

