    }
    public static int DFS(int x, int y, boolean root){
        visited[x][y] = true;
        if(x == 0 || x == grid.length - 1 || y == 0 || y == grid[0].length - 1)
            oceanCon = true;
        int children = 0;
        if(root){
            children++;
        }
        for(int i = 0; i < 4; i++){
            int currx = x+dx[i];
            int curry = y+dy[i];
            if(currx < 0 || curry < 0 || currx >= grid.length || curry >= grid[0].length || !grid[currx][curry] || visited[currx][curry])
                continue;
            if(currx == 0 || currx == grid.length - 1 || curry == 0 || curry == grid[0].length - 1)
                oceanCon = true;
            children++;
            children+=DFS(currx, curry, false);
        }
        if(oceanCon)
            return 0;
        return children;
    }
    public static void coverUp(int x, int y){
        visited[x][y] = true;
        ret[x][y] = false;
        for(int i = 0; i < 4; i++){
            int currx = x+dx[i];
            int curry = y+dy[i];
            if(currx < 0 || curry < 0 || currx >= grid.length || curry >= grid[0].length || !grid[currx][curry] || visited[currx][curry])
                continue;
            ret[currx][curry] = false;

            coverUp(currx, curry);
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.TreeMap;

public final class LakesInBerland {

	public static char[][] minimalLake(char[][] matrix, int k) {
		if (matrix.length == 0 || matrix[0].length == 0)
			return new char[][] {};

		TreeMap<Integer, List<Integer[]>> lakeSize = new TreeMap<>();



		for (int i = 0; i < matrix.length; i++) {
			if (matrix[i][0] == '.') {
				dfsTransform(matrix, i, 0, '$');
			}

			if (matrix[i][matrix[0].length - 1] == '.') {
				dfsTransform(matrix, i, matrix[0].length - 1, '$');
			}
		}

		for (int j = 0; j < matrix[0].length; j++) {
			if (matrix[0][j] == '.') {
				dfsTransform(matrix, 0, j, '$');
			}

			if (matrix[matrix.length - 1][j] == '.') {
				dfsTransform(matrix, matrix.length - 1, j, '$');
			}
		}

		boolean[][] visited = new boolean[matrix.length][matrix[0].length];
		int countLake = 0;
		for (int i = 0; i < matrix.length; i++) {
			for (int j = 0; j < matrix[0].length; j++) {
				if (matrix[i][j] == '.' && !visited[i][j]) {
					int[] count = new int[] { 0 };
					dfs(matrix, i, j, visited, count);
					List<Integer[]> list = lakeSize.getOrDefault(count[0], new ArrayList<>());
					list.add(new Integer[] { i, j });
					lakeSize.put(count[0], list);
                  	countLake++;
				}
			}
		}

		int i = countLake - k;
		int sum = 0;
      	if (i > 0) {
            for (int key : lakeSize.keySet()) {
              List<Integer[]> transforms = lakeSize.get(key);
              boolean isEnd = false;
              for (Integer[] transform : transforms) {
                  sum += key;
                  dfsTransform(matrix, transform[0], transform[1], '*');
                  i--;
                  if (i == 0) {
                      isEnd = true;
                      break;
                  }
              }
              if (isEnd)
                  break;
			}
        }

		System.out.println(sum);

		return matrix;
	}

	private static void dfsTransform(char[][] matrix, int i, int j, char c) {
		if (i < 0 || j < 0 || i == matrix.length || j == matrix[0].length || matrix[i][j] != '.')
			return;

		matrix[i][j] = c;
		dfsTransform(matrix, i, j - 1, c);
		dfsTransform(matrix, i - 1, j, c);
		dfsTransform(matrix, i, j + 1, c);
		dfsTransform(matrix, i + 1, j, c);

	}












	private static void dfs(char[][] matrix, int i, int j, boolean[][] visited, int[] count) {

		count[0]++;
		visited[i][j] = true;
		if (j - 1 >= 0 && matrix[i][j - 1] == '.' && !visited[i][j - 1])
			dfs(matrix, i, j - 1, visited, count);

		if (i - 1 >= 0 && matrix[i - 1][j] == '.' && !visited[i - 1][j])
			dfs(matrix, i - 1, j, visited, count);

		if (j + 1 < matrix[0].length && matrix[i][j + 1] == '.' && !visited[i][j + 1])
			dfs(matrix, i, j + 1, visited, count);
		if (i + 1 < matrix.length && matrix[i + 1][j] == '.' && !visited[i + 1][j])
			dfs(matrix, i + 1, j, visited, count);
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();
		int k = sc.nextInt();
		char[][] matrix = new char[n][m];
		sc.nextLine();
		for (int i = 0; i < n; i++) {
			String row = sc.nextLine();
			String[] rowArr = row.split("");
			for (int j = 0; j < m; j++) {
				matrix[i][j] = rowArr[j].charAt(0);
			}
		}

		char[][] mimimize = minimalLake(matrix, k);
		for (int i = 0; i < mimimize.length; i++) {
			for (int j = 0; j < mimimize[0].length; j++) {
				System.out.print(mimimize[i][j] == '$' ? '.' : mimimize[i][j]);
			}
			System.out.println();
		}

	}

}

import java.util.ArrayList;
