public class vn2 {
	private static class Point {
		int x, y, count;

		Point(int x, int y) {
			this.x = x;
			this.y = y;
			this.count = 0;
		}

		void setCount(int count) {
			this.count = count;
		}

		int getCount() {
			return this.count;
		}
	}

	private static char[][] matrix;
	private static int dx[] = { 0, 0, 1, -1 };
	private static int dy[] = { 1, -1, 0, 0 };
	private static boolean visited[][] = new boolean[50][50];
	private static int rowNum, colNum;
	private static List<Point> lakeList = new ArrayList<Point>();

	private static boolean isLake(Point start) {
		boolean ret = true;
		int count = 1;
		Queue<Point> queue = new LinkedList<Point>();
		queue.add(start);
		visited[start.x][start.y] = true;
		int x, y;
		Point tmp;
		if (start.x == 0 || start.x == rowNum - 1 || start.y == 0 || start.y == colNum - 1) {
			ret = false;
		}

		while (!queue.isEmpty()) {
			tmp = queue.poll();

			for (int i=0;i<4;i++) {
				x = tmp.x + dx[i];
				y = tmp.y + dy[i];

				if (x >= 0 && x < rowNum && y >= 0 && y < colNum) {
					if (!visited[x][y] && matrix[x][y] == '.') {
						visited[x][y] = true;
						queue.add(new Point(x, y));
						count++;
						if (ret && (x == 0 || x == rowNum - 1 || y == 0 || y == colNum - 1)) {
							ret = false;
						}
					}
				}
			}
		}

		if (ret) {
			start.setCount(count);
		}
		return ret;
	}

	private static int dfs(Point start) {
		int count = 1;
		Queue<Point> queue = new LinkedList<Point>();
		queue.add(start);
		visited[start.x][start.y] = false;
		matrix[start.x][start.y] = '*';
		int x, y;
		Point tmp;

		while (!queue.isEmpty()) {
			tmp = queue.poll();

			for (int i=0;i<4;i++) {
				x = tmp.x + dx[i];
				y = tmp.y + dy[i];

				if (x >= 0 && x < rowNum && y >= 0 && y < colNum) {
					if (visited[x][y] && matrix[x][y] == '.') {
						visited[x][y] = false;
						queue.add(new Point(x, y));
						matrix[x][y] = '*';
						count++;
					}
				}
			}
		}

		return count;
	}

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);

		rowNum = in.nextInt();
		colNum = in.nextInt();
		int k = in.nextInt();
		in.nextLine();
		int lakeCount = 0;
		matrix = new char[rowNum][colNum];

		for (int i=0;i<rowNum;i++) {
			matrix[i] = in.nextLine().toCharArray();
		}

		for (int i=0;i<rowNum;i++) {
			for (int j=0;j<colNum;j++) {
				if (matrix[i][j] == '.' && !visited[i][j]) {
					Point start = new Point(i, j);
					if (isLake(start)) {
						lakeList.add(start);
						lakeCount++;
					}
				}
			}
		}

		int count = 0;
		if (lakeCount > k) {
			int n = lakeCount - k;
			Collections.sort(lakeList, new Comparator<Point>() {

				@Override
				public int compare(Point p1, Point p2) {
					return p1.getCount() - p2.getCount();
				}

			});

			for (Point p : lakeList) {
				int landCount = dfs(p);
				count += landCount;
				n--;
				if (n == 0) {
					break;
				}
			}

		}

		System.out.println(count);
		for (int i=0;i<rowNum;i++) {
			for (int j=0;j<colNum;j++) {
				System.out.print(matrix[i][j]);
			}
			System.out.println();
		}

		in.close();
	}
}

