public class Solution {
    static char[][] grid;
    static char[][] gridNew;
    static int n;
    static int m;
    static boolean[][] visited;
    static int count;
    static boolean prob;

    static void dfs(int i, int j) {
        if (i >= n || j >= m || i < 0 || j < 0 || visited[i][j] || grid[i][j] == '*') {
            return;
        }
        visited[i][j] = true;
        if (i == n - 1 || i == 0 || j == m - 1 || j == 0) {
            prob = true;
        }
        count++;
        dfs(i + 1, j);
        dfs(i - 1, j);
        dfs(i, j + 1);
        dfs(i, j - 1);
    }

    static void dfsChange(int i, int j) {
        if (i >= n || j >= m || i < 0 || j < 0 || visited[i][j] || grid[i][j] == '*') {
            return;
        }
        visited[i][j] = true;
        gridNew[i][j] = '*';
        dfsChange(i + 1, j);
        dfsChange(i - 1, j);
        dfsChange(i, j + 1);
        dfsChange(i, j - 1);
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        int k = sc.nextInt();
        grid = new char[n][m];
        gridNew = new char[n][m];
        visited = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String s = sc.nextLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = s.charAt(j);
                gridNew[i][j] = s.charAt(j);
            }
        }

        PriorityQueue<Pair> pq = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    count = 0;
                    prob = false;
                    dfs(i, j);
                    if (!prob)
                        pq.add(new Pair(i, j, count));
                }
            }
        }


        visited = new boolean[n][m];
        int num = 0;
        while (pq.size() != k) {
            Pair pair = pq.poll();
            dfsChange(pair.x, pair.y);
            num+=pair.size;
        }
        System.out.println(num);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                System.out.print(gridNew[i][j]);
            }
            System.out.println();
        }

    }

    static class Pair implements Comparable<Pair> {
        int x;
        int y;
        int size;

        public Pair(int x, int y, int size) {
            this.x = x;
            this.y = y;
            this.size = size;
        }

        @Override
        public int compareTo(Pair o) {
            return this.size - o.size;
        }
    }

