import java.util.InputMismatchException;
import java.util.List;

public class C375D{
	static int n;
	static int m;
	public static void main(String[] args){
		FasterScanner in = new FasterScanner();
		PrintWriter out = new PrintWriter(System.out);

		n = in.nextInt();
		m = in.nextInt();
		int k = in.nextInt();

		boolean[][] a = new boolean[n][m];

		for(int i = 0;i<n;i++){
			String s = in.nextLine();
			for(int j = 0;j<m;j++){
				a[i][j] = s.charAt(j)=='.';
			}
		}

		boolean[][] v = new boolean[n][m];
		ArrayList<Comp> list = new ArrayList<>();
		int how = 0;
		for(int i = 0;i<n;i++){
			for(int j = 0;j<m;j++){
				if(a[i][j] && !v[i][j]){
					places = new ArrayList<>();
					boolean add = dfs(i,j,a,v);
					if(add){
						Comp comp = new Comp(how++);
						comp.places = places;
						list.add(comp);
					}
				}
			}
		}

		Collections.sort(list);
		int count = 0;
		for(Comp comp:list){
			if(how==k){
				break;
			}
			ArrayList<Pair> where = comp.places;
			for(Pair p:where){
				a[p.r][p.c] = false;
				count++;
			}
			how--;
		}
		out.println(count);
		for(int i = 0;i<n;i++){
			for(int j = 0;j<m;j++){
				if(a[i][j]){
					out.print('.');
				}
				else{
					out.print('*');
				}
			}
			out.println();
		}

		out.close();
	}

	static int[] dr = {-1,0,1,0};
	static int[] dc = {0,1,0,-1};
	static int size;
	static ArrayList<Pair> places;
	static boolean dfs(int row,int col,boolean[][] a,boolean[][] v){
		if(row<0 || col<0 || row==n || col==m){
			return false;
		}

		if(v[row][col]){
			return true;
		}

		if(!a[row][col]){
			return true;
		}

		v[row][col] = true;

		places.add(new Pair(row, col));

		boolean ans = true;

		for(int i = 0;i<4;i++){
			int nr = row+dr[i];
			int nc = col + dc[i];
			ans &= dfs(nr,nc,a,v);
		}
		return ans;
	}

	static class Comp implements Comparable<Comp>{
		int id;
		ArrayList<Pair> places;

		public Comp(int i){
			this.id = i;
			places = new ArrayList<>();
		}

		@Override
		public int compareTo(Comp o) {

			if(places.size()==o.places.size()){
				return id-o.id;
			}
			return places.size() - o.places.size();
		}


	}

	static class Pair{
		int r;
		int c;
		public Pair(int r,int c){
			this.r = r;
			this.c = c;
		}
	}

	static class FasterScanner {

	    private byte[] buf = new byte[1024];
	    private int curChar;
	    private int numChars;

	    public int read() {
	        if (numChars == -1) {
	            throw new InputMismatchException();
	        }
	        if (curChar >= numChars) {
	            curChar = 0;
	            try {
	                numChars = System.in.read(buf);
	            } catch (IOException e) {
	                throw new InputMismatchException();
	            }
	            if (numChars <= 0) {
	                return -1;
	            }
	        }
	        return buf[curChar++];
	    }

	    public String nextLine() {
