public class BasicJava
{
   public static void main (String[] args) {

      Task Main = new Task();

      Main.solve();
   }

   static class Task
   {
      public InputReader in = new InputReader(System.in);
      public PrintWriter out = new PrintWriter(System.out);

      public boolean good;
      public int nrf = 0;
      public int n, m;
      public int ans = 0;
      public boolean[][] viz = new boolean[55][55];
      public String[] s = new String[55];

      public boolean outOfBounds(int x, int y)
      {
         return ((x > 0 && y > 0 && x <= n && y <= m));
      }

      public void fill(int x, int y)
      {
         if (!outOfBounds(x, y)) { good = false; return; }

         nrf++; viz[x][y] = true;

         if (s[x + 1].charAt(y) != '*' && !viz[x + 1][y]) fill(x+1, y);
         if (s[x].charAt(y + 1) != '*' && !viz[x][y + 1]) fill(x, y+1);
         if (s[x - 1].charAt(y) != '*' && !viz[x - 1][y]) fill(x-1, y);
         if (s[x].charAt(y - 1) != '*' && !viz[x][y - 1]) fill(x, y-1);

      }

      public void clean(int x, int y)
      {
         if (!outOfBounds(x, y)) return; 

         viz[x][y] = true; ans++;

         if (s[x + 1].charAt(y) == '.' && !viz[x + 1][y]) clean(x+1, y);
         if (s[x].charAt(y + 1) == '.' && !viz[x][y + 1]) clean(x, y+1);
         if (s[x - 1].charAt(y) == '.' && !viz[x - 1][y]) clean(x-1, y);
         if (s[x].charAt(y - 1) == '.' && !viz[x][y - 1]) clean(x, y-1);

      }

      public void solve()
      {
         n = in.nextInt();
         m = in.nextInt();
         int k = in.nextInt();
         int[][] dp = new int[55][55];

         s[0] = new String("");
         s[n+1] = new String("");

         for (int i = 0; i <= m + 1; i++) s[0] += "1";

         for (int i = 1; i <= n; i++) {
            s[i] = in.next(); s[i] = "1" + s[i] + "1";
         }

         for (int i = 0; i <= m + 1; i++) s[n+1] += "1";

         int l = 0;

         for (int i = 1; i <= n; i++)
            for (int j = 1; j <= m; j++)
               if (s[i].charAt(j) == '.' && !viz[i][j]) {

                  good = true; nrf = 0;

                  fill(i, j);

                  if (good) { l++; dp[i][j] = nrf; }

               }

         for (int i = 1; i <= n; i++)
            for (int j = 1; j <= m; j++)
               if (s[i].charAt(j) == '.') viz[i][j] = false;

         while (l > k) {

            int minn = (int) 2e9;
            int posx = 0, posy = 0;

            for (int i = 1; i <= n; i++)
               for (int j = 1; j <= m; j++)
                  if (dp[i][j] > 0 && dp[i][j] < minn) {

                     minn = dp[i][j]; posx = i; posy = j;

                  }

            dp[posx][posy] = 0; clean(posx, posy);

            l--;

         }

         out.println(ans);

         for (int i = 1; i <= n; i++) {

            for (int j = 1; j <= m; j++)
               if (viz[i][j]) out.print("*"); else
                  out.print(s[i].charAt(j));

            out.println();

         }

         out.close();

      }

   }

   static class InputReader
   {
      private InputStream stream;
      private byte[] buf = new byte[2048];
      private int curChar;
      private int numChars;

      public InputReader(InputStream stream)
      {
         this.stream = stream;
      }

      public int read()
      {
         if (numChars == -1)
            throw new UnknownError();
         if (curChar >= numChars)
         {
            curChar = 0;
            try
            {
               numChars = stream.read(buf);
            }
            catch (IOException e)
            {
               throw new UnknownError();
            }
            if (numChars <= 0)
               return -1;
         }
         return buf[curChar++];
      }

      public int peek()
      {
         if (numChars == -1)
            return -1;
         if (curChar >= numChars)
         {
            curChar = 0;
            try
            {
               numChars = stream.read(buf);
            }
            catch (IOException e)
            {
               return -1;
            }
            if (numChars <= 0)
               return -1;
         }
         return buf[curChar];
      }

      public void skip(int x)
      {
         while (x-- > 0)
            read();
      }

      public int nextInt()
      {
         return Integer.parseInt(next());
      }

      public long nextLong()
      {
         return Long.parseLong(next());
      }

      public String nextString()
      {
         return next();
      }

      public String next()
      {
         int c = read();
         while (isSpaceChar(c))
            c = read();
         StringBuffer res = new StringBuffer();
         do
         {
            res.appendCodePoint(c);
            c = read();
         }
         while (!isSpaceChar(c));

         return res.toString();
      }

      public String nextLine()
      {
         StringBuffer buf = new StringBuffer();
         int c = read();
         while (c != '\n' && c != -1)
         {
            if (c != '\r')
               buf.appendCodePoint(c);
            c = read();
         }
         return buf.toString();
      }

      public double nextDouble()
      {
         int c = read();
         while (isSpaceChar(c))
            c = read();
         int sgn = 1;
         if (c == '-')
         {
            sgn = -1;
            c = read();
         }
         double res = 0;
         while (!isSpaceChar(c) && c != '.')
         {
            if (c == 'e' || c == 'E')
               return res * Math.pow(10, nextInt());
            if (c < '0' || c > '9')
               throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
         }
         if (c == '.')
         {
            c = read();
            double m = 1;
            while (!isSpaceChar(c))
            {
               if (c == 'e' || c == 'E')
                  return res * Math.pow(10, nextInt());
               if (c < '0' || c > '9')
                  throw new InputMismatchException();
               m /= 10;
               res += (c - '0') * m;
               c = read();
            }
         }
         return res * sgn;
      }

      public boolean hasNext()
      {
         int value;
         while (isSpaceChar(value = peek()) && value != -1)
            read();
         return value != -1;
      }

      private boolean isSpaceChar(int c)
      {
         return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
      }

   }
}

import java.io.*;
import java.util.*;

public class Main {
    static InputReader in = new InputReader(System.in);
    static PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        new Solution().solve();
        out.close();
    }

    static class Solution {
        boolean[][] visited;
        char[][] map;
        int[] dr = {0, 0, -1, 1};
        int[] dc = {-1, 1, 0, 0};
        int numRows, numCols;
        int size;

        public void solve() {
            numRows = in.nextInt();
            numCols = in.nextInt();
            int finalNumLakes = in.nextInt();
            map = new char[numRows][];

            for (int r = 0; r < numRows; r++) {
                map[r] = in.next().toCharArray();
            }

            visited = new boolean[numRows][];
            for (int r = 0; r < numRows; r++) {
                visited[r] = new boolean[numCols];
                for (int c = 0; c < numCols; c++) {
                    visited[r][c] = false;
                }
            }



            for (int c = 0; c < numCols; c++) {
                if (map[0][c] == '.' && !visited[0][c]) {
                    dfsVisit(0, c);
                }
            }

            for (int c = 0; c < numCols; c++) {
                if (map[numRows - 1][c] == '.' && !visited[numRows - 1][c]) {
                    dfsVisit(numRows - 1, c);
                }
            }

            for (int r = 0; r < numRows; r++) {
                if (map[r][0] == '.' && !visited[r][0]) {
                    dfsVisit(r, 0);
                }
            }

            for (int r = 0; r < numRows; r++) {
                if (map[r][numCols - 1] == '.' && !visited[r][numCols - 1]) {
                    dfsVisit(r, numCols - 1);
                }
            }


            ArrayList<Lake> lakes = new ArrayList<>();
            for (int r = 1; r < numRows - 1; r++) {
                for (int c = 1; c < numCols - 1; c++) {
                    if (map[r][c] == '.' && !visited[r][c]) {
                        size = 0;
                        dfsVisit(r, c);
                        lakes.add(new Lake(r, c, size));
                    }
                }
            }

            Collections.sort(lakes, (o1, o2) -> Integer.compare(o1.size, o2.size));

            int numLakesToFill = lakes.size() - finalNumLakes;
            int fillCount = 0;
            for (int i = 0; i < numLakesToFill; i++) {
                dfsFill(lakes.get(i).sr, lakes.get(i).sc);
                fillCount += lakes.get(i).size;
            }

            out.println(fillCount);
            for (int r = 0; r < numRows; r++) {
                for (int c = 0; c < numCols; c++) {
                    out.print(map[r][c]);
                }
                out.println();
            }
        }

        private void dfsFill(int r, int c) {
            map[r][c] = '*';
            if (r < 1 || r > numRows - 2 || c < 1 || c > numCols - 2) {
                throw new RuntimeException("r = " + r + "; c = " + c);
            }
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (map[nr][nc] == '.') {
                    dfsFill(nr, nc);
                }
            }
        }

        private void dfsVisit(int r, int c) {
            visited[r][c] = true;
            size++;
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (nr > -1 && nr < numRows && nc > -1 && nc < numCols && map[nr][nc] == '.' && !visited[nr][nc]) {
                    dfsVisit(nr, nc);
                }
            }
        }

        class Lake {
            int sr;
            int sc;
            int size;

            Lake(int sr, int sc, int size) {
                this.sr = sr;
                this.sc = sc;
                this.size = size;
            }

            public String toString() {
                return "r = " + this.sr + "; c = " + this.sc + "; size = " + this.size;
            }
        }
        }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;
        public int numLines;

        public InputReader(InputStream inStream) {
            reader = new BufferedReader(new InputStreamReader(inStream));
            tokenizer = null;
            numLines = 0;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    numLines++;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input Error");
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public char nextChar() {
            return next().charAt(0);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;


public class App {
    private static int[][] xr = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String[] line;
            line = reader.readLine().split(" ");
            int n = Integer.parseInt(line[0]);
            int m = Integer.parseInt(line[1]);
            int k = Integer.parseInt(line[2]);
            char[][] map = new char[n][m];
            for (int i = 0; i < n; ++i) {
                map[i] = reader.readLine().toCharArray();
            }
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if ((i == 0 || j == 0 || i == n - 1 || j == m - 1) && map[i][j] == '.') {
                        dfs(map, i, j, 'v', '.');
                    }
                }
            }
            Map<Integer, List<Integer>> cntToLocs = new TreeMap<>();
            int islands = 0;
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (map[i][j] == '.') {
                        int cnt = dfs(map, i, j, 'v', '.');
                        if (!cntToLocs.containsKey(cnt)) {
                            cntToLocs.put(cnt, new ArrayList<>());
                        }
                        cntToLocs.get(cnt).add(i * m + j);
                        islands++;
                    }
                }
            }
            int res = 0;
            for (Map.Entry<Integer, List<Integer>> entry : cntToLocs.entrySet()) {
                if (islands == k) {
                    break;
                }
                List<Integer> starts = entry.getValue();
                for (int s : starts) {
                    if (islands == k) {
                        break;
                    }
                    int i = s / m;
                    int j = s % m;
                    res += dfs(map, i, j, '*', 'v');
                    --islands;
                }
            }
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (map[i][j] == 'v') {
                        map[i][j] = '.';
                    }
                }
            }
            System.out.println(res);
            for (char[] l : map) {
                System.out.println(new String(l));
            }
        }
    }

    private static int dfs(char[][] map, int i, int j, char marker, char org) {
        if (i < 0 || j < 0 || i >= map.length || j >= map[i].length || map[i][j] != org) {
            return 0;
        }
        map[i][j] = marker;
        int cnt = 1;
        for (int[] r : xr) {
            cnt += dfs(map, i + r[0], j + r[1], marker, org);
        }
        return cnt;
    }

    private static void union(int[] roots, int u, int v) {
        u = find(roots, u);
        v = find(roots, v);
        if (u != v) {
            roots[v] = u;
        }
    }

    private static int find(int[] roots, int u) {
        return roots[u] == 0 ? u : (roots[u] = find(roots, roots[u]));
    }
}

