    int n, m, k;

    void dfs(int ti, int tj, int c) {
        if (color[ti][tj] != 0) {
            return;
        }
        color[ti][tj] = c;
        for (int i = 0; i < 4; i++) {
            int ni = ti + di[i], nj = tj + dj[i];
            if (ni < 0 || nj < 0 || ni >= n || nj >= m) {
                continue;
            }
            if (d[ni][nj] == '.') {
                dfs(ni, nj, c);
            }
        }
    }


    void fill(int ti, int tj) {
        d[ti][tj] = '*';
        for (int i = 0; i < 4; i++) {
            int ni = ti + di[i], nj = tj + dj[i];
            if (ni < 0 || nj < 0 || ni >= n || nj >= m) {
                continue;
            }
            if (d[ni][nj] == '.') {
                fill(ni, nj);
            }
        }
    }

    private void solve() {


        n = scanner.nextInt();
        m = scanner.nextInt();
        k = scanner.nextInt();

        d = new char[n][m];
        a = new char[n][m];
        color = new int[n][m];

        scanner.nextLine();

        for (int i = 0; i < n; i ++) {
            String s = scanner.nextLine();
            for (int j = 0; j < m; j++){
                d[i][j] = s.charAt(j);
                a[i][j] = s.charAt(j);
            }
        }


        for (int i = 0; i < n; i ++) {
            for (int j = 0; j < m; j++){
                if ((i == 0 || i == n - 1 || j == 0 || j == m - 1) && d[i][j] == '.') {
                    fill(i, j);
                }
            }
        }


        int c = 1;
        for (int i = 0; i < n; i ++) {
            for (int j = 0; j < m; j++){
                if (d[i][j] == '.' && color[i][j] == 0) {
                    dfs(i, j, c);
                    c++;
                }
            }
        }

        int temp [] = new int[c];

        for (int i = 0; i < n; i ++) {
            for (int j = 0; j < m; j++){
                if (color[i][j] != 0) {
                    temp[color[i][j]] ++;
                }
            }
        }

        List<Pair> pairs = new ArrayList<>();
        for (int i = 1; i < c; i++) {
            pairs.add(new Pair(temp[i], i));
        }

        Collections.sort(pairs);

        int ll = pairs.size() - k;
        int ans = 0;
        for (int i = 0; i < ll ; i ++) {
            ans += pairs.get(i).a;
        }

        out.println(ans);

        for (int l = 0; l < ll ; l ++) {
            int cl = pairs.get(l).i;
            for (int i = 0; i < n; i ++) {
                for (int j = 0; j < m; j++){
                    if (color[i][j] == cl) {
                        a[i][j] = '*';
                    }
                }
            }
        }

        for (int i = 0; i < n ; i ++) {
            for (int j = 0; j < m; j++){
                out.print(a[i][j]);
            }
            out.println();
        }

    }


