  int [] dj = new int[] {0, 1,  0,-1};

  boolean ok(int i, int j) {
    return i >= 0 && i <= n - 1 && j >= 0 && j <= m - 1 && g[i][j] == 0;
  }




  int calcSize(int col) {  
    int res = 0;
    for (int i = 0 ; i < n ; i ++) 
      for (int j = 0 ; j < m ; j ++) {
        if (g[i][j] == col) res ++;
        if ( (g[i][j] == col) && (i == 0 || i == n-1 || j == 0 || j == m-1)) return inf;
      }

    return res;
  }
  void dfs(int i, int j, int color) {
    g[i][j] = color;


    for (int k = 0 ; k < 4 ; k++) {
      int ni = i + di[k], nj = j + dj[k];
      if (ok(ni, nj)) {
        dfs(ni, nj, color);
      }
    }
