        out.close();
    }

    static class TaskD {
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();

            char[][] grid = new char[n][m];

            for (int i = 0; i < n; ++i) {
                char[] arr = in.next().toCharArray();
                for (int j = 0; j < m; ++j) {
                    grid[i][j] = arr[j];
                }
            }

            boolean[][] checked = new boolean[n][m];
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if ((i == 0 || j == 0 || i == n - 1 || j == m - 1) && grid[i][j] == '.' && !checked[i][j]) {
                        ArrayDeque<Pair> q = new ArrayDeque<>();
                        q.offer(new Pair(i, j));

                        while (!q.isEmpty()) {
                            Pair state = q.poll();
                            int x = state.f;
                            int y = state.s;
                            if (grid[x][y] == '*') continue;
                            if (checked[x][y]) continue;
                            checked[x][y] = true;

                            for (int ii = 0; ii < 4; ++ii) {
                                int xx = x + dx[ii];
                                int yy = y + dy[ii];

                                if (xx < 0 || yy < 0) continue;
                                if (xx >= n || yy >= m) continue;
                                if (checked[xx][yy] || grid[xx][yy] == '*') continue;
                                q.offer(new Pair(xx, yy));
                            }
                        }
                    }
                }
            }

            PriorityQueue<Triple> pq = new PriorityQueue<>();
            boolean[][] vis = new boolean[n][m];
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (!(grid[i][j] == '.' && !checked[i][j] && !vis[i][j]))
                        continue;

                    int cnt = 0;
                    ArrayDeque<Pair> q = new ArrayDeque<>();
                    q.offer(new Pair(i, j));

                    while (!q.isEmpty()) {
                        Pair state = q.poll();
                        int x = state.f;
                        int y = state.s;

                        if (vis[x][y]) continue;
                        vis[x][y] = true;
                        ++cnt;

                        for (int ii = 0; ii < 4; ++ii) {
                            int xx = x + dx[ii];
                            int yy = y + dy[ii];

                            if (xx < 0 || x >= n) continue;
                            if (yy < 0 || y >= m) continue;
                            if (grid[xx][yy] == '*') continue;

                            q.offer(new Pair(xx, yy));
                        }
                    }

                    pq.offer(new Triple(i, j, cnt));
                }
            }

            int ans = 0;
            while (pq.size() > k) {
                Triple t = pq.poll();
                int i = t.f;
                int j = t.s;
                ans += t.t;

                ArrayDeque<Pair> q = new ArrayDeque<>();
                q.offer(new Pair(i, j));

                while (!q.isEmpty()) {
                    Pair state = q.poll();
                    int x = state.f;
                    int y = state.s;

                    if (grid[x][y] == '*') continue;
                    grid[x][y] = '*';

                    for (int ii = 0; ii < 4; ++ii) {
                        int xx = x + dx[ii];
                        int yy = y + dy[ii];

                        if (xx <= 0 || x >= n - 1) continue;
                        if (yy <= 0 || y >= m - 1) continue;
                        if (grid[xx][yy] == '*') continue;

                        q.offer(new Pair(xx, yy));
                    }
                }
            }

            out.println(ans);

            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    out.print(grid[i][j]);
                }
                out.println();
            }

        }

    }

    static class Pair {
        int f;
        int s;

        public Pair(int f, int s) {
            this.f = f;
            this.s = s;
        }

    }

    static class Triple implements Comparable<Triple> {
        int f;
        int s;
        int t;

        public Triple(int f, int s, int t) {
            this.f = f;
            this.s = s;
            this.t = t;
        }


        public int compareTo(Triple t) {
            return this.t - t.t;
        }

    }
}

