import java.util.Scanner;

public class LakesInBerland {


	static int n=0;
	static int m=0;
	static int k=0;
	static char array[][]=new char[50][50];
	static int visited[][]=new int[50][50];
	static int queue[][]=new int[5000][2];
	static int front=0;
	static int rear=1;
	static int count=0;
	static int c[]=new int[10000];
	static int temp=0;
	public static int valid(int a, int b)
	{
		if(a<0||a>=n||b<0||b>=m)
		{
			return 0;
		}
		return 1;
	}


	public static void bfs(int a, int b)
	{
		queue[front][0]=a;
		queue[front][1]=b;
		visited[a][b]=-1;

		while(front!=rear)
		{
			int x=queue[front][0];
			int y=queue[front][1];
			if(valid(x-1, y)==1&&visited[x-1][y]==0&&array[x-1][y]=='.')
			{
				visited[x-1][y]=-1;
				queue[rear][0]=x-1;
				queue[rear][1]=y;
				rear++;
			}

			if(valid(x+1, y)==1&&visited[x+1][y]==0&&array[x+1][y]=='.')
			{
				visited[x+1][y]=-1;
				queue[rear][0]=x+1;
				queue[rear][1]=y;
				rear++;
			}


			if(valid(x, y-1)==1&&visited[x][y-1]==0&&array[x][y-1]=='.')
			{
				visited[x][y-1]=-1;
				queue[rear][0]=x;
				queue[rear][1]=y-1;
				rear++;
			}

			if(valid(x, y+1)==1&&visited[x][y+1]==0&&array[x][y+1]=='.')
			{
				visited[x][y+1]=-1;
				queue[rear][0]=x;
				queue[rear][1]=y+1;
				rear++;
			}

			front++;
		}
	}


	public static void bfs1(int a, int b)
	{
		queue[front][0]=a;
		queue[front][1]=b;
		visited[a][b]=count;
		temp++;
		while(front!=rear)
		{
			int x=queue[front][0];
			int y=queue[front][1];
			if(valid(x-1, y)==1&&visited[x-1][y]==0&&array[x-1][y]=='.')
			{
				visited[x-1][y]=count;
				queue[rear][0]=x-1;
				queue[rear][1]=y;
				rear++;
				temp++;
			}

			if(valid(x+1, y)==1&&visited[x+1][y]==0&&array[x+1][y]=='.')
			{
				visited[x+1][y]=count;
				queue[rear][0]=x+1;
				queue[rear][1]=y;
				rear++;
				temp++;
			}


			if(valid(x, y-1)==1&&visited[x][y-1]==0&&array[x][y-1]=='.')
			{
				visited[x][y-1]=count;
				queue[rear][0]=x;
				queue[rear][1]=y-1;
				rear++;
				temp++;
			}

			if(valid(x, y+1)==1&&visited[x][y+1]==0&&array[x][y+1]=='.')
			{
				visited[x][y+1]=count;
				queue[rear][0]=x;
				queue[rear][1]=y+1;
				rear++;
				temp++;
			}

			front++;
		}
	}

	public static void changearray(int a)
	{
		for(int i=0;i<n;i++)
		{
			for(int j=0;j<m;j++)
			{
				if(visited[i][j]==a)
				{
					array[i][j]='*';
				}
			}
		}
	}
	public static void main(String[] args)
	{
		Scanner sc=new Scanner(System.in);
		n=sc.nextInt();
		m=sc.nextInt();
		k=sc.nextInt();
		for(int i=0;i<n;i++)
		{
			String str=sc.next();
			for(int j=0;j<str.length();j++)
			{
				array[i][j]=str.charAt(j);
			}
		}
		for(int i=0;i<n;i++)
		{
			for(int j=0;j<m;j++)
			{
				if((i==0||j==0||i==n-1||j==m-1)&&visited[i][j]==0&&array[i][j]=='.')
				{
					front=0;
					rear=1;
					bfs(i,j);
				}
			}
		}


		for(int i=0;i<n;i++)
		{
			for(int j=0;j<m;j++)
			{
				if(visited[i][j]==0&&array[i][j]=='.')
				{
					count++;
					front=0;
					rear=1;
					temp=0;
					bfs1(i,j);
					c[count]=temp;
				}
			}
		}

		int diff=count-k;
		int sum=0;
		for(int i=1;i<=diff;i++)
		{
			int ind=1;
			int min=99999999;
			for(int j=1;j<=count;j++)
			{
				if(c[j]<min)
				{
					min=c[j];
					ind=j;
				}
			}
			sum=sum+c[ind];
			c[ind]=99999999;
			changearray(ind);
		}
		System.out.println(sum);
		for(int i=0;i<n;i++)
		{
			for(int j=0;j<m;j++)
			{
				System.out.print(array[i][j]);
			}
			System.out.println();
		}
	}


}

import java.io.BufferedReader;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.UnsupportedEncodingException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.Stack;
import java.util.StringTokenizer;

public class Main {

	static class Pair implements Comparable<Pair> {
		public int x;
		public int y;

		public Pair(int x, int y) {
			this.x = x;
			this.y = y;
		}

		@Override
		public int compareTo(Pair arg0) {
			if (Integer.compare(this.x, arg0.x) != 0) {
				return Integer.compare(this.x, arg0.x);
			}

			return Integer.compare(this.y, arg0.y);

		}

	}

	public static void main(String[] args) throws FileNotFoundException, UnsupportedEncodingException {

		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);

		solve(in, out);
		out.flush();
		out.close();
		System.exit(0);
	}

	private static void solve(InputReader in, PrintWriter out) {
		int n = in.nextInt();
		int m = in.nextInt();
		int k = in.nextInt();

		int[] moveX = new int[] { -1, 0, 1, 0 };
		int[] moveY = new int[] { 0, -1, 0, 1 };

		int cnt = 0;
		int[][] scc = new int[n][m];
		int[] cntScc = new int[n * m + 1];

		char[][] board = new char[n][m];
		for (int i = 0; i < n; i++) {
			board[i] = in.next().toCharArray();
		}

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (scc[i][j] > 0 || board[i][j] == '*') {
					continue;
				}

				Stack<Integer> xs = new Stack<>();
				Stack<Integer> ys = new Stack<>();
				xs.add(i);
				ys.add(j);
				++cnt;
				while (!xs.isEmpty()) {
					int rootX = xs.pop();
					int rootY = ys.pop();

					if (scc[rootX][rootY] > 0) {
						continue;
					}

					scc[rootX][rootY] = cnt;
					cntScc[cnt]++;
					for (int a = 0; a < 4; a++) {
						int posX = rootX + moveX[a];
						int posY = rootY + moveY[a];
						if (posX < 0 || posX >= n) {
							continue;
						}
						if (posY < 0 || posY >= m) {
							continue;
						}
						if (board[posX][posY] == '.' && scc[posX][posY] == 0) {
							xs.add(posX);
							ys.add(posY);
						}
					}
				}

			}
		}

		HashSet<Integer> map = new HashSet<>();
		for (int i = 0; i < n; i++) {
			if (board[i][0] == '.') {
				map.add(scc[i][0]);
			}
			if (board[i][m - 1] == '.') {
				map.add(scc[i][m - 1]);
			}
		}

		for (int j = 0; j < m; j++) {
			if (board[0][j] == '.') {
				map.add(scc[0][j]);
			}
			if (board[n - 1][j] == '.') {
				map.add(scc[n - 1][j]);
			}
		}

		ArrayList<Pair> arr = new ArrayList<>();
		for (int i = 1; i < n * m + 1; i++) {
			if (map.contains(i)) {
				continue;
			}

			arr.add(new Pair(cntScc[i], i));
		}

		Collections.sort(arr);

		int num = arr.size();
		map.clear();
		for (int i = 0; i < num - k; i++) {
			map.add(arr.get(i).y);
		}

		int result = 0;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (map.contains(scc[i][j])) {
					board[i][j] = '*';
					result++;
				}
			}
		}

		out.println(result);
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				out.print(board[i][j]);
			}
			if (i != n - 1) {
				out.println();
			}
		}

	}

	static class InputReader {
		public BufferedReader reader;
		public StringTokenizer tokenizer;

		public InputReader(InputStream stream) {
			reader = new BufferedReader(new InputStreamReader(stream), 32768);
			tokenizer = null;
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public String nextLine() {
			String str = "";
			try {
				str = reader.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}

			return str;
		}
	}

}

import java.util.*;

public class BerlandLakes {
    private static int n;
    private static int m;
    private static int k;
    private static char[][] board;
    private static List<Boolean> visited;
    private static List<Boolean> filled;
    private static int[] dr = {-1, 1, 0, 0};
    private static int[] dc = {0, 0, -1, 1};
    private static final int MAX = 50 * 50 + 5;
    private static List<List<Integer>> lakeTrack;
    private static int countComponent = 0;
    private static int filledCell = 0;

    private static int getCodeCell(int row, int col) {
        int cellCode = row * m + col;
        return cellCode;
    }

    private static int[] getRowCol(int cellCode) {
        int[] RowCol = new int[2];
        RowCol[0] = cellCode / m;
        RowCol[1] = cellCode % m;
        return RowCol; 
    }

    private static boolean isValid(int row, int col) {
        return row >= 0 && row < n && col >= 0 && col < m; 
    }

    private static void DFS(int src) {
        Stack<Integer> s = new Stack<Integer>();
        boolean isBoarder = false;
        int lakeSize = 1;

        visited.set(src, true);
        s.push(src);

        while(!s.empty()) {
            int u = s.pop();
            int rowU = getRowCol(u)[0];
            int colU = getRowCol(u)[1];
            if(rowU == 0 || rowU == n - 1 || colU == 0 || colU == m - 1) {
                isBoarder = true;
            }
            for(int i = 0; i < dr.length; i++) {
                int rowV = rowU + dr[i];
                int colV = colU + dc[i];
                int vCode = getCodeCell(rowV, colV);
                if(isValid(rowV, colV) && !visited.get(vCode) && board[rowV][colV] == '.') {
                    visited.set(vCode, true);
                    s.add(vCode);
                    lakeSize++;
                }
            }
        }

        if(!isBoarder) {
            lakeTrack.get(lakeSize).add(src);
            countComponent++;
        }
    }

    private static void fillLake(int src) {
        Stack<Integer> s = new Stack<Integer>();
        filled.set(src, true);
        s.push(src);
        board[getRowCol(src)[0]][getRowCol(src)[1]] = '*';
        filledCell++;

        while(!s.empty()) {
            int u = s.pop();
            int rowU = getRowCol(u)[0];
            int colU = getRowCol(u)[1];

            for(int i = 0; i < dr.length; i++) {
                int rowV = rowU + dr[i];
                int colV = colU + dc[i];
                int vCode = getCodeCell(rowV, colV);
                if(isValid(rowV, colV) && board[rowV][colV] == '.') {
                    board[rowV][colV] = '*';
                    s.add(vCode);
                    filledCell++;
                }
            }
        }
        countComponent--;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();

        board = new char[n][m];
        for(int row = 0; row < n; row++) {
            String s = sc.next();
            for(int col = 0; col < m; col++) {
                board[row][col] = s.charAt(col);     
            }        
        }

        visited = new ArrayList<Boolean>();
        lakeTrack = new ArrayList<List<Integer>>();
        filled = new ArrayList<Boolean>();
        for(int i = 0; i < MAX; i++) {
            visited.add(false);
            lakeTrack.add(new ArrayList<Integer>());
            filled.add(false);
        }

        for(int row = 0; row < n; row++) {
            for(int col = 0; col < m; col++) {
                int currentCellCode = getCodeCell(row, col);
                if(!visited.get(currentCellCode) && board[row][col] == '.') {
                    DFS(currentCellCode);
                }
            }
         }

        if(countComponent == k) {
            System.out.println(0);
            for(int row = 0; row < n; row++) {
                for(int col = 0; col < m; col++) {
                    System.out.print(board[row][col]);
                }
                System.out.println();
            }
        }

        else {

            while(countComponent > k) {
                for(int i = 0; i < lakeTrack.size(); i++) {
                    if(!lakeTrack.get(i).isEmpty()) {
                        for(int j = 0; j < lakeTrack.get(i).size(); j++) {
                            int currentComponent = lakeTrack.get(i).get(j);
                            if(countComponent == k) {
                                break;
                            }
                            fillLake(currentComponent);
                        }
                    }
                }
            }
            System.out.println(filledCell);
            for(int row = 0; row < n; row++) {
                for(int col = 0; col < m; col++) {
                    System.out.print(board[row][col]);
                }
                System.out.println();
            }
        }
    }    
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class VirtC {

	static int n, m, c;

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		n = scan.nextInt();
		m = scan.nextInt();
		int k = scan.nextInt();
		char[][] grid = new char[n][m];
		for(int i = 0; i < n; i++) grid[i] = scan.next().toCharArray();
		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if((i == 0 || j == 0 || i == n-1 || j == m-1) && grid[i][j] == '.'){
					dfs(i, j, grid, new boolean[n][m]);
				}
			}
		}
		ArrayList<Lake> a = new ArrayList<Lake>();
		boolean[][] v = new boolean[n][m];
		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(grid[i][j] == '.' && !v[i][j]){
					c = 0;
					DFS(i, j, grid, v);
					a.add(new Lake(i, j, c));

				}
			}
		}
		Collections.sort(a);

		int count = 0;
		while(a.size() > k){
			Lake l = a.remove(0);

			DeeEfEs(l.x, l.y, grid, new boolean[n][m]);
			count += l.s;
		}
		System.out.println(count);
		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(grid[i][j] == '#') System.out.print(".");
				else System.out.print(grid[i][j]);
			}
			System.out.println();
		}
	}

	static void DeeEfEs(int x, int y, char[][] grid, boolean[][] v){
		int[] d = {-1, 1, 0, 0};
		v[x][y] = true;
		grid[x][y] = '*';
		for(int i = 0; i < 4; i++){
			int dx = x+d[i], dy = y+d[3-i];
			if(inBounds(dx, dy) && !v[dx][dy]){
				if(grid[dx][dy] == '.'){
					DeeEfEs(dx, dy, grid, v);
				}
			}
		}
	}

	static void DFS(int x, int y, char[][] grid, boolean[][] v){
		int[] d = {-1, 1, 0, 0};
		v[x][y] = true;
		c++;
		for(int i = 0; i < 4; i++){
			int dx = x+d[i], dy = y+d[3-i];
			if(inBounds(dx, dy) && !v[dx][dy]){
				if(grid[dx][dy] == '.'){
					DFS(dx, dy, grid, v);
				}
			}
		}
	}

	static void dfs(int x, int y, char[][] grid, boolean[][] v){
		int[] d = {-1, 1, 0, 0};
		v[x][y] = true;
		grid[x][y] = '#';
		for(int i = 0; i < 4; i++){
			int dx = x+d[i], dy = y+d[3-i];
			if(inBounds(dx, dy) && !v[dx][dy]){
				if(grid[dx][dy] == '.'){
					dfs(dx, dy, grid, v);
				}
			}
		}
	}
