    static char[][] map = new char[55][55];
    private static void findMimunWaterCallNeedToFill(int n, int m, int k){
        List<Point> lakes = new ArrayList<>();
        char[][] b = new char[n][m];
        for (int i = 0; i < n ; i++){
            for (int j = 0; j < m; j++){
                b[i][j] = map[i][j];
            }
        }


        for (int i = 0; i < n; i++){
            if (map[i][0] == '.'){

                dfs(i, 0, n, m);
            }
            if (map[i][m-1] == '.'){

                dfs(i, m-1, n, m);
            }
        }


        for (int i = 0; i < m; i++){
            if (map[0][i] == '.'){

                dfs(0, i, n, m);
            }
            if (map[n-1][i] == '.'){

                dfs(n-1, i, n, m);
            }
        }


        for(int i = 0; i < n; i++){
            for (int j = 0; j < m; j++){
                if (map[i][j] == '.'){
                    count = 0;

                    dfs(i, j , n, m);

                    lakes.add(new Point(i, j, count));
                }
            }
        }


        for(int i = 0; i < n; i++){
            for (int j = 0; j < m; j++){
                    map[i][j] = b[i][j];
            }
        }

        Collections.sort(lakes);

