    static int[] dy = new int[]{0, 0, 1, -1};
    static int count = 0;
    private static void dfs(int x, int y, int n, int m){
        map[x][y] = '*';
        count++;
        for (int i = 0; i < 4; i++){
            int newX = x + dx[i];
            int newY = y + dy[i];
            if (newX >=0 && newX < n && newY >=0 && newY < m && map[newX][newY] == '.'){
                dfs(newX, newY, n, m);
            }
        }
    }
