import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

public class D723 {
    static BufferedReader br;
    static StringTokenizer st;
    static PrintWriter pw;

    static String nextToken() {
        try {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return st.nextToken();
    }

    static int nextInt() {
        return Integer.parseInt(nextToken());
    }

    static long nextLong() {
        return Long.parseLong(nextToken());
    }

    static double nextDouble() {
        return Double.parseDouble(nextToken());
    }

    public static void main(String[] args) {
        br = new BufferedReader(new InputStreamReader(System.in));
        pw = new PrintWriter(System.out);
        run();
        pw.close();
    }

    static int[] head;
    static int[] edges;
    static int[] next;
    static int edgeId = 0;
    static boolean[] V;
    static char[][] s;
    static int n;
    static int m;

    private static void run() {
        n = nextInt();
        m = nextInt();
        int k = nextInt();
        head = new int[n * m];
        Arrays.fill(head, -1);
        next = new int[m * n * 4 * 2];
        edges = new int[m * n * 4 * 2];
        V = new boolean[n * m];
        s = new char[n][m];
        for (int i = 0; i < n; i++) {
            String ss = nextToken();
            for (int j = 0; j < ss.length(); j++) {
                s[i][j] = ss.charAt(j);
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s[i][j] == '.') {
                    if (j + 1 < m && s[i][j + 1] == '.') {
                        addEdge(i * m + j, i * m + j + 1);
                    }
                    if (j - 1 >= 0 && s[i][j - 1] == '.') {
                        addEdge(i * m + j, i * m + j - 1);
                    }
                    if (i + 1 < n && s[i + 1][j] == '.') {
                        addEdge(i * m + j, (i + 1) * m + j);
                    }
                    if (i - 1 >= 0 && s[i - 1][j] == '.') {
                        addEdge(i * m + j, (i - 1) * m + j);
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            if (s[i][0] == '.') {
                dfs1(i * m);
            }
            if (s[i][m - 1] == '.') {
                dfs1(i * m + m - 1);
            }
        }
        for (int i = 0; i < m; i++) {
            if (s[0][i] == '.') {
                dfs1(i);
            }
            if (s[n - 1][i] == '.') {
                dfs1((n - 1) * m + i);
            }
        }
        ArrayList<Four> mas = new ArrayList<>();
        used = new int[n * m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s[i][j] == '.' && used[i * m + j] == 0 && !V[i * m + j]) {
                    ss = 0;
                    dfs2(i * m + j);
                    mas.add(new Four(ss, sh, i, j));
                    sh++;
                }
            }
        }
        long ans = 0;
        Collections.sort(mas);
        used2 = new boolean[n * m];
        for (int i = 0; i < mas.size() - k; i++) {
            ans += mas.get(i).a;
            dfs3(mas.get(i).c * m + mas.get(i).d);
        }
        pw.println(ans);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                pw.print(s[i][j]);
            }
            pw.println();
        }
    }


    private static void dfs3(int v) {
        if (used2[v]) return;
        used2[v] = true;
        s[(v - v % m) / m][v % m] = '*';
        for (int i = head[v]; i != -1; i = next[i]) {
            int vv = edges[i];
            dfs3(vv);
        }
    }

    static boolean[] used2;

    static int ss;
    static int sh = 1;

    private static void dfs2(int v) {
        if (used[v] != 0) return;
        used[v] = sh;
        ss++;
        for (int i = head[v]; i != -1; i = next[i]) {
            dfs2(edges[i]);
        }
    }

    static int[] used;

    private static void dfs1(int v) {
        if (V[v]) return;
        V[v] = true;
        for (int i = head[v]; i != -1; i = next[i]) {
            int vv = edges[i];
            dfs1(vv);
        }
    }

    private static void addEdge(int x, int y) {
        edges[edgeId] = y;
        next[edgeId] = head[x];
        head[x] = edgeId++;
    }

}

