public class Codeforces375_2D {

static class Field{
	int n;
	int m;
	int k;
	boolean[][] b;

	Field(){
		Scanner in = new Scanner(System.in);
		String[] s = in.nextLine().split(" ");
		n = Integer.parseInt(s[0]);
		m = Integer.parseInt(s[1]);
		k = Integer.parseInt(s[2]);

		b = new boolean[n][m];
		for (int i = 0; i < n; i++) {
			String str = in.nextLine();
			for (int j = 0; j < m; j++) {
				if (str.charAt(j) == '*') {
					b[i][j] = false;
				} else {
					b[i][j] = true;
				}
			}
		}
		in.close();
	}

	ArrayList<ArrayList<int[]>> getLakes(){
		boolean[][] b1 = new boolean[n][m];
		for(int i = 0; i<n; i++){
			for (int j = 0; j<m; j++){
				 b1[i][j] = b[i][j];
			}
		}
		ArrayList<ArrayList<int[]>> lakes = new ArrayList<>();
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				boolean hasBorder = false;
				LinkedList<int[]> ll = new LinkedList<>();
				if (b1[i][j]) {
					ArrayList<int[]> lake = new ArrayList<>();
					int[] arr = new int[2];
					arr[0] = i;
					arr[1] = j;
					lake.add(arr);
					ll.addLast(arr);

					if (i == 0 || i == n - 1 || j == 0 || j == m - 1)
						hasBorder = true;

					b1[i][j] = false;
					int i1, j1;
					while (ll.size() > 0) {
						arr = ll.removeFirst();
						i1 = arr[0];
						j1 = arr[1];
						if (i1 == 0 || i1 == n - 1 || j1 == 0 || j1 == m - 1)
							hasBorder = true;
						if (i1 != 0)
							if (b1[i1 - 1][j1] == true) {
								arr = new int[2];
								arr[0] = i1 - 1;
								arr[1] = j1;
								lake.add(arr);
								ll.addLast(arr);

								b1[i1 - 1][j1] = false;
							}
						if (i1 != n - 1)
							if (b1[i1 + 1][j1] == true) {
								arr = new int[2];
								arr[0] = i1 + 1;
								arr[1] = j1;
								lake.add(arr);
								ll.addLast(arr);

								b1[i1 + 1][j1] = false;
							}
						if (j1 != 0)
							if (b1[i1][j1 - 1] == true) {
								arr = new int[2];
								arr[0] = i1;
								arr[1] = j1 - 1;
								lake.add(arr);
								ll.addLast(arr);

								b1[i1][j1 - 1] = false;
							}
						if (j1 != m - 1)
							if (b1[i1][j1 + 1] == true) {
								arr = new int[2];
								arr[0] = i1;
								arr[1] = j1 + 1;
								lake.add(arr);
								ll.addLast(arr);

								b1[i1][j1 + 1] = false;
							}
					}
					if (!hasBorder)
						lakes.add(lake);
				}
			}
		}
		return lakes;
	}
	int fillLakes(){
		ArrayList<ArrayList<int[]>> lakes = getLakes();


		class Pair implements Comparable<Pair> {
			int i;
			int j;

			Pair(int i, int j) {
				this.i = i;
				this.j = j;
			}

			@Override
			public int compareTo(Pair o) {
				if (this.i > o.i)
					return 1;
				else if (this.i < o.i)
					return -1;
				else
					return 0;
			}
		}

		ArrayList<Pair> utilList = new ArrayList<>();
		for (int i = 0; i < lakes.size(); i++) {
			utilList.add(new Pair(lakes.get(i).size(), i));
		}
		Collections.sort(utilList);
		int count = lakes.size();
		int res = 0;
		for (int i = 0; i < count - k; i++) {
			ArrayList<int[]> lake = lakes.get(utilList.get(i).j);
			for (int[] arr : lake) {
				b[arr[0]][arr[1]] = false;
				res++;
			}
		}
		return res;
	}
	void out(){
		if (m <= 2 || n <= 2) {
			System.out.println(0);
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					System.out.print(b[i][j] ? '.' : '*');
				}
				System.out.println();
			}
		}else{
			System.out.println(fillLakes());
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					System.out.print(b[i][j] ? '.' : '*');
				}
				System.out.println();
			}
		}

	}
}

	public static void main(String[] args) {
		Field f = new Field();
		f.out();
	}
}

import java.util.*;
import java.io.*;

public class lakesinberland {
	public static void main(String[] args) throws IOException {
		BufferedReader fin = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(fin.readLine());
		int n = Integer.parseInt(st.nextToken());
		int m = Integer.parseInt(st.nextToken());
		int k = Integer.parseInt(st.nextToken());
		HashSet<Integer> lakes = new HashSet<Integer>();
		ArrayList<int[]> sizes = new ArrayList<int[]>();
		int[][] g = new int[n][m];
		for(int i = 0; i < n; i++) {
			String input = fin.readLine();
			for(int j = 0; j < m; j++) {
				char next = input.charAt(j);
				g[i][j] = (next == '*')? 0 : -1;
			}
		}
		int[] xDiff = new int[] {0, 0, 1, -1};
		int[] yDiff = new int[] {1, -1, 0, 0};
		int pointer = 0;
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(g[i][j] == -1) {

					pointer ++;
					Stack<ArrayList<Integer>> s = new Stack<ArrayList<Integer>>();
					HashSet<ArrayList<Integer>> v = new HashSet<ArrayList<Integer>>();
					ArrayList<Integer> first = new ArrayList<Integer>(Arrays.asList(i, j));
					s.add(first);
					v.add(first);
					boolean isOcean = false;
					int size = 0;
					while(s.size() != 0) {
						size ++;
						ArrayList<Integer> next = s.pop();
						int x = next.get(0);
						int y = next.get(1);
						g[x][y] = pointer;
						if(x + 1 == n || x - 1 == -1 || y + 1 == m || y - 1 == -1) {
							isOcean = true;
						}
						for(int u = 0; u < 4; u++) {
							int[] cur = new int[] {x + xDiff[u], y + yDiff[u]};
							if(cur[0] != -1 && cur[0] != n && cur[1] != m && cur[1] != -1 && g[cur[0]][cur[1]] == -1 && !v.contains(new ArrayList<Integer>(Arrays.asList(cur[0], cur[1])))) {
								ArrayList<Integer> newArray = new ArrayList<Integer>(Arrays.asList(cur[0], cur[1]));
								s.add(newArray);
								v.add(newArray);
							}
						}
					}
					if(!isOcean) {
						lakes.add(pointer);
						sizes.add(new int[] {size, pointer});
					}
				}
			}
		}
		int removeNum = lakes.size() - k;







		sizes.sort((a, b) -> a[0] - b[0]);




		int cost = 0;
		HashSet<Integer> remove = new HashSet<Integer>();
		for(int i = 0; i < removeNum; i++) {
			cost += sizes.get(i)[0];
			remove.add(sizes.get(i)[1]);
		}
		StringBuilder fout = new StringBuilder();
		fout.append(cost).append("\n");
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(g[i][j] == 0) {
					fout.append("*");
				}
				else if(remove.contains(g[i][j])) {
					fout.append("*");
				}
				else {
					fout.append(".");
				}
			}
			fout.append("\n");
		}
		System.out.print(fout);
	}
}

