    static void bfsForUpdate(Pair p,char[][] c){
        Queue<Pair> q = new LinkedList<>();
        q.add(p);
        visited[p.u][p.v] = true;

        while (!q.isEmpty()) {
            p = q.poll();
            int x = p.u;
            int y = p.v;
            c[x][y] = '*';
            for (int m = -1; m <= 1; m++) {
                for (int l = -1; l <= 1; l++) {
                    if (Math.abs(m) != Math.abs(l)) {
                        if (c[x + m][y + l] == '.' && !visited[x + m][y + l]) {
                            q.add(new Pair(x + m, y + l));
                        }
                        visited[x + m][y + l] = true;
                    }
                }
            }
        }
    }
    static int bfs(int i, int j, char[][] c, int a,int b) {
        int count = 0;
        int flag = 0;
        Queue<Pair> q = new LinkedList<>();
        q.add(new Pair(i, j));
        visited[i][j] = true;
        while (!q.isEmpty()) {
            Pair p = q.poll();
            count++;
            int x = p.u;
            int y = p.v;
            for (int m = -1; m <= 1; m++) {
                for (int l = -1; l <= 1; l++) {
                    if(x+m>=0 && x+m<=a-1 && y+l>=0 && y+l<=b-1 && Math.abs(m)!=Math.abs(l)){
                        if ((x + m == 0 || y + l == 0 || x + m == a - 1 || y + l == b - 1) && c[x + m][y + l] == '.') {
                            flag = 1;
                        }
                        if (c[x + m][y + l] == '.' && !visited[x + m][y + l] ) {
                            q.add(new Pair(x + m, y + l));
                        }
                        visited[x+m][y+l] = true;
                    }
                }
            }
        }
        if (flag == 0) {
            return count;
        } else
            return -1;
    }




    static class Pair implements Comparable<Pair> {
        int u;
        int v;
        BigInteger bi;
        public Pair(int u,int v) {
            this.u = u;
            this.v = v;
        }


        public int hashCode() {
            int hu = (int) (u ^ (u >>> 32));
            int hv = (int) (v ^ (v >>> 32));
            return 31 * hu + hv;
        }

        public boolean equals(Object o) {
            Pair other = (Pair) o;
            return u == other.u && v == other.v;
        }

        public int compareTo(Pair other) {
            return Long.compare(u, other.u) != 0 ? Long.compare(u, other.u) : Long.compare(v, other.v);
        }

        public String toString() {
            return "[u=" + u + ", v=" + v + "]";
        }
    }
    static class FasterScanner {
        private byte[] buf = new byte[1024];
        private int curChar;
        private int snumChars;

        public int read() {
            if (snumChars == -1)
                throw new InputMismatchException();
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = System.in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

