public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        int n;
        int m;
        int k;
        char[][] map;
        static final int[] dx = {-1, 0, 1, 0};
        static final int[] dy = {0, -1, 0, 1};

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            k = in.nextInt();
            map = new char[n][m + 1];
            for (int i = 0; i < n; ++i) {
                map[i] = in.next().toCharArray();
            }
            int[][] vis = new int[n][m];
            for (int i = 0; i < n; ++i) {
                Arrays.fill(vis[i], -1);
            }
            ArrayList<Node> candidate = new ArrayList<>();
            int tot = 0;
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (map[i][j] == '.' && vis[i][j] == -1) {
                        int cnt = go(i, j, vis, tot);
                        if (cnt != 0) {
                            candidate.add(new Node(cnt, tot));
                        }
                        ++tot;
                    }
                }
            }
            Collections.sort(candidate);
            int cnt = 0;
            boolean[] mk = new boolean[tot];
            for (int i = 0; i < candidate.size() - k; ++i) {
                Node a = candidate.get(i);
                cnt += a.size;
                mk[a.id] = true;
            }
            out.println(cnt);
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (vis[i][j] >= 0 && mk[vis[i][j]]) {
                        map[i][j] = '*';
                    }
                }
            }
            for (int i = 0; i < n; ++i) {
                out.println(map[i]);
            }
        }

        int go(int x, int y, int[][] vis, int id) {
            int ret = 1;
            vis[x][y] = id;
            boolean flag = false;
            for (int i = 0; i < 4; ++i) {
                int xx = x + dx[i];
                int yy = y + dy[i];
                if (xx < 0 || xx >= n || yy < 0 || yy >= m) {
                    flag = true;
                } else {
                    if (vis[xx][yy] == -1 && map[xx][yy] == '.') {
                        int tmp = go(xx, yy, vis, id);
                        if (tmp == 0) {
                            flag = true;
                        } else {
                            ret += tmp;
                        }
                    }
                }
            }
            if (flag) {
                ret = 0;
            }
            return ret;
        }

        class Node implements Comparable<Node> {
            int size;
            int id;

            Node(int size, int id) {
                this.size = size;
                this.id = id;
            }


            public int compareTo(Node o) {
                return size - o.size;
            }

        }

    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
