import java.util.StringTokenizer;

public class Main {

    public static char[][] grid;
    public static boolean[][] marked;
    public static int[] di = new int[] {1, -1, 0, 0};
    public static int[] dj = new int[] {0, 0, 1, -1};
    public static boolean isLake = true;
    public static ArrayList<int[]> lakes = new ArrayList<>();
    public static ArrayList<ArrayList<int[]>> lakeCells = new ArrayList<>();
    public static ArrayList<int[]> curCells = new ArrayList<>();
    public static int count = 0;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken()); int m = Integer.parseInt(st.nextToken()); int k = Integer.parseInt(st.nextToken());
        grid = new char[n][m];
        for (int i=0; i<n; i++) {
            st = new StringTokenizer(br.readLine());
            String line = st.nextToken();
            for (int j=0; j<m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        marked = new boolean[n][m];
        for (int i=0; i<n; i++) {
            for (int j=0; j<m; j++) {
                if (!marked[i][j] && grid[i][j]=='.') {
                    marked[i][j] = true;
                    isLake = true; count = 0;
                    curCells = new ArrayList<>();
                    flood_fill(i, j);



                    if (isLake) {

                        lakeCells.add(curCells);

                        lakes.add(new int[] {count, lakes.size()});
                    }
                }
            }
        }








        java.util.Collections.sort(lakes, new java.util.Comparator<int[]>() {
            public int compare(int[] a, int[] b) {
                return Integer.compare(a[0], b[0]);
            }
        });
        int ans = 0;
        for (int i=0; i<lakes.size()-k; i++) {
            ans += lakes.get(i)[0];
            for (int j=0; j<lakeCells.get(lakes.get(i)[1]).size(); j++) {
                grid[lakeCells.get(lakes.get(i)[1]).get(j)[0]][lakeCells.get(lakes.get(i)[1]).get(j)[1]] = '*';
            }
        }
        System.out.println(ans);
        for (int i=0; i<n; i++) {
            for (int j=0; j<m; j++) {
                System.out.print(grid[i][j]);
            }
            System.out.println();
        }

    }

    public static void flood_fill(int r, int c) {
        if (r==0 || c==0 || r==grid.length-1 || c==grid[0].length-1) {
            isLake = false;
        }
        count++; curCells.add(new int[] {r, c});
        for (int i=0; i<4; i++) {
            if (r+di[i]>=0 && r+di[i]<grid.length && c+dj[i]>=0 && c+dj[i]<grid[0].length && grid[r+di[i]][c+dj[i]]=='.' && !marked[r+di[i]][c+dj[i]]) {
                marked[r+di[i]][c+dj[i]] = true;
                flood_fill(r+di[i], c+dj[i]);
            }
        }
    }
}

import java.awt.Point;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;
import java.util.Stack;



public class Main {

    static int dx[] = {0,0,1,-1};
    static int dy[] = {1,-1,0,0};
    private static int [][] path;
    private static char [][] input;
    private static int N;
    private static int M;
    private static boolean [][] visited;
    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        int K = sc.nextInt();
        input  = new char [N][M];
        for (int i = 0; i < N; i++){
            String line = sc.next();
            for (int j = 0; j < M; j++){
                input[i][j] = line.charAt(j);
            }
        }
        path = new int [N][M];
        for (int i = 0; i < N; i++){
            for (int j = 0; j < M; j++){
                path[i][j] = -1;
            }
        }
        for (int i = 0; i < N; i++){
            for (int j = 0; j < M; j++){
                if (isPointOnEdge(new Point(i,j)) == true && input[i][j] == '.'){
                    DFS(new Point(i,j));
                }
            }
        }
        int cur_lake = 0;
        ArrayList<ArrayList<Point>> dots = new ArrayList<>();
        ArrayList<Integer> length = new ArrayList<>();

        for (int i = 0; i < N; i++){
            for (int j = 0; j < M; j++){
                if (path[i][j] == -1 && input[i][j] == '.'){
                    ArrayList<Point> temp = DFS( new Point(i,j));
                    dots.add(temp);
                    length.add(temp.size());
                    cur_lake ++;
                }
            }
        }
        Collections.sort(length);
        int clear_lake = cur_lake - K;
        int min_num = 0;
        for (int i = 0; i < clear_lake; i++){
            min_num += length.get(i);

            for (int j = 0; j < dots.size(); j++){
                if (dots.get(j).size() == length.get(i)){
                    Point t = dots.get(j).get(0);
                    if (path[t.x][t.y] != 1){
                        for (int k = 0; k < dots.get(j).size(); k++){
                            Point p = dots.get(j).get(k);
                            path[p.x][p.y] = 1;
                        }
                        break;
                    }
                }
            }
        }
        System.out.println(min_num);

        for (int i = 0; i < N; i++){
            for (int j = 0; j < M; j++){
                if (path[i][j] == -1 || path[i][j] == 0) 
                    System.out.print(input[i][j]);
                if (path[i][j] == 1) System.out.print("*");
            }
            System.out.println();
        }

    }

    public static boolean isPointOnEdge(Point s){
        return(s.x == 0 || s.y == 0 || s.x == N-1 || s.y == M-1);
    }
    public static ArrayList<Point> DFS (Point s){
        Stack<Point> stack = new Stack <>();
        ArrayList<Point> dots_arr = new ArrayList<>();
        stack.push(s);
        dots_arr.add(s);
        path [s.x][s.y] = 0;
        while (!stack.isEmpty()){
            Point u = stack.peek();
            stack.pop();
            for (int i = 0; i < dx.length; i++){
                int x = u.x + dx[i];
                int y = u.y + dy[i];
                if (x >= 0 && x < N && y >= 0 && y < M){
                    if (path[x][y] == -1 && input[x][y] == '.'){
                        stack.add(new Point(x,y));
                        dots_arr.add(new Point(x,y));
                        path[x][y] = 0;
                    }
                }
            }
        }
        return dots_arr;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;

public class Main
{	
	private static String[] input = new String[100];
	private static char[][] matrix = new char[100][];

	private static class Element implements Comparable<Element>
	{
		public int x;
		public int y;
		public int size;

		public Element(int x , int y , int size)
		{
			this.x = x;
			this.y = y;
			this.size = size;
		}

		public int compareTo(Element e)
		{
			if (this.size < e.size)
				return - 1;
			else if (this.size > e.size)
				return 1;
			else
				return 0;
		}
	}

	private static boolean[][] vis = new boolean[100][100];
	private static List<Element> list = new ArrayList<Element>();

	public static void main(String[] args)
	{
		Scanner scan = new Scanner(System.in);
		int i , j , n , m , k;
		n = scan.nextInt();
		m = scan.nextInt();
		k = scan.nextInt();

		for (i = 0;i < n;i ++)
		{
			input[i] = scan.next();
			matrix[i] = input[i].toCharArray();
		}

		for (i = 0;i < n;i ++)
		{
			for (j = 0;j < m;j ++)
			{
				if (input[i].charAt(j) == '.' && !vis[i][j])
					bfs(i , j , n , m);
			}
		}

		for (i = 0;i < n;i ++)
			for (j = 0;j < m;j ++)
				vis[i][j] = false;

		Collections.sort(list);
		int tot = list.size() , ans = 0;
		for (i = 0;i < tot - k;i ++)
		{
			fill(list.get(i).x , list.get(i).y , n , m);
			ans += list.get(i).size;
		}

		System.out.println(ans);
		for (i = 0;i < n;i ++)
		{
			StringBuilder builder = new StringBuilder();
			for (j = 0;j < m;j ++)
				builder.append(matrix[i][j]);
			System.out.println(builder.toString());
		}
	}

	private static void fill(int x , int y , int n , int m)
	{
		Queue<Position> queue = new LinkedList<Position>();
		queue.add(new Position(x , y));
		vis[x][y] = true;

		while (!queue.isEmpty())
		{
			Position pos = queue.poll();
			matrix[pos.x][pos.y] = '*';

			for (int i = 0;i < 4;i ++)
			{
				int tx = pos.x + dx[i];
				int ty = pos.y + dy[i];
				if (tx >= 0 && tx < n && ty >= 0 && ty < m && !vis[tx][ty] && matrix[tx][ty] == '.')
				{
					vis[tx][ty] = true;
					queue.add(new Position(tx , ty));
				}
			}
		}

	}

	private static class Position
	{
		public int x;
		public int y;

		public Position(int x , int y)
		{
			this.x = x;
			this.y = y;
		}
	}

	private static int[] dx = new int[] {- 1 , 0 , 1 , 0};
	private static int[] dy = new int[] {0 , 1 , 0 , - 1};

	private static void bfs(int x , int y , int n , int m)
	{
		Queue<Position> queue = new LinkedList<Position>();
		queue.add(new Position(x , y));
		vis[x][y] = true;
		boolean flag = false;
		int tot = 0;

		while (!queue.isEmpty())
		{	
			Position pos = queue.poll();
			tot ++;

			for (int i = 0;i < 4;i ++)
			{
				int tx = pos.x + dx[i];
				int ty = pos.y + dy[i];
				if (tx >= 0 && tx < n && ty >= 0 && ty < m)
				{
					if (input[tx].charAt(ty) == '.' && !vis[tx][ty])
					{
						vis[tx][ty] = true;
						queue.add(new Position(tx , ty));
					}
				}
				else
					flag = true;
			}
		}

		if (!flag)
			list.add(new Element(x , y , tot));
	}

}

import java.util.Scanner;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Set;
import java.util.HashSet;
import java.util.Comparator;
import java.util.Collections;

public class BigO2302 {

	private static Queue<int[]> moving = new LinkedList<>(); 
	private static int[] dx = {0, 0, -1, 1};
	private static int[] dy = {-1, 1, 0, 0};
	private static int N;
	private static int M;
	private static int K;
	private static char[][] map;
	private static Set<int[]> mark;
	private static boolean[][] check;
	private static LinkedList<Set<int[]>> lakes = new LinkedList<Set<int[]>>();

	public static void move() {
		boolean checking = false;
		while (!moving.isEmpty()) {
			int[] temp = moving.remove();
			for (int i = 0; i < dx.length; i++) {
				int x = temp[0] + dx[i];
				int y = temp[1] + dy[i];
				int[] tempA = {x, y};
				if (((x >= 0) && (x <= M - 1) && (y >= 0) && (y <= N - 1)) && (map[x][y] == '.') && (check[x][y] == false)) {
					if ((x == 0) || (y == 0) || (x == M - 1) || (y == N - 1))
						checking = true;
					mark.add(tempA);
					moving.add(tempA);
					check[x][y] = true;
				}
			}
		}
		if (checking) {
			mark.removeAll(mark);
			return;
		}
		Set<int[]> tempMark = new HashSet<int[]>(mark);
		lakes.add(tempMark);
		mark.removeAll(mark);
	}

	public static void main(String[] args) {
		Scanner userInput = new Scanner(System.in);
		N = userInput.nextInt();
		M = userInput.nextInt();
		K = userInput.nextInt();
		map = new char[M][N];
		check = new boolean[M][N];
		mark = new HashSet<int[]>();
		for (int i = 0; i < N; i++) {
			String t = userInput.next();
			for (int j = 0; j < M; j++) 
				map[j][i] = t.charAt(j);
		}
		for (int y = 1; y < N - 1; y++)
			for (int x = 1; x < M - 1; x++) {
				if ((map[x][y] == '.') && check[x][y] == false) {
					int[] temp = {x, y};
					moving.add(temp);
					mark.add(temp);
					check[x][y] = true;
					move();
				}
			}
		Collections.sort(lakes, new Comparator<Set<int[]>>() {
			@Override
			public int compare(Set<int[]> a, Set<int[]> b) {
				return a.size() - b.size();
			}
		});
		int output = 0;
		for (int i = 0; i < lakes.size() - K; i++) {
			for (int[] t : lakes.get(i)) {
				output++;
				int x = t[0];
				int y = t[1];
				map[x][y] = '*';
			}
		}
		System.out.println(output);
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < M; j++)
				System.out.print(map[j][i]);
			System.out.print("\n");
		}
		userInput.close();
	}

}

import java.lang.*;
import java.util.*;
import java.io.*;

public class Main {
    static FastScanner in = new FastScanner();

    static int[] dx = {-1, 0, 1, 0};
    static int[] dy = {0, 1, 0, -1};
    static int n, m;
    static boolean[][] a, vis, ignore;

    static boolean isOk(int x, int y) {
        if (x < 0 || x >= n || y < 0 || y >= m)
            return false;
        if (!a[x][y])
            return false;
        if (vis[x][y] || ignore[x][y])
            return false;
        return true;
    }

    static void fillEdges(int startx, int starty) {
        Queue<Pair<Integer, Integer>> q = new LinkedList<>();
        q.add(new Pair<>(startx, starty));
        ignore[startx][starty] = true;
        while (!q.isEmpty()) {
            Pair<Integer, Integer> p = q.remove();
            int x = p.x, y = p.y;
            for (int d = 0; d < 4; ++d) {
                int nx = x + dx[d], ny = y + dy[d];
                if (isOk(nx, ny)) {
                    q.add(new Pair<>(nx, ny));
                    ignore[nx][ny] = true;
                }
            }
        }
    }

    static int BFS(int startx, int starty, boolean fill) {
        Queue<Pair<Integer, Integer>> q = new LinkedList<>();
        q.add(new Pair<>(startx, starty));
        vis[startx][starty] = true;
        if (fill) a[startx][starty] = false;
        int size = 0;
        while (!q.isEmpty()) {
            Pair<Integer, Integer> p = q.remove();
            int x = p.x, y = p.y;
            ++size;
            for (int d = 0; d < 4; ++d) {
                int nx = x + dx[d], ny = y + dy[d];
                if (isOk(nx, ny)) {
                    q.add(new Pair<>(nx, ny));
                    vis[nx][ny] = true;
                    if (fill) a[nx][ny] = false;
                }
            }
        }
        return size;
    }

    static void solve() {
        n = in.nextInt(); m = in.nextInt();
        int k = in.nextInt();
        a = new boolean[n][m];
        vis = new boolean[n][m];
        ignore = new boolean[n][m];
        for (int i = 0; i < n; ++i) {
            String s = in.next();
            for (int j = 0; j < m; ++j)
                a[i][j] = (s.charAt(j) == '.');
        }


        for (int i = 0; i < n; ++i) {
            if (a[i][0]) fillEdges(i, 0);
            if (a[i][m - 1]) fillEdges(i, m - 1);
        }
        for (int j = 0; j < m; ++j) {
            if (a[0][j]) fillEdges(0, j);
            if (a[n - 1][j]) fillEdges(n - 1, j);
        }


        int nrLakes = 0;
        ArrayList<Pair<Integer, Pair<Integer, Integer>>> v = new ArrayList<>();
        for (int i = 1; i < n - 1; ++i) {
            for (int j = 1; j < m - 1; ++j) {
                if (a[i][j] && !vis[i][j] && !ignore[i][j]) {
                    int size = BFS(i, j, false);
                    ++nrLakes;
                    v.add(new Pair<>(size, new Pair<>(i, j)));
                }
            }
        }


        Collections.sort(v, (a, b) -> (a.x - b.x));
        vis = new boolean[n][m];
        int ans = 0;
        for (Pair<Integer, Pair<Integer, Integer>> el : v) {
            if (nrLakes <= k)
                break;
            int x = el.y.x, y = el.y.y, size = el.x;
            BFS(x, y, true);
            ans += size;
            --nrLakes;
        }


        System.out.println(ans);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j)
                System.out.print(a[i][j] ? '.' : '*');
            System.out.println();
        }
    }

    public static void main(String[] args) {
        int T = 1;
        while (T-- > 0)
            solve();
    }

    static void swap(int a, int b) {
        int r = a;
        a = b;
        b = r;
    }

    static class Pair<X, Y> {
        X x;
        Y y;

        public Pair(X x, Y y) {
            this.x = x;
            this.y = y;
        }
    }
}

