import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.Scanner;

public class Main {
    static int dx[] = {-1, 0, 1, 0};
    static int dy[] = {0, 1, 0, -1};
    static int n, m, k, cellCnt;
    static StringBuilder[] sb;
    static boolean visited[][], onBoundary;

    static void DFS(int x, int y) {
        visited[x][y] = true;
        ++cellCnt;
        if (x == 0 || x == n - 1 || y == 0 || y == m - 1)
            onBoundary = true;
        for (int dir = 0; dir < 4; ++dir) {
            int u = x + dx[dir], v = y + dy[dir];
            if (u >= 0 && u < n && v >= 0 && v < m && sb[u].charAt(v) == '.' && !visited[u][v])
                DFS(u, v);
        }
    }

    static void fill(int x, int y) {
        sb[x].setCharAt(y, '*');
        for (int dir = 0; dir < 4; ++dir) {
            int u = x + dx[dir], v = y + dy[dir];
            if (sb[u].charAt(v) == '.') fill(u, v);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        sb = new StringBuilder[n];
        for (int i = 0; i < n; ++i)
            sb[i] = new StringBuilder(sc.next());

        ArrayList<Lake> lakes = new ArrayList<>();

        visited = new boolean[n][m];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (sb[i].charAt(j) == '.' && !visited[i][j]) {
                    cellCnt = 0;
                    onBoundary = false;
                    DFS(i, j);
                    if (!onBoundary)
                        lakes.add(new Lake(cellCnt, i, j));
                }
            }
        }

        Collections.sort(lakes, Comparator.comparing(o -> o.compSz));

        int lakeCnt = lakes.size();
        cellCnt = 0;
        for(Lake lake: lakes) {
            if (lakeCnt == k)
                break;
            --lakeCnt;
            cellCnt += lake.compSz;
            fill(lake.x, lake.y);
        }

        pw.println(cellCnt);
        for(int i = 0; i < n; ++i)
            pw.println(sb[i].toString());
        pw.close();
    }

    static class Lake {
        int compSz, x, y;

        public Lake(int compSz, int x, int y) {
            this.compSz = compSz;
            this.x = x;
            this.y = y;
        }
    }
}

import java.awt.Point;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;
import java.util.Stack;

public class Main {
    static int [][] dist;
    static int[] dx = {0,0,1,-1};
    static int[] dy = {1,-1, 0,0};
    static int N;
    static int M;
    static int[][] input;
    public static void main(String[] args) {
        Scanner sc = new Scanner (System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        int K = sc.nextInt();
        input = new int [N][M];
        char[][] arr = new char[N][M];
        sc.nextLine();
        dist = new int [N][M];
        for (int i = 0; i < N; i++){
            String line = sc.nextLine();
            for (int j = 0; j < M; j++){
                arr[i][j] = line.charAt(j);
                if (line.charAt(j) == '*')
                    input[i][j] = 0;
                else if (line.charAt(j) == '.'){
                    input[i][j] = 1;
                }
                dist[i][j] = -1;
            }
        } 

        for (int i = 0; i < N; i++){
            for (int j = 0; j < M; j++){
                if (isPointOnEdge(new Point(i,j)) == true){

                    DFS (new Point(i,j));
                }
            }
        }

        int cnt_lake = 0;
        ArrayList<ArrayList<Point>> res = new ArrayList<>();
        ArrayList<Integer> length = new ArrayList<>();
        for (int i = 0; i < N; i++){
            for (int j = 0; j < M; j++){
                if (input[i][j] == 1 && dist[i][j] == -1){

                    ArrayList<Point> temp = DFS(new Point(i,j));
                    res.add(temp);
                    length.add(temp.size());
                    cnt_lake++;
                }
            }
        }
        int del = cnt_lake - K;

        int erase = 0;
        Collections.sort(length);
        for (int i = 0; i < del; i++){
            int a = length.get(i);
            erase += a;
            for (int j = 0; j < res.size(); j++){
                if (res.get(j).size() == a && dist[res.get(j).get(0).x][res.get(j).get(0).y] != 1){
                    for (int k = 0; k < a; k++){
                        Point t = res.get(j).get(k);
                        dist[t.x][t.y] = 1;
                    }
                    break;
                }
            }
        }
        System.out.println(erase);
        for (int i = 0; i < N; i++){
            for (int j = 0; j < M; j++){

                if(dist[i][j] == -1 || dist[i][j] == 0){
                    System.out.print(arr[i][j]);
                }
                else if (dist[i][j] == 1){
                    System.out.print("*");
                }
            }
            System.out.println();
        }
    }
    public static boolean isPointOnEdge(Point s){
        return (input[s.x][s.y] == 1 && (s.x == 0 || s.x == N-1 || s.y == 0 || s.y == M-1));
    }
    public static ArrayList<Point> DFS (Point src){
        ArrayList<Point> result = new ArrayList<>();
        Stack <Point> s = new Stack<>();
        result.add(new Point(src.x, src.y));
        s.push(src);
        dist[src.x][src.y] = 0;
        while (!s.isEmpty()){
            Point u = s.pop();
            for (int i = 0; i < dx.length; i++){
                int a = u.x + dx[i];
                int b = u.y + dy[i];
                if (a >= 0 && a < N && b >= 0 && b < M){
                    if (dist[a][b] == -1 && input[a][b] == 1){
                        dist[a][b] = 0;
                        s.add(new Point(a,b));
                        result.add(new Point(a,b));
                    }
                }
            }
        }
        return result;
    }
}

