	public static class DSU {
		int[] parent;

		public DSU(int N) {
			parent = new int[N];

			for (int i = 1; i < N; i++) {
				parent[i] = i;
			}
		}

		public int getParent(int x) {
			if (x != parent[x]) parent[x] = getParent(parent[x]);
			return parent[x];
		}

		public void union(int x, int y) {
			int xParent = getParent(x);
			int yParent = getParent(y);

			if (xParent < yParent) {
				parent[yParent] = xParent;
			}
			else if (yParent < xParent) {
				parent[xParent] = yParent;
			}
		}
	}

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));



		int M = sc.nextInt();
		int N = sc.nextInt();
		int K = sc.nextInt();


		char[][] graph = new char[M][N];
		for (int r = 0; r < M; r++) {
			graph[r] = sc.next().toCharArray();
		}



		DSU dsu = new DSU(M*N);

		for (int r = 0; r < M; r++) {
			for (int c = 0; c < N; c++) {
			    if (graph[r][c] == '.') {
    				if (r > 0 && graph[r-1][c] == '.') {
    					dsu.union((r-1)*N + c, r*N + c);
    				}
    				if (c > 0 && graph[r][c-1] == '.') {
    					dsu.union(r*N + (c-1), r*N + c);
    				}
			    }
			}
		}



		Set<Integer> roots = new HashSet();
		Map<Integer, Integer> sizes = new HashMap();
		Set<Integer> onBorder = new HashSet();

		for (int r = 0; r < M; r++) {
			for (int c = 0; c < N; c++) {
				if (graph[r][c] == '.') {
					int parent = dsu.getParent(r*N + c);
					roots.add(parent);
					sizes.put(parent, sizes.getOrDefault(parent, 0) + 1);

					if (r == 0 || r == M-1 || c == 0 || c == N-1) {
					    onBorder.add(parent);
					}
				}
			}
		}




		for (int root : onBorder) {
		    roots.remove(root);
		    sizes.remove(root);
		}

		int toRemove = roots.size() - K;


		List<int[]> list = new ArrayList();
		for (int root : sizes.keySet()) {
			list.add(new int[] {root, sizes.get(root)});
		}

		Collections.sort(list, new Comparator<int[]>() {
			@Override
			public int compare(int[] a, int[] b) {
				return a[1] - b[1];
			}
		});


		Set<Integer> removeSet = new HashSet();
		for (int i = 0; i < toRemove; i++) {
			removeSet.add(list.get(i)[0]);
		}

		int removed = 0;

		for (int r = 0; r < M; r++) {
			for (int c = 0; c < N; c++) {
				if (graph[r][c] == '.') {
					int root = dsu.getParent(r*N + c);

					if (removeSet.contains(root)) {
						graph[r][c] = '*';
						removed++;
					}
				}
			}
		}


		out.println(removed);

		for (int r = 0; r < M; r++) {
		    out.println(new String(graph[r]));
		}








		out.close();
	}
}

