        Task723D task = new Task723D();
        task.open();
        task.solve();
        task.close();

    }

    private void close() {
        out.flush();
    }


    private void solve() throws IOException {


        int n = nextInt();
        int m = nextInt();
        int k = nextInt();

        char[][] arr = new char[n][m];
        int[][] mark = new int[n][m];
        for (int i = 0; i < n; ++i) {
            String s = in.readLine();
            for (int j = 0; j < s.length(); ++j) {
                arr[i][j] = s.charAt(j);
                if (arr[i][j] == '*') {
                    mark[i][j] = -1;
                }
            }
        }







        int count = 0;
        boolean[] isLake = new boolean[1000000];
        ArrayList<Integer> lakeNum = new ArrayList<Integer>();
        ArrayList<Integer> lakeSize = new ArrayList<Integer>();
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (mark[i][j] == 0) {
                    count++;
                    isLake[count] = true;
                    int size = Find(mark, count, i, j, n, m, isLake);
                    if (isLake[count]) {
                        lakeNum.add(count);
                        lakeSize.add(size);
                    }
                }
            }
        }









        int len = lakeNum.size();
        count = len;
        boolean[] c = new boolean[1000000];
        int total = 0;

        while (count > k) {
            int best = INF;
            int index = -1;
            for (int i = 0; i < len; ++i) {
                if (!c[i]) {
                    if (best > lakeSize.get(i)) {
                        index = i;
                        best = lakeSize.get(i);
                    }
                }
            }
            count--;
            int num = lakeNum.get(index);

            total += best;
            Fill(arr, mark, num, n, m);
            c[index] = true;
        }

