            for (int j = 0; j < m; ++j) {
                if (mark[i][j] == num)
                    arr[i][j] = '*';
            }
        }
    }

    private int Find(int[][] mark, int count, int x, int y, int n, int m, boolean[] isLake) {
        if (x == 0 || y == 0 || (x == n - 1) || (y == m - 1)) {
            isLake[count] = false;
        }
        mark[x][y] = count;
        int res = 1;
        for (int k = 0; k < 4; ++k) {
            int u = x + dx[k];
            int v = y + dy[k];
            if (inside(u, v, n, m) && mark[u][v] == 0) {
                res += Find(mark, count, u, v, n, m, isLake);
            }
        }
        return res;
    }

    private static boolean inside(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }


