import java.util.*;
import java.io.*;
public class f
{
	public static void main(String[] arg) throws IOException
	{
		new f();
	}
	int n, m, k;
	char[][] g;
	int ans;
	int[] dx = {-1, 1, 0, 0};
	int[] dy = {0, 0, -1, 1};
	void flood(int i, int j)
	{
		if(i < 0 || i >= n || j < 0 || j >= m) return;
		if(g[i][j] == '*') return;
		g[i][j] = '*';
		ans++;
		for(int kk = 0; kk < 4; kk++)
		{
			int ni = i+dx[kk];
			int nj = j+dy[kk];
			flood(ni, nj);
		}
	}
	public f() throws IOException
	{
		FastScanner in = new FastScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		n = in.nextInt();
		m = in.nextInt();
		k = in.nextInt();
		g = new char[n][m];
		ans = 0;
		for(int i = 0; i < n; i++) g[i] = in.next().toCharArray();
		DJ dj = new DJ(n*m);
		int size = 0;
		int[][] id = new int[n][m];
		for(int i = 0; i < n; i++) for(int j = 0; j < m; j++) id[i][j] = size++;

		for(int i = 0; i < n; i++)
		{
			for(int j = 0; j < m; j++)
			{
				for(int kk = 0; kk < 4; kk++)
				{
					int ni = i+dx[kk];
					int nj = j+dy[kk];
					if(0 <= ni && ni < n && 0 <= nj && nj < m && g[i][j] == g[ni][nj])
					{
						dj.union(id[i][j], id[ni][nj]);
					}
				}
			}
		}
		HashSet<Integer> ignore = new HashSet<Integer>();
		for(int i = 0; i < n; i++)
		{
			ignore.add(dj.find(id[i][0]));
			ignore.add(dj.find(id[i][m-1]));
		}
		for(int i = 0; i < m; i++)
		{
			ignore.add(dj.find(id[0][i]));
			ignore.add(dj.find(id[n-1][i]));
		}
		PriorityQueue<Integer> pq = new PriorityQueue<Integer>((a, b) -> (-Integer.compare(dj.vs[dj.find(a)], dj.vs[dj.find(b)])));
		boolean[] u = new boolean[n*m];
		for(int i = 1; i < n-1; i++)
		{
			for(int j = 1; j < m-1; j++)
			{
				if(g[i][j] == '*') continue;
				int p = dj.find(id[i][j]);
				if(u[p]) continue;
				if(ignore.contains(p)) continue;
				u[p] = true;
				pq.add(p);
			}
		}
		while(pq.size() > k)
		{
			int v = pq.poll();
			flood(v/m, v%m);
		}
		out.println(ans);
		for(int i = 0; i < n; i++)
		{
			for(int j = 0; j < m; j++)
			{
				out.print(g[i][j]);
			}
			out.println();
		}
		in.close(); out.close();
	}
	class DJ
	{
		int[] vs;
		public DJ(int size)
		{
			vs = new int[size];
			Arrays.fill(vs, -1);
		}
		public int find(int v)
		{
			if(vs[v] < 0) return v;
			return vs[v] = find(vs[v]);
		}
		public boolean union(int a, int b)
		{
			int pa = find(a);
			int pb = find(b);
			if(pa == pb) return false;
			if(vs[pb] < vs[pa]) pa = pa^pb^(pb=pa);
			vs[pa] += vs[pb];
			vs[pb] = pa;
			return true;
		}
	}
	class FastScanner
	{
		BufferedReader br;
		StringTokenizer st;
		public FastScanner(InputStream in)
		{
			br = new BufferedReader(new InputStreamReader(in));
			st = new StringTokenizer("");
		}
		public String next() throws IOException
		{
			while(!st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}
		public int nextInt() throws IOException
		{
			return Integer.parseInt(next());
		}
		public long nextLong() throws IOException
		{
			return Long.parseLong(next());
		}
		public void close() throws IOException
		{
			br.close();
		}
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.PriorityQueue;

public class ProblemD {
	static int n, m, k;
	static char[][] map;
	static boolean[][] visited;
	static int curArea;

	static class Lake implements Comparable<Lake> {
		int startX;
		int startY;
		int area;

		Lake (int startX, int startY, int area) {
			this.startX = startX;
			this.startY = startY;
			this.area = area;
		}

		@Override
		public int compareTo(Lake lake) {
			if (this.area > lake.area) {
				return 1;
			} else if (this.area == lake.area) {
				return 0;
			} else {
				return -1;
			}
		}
	}

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] tmp = br.readLine().split(" ");
		n = Integer.parseInt(tmp[0]);
		m = Integer.parseInt(tmp[1]);
		k = Integer.parseInt(tmp[2]);
		map = new char[n][m];
		visited = new boolean[n][m];
		for (int i=0; i<n; i++) {
			map[i] = br.readLine().toCharArray();
		}


		curArea = 0;
		for (int i=0; i<m; i++) {
			if (!visited[0][i] && map[0][i] == '.') findArea(0, i);
			if (!visited[n-1][i] && map[n-1][i] == '.') findArea(n-1, i);
		}
		for (int i=0; i<n; i++) {
			if (!visited[i][0] && map[i][0] == '.') findArea(i, 0);
			if (!visited[i][m-1] && map[i][m-1] == '.') findArea(i, m-1);
		}

		PriorityQueue<Lake> lakes = new PriorityQueue<Lake>();
		for (int i=1; i<n-1; i++) {
			for (int j=1; j<m-1; j++) {
				if (!visited[i][j] && map[i][j] == '.') {
					curArea = 0;
					findArea(i, j);
					lakes.add(new Lake(i, j, curArea));
				}
			}
		}

		int res = 0;
		while (lakes.size() > k) {
			Lake cur = lakes.poll();
			fill(cur.startX, cur.startY);
			res += cur.area;
		}

		System.out.println(res);
		for (int i=0; i<n; i++) {
			for (int j=0; j<m; j++) {
				System.out.print(map[i][j]);
			}
			System.out.println();
		}
	}

	private static void fill(int x, int y) {
		map[x][y] = '*';
		if (x > 0 && map[x-1][y] == '.') fill(x-1, y);
		if (x < n-1 && map[x+1][y] == '.') fill(x+1, y);
		if (y > 0 && map[x][y-1] == '.') fill(x, y-1);
		if (y < m-1 && map[x][y+1] == '.') fill(x, y+1);
	}

	private static void findArea(int x, int y) {
		visited[x][y] = true;
		curArea++;
		if (x > 0 && !visited[x-1][y] && map[x-1][y] == '.') findArea(x-1, y);
		if (x < n-1 && !visited[x+1][y] && map[x+1][y] == '.') findArea(x+1, y);
		if (y > 0 && !visited[x][y-1] && map[x][y-1] == '.') findArea(x, y-1);
		if (y < m-1 && !visited[x][y+1] && map[x][y+1] == '.') findArea(x, y+1);
	}
}

import java.io.BufferedReader;
