        }

        void fillLake(Lake lake) {
            fillLakeRec(lake.ze, lake.sp, new boolean[ze][sp]);
        }

        void fillLakeRec(int i, int j, boolean[][] visited) {
            if (visited[i][j]) return;
            visited[i][j] = true;
            if (lakeSize[i][j] > 0) {

                StringBuilder sb = new StringBuilder(s[i]);
                sb.setCharAt(j, '*');
                s[i] = sb.toString();

                if (!visited[i + 1][j]) fillLakeRec(i + 1, j, visited);
                if (!visited[i - 1][j]) fillLakeRec(i - 1, j, visited);
                if (!visited[i][j + 1]) fillLakeRec(i, j + 1, visited);
                if (!visited[i][j - 1]) fillLakeRec(i, j - 1, visited);
            }
        }

        void fillLakeSize(int i, int j, int z, boolean[][] visited) {
            if (visited[i][j]) return;
            visited[i][j] = true;
            lakeSize[i][j] = z;
            if ((i + 1 < ze) && (isWater[i + 1][j]) && (!visited[i + 1][j])) fillLakeSize(i + 1, j, z, visited);
            if ((i > 0) && (isWater[i - 1][j]) && (!visited[i - 1][j])) fillLakeSize(i - 1, j, z, visited);
            if ((j + 1 < sp) && (isWater[i][j + 1]) && (!visited[i][j + 1])) fillLakeSize(i, j + 1, z, visited);
            if ((j > 0) && (isWater[i][j - 1]) && (!visited[i][j - 1])) fillLakeSize(i, j - 1, z, visited);
        }

        int getLakeSize(int i, int j, boolean[][] visited) {
            if (visited[i][j]) return 0;
            visited[i][j] = true;
            if (!isWater[i][j]) return 0;
            if ((i == 0) || (i == ze - 1) || (j == 0) || (j == sp - 1)) return -1;
            int result = 1;

            int up = 0;
            if (!visited[i - 1][j]) up = getLakeSize(i - 1, j, visited);
            if (up == -1) return -1;
            result += up;

            up = 0;
            if (!visited[i + 1][j]) up = getLakeSize(i + 1, j, visited);
            if (up == -1) return -1;
            result += up;

            up = 0;
            if (!visited[i][j + 1]) up = getLakeSize(i, j + 1, visited);
            if (up == -1) return -1;
            result += up;

            up = 0;
            if (!visited[i][j - 1]) up = getLakeSize(i, j - 1, visited);
            if (up == -1) return -1;
            result += up;

            return result;

        }

        class Lake {
            int ze;
            int sp;
            int size;

            public Lake(int i, int j, int s) {
                ze = i;
                sp = j;
                size = s;
            }

        }

    }

    static class InputReader {
        private static BufferedReader in;
        private static StringTokenizer tok;

        public InputReader(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            try {
                while (tok == null || !tok.hasMoreTokens()) {
                    tok = new StringTokenizer(in.readLine());
                }
            } catch (IOException ex) {
                System.err.println("An IOException was caught :" + ex.getMessage());
            }
            return tok.nextToken();
        }

    }
}

import java.util.ArrayList;
import java.util.Map;
import java.util.Scanner;
import java.util.Stack;
import java.util.TreeMap;

public class LakesInBerlandCodeforces {
	private static Scanner in;

	public static void main(String[] args) {

		in = new Scanner(System.in);
		int n = in.nextInt();
		int m = in.nextInt();
		int lakes = in.nextInt();

		in.nextLine();		
		char[][] map = new char[n][m];

		for(int i = 0; i < n; i++)
		{
			String s = in.nextLine();
			map[i] = s.toCharArray();
		}

		char[][] backupMap = new char[n][m];

		for(int j = 0; j < n; j++)
		{
			for(int k = 0; k < m; k++)
			{
				backupMap[j][k] = map[j][k];
			}
		}

		Map<Integer, ArrayList<ArrayList<Point>>> hs = new TreeMap<Integer, ArrayList<ArrayList<Point>>>();
		int totalLakes = 0;

		for(int j = 0; (n > 1) ? j < n - 1 : j < n; j++)
		{
			for(int k = 0; k < m; k++)
			{
				if(isValidPoint(n, m, j, k) && map[j][k] == '.')
				{
					ArrayList<Point> result = DFS(n, m, map, lakes, new Point(j, k));

					if(result != null)
					{											
						int tempSize = result.size();
						totalLakes++;

						if (hs.containsKey(tempSize))
						{
							hs.get(tempSize).add(result);
						}
						else
						{
							ArrayList<ArrayList<Point>> aal = new ArrayList<ArrayList<Point>>();
							aal.add(result);
							hs.put(tempSize, aal);
						}		
					}
				}
			}
		}		

		int numOfCells = 0;

		while(totalLakes > lakes)
		{
			int diff = totalLakes - lakes;

			for(int l = 0; l < diff; l++)
			{
				if(totalLakes == lakes)
				{
					break;
				}

				int tempValue = (int)hs.keySet().toArray()[l];

				for(int q = 0; q < hs.get(tempValue).size(); q++)
				{
					numOfCells = numOfCells + tempValue;
					totalLakes--;
					ArrayList<Point> al = hs.get(tempValue).get(q);

					for(int z = 0; z < al.size(); z++)
					{
						Point pp = al.get(z);
						backupMap[pp.x][pp.y] = '*';
					}

					if(totalLakes == lakes)
					{
						break;
					}
				}
			}
		}		

		System.out.println(numOfCells);

		for(int j = 0; j < n; j++)
		{
			for(int k = 0; k < m; k++)
			{
				System.out.print(backupMap[j][k]);
			}

			System.out.println();
		}
	}

	private static boolean isValidPoint(int n, int m, int j, int k)
	{
		return (j >= 0 && j < n) && (k >= 0 && k < m);
	}

	private static ArrayList<Point> DFS(int n, int m, char[][] map, int lakes, Point p)
	{
		Stack<Point> stack = new Stack<Point>();
		stack.add(p);				
		int[] X = {-1, 0, 1, 0};
		int[] Y = {0, 1, 0, -1};

		ArrayList<Point> result = new ArrayList<Point>();
		result.add(p);
		map[p.x][p.y] = '*';		
		boolean connectedToOcean = false;

		if(isConnectedToOcean(p.x, p.y, n, m))
		{
			connectedToOcean = true;
		}

		while(!stack.isEmpty())
		{
			Point current = stack.pop();

			for(int i = 0; i < 4; i++)
			{
				int xx = current.x + X[i];
				int yy = current.y + Y[i];

				if(isValidPoint(n, m, xx, yy) && map[xx][yy] == '.')
				{
					if(isConnectedToOcean(xx, yy, n, m))
					{
						connectedToOcean = true;
					}

					Point temp = new Point(xx, yy);
					stack.add(temp);
					map[xx][yy] = '*';
					result.add(temp);
				}
			}
		}

		if(connectedToOcean)
		{
			return null;
		}

		return result;
	}

	private static boolean isConnectedToOcean(int xx, int yy, int n, int m)
	{
		return (xx == 0 || xx == n - 1 || yy == 0 || yy == m - 1);
	}

	private static class Point
	{
		int x;
		int y;

		Point(int x, int y)
		{
			this.x = x;
			this.y = y;
		}
	}

}

