public class lakes {

    static boolean[][] visited;
    static Stack<Point> stack;
    static ArrayList<ArrayList<Point>> lakes;
    static int n, m;
    static char[][] map;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String line = br.readLine();
        String[] l = line.split("\\s+");
        n = Integer.parseInt(l[0]);
        m = Integer.parseInt(l[1]);
        int k = Integer.parseInt(l[2]);
        map = new char[n][m];
        visited = new boolean[n][m];
        stack = new Stack<Point>();
        lakes = new ArrayList<ArrayList<Point>>();

        for (int i = 0; i < n; i++) {
            line = br.readLine();
            map[i] = line.toCharArray();
        }
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                if (map[i][j] == '.' && !visited[i][j]) {
                    stack.push(new Point(i, j));
                    DFS();
                }
            }

        Collections.sort(lakes, new Comparator<ArrayList>(){
            @Override
            public int compare(ArrayList a1, ArrayList a2) {
                return a1.size() - a2.size();
            }
        });
        int count = 0;
        for(int i = 0; i < lakes.size() - k; i++) {
            ArrayList<Point> c = lakes.get(i);
            for(int j = 0; j < c.size(); j++) {
                map[c.get(j).x][c.get(j).y] = '*';
                count ++;
            }

        }

        System.out.println(count);
        for(int i = 0; i < n; i++)
            System.out.println(map[i]);
    }

    public static void DFS() {
        ArrayList<Point> newLake = new ArrayList<Point>();
        boolean take = true;
        while (!stack.isEmpty()) {
            Point crnt = stack.pop();
            if(visited[crnt.x][crnt.y]) continue;
            if(crnt.x == 0 || crnt.y == 0 || crnt.x == n - 1 || crnt.y == m - 1) take = false;
            newLake.add(crnt);
            visited[crnt.x][crnt.y] = true;
            if (crnt.x > 0 && map[crnt.x - 1][crnt.y] == '.' && !visited[crnt.x - 1][crnt.y])
                stack.push(new Point(crnt.x - 1, crnt.y));
            if (crnt.x < n - 1 && map[crnt.x + 1][crnt.y] == '.' && !visited[crnt.x + 1][crnt.y])
                stack.push(new Point(crnt.x + 1, crnt.y));
            if (crnt.y > 0 && map[crnt.x][crnt.y - 1] == '.' && !visited[crnt.x][crnt.y - 1])
                stack.push(new Point(crnt.x, crnt.y - 1));
            if (crnt.y < m - 1 && map[crnt.x][crnt.y + 1] == '.' && !visited[crnt.x][crnt.y + 1])
                stack.push(new Point(crnt.x, crnt.y + 1));
        }
        if(take)
            lakes.add(newLake);
    }

}

