        if(vis[i][j]) return 0;
        vis[i][j] = true;
        return find(i+1, j)+find(i, j+1)+find(i-1, j)+find(i, j-1)+1;
    }
    public static void fill(int i, int j){
        if(i<0 || i >=n || j<0 || j>=m) return;
        if(grid[i][j] == '*') return;
        if(vis[i][j]) return;
        vis[i][j] = true;
        grid[i][j] = '*';
        fill(i+1, j);
        fill(i-1, j);
        fill(i, j+1);
        fill(i, j-1);
    }

    static class lack implements Comparable<lack>{
        int size , i,j;
        public lack(int size, int i, int j){
            this.size = size;
            this.i = i;
            this.j = j;
        }
        @Override
        public int compareTo(lack t) {
            if(this.size > t.size) return 1;
            else if(this.size < t.size) return -1;
            else return 0;
        }

    }   
}

import java.io.*;
