public class main {
    public static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    public static PrintWriter pw = new PrintWriter(System.out);
    public static String line;
    public static StringTokenizer st;
    public static ArrayList<ArrayList<Integer>> adjList;
    public static int[] dx = {-1, 0, 1, 0, -1, 1, 1, -1};
    public static int[] dy = {0, 1, 0, -1, 1, 1, -1, -1};

    public static int R, C;
    public static char[][] grid;
    public static boolean[][] vis;
    public static boolean bad;

    public static int dfs(int i, int j){
        vis[i][j] = true;
        int total = 0;
        for(int k = 0; k < 4; k++){
            int nx = dx[k] + i;
            int ny = dy[k] + j;
            if(nx < 0 || nx >= R || ny < 0 || ny >= C){
                bad = true;
                continue;
            }
            if(grid[nx][ny] == '*' || vis[nx][ny]) continue;
            int n = dfs(nx, ny);
            if(n == -1) return -1;
            total += n;
        }
        return total + 1;
    }

    public static void fill(int i, int j){
        grid[i][j] = '*';
        for(int k = 0; k < 4; k++){
            int nx = dx[k] + i;
            int ny = dy[k] + j;
            if(nx < 0 || nx >= R || ny < 0 || ny >= C) continue;
            if(grid[nx][ny] == '*') continue;
            fill(nx, ny);
        }
    }


    public static void main(String[] args) throws IOException{
        st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        C = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());

        vis = new boolean[R][C];
        grid = new char[R][C];

        for(int i = 0; i < R; i++){
            line = br.readLine();
            for(int j = 0; j < C; j++){
                grid[i][j] = line.charAt(j);
            }
        }

        PriorityQueue<State> PQ = new PriorityQueue<State>();
        int lakes = 0;
        for(int i = 0; i < R; i++){
            for(int j = 0; j < C; j++){
                if(grid[i][j] == '.' && !vis[i][j]){
                    bad = false;
                    int n = dfs(i, j);
                    if(!bad){
                        PQ.add(new State(i, j, n));
                        lakes++;
                    }
                }
            }
        }
        int cnt = 0;
        while(lakes > t){
            State s = PQ.poll();
            fill(s.x, s.y);
            cnt += s.n;
            lakes--;
        }

        pw.print(cnt + "\n");
        for(int i = 0; i < R; i++){
            for(int j = 0; j < C; j++){
                pw.print(grid[i][j]);
            }
            pw.print("\n");
        }

        pw.close();
        br.close();
    }
}

class State implements Comparable<State>{
    public int x, y, n;

    State(int _x, int _y, int _n){
        x = _x;
        y = _y;
        n = _n;
    }

    public int compareTo(State s){
        if(n != s.n) return n - s.n;
        if(x != s.x) return x - s.x;
        return y - s.y;
    }
}

