  static int getLakeSize(Point from) {
    Boolean touchedOcean = false;
    if (from.x == 1 || from.x == n || from.y == 1 || from.y == m)
      touchedOcean = true;
    visited[from.x][from.y] = true;
    int result = 1;
    Queue<Point> q = new LinkedList<Point>();
    q.add(from);
    int x, y;
    Point u;
    while (!q.isEmpty()) {
      u = q.remove();
      for (int i = 0; i < 4; i++) {
        x = u.x + dx[i];
        y = u.y + dy[i];
        if ((x == 1 || x == n || y == 1 || y == m) && (x >= 0 && x <= n && y >= 0 && y <= m) && map[x][y] == '.')
          touchedOcean = true;
        if (x >= 0 && x <= n && y >= 0 && y <= m) {
          if (visited[x][y] == false && map[x][y] == '.' ) {
            visited[x][y] = true;
            result++;
            q.add(new Point(x, y));
          }
        }
      }
    }
    if (!touchedOcean)
      return result;
    else
      return 0;
  }

  static int lakeToLand(Point from) {
    map[from.x][from.y] = '*';
    int result = 1;
    Queue<Point> q = new LinkedList<Point>();
    q.add(from);
    int x, y;
