		LinkedList<Lake> lakes = new LinkedList<Lake>();
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (!visited[i][j] && map[i][j] == '.') {
					flag = true;
					LinkedList<Point> visitedLocs = new LinkedList<Point>();
					dfs(i, j, visitedLocs);
					if (flag) {
						Lake lake = new Lake(i, j, visitedLocs.size(),
								visitedLocs);
						lakes.add(lake);
					}
				}
			}
		}
		Collections.sort(lakes);
		ans = 0;
		while (lakes.size() > k) {
			Lake curr = lakes.removeFirst();
			ans += curr.locs.size();
			for (Point p : curr.locs)
				map[p.x][p.y] = '*';
		}
		StringBuffer sb = new StringBuffer();
		sb.append(ans + "\n");
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				sb.append(map[i][j]);
			}
			sb.append("\n");
		}
		System.out.print(sb);
	}

	static int nI[] = new int[] { 0, 0, -1, 1 };
	static int nJ[] = new int[] { -1, 1, 0, 0 };
	static boolean flag;

	private static void dfs(int i, int j, LinkedList<Point> visitedLocs) {
		if (i == 0 || i == n - 1 || j == 0 || j == m - 1) {
			flag = false;
		}
		visitedLocs.add(new Point(i, j));
		visited[i][j] = true;
		for (int k = 0; k < 4; k++) {
			int ni = i + nI[k];
			int nj = j + nJ[k];
			if (inBounds(ni, nj) && !visited[ni][nj] && map[ni][nj] == '.') {
				dfs(ni, nj, visitedLocs);
			}
		}
	}

	private static boolean inBounds(int i, int j) {
		return i >= 0 && i <= n - 1 && j >= 0 && j <= m - 1;
	}
}

