                }
            }
        }
        for (int i = 0; i < n; ++i) {
            if (a[i][0] == 1)
                change(i, 0);
            if (a[i][m - 1] == 1)
                change(i, m - 1);
        }
        for (int j = 0; j < m; ++j) {
            if (a[0][j] == 1)
                change(0, j);
            if (a[n - 1][j] == 1)
                change(n - 1, j);
        }
        int tmp = 1;
        Point p[] = new Point[n*m];
        int ind = 0;
        for (int i = 1; i + 1 < n; ++i) {
            for (int j = 1; j + 1 < m; ++j) {
                if (a[i][j] == 1) {
                    tmp++;
                    sum = 0;
                    cnt(i, j, tmp);
                    p[ind++] = new Point(tmp, sum);
                }
            }
        }
        Arrays.sort(p, 0, ind);
        sum = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
