            for (int j = 0; j < m; ++j)
                out.print(c[i][j]);
            out.println();
        }
    }
    void change(int i, int j) {
        a[i][j] = 0;
        for (int k = 0; k < 4; ++k){
            int fir = i + x[k];
            int sec = j + y[k];
            if (fir >= 0 && fir < n && sec >= 0 && sec < m && a[fir][sec] == 1)
                change(fir, sec);
        }
    }
    void cnt(int i, int j, int v) {
        a[i][j] = v;
        sum++;
        for (int k = 0; k < 4; ++k) {
            int fir = i + x[k];
            int sec = j + y[k];
            if (a[fir][sec] == 1)
                cnt(fir, sec, v);
        }
    }
    class Point implements Comparable<Point> {
