public class CF375D {
	private static char[][] map;

	private static int flood(int ii, int jj) {
		if (map[ii][jj] == '~') return -1000000;
		else if (map[ii][jj] != '.') return 0;
		else {
			map[ii][jj] = ',';
			return 1 + flood(ii-1, jj) + flood(ii+1, jj) + flood(ii, jj-1) + flood(ii, jj+1);
		}
	}

	public static void main(String[] args) throws Exception {
		Scanner scanner = new Scanner(System.in);
		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));

		String[] input1 = reader.readLine().split(" ");
		int n = Integer.parseInt(input1[0]);
		int m = Integer.parseInt(input1[1]);
		int k = Integer.parseInt(input1[2]);

		map = new char[n+5][m+5];
		for (int ii = 0; ii <= n+1; ii++) map[ii][0] = map[ii][m+1] = '~';
		for (int jj = 0; jj <= m+1; jj++) map[0][jj] = map[n+1][jj] = '~';
		for (int ii = 1; ii <= n; ii++) {
			String input2 = reader.readLine();
			for (int jj = 1; jj <= m; jj++) {
				map[ii][jj] = input2.charAt(jj-1);
			}
		}

		int countLake = 0;
		int[] numfloods = new int[2500];
		int[] nn = new int[2500];
		int[] mm = new int[2500];
		for (int ii = 1; ii <= n; ii++) {
			for (int jj = 1; jj <= m; jj++) {
				if (map[ii][jj] == '.') {
					int numflood = flood(ii, jj);
					if (numflood > 0) {
						numfloods[countLake] = numflood;
						nn[countLake] = ii;
						mm[countLake] = jj;
						countLake++;
					}
				}
			}
		}

		for (int ii = 1; ii < countLake; ii++) {
			int x = numfloods[ii];
			int y = nn[ii];
			int z = mm[ii];
			int jj = ii-1;
			while (jj >= 0 && numfloods[jj] > x) {
				numfloods[jj+1] = numfloods[jj];
				nn[jj+1] = nn[jj];
				mm[jj+1] = mm[jj];
				jj--;
			}
			numfloods[jj+1] = x;
			nn[jj+1] = y;
			mm[jj+1] = z;
		}


		for (int ii = 1; ii <= n; ii++) {
			for (int jj = 1; jj <= m; jj++) {
				if (map[ii][jj] == ',') map[ii][jj] = '.';
			}
		}

		int ans = 0;
		int countConvert = countLake - k;
		for (int ii = 0; ii < countConvert; ii++) {
			ans += numfloods[ii];
			flood(nn[ii], mm[ii]);
		}

		writer.write(ans + "\n");

		for (int ii = 1; ii <= n; ii++) {
			for (int jj = 1; jj <= m; jj++) {
				if (map[ii][jj] == ',') map[ii][jj] = '*';
				writer.write(map[ii][jj]);
			}
			writer.write("\n");
		}

		writer.flush();
	}
}

import java.util.*;

public class D {
	static ArrayList<StringBuilder> map = new ArrayList<>();
	static ArrayList<Pair> water = new ArrayList<>();
	static HashSet<Pair> visited = new HashSet<>();
	static ArrayList<HashSet<Pair>> lakes = new ArrayList<>();
	static int n, m, k;
	static boolean notLake = false;

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		n = in.nextInt();
		m = in.nextInt();
		k = in.nextInt();
		in.nextLine();
		for (int i = 0; i < n; i++)
			map.add(new StringBuilder(in.nextLine()));
		for (int i = 0; i < n; i++)
			for (int j = 0; j < m; j++)
				if (map.get(i).charAt(j) == '.')
					water.add(new Pair(i, j));
		for (Pair w : water) {
			if (visited.contains(w)) continue;
			notLake = false;
			HashSet<Pair> curLake = new HashSet<>();
			dfs(w, curLake);
			if (!notLake) lakes.add(curLake);
		}
		int replace = 0;
		while (k < lakes.size()) {
		int min = Integer.MAX_VALUE;
			int minId = 0;
			for (int i = 0; i < lakes.size(); i++) {
				if (lakes.get(i).size() < min) {
					minId = i;
					min = lakes.get(i).size();
				}
			}
			replace += min;
			Iterator it = lakes.get(minId).iterator();
			while (it.hasNext()) {
				Pair cur = (Pair) it.next();
				map.get(cur.a).setCharAt(cur.b, '*');
			}
			lakes.remove(minId);
		}
		System.out.println(replace);
		for (StringBuilder l : map)
			System.out.println(l.toString());
	}

	private static void dfs(Pair w, HashSet<Pair> curLake) {
		visited.add(w);
		curLake.add(w);
		if (w.a == 0 || w.a == n-1 || w.b == 0 || w.b == m-1)
			notLake = true;
		if (w.a > 0) {
			Pair up = new Pair(w.a-1, w.b);
			if (map.get(w.a-1).charAt(w.b) == '.' && !visited.contains(up))
				dfs(up, curLake);
		}
		if (w.a < n-1) {
			Pair down = new Pair(w.a+1, w.b);
			if (map.get(w.a+1).charAt(w.b) == '.' && !visited.contains(down))
				dfs(down, curLake);
		}
		if (w.b > 0) {
			Pair left = new Pair(w.a, w.b-1);
			if (map.get(w.a).charAt(w.b-1) == '.' && !visited.contains(left))
				dfs(left, curLake);
		}
		if (w.b < m-1) {
			Pair right = new Pair(w.a, w.b+1);
			if (map.get(w.a).charAt(w.b+1) == '.' && !visited.contains(right))
				dfs(right, curLake);
		}
	}

	public static class Pair implements Comparable<Pair> {
		int a, b;

		public Pair(int a, int b) {
			this.a = a;
			this.b = b;
		}

		public int compareTo(Pair o) {
			if (this.a != o.a)
				return Integer.compare(this.a, o.a);
			else
				return Integer.compare(this.b, o.b);
		}

		public boolean equals(Object o) {
			if (o instanceof Pair) {
				Pair p = (Pair) o;
				return p.a == a && p.b == b;
			}
			return false;
		}

		public int hashCode() {
			return new Integer(a).hashCode() * 31 + new Integer(b).hashCode();
		}

		public String toString() {
			return "(" + this.a + "," + this.b + ")";
		}
	}
}

