		visited=new boolean [n][m];
		for (int i=0;i<n ; ++i){
			arr[i]=bf.readLine().toCharArray();
		}

		List<Lake> list = new ArrayList<>();
		for (int i =1;  i <n-1 ; ++i){
			for (int j= 1 ; j<m-1 ; ++j){
				if (!visited[i][j]){
					flag=true;
					cnt=0;
					cntLakes(i, j);
					if (flag){
						list.add(new Lake(i, j, cnt));
					}
				}
			}
		}
		Collections.sort(list);
		int numOfLakes =list.size() , in=0 , ans=0;
		while (k!=numOfLakes){
			Lake l=list.get(in);
			mark(l.i, l.j);
			ans+=l.cn;
			--numOfLakes;
			++in;
