	static char arr[][];
	static int cnt;
	static boolean visited[][];
	static boolean flag;
	public static void cntLakes ( int r , int c){
		if (!valid(r, c)){
			flag=false;
			return;
		}
		if (visited[r][c]||arr[r][c]=='*'){
			return;
		}
		++cnt;
		visited[r][c]=true;
		cntLakes(r+1, c);
		cntLakes(r-1, c);
		cntLakes(r, c+1);
		cntLakes(r, c-1);

	}

	static boolean valid (int r ,int c){
		if ((r==0 || r==arr.length-1 || c==0 || c==arr[0].length-1 )&& arr[r][c]=='.'){
			return false;
		}
		return true;
	}

	static void mark (int r , int c){

		if (arr[r][c]=='*')
			return;
		arr[r][c]='*';
		mark(r+1, c);
		mark(r-1, c);
		mark(r, c+1);
		mark(r, c-1);
	}

	static class Lake implements Comparable<Lake>{
		int i;
		int j;
		int cn;
		public Lake (int i , int j , int cn){
			this.j=j;
			this.i=i;
			this.cn=cn;
		}
		@Override
		public int compareTo(Lake o) {
			return Integer.compare(cn, o.cn);
		}
	}

}

