    static int[][] P = new int[51][51];
    static int[][] set = new int[51][51];

    static boolean in(int x, int y){
        return x > 0 && x <51 && y>0 && y<51;
    }

    static void fill(int x, int y, int flag){
        if(!in(x,y)) return;
        if(mp[x][y] == '*') return;
        if(!vis[x][y]){
            vis[x][y] = true;
            set[x][y] = flag;
            fill(x,y+1,flag);
            fill(x,y-1,flag);
            fill(x+1,y,flag);
            fill(x-1,y,flag);
        }
    }
    public static void solve()
    {
        n = in.nextInt();
        m = in.nextInt();
        k = in.nextInt();
        for(int i=1; i<=n; i++){
            char[] s = in.next().toCharArray();
            for(int j=1; j<=m; j++){
                mp[i][j] = s[j-1];
            }
        }



        int sptr = 0;
        for(int i=1; i<=n; i++){
            for(int j=1; j<=m; j++){
                if(mp[i][j] == '.' && !vis[i][j]){

                    fill(i,j, ++sptr);
                }
            }
        }


        HashSet<Pair>[] ts = new HashSet[sptr+1];

        for(int i=1; i<=sptr; i++) ts[i] = new HashSet<>();
        for(int i=1; i<=n; i++){
            for(int j=1; j<=m; j++){
                if(mp[i][j] == '.')
                    ts[set[i][j]].add(new Pair(i,j));
            }
        }

        HashSet<Integer> no = new HashSet<Integer>();
        for(int i=1; i<=n; i++)
            for(int j=1; j<=m; j++)
                if(mp[i][j] == '.'  && (i==1||i==n||j==1||j==m))
                    no.add(set[i][j]);


        int u = sptr-no.size();

        int ans = 0;
        while(u > k){
            int min = 500000, mind = -1;
            for(int i=1; i<=sptr; i++) {
                if(no.contains(i)) continue;
                if(!ts[i].isEmpty() && ts[i].size() < min){
                    min = ts[i].size();
                    mind = i;
                }
            }
            for(Pair p : ts[mind]){
                mp[p.f][p.s] = '*';
            }

            ans += ts[mind].size();
            ts[mind].clear();
            u--;

        }

        out.println(ans);
        for(int i=1; i<=n; i++){
            for(int j=1; j<=m; j++){
                out.print(mp[i][j]);
            }
            out.println("");
        }

    }

