        fillLakes(final_lakes, sizes, k);
        System.out.println(sum);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                System.out.print(final_lakes[i][j]);
            }
            System.out.println();
        }
    }

    private static void fillLakes(char[][] lakes, ArrayList<int[]> sizes, int k) {
        if(sizes == null)
            return;
        for (int i = 0; i < sizes.size() - k; i++) {
            int x = sizes.get(i)[1];
            int y = sizes.get(i)[2];
            lakes[x][y] = '*';
            dfs(lakes, sizes.get(i)[1], sizes.get(i)[2]);
        }
    }

    private static void dfs(char[][] lakes, int x, int y) {
        lakes[x][y] = '*';
        int[] dx = {0,0,1,-1};
        int[] dy = {1,-1,0,0};
        for (int i = 0; i < 4; i++) {
            if(x + dx[i] >= 0 && x + dx[i] < lakes.length && y + dy[i] >= 0 && y + dy[i] < lakes[0].length) {
                if(lakes[x+dx[i]][y+dy[i]] == '.') {
                    lakes[x + dx[i]][y + dy[i]] = '*';
                    dfs(lakes, x + dx[i], y + dy[i]);
                }
            }
        }
    }

    private static void dfscount(char[][] lakes, int x, int y, int[] count) {
        lakes[x][y] = '*';
        int[] dx = {0,0,1,-1};
        int[] dy = {1,-1,0,0};
        for (int i = 0; i < 4; i++) {
            if(x + dx[i] >= 0 && x + dx[i] < lakes.length && y + dy[i] >= 0 && y + dy[i] < lakes[0].length) {
                if(lakes[x+dx[i]][y+dy[i]] == '.') {
                    lakes[x + dx[i]][y + dy[i]] = '*';
                    count[0]++;
                    dfscount(lakes, x + dx[i], y + dy[i], count);
                }
            }
        }
    }
    private static int findSum(ArrayList<int[]> sizes, int k) {
        Collections.sort(sizes, new Comparator<int[]>() {
            @Override
            public int compare(int[] o1, int[] o2) {
                return o1[0] - o2[0];
            }
        });



        int needFill = sizes.size()-k;
        int sum = 0;
        for (int i = 0; i < needFill; i++) {
            sum += sizes.get(i)[0];
        }
        return sum;
    }

    private static ArrayList<int[]> findSizes(char[][] lakes) {


        for(int i = 0; i < lakes.length; i++){
            if(lakes[i][0] == '.')
                dfs(lakes, i, 0);
            if(lakes[i][lakes[0].length-1] == '.')
                dfs(lakes,i,lakes[0].length-1);
        }

        for(int i = 0; i < lakes[0].length; i++){
            if(lakes[0][i] == '.')
                dfs(lakes,0,i);
            if(lakes[lakes.length-1][i] == '.')
                dfs(lakes,lakes.length-1,i);
        }



        ArrayList<int[]> res = new ArrayList<>();
        for (int i = 0; i < lakes.length; i++) {
            for (int j = 0; j < lakes[0].length; j++) {
                if(lakes[i][j] == '.'){
                   int[] xy = {i,j};
                   int[] count = {1};
                   dfscount(lakes,i,j,count);
                   res.add(new int[]{count[0],xy[0],xy[1]});
                }
            }
        }
        return res;
    }

}

