      else return 5;
    }
    if(y == by){
      if(bx > x) return 3;
      else return 7;
    }

    long y1 = Math.abs(y - by), x1 = Math.abs(x - bx);

    if(y1 == x1){
      if(bx > x && by > y) return 2;
      if(bx > x && by < y) return 4;
      if(bx < x && by < y) return 6;
      else return 8;
    }

    return 0;
  }
  static class Node implements Comparable<Node>{
    int x, y;
    char c;
    public Node(char cc, int xx, int yy){
      c = cc; x = xx; y = yy;
    }

    public int compareTo(Node n){
      int m1 = Math.abs(kx - n.x), m2 = Math.abs(ky - n.y);

      int p1 = Math.abs(kx - x), p2 = Math.abs(ky - y);

      if(m1 == p1) return p2 - m2;
      else return p1 - m1;
    }

    public String toString(){
      return c+" "+x+" "+y;
    }

  }


  static int gcd(int p, int q) {
    if (q == 0) return p;
    else return gcd(q, p % q);
  }

  static class InputReader {
    public BufferedReader reader;
    public StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
      reader = new BufferedReader(new InputStreamReader(stream));
      tokenizer = null;
    }

    public String next() {

      try {
        while (tokenizer == null || !tokenizer.hasMoreTokens())
          tokenizer = new StringTokenizer(reader.readLine());
      } catch (IOException e) {
        return null;
      }

      return tokenizer.nextToken();
    }

    public String nextLine() {
      String line = null;
      try {
        tokenizer = null;
        line =  reader.readLine();
      } catch (IOException e) {
        throw new RuntimeException(e);
      }
      return line;
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public long nextLong() {
      return Long.parseLong(next());
    }
    public boolean hasNext(){
      try {
        while (tokenizer == null || !tokenizer.hasMoreTokens())
          tokenizer = new StringTokenizer(reader.readLine());
      } 
      catch (Exception e) {
        return false;
      }

    return true; 

    }
  }
}

