	{
		if(getX(s1) == getX(s2))
			return true;
		return false;
	}
	public static boolean isinLine(String s1, String s2)
	{
		double y1 = getY(s1);
		double y2 = getY(s2);
		double x1 = getX(s1);
		double x2 = getX(s2);
		if((y1 - y2) != 0 && (x1 - x2)/(y1 - y2) == 1 | (x1 - x2)/(y1 - y2) == -1)
			return true;
		return false;
	}
	public static boolean checker(String s1, String s2)
	{
		if(s1 == null)
		{
			return false;}
		if(s1.charAt(0) == 'Q')
				return isinLine(s2,s1) || getX(s2) == getX(s1) || getY(s2) == getY(s1);
		else
			if(s1.charAt(0) == 'R')
				return getX(s2) == getX(s1) || getY(s2) == getY(s1);
			else
				if(s1.charAt(0) == 'B')
					return isinLine(s2,s1);
				else
					return false;
	}
	public static int getX(String s1)
	{
		String[] y = s1.split(" ");
		if(y.length > 2)
			return Integer.parseInt(y[1]);
		else
			return Integer.parseInt(y[0]);
	}
	public static int getY(String s1)
	{
		String[] y = s1.split(" ");
		if(y.length > 2)
			return Integer.parseInt(y[2]);
		else
			return Integer.parseInt(y[1]);

	}
	public static boolean toping(String s1, String s2)
	{
		return getX(s1) < getX(s2); 
