    static class TaskD {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int x = in.nextInt();
            int y = in.nextInt();


            boolean schachRechts = false;
            int abstandRechts = Integer.MAX_VALUE;
            boolean schachLinks = false;
            int abstandLinks = Integer.MAX_VALUE;
            boolean schachOben = false;
            int abstandOben = Integer.MAX_VALUE;
            boolean schachUnten = false;
            int abstandUnten = Integer.MAX_VALUE;

            boolean schachRO = false;
            int abstandRO = Integer.MAX_VALUE;
            boolean schachRU = false;
            int abstandRU = Integer.MAX_VALUE;
            boolean schachLO = false;
            int abstandLO = Integer.MAX_VALUE;
            boolean schachLU = false;
            int abstandLU = Integer.MAX_VALUE;

            for (int i = 0; i < n; i++) {
                String s = in.next();
                char type = s.charAt(0);
                int xi = in.nextInt();
                int yi = in.nextInt();

                if (xi == x) {
                    if (yi > y) { 
                        if (yi - y < abstandRechts) {
                            abstandRechts = yi - y;
                            schachRechts = type == 'B' ? false : true;
                        }
                    } else { 
                        if (y - yi < abstandLinks) {
                            abstandLinks = y - yi;
                            schachLinks = type == 'B' ? false : true;
                        }
                    }
                }

                if (yi == y) {
                    if (xi > x) { 
                        if (xi - x < abstandUnten) {
                            abstandUnten = xi - x;
                            schachUnten = type == 'B' ? false : true;
                        }
                    } else { 
                        if (x - xi < abstandOben) {
                            abstandOben = x - xi;
                            schachOben = type == 'B' ? false : true;
                        }
                    }
                }

                int d1 = (xi - x);
                int d2 = (yi - y);

                if (Math.abs(d1) == Math.abs(d2)) {
                    if (d1 > 0) {
                        if (d2 > 0) { 
                            if (d1 < abstandRU) {
                                abstandRU = d1;
                                schachRU = type == 'R' ? false : true;
                            }
                        } else { 
                            if (d1 < abstandRO) {
                                abstandRO = d1;
                                schachRO = type == 'R' ? false : true;
                            }
                        }
                    } else {
                        if (d2 > 0) { 
                            if (d2 < abstandLU) {
                                abstandLU = d2;
                                schachLU = type == 'R' ? false : true;
                            }
                        } else { 
                            if (-d2 < abstandLO) {
                                abstandLO = -d2;
                                schachLO = type == 'R' ? false : true;
                            }
                        }
                    }
                }
            }

            if (schachLinks || schachRechts || schachOben || schachUnten || schachLO || schachLU || schachRO || schachRU) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

