	public static void main(String[] args) throws java.lang.Exception
	{
		Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));



		int n = in.nextInt();
		in.nextLine();
		int x = in.nextInt();
		int y = in.nextInt();


		int NNd = Integer.MAX_VALUE;
		int NEd = Integer.MAX_VALUE;
		int EEd = Integer.MAX_VALUE;
		int SEd = Integer.MAX_VALUE;
		int SSd = Integer.MAX_VALUE;
		int SWd = Integer.MAX_VALUE;
		int WWd = Integer.MAX_VALUE;
		int NWd = Integer.MAX_VALUE;


		boolean NNb = false;
		boolean NEb = false;
		boolean EEb = false;
		boolean SEb = false;
		boolean SSb = false;
		boolean SWb = false;
		boolean WWb = false;
		boolean NWb = false;

		for(int i = 0; i < n; ++i) {
			in.nextLine();
			String piece = in.next();
			int dx = in.nextInt()-x;
			int dy = in.nextInt()-y;
			int dist = Math.max(Math.abs(dy), Math.abs(dx));
			if(dx == 0) {
				if(dy > 0) {
					if(dist < NNd) {
						NNd = dist;
						NNb = update(piece,false);
					}
				} else {
					if(dist < SSd) {
						SSd = dist;
						SSb = update(piece,false);
					}
				}
			} else if (dy == 0) {
				if(dx > 0) {
					if(dist < EEd) {
						EEd = dist;
						EEb = update(piece,false);
					}
				} else {
					if(dist < WWd) {
						WWd = dist;
						WWb = update(piece,false);
					}
				}
 			}else if(Math.abs(dx)-Math.abs(dy)==0) {
 				if(dx > 0 && dy > 0) {
					if(dist < NEd) {
						NEd = dist;
						NEb = update(piece,true);
					}
 				} else if(dx > 0 && dy < 0){
					if(dist < SEd) {
						SEd = dist;
						SEb = update(piece,true);
					}
 				} else if(dx < 0 && dy < 0) {
					if(dist < SWd) {
						SWd = dist;
						SWb = update(piece,true);
					}
 				} else {
					if(dist < NWd) {
						NWd = dist;
						NWb = update(piece,true);
					}
 				}
			}
		}	

		if(NNb||SSb||EEb||WWb||NEb||NWb||SEb||SWb) {
			System.out.println("YES");
		} else {
			System.out.println("NO");
		}

		in.close();

	}

	static boolean update(String s, boolean diag) {
		if(s.equals("Q")) {
			return true;
		} else if(s.equals("R")) {
			if(diag) {
				return false;
			}
			return true;
		} else {
			if(diag) {
				return true;
			}
			return false;
		}
	}



}

