public class Main{
    public static void main(String[] args) throws FileNotFoundException {
        Scanner scanner =new Scanner(System.in);


        Node []nodes = new Node[8];
        for(int i=0;i<8;i++){
            nodes[i]=new Node('m',Integer.MAX_VALUE);
        }
        int n=  scanner.nextInt();
        int x=scanner.nextInt();
        int y=scanner.nextInt();
        for(int i=1;i<=n;i++){
            String op = scanner.next();
            int x1 = scanner.nextInt();
            int y1 = scanner.nextInt();


            int dir=-1;
            int dis=Integer.MAX_VALUE;
            if(x1==x){
                if(y1<y){
                    dir=0;
                    dis=y-y1;
                }else{
                    dir=4;
                    dis=y1-y;
                }
            }else if(y1==y){
                if(x1<x){
                    dir=6;
                    dis=x-x1;
                }else{
                    dir=2;
                    dis=x1-x;
                }
            }else if(x-x1==y1-y&&x-x1>0){
                dis=x-x1;
                dir=1;
            }else if(x1-x==y-y1&&x1-x>0){
                dir=3;
                dis=x1-x;
            }else if(x-x1==y-y1&&x-x1>0){
                dis=x-x1;
                dir=5;
            }else if(x1-x==y1-y&&x1-x>0){
                dis=x1-x;
                dir=7;
            }

            if(dir!=-1){
                if(nodes[dir].dis>dis){
                    nodes[dir]=new Node(op.charAt(0),dis);
                }
            }
        }
        boolean flag=false;
        if(nodes[0].type=='R'||nodes[0].type=='Q'||
                nodes[2].type=='R'||nodes[2].type=='Q'||
                nodes[4].type=='R'||nodes[4].type=='Q'||
                nodes[6].type=='R'||nodes[6].type=='Q'
        ){
            flag=true;
        }

        if(nodes[1].type=='B'||nodes[1].type=='Q'||
                nodes[3].type=='B'||nodes[3].type=='Q'||
                nodes[5].type=='B'||nodes[5].type=='Q'||
                nodes[7].type=='B'||nodes[7].type=='Q'
        ){
            flag=true;
        }
        if(flag){
            System.out.println("YES");
        }else{
            System.out.println("NO");
        }
    }
}

