import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;




public class Chess
{

    public static void main(String[] args) throws Exception
    {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int num = Integer.parseInt(br.readLine());
        String king = br.readLine();
        int kingSpace = king.indexOf(' ');
        int kingx = Integer.parseInt(king.substring(0, kingSpace));
        int kingy = Integer.parseInt(king.substring(kingSpace + 1));
        State n = new State(Integer.MAX_VALUE, false);
        State s = new State(Integer.MAX_VALUE, false);
        State e = new State(Integer.MAX_VALUE, false);
        State w = new State(Integer.MAX_VALUE, false);
        State ne = new State(Integer.MAX_VALUE, false);
        State nw = new State(Integer.MAX_VALUE, false);
        State se = new State(Integer.MAX_VALUE, false);
        State sw = new State(Integer.MAX_VALUE, false);
        for(int i = 0; i < num; i++){
            StringTokenizer st = new StringTokenizer(br.readLine());
            String type = st.nextToken();
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            if(x == kingx){
                if(y > kingy){
                    if(y - kingy < n.dist){
                        n = new State(y - kingy, !type.equals("B"));
                    }
                } else {
                    if(kingy - y < s.dist){
                        s = new State(kingy - y, !type.equals("B"));
                    }
                }
            } else if(y == kingy){
                if(x > kingx){
                    if(x - kingx < w.dist){
                        w = new State(x - kingx, !type.equals("B"));
                    }
                } else {
                    if(kingx - x < e.dist){
                        e = new State(kingx - x, !type.equals("B"));
                    }
                }
            } else if(x - kingx == y - kingy){
                if(x > kingx){
                    if(x - kingx < nw.dist){
                        nw = new State(x - kingx, !type.equals("R"));
                    }
                } else {
                    if(kingx - x < se.dist){
                        se = new State(kingx - x, !type.equals("R"));
                    }
                }
            } else if(x - kingx == kingy - y){
                if(x > kingx){
                    if(x - kingx < sw.dist){
                        sw = new State(x - kingx, !type.equals("R"));
                    }
                } else {
                    if(kingx - x < ne.dist){
                        ne = new State(kingx - x, !type.equals("R"));
                    }
                }
            }
        }
        if(n.threatening || s.threatening || e.threatening || w.threatening || ne.threatening || nw.threatening || se.threatening || sw.threatening){
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
        br.close();
        System.exit(0);
    }

    static class State {
        int dist;
        boolean threatening;

        protected State(int dist, boolean threatening)
        {
            super();
            this.dist = dist;
            this.threatening = threatening;
        }

    }

}

