public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        BladeReader in = new BladeReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, BladeReader in, PrintWriter out) {
            long numberOfBlack = in.nextLong();
            Point king = new Point('K', in.nextLong(), in.nextLong());
            Point north = null, south = null, east = null, west = null;
            Point northEast = null, southEast = null, southWest = null, northWest = null;
            for (long i = 0; i < numberOfBlack; i++) {
                char currType = in.next().charAt(0);
                long currX = in.nextLong();
                long currY = in.nextLong();
                if (king.slope(currX, currY) == 1 || king.slope(currX, currY) == -1 || currX == king.x || currY == king.y) {
                    Point curr = new Point(currType, currX, currY);
                    int dir = determineDirection(curr, king);
                    switch (dir) {
                        case 1:
                            if (north == null) {
                                north = curr;
                            } else if (curr.distance(king) < north.distance(king)) {
                                north = curr;
                            }
                            break;
                        case 2:
                            if (northEast == null) {
                                northEast = curr;
                            } else if (curr.distance(king) < northEast.distance(king)) {
                                northEast = curr;
                            }
                            break;
                        case 3:
                            if (east == null) {
                                east = curr;
                            } else if (curr.distance(king) < east.distance(king)) {
                                east = curr;
                            }
                            break;
                        case 4:
                            if (southEast == null) {
                                southEast = curr;
                            } else if (curr.distance(king) < southEast.distance(king)) {
                                southEast = curr;
                            }
                            break;
                        case 5:
                            if (south == null) {
                                south = curr;
                            } else if (curr.distance(king) < south.distance(king)) {
                                south = curr;
                            }
                            break;
                        case 6:
                            if (southWest == null) {
                                southWest = curr;
                            } else if (curr.distance(king) < southWest.distance(king)) {
                                southWest = curr;
                            }
                            break;
                        case 7:
                            if (west == null) {
                                west = curr;
                            } else if (curr.distance(king) < west.distance(king)) {
                                west = curr;
                            }
                            break;
                        case 8:
                            if (northWest == null) {
                                northWest = curr;
                            } else if (curr.distance(king) < northWest.distance(king)) {

                                northWest = curr;
                            }
                            break;
                        default:
                            throw new RuntimeException();
                    }
                }
            }

            boolean isCheckMate = false;
            if (north != null && (north.type == 'Q' || north.type == 'R')) {
                isCheckMate = true;
            } else if (northEast != null && (northEast.type == 'Q' || northEast.type == 'B')) {
                isCheckMate = true;
            } else if (east != null && (east.type == 'Q' || east.type == 'R')) {
                isCheckMate = true;
            } else if (southEast != null && (southEast.type == 'Q' || southEast.type == 'B')) {
                isCheckMate = true;
            } else if (south != null && (south.type == 'Q' || south.type == 'R')) {
                isCheckMate = true;
            } else if (southWest != null && (southWest.type == 'Q' || southWest.type == 'B')) {
                isCheckMate = true;
            } else if (west != null && (west.type == 'Q' || west.type == 'R')) {
                isCheckMate = true;
            } else if (northWest != null && (northWest.type == 'Q' || northWest.type == 'B')) {
                isCheckMate = true;
            }

            out.println(isCheckMate ? "YES" : "NO");
        }

        private int determineDirection(Point curr, Point king) {
            if (curr.y == king.y) {             
                if (king.x > curr.x) {
                    return 7;
                } else {
                    return 3;
                }
            } else if (curr.x == king.x) {      
                if (king.y > curr.y) {
                    return 5;
                } else {
                    return 1;
                }
            } else if (king.slope(curr) == -1) {
                if (king.x > curr.x && king.y < curr.y) {
                    return 4;
                } else if (king.x < curr.x && king.y > curr.y) {
                    return 8;
                } else {




                    throw new RuntimeException();
                }
            } else if (king.slope(curr) == 1) {
                if (king.x > curr.x && king.y > curr.y) {
                    return 6;
                } else if (king.x < curr.x && king.y < curr.y) {
                    return 2;
                } else {
                    throw new RuntimeException();
                }
            }
            throw new RuntimeException();
        }

    }

    static class BladeReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public BladeReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }

    static class Point {
        char type;
        long x;
        long y;

        Point(char type, long x, long y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        public int slope(Point other) {
            if ((x - other.x) == (y - other.y)) {
                return 1;
            } else if ((x - other.x) == -(y - other.y)) {
                return -1;
            } else {
                return -2;
            }
        }

        public int slope(long x2, long y2) {
            if ((x - x2) == (y - y2)) {
                return 1;
            } else if ((x - x2) == -(y - y2)) {
                return -1;
            } else {
                return -2;
            }
        }


        public String toString() {
            return String.format("%s %d %d", type, x, y);
        }

        public double distance(Point other) {
            return Math.sqrt((other.x - this.x) * (other.x - this.x)) + ((other.y - this.y) * (other.y - this.y));
        }

    }
}

import java.io.*;
import java.util.*;


public class smell {
	public static void main(String[] args) throws Exception {
		BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter out = new PrintWriter(System.out);
		Scanner s = new Scanner(System.in);

		int n = Integer.parseInt(f.readLine());
		String[] split = f.readLine().split("\\s+");
		int x = Integer.parseInt(split[0]), y = Integer.parseInt(split[1]);
		Piece[] a = new Piece[n];
		Piece[] closest = new Piece[8];
		double[] closestDists = new double[8];
		Arrays.fill(closestDists, Double.MAX_VALUE);
		for(int i = 0; i < n; i++) {
			split = f.readLine().split("\\s+");
			char id = split[0].charAt(0); long X = Long.parseLong(split[1]), Y = Long.parseLong(split[2]);
			a[i] = new Piece(id, X, Y);
			if(a[i].x == x) {
				if(a[i].y < y) {
					a[i].which[0] = true; 
					double dist = dist(X ,Y, x, y);
					if(dist < closestDists[0]) {
						closestDists[0] = dist;
						closest[0] = a[i];
					}
				}
				else {
					a[i].which[1] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[1]) {
						closestDists[1] = dist;
						closest[1] = a[i];
					}
				}
			} else if(a[i].y == y) {
				if(a[i].x < x) {
					a[i].which[2] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[2]) {
						closestDists[2] = dist;
						closest[2] = a[i];
					}
				}
				else {
					a[i].which[3] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[3]) {
						closestDists[3] = dist;
						closest[3] = a[i];
					}
				}
			} else if(Math.abs(a[i].x - x) == Math.abs(a[i].y - y)) {
				if(a[i].x < x && a[i].y > y) {
					a[i].which[4] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[4]) {
						closestDists[4] = dist;
						closest[4] = a[i];
					}
				}
				else if(a[i].x > x && a[i].y > y) {
					a[i].which[5] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[5]) {
						closestDists[5] = dist;
						closest[5] = a[i];
					}
				}
				else if(a[i].x < x && a[i].y < y) {
					a[i].which[6] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[6]) {
						closestDists[6] = dist;
						closest[6] = a[i];
					}
				}
				else {
					a[i].which[7] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[7]) {
						closestDists[7] = dist;
						closest[7] = a[i];
					}
				}
			}
		}

		boolean yes = false;
		for(int i = 0; i < 4; i++) {
			if(closest[i] == null) continue;
			if(closest[i].id == 'R' || closest[i].id == 'Q') yes = true;
		}
		for(int i = 4; i < 8; i++) {
			if(closest[i] == null) continue;
			if(closest[i].id == 'Q' || closest[i].id == 'B') yes = true;
		}
		System.out.println(yes ? "YES" : "NO");
	}

	static double dist(long x1, long y1, long x2, long y2) {
		long X = x1-x2;
		long Y = y1-y2;
		return (Math.sqrt(X*X + Y*Y));
	}
}


class Piece {
	char id;
	boolean[] which;


	long x, y;
	Piece(char id, long X, long Y) {
		this.id = id;
		x = X;
		y = Y;
		which = new boolean[8];
	}
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.BufferedWriter;
import java.util.HashMap;
import java.util.InputMismatchException;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.util.Comparator;
import java.io.InputStream;


public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int kx = in.readInt();
            int ky = in.readInt();
            Map<Character, List<Chess>> chess = new HashMap<>();
            for (int i = 0; i < n; i++) {
                char c = in.readCharacter();
                int x = in.readInt();
                int y = in.readInt();
                chess.computeIfAbsent(c, key -> new ArrayList<>()).add(new Chess(c, x, y));
            }

            boolean beat = processB(kx, ky, chess) || processR(kx, ky, chess);
            out.print(beat ? "YES" : "NO");
        }

        private boolean processR(int kx, int ky, Map<Character, List<Chess>> chess) {
            return processLine(kx, ky, chess, true) || processLine(kx, ky, chess, false);
        }

        private boolean processLine(int kx, int ky, Map<Character, List<Chess>> chess, boolean byX) {
            Chess main = new Chess('R', kx, ky);
            Map<Integer, List<Chess>> byLine = new HashMap<>();
            for (List<Chess> l : chess.values()) {
                for (Chess c : l) {
                    byLine.computeIfAbsent(byX ? c.x : c.y, k -> new ArrayList<>()).add(c);
                }
            }
            List<Chess> curChess = byLine.get(byX ? main.x : main.y);
            if (curChess == null) {
                return false;
            }
            curChess.sort(Comparator.<Chess>comparingInt(c -> c.x).thenComparingInt(c -> c.y));
            int sz = curChess.size();
            if ((sz == 1 && isR(curChess.get(0))) ||
                    (isR(curChess.get(0)) && isAfterLine(main, curChess.get(0))) ||
                    (isR(curChess.get(sz - 1)) && isAfterLine(curChess.get(sz - 1), main))) {
                return true;
            }
            for (int i = 0; i < sz - 1; i++) {
                Chess c1 = curChess.get(i);
                Chess c2 = curChess.get(i + 1);
                if (isOnLine(c1, main, c2)) {
                    return isR(c1) || isR(c2);
                }
            }
            return false;
        }

        private boolean isOnLine(Chess a, Chess o, Chess b) {
            return isAfterLine(a, o) && isAfterLine(o, b);
        }

        private boolean isAfterLine(Chess cur, Chess c) {
            if (cur.x == c.x) {
                return cur.y < c.y;
            }
            return cur.x < c.x;
        }

        private boolean processB(int kx, int ky, Map<Character, List<Chess>> chess) {
            return processDiag(kx, ky, chess, true) || processDiag(kx, ky, chess, false);
        }

        private boolean processDiag(int kx, int ky, Map<Character, List<Chess>> chess, boolean by1) {
            Chess main = new Chess('B', kx, ky);
            Map<Integer, List<Chess>> byDiag = new HashMap<>();
            for (List<Chess> l : chess.values()) {
                for (Chess c : l) {
                    byDiag.computeIfAbsent(by1 ? c.diag1() : c.diag2(), k -> new ArrayList<>()).add(c);
                }
            }
            List<Chess> curChess = byDiag.get(by1 ? main.diag1() : main.diag2());
            if (curChess == null) {
                return false;
            }
            curChess.sort(Comparator.comparing(c -> c.x));
            int sz = curChess.size();
            if ((sz == 1 && isB(curChess.get(0))) ||
                    (isB(curChess.get(0)) && isAfterDiag(main, curChess.get(0))) ||
                    (isB(curChess.get(sz - 1)) && isAfterDiag(curChess.get(sz - 1), main))) {
                return true;
            }
            for (int i = 0; i < sz - 1; i++) {
                Chess c1 = curChess.get(i);
                Chess c2 = curChess.get(i + 1);
                if (isBetween(c1, main, c2)) {
                    return isB(c1) || isB(c2);
                }
            }
            return false;
        }

        private boolean isBetween(Chess a, Chess o, Chess b) {
            return isAfterDiag(a, o) && isAfterDiag(o, b);
        }

        private boolean isAfterDiag(Chess cur, Chess c) {
            return cur.x < c.x;
        }

        private boolean isR(Chess c) {
            return c.type == 'R' || c.type == 'Q';
        }

        private boolean isB(Chess c) {
            return c.type == 'B' || c.type == 'Q';
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void close() {
            writer.close();
        }

    }

    static class Chess {
        public char type;
        public int x;
        public int y;

        public Chess(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        public int diag1() {
            return x - y;
        }

        public int diag2() {
            return -x - y;
        }


        public String toString() {
            return "Chess{" +
                    "type=" + type +
                    ", x=" + x +
                    ", y=" + y +
                    '}';
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class D {

    public static void main(String[] args) throws IOException {
        new D().solve();
    }

    StringTokenizer tokenizer = null;
    BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

    String nextToken() throws IOException {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    private static class Pair {
        public long x, y;
        public Pair(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    void solve() throws IOException {
        int n = nextInt();
        long x0 = nextLong();
        long y0 = nextLong();
        List<Pair> f = new ArrayList<>();
        List<Pair> l = new ArrayList<>();
        List<Pair> s = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String token = nextToken();
            long x = nextLong();
            long y = nextLong();
            if ("B".equals(token)) {
                s.add(new Pair(x, y));
            } else if ("R".equals(token)) {
                l.add(new Pair(x, y));
            } else {
                f.add(new Pair(x, y));
            }
        }

        long up = Long.MAX_VALUE - 100;
        long down = Long.MAX_VALUE - 100;
        long left = Long.MAX_VALUE - 100;
        long right = Long.MAX_VALUE - 100;

        long upLeft = Long.MAX_VALUE - 100;
        long upRight = Long.MAX_VALUE - 100;
        long downLeft = Long.MAX_VALUE - 100;
        long downRight = Long.MAX_VALUE - 100;

        for (Pair slon: s) {
            if (slon.x == x0) {
                if (slon.y > y0) {
                    up = Math.min(up, slon.y - y0);
                } else {
                    down = Math.min(down, y0 - slon.y);
                }
            }
            if (slon.y == y0) {
                if (slon.x > x0) {
                    right = Math.min(right, slon.x - x0);
                } else {
                    left = Math.min(left, x0 - slon.x);
                }
            }
        }
        for (Pair lad: l) {
            if (lad.x - lad.y == x0 - y0) {
                if (lad.x > x0) {
                    upRight = Math.min(upRight, lad.x - x0);
                } else {
                    downLeft = Math.min(downLeft, x0 - lad.x);
                }
            }
            if (lad.x + lad.y == x0 + y0) {
                if (lad.x > x0) {
                    downRight = Math.min(downRight, lad.x - x0);
                } else {
                    upLeft = Math.min(upLeft, x0 - lad.x);
                }
            }
        }

        boolean result = false;
        for (Pair slon: s) {
            result = result || (
                    slon.x - slon.y == x0 - y0 && -downLeft < slon.x - x0 && slon.x - x0 < upRight ||
                    slon.x + slon.y == x0 + y0 && -upLeft < slon.x - x0 && slon.x - x0 < downRight
                    );
        }
        for (Pair lad: l) {
            result = result || (
                    lad.x == x0 && -down < lad.y - y0 && lad.y - y0 < up ||
                    lad.y == y0 && -left < lad.x - x0 && lad.x - x0 < right
                    );
        }
        for (Pair ferz: f) {
            result = result || (
                    ferz.x - ferz.y == x0 - y0 && -downLeft < ferz.x - x0 && ferz.x - x0 < upRight ||
                            ferz.x + ferz.y == x0 + y0 && -upLeft < ferz.x - x0 && ferz.x - x0 < downRight ||
                            ferz.x == x0 && -down < ferz.y - y0 && ferz.y - y0 < up ||
                            ferz.y == y0 && -left < ferz.x - x0 && ferz.x - x0 < right
            );
        }
        if (result) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

}

