import java.util.Arrays;
import java.util.Scanner;


public class AntonAndChess {

    public static long diff(long n1, long n2) {
        if(n1 >= 0 && n2 >= 0) { 
            return Math.abs(n1-n2);
        }
        else if(n1 >= 0 && n2 < 0) { 
            return Math.abs(n1-n2);
        }
        else if(n1 < 0 && n2 >= 0) { 
            return Math.abs(n2-n1);
        }
        else { 
            return Math.abs((n2*-1)-(n1*-1));
        }
    }

    public static void resolveDirection(long[] xMax, long[] yMax, char[] dir, long x, long y, long bx, long by, char pi) {
        if(y == by && bx > x) { 
            if(xMax[0] > bx) {
                xMax[0] = bx; dir[0] = pi;
            }
        }
        else if(bx > x && by < y) { 
            long dif = diff(x, bx);
            if(Math.abs(bx-x) == Math.abs(by-y) && dif < xMax[1]) {
                xMax[1] = dif; dir[1] = pi;
            }
        }
        else if(x == bx && y > by) { 
            if(yMax[2] < by) {
                yMax[2] = by; dir[2] = pi;
            }
        }
        else if(x > bx && y > by) { 
            long dif = diff(x, bx);
            if(Math.abs(bx-x) == Math.abs(by-y) && dif < xMax[3]) {
                xMax[3] = dif; dir[3] = pi;
            }
        }
        else if(y == by && bx < x) { 
            if(xMax[4] < bx) {
                xMax[4] = bx; dir[4] = pi;
            }
        }
        else if(bx < x && by > y) { 
            long dif = diff(x, bx);
            if(Math.abs(bx-x) == Math.abs(by-y) && dif < xMax[5]) {
                xMax[5] = dif; dir[5] = pi;
            }
        }
        else if(x == bx && y < by) { 
            if(by < yMax[6]) {
                yMax[6] = by; dir[6] = pi;
            }
        }
        else if(bx > x && by > y) { 
            long dif = diff(x, bx);
            if(Math.abs(bx-x) == Math.abs(by-y) && dif < xMax[7]) {
                xMax[7] = dif; dir[7] = pi;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int bc = Integer.parseInt(sc.nextLine());
        String[] king = sc.nextLine().split(" ");
        long x = Long.parseLong(king[0]), y = Long.parseLong(king[1]);
        long[] xMax = new long[8] , yMax = new long[8];


        xMax[0] = Long.MAX_VALUE; xMax[1] = Long.MAX_VALUE; yMax[2] = -Long.MAX_VALUE;
        xMax[3] = Long.MAX_VALUE; xMax[5] = Long.MAX_VALUE; xMax[7] = Long.MAX_VALUE;
        yMax[6] = Long.MAX_VALUE; xMax[4] = -Long.MAX_VALUE;
        char[] dir = new char[8];
        for(int i = 0; i < bc; i++) {
            String[] in = sc.nextLine().split(" ");
            char pi = in[0].charAt(0);
            long bx = Long.parseLong(in[1]), by = Long.parseLong(in[2]);
            resolveDirection(xMax, yMax, dir, x, y, bx, by, pi);
        }
        boolean hit = false;
        for(int i = 0; i < 8; i++) {
            if(dir[i] == ' ') {
                continue;
            }
            char ch = dir[i];
            if(i % 2 == 0 && (ch == 'Q' || ch == 'R')) {
                hit = true;
                break;
            }
            else if(i % 2 != 0 && (ch == 'Q' || ch == 'B')) {
                hit = true;
                break;
            }
        }
        System.out.println((hit==true)? "YES" : "NO");
    }
}

