        if (xi > x0 && yi == y0)
          if (xi - x0 < d[0]) {
            name[0] = ch;
            d[0] = xi - x0;
          }
        if (xi > x0 && xi - x0 == yi - y0)
          if (xi - x0 < d[1]) {
            name[1] = ch;
            d[1] = xi - x0;
          }
        if (xi == x0 && yi > y0)
          if (yi - y0 < d[2]) {
            name[2] =ch;
            d[2] = yi - y0;
          }
        if (xi < x0 && xi - x0 == y0 - yi)
          if (x0 - xi < d[3]) {
            name[3] = ch;
            d[3] = x0 - xi;
          }
        if (xi < x0 && yi == y0)
          if (x0 - xi < d[4]) {
            name[4] = ch;
            d[4] = x0 - xi;
          }
        if (xi < x0 && xi - x0 == yi - y0)
          if (x0 - xi < d[5]) {
            name[5] = ch;
            d[5] = x0 - xi;
          }
        if (xi == x0 && yi < y0)
          if (y0 - yi < d[6]) {
            name[6] = ch;
            d[6] = y0 - yi;
          }
        if (xi > x0 && xi - x0 == y0 - yi)
          if (xi - x0 < d[7]) {
            name[7] = ch;
            d[7] = xi - x0;
          }        
      }
      boolean okay = true;
      for (int i = 0; i < 8; ++i) {
        if (i % 2 == 0 && (name[i] == 'Q' || name[i] == 'R'))
          okay = false;
        if (i % 2 != 0 && (name[i] == 'B' || name[i] == 'Q'))
          okay = false;
