import java.util.stream.Stream;

public class D_379_div2
{
    private static BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));
    private static StringTokenizer stringTokenizer = null;
    private static PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

    private static String next() throws IOException
    {
        while ((stringTokenizer == null) || (!stringTokenizer.hasMoreTokens()))
        {
            stringTokenizer = new StringTokenizer(bufferedReader.readLine());
        }
        return stringTokenizer.nextToken();
    }

    public static int nextInt() throws IOException
    {
        return Integer.parseInt(next());
    }

    public static double nextDouble() throws IOException
    {
        return Double.parseDouble(next());
    }

    public static long nextLong() throws IOException
    {
        return Long.parseLong(next());
    }

    public static String nextLine() throws IOException
    {
        return bufferedReader.readLine();
    }

    public static void close()
    {
        out.close();
    }

    public static void main(String[] args)
    {
        try
        {
            solve();
        } catch (IOException exception)
        {
            exception.printStackTrace();
        }
        close();
    }

    enum BKR
    {
        QUEEN, ROOK, BISHOP
    }

    static class Piece
    {
        BKR piece;
        long x;
        long y;

        public Piece(BKR piece, long x,long y)
        {
            this.piece = piece;
            this.x = x;
            this.y = y;
        }
    }

    public static Piece get(Piece[] pieces, Predicate<Piece> predicate)
    {
        return Stream
                .of(pieces)
                .filter(predicate)
                .findFirst()
                .orElse(null);
    }

    public static void solve() throws IOException
    {
        int n = nextInt();
        long kingX = nextLong();
        long kingY = nextLong();
        Piece[] pieces = new Piece[n];
        for (int index = 0; index < n; index++)
        {
            String p = next();
            BKR piece = null;
            if (p.equals("R"))
            {
                piece = BKR.ROOK;
            }
            if (p.equals("B"))
            {
                piece = BKR.BISHOP;
            }
            if (p.equals("Q"))
            {
                piece = BKR.QUEEN;
            }
            long x = nextLong() - kingX;
            long y = nextLong() - kingY;
            pieces[index] = new Piece(piece, x, y);
        }
        Arrays.sort(pieces, (a, b) -> Long.compare(Math.abs(a.x) + Math.abs(a.y), Math.abs(b.x) + Math.abs(b.y)));
        Piece p;
        boolean check = false;
        p = get(pieces, piece -> piece.y == 0 && piece.x < 0);
        check |= p != null && (p.piece == BKR.ROOK || p.piece == BKR.QUEEN);
        p = get(pieces, piece -> piece.y == 0 && piece.x > 0);
        check |= p != null && (p.piece == BKR.ROOK || p.piece == BKR.QUEEN);
        p = get(pieces, piece -> piece.x == 0 && piece.y < 0);
        check |= p != null && (p.piece == BKR.ROOK || p.piece == BKR.QUEEN);
        p = get(pieces, piece -> piece.x == 0 && piece.y > 0);
        check |= p != null && (p.piece == BKR.ROOK || p.piece == BKR.QUEEN);
        p = get(pieces, piece -> piece.x == piece.y && piece.x < 0);
        check |= p != null && (p.piece == BKR.BISHOP || p.piece == BKR.QUEEN);
        p = get(pieces, piece -> piece.x == piece.y && piece.x > 0);
        check |= p != null && (p.piece == BKR.BISHOP || p.piece == BKR.QUEEN);
        p = get(pieces, piece -> piece.x == -piece.y && piece.x < 0);
        check |= p != null && (p.piece == BKR.BISHOP || p.piece == BKR.QUEEN);
        p = get(pieces, piece -> piece.x == -piece.y && piece.x > 0);
        check |= p != null && (p.piece == BKR.BISHOP || p.piece == BKR.QUEEN);
        out.println(check ? "YES" : "NO");
    }
}

