public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int x = sc.nextInt(), y = sc.nextInt();
        int dist[] = new int[8];
        char chr[] = new char[8];

        for (int i = 0; i < n; i++) {
            char r = sc.next().charAt(0);
            int x1 = sc.nextInt(), y1 = sc.nextInt();
            int type = getType(x1 - x, y1 - y);
            if (type != -1) {
                int distance = getDist(x1 - x, y1 - y);
                if (dist[type] == 0 || dist[type] > distance) {
                    dist[type] = distance;
                    chr[type] = r;
                }
            }
        }

        boolean hana = false;
        for (int i = 0; i < 8; i++) {
            if (chr[i] == 'Q' || (i % 2 == 0 && chr[i] == 'R') || (i % 2 == 1 && chr[i] == 'B')) {
                hana = true;
                break;
            }
        }

        System.out.println(hana ? "YES" : "NO");
    }

    private static int getDist(int dx, int dy) {
        dx = Math.abs(dx);
        dy = Math.abs(dy);
        if (dx == dy || dx == 0) {
            return dy;
        }
        if (dy == 0) {
            return dx;
        }

        return 0;
    }

    private static int getType(int dx, int dy) {
        if (dx < 0 && dy == 0) {
            return 0;
        } else if (dx < 0 && dx == -dy) {
            return 1;
        } else if (dx == 0 && dy > 0) {
            return 2;
        } else if (dx > 0 && dx == dy) {
            return 3;
        } else if (dx > 0 && dy == 0) {
            return 4;
        } else if (dx > 0 && dx == -dy) {
            return 5;
        } else if (dx == 0 && dy < 0) {
            return 6;
        } else if (dx < 0 && dx == dy) {
            return 7;
        }

        return -1;
    }
}

