public class D {
    public static void solution(BufferedReader reader, PrintWriter writer)
            throws IOException {
        In in = new In(reader);
        Out out = new Out(writer);
        int n = in.nextInt();
        int x0 = in.nextInt(), y0 = in.nextInt();
        int[] bMinD = new int[8], rMinD = new int[8];
        Arrays.fill(bMinD, Integer.MAX_VALUE);
        Arrays.fill(rMinD, Integer.MAX_VALUE);
        for (int i = 0; i < n; i++) {
            char c = in.next().charAt(0);
            int x = in.nextInt(), y = in.nextInt();
            int d = dir(x, y, x0, y0);
            if (d != -1) {
                if (c == 'B' || (c == 'Q' && d > 3))
                    bMinD[d] = Math.min(bMinD[d], d(x, y, x0, y0));
                else if (c == 'R' || (c == 'Q' && d < 4))
                    rMinD[d] = Math.min(rMinD[d], d(x, y, x0, y0));
            }
        }
        boolean check = false;
        for (int i = 0; i < 4; i++)
            if (rMinD[i] < bMinD[i])
                check = true;
        for (int i = 4; i < 8; i++)
            if (bMinD[i] < rMinD[i])
                check = true;
        out.println(check ? "YES" : "NO");
    }

    private static int dir(int x, int y, int x0, int y0) {
        if (y == y0)
            return x > x0 ? 0 : 1;
        else if (x == x0)
            return y > y0 ? 2 : 3;
        else if (Math.abs(x - x0) == Math.abs(y - y0)) {
            if (x - x0 > 0)
                return y - y0 > 0 ? 4 : 5;
            else
                return y - y0 > 0 ? 6 : 7;
        }
        else
            return -1;
    }

    private static int d(int x, int y, int x0, int y0) {
        return Math.max(Math.abs(x - x0), Math.abs(y - y0));
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(
                new BufferedWriter(new OutputStreamWriter(System.out)));
        solution(reader, writer);
        writer.close();
    }

