import java.util.Arrays;
import java.util.StringTokenizer;


public class AntonChess2 {

    int[] d = new int[8];
    int x0, y0;
    char[] t;
    int[] x, y;

    void solve() {
        int n = in.nextInt();
        x0 = in.nextInt();
        y0 = in.nextInt();

        Arrays.fill(d, -1);
        t = new char[n];
        x = new int[n];
        y = new int[n];
        for (int i = 0; i < n; i++) {
            t[i] = in.nextToken().charAt(0);
            x[i] = in.nextInt();
            y[i] = in.nextInt();
            int dir = getDirection(i);
            if (dir >= 0) updateNearest(dir, i);
        }

        for (int i = 0; i < 8; i++) {
            if (d[i] >= 0) {
                if (i < 4 && rookOrQueen(d[i])) {
                    out.println("YES");
                    return;
                }
                if (i >= 4 && bishopOrQueen(d[i])) {
                    out.println("YES");
                    return;
                }
            }
        }
        out.println("NO");
    }

    void updateNearest(int dir, int i) {
        if (d[dir] < 0 || getDistance(i) < getDistance(d[dir])) d[dir] = i;
    }

    int getDistance(int i) {
        return Math.max(Math.abs(x[i] - x0), Math.abs(y[i] - y0));
    }

    int getDirection(int i) {
        if (x[i] == x0) {
            if (y[i] < y0) return 0;
            return 1;
        }
        if (y[i] == y0) {
            if (x[i] < x0) return 2;
            return 3;
        }
        if (x[i] - x0 == y[i] - y0) {
            if (x[i] < x0) return 4;
            return 5;
        }
        if (x[i] - x0 == y0 - y[i]) {
            if (x[i] < x0) return 6;
            return 7;
        }
        return -1;
    }

    boolean rookOrQueen(int i) {
        return t[i] == 'R' || t[i] == 'Q';
    }

    boolean bishopOrQueen(int i) {
