public class D {

    public static void main(String[] args) {
        final Scanner reader = new Scanner(System.in);
        final PrintWriter writer = new PrintWriter(System.out);

        solve(reader, writer);

        reader.close();
        writer.close();
    }

    private static void solve(final Scanner reader, final PrintWriter writer) {
        final int n = reader.nextInt();
        final int x0 = reader.nextInt();
        final int y0 = reader.nextInt();
        final Chess whiteKing = new Chess('K', x0, y0);
        final Chess[] blackFigures = new Chess[n];
        for (int i = 0; i < blackFigures.length; i++) {
            final char role = reader.next().charAt(0);
            final int x = reader.nextInt();
            final int y = reader.nextInt();
            blackFigures[i] = new Chess(role, x, y);
        }
        Arrays.sort(blackFigures, new Comparator<Chess>() {
            @Override
            public int compare(final Chess o1, final Chess o2) {
                final long dist1 = (long)Math.abs(o1.x - whiteKing.x) + (long)Math.abs(o1.y - whiteKing.y);
                final long dist2 = (long)Math.abs(o2.x - whiteKing.x) + (long)Math.abs(o2.y - whiteKing.y);
                if (dist1 == dist2) {
                    final int xComp = Integer.compare(o1.x, o2.x);
                    return xComp != 0 ? xComp : Integer.compare(o1.y, o2.y);
                }
                return Long.compare(dist1, dist2);
            }
        });
        Map<Integer, Boolean> map = new HashMap<>();
        for (int i = 1; i <= 8; ++i) {
            map.put(i, false);
        }

        boolean answer = false;
        for (int i = 0; i < n && !answer; ++i) {
            boolean canBeat = canBeat(whiteKing, blackFigures[i]);
            int position = findPosition(whiteKing, blackFigures[i]);
            if (canBeat) {
                if (position != 0 && !map.get(position)) {
                    answer = true;
                    map.put(position, true);
                }
            } else {
                if (position != 0 && !map.get(position)) {
                    map.put(position, true);
                }
            }
        }
        if (answer) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    private static int findPosition(final Chess whiteKing, final Chess blackFigure) {
        if (whiteKing.x == blackFigure.x) {
            return whiteKing.y < blackFigure.y ? 4 : 8;
        } else if (whiteKing.y == blackFigure.y) {
            return whiteKing.x < blackFigure.x ? 6 : 2;
        } else if (Math.abs(whiteKing.x - blackFigure.x) == Math.abs(whiteKing.y - blackFigure.y)) {
            if (whiteKing.x < blackFigure.x) {
                return whiteKing.y < blackFigure.y ? 5 : 7;
            } else {
                return whiteKing.y < blackFigure.y ? 3 : 1;
            }
        }
        return 0;
    }

    private static boolean canBeat(final Chess whiteKing, final Chess blackFigure) {
        if (blackFigure.role == 'B') {

            return Math.abs(whiteKing.x - blackFigure.x) == Math.abs(whiteKing.y - blackFigure.y);
        } else if (blackFigure.role == 'R') {

            return whiteKing.x == blackFigure.x || whiteKing.y == blackFigure.y;
        } else {

            return Math.abs(whiteKing.x - blackFigure.x) == Math.abs(whiteKing.y - blackFigure.y)
                    || (whiteKing.x == blackFigure.x || whiteKing.y == blackFigure.y);
        }
    }

    private static final class Chess {
        private final char role;
        private final int x;
        private final int y;

        private Chess(final char role, final int x, final int y) {
            this.role = role;
            this.x = x;
            this.y = y;
        }
    }

}

