    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));

        int n = Integer.parseInt(br.readLine());
        String[] nums = br.readLine().split(" ");
        long x = Long.parseLong(nums[0]);
        long y = Long.parseLong(nums[1]);

        for (int i = 0; i < n; i++) {
            nums = br.readLine().split(" ");
            long xx = Long.parseLong(nums[1]) - x;
            long yy = Long.parseLong(nums[2]) - y;
            addNode(xx, yy, nums[0].charAt(0));
        }

        if (check()) pw.println("YES");
        else pw.println("NO");


        pw.flush();
        pw.close();
        br.close();

    }

    private static void addNode(long x, long y, char c){
        if (x > 0 && x == y) update(0, x, y, c);
        else if (x > 0 && y == 0) update(1, x, y, c);
        else if (x > 0 && x == -y) update(2, x, y, c);
        else if (x == 0 && y < 0) update(3, x, y, c);
        else if (x < 0 && x == y) update(4, x, y, c);
        else if (x < 0 && y == 0) update(5, x, y, c);
        else if (x < 0 && x == -y) update(6, x, y, c);
        else if (x == 0 && y > 0) update(7, x, y, c);

    }

    private static void update(int p, long x, long y, char c) {
        if (nds[p] == null) nds[p] = new Node(x, y, c);
        else if (Math.abs(x) < Math.abs(nds[p].x) || Math.abs(y) < Math.abs(nds[p].y)) nds[p] = new Node(x, y, c);
    }

    private static boolean check(){
        for (int i = 0; i < 8; i++) {
            if (nds[i] == null) continue;
            if (nds[i].c == 'Q') return true;
            else if (nds[i].c == 'R' && (nds[i].x == 0 || nds[i].y == 0)) return true;
            else if (nds[i].c == 'B' && nds[i].x != 0 && nds[i].y != 0) return true;

        }
        return false;
    }

}

