	static class InputReader {
		private final InputStream stream;
		private final byte[] buf = new byte[8192];
		private int curChar, snumChars;
		private SpaceCharFilter filter;

		public InputReader(InputStream stream) {
			this.stream = stream;
		}

		public int snext() {
			if (snumChars == -1)
				throw new InputMismatchException();
			if (curChar >= snumChars) {
				curChar = 0;
				try {
					snumChars = stream.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (snumChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		public int nextInt() {
			int c = snext();
			while (isSpaceChar(c)) {
				c = snext();
			}
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = snext();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = snext();
			} while (!isSpaceChar(c));
			return res * sgn;
		}

		public long nextLong() {
			int c = snext();
			while (isSpaceChar(c)) {
				c = snext();
			}
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = snext();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = snext();
			} while (!isSpaceChar(c));
			return res * sgn;
		}

		public int[] nextIntArray(int n) {
			int a[] = new int[n];
			for (int i = 0; i < n; i++) {
				a[i] = nextInt();
			}
			return a;
		}

		public String readString() {
			int c = snext();
			while (isSpaceChar(c)) {
				c = snext();
			}
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = snext();
			} while (!isSpaceChar(c));
			return res.toString();
		}

		public String nextLine() {
			int c = snext();
			while (isSpaceChar(c))
				c = snext();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = snext();
			} while (!isEndOfLine(c));
			return res.toString();
		}

		public boolean isSpaceChar(int c) {
			if (filter != null)
				return filter.isSpaceChar(c);
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		private boolean isEndOfLine(int c) {
			return c == '\n' || c == '\r' || c == -1;
		}

		public interface SpaceCharFilter {
			public boolean isSpaceChar(int ch);
		}
	}
}

import java.util.Arrays;
import java.util.Scanner;


public class D_AntonAndChess2 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        int n = in.nextInt();

        int x = in.nextInt();
        int y = in.nextInt();

        int[] treatDist = new int[9];
        Arrays.fill(treatDist, Integer.MAX_VALUE);

        boolean[] treats = new boolean[9];

        for (int i = 0; i < n; i++) {

            char figType = in.next().charAt(0);

            int xi = in.nextInt();
            int yi = in.nextInt();

            int disty = Math.abs(y - yi);
            int distx = Math.abs(x - xi);

            if (xi == x || yi == y || distx == disty) {

                int dirCodeX = distx == 0 ? 0 : (xi - x) / distx;
                int dirCodeY = disty == 0 ? 0 : (yi - y) / disty;
                int dirCode = dirCodeY * 3 + dirCodeX + 4;

                int dist = distx == 0 ? disty : distx;

                if (dist < treatDist[dirCode]) {
                    treatDist[dirCode] = dist;
                    treats[dirCode] = distx == disty ? figType != 'R' : figType != 'B';
                }
            }
        }

        boolean isTreat = false;
        for (int i = 0; i < 9; i++) if (treats[i]) isTreat = true;

        if (isTreat) System.out.println("YES");
        else System.out.println("NO");
    }
}

