		String[] input = bf.readLine().trim().split(" ");
		int x = Integer.parseInt(input[0]);
		int y = Integer.parseInt(input[1]);

		int[] dist = new int[9];

		boolean[] distBool = new boolean[9];
		Arrays.fill(dist, Integer.MAX_VALUE);
		char type;
		int x1, y1;
		int dirX, dirY, dirCode, distance, disty, distx;

		for (int i = 0; i < n; i++) {
			input = bf.readLine().trim().split(" ");
			type = input[0].toCharArray()[0];
			x1 = Integer.parseInt(input[1]);
			y1 = Integer.parseInt(input[2]);

			disty = Math.abs(y - y1);
			distx = Math.abs(x - x1);

			if (x - x1 == 0 || y - y1 == 0 || disty == distx) {

				dirX = distx == 0 ? 0 : (x - x1) / distx;
				dirY = disty == 0 ? 0 : (y - y1) / disty;


				dirCode = dirY * 3 + dirX + 4;
				distance = Integer.max(distx,disty);

				if (distance < dist[dirCode]) {
					dist[dirCode] = distance;
					distBool[dirCode] = distx == disty ? type != 'R' : type != 'B';
				}
			}
		}

		if (isCheckPossible(distBool)) {
			System.out.println("YES");
		} else {
			System.out.println("NO");
		}

	}

	private static boolean isCheckPossible(boolean[] distBool) {
		for (boolean b : distBool) {
			if (b)
				return b;
		}
		return false;
	}


}

import java.util.Scanner;
import java.util.Comparator;
import java.util.Arrays;

public class InfiniteChess {

	static enum PieceType {

		NONE('0',false,false),
		KING('K',false,false),
		QUEEN('Q',true,true),
		ROOK('R',true,false),
		BISHOP('B',false,true);

		private boolean lines, diags;
		private char letter;

		private static long abs(long x) {
			return (x<0)?-x:x;
		}

		private PieceType(char letter, boolean lines, boolean diags) {
			this.letter = letter;
			this.lines = lines;
			this.diags = diags;
		}

		public boolean attacks(long x0, long y0, long x, long y) {
			long diffx = x-x0;
			long diffy = y-y0;
			return ( lines && (diffx==0 || diffy==0) ) || ( diags && (abs(diffx)==abs(diffy)) );
		}

		public static PieceType getType(char letter) {
			for(PieceType type : PieceType.values()) {
				if(letter==type.letter)
					return type;
			}
			return null;
		}

		public boolean getLines() {
			return lines;
		}
		public boolean getDiags() {
			return diags;
		}
		public char getLetter() {
			return letter;
		}

	}

	static enum Direction {
		RIGHT(1,0,new CompareByX(1)),
		LEFT(-1,0,new CompareByX(-1)),
		UP(0,1,new CompareByY(1)),
		DOWN(0,-1,new CompareByY(-1)),
		UPRIGHT(1,1,new CompareByUp(1)),
		DOWNRIGHT(1,-1,new CompareByDown(1)),
		UPLEFT(-1,1,new CompareByDown(-1)),
		DOWNLEFT(-1,-1,new CompareByUp(-1));

		private int horz,vert;
		private Comparator<Piece> comp;

		private Direction(int horz, int vert, Comparator<Piece> comp) {
			this.horz = horz;
			this.vert = vert;
			this.comp = comp;
		}

		public boolean lineOfSight(Piece king, Piece piece) {
			long diffx = piece.x-king.x;
			long diffy = piece.y-king.y;
			return horz*diffy==vert*diffx;
		}

		public int getHorz() { return horz; }
		public int getVert() { return vert; }
		public Comparator<Piece> getCompare() { return comp; }

	}

	static class Piece {
		private PieceType type;
		private long x,y;
		Piece(PieceType type, long x, long y) {
			this.type = type;
			this.x = x;
			this.y = y;
		}
		boolean attacks(Piece king) {
			return type.attacks(king.x,king.y,x,y);
		}
		PieceType getType() {
			return type;
		}
		@Override
		public String toString() {
			return ""+type.getLetter()+"("+x+","+y+")";
		}
	}

	private static int sign(long x) {
		if(x<0)
			return -1;
		else if(x>0)
			return 1;
		else
			return 0;
	}

	static class CompareByX implements Comparator<Piece> {
		private int forward;
		public CompareByX(int forward) {
			this.forward = forward;
		}
		public int compare(Piece p1, Piece p2) {
			long diffx = p1.x-p2.x;
			return forward*sign(diffx);
		}
	}
	static class CompareByY implements Comparator<Piece> {
		private int forward;
		public CompareByY(int forward) {
			this.forward = forward;
		}
		public int compare(Piece p1, Piece p2) {
			long diffy = p1.y-p2.y;
			return forward*sign(diffy);
		}
	}
	static class CompareByUp implements Comparator<Piece> {
		private int forward;
		public CompareByUp(int forward) {
			this.forward = forward;
		}
		public int compare(Piece p1, Piece p2) {
			long diffx = p1.x-p2.x;
			long diffy = p1.y-p2.y;
			return forward*sign(diffx+diffy);
		}
	}
	static class CompareByDown implements Comparator<Piece> {
		private int forward;
		public CompareByDown(int forward) {
			this.forward = forward;
		}
		public int compare(Piece p1, Piece p2) {
			long diffx = p1.x-p2.x;
			long diffy = p1.y-p2.y;
			return forward*sign(diffx-diffy);
		}
	}

	static Piece searchDirection(Direction direction, Piece king, Piece[] pieces) {
		Arrays.sort(pieces, direction.getCompare());
		int n = pieces.length;
		int i = Arrays.binarySearch(pieces, king, direction.getCompare());
		if(i<0)
			i = -i-1;

		for(int j=i; j<n; j++) {
			if(direction.lineOfSight(king, pieces[j]))
				return pieces[j];
		}
		return null;
	}

	static boolean kingInCheck(Piece king, Piece[] pieces) {
		int n = pieces.length;

		for(Direction direction : Direction.values()) {
			Piece piece = searchDirection(direction, king, pieces);

			if(piece!=null && piece.attacks(king))
				return true;
		}
		return false;
	}

	public static void main(String[] args) {
		Scanner scanIn = new Scanner(System.in);
		int n = scanIn.nextInt();
		long x0 = scanIn.nextLong();
		long y0 = scanIn.nextLong();
		Piece king = new Piece(PieceType.KING, x0, y0);
		Piece[] pieces = new Piece[n];
		for(int i=0; i<n; i++) {
			String lett = scanIn.next();
			char letter = lett.charAt(0);
			long x = scanIn.nextLong();
			long y = scanIn.nextLong();
			PieceType type = PieceType.getType(letter);
			pieces[i] = new Piece(type, x, y);
		}



		if(kingInCheck(king, pieces))
			System.out.println("YES");
		else
			System.out.println("NO");
	}

}

