import java.math.BigInteger;

public class Main{
  public static class InputReader {
    BufferedReader reader;
    StringTokenizer tokenizer;

    public InputReader(InputStream stream){
      reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String next(){
      while(tokenizer == null || !tokenizer.hasMoreTokens()){
        try{
          tokenizer = new StringTokenizer(reader.readLine());
        } catch (IOException ioe) {
          throw new RuntimeException(ioe);
        }
      }
      return tokenizer.nextToken();
    }

    public int nextInt(){
      return Integer.parseInt(next());
    }

    public long nextLong(){
      return Long.parseLong(next());
    }

    public double nextDouble(){
      return Double.parseDouble(next());
    }

    public BigInteger nextBigInteger(){
      return new BigInteger(next());
    }
  }

  public static boolean canWin(char[][] p, int ax, int ay,  int bx, int by, int cx, int cy){
    int c = 0;
    int d = 0;
    if(p[ax][ay] == '.'){
      d++;
    }
    if(p[bx][by] == '.'){
      d++;
    }
    if(p[cx][cy] == '.'){
      d++;
    }
    if(p[ax][ay] == 'x'){
      c++;
    }
    if(p[bx][by] == 'x'){
      c++;
    }
    if(p[cx][cy] == 'x'){
      c++;
    }
    return (c == 2 && d == 1);
  }

  public static void main(String[] args){
    InputReader reader = new InputReader(System.in);
    PrintWriter pw = new PrintWriter(System.out);
    char[][] p = new char[4][4];
    for(int i=0;i<4;++i){
     p[i] = reader.next().toCharArray();
    } 
    boolean canWin = false;
    for(int i=0;i<4;++i){
      for(int j=0;j<2;++j){
        canWin |= canWin(p,i,j,i,j+1,i,j+2);
      }
    }
    for(int i=0;i<2;++i){
      for(int j=0;j<4;++j){
        canWin |= canWin(p,i,j,i+1,j,i+2,j);
      }
    }

    for(int i=0;i<2;++i){
      for(int j=0;j<2;++j){
        canWin |= canWin(p,i,j,i+1,j+1,i+2,j+2);
      }
    }

    for(int i=2;i<4;++i){
      for(int j=0;j<2;++j){
        canWin |= canWin(p,i,j,i-1,j+1,i-2,j+2);
      }
    }

    if(canWin){
      pw.println("YES");
    } else {
      pw.println("NO");
    }
    pw.flush();
    pw.close();
  }

}

import java.io.*;    
import java.math.*;  
import java.util.*;  


public class R390_Div2_B
{	
	FastReader in;
	PrintWriter out;

	public static void main(String[] args)  {
		new R390_Div2_B().run();
	}

	void run()
	{		
		in = new FastReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.close();
	}

	void solve()
	{
		int n = 4;
		String[] s = new String[n];
		for (int i = 0; i < n; i++) 
			s[i] = in.next();

		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++)
			{
				for (int d1 = -1; d1 <= 1; d1++)
					for (int d2 = -1; d2 <= 1; d2++)
					{
						if (d1 == 0 && d2 == 0) continue;
						boolean ok = true;
						int p = 0;
						for (int k = 0; k < 3; k++)
						{
							int x = i + d1*k;
							int y = j + d2*k;
							if (x < 0 || x > n-1 || y < 0 || y > n-1) 
								ok = false;
							else if (s[x].charAt(y) == 'o') ok = false;
							else if (s[x].charAt(y) == '.') p++;

						}
						if (ok && p <= 1)
						{
							out.println("YES");
							return;
						}
					}
			}
		out.println("NO");	
	}


	void runWithFiles() {
		in = new FastReader(new File("input.txt"));
		try {
			out = new PrintWriter(new File("output.txt"));
		} 
		catch (FileNotFoundException e) {
			e.printStackTrace();
		}
		solve();
		out.close();
	}

	class FastReader
	{
	    BufferedReader br;
	    StringTokenizer tokenizer;

	    public FastReader(InputStream stream)
	    {
	        br = new BufferedReader(new InputStreamReader(stream));
	        tokenizer = null;
	    }
		public FastReader(File f) {
			try {
				br = new BufferedReader(new FileReader(f));
				tokenizer = null;
			}
			catch (FileNotFoundException e) {
				e.printStackTrace();
			}
		}

	    private String next() {
	        while (tokenizer == null || !tokenizer.hasMoreTokens())
	            try {
	            	tokenizer = new StringTokenizer(br.readLine());
	            }
	            catch (IOException e) {
	                throw new RuntimeException(e);
	            }
	        return tokenizer.nextToken();
	    }
		public String nextLine() {
			try	{
				return br.readLine();
			}
			catch(Exception e) {
				throw(new RuntimeException());
			}
		}

	    int nextInt() {
	        return Integer.parseInt(next());
	    }
	    long nextLong() {
	        return Long.parseLong(next());
	    }
	    double nextDouble() {
	        return Double.parseDouble(next());
	    }	    
	    BigInteger nextBigInteger() {
	        return new BigInteger(next());
	    }
	    BigDecimal nextBigDecimal() {
	        return new BigDecimal(next());
	    }
	}
}

