class Board {
    private List<RowCol> sequences = new ArrayList<>();

    public Board(char[][] board) {

        for (int i=0; i<4; i++) {
            RowCol row = new RowCol(board[i]);
            sequences.add(row);
        }

        for (int j=0; j<4; j++) {
            char[] col = new char[4];
            for (int i=0; i<4; i++) {
                col[i] = board[i][j];
            }
            RowCol column = new RowCol(col);
            sequences.add(column);
        }

        sequences.add(new RowCol(board[0][0], board[1][1], board[2][2], board[3][3]));
        sequences.add(new RowCol(board[0][1], board[1][2], board[2][3]));
        sequences.add(new RowCol(board[1][0], board[2][1], board[3][2]));

        sequences.add(new RowCol(board[3][0], board[2][1], board[1][2], board[0][3]));
        sequences.add(new RowCol(board[3][1], board[2][2], board[1][3]));
        sequences.add(new RowCol(board[2][0], board[1][1], board[0][2]));
    }

    public boolean canWin() {
        for (RowCol sequence : sequences) {
            if (sequence.canWin()) {
                return true;
            }
        }
        return false;
    }
}

class RowCol extends CanWin {
    char[] rowCol;

    public RowCol(char[] rowCol) {
        this.rowCol = rowCol;
    }

    public RowCol(char first, char second, char third) {
        rowCol = new char[3];
        rowCol[0] = first;
        rowCol[1] = second;
        rowCol[2] = third;
    }

    public RowCol(char first, char second, char third, char fourth) {
        rowCol = new char[4];
        rowCol[0] = first;
        rowCol[1] = second;
        rowCol[2] = third;
        rowCol[3] = fourth;
    }

    public boolean canWin() {
        return canWin1() || canWin2();
    }

    private boolean canWin1() {
        char first = rowCol[0];
        char second = rowCol[1];
        char third = rowCol[2];
        return isWinning(first, second, third);
    }

    private boolean canWin2() {
        if (rowCol.length == 3) {
            return false;
        }
        char first = rowCol[1];
        char second = rowCol[2];
        char third = rowCol[3];
        return isWinning(first, second, third);
    }
}

class CanWin {
    protected boolean isWinning(char first, char second, char third) {

        return
                (first == '.' && second == 'x' && third == 'x')
                || (first == 'x' && second == '.' && third == 'x')
                || (first == 'x' && second == 'x' && third == '.');
    }
}

