public class B {
    char findNextTurn(char board[][]) {
        int sum = 0;
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == 'x') sum++;
                else if (board[i][j] == 'o') sum--;
            }
        }

        if (sum == 1) return 'o';
        else if (sum == 0) return 'x';
        else throw new RuntimeException("impossible");
    }

    boolean isWin(char board[][], char c) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (isWinFrom(board, i, j, c)) return true;
            }
        }
        return false;
    }

    boolean isWinFrom(char board[][], int si, int sj, char player) {
        if (count(board, si, sj, player, 0, 1) >= 3) return true;
        else if (count(board, si, sj, player, 1, 0) >= 3) return true;
        else if (count(board, si, sj, player, 1, 1) >= 3) return true;
        else if (count(board, si, sj, player, -1, 1) >= 3) return true;
        else return false;
    }

    int count(char board[][], int si, int sj, char player, int di, int dj) {
        int cnt = 0;
        while (si >= 0 && sj >= 0 && si < board.length && sj < board[si].length && board[si][sj] == player) {
            si += di;
            sj += dj;
            cnt++;
        }
        return cnt;
    }

    public void run() {
        Scanner sc = new Scanner(System.in);
        char board[][] = new char[4][4];
        for (int i = 0; i < 4; i++) {
            board[i] = sc.nextLine().toCharArray();
        }

        char c = findNextTurn(board);
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == '.') {
                    board[i][j] = c;
                    if (board[i][j] == c && isWin(board, c)) {
                        System.out.println("YES");
                        return;
                    }
                    board[i][j] = '.';
                }
            }
        }
        System.out.println("NO");
    }

    public static void main(String[] args) {
        new B().run();
    }
}

