			}
		}

		boolean win=false;

		for(int i=0 ; i<4 ; i++){
			if(win)
				break;
			for(int j=0 ; j<2 ; j++){
				win = win(new int[]{i,j},new int[]{i,j+1},new int[]{i,j+2});
				if(win)
					break;
			}
		}

		for(int j=0 ; j<4 ; j++){
			if(win)
				break;
			for(int i=0 ; i<2 ; i++){
				win = win(new int[]{i,j},new int[]{i+1,j},new int[]{i+2,j});
				if(win)
					break;
			}
		}

		for(int j=0 ; j<2 ; j++){
			if(win)
				break;
			for(int i=0 ; i<2 ; i++){
				win = win(new int[]{i,j},new int[]{i+1,j+1},new int[]{i+2,j+2});
				if(win)
					break;
			}
		}

		for(int j=3 ; j>1 ; j--){
			if(win)
				break;
			for(int i=0 ; i<2 ; i++){
				win = win(new int[]{i,j},new int[]{i+1,j-1},new int[]{i+2,j-2});
				if(win)
					break;
			}
		}

		System.out.print(win? "YES" : "NO");


	}

	static boolean win(int[] a,int[] b,int[] c){
		int countx =0 , countnon = 0;

		if(arr[a[0]][a[1]]=='x')
			countx++;
		else if(arr[a[0]][a[1]]=='.')
			countnon++;

		if(arr[b[0]][b[1]]=='x')
			countx++;
		else if(arr[b[0]][b[1]]=='.')
			countnon++;

		if(arr[c[0]][c[1]]=='x')
			countx++;
		else if(arr[c[0]][c[1]]=='.')
			countnon++;

		if(countx==2 && countnon ==1)
			return true;

		return false;
	}
}

