public class Ilya {

  public static void main(String[] args) throws IOException{
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

    char[][] ttt = new char[4][4];
    for(int i = 0; i < 4; i++)
      ttt[i] = (br.readLine()).toCharArray();

    boolean canWin = checkRows(ttt);
    if(!canWin){
      canWin = checkCols(ttt);
      if(!canWin)
        canWin = checkDiagonals2(ttt);
    }

    if(canWin)
      System.out.println("YES");
    else
      System.out.println("NO");
  }

  public static boolean checkRows(char[][] ttt){

    for(int i = 0; i < 4; i++){
      String s = String.valueOf(ttt[i]);
      if(checkString(s))
        return true;
    }
    return false;
  }

  public static boolean checkCols(char[][] ttt){

    for(int i = 0; i < 4; i++){
      String s = String.valueOf(new char[]{ttt[0][i],ttt[1][i],ttt[2][i],ttt[3][i]});
      if(checkString(s))
        return true;
    }
    return false;
  }

  public static boolean checkDiagonals2(char[][] ttt){

    StringBuilder[] sb = new StringBuilder[4];

    for(int i = 0; i < 4; i++)
      sb[i] = new StringBuilder();

    for(int i = 0; i < 3; i++){
      sb[0].append(ttt[i][i+1]);
      sb[1].append(ttt[i+1][i]);
      sb[2].append(ttt[2-i][i]);
      sb[3].append(ttt[3-i][i+1]);
    }

    String s = String.valueOf(new char[]{ttt[0][0],ttt[1][1],ttt[2][2],ttt[3][3]});
    if(checkString(s))
      return true;

    s =  String.valueOf(new char[]{ttt[0][3],ttt[1][2],ttt[2][1],ttt[3][0]});
    if(checkString(s))
      return true;

    for(int i = 0; i < 4; i++)
      if(checkString(sb[i].toString()))
        return true;

    return false;
  }

  public static boolean checkString(String s){
    if(s.indexOf(".xx") != -1 || s.indexOf("xx.") != -1 || s.indexOf("x.x") != -1)
      return true;
    return false;
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;


public class IlyaTicTacToegame {

    public static void main(String [] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        char [][] board = new char[4][];
        for (int i = 0; i < board.length; i++) {
            board[i] = br.readLine().toCharArray();
        }

        boolean flag = false;
        for (int i = 0; i < board.length && !flag; i++) {
            for (int j = 0; j < board.length && !flag; j++) {

                if (checkHorizontal(i, j, board)) {
                    flag = true;
                }

                if (checkVertical(i, j, board)) {
                    flag = true;
                }

                if (checkDiagonal(i, j, board)) {
                    flag = true;
                }

                if (checkReverseDiagonal(i, j, board)) {
                    flag = true;
                }
            }
        }

        System.out.println(flag ? "YES" : "NO");
    }

    static boolean checkHorizontal(int i, int j, char [][] board) {
        int xs = 0;
        int os = 0;
        int cnt = 0;
        for (int c = j; c < j + 3 && c < 4; c++) {
            char ch = board[i][c];
            if (ch == 'x')
                xs ++;
            if (ch == 'o')
                os ++;
            cnt++;
        }
        return xs == 2 && os == 0 && cnt == 3;
    }

    static boolean checkVertical(int i, int j, char [][] board) {
        int xs = 0;
        int os = 0;
        int cnt = 0;
        for (int c = i; c < i + 3 && c < 4; c++) {
            char ch = board[c][j];
            if (ch == 'x')
                xs ++;
            if (ch == 'o')
                os ++;
            cnt++;
        }
        return xs == 2 && os == 0 && cnt == 3;
    }

    static boolean checkDiagonal(int i, int j, char [][] board) {
        int xs = 0;
        int os = 0;
        int cnt = 0;
        for (int c = 0; c < 3 && c + i < 4 && c + j < 4; c++) {
            char ch = board[c + i][j + c];
            if (ch == 'x')
                xs ++;
            if (ch == 'o')
                os ++;
            cnt++;
        }
        return xs == 2 && os == 0 && cnt == 3;
    }

    static boolean checkReverseDiagonal(int i, int j, char [][] board) {
        int xs = 0;
        int os = 0;
        int cnt = 0;
        for (int c = 0; c < 3 && i + c < 4 && j - c >= 0; c++) {
            char ch = board[i + c][j - c];
            if (ch == 'x')
                xs ++;
            if (ch == 'o')
                os ++;
            cnt++;
        }
        return xs == 2 && os == 0 && cnt == 3;
    }
}

