            }
        }

        if (checkCanWin(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    private static boolean checkCanWin(char[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid.length; j++) {
                if (grid[i][j] != '.')
                    continue;

                grid[i][j] = 'x';
                if (checkWins(grid)) {
                    return true;
                }
                grid[i][j] = '.';
            }
        }
        return false;
    }

    private static boolean checkWins(char[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid.length; j++) {
                if (grid[i][j] != 'x')
                    continue;

                if (checkFrom(i, j, grid)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean checkFrom(int i, int j, char[][] grid) {
        if (i < grid.length - 2) {
            if (grid[i + 1][j] == 'x' && grid[i + 2][j] == 'x')
                return true;
        }

        if (j < grid.length - 2) {
            if (grid[i][j + 1] == 'x' && grid[i][j + 2] == 'x')
                return true;
        }

        if (i < grid.length - 2 && j < grid.length - 2) {
            if (grid[i + 1][j + 1] == 'x' && grid[i + 2][j + 2] == 'x')
                return true;
        }

        if (i < grid.length - 2 && j > 1) {
            if (grid[i + 1][j - 1] == 'x' && grid[i + 2][j - 2] == 'x')
                return true;
        }

        return false;
    }

}

