import java.util.ArrayList;
import java.util.Scanner;

public class main {

	static class Coordinate {
		public int v1;
		public int v2;

		public Coordinate(int v1, int v2){
			this.v1 = v1;
			this.v2 = v2;
		}

		public int getV1() {
			return v1;
		}

		public void setV1(int v1) {
			this.v1 = v1;
		}

		public int getV2() {
			return v2;
		}

		public void setV2(int v2) {
			this.v2 = v2;
		}

		public String toString(){
			return "(" + v1 + ", " + v2 + ")";
		}
	}

	public static void main(String args[]){
		Scanner input = new Scanner(System.in);

		char[][] ticTacGame = new char[4][];
		for(int i=0; i<4; i++){
			ticTacGame[i] = input.next().toCharArray();
		}
		checkTicTac(ticTacGame);

		input.close();
	}

	public static void checkTicTac(char[][] ticTacGame){
		for(int i=0; i<4; i++){
			for(int j=0; j<4; j++){
				if(ticTacGame[i][j] == '.'){
					ticTacGame[i][j] = 'x';
					if(checkWin(ticTacGame)){
						System.out.println("YES");
						return;
					}
					ticTacGame[i][j] = '.';
				}
			}
		}
		System.out.println("NO");
	}

	public static boolean checkWin(char[][] ticTacGame){
		ArrayList<Coordinate> coords = getCoords(ticTacGame, 'x');
		for(Coordinate coord : coords){
			ArrayList<Coordinate> coordsOnRow = filterCoordsByVal1(coords, coord.v1);
			ArrayList<Coordinate> coordsOnCol = filterCoordsByVal2(coords, coord.v2);
			ArrayList<Coordinate> coordsOnDiag1 = filterCoordsByDiag1(coords, coord);
			ArrayList<Coordinate> coordsOnDiag2 = filterCoordsByDiag2(coords, coord);

			if(filterAdjacent(coordsOnRow, coord).size() == 2){
				return true;
			}
			if (filterAdjacent(coordsOnCol, coord).size() == 2){
				return true;
			}
			if (filterAdjacent(coordsOnDiag1, coord).size() == 2){
				return true;
			}
			if (filterAdjacent(coordsOnDiag2, coord).size() == 2){
				return true;
			}
		}
		return false;
	}

	public static ArrayList<Coordinate> getCoords(char[][] grid, char elem){
		ArrayList<Coordinate> coords = new ArrayList<Coordinate>();
		for(int i=0; i<grid.length; i++){
			for(int j=0; j<grid[i].length; j++){
				if(grid[i][j] == elem){
					coords.add(new Coordinate(i, j));
				}
			}
		}
		return coords;
	}

	public static ArrayList<Coordinate> filterCoordsByVal1(ArrayList<Coordinate> coords, int val1){
		ArrayList<Coordinate> res = new ArrayList<Coordinate>();
		for(Coordinate coord : coords){
			if(coord.v1 == val1){
				res.add(coord);
			}
		}
		return res;
	}

	public static ArrayList<Coordinate> filterCoordsByVal2(ArrayList<Coordinate> coords, int val2){
		ArrayList<Coordinate> res = new ArrayList<Coordinate>();
		for(Coordinate coord : coords){
			if(coord.v2 == val2){
				res.add(coord);
			}
		}
		return res;
	}

	public static ArrayList<Coordinate> filterCoordsByDiag1(ArrayList<Coordinate> coords, Coordinate coordIn){
		ArrayList<Coordinate> res = new ArrayList<Coordinate>();
		for(Coordinate coord : coords){
			if(coord.v2 - coord.v1 == coordIn.v2 - coordIn.v1){
				res.add(coord);
			}
		}
		return res;
	}

	public static ArrayList<Coordinate> filterCoordsByDiag2(ArrayList<Coordinate> coords, Coordinate coordIn){
		ArrayList<Coordinate> res = new ArrayList<Coordinate>();
		for(Coordinate coord : coords){
			if (coord.v2 + coord.v1 == coordIn.v2 + coordIn.v1){
				res.add(coord);
			}
		}
		return res;
	}

	public static ArrayList<Coordinate> filterAdjacent(ArrayList<Coordinate> coords, Coordinate coordIn){
		ArrayList<Coordinate> res = new ArrayList<Coordinate>();
		for(Coordinate coord : coords){
			if(Math.max(Math.abs(coord.v1 - coordIn.v1), Math.abs(coord.v2 - coordIn.v2)) == 1){
				res.add(coord);
			}
		}
		return res;
	}
}

