public class B {
    public static void solution(BufferedReader reader, PrintWriter writer)
            throws IOException {
        In in = new In(reader);
        Out out = new Out(writer);
        char[][] b = new char[4][4];
        for (int i = 0; i < 4; i++)
            b[i] = in.next().toCharArray();
        for (int i = 0; i < 4; i++)
            for (int j = 0; j < 4; j++)
                if (check(b, i, j)) {
                    out.println("YES");
                    return;
                }
        out.println("NO");
    }

    private static int[] x = { -1, -1, -1, 0, 1, 1, 1, 0 };
    private static int[] y = { -1, 0, 1, 1, 1, 0, -1, -1 };

    private static boolean check(char[][] b, int i, int j) {
        for (int k = 0; k < 4; k++) {
            int i1 = i + x[k], i2 = i + x[k + 4];
            int j1 = j + y[k], j2 = j + y[k + 4];
            if (!good(i1, j1) || !good(i2, j2))
                continue;
            if (b[i1][j1] == '.' && b[i][j] == 'x' && b[i2][j2] == 'x')
                return true;
            if (b[i1][j1] == 'x' && b[i][j] == '.' && b[i2][j2] == 'x')
                return true;
            if (b[i1][j1] == 'x' && b[i][j] == 'x' && b[i2][j2] == '.')
                return true;
        }
        return false;
    }

    private static boolean good(int i, int j) {
        return i >= 0 && i < 4 && j >= 0 && j < 4;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(
                new BufferedWriter(new OutputStreamWriter(System.out)));
        solution(reader, writer);
        writer.close();
    }

    protected static class In {
        private BufferedReader reader;
        private StringTokenizer tokenizer = new StringTokenizer("");

        public In(BufferedReader reader) {
            this.reader = reader;
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens())
                tokenizer = new StringTokenizer(reader.readLine());
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public int[] nextIntArray(int n) throws IOException {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        public int[] nextIntArray1(int n) throws IOException {
            int[] a = new int[n + 1];
            for (int i = 1; i <= n; i++)
                a[i] = nextInt();
            return a;
        }

        public int[] nextIntArraySorted(int n) throws IOException {
            int[] a = nextIntArray(n);
            Random r = new Random();
            for (int i = 0; i < n; i++) {
                int j = i + r.nextInt(n - i);
                int t = a[i];
                a[i] = a[j];
                a[j] = t;
            }
            Arrays.sort(a);
            return a;
        }

        public long[] nextLongArray(int n) throws IOException {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }

        public long[] nextLongArray1(int n) throws IOException {
