        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        BladeReader in = new BladeReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public boolean solve(char[][] grid) {
            int N = grid.length;
            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < grid.length; j++) {
                    if (grid[i][j] == 'x') {


                        if (i >= 2 && (grid[i - 1][j] == '.' && grid[i - 2][j] == 'x' || grid[i - 1][j] == 'x' && grid[i - 2][j] == '.')) {
                            return true;
                        }


                        if ((i + 2) < N && (grid[i + 1][j] == '.' && grid[i + 2][j] == 'x' || grid[i + 1][j] == 'x' && grid[i + 2][j] == '.')) {
                            return true;
                        }

                        if ((j >= 2) && (grid[i][j - 1] == '.' && grid[i][j - 2] == 'x' || grid[i][j - 1] == 'x' && grid[i][j - 2] == '.')) {
                            return true;
                        }

                        if ((j + 2) < N && (grid[i][j + 1] == '.' && grid[i][j + 2] == 'x' || grid[i][j + 1] == 'x' && grid[i][j + 2] == '.')) {
                            return true;
                        }

                        if ((i >= 2) && (j + 2) < N && (grid[i - 1][j + 1] == '.' && grid[i - 2][j + 2] == 'x' || grid[i - 1][j + 1] == 'x' && grid[i - 2][j + 2] == '.')) {
                            return true;
                        }

                        if ((i + 2 < N) && (j + 2 < N) && (grid[i + 1][j + 1] == '.' && grid[i + 2][j + 2] == 'x' || grid[i + 1][j + 1] == 'x' && grid[i + 2][j + 2] == '.')) {
                            return true;
                        }

                        if ((i >= 2 && j >= 2) && (grid[i - 1][j - 1] == '.' && grid[i - 2][j - 2] == 'x' || grid[i - 1][j - 1] == 'x' && grid[i - 2][j - 2] == '.')) {
                            return true;
                        }

                        if ((i + 2) < N && (j >= 2) && (grid[i + 1][j - 1] == '.' && grid[i + 2][j - 2] == 'x' || grid[i + 1][j - 1] == 'x' && grid[i + 2][j - 2] == '.')) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        public void solve(int testNumber, BladeReader in, PrintWriter out) {
            char[][] grid = new char[4][4];
            for (int i = 0; i < 4; i++) {
                String line = in.nextString();
                char[] lineSplit = line.toCharArray();
                for (int j = 0; j < 4; j++) {
                    grid[i][j] = lineSplit[j];
                }
            }
            out.println(solve(grid) ? "YES" : "NO");
        }

    }

    static class BladeReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public BladeReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public String nextString() {
            return next();
        }

    }
}

