import java.util.*;
public class CF {
    public static boolean winningAnswer(ArrayList list){
        int xCounter = 0;
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i).equals('x')) {
                xCounter++;
            }
        }
        if (xCounter < 2) return false;
        if (list.size() == 3 && xCounter == 2 && list.contains('.')) return true;
        if (list.size() == 4 && list.contains('o') && list.contains('.')) {
            if (xCounter >= 2 && !list.get(1).equals('o') && !list.get(2).equals('o')) return true;
        }
        else if (list.size() == 4 && !list.contains('o')){
            if (xCounter >= 2 && list.get(1).equals('x') || list.get(2).equals('x')) return true;
        }
        return false;
    }
    public static boolean outOfRange(int x, int y){
        if (x > 3 || x < 0 || y > 3 || y < 0){
            return true;
        }
        return false;
    }
    public static boolean checkRightDown(ArrayList list, char[][] t){
        int counter = 0;
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                for (int k = 0; k < 4; k++) {
                    int x = i+k;
                    int y = j+k;
                    if (outOfRange(x,y)) break;
                    list.add(t[x][y]);
                }
                if (list.size() > 2) {
                    if (winningAnswer(list)) return true;
                }
                list.clear();
            }
        }
        return false;
    }
    public static boolean checkLeftDown(ArrayList list, char[][] t){
        int counter = 0;
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                for (int k = 0; k < 4; k++) {
                    int x = i+k;
                    int y = j-k;
                    if (outOfRange(x,y)) break;
                    list.add(t[x][y]);
                }
                if (list.size() > 2) {
                    if (winningAnswer(list)) return true;
                }
                list.clear();
            }
        }
        return false;
    }
    public static boolean checkRows(ArrayList list, char[][] t){
        int counter = 0;
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                list.add(t[i][j]);
            }
            if (list.size() > 2) {
                if (winningAnswer(list)) return true;
            }
            list.clear();
        }
        return false;
    }
    public static boolean checkColumns(ArrayList list, char[][] t){
        int counter = 0;
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                list.add(t[j][i]);
            }
            if (list.size() > 2) {
                if (winningAnswer(list)) return true;
            }
            list.clear();
        }
        return false;
    }
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        ArrayList<Character> list = new ArrayList<>();
        char[][] t = new char[4][];
        for (int i = 0; i < 4; i++) {
            t[i] = sc.next().toCharArray();
        }

        if (checkRightDown(list, t)) {System.out.println("YES"); return;}
        if (checkLeftDown(list, t)) {System.out.println("YES"); return;}
        if (checkRows(list, t)) {System.out.println("YES"); return;}
        if (checkColumns(list, t)) {System.out.println("YES"); return;}
        System.out.println("NO");
    }
}

