public class Solution {
	public static class Board{
		char[][] array= new char[4][4];
		void add(int i, String str)
		{
			for(int j=0; j<4; j++)
			{
				array[i][j]= str.charAt(j);
			}
		}
		boolean check()
		{
			for(int i=0; i<4; i++)
			{
				for(int j=0; j<=1; j++)
				{
					if(array[i][j]=='x' && array[i][j+1]=='x' && array[i][j+2]=='x')
						return true;
				}
			}
			for(int j=0; j<4; j++)
			{
				for(int i=0; i<=1; i++)
				{
					if(array[i][j]=='x' && array[i+1][j]=='x' && array[i+2][j]=='x')
						return true;
				}
			}
			if(array[0][0]=='x' && array[1][1]=='x' && array[2][2]=='x')
				return true;
			if(array[3][3]=='x' && array[1][1]=='x' && array[2][2]=='x')
				return true;
			if(array[0][1]=='x' && array[1][2]=='x' && array[2][3]=='x')
				return true;
			if(array[1][0]=='x' && array[2][1]=='x' && array[3][2]=='x')
				return true;


			if(array[0][3]=='x' && array[1][2]=='x' && array[2][1]=='x')
				return true;
			if(array[3][0]=='x' && array[1][2]=='x' && array[2][1]=='x')
				return true;
			if(array[0][2]=='x' && array[1][1]=='x' && array[2][0]=='x')
				return true;
			if(array[1][3]=='x' && array[2][2]=='x' && array[3][1]=='x')
				return true;

			return false;
		}
		void put(int i, int j)
		{
			array[i][j]='x';
		}
		void take(int i, int j)
		{
			array[i][j]= '.';
		}
	}

	public static void main(String[] args) throws IOException {
		BufferedReader in= new BufferedReader(new InputStreamReader(System.in) );
		Board board= new Board();

		for(int i=0; i<4; i++)
			board.add(i, in.readLine());
		boolean test= false;
		for(int i=0; i<4; i++)
		{
			for(int j=0; j<4; j++)
			{
				if(board.array[i][j]=='.')
				{
					board.put(i, j);
					if(board.check())
					{
						test= true;
						break;
					}
					board.take(i, j);
				}
			}
			if(test)
				break;
		}
		if(test)
			System.out.println("YES");
		else
			System.out.println("NO");
	}

}

