public class ProblemB
{
  public static boolean vertical(char[][] arr)
  {
    boolean flag = false;
    for(int i = 0; i<4; i++)
    {
      for(int j=0; j<2;j++)
      {
        if ((arr[i][j] == 'x') && (arr[i][j+1] == 'x') && (arr[i][j+2] == 'x'))
        {
          flag = true;
        }
      }
    }
    return flag;
  }

  public static boolean horizontal(char[][] arr)
  {
    boolean flag = false;
    for(int i=0; i<2; i++)
    {
      for(int j=0; j<4;j++)
      {
        if ((arr[i][j] == 'x') && (arr[i+1][j] == 'x') && (arr[i+2][j] == 'x'))
        {
          flag = true;
        }
      }
    }
    return flag;
  }

  public static boolean diagonal1(char[][] arr)
  {
    boolean flag = false;
    for(int i=0; i<2; i++)
    {
      for(int j=0; j<2;j++)
      {
        if ((arr[i][j] == 'x') && (arr[i+1][j+1] == 'x') && (arr[i+2][j+2] == 'x'))
        {
          flag = true;
        }
      }
    }
    return flag;
  }

  public static boolean diagonal2(char[][] arr)
  {
    boolean flag = false;
    for(int i=0; i<2; i++)
    {
      for(int j=2; j<4;j++)
      {
        if ((arr[i][j] == 'x') && (arr[i+1][j-1] == 'x') && (arr[i+2][j-2] == 'x'))
        {
          flag = true;
        }
      }
    }
    return flag;
  }

  public static boolean threeInARow(char[][] arr)
  {
    return (vertical(arr) || horizontal(arr) || diagonal1(arr) || diagonal2(arr));
  }


  public static int[] subarr(int[]arr, int beginning, int end)
  {
    int[] ans = new int[end-beginning];
    for (int i=0; i<ans.length; i++)
    {
      ans[i] = arr[i+beginning];
    }
    return ans;
  }


  public static void main (String[] args)
  {
    Scanner scan = new Scanner(System.in);
    char[][] board = new char[4][4];
    for(int i=0; i<4; i++)
    {
      String thisStr = scan.next();
      for (int j = 0; j<4; j++)
      {
        board[i][j] = thisStr.charAt(j);
      }
    }
    boolean canWin = false;
    for (int i=0; i<4; i++)
    {
      for(int j=0; j<4; j++)
      {
        if (board[i][j] == '.')
        {
          board[i][j] = 'x';
          if (threeInARow(board))
          {
            canWin = true;
          }
          board[i][j] = '.';
        }
      }
    }
    if (canWin)
    {
      System.out.println("YES");
    }
    else
    {
      System.out.println("NO");
    }
  }
}

