	static class Scanner 
	{
		StringTokenizer st;
		BufferedReader br;

		public Scanner(InputStream s){	br = new BufferedReader(new InputStreamReader(s));}

		public String next() throws IOException 
		{
			while (st == null || !st.hasMoreTokens()) 
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		public int nextInt() throws IOException {return Integer.parseInt(next());}

		public long nextLong() throws IOException {return Long.parseLong(next());}

		public String nextLine() throws IOException {return br.readLine();}

		public double nextDouble() throws IOException
		{
			String x = next();
			StringBuilder sb = new StringBuilder("0");
			double res = 0, f = 1;
			boolean dec = false, neg = false;
			int start = 0;
			if(x.charAt(0) == '-')
			{
				neg = true;
				start++;
			}
			for(int i = start; i < x.length(); i++)
				if(x.charAt(i) == '.')
				{
					res = Long.parseLong(sb.toString());
					sb = new StringBuilder("0");
					dec = true;
				}
				else
				{
					sb.append(x.charAt(i));
					if(dec)
						f *= 10;
				}
			res += Long.parseLong(sb.toString()) / f;
			return res * (neg?-1:1);
		}

		public boolean ready() throws IOException {return br.ready();}


	}
}

import java.util.HashMap;
import java.util.Scanner;

public class R754B {
	static Scanner in = new Scanner(System.in);

	public static void solve() {
		char[][] p = new char[4][4];
		for (int i = 0; i < 4; i++) {
			p[i] = in.nextLine().toCharArray();
		}

		for (int x = 0; x < 4; x++) {
			for (int y = 0; y < 4; y++) {
				if (p[x][y] == 'x') {
					if (checkDirect(p, x, y, 1, 0, true, false) || checkDirect(p, x, y, 0, 1, true, false)
							|| checkDirect(p, x, y, 1, 1, true, false)|| checkDirect(p, x, y, -1, 1, true, false)) {
						System.out.print("YES");
						return;
					}
				}else				if (p[x][y] == '.') {
					if (checkDirect(p, x, y, 1, 0, true, true) || checkDirect(p, x, y, 0, 1, true, true)
							|| checkDirect(p, x, y, 1, 1, true, true)|| checkDirect(p, x, y, -1, 1, true, true)) {
						System.out.print("YES");
						return;
					}
				}
			}
		}
		System.out.print("NO");

	}

	public static boolean checkDirect(char[][] p, int cX, int cY, int oX, int oY, boolean first, boolean must) {
		if (cX + oX > 3 || cY + oY > 3 || cX + oX < 0 || cY + oY < 0) {
			return false;
		}
		if (first) {
			if (p[cX + oX][cY + oY] == 'x') {
				return checkDirect(p, cX + oX, cY + oY, oX, oY, false, must);
			} else if (p[cX + oX][cY + oY] == '.' && !must) {
				return checkDirect(p, cX + oX, cY + oY, oX, oY, false, true);
			} else {
				return false;
			}
		} else {
			if (p[cX + oX][cY + oY] == 'x') {
				return true;
			} else if (p[cX + oX][cY + oY] == '.' && !must) {
				return true;
			} else {
				return false;
			}
		}
	}

	@SuppressWarnings({ "rawtypes", "unchecked" })
	public static HashMap charOrderMap(HashMap inputMap, String orderingString, int startFrom, boolean charAsKey) {
		char[] chars = orderingString.toCharArray();
		if (charAsKey) {
			for (int i = 0; i < chars.length; i++) {
				inputMap.put(chars[i], i + startFrom);
			}
		} else {
			for (int i = 0; i < chars.length; i++) {
				inputMap.put(i + startFrom, chars[i]);
			}
		}
		return inputMap;
	}

	public static void main(String args[]) {
		solve();
	}

	public static double quadraticEquationRootMax(double a, double b, double c) {
		double root1, root2;
		root1 = (-b + Math.sqrt(Math.pow(b, 2) - 4 * a * c)) / (2 * a);
		root2 = (-b - Math.sqrt(Math.pow(b, 2) - 4 * a * c)) / (2 * a);
		return Math.max(root1, root2);
	}

	public static double quadraticEquationRootMin(double a, double b, double c) {
		double root1, root2;
		root1 = (-b + Math.sqrt(Math.pow(b, 2) - 4 * a * c)) / (2 * a);
		root2 = (-b - Math.sqrt(Math.pow(b, 2) - 4 * a * c)) / (2 * a);
		return Math.min(root1, root2);
	}
}

