        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public boolean inRange(int i, int j) {
            if (i >= 0 && i < 4 && j >= 0 && j < 4)
                return true;
            return false;
        }

        public boolean check(char[][] grid) {

            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    if (inRange(i, j + 1) && inRange(i, j + 2))
                        if (grid[i][j] == 'x' && grid[i][j + 1] == 'x' && grid[i][j + 2] == 'x') {
                            return true;
                        }
                    if (inRange(i + 1, j) && inRange(i + 2, j))
                        if (grid[i][j] == 'x' && grid[i + 1][j] == 'x' && grid[i + 2][j] == 'x') {
                            return true;
                        }
                    if (inRange(i + 1, j + 1) && inRange(i + 2, j + 2))
                        if (grid[i][j] == 'x' && grid[i + 1][j + 1] == 'x' && grid[i + 2][j + 2] == 'x') {
                            return true;
                        }

                    if (inRange(i + 1, j - 1) && inRange(i + 2, j - 2))
                        if (grid[i][j] == 'x' && grid[i + 1][j - 1] == 'x' && grid[i + 2][j - 2] == 'x') {
                            return true;
                        }


                }
            }

            return false;
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            char[][] grid = new char[4][4];

            for (int i = 0; i < 4; i++) {
                String str = in.next();
                for (int j = 0; j < 4; j++) {
                    grid[i][j] = str.charAt(j);
                }
            }

            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    if (grid[i][j] == '.') {
                        grid[i][j] = 'x';

                        if (check(grid)) {
                            out.print("YES");
                            return;
                        } else {
                            grid[i][j] = '.';
                        }
                    }
                }
            }

            out.println("NO");

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

    }
}

