        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        FastPrinter out = new FastPrinter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB
    {
        private final static char X = 'x';
        private final static char DOT = '.';

        public void solve(int testNumber, FastScanner in, FastPrinter out)
        {
            int n = 4;
            char[][] board = new char[n][n];
            for (int i = 0; i < n; i++)
            {
                String s = in.next();
                for (int j = 0; j < n; j++)
                {
                    board[i][j] = s.charAt(j);
                }
            }

            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < n; j++)
                {
                    int x = 0;
                    int dot = 0;
                    for (int k = 0; k < 3; k++)
                    {
                        if (j + k < n)
                        {
                            if (board[i][j + k] == DOT)
                            {
                                dot++;
                            }
                            if (board[i][j + k] == X)
                            {
                                x++;
                            }
                        }
                    }
                    if (check(x, dot))
                    {
                        out.println("YES");
                        return;
                    }
                    x = 0;
                    dot = 0;
                    for (int k = 0; k < 3; k++)
                    {
                        if (i - k >= 0)
                        {
                            if (board[i - k][j] == DOT)
                            {
                                dot++;
                            }
                            if (board[i - k][j] == X)
                            {
                                x++;
                            }
                        }
                    }
                    if (check(x, dot))
                    {
                        out.println("YES");
                        return;
                    }
                    x = 0;
                    dot = 0;
                    for (int k = 0; k < 3; k++)
                    {
                        if (i + k < n && j + k < n)
                        {
                            if (board[i + k][j + k] == DOT)
                            {
                                dot++;
                            }
                            if (board[i + k][j + k] == X)
                            {
                                x++;
                            }
                        }
                    }
                    if (check(x, dot))
                    {
                        out.println("YES");
                        return;
                    }
                    x = 0;
                    dot = 0;
                    for (int k = 0; k < 3; k++)
                    {
                        if (i - k >= 0 && j + k < 3)
                        {
                            if (board[i - k][j + k] == DOT)
                            {
                                dot++;
                            }
                            if (board[i - k][j + k] == X)
                            {
                                x++;
                            }
                        }
                    }
                    if (check(x, dot))
                    {
                        out.println("YES");
                        return;
                    }
                    x = 0;
                    dot = 0;
                    for (int k = 0; k < 3; k++)
                    {
                        if (i + k < n && j - k >= 0)
                        {
                            if (board[i + k][j - k] == DOT)
                            {
                                dot++;
                            }
                            if (board[i + k][j - k] == X)
                            {
                                x++;
                            }
                        }
                    }
                    if (check(x, dot))
                    {
                        out.println("YES");
                        return;
                    }
                }
            }
            out.println("NO");
        }

        private boolean check(int x, int dot)
        {
            return (x == 2 && dot == 1) || (x == 3 && dot == 0);
        }

    }

    static class FastScanner
    {
        public BufferedReader br;
        public StringTokenizer st;

        public FastScanner(InputStream is)
        {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public FastScanner(File f)
        {
            try
            {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e)
            {
                e.printStackTrace();
            }
        }

        public String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                String s = null;
                try
                {
                    s = br.readLine();
                } catch (IOException e)
                {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

    }

    static class FastPrinter extends PrintWriter
    {
        public FastPrinter(OutputStream out)
        {
            super(out);
        }

        public FastPrinter(Writer out)
        {
            super(out);
        }

    }
}

