        private boolean isWinning(char[][] board) {
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    if (board[i][j] != 'x') continue;

                    int x1 = i;
                    int x2 = i;
                    int y1 = j + 1;
                    int y2 = j + 2;

                    if (y1 < 4 && y2 < 4) {
                        if (board[x1][y1] == 'x' && board[x2][y2] == 'x') {
                            return true;
                        }
                    }

                    x1 = i + 1;
                    x2 = i + 2;
                    y1 = j;
                    y2 = j;

                    if (x1 < 4 && x2 < 4) {
                        if (board[x1][y1] == 'x' && board[x2][y2] == 'x') {
                            return true;
                        }
                    }

                    x1 = i + 1;
                    x2 = i + 2;
                    y1 = j + 1;
                    y2 = j + 2;

                    if (x1 < 4 && x2 < 4 && y1 < 4 && y2 < 4) {
                        if (board[x1][y1] == 'x' && board[x2][y2] == 'x') {
                            return true;
                        }
                    }

                    x1 = i + 1;
                    x2 = i + 2;
                    y1 = j - 1;
                    y2 = j - 2;

                    if (x1 < 4 && x2 < 4 && y1 >= 0 && y2 >= 0) {
                        if (board[x1][y1] == 'x' && board[x2][y2] == 'x') {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

