import java.io.IOException;
import java.io.PrintWriter;
import java.util.*;

public class B {

	static FasterScanner sc = new FasterScanner();
	static PrintWriter out = new PrintWriter(System.out);

	static void exit() {

		out.close();
	}

	char [][] grid = new char [4][];
	public B () {
		for (int i = 0; i < 4; i++) {
			grid[i] = sc.nextLine().toCharArray();
		}
		for (int i = 0; i < 4; i++) {
			for (int j = 0; j < 4; j++) {
				if (grid[i][j] == '.' && test(i, j)) {
					out.println("YES");
					return;
				}
			}
		}
		out.println("NO");
	}

	boolean inbound(int ind) {
		return ind >= 0 && ind < 4;
	}
	boolean test(int i, int j) {
		int dir[][] = {{0, 1}, {1, 0}, {1, 1}, {-1, 1}};
		for (int k = 0; k < 4; k++) {
			int dx = dir[k][0];
			int dy = dir[k][1];
			int count = 1;
			for (int step = 1; inbound(i-step*dx) && inbound(j-step*dy); step ++) {
				if (grid[i-step*dx][j-step*dy] == 'x') count ++;
				else break;
			}
			for (int step = 1; inbound(i+step*dx) && inbound(j+step*dy); step ++) {
				if (grid[i+step*dx][j+step*dy] == 'x') count ++;
				else break;
			}
			if (count >= 3) return true;
		}

		return false;
	}

	public static void main(String[] args) {
		new B();
		exit();
	}

	static class FasterScanner {
        private byte[] buf = new byte[1024];
        private int curChar;
        private int snumChars;

        public int read() {
            if (snumChars == -1)
                throw new InputMismatchException();
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = System.in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n, int f) {
            if (f == 0) {
                int[] arr = new int[n];
                for (int i = 0; i < n; i++) {
                    arr[i] = nextInt();
                }
                return arr;
            } else {
                int[] arr = new int[n + 1];
                for (int i = 1; i < n + 1; i++) {
                    arr[i] = nextInt();
                }
                return arr;
            }
        }

        public long[] nextLongArray(int n, int f) {
            if (f == 0) {
                long[] arr = new long[n];
                for (int i = 0; i < n; i++) {
                    arr[i] = nextLong();
                }
                return arr;
            } else {
                long[] arr = new long[n + 1];
                for (int i = 1; i < n + 1; i++) {
                    arr[i] = nextLong();
                }
                return arr;
            }
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

