    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int[][] row = new int[4][4];

            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    char val = in.readCharacter();
                    if (val == 'x') {
                        row[i][j] = 1;
                    } else if (val == 'o') {
                        row[i][j] = 2;
                    } else {
                        row[i][j] = 0;
                    }
                }
            }
            boolean answer = false;
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < 4; j++) {
                    List<Integer> list = new ArrayList<>();
                    for (int l = 0; l < 3; l++) {
                        list.add(row[i + l][j]);
                    }

                    if (contains(list))
                        answer = true;
                }
            }

            if (answer) {
                out.println("YES");
                return;
            }


            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < 4; j++) {
                    List<Integer> list = new ArrayList<>();
                    for (int l = 0; l < 3; l++) {
                        list.add(row[j][i + l]);
                    }
                    if (contains(list))
                        answer = true;
                }
            }

            if (answer) {
                out.println("YES");
                return;
            }

            List<Integer> list = new ArrayList<>();
            List<Integer> list1 = new ArrayList<>();
            List<Integer> list2 = new ArrayList<>();
            List<Integer> list3 = new ArrayList<>();
            for (int i = 0; i < 4; i++) {
                if (i != 3) {
                    list.add(row[i][i]);
                    list3.add(row[i][i + 1]);
                }
                if (i != 0) {
                    list1.add(row[i][i]);
                    list2.add(row[i][i - 1]);
                }
            }
            answer = contains(list) || contains(list1) || contains(list2) || contains(list3);

            if (answer) {
                out.println("YES");
                return;
            }

            list.clear();
            list1.clear();
            list2.clear();
            list3.clear();

            for (int i = 3; i >= 0; i--) {
                if (3 - i != 3) {
                    list.add(row[3 - i][i]);
                    list3.add(row[3 - i][i - 1]);
                }
                if (3 - i != 0) {
                    list1.add(row[3 - i][i]);
                    list2.add(row[3 - i][i + 1]);
                }
            }

            answer = contains(list) || contains(list1) || contains(list2) || contains(list3);

            if (answer)
                out.println("YES");
            else {
                out.println("NO");
            }
        }

        private boolean contains(List<Integer> list) {
            int xS = 0;
            int dS = 0;
            for (int i = 0; i < 3; i++) {
                if (list.get(i) == 1)
                    xS++;
                else if (list.get(i) == 0)
                    dS++;
            }
            return xS == 2 && dS == 1;
        }

