public class B390 {

	public static void main(String[] args) {


		Scanner sc = new Scanner(System.in);

		char[][] t = new char[4][4];

		for(int i=0;i<4;i++){
			String s = sc.next();
			for(int j=0;j<4;j++){				
				t[i][j] = s.charAt(j);
			}			
		}

		String ans = "NO";
		for(int i=0;i<4;i++){
			for(int j=0;j<4;j++){				

				if(t[i][j]!='.')continue;

				t[i][j] = 'x';
				boolean b = check(t);
				if(b){
					ans = "YES";
					break;
				}
				t[i][j] = '.';

			}			
		}

		System.out.println(ans);
	}


	private static boolean check(char[][] t){

		for(int i=0;i<4;i++){
			for(int j=0;j<4;j++){				

				if(t[i][j]!='x')continue;


				if((i+2)<4 && t[i+1][j]=='x' && t[i+2][j]=='x'){
					return true;
				}

				if((i+2)<4 && (j+2)<4 && t[i+1][j+1]=='x' && t[i+2][j+2]=='x'){
					return true;
				}



				if((i+2)<4 && (j-2)>=0 && t[i+1][j-1]=='x' && t[i+2][j-2]=='x'){
					return true;
				}


				if((j+2)<4 && t[i][j+1]=='x' && t[i][j+2]=='x'){
					return true;
				}

			}			
		}		

		return false;


	}

}

import java.io.*;
import java.util.*;
import java.util.Scanner;
import java.util.StringTokenizer;

public class Main
{
    static class Reader
    {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public Reader()
        {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public Reader(String file_name) throws IOException
        {
            din = new DataInputStream(new FileInputStream(file_name));
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public String readLine() throws IOException
        {
            byte[] buf = new byte[1024]; 
            int cnt = 0, c;
            while ((c = read()) != -1)
            {
                if (c == '\n')
                    break;
                buf[cnt++] = (byte) c;
            }
            return new String(buf, 0, cnt);
        }

        public int nextInt() throws IOException
        {
            int ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do
            {
                ret = ret * 10 + c - '0';
            }  while ((c = read()) >= '0' && c <= '9');

            if (neg)
                return -ret;
            return ret;
        }

        public long nextLong() throws IOException
        {
            long ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + c - '0';
            }
            while ((c = read()) >= '0' && c <= '9');
            if (neg)
                return -ret;
            return ret;
        }

        public double nextDouble() throws IOException
        {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();

            do {
                ret = ret * 10 + c - '0';
            }
            while ((c = read()) >= '0' && c <= '9');

            if (c == '.')
            {
                while ((c = read()) >= '0' && c <= '9')
                {
                    ret += (c - '0') / (div *= 10);
                }
            }

            if (neg)
                return -ret;
            return ret;
        }

        private void fillBuffer() throws IOException
        {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1)
                buffer[0] = -1;
        }

        private byte read() throws IOException
        {
            if (bufferPointer == bytesRead)
                fillBuffer();
            return buffer[bufferPointer++];
        }

        public void close() throws IOException
        {
            if (din == null)
                return;
            din.close();
        }

		public String next() throws IOException
		{
			return readLine();
		}
    }

    public static void main(String[] args) throws IOException
    {
        Reader In = new Reader();

		char arr[][] = new char[4][];

		for(int i = 0 ; i < 4 ; i++)
		{
			String temp = In.next();

			arr[i] = temp.toCharArray();
		}

		String A[] = new String[14];

		int k = 0;

		for( k = 0 ; k < 4 ; k++)
		{
			A[k] = new String(arr[k]);
		}

		for(int j = 0 ; k < 8 ; k++,j++)
		{
			A[k] = "";

			for(int i = 0 ; i < 4 ; i++)
			{
				A[k] += arr[i][j];
			}
		}

		A[k] = "";

		for(int i = 0 ; i < 4 ; i++)
		{
			A[k] += arr[i][i];
		}

		k++;

		A[k] = "";

		for(int i = 0 ; i < 4 ; i++)
		{
			A[k] += arr[i][3-i];
		}

		k++;

		A[10] = "";
		A[10] += arr[1][0];
		A[10] += arr[2][1];
		A[10] += arr[3][2];

		A[11] = "";
