			for(int j = 0 ; j < 4 ; j++){
				if(check(i, j, grid)){
					System.out.println("YES");
					return;
				}
			}
		}
		System.out.println("NO");
	}
	static boolean check(int row, int col, char[][] grid){
		int count = 0, dot = 0;
		for(int i = row ; i < row+3 ; i++){
			if(inbounds(i, col)){
				if(grid[i][col] == 'x') count++;
				if(grid[i][col] == '.') dot++;
			}
		}
		if(count == 2 && dot == 1) return true;
		dot = 0;
		count = 0;
		for(int i = col ; i < col+3 ; i++){
			if(inbounds(row, i)){
				if(grid[row][i] == 'x') count++;
				if(grid[row][i] == '.') dot++;
			}
		}
		if(count == 2 && dot == 1) return true;
		dot = 0;
		count = 0;
		for(int i = row ; i > row-3 ; i--){
			if(inbounds(i, col)){
				if(grid[i][col] == 'x') count++;
				if(grid[i][col] == '.') dot++;
			}
		}
		if(count == 2 && dot == 1) return true;
		dot = 0;
		count = 0;
		for(int i = col ; i > col-3 ; i--){
			if(inbounds(row, i)){
				if(grid[row][i] == 'x') count++;
				if(grid[row][i] == '.') dot++;
			}
		}
		if(count == 2 && dot == 1) return true;
		dot = 0;
		count = 0;
		for(int i = row, j = col ; i > row-3 ; i--, j--){
			if(inbounds(i, j)){
				if(grid[i][j] == 'x') count++;
				if(grid[i][j] == '.') dot++;
			}
		}
		if(count == 2 && dot == 1) return true;
		dot = 0;
		count = 0;
		for(int i = row, j = col ; i > row-3 ; i--, j++){
			if(inbounds(i, j)){
				if(grid[i][j] == 'x') count++;
				if(grid[i][j] == '.') dot++;
			}
		}
		if(count == 2 && dot == 1) return true;
		dot = 0;
		count = 0;
		for(int i = row, j = col ; i < row+3 ; i++, j--){
			if(inbounds(i, j)){
				if(grid[i][j] == 'x') count++;
				if(grid[i][j] == '.') dot++;
			}
		}
		if(count == 2 && dot == 1) return true;
		dot = 0;
		count = 0;
		for(int i = row, j = col ; i < row+3 ; i++, j++){
			if(inbounds(i, j)){
				if(grid[i][j] == 'x') count++;
				if(grid[i][j] == '.') dot++;
			}
		}
		if(count == 2 && dot == 1) return true;
		return false;
	}
	static boolean inbounds(int row, int col){
		return row >= 0 && row < 4 && col >= 0 && col < 4;
	}
}

