import java.util.Scanner;

public class tictactoe {
	public static boolean isRow(char[][] array) {
		for(int i=0;i<4;i++) {
			if(isMatching(array[i][0], array[i][1], array[i][2])) {
				return true;
			} else if( isMatching(array[i][3], array[i][1], array[i][2])) {
				return true;
			}
		}
		return false;
	}

	public static boolean isCol(char[][] array) {
		for(int j=0;j<4;j++) {
			if(isMatching(array[0][j], array[1][j], array[2][j])) {
				return true;
			} else if(isMatching(array[3][j], array[1][j], array[2][j])) {
				return true;
			}
		}
		return false;
	}

	public static boolean isDiagonal(char[][] array) {
		if(isMatching(array[2][0], array[1][1], array[0][2])) {
			return true;
		} else if(isMatching(array[3][0], array[2][1], array[1][2])) {
			return true;
		} else if(isMatching(array[0][3], array[2][1], array[1][2])) {
			return true;
		} else if(isMatching(array[3][1], array[2][2], array[1][3])) {
			return true;
		} else if(isMatching(array[0][1], array[1][2], array[2][3])) {
			return true;
		} else if(isMatching(array[0][0], array[1][1], array[2][2])) {
			return true;
		} else if(isMatching(array[3][3], array[1][1], array[2][2])) {
			return true;
		} else if(isMatching(array[1][0], array[2][1], array[3][2])) {
			return true;
		}
		return false;
	}

	public static boolean isMatching(char a,char b,char c) {
		if(a=='x' && b=='x' && c=='.') {
			return true;
		} else if(b=='x' && c=='x' && a=='.') {
			return true;
