        private boolean valid(char[][] x) {
            for (int i = 0; i < 4; i++) {
                String next = new String(x[i]);
                if (ok(next)) {
                    return true;
                }
            }
            for (int i = 0; i < 4; i++) {
                String next = "";
                for (int j = 0; j < 4; j++) {
                    next += x[j][i];
                }
                if (ok(next)) {
                    return true;
                }
            }
            String main = "", secondary = "";
            for (int i = 0; i < 4; i++) {
                main += x[i][i];
                secondary += x[i][3 - i];
            }
            if (ok(main) || ok(secondary)) {
                return true;
            }
            String p = String.valueOf(new char[]{x[0][1], x[1][2], x[2][3]});
