import java.io.*;
import java.util.*;

public class Main {

    static char[][] map = new char[4][4];

    public static void main(String[] args) throws Exception {
        Reader in = new Reader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        int x = 0, o = 0;
        for (int i = 0; i < 4; i++) {
            map[i] = in.next().toCharArray();
            for (int j = 0; j < 4; j++) {
                if (map[i][j] == 'x') {
                    x++;
                } else if (map[i][j] == 'o') {
                    o++;
                }
            }
        }

        if (x == o) {
            out.println(check('x') ? "YES" : "NO");
        } else {
            out.println(check('o') ? "YES" : "NO");
        }

        out.flush();
        in.close();
        out.close();
    }

    private static boolean check(char x) {
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                if (can(i, j, x, 1, -1)) {
                    return true;
                }
                if (can(i, j, x, 1, 1)) {
                    return true;
                }
                if (can(i, j, x, 1, 0)) {
                    return true;
                }
                if (can(i, j, x, 0, 1)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean can(int x, int y, char c, int dx, int dy) {
        int nx, ny;
        int empty = 0, aim = 0;
        for (int i = 0; i < 3; i++) {
            nx = x + dx * i;
            ny = y + dy * i;
            if (nx >= 4 || ny >= 4 || nx < 0 || ny < 0) {
                return false;
            }
            if (map[nx][ny] == c) aim++;
            if (map[nx][ny] == '.') empty++;
        }
        return empty + aim == 3 && empty <= 1;
    }

    static class Reader {
        BufferedReader reader;
        StringTokenizer st;

        Reader(InputStreamReader stream) {
            reader = new BufferedReader(stream);
            st = null;
        }

        void close() throws IOException {
            reader.close();
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() throws IOException {
            return reader.readLine();
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

    }
}

