  static class TaskB {
    private static final int[] dX = new int[]{1, 0, 1, 1};
    private static final int[] dY = new int[]{0, 1, 1, -1};

    public void solve(int testNumber, InputReader in, OutputWriter out) {
      char[][] mp = new char[4][];
      int nX = 0, nO = 0;
      for (int i = 0; i < 4; i++) {
        mp[i] = in.nextChars();
        nX += count(mp[i], 'x');
        nO += count(mp[i], 'o');
      }
      char c = nX == nO ? 'x' : 'o';
      for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
          if (mp[i][j] == '.') {
            if (check(mp, i, j, c)) {
              out.println("YES");
              return;
            }
          }
        }
      }
      out.println("NO");
    }

    private int count(char[] chars, char x) {
      int s = 0;
      for (char c : chars) {
        if (c == 'x') {
          s++;
        }
      }
      return s;
    }

    private boolean check(char[][] mp, int x, int y, char c) {
      for (int k = 0; k < 4; k++) {
        int s = 1;
        for (int d = -1; d <= 1; d += 2) {
          for (int i = x + d * dX[k], j = y + d * dY[k];
               i >= 0 && i < 4 && j >= 0 && j < 4;
               i += d * dX[k], j += d * dY[k]) {
            if (mp[i][j] == c) {
              s++;
            } else {
              break;
            }
          }
        }
        if (s >= 3) {
          return true;
        }
      }
      return false;
    }

  }

  static class InputReader {
    public final BufferedReader reader;
    public StringTokenizer tokenizer = null;

    public InputReader(Reader reader) {
      this.reader = new BufferedReader(reader, 32767);
    }

    public InputReader(InputStream inputStream) {
      this(new InputStreamReader(inputStream));
    }

    public String next() {
      if (hasNext()) return tokenizer.nextToken();
      else throw new NoSuchElementException();
    }

    public char[] nextChars() {
      return next().toCharArray();
    }

    public boolean hasNext() {
      while (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          String nextLine = reader.readLine();
          if (nextLine == null) return false;
          tokenizer = new StringTokenizer(nextLine);
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return tokenizer.hasMoreTokens();
    }

  }

