import java.util.Scanner;

public class IllyaTicTacToe {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] g = new char[4][4];
        for(int i = 0; i < 4; i++) {
            char[] temp = scanner.next().toCharArray();
            System.arraycopy(temp, 0, g[i], 0, 4);
        }
        boolean win = false;
        for(int i = 0; i < 4; i++)
            for (int j = 0; j < 4; j++)
                if (g[i][j] == '.') {
                    g[i][j] = 'x';
                    if (evaluate(g)) {
                        win = true;
                        break;
                    }
                    g[i][j] = '.';
                }
        if (win)
            System.out.println("YES");
        else
            System.out.println("NO");
    }

    private static boolean evaluate(char[][] g) {
        for(int i = 0; i < 4; i++)
            for (int j = 0; j < 4; j++) {
                int[] marks = new int[8];
                for (int k = 0; k < 3; k++) {
                    if (isX(g, i + k, j))
                        marks[0]++;
                    if (isX(g, i - k, j))
                        marks[1]++;
                    if (isX(g, i, j + k))
                        marks[2]++;
                    if (isX(g, i, j - k))
                        marks[3]++;
                    if(isX(g, i-k, j-k))
                        marks[4]++;
                    if (isX(g, i+k, j+k))
                        marks[5]++;
                    if (isX(g, i-k, j+k))
                        marks[6]++;
                    if (isX(g, i+k, j-k))
                        marks[7]++;
                }
                for (int k = 0; k < marks.length; k++)
                    if (marks[k] == 3)
                        return true;
            }
        return  false;
    }

    private static boolean isX(char[][] g, int i, int j) {
        if (i >= 0 && i <= 3 && j >= 0 && j <= 3)
            return g[i][j] == 'x';
        return false;
    }
}

