			out.println("YES");
		} else {
			out.println("NO");
		}

		System.err.println("time: " + (System.currentTimeMillis() - time0));
	}

	private boolean solve(int n, int m, String[] field) {
		int si = -1;
		int sj = -1;
		int fi = -1;
		int fj = -1;
		boolean[][] a = new boolean[n][m];
		for (int i = 0; i < n; i++) {
