				if (c == '.') {

				} else if (c == '*') {
					a[i][j] = true;
				} else if (c == 'S') {
					si = i;
					sj = j;
				} else if (c == 'T') {
					fi = i;
					fj = j;
				} else {
					throw new RuntimeException("Unknown character '" + c + "'");
				}
			}
		}
		boolean[][][][] b = new boolean[3][DX.length][n][m];
		int stHead = 0;
