			int oi = stI[stHead];
			int oj = stJ[stHead];

			int ni = oi + DX[od];
			int nj = oj + DY[od];
			if (ni >= 0 && ni < n && nj >= 0 && nj < m && !a[ni][nj] && !b[oc][od][ni][nj]) {
				b[oc][od][ni][nj] = true;
				stC[stHead] = oc;
				stD[stHead] = od;
				stI[stHead] = ni;
				stJ[stHead] = nj;
				stHead++;
			}

			if (oc + 1 < b.length) {
				for (int d = 0; d < DX.length; d++) {
					ni = oi + DX[d];
					nj = oj + DY[d];
					if (ni >= 0 && ni < n && nj >= 0 && nj < m && !a[ni][nj] && !b[oc + 1][d][ni][nj]) {
						b[oc + 1][d][ni][nj] = true;
						stC[stHead] = oc + 1;
						stD[stHead] = d;
						stI[stHead] = ni;
						stJ[stHead] = nj;
						stHead++;
					}
				}
			}
		}
		for (int c = 0; c < b.length; c++) {
			for (int d = 0; d < DX.length; d++) {
				if (b[c][d][fi][fj]) {
					return true;
				}
			}
		}
		return false;
	}

