    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            String field[] = new String[n];
            for (int i = 0; i < n; i++) {
                field[i] = in.next();
            }
            int[][] toT = new int[n][m];
            int[][] toS = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (field[i].charAt(j) == 'S') {
                        calc2(toS, field, i, j);
                    } else if (field[i].charAt(j) == 'T') {
                        calc1(toT, field, i, j);
                    }
                }
            }
            long ans = Integer.MAX_VALUE;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    ans = Math.min(ans, (long) toT[i][j] + (long) toS[i][j]);
                }
            }
            if (ans >= Integer.MAX_VALUE) {
                out.println("NO");
            } else {
                out.println("YES");
            }
        }

        void calc1(int[][] to, String[] field, int r, int c) {
            for (int i = 0; i < to.length; i++) {
                Arrays.fill(to[i], Integer.MAX_VALUE);
            }
            to[r][c] = 0;
            for (int i = 1; i + r < to.length; i++) {
                if (field[i + r].charAt(c) == '*') break;
                to[i + r][c] = i;
                for (int j = 1; c + j < to[0].length; j++) {
                    if (field[i + r].charAt(c + j) == '*') break;
                    to[i + r][c + j] = i + j;
                }
                for (int j = 1; j <= c; j++) {
                    if (field[i + r].charAt(c - j) == '*') break;
                    to[i + r][c - j] = i + j;
                }
            }
            for (int i = 1; i <= r; i++) {
                if (field[r - i].charAt(c) == '*') break;
                to[r - i][c] = i;
                for (int j = 1; c + j < to[0].length; j++) {
                    if (field[r - i].charAt(c + j) == '*') break;
                    to[r - i][c + j] = i + j;
                }
                for (int j = 1; j <= c; j++) {
                    if (field[r - i].charAt(c - j) == '*') break;
                    to[r - i][c - j] = i + j;
                }
            }
            for (int i = 1; i + c < to[0].length; i++) {
                if (field[r].charAt(c + i) == '*') break;
                to[r][c + i] = i;
                for (int j = 1; r + j < to.length; j++) {
                    if (field[r + j].charAt(c + i) == '*') break;
                    to[r + j][c + i] = i + j;
                }
                for (int j = 1; j <= r; j++) {
                    if (field[r - j].charAt(c + i) == '*') break;
                    to[r - j][c + i] = i + j;
                }
            }
            for (int i = 1; i <= c; i++) {
                if (field[r].charAt(c - i) == '*') break;
                to[r][c - i] = i;
                for (int j = 1; r + j < to.length; j++) {
                    if (field[r + j].charAt(c - i) == '*') break;
                    to[r + j][c - i] = i + j;
                }
                for (int j = 1; j <= r; j++) {
                    if (field[r - j].charAt(c - i) == '*') break;
                    to[r - j][c - i] = i + j;
                }
            }
        }

        void calc2(int[][] to, String[] field, int r, int c) {
            for (int i = 0; i < to.length; i++) {
                Arrays.fill(to[i], Integer.MAX_VALUE);
            }
            to[r][c] = 0;
            for (int i = 1; i + r < to.length; i++) {
                if (field[i + r].charAt(c) == '*') break;
                to[i + r][c] = i;
            }
            for (int i = 1; i <= r; i++) {
                if (field[r - i].charAt(c) == '*') break;
                to[r - i][c] = i;
            }
            for (int i = 1; i + c < to[0].length; i++) {
                if (field[r].charAt(c + i) == '*') break;
                to[r][c + i] = i;
            }
            for (int i = 1; i <= c; i++) {
                if (field[r].charAt(c - i) == '*') break;
                to[r][c - i] = i;
            }
        }

    }

