    private int m;
    private char[][] map;

    Solver() {
        read();
        String res = solve();
        System.out.println(res);
    }

    private String solve() {
        boolean[][] routeS = new boolean[n][m];
        boolean[][] routeT = new boolean[n][m];

        int xS = -1, yS = -1, xT = -1, yT = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map[i][j] == 'S') {
                    xS = j;
                    yS = i;
                } else if (map[i][j] == 'T') {
                    xT = j;
                    yT = i;
                }
            }
        }
        routeS[yS][xS] = true;
        routeT[yT][xT] = true;
        int i = yS;
        int j;
        for (j = xS + 1; j < m && map[i][j] != '*'; j++) {
            routeS[i][j] = true;
        }
        for (j = xS - 1; j >= 0 && map[i][j] != '*'; j--) {
            routeS[i][j] = true;
        }
        j = xS;
        for (i = yS + 1; i < n && map[i][j] != '*'; i++) {
            routeS[i][j] = true;
        }
        for (i = yS - 1; i >= 0 && map[i][j] != '*'; i--) {
            routeS[i][j] = true;
        }

        i = yT;
        for (j = xT + 1; j < m && map[i][j] != '*'; j++) {
            routeT[i][j] = true;
        }
        for (j = xT - 1; j >= 0 && map[i][j] != '*'; j--) {
            routeT[i][j] = true;
        }
        j = xT;
        for (i = yT + 1; i < n && map[i][j] != '*'; i++) {
            routeT[i][j] = true;
        }
        for (i = yT - 1; i >= 0 && map[i][j] != '*'; i--) {
            routeT[i][j] = true;
        }


        for (int k = 0; k < n; k++) {
            for (int l = 0; l < m; l++) {
                if (!routeS[k][l]) continue;
                i = k;
                for (j = l; j < m && map[i][j] != '*'; j++) {
                    if (routeT[i][j]) return "YES";
                }
                for (j = l - 1; j >= 0 && map[i][j] != '*'; j--) {
                    if (routeT[i][j]) return "YES";
                }
                j = l;
                for (i = k + 1; i < n && map[i][j] != '*'; i++) {
                    if (routeT[i][j]) return "YES";
                }
                for (i = k - 1; i >= 0 && map[i][j] != '*'; i--) {
                    if (routeT[i][j]) return "YES";
                }
            }
        }
        return "NO";
    }

