class Task {
	public static final int[] MR = { 0, 0, 1, -1 };
	public static final int[] MC = { 1, -1, 0, 0 };

	private PriorityQueue<Point> q;
	private boolean[][] visit;
	private char[][] arr;
	private int n;
	private int m;

	public void solve(int testNumber, InputReader in, OutputWriter out) {
		q = new PriorityQueue<Point>(new Comparator<Point>() {
			@Override
			public int compare(Point o1, Point o2) {
				return o1.getMc() < o2.getMc() ? -1 : 1;
			}
		});
		n = in.nextInt();
		m = in.nextInt();
		visit = new boolean[n][m];
		arr = new char[n][m];
		for (int i = 0; i < n; i++) {
			String line = in.next();
			for (int j = 0; j < m; j++) {
				arr[i][j] = line.charAt(j);
				if (arr[i][j] == 'S') {
					q.offer(new Point(i, j, -1, -1));
				}
			}
		}
		while (!q.isEmpty()) {
			Point p = q.poll();
			int r = p.getR();
			int c = p.getC();
			int d = p.getD();
			int mc = p.getMc();
			if (arr[r][c] == 'T') {
				out.print("YES");
				return;
			}
			if (visit[r][c]) {
				continue;
			}
			visit[r][c] = true;
			for (int i = 0; i < 4; i++) {
				int r2 = r + MR[i];
				int c2 = c + MC[i];
				if (0 <= r2 && r2 < n && 0 <= c2 && c2 < m && arr[r2][c2] != '*' && !visit[r2][c2]) {
					if (d == i) {
						q.offer(new Point(r2, c2, d, mc));
					} else {
						if (mc < 2) {
							q.offer(new Point(r2, c2, i, mc + 1));
						}
					}
				}
			}
		}
		out.print("NO");
	}

	class Point {
		private int r;
		private int c;
		private int d;
		private int mc;

		public Point(int r, int c, int d, int mc) {
			this.r = r;
			this.c = c;
			this.d = d;
			this.mc = mc;
		}

		public int getR() {
			return r;
		}

		public void setR(int r) {
			this.r = r;
		}

		public int getC() {
			return c;
		}

		public void setC(int c) {
			this.c = c;
		}

		public int getD() {
			return d;
		}

		public void setD(int d) {
			this.d = d;
		}

		public int getMc() {
			return mc;
		}

		public void setMc(int mc) {
			this.mc = mc;
		}
	}
}

class InputReader {
	private InputStream stream;
	private byte[] buf = new byte[1024];
	private int curChar;
	private int numChars;

	public InputReader(InputStream stream) {
		this.stream = stream;
	}

	public int read() {
		if (numChars == -1) {
			throw new InputMismatchException();
		} else {
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = stream.read(buf);
				} catch (IOException var2) {
					throw new InputMismatchException();
				}
				if (numChars <= 0) {
					return -1;
				}
			}
			return buf[curChar++];
		}
	}

	public boolean isSpace(int c) {
		return c == 10 || c == 13 || c == -1 || c == 9 || c == 32;
	}

	private boolean isEnd(int c) {
		return c == 10 || c == 13 || c == -1;
	}

	public String next() {
		int c = this.read();
		while (isSpace(c)) {
			c = this.read();
		}
		StringBuilder res = new StringBuilder();
		do {
			res.appendCodePoint(c);
		} while (!isSpace(c = this.read()));
		return res.toString();
	}

	public char nextChar() {
		int c = this.read();
		while (isSpace(c)) {
			c = this.read();
		}
		return (char) c;
	}

	public int nextInt() {
		int c = this.read();
		while (isSpace(c)) {
			c = this.read();
		}
		byte sgn = 1;
		if (c == 45) {
			sgn = -1;
			c = this.read();
		}
		int res = 0;
		while (c >= 48 && c <= 57) {
			res *= 10;
			res += c - 48;
			c = this.read();
			if (isSpace(c)) {
				return res * sgn;
			}
		}
		throw new InputMismatchException();
	}

	public long nextLong() {
		int c = this.read();
		while (isSpace(c)) {
			c = this.read();
		}
		byte sgn = 1;
		if (c == 45) {
			sgn = -1;
			c = this.read();
		}
		long res = 0;
		while (c >= 48 && c <= 57) {
			res *= 10;
			res += c - 48;
			c = this.read();
			if (isSpace(c)) {
				return res * sgn;
			}
		}
		throw new InputMismatchException();
	}

	public String nextLine() {
		int c = read();
		while (isEnd(c)) {
			c = this.read();
		}
		StringBuilder res = new StringBuilder();
		do {
			res.appendCodePoint(c);
		} while (!isEnd(c = this.read()));
		return res.toString();
	}

}

