	public static boolean xplore(int dir, int x, int y, short[][] s, boolean[][][][] p, int tleft, int n, int m){
		if(y < 0 || y >= n || x < 0 || x >= m){
			return false;
		}else if(s[y][x] == 2){

			return false;
		}else if(p[dir][tleft][y][x] == true){
			return false;
		}else{

			p[dir][tleft][y][x] = true;
			for(int i = tleft - 1; i >= 0; i--){
				for(int i2 = 0; i2 < 4; i2++){
					p[i2][i][y][x] = true;
				}
			}
			int found = 0;
			if(s[y][x] == 3){
				found++;
			}
			if(dir == 0){
				if(xplore(0, x, y + 1, s, p, tleft, n, m)){
					found++;
				}
			}else if(tleft > 0){
				if(xplore(0, x, y + 1, s, p, tleft - 1, n, m)){
					found++;
				}
			}

			if(dir == 1){
				if(xplore(1, x + 1, y, s, p, tleft, n, m)){
					found++;
				}
			}else if(tleft > 0){
				if(xplore(1, x + 1, y, s, p, tleft - 1, n, m)){
					found++;
				}
			}

			if(dir == 2){
				if(xplore(2, x, y - 1, s, p, tleft, n, m)){
					found++;
				}
			}else if(tleft > 0){
				if(xplore(2, x, y - 1, s, p, tleft - 1, n, m)){
					found++;
				}
			}

			if(dir == 3){
				if(xplore(3, x - 1, y, s, p, tleft, n, m)){
					found++;
				}
			}else if(tleft > 0){
				if(xplore(3, x - 1, y, s, p, tleft - 1, n, m)){
					found++;
				}
			}
			if(found > 0){
				return true;
			}else{
				return false;
			}
		}
	}
