    static class TaskB {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] map = in.nextCharacterMap(n, m);
            int sr = -1, sc = -1;
            int tr = -1, tc = -1;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (map[i][j] == 'S') {
                        sr = i;
                        sc = j;
                        map[i][j] = '.';
                    }
                    if (map[i][j] == 'T') {
                        tr = i;
                        tc = j;
                        map[i][j] = '.';
                    }
                }
            }
            int[] dr = new int[]{1, 0, -1, 0};
            int[] dc = new int[]{0, 1, 0, -1};
            int[][][] d = new int[4][n][m];
            ArrayUtils.fill(d, 99);
            Deque<int[]> q = new ArrayDeque<>();
            for (int j = 0; j < 4; j++) {
                d[j][sr][sc] = 0;
                q.add(new int[]{j, sr, sc});
            }
            while (!q.isEmpty()) {
                int[] cur = q.poll();
                int di = cur[0], r = cur[1], c = cur[2];
                if (r == tr && c == tc) {
                    out.println(d[di][tr][tc] <= 2 ? "YES" : "NO");
                    return;
                }
                for (int k = 0; k < 4; k++) {
                    int nr = r + dr[k], nc = c + dc[k];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < m && map[nr][nc] == '.') {
                        if (di == k) {
                            if (d[k][nr][nc] > d[di][r][c]) {
                                d[k][nr][nc] = d[di][r][c];
                                q.addFirst(new int[]{k, nr, nc});
                            }
                        } else {
                            if (d[k][nr][nc] > d[di][r][c] + 1) {
                                d[k][nr][nc] = d[di][r][c] + 1;
                                q.addLast(new int[]{k, nr, nc});
                            }
                        }
                    }
                }
            }
            out.println("NO");
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int pnumChars;
        private FastReader.SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (pnumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= pnumChars) {
                curChar = 0;
                try {
                    pnumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (pnumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c == ',') {
                    c = read();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char nextCharacter() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            return (char) c;
        }

        public char[] nextCharacterArray(int n) {
            char[] chars = new char[n];
            for (int i = 0; i < n; i++) {
                chars[i] = nextCharacter();
            }
            return chars;
        }

        public char[][] nextCharacterMap(int n, int m) {
            char[][] map = new char[n][];
            for (int i = 0; i < n; i++) {
                map[i] = nextCharacterArray(m);
            }
            return map;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class ArrayUtils {
        public static void fill(int[][] array, int value) {
            for (int[] row : array) {
                Arrays.fill(row, value);
            }
        }

        public static void fill(int[][][] array, int value) {
            for (int[][] subArray : array) {
                fill(subArray, value);
            }
        }

    }
}

