import java.io.BufferedReader;
import java.io.InputStream;


public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        private static final char START = 'S';
        private static final char END = 'T';
        private static final int INF = Integer.MAX_VALUE;
        private static final int[] dr = {0, -1, 0, 1};
        private static final int[] dc = {-1, 0, 1, 0};
        private static final char BLOCK = '*';
        private static final int THRESHOLD = 2;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int nRows = in.nextInt();
            int nCols = in.nextInt();
            char[][] grid = new char[nRows][];
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;
            for (int i = 0; i < nRows; ++i) {
                grid[i] = in.next().toCharArray();
                for (int j = 0; j < nCols; ++j) {
                    if (grid[i][j] == START) {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == END) {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            int[][][] minTurns = new int[nRows][nCols][dr.length];
            for (int[][] x : minTurns) for (int[] y : x) Arrays.fill(y, INF);

            List<TaskB.State> frontier = new ArrayList<>();
            for (int i = 0; i < dr.length; ++i) {
                minTurns[startRow][startCol][i] = 0;
                frontier.add(new TaskB.State(startRow, startCol, i));
            }

            while (!frontier.isEmpty()) {
                List<TaskB.State> next = new ArrayList<>();
                for (TaskB.State state : frontier) {
                    int currentTurns = minTurns[state.row][state.col][state.dir];


                    int row = state.row + dr[state.dir];
                    int col = state.col + dc[state.dir];
                    while (row >= 0 && row < nRows && col >= 0 && col < nCols && grid[row][col] != BLOCK && minTurns[row][col][state.dir] > currentTurns) {
                        minTurns[row][col][state.dir] = currentTurns;
                        next.add(new TaskB.State(row, col, state.dir));
                        row += dr[state.dir];
                        col += dc[state.dir];
                    }


                    if (currentTurns + 1 <= THRESHOLD) {
                        for (int dir = 0; dir < dr.length; ++dir) {
                            if (dir == state.dir) continue;
                            row = state.row + dr[dir];
                            col = state.col + dc[dir];
                            while (row >= 0 && row < nRows && col >= 0 && col < nCols && grid[row][col] != BLOCK && minTurns[row][col][dir] > currentTurns + 1) {
                                minTurns[row][col][dir] = currentTurns + 1;
                                next.add(new TaskB.State(row, col, dir));
                                row += dr[dir];
                                col += dc[dir];
                            }
                        }
                    }
                }
                frontier = next;
            }

            int result = INF;
            for (int i = 0; i < dr.length; ++i)
                result = Math.min(result, minTurns[endRow][endCol][i]);
            out.println((result <= THRESHOLD) ? "YES" : "NO");
        }

        private static class State {
            private int row;
            private int col;
            private int dir;

            private State(int r, int c, int d) {
                row = r;
                col = c;
                dir = d;
            }

        }

    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;
        private static final int BUFFER_SIZE = 32768;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(
                    new InputStreamReader(stream), BUFFER_SIZE);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        String[] split = scan.nextLine().split(" ");
        int m = Integer.valueOf(split[0]), n = Integer.valueOf(split[1]);
        int[][] grid = new int[m][n];
        int[] home = new int[2], office = new int[2];
        for(int i=0; i<m; ++i) {
            char[] arr = scan.nextLine().toCharArray();
            for(int j=0; j<n; ++j) {
                if(arr[j] == 'T') {
                    grid[i][j] = 0;
                    office[0] = i;
                    office[1] = j;
                } else if(arr[j] == 'S') {
                    grid[i][j] = 4;
                    home[0] = i;
                    home[1] = j;
                } else if(arr[j] == '.') grid[i][j] = 4;
                else grid[i][j] = -1;
            }
        }

		if(dewIt(grid, n, m, home[0], home[1], office[0], office[1])) {
			System.out.print("YES");
			return;
		}

		for(int i=0; i<m; ++i) {
			for(int j=0; j<n; ++j) {
				if(grid[i][j] == 1) {
					if(dewIt(grid, n, m, home[0], home[1], i, j)) {
						System.out.print("YES");
						return;
					}
				}
			}
		}

		for(int i=0; i<m; ++i) {
			for(int j=0; j<n; ++j) {
				if(grid[i][j] == 2) {
					if(dewIt(grid, n, m, home[0], home[1], i, j)) {
						System.out.print("YES");
						return;
					}
				}
			}
		}

		System.out.print("NO");
    }

	private static boolean dewIt(int[][] grid, int n, int m, int x, int y, int a, int b) {

		int p = grid[a][b] + 1;

		for(int i=a+1; i<m; ++i) {
			int j = b;
			if(grid[i][j] < p) break;
			else {
				if(i == x && j == y) return true;
				else grid[i][j] = p;
			}
		}

		for(int i=a-1; i>-1; --i) {
			int j = b;
			if(grid[i][j] < p) break;
			else {
				if(i == x && j == y) return true;
				else grid[i][j] = p;
			}
		}
		for(int j=b+1; j<n; ++j) {
			int i = a;
			if(grid[i][j] < p) break;
			else {
				if(i == x && j == y) return true;
				else grid[i][j] = p;
			}
		}
		for(int j=b-1; j>-1; --j) {
			int i = a;
			if(grid[i][j] < p) break;
			else {
				if(i == x && j == y) return true;
				else grid[i][j] = p;
			}
		}

		return false;
	}
}

import java.io.*;
