public class Main {
    public static void main(String[] args) throws FileNotFoundException {
        ConsoleIO io = new ConsoleIO(new InputStreamReader(System.in), new PrintWriter(System.out));



        new Main(io).solve();
        io.close();
    }

    ConsoleIO io;
    Main(ConsoleIO io) {
        this.io = io;
    }

    long MOD = 1_000_000_007;
    List<List<Integer>> gr = new ArrayList<>();

    public void solve() {
        int[] l = io.readIntArray();
        int n = l[0], m = l[1];
        char[][] map = new char[n][m];
        int rs = 0, cs = 0;
        for(int i = 0;i<n;i++) {
            map[i] = io.readLine().toCharArray();
            for (int j = 0; j < m; j++) {
                int v = map[i][j];
                if (v == 'S') {
                    rs = i;
                    cs = j;
                }
            }
        }

        int[] dr = {-1,0,1,0};
        int[] dc = {0,-1,0,1};

        int[] pos = new int[n*m*12+5];
        int[] dir = new int[pos.length];
        pos[0] = rs*m+cs;
        pos[1] = rs*m+cs;
        pos[2] = rs*m+cs;
        pos[3] = rs*m+cs;
        dir[0] = 0;
        dir[1] = 1;
        dir[2] = 2;
        dir[3] = 3;
        int[] visit = new int[n*m];
        visit[rs*m+cs] = (1<<15)-1;
        int head = 0;
        int tail = 4;
        while(head<tail){
            int v = pos[head];
            int d = dir[head++];
            int col = v%m;
            int row = v/m;
            if(map[row][col] == 'T'){
                io.writeLine("YES");
                return;
            }
            int dd = d%4;
            int time = d/4;
            for(int e = 0;e<4;e++) {
                int r = row + dr[e];
                int c = col + dc[e];
                if (time == 2 && e != dd) continue;
                if (r >= 0 && r < n && c >= 0 && c < m && map[r][c] != '*') {
                    int coor = r * m + c;
                    int flag = (time + (e != dd ? 1 : 0)) * 4 + e;
                    if ((visit[coor] & (1 << flag)) == 0) {
                        pos[tail] = coor;
                        dir[tail++] = flag;
                        visit[coor] |= 1 << flag;
                    }
                }
            }
        }

        io.writeLine("NO");
    }




}

class ConsoleIO {
    BufferedReader br;
    PrintWriter out;
    public ConsoleIO(Reader reader, PrintWriter writer){br = new BufferedReader(reader);out = writer;}
    public void flush(){this.out.flush();}
    public void close(){this.out.close();}
    public void writeLine(String s) {this.out.println(s);}
    public void writeInt(int a) {this.out.print(a);this.out.print(' ');}
    public void writeWord(String s){
        this.out.print(s);
    }
    public void writeIntArray(int[] a, int k, String separator) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < k; i++) {
            if (i > 0) sb.append(separator);
            sb.append(a[i]);
        }
        this.writeLine(sb.toString());
    }
    public int read(char[] buf, int len){try {return br.read(buf,0,len);}catch (Exception ex){ return -1; }}
    public String readLine() {try {return br.readLine();}catch (Exception ex){ return "";}}
    public long[] readLongArray() {
        String[]n=this.readLine().trim().split("\\s+");long[]r=new long[n.length];
        for(int i=0;i<n.length;i++)r[i]=Long.parseLong(n[i]);
        return r;
    }
    public int[] readIntArray() {
        String[]n=this.readLine().trim().split("\\s+");int[]r=new int[n.length];
        for(int i=0;i<n.length;i++)r[i]=Integer.parseInt(n[i]);
        return r;
    }
    public int[] readIntArray(int n) {
        int[] res = new int[n];
        char[] all = this.readLine().toCharArray();
        int cur = 0;boolean have = false;
        int k = 0;
        boolean neg = false;
        for(int i = 0;i<all.length;i++){
            if(all[i]>='0' && all[i]<='9'){
                cur = cur*10+all[i]-'0';
                have = true;
            }else if(all[i]=='-') {
                neg = true;
            }
            else if(have){
                res[k++] = neg?-cur:cur;
                cur = 0;
                have = false;
                neg = false;
            }
        }
        if(have)res[k++] = neg?-cur:cur;
        return res;
    }
    public int ri() {
        try {
            int r = 0;
            boolean start = false;
            boolean neg = false;
            while (true) {
                int c = br.read();
                if (c >= '0' && c <= '9') {
                    r = r * 10 + c - '0';
                    start = true;
                } else if (!start && c == '-') {
                    start = true;
                    neg = true;
                } else if (start || c == -1) return neg ? -r : r;
            }
        } catch (Exception ex) {
            return -1;
        }
    }
    public long readLong() {
        try {
            long r = 0;
            boolean start = false;
            boolean neg = false;
            while (true) {
                int c = br.read();
                if (c >= '0' && c <= '9') {
                    r = r * 10 + c - '0';
                    start = true;
                } else if (!start && c == '-') {
                    start = true;
                    neg = true;
                } else if (start || c == -1) return neg ? -r : r;
            }
        } catch (Exception ex) {
            return -1;
        }
    }
    public String readWord() {
        try {
            boolean start = false;
            StringBuilder sb = new StringBuilder();
            while (true) {
                int c = br.read();
                if (c!= ' ' && c!= '\r' && c!='\n' && c!='\t') {
                    sb.append((char)c);
                    start = true;
                } else if (start || c == -1) return sb.toString();
            }
        } catch (Exception ex) {
            return "";
        }
    }
    public char readSymbol() {
        try {
            while (true) {
                int c = br.read();
                if (c != ' ' && c != '\r' && c != '\n' && c != '\t') {
                    return (char) c;
                }
            }
        } catch (Exception ex) {
            return 0;
        }
    }

}

