import java.util.*;
import java.io.*;

public class L {
	static int[] dy= {0,1,0,-1};
	static int[] dx = {-1,0,1,0};
	static int up=1,right=2,down=3,left=4;
	static int [][][] visited;
	static char[][] graph;
	static pair end;

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] inp = br.readLine().split(" ");
		int n = Integer.parseInt(inp[0]);
		int m = Integer.parseInt(inp[1]);
		visited = new int[n][m][4];
		graph = new char[n][m];
		pair start= new pair(0,0);
		for(int i=0;i<n;i++)
		{
			String s = br.readLine();
			for(int j=0; j<m;j++)
				{
					for(int k=0;k<4;k++)visited[i][j][k]=n*m;
					graph[i][j]=s.charAt(j);
					if(s.charAt(j)=='*')
					{
						for(int k=0;k<4;k++)visited[i][j][k]=-1;
					}
					else if(s.charAt(j)=='S')
					{
						start = new pair(i,j);
					}
					else if(s.charAt(j)=='T')
					{
						end = new pair(i,j);
					}
				}		
		}
		for(int k=0;k<4;k++)visited[start.x][start.y][k]=0;
		fill(start , 1);
		fill(start , 2);
		fill(start , 3);
		fill(start , 4);
		boolean ans=false;
		for(int i=0;i<4;i++) {
			if(visited[end.x][end.y][i]<=2)
				ans=true;
		}
		if(ans)System.out.println("YES");
		else System.out.println("NO");

	}

	public static void fill(pair p1, int direction)
	{
		if(p1.x==end.x && p1.y==end.y)return;
		int turns = visited[p1.x][p1.y][direction-1];
		if(valid(p1.x+dx[0],p1.y+dy[0]))
		{
			if(direction !=up && visited[p1.x+dx[0]][p1.y+dy[0]][0] > turns+1 && turns<2)
			{
				visited[p1.x+dx[0]][p1.y+dy[0]][0]=turns+1;
				fill(new pair(p1.x+dx[0],p1.y+dy[0]) , up);
			}
			else if(direction == up && visited[p1.x+dx[0]][p1.y+dy[0]][0] > turns)
				{
				visited[p1.x+dx[0]][p1.y+dy[0]][0]=turns;
					fill(new pair(p1.x+dx[0],p1.y+dy[0]) , up );
				}
		}
		if(valid(p1.x+dx[1],p1.y+dy[1]))
		{
			if(direction !=right && visited[p1.x+dx[1]][p1.y+dy[1]][1] > turns+1 && turns<2)
			{
				visited[p1.x+dx[1]][p1.y+dy[1]][1]=turns+1;
				fill(new pair(p1.x+dx[1],p1.y+dy[1]) , right);
			}
			else if(direction == right && visited[p1.x+dx[1]][p1.y+dy[1]][1] > turns)
				{
				visited[p1.x+dx[1]][p1.y+dy[1]][1]=turns;
					fill(new pair(p1.x+dx[1],p1.y+dy[1]) , right);
				}
		}
		if(valid(p1.x+dx[2],p1.y+dy[2]))
		{
			if(direction !=down && visited[p1.x+dx[2]][p1.y+dy[2]][2] > turns+1 && turns<2)
			{
				visited[p1.x+dx[2]][p1.y+dy[2]][2]=turns+1;
				fill(new pair(p1.x+dx[2],p1.y+dy[2]) , down );
			}
			else if(direction == down && visited[p1.x+dx[2]][p1.y+dy[2]][2] > turns)
				{
				visited[p1.x+dx[2]][p1.y+dy[2]][2]=turns;
				fill(new pair(p1.x+dx[2],p1.y+dy[2]) , down );
				}
		}
		if(valid(p1.x+dx[3],p1.y+dy[3]))
		{
			if(direction !=left && visited[p1.x+dx[3]][p1.y+dy[3]][3] > turns+1 && turns<2)
			{
				visited[p1.x+dx[3]][p1.y+dy[3]][3]=turns+1;
				fill(new pair(p1.x+dx[3],p1.y+dy[3]) , left );
			}
			else if(direction == left && visited[p1.x+dx[3]][p1.y+dy[3]][3] > turns)
				{
				visited[p1.x+dx[3]][p1.y+dy[3]][3]=turns;
					fill(new pair(p1.x+dx[3],p1.y+dy[3]) , left );
				}
		}

	}


	public static boolean valid(int dx , int dy)
	{
		return (dy>=0) && (dy<visited[0].length) &&(dx>=0)&&(dx<visited.length);
	}

	static class pair
	{
		int x ,  y;
		public pair(int i , int j)
		{
			x=i;
			y=j;
		}
	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
