import java.util.StringTokenizer;


public class TinkoffB {
	public static void main(String[] args) {
		FS scan =new FS(System.in);
		int R = scan.nextInt(), C = scan.nextInt();
		char[][] mat = new char[R][C];

		int r1 = 0, c1 = 0, r2 = 0, c2 = 0;
		for(int i=0;i<R;i++){
			String line = scan.next();
			for(int j=0;j<C;j++){
				mat[i][j] = line.charAt(j);
				if(mat[i][j] == 'S'){
					r1=i;
					c1 = j;
				}
				if(mat[i][j] == 'T'){
					r2 = i;
					c2 = j;
				}
			}
		}

		int[][][] memo = new int[2][R][C];
		for(int i=0;i<2;i++)for(int j=0;j<R;j++)Arrays.fill(memo[i][j], 10);


		ArrayDeque<Integer> q = new ArrayDeque<>();
		q.add(r1);q.add(c1);q.add(0);
		q.add(r1);q.add(c1);q.add(1);

		int[][] dr = {{0,0},{-1,1}}, dc = {{-1,1},{0,0}};

		memo[0][r1][c1] = 0;
		memo[1][r1][c1] = 0;

		while(!q.isEmpty()){
			int r = q.pollFirst();
			int c = q.pollFirst();
			int d = q.pollFirst();

			for(int k=0;k<2;k++){
				int rr = r+dr[d][k], cc = c+dc[d][k];
				if(rr<0||rr>=R||cc<0||cc>=C||mat[rr][cc]=='*')continue;
				if(memo[d][rr][cc]>memo[d][r][c]){
					memo[d][rr][cc] = memo[d][r][c];
					q.addLast(rr);
					q.addLast(cc);
					q.addLast(d);
				}
			}
			if(memo[d][r][c] < 2) {
				for(int k=0;k<2;k++){
					int rr = r+dr[d^1][k], cc = c+dc[d^1][k];
					if(rr<0||rr>=R||cc<0||cc>=C||mat[rr][cc]=='*')continue;
					if(memo[d^1][rr][cc]>memo[d][r][c]+1){
						memo[d^1][rr][cc] = memo[d][r][c]+1;
						q.addLast(rr);
						q.addLast(cc);
						q.addLast(d^1);
					}
				}
			}
		}

		System.out.println(memo[0][r2][c2] <=2 || memo[1][r2][c2] <=2 ? "YES" : "NO");

	}
	private static class FS {
		BufferedReader br;
		StringTokenizer st;
		public FS(InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}
		String next(){
			while(st==null||!st.hasMoreElements()){
				try{st = new StringTokenizer(br.readLine());}
				catch(IOException e){e.printStackTrace();}
			}
			return st.nextToken();
		}
		int nextInt() {
			return Integer.parseInt(next());
		}
	}
}

import java.util.*;
public class CF_793B {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        StringTokenizer d = new StringTokenizer(s.nextLine());
        int n = Integer.parseInt(d.nextToken());
        int m = Integer.parseInt(d.nextToken());

        int[][] turns = new int[n][m];
        boolean[][] v = new boolean[n][m];

        for(int[] x : turns) Arrays.fill(x, 1 << 25);

        int[] start = new int[2];
        int[] end = new int[2];

        for(int i = 0; i < n; i++) {
            String line = s.nextLine();

            for(int j = 0; j < m; j++) {
                if(line.charAt(j) == 'S') {
                    start[0] = i;
                    start[1] = j;
                    continue;
                }

                if(line.charAt(j) == 'T') {
                    end[0] = i;
                    end[1] = j;
                    v[i][j] = true;
                    continue;
                }

                if(line.charAt(j) == '.') {
                    v[i][j] = true;
                }
            }
        }

        LinkedList<int[]> q = new LinkedList<int[]>();

        q.add(start);
        turns[start[0]][start[1]] = -1;
        while(!q.isEmpty()) {
            int d1 = 1, d2 = -1, d3 = 1, d4 = -1; 
            int[] focus = q.remove();
            int dist = turns[focus[0]][focus[1]];

            while(focus[0]+d1 >= 0 && focus[0]+d1 < n && v[focus[0]+d1][focus[1]] && turns[focus[0]+d1][focus[1]] > dist) {
                turns[focus[0]+d1][focus[1]] = dist+1;

                int[] next = {focus[0]+d1, focus[1]};
                q.add(next);
                d1++;
            }
            while(focus[0]+d2 >= 0 && focus[0]+d2 < n && v[focus[0]+d2][focus[1]] && turns[focus[0]+d2][focus[1]] > dist) {
                turns[focus[0]+d2][focus[1]] = dist+1;

                int[] next = {focus[0]+d2, focus[1]};
                q.add(next);
                d2--;
            }
            while(focus[1]+d3 >= 0 && focus[1]+d3 < m && v[focus[0]][focus[1]+d3] && turns[focus[0]][focus[1]+d3] > dist) {
                turns[focus[0]][focus[1]+d3] = dist+1;

                int[] next = {focus[0], focus[1]+d3};
                q.add(next);
                d3++;
            }
            while(focus[1]+d4 >= 0 && focus[1]+d4 < m && v[focus[0]][focus[1]+d4] && turns[focus[0]][focus[1]+d4] > dist) {
                turns[focus[0]][focus[1]+d4] = dist+1;

                int[] next = {focus[0], focus[1]+d4};
                q.add(next);
                d4--;
            }
        }



        if(turns[end[0]][end[1]] >= 0 && turns[end[0]][end[1]] <= 2) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }
}

