                a[i][y] = val;
            }

        }


    }

    int[][] solve(char[][] a, int c)
    {
        int[][] ans = new int[a.length][a[0].length];
        for (int i = 0; i < a.length; i++)
        {
            for (int j = 0; j < a[0].length; j++)
            {
                if (a[i][j] == c)
                {
                    a[i][j] = 1;
                    fill(a, ans,i,j,1);
                }
            }
        }
        for (int i = 0; i < a.length; i++)
        {
            for (int j = 0; j < a[0].length; j++)
            {
                if (ans[i][j] == 1)
                {
                    fill(a, ans, i,j, 2);
                }
            }
        }
        return ans;
    }

    public void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        char[][] a = new char[n][m];
        for (int i = 0; i < n; i++)
        {
            a[i] = next().toCharArray();
        }

        int[][] ans1 = solve(a, 'S');
        int[][] ans2 = solve(a, 'T');

        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < m; j++)
            {
                if (ans1[i][j] > 0 && ans2[i][j] > 0 && ans1[i][j] + ans2[i][j] < 4)
                {
                    out.println("YES");
                    return;
                }
            }
        }
        out.println("NO");

    }


    public static void main(String[] args) throws IOException {
        new A().run();
    }

    public void run() throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

