public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        FastPrinter out = new FastPrinter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, FastScanner in, FastPrinter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] c = in.readCharacterFieldTokens(n, m);
            int startX = -1;
            int startY = -1;
            int finishX = -1;
            int finishY = -1;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (c[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    } else if (c[i][j] == 'T') {
                        finishX = i;
                        finishY = j;
                    }
                }
            }
            int[] q = new int[n * m * 3 * 4];
            int head = 0;
            int tail = 0;
            boolean[][][][] was = new boolean[3][4][n][m];
            for (int dir = 0; dir < 4; dir++) {
                q[tail++] = (startX * m + startY) + dir * n * m;
                was[0][dir][startX][startY] = true;
            }
            final int[] DX = {1, 0, -1, 0};
            final int[] DY = {0, 1, 0, -1};
            while (head < tail) {
                int v = q[head++];
                int turn = v / (n * m * 4);
                int dir = v / (n * m) % 4;
                int cx = v / m % n;
                int cy = v % m;
                if (c[cx][cy] == 'T') {
                    out.println("YES");
                    return;
                }
                for (int nDir = 0; nDir < 4; nDir++) {
                    int nTurn = turn + (nDir == dir ? 0 : 1);
                    if (nTurn > 2) continue;
                    int nx = cx + DX[nDir];
                    int ny = cy + DY[nDir];
                    if (nx < 0 || ny < 0 || nx >= n || ny >= m || c[nx][ny] == '*' || was[nTurn][nDir][nx][ny])
                        continue;
                    was[nTurn][nDir][nx][ny] = true;
                    q[tail++] = nTurn * 4 * n * m + nDir * n * m + nx * m + ny;
                }
            }
            out.println("NO");
        }

    }

    static class FastPrinter extends PrintWriter {
        public FastPrinter(OutputStream out) {
            super(out);
        }

        public FastPrinter(Writer out) {
            super(out);
        }

    }

    static class FastScanner extends BufferedReader {
        public FastScanner(InputStream is) {
            super(new InputStreamReader(is));
        }


        public int read() {
            try {
                int ret = super.read();




                return ret;
            } catch (IOException e) {
                throw new InputMismatchException();
            }
        }

        public String next() {
            StringBuilder sb = new StringBuilder();
            int c = read();
            while (isWhiteSpace(c)) {
                c = read();
            }
            if (c < 0) {
                return null;
            }
            while (c >= 0 && !isWhiteSpace(c)) {
                sb.appendCodePoint(c);
                c = read();
            }
            return sb.toString();
        }

        static boolean isWhiteSpace(int c) {
            return c >= 0 && c <= 32;
        }

        public int nextInt() {
            int c = read();
            while (isWhiteSpace(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int ret = 0;
            while (c >= 0 && !isWhiteSpace(c)) {
                if (c < '0' || c > '9') {
                    throw new NumberFormatException("digit expected " + (char) c
                            + " found");
                }
                ret = ret * 10 + c - '0';
                c = read();
            }
            return ret * sgn;
        }

        public String readLine() {
            try {
                return super.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        public char[][] readCharacterFieldTokens(int n, int m) {
            char[][] ret = new char[n][];
            for (int i = 0; i < n; i++) {
                ret[i] = next().toCharArray();
                if (ret[i].length != m) {
                    throw new AssertionError("length expected " + m + ", found " + ret[i].length);
                }
            }
            return ret;
        }

    }
}

import java.util.*;
import java.io.*;

public class IgorWayToWork {

    String ans = "NO";
    boolean[][][] visited;
    int startx, starty, endx, endy;
    int n, m;

    public void dfs(int[][] board, int x, int y, int dir, int turns) {



        if (x == endx && y == endy) {
            ans = "YES";
        }

        if (ans.equals("YES")) {
            return;
        }

        visited[x][y][turns] = true;

        int[] chx = {x - 1, x, x + 1, x};
        int[] chy = {y, y - 1, y, y + 1};
        for (int i = 0; i < 4; ++i) {
            if (ans.equals("YES")) {
                return;
            }
            int tmpx = chx[i];
            int tmpy = chy[i];


            if (tmpx < 0 || tmpx >= n || tmpy < 0 || tmpy >= m) {
                continue;
            }

            if (board[tmpx][tmpy] == 1 && !visited[tmpx][tmpy][turns]) {
                if (dir == 1 && tmpy != y) {
                    if (turns < 2) dfs(board, tmpx, tmpy, 2, turns + 1);
                } else if (dir == 2 && tmpx != x) {
                    if (turns < 2) dfs(board, tmpx, tmpy, 1, turns + 1);
                } else {
                    int tmpdir = dir;
                    if (dir == 0) tmpdir = (tmpy != y) ? 2 : 1;
                    dfs(board, tmpx, tmpy, tmpdir, turns);
                }
            }
        }
    }

    public void run(BufferedReader br, PrintWriter pw) throws IOException {
        StringTokenizer st;
        st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());

        int[][] board = new int[n][m];
        for (int i = 0; i < n; ++i) {
            String s = br.readLine();
            for (int j = 0; j < m; ++j) {
                char c = s.charAt(j);
                if (c != '*') {
                    board[i][j] = 1;
                    if (c == 'S') {
                        startx = i;
                        starty = j;
                    }

                    if (c == 'T') {
                        endx = i;
                        endy = j;
                    }
                }
            }
        }

        visited = new boolean[n][m][3];
        dfs(board, startx, starty, 0, 0);

        pw.println(ans);

    }

    public static void main(String[] args) throws IOException {

        new IgorWayToWork().runStdIO();

    }

    public void runFileIO(String filename) throws IOException {
        BufferedReader br = new BufferedReader(new FileReader(filename + ".in"));
        PrintWriter pw = new PrintWriter(new BufferedWriter(new FileWriter(filename + ".out")));
        run(br, pw);
        pw.close();
    }

    public void runStdIO() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        run(br, pw);
        pw.close();
    }
}

import java.util.Scanner;

public class IgorToWork {
    static char [][] grid;
    static int endRow;
    static int endCol;

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        int m = scan.nextInt();

        grid = new char[n][m];
        int startRow = -1;
        int startCol = -1;

        for (int i = 0; i < n; i++) {
            String line = scan.next();
            for (int j = 0; j < m; j++) {
                Character cell = line.charAt(j);
                grid[i][j] = cell;
                if (cell == 'S') {
                    startRow = i;
                    startCol = j;
                }
                else if (cell == 'T') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        dfs(startRow, startCol - 1, 0, 'L');
        dfs(startRow, startCol + 1, 0, 'R');
        dfs(startRow - 1, startCol, 0, 'U');
        dfs(startRow + 1, startCol, 0, 'D');
        System.out.println("NO");
    }

    static void dfs(int row, int col, int numTurns, char dir) {

        if (row < 0 || col < 0 || row >= grid.length || col >= grid[0].length) {
            return;
        }


        if (numTurns >= 3) {
            return;
        }



        if (numTurns == 2 && (dir == 'L' || dir == 'R') && row != endRow) {
            return;
        }



        if (numTurns == 2 && (dir == 'U' || dir == 'D') && col != endCol) {
            return;
        }


        if (grid[row][col] == '*') {
            return;
        }


        if (grid[row][col] == 'T') {
            System.out.println("YES");
            System.exit(0);
        }


        if (dir == 'L') { 
            dfs(row, col - 1, numTurns, 'L');
            dfs(row - 1, col, numTurns + 1, 'U');
            dfs(row + 1, col, numTurns + 1, 'D');
        }


        if (dir == 'R') { 
            dfs(row, col + 1, numTurns, 'R');
            dfs(row - 1, col, numTurns + 1, 'U');
            dfs(row + 1, col, numTurns + 1, 'D');
        }


        if (dir == 'U') { 
            dfs(row - 1, col, numTurns, 'U');
            dfs(row, col - 1, numTurns + 1, 'L');
            dfs(row, col + 1, numTurns + 1, 'R');
        }


        if (dir == 'D') { 
            dfs(row + 1, col, numTurns, 'D');
            dfs(row, col - 1, numTurns + 1, 'L');
            dfs(row, col + 1, numTurns + 1, 'R');
        }
    }

}

