            return LEFT;
        }
        return -1;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(f.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] map = new char[n][m];



        int[][][] visited = new int[n][m][4];


        for (int[][] a : visited) {
            for (int[] b : a) {
                Arrays.fill(b, Integer.MAX_VALUE);
            }
        }


        int[] start = new int[4];

        for (int i = 0; i < n; i++) {
            String row = f.readLine();

            for (int j = 0; j < m; j++) {
                map[i][j] = row.charAt(j);
                if (map[i][j] == 'S') {


                    start[0] = i; start[1] = j;
                    start[2] = 0; 
                    start[3] = START;
                }
            }
        }


        int newRow;
        int newCol;

        Stack<int[]> stk = new Stack<>();
        stk.add(start);

        for (int[] move : MOVES) {
            newRow = start[0] + move[0];
            newCol = start[1] + move[1];
            if (newRow >= 0 && newRow < n && newCol >= 0
                && newCol < m && map[newRow][newCol] == '.') {
                    int[] newPos = new int[] {start[0] + move[0],
                        start[1] + move[1], 0, getDirectionCode(move[0], move[1])};

                    visited[newRow][newCol][getDirectionCode(move[0], move[1])] = 0;
                    stk.add(newPos);
            }


        }


        while(!stk.isEmpty()) {
            int[] spot = stk.pop();
            for (int[] move : MOVES) {

                newRow = spot[0] + move[0];
                newCol = spot[1] + move[1];

                if (!(newRow >= 0 && newRow < n && newCol >= 0 && newCol < m)) {continue;}


                int direction = getDirectionCode(move[0], move[1]);
                boolean changingDirection = direction != spot[3];
                int turns = changingDirection ? spot[2] + 1 : spot[2];


                if (visited[newRow][newCol][direction] <= turns) {

                    continue;
                }

                if (changingDirection && spot[2] == 2){continue;}

                if (map[newRow][newCol] == '.') {
                    visited[newRow][newCol][direction] = turns;
                    stk.add(new int[] {newRow, newCol, turns, direction});
                }
                else if (map[newRow][newCol] == 'T') {
                    System.out.println("YES");
                    return;
                }

            }
        }








        System.out.println("NO");

    }
}

