public class B {
    static char[][] grid;
    static int m,n,si,sj,ti,tj;
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n= Integer.parseInt(st.nextToken());
        m= Integer.parseInt(st.nextToken());
        grid = new char[n][m];
        for(int i=0;i<n;i++){
            grid[i]=br.readLine().toCharArray();
        }
        ti=0;tj=0;si=0;sj=0;
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(grid[i][j]=='S'){
                    si=i;
                    sj=j;
                }
                else if(grid[i][j]=='T'){
                    ti=i;
                    tj=j;
                }
            }
        }
        getPath(ti,tj,0,'u');
        getPath(ti,tj,0,'d');
        getPath(ti,tj,0,'l');
        getPath(ti,tj,0,'r');
        System.out.println("NO");

    }
    static void getPath(int x, int y, int turns, char dir){
        if(turns==3) return;
        if(turns==2 && (dir=='u' || dir=='d') && y!=sj) return;
        if(turns==2 && (dir=='l' || dir=='r') && x!=si) return;
        if(x==si && y==sj){
            System.out.println("YES");
            System.exit(0);
        }
        if(dir=='u'){
            if(x!=0 && grid[x-1][y]!='*'){
                getPath(x-1,y,turns,'u');
            }
            if(y!=0 && grid[x][y-1]!='*'){
                getPath(x,y-1,turns+1,'l');
            }
            if(y!=m-1 && grid[x][y+1]!='*'){
                getPath(x,y+1,turns+1,'r');
            }
        }
        else if(dir=='d'){
            if(x!=n-1 && grid[x+1][y]!='*'){
                getPath(x+1,y,turns,'d');
            }
            if(y!=0 && grid[x][y-1]!='*'){
                getPath(x,y-1,turns+1,'l');
            }
            if(y!=m-1 && grid[x][y+1]!='*'){
                getPath(x,y+1,turns+1,'r');
            }
        }
        else if(dir=='l'){
            if(x!=n-1 && grid[x+1][y]!='*'){
                getPath(x+1,y,turns+1,'d');
            }
            if(y!=0 && grid[x][y-1]!='*'){
                getPath(x,y-1,turns,'l');
            }
            if(x!=0 && grid[x-1][y]!='*'){
                getPath(x-1,y,turns+1,'u');
            } 
        }
        else if(dir=='r'){
            if(x!=0 && grid[x-1][y]!='*'){
                getPath(x-1,y,turns+1,'u');
            } 
            if(x!=n-1 && grid[x+1][y]!='*'){
                getPath(x+1,y,turns+1,'d');
            }
            if(y!=m-1 && grid[x][y+1]!='*'){
                getPath(x,y+1,turns,'r');
            }
        }
    }
}

