import java.util.StringTokenizer;

public class B {

	static BufferedReader in;
	static PrintWriter out;
	static StringTokenizer tok;

	static class IntDeque {

		int data[] = new int[3];
		int p1 = 0, p2 = 0;

		boolean isEmpty() {
			return p1 == p2;
		}

		int size() {
			return p2 - p1;
		}

		void adjust() {
			if (p1 == 0 || p2 == data.length) {
				int size = p2 - p1;
				int odata[] = data;
				if (data.length - size <= size) {
					data = new int[(odata.length << 1) + 1];
				}
				int npos = (data.length - size) >> 1;
				arraycopy(odata, p1, data, npos, size);
				p1 = npos;
				p2 = npos + size;
			}
		}

		void addFirst(int value) {
			adjust();
			data[--p1] = value;
		}

		void addLast(int value) {
			adjust();
			data[p2++] = value;
		}

		int removeFirst() {
			if (isEmpty()) {
				throw new AssertionError();
			}
			return data[p1++];
		}

		int removeLast() {
			if (isEmpty()) {
				throw new AssertionError();
			}
			return data[--p2];
		}

		void clear() {
			p1 = p2 = data.length >> 1;
		}
	}

	static final int DIJ[] = {0, 1, 0, -1, 0};

	static void solve() throws Exception {
		int n = nextInt();
		int m = nextInt();
		boolean map[][] = new boolean[n][m];
		int si = -1, sj = -1, ei = -1, ej = -1;
		for (int i = 0; i < n; i++) {
			String s = next();
			for (int j = 0; j < m; j++) {
				switch (s.charAt(j)) {
				case '.':
					map[i][j] = true;
					break;
				case 'S':
					map[i][j] = true;
					si = i;
					sj = j;
					break;
				case 'T':
					map[i][j] = true;
					ei = i;
					ej = j;
					break;
				}
			}
		}
		byte turns[][][] = new byte[4][n][m];
		for (byte a[][]: turns) {
			for (byte aa[]: a) {
				fill(aa, Byte.MAX_VALUE);
			}
		}
		IntDeque q = new IntDeque();
		for (int d = 0; d < 4; d++) {
			turns[d][si][sj] = 0;
			q.addLast((d << 20) | (si << 10) | sj);
		}
		do {
			int cur = q.removeFirst();
			int cd = cur >>> 20;
			int ci = (cur >> 10) & 0x3ff;
			int cj = cur & 0x3ff;
			int cturns = turns[cd][ci][cj];
			if (cturns > 2) {
				break;
			}
			int ni = ci + DIJ[cd], nj = cj + DIJ[cd + 1];
			if (ni >= 0 && ni < n && nj >= 0 && nj < m && map[ni][nj] && turns[cd][ni][nj] > cturns) {
				turns[cd][ni][nj] = (byte) cturns;
				q.addFirst((cd << 20) | (ni << 10) | nj);
			}
			for (int nd = 0; nd < 4; nd++) {
				if (turns[nd][ci][cj] > cturns + 1) {
					turns[nd][ci][cj] = (byte) (cturns + 1);
					q.addLast((nd << 20) | (ci << 10) | cj);
				}
			}
		} while (!q.isEmpty());
		int ans = Integer.MAX_VALUE;
		for (int d = 0; d < 4; d++) {
			ans = min(ans, turns[d][ei][ej]);
		}
		out.print(ans <= 2 ? "YES" : "NO");
	}

	static int nextInt() throws IOException {
		return parseInt(next());
	}

	static long nextLong() throws IOException {
		return parseLong(next());
	}

	static double nextDouble() throws IOException {
		return parseDouble(next());
	}

	static String next() throws IOException {
		while (tok == null || !tok.hasMoreTokens()) {
			tok = new StringTokenizer(in.readLine());
		}
		return tok.nextToken();
	}

	public static void main(String[] args) {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(new OutputStreamWriter(System.out));
			solve();
			in.close();
			out.close();
		} catch (Throwable e) {
			e.printStackTrace();
			exit(1);
		}
	}
}

import java.util.PriorityQueue;
import java.util.Scanner;

public class b {

	public static void main(String[] args) {

		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		int m = in.nextInt();
		PriorityQueue<Move> pq = new PriorityQueue<Move>();
		int[][] grid = new int[n + 2][m + 2];
		int startx = 0;
		int starty = 0;
		int endx = 0;
		int endy = 0;
		for (int i = 0; i < n; i++) {
			String s = in.next();
			for (int j = 0; j < m; j++) {
				grid[i + 1][j + 1] = s.charAt(j) == '*' ? 0 : 1;
				if (s.charAt(j) == 'S') {
					starty = i + 1;
					startx = j + 1;
				}
				if (s.charAt(j) == 'T') {
					endy = i + 1;
					endx = j + 1;
				}
			}
		}
		int[][][] dist = new int[4][n + 2][m + 2];
		for (int i = 0; i < dist.length; i++) {
			for (int j = 0; j < dist[i].length; j++) {
				for (int k = 0; k < dist[i][j].length; k++) {
					dist[i][j][k] = Integer.MAX_VALUE / 3;
				}
			}
		}
		int[] dx = { 0, 1, 0, -1 };
		int[] dy = { 1, 0, -1, 0 };
		for (int i = 0; i < 4; i++) {
			pq.add(new Move(starty, startx, i, 0));
			dist[i][starty][startx] = 0;
		}
		while (!pq.isEmpty()) {
			Move cur = pq.poll();

			if (dist[cur.dir][cur.y][cur.x] < cur.cost) {
				continue;
			}
			for (int i = -1; i < 2; i++) {
				int newdir = (cur.dir + i + 4) % 4;
				int newy = cur.y + dy[newdir];
				int newx = cur.x + dx[newdir];
				if (grid[newy][newx] == 0)
					continue;
				if (dist[newdir][newy][newx] > dist[cur.dir][cur.y][cur.x] + Math.abs(i)) {
					dist[newdir][newy][newx] = dist[cur.dir][cur.y][cur.x] + Math.abs(i);
					pq.add(new Move(newy, newx, newdir, dist[cur.dir][cur.y][cur.x] + Math.abs(i)));
				}
			}
		}
		for (int i = 0; i < 4; i++) {

			if (dist[i][endy][endx] <= 2) {
				System.out.println("YES");
				return;
			}
		}
		System.out.println("NO");
	}

	private static class Move implements Comparable<Move> {
		int y;
		int x;
		int dir;
		int cost;

		public Move(int y, int x, int dir, int cost) {
			this.y = y;
			this.x = x;
			this.dir = dir;
			this.cost = cost;
		}

		@Override
		public int compareTo(Move arg0) {

			return Integer.compare(cost, arg0.cost);
		}

		public String toString() {
			return dir + " <" + x + "," + y + "> " + cost;
		}

	}

}

