public class Ds {

	static char[][] adj;

	static int[] dx = {1,-1,0,0};
	static int[] dy = {0,0,1,-1};

	static int endR;
	static int endC;

	static Short[][][][] dp = new Short[4][1001][1001][4];
	static boolean[][] vis = new boolean[1001][1001];

	public static void main(String[] args) throws NumberFormatException, IOException {

		Scanner in = new Scanner(System.in);


























		String[] line = in.nextLine().split("\\s+");
		int r = Integer.parseInt(line[0]);
		int c = Integer.parseInt(line[1]);


		adj = new char[r][c];

		int r1 = -1;
		int c1 = -1;

		for(int i=0; i<r; i++) {
			String cur = in.nextLine();
			for(int j=0; j<c; j++) {
				adj[i][j] = cur.charAt(j);
				if(adj[i][j] == 'S') {
					r1 = i;
					c1 = j;
				}
				if(adj[i][j] == 'T') {
					endR = i;
					endC = j;
				}
			}
		}

		int good = 0;

		for(int i=0; i<4; i++) {
			good |= dfs(i, r1, c1, 0);
		}

		System.out.println(good == 1 ? "YES" : "NO");
	}

	private static int dfs(int dir, int r, int c, int turn) {


		if(turn > 2) {
			return 0;
		}

		if(adj[r][c] == 'T') {
			return 1;
		}

		if(dp[dir][r][c][turn] != null) {
			return dp[dir][r][c][turn];
		}

		vis[r][c] = true;
		int good = 0;

		for(int i=0; i<4; i++) {
			int nR = r + dx[i];
			int nC = c + dy[i];

			if(nR >= 0 && nC >= 0 && nR < adj.length && nC < adj[0].length && adj[nR][nC] != '*' && !vis[nR][nC]) {
				if(nR < r) {
					good |= dfs(0, nR, nC, turn + (dir == 0 ? 0 : 1));
				}
				else if(nR > r) {
					good |= dfs(2, nR, nC, turn + (dir == 2 ? 0 : 1));
				}
				else if(nC < c) {
					good |= dfs(3, nR, nC, turn + (dir == 3 ? 0 : 1));
				}
				else if(nC > c) {
					good |= dfs(1, nR, nC, turn + (dir == 1 ? 0 : 1));
				}
			}
		}

		vis[r][c] = false;
		return dp[dir][r][c][turn] = (short) good;

	}
}

