			charNPvalues();


			for (int i = 0; i < n; i++)
				for (int j = 0; j < m; j++) {
					if (charNP[i][j] == 'S') {
						xS = i;
						yS = j;
						charNP[i][j] = '.';
					}
					if (charNP[i][j] == 'T') {
						xT = i;
						yT = j;
						charNP[i][j] = '.';
					}
				}

			visitedDir = new boolean[4][3][n][m];

			for (int d=0; d<4; d++) 
				if (dfs(xS, yS, 0, d)) {
					System.out.println("YES");
					return;
				}
			System.out.println("NO");
		} catch (IOException e) {
			e.printStackTrace();
		}

	}

	public static boolean dfs(int x, int y, int turns, int dir) {
		if (x < 0 || x >= n || y<0 || y>=m || charNP[x][y] == '*' || turns > 2)
			return false;

		if (x == xT && y == yT)
			return true;

		if (visitedDir[dir][turns][x][y])
			return false;

		for (int d=0; d<4; d++)
			if ( dfs(x + dirX[d], y + dirY[d], turns + (dir == d ? 0 : 1), d ))
				return true;

		visitedDir[dir][turns][x][y] = true;

		return false;
	}

}

import java.io.*;
import java.util.*;

public class h {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = fs.nextInt(), m = fs.nextInt();
        char[][] g = new char[n][m];
        for(int i = 0; i < n; i++) g[i] = fs.nextCharArray();
        State start = null;
        for(int i =0 ; i <n; i++) {
            for(int j = 0; j < m; j++) {
                if(g[i][j] == 'S') {
                    start = new State(i, j);
                    break;
                }
            }
        }
        boolean res = BFS(g, 0, start);
        if(!res) res |= BFS(g, 1, start);
        if(!res) res |= BFS(g, 2, start);
        if(!res) res |= BFS(g, 3, start);

        out.println(res ? "YES" : "NO");

        out.close();
    }

    static boolean BFS (char[][] a, int dir, State start) {
        ArrayDeque<State> bfs = new ArrayDeque<>();
        start.dir = dir;
        bfs.add(start);
        int n = a.length, m = a[0].length;
        int[] dx = {1, -1, 0, 0}, dy = {0, 0, -1, 1};
        boolean[][][] V = new boolean[n][m][4];
        V[start.i][start.j][dir] = true;
        while(!bfs.isEmpty()) {
            State now = bfs.pollFirst();
            if(a[now.i][now.j] == 'T') {
                if(now.change < 3) return true;
                continue;
            }
            for(int i= 0; i < 4; i++) {
                int nx = now.i + dx[i], ny = now.j + dy[i];
                if(!good(nx, ny, n, m)) continue;
                if(a[nx][ny] == '*') continue;
                if(V[nx][ny][i]) continue;
                if(a[nx][ny] != 'T') V[nx][ny][i] = true;
                State add = new State(nx, ny);
                add.change = now.change;
                add.dir = i;
                if(i != now.dir) {
                    add.change++;
                    bfs.addLast(add);
                } else {
                    bfs.addFirst(add);
                }
            }
        }
        return false;
    }

    static boolean good (int i, int j, int n, int m) {
        return i >= 0 && j >= 0 && i < n && j < m;
    }

    static class State {
        int i, j, change, dir;
        State (int a, int b) {
            i = a; j = b;
            change = 0;
            dir = -1;
        }
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            try	{
                br = new BufferedReader(new InputStreamReader(System.in));
                st = new StringTokenizer("");
            } catch (Exception e){e.printStackTrace();}
        }

        public String next() {
            if (st.hasMoreTokens())	return st.nextToken();
            try {st = new StringTokenizer(br.readLine());}
            catch (Exception e) {e.printStackTrace();}
            return st.nextToken();
        }

        public int nextInt() {return Integer.parseInt(next());}

        public long nextLong() {return Long.parseLong(next());}

        public double nextDouble() {return Double.parseDouble(next());}

        public String nextLine() {
            String line = "";
