public class B {

	class Data{
		int x,y,d;
		Data(){

		}
		Data(int x,int y,int d){
			this.x=x;
			this.y=y;
			this.d=d;
		}
	}
	static int row,col;
	static int[] xx={0,1,-1,0};
	static int[] yy={1,0,0,-1};
	static int[][][] dp;
	static String[] grid; 
	static void init(){
		grid=new String[row];
		dp=new int[row][col][4];
		for (int i = 0; i < row; i++) {
			for (int j = 0; j < col; j++) {
				for (int k = 0; k < 4; k++) {
					dp[i][j][k] = 100; 
				}
			}
		}
	}

	public static void main(String[] args) {

		String res[]={"NO","YES"};
		Scanner scan=new Scanner(System.in);
		row=scan.nextInt();
		col=scan.nextInt();
		init();
		int x=0;
		int y=0;
		for (int i = 0; i < row; i++) {
			grid[i]=scan.next();
			for (int j = 0; j < col; j++) {
				if(grid[i].charAt(j)=='S'){
					x=i;
					y=j;
					break;
				}
			}
		}
		System.out.println(res[solve(x,y)?1:0]);
		scan.close();
	}

	static boolean solve(int x,int y){
		Queue q = new LinkedList();
		for(int i=0;i<4;i++){
			q.add(new B().new Data(x,y,i));
			dp[x][y][i]=0;
		}
		while(!q.isEmpty()){
			Data data = (Data)q.element();
			q.remove();
			if(grid[data.x].charAt(data.y)=='T' && dp[data.x][data.y][data.d]<=2) return true;
			for (int i = 0; i < 4; i++) {
				x=data.x+xx[i];
				y=data.y+yy[i];
				if(x<0 || y<0 || x>=row || y>=col){
					continue;
				}
				if(grid[x].charAt(y)=='*') continue;
				int cost=dp[data.x][data.y][data.d]+(i!=data.d?1:0);
				if(dp[x][y][i]<=cost) continue;
				dp[x][y][i]=cost;
				q.add(new B().new Data(x,y,i));
			}
		}
		return false;

	}
}

