    static char[][] g;

    static boolean valid(int i, int j)
    {
	return i >= 0 && i < n && j >= 0 && j < m && g[i][j] != '*';
    }

    static boolean dfs(int i, int j, int d)
    {
	if (i == tx && j == ty)
	    return true;
	boolean flag = false;
	for (int k = 0; k < dx.length && !flag; k++)
	{
	    int mx = i + dx[k], my = j + dy[k], tur = vis[i][j][d] + (k == d ? 0 : 1);
	    if (valid(mx, my) && tur <= 2 && tur < vis[mx][my][k])
	    {
		vis[mx][my][k] = tur;
		flag |= dfs(mx, my, k);
	    }
	}
	return flag;
    }

