        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        FastScanner in=new FastScanner(br);
        solve(in);



    }

    static char[][] maze;
    static boolean[][][][] v;
    static int n,m;

    static int[] dr = {1,-1,0,0};
    static int[] dc = {0,0, 1,-1};

    private static void solve(FastScanner in) throws Exception {
        n = in.nextInt();
        m = in.nextInt();

        maze = new char[n][m];

        for(int i=0;i<n;i++) {
            String s = in.next();
            maze[i] = s.toCharArray();

        }

        int sr=-1,sc=-1;
        for(int i=0;i<n;i++) {
            for(int j=0;j<m;j++) {
                if (maze[i][j] == 'S') {
                    sr=i;sc=j;
                    break;
                }
            }
        }
        v = new boolean[n][m][3][5];
        System.out.println(dfs(sr,sc, 0, 4) ? "YES" : "NO");
    }


    static boolean dfs(int cr,int cc, int turns, int lm) {



        if (v[cr][cc][turns][lm]) return false;

        if (maze[cr][cc]=='T') {
            return turns <= 2;
        }


        v[cr][cc][turns][lm] = true;


        for(int i=0;i<4;i++) {
            int nr = cr+dr[i];
            int nc = cc+dc[i];
            boolean turnneeded = turnnee(lm, i);

            if (!valid(nr, nc)) continue;
            if (maze[nr][nc]=='*') continue;
            if (turns == 2 && turnneeded) continue;
            if (dfs(nr,nc, turns +  (turnneeded ? 1: 0), i)) return true;
        }

        return false;
    }

    private static boolean turnnee(int lm, int i) {
        if (lm==0 || lm==1) {
            return i>=2;
        } else if (lm==2 || lm==3) {
            return i <=1;
        }
        return false;
    }

    private static boolean valid(int nr, int nc) {
        return nr>=0 && nr < n && nc >=0 && nc < m;
    }


    private static int[] readIntArray(Scanner in, int n) {
        int[] a = new int[n];
        for(int i=0;i<n;i++)
            a[i] = in.nextInt();

        return a;
    }

    private static long getSum(long[] a) {
        long ret = 0;
        for (long l : a) {
            ret+=l;
        }
        return ret;
    }

