import java.util.*;


public class Main {
    private static boolean[][] city;
    private static int[][] used;
    private static int[] x = new int[]{0, 1, 0, -1};
    private static int[] y = new int[]{1, 0, -1, 0};

    private static boolean f(int x, int y, int count) {
        return (x < city.length && x >= 0 && y < city[0].length && y >= 0) && city[x][y] && used[x][y] >= count;
    }

    private static void bfs(int sx, int sy, int ex, int ey) {
        used[sx][sy] = 0;
        LinkedList<Integer> queue = new LinkedList<>();
        queue.add(sx);
        queue.add(sy);
        queue.add(0);
        queue.add(0);
        queue.add(sx);
        queue.add(sy);
        queue.add(1);
        queue.add(0);
        queue.add(sx);
        queue.add(sy);
        queue.add(2);
        queue.add(0);
        queue.add(sx);
        queue.add(sy);
        queue.add(3);
        queue.add(0);
        while (!queue.isEmpty()) {
            int cx = queue.pollFirst();
            int cy = queue.pollFirst();
            if (cx == ex && cy == ey) {
                System.out.println("YES");
                return;
            }
            int p = queue.pollFirst();
            int count = queue.pollFirst();
            if (f(cx + x[p], cy + y[p], count)) {
                queue.add(cx + x[p]);
                queue.add(cy + y[p]);
                queue.add(p);
                queue.add(count);
                used[cx + x[p]][cy + y[p]] = count;
            }
            if (count < 2) {
                int tmp_p = (p + 1) % 4;
                if (f(cx + x[tmp_p], cy + y[tmp_p], count + 1)) {
                    queue.add(cx + x[tmp_p]);
                    queue.add(cy + y[tmp_p]);
                    queue.add(tmp_p);
                    queue.add(count + 1);
                    used[cx + x[tmp_p]][cy + y[tmp_p]] = count + 1;
                }
                tmp_p = (p - 1 + 4) % 4;
                if (f(cx + x[tmp_p], cy + y[tmp_p], count + 1)) {
                    queue.add(cx + x[tmp_p]);
                    queue.add(cy + y[tmp_p]);
                    queue.add(tmp_p);
                    queue.add(count + 1);
                    used[cx + x[tmp_p]][cy + y[tmp_p]] = count + 1;
                }
            }
        }
        System.out.println("NO");
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int m = in.nextInt();
        int sx = 0, sy = 0, ex = 0, ey = 0;
        city = new boolean[n][m];
        used = new int[n][m];
        for (int i = 0; i < n; i++) {
            String row = in.next();
            for (int j = 0; j < m; j++) {
                used[i][j] = Integer.MAX_VALUE;
                if (row.charAt(j) == 'S') {
                    sx = i;
                    sy = j;
                    city[i][j] = true;
                } else if (row.charAt(j) == 'T') {
                    ex = i;
                    ey = j;
                    city[i][j] = true;
                } else if (row.charAt(j) == '.') {
                    city[i][j] = true;
                } else {
                    city[i][j] = false;
                }
            }
        }
        bfs(sx, sy, ex, ey);
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.io.IOException;
import java.io.InputStream;


public class Main {
  public static void main(String[] args) {
    InputStream inputStream = System.in;
    OutputStream outputStream = System.out;
    InputReader in = new InputReader(inputStream);
    PrintWriter out = new PrintWriter(outputStream);
    TaskB solver = new TaskB();
    solver.solve(1, in, out);
    out.close();
  }

  static class TaskB {
    private boolean[][][][] dp;
    private boolean[][][][] visited;
    int[] x = {0, 1, 0, -1};
    int[] y = {1, 0, -1, 0};

    public void solve(int testNumber, InputReader in, PrintWriter out) {
      int n = in.nextInt();
      int m = in.nextInt();
      String grid[] = new String[n];
      for (int i = 0; i < n; i++) {
        grid[i] = in.next();
      }
      dp = new boolean[n][m][4][3];
      visited = new boolean[n][m][4][3];
      int sti = -1;
      int stj = -1;
      for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
          if (grid[i].charAt(j) == 'S') {
            sti = i;
            stj = j;
            break;
          }
        }
      }
      for (int i = 0; i < 4; i++) {
        if (isPos(sti, stj, grid, i, 2)) {
          out.println("YES");
          return;
        }
      }
      out.println("NO");
    }

    private boolean isPos(int sti, int stj, String grid[], int currentDir, int turnLeft) {
      if (grid[sti].charAt(stj) == '*') {
        return false;
      }
      if (turnLeft < 0) {
        return false;
      }
      if (grid[sti].charAt(stj) == 'T') {
        return true;
      }
      if (visited[sti][stj][currentDir][turnLeft]) {
        return dp[sti][stj][currentDir][turnLeft];
      }
      boolean isPos = false;
      for (int i = 0; i < x.length; i++) {
        int ni = sti + x[i];
        int nj = stj + y[i];
        if (ni >= 0 && ni < grid.length && nj >= 0 && nj < grid[0].length()) {
          if (i == currentDir) {
            isPos |= isPos(ni, nj, grid, currentDir, turnLeft);
          } else {
            isPos |= isPos(ni, nj, grid, i, turnLeft - 1);
          }

        }
        if (isPos) break;
      }
      visited[sti][stj][currentDir][turnLeft] = true;
      dp[sti][stj][currentDir][turnLeft] = isPos;
      return isPos;

    }

  }

  static class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

    public int read() {
      if (numChars == -1)
        throw new InputMismatchException();
      if (curChar >= numChars) {
        curChar = 0;
        try {
          numChars = stream.read(buf);
        } catch (IOException e) {
          throw new InputMismatchException();
        }
        if (numChars <= 0)
          return -1;
      }
      return buf[curChar++];
    }

    public int readInt() {
      int c = read();
      while (isSpaceChar(c))
        c = read();
      int sgn = 1;
      if (c == '-') {
        sgn = -1;
        c = read();
      }
      int res = 0;
      do {
        if (c < '0' || c > '9')
          throw new InputMismatchException();
        res *= 10;
        res += c - '0';
        c = read();
      } while (!isSpaceChar(c));
      return res * sgn;
    }

    public String readString() {
      int c = read();
      while (isSpaceChar(c))
        c = read();
      StringBuffer res = new StringBuffer();
      do {
        res.appendCodePoint(c);
        c = read();
      } while (!isSpaceChar(c));
      return res.toString();
    }

    private boolean isSpaceChar(int c) {
      return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int nextInt() {
      return readInt();
    }

    public String next() {
      return readString();
    }

  }
}

