    int t = 1;

    for (int tc = 0; tc < t; tc++) {
      solve(tc);
    }
  }

  static long minv(long v) {
    return mpow(v, mod - 2);
  }

  static long mpow(long base, long exp) {
    long res = 1;

    while (exp > 0) {
      if ((exp & 1) == 1) {
        res = (res * base) % mod;
      }
      base = (base * base) % mod;
      exp >>= 1;
    }

    return res;
  }

  static int gcd(int x, int y) {
    if (x == 0) return y;
    if (y == 0) return x;
    return gcd(y % x, x);
  }

  static void rsort(long[] arr) {
    Random r = new Random();
    for (int i = 0; i < arr.length; i++) {
      int j = i + r.nextInt(arr.length - i);
      long t = arr[i];
      arr[i] = arr[j];
      arr[j] = t;
    }
    Arrays.sort(arr);
  }

  static void rsort(int[] arr) {
