    static class TaskB {
        int[] drow = {-1, 0, 1, 0};
        int[] dcol = {0, 1, 0, -1};

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int rows = in.readInt();
            int cols = in.readInt();
            char[][] tab = new char[rows][];
            for (int row = 0; row < rows; row++) {
                tab[row] = in.next().toCharArray();
            }
            int startRow = -1, startCol = -1;
            int finishRow = -1, finishCol = -1;
            for (int row = 0; row < rows; row++) {
                for (int col = 0; col < cols; col++) {
                    if (tab[row][col] == 'S') {
                        startRow = row;
                        startCol = col;
                    }
                    if (tab[row][col] == 'T') {
                        finishRow = row;
                        finishCol = col;
                    }
                }
            }
            ArrayDeque<State> ll = new ArrayDeque<>();
            for (int dir = 0; dir < 4; dir++) {
                ll.addLast(new State(startRow, startCol, dir, 0));
            }
            boolean[][][] visited = new boolean[rows][cols][4];
            while (!ll.isEmpty()) {
                State state = ll.pollFirst();
                if (state.row == finishRow && state.col == finishCol) {
                    out.printLine("YES");
                    return;
                }
                if (visited[state.row][state.col][state.dir]) continue;
                visited[state.row][state.col][state.dir] = true;
                for (int dir = 0; dir < 4; dir++) {
                    int nrow = state.row + drow[dir];
                    int ncol = state.col + dcol[dir];
                    if (MiscUtils.isValidCell(nrow, ncol, rows, cols) && tab[nrow][ncol] != '*') {
                        if (dir == state.dir) {
                            ll.addFirst(new State(nrow, ncol, dir, state.turns));
                        } else {
                            if (state.turns <= 1) {
                                ll.addLast(new State(nrow, ncol, dir, state.turns + 1));
                            }
                        }
                    }
                }
            }
            out.printLine("NO");
        }

        class State {
            int row;
            int col;
            int dir;
            int turns;

            public State(int row, int col, int dir, int turns) {
                this.row = row;
                this.col = col;
                this.dir = dir;
                this.turns = turns;
            }
        }
    }
    static class MiscUtils {
        public static boolean isValidCell(int row, int column, int rowCount, int columnCount) {
            return row >= 0 && row < rowCount && column >= 0 && column < columnCount;
        }
    }
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }
    }
    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return readString();
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }
}

