static int ey;
static boolean[][]jl;
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		PrintWriter pw = new PrintWriter(System.out);
		while (sc.hasNext()) {
			n=sc.nextInt();
			m=sc.nextInt();
			maze=new char[n][m];
			jl=new boolean[n][m];
			int dx=0;
			int dy=0;
			flag=false;
			for(int i=0;i<n;i++){
				String s=sc.next();
				for(int j=0;j<m;j++){
					maze[i][j]=s.charAt(j);
					if(maze[i][j]=='S'){
						dx=i;
						dy=j;
					}
					else if(maze[i][j]=='T'){
						ex=i;
						ey=j;
					}
				}
			}
			dfs(dx,dy,-1,0);
			if(flag)pw.println("YES");
			else pw.println("NO");
			pw.flush();
		}
	}
static void dfs(int i,int j,int pre,int turn){
	if(i<0||i>=n||j<0||j>=m) return;
	if(turn>=3)return;
	if(turn==2){
		if(pre==0){
			if(i!=ex)return;
		}
		else if(pre==1){
			if(j!=ey)return;
		}else if(pre==2){
			if(i!=ex)return;
		}else if(pre==3){
			if(j!=ey)return;
		}
	}
	if(maze[i][j]=='*'||jl[i][j]) return;
	if(maze[i][j]=='T'){
		if(turn<=2){
			flag=true;
		}
		return;
	}
	jl[i][j]=true;
	if(pre==-1){
		dfs(i,j-1,0,turn);
		if(check(i,j-1))
		jl[i][j-1]=false;
		dfs(i-1,j,1,turn);
		if(check(i-1,j))
		jl[i-1][j]=false;
		dfs(i,j+1,2,turn);
		if(check(i,j+1))
		jl[i][j+1]=false;
		dfs(i+1,j,3,turn);
		if(check(i+1,j))
		jl[i+1][j]=false;
	}
	else if(pre==0){
		dfs(i,j-1,0,turn);
		if(check(i,j-1))
		jl[i][j-1]=false;
		dfs(i-1,j,1,turn+1);
		if(check(i-1,j))
		jl[i-1][j]=false;
		dfs(i,j+1,2,turn+1);
		if(check(i,j+1))
		jl[i][j+1]=false;
		dfs(i+1,j,3,turn+1);
		if(check(i+1,j))
		jl[i+1][j]=false;
	}
	else if(pre==1){
		dfs(i,j-1,0,turn+1);
		if(check(i,j-1))
		jl[i][j-1]=false;
		dfs(i-1,j,1,turn);
		if(check(i-1,j))
		jl[i-1][j]=false;
		dfs(i,j+1,2,turn+1);
		if(check(i,j+1))
		jl[i][j+1]=false;
		dfs(i+1,j,3,turn+1);
		if(check(i+1,j))
		jl[i+1][j]=false;
	}
	else if(pre==2){
		dfs(i,j-1,0,turn+1);
		if(check(i,j-1))
		jl[i][j-1]=false;
		dfs(i-1,j,1,turn+1);
		if(check(i-1,j))
		jl[i-1][j]=false;
		dfs(i,j+1,2,turn);
		if(check(i,j+1))
		jl[i][j+1]=false;
		dfs(i+1,j,3,turn+1);
		if(check(i+1,j))
		jl[i+1][j]=false;
	}
	else if(pre==3){
		dfs(i,j-1,0,turn+1);
		if(check(i,j-1))
		jl[i][j-1]=false;
		dfs(i-1,j,1,turn+1);
		if(check(i-1,j))
		jl[i-1][j]=false;
		dfs(i,j+1,2,turn+1);
		if(check(i,j+1))
		jl[i][j+1]=false;
		dfs(i+1,j,3,turn);
		if(check(i+1,j))
		jl[i+1][j]=false;
	}
}
static boolean check(int i,int j){
	if(i<0||i>=n||j<0||j>=m) return false;
	return true;
}
}

