							count++;
						}else if(board[i-k][j-k].equals("O")){
							flag = false;
							break;
						}else if(board[i-k][j-k].equals(".")){
							ncount++;
						}
					}
					if(flag && ncount==1 && count>=3){
						System.out.println("YES");
						System.exit(0);
					}
				}
			}
		}
		System.out.println("NO");
	}

}

