public class Main {



	static class Solver {

		private final static int SIZE = 10;

		private static int[] dr = {0,1,1,1};
		private static int[] dc = {1,0,1,-1};

		public String solve() {
			Scanner in = new Scanner(System.in);

			char str[][] = new char [SIZE][SIZE];
			for (int i=0;i<SIZE;++i) {
				String tmp = in.next();
				for (int j=0;j<SIZE;++j) {
					str[i][j] = tmp.charAt(j);
				}
			}

			if (check(str)) {
				return "YES";
			}

			for (int i=0;i<SIZE;++i) {
				for (int j=0;j<SIZE;++j) {
					char save = str[i][j];
					if (save != '.')continue;
					str[i][j] = 'X';
					if (check(str)) {
						return "YES";
					}
					str[i][j] = save;
				}
			}
			return "NO";
		}


		private boolean check(char [][]str) {

			for (int i=0;i<SIZE;++i) {
				for (int j=0;j<SIZE;++j) {
					for (int d=0;d<4;++d) {
						int k;
						for (k=0;k<5;++k) {
							int r = i + k*dr[d];
							int c = j + k*dc[d];

							if (!valid(r,c) || str[r][c] != 'X') {
								break;
							}
						}
						if (k == 5){
							return true;
						}	
					}
				}
			}

			return false;
		}

		private boolean valid(int r,int c) {
			return r>=0 && r<SIZE && c>=0 && c<SIZE;
		}
	}

	public static void main(String []args) {
		System.out.println(new Solver().solve());
	}
}

import java.util.Scanner;

public class ProblemB {

	private static Scanner input;
	private static int[][] grid = new int[10][10];

	static boolean check(int i, int j) {
		return checkHorizontal(i) || checkVertical(j) || checkDiagonalLeft(i, j) || checkDiagonalRight(i, j);
	}

	static boolean checkHorizontal(int iCurrent) {
		for (int counter = 0; counter <= 5; counter++) {
			boolean found = true;
			for (int j = counter; j < counter + 5 && found; j++) {
				if (grid[iCurrent][j] != 1) {
					found = false;
				}
			}
			if (found) {
				return true;
			}
		}
		return false;
	}

	static boolean checkVertical(int jCurrent) {
		for (int counter = 0; counter <= 5; counter++) {
			boolean found = true;
			for (int i = counter; i < counter + 5 && found; i++) {
				if (grid[i][jCurrent] != 1) {
					found = false;
				}
			}
			if (found) {
				return true;
			}
		}
		return false;
	}

	static boolean checkDiagonalLeft(int iCurrent, int jCurrent) {

		while (iCurrent != 0 && jCurrent != 0) {
			iCurrent--;
			jCurrent--;
		}

		while (iCurrent + 5 - 1 < 10 && jCurrent + 5 - 1 < 10) {
			boolean found = true;
			for (int i = 0; i < 5 && found; i++) {
				if (grid[iCurrent + i][jCurrent + i] != 1) {
					found = false;
				}
			}
			if (found) {
				return true;
			}
			iCurrent++;
			jCurrent++;
		}

		return false;
	}

	static boolean checkDiagonalRight(int iCurrent, int jCurrent) {

		while (iCurrent != 0 && jCurrent != 10 - 1) {
			iCurrent--;
			jCurrent++;
		}

		while (iCurrent + 5 - 1 < 10 && jCurrent - 5 + 1 >= 0) {
			boolean found = true;
			for (int i = 0; i < 5; i++) {
				if (grid[iCurrent + i][jCurrent - i] != 1) {
					found = false;
				}
			}
			if (found) {
				return true;
			}
			iCurrent++;
			jCurrent--;
		}

		return false;
	}

	public static void main(String[] args) {

		input = new Scanner(System.in);

		for (int i = 0; i < 10; i++) {
			String line = input.nextLine();
			for (int j = 0; j < 10; j++) {
				Character currentC = line.charAt(j);
				if (currentC == 'X') {
					grid[i][j] = 1;
				} else if (currentC == 'O') {
					grid[i][j] = 2;
				} else {
					grid[i][j] = 0;
				}
			}
		}

		for (int i = 0; i < 10; i++) {
			for (int j = 0; j < 10; j++) {
				if (grid[i][j] == 0) {
					grid[i][j] = 1;
					if (check(i, j)) {
						checkDiagonalLeft(i, j);
						checkDiagonalRight(i, j);
						System.out.println("YES");
						return;
					}
					grid[i][j] = 0;
				}
			}
		}

		System.out.println("NO");

	}

}

