            for (x=10 ; x>=6 ; x--, y++) {
                if (board[r+y][x] == 1) xCount++;
                else if (board[r+y][x] == 0) dotCount++;
            } 
            if (xCount + dotCount == 5 && dotCount<2) {
                System.out.println("YES");
                return;
            }
            while (r+y <= 10 && x >= 1) {
                if (board[r+y][x] == 1) xCount++;
                else if (board[r+y][x] == 0) dotCount++;

                if (board[r+y-5][x+5] == 1) xCount--;
                else if (board[r+y-5][x+5] == 0) dotCount--;

                if (xCount + dotCount == 5  && dotCount<2) {
                    System.out.println("YES");
                    return;
                }
                x--;
                y++;
            }
        }

        for (int c=9 ; c>=5 ; c--) {
            xCount = 0;
            dotCount = 0;
            int x = 0,
                y = 1;
            for (x=0 ; x<5 ; x++, y++) {
                if (board[y][c-x] == 1) xCount++;
                else if (board[y][c-x] == 0) dotCount++;
            }
            if (xCount + dotCount == 5 && dotCount<2) {
                System.out.println("YES");
                return;
            }
            while (y <= 10 && c-x >= 1) {
                if (board[y][c-x] == 1) xCount++;
                else if (board[y][c-x] == 0) dotCount++;

                if (board[y-5][c-x+5] == 1) xCount--;
                else if (board[y-5][c-x+5] == 0) dotCount--;

                if (xCount + dotCount == 5 && dotCount<2) {
                    System.out.println("YES");
                    return;
                }
                x++; y++;
            }
        }
        System.out.println("NO");
    }
}

import java.io.OutputStream;
