    static boolean checkOne(char[] seq, int s)
    {
        int x=1;
        int dot=0;
        int end=s+1;

        for (; end<seq.length; end++) {
            if (seq[end]=='X') {
                x++;
            } else if (seq[end]=='.') {
                if (dot>0)
                    return false;
                dot++;            
            }
            else
                break;
            if (dot+x==5)
                break;            
        }
        if (x<4)
            return false;
        if (dot==1)
            return true;
        if ( s>0 && seq[s-1]=='.')
            return true;
        if (end==seq.length)
            return false;
        return seq[end]=='.';
    }

    static boolean scanSequence(char[] seq)
    {

        if (seq.length<5)
            return false;
        boolean skip=false;
        for (int i=0; i<seq.length; i++) {
            if (seq.length-i<4)
                return false;
            if (seq[i]=='X') {
                if (skip)
                    continue;
                if (checkOne(seq, i))
                    return true;
                skip=true;  
            } else
                skip=false;
        }
        return false;
    }
