import java.io.IOException;
import java.util.InputMismatchException;

public class FiveInARow {
	private static final int[] DR = { 1, 1, 1, 0 };
	private static final int[] DC = { -1, 0, 1, 1 };

	public static void main(String[] args) {
		FasterScanner sc = new FasterScanner();

		char[][] A = new char[10][];
		for (int i = 0; i < 10; ++i) {
			A[i] = sc.nextLine().toCharArray();
		}

		for (int r = 0; r < 10; ++r) {
			for (int c = 0; c < 10; ++c) {
				for (int d = 0; d < DR.length; ++d) {
					char[] p = new char[5];
					for (int i = 0; i < 5; ++i) {
						int nr = r + i * DR[d];
						int nc = c + i * DC[d];
						if (nr < 10 && nc >= 0 && nc < 10) {
							p[i] = A[nr][nc];
						}
					}
					if (win(p)) {
						System.out.println("YES");
						return;
					}
				}
			}
		}
		System.out.println("NO");
	}

	private static boolean win(char[] p) {
		int xc = 0;
		int dc = 0;
		for (char c : p) {
			switch (c) {
			case 'X':
				++xc;
				break;
			case '.':
				++dc;
				break;
			}
		}
		return xc == 4 && dc == 1;
	}

	public static class FasterScanner {
		private byte[] buf = new byte[1024];
		private int curChar;
		private int numChars;

		public int read() {
			if (numChars == -1)
				throw new InputMismatchException();
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = System.in.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (numChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		public String nextLine() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isEndOfLine(c));
			return res.toString();
		}

		public String nextString() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isSpaceChar(c));
			return res.toString();
		}

		public long nextLong() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = read();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			} while (!isSpaceChar(c));
			return res * sgn;
		}

		public int nextInt() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = read();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			} while (!isSpaceChar(c));
			return res * sgn;
		}

		public int[] nextIntArray(int n) {
			return nextIntArray(n, 0);
		}

		public int[] nextIntArray(int n, int off) {
			int[] arr = new int[n + off];
			for (int i = 0; i < n; i++) {
				arr[i + off] = nextInt();
			}
			return arr;
		}

		public long[] nextLongArray(int n) {
			return nextLongArray(n, 0);
		}

		public long[] nextLongArray(int n, int off) {
			long[] arr = new long[n + off];
			for (int i = 0; i < n; i++) {
				arr[i + off] = nextLong();
			}
			return arr;
		}

		private boolean isSpaceChar(int c) {
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		private boolean isEndOfLine(int c) {
			return c == '\n' || c == '\r' || c == -1;
		}
	}
}

import java.io.BufferedInputStream;
import java.util.Scanner;

public class Main {
	static Scanner scan = new Scanner(new BufferedInputStream(System.in));
	static char[][] Checkerboard = new char[10][10];
	static boolean winFlag = false;

	public static void main(String[] args) {
		while(scan.hasNext()){
			for(int i = 0;i<10;i++){
				String Line = scan.nextLine();
				for(int j = 0;j<10;j++){
					Checkerboard[i][j] = Line.charAt(j);
				}
			}
			winFlag = false; 
Traverse:
			for(int i = 0;i<10;i++){
				for(int j = 0;j<10;j++){
					if (Checkerboard[i][j] == '.' && Judge(i,j)){
						winFlag = true;
						break Traverse;
					}				
				}
			}
			if(winFlag) System.out.println("YES");
			else System.out.println("NO");

		}
	}
	public static boolean Judge(int i,int j){
		if (HorizontalJudge(i,j)){
			return true;}
		else if (VerticalJudge(i,j)){
			return true;}
		else if (Left_diagonalJudge(i,j)){
			return true;}
		else if (Right_diagonalJudge(i,j)){
			return true;}
		return false;

	}
	public static boolean HorizontalJudge(int i,int j){
		int cnt = 0;
		while( j<9 && Checkerboard[i][++j] == 'X'){
			cnt++;
		}
		if(j==9)j++;
		j=j-cnt-1;
		while( j>0 && Checkerboard[i][--j] == 'X'){
			cnt++;
		}

		if (cnt>=4)
			return true;	
		return false;
	}

	public static boolean VerticalJudge(int i,int j){
		int x = i,y = j;
		int cnt = 0;
		while( x<9 && Checkerboard[++x][y] == 'X'){
			cnt++;
		}
		x = i; y = j;
		while( x>0 && Checkerboard[--x][y] == 'X'){
			cnt++;
		}
		if (cnt>=4)
			return true;	
		return false;
	}

	public static boolean Left_diagonalJudge(int i,int j){
		int x = i,y = j;
		int cnt = 0;
		while( x<9 && y<9 && Checkerboard[++x][++y] == 'X'){
			cnt++;
		}
		x = i; y = j;
		while( x>0 && y>0 &&Checkerboard[--x][--y] == 'X'){
			cnt++;
		}
		if (cnt>=4)
			return true;	
		return false;	
	}

	public static boolean Right_diagonalJudge(int i,int j){
		int x = i,y = j;
		int cnt = 0;
		while( x<9 && y>0 && Checkerboard[++x][--y] == 'X'){
			cnt++;
		}
		x = i; y = j;
		while( x>0 && y<9 &&Checkerboard[--x][++y] == 'X'){
			cnt++;
		}
		if (cnt>=4)
			return true;	
		return false;	
	}

}

import java.io.*;    
import java.math.*;  
import java.util.*;  


public class Ed_2017_R25_B
{	
	FastReader in;
	PrintWriter out;

	public static void main(String[] args)  {
		new Ed_2017_R25_B().run();
	}

	void run()
	{		
		in = new FastReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.close();
	}

	static String[] s;

	void solve()
	{

		s = new String[10];
		for (int i = 0; i < 10; i++)
			s[i] = in.next();

		for (int i = 0; i < 10; i++)
			for (int j = 0; j < 10; j++)
				if (s[i].charAt(j) == '.')
				{
					if (checkRow(i,j) || checkCol(i,j) || checkDiag(i,j)) 
					{
						out.println("YES");
						return;
					}
				}

		out.println("NO");
	}

	private boolean checkRow(int i, int j)
	{
		for (int colStart = j-4; colStart <= j; colStart++)
		{
			int colEnd = colStart + 4;
			if (colStart >= 0 && colEnd < 10)
			{
				int cnt = 0;
				for (int k = colStart; k <= colEnd; k++)
					if (s[i].charAt(k) == 'X') cnt++;
				if (cnt == 4) return true;
			}
		}
		return false;
	}

	private boolean checkCol(int i, int j)
	{
		for (int rowStart = i-4; rowStart <= i; rowStart++)
		{
			int rowEnd = rowStart + 4;
			if (rowStart >= 0 && rowEnd < 10)
			{
				int cnt = 0;
				for (int k = rowStart; k <= rowEnd; k++)
					if (s[k].charAt(j) == 'X') cnt++;
				if (cnt == 4) return true;
			}
		}
		return false;
	}

	private boolean checkDiag(int i, int j)
	{
		for (int start = -4; start <= 0; start++)
		{
			int rowStart = i + start, rowEnd = rowStart + 4;
			int colStart = j + start, colEnd = colStart + 4;
			if (rowStart >= 0 && rowEnd < 10 && colStart >= 0 && colEnd < 10)
			{
				int cnt = 0;
				for (int k = 0; k <= 4; k++)
					if (s[rowStart + k].charAt(colStart + k) == 'X') cnt++;
				if (cnt == 4) return true;
			}
		}

		for (int start = -4; start <= 0; start++)
		{
			int rowStart = i + start, rowEnd = rowStart + 4;
			int colStart = j - start, colEnd = colStart - 4;
			if (rowStart >= 0 && rowEnd < 10 && colStart < 10 && colEnd >= 0)
			{
				int cnt = 0;
				for (int k = 0; k <= 4; k++)
					if (s[rowStart + k].charAt(colStart - k) == 'X') cnt++;
				if (cnt == 4) return true;
			}
		}
		return false;
	}


	void runWithFiles() {
		in = new FastReader(new File("input.txt"));
		try {
			out = new PrintWriter(new File("output.txt"));
		} 
		catch (FileNotFoundException e) {
			e.printStackTrace();
		}
		solve();
		out.close();
	}

	class FastReader
	{
	    BufferedReader br;
	    StringTokenizer tokenizer;

	    public FastReader(InputStream stream)
	    {
	        br = new BufferedReader(new InputStreamReader(stream));
	        tokenizer = null;
	    }
		public FastReader(File f) {
			try {
				br = new BufferedReader(new FileReader(f));
				tokenizer = null;
			}
			catch (FileNotFoundException e) {
				e.printStackTrace();
			}
		}

	    private String next() {
	        while (tokenizer == null || !tokenizer.hasMoreTokens())
	            try {
	            	tokenizer = new StringTokenizer(br.readLine());
	            }
	            catch (IOException e) {
	                throw new RuntimeException(e);
	            }
	        return tokenizer.nextToken();
	    }
		public String nextLine() {
			try	{
				return br.readLine();
			}
			catch(Exception e) {
				throw(new RuntimeException());
			}
		}

	    int nextInt() {
	        return Integer.parseInt(next());
	    }
	    long nextLong() {
	        return Long.parseLong(next());
	    }
	    double nextDouble() {
	        return Double.parseDouble(next());
	    }	    
	    BigInteger nextBigInteger() {
	        return new BigInteger(next());
	    }
	    BigDecimal nextBigDecimal() {
	        return new BigDecimal(next());
	    }
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class A implements Runnable {
	BufferedReader in;
	PrintWriter out;
	StringTokenizer tok = new StringTokenizer("");

	@Override
	public void run() {
		init();
		solve();
		out.close();
	}

	private void init() {
		in = new BufferedReader(new InputStreamReader(System.in));
		out = new PrintWriter(System.out);
	}

	private String readString() {
		while (!tok.hasMoreTokens()) {
			try {
				tok = new StringTokenizer(in.readLine());
			} catch (IOException e) {
				e.printStackTrace();
			}
		}
		return tok.nextToken();
	}

	private int readInt() {
		return Integer.parseInt(readString());
	}

	public static void main(String[] args) {
		new Thread(new A()).run();
	}

	private long readLong() {
		return Long.parseLong(readString());
	}

	private void solve() {
		int n = 10;
		char[][] ar = new char[n][n];
		for (int i = 0; i < n; i++) {
			ar[i] = readString().toCharArray();
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (ar[i][j] == '.' && check(ar, n, i, j)) {
					out.println("YES");
					return;
				}
			}
		}
		out.println("NO");

	}

	boolean check(char[][] input, int n, int startX, int startY) {
		int count = 0;
		if (checkHorizontal(input, n, startX, startY, count)) return true;

		count = 0;
		if (checkVertical(input[startX], n, startY, count)) return true;

		count = 0;
		for (int i = startX + 1, j = startY + 1; i < n && j < n && input[i][j] == 'X'; i++, j++)
			count++;
		for (int i = startX - 1, j = startY - 1; i >= 0 && j >= 0 && input[i][j] == 'X'; i--, j--)
			count++;
		if (count >= 4) {
			return true;
		}

		count = 0;
		for (int i = startX + 1, j = startY - 1; i < n && j >= 0 && input[i][j] == 'X'; i++, j--)
			count++;
		for (int i = startX - 1, j = startY + 1; i >= 0 && j < n && input[i][j] == 'X'; i--, j++)
			count++;
		return count >= 4;
	}

	private boolean checkVertical(char[] chars, int n, int startY, int count) {
		for (int j = startY + 1; j < n && chars[j] == 'X'; j++)
			count++;
		for (int j = startY - 1; j >= 0 && chars[j] == 'X'; j--)
			count++;
		if (count >= 4) {
			return true;
		}
		return false;
	}

	private boolean checkHorizontal(char[][] input, int n, int startX, int startY, int count) {
		for (int i = startX + 1; i < n && input[i][startY] == 'X'; i++)
			count++;
		for (int i = startX - 1; i >= 0 && input[i][startY] == 'X'; i--)
			count++;
		if (count >= 4) {
			return true;
		}
		return false;
	}
}

