            dots = 1;
        }

        return c + dots == 5;
    }

    static boolean isDia4(int x, int y) {
        int c = 0;
        int dots = 0;

        for (int i = 0; i < 5; i++) {
            try {
                if (arr[x - i][y + i] == 'X') {
                    c++;
                }
                if (arr[x - i][y + i] == '.') {
                    dots++;
                }
            } catch (Exception ex) {
                return false;
            }
        }
        if (dots > 0) {
            dots = 1;
        }

        return c + dots == 5;
    }

    static boolean is(int x, int y) {
        return isHozRight(x, y) || isHozRight(x, y) || isVerUp(x, y) || isVerDown(x, y) || isDia1(x, y) || isDia2(x, y) || isDia3(x, y) || isDia4(x, y);
    }

