public class CF825B 
{
	public static void main(String[] args)
	{
		CF825B task = new CF825B();
		Problem solver = task.new Problem();
		Scanner in = new Scanner(System.in);

		int n = 10;
		char[][] mat = new char[n][n];

		for(int y = 0; y < n; y++)
		{
			char[] temp = new char[n];
			String temps = in.next();
			temp = temps.toCharArray();
			for(int x = 0; x < n; x++)
			{
				mat[y][x] = temp[x];
			}
		}

		if(solver.solve(mat,n))
			System.out.println("YES");
		else
			System.out.println("NO");
	}

	public class Problem
	{

		public Problem()
		{

		}

		public char[][] fill(char[][] mat,int n)
		{
			char[][] ans = new char[n][n];

			for(int y = 0; y < n; y++)
			{
				for(int x = 0; x < n; x++)
				{
					ans[y][x] = mat[y][x];
				}
			}

			return ans;
		}

		public boolean solve(char[][] mat,int n)
		{
			boolean ans = false;

			for(int y = 0; y < n; y++)
			{
				for(int x = 0; x < n; x++)
				{
					char[][] dmat = fill(mat, n);
					if(checkAtPos(y, x, dmat, n, 5))
					{
						ans = true;
						y = n + 1;
						x = n + 1;
					}
				}
			}

			return ans;
		}

		public boolean checkAtPos(int _ys,int _xs,char[][] mat,int n,int lim)
		{
			boolean ans = false;

			int[] counter = new int[4];
			boolean[] skip = new boolean[4];

			skip[0] = true;
			for(int x = _xs; x < (_xs + lim) && x >= 0 && x < n; x++)
			{	
				if(mat[_ys][x] == 'X')
				{
					counter[0] = counter[0] + 1;
				}
				else
				if(mat[_ys][x] == '.' && skip[0] == true)
				{
					counter[0] = counter[0] + 1;
					skip[0] = false;
				}
				else
				{
					break;
				}
			}

			skip[1] = true;
			for(int y = _ys; y < (_ys + lim) && y >= 0 && y < n; y++)
			{	
				if(mat[y][_xs] == 'X')
				{
					counter[1] = counter[1] + 1;
				}
				else
				if(mat[y][_xs] == '.' && skip[1] == true)
				{
					counter[1] = counter[1] + 1;
					skip[1] = false;
				}
				else
				{
					break;
				}
			}

			skip[2] = true;
			for(int x = _xs,y = _ys; x < (_xs + lim) && y < (_ys + lim) && x >= 0 && x < n && y >= 0 && y < n; x++,y++)
			{
				if(mat[y][x] == 'X')
				{
					counter[2] = counter[2] + 1;
				}
				else
				if(mat[y][x] == '.' && skip[2] == true)
				{
					counter[2] = counter[2] + 1;
					skip[2] = false;
				}
				else
				{
					break;
				}
			}

			skip[3] = true;
			for(int x = _xs,y = _ys; x > (_xs - lim) && y < (_ys + lim) && x >= 0 && x < n && y >= 0 && y < n; x--,y++)
			{
				if(mat[y][x] == 'X')
				{
					counter[3] = counter[3] + 1;
				}
				else
				if(mat[y][x] == '.' && skip[3] == true)
				{
					counter[3] = counter[3] + 1;
					skip[3] = false;
				}
				else
				{
					break;
				}
			}

			for(int i = 0; i < counter.length; i++)
			{	
				if(counter[i] >= lim)
				{
					ans = true;
					break;
				}
			}

			return ans;
		}

	}
}

