        Scanner scanner = new Scanner(System.in);
        char[][] a = new char[10][10];
        for (int i = 0; i < 10; i++) {
            a[i] = scanner.next().toCharArray();
        }
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                if (a[i][j] != '.') continue;
                a[i][j] = 'X';
                int countX = 0;
                int countY = 0;
                for (int k = 0; k < 10; k++) {
                    if (a[i][k] == 'X') {
                        countX++;
                    } else {
                        countX = 0;
                    }
                    if (a[k][j] == 'X') {
                        countY++;
                    } else {
                        countY = 0;
                    }
                    if (countX == 5 || countY == 5) {
                        System.out.println("YES");
                        return;
                    }
                }
                int count = 0;
                for (int k = -5; k < 5; k++) {
                    int r = i + k;
                    int c = j + k;
                    if (r < 0 || c < 0) continue;
                    if (r > 9 || c > 9) break;
                    if (a[r][c] == 'X') {
                        count++;
                    } else {
                        count = 0;
                    }
                    if (count == 5) {
                        System.out.println("YES");
                        return;
                    }
                }
                count = 0;
                for (int k = -5; k < 5; k++) {
                    int r = i - k;
                    int c = j + k;
                    if (r > 9 || c < 0) continue;
                    if (r < 0 || c > 9) break;
                    if (a[r][c] == 'X') {
                        count++;
                    } else {
                        count = 0;
                    }
                    if (count == 5) {
                        System.out.println("YES");
                        return;
                    }
                }
                a[i][j] = '.';
            }
        }
        System.out.println("NO");
    }
}

