public class FiveInARow {

	public static boolean horizontal(char[][] table,int i,int j)
	{
		int limit = Math.min(10, j+5);
		int Xcount=0,dotcount=0;
		for(int k=j;k<limit;k++)
		{
			if(table[i][k]=='X')
				Xcount++;
			else if(table[i][k]=='.')
				dotcount++;
		}
		if(Xcount==4 && dotcount==1)
			return true;
		else
			return false;
	}

	public static boolean vertical(char[][] table,int i,int j)
	{
		int limit = Math.min(10, i+5);
		int Xcount=0,dotcount=0;
		for(int k=i;k<limit;k++)
		{
			if(table[k][j]=='X')
				Xcount++;
			else if(table[k][j]=='.')
				dotcount++;
		}
		if(Xcount==4 && dotcount==1)
			return true;
		else
			return false;
	}

	public static boolean diagonal(char[][] table,int i,int j)
	{
		int Xcount=0,dotcount=0;
