import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class FiveInRow {
    private static final int dimX = 10;
    private static final int dimY = 10;
    private static final char CROSS = 'X';
    private static final char ZERO = 'O';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = new char[dimY][dimX];
            for (int y = 0; y < dimY; y++) {
                String row = reader.readLine();
                for (int x = 0; x < dimX; x++) {
                    board[y][x] = row.charAt(x);
                }
            }
            boolean winInOneMove = false;
            for (int y = 0; y < dimY; y++) {
                for (int x = 0; x < dimX; x++ ) {
                    if (board[y][x] == CROSS && analyzePoint(board, x, y)) {
                        winInOneMove = true;
                        break;
                    }
                }
            }
            System.out.println((winInOneMove) ? "YES" : "NO");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static boolean analyzePoint(char[][] board, int x, int y) {
        if (board[y][x] != CROSS) {
            return false;
        }
        return analyzePoint(board, x, y, 0, false, Direction.LEFT) >= 5
                || analyzePoint(board, x, y, 0, false, Direction.RIGHT) >= 5
                || analyzePoint(board, x, y, 0, false, Direction.UP) >= 5
                || analyzePoint(board, x, y, 0, false, Direction.DOWN) >= 5
                || analyzePoint(board, x, y, 0, false, Direction.LEFT_UP) >= 5
                || analyzePoint(board, x, y, 0, false, Direction.RIGHT_UP) >= 5
                || analyzePoint(board, x, y, 0, false, Direction.LEFT_DOWN) >= 5
                || analyzePoint(board, x, y, 0, false, Direction.RIGHT_DOWN) >= 5;
    }

    private static int analyzePoint(char[][] board, int x, int y, int count, boolean isStepMade, Direction direction) {
        if (x < 0 || y < 0 || x >= dimX || y >= dimY) {
            return count;
        }
        char currentSymbol = board[y][x];
        if (currentSymbol == ZERO) {
            return count;
        }
        if (currentSymbol == EMPTY ) {
            if (isStepMade) {
                return count;
            } else {
                isStepMade = true;
                count++;
            }
        }
        if (currentSymbol == CROSS) {
            count++;
        }
        return analyzePoint(board, x + direction.getX(), y + direction.getY(), count, isStepMade, direction);
    }

    enum Direction {
        LEFT(-1, 0),
        RIGHT(1, 0),
        UP(0, -1),
        DOWN(0, 1),
        LEFT_UP(-1, -1),
        RIGHT_UP(1, -1),
        LEFT_DOWN(-1, 1),
        RIGHT_DOWN(1, 1);
        private int x;
        private int y;
        Direction(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int getX() {
            return x;
        }

        public int getY() {
            return y;
        }
    }
}

