        }
    }
    public static boolean checkTheLine(String line){
        if (line.contains(".XXXX") || line.contains("X.XXX") ||
                line.contains("XX.XX") || line.contains("XXX.X") || line.contains("XXXX.")){
            return true;
        }
        return false;
    }

    public static boolean verticalLinesBuilder(String[] array) {
        int i = 10;
        while (--i >= 0) {
            String line = "";
            for (int j = 0; j < 10; j++) {
                line += array[j].charAt(i);
            }
            if (checkTheLine(line)){
                return true;
            } else {
                if (upDiagonalLinesBuilder(array) || downDiagonalLinesBuilder(array)){
                    return true;
                }
            }
        }
        return false;
    }

    public static boolean upDiagonalLinesBuilder(String[] array){
        int temp = 3;
        while (++temp <=9){
            String line = "";
            for (int i = 0; i <=temp; i++){
                line +=array[i].charAt(temp-i);
            }
            if (checkTheLine(line)){
                return true;
            }
        }
        temp = 15;
        while (--temp >=10){
            String line = "";
            for (int i = 9; i >=temp-9; i--){
                line +=array[i].charAt(temp-i);
            }
            if (checkTheLine(line)){
                return true;
            }
        }
        return false;
    }

    public static boolean downDiagonalLinesBuilder(String[] array) {
        int temp = 6;
        while (--temp >=0) {
            String line = "";
            for (int i = temp; i <= 9; i++) {
                line += array[i].charAt(i-temp);
            }
            if (checkTheLine(line)) {
                return true;
            }
        }
        temp = 6;
        while (--temp>0) {
            String line = "";
            for (int i = 0; i <=9-temp; i++) {
                line += array[i].charAt(temp + i);
            }
            if (checkTheLine(line)) {
                return true;
            }
        }
        return false;
    }
}

