import static java.lang.System.out;

public class B {

    private static final String PATTERN = ".*XXXXX.*";

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        char[][] field = new char[10][10];

        for (int row = 0; row < 10; ++row) {
            String line = in.nextLine();
            for (int col = 0; col < 10; ++col)
                field[row][col] = line.charAt(col);
        }

        for (int row = 0; row < 10; ++row)
            for (int col = 0; col < 10; ++col)
                if (field[row][col] == '.') {
                    field[row][col] = 'X';
                    if (canWin(field)) {
                        out.println("YES");
                        return;
                    }
                    field[row][col] = '.';
                }
        out.println("NO");
    }

    private static boolean canWin(char[][] field) {

        for (int row = 0; row < 10; ++row) {
            StringBuilder rowString = new StringBuilder();
            for (char c : field[row])
                rowString.append(c);
            if (rowString.toString().matches(PATTERN))
                return true;
        }


        for (int col = 0; col < 10; ++col) {
            StringBuilder rowString = new StringBuilder();
            for (int row = 0; row < 10; ++row)
                rowString.append(field[row][col]);
            if (rowString.toString().matches(PATTERN))
                return true;
        }


        for (int row = 0; row <= 5; ++row) {
            for (int col = 0; col <= 5; ++col) {
                StringBuilder diagString = new StringBuilder();
                int r = row;
                int c = col;
                do {
                    diagString.append(field[r][c]);
                    ++r;
                    ++c;
                } while (r < 10 && c < 10);
                if (diagString.toString().matches(PATTERN))
                    return true;
            }
        }


        for (int row = 0; row <= 5; ++row) {
            for (int col = 4; col <= 9; ++col) {
                StringBuilder diagString = new StringBuilder();
                int r = row;
                int c = col;
                do {
                    diagString.append(field[r][c]);
                    ++r;
                    --c;
                } while (r < 10 && c >= 0);
                if (diagString.toString().matches(PATTERN))
                    return true;
            }
        }

        return false;
    }
}

