public class B {

    Scanner in;
    PrintWriter out;

    boolean check(char[] t) {
        int x = 0, p = 0;
        for (int i = 0; i < t.length; i++) {
            if (t[i] == 'X') {
                x++;
            } else if (t[i] == '.') {
                p++;
            }
        }
        return x == 4 && p == 1;
    }

    public void solve() throws Exception {
        char[][] f = new char[10][10];
        for (int i = 0; i < 10; i++) {
            f[i] = in.next().toCharArray();
        }
        boolean canWin = false;
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                String temp = "";
                for (int k = 0; k < 5 && j + k < 10; k++) {
                    temp += f[i][j + k];
                }
                if (check(temp.toCharArray())) {
                    canWin = true;
                }

                temp = "";
                for (int k = 0; k < 5 && i + k < 10 && j + k < 10; k++) {
                    temp += f[i + k][j + k];
                }
                if (check(temp.toCharArray())) {
                    canWin = true;
                }

                temp = "";
                for (int k = 0; k < 5 && i + k < 10; k++) {
                    temp += f[i + k][j];
                }
                if (check(temp.toCharArray())) {
                    canWin = true;
                }

                temp = "";
                for (int k = 0; k < 5 && i + k < 10 && j - k >= 0; k++) {
                    temp += f[i + k][j - k];
                }
                if (check(temp.toCharArray())) {
                    canWin = true;
                }
            }
        }

        out.println(canWin ? "YES" : "NO");
    }

    public void init() throws Exception {
        in = new Scanner(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

