                char c = str.charAt(j);
                if( c == '.' ) {
                    int left = findLeft(i, j, matrix);
                    int right = findRight(i, j, matrix);
                    int leftUp = findLeftUp(i, j, matrix);
                    int rightDown = findRightDown(i, j, matrix);
                    int rightUp = findRightUp(i, j, matrix);
                    int leftDown = findLeftDown(i, j, matrix);
                    int up = findUp(i, j, matrix);
                    int down = findDown(i, j, matrix);

                    if (left + right >= 4 ||
                            up + down >=4 ||
                            leftUp + rightDown >= 4 ||
                            rightUp + leftDown >= 4) {
                        System.out.println("YES");
                        return;
                    }
                }
            }
        }

        System.out.println("NO");

    }

    private static int findLeft(int x, int y, String[] matrix){
        int count = 0;
        y--;
        while( y >= 0 && matrix[x].charAt(y) == 'X'){
            count++;
            y--;
        }

        return count;
    }

    private static int findRight(int x, int y, String[] matrix){
        int count = 0;
        y++;
        while( y < 10 && matrix[x].charAt(y) == 'X'){
            count++;
            y++;
        }

        return count;
    }

    private static int findUp(int x, int y, String[] matrix){
        int count = 0;
        x--;
        while( x >= 0 && matrix[x].charAt(y) == 'X' ){
            count++;
            x--;
        }

        return count;
    }

    private static int findDown(int x, int y, String[] matrix){
        int count = 0;
        x++;
        while( x < 10 && matrix[x].charAt(y) == 'X' ){
            count++;
            x++;
        }

        return count;
    }

    private static int findLeftUp(int x, int y, String[] matrix){
        int count = 0;
        x--;
        y--;
        while( x >= 0 && y >= 0 && matrix[x].charAt(y) == 'X'){
            count++;
            x--;
            y--;
        }

        return count;
    }

    private static int findRightDown(int x, int y, String[] matrix){
        int count = 0;
        x++;
        y++;
        while( x < 10 && y < 10 && matrix[x].charAt(y) == 'X'){
            count++;
            x++;
            y++;
        }

        return count;
    }

    private static int findRightUp(int x, int y, String[] matrix){
