    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int M = in.nextInt();
            char[][] flag = in.nextCharMatrix(N, M);
            if (N % 3 == 0 && M % 3 == 0) {
                if (checkLine(flag, N, M) || checkCol(flag, N, M)) out.print("YES");
                else out.print("NO");
            } else if (N % 3 == 0) {
                if (checkLine(flag, N, M)) out.print("YES");
                else out.print("NO");
            } else if (M % 3 == 0) {
                if (checkCol(flag, N, M)) out.print("YES");
                else out.print("NO");
            } else {
                out.print("NO");
            }
        }

        private boolean checkLine(char[][] flag, int N, int M) {
            boolean[] used = new boolean[234];
            int line = N / 3;
            for (int i = 0; i < N; i += line) {
                char color = flag[i][0];
                if (used[color]) return false;
                else used[color] = true;
                for (int k = i; k < i + line; k++) {
                    for (int j = 0; j < M; j++) {
                        if (flag[k][j] != color) return false;
                    }
                }
            }
            return true;
        }

        private boolean checkCol(char[][] flag, int N, int M) {
            boolean[] used = new boolean[234];
            int col = M / 3;
            for (int j = 0; j < M; j += col) {
                char color = flag[0][j];
                if (used[color]) return false;
                else used[color] = true;
                for (int k = j; k < j + col; k++) {
                    for (int i = 0; i < N; i++) {
                        if (flag[i][k] != color) return false;
                    }
                }
            }
            return true;
        }

    }

    static class InputReader {
        private int lenbuf = 0;
        private int ptrbuf = 0;
        private InputStream in;
        private byte[] inbuf = new byte[1024];

        public InputReader(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (lenbuf == -1) throw new InputMismatchException();
            if (ptrbuf >= lenbuf) {
                ptrbuf = 0;
                try {
                    lenbuf = in.read(inbuf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (lenbuf <= 0) return -1;
            }
            return inbuf[ptrbuf++];
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        private int skip() {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b)) ;
            return b;
        }

        public int nextInt() {
            int num = 0, b;
            boolean minus = false;
            while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
            if (b == '-') {
                minus = true;
                b = readByte();
            }

            while (true) {
                if (b >= '0' && b <= '9') {
                    num = num * 10 + (b - '0');
                } else {
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }

        public char[] nextCharArray(int n) {
            char[] buf = new char[n];
            int b = skip(), p = 0;
            while (p < n && !(isSpaceChar(b))) {
                buf[p++] = (char) b;
                b = readByte();
            }
            return n == p ? buf : Arrays.copyOf(buf, p);
        }

        public char[][] nextCharMatrix(int n, int m) {
            char[][] map = new char[n][];
            for (int i = 0; i < n; i++) map[i] = nextCharArray(m);
            return map;
        }

    }
}

