    static class BFlagOfBerland {
        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            int n = in.scanInt();
            int m = in.scanInt();
            boolean flag = false;
            char[][] ar = new char[n][];
            for (int i = 0; i < n; i++) ar[i] = in.scanString().toCharArray();

            if (n % 3 == 0) {
                boolean tt = true;
                char tt1 = ar[0][0];
                char tt2 = ar[n / 3][0];
                char tt3 = ar[(n / 3) * 2][0];
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        if (i < n / 3 && ar[i][j] != tt1) tt = false;
                        else if (i >= n / 3 && i < 2 * (n / 3) && ar[i][j] != tt2) tt = false;
                        else if (i >= 2 * (n / 3) && i < n && ar[i][j] != tt3) tt = false;
                    }
                }
                if (tt1 != tt2 && tt2 != tt3 && tt3 != tt1) flag |= tt;
            }
            if (m % 3 == 0) {
                boolean tt = true;
                char tt1 = ar[0][0];
                char tt2 = ar[0][m / 3];
                char tt3 = ar[0][(m / 3) * 2];
                for (int i = 0; i < m; i++) {
                    for (int j = 0; j < n; j++) {
                        if (i < m / 3 && ar[j][i] != tt1) tt = false;
                        else if (i >= m / 3 && i < 2 * (m / 3) && ar[j][i] != tt2) tt = false;
                        else if (i >= (m / 3) * 2 && i < m && ar[j][i] != tt3) tt = false;
                    }
                }
                if (tt1 != tt2 && tt2 != tt3 && tt3 != tt1) flag |= tt;
            }
            if (flag) out.println("YES");
            else out.println("NO");
        }

    }

    static class ScanReader {
        private byte[] buf = new byte[4 * 1024];
        private int index;
        private BufferedInputStream in;
        private int total;

        public ScanReader(InputStream inputStream) {
            in = new BufferedInputStream(inputStream);
        }

        private int scan() {
            if (index >= total) {
                index = 0;
                try {
                    total = in.read(buf);
                } catch (Exception e) {
                    e.printStackTrace();
                }
                if (total <= 0) return -1;
            }
            return buf[index++];
        }

        public int scanInt() {
            int integer = 0;
            int n = scan();
            while (isWhiteSpace(n)) n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    integer *= 10;
                    integer += n - '0';
                    n = scan();
                }
            }
            return neg * integer;
        }

        public String scanString() {
            int c = scan();
            if (c == -1) return null;
            while (isWhiteSpace(c)) c = scan();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = scan();
            } while (!isWhiteSpace(c));
            return res.toString();
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1) return true;
            else return false;
        }

    }
}

