public class BerlandFlag {

	public static void main(String[] args) throws IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

		StringTokenizer st = new StringTokenizer(in.readLine());
		int n = Integer.parseInt(st.nextToken()), m = Integer.parseInt(st.nextToken());

		char[][] flag = new char[n][m];
		String str;
		char c;
		for (int i = 0; i < n; i++) {
			str = in.readLine();
			for (int j = 0; j < m; j++) {
				c = str.charAt(j);
				if (c == 'R' || c == 'B' || c == 'G')
					flag[i][j] = c;
				else {
					wrong(out);
					return;
				}
			}
		}


		int w, h;
		c = flag[0][0];

		for (h = 1; h < n && flag[h][0] == c; h++);

		for (w = 1; w < m && flag[0][w] == c; w++);

		if (h != n && w != m) {
			wrong(out);
			return;
		}

		if (h != n) {
			if (n % 3 != 0 || h != n / 3) {
				wrong(out);
				return;
			}
			if (c != flag[h][0] && c != flag[h * 2][0] && flag[h][0] != flag[h * 2][0] && check(flag, c, 0, 0, h, m)
					&& check(flag, flag[h][0], h, 0, h * 2, m) && check(flag, flag[h * 2][0], h * 2, 0, n, m)) {
				out.println("YES");
				out.close();
				return;
			} else {
				wrong(out);
				return;
			}
		} else {
			if (m % 3 != 0 || w != m / 3) {
				wrong(out);
				return;
			}
			if (c != flag[0][w] && c != flag[0][w * 2] && flag[0][w] != flag[0][w * 2] && check(flag, c, 0, 0, n, w)
					&& check(flag, flag[0][w], 0, w, n, w * 2) && check(flag, flag[0][w * 2], 0, w * 2, n, m)) {
				out.println("YES");
				out.close();
				return;
			} else {
				wrong(out);
				return;
			}
		}

	}

	private static void wrong(PrintWriter out) {
		out.println("NO");
		out.close();
	}

	private static boolean check(char[][] flag, char c, int row, int col, int endRow, int endCol) {

		for (; row < endRow; row++)
			for (int j = col; j < endCol; j++)
				if (flag[row][j] != c)
					return false;
		return true;
	}

}

