import java.io.*;

public class _837B {

    static int[] iOF(char[][] s, char x) {
        for (int i = 0; i < s.length; i++)
            for (int j = 0; j < s[0].length; j++)
                if (s[i][j] == x) return new int[]{i, j};
        return null;
    }

    static boolean flagRow(char[][] s, int[] R, int[] G, int[] B, int count) {
        if (R[1] != 0 || G[1] != 0 || B[1] != 0) return false;

        int Rcount = 0, Gcount = 0, Bcount = 0;
        loop:
        for (int i = R[0]; i < s.length; i++)
            for (int j = 0; j < s[0].length; j++)
                if (s[i][j] == 'R') Rcount++;
                else if (Rcount == count) break loop;
                else return false;

        loop:
        for (int i = G[0]; i < s.length; i++)
            for (int j = 0; j < s[0].length; j++)
                if (s[i][j] == 'G') Gcount++;
                else if (Gcount == count) break loop;
                else return false;

        loop:
        for (int i = B[0]; i < s.length; i++)
            for (int j = 0; j < s[0].length; j++)
                if (s[i][j] == 'B') Bcount++;
                else if (Bcount == count) break loop;
                else return false;
        return true;
    }

    static boolean flagCol(char[][] s, int[] R, int[] G, int[] B, int count) {
        if (R[0] != 0 || G[0] != 0 || B[0] != 0) return false;
        int Rcount = 0, Gcount = 0, Bcount = 0;
        loop:
        for (int j = R[1]; j < s[0].length; j++)
            for (int i = 0; i < s.length; i++)
                if (s[i][j] == 'R') Rcount++;
                else if (Rcount == count) break loop;
                else return false;
        loop:
        for (int j = G[1]; j < s[0].length; j++)
            for (int i = 0; i < s.length; i++)
                if (s[i][j] == 'G') Gcount++;
                else if (Gcount == count) break loop;
                else return false;
        loop:
        for (int j = B[1]; j < s[0].length; j++)
            for (int i = 0; i < s.length; i++)
                if (s[i][j] == 'B') Bcount++;
                else if (Bcount == count) break loop;
                else return false;
        return true;
    }

    public static void main(String[] args) throws IOException {
        Scan in = new Scan();
        int n = in.nextInt(), m = in.nextInt(), R = 0, B = 0, G = 0;
        char[][] s = new char[n][];
        for (int i = 0; i < n; i++) {
            s[i] = in.nextArr();
            for (int j = 0; j < m; j++)
                switch (s[i][j]) {
                    case 'R': R++; break;
                    case 'G': G++; break;
                    case 'B': B++; break;
                }
            }
        if (R != B || B != G)
            System.out.println("NO");
        else {
            int[] rPOS = iOF(s, 'R'), gPOS = iOF(s, 'G'), bPos = iOF(s, 'B');
            System.out.println(flagCol(s, rPOS, gPOS, bPos, B) ||
                               flagRow(s, rPOS, gPOS, bPos, B) ? "YES" : "NO");
        }
    }
}
class Scan {

    private final InputStream stream;
    private final byte EOF = -1, NL = '\n', DASH = '-', SPACE = ' ', R = '\r';
    private final byte[] buffer;
    private char[] charBuff;
    private int $index, $readCount;

    public Scan(InputStream stream, int bufferSize, int chrBuffSize) {
        this.stream = stream;
        this.buffer = new byte[bufferSize];
        this.charBuff = new char[chrBuffSize];
    }

    public Scan() {
        this(System.in, 1 << 16, 1 << 8);
    }

    private void skip(byte skp) throws IOException {
        if ($readCount == EOF) return;
        for (;;) {
            while ($index < buffer.length) {
                if (buffer[$index] > skp) return;
                $index++;
            }
            $readCount = stream.read(buffer);
            $index = 0;
            if ($readCount == EOF) return;
        }
    }

    private void quadCharSize() {
        char[] tmp = new char[charBuff.length << 2];
		System.arraycopy(charBuff, 0, tmp, 0, charBuff.length);
        charBuff = tmp;
    }

    public char[] nextArr() throws IOException {
        skip(SPACE);
        if ($readCount == EOF) return null;

        for (int i = 0;;) {
            while ($index < $readCount) {
                if (buffer[$index] > SPACE) {
                    if (i == charBuff.length) quadCharSize();
                    charBuff[i++] = (char)buffer[$index++];
                } else
                    return java.util.Arrays.copyOf(charBuff, i);
            }
            $readCount = stream.read(buffer);
            $index = 0;
            if ($readCount == EOF) return java.util.Arrays.copyOf(charBuff, i);
        }
    }

    public char[] nextLineArr() throws IOException {
        if ($readCount == EOF) return null;

        for (int i = 0;;) {
            while ($index < $readCount) {
                if (buffer[$index] == NL) {
                    $index++;
                    return java.util.Arrays.copyOf(charBuff, i);
                } else {
                    if (i == charBuff.length) quadCharSize();
                    charBuff[i++] = (char)buffer[$index++];
                }
            }
            $readCount = stream.read(buffer);
            $index = 0;
            if ($readCount == EOF) return java.util.Arrays.copyOf(charBuff, i);
        }
    }

    public int nextInt() throws IOException {
        skip(SPACE);
        if ($readCount == EOF) throw new IOException();

        int res = 0;
        boolean neg = false;
        if (buffer[$index] == DASH) {
            neg = true;
            $index++;
        }

        for (;;) {
            while ($index < $readCount) {
                if (buffer[$index] > SPACE) {
                    res = (res << 3) + (res << 1);
                    res += buffer[$index++] - '0';
                } else return neg ? -res : res;
            }
            $index = 0;
            $readCount = stream.read(buffer);
            if ($readCount == EOF) return neg ? -res : res;
        }
    }

    public long nextLong() throws IOException {
        skip(SPACE);
        if ($readCount == EOF) throw new IOException();

        long res = 0;
        boolean neg = false;
        if (buffer[$index] == DASH) {
            neg = true;
            $index++;
        }
        for (;;) {
            while ($index < $readCount) {
                if (buffer[$index] > SPACE) {
                    res = (res << 3) + (res << 1);
                    res += buffer[$index++] - '0';
                } else
                    return neg ? -res : res;
            }
            $index = 0;
            $readCount = stream.read(buffer);
            if ($readCount == EOF) return neg ? -res : res;
        }
    }
}

