                    if(s[i].charAt(j)!=first)
                    {
                        flag2=1;
                    }
                }
            }
            for(int j=term;j<2*term&&flag2!=1;j++)
            {
                for(int i=0;i<n&&flag2!=1;i++)
                {
                    if(s[i].charAt(j)!=second)
                    {
                        flag2=1;
