    static class TaskB {
        int n;
        int m;
        char[][] data;
        char[][] rev;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.readInt();
            m = in.readInt();

            data = new char[n][m];
            rev = new char[m][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    data[i][j] = in.readCharacter();
                }
            }

            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    rev[i][j] = data[j][i];
                }
            }

            if (vertical(data, n, m) || vertical(rev, m, n)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        public boolean vertical(char[][] data, int n, int m) {
            if (n % 3 != 0) return false;
            n /= 3;
            HashSet<Character> st = new HashSet<>();
            for (int i = 0; i < 3; i++) {
                char src = data[i * n][0];
                st.add(src);
                for (int row = i * (n); row < (i + 1) * n; row++) {
                    for (int col = 0; col < m; col++) {
                        if (data[row][col] != src) return false;
                    }
                }
            }

            return st.contains('R') && st.contains('G') && st.contains('B');
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            return (char) c;
        }

    }
}

