public class problem {
    public static boolean isStripe(char[][] arr){
        char c = arr[0][0];
        for (int i = 0 ; i < arr.length; i++){
            for (int j = 0; j <arr[0].length; j++){
                if (arr[i][j] != c) return false;
            }
        }
        return true;
    }

    public static boolean areDifferent(char x, char y, char z) {
        return x != y && y != z && z != x;
    }

    public static char[][] subArray(char[][] arr, int y1, int y2, int x1, int x2){
        char[][] res = new char[x2 - x1][y2 - y1];
        for (int i = x1; i < x2; i++){
            for (int j = y1; j < y2; j++){
                res[i - x1][j - y1] = arr[i][j];
            }
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        int m = input.nextInt();
        char[][] flag = new char[n][m];

        for (int i = 0; i < n; i++){
            String s = input.next();
            for (int j = 0; j < m; j++){
                flag[i][j] = s.charAt(j);
            }
        }

        boolean isFlag = false;

        if (m%3 == 0){
            int k = m/3;
            isFlag = areDifferent(flag[0][0], flag[0][k], flag[0][2*k]) && isStripe(subArray(flag, 0, k, 0, n))
                    && isStripe(subArray(flag, k, 2*k, 0, n)) && isStripe(subArray(flag, 2*k, 3*k, 0, n));
        }

        if (n%3 == 0){
            int k = n/3;
            isFlag = isFlag || areDifferent(flag[0][0], flag[k][0], flag[2*k][0]) && isStripe(subArray(flag, 0, m, 0, k))
                    && isStripe(subArray(flag, 0, m, k, 2*k)) && isStripe(subArray(flag, 0, m, 2*k, 3*k));
        }

        if (m%3 != 0 && n%3 != 0){
            isFlag = false;
        }

        if (isFlag) System.out.println("YES");
        else System.out.println("NO");
    }
}

