                    for (int j = 0; j < n; j++) d += b[j][i];
                    if (!c.equals(d)) {
                        out.print("NO");
                        return;
                    }
                }
            } else {
                if (m % 3 != 0) {
                    out.print("NO");
                    return;
                }
