        {
            StringBuilder sb = new StringBuilder();
            for(int j=0;j<n;j++)
                sb.append(flag[j][i]);
            hori[i] = sb.toString();
        }
        boolean v = sarreq(verti,n);
        boolean h = sarreq(hori,m);
        if(!v && !h)
            System.out.println("NO");
        else if(v)
            fp(verti[0]);        
        else if(h)
            fp(hori[0]);
    }
    static boolean sarreq(String ar[],int n)
    {
        for(int i=1;i<n;i++)
            if(!ar[i].equals(ar[i-1]))
                return false;
        return true;
    }
    static void fp(String check)
    {
        ArrayList<Integer> r = new ArrayList<>();
        ArrayList<Integer> g = new ArrayList<>();
        ArrayList<Integer> b = new ArrayList<>();
        for(int i=0;i<check.length();i++)
            if(check.charAt(i) == 'R')
                r.add(i);
            else if(check.charAt(i) == 'G')
                g.add(i);
            else
                b.add(i);
        if(r.size() != g.size() || g.size() != b.size() || b.size() != r.size())
        {
            System.out.println("NO");
            return;
        }
        int ct = 0;
        for(int i=1;i<r.size();i++)
            if(r.get(i) - r.get(i-1) > 1)
                ct++;
        for(int i=1;i<g.size();i++)
            if(g.get(i) - g.get(i-1) > 1)
                ct++;
        for(int i=1;i<b.size();i++)
            if(b.get(i) - b.get(i-1) > 1)
                ct++;
        System.out.println(ct == 0 ? "YES" : "NO");
    }
}

import java.io.BufferedReader;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class FlagOfBerland implements Closeable {

    private InputReader in = new InputReader(System.in);
    private PrintWriter out = new PrintWriter(System.out);

    public void solve() {
        int n = in.ni(), m = in.ni();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        boolean ok = horizontal(grid) || vertical(grid);
        out.println(ok ? "YES" : "NO");
    }

    private boolean horizontal(char[][] grid) {
        int n = grid.length, m = grid[0].length;
        if (n % 3 != 0) return false;
        int limit = n / 3;
        boolean ok = true;
        for (int i = 0; i < limit; i++) {
            for (int j = 0; j < m; j++) {
                ok &= grid[i][j] == grid[0][0];
                ok &= grid[limit + i][j] == grid[limit][0];
                ok &= grid[2 * limit + i][j] == grid[2 * limit][0];
            }
        }
        ok &= (grid[0][0] != grid[limit][0] && grid[limit][0] != grid[2 * limit][0] && grid[2 * limit][0] != grid[0][0]);
        return ok;
    }

    private boolean vertical(char[][] grid) {
        int n = grid.length, m = grid[0].length;
        if (m % 3 != 0) return false;
