    static class TaskB {
        char[][] a;
        int n;
        int m;

        public void solve(int testNumber, InputReader in, PrintWriter out) {

            n = in.nextInt();
            m = in.nextInt();

            a = new char[n][m];

            for (int i = 0; i < n; ++i)
                a[i] = in.next().toCharArray();

            int[][] sz = new int[3][2];

            sz[0] = calc('R');
            sz[1] = calc('G');
            sz[2] = calc('B');

            boolean ok = true;
            for (int i = 0; i < 2; ++i) {
                ok &= sz[i][0] == sz[i + 1][0] && sz[i][1] != -1;
                ok &= sz[i][1] == sz[i + 1][1] && sz[i][1] != -1;
            }

            out.println(ok ? "YES" : "NO");

        }

        private int[] calc(char r) {

            int[] res = new int[2];

            int x0 = -1, y0 = -1;
            int x1 = -1, y1 = -1;

            int cnt = 0;

            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (a[i][j] == r) {
                        cnt++;
                        if (x0 == -1) {
                            x0 = i;
                            y0 = j;
                        }

                        x1 = Math.max(x1, i);
                        y1 = Math.max(y1, j);
                    }
                }
            }

            int h = x1 - x0 + 1;
            int w = y1 - y0 + 1;

            if (h * w != cnt) {
                Arrays.fill(res, -1);
                return res;
            }

            res[0] = h;
            res[1] = w;

            return res;
        }

    }

