class Answer {
    private final int INF = (int) (1e9 + 7);
    private final int MOD = (int) (1e9 + 7);
    private final int MOD1 = (int) (1e6 + 3);
    private final long INF_LONG = (long) (1e18 + 1);
    private final double EPS = 1e-9;

    private long gcd(long a, long b) {
        return (b == 0) ? a : gcd(b, a % b);
    }


    private char[][] transpose(char[][] matrix, int n, int m) {
        char[][] newMatix = new char[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                newMatix[i][j] = matrix[j][i];
            }
        }

        return newMatix;
    }

    private boolean test(char[][] matrix, int n, int m) {
        if (n % 3 != 0) {
            return false;
        }

        if (matrix[0][0] == matrix[n / 3][0]
                || matrix[0][0] == matrix[2 * n / 3][0]
                || matrix[n / 3][0] == matrix[2 * n / 3][0]) {
            return false;
        }

        for (int i = 0; i < n / 3; i++) {
            for (int j = 0; j < m; j++) {
                if (matrix[i][j] != matrix[0][0]) {
                    return false;
                }
            }
        }
        for (int i = n / 3; i < 2 * n / 3; i++) {
            for (int j = 0; j < m; j++) {
                if (matrix[i][j] != matrix[n / 3][0]) {
                    return false;
                }
            }
        }
        for (int i = 2 * n / 3; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (matrix[i][j] != matrix[2 * n / 3][0]) {
                    return false;
                }
            }
        }

        return true;
    }

    public void solve(InputReader in, PrintWriter out) throws IOException {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] matrix = new char[n][m];

        for (int i = 0; i < n; i++) {
            String s = in.next();
            matrix[i] = s.toCharArray();
        }

        if (test(matrix, n, m)) {
            out.print("YES");
            return;
        }

        char[][] newMatrix = transpose(matrix, n, m);

        if (test(newMatrix, m, n)) {
            out.print("YES");
            return;
        }

        out.print("NO");
    }
}

class InputReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public int[] nextArrayInt(int count) {
        int[] a = new int[count];
        for (int i = 0; i < count; i++) {
            a[i] = nextInt();
        }
        return a;
    }

    public long[] nextArrayLong(int count) {
        long[] a = new long[count];
        for (int i = 0; i < count; i++) {
            a[i] = nextLong();
        }
        return a;
    }
}

