import java.util.*;
import java.io.*;

public class B
{

    Reader in;
    PrintWriter out;
    int i = 0, j = 0;
    void solve()
    {


        int n = in.nextInt();
        int[][] dice = new int[n][6];
        BitSet bs = new BitSet(1001);
        bs.set(0);
        for (i = 0; i < n; i++)
        {
            for (j = 0; j < 6; j++)
            {
                dice[i][j] = in.nextInt();
                bs.set(dice[i][j]);
            }
        }
        if (n >= 2)
        {
            for (int a = 0; a < 6; a++)
            {
                for (int b = 0; b < 6; b++)
                {
                    bs.set(dice[0][a]*10 + dice[1][b]);
                    bs.set(dice[1][b]*10 + dice[0][a]);
                }
            }
        }
        if (n == 3)
        {
            for (int a = 0; a < 6; a++)
            {
                for (int b = 0; b < 6; b++)
                {
                    bs.set(dice[2][a]*10 + dice[1][b]);
                    bs.set(dice[2][a]*10 + dice[0][b]);
                    bs.set(dice[0][b]*10 + dice[2][a]);
                    bs.set(dice[1][b]*10 + dice[2][a]);
                }
            }
        }
        int sol = bs.nextClearBit(0);
        sol--;
        out.println(sol);











    }
    void runIO()
    {
        in = new Reader();
        out = new PrintWriter(System.out, false);
        solve();
        out.close();
    }

    public static void main(String[] args)
    {
        new B().runIO();
    }



    static class Reader
    {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public Reader()
        {
            din = new DataInputStream(System.in);

            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }



        public final String next()
        {
            int c = read();
            while (isSpaceChar(c))
            {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do
            {
                res.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c)
        {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt()
        {
            int ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do
            {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg)
                return -ret;
            return ret;
        }

        public long nextLong()
        {
            long ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do
            {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg)
                return -ret;
            return ret;
        }

        public double nextDouble()
        {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do
            {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (c == '.')
                while ((c = read()) >= '0' && c <= '9')
                    ret += (c - '0') / (div *= 10);
            if (neg)
                return -ret;
            return ret;
        }

        public int[] readIntArray(int size)
        {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++)
                arr[i] = nextInt();
            return arr;
        }

        public long[] readLongArray(int size)
        {
            long[] arr = new long[size];
            for (int i = 0; i < size; i++)
                arr[i] = nextInt();
            return arr;
        }

        private void fillBuffer()
        {
            try
            {
                bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            }
            catch (IOException e)
            {

            }

            if (bytesRead == -1)
                buffer[0] = -1;
        }

        private byte read()
        {
            if (bufferPointer == bytesRead)
                fillBuffer();
            return buffer[bufferPointer++];
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ProblemB {
    BufferedReader rd;
    int[][] pe = new int[][] { {0,1,2}, {0,2,1}, {1,0,2}, {1,2,0}, {2,0,1}, {2,1,0} };

    ProblemB() throws IOException {
        rd = new BufferedReader(new InputStreamReader(System.in));
        compute();
    }

    private void compute() throws IOException {
        int n = pint();
        int[][] d = new int[n][];
        for(int i=0;i<n;i++) {
            d[i] = intarr();
        }
        int to = pow(10,n);
        int max = 0;
        for(int i=1;i<to;i++) {
            if(!possible(d,i)) {
                break;
            }
            max = i;
        }
        out(max);
    }

    private int pow(int a, int b) {
        int res = 1;
        for(int i=0;i<b;i++) {
            res *= a;
        }
        return res;
    }

    private boolean possible(int[][] d, int i) {
        char[] q = Integer.toString(i).toCharArray();
        int z = q.length;
        int[] u = new int[z];
        for(int j=0;j<z;j++) {
            u[j] = q[j]-'0';
        }
        for(int[] p: pe) {
            boolean ok = true;
            for(int w=0;w<z;w++) {
                if(p[w] >= d.length) {
                    ok = false;
                    break;
                }
                int[] a = d[p[w]];
                if(!contains(a, u[w])) {
                    ok = false;
                    break;
                }
            }
            if(ok) {
                return true;
            }
        }
        return false;
    }

    private boolean contains(int[] a, int i) {
        for(int x: a) {
            if(x == i) {
                return true;
            }
        }
        return false;
    }

    private int pint() throws IOException {
        return pint(rd.readLine());
    }

    private int pint(String s) {
        return Integer.parseInt(s);
    }

    private int[] intarr() throws IOException {
        return intarr(rd.readLine());
    }

    private int[] intarr(String s) {
        String[] q = split(s);
        int n = q.length;
        int[] a = new int[n];
        for(int i=0;i<n;i++) {
            a[i] = Integer.parseInt(q[i]);
        }
        return a;
    }

    private String[] split(String s) {
        if(s == null) {
            return new String[0];
        }
        int n = s.length();
        int start = -1;
        int end = 0;
        int sp = 0;
        boolean lastWhitespace = true;
        for(int i=0;i<n;i++) {
            char c = s.charAt(i);
            if(isWhitespace(c)) {
                lastWhitespace = true;
            } else {
                if(lastWhitespace) {
                    sp++;
                }
                if(start == -1) {
                    start = i;
                }
                end = i;
                lastWhitespace = false;
            }
        }
        if(start == -1) {
            return new String[0];
        }
        String[] res = new String[sp];
        int last = start;
        int x = 0;
        lastWhitespace = true;
        for(int i=start;i<=end;i++) {
            char c = s.charAt(i);
            boolean w = isWhitespace(c);
            if(w && !lastWhitespace) {
                res[x++] = s.substring(last,i);
            } else if(!w && lastWhitespace) {
                last = i;
            }
            lastWhitespace = w;
        }
        res[x] = s.substring(last,end+1);
        return res;
    }

    private boolean isWhitespace(char c) {
        return c==' ' || c=='\t';
    }

    private static void out(Object x) {
        System.out.println(x);
    }

    public static void main(String[] args) throws IOException {
        new ProblemB();
    }
}

import java.util.Scanner;

public class Program
{
	static void resetComb(int[] comb)
	{
		for(int i = 0; i < comb.length; i++)
			comb[i] = 0;
	}

	static boolean nextComb(int[] comb, int k)
	{
		int i = comb.length - 1;
		while(i >= 0 && comb[i] == k)
			comb[i--] = 0;

		if(i < 0)
			return false;

		comb[i]++;
		return true;
	}

	static boolean check(int x, int[] nums)
	{
		if(x < 10)
		{
			for(int i = 0; i < nums.length; i++)
				if(nums[i] == x)
					return true;

			return false;
		}

		if(x < 100)
		{
			for(int i = 0; i < nums.length; i++)
				for(int j = 0; j < nums.length; j++)
					if(i != j && x == nums[i] * 10 + nums[j])
						return true;

			return false;
		}

		for(int i = 0; i < nums.length; i++)
			for(int j = 0; j < nums.length; j++)
				for(int k = 0; k < nums.length; k++)
					if(i != j && i != k && j != k && x == nums[i] * 100 + nums[j] * 10 + nums[k])
						return true;

		return false;
	}

	public static void main(String[] args)
	{
		Scanner s = new Scanner(System.in);

		int n = s.nextInt();
		int[][] mat = new int[n][6];
		for(int i = 0; i < n; i++)
			for(int j = 0; j < 6; j++)
				mat[i][j] = s.nextInt();

		s.close();

		int[] arr = new int[n];
		int[] comb = new int[n];


		int x;
		for(x = 1; x < Math.pow(10, n); x++)
		{
			boolean flag = false;
			resetComb(comb);

			do
			{	
				for(int i = 0; i < n; i++)
					arr[i] = mat[i][comb[i]];

				flag = check(x, arr);
			} while(nextComb(comb, 5) && flag == false);

			if(flag == false)
				break;
		}

		System.out.println(x-1);
	}

}

