					for(int j = i+1; j<n; j++) {
						for(int k = 0; k<6; k++) {
							for(int l = 0; l<6; l++) {
								possible[cubes[i][k]*10+cubes[j][l]] =
										possible[cubes[j][l]*10+cubes[i][k]] = true;
