public class Main {
  public static void main(String[] args) {
    InputStream inputStream = System.in;
    OutputStream outputStream = System.out;
    FastIO in = new FastIO(inputStream);
    PrintWriter out = new PrintWriter(outputStream);
    TaskB solver = new TaskB();
    solver.solve(1, in, out);
    out.close();
  }

  static class TaskB {
    public void solve(int testNumber, FastIO in, PrintWriter out) {
      int n = in.nextInt();
      boolean[][] nums = new boolean[10][3];
      for (int i = 0; i < n; i++) {
        for (int j = 0; j < 6; j++) {
          nums[in.nextInt()][i] = true;
        }
      }
      for (int i = 1; i < 100; i++) {
        if (i < 10) {
          if (!nums[i][0] && !nums[i][1] && !nums[i][2]) {
            out.println(i - 1);
            return;
          }
        }
        else {
          int first = i % 10;
          int second = i / 10;
          if ((!nums[first][0] || !nums[second][1]) &&
              (!nums[first][0] || !nums[second][2]) &&
              (!nums[first][1] || !nums[second][0]) &&
              (!nums[first][1] || !nums[second][2]) &&
              (!nums[first][2] || !nums[second][1]) &&
              (!nums[first][2] || !nums[second][0])) {
            out.println(i - 1);
            return;
          }

        }
      }
      out.println(99);
    }

  }


  static class FastIO {
    final private int BUFFER_SIZE = 1 << 16;
    private InputStream din;
    private byte[] buffer;
    private int bufferPointer;
    private int bytesRead;

    public FastIO() {
      buffer = new byte[BUFFER_SIZE];
      bufferPointer = bytesRead = 0;
    }

    public FastIO(InputStream inputStream) {
      this();
      din = new DataInputStream(inputStream);
    }

    public FastIO(String file_name) {
      try {
        din = new DataInputStream(new FileInputStream(file_name));
        buffer = new byte[BUFFER_SIZE];
        bufferPointer = bytesRead = 0;
      }
      catch (FileNotFoundException e) {
        e.printStackTrace();
      }
    }

    public int nextInt() {
      int ret = 0;
      try {
        byte c = read();
        while (c <= ' ') {
          c = read();
        }
        boolean neg = (c == '-');
        if (neg) {
          c = read();
        }
        do {
          ret = ret * 10 + c - '0';
        }
        while ((c = read()) >= '0' && c <= '9');

        if (neg) {
          return -ret;
        }
      }
      catch (Exception e) {
        e.printStackTrace();
      }
      return ret;
    }

    private void fillBuffer() {
      try {
        bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
        if (bytesRead == -1) {
          buffer[0] = -1;
        }
      }
      catch (IOException e) {
        e.printStackTrace();
      }
    }

    private byte read() {
      if (bufferPointer == bytesRead) {
        fillBuffer();
      }
      return buffer[bufferPointer++];
    }

  }
}

