    static class TaskB {
        public void solve(int testNumber, InputReader sc, PrintWriter w) {

            int n = sc.nextInt();

            HashSet arr[] = new HashSet[n];

            for (int i = 0; i < n; i++)
                arr[i] = new HashSet();

            for (int i = 0; i < n; i++)
                for (int j = 0; j < 6; j++)
                    arr[i].add(sc.nextInt());

            int max = 0;
            for (int i = 1; i <= 1010; i++) {
                int present = 0;
                if (i < 10) {
                    for (int j = 0; j < n; j++) {
                        if (arr[j].contains(i))
                            present++;
                    }
                } else if (i < 100) {
                    int firstDigit = i / 10;
                    int secondDigit = i % 10;
                    if (n == 2) {
                        if (arr[0].contains(firstDigit) && arr[1].contains(secondDigit))
                            present++;

                        if (arr[1].contains(firstDigit) && arr[0].contains(secondDigit))
                            present++;
                    } else if (n == 3) {
                        if (arr[0].contains(firstDigit) && arr[1].contains(secondDigit))
                            present++;

                        if (arr[0].contains(firstDigit) && arr[2].contains(secondDigit))
                            present++;

                        if (arr[1].contains(firstDigit) && arr[2].contains(secondDigit))
                            present++;

                        if (arr[1].contains(firstDigit) && arr[0].contains(secondDigit))
                            present++;

                        if (arr[2].contains(firstDigit) && arr[0].contains(secondDigit))
                            present++;

                        if (arr[2].contains(firstDigit) && arr[1].contains(secondDigit))
                            present++;


                    }
                } else {
                    int firstDigit = i / 100;
                    int secondDigit = (i / 10) % 10;
                    int thirdDigit = i % 10;

                    if (n == 3) {
                        if (arr[0].contains(firstDigit) && arr[1].contains(secondDigit) && arr[2].contains(thirdDigit))
                            present++;
                        if (arr[0].contains(firstDigit) && arr[2].contains(secondDigit) && arr[1].contains(thirdDigit))
                            present++;
                        if (arr[1].contains(firstDigit) && arr[0].contains(secondDigit) && arr[2].contains(thirdDigit))
                            present++;
                        if (arr[1].contains(firstDigit) && arr[2].contains(secondDigit) && arr[0].contains(thirdDigit))
                            present++;

                        if (arr[2].contains(firstDigit) && arr[1].contains(secondDigit) && arr[0].contains(thirdDigit))
                            present++;

                        if (arr[2].contains(firstDigit) && arr[0].contains(secondDigit) && arr[1].contains(thirdDigit))
                            present++;
                    }
                }

                if (present == 0) {
                    w.println(max);
                    return;
                }
                max = i;
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));

            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

