	private static PrintWriter out;

	public static void main(String[] args) throws FileNotFoundException{







		MyScanner sc = new MyScanner();

		out = new PrintWriter(new BufferedOutputStream(System.out)); 


		int n = sc.ni();

		if(n == 1){
			HashSet<Integer> one = new HashSet<>();
			for(int i = 0; i < 6; i++) one.add(sc.ni());
			for(int i = 1; i < 10; i++){
				if(!onePossible(i, one)){
					out.println(i - 1);
					break;
				}
			}
		}else if(n == 2){
			HashSet<Integer> one = new HashSet<>();
			HashSet<Integer> two = new HashSet<>();
			for(int i = 0; i < 6; i++) one.add(sc.ni());
			for(int i = 0; i < 6; i++) two.add(sc.ni());

			for(int i = 1; i < 100; i++){
				if(!twoPossible(i, one, two)){
					out.println(i - 1);
					break;
				}
			}
		}else{
			HashSet<Integer> one = new HashSet<>();
			HashSet<Integer> two = new HashSet<>();
			HashSet<Integer> three = new HashSet<>();
			for(int i = 0; i < 6; i++) one.add(sc.ni());
			for(int i = 0; i < 6; i++) two.add(sc.ni());
			for(int i = 0; i < 6; i++) three.add(sc.ni());

			for(int i = 1; i < 1000; i++){
				if(!threePossible(i, one, two, three)){
					out.println(i - 1);
					break;
				}
			}
		}

		out.close();
	}

	private static boolean onePossible(int cur, HashSet<Integer> one){
		return one.contains(cur);
	}

	private static boolean twoPossible(int n, HashSet<Integer> one, HashSet<Integer> two){
		if(n < 10)
			return onePossible(n, one) || onePossible(n, two);

		return (one.contains(n % 10) && two.contains(n / 10)) || (one.contains(n / 10) && two.contains(n % 10));
	}

	private static boolean threePossible(int n, HashSet<Integer> one, HashSet<Integer> two, HashSet<Integer> three){
		if(n < 100)
			return twoPossible(n, one, two) || twoPossible(n, one, three) || twoPossible(n, two, three);

		return (one.contains(n % 10) && two.contains(n % 100 / 10) && three.contains(n / 100)) ||
				(one.contains(n % 10) && three.contains(n % 100 / 10) && two.contains(n / 100)) ||
				(two.contains(n % 10) && one.contains(n % 100 / 10) && three.contains(n / 100)) ||
				(two.contains(n % 10) && three.contains(n % 100 / 10) && one.contains(n / 100)) ||
				(three.contains(n % 10) && two.contains(n % 100 / 10) && one.contains(n / 100)) ||
				(three.contains(n % 10) && one.contains(n % 100 / 10) && two.contains(n / 100));
	}
}

