		for (int i = 1; i <= m.size(); i++) {
			if (!m.containsKey(i))
				break;
			res = i;
		}
		return res;
	}

	static int mxNum(HashMap<Integer, Boolean> m1, HashMap<Integer, Boolean> m2) {
		int res = 0;
		HashMap<Integer, Boolean> all = new HashMap<>();
		all.putAll(m1);
		all.putAll(m2);
		res = mxNum(all);
		if (res < 9)
			return res;
		for (int i = 10; i <= 99; i++) {
			int d1 = i / 10;
			int d2 = i % 10;

			if (!(m1.containsKey(d1) && m2.containsKey(d2)) && !(m1.containsKey(d2) && m2.containsKey(d1))) {

				break;
			}
			res = i;
		}
		return res;
	}

	static int mxNum(ArrayList<HashMap<Integer, Boolean>> cubes) {
		int res = 0;
		for(int n = 1; n < 10; n++) {
			for(int i = 0; i < 3; i++) {
				if(cubes.get(i).containsKey(n)) {
					res = n;
					break;
				}
			}
			if(res != n) break;
		}
		if(res < 9) return res;
		for(int n = 10; n < 100; n++) {
			String s = String.valueOf(n);
			int d1 = s.charAt(0) - '0';
			int d2 = s.charAt(1) - '0';
			boolean f = false;
			for(int i = 0; i < 3; i++) {
				f = false;
				if(cubes.get(i).containsKey(d1)) {
					for(int j = 0; j < 3; j++) {
						if(i == j) continue;
						if(cubes.get(j).containsKey(d2)) {
							res = n;
							f = true;
							break;
						}
					}
				}
				if(f) break;
			}
			if(res != n) break;
		}
		if(res < 99) return res;
		for (int n = 1; n <= 999; n++) {
			String s = String.valueOf(n);
			int d1 = s.charAt(0) - '0';
			int d2 = s.charAt(1) - '0';
			int d3 = s.charAt(2) - '0';
			boolean f = false;
			for (int i = 0; i < 3; i++) {
				f = false;
				if (cubes.get(i).containsKey(d1)) {
					for (int j = 0; j < 3; j++) {
						if(i == j) continue;
						if (cubes.get(j).containsKey(d2)) {
							for (int k = 0; k < 3; k++) {
								if(k == i || k == j) continue;
								if (cubes.get(k).containsKey(d3)) {
									res = n;
									f = true;
									break;
								}
							}
						}
						if(f) break;
					}
				}
				if(f)break;
			}
			if (res != n)
				break;
		}
		return res;
	}

