public class Main {

    static class Cube {

        private boolean[] hasDigit;

        public boolean[] getHasDigit() {
            return hasDigit;
        }

        public Cube(int[] digits) {
            hasDigit = new boolean[10];
            Arrays.fill(hasDigit,false);

            for (int x: digits) {
                hasDigit[x] = true;
            }
        }

        public static void solve() {

            Scanner in = new Scanner(System.in);
            int n = in.nextInt();
            Cube[] cubes = new Cube[n];
            boolean[] wasCube = new boolean[n];

            for (int i = 0; i < n; i++) {
                int[] array = new int[6];
                for (int j = 0; j < 6; j++) {
                    array[j] = in.nextInt();
                }
                cubes[i] = new Cube(array);
            }

            ArrayList shuffle = new ArrayList<>();
            if (n == 1) {
                shuffle.add(new int[]{0});
            } else if (n == 2) {
                shuffle.add(new int[]{0, 1});
                shuffle.add(new int[]{1, 0});
            } else {
                shuffle.add(new int[]{0, 1, 2});
                shuffle.add(new int[]{0, 2, 1});
                shuffle.add(new int[]{1, 0, 2});
                shuffle.add(new int[]{1, 2, 0});
                shuffle.add(new int[]{2, 0, 1});
                shuffle.add(new int[]{2, 1, 0});
            }


            for (int x = 1; x < 1000; x++) {
                String number = Integer.toString(x);
                boolean ok = false;

                for (int i = 0; i < shuffle.size(); i++) {
                    int[] permutation = (int[]) shuffle.get(i);
                    int count = 0;
                    Arrays.fill(wasCube, false);

                    for (int j = 0; j < number.length(); j++) {
                        for (int k = 0; k < cubes.length; k++) {
                            boolean[] search = cubes[permutation[k]].getHasDigit();
                            if (!wasCube[permutation[k]] && search[Character.getNumericValue(number.charAt(j))]) {
                                count++;
                                wasCube[permutation[k]] = true;
                                break;
                            }
                        }
                    }

                    if (count == number.length()) {
                        ok = true;
                        break;
                    }
                }

                if (!ok) {
                    System.out.println(x-1);
                    return;
                }

            }
            System.out.println(999);
        }
    }

    public static void main(String[] args) {
        Cube.solve();
    }
}

