		for(int i = 1; i <= Math.pow(2, digits.length); i++) {
			int ones = 0;
			int[]onepos = new int[digits.length];
			for(int j = 0 ; j < digits.length; j++) {
				if((i & (1 << j)) != 0) {
					ones++;
					onepos[j] = 1;
				}
			}
			if(ones != rep.length()) {
				continue;
			} else {
				String perm = "";
				for(int l = 0; l < digits.length; l++)
					if(onepos[l] == 1)
						perm += (""+l);

				char[]rot = perm.toCharArray();
				Arrays.sort(rot);

				if(correct(rot, rep))
					return false;
				while(j_next_permutation(rot))
					if(correct(rot, rep))
						return false;
			}
		}
		return true;
	}
	public static boolean correct(char[]rot, String rep) {
		for(int k = 0; k < rot.length; k++) {
			if(!contains(rot[k] - '0', rep.charAt(k)-'0'))
				return false;
		}
		return true;
	}
	public static boolean contains(int index, int num) {
		for(int i = 0; i < 6; i++)
			if(digits[index][i] == num)
				return true;
		return false;
	}
	public static boolean j_next_permutation(char[] a) {
		int F = 0, L = a.length, I = a.length;
		if (F == L || F == --I) return false;
		for (;;) {
			int Ip = I;
			if (a[--I] < a[Ip]) {
				int J = L;
				for (; !(a[I] < a[--J]););
				char tmp = a[I]; a[I] = a[J]; a[J] = tmp;
				for (int i = Ip; i < ((L - Ip) % 2 == 0 ? Ip + (L - Ip) / 2 : Ip + (L - Ip) / 2 + 1); ++i) {
					char tm = a[i]; a[i] = a[a.length - 1 - i + Ip]; a[a.length - 1 - i + Ip] = tm;
				}
				return true;
			}
			if (I == F) {
				for (int i = 0; i < ((L - F) % 2 == 0 ? (L - F) / 2 : (L - F) / 2 + 1); ++i) {
					char tm = a[i]; a[i] = a[a.length - 1 - i]; a[a.length - 1 - i] = a[i];
				}
				return false;
			}
		}
	}
}

