	static boolean canForm(int x,int mask)
	{
		if(x==0)
			return true;
		if(x/10==0)
		{
			for(int i=0;i<n;i++){
				if(cubes[i].contains(x)&& (mask & 1<<i)==0)
					return true;
			}
			return false;			
		}
		else{
			for(int i=0;i<n;i++)
			{
				if((mask & 1<<i) ==1)
					continue;
				if(cubes[i].contains(x%10)&& canForm(x/10,(mask|(1<<i))))
					return true;

			}

			return false;	
		}
	}

}

