public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        boolean check(List<Integer> a, boolean[] occu, boolean[][] dp, int ind) {
            if (ind == a.size()) return true;
            for (int i = 0; i < occu.length; ++i) {
                if (!occu[i] && dp[i][a.get(ind)]) {
                    occu[i] = true;
                    if (check(a, occu, dp, ind + 1)) return true;
                    occu[i] = false;
                }
            }
            return false;
        }

        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            boolean[][] dp = new boolean[n][10];
            for (int i = 0; i < n; ++i) Arrays.fill(dp[i], false);

            for (int i = 0; i < n; ++i) {
                int a;
                for (int j = 0; j < 6; ++j) {
                    a = in.nextInt();
                    dp[i][a] = true;
                }
            }

            int res = 0;
            boolean[] occu = new boolean[n];
            for (int i = 1; i <= 999; ++i) {
                Arrays.fill(occu, false);
                List<Integer> foo = new ArrayList<>();
                int j = i;
                while (j > 0) {
                    foo.add(j % 10);
                    j /= 10;
                }
                if (check(foo, occu, dp, 0)) {
                    res = i;
                } else break;
            }
            out.println(res);
        }

    }
}

