public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            TreeSet<Integer>[] v = new TreeSet[n];
            for (int i = 0; i < n; ++i) {
                v[i] = new TreeSet<>();
                for (int j = 0; j < 6; ++j) {
                    v[i].add(in.nextInt());
                }
            }
            TreeSet<Integer> nums = generateAllNums(v);
            int ans = 0;
            for (int i = 1; i <= 999; ++i) {
                if (!nums.contains(i)) {
                    break;
                }
                ans = i;
            }
            out.println(ans);
        }

        private TreeSet<Integer> generateAllNums(TreeSet<Integer>[] v) {
            boolean[] avail = new boolean[v.length];
            Arrays.fill(avail, true);
            TreeSet<Integer> ret = backtrack(v, 0, avail, 0);
            return ret;
        }

        private TreeSet<Integer> backtrack(TreeSet<Integer>[] v, int i, boolean[] avail, int accm) {
            if (i == v.length) {
                TreeSet<Integer> ret = new TreeSet<>();
                ret.add(accm);
                return ret;
            }
            TreeSet<Integer> ret = backtrack(v, i + 1, avail, accm);
            for (int j = 0; j < v.length; ++j) {
                if (avail[j]) {
                    avail[j] = false;
                    for (int x : v[j]) {
                        ret.addAll(backtrack(v, i + 1, avail, 10 * accm + x));
                    }
                    avail[j] = true;
                }
            }
            return ret;
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 65536 / 2);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

