public class Codeforces {

    static char t[][];
    static int n, m;
    static int r0=0, c0=0, r1=0, c1=0; 
    static int dx[] = {0,0,-1,1};
    static int dy[] = {-1,1,0,0};
    static int ans;
    static boolean used[] = new boolean[4];
    static char dir[];
    static int myDir[] = new int[4];

    public static void main(String[] args) throws IOException{
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        String toks[] = in.readLine().split(" ");
        n = Integer.parseInt(toks[0]);
        m = Integer.parseInt(toks[1]);
        t = new char[n][];
        for (int i = 0; i < n; i++) {
            String s = in.readLine();
            t[i] = s.toCharArray();
            if( s.indexOf("S")>=0 ) {
                r0=i;
                c0=s.indexOf("S");
            }
            if( s.indexOf("E")>=0 ) {
                r1=i;
                c1=s.indexOf("E");
            }
        }
        dir = in.readLine().toCharArray();
        go(0);
        System.out.println(ans);
    }

    static void go(int idx) {
        if(idx==4) {
            if(go2(r0, c0, 0)) ans++;
        } else {
            for (int i = 0; i < 4; i++) {
                if(!used[i]) {
                    used[i] = true;
                    myDir[idx] = i;
                    go(idx+1);
                    used[i] = false;
                }
            }
        }
    }

    static boolean go2(int r, int c, int idx) {
        if(r==r1 && c==c1) return true;
        if(r<0 || r==n || c<0 || c==m) return false;
        if(t[r][c]=='#') return false;
        if(idx==dir.length) return false;
        return go2(r + dx[myDir[dir[idx]-'0']], c + dy[myDir[dir[idx]-'0']], idx + 1);
    }
}

import java.util.Scanner;

public class Main {
	static char maze[][] = null;
	static int nRow, nCol;
	static char[] ops = {'a', 'd', 's', 'w'};
	static int[] dirs = null;
	static int startX, startY, endX, endY;
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		nRow = in.nextInt();
		nCol = in.nextInt();
		maze = new char[nRow][nCol];
		for(int i = 0; i < nRow; i++) {
			String str = in.next();
			maze[i] = str.toCharArray();
			for(int j = 0; j < nCol; j++) {
				if(maze[i][j] == 'S') {
					startX = i; startY = j;
				}
				else if(maze[i][j] == 'E') {
					endX = i; endY = j;
				}
			}
		}
		String str = in.next();
		dirs = new int[str.length()];
		for(int i = 0; i < str.length(); i++)
			dirs[i] = str.charAt(i) - '0';

		int cnt = 0;
		do {
			if(tryMove())
				cnt++;
		}while(next_permutation(ops, 0, ops.length));
		System.out.println(cnt);
	}
	static boolean tryMove() {
		int cx = startX, cy = startY;
		for(int i = 0; i < dirs.length; i++) {
			int op = dirs[i];
			switch(ops[op]) {
			case 'a':
				cy--;
				break;
			case 'd':
				cy++;
				break;
			case 's':
				cx++;
				break;
			case 'w':
				cx--;
				break;
			}
			if(cx < 0 || cx >= nRow || cy < 0 || cy >= nCol)
				return false;
			if(maze[cx][cy] == '#')
				return false;
			if(cx == endX && cy == endY)
				return true;
		}
		return false;
	}
	static boolean next_permutation(char[] str, int start, int end) {
		if(str == null || str.length <= 1)
			return false;
		int i = end - 2;
		for(; i >= start && str[i] >= str[i + 1]; i--);
		if(i == start - 1)
			return false;

		int j = i + 1;
		for(; j < end && str[j] > str[i]; j++);
		swap(str, i, j - 1);

		i++;
		int k = end - 1;
		for(; i < k; i++, k--) {
			swap(str, i, k);
		}
		return true;
	}
	static void swap(char[] str, int a, int b) {
		char tmp =  str[a];
		str[a] = str[b];
		str[b] = tmp;
	}
}

