	public static ArrayList<String> l= new ArrayList<>();
	public static int sx, sy, ex,ey, n, m;
	public static char [][] g;
	public static void main(String[] args) throws IOException {
		FastScanner in= new FastScanner(System.in);
		n= in.nextInt();
		m= in.nextInt();
		g= new char[n][m];
		sx=0;
		sy=0;
		ex=0;
		ey=0;
		for (int i = 0; i < n; i++) {
			char [] cc= in.next().toCharArray();
			for (int j = 0; j < cc.length; j++) {
				g[i][j]= cc[j];
				if(g[i][j]=='S') {
					sx= j;
					sy=i;
				}
				if(g[i][j]=='E') {
					ex=j;
					ey=i;
				}
			}
		}
		ins= in.next();
		int [] perm= new int[4];
		boolean [] used= new boolean[4];
		go(perm,used, 0);
		int res=0;
		for(String cur: l) {
			res+=t(cur);
		}
		System.out.println(res);

	}
	public static int t(String ins) {
		int curx=sx;
		int cury=sy;
		for (int i = 0; i < ins.length(); i++) {
			int nx= curx+dx[ins.charAt(i)-'0'];
			int ny= cury+dy[ins.charAt(i)-'0'];
			if(gucc(nx,ny)) {
				curx=nx;
				cury=ny;
				if(g[ny][nx]=='E') return 1;
			}
			else {
				return 0;
			}
		}
		if(curx==ex&&cury==ey) {
			return 1;
		}
		return 0;
	}
	public static void go(int[] perm, boolean[] used, int k) {
        if (k == perm.length) {
        	String nex="";
        	for (int i = 0; i < ins.length(); i++) {
				if(ins.charAt(i)-'0'==0) {
					nex+=perm[0];
				}
				else if(ins.charAt(i)-'0'==1) nex+=perm[1];
				else if(ins.charAt(i)-'0'==2) nex+=perm[2];
				else if(ins.charAt(i)-'0'==3) nex+=perm[3];
			}
        	l.add(nex);
        }
        else {
            for (int i=0; i<perm.length; i++) {
                if (!used[i]) {
                    perm[k] = i;
                    used[i] = true;
                    go(perm, used, k+1);
                    used[i] = false;
                }
            }
        }
    }
	public static boolean gucc(int x, int y) {
		return x>=0&&x<m&&y>=0&&y<n&&(g[y][x]!='#');
	}
