public class B {
    String fileName = "B";

    public int[] dx = new int[]{1, -1, 0, 0};
    public int[] dy = new int[]{0, 0, 1, -1};

    public boolean next_permutation(int[] p) {
        for (int a = p.length - 2; a >= 0; --a)
            if (p[a] < p[a + 1])
                for (int b = p.length - 1; ; --b)
                    if (p[b] > p[a]) {
                        int t = p[a];
                        p[a] = p[b];
                        p[b] = t;
                        for (++a, b = p.length - 1; a < b; ++a, --b) {
                            t = p[a];
                            p[a] = p[b];
                            p[b] = t;
                        }
                        return true;
                    }
        return false;
    }

    public int n, m;

    public boolean check(int i, int j) {
        return i < n && i >= 0 && j < m && j >= 0;
    }

    public void solve() throws IOException {
        int[] curPerm = new int[]{0, 1, 2, 3};
        n = nextInt();
        m = nextInt();
        int startI = -1, endI = -1;
        int startJ = -1, endJ = -1;
        boolean[][] lab = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String curS = nextToken();
            for (int j = 0; j < m; j++) {
                char curChar = curS.charAt(j);
                lab[i][j] = curChar == '#';
                if (curChar == 'S') {
                    startI = i;
                    startJ = j;
                } else if (curChar == 'E') {
                    endI = i;
                    endJ = j;
                }
            }
        }
        String commands = nextToken();
        int ans = 0;
        do {
            int curI = startI;
            int curJ = startJ;
            for (int i = 0; i < commands.length(); i++) {
                int curCommand = curPerm[Integer.parseInt(Character.toString(commands.charAt(i)))];
                curI += dx[curCommand];
                curJ += dy[curCommand];
                if (curI == endI && curJ == endJ) {
                    ans++;
                    break;
                }
                if (!check(curI, curJ) || lab[curI][curJ])
                    break;
            }
        } while (next_permutation(curPerm));
        out.print(ans);
    }

    public void run() {
        try {
            br = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);

            solve();

            out.close();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    BufferedReader br;
    StringTokenizer in;
    PrintWriter out;

    public String nextToken() throws IOException {
        while (in == null || !in.hasMoreTokens()) {
            in = new StringTokenizer(br.readLine());
        }
        return in.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    public double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    public long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    public static void main(String[] args) throws IOException {
        Locale.setDefault(Locale.US);
        new B().run();
    }

}

