    static class Good_bye_2 {
        HashMap<Integer, Character>[] hm;
        int temp = 0;

        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            int n = in.scanInt();
            int m = in.scanInt();
            char arr[][] = new char[n][m];
            int sr = -1;
            int sc = -1;
            int er = -1;
            int ec = -1;

            hm = new HashMap[24];
            for (int i = 0; i < 24; i++) {
                hm[i] = new HashMap<>();
            }
            permute("LRUD", 0, 3);


            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    arr[i][j] = in.scanChar();
                    if (arr[i][j] == 'S') {
                        sr = i;
                        sc = j;

                    }
                    if (arr[i][j] == 'E') {
                        er = i;
                        ec = j;
                    }

                }
            }

            String str = in.scanString();


            int ans = 0;
            for (int i = 0; i < 24; i++) {
                int cx = sr;
                int cy = sc;

                boolean flag = true;
                for (int j = 0; j < str.length(); j++) {
                    int temp = (int) str.charAt(j) - '0';
                    if (hm[i].get(temp) == 'L') {
                        cy--;
                        if (!isvalid(n, m, cx, cy, arr)) {
                            flag = false;
                            break;
                        }
                    } else if (hm[i].get(temp) == 'R') {
                        cy++;
                        if (!isvalid(n, m, cx, cy, arr)) {
                            flag = false;
                            break;
                        }
                    } else if (hm[i].get(temp) == 'U') {
                        cx--;
                        if (!isvalid(n, m, cx, cy, arr)) {
                            flag = false;
                            break;
                        }
                    } else if (hm[i].get(temp) == 'D') {
                        cx++;
                        if (!isvalid(n, m, cx, cy, arr)) {
                            flag = false;
                            break;
                        }
                    }


                    if (cx == er && cy == ec) {
                        flag = true;
                        break;
                    }


                }


                if (flag && cx == er && cy == ec) {
                    ans++;

                }

            }


            out.println(ans);
        }

        boolean isvalid(int n, int m, int x, int y, char arr[][]) {
            if (x >= 0 && x < n && y >= 0 && y < m) {
                if (arr[x][y] != '#') {
                    return true;
                } else {
                    return false;
                }

            }
            return false;
        }

        private void permute(String str, int l, int r) {
            if (l == r) {

                for (int i = 0; i < str.length(); i++) {
                    hm[temp].put(i, str.charAt(i));
                }
                temp++;
            } else {
                for (int i = l; i <= r; i++) {
                    str = swap(str, l, i);
                    permute(str, l + 1, r);
                    str = swap(str, l, i);
                }
            }
        }

        public String swap(String a, int i, int j) {
            char temp;
            char[] charArray = a.toCharArray();
            temp = charArray[i];
            charArray[i] = charArray[j];
            charArray[j] = temp;
            return String.valueOf(charArray);
        }

    }

    static class ScanReader {
        private byte[] buf = new byte[4 * 1024];
        private int index;
        private BufferedInputStream in;
        private int total;

        public ScanReader(InputStream inputStream) {
            in = new BufferedInputStream(inputStream);
        }

        private int scan() {
            if (index >= total) {
                index = 0;
                try {
                    total = in.read(buf);
                } catch (Exception e) {
                    e.printStackTrace();
                    ;
                }
                if (total <= 0) return -1;
            }
            return buf[index++];
        }

        public char scanChar() {
            int c = scan();
            while (isWhiteSpace(c)) c = scan();
            return (char) c;
        }

        public int scanInt() {
            int integer = 0;
            int n = scan();
            while (isWhiteSpace(n)) n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    integer *= 10;
                    integer += n - '0';
                    n = scan();
                }
            }
            return neg * integer;
        }

        public String scanString() {
            int c = scan();
            while (isWhiteSpace(c)) c = scan();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = scan();
            } while (!isWhiteSpace(c));
            return res.toString();
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1) return true;
            else return false;
        }

    }
}

