		if (grid[x][y] == 'E') {
			reach = true;
			return;
		}
		if(grid[x][y] == '#')
			return;
		if(idx == instr.length())
			return;
		int dir = d[instr.charAt(idx) - '0'];
		int x2 = x + dx[dir];
		int y2 = y + dy[dir];
		if (valid(x2, y2))
			dfs(x2, y2, idx + 1);

	}

	static boolean valid(int x, int y) {
		return x >= 0 && y >= 0 && x < grid.length && y < grid[0].length;
	}

	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();
		grid = new char[n][m];
		for (int i = 0; i < n; i++) {
			grid[i] = sc.next().toCharArray();
		}
		int stx = 0;
		int sty = 0;
		for (int i = 0; i < n; i++)
			for (int j = 0; j < m; j++)
				if (grid[i][j] == 'S') {
					stx = i;
					sty = j;
				}
		instr = sc.next();
		d = new int[] { 0, 1, 2, 3 };
		int cnt = 0;
		do {
			reach = false;
			dfs(stx, sty, 0);
			if (reach)
				cnt++;
		}
		while (nextPermutation(d));
		System.out.println(cnt);
	}

	static boolean nextPermutation(int[] c) {

		int first = getFirst(c);
		if (first == -1)
			return false;


		int toSwap = c.length - 1;
		while (c[first] >= c[toSwap])
			--toSwap;


		swap(c, first++, toSwap);


		toSwap = c.length - 1;
		while (first < toSwap)
			swap(c, first++, toSwap--);
		return true;
	}



	static int getFirst(int[] c) {
		for (int i = c.length - 2; i >= 0; i--)
			if (c[i] < c[i + 1])
				return i;
		return -1;
	}

	static void swap(int[] c, int i, int j) {
		int tmp = c[i];
		c[i] = c[j];
		c[j] = tmp;
	}

