    static class BNewYearAndBuggyBot {
        static int n;
        static int m;
        static char[][] grid;
        static String s;

        static boolean dfs(int i, int j, int pos, int up, int down, int left, int right) {
            if (pos == s.length() && grid[i][j] != 'E') {
                return false;
            }
            if (grid[i][j] == 'E') {
                return true;
            }
            if (grid[i][j] == '#') {
                return false;
            }
            boolean b;
            if (s.charAt(pos) - '0' == up) {
                if (i == 0) {
                    return false;
                }
                return dfs(i - 1, j, pos + 1, up, down, left, right);
            }
            if (s.charAt(pos) - '0' == down) {
                if (i == n - 1) {
                    return false;
                }
                return dfs(i + 1, j, pos + 1, up, down, left, right);
            }
            if (s.charAt(pos) - '0' == left) {
                if (j == 0) {
                    return false;
                }
                return dfs(i, j - 1, pos + 1, up, down, left, right);
            }
            if (s.charAt(pos) - '0' == right) {
                if (j == m - 1) {
                    return false;
                }
                return dfs(i, j + 1, pos + 1, up, down, left, right);
            }
            return false;
        }

        public void solve(int testNumber, inputClass sc, PrintWriter out) {
            n = sc.nextInt();
            m = sc.nextInt();
            int startx = 0, starty = 0;
            grid = new char[n][m];
