                        startx = i;
                        starty = j;
                    }
                }
                grid[i] = a.toCharArray();
            }
            s = sc.nextLine();
            long ans = 0;
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    if (j != i) {
                        for (int k = 0; k < 4; k++) {
                            if (k != i && k != j) {
                                for (int l = 0; l < 4; l++) {
                                    if (l != i && l != j && l != k) {
                                        if (dfs(startx, starty, 0, i, j, k, l)) {
                                            ans++;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            out.println(ans);
        }

    }

