class Solver{
	Reader ip = new Reader(System.in) ;	  
	PrintWriter op = new PrintWriter(System.out) ;
	int n,m ;
	char c[][],dir[] ;
	int per[] = new int[4] ;
	int hit[] = new int[4] ;
	int ans=0 ;
	int sx,sy,ex,ey ;
	boolean valid(int x,int y){
		if(x<0 || x>=n || y<0 || y>=m) return false ;
		return c[x][y]!='#' ;
	}
	boolean reached(int x,int y){
		return x==ex && y==ey ;
	}
	boolean check(){
		int x = sx ; int y = sy ;
		for(int i=0 ; i<dir.length ; i++){
			int bit = per[dir[i]-'0'] ;
			switch(bit){
				case 0 : x-- ;
				break ;
				case 1 : y++ ;
				break ;
				case 2 : x++ ;
				break ;
				case 3 : y-- ;
			}
			if(!valid(x,y)) return false ;
			if(reached(x,y)) return true ;
		}
		return reached(x,y) ;
	}
	void permute(int idx){
		if(idx==4){
			boolean flag = check() ;
			if(flag) ans++ ;
			return ;
		}
		for(int i=0 ; i<4 ; i++){
			if(hit[i]==0){
				hit[i]=1 ;
				per[idx]=i ;
				permute(idx+1) ;
				hit[i]=0 ;
			}
		}
	}
	public void Solve() throws IOException{
		n = ip.i() ;
		m = ip.i() ;
		c = new char[n][] ;
		for(int i=0 ; i<n ; i++)
			c[i] = ip.s().toCharArray() ;
		sx=-1 ; sy=-1 ; ex=-1 ; ey=-1 ;
		for(int i=0 ; i<n ; i++)
			for(int j=0 ; j<m ; j++)
				if(c[i][j]=='S'){
					sx=i ; sy=j ;
				}else if(c[i][j]=='E'){
					ex=i ; ey=j ;
				}
		dir = ip.s().toCharArray() ;
		permute(0) ;
		pln(ans) ;
	}
	void Finish(){
		op.flush();
		op.close();
	}
	void p(Object o){
		op.print(o) ;
	}
	void pln(Object o){
		op.println(o) ;
	}		
}
