import java.lang.reflect.Array;
import java.util.*;
public class Main {
    static Scanner in = new Scanner(System.in);

    public static void main(String[] args) {
        int possibilities = 0;
        int n = Integer.parseInt(in.next());
        int m = Integer.parseInt(in.next());
        Maze maze = new Maze(n, m);
        String instructions = in.nextLine();

        ArrayList<String> perms = permutations();
        permLoop:
        for(int i = 0; i < perms.size(); i++) {
            maze.reset();
            String sequence = perms.get(i);
            char right = sequence.charAt(0);
            char up = sequence.charAt(1);
            char left = sequence.charAt(2);
            char down = sequence.charAt(3);
            for(int j = 0; j < instructions.length(); j++) {
                if(instructions.charAt(j) == right) {
                    if(!maze.move(0)) {
                        continue permLoop;
                    }
                }
                else if(instructions.charAt(j) == up) {
                    if(!maze.move(1)) {
                        continue permLoop;
                    }
                }
                else if(instructions.charAt(j) == left) {
                    if(!maze.move(2)) {
                        continue permLoop;
                    }
                }
                else if(instructions.charAt(j) == down) {
                    if(!maze.move(3)) {
                        continue permLoop;
                    }
                }
                if(maze.checkForWin()) {
                    possibilities++;
                    continue permLoop;
                }
            }
        }
        System.out.println(possibilities);
    }

    public static ArrayList<String> permutations() {
        HashSet<String> perms  = new HashSet<>();
        for(int i = 0; i < 1000; i++) {
            String base = "";
            ArrayList<Integer> nums = new ArrayList<>();
            nums.add(0);
            nums.add(1);
            nums.add(2);
            nums.add(3);
            for(int j = 0; j < 4; j++) {
                int num = nums.get((int) (Math.random() * nums.size()));
                base += num;
                nums.remove(nums.indexOf(num));
            }
            perms.add(base);
        }
        ArrayList<String> answer = new ArrayList<>(perms);

        return answer;
    }



    public static class Maze {

        int dc[][] = {{1, 0} , {0, 1}, {-1, 0}, {0, -1}};
        private int xLowBound;
        private int xHighBound;
        private int yLowBound;
        private int yHighBound;
        private int currX;
        private int currY;
        private int startX;
        private int startY;
        private int endX;
        private int endY;
        private char array[][];

        public Maze(int n, int m) {
            xLowBound = 0;
            yLowBound = 0;
            xHighBound = n - 1;
            yHighBound = m - 1;
            array = new char[n][m];
            in.nextLine();
            for(int i = 0; i < n; i++) {
                String input = in.nextLine();
                for(int j = 0; j < m; j++) {
                    array[i][j] = input.charAt(j);
                    if(input.charAt(j) == 'S') {
                        startX = currX = i;
                        startY = currY = j;
                    }
                    else if(input.charAt(j) == 'E') {
                        endX = i;
                        endY = j;
                    }
                }
            }
        }

        public boolean move(int direction) {
            currX += dc[direction][0];
            currY += dc[direction][1];
            if(currX < xLowBound || currX > xHighBound) {
                return false;
            }
            if(currY < yLowBound || currY > yHighBound) {
                return false;
            }
            if(array[currX][currY] == '#') {
                return false;
            }
            return true;
        }

        public boolean checkForWin() {
            if(array[currX][currY] == 'E') {
                return true;
            }
            return false;
        }

        public void reset() {
            currX = startX;
            currY = startY;
        }

    }
}

