                }
                if (currentCol < 0 || currentCol >= m) {




                    return false;

                }
                if (arr[currentRow][currentCol] == '#') {




                    return false;

                }
            }




            return false;
        }

        boolean nextPermutation(int[] arr) {
            int n = arr.length;
            int i;
            for (i = n - 1; i > 0; --i) {
                if (arr[i] > arr[i - 1])
                    break;
            }
            if (i == 0)
                return false;
            int x = arr[i - 1], min = i;
            for (int j = i + 1; j < n; ++j) {
                if (arr[j] > x && arr[j] < arr[min])
                    min = j;
            }

            arr[i - 1] = arr[min];
            arr[min] = x;
            Arrays.sort(arr, i, n);
            return true;
        }

