public class CODE {

    static Scanner sc = new Scanner(System.in);
    static String moves[] = {"><^v", "><v^", ">^<v", ">^v<", ">v^<", ">v<^", "<>^v",
        "<>v^", "<^>v", "<^v>", "<v^>", "<v>^", "^<>v", "^<v>", "^><v", "^>v<", "^v><",
        "^v<>", "v<^>", "v<>^", "v^<>", "v^><", "v>^<", "v><^"};

    static char map[][];
    static Point S = null;
    static String way;
    static int n, m;

    static void fillMap() {
        n = sc.nextInt();
        m = sc.nextInt();
        map = new char[n][m];

        for (int i = 0; i < n; i++) {
            String currentRow = sc.next();
            for (int j = 0; j < m; j++) {
                map[i][j] = currentRow.charAt(j);
                if (map[i][j] == 'S') {
                    S = new Point(i, j);
                }

            }
        }

    }

    static boolean tryMove(String move) {
        Point robot = new Point(S.x, S.y);

        for (int i = 0; i < way.length(); i++) {
            switch (move.charAt(way.charAt(i) - '0')) {
                case '>':
                    robot.x++;
                    break;
                case '<':
                    robot.x--;
                    break;
                case '^':
                    robot.y++;
                    break;
                case 'v':
                    robot.y--;
                    break;
            }
            if (robot.y == m || robot.x == n || robot.x < 0 || robot.y < 0) {
                return false;
            }

            if (map[robot.x][robot.y] == '#') {
                return false;
            }

            if (map[robot.x][robot.y] == 'E') {
                return true;
            }

        }
        return false;
    }

    public static void main(String[] args) {
        fillMap();
        way = sc.next();
        int c = 0;
        for (String move : moves) {
            if (tryMove(move)) {
                c++;
            }
        }
        System.out.println(c);
    }

}

