                        x1 = i;
                        y1 = j;
                    }
                }
            }
            command = new int[4];
            int arr[] = new int[4];
            for (int i = 0; i < 4; i++) {
                arr[i] = i;
            }
            heapPermutation(arr, 4, 4);
            comm = in.readString();


            int ans = 0;
            for (int i = 0; i < 24; i++) {
                for (int j = 0; j < 4; j++) {
                    command[j] = ar[i][j];
                }
                if (solve(x1, y1, 0)) {
                    ans++;
                }
            }
            out.print(ans);

        }

        boolean solve(int x, int y, int no) {

            if (x >= n || y >= m || x < 0 || y < 0)
                return false;
            if (str[x].charAt(y) == '#')
                return false;
            if (str[x].charAt(y) == 'E')
                return true;
            if (no >= comm.length())
                return false;
            if (command[comm.charAt(no) - '0'] == 0) {
                return solve(x + 1, y, no + 1);
            }
            if (command[comm.charAt(no) - '0'] == 1) {
                return solve(x, y - 1, no + 1);
            }
            if (command[comm.charAt(no) - '0'] == 2) {
                return solve(x - 1, y, no + 1);
            }
            if (command[comm.charAt(no) - '0'] == 3) {
                return solve(x, y + 1, no + 1);
            }
            return false;
        }

        void heapPermutation(int a[], int size, int n) {


            if (size == 1) {


                for (int i = 0; i < 4; i++) {
                    ar[ct][i] = a[i];
                }
                ct++;
            }

            for (int i = 0; i < size; i++) {
                heapPermutation(a, size - 1, n);



                if (size % 2 == 1) {
                    int temp = a[0];
                    a[0] = a[size - 1];
                    a[size - 1] = temp;
                }



                else {
                    int temp = a[i];
                    a[i] = a[size - 1];
                    a[size - 1] = temp;
                }
            }
        }

    }

