public class B {
	static int[] map = new int[4];
	static char[][] mat;
	static String s;
	static boolean recur(int r, int c, int ind) {

		if(r < 0 || c < 0 || r>= mat.length || c >= mat[0].length || mat[r][c] == '#') return false;
		if(ind == s.length() && mat[r][c] == 'E') {
			return true;
		}
		else if(ind == s.length()) return false;
		if(mat[r][c] == 'E') return true;
		int x = Integer.parseInt(s.substring(ind, ind+1));
		if(map[x] == 0) return recur(r-1,c,++ind);
		if(map[x] == 1) return recur(r+1,c,++ind);
		if(map[x] == 2) return recur(r,c+1,++ind);
		if(map[x] == 3) return recur(r,c-1,++ind);
		return true;
	}
	public static void main(String[] args) throws Exception {
		FastScanner sc = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);
		int n = sc.nextInt();
		int m = sc.nextInt();
		mat = new char[n][m];
		int sr = -1;
		int scol = -1;
		for(int i = 0; i < n; i++) {
			mat[i] = sc.next().toCharArray();
			for(int j = 0; j  < m; j++) {
				if(mat[i][j] == 'S') {
					sr = i;
					scol = j;
				}
			}
		}
		int res = 0;
		s = sc.next();
		int cnt = 0;
		for(int i = 0; i < 4; i++) {
			for(int j = 0; j < 4; j++) {
				for(int k = 0; k < 4; k++) {
					for(int l = 0; l < 4; l++) {
						if(i != j && i != k && i != l && j != k && j != l && k != l) {
							cnt++;

							map[0] = i;
							map[1] = j;
							map[2] = k;
							map[3] = l;
							if(recur(sr, scol, 0)) {
								++res;
							}
						}
					}
				}
			}
		}
		out.println(res);
		out.flush();
	}

	static class FastScanner {
		public BufferedReader reader;
		public StringTokenizer tokenizer;

		public FastScanner() {
			reader = new BufferedReader(new InputStreamReader(System.in), 32768);
			tokenizer = null;
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public String nextLine() {
			try {
				return reader.readLine();
			} catch (IOException e) {
				throw new RuntimeException(e);
			}
		}

	}
}

