        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Kattio in = new Kattio(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        int[] odx = {-1, 1, 0, 0};
        int[] ody = {0, 0, -1, 1};

        public void solve(int testNumber, Kattio in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] maze = new char[n][m];
            int sx = 0;
            int sy = 0;
            int ex = 0;
            int ey = 0;

            for (int i = 0; i < n; ++i) {
                char[] arr = in.next().toCharArray();
                for (int j = 0; j < m; ++j) {
                    maze[i][j] = arr[j];


                    if (maze[i][j] == 'S') {
                        sx = i;
                        sy = j;
                    } else if (maze[i][j] == 'E') {
                        ex = i;
                        ey = j;
                    }
                }
            }

            int[] dx = new int[4];
            int[] dy = new int[4];

            char[] map = in.next().toCharArray();

            int ans = 0;
            for (int i = 0; i < 4; ++i) {
                dx[i] = odx[0];
                dy[i] = ody[0];
                for (int j = 0; j < 4; ++j) {
                    if (i == j) continue;
                    dx[j] = odx[1];
                    dy[j] = ody[1];
                    for (int k = 0; k < 4; ++k) {
                        if (k == j || k == i) continue;
                        dx[k] = odx[2];
                        dy[k] = ody[2];
                        for (int t = 0; t < 4; ++t) {
                            if (t == k || t == j || t == i) continue;
                            dx[t] = odx[3];
                            dy[t] = ody[3];

                            int x = sx;
                            int y = sy;
                            boolean flag = false;
                            for (char c : map) {
                                int d = c - '0';

                                x += dx[d];
                                y += dy[d];

                                if (x == ex && y == ey) {
                                    flag = true;
                                    break;
                                }

                                if (x < 0 || x >= n || y < 0 || y >= m)
                                    break;

                                if (maze[x][y] == '#') {
                                    break;
                                }

                            }

                            if (flag)
                                ++ans;
                        }
                    }
                }
            }

            out.println(ans);


        }

    }

    static class Kattio extends PrintWriter {
        private BufferedReader r;
        private String line;
        private StringTokenizer st;
        private String token;

        public Kattio(InputStream i) {
            super(new BufferedOutputStream(System.out));
            r = new BufferedReader(new InputStreamReader(i));
        }

        public Kattio(InputStream i, OutputStream o) {
            super(new BufferedOutputStream(o));
            r = new BufferedReader(new InputStreamReader(i));
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public String next() {
            return nextToken();
        }

        private String peekToken() {
            if (token == null)
                try {
                    while (st == null || !st.hasMoreTokens()) {
                        line = r.readLine();
                        if (line == null) return null;
                        st = new StringTokenizer(line);
                    }
                    token = st.nextToken();
                } catch (IOException e) {
                }
            return token;
        }

        private String nextToken() {
            String ans = peekToken();
            token = null;
            return ans;
        }

    }
}

