    static class TaskB {
        static char[][] mat;
        static int n;
        static int m;
        static int x;
        static int y;
        static String digits;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            x = 0;
            y = 0;
            mat = new char[n][m];
            for (int i = 0; i < n; i++) {
                String str = in.readLine();
                for (int j = 0; j < m; j++) {
                    char c = str.charAt(j);
                    if (c == 'S') {
                        x = i;
                        y = j;
                    }
                    mat[i][j] = c;
                }
            }
            digits = in.readLine();
            int ans = 0;
            String arr[] = new String[4];
            arr[0] = "R";
            arr[1] = "L";
            arr[2] = "U";
            arr[3] = "D";

            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    for (int k = 0; k < 4; k++) {
                        for (int l = 0; l < 4; l++) {
                            if (i != j && i != k && i != l && j != k && j != l && k != l) {
                                if (sol(arr[i], arr[j], arr[k], arr[l])) {
                                    ans++;
                                }
                            }
                        }
                    }
                }

            }

            out.println(ans);
        }

        private boolean sol(String c0, String c1, String c2, String c3) {
            String arr[] = {c0, c1, c2, c3};
            int x1 = x;
            int y1 = y;
            for (int i = 0; i < digits.length(); i++) {
                char c = digits.charAt(i);
                if (arr[c - '0'] == "R") {
                    y1 = y1 + 1;
                } else if (arr[c - '0'] == "L") {
                    y1 = y1 - 1;
                } else if (arr[c - '0'] == "U") {
                    x1 = x1 + 1;
                } else if (arr[c - '0'] == "D") {
                    x1 = x1 - 1;
                }
                if (x1 < 0 || y1 < 0 || x1 > n - 1 || y1 > m - 1) {
                    return false;
                }
                if (mat[x1][y1] == '#') {
                    return false;
                }
                if (mat[x1][y1] == 'E') {
                    return true;
                }

            }
            return false;
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private String readLine0() {
            StringBuilder buf = new StringBuilder();
            int c = read();
            while (c != '\n' && c != -1) {
                if (c != '\r') {
                    buf.appendCodePoint(c);
                }
                c = read();
            }
            return buf.toString();
        }

        public String readLine() {
            String s = readLine0();
            while (s.trim().length() == 0) {
                s = readLine0();
            }
            return s;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(int i) {
            writer.println(i);
        }

    }
}

