    static class TaskC {

        void Solve(InputReader in, PrintWriter out) {
            int n, m;
            n = in.NextInt();
            m = in.NextInt();
            char[][] maze = new char[n][];
            for (int i = 0; i < n; i++) {
                maze[i] = in.Next().toCharArray();
            }
            char[] s = in.Next().toCharArray();
            int[][] mapping = new int[][]{{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

            int goodMappings = 0;
            int[] i = new int[4];
            for (i[0] = 0; i[0] < 4; i[0]++) {
                for (i[1] = 0; i[1] < 4; i[1]++) {
                    for (i[2] = 0; i[2] < 4; i[2]++) {
                        for (i[3] = 0; i[3] < 4; i[3]++) {
                            if (i[0] != i[1] && i[1] != i[2] && i[0] != i[2] && i[0] != i[3] && i[1] != i[3] && i[2] != i[3]) {

                                int row = 0, col = 0;
                                FINDS:
                                for (int i1 = 0; i1 < n; i1++) {
                                    for (int j1 = 0; j1 < m; j1++) {
                                        if (maze[i1][j1] == 'S') {
                                            row = i1;
                                            col = j1;
                                            break FINDS;
                                        }
                                    }
                                }

                                for (char a : s) {
                                    row += mapping[i[a - '0']][0];
                                    col += mapping[i[a - '0']][1];
                                    if (row < 0 || row == n) break;
                                    if (col < 0 || col == m) break;
                                    if (maze[row][col] == '#') break;
                                    if (maze[row][col] == 'E') {
                                        goodMappings++;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            out.println(goodMappings);
        }

        static int GetMax(int[] ar) {
            int max = Integer.MIN_VALUE;
            for (int a : ar) {
                max = Math.max(max, a);
            }
            return max;
        }

        static int GetMin(int[] ar) {
            int min = Integer.MAX_VALUE;
            for (int a : ar) {
                min = Math.min(min, a);
            }
            return min;
        }

        static long GetSum(int[] ar) {
            long s = 0;
            for (int a : ar) s += a;
            return s;
        }

        static int[] GetCount(int[] ar) {
            return GetCount(ar, GetMax(ar));
        }

        static int[] GetCount(int[] ar, int maxValue) {
            int[] dp = new int[maxValue + 1];
            for (int a : ar) {
                dp[a]++;
            }
            return dp;
        }

        static class InputReader {
            BufferedReader reader;
            StringTokenizer tokenizer;

            InputReader(InputStream stream) {
                reader = new BufferedReader(new InputStreamReader(stream), 32768);
                tokenizer = null;
            }

            String Next() {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    try {
                        tokenizer = new StringTokenizer(reader.readLine(), " \t\n\r\f,");
                    } catch (IOException e) {
                        throw new RuntimeException(e);
                    }
                }
                return tokenizer.nextToken();
            }

            int NextInt() {
                return Integer.parseInt(Next());
            }

            long NextLong() {
                return Long.parseLong(Next());
            }

            double NextDouble() {
                return Double.parseDouble(Next());
            }

            int[] NextIntArray(int n) {
                return NextIntArray(n, 0);
            }

            int[] NextIntArray(int n, int offset) {
                int[] a = new int[n];
                for (int i = 0; i < n; i++) {
                    a[i] = NextInt() - offset;
                }
                return a;
            }

            int[][] NextIntMatrix(int n, int m) {
                return NextIntMatrix(n, m, 0);
            }

            int[][] NextIntMatrix(int n, int m, int offset) {
                int[][] a = new int[n][m];
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        a[i][j] = NextInt() - offset;
                    }
                }
                return a;
            }
        }
    }
