        	for(int j=0; j<m; j++){
        		if(d.charAt(j)=='S'){
        			s = i;
        			ss = j;
        		}
        	}
        }
        String p = in.next();
        int ans = 0;
		for(int f=0; f<4; f++){
			for(int g=0; g<4; g++){
				if(g==f){
					continue;
				}
				for(int v=0; v<4; v++){
					if(f==v || g==v){
						continue;
					}
					for(int b=0; b<4; b++){
						if(f==b || g==b || v==b){
							continue;
						}

				        int x = s;
				        int y = ss;
				        int c = 0;
				        while(x<n && y<m && x>=0 && y>=0 && c<p.length()){
				        	if(a[x][y]=='E'){
