				        	}
				        	else if(Integer.parseInt(p.charAt(c)+"")==b){
				        		y--;
				        	}
				        	c++;
				        }
				        if(c==p.length() && x<n && y<m && x>=0 && y>=0 && a[x][y]=='E'){
				        	ans++;
				        }
 		   			}
    			}
			}
		}
		System.out.println(ans);
    }
}

