import java.util.*;

public class GB17B {

	static int sr;
	static int sc;

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int r = scan.nextInt();
		int c = scan.nextInt();
		char[][] grid = new char[r][c];
		for(int i = 0; i < r; i++){
			grid[i] = scan.next().toCharArray();
		}
		for(int i = 0; i < r; i++){
			for(int j = 0; j < c; j++){
				if(grid[i][j] == 'S'){
					sr = i;
					sc = j;
				}
			}
		}
		String key = scan.next();
		int count = 0;
		for(int i = 0; i < 4; i++){ 
			for(int j = 0; j < 4; j++){ 
				if(j == i) continue;
				for(int k = 0; k < 4; k++){ 
					if(k == j || k == i) continue;
					for(int l = 0; l < 4; l++){ 
						if(l == k || l == j || l == i) continue;
						int[] arr = new int[4];
						arr[0] = i;
						arr[1] = j;
						arr[2] = k;
						arr[3] = l;
						if(exit(grid, key, 0, arr, sr, sc)){
							count++;
						}
					}
				}
			}
		}
		System.out.println(count);
	}

	static boolean exit(char[][] grid, String key, int curr, int[] arr, int cr, int cc){
		if(curr >= key.length()) return false;
		int move = key.charAt(curr)-'0';
		int m = 0;
		for(int i = 0; i < 4; i++){
			if(move == arr[i]){
				m = i;
			}
		}
		if(m == 0){
			int nr = cr-1;
			if(!inbounds(nr, cc, grid)) return false;
			if(grid[nr][cc] == '#') return false;
			if(grid[nr][cc] == 'E') return true;
			return exit(grid, key, curr+1, arr, nr, cc);
		}
		if(m == 1){
			int nc = cc+1;
			if(!inbounds(cr, nc, grid)) return false;
			if(grid[cr][nc] == '#') return false;
			if(grid[cr][nc] == 'E') return true;
			return exit(grid, key, curr+1, arr, cr, nc);
		}
		if(m == 2){
			int nr = cr+1;
			if(!inbounds(nr, cc, grid)) return false;
			if(grid[nr][cc] == '#') return false;
			if(grid[nr][cc] == 'E') return true;
			return exit(grid, key, curr+1, arr, nr, cc);
		}
		if(m == 3){
			int nc = cc-1;
			if(!inbounds(cr, nc, grid)) return false;
			if(grid[cr][nc] == '#') return false;
			if(grid[cr][nc] == 'E') return true;
			return exit(grid, key, curr+1, arr, cr, nc);
		}
		return false;
	}

	static boolean inbounds(int r, int c, char[][] grid){
		return r < grid.length && c < grid[0].length && r >= 0 && c >= 0;
	}
}

