public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static
    @SuppressWarnings("Duplicates")
    class TaskB {
        int n;
        int m;
        int initR;
        int initC;
        char[][] grid;
        int[] moves;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            grid = in.nextCharTable(n, m);
            String ms = in.next();
            moves = new int[ms.length()];
            for (int i = 0; i < ms.length(); i++) {
                moves[i] = Integer.parseInt(ms.substring(i, i + 1));
            }

            out:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        initR = i;
                        initC = j;
                        break out;
                    }
                }
            }


            int res = 0;
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    if (i == j) continue;
                    for (int k = 0; k < 4; k++) {
                        if (k == i || k == j) continue;
                        for (int l = 0; l < 4; l++) {
                            if (l == k || l == j || l == i) continue;
                            if (tryIt(new int[]{i, j, k, l})) res++;
                        }
                    }
                }
            }

            out.print(res);
        }

        private boolean tryIt(int[] dirs) {
            int currenR = initR;
            int currentC = initC;
            for (int i = 0; i < moves.length; i++) {
                switch (dirs[moves[i]]) {
                    case 0:
                        currentC--;
                        break;
                    case 1:
                        currenR--;
                        break;
                    case 2:
                        currentC++;
                        break;
                    default:
                        currenR++;
                        break;
                }

                if ((currenR >= n || currenR < 0) || (currentC >= m || currentC < 0) ||
                        grid[currenR][currentC] == '#')
                    return false;
                if (grid[currenR][currentC] == 'E') return true;
            }

            return false;
        }

    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public char[][] nextCharTable(int rows, int columns) {
            char[][] table = new char[rows][];
            for (int i = 0; i < rows; ++i) {
                table[i] = next().toCharArray();
                assert table[i].length == columns;
            }
            return table;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(readLine());
            }
            return tokenizer.nextToken();
        }

        public String readLine() {
            String line;
            try {
                line = reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return line;
        }

    }
}

