public class NewYearAndBuggyBot {
	static int R;
	static int C;
	public static void main(String[] args) throws IOException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter out = new PrintWriter(System.out);
		StringTokenizer t = new StringTokenizer(in.readLine());
		R = Integer.parseInt(t.nextToken());
		C = Integer.parseInt(t.nextToken());
		boolean[][] maze = new boolean[R][C];
		int startRow = 0;
		int startCol = 0;
		int endRow = 0;
		int endCol = 0;
		for(int r = 0; r < R; ++r) {
			String line = in.readLine();
			for(int c = 0; c < C; ++c) {
				char ch = line.charAt(c);
				if(ch == 'S') {
					startRow = r;
					startCol = c;
				}
				else if(ch == 'E') {
					endRow = r;
					endCol = c;
				}
				maze[r][c] = ch == '#';
			}
		}
		int ans = 0;
		char[] directions = in.readLine().toCharArray();
		int[] dir = new int[4];
		for(dir[0] = 0; dir[0] < 4; ++dir[0]) {
			for(dir[1] = 0; dir[1] < 4; ++dir[1]) {
				if(dir[1] == dir[0])
					continue;
				for(dir[2] = 0; dir[2] < 4; ++dir[2]) {
					if(dir[2] == dir[1] || dir[2] == dir[0])
						continue;
					for(dir[3] = 0; dir[3] < 4; ++dir[3]) {
						if(dir[3] == dir[2] || dir[3] == dir[1] || dir[3] == dir[0])
							continue;
						ans += works(maze, dir, directions, startRow, startCol, endRow, endCol) ? 1 : 0;
					}
				}
			}
		}
		out.println(ans);
		in.close();
		out.close();
	}
	public static boolean works(boolean[][] maze, int[] dir, char[] directions, int startRow, int startCol, int endRow, int endCol) {
		int r = startRow;
		int c = startCol;
		int i = 0;
		boolean works = true;
		while(i < directions.length && !(r == endRow && c == endCol)) {
			int d = dir[directions[i] - '0'];
			r += d % 2 == 0 ? 0 : d - 2;
			c += d % 2 == 1 ? 0 : d - 1;
			if(r < 0 || r >= R || c < 0 || c >= C || maze[r][c]) {
				works = false;
				break;
			}
			i++;
		}
		return works && r == endRow && c == endCol;
	}
}

