    static class TaskB {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            String[] s = new String[n];
            char[][] str = new char[n][m];
            int sx = 0, sy = 0, ex = 0, ey = 0;
            for (int i = 0; i < n; i++) {
                s[i] = in.next();
                str[i] = s[i].toCharArray();
                for (int j = 0; j < m; j++) {
                    if (str[i][j] == 'S') {
                        sx = i;
                        sy = j;
                    }
                    if (str[i][j] == 'E') {
                        ex = i;
                        ey = j;
                    }
                }
            }
            int h = 0;
            String st = in.next();
            int[] a = new int[4];
            int[] myMap = new int[4];
            for (int i = 0; i < 4; i++) {
                if (myMap[i] != 1) {
                    a[0] = i;
                    myMap[i] = 1;
                } else {
                    continue;
                }
                for (int j = 0; j < 4; j++) {
                    if (myMap[j] != 1) {
                        a[1] = j;
                        myMap[j] = 1;
                    } else {
                        continue;
                    }
                    for (int k = 0; k < 4; k++) {
                        if (myMap[k] != 1) {
                            a[2] = k;
                            myMap[k] = 1;
                        } else {
                            continue;
                        }
                        for (int p = 0; p < 4; p++) {
                            if (myMap[p] != 1) {
                                a[3] = p;
                                myMap[p] = 1;
                                if (bfs(a, sx, sy, ex, ey, str, n, m, st)) {
                                    h++;
                                }
                            } else {
                                continue;
                            }
                            myMap[p] = 0;
                        }
                        myMap[k] = 0;
                    }
                    myMap[j] = 0;
                }
                myMap[i] = 0;
            }
            out.println(h);
        }

        private boolean bfs(int[] a, int sx, int sy, int ex, int ey, char[][] str, int n, int m, String st) {
            int h = 0;
            char[] t = st.toCharArray();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (a[t[h] - '0'] == 0) {
                        sx -= 1;
                    }
                    if (a[t[h] - '0'] == 1) {
                        sx += 1;
                    }
                    if (a[t[h] - '0'] == 2) {
                        sy -= 1;
                    }
                    if (a[t[h] - '0'] == 3) {
                        sy += 1;
                    }
                    if (sx > n - 1 || sx < 0 || sy > m - 1 || sy < 0 || str[sx][sy] == '#') {
                        return false;
                    }
                    if (sx == ex && sy == ey) {
                        return true;
                    }
                    h++;
                    if (h == t.length) {
                        return false;
                    }
                }
            }
            return false;
        }

    }
}

