    int[] dir = {0, 1, 2, 3};
    Set<Integer> set = new HashSet<Integer>();
    int[] perm = new int[dir.length];
    int ans = 0;
    int runs = 0;
    for (int aDir : dir) {
      perm[0] = aDir;
      set.add(aDir);
      for (int aDir1 : dir) {
        if (!set.contains(aDir1)) {
          perm[1] = aDir1;
          set.add(aDir1);
          for (int aDir2 : dir) {
            if (!set.contains(aDir2)) {
              perm[2] = aDir2;
              set.add(aDir2);
              for (int aDir3 : dir) {
                if (!set.contains(aDir3)) {
                  perm[3] = aDir3;
                  if (valid(grid, n, m, path, perm, start, end)) {
                    ans++;
                  }
                  runs++;
                }
              }
              set.remove(aDir2);
            }
          }
          set.remove(aDir1);
        }
      }
      set.remove(aDir);
    }

    System.out.println(ans);

  }

  private static boolean valid(char[][] grid, int n, int m, char[] path, int[] perm, Pair start, Pair end) {
    int[] dx = {0, 0, 1, -1};
    int[] dy = {1, -1, 0, 0};
    int curx = start.first, cury = start.second;
    for (char c : path) {
      int p = c - '0';
      int idx = perm[p];
      int nx = curx + dx[idx];
      int ny = cury + dy[idx];

      if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
        if (nx == end.first && ny == end.second) {
          return true;
        }
        if (grid[nx][ny] == '#') {
          return false;
        }
        curx = nx; cury = ny;
      } else {
        return false;
      }
    }
    return false;
  }

  private static class Pair {
    private final int first;
    private final int second;

    private Pair(int first, int second) {
      this.first = first;
      this.second = second;
    }

    @Override
    public String toString() {
      return String.format("[%d,%d]", first, second);
    }
  }
}

