public class Sol implements Runnable {

    static long mod = 1000000007;

    char board[][];
    int count, x, y, n, m;
    String directions;

    boolean check(char c[], int l, int r, int ind) {
        if(l == 0 || r == 0 || l > n || r > m || board[l][r] == '#') return false;
        if(board[l][r] == 'E') return true;
        if(ind == directions.length()) return false;

        if(c[directions.charAt(ind) - '0'] == 'U')
            return check(c, l - 1, r, ind + 1);
        else if(c[directions.charAt(ind) - '0'] == 'D')
            return check(c, l + 1, r, ind + 1);
        else if(c[directions.charAt(ind) - '0'] == 'R')
            return check(c, l, r + 1, ind + 1);
        else
            return check(c, l, r - 1, ind + 1);
    }

    void swap(char c[], int p1, int p2) {
        char temp = c[p1];
        c[p1] = c[p2];
        c[p2] = temp;
    }

    void permute(char c[], int l, int r) {
        if(l == r) {
            if(check(c, x, y, 0)) count++;
        }
        else {
            for(int i=l;i<=r;i++) {
                swap(c, l, i);
                permute(c, l + 1, r);
                swap(c, l, i);
            }
        }
    }

    void solve(int total_test_cases, InputReader in, PrintWriter w) {
        for (int test_case = 1; test_case <= total_test_cases; test_case++) {
            n = in.nextInt(); m = in.nextInt();
            board = new char[n + 1][m + 1];
            count = 0; x = 0; y = 0;

            for(int i=1;i<=n;i++) {
                String s = in.next();
                for(int j=0;j<s.length();j++) {
                    board[i][j + 1] = s.charAt(j);

                    if(board[i][j + 1] == 'S') {
                        x = i;
                        y = j + 1;
                    }
                }
            }

            directions = in.next();

            char C[] = {'U', 'L', 'R', 'D'};
            permute(C, 0, 3);

            w.println(count);
        }
    }



    void init() throws Exception {

        InputReader in;
        PrintWriter w;
        boolean online = false;

