public class _908B {

    static void swap(int[] a, int i, int j) {
        int temp = a[i];
        a[i] = a[j];
        a[j] = temp;
    }

    static void reverse(int[] a, int i, int j) {
        while (i < j) {
            int temp = a[i];
            a[i++] = a[j];
            a[j--] = temp;
        }
    }

    static boolean next(int[] str) {
        int i = str.length - 1;
        while (i > 0) {
            if (str[i] > str[i - 1]) {
                int j = str.length - 1;
                while (str[j] <= str[i - 1]) j--;

                swap(str, i - 1, j);
                reverse(str, i, str.length - 1);

                return true;
