public class B {
    static int dx[] = new int[]{0, 1, 0,-1};
    static int dy[] = new int[]{1, 0,-1, 0};
    static int n, m, sx, sy, ex, ey;
    static char[][] mat;
    static char [] dir;
    public static void main(String[] args)throws Exception {
        FastReader in = new FastReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        n = in.nextInt(); m = in.nextInt();
        mat = new char[n][m];
        for(int i = 0; i < n; i++){
            mat[i] = in.nextCharArray();
            for(int j = 0; j < m; j++){
                if(mat[i][j] == 'S'){
                    sx = i; sy = j;
                }
                else if(mat[i][j] == 'E'){
                    ex = i; ey = j;
                }
            }
        }


        dir = in.nextCharArray();
        boolean [] k = new boolean[4];
        for(char c : dir) k[c-'0'] = true;


        int p[] = new int[]{0, 1, 2, 3};
        int ans = 0;
        while(true){
            String s = "";
            for(int i = 0; i < 4; i++){
                if(k[i]) s += p[i];
            }
            if(check(p)) ans++;

            if(nextPermutation(p) == false) break;
        }



        pw.println(ans);

        pw.close();
    }

    static boolean check(int p[]){
        int a = sx, b = sy;
        for(char c : dir){
            int d = c - '0';
            a += dx[p[d]];
            b += dy[p[d]];

            if(a < 0 || a >= n || b < 0 || b >= m || mat[a][b] == '#') return false;
            if(mat[a][b] == 'E') return true;
        }

        return a == ex && b == ey;
    }



    public static boolean nextPermutation(int[] p) {
        for (int a = p.length - 2; a >= 0; --a)
            if (p[a] < p[a + 1])
                for (int b = p.length - 1; ; --b)
                    if (p[b] > p[a]) {
                        int t = p[a];
                        p[a] = p[b];
                        p[b] = t;
                        for (++a, b = p.length - 1; a < b; ++a, --b) {
                            t = p[a];
                            p[a] = p[b];
                            p[b] = t;
                        }
                        return true;
                    }
        return false;
    }

    static void debug(Object...obj) {
        System.err.println(Arrays.deepToString(obj));
    }

    static class FastReader {
        InputStream is;
        private byte[] inbuf = new byte[1024];
        private int lenbuf = 0, ptrbuf = 0;
        static final int ints[] = new int[128];

        public FastReader(InputStream is){
            for(int i='0';i<='9';i++) ints[i]=i-'0';
            this.is = is;
        }

        public int readByte(){
            if(lenbuf == -1)throw new InputMismatchException();
            if(ptrbuf >= lenbuf){
                ptrbuf = 0;
                try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
                if(lenbuf <= 0)return -1;
            }
            return inbuf[ptrbuf++];
        }

        public boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }
        public int skip() {
            int b;
            while((b = readByte()) != -1 && isSpaceChar(b));
            return b;
        }

        public String next(){
            int b = skip();
            StringBuilder sb = new StringBuilder();
            while(!(isSpaceChar(b))){ 
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt(){
            int num = 0, b;
            boolean minus = false;
            while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
            if(b == '-'){
                minus = true;
                b = readByte();
            }

            while(true){
                if(b >= '0' && b <= '9'){
                    num = (num<<3) + (num<<1) + ints[b];
                }else{
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }

        public long nextLong() {
            long num = 0;
            int b;
            boolean minus = false;
            while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
            if(b == '-'){
                minus = true;
                b = readByte();
            }

            while(true){
                if(b >= '0' && b <= '9'){
                    num = (num<<3) + (num<<1) + ints[b];
                }else{
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }


        public char[] next(int n){
            char[] buf = new char[n];
            int b = skip(), p = 0;
            while(p < n && !(isSpaceChar(b))){
                buf[p++] = (char)b;
                b = readByte();
            }
            return n == p ? buf : Arrays.copyOf(buf, p);
        }

        private char buff[] = new char[100];
        public char[] nextCharArray(){
            int b = skip(), p = 0;
            while(!(isSpaceChar(b))){
                buff[p++] = (char)b;
                b = readByte();
            }
            return Arrays.copyOf(buff, p);
        }
    }
}

