import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;



public class Qn1 {
    InputStream is;
    PrintWriter out;
    String INPUT = "";
    String possibilites[] = {"0123","0132","0213","0231","0321","0312","1023","1032","1203","1230","1320","1302","2103","2130","2013","2031","2301","2310","3120","3102","3210","3201","3021","3012"} ;
    int numOfRows, numOfCols;
    char up,down,left,right;
    int sr,sc,er,ec;
    char matrix[][];
    String ip;
    boolean isValidRow(int r){
        if(r < 0 || r >= numOfRows){
            return false;
        }
        return true;
    }

    boolean isValidCol(int c){
        if(c < 0 || c >= numOfCols){
            return false;
        }
        return true;
    }

    void solve() {
        numOfRows = ni();
        numOfCols = ni();
         matrix = new char[numOfRows][numOfCols];
        for (int i = 0; i < numOfRows; i++) {
            for (int j = 0; j < numOfCols; j++) {
                matrix[i][j] = nc();
                if(matrix[i][j] == 'S'){
                    sr = i;
                    sc = j;
                }else if(matrix[i][j] == 'E'){
                    er = i;
                    ec = j;
                }
            }
        }

        ip = ns();
        int ans = 0;
        for (int i = 0; i < possibilites.length; i++) {
            up = possibilites[i].charAt(0);
            down = possibilites[i].charAt(1);
            left = possibilites[i].charAt(2);
            right = possibilites[i].charAt(3);
            if(perform(sr,sc,0)){
                ans++;
            }


        }
        System.out.println(ans);



    }

    boolean perform(int r, int c ,int pos){


        if(!isValidCol(c) || !isValidRow(r) || matrix[r][c] == '#'){
            return false;
        }else if(matrix[r][c] == 'E'){
            return true;
        }else if(pos == ip.length()) {
            return false;
        } else if(ip.charAt(pos) == up){
            return perform(r-1,c,pos+1);
        }else if(ip.charAt(pos) == down){
            return perform(r+1, c, pos+1);
        }else if(ip.charAt(pos) == left){
            return perform(r,c-1,pos+1);
        }else  {
            return perform(r,c+1,pos+1);
        }



    }


    void run() throws Exception {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);

        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if (!INPUT.isEmpty()) tr(System.currentTimeMillis() - s + "ms");
    }

    public static void main(String[] args) throws Exception {
        new Qn1().run();
    }

    private byte[] inbuf = new byte[1024];
    public int lenbuf = 0, ptrbuf = 0;

    private int readByte() {
        if (lenbuf == -1) throw new InputMismatchException();
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0;
            try {
                lenbuf = is.read(inbuf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (lenbuf <= 0) return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    private int skip() {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b)) ;
        return b;
    }

    private double nd() {
        return Double.parseDouble(ns());
    }

    private char nc() {
        return (char) skip();
    }

    private String ns() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (!(isSpaceChar(b))) { 
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n) {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while (p < n && !(isSpaceChar(b))) {
            buf[p++] = (char) b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m) {
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++) map[i] = ns(m);
        return map;
    }

    private int[] na(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = ni();
        return a;
    }

    private int ni() {
        int num = 0, b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl() {
        long num = 0;
        int b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) {
        System.out.println(Arrays.deepToString(o));
    }
}

