    static int m;
    static char[][] grid;
    static String nums;
    static int startx;
    static int starty;
    static int endx;
    static int endy;
    public static boolean simulate(int up, int left, int down, int right) {

	int currx = startx;
	int curry = starty;
	int index = 0;

	while (index < nums.length()) {
	    int comm = nums.charAt(index) - '0';

	    if (comm == up) {
		curry--;
	    } else if (comm == down) {
		curry++;
	    } else if (comm == left) {
		currx--;
	    } else {
		currx++;
	    }
	    if (currx < 0 || currx >= m || curry < 0 || curry >= n) {

		return false;
	    }
	    if (grid[curry][currx] == '#') {

		return false;
	    }
	    if (grid[curry][currx] == 'E') {

		return true;
	    }

	    index++;
	}


	return false;
    }

    public static void main(String[] args) {
	Scanner input = new Scanner(System.in);
	n = input.nextInt();
	m = input.nextInt();
	grid = new char[n][m];
	for (int i = 0; i < n; i++) {
	    String curr = input.next();
	    for (int j = 0; j < curr.length(); j++) {
		grid[i][j] = curr.charAt(j);
		if (grid[i][j] == 'S') {
		    startx = j;
		    starty = i;
		} else if (grid[i][j] == 'E') {
		    endx = j;
		    endy = i;
		}
	    }
	}

	nums = input.next();
	int total = 0;
	for (int i = 0; i < 4; i++) {
	    for (int j = 0; j < 4; j++) {
		if (i == j) continue;
		for (int k = 0; k < 4; k++) {
		    if (k == i || k == j) continue;
		    for (int l = 0; l < 4; l++) {
			if (l == i || l == j || l == k) continue;

			if (simulate(i, j, k, l)) {
			    total++;
			}

		    }
		}
	    }
	}

	System.out.println(total);
    }
}

