        if (y == gy && x == gx) {
            return 1;
        }
        if (si == s.length) {
            return 0;
        }
        int ny = y + dy[dir[s[si]-'0']];
        int nx = x + dx[dir[s[si]-'0']];
        int ret = 0;

        if (ny >= 0 && nx >= 0 && ny < N && nx < M) {
            if (maze[ny][nx] != '#') {
                ret += dfs(ny,nx,si + 1);
            }
        }

        return ret;
    }

