	static void recur(List<Pair> mapping, List<Pair> dirsLeft) {
		if(dirsLeft.isEmpty()) {
			int si=-1, sj=-1;
			for(int i=0; i<n; ++i) {
				for(int j=0; j<m; ++j) {
					if(board[i][j]=='S') {
						si=i;
						sj=j;
					}
				}
			}
			for(int k=0; k<s.length; ++k) {
				Pair dir=mapping.get(s[k]-'0');
				si+=dir.a;
				sj+=dir.b;
				if(si<0||si>=n||sj<0||sj>=m||board[si][sj]=='#')
					return;
				if(board[si][sj]=='E') {
					++t;
					return;
				}
			}
		} else {
			for(int i=0; i<dirsLeft.size(); ++i) {
				Pair p=dirsLeft.remove(i);
				mapping.add(p);
				recur(mapping, dirsLeft);
				mapping.remove(p);
				dirsLeft.add(i, p);
			}
		}
	}

	static class Pair {
		int a, b;
		Pair(int a, int b) {
