            int tmp = a[i - 1];
            a[i - 1] = a[j - 1];
            a[j - 1] = tmp;


            i++;
            j = a.length;
            while (i < j) {
                tmp = a[i - 1];
                a[i - 1] = a[j - 1];
                a[j - 1] = tmp;
