import java.util.*;

public class R2017B {
	static int n,m;
	static char[][] a;
	static int sI,sJ,eI,eJ;
	static String dir;
	static int res=0;
	public static void main(String[] args) {
		Scanner scan=new Scanner(System.in);
		n=scan.nextInt();m=scan.nextInt();
		a=new char[n][m];
		for(int i=0;i<n;i++) {
			String s=scan.next();
			for(int j=0;j<m;j++) {
				a[i][j]=s.charAt(j);
				if(a[i][j]=='S') {
					sI=i;
					sJ=j;
				}
				else if(a[i][j]=='E') {
					eI=i;
					eJ=j;
				}
			}
		}
		dir=scan.next();
		boolean[] v=new boolean[4];
		int[] p=new int[4];
		perm(v,p,0);
		System.out.println(res);
	}
	public static void perm(boolean[] v, int[] p, int k) {
		if(k==4) {
			res+=go(p);
			return;
		}
		for(int i=0;i<4;i++) {
			if(!v[i]) {
				v[i]=true;
				p[k]=i;
				perm(v,p,k+1);
				v[i]=false;
			}
		}	
	}
	public static int go(int[] p) {
		ArrayDeque<Pt> q=new ArrayDeque<>();
		q.offer(new Pt(sI,sJ));
		int ind=0;
		while(!q.isEmpty()) {
			Pt temp=q.poll();
			int curI=temp.i, curJ=temp.j;
			if(curI==eI&&curJ==eJ)return 1;
			if(ind==dir.length())return 0;
			int d=Integer.parseInt(""+dir.charAt(ind));
			if(p[0]==d) {
				if(inBounds(curI-1,curJ)&&a[curI-1][curJ]!='#') {
					q.offer(new Pt(curI-1,curJ));
				}
				else return 0;
			}
			if(p[1]==d) {
				if(inBounds(curI+1,curJ)&&a[curI+1][curJ]!='#') {
					q.offer(new Pt(curI+1,curJ));
				}
				else return 0;
			}
			if(p[2]==d) {
				if(inBounds(curI,curJ+1)&&a[curI][curJ+1]!='#') {
					q.offer(new Pt(curI,curJ+1));
				}
				else return 0;
			}
			if(p[3]==d) {
				if(inBounds(curI,curJ-1)&&a[curI][curJ-1]!='#') {
					q.offer(new Pt(curI,curJ-1));
				}
				else return 0;
			}
			ind++;
		}
		return 0;
	}
	public static boolean inBounds(int i, int j) {
		return i>=0&&i<n&&j>=0&&j<m;
	}
	static class Pt {
		int i,j;
		Pt(int i, int j) {
			this.i=i;
			this.j=j;
		}
	}
}

