    static class TaskB {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt(), m = in.nextInt();
            String[] mat = new String[n];
            for (int i = 0; i < n; i++) {
                mat[i] = in.nextString();
            }
            String seq = in.nextString();
            int[] dx = new int[]{0, 0, -1, 1};
            int[] dy = new int[]{-1, 1, 0, 0};
            int[] p = new int[]{0, 1, 2, 3};
            int cnt = 0;
            do {
                int[] a = new int[4];
                int[] b = new int[4];
                for (int i = 0; i < 4; i++) {
                    a[i] = dx[p[i]];
                    b[i] = dy[p[i]];
                }
                if (isPossible(mat, seq, a, b))
                    cnt++;
            } while (next_permutation(p));
            out.println(cnt);
        }

        boolean next_permutation(int[] p) {
            for (int a = p.length - 2; a >= 0; --a)
                if (p[a] < p[a + 1])
                    for (int b = p.length - 1; ; --b)
                        if (p[b] > p[a]) {
                            int t = p[a];
                            p[a] = p[b];
                            p[b] = t;
                            for (++a, b = p.length - 1; a < b; ++a, --b) {
                                t = p[a];
                                p[a] = p[b];
                                p[b] = t;
                            }
                            return true;
                        }
            return false;
        }

        boolean isPossible(String[] mat, String seq, int[] dx, int[] dy) {
            int sx = 0, sy = 0;
            int n = mat.length, m = mat[0].length();
            for (int i = 0; i < mat.length; i++) {
                for (int j = 0; j < mat[i].length(); j++) {
                    if (mat[i].charAt(j) == 'S') {
                        sx = i;
                        sy = j;
                    }
                }
            }
            for (int i = 0; i < seq.length(); i++) {
                int id = seq.charAt(i) - '0';
                int nx = sx + dx[id], ny = sy + dy[id];
                if (nx < 0 || nx >= n || ny < 0 || ny >= m || mat[nx].charAt(ny) == '#')
                    return false;
                if (mat[nx].charAt(ny) == 'E') return true;
                sx = nx;
                sy = ny;
            }
            return false;
        }

    }

