        if (sources.size() == 0) {
            permutation.add(result);
        } else {
            for (int i = 0; i < sources.size(); i++) {
                List<Integer> newSources = new ArrayList<>();
                newSources.addAll(sources);
                int temp = newSources.remove(i);
                List<Integer> newResult = new ArrayList<>();
                newResult.addAll(result);
                newResult.add(temp);
                permute(newResult, newSources, permutation);
            }
        }

    }

    public static void main(String[] args) {
        dimension = new ArrayList<>();
        dimension.add(0);
        dimension.add(1);
        dimension.add(2);
        dimension.add(3);
        List<List<Integer>> setOfPermutation = new ArrayList<>();
        permute(new ArrayList<Integer>(), dimension, setOfPermutation);
        int xstart = 0;
        int ystart = 0;
        int count = 0;
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine();
        char[][] matrix = new char[n][m];
        for (int i = 0; i < n; i++) {
            String thisRow = scanner.nextLine();
            if (thisRow.contains("S")) {
                xstart = i;
                ystart = thisRow.indexOf("S");

            }
            matrix[i] = thisRow.toCharArray();
        }

        String michi = scanner.next();
        int countRow = 0;
        int countCol = 0;
        for (int i = 0; i < setOfPermutation.size(); i++) {
            List<Integer> thisList = setOfPermutation.get(i);
            countRow = 0;
            countCol = 0;
            for (int j = 0; j < michi.length(); j++) {
                if (Integer.parseInt(michi.substring(j, j + 1)) == thisList.get(0)) {
                    countRow--;
                } else if (Integer.parseInt(michi.substring(j, j + 1)) == thisList.get(1)) {
                    countRow++;
                } else if (Integer.parseInt(michi.substring(j, j + 1)) == thisList.get(2)) {
                    countCol--;
                } else if (Integer.parseInt(michi.substring(j, j + 1)) == thisList.get(3)) {
                    countCol++;
                }
                if (xstart + countRow < 0 || xstart + countRow > n - 1 || ystart + countCol < 0 || ystart + countCol > m - 1) {
                    break;
                } else if (matrix[xstart + countRow][ystart + countCol] == '#') {
                    break;
                } else if (matrix[xstart + countRow][ystart + countCol] == 'E') {
                    count++;

                    break;
                }

            }
        }
        System.out.println(count);
    }

