            for (int j = 0; j < w; j++) {
                board[i][j] = str.charAt(j);
            }
        }


        int[] dx = new int[]{1, 0, -1, 0};
        int[] dy = new int[]{0, 1, 0, -1};


        boolean[][] visited = new boolean[h][w];


        int[][] dist = new int[h][w];
        for (int[] aaaa : dist) {
            Arrays.fill(aaaa, INF);
        }
        dist[sh][sw] = 0;



        PriorityQueue<Point> que = new PriorityQueue<>();
        que.add(new Point(sh, sw, 0));
        while (!que.isEmpty()) {
            Point cur = que.poll();
            int x = cur.x;
            int y = cur.y;
            int depth = cur.dist;
            visited[x][y] = true;



            for (int k = 0; k < 4; k++) {
                int nx = x + dx[k];
                int ny = y + dy[k];
                int ndepth = depth + 0;


                if (0 <= nx && nx < h && 0 <= ny && ny < w &&
                    board[nx][ny] == '.' && !visited[nx][ny] &&
                    ndepth < dist[nx][ny]) {
                    dist[nx][ny] = ndepth;
                    que.add(new Point(nx, ny, ndepth));
                }
            }



            for (int i = -2; i <= 2; i++) {
                for (int j = -2; j <= 2; j++) {
                    int nx = x + i;
                    int ny = y + j;
                    int ndepth = depth + 1;


                    if (0 <= nx && nx < h && 0 <= ny && ny < w &&
                        board[nx][ny] == '.' && !visited[nx][ny] &&
                        ndepth < dist[nx][ny]) {
                        dist[nx][ny] = ndepth;
                        que.add(new Point(nx, ny, ndepth));
                    }
                }
            }
        }

        ans = dist[gh][gw];
        if (ans == INF) ans = -1;
        System.out.println(ans);
    }
}

class Point implements Comparable<Point> {
    int x;
    int y;
    int dist;

