import java.io.DataInputStream;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Comparator;
import java.util.PriorityQueue;

public class Main {
    static class Reader
    {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public Reader()
        {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public Reader(String file_name) throws IOException
        {
            din = new DataInputStream(new FileInputStream(file_name));
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public String readLine() throws IOException
        {
            byte[] buf = new byte[1_000_010]; 
            int cnt = 0, c;
            while ((c = read()) != -1)
            {
                if (c == '\n')
                    break;
                buf[cnt++] = (byte) c;
            }
            return new String(buf, 0, cnt);
        }

        public int nextInt() throws IOException
        {
            int ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do
            {
                ret = ret * 10 + c - '0';
            }  while ((c = read()) >= '0' && c <= '9');

            if (neg)
                return -ret;
            return ret;
        }

        public long nextLong() throws IOException
        {
            long ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + c - '0';
            }
            while ((c = read()) >= '0' && c <= '9');
            if (neg)
                return -ret;
            return ret;
        }

        public double nextDouble() throws IOException
        {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();

            do {
                ret = ret * 10 + c - '0';
            }
            while ((c = read()) >= '0' && c <= '9');

            if (c == '.')
            {
                while ((c = read()) >= '0' && c <= '9')
                {
                    ret += (c - '0') / (div *= 10);
                }
            }

            if (neg)
                return -ret;
            return ret;
        }

        private void fillBuffer() throws IOException
        {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1)
                buffer[0] = -1;
        }

        private byte read() throws IOException
        {
            if (bufferPointer == bytesRead)
                fillBuffer();
            return buffer[bufferPointer++];
        }

        public void close() throws IOException
        {
            if (din == null)
                return;
            din.close();
        }
    }
    void solve(Reader sc, PrintWriter pw) throws IOException {
        int INF = Integer.MAX_VALUE / 10;
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int[][] dist = new int[rows][cols];
        for (int[] arr : dist) {
            Arrays.fill(arr, INF);
        }
        int sRow = sc.nextInt();
        sRow--;
        int sCol = sc.nextInt();
        sCol--;
        int eRow = sc.nextInt();
        eRow--;
        int eCol = sc.nextInt();
        eCol--;

        String[] board = new String[rows];
        for (int i = 0; i < rows; i++) {
            board[i] = sc.readLine();
        }

        dist[sRow][sCol] = 0;
        PriorityQueue<Triple> pq = new PriorityQueue<>(rows, Comparator.comparingInt(a -> a.cost));
        pq.add(new Triple(0, sRow, sCol));

        while (!pq.isEmpty()) {
            Triple top = pq.poll();
            if (top.row == eRow && top.col == eCol) {
                break;
            }
            if (top.cost > dist[top.row][top.col]) {
                continue;
            }
            for (int i = -2; i <= 2; i++) {
                for (int j = -2; j <=2; j++) {
                    if (i == 0 && j == 0) {
                        continue;
                    }

                    int nextRow = top.row + i;
                    int nextCol = top.col + j;
                    if (nextRow < 0 || nextRow >= rows) {
                        continue;
                    }
                    if (nextCol < 0 || nextCol >= cols) {
                        continue;
                    }

                    if (board[nextRow].charAt(nextCol) == '#') {
                        continue;
                    }

                    int newCost = 0;
                    if (Math.abs(i) + Math.abs(j) > 1) {
                        newCost = 1;
                    }
                    if (top.cost + newCost >= dist[nextRow][nextCol]) {
                        continue;
                    }

                    dist[nextRow][nextCol] = top.cost + newCost;
                    pq.add(new Triple(top.cost + newCost, nextRow, nextCol));
                }
            }
        }

        int result = dist[eRow][eCol] == INF ? -1 : dist[eRow][eCol];
        pw.println(result);
    }
    class Triple {
        int cost;
        int row;
        int col;
        Triple(int cost, int row, int col) {
            this.cost = cost;
            this.row = row;
            this.col = col;
        }
    }
    public static void main(String[] args) throws IOException {
        Reader sc = new Reader();
        PrintWriter pw = new PrintWriter(System.out);

        new Main().solve(sc, pw);
        pw.flush();
        pw.close();
        sc.close();
    }
}

import java.util.*;
import java.io.*;

public class Main {
    static int h, w;
    public static void main(String[] args) {
        MyScanner sc = new MyScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        h = sc.nextInt(); w = sc.nextInt();
        int rs = sc.nextInt() - 1; int cs = sc.nextInt() - 1;
        int re = sc.nextInt() - 1; int ce = sc.nextInt() - 1;
        int [][] grid = new int[h][w];
        for (int i = 0; i < h; i++) {
            String s = sc.next();
            for (int j = 0; j < w; j++) if (s.charAt(j) == '#') grid[i][j] = 1;
        }
        int [][] dp = new int[h][w];
        int [] dx = new int[]{0, 1, -1, 2, -2};
        int [] dy = new int[]{0, 1, -1, 2, -2};
        PriorityQueue<State> q = new PriorityQueue<>(Comparator.comparingInt(x -> x.t));
        q.add(new State(rs, cs, 0));
        for (int [] arr: dp) Arrays.fill(arr, Integer.MAX_VALUE);
        while (!q.isEmpty()) {
            State next = q.poll();
            int r = next.r; int c = next.c; int t = next.t;
            dp[r][c] = Math.min(dp[r][c], t);
            for (Integer mx: dx) {
                for (Integer my: dy) {
                    if (mx == 0 && my == 0) continue;
                    int nr = r + mx; int nc = c + my;
                    if (!inBounds(nr, nc)) continue;
                    if (grid[nr][nc] == 1) continue;
                    if ((mx == 0 && my == 1) || (mx == 1 && my == 0) || (mx == -1 && my == 0) || (mx == 0 && my == -1)) {
                        if (t < dp[nr][nc]) {
                            dp[nr][nc] = t;
                            if (nr == re && nc == ce) continue;
                            q.add(new State(nr, nc, t));
                        }
                    } else {
                        if (t + 1 < dp[nr][nc]) {
                            dp[nr][nc] = t + 1;
                            if (nr == re && nc == ce) continue;
                            q.add(new State(nr, nc, t + 1));
                        }
                    }
                }
            }
        }
        out.println(dp[re][ce] == Integer.MAX_VALUE ? -1 : dp[re][ce]);
        out.close();
    }

    static boolean inBounds(int r, int c) {
        return (r >= 0 && r < h)  && (c >= 0 && c < w);
    }

    static class State {
        int r; int c; int t;
        State (int r, int c, int t) {
            this.r = r; this.t = t; this.c = c;
        }
    }



    public static class MyScanner {
        BufferedReader br;
        StringTokenizer st;

        public MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }


    }

}

import java.io.BufferedReader;
