import java.io.*;
import java.util.*;

public class Main {
    private static final boolean N_CASE = false;

    private static final int[][] D = { {-1, 0}, {1, 0}, {0, -1}, {0, 1} };

    private static class Node implements Comparable<Node> {
        int x, y;
        int d;

        public Node(int x, int y, int d) {
            this.x = x;
            this.y = y;
            this.d = d;
        }

        @Override
        public int compareTo(Node node) {
            return d - node.d;
        }
    }

    private boolean isValid(int H, int W, int x, int y) {
        return x >= 0 && x < H && y >= 0 && y < W;
    }

    private void solve() {
        int H = sc.nextInt();
        int W = sc.nextInt();
        int CH = sc.nextInt() - 1;
        int CW = sc.nextInt() - 1;
        int DH = sc.nextInt() - 1;
        int DW = sc.nextInt() - 1;

        String[] M = new String[H];
        for (int i = 0; i < H; i++) {
            M[i] = sc.next();
        }

        PriorityQueue<Node> q = new PriorityQueue<>();
        q.add(new Node(CH, CW, 0));

        boolean[][] vis = new boolean[H][W];
        while (!q.isEmpty()) {
            Node u = q.poll();
            if (vis[u.x][u.y]) {
                continue;
            }

            vis[u.x][u.y] = true;
            if (u.x == DH && u.y == DW) {
                out.println(u.d);
                return;
            }

            for (int[] d : D) {
                int dx = u.x + d[0];
                int dy = u.y + d[1];

                if (isValid(H, W, dx, dy) && !vis[dx][dy] && M[dx].charAt(dy) == '.') {
                    q.add(new Node(dx, dy, u.d));
                }
            }

            for (int x = u.x - 2; x <= u.x + 2; ++x) {
                for (int y = u.y - 2; y <= u.y + 2; ++y) {
                    if (isValid(H, W, x, y) && !vis[x][y] && M[x].charAt(y) == '.') {
                        q.add(new Node(x, y, u.d + 1));
                    }
                }
            }
        }

        out.println(-1);
    }

    private void run() {
        int T = N_CASE ? sc.nextInt() : 1;
        for (int t = 0; t < T; ++t) {
            solve();
        }
    }

