@SuppressWarnings("unused")
public class Main {
    FastScanner in;
    PrintWriter out;
    final static int MOD = (int)1e9+7;

    void solve(){
        int H = in.nextInt(), W = in.nextInt();
        int sy = in.nextInt()-1, sx = in.nextInt()-1;
        int gy = in.nextInt()-1, gx = in.nextInt()-1;
        char[][] S = new char[H][W];
        for(int i = 0; i < H; i++){
            for(int j = 0; j < W; j++){
                S[i][j] = in.nextChar();
            }
        }
        int[] dy = {-1, 0, 1, 0};
        int[] dx = {0, 1, 0, -1};

        long INF = Long.MAX_VALUE / 2;
        long[] dist = new long[H * W];
        Arrays.fill(dist, INF);
        ArrayDeque<Integer> deque = new ArrayDeque<>();
        dist[sy + sx * H] = 0;
        deque.addLast(sy + sx * H);
        ArrayDeque<Integer> s = new ArrayDeque<>();

        while(!deque.isEmpty()){
            while(!deque.isEmpty()){
                int v = deque.removeFirst();
                int y = v % H, x = v / H;
                s.addLast(v);
                for(int k = 0; k < dy.length; k++){
                    int ny = y + dy[k], nx = x + dx[k], n = ny + nx * H;
                    if(ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
                    if(S[ny][nx] == '#') continue;
                    if(dist[n] > dist[v]){
                        dist[n] = dist[v];
                        deque.addLast(n);
                        s.addLast(n);
                    }
                }
            }
            while(!s.isEmpty()){
                int v = s.removeFirst();
                int y = v % H, x = v / H;
                for(int ry = -2; ry <= 2; ry++){
                    for(int rx = -2; rx <= 2; rx++){
                        int ny = y + ry, nx = x + rx, n = ny + nx * H;
                        if(ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
                        if(S[ny][nx] == '#') continue;
                        if(dist[n] > dist[v] + 1){
                            dist[n] = dist[v] + 1;
                            deque.addLast(n);
                        }
                    }
                }
            }
        }
        out.println(dist[gy + gx * H] == INF ? "-1" : dist[gy + gx * H]);
    }

    public static void main(String[] args) {
        new Main().m();
    }

