public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final double eps = 1e-9;
    static long mod = 1000000007;

    void solve() {
        int h = in.nextInt();
        int w = in.nextInt();
        int sy = in.nextInt() - 1;
        int sx = in.nextInt() - 1;
        int gy = in.nextInt() - 1;
        int gx = in.nextInt() - 1;
        char[][] s = in.nextCharGrid(h, w);
        int[][] dp = new int[h][w];
        for (int i = 0; i < h; i++) {
            Arrays.fill(dp[i], iinf);
        }
        Point.h = h;
        Point.w = w;
        dp[sy][sx] = 0;
        Queue<Point> queue = new PriorityQueue<>(Comparator.comparingInt(p -> dp[p.y][p.x]));
        queue.add(new Point(sx, sy));
        while (!queue.isEmpty()) {
            Point p = queue.poll();
            for (Point q : p.neighborPoints(4)) {
                if (s[q.y][q.x] == '.' && dp[q.y][q.x] > dp[p.y][p.x]) {
                    dp[q.y][q.x] = dp[p.y][p.x];
                    queue.add(q);
                }
            }
            for (int i = -2; i <= 2; i++) {
                for (int j = -2; j <= 2; j++) {
