                    int y = cur[1] + j;
                    int cost = cur[2];
                    if (x >= 0 && y >= 0 && x < h && y < w && field[x][y] == '.' && !visited[x][y]) {
                        if (Math.abs(i + j) == 1 && (i == 0 || j == 0)) {
                            q.addFirst(new Integer[]{x, y, cost});
                        } else {
