public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt();
        int W = sc.nextInt();
        int Ch = sc.nextInt() - 1;
        int Cw = sc.nextInt() - 1;
        int Dh = sc.nextInt() - 1;
        int Dw = sc.nextInt() - 1;
        char[][] maze = new char[H][W];
        for(int i = 0; i < H; i++){
            String s = sc.next();
            for(int j = 0; j < W; j++)
                maze[i][j] = s.charAt(j);
        }
        sc.close();

        int[][] dist = new int[H][W];
        for(int i = 0; i < H; i++)
            Arrays.fill(dist[i], Integer.MAX_VALUE / 2);
        dist[Ch][Cw] = 0;

        int[] dx = {1, 0, -1, 0};
        int[] dy = {0, 1, 0, -1};

        Deque<Integer> deque = new ArrayDeque<>(100000);
        deque.addLast(Ch);
        deque.addLast(Cw);
        int d = dist[Ch][Cw];
        while(deque.isEmpty() == false){
            int pi = deque.poll();
            int pj = deque.poll();
            d = dist[pi][pj];
            for(int i = 0; i < 4; i++){
                int ni = pi + dx[i];
                int nj = pj + dy[i];
                if(ni < 0 || ni >= H || nj < 0 || nj >= W) continue;
                if(maze[ni][nj] == '#') continue;
                if(dist[ni][nj] <= d) continue;
                dist[ni][nj] = d;
                deque.addFirst(nj);
                deque.addFirst(ni);
            }
            for(int i = -2; i <= 2; i++){
                for(int j = -2; j <= 2; j++){
                    int ni = pi + i;
                    int nj = pj + j;
                    if(ni < 0 || ni >= H || nj < 0 || nj >= W) continue;
                    if(maze[ni][nj] == '#') continue;
                    if(dist[ni][nj] <= d + 1) continue;
                    dist[ni][nj] = d + 1;
                    deque.addLast(ni);
                    deque.addLast(nj);
                }
            }
        }

        int ans = dist[Dh][Dw];
        if(ans == Integer.MAX_VALUE / 2) ans = -1;
        System.out.println(ans);
    }
}

import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
	static final long MOD = 1000000007L;
	static final int INF = 50000000;

	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter pw = new PrintWriter(System.out);

		int H = sc.ni();
		int W = sc.ni();
		int C = (sc.ni()-1)*W+(sc.ni()-1); 
		int D = (sc.ni()-1)*W+(sc.ni()-1); 
		int[][] grid = new int[H][W];
		for (int i = 0; i < H; i++) {
			String s = sc.next();
			for (int j = 0; j < W; j++) {
				if (s.charAt(j)=='#')
					grid[i][j] = 1;
			}
		}
		int[][] dirs = {{-1,0},{1,0},{0,1},{0,-1}};
		int[][] mags = {{-2,1},{-2,2},{-2,-2},{-2,-1},{-1,-2},{-1,2},{1,-2},{1,2},{2,-2},{2,-1},{2,1},{2,2}};
		Dijkstra dij = new Dijkstra(H*W);
		for (int i = 0; i < H; i++) {
			for (int j = 0; j < W; j++) {
				int n1 = i*W+j;
				for (int[] dir: dirs) {
					int newR = i+dir[0];
					int newC = j+dir[1];
					if (newR >= 0 && newR < H && newC >= 0 && newC < W) {
						int n2 = newR*W+newC;
						if (grid[newR][newC]==0) {
							dij.addEdge(n1, n2, 0);
						} else if (grid[i][j]==0) {
							dij.addEdge(n1, n2, 1);
						}
					}
				}
				if (grid[i][j]==1)continue;
				for (int[] mag: mags) {
					int newR = i+mag[0];
					int newC = j+mag[1];
					if (newR >= 0 && newR < H && newC >= 0 && newC < W) {
						int n2 = newR*W+newC;
						if (grid[newR][newC]==0) {
							dij.addEdge(n1, n2, 1);
						}
					}
				}
			}
		}
		int[] dist = dij.dijkstra(C);
		int ans = dist[D];
		if (ans == Integer.MAX_VALUE)
			ans = -1;
		pw.println(ans);

		pw.close();
	}

	static class Dijkstra {
		public int N;
		public ArrayList<int[]>[] graph;

		public Dijkstra(int numNodes) {
			N = numNodes;
			graph = new ArrayList[N];
			for (int i = 0; i < N; i++) {
				graph[i] = new ArrayList<int[]>();
			}
		}


		public void addEdge(int n1, int n2, int w) {
			graph[n1].add(new int[]{n2,w});
		}


		public int[] dijkstra(int root) {



			int[] distances = new int[N];
			Arrays.fill(distances,Integer.MAX_VALUE);
			distances[root] = 0;

			PriorityQueue<int[]> pq = new PriorityQueue<int[]>(new Comparator<int[]>() {
				@Override
				public int compare(int[] arr1, int[] arr2) {
					return (arr1[1] - arr2[1]);
				}
			});
			int[] temp = new int[]{root,0};
			pq.add(temp);
			while (! pq.isEmpty()) {
				temp = pq.poll();
				for (int[] e: graph[temp[0]]) {
					int child = e[0];
					int w = e[1];
					int node = temp[0];
					if (distances[child] > distances[node] + w) {
						distances[child] = distances[node] + w;
						pq.add(new int[]{child,distances[child]});
					}
				}
			}

			return distances;
		}
	}

    static class FastScanner { 
        BufferedReader br; 
        StringTokenizer st; 

        public FastScanner() { 
            br = new BufferedReader(new InputStreamReader(System.in)); 
        } 

        String next() { 
            while (st == null || !st.hasMoreElements()) { 
                try { 
                    st = new StringTokenizer(br.readLine());
                } catch (IOException  e) { 
                    e.printStackTrace(); 
                } 
            } 
            return st.nextToken(); 
        }

        int ni() { 
            return Integer.parseInt(next()); 
        }

        long nl() { 
            return Long.parseLong(next()); 
        } 

        double nd() { 
            return Double.parseDouble(next()); 
        } 

        String nextLine() {
            String str = ""; 
            try { 
                str = br.readLine(); 
            } catch (IOException e) {
                e.printStackTrace(); 
            } 
            return str;
        }
    }
}

