        for (int i = 0; i < h; i++) {
            s[i] = scan.next().split("");
        }
        scan.close();

        long ans = 0;

        Deque<Pair> stack = new ArrayDeque<Pair>();
        s[ch][cw] = flag;
        stack.push(new Pair(ch, cw));

        while (true) {
            List<Pair> warpList = new ArrayList<Pair>();
            while (!stack.isEmpty()) {
                Pair p = stack.poll();

                for (int i = 0; i < dx.length; i++) {
                    int x = p.h + dx[i];
                    int y = p.w + dy[i];

                    if (x == dh && y == dw) {
                        System.out.println(ans);
                        return;
                    }

                    if (0 <= x && x < h && 0 <= y && y < w) {
                        if (s[x][y].equals(".")) {
                            s[x][y] = flag;
                            stack.push(new Pair(x, y));
                        }
                    }
                }

                warpList.add(p);
            }

            ans++;
            for (Pair p : warpList) {
                for (int i = 0; i < warpx.length; i++) {
                    int x = p.h + warpx[i];
