    		                dist[ni][nj] = now + c;
    		                if(c == 0){
    		                    q.addFirst(new int[]{ni, nj});
    		                }else{
    		                    q.addLast(new int[]{ni, nj});
    		                }
    		            }
    		        }
    			}
    		}
		}

		if(dist[dh][dw] == INF){
		    result = -1;
		}else{
		    result = dist[dh][dw];
		}



		System.out.println(result);
	}

