import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {
	static Deque<Point> que;
	static Deque<Point> cornerque;
	static int[][] warpcnt;
	static boolean[][] map;
	static int H;
	static int W;

	public static void main(String[] args) {
		try (Scanner sc = new Scanner(System.in)) {
			H = sc.nextInt();
			W = sc.nextInt();
			warpcnt = new int[H][W];
			int CH = sc.nextInt() - 1;
			int CW = sc.nextInt() - 1;
			int DH = sc.nextInt() - 1;
			int DW = sc.nextInt() - 1;
			map = new boolean[H][W];
			for (int i = 0; i < H; i++) {
				String line = sc.next();
				for (int j = 0; j < W; j++) {
					map[i][j] = line.charAt(j) == '.';
					warpcnt[i][j] = -1;
				}
			}
			que = new ArrayDeque<>();
			cornerque = new ArrayDeque<>();
			warpcnt[CH][CW] = 0;
			Point C = new Point(CH, CW);
			que.add(C);
			while (!que.isEmpty()) {
				while (!que.isEmpty()) {
					Point tmp = que.remove();
					boolean up = move(tmp, 0, -1, 0);
					boolean down = move(tmp, 0, 1, 0);
					boolean left = move(tmp, 0, 0, -1);
					boolean right = move(tmp, 0, 0, 1);
					if (!up || !down || !left || !right) {
						cornerque.add(tmp);
					}
				}
				while (!cornerque.isEmpty()) {
					Point tmp = cornerque.remove();
					move(tmp, 1, -2, -1);
					move(tmp, 1, -2, 1);
					move(tmp, 1, -2, 0);
					move(tmp, 1, 2, -1);
					move(tmp, 1, 2, 0);
					move(tmp, 1, 2, 1);
					move(tmp, 1, -1, -2);
					move(tmp, 1, 0, -2);
					move(tmp, 1, 1, -2);
					move(tmp, 1, -1, 2);
					move(tmp, 1, 0, 2);
					move(tmp, 1, 1, 2);
					move(tmp, 1, -1, -1);
					move(tmp, 1, -2, -2);
					move(tmp, 1, -1, 1);
					move(tmp, 1, -2, 2);
					move(tmp, 1, 1, -1);
					move(tmp, 1, 2, -2);
					move(tmp, 1, 1, 1);
					move(tmp, 1, 2, 2);
				}
			}
			System.out.println(warpcnt[DH][DW]);
		}
	}

	static boolean move(Point p, int warp, int h, int w) {
		if (p.h + h < 0 || p.w + w < 0 || p.h + h >= H || p.w + w >= W) {

			return false;
		}
		if (map[p.h + h][p.w + w]) {
			int wcnt = warpcnt[p.h + h][p.w + w];
			int nowcnt = warpcnt[p.h][p.w] + warp;
			if (wcnt == -1) {
				warpcnt[p.h + h][p.w + w] = nowcnt;
				if (warp == 0) {
					que.addFirst(new Point(p.h + h, p.w + w));
				} else {
					que.add(new Point(p.h + h, p.w + w));
				}
				return true;
			} else if (wcnt > nowcnt) {
				warpcnt[p.h + h][p.w + w] = nowcnt;
				if (warp == 0) {
					que.addFirst(new Point(p.h + h, p.w + w));
				} else {
					que.add(new Point(p.h + h, p.w + w));
				}
				return true;
			}
		}
		return false;
	}

	static class Point {
		int h;
		int w;
		int warp;

		public Point(int h, int w) {
			this.h = h;
			this.w = w;
			this.warp = 0;
		}
	}
}

import java.util.*;

public class Main{
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);

        int h = Integer.parseInt(sc.next());
        int w = Integer.parseInt(sc.next());

        int cy = Integer.parseInt(sc.next())-1;
        int cx = Integer.parseInt(sc.next())-1;
        int dy = Integer.parseInt(sc.next())-1;
        int dx = Integer.parseInt(sc.next())-1;

        boolean[][] grd = new boolean[h][w];

        for(int i=0; i<h; i++){
            String line = sc.next();
            for(int j=0; j<w; j++){
                char c = line.charAt(j);
                if(c=='#'){
                    grd[i][j] = true;
                }
            }
        }

        int[][] memo = new int[h][w];
        for(int i=0; i<h; i++){
            for(int j=0; j<w; j++){
                memo[i][j] = (int)1e9;
            }
        }
        memo[cy][cx] = 0;

        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.addFirst(cy*w + cx);
        while(q.size() != 0){
            int tmp = q.pollFirst();
            int y = tmp/w;
            int x = tmp%w;
            int[] d = {0,1,0,-1};
            for(int i=0; i<4; i++){
                int ny = y+d[i^1];
                int nx = x+d[i];
                if(0<=nx && nx<w && 0<=ny && ny<h){
                    if(!grd[ny][nx]){
                        if(memo[ny][nx] > memo[y][x]){
                            memo[ny][nx] = memo[y][x];
                            q.addFirst(ny*w + nx);
                        }
                    }
                }
            }
            for(int ny=Math.max(0, y-2); ny<=Math.min(h-1, y+2); ny++){
                for(int nx=Math.max(0, x-2); nx<=Math.min(w-1, x+2); nx++){
                    if(!grd[ny][nx]){
                        if(memo[ny][nx] > memo[y][x]+1){
                            memo[ny][nx] = memo[y][x]+1;
                            q.addLast(ny*w + nx);
                        }
                    }
                }
            }
        }

        if(memo[dy][dx] != (int)1e9){
            System.out.println(memo[dy][dx]);
        }else{
            System.out.println(-1);
        }
    }
}

import java.util.Deque;
import java.util.LinkedList;
import java.util.Scanner;


public class Main {

    static class Node{
        int i;
        int j;
        int value;

        Node(int i,int j,int value){
            this.i = i;
            this.j =j;
            this.value =value;
        }
    }

    private static int[][] dir = {{-1,0},{1,0},{0,-1},{0,1}};

    private static int vis[][] = new int[1003][1003];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int h = scanner.nextInt();
        int w = scanner.nextInt();
        int s = scanner.nextInt();
        int e= scanner.nextInt();
        int ts = scanner.nextInt();
        int te = scanner.nextInt();
        String[] map = new String[h+1];
        for(int i=1;i<=h;i++){
            map[i] =scanner.next();
        }
        for(int i = 1;i<=h;i++){
            for(int j = 1;j<=w;j++){
                vis[i][j] = 100000000;
            }
        }
        Deque<Node> deque = new LinkedList<>();
        deque.add(new Node(s,e,0));
        vis[s][e] = 0;
        while(!deque.isEmpty()){
            Node node = deque.pollFirst();
            int now_i = node.i;
            int now_j = node.j;
            int now_value = node.value;
            for(int i = 0;i<4;i++){
                int tmp_i = dir[i][0] + now_i;
                int tmp_j = dir[i][1] + now_j;
                if(tmp_i <=0 || tmp_i > h || tmp_j <=0 || tmp_j > w)continue;
                if(vis[tmp_i][tmp_j] > now_value  && map[tmp_i].charAt(tmp_j-1) != '#') {
                    deque.addFirst(new Node(tmp_i, tmp_j, now_value));
                    vis[tmp_i][tmp_j] = now_value;
                }
            }
            for(int i = now_i-2;i<=now_i+2;i++){
                if(i <=0 || i > h)continue;
                for(int j = now_j-2;j<=now_j+2;j++){
                    if(j <=0 || j > w)continue;
                    if(vis[i][j] > now_value+1 && map[i].charAt(j-1) != '#') {
                        deque.addLast(new Node(i, j, now_value+1));
                        vis[i][j] = now_value+1;
                    }
                }
            }
        }
        System.out.println(vis[ts][te] == 100000000?-1:vis[ts][te]);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    char[][] map;
    int[][] roads;
    int h;
    int w;

    public static void main(String[] args) throws IOException {
        new Main().solve();
    }

    private void solve() throws IOException {
        BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        StringTokenizer tokenizer = new StringTokenizer(f.readLine());
        h = Integer.parseInt(tokenizer.nextToken());
        w = Integer.parseInt(tokenizer.nextToken());
        tokenizer = new StringTokenizer(f.readLine());
        int x0 = Integer.parseInt(tokenizer.nextToken()) - 1;
        int y0 = Integer.parseInt(tokenizer.nextToken()) - 1;
        tokenizer = new StringTokenizer(f.readLine());
        int x1 = Integer.parseInt(tokenizer.nextToken()) - 1;
        int y1 = Integer.parseInt(tokenizer.nextToken()) - 1;
        map = new char[h][w];
        for (int i = 0; i <h; i++) map[i] = f.readLine().toCharArray();

        roads = new int[h][w];
        for (int i = 0; i < h; i++) for (int j = 0; j < w; j++) roads[i][j] = -1;
        int currRoad = 0;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (map[i][j] == '.' && roads[i][j] == -1) {
                    ArrayDeque<int[]> queue = new ArrayDeque<int[]>();
                    roads[i][j] = currRoad;
                    int[] pos = {i, j};
                    queue.addLast(pos);
                    while (!queue.isEmpty()) {
                        pos = queue.removeFirst();

                        for (int x = -1; x <= 1; x += 2) {
                            if (goodAdjacent(pos[0] + x, pos[1])) {
                                roads[pos[0] + x][pos[1]] = currRoad;
                                int[] newPos = {pos[0] + x, pos[1]};
                                queue.addLast(newPos);
                            }
                        }

                        for (int y = -1;  y <= 1; y += 2) {
                            if (goodAdjacent(pos[0], pos[1] + y)) {
                                roads[pos[0]][pos[1] + y] = currRoad;
                                int[] newPos = {pos[0], pos[1] + y};
                                queue.addLast(newPos);
                            }
                        }
                    }
                    currRoad++;
                }
            }
        }

        HashSet<Integer>[] connectedTo = new HashSet[currRoad];
        for (int i = 0; i < currRoad; i++) connectedTo[i] = new HashSet<Integer>();

        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                for (int k = -2; k <= 2; k++) {
                    for (int l = -2; l <= 2; l++) {
                        if (map[i][j] == '#') continue;
                        if (goodMagic(roads[i][j], i + k, j + l)) {
                            connectedTo[roads[i][j]].add(roads[i + k][j + l]);
                        }
                    }
                }
            }
        }

        int[] startRoad = {roads[x0][y0], 0};
        int[] shortesPathToRoad = new int[currRoad];
        Arrays.fill(shortesPathToRoad, -1);
        boolean[] visited = new boolean[currRoad];
        ArrayDeque<int[]> queue = new ArrayDeque<int[]>();
        visited[startRoad[0]] = true;
        queue.addLast(startRoad);
        while (!queue.isEmpty()) {
            int[] road = queue.removeFirst();

            shortesPathToRoad[road[0]] = road[1];
            for (int adjacent : connectedTo[road[0]]) {
                if (!visited[adjacent]) {
                    int[] newRoad = {adjacent, road[1] + 1};
                    visited[adjacent] = true;
                    queue.addLast(newRoad);
                }
            }
        }

        out.println(shortesPathToRoad[roads[x1][y1]]);

        out.close();
    }

    private boolean goodAdjacent(int i, int j) {
        return i >= 0 && i < h && j >= 0 && j < w  && map[i][j] == '.' && roads[i][j] == -1;
    }

    private boolean goodMagic(int road, int i, int j) {
        return i >= 0 && i < h && j >= 0 && j < w  && map[i][j] == '.' && roads[i][j] != road;
    }
}

import java.util.Arrays;
import java.util.TreeSet;

public class Main {

  private static void solve() {
    int h = ni();
    int w = ni();

    int[] s = na(2);
    int[] g = na(2);

    char[][] map = new char[h + 2][w + 2];
    for (int i = 1; i <= h; i++) {
      char[] line = ns();
      for (int j = 1; j <= w; j++) {
        map[i][j] = line[j - 1];
      }
    }
    int[][] d = dijk(map, s);

    int ret = d[g[0]][g[1]];
    if (ret >= Integer.MAX_VALUE / 2) {
      System.out.println(-1);
    } else {
      System.out.println(ret);
    }
  }

  public static int[][] dijk(char[][] map, int[] s) {
    int h = map.length;
    int w = map[0].length;
    final int[][] td = new int[h][w];
    for (int[] v : td)
      Arrays.fill(v, Integer.MAX_VALUE);

    TreeSet<int[]> q = new TreeSet<>((a, b) -> {
      if (td[a[0]][a[1]] - td[b[0]][b[1]] != 0)
        return td[a[0]][a[1]] - td[b[0]][b[1]];
      return a[0] == b[0] ? a[1] - b[1] : a[0] - b[0];
    });

    q.add(s);
    td[s[0]][s[1]] = 0;
    while (q.size() > 0) {
      int[] cur = q.pollFirst();

      for (int dy = -2; dy <= 2; dy++) {
        for (int dx = -2; dx <= 2; dx++) {
          int ny = cur[0] + dy;
          int nx = cur[1] + dx;
          if (ny < 0 || ny >= h || nx < 0 || nx >= w)
            continue;

          int len = Math.abs(dy) + Math.abs(dx) <= 1 ? 0 : 1;
          int nd = td[cur[0]][cur[1]] + len;

          if (map[ny][nx] == '.' && nd < td[ny][nx]) {
            int[] nex = { ny, nx };
            q.remove(nex);
            td[ny][nx] = nd;
            q.add(nex);
          }
        }
      }
    }

    return td;
  }

  public static void main(String[] args) {
    new Thread(null, new Runnable() {
      @Override
      public void run() {
        long start = System.currentTimeMillis();
        String debug = args.length > 0 ? args[0] : null;
